recursiveSchemaEdgeRecorded :: CheckState -> Text -> Text -> Text -> Bool
recursiveSchemaEdgeRecorded state caller callee relation =
  any matches (Set.toList (csRecursiveSchemaEdges state))
  where
    matches edge =
      nameMatches caller (rseCaller edge)
        && nameMatches callee (rseCallee edge)
        && relation == relationName (rseRelation edge)
    nameMatches requested name = requested == gnameText name || requested == gKey name
    relationName = \case
      RecursiveSchemaIdentity -> "identity"
      RecursiveSchemaLowerOrEqual -> "lower-or-equal"
      RecursiveSchemaStrictLower -> "strict-lower"

selectedUniverseEvidenceRecorded :: CheckState -> Text -> Text -> Bool
selectedUniverseEvidenceRecorded state goal evidence =
  any matches (Set.toList (csSelectedUniverseEvidence state))
  where
    matches selected =
      normalizeGoal goal == normalizeGoal (sueGoal selected)
        && (evidence == gnameText (sueEvidence selected) || evidence == gKey (sueEvidence selected))
    normalizeGoal = T.unwords . T.words

universeInferenceRecord :: CheckState -> Text -> Maybe UniverseInferenceRecord
universeInferenceRecord state requested =
  case [record | (name, record) <- Map.toAscList (csUniverseInferenceRecords state), matches name] of
    [record] -> Just record
    _ -> Nothing
  where
    matches name =
      requested == name
        || ("." <> requested) `T.isSuffixOf` name

-- | The §22 derivation-shape reflection module.
shapeModule :: ModuleName
shapeModule = modDerivingShape

-- | The wired-in prelude names (see "Kappa.Builtins") that fail to resolve
-- in a checked state — i.e. names the compiler assumes the prelude defines
-- but which are absent from its globals and constructors. An empty result
-- means the compiler↔prelude name contract holds. Used by the pipeline's
-- post-prelude validation to turn silent drift into a reported error.
unresolvedBuiltins :: CheckState -> [WiredIn]
unresolvedBuiltins st =
  [ w
  | w <- wiredInPreludeNames
  , not (wiName w `Map.member` csGlobals st)
  , not (wiName w `Map.member` csCtors st)
  ]

type CheckM = State CheckState

-- | Compare two declaration interfaces as ordinary source occurrences.
-- Hidden declaration-universe telescopes are occurrence-polymorphic, so
-- comparing their stored @LParam@s directly is ill-scoped and rejects valid
-- specializations such as @Option.{0} Int@.  The Appendix-T harness uses this
-- entry point to freshen both interfaces exactly as name resolution does,
-- then asks the checker and principal level solver for definitional equality.
declarationTypesConvertibleAtUse :: CheckState -> GName -> GName -> Bool
declarationTypesConvertibleAtUse initial actual expected =
  evalState compareOccurrences initial
  where
    compareOccurrences = do
      diagnosticCount <- gets (length . csDiags)
      actualOccurrence <- globalTypeIn emptyCtx noSpan actual
      expectedOccurrence <- globalTypeIn emptyCtx noSpan expected
      case (actualOccurrence, expectedOccurrence) of
        (Just (_, actualType), Just (_, expectedType)) -> do
          equal <- unify emptyCtx actualType expectedType
          levelsSolved <- solveDeferredLevelConstraints True
          diagnostics <- gets csDiags
          let newDiagnostics = take (length diagnostics - diagnosticCount) diagnostics
          pure (equal && levelsSolved && not (any isError newDiagnostics))
        _ -> pure False

data VarRefInfo = VarRefInfo
  { vriStoredType :: !Value
  , vriStoredTypeTerm :: !Term
  , vriMonadRefDict :: !Term
  , vriMonadType :: !Value
  , vriDiagnosticRefType :: !Value
  , vriLoweringWitness :: !(Maybe RefLoweringWitness)
  }

data VarReadBlock
  = VarReadCrossesBoundary
  | VarReadStaticPosition

-- | Checker-owned interface for a universe-polymorphic local declaration.
-- The generalized type lives in 'ceType'; this telescope is the authority for
-- fresh occurrence instantiation and for KCore serialization.
data LocalUniverseInfo = LocalUniverseInfo
  { luiTelescope :: !DeclarationUniverseTelescope
  }

data LocalLetItem
  = LocalLetBinding !LetBind
  | LocalLetRecursiveGroup ![LetBind]

-- | One entry in the local typing context: a variable in scope, with its
-- type and the quantity\/borrow\/origin metadata the usage and diagnostic
-- machinery needs. The list of these (innermost first) /is/ the scope.
data CtxEntry = CtxEntry
  { ceName :: !Text
  , ceType :: !Value
  , ceLocalUniverses :: !(Maybe LocalUniverseInfo)
  , ceMode :: !ObservationMode
  , ceModeProvisional :: !Bool
  -- ^ True only while a generated binder's domain is being inferred. This
  -- covers unannotated local parameters and implicitly universalized free
  -- variables. Source-time observation checks recompute the mode from the
  -- solved domain; finalized KCore never contains provisional modes.
  , ceImplicitLocal :: !Bool
  , ceVarInfo :: !(Maybe VarRefInfo)
  -- ^ Introduced by @var@ (§18.6.1): ordinary value occurrences select the
  -- current-value facet during do-item lifting; @ref x@ and assignments use the
  -- same MonadRef evidence that created the hidden cell.
  , ceProjInfo :: !(Maybe ProjInfo)
  -- ^ Local alias of a projection declaration. This carries the projection's
  -- symbol-backed footprint through ordinary let bindings, so inout rewriting
  -- can reason about @~(proj x)@ without inspecting source spellings.
  , ceOpValueInfo :: !(Maybe EffectOpValueInfo)
  -- ^ Local alias of a resolved effect operation value. The operation's
  -- first-class type does not retain its declared resumption quantity, so flow
  -- and usage analyses must carry this checker-owned fact through simple
  -- aliases instead of rediscovering @label.op@ from source spelling.
  , ceCoreQ :: !Q
  -- ^ Elaborated quantity retained independently from observation mode.
  , ceObservationOrigin :: !(Maybe Text)
  -- ^ Diagnostic provenance for a parametric observation. This is checker
  -- metadata only; KCore identity contains the mode but never source origin.
  , ceQ :: !(Maybe S.Quantity)
  -- ^ Quantity prefix of an implicit local binder (§16.3.3).
  , ceBorrow :: !Bool
  -- ^ @\@&@-marked implicit local: may not escape into closures.
  , ceOrigin :: !Span
  -- ^ §3.1.1A binder origin: the source span where this entry was
  -- introduced, so a borrow/ownership diagnostic about it can cite its
  -- introduction site. 'noSpan' when the introduction is untracked for
  -- this binder kind.
  }

-- | A checked occurrence judgment (§30.2.0). This value is transient checker
-- state, not a KCore wrapper or interface side table: persistent mode lives on
-- the binding/projection/global fact that introduced the occurrence.
data ObservationJudgment = ObservationJudgment
  { ojMode :: !ObservationMode
  , ojOrigin :: !Text
  , ojClassifier :: !(Maybe ObservationClassifier)
  }

data ObservationClassifier
  = ObservationType !Level
  | ObservationTypeFormer

ceVarBind :: CtxEntry -> Bool
ceVarBind = isJust . ceVarInfo

-- | The elaboration context threaded through 'infer'\/'check': everything
-- that depends on /where/ in the program we are. 'ctxEntries' is the scope
-- (and 'ctxEnv' its evaluated mirror, for NbE); the remaining fields carry
-- flow refinement, scope barriers, effect labels, hygiene, and the current
-- @return@ target. Helpers like @bindCtx@\/@pushCtxBarrier@ extend it.
data Ctx = Ctx
  { ctxEntries :: ![CtxEntry]
  , ctxEnv :: !Env
  , ctxRefines :: !(Map Text [GName])
  -- ^ §7.4.1 flow refinement: variable → possible constructors.
  , ctxAliases :: !(Map Text Text)
  -- ^ §7.4.3 stable aliases: @let q = p@ makes q transport p's refinement.
  , ctxVarCurrentVersions :: !(Map Text Int)
  -- ^ §18.6.2 tracked local mutable-cell current-value versions.
  , ctxVarCurrentEscaped :: !(Set Text)
  -- ^ §18.6.2 mutable cells whose @ref x@ has escaped flow tracking.
  , ctxBarriers :: ![Int]
  -- ^ Context lengths at which lambda bodies began (closure
  -- boundaries for §16.3.3 borrow-escape and scope grouping).
  , ctxEffLabels :: !(Map Text EffLabelInfo)
  -- ^ Lexically scoped effect labels (§9.3.1.1 @scoped effect@).
  , ctxInDo :: !Bool
  -- ^ Inside a @do@ elaboration: gates the §18.9.3 @~@ marker.
  , ctxVarReadBlock :: !(Maybe VarReadBlock)
  -- ^ Why a surface @var@ current-value occurrence cannot be lifted in
  -- this context, for the §18.3.1/§18.6.1 diagnostic split.
  , ctxHyg :: !(Map Text (Int, Value))
  -- ^ §21.4 hygienic capture references in spliced syntax: fresh
  -- spelling ↦ (binding LEVEL in this context, binder type).
  , ctxQuoteSlots :: !(Map Int Value)
  -- ^ Types of the enclosing quote's grafting slots ('EQuoteHole'),
  -- while the quote payload is being checked (§21.1).
  , ctxCodeDepth :: !Int
  -- ^ Nesting depth of enclosing §23.2 code quotes ('.~' is only
  -- meaningful inside one).
  , ctxReturnTarget :: !(Maybe Text)
  -- ^ §18.5: name/label of the innermost enclosing return target — a named
  -- function/method, an inherited-name lambda, or a labeled lambda. A
  -- @return@L@ resolves only when @L@ matches this (resolution does not
  -- cross user-written lambda boundaries); an anonymous lambda resets it to
  -- Nothing (nothing outside is reachable across it).
  , ctxLevelAssumptions :: !Assumptions
  -- ^ §11.1.2.2 lexically scoped inequalities introduced by earlier erased
  -- level-comparison proof binders in the current telescope.
  , ctxLevelFieldIds :: !(Map Text Int)
  -- ^ Scoped identities of TypeLevel-valued `this.field` siblings. Nested
  -- telescope labels shadow by map insertion without aliasing solver atoms.
  , ctxBorrowCaptureRegions :: !(Map Text (Maybe Value))
  -- ^ Explicit borrowed locals mapped to their declared region witness.
  -- 'Nothing' records an anonymous rigid borrow, which cannot be named in a
  -- source capture annotation. Entries come from resolved binder prefixes,
  -- and 'bindEntry' removes shadowed names.
  }

-- | A scoped effect's elaborated interface (§9.3.1.1, §18.1.15): label
-- identity, interface-type identity, and operation metadata.
data EffLabelInfo = EffLabelInfo
  { eliLabel :: !GName -- ^ effect-label value identity (§18.1.18)
  , eliIface :: !GName -- ^ effect-interface type constructor
  , eliParams :: !Telescope
  -- ^ §18.1.15 effect type parameters, including their independent
  -- observation mode and quantity. Domains are de Bruijn under the preceding
  -- parameters.
  , eliFixedArgs :: !(Maybe [Value])
  -- ^ A declared @effect label l : E args@ fixes the interface arguments at
  -- the declaration site. 'Nothing' is reserved for the canonical label
  -- introduced by @effect E ...@, whose operations remain polymorphic in the
  -- interface parameters; @Just []@ is an explicit alias of an
  -- unparameterized interface.
  , eliFixedUniverses :: !(Maybe [Level])
  -- ^ The exact declaration-universe occurrence selected by an effect-label
  -- alias.  Fixed interface arguments and their hidden universe spine form
  -- one semantic instance: operation selection must not freshen the owner
  -- independently and then reuse arguments elaborated at another occurrence.
  , eliOps :: ![EffOpInfo]
  }

data EffOpInfo = EffOpInfo
  { eoiName :: !Text
  , eoiQ :: !Q -- ^ declared resumption quantity (§18.1.16)
  , eoiImplicits :: !Telescope
  -- ^ §18.1.15: the operation's own implicit (forall-bound) parameters
  -- (e.g. @op : forall a. a -> a@), de Bruijn under the effect's parameters
  -- then the preceding op-implicits. Universally quantified per
  -- operation: instantiated fresh at each call and treated as skolems in the
  -- handler clause.
  , eoiArgs :: !Telescope
  -- ^ §18.1.15/§30.2.0: the operation's explicit parameter telescope. Each
  -- entry retains mode, quantity, explicitness, access, and its domain under
  -- the effect parameters, operation implicits, and preceding arguments.
  -- Non-empty.
  , eoiResT :: !Term
  -- ^ The final result type @B@, de Bruijn under the effect parameters,
  -- operation implicits, and the complete explicit-argument telescope.
  }

-- | Reconstruct one operation header as a closed term under the owning
-- effect interface's parameter telescope. Operation signatures are part of
-- the effect declaration's observable interface (§11.1.2.3A, §18.1.15):
-- levels that occur only in an operation domain must therefore contribute to
-- the effect's declaration-universe schema just like levels in the effect's
-- own parameter telescope.
effectOperationInterfaceTerm :: EffLabelInfo -> EffOpInfo -> Term
effectOperationInterfaceTerm effectInfo operation =
  foldr telePi operationBody (eliParams effectInfo)
  where
    operationBody =
      foldr telePi
        (foldr telePi (eoiResT operation) (eoiArgs operation))
        (eoiImplicits operation)

-- | Canonical operation-header terms owned by one effect interface. Alias
-- labels reuse this metadata but do not own another copy of its universe
-- schema, so only the canonical (unfixed) interface entry contributes.
effectUniverseInterfaceTerms :: CheckState -> GName -> [Term]
effectUniverseInterfaceTerms st interface =
  [ effectOperationInterfaceTerm effectInfo operation
  | effectInfo <- maybeToList (Map.lookup interface (csEffectInterfaces st))
  , operation <- eliOps effectInfo
  ]

data EffectOpValueInfo = EffectOpValueInfo
  { eoviLabel :: !GName
  , eoviName :: !Text
  , eoviQ :: !Q
  , eoviArity :: !Int
  }

emptyCtx :: Ctx
emptyCtx = Ctx [] [] Map.empty Map.empty Map.empty Set.empty [] Map.empty False Nothing Map.empty Map.empty 0 Nothing emptyAssumptions Map.empty Map.empty

ctxLen :: Ctx -> Int
ctxLen = length . ctxEntries

-- | Mark a closure boundary: entries below it are captured (§16.2.1).
pushCtxBarrier :: Ctx -> Ctx
pushCtxBarrier ctx = ctx {ctxBarriers = ctxLen ctx : ctxBarriers ctx}

withVarReadBlock :: VarReadBlock -> Ctx -> Ctx
withVarReadBlock block ctx = ctx {ctxVarReadBlock = Just block}

-- | Shared binder scaffold: prepend @entry@, push @v@ onto the
-- environment, and drop any prior flow-refinement/alias facts about the
-- binder's name (a fresh binder shadows them). All three @bindCtx*@
-- helpers differ only in the entry's flags and the environment value.
bindEntry :: CtxEntry -> Value -> Ctx -> Ctx
bindEntry entry v ctx =
  ctx
    { ctxEntries = entry : ctxEntries ctx
    , ctxEnv = v : ctxEnv ctx
    , ctxRefines = Map.delete (ceName entry) (ctxRefines ctx)
    , ctxAliases = Map.delete (ceName entry) (ctxAliases ctx)
    , ctxVarCurrentVersions = Map.delete (ceName entry) (ctxVarCurrentVersions ctx)
    , ctxVarCurrentEscaped = Set.delete (ceName entry) (ctxVarCurrentEscaped ctx)
    , ctxBorrowCaptureRegions = Map.delete (ceName entry) (ctxBorrowCaptureRegions ctx)
    }

bindCtx :: Text -> Bool -> Value -> Ctx -> Ctx
bindCtx n implocal ty ctx =
  bindCtxMQ Ordinary QW n implocal ty ctx

bindCtxQ :: Q -> Text -> Bool -> Value -> Ctx -> Ctx
bindCtxQ q n implocal ty ctx =
  bindCtxMQ Ordinary q n implocal ty ctx

bindCtxMQ :: ObservationMode -> Q -> Text -> Bool -> Value -> Ctx -> Ctx
bindCtxMQ mode q n implocal ty ctx =
  bindCtxMQB mode q n implocal False ty ctx

-- | Bind a compiler-generated variable whose observation mode is only a
-- placeholder until uses have solved its domain. The provisional mode keeps
-- kind variables usable while elaborating the surrounding declaration;
-- source-time observation checks and the final telescope both classify the
-- solved domain instead of treating that placeholder as authoritative.
bindCtxMQProvisional :: ObservationMode -> Q -> Text -> Bool -> Value -> Ctx -> Ctx
bindCtxMQProvisional mode q n implocal ty ctx =
  case ctxEntries bound of
    entry : rest -> bound {ctxEntries = entry {ceModeProvisional = True} : rest}
    [] -> bound
  where
    bound = bindCtxMQ mode q n implocal ty ctx

-- | Bind a local with its complete telescope contract. Implicit-candidate
-- status and borrowed access are independent properties; conflating them made
-- borrowed explicit binders participate in implicit search while silently
-- dropping their access restriction.
bindCtxMQB :: ObservationMode -> Q -> Text -> Bool -> Bool -> Value -> Ctx -> Ctx
bindCtxMQB mode q n implocal borrowed ty ctx =
  bindEntry
    (CtxEntry n ty Nothing mode False implocal Nothing Nothing Nothing q Nothing Nothing borrowed noSpan)
    (VRigid (length (ctxEnv ctx)) [])
    ctx

-- | Bind a local definition: the environment carries the definiens, so
-- conversion sees through local lets (delta for locals, §15.1).
bindCtxLet :: Text -> Bool -> Value -> Value -> Ctx -> Ctx
bindCtxLet n implocal ty v ctx =
  bindCtxLetProj n implocal ty v Nothing ctx

bindCtxLetProj :: Text -> Bool -> Value -> Value -> Maybe ProjInfo -> Ctx -> Ctx
bindCtxLetProj n implocal ty v mpj ctx =
  bindCtxLetProjOp n implocal ty v mpj Nothing ctx

bindCtxLetProjOp :: Text -> Bool -> Value -> Value -> Maybe ProjInfo -> Maybe EffectOpValueInfo -> Ctx -> Ctx
bindCtxLetProjOp n implocal ty v mpj mop ctx =
  bindCtxLetProjOpMode n implocal ty v mpj mop Ordinary Nothing ctx

bindCtxLetProjOpMode :: Text -> Bool -> Value -> Value -> Maybe ProjInfo -> Maybe EffectOpValueInfo -> ObservationMode -> Maybe Text -> Ctx -> Ctx
bindCtxLetProjOpMode n implocal ty v mpj mop mode observationOrigin ctx =
  bindEntry (CtxEntry n ty Nothing mode False implocal Nothing mpj mop QW observationOrigin Nothing False noSpan) v ctx

bindCtxLetUniverseMode
  :: Text
  -> Bool
  -> Value
  -> Value
  -> DeclarationUniverseTelescope
  -> Maybe ProjInfo
  -> Maybe EffectOpValueInfo
  -> ObservationMode
  -> Maybe Text
  -> Ctx
  -> Ctx
bindCtxLetUniverseMode n implocal ty v telescope mpj mop mode observationOrigin ctx =
  bindEntry
    (CtxEntry n ty (Just (LocalUniverseInfo telescope)) mode False implocal Nothing mpj mop QW observationOrigin Nothing False noSpan)
    v
    ctx

-- | Bind a @var@ cell; the name denotes the cell itself (§18.6.1).
bindCtxVar :: Text -> Value -> VarRefInfo -> Ctx -> Ctx
bindCtxVar n ty info ctx =
  let ctx' = bindEntry (CtxEntry n ty Nothing Ordinary False False (Just info) Nothing Nothing QW Nothing Nothing False noSpan) (VRigid (length (ctxEnv ctx)) []) ctx
   in ctx' {ctxVarCurrentVersions = Map.insert n 0 (ctxVarCurrentVersions ctx')}

kCondTerm :: KCond -> Term
kCondTerm = \case
  KCondPure t -> t
  KCondAction t -> t

-- | Record the implicit binder prefix on the most recent entry
-- (quantity and borrow marker, §16.3.3). @binderSp@ is the binder's
-- source span; when the prefix marks a borrow (@\@&@) it is recorded as
-- the entry's §3.1.1A introduction origin so a later borrow-escape
-- diagnostic about this candidate can cite where it was borrowed.
setTopPrefix :: Span -> BinderPrefix -> Ctx -> Ctx
setTopPrefix binderSp (BinderPrefix _ mq mb) ctx = case ctxEntries ctx of
  (e : rest) ->
    ctx
      { ctxEntries =
          e
            { ceQ = mq
            , ceCoreQ = qOf mq
            , ceBorrow = isJust mb
            , ceOrigin = if isJust mb then binderSp else ceOrigin e
            }
            : rest
      }
  [] -> ctx

setTopCoreQ :: Q -> Ctx -> Ctx
setTopCoreQ q ctx = case ctxEntries ctx of
  e : rest -> ctx {ctxEntries = e {ceCoreQ = q} : rest}
  [] -> ctx

-- | The §7.4.3 stable-alias root of a variable.
refineRoot :: Ctx -> Text -> Text
refineRoot ctx = go (16 :: Int)
  where
    go 0 n = n
    go fuel n = case Map.lookup n (ctxAliases ctx) of
      Just n' -> go (fuel - 1) n'
      Nothing -> n

-- | Record §7.4.1 refinements (through alias roots).
refineCtx :: [(Text, [GName])] -> Ctx -> Ctx
refineCtx refs ctx =
  ctx {ctxRefines = foldr add (ctxRefines ctx) refs}
  where
    add (n, gs) = Map.insert (refinementRoot ctx n) gs

-- | Record a stable alias @q = p@ (§7.4.3).
addCtxAlias :: Text -> Text -> Ctx -> Ctx
addCtxAlias q p ctx = ctx {ctxAliases = Map.insert q p (ctxAliases ctx)}

-- | Current refinement of a variable, through its alias root.
ctxRefinementOf :: Ctx -> Text -> Maybe [GName]
ctxRefinementOf ctx n = Map.lookup (refinementRoot ctx n) (ctxRefines ctx)

-- | Flow facts for a mutable current value are versioned just like snapshot
-- aliases. A direct occurrence of the mutable binding denotes its current
-- version; an immutable alias already resolves to the version it captured.
refinementRoot :: Ctx -> Text -> Text
refinementRoot ctx n =
  fromMaybe (refineRoot ctx n) (varCurrentRootOf ctx n)

varCurrentKey :: Text -> Int -> Text
varCurrentKey n v = "$var-current:" <> n <> ":" <> T.pack (show v)

varCurrentKeyPrefix :: Text
varCurrentKeyPrefix = "$var-current:"

isVarCurrentKey :: Text -> Bool
isVarCurrentKey = T.isPrefixOf varCurrentKeyPrefix

varCurrentRootOf :: Ctx -> Text -> Maybe Text
varCurrentRootOf ctx n = do
  (_, entry) <- lookupCtx n ctx
  _ <- ceVarInfo entry
  version <- Map.lookup n (ctxVarCurrentVersions ctx)
  if n `Set.member` ctxVarCurrentEscaped ctx
    then Nothing
    else Just (varCurrentKey n version)

addVarCurrentAlias :: Text -> Text -> Ctx -> Ctx
addVarCurrentAlias alias root ctx =
  ctx {ctxAliases = Map.insert alias root (ctxAliases ctx)}

invalidateVarCurrent :: Text -> Ctx -> Ctx
invalidateVarCurrent n ctx =
  ctx {ctxVarCurrentVersions = Map.adjust (+ 1) n (ctxVarCurrentVersions ctx)}

escapeVarCurrent :: Text -> Ctx -> Ctx
escapeVarCurrent n ctx =
  let ctx' = invalidateVarCurrent n ctx
   in ctx' {ctxVarCurrentEscaped = Set.insert n (ctxVarCurrentEscaped ctx')}

lookupCtx :: Text -> Ctx -> Maybe (Int, CtxEntry)
lookupCtx n ctx = go 0 (ctxEntries ctx)
  where
    go _ [] = Nothing
    go i (e : rest)
      | ceName e == n = Just (i, e)
      | otherwise = go (i + 1) rest

ec_ :: CheckM EvalCtx
ec_ = gets ecOf

-- | The (compile-time, non-runtime) 'EvalCtx' implied by a 'CheckState'. Pure
-- so callers holding a saved state can force values without re-entering the
-- monad.
ecOf :: CheckState -> EvalCtx
ecOf st = EvalCtx (Globals (csGlobals st)) (csMetas st) False (csFacts st)

evalIn :: HasCallStack => Ctx -> Term -> CheckM Value
evalIn ctx t = do
  unless (termScopedAt (ctxLen ctx) t) $
    error
      ( "Kappa.Check.evalIn: internal error: term is not scoped at context depth "
          <> show (ctxLen ctx)
          <> ": "
          <> T.unpack (renderTerm t)
          <> "\nraw term: "
          <> show t
          <> "\n"
          <> prettyCallStack callStack
      )
  ec <- ec_
  pure (eval ec (ctxEnv ctx) t)

quoteIn :: HasCallStack => Ctx -> Value -> CheckM Term
quoteIn ctx v = do
  quoted <- quoteRawIn ctx v
  unless (termScopedAt (ctxLen ctx) quoted) $
    error
      ( "Kappa.Check.quoteIn: internal error: value quotes outside context depth "
          <> show (ctxLen ctx)
          <> ": "
          <> T.unpack (renderTerm quoted)
          <> "\nraw term: "
          <> show quoted
          <> "\n"
          <> prettyCallStack callStack
      )
  pure quoted

quoteRawIn :: Ctx -> Value -> CheckM Term
quoteRawIn ctx v = do
  ec <- ec_
  pure (quote ec (ctxLen ctx) v)

-- | Read-only normalization probes may encounter values originating in a
-- deeper pattern/closure context. Such a probe is simply inapplicable at the
-- caller depth; only committed Core construction uses 'quoteIn' and its fatal
-- scoping invariant.
tryQuoteIn :: Ctx -> Value -> CheckM (Maybe Term)
tryQuoteIn ctx value = do
  quoted <- quoteRawIn ctx value
  pure (quoted <$ guard (termScopedAt (ctxLen ctx) quoted))

forceM :: Value -> CheckM Value
forceM v = do
  ec <- ec_
  pure (force ec v)

clApp :: Closure -> Value -> CheckM Value
clApp (Closure env body) v = do
  ec <- ec_
  pure (eval ec (v : env) body)

-- | Record a diagnostic. Diagnostics accumulate in reverse (prepend)
-- order; 'checkModule' restores source order once at the end.
report :: Diagnostic -> CheckM ()
report d = modify' $ \st -> st {csDiags = d : csDiags st}

-- | Run an action under a given §16.1.5 place demand, restoring the
-- ambient demand afterwards.
withDemand :: PlaceDemand -> CheckM a -> CheckM a
withDemand d act = do
  old <- gets csDemand
  modify' $ \st -> st {csDemand = d}
  r <- act
  modify' $ \st -> st {csDemand = old}
  pure r

demandOfQ :: Q -> PlaceDemand
demandOfQ q
  | q `elem` [Q1, QGe1] = DemandConsume
  | otherwise = DemandRead

-- | Run an action with @this@ denoting the given §13.2.1 sibling scope.
withThis :: Maybe ThisMode -> CheckM a -> CheckM a
withThis tm act = do
  old <- gets csThis
  modify' $ \st -> st {csThis = tm}
  r <- act
  modify' $ \st -> st {csThis = old}
  pure r

-- | Reject reification of the dictionary currently being completed only at
-- an explicit fresh-evidence request. Method calls may still dispatch through
-- that dictionary while their member body is checked.
withIncompleteSelfEvidenceForbidden :: CheckM a -> CheckM a
withIncompleteSelfEvidenceForbidden action = do
  previous <- gets csForbidIncompleteSelfEvidence
  modify' $ \state -> state {csForbidIncompleteSelfEvidence = True}
  result <- action
  modify' $ \state -> state {csForbidIncompleteSelfEvidence = previous}
  pure result

-- | The neutral standing for the record under §13.2.1 elaboration.
thisG :: GName
thisG = prelThis

-- | §13.2.11 internal existential member labels. The angle-bracket
-- sigil cannot occur in a source identifier (the lexer admits only
-- @[A-Za-z0-9_]@ and non-ASCII letters), so these labels are never
-- source-addressable through @EProj@/@elabDot@ — exactly the spec's
-- requirement that witness members and a non-record payload "are not
-- source-addressable and not rendered as a public field" (Spec.md
-- 13314, 13316-13317). The labels are position-based so that
-- alpha-equivalent existential types elaborate to the same internal
-- shape and remain convertible (Spec.md 13322).
existsWitLabel :: Int -> Text
existsWitLabel i = "⟨wit" <> T.pack (show i) <> "⟩"

-- | The single anonymous non-record payload label of an existential
-- (Spec.md 13316-13317: @⟨payload⟩ : T@, not a field named @value@).
existsPayloadLabel :: Text
existsPayloadLabel = "⟨payload⟩"

-- | Whether a member label is a §13.2.11 internal existential label
-- (witness or anonymous payload). Such labels are not source-visible
-- projection fields.
isExistsInternalLabel :: Text -> Bool
isExistsInternalLabel l = "⟨" `T.isPrefixOf` l

-- | Does a term mention the §13.2.1 @this@ neutral?
mentionsThis :: Term -> Bool
mentionsThis = mentionsGlobal thisG

-- | The sibling field labels a §13.2.1 field type depends on.
thisDepsOf :: Term -> [Text]
thisDepsOf = projectionDepsOf thisG

-- | Sibling dependencies represented in the universe solver language rather
-- than as ordinary Core projections.  Dependent record telescopes use both
-- forms, and their introduction/update order must respect both.
levelFieldDepsOf :: Term -> [Text]
levelFieldDepsOf =
  foldTerm
    (\case
      CSort level -> names level
      CLevel level -> names level
      CGlobal _ universes -> concatMap names universes
      CUniverseLift from to evidence _ ->
        names from
          ++ names to
          ++ concatMap
            (\step -> names (uesLower step) ++ names (uesUpper step)
              ++ concatMap (\(lhs, rhs) -> names lhs ++ names rhs) (uesAssumptions step))
            (ueSteps evidence)
      _ -> [])
    (const [])
  where
    names level = [field | LField _ field <- universeLevelNodes level]

    universeLevelNodes level = level : case level of
      LSucc inner -> universeLevelNodes inner
      LAdd lhs rhs -> universeLevelNodes lhs ++ universeLevelNodes rhs
      LMax lhs rhs -> universeLevelNodes lhs ++ universeLevelNodes rhs
      _ -> []

-- | Substitute a receiver term (well-scoped at the substitution site)
-- for the §13.2.1 @this@ neutral, shifting under binders.
substThisTm :: Term -> Term -> Term
substThisTm = substGlobal thisG

-- | Substitute a receiver term for @this@ inside a field-type value
-- (§13.2.1 dependent projection).
substThisInto :: Ctx -> Term -> Value -> CheckM Value
substThisInto ctx recv fty = do
  ftyTm <- quoteIn ctx fty
  levelFieldSubstitutions <-
    fmap Map.fromList . forM (nub (levelFieldDepsOf ftyTm)) $ \field -> do
      replacement <- receiverFieldLevel recv field
      pure (field, replacement)
  let hasLevelFields = not (null (foldTerm termLevelFields (const []) ftyTm))
      substitutedTerms = substThisTm recv ftyTm
      substitutedLevels =
        zonkTermWith
          (\_ _ -> Nothing)
          (substLevelField levelFieldSubstitutions)
          (ctxLen ctx)
          substitutedTerms
  if mentionsThis ftyTm || hasLevelFields
    then evalIn ctx substitutedLevels
    else pure fty
  where
    termLevelFields = \case
      CSort level -> levelFields level
      CLevel level -> levelFields level
      CGlobal _ universes -> concatMap levelFields universes
      CUniverseLift from to evidence _ ->
        levelFields from
          ++ levelFields to
          ++ concatMap
            (\step -> levelFields (uesLower step) ++ levelFields (uesUpper step)
              ++ concatMap (\(lhs, rhs) -> levelFields lhs ++ levelFields rhs) (uesAssumptions step))
            (ueSteps evidence)
      _ -> []

    receiverFieldLevel receiver field =
      case stripIdentityWrappers receiver of
        CRecordV fields ->
          case lookup field fields of
            Nothing -> pure Nothing
            Just value -> coreTypeLevel ctx value
        _ -> pure (localProjectionLevel ctx (CProjM Ordinary receiver field))

    substLevelField replacements = normalizeLevel . go
      where
        go = \case
          original@(LField _ field) ->
            fromMaybe
              original
              (Map.findWithDefault Nothing field replacements)
          LSucc level -> LSucc (go level)
          LAdd lhs rhs -> LAdd (go lhs) (go rhs)
          LMax lhs rhs -> LMax (go lhs) (go rhs)
          level -> level

-- | Does any field type of the record mention @this@?
recordTypeIsDependent :: Ctx -> [(Text, Value)] -> CheckM Bool
recordTypeIsDependent ctx fs =
  or <$> mapM (fmap mentionsThis . quoteIn ctx . snd) fs

-- | Topologically sort labelled items by their dependency labels;
-- 'Nothing' on a cycle.
topoFields :: [(Text, [Text], a)] -> Maybe [a]
topoFields = goT []
  where
    goT _ [] = Just []
    goT doneLs pending =
      case sortOn (\(label, _, _) -> label) [x | x@(_, ds, _) <- pending, all (`elem` doneLs) ds] of
        [] -> Nothing
        ready -> do
          let readyLs = [l | (l, _, _) <- ready]
              rest = [x | x@(l, _, _) <- pending, l `notElem` readyLs]
          ((map (\(_, _, a) -> a) ready) ++) <$> goT (doneLs ++ readyLs) rest

-- | Report a diagnostic unless an identical (code, message) one was
-- already reported — for judgements re-checked once per occurrence of
-- the same source type (e.g. a signature and its definition binders).
errOnce :: Span -> DiagnosticCode -> Maybe DiagnosticFamily -> Text -> CheckM ()
errOnce sp code fam msg = do
  ds <- gets csDiags
  unless (any (\d -> dCode d == code && dMessage d == msg) ds) $
    errAt sp code fam msg

-- | Like 'errOnce', but distinct origins each report (one diagnostic
-- per malformed source construct, not per judgement).
errOncePerSpan :: Span -> DiagnosticCode -> Maybe DiagnosticFamily -> Text -> CheckM ()
errOncePerSpan sp code fam msg = do
  ds <- gets csDiags
  unless (any (\d -> dCode d == code && dMessage d == msg && dPrimary d == sp) ds) $
    errAt sp code fam msg

errAt :: Span -> DiagnosticCode -> Maybe DiagnosticFamily -> Text -> CheckM ()
errAt sp code fam msg = report (diag SevError StageElaborate code fam sp msg)

mutableBindingPayload :: Text -> Text -> [(Text, Text)] -> Payload
mutableBindingPayload binding selectedFacet fields =
  foldl
    (\p (k, v) -> withPayloadField k v p)
    ( withPayloadField "selectedFacet" selectedFacet $
        withPayloadField "binding" binding $
          payloadKind "mutable-binding"
    )
    fields

errMutableBinding :: Span -> DiagnosticCode -> Text -> Text -> [(Text, Text)] -> Text -> CheckM ()
errMutableBinding sp code binding selectedFacet fields msg =
  report $
    withPayload (mutableBindingPayload binding selectedFacet fields) $
      diag SevError StageElaborate code (Just "kappa.var.mutable-binding") sp msg

mutableBindingInfoFields :: Ctx -> Int -> CtxEntry -> VarRefInfo -> Text -> CheckM [(Text, Text)]
mutableBindingInfoFields ctx i _entry info occurrence = do
  hiddenRef <- renderPayloadValue ctx (vriDiagnosticRefType info)
  stored <- renderPayloadValue ctx (vriStoredType info)
  monadTy <- renderPayloadValue ctx (vriMonadType info)
  evidenceTy <- renderPayloadValue ctx (VGlobN prelMonadRef [(Expl, vriMonadType info)])
  evidence <- renderPayloadTerm ctx (shiftTerm (i + 1) 0 (vriMonadRefDict info))
  pure
    [ ("hiddenReferenceType", hiddenRef)
    , ("storedValueType", stored)
    , ("enclosingMonad", monadTy)
    , ("enclosingDoBlock", "nearest")
    , ("monadRefEvidence", evidence)
    , ("monadRefEvidenceType", evidenceTy)
    , ("occurrence", occurrence)
    ]

mutableBindingLookupFields :: Ctx -> Name -> Text -> CheckM [(Text, Text)]
mutableBindingLookupFields ctx n occurrence =
  case lookupCtx (nameText n) ctx of
    Just (i, entry)
      | Just info <- ceVarInfo entry -> mutableBindingInfoFields ctx i entry info occurrence
    _ -> pure []

recordMutableBindingFields :: Ctx -> Span -> Value -> VarRefInfo -> CheckM ()
recordMutableBindingFields ctx sp _hiddenRefTy info = do
  hiddenRef <- renderPayloadValue ctx (vriDiagnosticRefType info)
  stored <- renderPayloadValue ctx (vriStoredType info)
  monadTy <- renderPayloadValue ctx (vriMonadType info)
  evidenceTy <- renderPayloadValue ctx (VGlobN prelMonadRef [(Expl, vriMonadType info)])
  evidence <- renderPayloadTerm ctx (vriMonadRefDict info)
  let fields =
        [ ("hiddenReferenceType", hiddenRef)
        , ("storedValueType", stored)
        , ("enclosingMonad", monadTy)
        , ("enclosingDoBlock", "nearest")
        , ("monadRefEvidence", evidence)
        , ("monadRefEvidenceType", evidenceTy)
        ]
  modify' $ \st -> st {csMutableBindingFields = Map.insert sp fields (csMutableBindingFields st)}

recordRecognizedRefOp :: Span -> Text -> CheckM ()
recordRecognizedRefOp sp op =
  modify' $ \st -> st {csRecognizedRefOps = Map.insert sp op (csRecognizedRefOps st)}

recordRecognizedMultishotOp :: Span -> EffectOpValueInfo -> CheckM ()
recordRecognizedMultishotOp sp info =
  modify' $ \st ->
    st {csRecognizedMultishotOps = Map.insert sp (eoviLabel info, eoviName info) (csRecognizedMultishotOps st)}

recordEffectOpValueGlobal :: GName -> EffectOpValueInfo -> CheckM ()
recordEffectOpValueGlobal g info =
  modify' $ \st -> st {csEffectOpValueGlobals = Map.insert g info (csEffectOpValueGlobals st)}

recordHandlerOpQuantity :: Span -> Q -> CheckM ()
recordHandlerOpQuantity sp q =
  modify' $ \st -> st {csHandlerOpQuantities = Map.insert sp q (csHandlerOpQuantities st)}

recordPatternBinderQuantity :: Span -> Q -> CheckM ()
recordPatternBinderQuantity sp q =
  modify' $ \st ->
    st {csPatternBinderQuantities = Map.insert sp q (csPatternBinderQuantities st)}

-- | Publish the checked quantity and static-kind status of a pattern binder
-- to the syntax-level usage pass. Observation mode and quantity are
-- independent: an @ordinary 0 A : Type@ field remains statically observable
-- in a pattern even though it contributes no runtime demand.
recordPatternBinderFacts :: Ctx -> Span -> Q -> Value -> CheckM ()
recordPatternBinderFacts ctx sp q ty = do
  recordPatternBinderQuantity sp q
  when (q == Q0) $ do
    staticKind <- isParametricKind (ctxLen ctx) ty
    when staticKind $
      modify' $ \st ->
        st {csStaticKindBinders = Set.insert sp (csStaticKindBinders st)}

recordPatternBinderBorrow :: Span -> CheckM ()
recordPatternBinderBorrow sp =
  modify' $ \st -> st {csPatternBinderBorrows = Set.insert sp (csPatternBinderBorrows st)}

renderPayloadValue :: Ctx -> Value -> CheckM Text
renderPayloadValue ctx v = do
  tm <- quoteIn ctx v
  tm' <- principalizePayloadLevels (ctxLen ctx) tm >>= normalizeTermAt (ctxLen ctx)
  pure (renderTerm tm')

renderPayloadTerm :: Ctx -> Term -> CheckM Text
renderPayloadTerm ctx tm = do
  tm' <- principalizePayloadLevels (ctxLen ctx) tm
  pure (renderTerm tm')

-- | Diagnostic payloads are emitted before the enclosing declaration's final
-- universe solve, but portable payloads must never expose compiler level-meta
-- ids. Compute the same least solution non-destructively for the metas visible
-- in the rendered term. If the constraint set is not yet principal, retain the
-- ordinary zonked term rather than guessing.
principalizePayloadLevels :: Int -> Term -> CheckM Term
principalizePayloadLevels depth term = do
  zonked <- zonkTermM depth term
  st <- get
  let assignments = csLevelAssignments st
      base = zonkLevels assignments zonked
      targets = Set.fromList (levelMetasOfTerm base)
      constraints =
        [ substituteLevelConstraintMetas assignments constraint
        | constraint <- csLevelConstraints st
        ]
  if Set.null targets
    then pure base
    else case solveLevelConstraintsFor targets constraints of
      Left _ -> pure base
      Right solution -> do
        let solved = lsAssignments solution
            unresolved = Set.filter (`Map.notMember` solved) targets
            candidate = Map.union solved (Map.fromSet (const LZero) unresolved)
            residualTargets =
              Set.intersection targets . Set.fromList $
                concat
                  [ levelMetas (substituteLevelMetas candidate (lcLhs constraint))
                      ++ levelMetas (substituteLevelMetas candidate (lcRhs constraint))
                  | constraint <- lsResidual solution
                  ]
        pure $
          if Set.null residualTargets
            then zonkLevels candidate base
            else base

-- | §3 @kappa.unsupported.deterministic@ payload: the family REQUIRES the
-- diagnostic to carry the unsupported action, the selected language profile,
-- and whether source analysis continued (plus a backend profile / required
-- capability when those are relevant — these v1 restrictions are
-- elaboration-level with no owning capability gate, so those fields are
-- recorded as not-applicable). Source analysis continues: the error is
-- collected and the rest of the unit is still checked.
unsupportedPayload :: Text -> Payload
unsupportedPayload action =
  withPayloadField "unsupportedAction" action
    $ withPayloadField "languageProfile" "default"
    $ withPayloadField "backendProfile" "n/a"
    $ withPayloadField "requiredCapability" "none"
    $ withPayloadField "sourceAnalysisContinued" "true"
    $ payloadKind "unsupported-deterministic"

-- | Emit a deterministic-unsupported diagnostic (§3.x family
-- @kappa.unsupported.deterministic@) carrying the mandated payload.
unsupportedAt :: Span -> Text -> CheckM ()
unsupportedAt sp msg =
  report
    ( withPayload (unsupportedPayload msg)
        (diag SevError StageElaborate "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic") sp msg)
    )

-- | Allocate a fresh, unsolved metavariable and return its raw id.
freshMetaId :: CheckM MetaId
freshMetaId = do
  st <- get
  let m = csNextMeta st
  put st {csNextMeta = m + 1, csMetas = Map.insert m Nothing (csMetas st)}
  pure m

freshMeta :: CheckM Term
freshMeta = CMeta <$> freshMetaId

freshMetaV :: Ctx -> CheckM Value
freshMetaV ctx = freshMeta >>= evalIn ctx

-- | Allocate an inference meta whose classifier is already known by the
-- bidirectional checker. This provenance is the authority used by local
-- declaration generalization; reconstructing a classifier later from source
-- shape would make holes and evidence arguments indistinguishable.
freshMetaFor :: Ctx -> Value -> CheckM Term
freshMetaFor ctx classifier = snd <$> freshMetaForWithId ctx classifier

-- | Allocate a classifier-authenticated inference meta while retaining its
-- stable identity for analyses that must track the variable independently of
-- its current solution.
freshMetaForWithId :: Ctx -> Value -> CheckM (MetaId, Term)
freshMetaForWithId ctx classifier = do
  firstClassLevel <- isTypeLevelValue classifier
  meta <- freshMetaId
  classifierTerm <- quoteIn ctx classifier
  modify' $ \st ->
    st
      { csMetaClassifiers =
          Map.insert
            meta
            (MetaClassifier (ctxLen ctx) classifierTerm Nothing)
            (csMetaClassifiers st)
      , csFirstClassLevelMetas =
          if firstClassLevel
            then Set.insert meta (csFirstClassLevelMetas st)
            else csFirstClassLevelMetas st
      }
  pure (meta, CMeta meta)

freshLevelMeta :: CheckM Level
freshLevelMeta = LMeta <$> freshMetaId

-- | Allocate a level that is itself introduced by a source declaration
-- binder or annotation.  This is deliberately different from scanning the
-- elaborated binder domain after the fact: such a domain can contain freshly
-- instantiated universe arguments of referenced declarations, and those are
-- occurrences rather than parameters of the declaration being checked.
freshGeneralizableLevelMeta :: CheckM Level
freshGeneralizableLevelMeta = do
  level <- freshLevelMeta
  markGeneralizableLevelTerm (CSort level)
  pure level

markGeneralizableLevelTermFor :: GName -> Term -> CheckM ()
markGeneralizableLevelTermFor owner term =
  modify' $ \st ->
    let metas = Set.fromList (levelMetasOfTerm term)
     in st
          { csLevelGeneralizableMetas =
              Set.union metas (csLevelGeneralizableMetas st)
          , csLevelGeneralizableOwners =
              Set.foldl'
                (\owners meta -> Map.insertWith Set.union meta (Set.singleton owner) owners)
                (csLevelGeneralizableOwners st)
                metas
          }

markGeneralizableLevelTerm :: Term -> CheckM ()
markGeneralizableLevelTerm term = do
  owner <- gets csActiveUniverseDefinition
  forM_ owner $ \declaration ->
    markGeneralizableLevelTermFor declaration term

-- | At an inferred declaration boundary the completed semantic classifier,
-- not the provenance of the metavariable that happened to reach it, decides
-- which universe positions admit declaration generalization (§11.3.3). This
-- is what preserves an existing polymorphic value in @let boo = foo@: lookup
-- freshens @foo@'s schema as an occurrence, but the fresh level occurs in a
-- parameter position of @boo@'s inferred classifier and is therefore a
-- declaration candidate. Result-only occurrence choices remain minimizable.
markInferredDeclarationLevelCandidates :: GName -> Value -> CheckM ()
markInferredDeclarationLevelCandidates owner classifier = do
  classifierTerm <- quoteIn emptyCtx classifier >>= zonkTermM 0
  markDeclarationSchemaLevelCandidates owner classifierTerm

-- | Mark exactly the levels contributed by a declaration's semantic schema.
-- Generated comparison binders and the source endpoint of a cumulative lift
-- are checking evidence, while the lifted payload and the surrounding
-- nominal/application spine remain part of the declaration interface.
markDeclarationSchemaLevelCandidates :: GName -> Term -> CheckM ()
markDeclarationSchemaLevelCandidates owner term =
  forM_ (Set.toAscList candidates) $ \meta ->
    markGeneralizableLevelTermFor owner (CSort (LMeta meta))
  where
    candidates = declarationSchemaGeneralizableMetas term

declarationSchemaGeneralizableMetas :: Term -> Set LevelMeta
declarationSchemaGeneralizableMetas term =
  Set.intersection
    (durGeneralizable (declarationUniverseRoles term))
    (schemaBearingLevelMetas term)

constructorSchemaGeneralizableMetas :: Term -> Set LevelMeta
constructorSchemaGeneralizableMetas term =
  Set.intersection
    (durGeneralizable (constructorUniverseRoles term))
    (schemaBearingLevelMetas term)

-- | Levels visible only in cumulative annotations or generated level-proof
-- binders are occurrence/checking facts, not evidence that an inferred value
-- abstracts over that level. Ordinary nominal spines and source binders remain
-- schema-bearing. This distinction is made only while promoting inferred
-- occurrence metas; finalized interface role analysis still sees its complete
-- proof telescope.
schemaBearingLevelMetas :: Term -> Set LevelMeta
schemaBearingLevelMetas =
  Set.fromList . levelMetasOfTerm . eraseCheckingAnnotations
  where
    eraseCheckingAnnotations =
      mapTermWithDepth
        ( \_ -> \case
            CUniverseLift _ _ _ payload ->
              Just (eraseCheckingAnnotations payload)
            CPiEvidenceM _ _ _ _ _ _ (Just _) _ _ codomain ->
              Just (eraseCheckingAnnotations codomain)
            _ -> Nothing
        )
        0

inheritGeneralizableLevelRoles :: GName -> GName -> Term -> CheckM ()
inheritGeneralizableLevelRoles source target term = do
  owners <- gets csLevelGeneralizableOwners
  let inherited =
        [ meta
        | meta <- levelMetasOfTerm term
        , source `Set.member` Map.findWithDefault Set.empty meta owners
        ]
  forM_ inherited $ \meta ->
    markGeneralizableLevelTermFor target (CSort (LMeta meta))

-- | Allocate a universe metavariable for one omitted declaration-universe
-- instantiation. Such a meta may occur in a user-observable interface, but it
-- does not itself denote a new source universe parameter. Its least admissible
-- value is selected during SCC principalization (§11.1.2.4A).
freshLevelInstantiationMeta :: CheckM Level
freshLevelInstantiationMeta = do
  level <- freshLevelMeta
  owner <- gets csActiveUniverseDefinition
  case level of
    LMeta meta ->
      modify' $ \st ->
        st
          { csLevelInstantiationMetas =
              Set.insert meta (csLevelInstantiationMetas st)
          , csLevelInstantiationOwners =
              case owner of
                Nothing -> csLevelInstantiationOwners st
                Just declaration ->
                  Map.insertWith
                    Set.union
                    meta
                    (Set.singleton declaration)
                    (csLevelInstantiationOwners st)
          }
    _ -> pure ()
  pure level

-- | §11.1.2.3: bare @Type@ is floating.  The source span is the annotation
-- identity used by grouped declarations, whose parser expansion intentionally
-- reuses one annotation node; separate annotations have distinct spans and
-- therefore receive independent metas.
bareTypeLevel :: Span -> CheckM Level
bareTypeLevel sp = do
  known <- gets (Map.lookup sp . csBareTypeLevels)
  level <- case known of
    Just existing -> pure existing
    Nothing -> do
      fresh <- freshLevelMeta
      modify' $ \st -> st {csBareTypeLevels = Map.insert sp fresh (csBareTypeLevels st)}
      pure fresh
  generalizable <- gets csGeneralizeBareTypeLevels
  when generalizable (markGeneralizableLevelTerm (CSort level))
  pure level

-- | Give bare @Type@ nodes their parameter-position provenance while a
-- syntactic binder domain is elaborated. This is intentionally not inferred
-- from the resulting Core term: that term can contain freshly specialized
-- universes belonging to referenced declarations.
withGeneralizableBareTypeLevels :: CheckM a -> CheckM a
withGeneralizableBareTypeLevels action = do
  previous <- gets csGeneralizeBareTypeLevels
  modify' $ \st -> st {csGeneralizeBareTypeLevels = True}
  result <- action
  modify' $ \st -> st {csGeneralizeBareTypeLevels = previous}
  pure result

-- | A lazily forced declaration header may be reached while elaborating a
-- caller's binder domain. The caller's source-role marker is lexical and must
-- not leak into the callee's result classifier; the callee's own binder
-- domains re-enter 'withGeneralizableBareTypeLevels' explicitly.
withoutGeneralizableBareTypeLevels :: CheckM a -> CheckM a
withoutGeneralizableBareTypeLevels action = do
  previous <- gets csGeneralizeBareTypeLevels
  modify' $ \st -> st {csGeneralizeBareTypeLevels = False}
  result <- action
  modify' $ \st -> st {csGeneralizeBareTypeLevels = previous}
  pure result

-- | Semantic caches are keyed by a small epoch rather than by the whole
-- evaluator state.  Advancing the epoch is required when global lookup,
-- trait/instance lookup, or conversion-time reducibility changes.
-- Metavariable-sensitive normalization/proposition entries are kept out of the
-- caches until their quoted keys contain no unsolved metas; otherwise every
-- solved evidence hole would invalidate the very cache meant to tame evidence
-- storms.  Clearing the maps at the same time keeps memory use bounded on
-- proof-heavy files and prevents stale trait evidence after a new instance
-- enters scope.
invalidateSemanticCaches :: CheckState -> CheckState
invalidateSemanticCaches st =
  st
    { csEvidenceCache = Map.empty
    , csNormEpoch = csNormEpoch st + 1
    , csNormCache = Map.empty
    , csPropCache = Map.empty
    }

maxNormCacheEntries :: Int
maxNormCacheEntries = 8192

maxPropCacheEntries :: Int
maxPropCacheEntries = 8192

maxEvidenceCacheEntries :: Int
maxEvidenceCacheEntries = 4096

-- | Deterministic bounded insertion.  This is deliberately not an LRU cache:
-- carrying access-order state through the checker would complicate auditing
-- without changing the trusted result.  Dropping the smallest structural key
-- keeps the bound strict and leaves cache contents semantically irrelevant.
boundedInsert :: Ord k => Int -> k -> a -> Map k a -> Map k a
boundedInsert cap k v m =
  let m' = Map.insert k v m
   in if Map.size m' <= cap
        then m'
        else snd (Map.deleteFindMin m')

-- | Structural key for cache lookups.  This intentionally uses Core's derived
-- representation, not user-facing pretty printing: it is exact enough for a
-- best-effort cache and never participates in user-visible output or
-- reproducibility.
renderStructuralTermKey :: Term -> Text
renderStructuralTermKey = T.pack . show

-- | A declaration-universe parameter is lexical to its owning hidden
-- telescope. Cache entries may retain such parameters only while keyed by
-- that same declaration, and every index must be in range. This preserves
-- useful within-body caching without allowing syntactically identical
-- @LParam 0@ values from unrelated declarations to alias.
termCacheUniverseScoped :: CheckState -> Term -> Bool
termCacheUniverseScoped st term =
  case csActiveUniverseDefinition st >>= (`Map.lookup` csGlobals st) of
    Nothing -> null parameters
    Just definition ->
      let arity = dutParameterCount (gdUniverses definition)
       in all (\parameter -> parameter >= 0 && parameter < arity) parameters
  where
    parameters = levelParamsOfTerm term

solveMeta :: HasCallStack => MetaId -> Value -> CheckM ()
solveMeta m v = do
  state <- get
  case Map.lookup m (csMetaClassifiers state) of
    Just classifier
      | let depth = micDepth classifier
            candidate = quote (ecOf state) depth v
      , not (termScopedAt depth candidate) ->
          error
            ( "Kappa.Check.solveMeta: internal error: candidate for meta "
                <> show m
                <> " escapes its creation depth "
                <> show depth
                <> "\nclassifier: "
                <> show (micType classifier)
                <> "\ncandidate: "
                <> show candidate
                <> "\neffective level: "
                <> show
                  ( substituteLevelMetas
                      (csLevelAssignments state)
                      (LMeta m)
                  )
                <> "\n"
                <> prettyCallStack callStack
            )
    _ -> pure ()
  modify' $ \next ->
    next
      { csMetas = Map.insert m (Just v) (csMetas next)
      , csSolvedMetas = Set.insert m (csSolvedMetas next)
      }

-- | Solve a metavariable only when the candidate value is acyclic through the
-- current solved-meta graph.  The ordinary occurs check used to quote the
-- candidate first; that is unsafe when another solved meta already points back
-- to the target, because quotation/forcing can chase the cycle indefinitely.
-- Walking the value graph directly rejects exactly those cyclic solutions
-- without normalizing user code.
solveMetaAcyclic :: MetaId -> Value -> CheckM Bool
solveMetaAcyclic m v = do
  state <- get
  let metas = csMetas state
      scoped =
        case Map.lookup m (csMetaClassifiers state) of
          Nothing -> True
          Just classifier ->
            termScopedAt
              (micDepth classifier)
              (quote (ecOf state) (micDepth classifier) v)
  if not scoped || metaOccursInValue metas m v
      then pure False
      else solveMeta m v >> pure True

freshNameM :: Text -> CheckM Text
freshNameM base = do
  st <- get
  put st {csFresh = csFresh st + 1}
  pure (base <> T.pack (show (csFresh st)))

-- | Semantic generated globals must not inherit the allocation order of
-- unrelated checker temporaries. The declaration origin is the authoritative
-- identity source until the frontend carries first-class declaration IDs.
stableGeneratedNameAt :: Text -> Text -> Span -> CheckM Text
stableGeneratedNameAt category written site = do
  owner <- gets (moduleNameText . csModule)
  pure
    ( "#generated."
        <> category
        <> "."
        <> owner
        <> "."
        <> written
        <> "@"
        <> T.pack (spanFile site)
        <> ":"
        <> T.pack (show (posLine (spanStart site)))
        <> ":"
        <> T.pack (show (posCol (spanStart site)))
    )

-- | Install a checked Core body as the single authority for both lowering and
-- NbE. Declaration-universe generalization rewrites the Core term; retaining a
-- semantic value evaluated from the pre-generalized term leaves solved metas
-- whose 'LParam's belong to the old declaration telescope. Re-evaluating the
-- closed body is structural (functions remain closures and global references
-- remain neutral) and keeps every later lookup on the same generalized term.
canonicalCoreBodyForDefinition :: GlobalDef -> Term -> Term
canonicalCoreBodyForDefinition definition =
  zonkTermWith
    (\_ _ -> Nothing)
    ( substituteLevelMetas
        ( Map.fromList
            [ (meta, LParam parameter)
            | (meta, parameter) <-
                gdProvisionalUniverseProjection definition
            , parameter >= 0
            , parameter < dutParameterCount (gdUniverses definition)
            ]
        )
    )
    0

globalDefWithCanonicalCoreBody :: CheckState -> Term -> GlobalDef -> GlobalDef
globalDefWithCanonicalCoreBody st body definition =
  let canonicalBody = canonicalCoreBodyForDefinition definition body
   in
  definition
    { gdValue = Just (eval (ecOf st) [] canonicalBody)
    , gdCoreBody = Just canonicalBody
    }

addGlobal :: GName -> GlobalDef -> CheckM ()
addGlobal g@(GName m nm) gd = modify' $ \st ->
  let gdWithBody =
        maybe gd (\body -> globalDefWithCanonicalCoreBody st body gd)
          (Map.lookup g (csCoreBodies st))
      gd' =
        if Map.null (csActiveUniverseSchema st)
          then gdWithBody
          else
            globalDefWithUniverses
              ( DeclarationUniverseTelescope
                  (Map.size (csActiveUniverseSchema st))
                  True
              )
              gdWithBody
   in invalidateSemanticCaches
    ( st
        { csGlobals = Map.insert g gd' (csGlobals st)
        , -- Keep the §3.2.2 typo-suggestion index (if already built) in step
          -- with the module's own globals, so it never needs a full rebuild
          -- (see 'moduleScopeNameIndex'). Names from other modules are not
          -- unqualified-in-scope here, so only this module's globals extend it.
          csScopeNameCache =
            if m == csModule st
              then fmap (insertScopeName nm) (csScopeNameCache st)
              else csScopeNameCache st
        }
    )

-- | Add one spelling to the length-bucketed §3.2.2 candidate index.
insertScopeName :: Text -> Map Int (Set Text) -> Map Int (Set Text)
insertScopeName nm = Map.insertWith Set.union (T.length nm) (Set.singleton nm)

-- | Record the elaborated KCore body of a top-level term definition for
-- the native backend (see 'csCoreBodies'). Called from 'elabLetDecl'
-- after zonking, with the body the interpreter would evaluate.
recordCoreBody :: GName -> Term -> CheckM ()
recordCoreBody g tm = do
  definition <- gets (Map.lookup g . csGlobals)
  ec <- ec_
  let proofBinders = maybe [] (generatedConstraintBinderNames . globalCoreType ec) definition
      canonical0 =
        canonicalizeSchemaLiftComposition
          (ensureGeneratedConstraintLambdas proofBinders tm)
      canonical =
        maybe canonical0
          (`canonicalCoreBodyForDefinition` canonical0)
          definition
  modify' $ \st ->
    st
      { csCoreBodies = Map.insert g canonical (csCoreBodies st)
      , csGlobals =
          Map.adjust
            (globalDefWithCanonicalCoreBody st canonical)
            g
            (csGlobals st)
      }

-- Certified schema actions are representation identities, so a linear chain
-- of let-bound actions is one action from the first source to the final
-- target. Canonicalizing this exact, single-use shape preserves evaluation
-- order while retaining every covariance proof step.
canonicalizeSchemaLiftComposition :: Term -> Term
canonicalizeSchemaLiftComposition = mapTermWithDepth rewrite 0
  where
    rewrite _ (CLetM _ _ _ _ first body) = do
      (family, source, middle, roles, firstEvidence, certificate, sourceArguments, middleArguments, payload) <- schemaLift first
      second <- case body of
        direct@CSchemaLift {} -> Just direct
        CLetM _ _ _ _ direct (CVar 0) -> Just direct
        _ -> Nothing
      (family', middle', target, roles', secondEvidence, certificate', middleArguments', targetArguments, CVar 0) <- schemaLift second
      guard
        ( family == family'
            && map normalizeLevel middle == map normalizeLevel middle'
            && roles == roles'
            && certificate == certificate'
            && middleArguments == middleArguments'
        )
      evidence <- composeEvidence roles firstEvidence secondEvidence
      pure (CSchemaLift family source target roles evidence certificate sourceArguments targetArguments payload)
    rewrite _ _ = Nothing
    schemaLift = \case
      CSchemaLift family source target roles evidence certificate sourceArguments targetArguments payload ->
        Just (family, source, target, roles, evidence, certificate, sourceArguments, targetArguments, payload)
      _ -> Nothing
    composeEvidence roles first second
      | length roles /= length first || length roles /= length second = Nothing
      | otherwise = zipWith3M compose roles first second
    compose role left right = case (role, left, right) of
      (Invariant, SchemaInvariantEvidence, SchemaInvariantEvidence) -> Just SchemaInvariantEvidence
      (Irrelevant, SchemaIrrelevantEvidence, SchemaIrrelevantEvidence) -> Just SchemaIrrelevantEvidence
      (Covariant, SchemaCovariantEvidence (UniverseEvidence lhs), SchemaCovariantEvidence (UniverseEvidence rhs)) ->
        Just (SchemaCovariantEvidence (UniverseEvidence (lhs ++ rhs)))
      _ -> Nothing
    zipWith3M _ [] [] [] = Just []
    zipWith3M f (a : as) (b : bs) (c : cs) = (:) <$> f a b c <*> zipWith3M f as bs cs
    zipWith3M _ _ _ _ = Nothing

recordTerminationDecl :: TerminationDecl -> CheckM ()
recordTerminationDecl td =
  modify' $ \st -> st {csTerminationDecls = Map.insert (tdName td) td (csTerminationDecls st)}

-- | Keep a definition opaque until the SCC pass when a later declaration may
-- still close a cycle through it.  Acyclic dependencies on already-reducible
-- functions stay reducible immediately, preserving the existing conversion
-- behavior for ordinary helper definitions.
shouldDeferTermination :: GName -> Set GName -> CheckM Bool
shouldDeferTermination g deps = do
  st <- get
  let termDeps = Set.intersection deps (csTerminationNames st)
      pendingDeps = Set.intersection termDeps (Map.keysSet (csSigPending st))
      deferredDeps =
        Set.filter
          (\h ->
             Map.member h (csTerminationDecls st)
               && maybe False (not . gdReducible) (Map.lookup h (csGlobals st))
          )
          termDeps
  pure (Set.member g deps || not (Set.null pendingDeps) || not (Set.null deferredDeps))

-- | A direct self-recursive declaration may be certified as soon as every
-- other termination-relevant dependency is already conversion-reducible.
-- Requiring the complete dependency set to be exactly @{self}@ incorrectly
-- keeps ordinary recursion opaque when it calls an earlier total helper. A
-- pending signature or an earlier opaque declaration may still close a larger
-- SCC, so those dependencies continue to defer certification.
singletonTerminationDependenciesReady :: GName -> Set GName -> CheckM Bool
singletonTerminationDependenciesReady self dependencies = do
  state <- get
  let termDependencies =
        Set.delete self
          (Set.intersection dependencies (csTerminationNames state))
      ready dependency =
        dependency `Set.notMember` Map.keysSet (csSigPending state)
          && maybe False gdReducible (Map.lookup dependency (csGlobals state))
  pure (all ready (Set.toList termDependencies))

-- | §3.1.1A: record the first declaration site of a module-scope name
-- (later occurrences keep the earliest span). Consulted by the
-- duplicate-declaration diagnostic to cite the original site.
recordDeclSite :: GName -> Span -> CheckM ()
recordDeclSite g sp =
  modify' $ \st -> st {csDeclSites = Map.insertWith (\_ old -> old) g sp (csDeclSites st)}

-- | §3.1.1A duplicate-declaration related origins: the new (rejected)
-- declaration site as @declaration-site@, plus the original declaration
-- site (when recorded) as a second @declaration-site@. Both sites MUST
-- appear (§3.1.1A: "duplicate-declaration diagnostics MUST include both
-- sites"). Also attaches the §3.2.2 name payload.
duplicateRelated :: Text -> GName -> Span -> CheckM (Diagnostic -> Diagnostic)
duplicateRelated nm g sp = do
  mPrior <- gets (Map.lookup g . csDeclSites)
  let payload =
        withPayloadField "name" nm $
          payloadKind "name-duplicate"
      newSite = related RoleDeclarationSite sp ("redeclaration of '" <> nm <> "'")
      priorSite = case mPrior of
        Just psp | psp /= sp -> [related RoleDeclarationSite psp ("'" <> nm <> "' first declared here")]
        _ -> []
  pure (withPayload payload . withRelateds (newSite : priorSite))

-- ── Unification ──────────────────────────────────────────────────────

-- | Pi binder-quantity subsumption (§12.2.1): a function whose demand
-- interval is contained in the expected binder's demand may stand at
-- that type — every argument capability satisfying the expected demand
-- also satisfies the actual one (e.g. a @(1 x : A) -> B@ value may be
-- used where @(x : A) -> B@ is expected, but not vice versa).
qSubsumes :: Q -> Q -> Bool
qSubsumes qa qe = qa == qe || qInterval qa `contained` qInterval qe
  where
    qInterval :: Q -> (Int, Maybe Int)
    qInterval = \case
      Q0 -> (0, Just 0)
      Q1 -> (1, Just 1)
      QLe1 -> (0, Just 1)
      QGe1 -> (1, Nothing)
      QW -> (0, Nothing)
    contained (lo1, hi1) (lo2, hi2) =
      lo1 >= lo2 && case (hi1, hi2) of
        (_, Nothing) -> True
        (Nothing, Just _) -> False
        (Just h1, Just h2) -> h1 <= h2

-- | Outer-Pi observation-mode subsumption (§12.1.1, §30.2.0). In checking
-- direction, a function whose binder is parametric may stand where an
-- ordinary-binder function is expected: it accepts every ordinary argument
-- the expected contract permits, and more. The converse would let a caller
-- pass a parametrically-dependent argument to an ordinary-only function.
-- Like quantity subsumption, this is not definitional equality and is never
-- enabled in domains or nested type arguments.
observationModeSubsumes :: ObservationMode -> ObservationMode -> Bool
observationModeSubsumes actual expected =
  actual == expected || (actual == Parametric && expected == Ordinary)

-- | Reconcile one universe inequality with the module's pending constraint
-- set. A blocked comparison is accepted provisionally, but never guessed in
-- isolation: all lower bounds for a meta are joined by 'solveLevelConstraints'
-- before its corresponding first-class TypeLevel meta is assigned. This is
-- the order-independence boundary required by §11.1.3.
solveLevelInequality :: Ctx -> Level -> Level -> CheckM Bool
solveLevelInequality ctx lhs0 rhs0 = do
  -- Keep the original constraint graph until its owning boundary. Installing
  -- a provisional lower bound here makes checking order observable: after
  -- seeing @1 <= ?u@, a later @3 <= ?u@ would be compared with @1@ instead of
  -- joining both lower bounds. The pure solver may be queried provisionally,
  -- but only a boundary solve is committed to Core metas.
  assignments <- gets csLevelAssignments
  let lhs = normalizeLevel (substituteLevelMetas assignments lhs0)
      rhs = normalizeLevel (substituteLevelMetas assignments rhs0)
  assumptions <- effectiveLevelAssumptions ctx
  case proveLevelLeq assumptions lhs rhs of
    Proved -> pure True
    Disproved -> do
      generalized <- recordActiveUniverseRequirement assumptions lhs rhs
      if generalized
        then pure True
        else do
          localGeneralized <-
            recordActiveLocalUniverseRequirement assumptions lhs rhs
          if localGeneralized
            then pure True
            -- A rigid failed conversion that mentions lexical level identities
            -- cannot become a declaration-schema requirement. It is a failed
            -- conversion now, not a provisional constraint: speculative
            -- application checking is allowed to roll state back and would
            -- otherwise silently discard the contradiction.
            else pure False
    ContradictoryAssumptions -> do
      insertLevelConstraint assumptions
        (ConstraintOrigin "contradictory universe assumptions" "type conversion")
        lhs rhs
      pure True
    Blocked _ -> do
      registerLevelConstraint ctx "sort conversion" "type conversion" lhs rhs
      -- A blocked inequality is provisionally valid until the owning
      -- declaration/module boundary solves the complete constraint set. Running
      -- that global set here makes an unrelated pending contradiction appear as
      -- a failure of this expression and makes acceptance depend on traversal
      -- order. Rigid contradictions still take the 'Disproved' branch above.
      pure True
    IndeterminateResourceLimit -> do
      registerLevelConstraint ctx "sort conversion" "type conversion" lhs rhs
      pure True

-- | Constructor-size checking has a more specific failure contract than
-- ordinary cumulative conversion.  A rigid failed field bound is a
-- constructor-size error, while a relation closed over the enclosing data
-- schema becomes an erased declaration proof binder.  Meta-bearing bounds
-- remain deferred to the declaration SCC solver.
solveConstructorLevelInequality :: Ctx -> Level -> Level -> CheckM Bool
solveConstructorLevelInequality ctx lhs0 rhs0 = do
  assignments <- gets csLevelAssignments
  let lhs = normalizeLevel (substituteLevelMetas assignments lhs0)
      rhs = normalizeLevel (substituteLevelMetas assignments rhs0)
  assumptions <- effectiveLevelAssumptions ctx
  case proveLevelLeq assumptions lhs rhs of
    Proved -> pure True
    Disproved -> recordActiveUniverseRequirement assumptions lhs rhs
    ContradictoryAssumptions -> do
      registerLevelConstraint ctx "contradictory universe assumptions" "constructor-size checking" lhs rhs
      pure True
    Blocked _ -> do
      registerLevelConstraint ctx "constructor field universe" "constructor-size checking" lhs rhs
      pure True
    IndeterminateResourceLimit -> do
      registerLevelConstraint ctx "constructor field universe" "constructor-size checking" lhs rhs
      pure True

-- | Run constructor checking with the enclosing nominal family as the owner
-- of any retained universe obligation.  Constructors do not have an
-- independent declaration schema: a bound such as @succ u <= 3@ is part of
-- the family interface and every constructor result must pass its proof to
-- that family application.  Unlike 'withActiveUniverseDefinition', this
-- scope deliberately does not materialize the proof immediately; the data
-- header installs the family and all constructor interfaces atomically.
withUniverseConstraintOwner :: GName -> CheckM a -> CheckM a
withUniverseConstraintOwner owner action = do
  previous <- gets csActiveUniverseDefinition
  modify' $ \st -> st {csActiveUniverseDefinition = Just owner}
  result <- action
  modify' $ \st -> st {csActiveUniverseDefinition = previous}
  pure result

-- | Hidden declaration-universe arguments are part of global conversion
-- identity, so matching two occurrences requires level equality rather than
-- one-way cumulativity. Blocked equalities are recorded in both directions
-- and discharged at the declaration boundary. This hot path deliberately
-- avoids rerunning the complete solver after every global comparison; rigid
-- disagreement still rejects immediately and finalization remains the
-- fail-closed authority.
solveLevelIdentity :: Ctx -> Level -> Level -> CheckM Bool
solveLevelIdentity ctx lhs0 rhs0 = do
  assignments <- gets csLevelAssignments
  let lhs = normalizeLevel (substituteLevelMetas assignments lhs0)
      rhs = normalizeLevel (substituteLevelMetas assignments rhs0)
  assumptions <- effectiveLevelAssumptions ctx
  case (proveLevelLeq assumptions lhs rhs, proveLevelLeq assumptions rhs lhs) of
    (Proved, Proved) -> pure True
    (Disproved, _) -> recordActiveUniverseIdentity assumptions lhs rhs
    (_, Disproved) -> recordActiveUniverseIdentity assumptions lhs rhs
    _ -> do
      registerLevelConstraint ctx "global universe identity" "global reference" lhs rhs
      registerLevelConstraint ctx "global universe identity" "global reference" rhs lhs
      pure True

-- | Exact hidden-universe identity discovered while checking a definition is a
-- pair of constraints on that definition's generalized telescope. Install the
-- pair atomically: retaining only one direction after the reverse direction
-- fails would weaken the declaration interface and make a failed conversion
-- mutate subsequent checking.
recordActiveUniverseIdentity :: Assumptions -> Level -> Level -> CheckM Bool
recordActiveUniverseIdentity assumptions lhs rhs =
  recordActiveUniverseRequirements
    assumptions
    [ UniverseConstraint lhs rhs
    , UniverseConstraint rhs lhs
    ]

-- | Hidden declaration-universe constraints are assumptions while checking
-- the declaration that owns them. They are not ambient assumptions at an
-- ordinary reference: 'instantiateUniverseTelescope' turns them into fresh
-- level constraints for that use instead.
effectiveLevelAssumptions :: Ctx -> CheckM Assumptions
effectiveLevelAssumptions ctx = do
  active <- gets csActiveUniverseDefinition
  globals <- gets csGlobals
  pending <- gets csPendingUniverseProofs
  assignments <- gets csLevelAssignments
  ec <- ec_
  let scoped = case active >>= (`Map.lookup` globals) of
        Nothing -> ctxLevelAssumptions ctx
        Just gd ->
          foldl'
            (\assumptions constraint -> insertAssumption (ucLower constraint) (ucUpper constraint) assumptions)
            (ctxLevelAssumptions ctx)
            ( declarationConstraintSummary (dutParameterCount (gdUniverses gd)) (globalCoreType ec gd)
                ++ maybe [] id (active >>= (`Map.lookup` pending))
            )
  pure (substituteLevelAssumptions assignments scoped)

substituteLevelAssumptions :: Map LevelMeta Level -> Assumptions -> Assumptions
substituteLevelAssumptions assignments =
  foldr
    (\(lower, upper) assumptions ->
      insertAssumption
        (normalizeLevel (substituteLevelMetas assignments lower))
        (normalizeLevel (substituteLevelMetas assignments upper))
        assumptions)
    emptyAssumptions
    . assumptionsList

-- | The declaration type is the sole authority for schema constraints.  A
-- summary is admissible only when an authenticated Pi assumption is closed
-- over this declaration's hidden universe parameters; term-local level
-- variables, fields, and metas are ordinary lexical assumptions instead.
declarationConstraintSummary :: Int -> Term -> [UniverseConstraint]
declarationConstraintSummary = declarationUniverseConstraints

constraintProofType :: UniverseConstraint -> Term
constraintProofType (UniverseConstraint lower upper) =
  CApp Expl
    (CApp Expl (CGlobal prelLevelLe []) (CLevel lower))
    (CLevel upper)

generatedConstraintName :: Int -> Text
generatedConstraintName index = "__universeConstraint" <> T.pack (show index)

prependGeneratedConstraintBinders
  :: Int
  -> [UniverseConstraint]
  -> Term
  -> Term
  -> (Term, Term)
prependGeneratedConstraintBinders parameterCount requested ty body =
  let generated = generatedConstraintsNotIn parameterCount requested ty
      existing = declarationConstraintSummary parameterCount ty
      indexed = zip [length existing ..] generated
      wrapType (index, constraint@(UniverseConstraint lower upper)) codomain =
        CPiEvidenceM Ordinary FormationOrdinary Impl Q0 False
          (generatedConstraintName index)
          (Just (lower, upper))
          BinderGenerated
          (constraintProofType constraint)
          codomain
      wrapBody (index, _) term =
        CLamM Ordinary Impl Q0 (generatedConstraintName index) term
   in (foldr wrapType ty indexed, foldr wrapBody body indexed)

generatedConstraintsNotIn :: Int -> [UniverseConstraint] -> Term -> [UniverseConstraint]
generatedConstraintsNotIn parameterCount requested ty =
  let existing = declarationConstraintSummary parameterCount ty
      existingAssumptions =
        foldl'
          (\assumptions constraint ->
             insertAssumption (ucLower constraint) (ucUpper constraint) assumptions)
          emptyAssumptions
          existing
   in [ constraint
      | constraint <- dedupeUniverseConstraints requested
      , not (any (equivalentUniverseConstraint constraint) existing)
      , proveLevelLeq existingAssumptions (ucLower constraint) (ucUpper constraint) /= Proved
      ]

-- | §11.1.2.3A.3 orders generated proof binders by the first occurrence of
-- their normalized proposition in the completed declaration signature.
-- Constraint allocation order is an implementation detail: speculative
-- elaboration and candidate rollback may allocate equivalent obligations in
-- a different order.  The diagnostic span is the retained signature
-- occurrence identity; normalized endpoints provide a deterministic order
-- for multiple obligations originating at the same syntax node.  Constraints
-- without a source occurrence sort after source-backed obligations and by
-- their semantic proposition only.
orderLevelConstraintsBySignatureOccurrence
  :: CheckState
  -> [LevelConstraint]
  -> [LevelConstraint]
orderLevelConstraintsBySignatureOccurrence state =
  sortOn lcIdentity

-- | Add the generated proof arguments required by uses of a nominal family
-- before wrapping the containing declaration in the corresponding proof
-- binders.  At local depth @d@, the newly prepended binders live at indices
-- @d + n - 1 .. d@.  Rewriting the resolved global identity rather than a
-- source spelling keeps constructor result applications and nested GADT
-- results aligned with the family's physical Core telescope.
applyGeneratedConstraintArguments :: GName -> Int -> Term -> Term
applyGeneratedConstraintArguments _ 0 term = term
applyGeneratedConstraintArguments owner count term =
  mapTermWithDepth rewrite 0 term
  where
    rewrite depth = \case
      CGlobal target universes | target == owner ->
        Just $
          foldl'
            (CApp Impl)
            (CGlobal target universes)
            [CVar (depth + count - index - 1) | index <- [0 .. count - 1]]
      _ -> Nothing

-- | Repair a body at the exact boundary where declaration constraints become
-- new outer proof binders. Pending evidence metas are replaced only by a
-- semantically equal caller constraint. A global receives the newly-prepended
-- target arguments only when every target constraint, after specializing its
-- declaration universe spine, matches an available caller binder. Any other
-- call remains ill-typed for the finalized interface and is rejected by the
-- ordinary Core verifier rather than receiving guessed evidence.
rewriteGeneratedConstraintEvidence
  :: Map GName [UniverseConstraint]
  -> [UniverseConstraint]
  -> Map MetaId UniverseConstraint
  -> Term
  -> (Term, Set MetaId)
rewriteGeneratedConstraintEvidence targetConstraints callerConstraints pendingEvidence body =
  (mapTermWithDepth rewrite 0 body, resolvedPending)
  where
    callerCount = length callerConstraints
    bodyMetas = Set.fromList (metaIdsOf body)
    pendingIndices =
      Map.mapMaybe
        (\constraint -> List.findIndex (equivalentUniverseConstraint constraint) callerConstraints)
        pendingEvidence
    resolvedPending = Set.intersection bodyMetas (Map.keysSet pendingIndices)

    proofVariable depth index = CVar (depth + callerCount - index - 1)

    rewrite depth = \case
      CMeta meta
        | Just index <- Map.lookup meta pendingIndices ->
            Just (proofVariable depth index)
      CGlobal target universes
        | Just constraints <- Map.lookup target targetConstraints
        , not (null constraints)
        , Just indices <- traverse callerIndex (map instantiate constraints) ->
            Just $
              foldl'
                (CApp Impl)
                (CGlobal target universes)
                [proofVariable depth index | index <- indices]
        where
          instantiate (UniverseConstraint lower upper) =
            UniverseConstraint
              (normalizeLevel (substituteLevelParams universes lower))
              (normalizeLevel (substituteLevelParams universes upper))
      _ -> Nothing

    callerIndex constraint =
      List.findIndex (equivalentUniverseConstraint constraint) callerConstraints

-- | Complete applications of declarations whose generated constraint prefix
-- was discovered only by the final declaration-SCC solve.  Unlike the
-- boundary repair above, this runs after the caller's complete proof-lambda
-- prefix is present, so a caller constraint at telescope position @i@ is the
-- de Bruijn variable @depth - i - 1@.  A specialized target obligation may
-- use either that exact authenticated binder or the canonical erased witness
-- when rigid entailment proves it from the caller telescope.  Blocked and
-- false obligations are deliberately left missing for typed-Core validation
-- to reject.
data GeneratedProofScope
  = GeneratedProofLambdas
  | GeneratedProofTelescope

data GeneratedProofEnvironment = GeneratedProofEnvironment
  { gpeAvailableCallerConstraints :: ![(Int, UniverseConstraint)]
  , gpeCallerAssumptions :: !Assumptions
  , gpeRigidWitness :: !(Maybe Term)
  }

generatedProofEnvironment
  :: GeneratedProofScope
  -> Term
  -> [(Text, UniverseConstraint)]
  -> Maybe Term
  -> GeneratedProofEnvironment
generatedProofEnvironment proofScope body callerConstraintBinders rigidWitness =
  GeneratedProofEnvironment
    { gpeAvailableCallerConstraints = availableCallerConstraints
    , gpeCallerAssumptions =
        foldl'
          (\assumptions (_, constraint) ->
             insertAssumption (ucLower constraint) (ucUpper constraint) assumptions)
          emptyAssumptions
          availableCallerConstraints
    , gpeRigidWitness = rigidWitness
    }
  where
    bodyProofNames = case proofScope of
      GeneratedProofLambdas -> generatedProofPrefix body
      GeneratedProofTelescope -> map fst callerConstraintBinders
    availableCallerConstraints =
      [ (index, constraint)
      | (index, name) <- zip [0 ..] bodyProofNames
      , Just constraint <- [lookup name callerConstraintBinders]
      ]

generatedProofFor
  :: GeneratedProofEnvironment
  -> Int
  -> UniverseConstraint
  -> Maybe Term
generatedProofFor environment depth constraint =
  case
      List.find
        (equivalentUniverseConstraint constraint . snd)
        (gpeAvailableCallerConstraints environment) of
    Just (index, _)
      | depth > index -> Just (CVar (depth - index - 1))
    _
      | Just witness <- gpeRigidWitness environment
      , proveLevelLeq
          (gpeCallerAssumptions environment)
          (ucLower constraint)
          (ucUpper constraint)
            == Proved ->
          Just witness
      | otherwise -> Nothing

generatedProofPrefix :: Term -> [Text]
generatedProofPrefix = \case
  CLamM Ordinary Impl Q0 name inner ->
    name : generatedProofPrefix inner
  _ -> []

-- | Replay a previously published generated-proof prefix into an artifact
-- rebuilt from an older interface snapshot. Unlike a fresh publication delta,
-- the artifact may already contain the prefix. The finalized target telescope
-- therefore authenticates the only two rewrites allowed here:
--
-- * a saturated occurrence short by exactly the published prefix receives it;
-- * a partial occurrence whose icities align only after removing that prefix
--   receives it;
-- * an occurrence already aligned with the finalized telescope is preserved.
--
-- Partial or otherwise malformed applications are left untouched. Their
-- provenance is ambiguous without a typed occurrence annotation, so guessing
-- would risk treating an ordinary implicit as generated evidence; finalized
-- Core validation remains the fail-closed authority for those cases.
replayPublishedGeneratedConstraintCallSpines
  :: GeneratedProofScope
  -> Map GName ([UniverseConstraint], [Icit])
  -> Map GName ([UniverseConstraint], [Icit])
  -> [(Text, UniverseConstraint)]
  -> Maybe Term
  -> Term
  -> Term
replayPublishedGeneratedConstraintCallSpines proofScope targets constructors callerConstraintBinders rigidWitness body =
  walk 0 body
  where
    proofEnvironment =
      generatedProofEnvironment
        proofScope
        body
        callerConstraintBinders
        rigidWitness

    walk depth = mapTermWithDepth rewrite depth

    rewrite depth term =
      replayGlobal depth term <|> replayConstructor depth term

    replayGlobal depth term =
      case spineOfTerm term of
        (CGlobal target universes, arguments)
          | Just (constraints, finalizedIcities) <- Map.lookup target targets
          , not (null constraints) ->
              let walkedArguments =
                    [(icit, walk depth argument) | (icit, argument) <- arguments]
                  actualIcities = map fst walkedArguments
                  prefixCount = length constraints
                  finalizedArity = length finalizedIcities
                  saturatedMissing =
                    length walkedArguments + prefixCount == finalizedArity
                  saturatedComplete = length walkedArguments == finalizedArity
                  aligns expected = actualIcities == take (length actualIcities) expected
                  alignsComplete = aligns finalizedIcities
                  alignsMissing = aligns (drop prefixCount finalizedIcities)
                  missing =
                    saturatedMissing
                      || (not saturatedComplete && alignsMissing && not alignsComplete)
                      || null walkedArguments
                  complete =
                    saturatedComplete
                      || (alignsComplete && not alignsMissing)
               in if missing
                    then do
                      proofs <-
                        traverse
                          (generatedProofFor proofEnvironment depth . instantiate universes)
                          constraints
                      pure $
                        foldl'
                          (\function (icit, argument) -> CApp icit function argument)
                          (foldl' (CApp Impl) (CGlobal target universes) proofs)
                          walkedArguments
                    else if complete
                      then
                        Just $
                          foldl'
                            (\function (icit, argument) -> CApp icit function argument)
                            (CGlobal target universes)
                            walkedArguments
                      else
                        -- Suppress descent into the application head: a
                        -- shorter nested spine is not a distinct occurrence.
                        Just $
                          foldl'
                            (\function (icit, argument) -> CApp icit function argument)
                            (CGlobal target universes)
                            walkedArguments
        _ -> Nothing

    replayConstructor depth = \case
      CCtorI target universes annotation arguments
        | Just (constraints, finalizedIcities) <- Map.lookup target constructors
        , not (null constraints) ->
            let walkedAnnotation = fmap (walk depth) annotation
                walkedArguments =
                  [argument {caTerm = walk depth (caTerm argument)} | argument <- arguments]
                actualIcities = map caIcit walkedArguments
                prefixCount = length constraints
                finalizedArity = length finalizedIcities
                saturatedMissing =
                  length walkedArguments + prefixCount == finalizedArity
                saturatedComplete = length walkedArguments == finalizedArity
                aligns expected = actualIcities == take (length actualIcities) expected
                alignsComplete = aligns finalizedIcities
                alignsMissing = aligns (drop prefixCount finalizedIcities)
                missing =
                  saturatedMissing
                    || (not saturatedComplete && alignsMissing && not alignsComplete)
                    || null walkedArguments
             in if missing
                  then do
                    proofs <-
                      traverse
                        (generatedProofFor proofEnvironment depth . instantiate universes)
                        constraints
                    pure
                      ( CCtorI target universes walkedAnnotation
                          ( [ConstructorArg Impl False Nothing proof | proof <- proofs]
                              ++ walkedArguments
                          )
                      )
                  else Just (CCtorI target universes walkedAnnotation walkedArguments)
      _ -> Nothing

    instantiate universes (UniverseConstraint lower upper) =
      UniverseConstraint
        (normalizeLevel (substituteLevelParams universes lower))
        (normalizeLevel (substituteLevelParams universes upper))

corePiIcities :: Term -> [Icit]
corePiIcities = \case
  CPiBoundM _ icit _ _ _ _ _ codomain -> icit : corePiIcities codomain
  _ -> []

-- | Revalidate proof arguments that were selected while a declaration still
-- had a provisional universe spine. The target's finalized checked telescope
-- determines exactly which leading erased arguments are generated level
-- evidence. Only those slots are replaced, and only from an exact caller
-- binder or a rigid solver proof; ordinary implicits and unproved obligations
-- are preserved for typed-Core validation to judge.
repairGeneratedConstraintEvidenceArguments
  :: GeneratedProofScope
  -> Map GName [UniverseConstraint]
  -> Map GName [UniverseConstraint]
  -> [(Text, UniverseConstraint)]
  -> Maybe Term
  -> Term
  -> Term
repairGeneratedConstraintEvidenceArguments proofScope targetConstraints constructorConstraints callerConstraintBinders rigidWitness body =
  walk 0 body
  where
    proofEnvironment =
      generatedProofEnvironment
        proofScope
        body
        callerConstraintBinders
        rigidWitness

    walk depth = mapTermWithDepth rewrite depth

    rewrite depth term =
      repairGlobal depth term <|> repairConstructor depth term

    repairGlobal depth term =
      case spineOfTerm term of
        (CGlobal target universes, arguments)
          | Just constraints <- Map.lookup target targetConstraints
          , not (null constraints)
          , let (proofArguments, ordinaryArguments) =
                  splitAt (length constraints) arguments
          , length proofArguments == length constraints
          , all ((== Impl) . fst) proofArguments
          , Just proofs <-
              traverse
                (generatedProofFor proofEnvironment depth . instantiate universes)
                constraints ->
              Just $
                foldl'
                  (\function (icit, argument) -> CApp icit function argument)
                  (CGlobal target universes)
                  ( zip (map fst proofArguments) proofs
                      ++ [(icit, walk depth argument) | (icit, argument) <- ordinaryArguments]
                  )
        _ -> Nothing

    repairConstructor depth = \case
      CCtorI target universes annotation arguments
        | Just constraints <- Map.lookup target constructorConstraints
        , not (null constraints)
        , let (proofArguments, ordinaryArguments) =
                splitAt (length constraints) arguments
        , length proofArguments == length constraints
        , all ((== Impl) . caIcit) proofArguments
        , Just proofs <-
            traverse
              (generatedProofFor proofEnvironment depth . instantiate universes)
              constraints ->
            Just
              ( CCtorI target universes
                  (fmap (walk depth) annotation)
                  ( zipWith
                      (\argument proof -> argument {caTerm = proof})
                      proofArguments
                      proofs
                      ++ [argument {caTerm = walk depth (caTerm argument)} | argument <- ordinaryArguments]
                  )
              )
      _ -> Nothing

    instantiate universes (UniverseConstraint lower upper) =
      UniverseConstraint
        (normalizeLevel (substituteLevelParams universes lower))
        (normalizeLevel (substituteLevelParams universes upper))

-- | Enforce the finalized generated-proof ABI after all declaration SCCs,
-- interface-publication waves, and pending evidence have settled. Earlier
-- phases may retain a certificate selected against a provisional occurrence
-- assignment; this pass uses only checked final telescopes and rewrites only
-- their authenticated generated-evidence prefix.
repairFinalizedGeneratedConstraintEvidence :: CheckM ()
repairFinalizedGeneratedConstraintEvidence = do
  state <- get
  let currentModule = csModule state
      context = ecOf state
      rigidWitness =
        if Map.member prelRefl (csCtors state)
          then Just solverEstablishedLevelWitness
          else Nothing
      globalConstraints =
        Map.map
          (map snd . generatedConstraintBinders . globalCoreType context)
          (csGlobals state)
      constructorConstraints =
        Map.map
          (map snd . generatedConstraintBinders . ciType)
          (csCtors state)
      repairType global definition
        | not (gnameInModule global currentModule) = definition
        | otherwise =
            let coreType = globalCoreType context definition
                repaired =
                  repairGeneratedConstraintEvidenceArguments
                    GeneratedProofTelescope
                    globalConstraints
                    constructorConstraints
                    (generatedConstraintBinders coreType)
                    rigidWitness
                    coreType
             in definition {gdCoreType = Just repaired}
      globalsWithCoreTypes = Map.mapWithKey repairType (csGlobals state)
      repairedContext = context {ecGlobals = Globals globalsWithCoreTypes}
      globalsWithTypes =
        Map.mapWithKey
          (\global definition ->
             if gnameInModule global currentModule
               then
                 definition
                   { gdType =
                       eval repairedContext [] (globalCoreType repairedContext definition)
                   }
               else definition)
          globalsWithCoreTypes
      repairConstructor constructor info
        | not (gnameInModule constructor currentModule) = info
        | otherwise =
            info
              { ciType =
                  repairGeneratedConstraintEvidenceArguments
                    GeneratedProofTelescope
                    globalConstraints
                    constructorConstraints
                    (generatedConstraintBinders (ciType info))
                    rigidWitness
                    (ciType info)
              }
      constructors' = Map.mapWithKey repairConstructor (csCtors state)
      repairBody global body
        | not (gnameInModule global currentModule) = body
        | otherwise =
            let callerConstraints =
                  maybe
                    []
                    (generatedConstraintBinders . globalCoreType repairedContext)
                    (Map.lookup global globalsWithTypes)
             in repairGeneratedConstraintEvidenceArguments
                  GeneratedProofLambdas
                  globalConstraints
                  constructorConstraints
                  callerConstraints
                  rigidWitness
                  body
      bodies' = Map.mapWithKey repairBody (csCoreBodies state)
      stateWithArtifacts =
        state
          { csGlobals = globalsWithTypes
          , csCtors = constructors'
          , csCoreBodies = bodies'
          }
      globals' =
        Map.mapWithKey
          (\global definition ->
             maybe
               definition
               (\body ->
                  globalDefWithCanonicalCoreBody
                    stateWithArtifacts
                    body
                    definition)
               (Map.lookup global bodies'))
          globalsWithTypes
  put
    ( invalidateSemanticCaches
        stateWithArtifacts {csGlobals = globals'}
    )

-- | Closed proof-irrelevant representative used only after the level solver
-- has established a generated comparison.  The authenticated relation lives
-- on the Pi/application slot; the witness identity is intentionally not part
-- of interface semantics (§11.1.2.3A).  Building this term directly avoids
-- running ordinary constructor elaboration while the embedded prelude itself
-- is still being assembled.
solverEstablishedLevelWitness :: Term
solverEstablishedLevelWitness =
  CCtorI prelRefl [LZero] Nothing
    [ ConstructorArg Impl False Nothing (CGlobal prelBool [])
    , ConstructorArg Impl False Nothing truth
    , ConstructorArg Impl False Nothing truth
    ]
  where
    truth = CCtorI prelTrue [] Nothing []

generatedConstraintBinderNames :: Term -> [Text]
generatedConstraintBinderNames = map fst . generatedConstraintBinders

generatedConstraintBinders :: Term -> [(Text, UniverseConstraint)]
generatedConstraintBinders = go
  where
    go (CPiEvidenceM Ordinary FormationOrdinary Impl Q0 _ name (Just (lower, upper)) _ _ codomain)
      | schemaLevel lower
      , schemaLevel upper =
          (name, UniverseConstraint (normalizeLevel lower) (normalizeLevel upper)) : go codomain
    go _ = []

    schemaLevel level =
      null (levelMetas level)
        && null (levelVars level)
        && null (levelFields level)
        && all (>= 0) (levelParams level)

ensureGeneratedConstraintLambdas :: [Text] -> Term -> Term
ensureGeneratedConstraintLambdas names body
  | missingCount >= 0
  , existing == drop missingCount names =
      foldr (CLamM Ordinary Impl Q0) body (take missingCount names)
  | otherwise = go names body
  where
    existing = take (length names) (implicitErasedLambdaPrefix body)
    missingCount = length names - length existing

    -- The finalized Pi telescope supplies the exact generated binder identities.
    -- A source binder with a reserved-looking name has no semantic authority;
    -- only an exact suffix of that authenticated sequence can be an already
    -- materialized proof-lambda prefix.
    implicitErasedLambdaPrefix = \case
      CLamM Ordinary Impl Q0 name inner ->
        name : implicitErasedLambdaPrefix inner
      _ -> []

    go [] term = term
    go remaining@(name : rest) term = case term of
      CLamM _ Impl Q0 actual inner | actual == name ->
        CLamM Ordinary Impl Q0 actual (go rest inner)
      _ -> foldr (CLamM Ordinary Impl Q0) term remaining

-- | A defining body may reveal a relation between independently-floating bare
-- @Type@ annotations in its own signature (for example, returning @A@ from
-- @forall (A : Type). Type@ requires @uA <= uResult@). Once the signature has
-- been generalized those levels are rigid 'LParam's, so record the relation on
-- the hidden telescope rather than rejecting it as an unrelated rigid
-- inequality. This is fail-closed: only parameters owned by the active
-- declaration are admitted, and the complete telescope must remain
-- satisfiable.
recordActiveUniverseRequirement :: Assumptions -> Level -> Level -> CheckM Bool
recordActiveUniverseRequirement assumptions lhs rhs =
  recordActiveUniverseRequirements assumptions [UniverseConstraint lhs rhs]

-- | Retain a rigid relation discovered while checking one explicit local
-- declaration schema. Local declarations do not have a global owner in
-- 'csActiveUniverseDefinition'; their generalization boundary instead owns
-- every constraint allocated since its saved constraint identity. Admit only
-- a relation closed over that local telescope and only when the extended
-- assumptions remain consistent. This gives local SCC generalization the
-- same proof-binder input as a top-level declaration without allowing an
-- unrelated lexical rigid mismatch to become a declaration contract.
recordActiveLocalUniverseRequirement
  :: Assumptions
  -> Level
  -> Level
  -> CheckM Bool
recordActiveLocalUniverseRequirement assumptions lhs rhs = do
  state <- get
  let localParameterCount =
        csActiveLocalUniverseSchemaCount state
          <|> ( length . lrssCurrentInstance
                  <$> csActiveLocalRecursiveSchemaScope state
              )
      levels = [lhs, rhs]
      closed count =
        null (concatMap levelMetas levels)
          && null (concatMap levelVars levels)
          && null (concatMap levelFields levels)
          && all
            (\parameter -> parameter >= 0 && parameter < count)
            (concatMap levelParams levels)
      extended = insertAssumption lhs rhs assumptions
  case localParameterCount of
    Just count
      | closed count
      , assumptionsConsistent extended -> do
          insertLevelConstraintOwned
            Nothing
            assumptions
            (ConstraintOrigin "local declaration universe" "type conversion")
            lhs
            rhs
          pure True
    _ -> pure False

-- | Validate and install one logical refinement transaction. Exact identity
-- supplies both directions at once so the complete ordering solver sees the
-- equality as an equality, rather than exploring a transient one-way
-- relation that is not part of the declaration contract.
recordActiveUniverseRequirements :: Assumptions -> [UniverseConstraint] -> CheckM Bool
recordActiveUniverseRequirements assumptions candidates = do
  active <- gets csActiveUniverseDefinition
  maybe (pure False) (\owner -> recordUniverseRequirementsForOwner owner assumptions candidates) active

-- | Install inferred relations on the declaration identity that owns the
-- solver judgment. This owner-explicit form is used when cumulative evidence
-- is frozen after an intervening signature/header boundary: ambient checker
-- state is not authority for which interface may acquire the constraint.
recordUniverseRequirementsForOwner :: GName -> Assumptions -> [UniverseConstraint] -> CheckM Bool
recordUniverseRequirementsForOwner g assumptions candidates = do
  globals <- gets csGlobals
  case Map.lookup g globals of
    Nothing -> pure False
    Just gd -> do
      let telescope = gdUniverses gd
          parameterCount = dutParameterCount telescope
      ec <- ec_
      pendingForOwner <- gets (Map.findWithDefault [] g . csPendingUniverseProofs)
      let coreType = globalCoreType ec gd
          existingConstraints = declarationConstraintSummary parameterCount coreType ++ pendingForOwner
          usedLevels =
            [ level
            | UniverseConstraint lhs rhs <- candidates
            , level <- [lhs, rhs]
            ]
          usedParams = concatMap levelParams usedLevels
          closedOverTelescope =
            null (concatMap levelMetas usedLevels)
              && null (concatMap levelVars usedLevels)
              && null (concatMap levelFields usedLevels)
              && all (\parameter -> parameter >= 0 && parameter < parameterCount) usedParams
          newCandidates =
            [ candidate
            | candidate <- dedupeUniverseConstraints candidates
            , not (any (equivalentUniverseConstraint candidate) existingConstraints)
            ]
          authorizedCandidates = dedupeUniverseConstraints candidates
          authenticatedAssumptions =
            foldl'
              (\current constraint ->
                 insertAssumption (ucLower constraint) (ucUpper constraint) current)
              assumptions
              existingConstraints
          extendedAssumptions =
            foldl'
              (\current constraint -> insertAssumption (ucLower constraint) (ucUpper constraint) current)
              authenticatedAssumptions
              authorizedCandidates
          consistent = assumptionsConsistent extendedAssumptions
      if null authorizedCandidates
        then pure True
        else if not closedOverTelescope || not consistent
        then pure False
        else do
          modify' $ \st ->
            let refresh constraint
                  | Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st) == Just g =
                      constraint
                        { lcAssumptions =
                            foldl'
                              (\current candidate -> insertAssumption (ucLower candidate) (ucUpper candidate) current)
                              (lcAssumptions constraint)
                              authorizedCandidates
                        }
                  | otherwise = constraint
             in reindexLevelConstraints $
                  st
                  { csPendingUniverseProofs =
                      if null newCandidates
                        then csPendingUniverseProofs st
                        else
                          Map.insertWith
                            (\new old -> dedupeUniverseConstraints (old ++ new))
                            g
                            newCandidates
                            (csPendingUniverseProofs st)
                  , csLevelConstraints = map refresh (csLevelConstraints st)
                  }
          active <- gets csActiveUniverseDefinition
          when (not (null newCandidates) && active /= Just g)
            (materializePendingUniverseProofs g)
          pure True

materializePendingUniverseProofs :: GName -> CheckM ()
materializePendingUniverseProofs g = do
  before <- get
  materializePendingUniverseProofsRaw g
  after <- get
  synchronizeGeneratedConstraintInterfacesFor
    (Just (generatedConstraintInterfacesAffectedBy g before after))
    before

-- | Make one declaration's pending generated proof telescope physical without
-- publishing that interface change.  The public wrapper above is the ordinary
-- entry point.  The publication transaction uses this raw operation for the
-- callers in its next worklist wave, then publishes that complete wave exactly
-- once after repairing artifacts for the current one.
materializePendingUniverseProofsRaw :: GName -> CheckM ()
materializePendingUniverseProofsRaw g = do
  st <- get
  case (Map.lookup g (csPendingUniverseProofs st), Map.lookup g (csGlobals st)) of
    (Just pending@(_ : _), Just definition) -> do
      let parameterCount = dutParameterCount (gdUniverses definition)
          coreType = globalCoreType (ecOf st) definition
          body = gdCoreBody definition <|> Map.lookup g (csCoreBodies st)
          generated = generatedConstraintsNotIn parameterCount pending coreType
          generatedByTarget =
            Map.mapMaybeWithKey
              (\target requested -> do
                 targetDefinition <- Map.lookup target (csGlobals st)
                 let targetType = globalCoreType (ecOf st) targetDefinition
                     targetParameterCount = dutParameterCount (gdUniverses targetDefinition)
                     targetGenerated =
                       generatedConstraintsNotIn targetParameterCount requested targetType
                 if null targetGenerated then Nothing else Just targetGenerated)
              (csPendingUniverseProofs st)
          pendingForOwner =
            Map.map pleConstraint
              (Map.filter ((== g) . pleOwner) (csPendingLevelEvidence st))
          generalizedEvidence =
            Map.keysSet $
              Map.filter
                (\constraint -> any (equivalentUniverseConstraint constraint) generated)
                pendingForOwner
          (repairedType, resolvedTypeEvidence) =
            rewriteGeneratedConstraintEvidence
              generatedByTarget
              generated
              pendingForOwner
              coreType
          (coreType', body', rewrittenEvidence) =
            case body of
              Just coreBody ->
                let (repairedBody, resolvedBodyEvidence) =
                      rewriteGeneratedConstraintEvidence
                        generatedByTarget
                        generated
                        pendingForOwner
                        coreBody
                    (ty, wrapped) =
                      prependGeneratedConstraintBinders parameterCount pending repairedType repairedBody
                 in (ty, Just wrapped, Set.union resolvedTypeEvidence resolvedBodyEvidence)
              Nothing ->
                let (ty, _) = prependGeneratedConstraintBinders parameterCount pending repairedType (CRecordV [])
                 in (ty, Nothing, resolvedTypeEvidence)
          ownerMetadataTerms =
            concat
              [ concat
                  [ iePremises entry ++ ieHead entry
                  | entry <- csInstances st
                  , ieDict entry == g
                  ]
              , concat
                  [ map teDomain (piFvTele entry) ++ piPremTms entry ++ piArgTms entry
                  | Just entry <- Map.elems (csPreInstances st)
                  , piDictG entry == g
                  ]
              ]
          survivingMetadataEvidence =
            Set.intersection generalizedEvidence
              (Set.fromList (concatMap metaIdsOf ownerMetadataTerms))
          resolvedEvidence =
            Set.union rewrittenEvidence
              (Set.difference generalizedEvidence survivingMetadataEvidence)
          definition' =
            definition
              { gdType = eval (ecOf st) [] coreType'
              , gdCoreType = Just coreType'
              , gdValue = eval (ecOf st) [] <$> body'
              , gdCoreBody = body'
              }
          globalsWithTarget = Map.insert g definition' (csGlobals st)
          -- A nominal family's generated proof telescope is shared by every
          -- constructor facet. Extend the constructor telescope in the same
          -- raw transaction as the family global. Retained family call spines
          -- are deliberately left to the publication repair below: editing
          -- them here as well would supply this same authenticated delta twice.
          extendFamilyConstructor info
            | ciData info /= g = info
            | otherwise =
                let constructorParameterCount =
                      dutParameterCount (ciUniverses info)
                    constructorGenerated =
                      generatedConstraintsNotIn
                        constructorParameterCount generated (ciType info)
                    (typeWithProofTelescope, _) =
                      prependGeneratedConstraintBinders
                        constructorParameterCount
                        constructorGenerated
                        (ciType info)
                        (CRecordV [])
                 in info {ciType = typeWithProofTelescope}
          constructorsWithTarget = Map.map extendFamilyConstructor (csCtors st)
          dirtyNominalSummaries
            | null generated = csDirtyNominalSummaries st
            | Map.member g (csNominalSummaryRequests st) =
                Set.insert g (csDirtyNominalSummaries st)
            | otherwise = csDirtyNominalSummaries st
          coreBodiesWithTarget =
            maybe (csCoreBodies st) (\term -> Map.insert g term (csCoreBodies st)) body'
      put
        st
          { csGlobals = globalsWithTarget
          , csCtors = constructorsWithTarget
          , csDirtyNominalSummaries = dirtyNominalSummaries
          , csCoreBodies = coreBodiesWithTarget
          , csPendingUniverseProofs = Map.delete g (csPendingUniverseProofs st)
          , csPending =
              filter (\(meta, _, _, _, _) -> meta `Set.notMember` resolvedEvidence) (csPending st)
          , csPendingLevelEvidence =
              Map.withoutKeys (csPendingLevelEvidence st) resolvedEvidence
          }
    _ -> pure ()

-- | Publish proof binders that became physical across a checker boundary to
-- every retained Core artifact.  Generated declaration constraints are always
-- prepended, so the increase in the authenticated physical prefix is the exact
-- call-spine delta; endpoint rewriting alone does not count as publication.
-- This deliberately compares Core interfaces rather than pending queues or
-- source names, either of which can lag the actual declaration artifact.
synchronizeGeneratedConstraintInterfaces :: CheckState -> CheckM ()
synchronizeGeneratedConstraintInterfaces =
  synchronizeGeneratedConstraintInterfacesFor Nothing

-- | The owner-scoped materializer can change only its global facet and the
-- constructor facets of that nominal family. Supplying that authenticated
-- frontier avoids re-quoting every declaration after each ordinary header;
-- module-boundary callers pass 'Nothing' and retain the full reconciliation.
synchronizeGeneratedConstraintInterfacesFor
  :: Maybe (Set GeneratedConstraintInterface)
  -> CheckState
  -> CheckM ()
synchronizeGeneratedConstraintInterfacesFor frontier before = do
  after <- get
  let beforeContext = ecOf before
      afterContext = ecOf after
      currentModule = csModule after
      physicalGlobalConstraints context definition =
        map snd (generatedConstraintBinders (globalCoreType context definition))
      physicalConstructorConstraints = map snd . generatedConstraintBinders . ciType
      publishedCounts = csPublishedGeneratedConstraintCounts after
      frontierGlobals =
        case frontier of
          Nothing ->
            Map.filterWithKey
              (\global _ -> gnameInModule global currentModule)
              (csGlobals after)
          Just interfaces ->
            Map.restrictKeys
              (csGlobals after)
              ( Set.fromList
                  [ global
                  | GeneratedGlobalInterface global <- Set.toList interfaces
                  , gnameInModule global currentModule
                  ]
              )
      frontierConstructors =
        case frontier of
          Nothing ->
            Map.filterWithKey
              (\constructor _ -> gnameInModule constructor currentModule)
              (csCtors after)
          Just interfaces ->
            Map.restrictKeys
              (csCtors after)
              ( Set.fromList
                  [ constructor
                  | GeneratedConstructorInterface constructor <- Set.toList interfaces
                  , gnameInModule constructor currentModule
                  ]
              )
      globalDeltas =
        Map.mapMaybeWithKey
          (\global definition ->
             let current = physicalGlobalConstraints afterContext definition
                 previousCount =
                   Map.findWithDefault
                     ( maybe 0 (length . physicalGlobalConstraints beforeContext)
                         (Map.lookup global (csGlobals before))
                     )
                     (GeneratedGlobalInterface global)
                     publishedCounts
                 addedCount = max 0 (length current - previousCount)
                 added = take addedCount current
              in if null added then Nothing else Just added)
          frontierGlobals
      constructorDeltas =
        Map.mapMaybeWithKey
          (\constructor info ->
             let current = physicalConstructorConstraints info
                 previousCount =
                   Map.findWithDefault
                     ( maybe 0 (length . physicalConstructorConstraints)
                         (Map.lookup constructor (csCtors before))
                     )
                     (GeneratedConstructorInterface constructor)
                     publishedCounts
                 addedCount = max 0 (length current - previousCount)
                 added = take addedCount current
              in if null added then Nothing else Just added)
          frontierConstructors
  unless (Map.null globalDeltas && Map.null constructorDeltas) $ do
    -- Claim this complete physical-prefix wave before running any solver work.
    -- A nested or overlapping synchronization therefore cannot publish the
    -- same target delta twice. Callers materialized by this wave are absent
    -- from the frontier until the recursive next-wave call below.
    modify' $ \st ->
      st
        { csPublishedGeneratedConstraintCounts =
            Map.union
              ( Map.fromList
                  ( [ ( GeneratedGlobalInterface global
                      , maybe 0
                          (length . physicalGlobalConstraints (ecOf st))
                          (Map.lookup global (csGlobals st))
                      )
                    | global <- Map.keys globalDeltas
                    ]
                      ++ [ ( GeneratedConstructorInterface constructor
                           , maybe 0
                               (length . physicalConstructorConstraints)
                               (Map.lookup constructor (csCtors st))
                           )
                         | constructor <- Map.keys constructorDeltas
                         ]
                  )
              )
              (csPublishedGeneratedConstraintCounts st)
        }
    let termAssumptions term =
          foldl'
            (\assumptions (_, constraint) ->
               insertAssumption (ucLower constraint) (ucUpper constraint) assumptions)
            emptyAssumptions
            (generatedConstraintBinders term)
        callerAssumptions definition =
          termAssumptions (globalCoreType afterContext definition)
        interfaceOccurrences =
          foldTerm
            (\case
               CGlobal target universes ->
                 [(GeneratedGlobalInterface target, universes)]
               CCtorI target universes _ _ ->
                 [(GeneratedConstructorInterface target, universes)]
               _ -> [])
            (const [])
        interfaceDelta = \case
          GeneratedGlobalInterface target -> Map.lookup target globalDeltas
          GeneratedConstructorInterface target -> Map.lookup target constructorDeltas
        interfaceName = \case
          GeneratedGlobalInterface target -> target
          GeneratedConstructorInterface target -> target
        callerArtifacts caller definition =
          globalUniverseInterfaceTerms after caller definition
            ++ maybeToList (Map.lookup caller (csCoreBodies after))
            ++ ( if Map.member caller (csTraits after)
                   then maybe [] (maybe [] (pure . quote afterContext 0) . gdValue)
                          (Map.lookup caller (csGlobals after))
                   else []
               )
            ++ maybe [] (map snd . tiSupers) (Map.lookup caller (csTraits after))
            ++ concat
              [ map teDomain (piFvTele entry) ++ piPremTms entry ++ piArgTms entry
              | Just entry <- Map.elems (csPreInstances after)
              , piDictG entry == caller
              ]
            ++ concat
              [ maybe [] (map (quote afterContext 0)) (eliFixedArgs info)
              | info <-
                  Map.elems (csModEffLabels after)
                    ++ Map.elems (csEffectInterfaces after)
              , eliIface info == caller
              ]
        specialize universes (UniverseConstraint lower upper) =
          UniverseConstraint
            (normalizeLevel (substituteLevelParams universes lower))
            (normalizeLevel (substituteLevelParams universes upper))
        globalObligations =
          [ (caller, target, assumptions, constraint)
          | (caller@(GName callerModule _), definition) <- Map.toList (csGlobals after)
          , callerModule == currentModule
          , let assumptions = callerAssumptions definition
          , artifact <- callerArtifacts caller definition
          , (target, universes) <- interfaceOccurrences artifact
          , target /= GeneratedGlobalInterface caller
          , requested <- maybeToList (interfaceDelta target)
          , constraint <- map (specialize universes) requested
          , proveLevelLeq assumptions (ucLower constraint) (ucUpper constraint) /= Proved
          ]
        constructorObligations =
          [ (ciData info, caller, target, assumptions, constraint)
          | (caller@(GName callerModule _), info) <- Map.toList (csCtors after)
          , callerModule == currentModule
          , let assumptions = termAssumptions (ciType info)
          , (target, universes) <- interfaceOccurrences (ciType info)
          , target /= GeneratedConstructorInterface caller
          , requested <- maybeToList (interfaceDelta target)
          , constraint <- map (specialize universes) requested
          , proveLevelLeq assumptions (ucLower constraint) (ucUpper constraint) /= Proved
          ]
        affectedCallers =
          Set.fromList
            ( [caller | (caller, _, _, _) <- globalObligations]
                ++ [family | (family, _, _, _, _) <- constructorObligations]
            )
    forM_ globalObligations $ \(caller, target, assumptions, constraint) ->
      insertLevelConstraintOwned
        (Just caller)
        assumptions
        ( ConstraintOrigin
            ("published universe constraint of " <> gKey (interfaceName target))
            "declaration reference"
        )
        (ucLower constraint)
        (ucUpper constraint)
    -- Constructor field/result obligations refine the enclosing nominal family
    -- (§11.1.2.3A), not an independent constructor schema. Queue them under
    -- that owner and let the ordinary declaration-boundary solver decide
    -- whether they are closed, consistent, and materializable. The raw family
    -- materializer above then updates every constructor facet atomically.
    forM_ constructorObligations $ \(family, constructor, target, assumptions, constraint) ->
      insertLevelConstraintOwned
        (Just family)
        assumptions
        ( ConstraintOrigin
            ( "published universe constraint of "
                <> gKey (interfaceName target)
                <> " retained by constructor "
                <> gKey constructor
            )
            "nominal family constructor interface"
        )
        (ucLower constraint)
        (ucUpper constraint)
    -- The call was retained before the target's complete proof telescope was
    -- visible. Re-run the caller's ordinary declaration-boundary solver: a
    -- determined occurrence level is installed, while a genuinely rigid
    -- residual becomes the caller's own erased proof binder. No proof term is
    -- guessed in either case.
    forM_ (Set.toAscList affectedCallers) $ \caller ->
      withActiveUniverseDefinitionRaw caller $ do
        callerState <- get
        forM_ (Map.lookup caller (csGlobals callerState)) $ \definition -> do
          let (previewValid, previewAssignments) =
                previewOwnedInterfaceUniverseAssignments caller definition callerState
          when previewValid (installLevelAssignments previewAssignments)
        void (solveDeferredLevelConstraints False)
        materializeOwnedInterfaceUniverseProofs caller
        settleActiveUniverseRequirements
    -- The raw active-definition scope above materializes each caller without
    -- recursively publishing it. After repairing artifacts for this wave, the
    -- recursive publication step below observes those newly physical caller
    -- prefixes as the next delta wave. Each interface prefix grows finitely, so
    -- this reaches a fixed point without rewriting any wave twice.
    current <- get
    let currentContext = ecOf current
        assignments = csLevelAssignments current
        rigidWitness =
          if Map.member prelRefl (csCtors current)
            then Just solverEstablishedLevelWitness
            else Nothing
        globalDeltaTargets =
          Map.mapMaybeWithKey
            (\target constraints -> do
               definition <- Map.lookup target (csGlobals current)
               pure
                 ( constraints
                 , corePiIcities (globalCoreType currentContext definition)
                 ))
            globalDeltas
        constructorDeltaTargets =
          Map.mapMaybeWithKey
            (\target constraints -> do
               info <- Map.lookup target (csCtors current)
               pure (constraints, corePiIcities (ciType info)))
            constructorDeltas
        constructorCallerDeltas caller = Map.delete caller constructorDeltaTargets
        repairType _caller definition =
          let coreType = zonkLevels assignments (globalCoreType currentContext definition)
              repaired =
                replayPublishedGeneratedConstraintCallSpines
                  GeneratedProofTelescope
                  globalDeltaTargets
                  constructorDeltaTargets
                  (generatedConstraintBinders coreType)
                  rigidWitness
                  coreType
           in definition {gdCoreType = Just repaired}
        globalsWithCoreTypes =
          Map.mapWithKey
            (\global definition ->
               if gnameInModule global currentModule
                 then repairType global definition
                 else definition)
            (csGlobals current)
        repairedTypeContext =
          currentContext {ecGlobals = Globals globalsWithCoreTypes}
        globalsWithTypes =
          Map.mapWithKey
            (\global definition ->
               if gnameInModule global currentModule
                 then
                   let coreType = globalCoreType repairedTypeContext definition
                    in definition {gdType = eval repairedTypeContext [] coreType}
                 else definition)
            globalsWithCoreTypes
        repairOwnedTerm global body =
          let callerType = globalCoreType repairedTypeContext
                <$> Map.lookup global globalsWithTypes
           in replayPublishedGeneratedConstraintCallSpines
                GeneratedProofLambdas
                globalDeltaTargets
                constructorDeltaTargets
                (maybe [] generatedConstraintBinders callerType)
                rigidWitness
                (zonkLevels assignments body)
        repairConstructor constructor info =
          let coreType = zonkLevels assignments (ciType info)
           in info
                { ciType =
                    replayPublishedGeneratedConstraintCallSpines
                      GeneratedProofTelescope
                      globalDeltaTargets
                      (constructorCallerDeltas constructor)
                      (generatedConstraintBinders coreType)
                      rigidWitness
                      coreType
                }
        repairedConstructors =
          Map.mapWithKey
            (\constructor info ->
               if gnameInModule constructor currentModule
                 then repairConstructor constructor info
                 else info)
            (csCtors current)
        repairOwnedValue global value =
          let repaired = repairOwnedTerm global (quote currentContext 0 value)
           in if termScopedAt 0 repaired
                then eval repairedTypeContext [] repaired
                else value
        globalsWithValues =
          Map.mapWithKey
            (\global definition ->
              if gnameInModule global currentModule
                   && (Map.member global (csTraits current)
                    || globalValueIsUniverseInterface
                         (csUniverseInterfaceValues current) global definition)
                 then definition {gdValue = repairOwnedValue global <$> gdValue definition}
                 else definition)
            globalsWithTypes
        repairedBodies =
          Map.mapWithKey
            (\global body ->
               if gnameInModule global currentModule
                 then repairOwnedTerm global body
                 else body)
            (csCoreBodies current)
        repairedTerminationDecls =
          Map.mapWithKey
            (\global declaration ->
               if gnameInModule global currentModule
                 then
                   declaration
                     { tdSigType = repairOwnedValue global (tdSigType declaration)
                     , tdCoreBody = repairOwnedTerm global (tdCoreBody declaration)
                     }
                 else declaration)
            (csTerminationDecls current)
        repairedTraits =
          Map.mapWithKey
            (\global info ->
               if gnameInModule global currentModule
                 then
                   info
                     { tiSupers =
                         [ (field, repairOwnedTerm global term)
                         | (field, term) <- tiSupers info
                         ]
                     }
                 else info)
            (csTraits current)
        repairedInstances =
          [ if gnameInModule (ieDict entry) currentModule
              then
                entry
                  { ieTraitUniverses = map (normalizeLevel . substituteLevelMetas assignments) (ieTraitUniverses entry)
                  , iePremises = map (repairOwnedTerm (ieDict entry)) (iePremises entry)
                  , ieHead = map (repairOwnedTerm (ieDict entry)) (ieHead entry)
                  }
              else entry
          | entry <- csInstances current
          ]
        repairedPreInstances =
          Map.map
            (fmap
              (\entry ->
                 if gnameInModule (piDictG entry) currentModule
                   then
                     let repair = repairOwnedTerm (piDictG entry)
                      in entry
                           { piFvTele =
                               [ teleEntry {teDomain = repair (teDomain teleEntry)}
                               | teleEntry <- piFvTele entry
                               ]
                           , piPremTms = map repair (piPremTms entry)
                           , piArgTms = map repair (piArgTms entry)
                           }
                   else entry))
            (csPreInstances current)
        repairEffectLabel info =
          let owner = eliIface info
           in if not (gnameInModule owner currentModule)
                then info
                else
                  let repair = repairOwnedTerm owner
                      repairLevel = normalizeLevel . substituteLevelMetas assignments
                      repairEntry entry =
                        entry
                          { teDomain = repair (teDomain entry)
                          , teLevelAssumption =
                              fmap (\(lower, upper) -> (repairLevel lower, repairLevel upper))
                                (teLevelAssumption entry)
                          }
                      repairOperation operation =
                        operation
                          { eoiImplicits = map repairEntry (eoiImplicits operation)
                          , eoiArgs = map repairEntry (eoiArgs operation)
                          , eoiResT = repair (eoiResT operation)
                          }
                   in info
                        { eliParams = map repairEntry (eliParams info)
                        , eliFixedArgs = fmap (map (repairOwnedValue owner)) (eliFixedArgs info)
                        , eliFixedUniverses = fmap (map repairLevel) (eliFixedUniverses info)
                        , eliOps = map repairOperation (eliOps info)
                        }
        repairedEffectLabels = Map.map repairEffectLabel (csModEffLabels current)
        repairedEffectInterfaces = Map.map repairEffectLabel (csEffectInterfaces current)
        stateWithArtifacts =
          setCheckInstances repairedInstances $
          current
            { csGlobals = globalsWithValues
            , csCtors = repairedConstructors
            , csCoreBodies = repairedBodies
            , csTerminationDecls = repairedTerminationDecls
            , csTraits = repairedTraits
            , csPreInstances = repairedPreInstances
            , csModEffLabels = repairedEffectLabels
            , csEffectInterfaces = repairedEffectInterfaces
            }
        repairedGlobals =
          Map.mapWithKey
            (\global definition ->
               if gnameInModule global currentModule
                 then
                   maybe definition
                     (\body -> globalDefWithCanonicalCoreBody stateWithArtifacts body definition)
                     (Map.lookup global repairedBodies)
                 else definition)
            globalsWithValues
    put
      ( invalidateSemanticCaches
          stateWithArtifacts {csGlobals = repairedGlobals}
      )
    synchronizeGeneratedConstraintInterfaces after
    finalizePendingNominalSummaries

generatedConstraintInterfacesAffectedBy
  :: GName
  -> CheckState
  -> CheckState
  -> Set GeneratedConstraintInterface
generatedConstraintInterfacesAffectedBy owner before after =
  let newGlobals = Map.keysSet (Map.difference (csGlobals after) (csGlobals before))
      newConstructors = Map.keysSet (Map.difference (csCtors after) (csCtors before))
      ownerConstructors =
        Set.fromList (maybe [] diCtors (Map.lookup owner (csDatas after)))
   in Set.unions
        [ Set.singleton (GeneratedGlobalInterface owner)
        , Set.map GeneratedGlobalInterface newGlobals
        , Set.map GeneratedConstructorInterface
            (Set.union ownerConstructors newConstructors)
        ]

registerLevelConstraint :: Ctx -> Text -> Text -> Level -> Level -> CheckM ()
registerLevelConstraint ctx description construct lhs rhs = do
  assumptions <- effectiveLevelAssumptions ctx
  insertLevelConstraint assumptions (ConstraintOrigin description construct) lhs rhs

insertLevelConstraint :: Assumptions -> ConstraintOrigin -> Level -> Level -> CheckM ()
insertLevelConstraint assumptions origin lhs rhs = do
  owner <- gets csActiveUniverseDefinition
  insertLevelConstraintOwned owner assumptions origin lhs rhs

levelConstraintKey
  :: Maybe GName
  -> Maybe Span
  -> LevelConstraint
  -> LevelConstraintKey
levelConstraintKey owner sourceSpan constraint =
  LevelConstraintKey
    owner
    sourceSpan
    (lcLhs constraint)
    (lcRhs constraint)
    (lcOrigin constraint)
    (assumptionsList (lcAssumptions constraint))

reindexLevelConstraints :: CheckState -> CheckState
reindexLevelConstraints st =
  let constraints = csLevelConstraints st
      retainedIds = Set.fromList (map lcIdentity constraints)
      constraintIndex =
        Map.fromList
          [ ( levelConstraintKey
                (Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st))
                (Map.lookup (lcIdentity constraint) (csLevelConstraintSpans st))
                constraint
            , lcIdentity constraint
            )
          | constraint <- constraints
          ]
      -- Prepend in constant time, then restore the authoritative constraint
      -- order once per owner. Appending each singleton made this rebuild
      -- quadratic for declarations with many universe constraints.
      constraintsByOwner =
        Map.map reverse $
          List.foldl'
            (\byOwner constraint ->
               case Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st) of
                 Nothing -> byOwner
                 Just owner -> Map.insertWith (++) owner [constraint] byOwner)
            Map.empty
            constraints
   in st
    { csLevelConstraintIndex = constraintIndex
    , csLevelConstraintsByOwner = constraintsByOwner
    , csLevelConstraintOwners =
        Map.restrictKeys (csLevelConstraintOwners st) retainedIds
    , csLevelConstraintSpans =
        Map.restrictKeys (csLevelConstraintSpans st) retainedIds
    , csLevelConstraintProvenance =
        Map.restrictKeys (csLevelConstraintProvenance st) retainedIds
    }

constraintOwnedAfterRetiringOccurrences
  :: CheckState
  -> Set Int
  -> LevelConstraint
  -> Bool
constraintOwnedAfterRetiringOccurrences st retired constraint =
  case Map.lookup (lcIdentity constraint) (csLevelConstraintProvenance st) of
    Nothing -> True
    Just provenance ->
      lcpOrdinary provenance
        || not
             ( Set.null
                 ( Set.difference
                     (lcpProvisionalOccurrences provenance)
                     retired
                 )
             )

-- | Commit a successfully principalized provisional occurrence. Its checked
-- result no longer contains occurrence metas, so retaining the occurrence or
-- constraints owned solely by it would leak transaction-local inference state
-- into module closeout. Constraints also registered by source elaboration, or
-- shared with another live occurrence, remain owned.
retireProvisionalUniverseOccurrences :: Set Int -> CheckM ()
retireProvisionalUniverseOccurrences retired
  | Set.null retired = pure ()
  | otherwise =
      modify' $ \st ->
        let retainedConstraints =
              filter
                (constraintOwnedAfterRetiringOccurrences st retired)
                (csLevelConstraints st)
            retainedIds =
              Set.fromList (map lcIdentity retainedConstraints)
            trimProvenance provenance =
              provenance
                { lcpProvisionalOccurrences =
                    Set.difference
                      (lcpProvisionalOccurrences provenance)
                      retired
                }
         in reindexLevelConstraints
              st
                { csProvisionalUniverseInstantiations =
                    filter
                      ((`Set.notMember` retired) . puiIdentity)
                      (csProvisionalUniverseInstantiations st)
                , csLevelConstraints = retainedConstraints
                , csLevelConstraintOwners =
                    Map.restrictKeys
                      (csLevelConstraintOwners st)
                      retainedIds
                , csLevelConstraintSpans =
                    Map.restrictKeys
                      (csLevelConstraintSpans st)
                      retainedIds
                , csLevelConstraintProvenance =
                    Map.map trimProvenance
                      ( Map.restrictKeys
                          (csLevelConstraintProvenance st)
                          retainedIds
                      )
                }

levelConstraintsOwnedBy :: CheckState -> Set GName -> [LevelConstraint]
levelConstraintsOwnedBy st owners =
  concatMap
    (\owner -> Map.findWithDefault [] owner (csLevelConstraintsByOwner st))
    (Set.toAscList owners)

levelMetasOwnedBy
  :: Map GName (Set LevelMeta)
  -> Set GName
  -> Set LevelMeta
levelMetasOwnedBy byOwner owners =
  Set.unions
    [ Map.findWithDefault Set.empty owner byOwner
    | owner <- Set.toList owners
    ]

levelMetasByOwner
  :: Map LevelMeta (Set GName)
  -> Map GName (Set LevelMeta)
levelMetasByOwner =
  Map.foldlWithKey'
    (\byOwner meta owners ->
       Set.foldl'
         (\current owner ->
            Map.alter
              (Just . Set.insert meta . fromMaybe Set.empty)
              owner
              current)
         byOwner
         owners)
    Map.empty

constructorsByData
  :: Map GName CtorInfo
  -> Map GName (Map GName CtorInfo)
constructorsByData =
  Map.fromListWith Map.union
    . map
        (\(ctor, info) ->
           (ciData info, Map.singleton ctor info))
    . Map.toList

insertLevelConstraintOwned
  :: Maybe GName
  -> Assumptions
  -> ConstraintOrigin
  -> Level
  -> Level
  -> CheckM ()
insertLevelConstraintOwned owner assumptions origin lhs rhs =
  void
    ( insertLevelConstraintOwnedWithProvenance
        Nothing
        owner
        assumptions
        origin
        lhs
        rhs
    )

insertProvisionalLevelConstraintOwned
  :: Int
  -> Maybe GName
  -> Assumptions
  -> ConstraintOrigin
  -> Level
  -> Level
  -> CheckM Int
insertProvisionalLevelConstraintOwned occurrence =
  insertLevelConstraintOwnedWithProvenance (Just occurrence)

insertLevelConstraintOwnedWithProvenance
  :: Maybe Int
  -> Maybe GName
  -> Assumptions
  -> ConstraintOrigin
  -> Level
  -> Level
  -> CheckM Int
insertLevelConstraintOwnedWithProvenance provisionalOccurrence owner assumptions origin lhs rhs = do
  st <- get
  let sourceSpan = csUniverseDiagnosticSpan st
      identity = csNextLevelConstraint st
      constraint =
        LevelConstraint
          { lcIdentity = identity
          , lcLhs = lhs
          , lcRhs = rhs
          , lcOrigin = origin
          , lcAssumptions = assumptions
          }
      key = levelConstraintKey owner sourceSpan constraint
      addProvenance =
        Map.alter
          ( Just
              . maybe
                  ( LevelConstraintProvenance
                      (isNothing provisionalOccurrence)
                      (maybe Set.empty Set.singleton provisionalOccurrence)
                  )
                  (\provenance ->
                     provenance
                       { lcpOrdinary =
                           lcpOrdinary provenance
                             || isNothing provisionalOccurrence
                       , lcpProvisionalOccurrences =
                           maybe
                             (lcpProvisionalOccurrences provenance)
                             (`Set.insert` lcpProvisionalOccurrences provenance)
                             provisionalOccurrence
                       })
          )
  case Map.lookup key (csLevelConstraintIndex st) of
    Just existing -> do
      modify' $ \current ->
        current
          { csLevelConstraintProvenance =
              addProvenance existing (csLevelConstraintProvenance current)
          }
      pure existing
    Nothing -> do
      put
        st
          { csLevelConstraints = constraint : csLevelConstraints st
          , csLevelConstraintOwners =
              maybe
                (csLevelConstraintOwners st)
                (\definition -> Map.insert identity definition (csLevelConstraintOwners st))
                owner
          , csLevelConstraintsByOwner =
              maybe
                (csLevelConstraintsByOwner st)
                (\definition ->
                   Map.insertWith
                     (++)
                     definition
                     [constraint]
                     (csLevelConstraintsByOwner st))
                owner
          , csLevelConstraintSpans =
              maybe
                (csLevelConstraintSpans st)
                (\source -> Map.insert identity source (csLevelConstraintSpans st))
                sourceSpan
          , csLevelConstraintIndex =
              Map.insert key identity (csLevelConstraintIndex st)
          , csLevelConstraintProvenance =
              addProvenance identity (csLevelConstraintProvenance st)
          , csNextLevelConstraint = identity + 1
          }
      pure identity

-- | Solve the accumulated universe constraints. During elaboration residual
-- metas remain blocked so later constraints can determine their principal
-- lower bound. The owning module boundary delegates every remaining
-- minimizable meta to the versioned five-way principal-inference authority;
-- it has no separate defaulting or recovery assignment path.
solveDeferredLevelConstraints :: Bool -> CheckM Bool
solveDeferredLevelConstraints final = do
  st <- get
  let prior = csLevelAssignments st
      activeOwner = csActiveUniverseDefinition st
      belongsToActive constraint =
        Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st) == activeOwner
      pendingConstraints
        | final = reverse (csLevelConstraints st)
        | Just _ <- activeOwner = filter belongsToActive (reverse (csLevelConstraints st))
        | otherwise = []
      constraints = map (substituteLevelConstraintMetas prior) pendingConstraints
      run cs = solveLevelConstraints cs
  if final
    then solveFinalLevelConstraints st constraints
    else case run constraints of
      Left solveError ->
        case solveError of
          -- A body-local instantiation meta can mediate a relation between two
          -- already-generalized parameters, for example @p <= ?m <= q@. The
          -- principal solver eliminates @?m@ and exposes @p <= q@ as a rigid
          -- consequence. Give that consequence to the active telescope and
          -- leave the original meta constraints pending for SCC closeout.
          LevelConstraintDisproved constraint ->
            recordActiveUniverseConsequences
              (lcAssumptions constraint)
              (lcLhs constraint)
              (lcRhs constraint)
          _ -> pure False
      Right _ -> pure True

solveFinalLevelConstraints :: CheckState -> [LevelConstraint] -> CheckM Bool
solveFinalLevelConstraints initialState constraints = do
  let rigidFailure constraint =
        null
          ( levelMetas (lcLhs constraint)
              ++ levelMetas (lcRhs constraint)
              ++ concat
                   [ levelMetas lower ++ levelMetas upper
                   | (lower, upper) <- assumptionsList (lcAssumptions constraint)
                   ]
          )
          && proveLevelLeq
               (lcAssumptions constraint)
               (lcLhs constraint)
               (lcRhs constraint)
               == Disproved
      (rigidFailures, inferableConstraints) = List.partition rigidFailure constraints
  if not (null rigidFailures)
    then do
      mapM_ (reportLevelSolveError . LevelConstraintDisproved) rigidFailures
      -- Independent declaration failures must not mask one another. Continue
      -- through the remaining connected inference problem to expose any
      -- additional non-rigid failure, but retain the failed result even when
      -- that remainder solves.
      unless (null inferableConstraints) $
        void (solveFinalLevelConstraints initialState inferableConstraints)
      pure False
    else solveInferable
  where
    solveInferable = do
      let assignments = csLevelAssignments initialState
          constraintMetas constraint =
            Set.fromList
              ( levelMetas (lcLhs constraint)
                  ++ levelMetas (lcRhs constraint)
                  ++ concat
                       [ levelMetas lower ++ levelMetas upper
                       | (lower, upper) <- assumptionsList (lcAssumptions constraint)
                       ]
              )
          constrainedMetas = Set.unions (map constraintMetas constraints)
          -- Final evidence commitment can replace an ordinary term meta by a
          -- proof term carrying fresh universe occurrences. Materialize each
          -- body before collecting the complete final selected set.
          bodyMetas =
            Map.foldl'
              (\metas body ->
                 let materialized = evalState (zonkTermM 0 body) initialState
                  in Set.union metas
                       (Set.fromList (levelMetasOfTerm (zonkLevels assignments materialized))))
              Set.empty
              (csCoreBodies initialState)
          firstClassMetas =
            Set.fromList
              [ projected
              | origin <- Set.toList (csFirstClassLevelMetas initialState)
              , projected <-
                  levelMetas
                    (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
              ]
          remainingMetas = Set.unions [constrainedMetas, bodyMetas, firstClassMetas]
          -- Declaration generalization has already replaced every legal
          -- user-observable polymorphic identity by a rigid 'LParam'. Any
          -- level meta still present at module closeout is therefore an
          -- occurrence, result, or other minimizable inference choice.
          targets = remainingMetas
          owners =
            Set.toAscList . Set.fromList $
              [ owner
              | constraint <- constraints
              , Just owner <-
                  [Map.lookup (lcIdentity constraint) (csLevelConstraintOwners initialState)]
              ]
          declarations = case owners of
            [] -> [moduleNameText (csModule initialState)]
            _ -> map gKey owners
          explicitSchema =
            any
              (\owner -> maybe False (dutExplicit . gdUniverses)
                (Map.lookup owner (csGlobals initialState)))
              owners
          diagnosticSpan =
            fromMaybe
              (Span "<universe-inference>" (Pos 1 1) (Pos 1 1))
              (listToMaybe constraints >>= \constraint ->
                 Map.lookup (lcIdentity constraint) (csLevelConstraintSpans initialState))
      inferred <-
        inferPrincipalAtDeclarationBoundary
          diagnosticSpan declarations explicitSchema targets constraints
      case inferred of
        PrincipalBoundarySolved principal -> do
          installLevelAssignments principal
          finalState <- get
          let combined = csLevelAssignments finalState
              finalizedConstraints =
                map (substituteLevelConstraintMetas combined) constraints
          case solveLevelConstraints finalizedConstraints of
            Left solveError -> reportLevelSolveError solveError >> pure False
            Right solution
              | null (lsResidual solution) -> do
                  finalizeLevelArtifacts
                  modify' $ \state ->
                    if Map.null (csPendingLevelEvidence state)
                      then
                        reindexLevelConstraints $
                          state
                            { csLevelConstraints = []
                            , csLevelConstraintOwners = Map.empty
                            , csLevelConstraintSpans = Map.empty
                            }
                      else
                        -- Pending authenticated LevelLe terms may be the only
                        -- remaining roots that mention occurrence metas. Keep
                        -- the solved graph until those proofs replay against
                        -- its principal component; the next closeout
                        -- iteration clears it after the side table is retired.
                        reindexLevelConstraints
                          state {csLevelConstraints = finalizedConstraints}
                  pure True
              | otherwise -> do
                  modify' $ \state ->
                    reindexLevelConstraints $
                      state
                      { csLevelConstraints = lsResidual solution
                      , csLevelConstraintOwners =
                          Map.restrictKeys
                            (csLevelConstraintOwners state)
                            (Set.fromList (map lcIdentity (lsResidual solution)))
                      , csLevelConstraintSpans =
                          Map.restrictKeys
                            (csLevelConstraintSpans state)
                            (Set.fromList (map lcIdentity (lsResidual solution)))
                      }
                  pure False
        PrincipalBoundaryDeferred -> pure False
        PrincipalBoundaryRejected -> pure False

-- | A blocked body-local level can share a maximum with rigid declaration
-- parameters. If that maximum exceeds a rigid upper bound, retain each closed
-- rigid arm as a declaration constraint and leave meta-bearing arms deferred.
-- No level meta is assigned here; module-boundary principal inference remains
-- the only authority for body-local minimizable levels.
recordActiveUniverseConsequences :: Assumptions -> Level -> Level -> CheckM Bool
recordActiveUniverseConsequences assumptions lhs rhs = do
  let arms = flattenLeftMax (normalizeLevel lhs)
      closed level =
        null (levelMetas level)
          && null (levelVars level)
          && null (levelFields level)
      candidates =
        [ UniverseConstraint arm rhs
        | arm <- arms
        , closed arm
        , closed rhs
        , proveLevelLeq assumptions arm rhs /= Proved
        ]
  if null candidates
    then pure False
    else recordActiveUniverseRequirements assumptions candidates
  where
    flattenLeftMax (LMax left right) = flattenLeftMax left ++ flattenLeftMax right
    flattenLeftMax level = [level]

-- | Settle rigid relations exposed by a single active declaration body. The
-- non-final solver is intentionally declaration-local; whole-module solving,
-- defaulting, and artifact finalization happen only at the module boundary.
-- A newly recorded telescope relation can discharge another mediated
-- constraint, so iterate only while the active telescope actually changes.
settleActiveUniverseRequirements :: CheckM ()
settleActiveUniverseRequirements = do
  active <- gets csActiveUniverseDefinition
  case active of
    Nothing -> pure ()
    Just owner -> do
      st <- get
      let rigidRequirements =
            [ UniverseConstraint (lcLhs constraint) (lcRhs constraint)
            | constraint <- csLevelConstraints st
            , Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st) == Just owner
            , null (assumptionsList (lcAssumptions constraint))
            , null (levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint))
            , null (levelVars (lcLhs constraint) ++ levelVars (lcRhs constraint))
            , null (levelFields (lcLhs constraint) ++ levelFields (lcRhs constraint))
            ]
      -- Explicit schema parameters are rigid from the start, so their
      -- inferred body constraints never pass through the meta-generalization
      -- path. Promote those owner-local residual judgments into the same
      -- declaration telescope that inferred schemas eventually receive.
      -- Lexically assumed constraints remain attached to their proof binder
      -- and are deliberately excluded here.
      unless (null rigidRequirements) $
        void (recordActiveUniverseRequirements emptyAssumptions rigidRequirements)
      before <- gets (fmap gdUniverses . Map.lookup owner . csGlobals)
      solved <- solveDeferredLevelConstraints False
      after <- gets (fmap gdUniverses . Map.lookup owner . csGlobals)
      when (solved && after /= before) settleActiveUniverseRequirements

-- | Close checker-created universe instantiations before a reducible body is
-- installed. Module-final solving is too late for these metas: a following
-- declaration may unfold the body during conversion, and an unsolved
-- occurrence would then look like an independent universe choice. Source
-- interface metas are deliberately excluded; only fresh instantiations made
-- while specializing declaration telescopes are principalized here.
principalizeBodyUniverseInstantiations :: GName -> Value -> Term -> CheckM Term
principalizeBodyUniverseInstantiations owner interfaceType body = do
  st <- get
  let assignments = csLevelAssignments st
      bodyMetas = Set.fromList (levelMetasOfTerm (zonkLevels assignments body))
      interfaceMetas =
        Set.fromList
          (levelMetasOfTerm (zonkLevels assignments (quote (ecOf st) 0 interfaceType)))
      provisionalInstantiationMetas =
        Set.fromList
          [ meta
          | occurrence <- csProvisionalUniverseInstantiations st
          , let GName occurrenceModule _ = puiOwner occurrence
          , occurrenceModule == csModule st
          , puiOwner occurrence `Set.notMember` csFinalizedUniverseInterfaces st
          , level <- puiFreshLevels occurrence
          , meta <- levelMetas
              (normalizeLevel (substituteLevelMetas assignments level))
          ]
      recursiveCandidateInstantiationMetas =
        Set.fromList
          [ meta
          | occurrence <- csRecursiveSchemaOccurrences st
          , rsoCaller occurrence == owner
          , not (rsoExplicit occurrence)
          , rsoCallee occurrence `Set.member` csTerminationNames st
          , level <- rsoLevels occurrence
          , meta <- levelMetas
              (normalizeLevel (substituteLevelMetas assignments level))
          ]
      targets =
        Set.filter (`Map.notMember` assignments)
          ( Set.difference
              (Set.difference bodyMetas interfaceMetas)
              (Set.union provisionalInstantiationMetas recursiveCandidateInstantiationMetas)
          )
      ownerSymbols =
        Set.insert owner . Set.fromList $
          [ ctor
          | (ctor, info) <- Map.toList (csCtors st)
          , ciData info == owner
          ]
      constraints =
        [ substituteLevelConstraintMetas assignments constraint
        | constraint <- csLevelConstraints st
        , maybe False (`Set.member` ownerSymbols)
            (Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st))
        ]
  if Set.null targets
    then normalizeProvisionalBodyReferences body
    else do
      let diagnosticSpan = Span "<universe-inference>" (Pos 1 1) (Pos 1 1)
      inferred <-
        inferPrincipalAtDeclarationBoundary
          diagnosticSpan [gKey owner] False targets constraints
      case inferred of
        PrincipalBoundarySolved candidate -> do
          installLevelAssignments candidate
          normalizeProvisionalBodyReferences body
        PrincipalBoundaryDeferred -> pure body
        PrincipalBoundaryRejected -> pure body

-- | Close compiler-created declaration occurrences before deciding which
-- interface levels belong to a generated declaration's own schema.  An
-- instance head such as @Eq TypeLevel@ specializes @Eq@ at a fresh level and
-- constrains that occurrence to its least admissible value.  Treating the
-- fresh level as part of the dictionary's source schema would instead publish
-- a spurious polymorphic instance.
--
-- Source-owned levels are excluded by provenance.  If an occurrence depends
-- on one of those levels and cannot yet be solved independently, the portable
-- solver returns 'PrincipalBoundaryDeferred' and the complete declaration SCC
-- remains the authority.
principalizeGeneratedInterfaceOccurrences
  :: GName
  -> Set LevelMeta
  -> Term
  -> CheckM Term
principalizeGeneratedInterfaceOccurrences owner protectedOrigins interface = do
  st <- get
  let assignments = csLevelAssignments st
      zonked = zonkLevels assignments interface
      interfaceMetas = Set.fromList (levelMetasOfTerm zonked)
      ownedBy relation =
        Set.fromList
          [ meta
          | (meta, owners) <- Map.toList relation
          , owner `Set.member` owners
          ]
      projected =
        Set.fromList
          . concatMap
              ( levelMetas
                  . normalizeLevel
                  . substituteLevelMetas assignments
                  . LMeta
              )
          . Set.toList
      sourceOwned =
        projected
          ( Set.union protectedOrigins
              ( Set.difference
                  (ownedBy (csLevelGeneralizableOwners st))
                  (ownedBy (csLevelInstantiationOwners st))
              )
          )
      targets =
        Set.difference
          interfaceMetas
          sourceOwned
      constraints =
        map
          (substituteLevelConstraintMetas assignments)
          (levelConstraintsOwnedBy st (Set.singleton owner))
      groups = selectedConstraintGroups targets constraints
      diagnosticSpan = Span "<universe-inference>" (Pos 1 1) (Pos 1 1)
  forM_ groups $ \(componentTargets, componentConstraints) -> do
    inferred <-
      inferPrincipalAtDeclarationBoundary
        diagnosticSpan
        [gKey owner]
        False
        componentTargets
        componentConstraints
    case inferred of
      PrincipalBoundarySolved candidate -> installLevelAssignments candidate
      PrincipalBoundaryDeferred -> pure ()
      PrincipalBoundaryRejected -> pure ()
  zonkTermM 0 interface

-- | Resolve unsolved universe metas for one finalized owner without rewriting
-- its published rigid parameters. 'csFinalizedGlobalUniverseMetaMaps' is the
-- authenticated bridge from retained source identities to the declaration
-- telescope. Apply that bridge before the residual assignment graph: a source
-- meta selected for the final telescope denotes its 'LParam' even if an older
-- principalization attempt also recorded a concrete assignment. A genuinely
-- narrowed schema is rebuilt with a new (possibly empty) owner map, so it does
-- not need to reinterpret a still-published parameter after the fact.
resolveFinalizedOwnerLevel :: CheckState -> GName -> Level -> Level
resolveFinalizedOwnerLevel state owner =
  substituteLevelMetas assignments
    . substituteLevelMetas ownerMetas
  where
    assignments = csLevelAssignments state
    ownerMetas =
      Map.findWithDefault
        Map.empty
        owner
        (csFinalizedGlobalUniverseMetaMaps state)

-- | Late declaration bodies (notably instance dictionaries) are elaborated
-- after the module SCC pass.  Their global references may therefore still use
-- a dependency's provisional all-meta universe spine.  Once body-local metas
-- have been principalized, apply the same source-to-retained projection used
-- by the SCC finalizer before the body is recorded.
normalizeProvisionalBodyReferences :: Term -> CheckM Term
normalizeProvisionalBodyReferences body = do
  st <- get
  let targets = Set.toList (globalsOfTerm body)
      globalProjections =
        Map.unions [provisionalUniverseProjections st target | target <- targets]
      constructorProjections =
        Map.unions
          [ provisionalConstructorUniverseProjections st target
          | target <- targets
          ]
  pure
    ( rewriteProvisionalUniverseReferences
        ( UniverseReferenceProjections
            globalProjections
            constructorProjections
            Map.empty
            Map.empty
        )
        body
    )

provisionalUniverseProjections
  :: CheckState
  -> GName
  -> Map (GName, Int) UniverseReferenceProjection
provisionalUniverseProjections st global = fromMaybe Map.empty $ do
  definition <- Map.lookup global (csGlobals st)
  guard (not (dutExplicit (gdUniverses definition)))
  let assignments =
        Map.union
          (Map.findWithDefault Map.empty global (csFinalizedGlobalUniverseMetaMaps st))
          (csLevelAssignments st)
      originalTerms = globalUniverseInterfaceTerms st global definition
      fallbackSource = nub (concatMap levelMetasOfTerm originalTerms)
      sourceSpines =
        Map.findWithDefault [fallbackSource] global
          (csProvisionalGlobalUniverseMetas st)
      normalizedTerms = map (zonkLevels assignments) originalTerms
      retainedSet =
        durGeneralizable (mconcat (map declarationUniverseRoles normalizedTerms))
      retainedMetas =
        filter (`Set.member` retainedSet)
          (concatMap levelMetasOfTerm normalizedTerms)
      retainedLevels =
        if dutParameterCount (gdUniverses definition) > 0
          then map LParam [0 .. dutParameterCount (gdUniverses definition) - 1]
          else map LMeta retainedMetas
  pure $
    uniqueUniverseReferenceProjections
      [ ( (global, length sourceMetas)
        , deriveUniverseReferenceProjectionToLevels assignments sourceMetas retainedLevels
        )
      | sourceMetas <- sourceSpines
      ]

provisionalConstructorUniverseProjections
  :: CheckState
  -> GName
  -> Map (GName, Int) UniverseReferenceProjection
provisionalConstructorUniverseProjections st constructor = fromMaybe Map.empty $ do
  info <- Map.lookup constructor (csCtors st)
  guard (not (dutExplicit (ciUniverses info)))
  let assignments =
        Map.union
          ( Map.findWithDefault
              Map.empty
              constructor
              (csFinalizedGlobalUniverseMetaMaps st)
          )
          (csLevelAssignments st)
      fallbackSource = nub (levelMetasOfTerm (ciType info))
      sourceSpines =
        Map.findWithDefault
          [fallbackSource]
          constructor
          (csProvisionalConstructorUniverseMetas st)
      retainedLevels =
        map LParam [0 .. dutParameterCount (ciUniverses info) - 1]
  pure $
    uniqueUniverseReferenceProjections
      [ ( (constructor, length sourceMetas)
        , deriveUniverseReferenceProjectionToLevels
            assignments
            sourceMetas
            retainedLevels
        )
      | sourceMetas <- sourceSpines
      ]

zonkLevels :: Map LevelMeta Level -> Term -> Term
zonkLevels assignments =
  zonkTermWith
    (\_ _ -> Nothing)
    (substituteLevelMetas assignments)
    0

-- | Reconcile constructor-pattern checkpoint metadata with the finalized
-- typed scrutinee carried by each 'CMatch'. Constructor patterns and their
-- enclosing data family share one declaration-universe schema; provisional
-- body occurrences can nevertheless be minimized before the family SCC
-- acquires its final telescope. The typed match annotation is the checked
-- authority for that occurrence. Unknown heads, arity mismatches, and failed
-- field alignment are left untouched for the final KBackendIR validator.
repairConstructorPatternUniverseSpines
  :: EvalCtx
  -> Map GName CtorInfo
  -> Term
  -> Term
repairConstructorPatternUniverseSpines evaluation constructors = goTerm 0
  where
    rigidEnvironment depth =
      [VRigid level [] | level <- reverse [0 .. depth - 1]]

    goTerm depth =
      mapTermWithDepth (rewriteTerm depth) depth

    rewriteTerm _ currentDepth (CMatch scrutinee annotation resultAnnotation alternatives) =
      let scrutinee' = goTerm currentDepth scrutinee
          annotation' = goTerm currentDepth <$> annotation
          resultAnnotation' = goTerm currentDepth <$> resultAnnotation
          expected =
            eval evaluation (rigidEnvironment currentDepth) <$> annotation'
          alternatives' = map (repairAlternative currentDepth expected) alternatives
       in Just (CMatch scrutinee' annotation' resultAnnotation' alternatives')
    rewriteTerm _ _ _ = Nothing

    repairAlternative depth expected (CaseAlt pattern' guard body) =
      let pattern'' = repairPattern depth expected pattern'
          bodyDepth = depth + patBindersC pattern''
       in CaseAlt
            pattern''
            (goTerm bodyDepth <$> guard)
            (goTerm bodyDepth body)

    repairPattern depth expected = \case
      CPCtorM existentialModes bridges hidden constructor universes patterns ->
        let selected = do
              expectedType <- expected
              info <- Map.lookup constructor constructors
              (family, familyUniverses) <- nominalInstance expectedType
              guard (family == ciData info)
              guard
                (length familyUniverses
                  == dutParameterCount (ciUniverses info))
              pure (info, familyUniverses, expectedType)
            universes' = maybe universes (\(_, levels, _) -> levels) selected
            fieldTypes = do
              (info, levels, expectedType) <- selected
              constructorType <- specializeConstructorType evaluation (Just levels) info
              map snd
                <$> constructorPatternObservationSites
                      evaluation
                      False
                      depth
                      (length (ciFields info))
                      constructorType
                      expectedType
            bridgeDepth = depth + length existentialModes
            (bridges', fieldDepth) = repairBridges bridgeDepth bridges
            expectedTypes =
              fromMaybe
                (replicate (length patterns) Nothing)
                (map Just <$> fieldTypes)
            patterns' =
              repairConstructorPatterns
                fieldDepth
                expectedTypes
                hidden
                patterns
         in CPCtorM existentialModes bridges' hidden constructor universes' patterns'
      CPTuple patterns ->
        let fieldTypes = case expected of
              Just value -> case force evaluation value of
                VRecordTQ fields -> map (Just . rfType) fields
                _ -> replicate (length patterns) Nothing
              Nothing -> replicate (length patterns) Nothing
         in CPTuple (repairPatternList depth fieldTypes patterns)
      CPRecordM fields rest ->
        let recordFields = case expected of
              Just value -> case force evaluation value of
                VRecordTQ available -> available
                _ -> []
              Nothing -> []
            expectedFor name = rfType <$> find ((== name) . rfName) recordFields
            patterns = map snd fields
            repaired =
              repairPatternList
                depth
                [expectedFor name | (name, _) <- fields]
                patterns
         in CPRecordM (zip (map fst fields) repaired) rest
      CPInject tag pattern' ->
        CPInject tag (repairPattern depth Nothing pattern')
      CPOr patterns permutations ->
        CPOr (map (repairPattern depth expected) patterns) permutations
      CPAsM mode name pattern' ->
        CPAsM mode name (repairPattern (depth + 1) expected pattern')
      pattern' -> pattern'

    repairPatternList _ _ [] = []
    repairPatternList depth expectedTypes (pattern' : rest) =
      let expected = listToMaybe expectedTypes >>= id
          pattern'' = repairPattern depth expected pattern'
       in pattern''
            : repairPatternList
                (depth + patBindersC pattern'')
                (drop 1 expectedTypes)
                rest

    repairConstructorPatterns depth expectedTypes hidden patterns =
      case interleaveConstructorSourceBinders hidden (zip expectedTypes patterns) of
        Nothing -> patterns
        Just slots -> go depth slots
      where
        go _ [] = []
        go currentDepth (Left _ : rest) =
          go (currentDepth + 1) rest
        go currentDepth (Right (expected, pattern') : rest) =
          let repaired = repairPattern currentDepth expected pattern'
           in repaired
                : go
                    (currentDepth + patBindersC repaired)
                    rest

    repairBridges depth [] = ([], depth)
    repairBridges depth (bridge : rest) =
      case bridge of
        ConstructorForcedEquality left right ->
          let bridge' =
                ConstructorForcedEquality
                  (goTerm depth left)
                  (goTerm depth right)
              (rest', finalDepth) = repairBridges depth rest
           in (bridge' : rest', finalDepth)
        ConstructorPropositionalBridge proposition proof ->
          let bridge' =
                ConstructorPropositionalBridge
                  (goTerm depth proposition)
                  (goTerm depth proof)
              (rest', finalDepth) = repairBridges (depth + 1) rest
           in (bridge' : rest', finalDepth)

    nominalInstance value =
      case force evaluation value of
        VGlobI family universes _ -> Just (family, universes)
        _ -> Nothing

-- | Materialize the solved universe substitution in every semantic artifact
-- that survives the module boundary. The assignment map is elaborator state;
-- finalized Core and imported interfaces must be closed on their own.
finalizeLevelArtifacts :: CheckM ()
finalizeLevelArtifacts = do
  st <- get
  let assignments = csLevelAssignments st
      ec = ecOf st
      currentModule = csModule st
      zonkCurrentMap transform =
        Map.mapWithKey
          (\global value ->
             if gnameInModule global currentModule
               then transform global value
               else value)
      zonkCurrentOwner transform owner value =
        if gnameInModule owner currentModule
          then transform value
          else value
      finalUniverseArity global =
        (dutParameterCount . gdUniverses <$> Map.lookup global (csGlobals st))
          <|> (dutParameterCount . ciUniverses <$> Map.lookup global (csCtors st))
      -- A final arity of zero is itself a complete projection proof: none of
      -- the provisional dependency metas survived in the referenced schema.
      -- Remove only that obsolete all-meta spine here. Nonzero mismatches stay
      -- intact so the finalized-Core validator rejects rather than guessing a
      -- retained-position mapping.
      canonicalizeMonomorphicReferences =
        mapPatternConstructorUniverses
          (\constructor universes ->
             if not (null universes) && finalUniverseArity constructor == Just 0
               then []
               else universes)
          . mapTermWithDepth
              (\_ -> \case
                 CGlobal global universes
                   | not (null universes)
                   , finalUniverseArity global == Just 0 -> Just (CGlobal global [])
                 CCtorI constructor universes annotation arguments
                   | not (null universes)
                   , finalUniverseArity constructor == Just 0 ->
                       Just (CCtorI constructor [] annotation arguments)
                 _ -> Nothing)
              0
      resolveTermMeta = resolvedMetaCore st ec
      zonkTermWithLevels resolveLevel =
        -- Finalization is a substitution over already checked dependent Core,
        -- not a second elaboration pass. Rewriting evidence-selected
        -- operations independently in types and terms can invalidate
        -- eliminator telescopes and proof arguments. Operations whose
        -- evidence was established during elaboration are already canonical;
        -- late cases retain their checked generic lowering.
        canonicalizeMonomorphicReferences
          . zonkTermWith resolveTermMeta resolveLevel 0
      zonkTerm = zonkTermWithLevels (substituteLevelMetas assignments)
      ownerLevelResolver = resolveFinalizedOwnerLevel st
      zonkOwnedTerm owner = zonkTermWithLevels (ownerLevelResolver owner)
      zonkValue value =
        let term = zonkTerm (quote ec 0 value)
         in if termScopedAt 0 term then eval ec [] term else value
      zonkOwnedValue owner value =
        let term = zonkOwnedTerm owner (quote ec 0 value)
         in if termScopedAt 0 term then eval ec [] term else value
      zonkGlobal global def =
        let coreType = zonkOwnedTerm global <$> gdCoreType def
            coreBody = zonkOwnedTerm global <$> (Map.lookup global (csCoreBodies st) <|> gdCoreBody def)
         in def
              { gdType = case coreType of
                  Just ty | termScopedAt 0 ty -> eval ec [] ty
                  _ -> zonkValue (gdType def)
              , gdCoreType = coreType
              , gdValue = case coreBody of
                  Just body -> Just (eval ec [] body)
                  Nothing ->
                    if Map.member global (csTraits st)
                         || globalValueIsUniverseInterface
                              (csUniverseInterfaceValues st) global def
                      then zonkOwnedValue global <$> gdValue def
                      else gdValue def
              , gdCoreBody = coreBody
              }
      zonkData owner info =
        info {diLevel = ownerLevelResolver owner (diLevel info)}
      zonkCtor owner info = info {ciType = zonkOwnedTerm owner (ciType info)}
      zonkTrait owner info =
        info {tiSupers = [(name, zonkOwnedTerm owner term) | (name, term) <- tiSupers info]}
      zonkInstance entry =
        entry
          { ieTraitUniverses = map (ownerLevelResolver (ieDict entry)) (ieTraitUniverses entry)
          , ieUniverses = zonkUniverseTelescope (ieUniverses entry)
          , iePremises = map (zonkOwnedTerm (ieDict entry)) (iePremises entry)
          , ieHead = map (zonkOwnedTerm (ieDict entry)) (ieHead entry)
          }
      zonkUniverseTelescope telescope = telescope
      zonkPreInstance entry =
        entry
          { piFvTele = [te {teDomain = zonkOwnedTerm (piDictG entry) (teDomain te)} | te <- piFvTele entry]
          , piPremTms = map (zonkOwnedTerm (piDictG entry)) (piPremTms entry)
          , piArgTms = map (zonkOwnedTerm (piDictG entry)) (piArgTms entry)
          }
      zonkEffLabel info =
        let zonkEffectTerm = zonkOwnedTerm (eliIface info)
            zonkEffectValue = zonkOwnedValue (eliIface info)
            zonkEffectLevel = ownerLevelResolver (eliIface info)
         in
        info
          { eliParams = [entry {teDomain = zonkEffectTerm (teDomain entry)} | entry <- eliParams info]
          , eliFixedArgs = fmap (map zonkEffectValue) (eliFixedArgs info)
          , eliFixedUniverses = fmap (map zonkEffectLevel) (eliFixedUniverses info)
          , eliOps = map (zonkEffOp zonkEffectTerm) (eliOps info)
          }
      zonkEffOp zonkEffectTerm info =
        info
          { eoiImplicits = [entry {teDomain = zonkEffectTerm (teDomain entry)} | entry <- eoiImplicits info]
          , eoiArgs = [entry {teDomain = zonkEffectTerm (teDomain entry)} | entry <- eoiArgs info]
          , eoiResT = zonkEffectTerm (eoiResT info)
          }
      zonkTermination decl =
        decl
          { tdSigType = zonkOwnedValue (tdName decl) (tdSigType decl)
          , tdCoreBody = zonkOwnedTerm (tdName decl) (tdCoreBody decl)
          }
      globalsZonked = zonkCurrentMap zonkGlobal (csGlobals st)
      constructorsFinal = zonkCurrentMap zonkCtor (csCtors st)
      finalizedContext = ec {ecGlobals = Globals globalsZonked}
      repairPatterns =
        repairConstructorPatternUniverseSpines
          finalizedContext
          constructorsFinal
      coreBodiesFinal =
        Map.map repairPatterns
          (zonkCurrentMap zonkOwnedTerm (csCoreBodies st))
      globalsFinal =
        Map.map
          (\definition ->
             definition
               { gdCoreBody = repairPatterns <$> gdCoreBody definition
               })
          globalsZonked
      finalized =
        setCheckInstances
          [ zonkCurrentOwner zonkInstance (ieDict entry) entry
          | entry <- csInstances st
          ] $
        st
          { csGlobals = globalsFinal
          , csDatas = zonkCurrentMap zonkData (csDatas st)
          , csCtors = constructorsFinal
          , csTraits = zonkCurrentMap zonkTrait (csTraits st)
          , csBareTypeLevels = Map.map (substituteLevelMetas assignments) (csBareTypeLevels st)
          , csPreInstances =
              Map.map
                (fmap (\entry -> zonkCurrentOwner zonkPreInstance (piDictG entry) entry))
                (csPreInstances st)
          , csModEffLabels = Map.map zonkEffLabel (csModEffLabels st)
          , csEffectInterfaces =
              Map.map
                (\info -> zonkCurrentOwner zonkEffLabel (eliIface info) info)
                (csEffectInterfaces st)
          , csCoreBodies = coreBodiesFinal
          , csCoreSignatures =
              Map.filterWithKey
                (\global _ -> not (gnameInModule global currentModule))
                (csCoreSignatures st)
          , csBackendIntrinsics = Map.map zonkTerm (csBackendIntrinsics st)
          , csFoundationProviders = Map.map zonkTerm (csFoundationProviders st)
          , csTerminationDecls =
              Map.map
                (\declaration ->
                   zonkCurrentOwner zonkTermination (tdName declaration) declaration)
                (csTerminationDecls st)
          }
  put (invalidateSemanticCaches finalized)

reportLevelSolveError :: LevelSolveError -> CheckM ()
reportLevelSolveError solveError = do
  let constraint = levelSolveErrorConstraint solveError
  owner <- gets (Map.lookup (lcIdentity constraint) . csLevelConstraintOwners)
  sourceSpan <- gets (Map.lookup (lcIdentity constraint) . csLevelConstraintSpans)
  reportLevelSolveErrorWithProvenance owner sourceSpan solveError

levelSolveErrorConstraint :: LevelSolveError -> LevelConstraint
levelSolveErrorConstraint = \case
  LevelConstraintDisproved constraint -> constraint
  LevelContradictoryAssumptions constraint -> constraint
  LevelMetaOccurs _ _ constraint -> constraint
  LevelResourceLimit constraint _ -> constraint

-- | Render one solver failure with explicit source provenance. Deferred
-- constraints obtain this data from the checker side tables above; immediate
-- rigid conversion failures use the same constructor directly and therefore
-- do not poison the persistent inference graph with a known-unsatisfiable
-- edge merely to attach a span.
reportLevelSolveErrorWithProvenance
  :: Maybe GName
  -> Maybe Span
  -> LevelSolveError
  -> CheckM ()
reportLevelSolveErrorWithProvenance owner sourceSpan solveError = do
  let (code, constraint, detail) = case solveError of
        LevelConstraintDisproved c
          | constraintIsSelfContaining c ->
              ("E_UNIVERSE_SELF_CONTAINMENT", c, "the universe inequality requires strict self-containment")
          | otherwise ->
              ("E_UNIVERSE_CONSTRAINT_UNSATISFIABLE", c, "the universe inequality is inconsistent")
        LevelContradictoryAssumptions c ->
          ( "E_UNIVERSE_CONSTRAINT_UNSATISFIABLE"
          , c
          , "the scoped universe assumptions are contradictory"
          )
        LevelMetaOccurs meta lower c ->
          ( "E_UNIVERSE_SELF_CONTAINMENT"
          , c
          , "universe metavariable ?u" <> T.pack (show meta)
              <> " occurs recursively in " <> renderLevel lower
          )
        LevelResourceLimit c limit ->
          ( "E_UNIVERSE_INFERENCE_REQUIRES_ANNOTATION"
          , c
          , "the exact universe solver exceeded its "
              <> T.pack (show limit)
              <> "-node materialization budget; add an explicit universe schema or simplify the level relation"
          )
      normalized = renderLevel (lcLhs constraint) <> " <= " <> renderLevel (lcRhs constraint)
      ConstraintOrigin description construct = lcOrigin constraint
  let primary = fromMaybe (Span "<universe-inference>" (Pos 1 1) (Pos 1 1)) sourceSpan
      withOwner = case owner of
        Just declaration -> withPayloadField "declaration" (gKey declaration)
        Nothing -> id
      ownerKey = fmap gKey owner
      diagnostic =
        withPayload
          ( withPayloadField "normalizedFailedConstraint" normalized
              $ withPayloadField "levelAssumptions" (renderLevelAssumptions (lcAssumptions constraint))
              $ withPayloadField "constraintOrigin" description
              $ withPayloadField "construct" construct
              $ withOwner
              $ payloadKind "universe-constraint"
          )
          $ diag SevError StageElaborate code (Just "kappa.universe.constraint")
            primary
            (detail <> ": " <> normalized <> " (§11.1.3)")
      sameFailure existing =
        dCode existing == code
          && lookup "normalizedFailedConstraint" (pFields (dPayload existing)) == Just normalized
          && lookup "declaration" (pFields (dPayload existing)) == ownerKey
          && dPrimary existing == primary
  alreadyReported <- gets (any sameFailure . csDiags)
  unless alreadyReported (report diagnostic)
  where
    -- A failed @lhs <= rhs@ closes a strict cycle exactly when @lhs@ is
    -- equivalent to @succ rhs@ under the active assumptions. A merely closed
    -- contradiction such as @1 <= 0@ is unsatisfiable, but is not itself a
    -- self-containment cycle.
    constraintIsSelfContaining constraint =
      let assumptions = lcAssumptions constraint
          successor = levelSucc (lcRhs constraint)
       in proveLevelLeq assumptions successor (lcLhs constraint) == Proved
            && proveLevelLeq assumptions (lcLhs constraint) successor == Proved

-- | Final module solving can revisit an inconsistency already diagnosed while
-- checking a declaration body. 'reportLevelSolveError' deduplicates that
-- report, so closeout must distinguish "already explained" from "solver
-- failed silently" before adding the generic residual diagnostic.
levelConstraintFailureAlreadyReported :: CheckState -> LevelConstraint -> Bool
levelConstraintFailureAlreadyReported state constraint =
  any matches (csDiags state)
  where
    assignments = csLevelAssignments state
    normalized =
      renderLevel (substituteLevelMetas assignments (lcLhs constraint))
        <> " <= "
        <> renderLevel (substituteLevelMetas assignments (lcRhs constraint))
    ownerKey =
      gKey <$> Map.lookup (lcIdentity constraint) (csLevelConstraintOwners state)
    sourceSpan =
      Map.lookup (lcIdentity constraint) (csLevelConstraintSpans state)
    matches diagnostic =
      dCode diagnostic
        `elem` [ "E_UNIVERSE_CONSTRAINT_UNSATISFIABLE"
               , "E_UNIVERSE_SELF_CONTAINMENT"
               ]
        && lookup "normalizedFailedConstraint" (pFields (dPayload diagnostic))
             == Just normalized
        && lookup "declaration" (pFields (dPayload diagnostic)) == ownerKey
        && maybe True (== dPrimary diagnostic) sourceSpan

-- | Emit the complete §3.1.4/§11.1.2.4A no-principal-solution record.  Every
-- inference boundary uses this constructor so local declarations, bodies, and
-- top-level SCCs expose the same machine-readable evidence rather than a
-- message-only approximation.
reportNoPrincipalUniverseDiagnostic
  :: Span
  -> [Text]
  -> Bool
  -> Set LevelMeta
  -> [LevelConstraint]
  -> Maybe PrincipalNonLeastWitness
  -> Text
  -> CheckM ()
reportNoPrincipalUniverseDiagnostic diagnosticSpan declarations explicitSchema metas constraints witness message =
  report $
    withPayload
      ( withPayloadField "declarationIdentity" declarationIdentity
          $ withPayloadField "declarationSccIdentity" sccIdentity
          $ withPayloadField "unresolvedUniverseMetavariables" renderedMetas
          $ withPayloadField "normalizedBounds" renderedBounds
          $ withPayloadField "candidateIncomparableMinimalSolutions" candidateMinima
          $ withPayloadField "sourceOrigins" renderedOrigins
          $ withPayloadField "explicitUniverseSchema" (if explicitSchema then "true" else "false")
          $ withPayloadField "suggestedRepair" suggestedRepair
          $ payloadKind "universe-no-principal-solution"
      )
      $ diag SevError StageElaborate "E_UNIVERSE_NO_PRINCIPAL_SOLUTION"
        (Just "kappa.universe.no-principal-solution") diagnosticSpan message
  where
    normalizedDeclarations = sort (nub declarations)
    declarationIdentity = case normalizedDeclarations of
      [] -> "<local-declaration>"
      [declaration] -> declaration
      many -> T.intercalate ", " many
    -- The ordered member identities are the canonical identity of a semantic
    -- SCC. Source spelling order and allocation counters do not participate.
    sccIdentity = T.intercalate "|" normalizedDeclarations
    renderedMetas =
      T.intercalate ", " ["?u" <> T.pack (show meta) | meta <- Set.toAscList metas]
    mentions meta level = meta `elem` levelMetas level
    boundsFor meta =
      [ renderLevel (normalizeLevel lower)
          <> " <= " <> renderLevel (normalizeLevel upper)
      | constraint <- constraints
      , (lower, upper) <-
          (lcLhs constraint, lcRhs constraint) : assumptionsList (lcAssumptions constraint)
      , mentions meta lower || mentions meta upper
      ]
    renderedBounds =
      T.intercalate "; "
        [ "?u" <> T.pack (show meta) <> ": ["
            <> T.intercalate ", " (nub (boundsFor meta)) <> "]"
        | meta <- Set.toAscList metas
        ]
    renderedOrigins =
      T.intercalate "; " . nub $
        [ coDescription origin <> " (" <> coConstruct origin <> ")"
        | constraint <- constraints
        , let origin = lcOrigin constraint
        , any
            (\meta -> any (\(lower, upper) -> mentions meta lower || mentions meta upper)
              ((lcLhs constraint, lcRhs constraint) : assumptionsList (lcAssumptions constraint)))
            (Set.toList metas)
        ]
    candidateMinima = case witness of
      Just checked ->
        "left=" <> renderAssignment (pnlwLeft checked)
          <> "; right=" <> renderAssignment (pnlwRight checked)
      Nothing -> "not-applicable"
    renderAssignment assignment =
      "{" <> T.intercalate ", "
        [ "?u" <> T.pack (show meta) <> "=" <> renderLevel level
        | (meta, level) <- Map.toAscList assignment
        ] <> "}"
    suggestedRepair =
      "add the unresolved levels to an explicit .{u...} declaration schema or constrain the result universe so the least solution is unique"

-- | Report the distinct §11.1.3 outcome in which a semantic principal value
-- may exist but is not derivable by the versioned portable assignment rules.
-- This is deliberately not the no-principal family: tools and users need to
-- know that an annotation can make the same program portable without claiming
-- a mathematical non-principality result.
reportUniverseInferenceRequiresAnnotation
  :: Span
  -> [Text]
  -> Bool
  -> Set LevelMeta
  -> [LevelConstraint]
  -> Text
  -> CheckM ()
reportUniverseInferenceRequiresAnnotation diagnosticSpan declarations explicitSchema metas constraints semanticStatus =
  forM_ (Set.toAscList metas) $ \meta -> do
    let normalizedDeclarations = sort (nub declarations)
        declarationIdentity = case normalizedDeclarations of
          [] -> "<local-declaration>"
          [declaration] -> declaration
          many -> T.intercalate ", " many
        sccIdentity = T.intercalate "|" normalizedDeclarations
        mentions level = meta `elem` levelMetas level
        relevant =
          [ constraint
          | constraint <- constraints
          , mentions (lcLhs constraint) || mentions (lcRhs constraint)
          ]
        renderedConstraints =
          T.intercalate "; "
            [ renderLevel (normalizeLevel (lcLhs constraint))
                <> " <= "
                <> renderLevel (normalizeLevel (lcRhs constraint))
            | constraint <- relevant
            ]
        renderedAssumptions =
          T.intercalate "; " . nub $
            [ renderLevelAssumptions (lcAssumptions constraint)
            | constraint <- relevant
            , not (null (assumptionsList (lcAssumptions constraint)))
            ]
        repair =
          if explicitSchema
            then "add an explicit result-universe annotation that determines this schema occurrence"
            else "add an explicit .{u...} declaration schema or result-universe annotation for this occurrence"
    report $
      withPayload
        ( withPayloadField "declarationIdentity" declarationIdentity
            $ withPayloadField "declarationSccIdentity" sccIdentity
            $ withPayloadField "selectedMetavariableIdentity" ("?u" <> T.pack (show meta))
            $ withPayloadField "normalizedConstraints" renderedConstraints
            $ withPayloadField "rigidAssumptions" renderedAssumptions
            $ withPayloadField "portableAssignmentRulesAttempted"
                "direct lower-bound join; natural-add/successor cancellation; closed residuation; selected max contexts; substitution and rigid recheck"
            $ withPayloadField "semanticLeastSolutionStatus" semanticStatus
            $ withPayloadField "smallestKnownRepair" repair
            $ payloadKind "universe-inference-requires-annotation"
        )
        $ diag SevError StageElaborate "E_UNIVERSE_INFERENCE_REQUIRES_ANNOTATION"
          (Just "kappa.universe.inference-requires-annotation") diagnosticSpan
          "portable universe inference cannot determine this minimizable level; add an explicit annotation (§11.1.3)"

-- | The only successful declaration-boundary inference path. The detailed
-- solver remains useful for ordinary unification and for recovering the
-- concrete failed constraint, but declaration completion consumes the
-- normative five-way classification directly and never defaults a residual
-- selected metavariable by inspecting 'LevelSolution'.
data PrincipalBoundaryResult
  = PrincipalBoundarySolved !(Map LevelMeta Level)
  | PrincipalBoundaryDeferred
  | PrincipalBoundaryRejected

inferPrincipalAtDeclarationBoundary
  :: Span
  -> [Text]
  -> Bool
  -> Set LevelMeta
  -> [LevelConstraint]
  -> CheckM PrincipalBoundaryResult
inferPrincipalAtDeclarationBoundary diagnosticSpan declarations explicitSchema targets constraints =
  -- Inconsistency dominates the portable-fragment classification. A system
  -- with no model is not merely one whose principal solution needs an
  -- annotation, even when its syntax also lies outside the assignable
  -- fragment.
  case solveLevelConstraintsFor targets constraints of
    Left LevelResourceLimit {} -> do
      recordOutcome InferenceOutsidePortableInferenceFragment Map.empty
      reportUniverseInferenceRequiresAnnotation diagnosticSpan declarations explicitSchema targets constraints
        "unknown: the exact solver crossed its resource boundary before a principal solution could be established"
      pure PrincipalBoundaryRejected
    Left solveError -> do
      recordOutcome InferenceUnsatisfiable Map.empty
      reportLevelSolveError solveError
      pure PrincipalBoundaryRejected
    Right _ ->
      case inferPrincipalLevelsFor targets constraints of
        SolvedPrincipal assignments -> do
          recordOutcome InferenceSolvedPrincipal assignments
          pure (PrincipalBoundarySolved assignments)
        Unsatisfiable -> do
          recordOutcome InferenceUnsatisfiable Map.empty
          report $
            diag SevError StageElaborate "E_UNIVERSE_CONSTRAINT_UNSATISFIABLE"
              (Just "kappa.universe.constraint") diagnosticSpan
              "the selected universe constraint system is unsatisfiable (§11.1.3)"
          pure PrincipalBoundaryRejected
        NoPointwiseLeastSolution witness -> do
          recordOutcome InferenceNoPointwiseLeastSolution Map.empty
          reportNoPrincipalUniverseDiagnostic diagnosticSpan declarations explicitSchema targets constraints (Just witness)
            "declaration universe constraints have valid solutions but no pointwise least solution (§11.1.3)"
          pure PrincipalBoundaryRejected
        OutsidePortableInferenceFragment -> do
          recordOutcome InferenceOutsidePortableInferenceFragment Map.empty
          reportUniverseInferenceRequiresAnnotation diagnosticSpan declarations explicitSchema targets constraints
            "unknown: a semantic least solution may exist, but the constraint is outside the portable inference fragment"
          pure PrincipalBoundaryRejected
        BlockedByUnselectedMetas -> do
          recordOutcome InferenceBlockedByUnselectedMetas Map.empty
          -- This is not a source failure. At an intermediate declaration
          -- boundary the unselected metas are usually legal
          -- source-generalizable schema levels that have not yet been
          -- replaced by rigid parameters.
          pure PrincipalBoundaryDeferred
  where
    recordOutcome inferenceClass assignments =
      modify' $ \state ->
        state
          { csUniverseInferenceRecords =
              foldr
                (\declaration ->
                  Map.insert declaration (UniverseInferenceRecord inferenceClass assignments))
                (csUniverseInferenceRecords state)
                declarations
          }

installLevelAssignments :: HasCallStack => Map LevelMeta Level -> CheckM ()
installLevelAssignments new = do
  old <- gets csLevelAssignments
  oldDependents <- gets csLevelAssignmentDependents
  oldBudget <- gets csLevelAssignmentBudget
  case extendLevelAssignmentGraphWithBudget old oldDependents oldBudget new of
    Left (LevelAssignmentGraphConflict meta installed requested) ->
      report $
        withPayload
          ( withPayloadField "metavariable" ("?u" <> T.pack (show meta)) $
              withPayloadField "installedAssignment" (renderLevel installed) $
                withPayloadField "requestedAssignment" (renderLevel requested) $
                  payloadKind "universe-assignment-conflict"
          ) $
          diag SevError StageElaborate "E_UNIVERSE_CONSTRAINT_UNSATISFIABLE"
            (Just "kappa.universe.constraint")
            (Span "<universe-inference>" (Pos 1 1) (Pos 1 1))
            ( "a principal universe assignment was revised after installation: ?u"
                <> T.pack (show meta)
                <> " was " <> renderLevel installed
                <> ", requested " <> renderLevel requested
            )
    Left (LevelAssignmentGraphResourceLimit budget) ->
      report $
        withPayload
          ( withPayloadField "nodeBudget" (T.pack (show budget)) $
              payloadKind "universe-resource-limit"
          ) $
          diag SevError StageElaborate "E_UNIVERSE_INFERENCE_REQUIRES_ANNOTATION"
            (Just "kappa.universe.inference-requires-annotation")
            (Span "<universe-inference>" (Pos 1 1) (Pos 1 1))
            "incremental universe assignments exceed the portable solver resource boundary"
    Right (combined, dependents, budget, affected) -> do
      modify' $ \st ->
        st
          { csLevelAssignments = combined
          , csLevelAssignmentDependents = dependents
          , csLevelAssignmentBudget = budget
          }
      -- A new solution can make an older symbolic assignment concrete.
      -- Follow the reverse dependency closure and compare effective values;
      -- unrelated assignments have already been reflected into 'csMetas'.
      forM_ (Set.toAscList affected) $ \meta -> do
        let before = substituteLevelMetas old (LMeta meta)
            after = substituteLevelMetas combined (LMeta meta)
        when (before /= after) $
          forM_ (levelValueMaybe after) (solveMeta meta)

-- Hidden declaration-universe parameters are compiler-only telescope entries,
-- not term binders. Only levels with an actual term representation may be
-- reflected into the ordinary elaboration metavariable store.
levelValueMaybe :: Level -> Maybe Value
levelValueMaybe = \case
  LZero -> Just (VPrim "__typeLevelZero" [])
  LFinite n -> Just (VPrim "__typeLevelFinite" [VLit (LitInt n)])
  LOmega -> Just (VPrim "__typeLevelOmega" [])
  LSucc a -> VPrim "__typeLevelSucc" . pure <$> levelValueMaybe a
  LAdd a b -> do
    a' <- levelValueMaybe a
    b' <- levelValueMaybe b
    pure (VPrim "__typeLevelAdd" [a', b'])
  LMax a b -> do
    a' <- levelValueMaybe a
    b' <- levelValueMaybe b
    pure (VPrim "__typeLevelMax" [a', b'])
  LVar v -> Just (VRigid v [])
  LField _ field -> Just (VProjN Ordinary (VGlobN thisG []) field)
  LProjection root path ->
    Just (foldl (\receiver field -> VProjN Ordinary receiver field) (VRigid root []) path)
  LNeutral _ -> Nothing
  LParam _ -> Nothing
  LMeta _ -> Nothing

levelOperatorValue :: LevelOperatorIdentity -> Value
levelOperatorValue = \case
  LevelOperatorZero -> VPrim "__typeLevelZero" []
  LevelOperatorOne -> VPrim "__typeLevelFinite" [VLit (LitInt 1)]
  LevelOperatorSucc -> VPrim "__typeLevelSucc" []
  LevelOperatorAdd -> VPrim "__typeLevelAdd" []
  LevelOperatorMax -> VPrim "__typeLevelMax" []
  LevelOperatorFromInteger -> VPrim "__typeLevelFromNat" []
  LevelOperatorLt -> VGlobN (gPrel "<") []
  LevelOperatorLe -> VGlobN (gPrel "<=") []

recordLevelOperatorAlias :: GName -> Term -> CheckM ()
recordLevelOperatorAlias g term = do
  classifyLevelOperatorTerm Set.empty term >>= mapM_ (rememberLevelOperatorAlias g)

-- | Recover the semantic identity of a transparent local alias before its
-- body pass. Header checking may need such an identity in a later universe
-- proof, so the predeclared source equation is checked against the already
-- elaborated signature and then admitted only when finalized Core is an exact
-- rename or eta-expansion of an authenticated operation.
resolveLevelOperatorAliasIdentity :: Set GName -> GName -> CheckM (Maybe LevelOperatorIdentity)
resolveLevelOperatorAliasIdentity seen g
  | g `Set.member` seen = pure Nothing
  | otherwise = do
      known <- gets (Map.lookup g . csLevelOperatorAliases)
      case known of
        Just identity -> pure (Just identity)
        Nothing -> do
          definitions <- gets csTransparentValueAliases
          case Map.lookup g definitions of
            Nothing -> pure Nothing
            Just rhs -> do
              global <- gets (Map.lookup g . csGlobals)
              candidate <- case global of
                Just definition -> levelOperatorResultCarrier (gdType definition)
                Nothing -> pure True
              if not candidate
                then pure Nothing
                else do
                  aliasTerm <- case global of
                    Just definition -> check emptyCtx rhs (gdType definition)
                    Nothing -> fst <$> infer emptyCtx rhs
                  -- Overloaded source aliases elaborate through an evidence
                  -- metavariable.  Resolve and zonk that evidence before
                  -- authenticating the selected operation; the surrounding
                  -- speculative transaction rolls every other effect back.
                  flushPendingFinal
                  aliasTerm' <- zonkTermM 0 aliasTerm
                  identity <- classifyLevelOperatorTerm (Set.insert g seen) aliasTerm'
                  forM_ identity (rememberLevelOperatorAlias g)
                  pure identity

-- | A semantic level operation must ultimately produce either a TypeLevel
-- value or the Bool result of a level comparison. This cheap typed filter runs
-- before re-elaborating a captured source equation, so unrelated transparent
-- definitions (especially proof terms) are never inspected as alias
-- candidates. Exact operation identity is still established structurally by
-- 'classifyLevelOperatorTerm'.
levelOperatorResultCarrier :: Value -> CheckM Bool
levelOperatorResultCarrier = go False 0
  where
    go consumedTypeLevel level value = forceM value >>= \case
      VPiM _ _ _ _ _ domain closure -> do
        domain' <- forceM domain
        let consumesTypeLevel =
              consumedTypeLevel
                || case domain' of
                     VGlobN g [] -> g == prelTypeLevel
                     _ -> False
        clApp closure (VRigid level []) >>= go consumesTypeLevel (level + 1)
      VGlobN g [] ->
        pure
          ( g == prelTypeLevel
              || (g == prelBool && consumedTypeLevel)
          )
      _ -> pure False

rememberLevelOperatorAlias :: GName -> LevelOperatorIdentity -> CheckM ()
rememberLevelOperatorAlias g identity =
  modify' $ \st ->
    st {csLevelOperatorAliases = Map.insert g identity (csLevelOperatorAliases st)}

-- | Make a signed transparent alias available to later declaration headers.
-- The module checker processes every signature before any ordinary body, but
-- universe annotations in a later header may depend on the alias's semantic
-- identity. Certification is speculative: keep only a clean identity proof
-- and roll back diagnostics, metas, goals, and every other elaboration effect.
-- The body pass still performs the authoritative definition check.
precertifyLevelOperatorAlias :: GName -> CheckM ()
precertifyLevelOperatorAlias g = do
  baseline <- get
  identity <- resolveLevelOperatorAliasIdentity Set.empty g
  after <- get
  put $ case identity of
    Just proven
      | length (csDiags after) == length (csDiags baseline) ->
          baseline
            { csLevelOperatorAliases =
                Map.insert g proven (csLevelOperatorAliases baseline)
            }
    _ -> baseline

classifyLevelOperatorTerm :: Set GName -> Term -> CheckM (Maybe LevelOperatorIdentity)
classifyLevelOperatorTerm seen tm = do
  let (binders, body) = peelLambdas tm
      (headTm, args) = spineWithIcit body
  identity <- case headTm of
    CGlob op
      | op == prelTypeLevelZero -> pure (Just LevelOperatorZero)
      | op == prelTypeLevelSucc -> pure (Just LevelOperatorSucc)
      | op == prelTypeLevelAdd -> pure (Just LevelOperatorAdd)
      | op == prelTypeLevelMax -> pure (Just LevelOperatorMax)
      | otherwise ->
          authenticatedStandardLevelOperator op args >>= \case
            Just proven -> pure (Just proven)
            Nothing -> resolveLevelOperatorAliasIdentity seen op
    _ -> pure Nothing
  pure $ identity <* guard (etaEquivalent binders args)
  where
    peelLambdas = \case
      CLam ic _ _ body ->
        let (rest, result) = peelLambdas body
         in (ic : rest, result)
      body -> ([], body)

    spineWithIcit = go []
      where
        go args (CApp ic fun arg) = go ((ic, arg) : args) fun
        go args headTm = (headTm, args)

    etaEquivalent [] _ = True
    etaEquivalent binders args
      | length args < arity = False
      | otherwise =
          and
            [ ic == binderIcit && arg == CVar (arity - offset - 1)
            | (offset, (binderIcit, (ic, arg))) <- zip [0 :: Int ..] (zip binders suffix)
            ]
            && all (not . mentionsAnyEtaBinder . snd) prefix
      where
        arity = length binders
        (prefix, suffix) = splitAt (length args - arity) args
        mentionsAnyEtaBinder argument =
          any (`mentionsVar` argument) [0 .. arity - 1]

-- | Authenticate one overloaded TypeLevel operation by exact member identity,
-- carrier, and selected dictionary. Both the user-facing operator aliases and
-- the underlying trait members can appear in finalized Core, so spelling is
-- never the authorization boundary.
authenticatedStandardLevelOperator :: GName -> [(Icit, Term)] -> CheckM (Maybe LevelOperatorIdentity)
authenticatedStandardLevelOperator operation arguments =
  case Map.lookup operation standardOperators of
    Nothing -> pure Nothing
    Just (identity, trait) ->
      case [argument | (Impl, argument) <- arguments] of
        carrier : dictionary : _
          | termHeadGlob (stripIdentityWrappers carrier) == Just prelTypeLevel -> do
              standard <- standardTypeLevelDictionary trait dictionary
              pure (if standard then Just identity else Nothing)
        _ -> pure Nothing
  where
    standardOperators = Map.fromList
      [ (gPrel "zero", (LevelOperatorZero, gPrel "Zero"))
      , (gPrel "one", (LevelOperatorOne, gPrel "One"))
      , (gPrel "fromInteger", (LevelOperatorFromInteger, gPrel "FromInteger"))
      , (prelSucc, (LevelOperatorSucc, prelSuccessor))
      , (gPrel "+", (LevelOperatorAdd, gPrel "Add"))
      , (gPrel "add", (LevelOperatorAdd, gPrel "Add"))
      , (prelMaxOp, (LevelOperatorMax, prelMax))
      , (gPrel "<", (LevelOperatorLt, prelOrd))
      , (gPrel "<=", (LevelOperatorLe, prelOrd))
      ]

-- | Make two types definitionally equal, solving metavariables as needed,
-- and report whether it succeeded. This is how an /inferred/ type is
-- reconciled with an /expected/ one. It first compares matching global heads
-- (including their hidden universe instances), then forces other heads and
-- compares structurally; when one side is an unsolved meta ('VFlex') it
-- solves it (after the occurs check), and along the outer Pi spine it
-- allows quantity subsumption ('qSubsumes', gated by @allowQSubsumption@). It only ever
-- returns 'True' soundly — an undecidable comparison answers 'False'.
unify :: Ctx -> Value -> Value -> CheckM Bool
unify ctx actual expected = do
  exact <- gets csDefinitionalEqualityOnly
  unifyWith exact ctx actual expected

-- | Definitional equality with metavariable solving, but without any of the
-- directed subsumption admitted by ordinary expected-type checking. Instance
-- heads use this relation for higher-kinded arguments (§14.3.2).
unifyDefinitional :: Ctx -> Value -> Value -> CheckM Bool
unifyDefinitional = unifyWith True

unifyWith :: Bool -> Ctx -> Value -> Value -> CheckM Bool
unifyWith exact ctx =
  goAt
    (256 :: Int)
    (not exact)
    (not exact)
    (ctxLen ctx)
  where
    -- allowQSubsumption: §12.2.1 binder-quantity subsumption applies only along the
    -- outer Pi spine of the unified types, never under records, type
    -- arguments, or domains (no deep subsumption).
    --
    -- allowUniverseCumulativity is similarly restricted to the outer
    -- classifier boundary. §16.1.4 forbids recursively treating the
    -- components of a composite type as cumulative.
    goAt fuel _ _ _ _ _ | fuel <= 0 = pure False
    goAt fuel allowQSubsumption allowUniverseCumulativity lvl a b =
      -- Compare a common global head before delta-unfolding it. Reducible
      -- recursive declarations applied to neutral arguments unfold to stuck
      -- matches whose recursive branches reproduce the same application;
      -- forcing first therefore loses the finite structural proof and burns
      -- the conversion fuel. The pure converter has the same pre-force rule.
      -- This monadic form additionally reconciles the hidden universe spine,
      -- which the pure converter cannot do while those levels are still metas.
      case (a, b) of
        -- Two first-class level values denote solver identities.  Fresh
        -- declaration instantiations can therefore use different metas for
        -- the same level; reconcile them through the exact level relation
        -- before using the term-to-level admissibility bridge below.
        (VLevel left, VLevel right) -> solveLevelIdentity ctx left right
        -- Do not force the ordinary first-class side before crossing the
        -- TypeLevel/solver bridge.  In the defining module an opaque level
        -- function is temporarily conversion-reducible; forcing it here
        -- exposes its implementation and gives it a different neutral atom
        -- from the stable application recorded in the dependent type.  The
        -- admissibility checkpoint performs the permitted transparent
        -- normalization with opaque definitions sealed.
        (VLevel left, right) -> typeLevelIdentityMatches lvl left right
        (left, VLevel right) -> typeLevelIdentityMatches lvl right left
        -- Solve a bare inference variable from the typed semantic value
        -- before delta/iota forcing the concrete side.  Forcing first can
        -- replace a stable declared endpoint such as @xs ++ Nil@ by its open
        -- recursive match normal form; dependent consumers then retain that
        -- implementation shape and no longer agree with the declaration's
        -- own interface.  Applied flexes still use the guarded decomposition
        -- below, and first-class levels have already crossed their
        -- authenticated identity bridge above.
        (VFlex meta [], value) -> solveFlex (fuel - 1) lvl meta value
        (value, VFlex meta []) -> solveFlex (fuel - 1) lvl meta value
        (VGlobI g1 universes1 spine1, VGlobI g2 universes2 spine2)
          | g1 == g2
          , length spine1 == length spine2 -> do
              typeLevelRelationIdentitiesMatch fuel lvl a b >>= \case
                Just True -> pure True
                _ -> do
                  st0 <- get
                  normalizedUniverses1 <- normalizeProvisionalUniverseOccurrence g1 universes1
                  normalizedUniverses2 <- normalizeProvisionalUniverseOccurrence g2 universes2
                  universeOk <-
                    if length normalizedUniverses1 /= length normalizedUniverses2
                      then pure False
                      else
                        andM
                          [ solveLevelIdentity ctx universe1 universe2
                          | (universe1, universe2) <- zip normalizedUniverses1 normalizedUniverses2
                          ]
                  relevant <-
                    if universeOk
                      then
                        globalSpineRelevantDomains
                          g1
                          normalizedUniverses1
                          spine1
                          spine2
                      else pure Nothing
                  spineOk <- case relevant of
                    Just arguments ->
                      andM
                        [ compareRelevantArgument
                            (fuel - 1)
                            lvl
                            domain
                            argument1
                            argument2
                        | (domain, argument1, argument2) <- arguments
                        ]
                    Nothing -> pure False
                  if spineOk
                    then pure True
                    else do
                      put st0
                      forceAndCompare
        _ -> forceAndCompare
      where
        forceAndCompare = do
          a' <- forceM a
          b' <- forceM b
          go fuel allowQSubsumption allowUniverseCumulativity lvl a' b'
        andM [] = pure True
        andM (action : actions) =
          action >>= \ok -> if ok then andM actions else pure False
    go fuel _ _ _ _ _ | fuel <= 0 = pure False
    go fuel allowQSubsumption allowUniverseCumulativity lvl a b = case (a, b) of
      (VFlex m [], t) -> solveFlex (fuel - 1) lvl m t
      (t, VFlex m []) -> solveFlex (fuel - 1) lvl m t
      -- applied metas: first-order decomposition (?m a̅ ≡ G b̅ pre a̅'
      -- solves ?m := G b̅ pre and unifies the argument tails pairwise) —
      -- the standard Miller-adjacent approximation for higher-kinded
      -- goals like ?f Int ≡ Option Int (§14.3.1)
      (VFlex m sp, t) | not (null sp) -> solveFlexSpine (fuel - 1) lvl m sp t
      (t, VFlex m sp) | not (null sp) -> solveFlexSpine (fuel - 1) lvl m sp t
      (VSort m, VSort n) ->
        if allowUniverseCumulativity
          then solveLevelInequality ctx m n
          else solveLevelIdentity ctx m n
      (VLevel left, VLevel right) -> solveLevelIdentity ctx left right
      -- Dependent application substitutes a checked TypeLevel argument by
      -- its canonical solver identity in level positions, while ordinary
      -- proposition terms still contain the original first-class value.
      -- Reconcile those two views through the same admissibility checkpoint
      -- used by `Type e`; opaque values remain rigid neutral atoms.
      (VLevel left, right) -> typeLevelIdentityMatches lvl left right
      (left, VLevel right) -> typeLevelIdentityMatches lvl right left
      (VPiM mode1 i1 q1 _ _ d1 c1, VPiM mode2 i2 q2 _ _ d2 c2)
        | mode1 == mode2 || (allowQSubsumption && observationModeSubsumes mode1 mode2)
        , i1 == i2
        , q1 == q2 || (allowQSubsumption && qSubsumes q1 q2) -> do
        -- Function subsumption is contravariant in the domain. Checking the
        -- domains covariantly accepted an implementation quantified only over
        -- @Type0@ where the expected function quantified over @Type u@; the
        -- occurrence level was then correctly minimized to zero and the Core
        -- body no longer had its declared type.
        ok <- goAt (fuel - 1) False False lvl d2 d1
        if not ok
          then pure False
          else do
            let x = VRigid lvl []
            b1 <- clApp c1 x
            b2 <- clApp c2 x
            goAt (fuel - 1) allowQSubsumption False (lvl + 1) b1 b2
      -- Compare checked lambda bodies in the monadic converter rather than
      -- delegating them to the pure fallback. Declaration specialization can
      -- instantiate the same polymorphic lambda twice with distinct level
      -- metas; only this converter can reconcile those identities while
      -- comparing the bodies extensionally.
      (VLamM mode1 i1 q1 _ c1, VLamM mode2 i2 q2 _ c2)
        | mode1 == mode2
        , i1 == i2
        , q1 == q2 -> do
            let x = VRigid lvl []
            b1 <- clApp c1 x
            b2 <- clApp c2 x
            goAt (fuel - 1) False False (lvl + 1) b1 b2
      (VRecordTQ f1, VRecordTQ f2)
        | map rfName f1 == map rfName f2
        , map rfMode f1 == map rfMode f2
        , map rfQ f1 == map rfQ f2 ->
            andM
              [ goAt (fuel - 1) False False lvl (rfType x) (rfType y)
              | (x, y) <- zip f1 f2
              ]
      -- §11.3.1A: an open record type meets a closed record type by
      -- matching the explicit prefix against the closed fields and
      -- instantiating the row tail with the leftover fields as a
      -- closed residual row
      (VGlobN (GName pm "__openRec") [(_, rowV), (_, prefixV)], VRecordT fs)
        | pm == preludeModule -> goOpenClosed (fuel - 1) lvl rowV prefixV fs
      (VRecordT fs, VGlobN (GName pm "__openRec") [(_, rowV), (_, prefixV)])
        | pm == preludeModule -> goOpenClosed (fuel - 1) lvl rowV prefixV fs
      -- §13.2.10: signature types are equal iff the opaque label sets
      -- and the underlying record types agree
      (VSigT l1 v1, VSigT l2 v2)
        | l1 == l2 -> goAt (fuel - 1) False False lvl v1 v2
      -- §13.2.10: seal is pure and non-generative (seal e as S ≡ e)
      (VSealV _ x, t) ->
        goAt (fuel - 1) allowQSubsumption allowUniverseCumulativity lvl x t
      (t, VSealV _ x) ->
        goAt (fuel - 1) allowQSubsumption allowUniverseCumulativity lvl t x
      (VVariantT m1, VVariantT m2) | length m1 == length m2 ->
        andM (zipWith (goAt (fuel - 1) False False lvl) m1 m2)
      -- A saturated nullary constructor can survive interface construction
      -- either as its declared neutral head or as the typed constructor node
      -- produced by ordinary term elaboration. Constructor-table membership,
      -- not spelling, authenticates the equivalence; requiring an empty term
      -- spine on both forms keeps constructor functions out of this rule.
      (VGlobI g1 universes1 [], VCtorI g2 universes2 [])
        | g1 == g2 -> declaredNullaryConstructor g1 universes1 universes2
      (VCtorI g1 universes1 [], VGlobI g2 universes2 [])
        | g1 == g2 -> declaredNullaryConstructor g1 universes1 universes2
      (VCtor g1 a1, VCtor g2 a2) | g1 == g2 && length a1 == length a2 ->
        andM (zipWith (goAt (fuel - 1) False False lvl) a1 a2)
      (VLit (LitInt n), VCtor g args)
        | g == prelNatZero -> pure (n == 0 && null args)
        | g == prelNatSucc
        , n > 0
        , [predecessor] <- args ->
            goAt (fuel - 1) False False lvl (VLit (LitInt (n - 1))) predecessor
      (VCtor g args, VLit (LitInt n))
        | g == prelNatZero -> pure (n == 0 && null args)
        | g == prelNatSucc
        , n > 0
        , [predecessor] <- args ->
            goAt (fuel - 1) False False lvl predecessor (VLit (LitInt (n - 1)))
      -- A reducible recursive definition applied to a neutral scrutinee
      -- evaluates to a stuck match. Compare those eliminators in the
      -- checker, rather than delegating to pure conversion, so hidden
      -- universe instances inside their branch bodies are reconciled by
      -- 'solveLevelIdentity'. Guarded neutral matches remain conservative:
      -- a stuck guard has no branch-refinement equation to justify reducing
      -- either body.
      (VMatchN s1 _ _ alts1 env1, VMatchN s2 _ _ alts2 env2)
        | length alts1 == length alts2
        , all (isNothing . caGuard) alts1
        , all (isNothing . caGuard) alts2 -> do
            scrutineeOk <- goAt (fuel - 1) False False lvl s1 s2
            if not scrutineeOk
              then pure False
              else do
                ec <- ec_
                andM
                  [ do
                      patternOk <- unifyCorePat pat1 pat2
                      if not patternOk
                        then pure False
                        else
                          let binderCount = patBindersC pat1
                              binders = [VRigid (lvl + i) [] | i <- [0 .. binderCount - 1]]
                              branchEnv1 = reverse binders ++ env1
                              branchEnv2 = reverse binders ++ env2
                              branchCtx scrutinee pattern' =
                                case (scrutinee, patternFact pattern' binders) of
                                  (VRigid rigid [], Just fact) ->
                                    ec {ecFacts = Map.insert rigid fact (ecFacts ec)}
                                  _ -> ec
                           in goAt
                                (fuel - 1)
                                False
                                False
                                (lvl + binderCount)
                                (eval (branchCtx s1 pat1) branchEnv1 body1)
                                (eval (branchCtx s2 pat2) branchEnv2 body2)
                  | (CaseAlt pat1 _ body1, CaseAlt pat2 _ body2) <- zip alts1 alts2
                  ]
      (VGlobI g1 universes1 sp1, VGlobI g2 universes2 sp2)
        | g1 == g2
        , length sp1 == length sp2 -> do
            st0 <- get
            ec <- ec_
            normalizedUniverses1 <- normalizeProvisionalUniverseOccurrence g1 universes1
            normalizedUniverses2 <- normalizeProvisionalUniverseOccurrence g2 universes2
            universeOk <-
              if length normalizedUniverses1 /= length normalizedUniverses2
                then pure False
                else
                  andM
                    [ solveLevelIdentity ctx universe1 universe2
                    | (universe1, universe2) <- zip normalizedUniverses1 normalizedUniverses2
                    ]
            ok <-
              case globalSpineRelevantPairs ec g1 sp1 sp2 of
                Just relevant | universeOk ->
                  andM
                    [ goAt (fuel - 1) False False lvl left right
                    | (left, right) <- relevant
                    ]
                _ -> pure False
            if ok then pure True else put st0 >> fallback lvl a b
      -- rigid-rigid spine decomposition (incomplete but standard; the
      -- definitional-equality fallback still decides the rest)
      (VRigid l1 sp1, VRigid l2 sp2)
        | l1 == l2 && length sp1 == length sp2 && not (null sp1) -> do
            st0 <- get
            ok <-
              andM
                (zipWith
                   (\(_, x) (_, y) -> goAt (fuel - 1) False False lvl x y)
                   sp1
                   sp2)
            if ok then pure True else put st0 >> fallback lvl a b
      -- Typed neutral applications retain their application node instead of
      -- folding the argument into the neutral head's spine. Decompose them in
      -- the monadic unifier so metas below a matching application head remain
      -- solvable (for example @d.Ref ?A@ against @d.Ref (Option ?B)@).
      -- Restore all tentative solutions if either half fails.
      (VAppN icit1 function1 argument1, VAppN icit2 function2 argument2)
        | icit1 == icit2 -> do
            typeLevelRelationIdentitiesMatch fuel lvl a b >>= \case
              Just True -> pure True
              _ -> do
                st0 <- get
                functionOk <- goAt (fuel - 1) False False lvl function1 function2
                argumentOk <-
                  if functionOk
                    then goAt (fuel - 1) False False lvl argument1 argument2
                    else pure False
                if argumentOk then pure True else put st0 >> fallback lvl a b
      -- Associated-type projections are neutral eliminators whose receiver
      -- identity is semantically relevant. The pure fallback cannot solve a
      -- flexible receiver, so decompose matching projections here and let
      -- unification reconcile (for example) @?d.Ref A@ with @d.Ref A@.
      (VProjN mode1 receiver1 field1, VProjN mode2 receiver2 field2)
        | mode1 == mode2
        , field1 == field2 ->
            goAt (fuel - 1) False False lvl receiver1 receiver2
      _ -> fallback lvl a b
      where
        andM [] = pure True
        andM (m : ms) = m >>= \ok -> if ok then andM ms else pure False
        declaredNullaryConstructor constructor leftUniverses rightUniverses = do
          known <- gets (Map.member constructor . csCtors)
          if not known || length leftUniverses /= length rightUniverses
            then pure False
            else
              andM
                [ solveLevelIdentity ctx left right
                | (left, right) <- zip leftUniverses rightUniverses
                ]
        unifyCorePat left right = case (left, right) of
          (CPWild, CPWild) -> pure True
          (CPVarM leftMode _, CPVarM rightMode _) -> pure (leftMode == rightMode)
          (CPLit leftLiteral, CPLit rightLiteral) -> pure (leftLiteral == rightLiteral)
          ( CPCtorM leftExistentials leftBridges leftHidden leftConstructor leftUniverses leftFields
            , CPCtorM rightExistentials rightBridges rightHidden rightConstructor rightUniverses rightFields
            )
              | leftExistentials == rightExistentials
              , leftBridges == rightBridges
              , leftHidden == rightHidden
              , leftConstructor == rightConstructor
              , length leftUniverses == length rightUniverses
              , length leftFields == length rightFields -> do
                  universesOk <-
                    andM
                      [ solveLevelIdentity ctx leftUniverse rightUniverse
                      | (leftUniverse, rightUniverse) <- zip leftUniverses rightUniverses
                      ]
                  if universesOk
                    then andM (zipWith unifyCorePat leftFields rightFields)
                    else pure False
          (CPTuple leftFields, CPTuple rightFields)
            | length leftFields == length rightFields ->
                andM (zipWith unifyCorePat leftFields rightFields)
          (CPRecordM leftFields leftRest, CPRecordM rightFields rightRest)
            | map fst leftFields == map fst rightFields
            , fmap fst leftRest == fmap fst rightRest
            , length leftFields == length rightFields ->
                andM (zipWith unifyCorePat (map snd leftFields) (map snd rightFields))
          (CPInject leftTag leftField, CPInject rightTag rightField)
            | leftTag == rightTag -> unifyCorePat leftField rightField
          (CPInjectRestM leftMode leftTags, CPInjectRestM rightMode rightTags) ->
            pure (leftMode == rightMode && leftTags == rightTags)
          (CPOr leftPatterns leftPermutations, CPOr rightPatterns rightPermutations)
            | leftPermutations == rightPermutations
            , length leftPatterns == length rightPatterns ->
                andM (zipWith unifyCorePat leftPatterns rightPatterns)
          (CPAsM leftMode _ leftPattern, CPAsM rightMode _ rightPattern)
            | leftMode == rightMode -> unifyCorePat leftPattern rightPattern
          _ -> pure False
        patternFact pattern' binders = case pattern' of
          CPCtorM existentialModes bridges hidden constructor _ fields
            | all plainPatternBinder fields ->
                let sourceBinders =
                      drop
                        (length existentialModes + constructorBridgeBinderCount bridges)
                        binders
                    sourceSlots =
                      interleaveConstructorSourceBinders hidden fields
                 in do
                      slots <- sourceSlots
                      guard (length slots == length sourceBinders)
                      let runtimeFields =
                            [ value
                            | (Right _, value) <- zip slots sourceBinders
                            ]
                      guard (length runtimeFields == length fields)
                      pure (FactIs (VCtor constructor runtimeFields))
          _ -> Nothing
    -- split closed fields fs into the open record's explicit prefix
    -- and a '__closedRow' residual solving the row tail (§11.3.1A)
    goOpenClosed fuel lvl rowV prefixV fs = do
      pf <- forceM prefixV
      case pf of
        VRecordT pfs
          | all ((`elem` map fst fs) . fst) pfs -> do
              okTys <-
                andAll
                  [ goAt fuel False False lvl pv fv
                  | (pl, pv) <- pfs
                  , Just fv <- [lookup pl fs]
                  ]
              if not okTys
                then pure False
                else do
                  let rest = [f | f@(l, _) <- fs, l `notElem` map fst pfs]
                  goAt
                    fuel
                    False
                    False
                    lvl
                    rowV
                    (VGlobN prelClosedRow [(Expl, VRecordT rest)])
        _ -> fallback lvl (VGlobN prelOpenRec [(Expl, rowV), (Expl, prefixV)]) (VRecordT fs)
      where
        andAll [] = pure True
        andAll (m : ms) = m >>= \ok -> if ok then andAll ms else pure False
    fallback lvl a b = do
      ec <- ec_
      pure (convertible ec lvl a b)
    -- Recover the checked domain of every semantically relevant global
    -- argument from the declaration telescope. Generated universe-proof
    -- witnesses are still applied to reach later dependent domains, but are
    -- omitted from the returned suffix exactly as in
    -- 'globalSpineRelevantPairs'. This is classifier authority for specialized
    -- comparisons; argument source shape and spelling play no role.
    globalSpineRelevantDomains global universes left right = do
      definitions <- gets csGlobals
      ec <- ec_
      case
          ( Map.lookup global definitions
          , globalSpineRelevantPairs ec global left right
          ) of
        (Just definition, Just relevant) -> do
          (_, globalTypeValue) <-
            specializeGlobalAt ctx global definition universes
          allArguments <- collectDomains globalTypeValue (zip left right)
          pure $ do
            arguments <- allArguments
            guard (length relevant <= length arguments)
            pure (drop (length arguments - length relevant) arguments)
        _ -> pure Nothing
      where
        collectDomains _ [] = pure (Just [])
        collectDomains typeValue (((leftIcit, leftValue), (rightIcit, rightValue)) : rest)
          | leftIcit /= rightIcit = pure Nothing
          | otherwise = do
              typeValue' <- forceM typeValue
              case typeValue' of
                VPiM _ binderIcit _ _ _ domain closure
                  | binderIcit == leftIcit -> do
                      codomain <- clApp closure leftValue
                      remaining <- collectDomains codomain rest
                      pure (((domain, leftValue, rightValue) :) <$> remaining)
                _ -> pure Nothing

    compareRelevantArgument remainingFuel depth domain left right = do
      levelDomain <- isTypeLevelValue domain
      if not levelDomain
        then goAt remainingFuel False False depth left right
        else
          typeLevelValuesEqualAt ctx depth left right >>= \case
            Just result -> pure result
            Nothing -> goAt remainingFuel False False depth left right

    typeLevelIdentityMatches lvl expectedIdentity value
      | lvl /= ctxLen ctx = pure False
      | otherwise = do
          tryQuoteIn ctx value >>= \case
            Nothing -> pure False
            Just term -> do
              (_, identity) <- levelIdentityOfCheckedTerm ctx term
              pure $ case identity of
                Right actualIdentity ->
                  normalizeLevel actualIdentity == normalizeLevel expectedIdentity
                Left _ -> False
    -- A dependent TypeLevel application retains the original first-class
    -- term in Core while its closure receives the canonical solver identity.
    -- Comparing only the ordinary application spines can therefore meet
    -- @f x@ on one side and @VLevel (neutral f x)@ on the other. Authenticate
    -- the complete standard comparison first, then reconcile its endpoints
    -- in the solver view. This is representation coherence, not a new
    -- proposition rule: user operators and nonstandard dictionaries never
    -- enter this path, and distinct rigid atoms still fail.
    typeLevelRelationIdentitiesMatch _ lvl left right
      | lvl /= ctxLen ctx = pure Nothing
      | otherwise = do
          saved <- get
          quoted <- (,) <$> tryQuoteIn ctx left <*> tryQuoteIn ctx right
          case quoted of
            (Just leftTerm, Just rightTerm)
              | containsCanonicalLevel leftTerm || containsCanonicalLevel rightTerm -> do
                  leftRelation <- typeLevelRelationOf ctx leftTerm
                  rightRelation <- typeLevelRelationOf ctx rightTerm
                  put saved
                  case (leftRelation, rightRelation) of
                    ( Just (leftOperator, leftLo, leftHi)
                      , Just (rightOperator, rightLo, rightHi)
                      )
                        | leftOperator == rightOperator -> do
                            lowerOk <- solveLevelIdentity ctx leftLo rightLo
                            upperOk <-
                              if lowerOk
                                then solveLevelIdentity ctx leftHi rightHi
                                else pure False
                            if upperOk
                              then pure (Just True)
                              else put saved >> pure (Just False)
                    _ -> pure Nothing
            _ -> put saved >> pure Nothing
      where
        containsCanonicalLevel =
          getAny
            . foldTerm
                (\case
                   CLevel {} -> Any True
                   _ -> Any False)
                (const mempty)
    solveFlexSpine fuel lvl m sp t = case t of
      VGlobI g universes sp2
        | length sp2 >= length sp -> do
            st0 <- get
            let (pre, post) = splitAt (length sp2 - length sp) sp2
            ok <- solveFlex fuel lvl m (VGlobI g universes pre)
            oks <-
              if ok
                then
                  andM'
                    [ goAt fuel False False lvl x y
                    | ((_, x), (_, y)) <- zip sp post
                    ]
                else pure False
            if oks then pure True else put st0 >> fallback lvl (VFlex m sp) t
      VRigid l sp2
        | length sp2 >= length sp -> do
            st0 <- get
            let (pre, post) = splitAt (length sp2 - length sp) sp2
            ok <- solveFlex fuel lvl m (VRigid l pre)
            oks <-
              if ok
                then
                  andM'
                    [ goAt fuel False False lvl x y
                    | ((_, x), (_, y)) <- zip sp post
                    ]
                else pure False
            if oks then pure True else put st0 >> fallback lvl (VFlex m sp) t
      VFlex m2 sp2
        | length sp2 == length sp -> do
            st0 <- get
            ok <- solveFlex fuel lvl m (VFlex m2 [])
            oks <-
              if ok
                then
                  andM'
                    [ goAt fuel False False lvl x y
                    | ((_, x), (_, y)) <- zip sp sp2
                    ]
                else pure False
            if oks then pure True else put st0 >> fallback lvl (VFlex m sp) t
      _
        | Just argumentMetas <- freshPlanningSpine sp -> do
            -- Checked application planning represents not-yet-elaborated
            -- explicit arguments by distinct classifier-authenticated metas.
            -- A result equation such as @?m ?argument = Nat@ has the principal
            -- pattern solution @?m := \_ -> Nat@ when the target is
            -- independent of every argument placeholder. Arbitrary flexes,
            -- ambient metas, repeated placeholders, and dependent targets
            -- remain outside this bounded rule and use ordinary conversion.
            solveConstantPlanningSpine argumentMetas >>= \case
              True -> pure True
              False -> fallback lvl (VFlex m sp) t
        | Just argumentLevels <- rigidPatternSpine sp -> do
            -- Ordinary higher-order pattern unification also admits the
            -- constant-family case @?family x = target@ when every argument
            -- is a distinct rigid introduced after the meta and @target@ is
            -- scoped before those rigids. This is what lets a constant type
            -- @B@ instantiate a dependent family expected as @A -> Type@.
            -- The classifier still supplies every Pi mode/icit/quantity;
            -- source spelling and the target's head are irrelevant.
            solveConstantRigidSpine argumentLevels >>= \case
              True -> pure True
              False -> fallback lvl (VFlex m sp) t
      _ -> fallback lvl (VFlex m sp) t
      where
        andM' [] = pure True
        andM' (mx : ms) = mx >>= \ok -> if ok then andM' ms else pure False

        freshPlanningSpine arguments = do
          metas <- traverse bareFlex arguments
          if length metas == Set.size (Set.fromList metas)
            then Just metas
            else Nothing

        bareFlex (_, VFlex meta []) = Just meta
        bareFlex _ = Nothing

        rigidPatternSpine arguments = do
          levels <- traverse bareRigid arguments
          if length levels == Set.size (Set.fromList levels)
            then Just levels
            else Nothing

        bareRigid (_, VRigid level []) = Just level
        bareRigid _ = Nothing

        solveConstantPlanningSpine argumentMetas = do
          state <- get
          case Map.lookup m (csMetaClassifiers state) of
            Just classifier
              | micDepth classifier == ctxLen ctx
              , all (`Set.member` csApplicationPlanningMetas state) argumentMetas -> do
                  case t of
                    -- A stuck semantic match retains its branch environment
                    -- separately from the Core alternatives. Reconstructing a
                    -- lambda body from it requires closure conversion, not the
                    -- bounded syntactic planning rule below. Ordinary semantic
                    -- unification remains the conservative authority.
                    VMatchN {} -> pure False
                    _ -> do
                      targetTerm <- quoteIn ctx t
                      let targetMetas =
                            Set.fromList (unsolvedMetasOf state targetTerm)
                      if any (`Set.member` targetMetas) argumentMetas
                        then pure False
                        else do
                          classifierValue <- evalIn ctx (micType classifier)
                          buildConstantLambda classifierValue sp targetTerm >>= \case
                            Nothing -> pure False
                            Just candidate -> solveMetaAcyclic m candidate
            _ -> pure False

        solveConstantRigidSpine argumentLevels = do
          state <- get
          case Map.lookup m (csMetaClassifiers state) of
            Just classifier
              | let creationDepth = micDepth classifier
              , creationDepth == ctxLen ctx
              , all (>= creationDepth) argumentLevels -> do
                  targetTerm <- quoteIn ctx t
                  if not (termScopedAt creationDepth targetTerm)
                    then pure False
                    else do
                      classifierValue <- evalIn ctx (micType classifier)
                      buildConstantLambda classifierValue sp targetTerm >>= \case
                        Nothing -> pure False
                        Just candidate -> solveMetaAcyclic m candidate
            _ -> pure False

        buildConstantLambda classifier arguments targetTerm =
          go classifier arguments []
          where
            go _ [] binders = do
              let body = shiftTerm (length binders) 0 targetTerm
                  lambda =
                    foldr
                      (\(mode, icit, quantity, name) inner ->
                         CLamM mode icit quantity name inner)
                      body
                      binders
              Just <$> evalIn ctx lambda
            go classifierValue ((argumentIcit, _) : rest) binders =
              forceM classifierValue >>= \case
                VPiEvidenceM mode _ icit quantity _ name _ _ _ closure
                  | icit == argumentIcit -> do
                      let rigid = VRigid (ctxLen ctx + length binders) []
                      codomain <- clApp closure rigid
                      go
                        codomain
                        rest
                        (binders ++ [(mode, icit, quantity, name)])
                _ -> pure Nothing
    solveFlex fuel lvl m t = do
      st <- get
      case Map.lookup m (csMetas st) of
        Just (Just sol) -> do
          sol' <- forceM sol
          t' <- forceM t
          go fuel False False lvl sol' t'
        _ -> do
          -- The other flex may already be solved to this one. Dereference that
          -- indirection before the occurs check so definitional equality stays
          -- reflexive without forcing concrete global heads.
          target <- forceM t
          case target of
            VFlex m' [] | m' == m -> pure True
            _ -> solvePendingMetaAcyclic m target
      where
        -- A postponed evidence placeholder can be constrained indirectly by
        -- a later dependent argument.  Associated-member unification is the
        -- important case: @?d.Ref A@ against @d.Ref A@ reaches the receivers
        -- and proposes @?d := d@ before the pending evidence ladder runs.
        --
        -- Such a proposal is valid only when the candidate inhabits the
        -- exact checked goal captured for @?d@.  Solving the term meta without
        -- this check used to bypass hidden-universe identity, leaving a
        -- lower-capacity dictionary in Core while a member occurrence used a
        -- higher universe.  Validate transactionally so a rejected candidate
        -- cannot leak either term-meta solutions or level constraints.
        solvePendingMetaAcyclic meta candidate = do
          pending <-
            gets
              ( listToMaybe
                  . filter
                    (\(pendingMeta, _, _, pendingCtx, _) ->
                       pendingMeta == meta
                         && ctxLen pendingCtx == ctxLen ctx
                    )
                  . csPending
              )
          case pending of
            Nothing -> solveMetaAcyclic meta candidate
            Just (_, goal, _, pendingCtx, _) -> do
              saved <- get
              candidateType <- equandType pendingCtx candidate
              checked <- case candidateType of
                Nothing -> pure False
                Just actualType ->
                  unifyDefinitional pendingCtx actualType goal
              solved <-
                if checked
                  then solveMetaAcyclic meta candidate
                  else pure False
              if solved
                then pure True
                else put saved >> pure False

metaOccursInValue :: Map MetaId (Maybe Value) -> MetaId -> Value -> Bool
metaOccursInValue metas = metaOccursInValueSeen metas metaOccursFuel Set.empty

metaOccursFuel :: Int
metaOccursFuel = 4096

metaOccursInValueSeen :: Map MetaId (Maybe Value) -> Int -> Set MetaId -> MetaId -> Value -> Bool
metaOccursInValueSeen metas fuel0 seen0 target = goV fuel0 seen0
  where
    next n = n - 1

    exhausted n = n <= 0

    -- Direct meta solving is a shortcut.  If the finite occurs-check budget is
    -- exhausted, fail closed by reporting "may occur"; callers then use the
    -- ordinary unifier instead of installing a possibly cyclic solution.  This
    -- keeps the occurs check from recursively chasing large closure graphs or
    -- recursive standard-library values while preserving soundness.
    goSp n seen
      | exhausted n = const True
      | otherwise = any (goV (next n) seen . snd)

    goClosure boundCount n seen (Closure env body)
      | exhausted n = True
      | otherwise =
          metaOccursInTerm metas (next n) seen target body
            || goReachableEnvironment n seen env [(boundCount, body)]

    -- A semantic closure captures the complete evaluator environment, not
    -- merely the values its body references.  An occurs check must follow
    -- only reachable de Bruijn slots: scanning every captured value rejects
    -- acyclic solutions whenever an unrelated environment cell happens to
    -- contain the meta being solved.  Suspended do kernels are opaque to the
    -- depth-aware fold, so retain the conservative all-environment answer for
    -- those bodies rather than risking a missed cycle.
    goReachableEnvironment n seen env scopedTerms
      | any (termContainsDo . snd) scopedTerms = any (goV (next n) seen) env
      | otherwise = any reachable (nub (concatMap scopedEnvironmentIndices scopedTerms))
      where
        reachable index =
          case drop index env of
            value : _ -> goV (next n) seen value
            [] -> True

    scopedEnvironmentIndices (boundCount, term) =
      foldTermWithDepth occurrence boundCount term
      where
        occurrence depth = \case
          CVar index | index >= depth -> [index - depth]
          CLocal index _ | index >= depth -> [index - depth]
          _ -> []

    termContainsDo = getAny . foldTerm termNode (const mempty)
      where
        termNode = \case
          CDo {} -> Any True
          _ -> mempty

    goV n seen v
      | exhausted n = True
      | otherwise = case v of
      VRigid _ sp -> goSp n seen sp
      VFlex m sp ->
        m == target
          || goSp n seen sp
          || ( not (Set.member m seen)
                 && case Map.lookup m metas of
                   Just (Just sol) -> goV (next n) (Set.insert m seen) sol
                   _ -> False
             )
      VGlobN _ sp -> goSp n seen sp
      VLam _ _ _ clo -> goClosure 1 n seen clo
      VPi _ _ _ _ dom clo -> goV (next n) seen dom || goClosure 1 (next n) seen clo
      VSort _ -> False
      VLevel _ -> False
      VUniverseLift _ _ _ inner -> goV (next n) seen inner
      VLit _ -> False
      VCtor _ args -> any (goV (next n) seen) args
      VRecordT fs -> any (goV (next n) seen . snd) fs
      VRecordV fs -> any (goV (next n) seen . snd) fs
      VVariantT ms -> any (goV (next n) seen) ms
      VInject _ v' -> goV (next n) seen v'
      VMatchN scrut scrutineeAnnotation resultAnnotation alts env ->
        goV (next n) seen scrut
          || maybe False (goV (next n) seen) scrutineeAnnotation
          || maybe False (goV (next n) seen) resultAnnotation
          || any (goAlt (next n) seen) alts
          || goReachableEnvironment
               (next n)
               seen
               env
               [ (patBindersC pattern', term)
               | CaseAlt pattern' guardTerm body <- alts
               , term <- maybeToList guardTerm ++ [body]
               ]
      VProjN _ v' _ -> goV (next n) seen v'
      VAppN _ f a -> goV (next n) seen f || goV (next n) seen a
      VSealV _ v' -> goV (next n) seen v'
      VSigT _ v' -> goV (next n) seen v'
      VDoV _ items env -> any (goK (next n) seen) items || any (goV (next n) seen) env
      VThunkV clo -> goClosure 0 n seen clo
      VLazyV clo -> goClosure 0 n seen clo
      VIfN c t f ->
        goV (next n) seen c
          || goClosure 0 (next n) seen t
          || goClosure 0 (next n) seen f
      VArithmeticProof certificate ->
        any (goV (next n) seen) (foldMapArithmeticCertificate (: []) certificate)
      VPrim _ args -> any (goV (next n) seen) args
      VRef _ -> False
      VArr _ _ -> False
      VMVar _ -> False
      VFiber _ _ -> False
      VScope _ -> False
      VFiberRef _ -> False
      VTVar _ -> False
      VIOAction _ args -> any (goV (next n) seen) args
      VQuote _ slots -> any (goV (next n) seen) slots

    goAlt n seen (CaseAlt _ gd body)
      | exhausted n = True
      | otherwise =
          maybe False (metaOccursInTerm metas (next n) seen target) gd
            || metaOccursInTerm metas (next n) seen target body

    goK n seen
      | exhausted n = const True
      | otherwise = \case
      KBind _ _ t _ -> metaOccursInTerm metas (next n) seen target t
      KLet _ _ t -> metaOccursInTerm metas (next n) seen target t
      KLetQ _ t m -> metaOccursInTerm metas (next n) seen target t || maybe False (metaOccursInTerm metas (next n) seen target . snd) m
      KExpr t -> metaOccursInTerm metas (next n) seen target t
      KVarItem _ initT actT _ -> metaOccursInTerm metas (next n) seen target initT || metaOccursInTerm metas (next n) seen target actT
      KAssign lhs _ rhs actT _ ->
        metaOccursInTerm metas (next n) seen target lhs
          || metaOccursInTerm metas (next n) seen target rhs
          || metaOccursInTerm metas (next n) seen target actT
      KReturn t -> metaOccursInTerm metas (next n) seen target t
      KBreak _ -> False
      KContinue _ -> False
      KWhile _ c b e ->
        metaOccursInTerm metas (next n) seen target (kCondTerm c)
          || any (goK (next n) seen) b
          || maybe False (any (goK (next n) seen)) e
      KFor _ _ src b e ->
        metaOccursInTerm metas (next n) seen target src
          || any (goK (next n) seen) b
          || maybe False (any (goK (next n) seen)) e
      KIf alts e ->
        any
          (\(c, b) ->
             metaOccursInTerm metas (next n) seen target c
               || any (goK (next n) seen) b)
          alts
          || maybe False (any (goK (next n) seen)) e
      KDefer _ t -> metaOccursInTerm metas (next n) seen target t
      KUsing _ acquire release ->
        metaOccursInTerm metas (next n) seen target acquire
          || metaOccursInTerm metas (next n) seen target release
      KSubDo _ items -> any (goK (next n) seen) items

metaOccursInTerm :: Map MetaId (Maybe Value) -> Int -> Set MetaId -> MetaId -> Term -> Bool
metaOccursInTerm metas fuel0 seen target = go fuel0
  where
    next n = n - 1
    exhausted n = n <= 0

    goK n
      | exhausted n = const True
      | otherwise = \case
      KBind _ _ t _ -> go (next n) t
      KLet _ _ t -> go (next n) t
      KLetQ _ t m -> go (next n) t || maybe False (go (next n) . snd) m
      KExpr t -> go (next n) t
      KVarItem _ initT actT _ -> go (next n) initT || go (next n) actT
      KAssign lhs _ rhs actT _ -> go (next n) lhs || go (next n) rhs || go (next n) actT
      KReturn t -> go (next n) t
      KBreak _ -> False
      KContinue _ -> False
      KWhile _ c b e -> go (next n) (kCondTerm c) || any (goK (next n)) b || maybe False (any (goK (next n))) e
      KFor _ _ src b e -> go (next n) src || any (goK (next n)) b || maybe False (any (goK (next n))) e
      KIf alts e ->
        any (\(c, b) -> go (next n) c || any (goK (next n)) b) alts
          || maybe False (any (goK (next n))) e
      KDefer _ t -> go (next n) t
      KUsing _ acquire release -> go (next n) acquire || go (next n) release
      KSubDo _ items -> any (goK (next n)) items

    go n t
      | exhausted n = True
      | otherwise = case t of
      CMeta m ->
        m == target
          || ( not (Set.member m seen)
                 && case Map.lookup m metas of
                   Just (Just sol) -> metaOccursInValueSeen metas (next n) (Set.insert m seen) target sol
                   _ -> False
             )
      CApp _ f a -> go (next n) f || go (next n) a
      CLam _ _ _ b -> go (next n) b
      CPi _ _ _ _ a b -> go (next n) a || go (next n) b
      CCtor _ _ as -> any (go (next n)) as
      CMatch s _ _ alts -> go (next n) s || any (\(CaseAlt _ gd b) -> maybe False (go (next n)) gd || go (next n) b) alts
      CRecordT fs -> any (go (next n) . snd) fs
      CRecordV fs -> any (go (next n) . snd) fs
      CProj e _ -> go (next n) e
      CProjAt e _ _ -> go (next n) e
      CVariantT ms -> any (go (next n)) ms
      CInject _ e -> go (next n) e
      CLet _ _ a b c -> go (next n) a || go (next n) b || go (next n) c
      CLetRec _ _ a b c -> go (next n) a || go (next n) b || go (next n) c
      CIf a b c -> go (next n) a || go (next n) b || go (next n) c
      CThunkE e suspensionType ->
        go (next n) e || maybe False (go (next n)) suspensionType
      CLazyE e suspensionType ->
        go (next n) e || maybe False (go (next n)) suspensionType
      CForceE e resultType ->
        go (next n) e || maybe False (go (next n)) resultType
      CSealE _ e -> go (next n) e
      CSigT _ e -> go (next n) e
      CQuote _ slots -> any (go (next n)) slots
      CDo _ items -> any (goK (next n)) items
      _ -> False

-- | §3.1.9 expected/actual mismatch payload (the @kappa.type.mismatch@
-- family MUST expose it when both sides are available). The compact
-- rendered fragments are the user-facing renderings (already zonked and
-- metavar-hygienic, §3.1.11). The mismatch kind defaults to
-- @expression-type@ — the bare type-equality check shape (§3.1.9
-- ExpectedActualMismatchKind).
mismatchPayload :: Text -> Text -> Payload
mismatchPayload expectedR actualR =
  withPayloadField "expected" expectedR $
    withPayloadField "actual" actualR $
      withPayloadField "mismatchKind" "expression-type" $
        payloadKind "expected-actual"

-- | §18.1 effect-row subsumption (check direction): succeed when @actual@
-- and @expected@ are both Eff types whose result types unify and every
-- label in actual's row appears in expected's row with a unifiable
-- interface (so actual's effects ⊆ expected's). Restores state on failure.
tryEffRowSubsume :: Ctx -> Value -> Value -> CheckM Bool
tryEffRowSubsume ctx actual expected = do
  aF <- forceM actual
  eF <- forceM expected
  case (aF, eF) of
    (VGlobN ag [(_, aRow), (_, aRes)], VGlobN eg [(_, eRow), (_, eRes)])
      | ag == prelEff
      , eg == prelEff -> do
      st0 <- get
      resOk <- unify ctx aRes eRes
      aEs <- rowEntriesV aRow
      eEs <- rowEntriesV eRow
      case (aEs, eEs) of
        (Just aEntries, Just eEntries) | resOk -> do
          oks <- forM aEntries $ \(al, ai) -> do
            ms <- forM eEntries $ \(el, ei) -> do
              le <- sameLabelV al el
              if le then unify ctx ai ei else pure False
            pure (or ms)
          if and oks then pure True else put st0 >> pure False
        _ -> put st0 >> pure False
    _ -> pure False

-- | The (label, interface) entries of a fully-concrete effect row (ending
-- in @__effRowNil@); Nothing if the row has a non-cons tail (e.g. a
-- metavariable), where this subsumption does not apply.
rowEntriesV :: Value -> CheckM (Maybe [(Value, Value)])
rowEntriesV row0 = do
  row <- forceM row0
  case row of
    VGlobN (GName _ "__effRowNil") [] -> pure (Just [])
    VGlobN (GName _ "__effRowCons") [(_, l), (_, e), (_, rest)] -> do
      mrest <- rowEntriesV rest
      pure (fmap ((l, e) :) mrest)
    _ -> pure Nothing

sameLabelV :: Value -> Value -> CheckM Bool
sameLabelV a b = do
  aF <- forceM a
  bF <- forceM b
  pure $ case (aF, bF) of
    (VGlobN g1 [], VGlobN g2 []) -> g1 == g2
    (VCtor g1 [], VCtor g2 []) -> g1 == g2
    _ -> False

withUniverseDiagnosticSpan :: Span -> CheckM a -> CheckM a
withUniverseDiagnosticSpan source action = do
  previous <- gets csUniverseDiagnosticSpan
  modify' $ \state -> state {csUniverseDiagnosticSpan = Just source}
  result <- action
  modify' $ \state -> state {csUniverseDiagnosticSpan = previous}
  pure result

-- | Try the ordinary check-direction conversion without emitting a
-- diagnostic. A failed attempt is transactional: unification is allowed to
-- refine metas only when the complete conversion (including the two
-- check-direction subsumption rules) succeeds.
tryTypeCompatibility :: Ctx -> Span -> Value -> Value -> CheckM Bool
tryTypeCompatibility ctx sp actual expected = do
  before <- get
  exact <- gets csDefinitionalEqualityOnly
  ok <- withUniverseDiagnosticSpan sp $
    if exact then unifyDefinitional ctx actual expected else unify ctx actual expected
  -- §18.1: effect-row subsumption. A computation whose effect row's labels
  -- are a SUBSET of the expected row's (with matching interfaces) is usable
  -- where the larger row is demanded — it simply does not use the extra
  -- effects. This is what lets an operation `l.op` (natural row `<[l:E]>`)
  -- and any single-effect sub-computation compose inside a do-block whose
  -- row carries several effects. The OpCall tree is row-agnostic at runtime,
  -- so the relaxation is purely at the type level (sound in the check
  -- direction). Tried only after exact unification fails.
  subsumed <-
    if ok
      then pure True
      else if exact
        then pure False
        else do
          captureSubsumed <- tryCaptureSetSubsume ctx actual expected
          if captureSubsumed then pure True else tryEffRowSubsume ctx actual expected
  unless subsumed (put before)
  pure subsumed

reportRigidLevelConversionFailure
  :: Ctx
  -> Span
  -> Level
  -> Level
  -> CheckM ()
reportRigidLevelConversionFailure ctx sp lhs rhs = do
  assumptions <- effectiveLevelAssumptions ctx
  let origin = ConstraintOrigin "sort conversion" "type conversion"
      constraint = LevelConstraint (-1) lhs rhs origin assumptions
  owner <- gets csActiveUniverseDefinition
  reportLevelSolveErrorWithProvenance
    owner
    (Just sp)
    (LevelConstraintDisproved constraint)

-- | A first-class borrowed view cannot change its rigid region index while
-- being returned, stored, or passed. The exact prelude type identity is the
-- authority; unrelated same-shaped user families remain ordinary nominal
-- index mismatches.
borrowViewRegionMismatch
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe (Value, Value))
borrowViewRegionMismatch ctx actual expected = do
  actualView <- forceM actual
  expectedView <- forceM expected
  case (viewArguments actualView, viewArguments expectedView) of
    (Just (actualRegion, actualPayload), Just (expectedRegion, expectedPayload)) -> do
      payloadMatches <- captureRegionMatches ctx actualPayload expectedPayload
      regionMatches <- captureRegionMatches ctx actualRegion expectedRegion
      pure $
        if payloadMatches && not regionMatches
          then Just (actualRegion, expectedRegion)
          else Nothing
    _ -> pure Nothing
  where
    viewArguments = \case
      VGlobI global _ [(_, region), (_, payload)]
        | global == prelBorrowView -> Just (region, payload)
      VGlobN global [(_, region), (_, payload)]
        | global == prelBorrowView -> Just (region, payload)
      _ -> Nothing

reportBorrowViewRegionMismatch
  :: Ctx
  -> Span
  -> Value
  -> Value
  -> CheckM ()
reportBorrowViewRegionMismatch ctx site actualRegion expectedRegion = do
  actualTerm <- quoteIn ctx actualRegion >>= zonkTermM (ctxLen ctx)
  expectedTerm <- quoteIn ctx expectedRegion >>= zonkTermM (ctxLen ctx)
  let actualText = renderTerm actualTerm
      expectedText = renderTerm expectedTerm
      origin = rigidOrigin actualRegion
      withOrigin diagnostic =
        case origin of
          Just source | source /= noSpan ->
            withRelated
              (related RoleBorrowStart source "borrow region introduced here")
              diagnostic
          _ -> diagnostic
  report $
    withPayload
      ( withPayloadField "actualRegion" actualText $
          withPayloadField "expectedRegion" expectedText $
            payloadKind "borrow-escape"
      ) $
      withOrigin $
        withRelated
          (related RoleBorrowEscapeSite site "borrowed view would escape under a different region")
          ( diag SevError StageElaborate "E_QTT_BORROW_ESCAPE"
              (Just "kappa.borrow.escape") site
              "a first-class borrowed view cannot be retagged to an unrelated rigid region (§12.3, §12.4.3)"
          )
  where
    rigidOrigin region =
      case region of
        VRigid level [] ->
          ceOrigin
            <$> listToMaybe
              (drop (ctxLen ctx - level - 1) (ctxEntries ctx))
        _ -> Nothing

expectType :: Ctx -> Span -> Value -> Value -> CheckM ()
expectType ctx sp actual expected = do
  exact <- gets csDefinitionalEqualityOnly
  subsumed <- tryTypeCompatibility ctx sp actual expected
  diagnosedDependency <-
    if subsumed
      then pure False
      else conversionDependsOnDiagnosedEvidence ctx [actual, expected]
  unless (subsumed || diagnosedDependency) $ do
    borrowViewMismatch <-
      borrowViewRegionMismatch ctx actual expected
    captureMismatch <-
      if exact then pure Nothing else captureMismatchRegions ctx actual expected
    universeSelfContainment <- do
      actualF <- forceM actual
      expectedF <- forceM expected
      assignments <- gets csLevelAssignments
      pure $ case (actualF, expectedF) of
        (VSort actualLevel0, VSort expectedLevel0) ->
          let actualLevel =
                normalizeLevel
                  (substituteLevelMetas assignments actualLevel0)
              expectedLevel =
                normalizeLevel
                  (substituteLevelMetas assignments expectedLevel0)
           in actualLevel == levelSucc expectedLevel
        _ -> False
    rigidUniverseMismatch <-
      if exact
        then pure Nothing
        else do
          actualF <- forceM actual
          expectedF <- forceM expected
          case (actualF, expectedF) of
            (VSort actualLevel0, VSort expectedLevel0) -> do
              assignments <- gets csLevelAssignments
              let actualLevel =
                    normalizeLevel
                      (substituteLevelMetas assignments actualLevel0)
                  expectedLevel =
                    normalizeLevel
                      (substituteLevelMetas assignments expectedLevel0)
              assumptions <- effectiveLevelAssumptions ctx
              pure $ case proveLevelLeq assumptions actualLevel expectedLevel of
                Disproved -> Just (actualLevel, expectedLevel)
                _ -> Nothing
            _ -> pure Nothing
    aT <- quoteIn ctx actual
    eT <- quoteIn ctx expected
    -- §13.2.10: a mismatch whose head is an opaque sealed-package
    -- member is an attempt to unfold a hidden defining equation
    aOp <- opaqueSealHead actual
    eOp <- opaqueSealHead expected
    -- §16.1.8: at an application boundary, a same-head indexed type
    -- mismatch is a failed transport — an application-argument error
    retag <- gets csArgIndexRetag
    sameHead <- do
      aF <- forceM actual
      eF <- forceM expected
      pure $ case (aF, eF) of
        (VGlobN g1 sp1, VGlobN g2 sp2) ->
          g1 == g2 && not (null sp1) && length sp1 == length sp2
        _ -> False
    -- §16.1.7.1: a mismatch while checking an explicit argument is an
    -- application-argument error when both sides are canonical
    -- non-function types (the argument simply does not fit the
    -- parameter); same-head indexed mismatches additionally cite the
    -- failed transport (§16.1.8). The outer call classification is resolved
    -- before entering the argument and is preserved through nested checking:
    -- a constructor application remains the argument of its enclosing call.
    --
    -- The expected side must be a *nullary type former* (`VGlobN g []`):
    -- a saturated atomic type with no remaining indices. This is the
    -- §16.1.7.1 "argument does not satisfy the binder" shape. Structural
    -- record types (`VRecordT`) are deliberately excluded on the expected
    -- side: a record-into-record mismatch (e.g. passing a `RawDelayed`
    -- where a `Delayed` record is expected) is a §3.2.3 `kappa.type.mismatch`
    -- on structural type identity, not an argument-classifier failure — so
    -- it must keep its `E_TYPE_EQUALITY_MISMATCH` spelling. Widening this
    -- guard to admit records regresses that diagnostic, which is why the
    -- expected side is restricted to nullary `VGlobN` (any name, since the
    -- old fixed scalar-name list was not load-bearing).
    flatOk <- gets csArgFlatOk
    flatArgMismatch <- do
      if not retag || sameHead || not flatOk
        then pure False
        else do
          aF <- forceM actual
          eF <- forceM expected
          let canonical = \case
                VGlobN _ _ -> True
                VCtor _ _ -> True
                VRecordT _ -> True
                VSort _ -> True
                _ -> False
              nullaryExpected = case eF of
                VGlobN (GName _ _) [] -> True
                _ -> False
          pure (canonical aF && nullaryExpected)
    -- §16.1.7.1: a function value supplied at an explicit argument slot
    -- whose expected parameter type is itself a function type, where the
    -- two function types differ in the outermost explicit binder
    -- (quantity is part of function-type identity, §31.1/§12.2.1) — the
    -- argument simply does not fit the parameter, an
    -- application-argument error rather than a bare type equality.
    funcArgMismatch <- do
      if not retag || not flatOk
        then pure False
        else do
          aF <- forceM actual
          eF <- forceM expected
          pure $ case (aF, eF) of
            -- Any function value supplied to a function-typed argument slot
            -- is still an application mismatch when the checked Pi contracts
            -- disagree.  In particular an erased implicit @forall@ decider is
            -- not an ordinary explicit decision procedure; the binder icity
            -- difference is the reason the argument does not fit, not a
            -- free-standing type-equality failure (§11.3, §16.1.7.1).
            (VPi _ _ _ _ _ _, VPi _ _ _ _ _ _) -> True
            _ -> False
    let (inferredCaptures, demandedCaptures, missingCaptures) =
          fromMaybe ([], [], []) captureMismatch
    if isJust borrowViewMismatch
      then case borrowViewMismatch of
        Just (actualRegion, expectedRegion) ->
          reportBorrowViewRegionMismatch ctx sp actualRegion expectedRegion
        Nothing -> pure ()
      else if isJust captureMismatch
      then reportCaptureSetMismatch ctx sp inferredCaptures demandedCaptures missingCaptures
      else if universeSelfContainment
      then
        report $
          withPayload
            ( withPayloadField "rejectedConstraint" (renderTerm aT <> " <= " <> renderTerm eT) $
                withPayloadField "normalizedRejectedConstraint" (renderTerm aT <> " <= " <> renderTerm eT) $
                  withPayloadField "constraintOrigin" "sort conversion" $
                    withPayloadField "enclosingConstructKind" "type conversion" $
                      withPayloadField "universeVariablesInScope" "see normalized levels" $
                        withPayloadField "levelAssumptions" (renderLevelAssumptions (ctxLevelAssumptions ctx)) $
                          withPayloadField "selfContainment" "true" $
                            withPayloadField "failureKind" "cumulativity" $
                              withPayloadField "expectedUniverseCeiling" (renderTerm eT) $
                                withPayloadField "actualComponentUniverse" (renderTerm aT) $
                                  withPayloadField "sourceOrigin" (T.pack (show sp)) $
                                    payloadKind "universe-self-containment"
            ) $
              diag SevError StageElaborate "E_UNIVERSE_SELF_CONTAINMENT" (Just "kappa.universe.constraint") sp
                "a universe cannot inhabit itself; Type κ has classifier Type (succ κ) (§11.1.2)"
      else if isJust rigidUniverseMismatch
      then case rigidUniverseMismatch of
        Just (actualLevel, expectedLevel) ->
          reportRigidLevelConversionFailure ctx sp actualLevel expectedLevel
        Nothing -> pure ()
      else if not (aOp || eOp) && retag && sameHead
      then
        report $
          withNote ("expected: " <> renderTerm eT) $
            withNote ("actual:   " <> renderTerm aT) $
              diag SevError StageElaborate "E_APPLICATION_ARGUMENT_MISMATCH" (Just "kappa.application.argument-mismatch") sp
                "the supplied argument's type differs from the parameter type only in type indices, and no equality evidence licenses the transport (§16.1.8)"
      else if not (aOp || eOp) && (flatArgMismatch || funcArgMismatch)
        then
        report $
          withNote ("expected: " <> renderTerm eT) $
            withNote ("actual:   " <> renderTerm aT) $
              diag SevError StageElaborate "E_APPLICATION_ARGUMENT_MISMATCH" (Just "kappa.application.argument-mismatch") sp
                "the supplied argument's type does not match the parameter type (§16.1.7.1)"
      else if aOp || eOp
        then
        report $
          withNote ("expected: " <> renderTerm eT) $
            withNote ("actual:   " <> renderTerm aT) $
              diag SevError StageElaborate "E_SEAL_OPAQUE_UNFOLDING" (Just "kappa-hs.seal.opaque-unfolding") sp
                "an opaque member of a sealed package does not unfold to its hidden definition (§13.2.10)"
      else do
        -- §3.1.11: zonk before rendering so solved metavariables are
        -- substituted and only genuinely-unknown ones remain (those
        -- render as the stable hole `_`, never as a raw `?mN` solver id).
        aTz <- zonkTermM (ctxLen ctx) aT
        eTz <- zonkTermM (ctxLen ctx) eT
        -- §21: phase-boundary mismatches (a meta-phase 'Elab'/'Syntax'
        -- type against an object-phase one) carry the rendered types in
        -- the message itself, since the phase is the point
        let aR = renderTerm aTz
            eR = renderTerm eTz
            metaish r = "Elab" `T.isInfixOf` r || "Syntax" `T.isInfixOf` r
            msg =
              if (metaish aR || metaish eR) && aR /= eR
                then "type mismatch: expected '" <> eR <> "', actual '" <> aR <> "'"
                else "type mismatch"
        report $
          withPayload (mismatchPayload eR aR) $
            withRelated (related RoleUseSite sp ("this expression has type " <> aR)) $
              withNote ("expected: " <> eR) $
                withNote ("actual:   " <> aR) $
                  diag SevError StageElaborate "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch") sp
                    msg

-- | Is the value a §16.1.7.1 suspension type (Thunk/Need)?
isSuspV :: Value -> Bool
isSuspV = \case
  VGlobN global _ | global == prelThunk || global == prelNeed -> True
  _ -> False

-- | Strip §12.3.1 capture-annotation layers (elimination positions use
-- the underlying type; the annotation itself is part of type identity).
peelCapturesM :: Value -> CheckM Value
peelCapturesM v = fst <$> peelCapturesWithRegionsM v

-- | Capture annotations do not add a callable binder, but their exact region
-- witnesses remain useful while elaborating a borrowed Pi application. Keep
-- them alongside the elimination view instead of discarding the only typed
-- constraint that can solve an omitted anonymous-region argument.
peelCapturesWithRegionsM :: Value -> CheckM (Value, [Value])
peelCapturesWithRegionsM v = do
  v' <- forceM v
  case v' of
    VGlobI global _ ((_, inner) : (_, region) : _)
      | global == prelCaptures -> do
          (underlying, regions) <- peelCapturesWithRegionsM inner
          pure (underlying, regions ++ [region])
    _ -> pure (v', [])

-- | View an outer §12.3.1 capture annotation without confusing absence with
-- the explicit empty set.  Nested wrappers are the canonical Core encoding
-- of one finite set.
captureAnnotationView :: Value -> CheckM (Value, [Value], Bool)
captureAnnotationView value = do
  forced <- forceM value
  case forced of
    VGlobI global _ ((_, inner) : (_, region) : _)
      | global == prelCaptures -> do
          (underlying, regions, _) <- captureAnnotationView inner
          pure (underlying, regions ++ [region], True)
    _ -> pure (forced, [], False)

captureRegionMatches :: Ctx -> Value -> Value -> CheckM Bool
captureRegionMatches ctx left right = do
  saved <- get
  ok <- unifyDefinitional ctx left right
  unless ok (put saved)
  pure ok

missingCaptureRegions :: Ctx -> [Value] -> [Value] -> CheckM [Value]
missingCaptureRegions ctx inferred demanded =
  filterM (fmap not . contained) inferred
  where
    contained region = or <$> mapM (captureRegionMatches ctx region) demanded

-- | Directed capture-set subsumption (§12.3.1).  The underlying value types
-- still use the ordinary directed type relation, while only the outer capture
-- environment is widened.  The whole attempt is transactional because a
-- failed containment check must not retain solutions made while comparing the
-- underlying types.
tryCaptureSetSubsume :: Ctx -> Value -> Value -> CheckM Bool
tryCaptureSetSubsume ctx actual expected = do
  (actualType, actualRegions, actualAnnotated) <- captureAnnotationView actual
  (expectedType, expectedRegions, expectedAnnotated) <- captureAnnotationView expected
  if not (actualAnnotated || expectedAnnotated)
    then pure False
    else do
      saved <- get
      underlyingOk <- unify ctx actualType expectedType
      missing <- if underlyingOk then missingCaptureRegions ctx actualRegions expectedRegions else pure actualRegions
      if underlyingOk && null missing
        then pure True
        else put saved >> pure False

captureMismatchRegions :: Ctx -> Value -> Value -> CheckM (Maybe ([Value], [Value], [Value]))
captureMismatchRegions ctx actual expected = do
  (actualType, actualRegions, actualAnnotated) <- captureAnnotationView actual
  (expectedType, expectedRegions, expectedAnnotated) <- captureAnnotationView expected
  if not (actualAnnotated || expectedAnnotated)
    then pure Nothing
    else do
      saved <- get
      sameUnderlying <- unifyDefinitional ctx actualType expectedType
      missing <- if sameUnderlying then missingCaptureRegions ctx actualRegions expectedRegions else pure []
      put saved
      pure $ if sameUnderlying && not (null missing) then Just (actualRegions, expectedRegions, missing) else Nothing

renderCaptureRegions :: Ctx -> [Value] -> CheckM Text
renderCaptureRegions ctx regions = do
  rendered <- mapM (fmap renderTerm . quoteIn ctx) regions
  pure ("{" <> T.intercalate ", " rendered <> "}")

reportCaptureSetMismatch :: Ctx -> Span -> [Value] -> [Value] -> [Value] -> CheckM ()
reportCaptureSetMismatch ctx site inferred demanded missing = do
  inferredText <- renderCaptureRegions ctx inferred
  demandedText <- renderCaptureRegions ctx demanded
  missingText <- renderCaptureRegions ctx missing
  report $
    withPayload
      ( withPayloadField "valueExpression" (T.pack (show site)) $
          withPayloadField "inferredCaptureSet" inferredText $
            withPayloadField "demandedCaptureSet" demandedText $
              withPayloadField "missingRegions" missingText $
                withPayloadField "regionOrigins" (T.pack (show site)) $
                  withPayloadField "enclosingInterface" (T.pack (show site)) $
                    payloadKind "capture-set-mismatch"
      ) $
      diag SevError StageElaborate "E_CAPTURE_SET_MISMATCH" (Just "kappa.capture.mismatch") site
        "the value's hidden region environment is not contained in the demanded capture annotation (§12.3.1)"

-- | Source binders are the authority for associating a borrowed local with
-- its explicit region.  Recording the resolved region value here lets later
-- closure inference compare identities rather than source spellings.
recordBinderCaptureRegion :: Ctx -> Binder -> Bool -> [Value] -> Ctx -> CheckM Ctx
recordBinderCaptureRegion sourceCtx binder expectedBorrowed expectedRegions boundCtx =
  case (bName binder, bpBorrow (bPrefix binder)) of
    (Just binderName, Just (BorrowMark Nothing)) ->
      pure boundCtx {ctxBorrowCaptureRegions = Map.insert (nameText binderName) Nothing (ctxBorrowCaptureRegions boundCtx)}
    (Just binderName, Just (BorrowMark (Just regionName))) -> do
      (regionTerm, regionType) <- infer sourceCtx (EVar regionName)
      expectedRegion <- globalValueM prelRegion []
      expectType sourceCtx (nameSpan regionName) regionType expectedRegion
      regionValue <- evalIn sourceCtx regionTerm
      pure boundCtx {ctxBorrowCaptureRegions = Map.insert (nameText binderName) (Just regionValue) (ctxBorrowCaptureRegions boundCtx)}
    (Just binderName, Nothing)
      | expectedBorrowed ->
          pure boundCtx
            { ctxBorrowCaptureRegions =
                Map.insert (nameText binderName) (listToMaybe expectedRegions) (ctxBorrowCaptureRegions boundCtx)
            }
    _ -> pure boundCtx

-- | Minimal explicit capture environment of a closure literal.  Free locals
-- inherit capture annotations from their checked types; borrowed locals add
-- the resolved region installed by 'recordBinderCaptureRegion'.  Anonymous
-- borrows are returned separately because no surface annotation can name
-- their rigid region.
lambdaCaptureRequirements :: Ctx -> Expr -> CheckM ([(Value, Span)], [Span])
lambdaCaptureRequirements ctx expression = do
  requirements <- fmap concat $ forM (freeVarOccurrences expression) $ \occurrence ->
    case lookupCtx (nameText occurrence) ctx of
      Nothing -> pure []
      Just (_, entry) ->
        case Map.lookup (nameText occurrence) (ctxBorrowCaptureRegions ctx) of
          Just (Just region) -> pure [Left (region, nameSpan occurrence)]
          Just Nothing -> pure [Right (nameSpan occurrence)]
          Nothing -> do
            (_, regions, annotated) <- captureAnnotationView (ceType entry)
            pure [Left (region, nameSpan occurrence) | annotated, region <- regions]
  pure
    ( [entry | Left entry <- requirements]
    , [site | Right site <- requirements]
    )

checkCaptureAnnotatedLambda :: Ctx -> Expr -> Value -> CheckM Term
checkCaptureAnnotatedLambda ctx expression captureType = do
  (inner, demandedRegions) <- peelCapturesWithRegionsM captureType
  tm <- check ctx expression inner
  (namedRequirements, anonymousRequirements) <- lambdaCaptureRequirements ctx expression
  let inferredRegions = map fst namedRequirements
  missingRegions <- missingCaptureRegions ctx inferredRegions demandedRegions
  unless (null missingRegions && null anonymousRequirements) $
    reportCaptureSetMismatch ctx (exprSpan expression) inferredRegions demandedRegions missingRegions
  pure tm

-- | Preserve the identity of a user-written borrow region in the function
-- type's hidden region environment (§12.3.1). The borrowed-access bit on the
-- Pi controls calling convention and usage; it is not enough to distinguish
-- @&[s]@ from @&[t]@ during higher-rank subsumption. 'captures' is the
-- specification's existing compile-time representation for exactly that
-- identity and is erased before runtime lowering.
annotateExplicitBorrowRegion :: Ctx -> Binder -> Term -> CheckM Term
annotateExplicitBorrowRegion ctx binder functionType =
  case bpBorrow (bPrefix binder) of
    Just (BorrowMark (Just regionName)) -> do
      (regionTerm, regionType) <- infer ctx (EVar regionName)
      expectedRegion <- globalValueM prelRegion []
      expectType ctx (nameSpan regionName) regionType expectedRegion
      capturesHead <- globalHeadM prelCaptures
      pure (CApp Expl (CApp Expl capturesHead functionType) regionTerm)
    _ -> pure functionType

-- | Is the value (in whnf) headed by a projection of an opaque member
-- of a sealed package (§13.2.10)?
opaqueSealHead :: Value -> CheckM Bool
opaqueSealHead v = do
  v' <- forceM v
  case v' of
    VProjN _ r f -> do
      r' <- forceM r
      case r' of
        VSealV ls _ -> pure (f `elem` ls)
        _ -> pure False
    VAppN _ h _ -> opaqueSealHead h
    _ -> pure False

-- ── Names ────────────────────────────────────────────────────────────

lookupGlobalName :: Text -> CheckM (Maybe GName)
lookupGlobalName n = do
  st <- get
  let own = GName (csModule st) n
  case Map.lookup n (csLocalDeclScope st) of
    Just local -> pure (Just local)
    Nothing
      | Map.member own (csGlobals st) || Map.member own (csCtors st) ->
          pure (Just own)
      | otherwise -> pure (Map.lookup n (csScope st))

-- | Whether a constructor identity may be named unqualified at the current
-- source location. Expected-type-directed constructor selection must use the
-- same import authority as ordinary name resolution: knowing the result data
-- family does not make an opaque or non-imported constructor visible.
constructorInScope :: CheckState -> GName -> Bool
constructorInScope st constructor@(GName moduleName _) =
  constructor `elem` Map.elems (csLocalDeclScope st)
    || moduleName == csModule st
    || Map.lookup (gnameText constructor) (csScope st) == Just constructor

-- | §3.1.4/§8.3.1A: if the spelling @n@ names a live type, constructor,
-- or other top-level declaration (the kind of declaration a module alias
-- with the same spelling shadows), return a short human label for that
-- kind. Returns 'Nothing' when @n@ denotes no such declaration, so the
-- caller falls back to the ordinary unresolved-member diagnostic. The
-- test is keyed on "the alias spelling also has a declaration", not on
-- any particular name.
shadowedDeclKind :: Text -> CheckM (Maybe Text)
shadowedDeclKind n = do
  mg <- lookupGlobalName n
  st <- get
  pure $ do
    g <- mg
    if
      | Map.member g (csDatas st) -> Just "type"
      | Map.member g (csCtors st) -> Just "constructor"
      | Map.member g (csGlobals st) -> Just "declaration"
      | otherwise -> Nothing

globalTerm :: GName -> CheckM (Maybe (Term, Value))
globalTerm g = do
  st <- get
  -- §7.2: in term position the constructor facet of a same-spelling
  -- data family wins over the type facet.
  case Map.lookup g (csCtors st) of
    Just ci -> do
      (universes, cty) <- instantiateCtor g ci
      ec <- ec_
      let tm = etaCtor ec g universes cty
      ty <- evalIn emptyCtx cty
      pure (Just (tm, ty))
    Nothing -> case Map.lookup g (csGlobals st) of
      Nothing -> pure Nothing
      Just gd -> do
        (headTm, ty, _) <- instantiateGlobal g gd
        pure (Just (headTm, ty))

-- | Source occurrence of a possibly local nominal declaration.  Local
-- families are represented by closed global interfaces prefixed with their
-- closure-converted capture telescope; the source spelling denotes that head
-- applied to the declaration-site binders still in lexical scope.
globalTermIn :: Ctx -> Span -> GName -> CheckM (Maybe (Term, Value))
globalTermIn ctx site global = do
  resolved <- globalTerm global
  traverse recordAndApply resolved
  where
    recordAndApply pair@(headTerm, _) = do
      st <- get
      when
        ( Map.member global (csGlobals st)
            && not (Map.member global (csCtors st))
        )
        ( recordRecursiveSchemaOccurrence
            (Just ctx)
            False
            site
            global
            (case headTerm of
               CGlobI _ universes -> universes
               _ -> [])
        )
      applyGeneratedPrefixAndCaptures pair

    applyGeneratedPrefixAndCaptures (headTerm, headType) = do
      saturated <-
        insertDeclarationConstraintImplicits ctx site headTerm headType
      applyLocalNominalCaptures ctx site global saturated

-- type-facet lookup (type positions, §7.2)
globalType :: GName -> CheckM (Maybe (Term, Value))
globalType g = do
  st <- get
  case Map.lookup g (csGlobals st) of
    Just gd -> do
      (headTm, ty, _) <- instantiateGlobal g gd
      pure (Just (headTm, ty))
    Nothing -> pure Nothing

globalTypeIn :: Ctx -> Span -> GName -> CheckM (Maybe (Term, Value))
globalTypeIn ctx site global =
  globalType global >>= traverse applyGeneratedPrefixAndCaptures
  where
    applyGeneratedPrefixAndCaptures (headTerm, headType) = do
      saturated <-
        insertDeclarationConstraintImplicits ctx site headTerm headType
      applyLocalNominalCaptures ctx site global saturated

applyLocalNominalCaptures
  :: Ctx
  -> Span
  -> GName
  -> (Term, Value)
  -> CheckM (Term, Value)
applyLocalNominalCaptures ctx site global initial = do
  captures <- gets (Map.findWithDefault [] global . csLocalNominalCaptures)
  foldM applyOne initial captures
  where
    applyOne (function, functionType) capture = do
      let index = ctxLen ctx - lncLevel capture - 1
      if index < 0 || index >= ctxLen ctx
        then do
          report $
            withPayload
              ( withPayloadField "localDeclaration" (gnameText global) $
                  withPayloadField "capture" (lncName capture) $
                    payloadKind "local-declaration-capture-scope"
              ) $
              diag SevError StageElaborate "E_LOCAL_DECLARATION_CAPTURE_SCOPE"
                (Just "kappa.name.unresolved") site
                ( "local declaration '" <> gnameText global
                    <> "' requires captured binder '" <> lncName capture
                    <> "', but that declaration-site binder is no longer in lexical scope (§30.1.1)"
                )
          pure (function, functionType)
        else do
          let argument = CVar index
              argumentValue = ctxEnv ctx !! index
          forceM functionType >>= \case
            VPiM _ Impl _ _ _ _ codomain -> do
              resultType <- clApp codomain argumentValue
              pure (CApp Impl function argument, resultType)
            actual -> do
              actualTerm <- quoteIn ctx actual
              report $
                withPayload
                  ( withPayloadField "localDeclaration" (gnameText global) $
                      withPayloadField "capture" (lncName capture) $
                        withPayloadField "actualHeadType" (renderTerm actualTerm) $
                          payloadKind "local-declaration-capture-interface"
                  ) $
                  diag SevError StageElaborate "E_LOCAL_DECLARATION_CAPTURE_INTERFACE"
                    (Just "kappa.internal.compiler") site
                    ( "local declaration '" <> gnameText global
                        <> "' has no implicit capture binder for '" <> lncName capture
                        <> "' in its finalized interface"
                    )
              pure (function, functionType)
-- | Instantiate a declaration's hidden universe telescope at one reference.
-- Hidden universes are not Core Pi binders and never become runtime
-- arguments; they live only on the global head and in the specialized type.
instantiateGlobal :: GName -> GlobalDef -> CheckM (Term, Value, [Level])
instantiateGlobal g originalDefinition = do
  ensureTopLevelDataFamilyHeader g
  gd <- gets (Map.findWithDefault originalDefinition g . csGlobals)
  st <- get
  active <- gets csActiveUniverseDefinition
  ec <- ec_
  assignments <- gets csLevelAssignments
  let telescope = gdUniverses gd
      rawType = zonkLevels assignments (globalCoreType ec gd)
      rawInterfaceTerms =
        map (zonkLevels assignments) (globalUniverseInterfaceTerms st g gd)
      ownUniverses = map LParam [0 .. dutParameterCount telescope - 1]
      interfaceFinalized =
        dutParameterCount telescope > 0
          || g `Set.member` csFinalizedUniverseInterfaces st
  (universes, specialize) <-
    if interfaceFinalized
      then do
        instantiated <-
          if active == Just g
            then pure ownUniverses
            else instantiateUniverseTelescope g telescope
        pure
          ( instantiated
          , zonkTermWith
              (\_ _ -> Nothing)
              (substituteLevelParams instantiated)
              0
              rawType
          )
      else do
        let provisionalMetas = nub (concatMap levelMetasOfTerm rawInterfaceTerms)
        registerProvisionalGlobalUniverseMetas g provisionalMetas
        if active == Just g
          then pure (map LMeta provisionalMetas, rawType)
          else
            instantiateProvisionalUniverses
              ProvisionalGlobalFacet g provisionalMetas rawType
  ty <- evalIn emptyCtx specialize
  pure (CGlobI g universes, ty, universes)

registerProvisionalGlobalUniverseMetas
  :: GName
  -> [LevelMeta]
  -> CheckM ()
registerProvisionalGlobalUniverseMetas global provisionalMetas = do
  let provisionalProjection =
        [ (meta, index)
        | (index, meta) <- zip [0 ..] provisionalMetas
        ]
  modify' $ \current ->
    current
      { csGlobals =
          Map.adjust
            (\definition ->
               definition
                 { gdProvisionalUniverseProjection = provisionalProjection
                 })
            global
            (csGlobals current)
      , csProvisionalGlobalUniverseMetas =
          Map.insertWith
            (\new existing -> nub (existing ++ new))
            global
            [provisionalMetas]
            (csProvisionalGlobalUniverseMetas current)
      }

-- | Construct a checker-generated reference through the same hidden-universe
-- instantiation boundary as a source global occurrence. Generated Core must
-- never guess an empty universe spine for a generalized declaration.
globalHeadM :: GName -> CheckM Term
globalHeadM g = fst <$> globalHeadWithUniversesM g

-- | The generated global head together with the exact declaration-universe
-- occurrence selected for it. Semantic components stored beside a global
-- (effect-operation headers, supertrait closures, and similar metadata) must
-- be specialized with this same spine rather than freshening independently.
globalHeadWithUniversesM :: GName -> CheckM (Term, [Level])
globalHeadWithUniversesM g = do
  definition <- gets (Map.lookup g . csGlobals)
  case definition of
    Just gd -> do
      (headTerm, _, universes) <- instantiateGlobal g gd
      pure (headTerm, universes)
    Nothing -> pure (CGlob g, [])

-- | Apply a checker-generated declared constructor through the same
-- elaboration boundary as source syntax.  In particular, the eta-constructor
-- supplies the complete semantic Pi spine to 'CCtorI'; generated occurrences
-- must not retain only the runtime payload because KCoreText and observation
-- analysis validate erased and parametric constructor arguments as well.
generatedCtorApplyAtM :: Ctx -> Value -> GName -> [Term] -> CheckM Term
generatedCtorApplyAtM ctx expected constructor payload = do
  globalTerm constructor >>= \case
    Just (headTerm, headType) -> applyPayload headTerm headType payload
    Nothing -> do
      errAt noSpan "E_INTERNAL_CONSTRUCTOR_INTERFACE" Nothing
        ("compiler-generated constructor interface is unavailable for '" <> gnameText constructor <> "'")
      fst <$> anyHole ctx
  where
    applyPayload term ty [] = do
      (term', actual) <- insertAllImplicits ctx noSpan term ty
      coerceTerm ctx noSpan term' actual expected
    applyPayload term ty (argument : rest) = do
      (term', ty') <- insertAllImplicits ctx noSpan term ty
      forceM ty' >>= \case
        VPiM _ Expl _ _ _ _ closure -> do
          argumentValue <- evalIn ctx argument
          resultType <- clApp closure argumentValue
          applyPayload (CApp Expl term' argument) resultType rest
        _ -> do
          errAt noSpan "E_INTERNAL_CONSTRUCTOR_ARITY" Nothing
            ("compiler-generated constructor application supplies too many explicit arguments to '"
              <> gnameText constructor <> "'")
          fst <$> anyHole ctx

-- | Elaborate a compiler-generated constructor value against a known expected
-- type. This is required for erased/nullary proof constructors such as
-- @refl@: no runtime payload exists from which a fresh declaration-universe
-- instantiation could otherwise be constrained.
generatedCtorAtM :: Ctx -> Value -> GName -> CheckM Term
generatedCtorAtM ctx expected constructor =
  generatedCtorApplyAtM ctx expected constructor []

-- | Instantiate the data-family prefix of a constructor under an expected
-- family application. A GADT constructor interface retains every family
-- argument as a leading hidden binder, but an indexed result need not use that
-- binder uniformly: for @VCons : ... -> Vec (Succ n) a@, the expected family
-- argument @Succ Zero@ constrains @n@ to @Zero@; it is not itself the value of
-- @n@. Prefix binders that occur in the constructor result therefore remain
-- fresh metas for the ordinary expected-result unifier. Only phantom prefix
-- binders absent from the result are fixed directly from the corresponding
-- expected family argument.
--
-- Returning 'Nothing' is deliberately conservative: malformed/imported
-- constructor metadata continues through the ordinary checked-application
-- path and is rejected there rather than receiving guessed arguments.
applyExpectedConstructorFamilyPrefix
  :: Ctx
  -> CtorInfo
  -> Value
  -> Term
  -> Value
  -> CheckM (Maybe (Term, Value))
applyExpectedConstructorFamilyPrefix ctx constructorInfo expected headTerm headType = do
  expected' <- forceM expected
  dataInfo <- gets (Map.lookup (ciData constructorInfo) . csDatas)
  case (dataInfo, expected') of
    (Just info, VGlobN family arguments)
      | family == ciData constructorInfo
      , diParamCount info <= length arguments ->
          instantiatePrefix (take (diParamCount info) arguments) headTerm headType []
    _ -> pure Nothing
  where
    instantiatePrefix [] term ty prefixMetas = do
      -- Inspect the result with fresh throwaway placeholders for the remaining
      -- constructor telescope. The state rollback is intentional: these metas
      -- classify occurrence of the retained prefix metas but are not part of
      -- the source application. The real checked-spine planner allocates its
      -- own explicit placeholders and unifies that result with the expectation.
      checkpoint <- get
      result <- peelResult ty
      inspectionMetas <- gets csMetas
      put checkpoint
      forM_ prefixMetas $ \(meta, expectedArgument) ->
        unless (metaOccursInValue inspectionMetas meta result) $ do
          solved <- solveMetaAcyclic meta expectedArgument
          unless solved $ void (unify ctx (VFlex meta []) expectedArgument)
      pure (Just (term, ty))
    instantiatePrefix ((_, expectedArgument) : rest) term ty prefixMetas = do
      ty' <- forceM ty
      case ty' of
        VPiM _ Impl _ _ _ domain closure -> do
          metaTerm <- freshMetaFor ctx domain
          case metaTerm of
            CMeta meta -> do
              metaValue <- evalIn ctx metaTerm
              result <- clApp closure metaValue
              instantiatePrefix rest (CApp Impl term metaTerm) result
                (prefixMetas ++ [(meta, expectedArgument)])
            _ -> pure Nothing
        _ -> pure Nothing

    peelResult ty = do
      ty' <- forceM ty
      case ty' of
        VPiM _ _ _ _ _ domain closure -> do
          placeholder <- freshMetaFor ctx domain
          placeholderValue <- evalIn ctx placeholder
          clApp closure placeholderValue >>= peelResult
        result -> pure result

-- | Build the compiler-owned effect-tree pure node with its exact intrinsic
-- telescope.  It is not a declared constructor and therefore cannot use
-- 'generatedCtorApplyAtM'.
generatedEffPureCore :: Term -> Term -> Term -> Term
generatedEffPureCore payloadType resultType payload =
  CCtorI prelEffPure []
    (Just (CPiBoundFormedM Ordinary FormationOrdinary Expl Q1 False "__value" Nothing payloadType (shiftTerm 1 0 resultType)))
    [ConstructorArg Expl True Nothing payload]

generatedEffPureAtM :: Ctx -> Value -> Term -> CheckM Term
generatedEffPureAtM ctx expected payload = do
  forced <- forceM expected
  case monadActionViewValue forced of
    Just (carrier, payloadType)
      | nominalFamilyValueHead carrier == Just prelEff -> do
          payloadTypeTerm <- quoteIn ctx payloadType
          resultTypeTerm <- quoteIn ctx expected
          pure (generatedEffPureCore payloadTypeTerm resultTypeTerm payload)
    _ -> do
      errAt noSpan "E_INTERNAL_EFFECT_PURE_TYPE" Nothing
        "compiler-generated __EffPure requires an Eff row result type"
      fst <$> anyHole ctx

-- | Introduce a value into an arbitrary checked applicative carrier. This is
-- the semantic operation denoted by canonical @pure@ inside user-monad do
-- notation; the prelude global named @pure@ remains the concrete IO helper
-- when inferred without such an expectation.
generatedApplicativePureAtM
  :: Ctx
  -> Span
  -> Value
  -> Value
  -> Term
  -> Value
  -> CheckM Term
generatedApplicativePureAtM ctx site carrier sourceType payload expectedAction = do
  sourceTypeTerm <- quoteIn ctx sourceType
  sourceClassifier <- typeArgumentClassifier ctx site carrier sourceType
  applicativeGoal <- globalValueM prelApplicative [(Expl, carrier)]
  applicativeDictionary <- resolveImplicit ctx site applicativeGoal
  (pureMember, pureMemberType) <-
    knownTraitMemberProjection
      ctx
      site
      prelApplicative
      "pure"
      applicativeGoal
      applicativeDictionary
  (application, actualAction) <-
    applyGeneratedCoreSpine
      ctx
      site
      pureMember
      pureMemberType
      [ (Impl, sourceTypeTerm, sourceClassifier)
      , (Expl, payload, sourceType)
      ]
  coerceTerm ctx site application actualAction expectedAction

-- | Introduce the canonical equality witness after 'propProof' has established
-- the equality judgment.  The proposition decision may rely on branch-local
-- facts that ordinary conversion intentionally does not treat as ambient
-- definitional equations, so rebuilding @refl@ through generic implicit
-- insertion would discard the already-proved judgment.  Instead, specialize
-- the constructor at the authenticated equality head and apply its erased
-- carrier and endpoint arguments directly.  The result is the ordinary Core
-- introduction form @refl @{u} @A @lhs : lhs = lhs@, admissible at the goal
-- precisely because the caller has proved @lhs = rhs@.
generatedReflAtM :: Ctx -> Value -> CheckM Term
generatedReflAtM ctx = generatedReflForGoalAtM ctx Nothing

-- | Instantiate the compiler-owned raw proof primitive at the classifier of
-- the exact proposition it is checked against.  The primitive is unsafe and
-- remains guarded by 'gateUnsafeResolved'; this helper only preserves its
-- checked universe instance.  Inferring it independently and coercing later
-- can choose a least occurrence universe that becomes stale when the
-- enclosing declaration generalizes.
generatedRawProofAtM :: Ctx -> Span -> Value -> CheckM Term
generatedRawProofAtM ctx site proposition = do
  classifier <- typeValueClassifierLevel ctx proposition >>= \case
    Just level -> pure (normalizeLevel level)
    Nothing -> do
      errAt site "E_INTERNAL_PRELUDE_INTERFACE" Nothing
        "the compiler-owned proof primitive requires a proposition with a checked universe classifier"
      pure LZero
  definition <- gets (Map.lookup prelRawProof . csGlobals)
  case definition of
    Just global
      | dutParameterCount (gdUniverses global) == 1 -> do
          propositionTerm <- quoteIn ctx proposition
          (headTerm, headType) <-
            specializeGlobalAt ctx prelRawProof global [classifier]
          (proof, _) <-
            applyGeneratedCoreSpine
              ctx
              site
              headTerm
              headType
              [(Impl, propositionTerm, VSort classifier)]
          pure proof
    _ -> do
      errAt site "E_INTERNAL_PRELUDE_INTERFACE" Nothing
        "the compiler-owned proof primitive must have one declaration-universe parameter"
      fst <$> anyHole ctx

-- | Prefer the exact checked proposition when constructing generated equality
-- evidence. Quoting its semantic value can unfold a local definition and make
-- the proof mention an outer expression instead of the stable local consumed
-- by the surrounding generated term.
generatedReflForGoalAtM :: Ctx -> Maybe Term -> Value -> CheckM Term
generatedReflForGoalAtM ctx sourceGoal goal = do
  goal' <- forceM goal
  info <- gets (Map.lookup prelRefl . csCtors)
  case (goal', info) of
    ( VGlobI equality universes
        [(Impl, carrier), (Expl, lhs), (Expl, rhs)]
      , Just ctorInfo
      )
      | equality == prelEqType ->
          build ctorInfo equality universes carrier lhs rhs
    ( VCtorI equality universes arguments
      , Just ctorInfo
      )
      | equality == prelEqType
      , [carrier, lhs, rhs] <-
          [cvaValue argument | argument <- arguments, cvaPayload argument] ->
          build ctorInfo equality universes carrier lhs rhs
    _ -> do
      errAt noSpan "E_INTERNAL_REFL_GOAL" Nothing
        "the equality prover produced a witness request without a canonical equality goal"
      fst <$> anyHole ctx
  where
    build ctorInfo equality suppliedUniverses carrier lhs rhs
      | ciData ctorInfo == equality = do
          let universeCount = dutParameterCount (ciUniverses ctorInfo)
          case sourceGoal >>= canonicalEqualityCorePayload of
            Just (sourceUniverses, carrierTerm, lhsTerm, rhsTerm)
              | length sourceUniverses == universeCount ->
                  buildTerms
                    ctorInfo
                    sourceUniverses
                    carrierTerm
                    lhsTerm
                    rhsTerm
            _ -> do
              universes <-
                if length suppliedUniverses == universeCount
                  then pure (Just suppliedUniverses)
                  else
                    if null suppliedUniverses && universeCount == 1
                      then fmap (fmap pure) (typeValueClassifierLevel ctx carrier)
                      else pure Nothing
              case universes of
                Nothing -> invalidUniverse
                Just selectedUniverses ->
                  buildAt ctorInfo selectedUniverses carrier lhs rhs
      | otherwise = invalidUniverse

    buildAt ctorInfo universes carrier lhs rhs = do
      carrierTerm <- quoteIn ctx carrier
      lhsTerm <- quoteIn ctx lhs
      rhsTerm <- quoteIn ctx rhs
      buildTerms ctorInfo universes carrierTerm lhsTerm rhsTerm

    buildTerms ctorInfo universes carrierTerm lhsTerm rhsTerm = do
      (headTerm, _) <- specializeCtorAt ctx prelRefl ctorInfo universes
      -- Constructor interfaces retain the complete data-family prefix.
      -- Even though refl's result identifies both endpoints with lhs, the
      -- expected equality's rhs is still a semantic family argument and
      -- must be supplied to saturate that prefix.
      pure (CApp Impl (CApp Impl (CApp Impl headTerm carrierTerm) lhsTerm) rhsTerm)

    invalidUniverse = do
      errAt noSpan "E_INTERNAL_REFL_GOAL" Nothing
        "the equality prover produced a witness with an invalid universe instantiation"
      fst <$> anyHole ctx

canonicalEqualityCorePayload :: Term -> Maybe ([Level], Term, Term, Term)
canonicalEqualityCorePayload proposition = do
  let (headTerm, arguments) =
        spineOfTerm (stripIdentityWrappers proposition)
      implicit = [argument | (Impl, argument) <- arguments]
      explicit = [argument | (Expl, argument) <- arguments]
  universes <- case stripIdentityWrappers headTerm of
    CGlobal equality levels
      | equality == prelEqType -> Just levels
    CGlob equality
      | equality == prelEqType -> Just []
    _ -> Nothing
  carrier <- listToMaybe implicit
  (lhs, rhs) <- last2 explicit
  pure (universes, carrier, lhs, rhs)

-- | Construct a compiler-generated constructor semantic value from a known
-- result type. This is the value-level counterpart of 'generatedCtorAtM' for
-- elaboration-time primitives: quoting the result must retain the selected
-- declaration-universe instantiation instead of rebuilding a legacy empty
-- constructor spine.
generatedCtorValueAtM :: Ctx -> Value -> GName -> [Value] -> CheckM Value
generatedCtorValueAtM ctx expected constructor payload = do
  payloadTerms <- mapM (quoteIn ctx) payload
  term <- generatedCtorApplyAtM ctx expected constructor payloadTerms
  evalIn ctx term

-- | Apply a checker-generated global reference after instantiating its hidden
-- declaration-universe telescope.  Generated syntax must use this boundary
-- rather than rebuilding a compatibility 'CGlob', since the latter denotes an
-- explicitly empty telescope and is only correct for monomorphic globals.
globalAppM :: GName -> [(Icit, Term)] -> CheckM Term
globalAppM g arguments = do
  headTerm <- globalHeadM g
  pure (foldl' (\term (icit, argument) -> CApp icit term argument) headTerm arguments)

-- | Construct a checker-generated neutral value through the declaration's
-- hidden-universe instantiation boundary. This is the value-level counterpart
-- of 'globalHeadM'; using 'VGlobN' here would lose the fresh level spine when
-- the value is quoted back into Core.
globalValueM :: GName -> Spine -> CheckM Value
globalValueM g spine = do
  definition <- gets (Map.lookup g . csGlobals)
  case definition of
    Just gd -> do
      (_, _, universes) <- instantiateGlobal g gd
      pure (VGlobI g universes spine)
    Nothing -> pure (VGlobN g spine)

instantiateCtorType :: GName -> CtorInfo -> CheckM Term
instantiateCtorType g ci = snd <$> instantiateCtor g ci

instantiateCtor :: GName -> CtorInfo -> CheckM ([Level], Term)
instantiateCtor g ci = do
  assignments <- gets csLevelAssignments
  let rawType = zonkLevels assignments (ciType ci)
      telescope = ciUniverses ci
  if dutParameterCount telescope > 0
    then do
      universes <- instantiateUniverseTelescope g telescope
      pure
        ( universes
        , zonkTermWith
            (\_ _ -> Nothing)
            (substituteLevelParams universes)
            0
            rawType
        )
    else do
      let provisionalMetas = nub (levelMetasOfTerm rawType)
      modify' $ \state ->
        state
          { csProvisionalConstructorUniverseMetas =
              Map.insertWith
                (\new existing -> nub (existing ++ new))
                g
                [provisionalMetas]
                (csProvisionalConstructorUniverseMetas state)
          }
      instantiateProvisionalUniverses
        ProvisionalConstructorFacet g provisionalMetas rawType

-- | Freshen a declaration interface before the module SCC generalization
-- boundary has replaced its observable level metas by stable 'LParam's. This
-- is the provisional form of the same hidden telescope, not let-bound
-- monomorphism: every external occurrence receives fresh levels and the
-- constraints are installed once the declaration SCC materializes its stable
-- telescope. This temporary phase must stay bounded: scanning/copying the
-- module constraint graph at every use makes header elaboration quadratic.
-- Terms retained past the header pass are rewritten to the final telescope by
-- 'generalizeDeclarationUniverses'.
instantiateProvisionalUniverses
  :: ProvisionalUniverseFacet
  -> GName
  -> [LevelMeta]
  -> Term
  -> CheckM ([Level], Term)
instantiateProvisionalUniverses facet owner sourceMetas =
  instantiateProvisionalUniversesWith facet owner sourceMetas Map.empty

-- | Instantiate a provisional declaration while fixing selected source-meta
-- positions to levels authenticated by an enclosing semantic occurrence.
-- The complete source spine is retained so SCC finalization can apply the
-- ordinary provisional-to-principal projection.
instantiateProvisionalUniversesWith
  :: ProvisionalUniverseFacet
  -> GName
  -> [LevelMeta]
  -> Map LevelMeta Level
  -> Term
  -> CheckM ([Level], Term)
instantiateProvisionalUniversesWith facet owner sourceMetas pinned term = do
  freshLevels <-
    forM sourceMetas $ \meta ->
      maybe freshLevelInstantiationMeta pure (Map.lookup meta pinned)
  consumer <- gets csActiveUniverseDefinition
  let substitution = Map.fromList (zip sourceMetas freshLevels)
      substitute = substituteLevelMetas substitution
  unless (null sourceMetas) $
    modify' $ \st ->
      let identity = csNextProvisionalUniverseInstantiation st
       in st
            { csProvisionalUniverseInstantiations =
                ProvisionalUniverseInstantiation
                  identity
                  facet
                  owner
                  consumer
                  sourceMetas
                  freshLevels
                  False
                  Set.empty
                  : csProvisionalUniverseInstantiations st
            , csNextProvisionalUniverseInstantiation = identity + 1
            }
  pure
    ( freshLevels
    , zonkTermWith (\_ _ -> Nothing) substitute 0 term
    )

-- | Universe spine for a declaration reference emitted while that
-- declaration's header is still being elaborated. An explicit schema is
-- already rigid and uses its ordered parameters; an inferred declaration
-- forwards the observable provisional metas until SCC generalization replaces
-- them with stable parameters. Emitting an empty spine here creates a distinct
-- global identity and cannot be repaired later when no meta occurs in the
-- stale reference.
provisionalDeclarationUniverses :: [Term] -> CheckM [Level]
provisionalDeclarationUniverses interfaceTerms = do
  explicitCount <- gets (Map.size . csActiveUniverseSchema)
  finalizedTerms <- mapM (zonkTermM 0) interfaceTerms
  pure $
    if explicitCount > 0
      then map LParam [0 .. explicitCount - 1]
      else map LMeta (nub (concatMap levelMetasOfTerm finalizedTerms))

instantiateUniverseTelescope :: GName -> DeclarationUniverseTelescope -> CheckM [Level]
instantiateUniverseTelescope _ telescope =
  replicateM (dutParameterCount telescope) freshLevelInstantiationMeta

-- | Freshen a local declaration schema at one lexical occurrence. The
-- generalized semantic value remains in 'ctxEnv'; 'CLocal' carries the static
-- specialization needed by NbE and KCoreText without introducing a term
-- argument or runtime closure field (§11.1.2.3A.1).
instantiateLocalDeclaration
  :: Ctx
  -> Span
  -> Int
  -> CtxEntry
  -> LocalUniverseInfo
  -> CheckM (Term, Value)
instantiateLocalDeclaration ctx site index entry LocalUniverseInfo {luiTelescope = telescope} = do
  recursiveScope <- gets csActiveLocalRecursiveSchemaScope
  let calleeLevel = ctxLen ctx - 1 - index
      currentRecursiveInstance = do
        scope <- recursiveScope
        guard (calleeLevel `Map.member` lrssMembers scope)
        guard
          ( length (lrssCurrentInstance scope)
              == dutParameterCount telescope
          )
        pure (lrssCurrentInstance scope)
  universes <-
    maybe
      (replicateM (dutParameterCount telescope) freshLevelInstantiationMeta)
      pure
      currentRecursiveInstance
  recordLocalRecursiveSchemaOccurrence ctx False site index universes
  instantiateLocalDeclarationAt ctx index entry telescope universes

instantiateLocalDeclarationAt
  :: Ctx
  -> Int
  -> CtxEntry
  -> DeclarationUniverseTelescope
  -> [Level]
  -> CheckM (Term, Value)
instantiateLocalDeclarationAt ctx index entry telescope universes = do
  generalizedType <- quoteIn ctx (ceType entry)
  let specializedType =
        zonkTermWith
          (\_ _ -> Nothing)
          (instantiateLocalLevelParams (length universes) universes)
          0
          generalizedType
  ty <- evalIn ctx specializedType
  pure (CLocal index universes, ty)

recordLocalRecursiveSchemaOccurrence
  :: Ctx
  -> Bool
  -> Span
  -> Int
  -> [Level]
  -> CheckM ()
recordLocalRecursiveSchemaOccurrence ctx explicit site calleeIndex levels = do
  scope <- gets csActiveLocalRecursiveSchemaScope
  forM_ scope $ \LocalRecursiveSchemaScope {..} -> do
    let calleeLevel = ctxLen ctx - 1 - calleeIndex
    when (calleeLevel `Map.member` lrssMembers) $ do
      assumptions <- effectiveLevelAssumptions ctx
      modify' $ \state ->
        state
          { csLocalRecursiveSchemaOccurrences =
              LocalRecursiveSchemaOccurrence
                lrssCaller
                calleeLevel
                levels
                explicit
                assumptions
                site
                : csLocalRecursiveSchemaOccurrences state
          }

-- | Normalize a same-module reference while its declaration still has the
-- provisional all-meta telescope used during header elaboration. Seeded and
-- already-finalized references may carry the principal spine at the same
-- time. Conversion compares the two only after applying the declaration's
-- current provisional-to-principal morphism; the SCC finalizer later performs
-- the identical rewrite in retained Core.
normalizeProvisionalUniverseOccurrence :: GName -> [Level] -> CheckM [Level]
normalizeProvisionalUniverseOccurrence g universes = do
  definition <- gets (Map.lookup g . csGlobals)
  case definition of
    Just gd | not (dutExplicit (gdUniverses gd)) -> do
      st <- get
      let assignments = csLevelAssignments st
          rawInterfaceTerms = globalUniverseInterfaceTerms st g gd
          normalizedInterfaceTerms = map (zonkLevels assignments) rawInterfaceTerms
          sourceMetas = nub (concatMap levelMetasOfTerm rawInterfaceTerms)
          roles = mconcat (map declarationUniverseRoles normalizedInterfaceTerms)
          retainedSet = durGeneralizable roles
          retainedMetas =
            filter (`Set.member` retainedSet)
              (concatMap levelMetasOfTerm normalizedInterfaceTerms)
      pure $ case deriveUniverseReferenceProjection assignments sourceMetas retainedMetas of
        Just projection
          | length universes == urpSourceArity projection ->
              [universes !! position | position <- urpRetainedPositions projection]
        _ -> universes
    _ -> pure universes

specializeGlobalAt :: Ctx -> GName -> GlobalDef -> [Level] -> CheckM (Term, Value)
specializeGlobalAt ctx g gd universes = do
  assignments <- gets csLevelAssignments
  ec <- ec_
  let rawType = zonkLevels assignments (globalCoreType ec gd)
      specialized = specializeDeclarationUniverses (gdUniverses gd) universes rawType
  -- Explicit schema arguments are ordinary first-class TypeLevel terms and
  -- may therefore denote caller-local values.  Evaluate the specialized
  -- interface in the occurrence context so LVar identities remain rigid;
  -- evaluating in emptyCtx turns them into unrelated metas and loses proof
  -- obligations such as the reflexive bound in f.{v} v.
  ty <- evalIn ctx specialized
  pure (CGlobI g universes, ty)

recordRecursiveSchemaOccurrence :: Maybe Ctx -> Bool -> Span -> GName -> [Level] -> CheckM ()
recordRecursiveSchemaOccurrence occurrenceCtx explicit site callee levels = do
  st <- get
  case csActiveUniverseDefinition st of
    Just caller
      | csRecordRecursiveSchemaOccurrences st
      , Map.member caller (csGlobals st)
      , Map.member callee (csGlobals st) -> do
          assumptions <- effectiveLevelAssumptions (fromMaybe emptyCtx occurrenceCtx)
          modify' $ \current ->
            current
              { csRecursiveSchemaOccurrences =
                  RecursiveSchemaOccurrence caller callee levels explicit assumptions site
                    : csRecursiveSchemaOccurrences current
              }
    _ -> pure ()

-- | Specialize a semantic component stored under a declaration's universe
-- telescope (for example a trait's supertrait closures) at one occurrence of
-- that declaration. Components do not own an independent schema: the
-- declaration interface is authoritative. The provisional path uses the
-- interface's source-meta order so a component mentioning only a subset cannot
-- accidentally renumber the occurrence.
specializeDeclarationComponent :: GName -> [Level] -> Term -> CheckM Term
specializeDeclarationComponent owner universes component = do
  definition <- gets (Map.lookup owner . csGlobals)
  assignments <- gets csLevelAssignments
  st <- get
  let zonk = zonkLevels assignments
      rawComponent = zonk component
  pure $ case definition of
    Nothing -> rawComponent
    Just gd
      | dutParameterCount (gdUniverses gd) > 0 ->
          zonkTermWith
            (\_ _ -> Nothing)
            (substituteLevelParams universes)
            0
            rawComponent
      | otherwise ->
          let rawInterfaces = map zonk (globalUniverseInterfaceTerms st owner gd)
              sourceMetas = nub (concatMap levelMetasOfTerm rawInterfaces)
              substitution = substituteLevelMetas (Map.fromList (zip sourceMetas universes))
           in zonkTermWith (\_ _ -> Nothing) substitution 0 rawComponent

-- | Specialize the complete operation telescope with the same hidden or
-- provisional universe occurrence selected for its owning effect interface.
-- The metadata is not an independent declaration: freshening it separately,
-- or leaving its raw metas connected to the declaration header, makes two
-- operation selections spuriously monomorphic.
specializeEffectOperationMetadata
  :: GName
  -> [Level]
  -> EffLabelInfo
  -> EffOpInfo
  -> CheckM (EffLabelInfo, EffOpInfo)
specializeEffectOperationMetadata owner universes effectInfo operation = do
  let specializeTerm = specializeDeclarationComponent owner universes
      specializeLevel level = do
        specialized <- specializeTerm (CSort level)
        pure $ case specialized of
          CSort result -> result
          _ -> level
      specializeAssumption = traverse $ \(lower, upper) ->
        (,) <$> specializeLevel lower <*> specializeLevel upper
      specializeEntry entry = do
        domain <- specializeTerm (teDomain entry)
        assumption <- specializeAssumption (teLevelAssumption entry)
        pure entry {teDomain = domain, teLevelAssumption = assumption}
      specializeOperation op = do
        implicits <- traverse specializeEntry (eoiImplicits op)
        arguments <- traverse specializeEntry (eoiArgs op)
        result <- specializeTerm (eoiResT op)
        pure op {eoiImplicits = implicits, eoiArgs = arguments, eoiResT = result}
  parameters <- traverse specializeEntry (eliParams effectInfo)
  operation' <- specializeOperation operation
  pure (effectInfo {eliParams = parameters}, operation')

specializeCtorAt :: Ctx -> GName -> CtorInfo -> [Level] -> CheckM (Term, Value)
specializeCtorAt ctx g ci universes = do
  assignments <- gets csLevelAssignments
  ec <- ec_
  let rawType = zonkLevels assignments (ciType ci)
      specialized = specializeDeclarationUniverses (ciUniverses ci) universes rawType
  ty <- evalIn ctx specialized
  pure (etaCtor ec g universes specialized, ty)

-- | Specialize either a finalized declaration telescope ('LParam') or the
-- exact provisional meta spine carried by a same-SCC occurrence. The latter
-- is essential during header elaboration: re-reading the raw declaration type
-- without substituting its occurrence spine reconnects a use to the callee's
-- source metas and destroys independent instantiation (§11.1.2.3A).
specializeDeclarationUniverses
  :: DeclarationUniverseTelescope
  -> [Level]
  -> Term
  -> Term
specializeDeclarationUniverses telescope universes rawType
  | dutParameterCount telescope > 0 =
      zonkTermWith (\_ _ -> Nothing) (substituteLevelParams universes) 0 rawType
  | length universes == length provisionalMetas =
      zonkTermWith
        (\_ _ -> Nothing)
        (substituteLevelMetas (Map.fromList (zip provisionalMetas universes)))
        0
        rawType
  | otherwise = rawType
  where
    provisionalMetas = nub (levelMetasOfTerm rawType)

inferUniverseInstantiation :: Bool -> Ctx -> Expr -> [Expr] -> Span -> CheckM (Term, Value)
inferUniverseInstantiation preferTypeFacet ctx base arguments sp = do
  target <- universeInstantiationTarget
  case (target, traverse barePun arguments) of
    (False, Just names) -> elabPatch ctx base (map PatchPun names) sp
    _ -> do
      levels <- mapM (fmap snd . elabLevelExpr ctx) arguments
      case base of
        EVar name
          | Just (index, entry) <- lookupCtx (nameText name) ctx ->
              case ceLocalUniverses entry of
                Just LocalUniverseInfo {luiTelescope = telescope} -> do
                  actual <- checkLocalArity entry telescope levels
                  recordLocalRecursiveSchemaOccurrence ctx True sp index actual
                  instantiateLocalDeclarationAt ctx index entry telescope actual
                Nothing ->
                  case canonicalScopedEffect name of
                    Just effectInfo -> specializeScopedEffectAt effectInfo levels
                    Nothing -> unresolved
        _ -> inferGlobal levels
  where
    -- @x.{a}@ is the sole lexical overlap between explicit universe
    -- instantiation and forbidden record-patch punning. Resolution, not the
    -- identifier spelling, decides it: a declaration/constructor facet or a
    -- generalized local declaration owns a universe telescope; an ordinary
    -- local value owns the record-patch interpretation (§11.1.2.3A.1,
    -- §13.2.5). Other argument shapes remain fail-closed schema syntax.
    universeInstantiationTarget = case base of
      EVar name
        | Just (_, entry) <- lookupCtx (nameText name) ctx ->
            pure
              ( isJust (ceLocalUniverses entry)
                  || isJust (canonicalScopedEffect name)
              )
        | otherwise -> do
            target <- lookupGlobalName (nameText name)
            case target of
              Nothing -> pure False
              Just global ->
                gets $ \st ->
                  Map.member global (csGlobals st) || Map.member global (csCtors st)
      _ -> do
        target <- staticGlobalExpr ctx base
        gets $ \st -> maybe False (\global ->
          Map.member global (csGlobals st) || Map.member global (csCtors st)) target

    barePun = \case
      EVar name -> Just name
      _ -> Nothing

    canonicalScopedEffect name = do
      effectInfo <- Map.lookup (nameText name) (ctxEffLabels ctx)
      guard (isNothing (eliFixedArgs effectInfo))
      guard (isNothing (eliFixedUniverses effectInfo))
      pure effectInfo

    specializeScopedEffectAt effectInfo levels = do
      let owner = eliIface effectInfo
      definition <- gets (Map.lookup owner . csGlobals)
      case definition of
        Just gd -> do
          actual <- checkGlobalArity owner gd levels
          specializeGlobalAt ctx owner gd actual
        Nothing -> unresolved

    inferGlobal levels = do
      target <- case base of
        EVar name -> lookupGlobalName (nameText name)
        _ -> staticGlobalExpr ctx base
      case target of
        Just g -> gets (\st -> (Map.lookup g (csCtors st), Map.lookup g (csGlobals st))) >>= \facets ->
          case (preferTypeFacet, facets) of
            (True, (_, Just gd)) -> do
              actual <- checkGlobalArity g gd levels
              recordRecursiveSchemaOccurrence (Just ctx) True sp g actual
              specializeGlobalAt ctx g gd actual >>= applyLocalNominalCaptures ctx sp g
            (False, (Just ci, _)) -> do
              actual <- checkCtorArity g ci levels
              specializeCtorAt ctx g ci actual >>= applyLocalNominalCaptures ctx sp g
            (_, (Nothing, Just gd)) -> do
              actual <- checkGlobalArity g gd levels
              recordRecursiveSchemaOccurrence (Just ctx) True sp g actual
              specializeGlobalAt ctx g gd actual >>= applyLocalNominalCaptures ctx sp g
            (_, (Just ci, Nothing)) -> do
              actual <- checkCtorArity g ci levels
              specializeCtorAt ctx g ci actual >>= applyLocalNominalCaptures ctx sp g
            _ -> unresolved
        Nothing -> unresolved

    unresolved = do
      errAt sp "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
        "explicit universe instantiation requires a declaration or constructor reference"
      anyHole ctx

    checkGlobalArity g definition supplied = do
      st <- get
      let telescope = gdUniverses definition
          rawInterfaceTerms = globalUniverseInterfaceTerms st g definition
          provisionalArity =
            length (nub (concatMap levelMetasOfTerm rawInterfaceTerms))
          expected
            | dutExplicit telescope
                || g `Set.member` csFinalizedUniverseInterfaces st =
                dutParameterCount telescope
            | otherwise = provisionalArity
          found = length supplied
      when (expected /= found) $
        errAt sp "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
          ("declaration '" <> gnameText g <> "' expects " <> T.pack (show expected)
            <> " universe arguments, but this instantiation supplies " <> T.pack (show found))
      pure (take expected (supplied ++ repeat LZero))

    checkCtorArity g constructor supplied = do
      st <- get
      assignments <- gets csLevelAssignments
      let telescope = ciUniverses constructor
          owner = ciData constructor
          ownerDefinition = Map.lookup owner (csGlobals st)
          ownerTelescope = maybe emptyDeclarationUniverseTelescope gdUniverses ownerDefinition
          ownerInterfaceTerms =
            maybe [] (globalUniverseInterfaceTerms st owner) ownerDefinition
          ownerProvisionalMetas =
            nub (concatMap (levelMetasOfTerm . zonkLevels assignments) ownerInterfaceTerms)
          constructorProvisionalMetas =
            nub (levelMetasOfTerm (zonkLevels assignments (ciType constructor)))
          ownerExpected
            | dutExplicit ownerTelescope
                || owner `Set.member` csFinalizedUniverseInterfaces st =
                dutParameterCount ownerTelescope
            | otherwise = length ownerProvisionalMetas
          constructorExpected
            | g `Set.member` csFinalizedUniverseInterfaces st =
                dutParameterCount telescope
            | otherwise =
                ownerExpected
                  + length (constructorProvisionalMetas \\ ownerProvisionalMetas)
          found = length supplied
      when (ownerExpected /= found) $
        errAt sp "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
          ("constructor '" <> gnameText g <> "' expects " <> T.pack (show ownerExpected)
            <> " enclosing-data universe arguments, but this instantiation supplies " <> T.pack (show found))
      let ownerArguments = take ownerExpected (supplied ++ repeat LZero)
          inferredCount = max 0 (constructorExpected - ownerExpected)
      inferredArguments <- replicateM inferredCount freshLevelInstantiationMeta
      pure (ownerArguments ++ inferredArguments)

    checkLocalArity entry telescope supplied = do
      let expected = dutParameterCount telescope
          found = length supplied
      when (expected /= found) $
        errAt sp "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
          ("local declaration '" <> ceName entry <> "' expects " <> T.pack (show expected)
            <> " universe arguments, but this instantiation supplies " <> T.pack (show found))
      pure (take expected (supplied ++ repeat LZero))

-- Constructors as values: λ-wrap to a saturated source-shaped 'CCtor'. KCore
-- keeps explicit fields, including explicit erased fields, so the interpreter
-- and conversion continue to see source pattern arity. Only the KCore →
-- KBackendIR lowering physically drops runtime-erased fields.
--
-- The native backend recognises a saturated application of this shape and
-- beta-reduces it back to a direct 'CCtor' ('Kappa.Backend.IR.coreEtaCtorApp');
-- that recognizer depends on the exact shape produced here (nested 'CLam's
-- whose body is a 'CCtor' selecting the Core constructor payload binders by bare
-- 'CVar'), so keep the two in sync.
etaCtor :: EvalCtx -> GName -> [Level] -> Term -> Term
etaCtor ec g universes cty = build 0 [] (eval ec [] cty)
  where
    build n acc fty = case force ec fty of
      VPiM mode ic q _ name dom clo ->
        CLamM mode ic q ("x" <> T.pack (show n)) $
          build (n + 1) ((n, ic, coreCtorPayloadField ec n ic q dom, name) : acc) (evalClosure clo (VRigid n []))
      _ ->
        -- KBackendIR Stage 0 / Perceus S1.3: annotate the saturated 'CCtor'
        -- with the constructor's TYPE telescope ('cty', a closed top-level term)
        -- so KBackendIR lowering can recover the field count/layout via
        -- 'Repr.ctorLayoutOf' (the runtime fields are this telescope's
        -- non-erased explicit payloads plus non-erased implicit evidence).
        -- Observe-only metadata for KCore equality/conversion; KBackendIR reads it
        -- when attaching layout facts, but it cannot change tag ids or evaluation.
        CCtorI g universes (Just cty)
          [ ConstructorArg ic payload (Just name) (CVar (n - 1 - i))
          | (i, ic, payload, name) <- reverse acc
          ]
    evalClosure (Closure env body) v = eval ec (v : env) body
    coreCtorPayloadField ctx lvl ic q dom =
      ic == Expl || Repr.runtimeConstructorField ctx lvl ic q dom

-- | §3.2.2 suggestion edit-distance threshold for a spelling of this
-- length. Scales with the length so a one-character name does not match
-- every other one-character name. Used both to bound the candidate
-- buckets ('scopeNamesNear') and to filter by edit distance below.
suggestionThreshold :: Int -> Int
suggestionThreshold tlen = max 1 (min 2 (tlen `div` 3))

-- | §3.2.2 typo suggestions: in-scope names within a small edit distance
-- of the unresolved spelling, nearest first (ties broken alphabetically
-- for determinism, §3.1.10). The threshold scales with the length so a
-- one-character name does not match every other one-character name.
-- @cands@ is expected to already be length-compatible (see
-- 'scopeNamesNear'); the length pre-filter is kept so the function is
-- correct on any candidate list.
closeSpellings :: Text -> [Text] -> [Text]
closeSpellings target cands =
  map snd $
    sort
      [ (d, c)
      | c <- cands
      , c /= target
      -- Levenshtein distance is at least the length difference, so a
      -- candidate whose length differs from the target by more than the
      -- threshold can never be within threshold. Skipping it before the
      -- O(len^2) edit-distance keeps the per-error cost proportional to
      -- the (small) set of length-compatible candidates rather than the
      -- whole scope (avoids an O(Nnames * Nscope * len^2) blowup when a
      -- dropped import breaks many references in a large module).
      , abs (T.length c - tlen) <= threshold
      , let d = editDistance tchars (T.unpack c)
      , d <= threshold
      ]
  where
    tchars = T.unpack target
    tlen = T.length target
    threshold = suggestionThreshold tlen

-- | Standard Levenshtein edit distance.
editDistance :: String -> String -> Int
editDistance a b = last (foldl transform [0 .. length a] b)
  where
    transform prevRow@(p0 : _) c =
      scanl compute (p0 + 1) (zip3 a prevRow (tail prevRow))
      where
        compute z (ca, dDiag, dLeft) =
          minimum [dLeft + 1, z + 1, dDiag + if ca == c then 0 else 1]
    transform [] _ = []

resolveName :: Ctx -> Name -> CheckM (Term, Value)
resolveName ctx name =
  case lookupCtx n ctx of
    Just (i, e)
      | Just localUniverses <- ceLocalUniverses e ->
          instantiateLocalDeclaration ctx (nameSpan name) i e localUniverses
      | otherwise -> pure (CVar i, ceType e)
    Nothing ->
      gets (Map.lookup n . csActiveUniverseSchema) >>= \case
        Just level -> do
          allowed <- gets csAllowSchemaLevelTerms
          if allowed
            then do
              typeLevel <- globalValueM prelTypeLevel []
              pure (CLevel level, typeLevel)
            else do
              errAt sp "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
                ("declaration-universe parameter '" <> n
                  <> "' is a rigid static level identity and may only occur in a universe-level expression (§11.1.2.3A.1)")
              anyHole ctx
        Nothing -> do
          st <- get
          case Map.lookup n (csScopeAmbig st) of
            Just gs -> do
              -- §3.2.2 kappa.name.ambiguous payload + §3.1.1A: every
              -- candidate MUST appear. The candidates are cross-module
              -- imports without stored declaration spans, so each is a
              -- related origin anchored at the use site naming its providing
              -- module, with candidateSitesAvailable=false recorded in the
              -- payload (§3.1.1A unavailable-origin clause).
              let cands = T.intercalate ", " (map gKey gs)
                  payload =
                    withPayloadField "name" n $
                      withPayloadField "candidates" cands $
                        withPayloadField "candidateSitesAvailable" "false" $
                          payloadKind "name-ambiguous"
                  candRels =
                    [ related RoleRejectedCandidateSite sp
                        ("candidate '" <> gKey candidate <> "'")
                    | candidate <- gs
                    ]
              report $
                withPayload payload $
                  withRelateds (related RoleUseSite sp ("'" <> n <> "' used here") : candRels) $
                    diag SevError StageElaborate "E_NAME_AMBIGUOUS" (Just "kappa.name.ambiguous") sp
                      ( "name '" <> n <> "' is ambiguous; it is provided by "
                          <> T.intercalate " and " (map gKey gs)
                          <> " (qualify the name or import it explicitly, Spec §7.1)"
                      )
              anyHole ctx
            Nothing -> do
              mg <- lookupGlobalName n
              case mg of
                Just g -> do
                  gateUnsafeResolved g sp
                  mt <- globalTermIn ctx sp g
                  case mt of
                    Just pair -> pure pair
                    Nothing -> failUnresolved
                Nothing -> failUnresolved
  where
    n = nameText name
    sp = nameSpan name
    failUnresolved = do
      st0 <- get
      cands <- nearScopeNames
      -- §3.2.2: if a close spelling exists, suggest it. The fix is
      -- 'maybe-applicable' — the renamed reference type-checks only if
      -- the candidate happens to fit, so it is not 'machine-applicable'.
      let near = take 1 (closeSpellings n cands)
          preludeWouldResolve =
            Map.member (GName preludeModule n) (csGlobals st0)
              || Map.member (GName preludeModule n) (csCtors st0)
          unresolvedMessage =
            if csPreludeDisabled st0 && preludeWouldResolve
              then
                "unresolved name '" <> n
                  <> "' (implicit prelude is disabled; add an explicit import from std.prelude if this name is intended)"
              else "unresolved name '" <> n <> "' (not in scope)"
          base =
            withPayload
              ( withPayloadField "name" n $
                  withPayloadField "inGeneratedSyntax" "false" $
                    maybe id (withPayloadField "suggestion") (listToMaybe near) $
                      payloadKind "name-unresolved"
              )
              $ withRelated (related RoleUseSite sp ("'" <> n <> "' used here"))
              $ diag SevError StageElaborate "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved") sp
                  unresolvedMessage
          withFixIt d = case near of
            (cand : _) ->
              withHelp ("did you mean '" <> cand <> "'?") $
                withFix
                  ( DiagnosticFix
                      ("replace '" <> n <> "' with '" <> cand <> "'")
                      FixMaybeApplicable
                      [SourceEdit (spanFile sp) sp cand]
                  )
                  d
            [] -> d
          withPreludeHint d =
            if csPreludeDisabled st0 && preludeWouldResolve
              then withHelp ("implicit prelude is disabled; import std.prelude." <> n <> " explicitly or enable the prelude") d
              else d
      report (withPreludeHint (withFixIt base))
      anyHole emptyCtxDummy
    -- §3.2.2 candidate spellings for this unresolved name: only the
    -- length-compatible module-level names (from the cached length-bucket
    -- index, so unbounded scope does not make each diagnostic O(Nscope)),
    -- plus the call-site-local binders, which vary per error and so are
    -- not part of the cached index. There are only a handful of locals,
    -- so merging them in stays cheap per diagnostic.
    nearScopeNames = do
      let threshold = suggestionThreshold (T.length n)
      modLevel <- scopeNamesNear n threshold
      let locals = [ceName e | e <- ctxEntries ctx]
      pure $
        if null locals
          then modLevel
          else Set.toList (Set.fromList (locals ++ modLevel))
    emptyCtxDummy = ctx

-- | Primitive universe spellings are selected only after ordinary name
-- resolution proves that no lexical, static-schema, imported, module-object,
-- or global binding owns the same namespace key. Backtick spelling has the
-- same key as an unquoted identifier, so no token-form exception is needed.
nameHasOrdinaryBinding :: Ctx -> Name -> CheckM Bool
nameHasOrdinaryBinding ctx name =
  case lookupCtx text ctx of
    Just _ -> pure True
    Nothing -> do
      state <- get
      if Map.member text (csActiveUniverseSchema state)
          || Map.member text (csScopeAmbig state)
          || isJust (resolveModuleObjectName state text)
        then pure True
        else isJust <$> lookupGlobalName text
  where
    text = nameText name

resolveOrdinaryTermName :: Ctx -> Name -> CheckM (Term, Value)
resolveOrdinaryTermName ctx name =
  case lookupCtx (nameText name) ctx of
    Just (_, entry)
      | Just _ <- ceVarInfo entry -> varReadBlocked ctx name (nameSpan name)
    _ -> resolveName ctx name

inferRefFacet :: Ctx -> Name -> Span -> CheckM (Term, Value)
inferRefFacet ctx n sp =
  case lookupCtx (nameText n) ctx of
    Just (i, e)
      | Just _ <- ceVarInfo e ->
          pure (CVar i, ceType e)
      | otherwise -> do
          errMutableBinding sp "E_VAR_REF_REQUIRED" (nameText n) "reference" [("sourceOperation", "ref")]
            ("'ref " <> nameText n <> "' requires '" <> nameText n <> "' to be a mutable var binding introduced by 'var' (§18.6.1)")
          anyHole ctx
    Nothing -> do
      errAt (nameSpan n) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
        ("unresolved mutable var binding '" <> nameText n <> "' in 'ref " <> nameText n <> "'")
      anyHole ctx

inferVarRead :: Ctx -> Name -> Span -> CheckM (Term, Value)
inferVarRead ctx n sp =
  case lookupCtx (nameText n) ctx of
    Just (i, e)
      | Just info <- ceVarInfo e -> do
          let evidenceShift = i + 1
              refDict = shiftTerm evidenceShift 0 (vriMonadRefDict info)
              aTm = shiftTerm evidenceShift 0 (vriStoredTypeTerm info)
              refTm = CVar i
          case monadResultType (vriMonadType info) (vriStoredType info) of
            Just actionTy ->
              pure
                ( monadRefReadAction refDict aTm refTm
                , actionTy
                )
            Nothing -> do
              errAt sp "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
                ("mutable variable '" <> nameText n <> "' uses a higher-order monad shape this implementation cannot apply for generated reads (§18.6.1)")
              anyHole ctx
      | otherwise -> do
          errMutableBinding sp "E_VAR_READ_OUTSIDE_DO" (nameText n) "current-value" [("sourceOperation", "generated read")]
            ("internal current-value read for '" <> nameText n <> "' does not refer to a mutable var binding (§18.6.1)")
          anyHole ctx
    Nothing -> do
      errAt (nameSpan n) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
        ("unresolved mutable var binding '" <> nameText n <> "' in generated current-value read")
      anyHole ctx

varReadBlocked :: Ctx -> Name -> Span -> CheckM (Term, Value)
varReadBlocked ctx n sp = do
  let (code, blockedBy, msg) = case ctxVarReadBlock ctx of
        Just VarReadCrossesBoundary ->
          ( "E_VAR_READ_CROSSES_BOUNDARY"
          , "expression-lifting-boundary"
          , "mutable variable '" <> nameText n
              <> "' is a current-value occurrence here, but elaborating the generated read would cross a user-written lambda, local function, quote, type, or delayed-evaluation boundary; bind a snapshot before the boundary, use an inner do block, or write 'ref "
              <> nameText n <> "' to select the reference cell (§18.3.1, §18.6.1)"
          )
        Just VarReadStaticPosition ->
          ( "E_VAR_IN_STATIC_POSITION"
          , "static-position"
          , "mutable variable '" <> nameText n
              <> "' is a current-value occurrence in a type, static, erased, implicit-search, or elaboration-time position that cannot perform object-phase reads; bind a snapshot first or write 'ref "
              <> nameText n <> "' where a reference cell is required (§18.3.1, §18.6.1)"
          )
        _ ->
          ( "E_VAR_READ_OUTSIDE_DO"
          , "outside-do"
          , "mutable variable '" <> nameText n
              <> "' is a current-value occurrence here, but this expression is not in a do-item lifting position; use 'ref "
              <> nameText n <> "' to select the reference cell, or bind a snapshot inside an explicit do (§18.3.1, §18.6.1)"
          )
  infoFields <- mutableBindingLookupFields ctx n "user-written"
  errMutableBinding sp code (nameText n) "current-value"
    (infoFields ++ [("sourceOperation", "current read"), ("repair", "ref " <> nameText n), ("blockedBy", blockedBy)])
    msg
  case lookupCtx (nameText n) ctx of
    Just (_, entry)
      | Just info <- ceVarInfo entry -> do
          -- Blocking the object-phase read invalidates the term, not the
          -- mutable binding's authenticated stored type. Preserve that type
          -- in recovery so an expected static classifier can still constrain
          -- the declaration that introduced the cell; returning 'anyHole'
          -- here loses the relation and causes derivative literal ambiguity.
          recovery <- freshMeta
          pure (recovery, vriStoredType info)
    _ -> anyHole ctx

-- | §3.2.2 typo-suggestion candidate index, bucketed by spelling length:
-- the import scope plus this module's own globals. A single dropped
-- import can leave thousands of references unresolved, each raising a
-- suggestion diagnostic; rebuilding and rescanning the whole scope per
-- diagnostic is O(Nerrors * Nscope). The index is built once here (on the
-- first unresolved name) and thereafter extended incrementally in
-- 'addGlobal' as the module's own globals appear, so the build is paid
-- once. Bucketing by length lets each diagnostic consult only the
-- length-compatible candidates (Levenshtein distance is at least the
-- length difference), bounding the per-error scan. Entering a new module
-- clears the index (Pipeline / TestHarness), since scope and module change.
moduleScopeNameIndex :: CheckM (Map Int (Set Text))
moduleScopeNameIndex = do
  st <- get
  case csScopeNameCache st of
    Just idx -> pure idx
    Nothing -> do
      let scope = Map.keys (csScope st)
          own = [nm | GName m nm <- Map.keys (csGlobals st), m == csModule st]
          idx = foldr insertScopeName Map.empty (scope ++ own)
      modify' $ \s -> s {csScopeNameCache = Just idx}
      pure idx

-- | The length-compatible §3.2.2 candidates for a target spelling: only
-- names whose length is within @threshold@ of the target can be within
-- edit distance @threshold@, so only those buckets are gathered.
scopeNamesNear :: Text -> Int -> CheckM [Text]
scopeNamesNear target threshold = do
  idx <- moduleScopeNameIndex
  let tlen = T.length target
      buckets =
        [ s
        | len <- [tlen - threshold .. tlen + threshold]
        , Just s <- [Map.lookup len idx]
        ]
  pure (Set.toList (Set.unions buckets))

-- | Does a name resolve at all (locals or globals)? Used for §6.3.4
-- literal-prefix resolution, which is ordinary term name resolution.
prefixResolves :: Ctx -> Text -> CheckM Bool
prefixResolves ctx n =
  case lookupCtx n ctx of
    Just _ -> pure True
    Nothing -> do
      mg <- lookupGlobalName n
      pure (maybe False (const True) mg)

-- universe spellings: Type, Type0, Type1, ..., and '*' (§11.1)
sortName :: Text -> Maybe Level
sortName t
  | t == "Type" || t == "*" = Just LZero
  | t == "Typeω" = Just LOmega
  | Just rest <- T.stripPrefix "Type" t
  , not (T.null rest)
  , T.all (\c -> c >= '0' && c <= '9') rest
  , -- bounds check: a suffix this long would overflow 'Int'; treat the
    -- spelling as an ordinary (unresolved) identifier instead
    T.length rest <= 9 =
      Just (finiteLevel (read (T.unpack rest) :: Integer))
  | otherwise = Nothing

-- | Establish the semantic identity of an already-typed first-class
-- @TypeLevel@ term. Canonical arithmetic remains structural solver syntax;
-- every other stable term becomes one alpha-stable neutral atom after
-- ordinary beta/delta/iota normalization. This is the single checkpoint used
-- both by @Type e@ and by dependent applications whose domain is TypeLevel.
levelIdentityOfCheckedTerm
  :: Ctx
  -> Term
  -> CheckM (Term, Either (Term, Text) Level)
levelIdentityOfCheckedTerm ctx tm0 = do
  flushPending
  tm <- zonkTermM (ctxLen ctx) tm0
  st0 <- get
  let ec0 = ecOf st0
      semanticValue = force ec0 (eval ec0 (ctxEnv ctx) tm)
  case localProjectionValueLevel semanticValue of
    Just level -> pure (tm, Right (normalizeLevel level))
    Nothing -> coreTypeLevel ctx tm >>= \case
      Just level -> pure (tm, Right (normalizeLevel level))
      Nothing -> do
        -- A neutral level atom is serialized into declaration interfaces and
        -- must therefore have the same identity in the defining module and at
        -- every importing site.  Opaque definitions are temporarily reducible
        -- while their module is checked (§8.5.2), but their implementation may
        -- not leak into that public identity.  Normalize with precisely those
        -- definitions sealed while retaining ordinary beta/delta/iota
        -- reduction for transparent definitions.
        st <- get
        let sealedGlobals =
              Map.mapWithKey
                (\g gd ->
                   if Map.member g (csOpaqueDefs st)
                     then gd {gdReducible = False}
                     else gd)
                (csGlobals st)
            ec = (ecOf st) {ecGlobals = Globals sealedGlobals}
            normalized = quote ec (ctxLen ctx) (force ec (eval ec (ctxEnv ctx) tm))
        coreTypeLevel ctx normalized >>= \case
          Just level -> pure (tm, Right (normalizeLevel level))
          Nothing
            | not (termScopedAt (ctxLen ctx) normalized) ->
                reject normalized "the normalized level term is not scoped at this checkpoint"
            | not (null (metaIdsOf normalized) && null (levelMetasOfTerm normalized)) ->
                reject normalized "the normalized level term contains unresolved metavariables"
            | otherwise ->
                case coreToNeutralLevelTerm (ctxLen ctx) normalized of
                  Nothing ->
                    reject normalized "the stable level term has no canonical KCore serialization"
                  Just artifact
                    | any mutableLocal (neutralLevelTermLocals artifact) ->
                        reject normalized "the level term depends on a mutable current-value facet"
                    | otherwise ->
                        pure (tm, Right (LNeutral (neutralLevelTermAtom artifact)))
  where
    reject normalized reason = pure (tm0, Left (normalized, reason))

    mutableLocal level =
      let index = ctxLen ctx - level - 1
       in case drop index (ctxEntries ctx) of
            entry : _ | index >= 0 -> isJust (ceVarInfo entry)
            _ -> True

reportInvalidLevelTerm :: Span -> Text -> Term -> Text -> CheckM ()
reportInvalidLevelTerm sp source normalized reason =
  report $
    withPayload
      ( withPayloadField "sourceExpression" source $
          withPayloadField "expectedClassifier" "TypeLevel" $
            withPayloadField "normalizedExpression" (renderTerm normalized) $
              withPayloadField "reason" reason $
                withPayloadField "transparentReductionAttempted" "true" $
                  withPayloadField "normalizationBlockedBy" reason $
                    payloadKind "universe-level-expression"
      ) $
      diag SevError StageElaborate "E_UNIVERSE_LEVEL_EXPRESSION"
        (Just "kappa.universe.level-expression") sp
        "a Type index must be a stable, total, serializable TypeLevel term (§11.1.1)"

-- | Evaluate an application argument for a dependent Pi closure. TypeLevel
-- binders receive the same static identity that @Type e@ assigns, while the
-- emitted Core application retains the ordinary first-class term. Without
-- this bridge a neutral argument leaves an @LVar@ unsubstituted in the
-- codomain and can mis-type a valid application.
checkedArgumentValue :: Ctx -> Span -> Value -> Term -> CheckM Value
checkedArgumentValue ctx sp domain term = do
  isLevel <- isTypeLevelValue domain
  if not isLevel
    then do
      let requiresContextualReplay =
            not (null (metaIdsOf term) && null (levelMetasOfTerm term))
      replayable <-
        if requiresContextualReplay
          then zonkTermM (ctxLen ctx) term
          else pure term
      evalIn ctx replayable
    else do
      (_, result) <- levelIdentityOfCheckedTerm ctx term
      case result of
        Right level -> pure (VLevel level)
        Left (normalized, reason) -> do
          reportInvalidLevelTerm sp (renderTerm term) normalized reason
          pure (VLevel LZero)

-- | Elaborate the index of the primitive @Type e@ family. The source term is
-- checked through ordinary resolution and instance selection. Canonical
-- arithmetic is retained in the solver language; every other admitted term
-- receives its structural neutral identity at 'levelIdentityOfCheckedTerm'.
-- The reserved @ω@ token is the sole lexical introduction form and cannot be
-- shadowed.
elabLevelExpr :: Ctx -> Expr -> CheckM (Term, Level)
elabLevelExpr ctx e = do
  schemaLevels <- gets csActiveUniverseSchema
  canonical <- canonicalStandardLevelExpression ctx schemaLevels e
  (tm0, typingFailed, typingFailureReported) <- case (canonical, e) of
    (Just level, _) -> pure (CLevel level, False, False)
    (Nothing, EVar n)
      | Nothing <- lookupCtx (nameText n) ctx
      , Just level <- Map.lookup (nameText n) schemaLevels ->
          pure (CLevel level, False, False)
      | nameText n == "ω" -> (\tm -> (tm, False, False)) <$> globalHeadM prelTypeLevelOmega
    _ -> do
      typeLevel <- globalValueM prelTypeLevel []
      -- A rigid declaration-universe parameter is not a term binder, but it
      -- may occur inside this canonical level-expression checkpoint. Enable
      -- it only while elaborating the candidate spine; the identity-based
      -- authorization below still rejects every non-standard operator.
      previous <- gets csAllowSchemaLevelTerms
      diagnosticsBefore <- gets (length . csDiags)
      modify' $ \st -> st {csAllowSchemaLevelTerms = True}
      candidate <- check ctx e typeLevel
      modify' $ \st -> st {csAllowSchemaLevelTerms = previous}
      diagnosticsAfter <- gets (length . csDiags)
      let addedCount = diagnosticsAfter - diagnosticsBefore
      added <- gets (take addedCount . csDiags)
      let failed = any ((== SevError) . dSeverity) added
          preciseMutableFailure = any ((== "E_VAR_IN_STATIC_POSITION") . dCode) added
      when (failed && not preciseMutableFailure) $
        modify' $ \st -> st {csDiags = drop addedCount (csDiags st)}
      pure (candidate, failed, preciseMutableFailure)
  if typingFailed
    then do
      unless typingFailureReported $ do
        tm <- zonkTermM (ctxLen ctx) tm0
        reportInvalidLevelTerm (exprSpan e) (renderExprSrc e) tm
          "the level expression does not have type TypeLevel"
      -- The rejected source term may be an object-phase action (notably a
      -- blocked mutable-current read) and can retain inference metas. Never
      -- embed it in the recovered static family application: doing so makes
      -- declaration closeout diagnose derivative ambiguity and serialization
      -- failures. The reported source error owns the failure; @Type 0@ is the
      -- well-formed recovery placeholder.
      pure (CLevel LZero, LZero)
    else do
      (tm, identity) <- levelIdentityOfCheckedTerm ctx tm0
      case identity of
        Right level -> pure (tm, level)
        Left (normalized, reason) -> do
          reportInvalidLevelTerm (exprSpan e) (renderExprSrc e) normalized reason
          pure (tm, LZero)

-- | Elaborate the canonical TypeLevel value language before generic
-- overloaded application can replace a rigid declaration-schema argument by
-- a recovery metavariable.  Every accepted head is authenticated by resolved
-- global identity (including checked transparent aliases), and every operand
-- recursively passes the ordinary TypeLevel checkpoint.  The result is the
-- canonical static 'CLevel' form used by the solver and by KCore replay.
canonicalStandardLevelExpression :: Ctx -> Map Text Level -> Expr -> CheckM (Maybe Level)
canonicalStandardLevelExpression ctx schemaLevels = \case
  EIntLit value Nothing _
    | value >= 0 -> pure (Just (finiteLevel value))
  EApp headExpr arguments -> do
    operator <- canonicalHead headExpr
    case (operator, [argument | ArgExplicit argument <- arguments]) of
      (Just LevelOperatorSucc, [argument]) ->
        Just . levelSucc <$> levelOperand argument
      (Just LevelOperatorAdd, [lhs, rhs]) -> do
        lhsLevel <- levelOperand lhs
        rhsLevel <- levelOperand rhs
        pure (Just (levelAdd lhsLevel rhsLevel))
      (Just LevelOperatorMax, [lhs, rhs]) -> do
        lhsLevel <- levelOperand lhs
        rhsLevel <- levelOperand rhs
        pure (Just (levelMax lhsLevel rhsLevel))
      _ -> pure Nothing
  _ -> pure Nothing
  where
    levelOperand operand = case operand of
      EVar name
        | Nothing <- lookupCtx (nameText name) ctx
        , Just level <- Map.lookup (nameText name) schemaLevels -> pure level
      _ -> snd <$> elabLevelExpr ctx operand

    canonicalHead = \case
      EVar name -> do
        state <- get
        let text = nameText name
            shadowed =
              isJust (lookupCtx text ctx)
                || Map.member text schemaLevels
                || Map.member text (csScopeAmbig state)
                || isJust (resolveModuleObjectName state text)
        if shadowed
          then pure Nothing
          else
            lookupGlobalName text >>= \case
              Just global
                | global == prelTypeLevelSucc || global == prelSucc -> pure (Just LevelOperatorSucc)
                | global == prelTypeLevelAdd || global == gPrel "+" || global == gPrel "add" -> pure (Just LevelOperatorAdd)
                | global == prelTypeLevelMax || global == prelMaxOp -> pure (Just LevelOperatorMax)
                | otherwise -> resolveLevelOperatorAliasIdentity Set.empty global
              Nothing -> pure Nothing
      _ -> pure Nothing

inferUniverseApp :: Ctx -> Expr -> CheckM (Term, Value)
inferUniverseApp ctx levelExpr = do
  (_, lvl) <- elabLevelExpr ctx levelExpr
  pure (CSort lvl, VSort (levelSucc lvl))

-- | Recognize a level-bound proposition by resolved operation identity. The
-- checker does not trust the rendered operator name: a local/shadowed head
-- elaborates to a different Core identity and yields no assumption.
levelAssumptionFromExpr :: Ctx -> Maybe Term -> Expr -> CheckM (Maybe (Level, Level))
levelAssumptionFromExpr _ Nothing _ = pure Nothing
levelAssumptionFromExpr ctx (Just elaboratedEvidence) _source = do
  -- Explicit equality spellings may leave their carrier and selected
  -- ordering dictionary pending until both endpoints have constrained the
  -- application. Authenticate only the finalized Core proposition; the
  -- source spelling and a flexible evidence placeholder are not authority.
  flushPending
  finalizedEvidence <- zonkTermM (ctxLen ctx) elaboratedEvidence
  case boolEqualityTruePayload finalizedEvidence of
    Nothing -> pure Nothing
    Just relation ->
      typeLevelRelationOf ctx relation >>= \case
        Just (LevelOperatorLt, lhs, rhs) -> pure (Just (levelSucc lhs, rhs))
        Just (LevelOperatorLe, lhs, rhs) -> pure (Just (lhs, rhs))
        _ -> pure Nothing

-- | Select the least available explicit ceiling that proves an upper bound
-- for a component classifier. This deliberately consults only scoped proof
-- assumptions; ω is never inserted as an automatic ceiling.
ceilingLevel :: Ctx -> Level -> Level
ceilingLevel ctx lvl
  | null (levelVars normalized) && null (levelFields normalized) = normalized
  | otherwise = case candidates of
      [] -> normalized
      first : rest -> foldl choose first rest
  where
    normalized = normalizeLevel lvl
    edges = [(normalizeLevel lhs, normalizeLevel rhs) | (lhs, rhs) <- assumptionsList (ctxLevelAssumptions ctx)]
    -- Every level constructor is monotone. Closing a bounded number of rounds
    -- under contextual substitution derives, for example, `succ u <= succ ω`
    -- from `u <= ω` without inventing a global omega ceiling. The round bound
    -- prevents a cyclic/growing assumption from creating an infinite term
    -- sequence; the exact solver still validates every selected candidate.
    closure = take (length edges + 2) (iterate step [normalized])
    step prior = nub (prior ++ [replaceLevel lhs rhs term | term <- prior, (lhs, rhs) <- edges])
    candidates =
      nub
        [ candidate
        | candidate <- concat closure ++ map snd edges
        , candidate /= normalized
        , proveLevelLeq (ctxLevelAssumptions ctx) normalized candidate == Proved
        ]
    choose best candidate
      | proveLevelLeq (ctxLevelAssumptions ctx) candidate best == Proved = candidate
      | otherwise = best

    replaceLevel lhs rhs term
      | normalizeLevel term == lhs = rhs
      | otherwise = normalizeLevel $ case term of
          LSucc a -> LSucc (replaceLevel lhs rhs a)
          LAdd a b -> LAdd (replaceLevel lhs rhs a) (replaceLevel lhs rhs b)
          LMax a b -> LMax (replaceLevel lhs rhs a) (replaceLevel lhs rhs b)
          other -> other

isTypeLevelValue :: Value -> CheckM Bool
isTypeLevelValue v = forceM v >>= \case
  VGlobN g [] -> pure (g == prelTypeLevel)
  _ -> pure False

registerLevelField :: Ctx -> Text -> Value -> CheckM Ctx
registerLevelField ctx field ty = do
  isLevel <- isTypeLevelValue ty
  if not isLevel
    then pure ctx
    else do
      fieldId <- gets csNextLevelFieldId
      modify' $ \st -> st {csNextLevelFieldId = fieldId + 1}
      pure ctx {ctxLevelFieldIds = Map.insert field fieldId (ctxLevelFieldIds ctx)}

-- | Select and retain the formation judgment while the domain and source
-- annotation are available. Later phases consume this fact; they must not
-- reconstruct it from observation mode, quantity, or erasure.
selectFormationMode :: Ctx -> ObservationMode -> Value -> CheckM FormationMode
selectFormationMode ctx mode domain = do
  parametricKind <- isParametricKind (ctxLen ctx) domain
  pure $
    if mode == Parametric && parametricKind
      then FormationParametric
      else FormationOrdinary

formationContribution :: FormationMode -> Level -> Level
formationContribution formation classifier = case formation of
  FormationParametric -> LZero
  FormationOrdinary -> classifier

-- | Replace an internally-bound classifier by the least explicit ceiling
-- justified by assumptions in scope. The caller still verifies that no local
-- level identity escaped; this helper never invents an omega ceiling.
formationCeiling :: Ctx -> Level -> Level
formationCeiling ctx classifier
  | assumptionsConsistent (ctxLevelAssumptions ctx) = ceilingLevel ctx classifier
  | otherwise = LZero

-- | Raise a component type to the least scoped formation ceiling and retain
-- the exact solver derivation in KCore. Parametric components do not call this
-- helper: their classifier contributes zero by the modal formation rule and
-- no cumulative use of the component term occurred.
formationCeilingTerm :: Ctx -> Level -> Term -> (Term, Level)
formationCeilingTerm ctx classifier term =
  let target = formationCeiling ctx classifier
      evidence = solverUniverseEvidence (ctxLevelAssumptions ctx) classifier target
   in (universeLift evidence term, target)

reportUnboundedTelescope :: Ctx -> Span -> Text -> Text -> Level -> CheckM ()
reportUnboundedTelescope ctx sp kind0 component classifier = do
  -- An inconsistent scoped proof context has already received its primary
  -- universe-constraint diagnostic. It proves no ceiling (the pure solver
  -- fails closed on inconsistent assumptions), and reporting an additional
  -- unbounded telescope here would only be recovery noise.
  when (assumptionsConsistent (ctxLevelAssumptions ctx)) $ do
    let assumptions = renderLevelAssumptions (ctxLevelAssumptions ctx)
    let kind = case kind0 of
          "record telescope" -> "record"
          "existential telescope" -> "exists"
          "forall telescope" -> "pi"
          "dependent function" -> "pi"
          other -> other
        escaping = case levelVars classifier of
          v : _ -> "level#" <> T.pack (show v)
          [] -> case levelFields classifier of
            (_, field) : _ -> "this." <> field
            [] -> "unknown"
        repair = "add an earlier erased bound such as (@0 p : i < κ)"
    report $
      withPayload
        ( withPayloadField "telescopeKind" kind $
            withPayloadField "escapingVariable" escaping $
              withPayloadField "componentType" component $
                withPayloadField "componentClassifier" ("Type " <> renderLevel classifier) $
                  withPayloadField "levelAssumptions" assumptions $
                    withPayloadField "attemptedCeiling" "none" $
                      withPayloadField "reason" "no ceiling independent of the telescope variable exists" $
                        withPayloadField "binderOrigin" (T.pack (show sp)) $
                          withPayloadField "componentOrigin" (T.pack (show sp)) $
                            withPayloadField "suggestedRepair" repair $
                              payloadKind "universe-unbounded-telescope"
        ) $
        diag SevError StageElaborate "E_UNIVERSE_UNBOUNDED_TELESCOPE"
          (Just "kappa.universe.unbounded-telescope") sp
          ( kind0 <> " component '" <> component <> "' has classifier Type "
              <> renderLevel classifier
              <> " mentioning a level bound inside the telescope, with no outer-scope ceiling; "
              <> repair <> " (§11.1.2.8)"
          )

extendLevelAssumption :: Span -> Ctx -> Maybe (Level, Level) -> CheckM Ctx
extendLevelAssumption _ ctx Nothing = pure ctx
extendLevelAssumption sp ctx (Just (lhs, rhs)) = do
  let extended = insertAssumption lhs rhs (ctxLevelAssumptions ctx)
  case classifyAssumptions extended of
    Proved -> pure ctx {ctxLevelAssumptions = extended}
    Blocked _ -> pure ctx {ctxLevelAssumptions = extended}
    IndeterminateResourceLimit -> do
      report $
        withPayload
          ( withPayloadField "rejectedConstraint" (renderLevel lhs <> " <= " <> renderLevel rhs) $
              payloadKind "universe-inference-requires-annotation"
          ) $
          diag SevError StageElaborate "E_UNIVERSE_INFERENCE_REQUIRES_ANNOTATION"
            (Just "kappa.universe.inference-requires-annotation") sp
            "the scoped universe assumptions exceed the portable solver resource boundary"
      pure ctx {ctxLevelAssumptions = extended}
    Disproved -> rejectContradiction extended
    ContradictoryAssumptions -> rejectContradiction extended
  where
    rejectContradiction extended = do
      let rejected = renderLevel lhs <> " <= " <> renderLevel rhs
          -- A prior path may establish @succ rhs <= lhs@ transitively.  The
          -- rejected edge @lhs <= rhs@ then closes a strict cycle even when
          -- the two source expressions have different head identities.
          selfContainment =
            isNothing (compareClosedLevel lhs rhs)
              && proveLevelLeq (ctxLevelAssumptions ctx) (levelSucc rhs) lhs == Proved
          code =
            if selfContainment
              then "E_UNIVERSE_SELF_CONTAINMENT"
              else "E_UNIVERSE_CONSTRAINT_UNSATISFIABLE"
      report $
        withPayload
          ( withPayloadField "rejectedConstraint" rejected $
              withPayloadField "normalizedRejectedConstraint" rejected $
                withPayloadField "constraintOrigin" "erased level-comparison proof binder" $
                  withPayloadField "enclosingConstructKind" "telescope" $
                    withPayloadField "universeVariablesInScope" (T.pack (show (levelVars lhs ++ levelVars rhs))) $
                      withPayloadField "levelAssumptions" (renderLevelAssumptions extended) $
                        withPayloadField "selfContainment" (if selfContainment then "true" else "false") $
                          withPayloadField "failureKind" "explicit-level-evidence" $
                            withPayloadField "sourceOrigin" (T.pack (show sp)) $
                              payloadKind "universe-constraint"
          ) $
          diag SevError StageElaborate code
            (Just "kappa.universe.constraint") sp
            ( "the erased level bound " <> rejected
                <> " makes the scoped universe assumptions inconsistent (§11.1.2.2)"
            )
      -- Keep the rejected assumption in the recovery context. The exact
      -- solver treats an inconsistent context as proving nothing, while the
      -- marker lets later formation checks suppress cascaded diagnostics.
      pure ctx {ctxLevelAssumptions = extended}

-- | A synthesized erased proof metavariable is an obligation, not yet an
-- authority.  Its proposition may scope the dependent remainder of the
-- application, but an inconsistent proposition must not be diagnosed as
-- though the user had supplied established evidence.  The owning occurrence
-- or schema-lift check remains responsible for the dedicated failure.  Once
-- the proof term is solved, use the ordinary checked-assumption path.
extendLevelAssumptionFromSynthesized
  :: Span -> Ctx -> Maybe (Level, Level) -> Term -> CheckM Ctx
extendLevelAssumptionFromSynthesized sp ctx assumption proof = do
  st <- get
  if null (unsolvedMetasOf st proof)
    then extendLevelAssumption sp ctx assumption
    else pure $ case assumption of
      Nothing -> ctx
      Just (lhs, rhs) ->
        ctx {ctxLevelAssumptions = insertAssumption lhs rhs (ctxLevelAssumptions ctx)}

renderLevelAssumptions :: Assumptions -> Text
renderLevelAssumptions assumptions =
  T.intercalate ", "
    [renderLevel lhs <> " <= " <> renderLevel rhs | (lhs, rhs) <- assumptionsList assumptions]

anyHole :: Ctx -> CheckM (Term, Value)
anyHole ctx = do
  m <- freshMeta
  ty <- freshMetaV ctx
  pure (m, ty)

-- | §16.3.2 resolve an expression hole to its shared term metavariable and
-- type metavariable, recording this occurrence's span.
--
-- For an anonymous hole (@_@, 'Nothing') this is just 'anyHole': @_@ always
-- introduces a fresh hole, so anonymous holes are never tracked and never
-- shared. For a named hole (@?name@) all occurrences within one enclosing
-- declaration refer to the SAME metavariable (one @HoleId@): the first
-- occurrence creates the shared metas and later occurrences reuse them, so
-- the occurrences denote the same unknown and must elaborate at
-- definitionally equal expected types. Reset per declaration in
-- 'elabLetDecl'. Returns the shared metas plus the 'NamedHole' record (when
-- named) so a check-direction inconsistency can cite every occurrence.
holeMetas :: Ctx -> Maybe Name -> Span -> CheckM (Term, Value, Maybe NamedHole)
holeMetas ctx Nothing _ = do
  (m, ty) <- anyHole ctx
  pure (m, ty, Nothing)
holeMetas ctx (Just n) sp = do
  let nm = nameText n
  existing <- gets (Map.lookup nm . csHoles)
  case existing of
    Just nh -> do
      let nh' = nh {nhOccs = sp : nhOccs nh}
      modify' $ \st -> st {csHoles = Map.insert nm nh' (csHoles st)}
      pure (nhTerm nh', nhType nh', Just nh')
    Nothing -> do
      m <- freshMeta
      tyTerm <- freshMeta
      ty <- evalIn ctx tyTerm
      let nh =
            NamedHole
              { nhTerm = m
              , nhType = ty
              , nhTypeTerm = tyTerm
              , nhDepth = ctxLen ctx
              , nhOccs = [sp]
              }
      modify' $ \st -> st {csHoles = Map.insert nm nh (csHoles st)}
      pure (m, ty, Just nh)

-- | The display spelling of a hole (§16.3.2): @?name@ for a named hole,
-- @_@ for the anonymous hole.
holeSpelling :: Maybe Name -> Text
holeSpelling = maybe "_" (("?" <>) . nameText)

-- | §3.2.4 @E_HOLE_UNSOLVED@: report that an expression hole remains
-- unsolved, stating its expected type. Shared by both elaboration
-- directions so a hole reports the same payload whether it was inferred
-- (expected type = a fresh meta, rendered @_@ until solved) or checked
-- (expected type = the known checking type). The type term is zonked so a
-- solved expected type is shown concretely and an unsolved one renders as
-- the stable hole @_@ (§3.1.11).
reportUnsolvedHole :: Ctx -> Maybe Name -> Span -> Term -> CheckM ()
reportUnsolvedHole ctx mn =
  reportUnsolvedHoleAt (ctxLen ctx) (holeSpelling mn)

reportUnsolvedHoleAt :: Int -> Text -> Span -> Term -> CheckM ()
reportUnsolvedHoleAt depth holeName sp tyT = do
  tyTz <- zonkTermM depth tyT
  let
      expectedR = renderTerm tyTz
  report $
    -- §3.2.4 kappa.hole.unsolved payload: hole identifier + expected type.
    withPayload
      ( withPayloadField "hole" holeName $
          withPayloadField "expected" expectedR $
            payloadKind "hole-unsolved"
      )
      $ diag SevError StageElaborate "E_HOLE_UNSOLVED" (Just "kappa.hole.unsolved") sp
          ("hole " <> holeName <> " : " <> expectedR)

-- | Record the checked classifier of a named hole's shared term meta.
-- Arithmetic principalization and declaration-local generalization may assign
-- only metas whose creation-site classifier is known exactly; the fact that a
-- source token happened to be written as @?name@ is not type authority.
recordHoleClassifier :: Ctx -> Term -> Value -> CheckM ()
recordHoleClassifier ctx term classifier =
  case term of
    CMeta meta -> do
      classifierTerm <- quoteIn ctx classifier
      modify' $ \st ->
        st
          { csMetaClassifiers =
              Map.insertWith
                (\_ existing -> existing)
                meta
                (MetaClassifier (ctxLen ctx) classifierTerm Nothing)
                (csMetaClassifiers st)
          }
    _ -> pure ()

-- | §3.2.4 @E_HOLE_INCONSISTENT_EXPECTED_TYPE@ / family
-- @kappa.hole.inconsistent@: emitted when two occurrences of one named
-- hole receive expected types that are not definitionally equal
-- (unifying the shared type metavariable with the second occurrence's
-- expected type failed). The diagnostic cites every occurrence of the
-- hole (§16.3.2 MUST) and both distinct expected types.
reportInconsistentHole :: Ctx -> Name -> Span -> NamedHole -> Value -> CheckM ()
reportInconsistentHole ctx n sp nh expected = do
  -- the type the earlier occurrences agreed on (the shared meta, now
  -- solved to the first occurrence's expected type) versus this one.
  priorT <- quoteIn ctx (nhType nh) >>= zonkTermM (ctxLen ctx)
  thisT <- quoteIn ctx expected >>= zonkTermM (ctxLen ctx)
  let holeName = "?" <> nameText n
      priorR = renderTerm priorT
      thisR = renderTerm thisT
      -- every occurrence (nhOccs holds them most-recent first, including
      -- this one); cite each as a use-site related origin (§3.1.1A).
      rels = [related RoleUseSite osp ("occurrence of " <> holeName) | osp <- reverse (nhOccs nh)]
  report $
    withRelateds rels $
      withPayload
        ( withPayloadField "hole" holeName $
            withPayloadField "expected" priorR $
              withPayloadField "expected2" thisR $
                payloadKind "hole-inconsistent"
        )

        $ diag SevError StageElaborate "E_HOLE_INCONSISTENT_EXPECTED_TYPE"
            (Just "kappa.hole.inconsistent") sp
            ( "named hole " <> holeName <> " is used at inconsistent expected types: "
                <> priorR <> " and " <> thisR <> " (§16.3.2)"
            )

-- | Defer a type equality only while its exact pending evidence component is
-- unresolved.  This is shared by expression coercions and repeated binder
-- annotations: both may compare a selected dictionary with the placeholder
-- captured by an earlier signature occurrence.  The comparison is replayed
-- by 'flushDeferredTypeEqualities' after evidence selection, so no unresolved
-- dictionary is treated as definitionally equal.
deferTypeEqualityOnPendingEvidence
  :: Ctx
  -> Span
  -> Value
  -> Value
  -> Set MetaId
  -> CheckM Bool
deferTypeEqualityOnPendingEvidence ctx sp actual expected dependencies = do
  flushPendingSelected dependencies
  pendingAfter <-
    gets
      ( Set.fromList
          . map (\(meta, _, _, _, _) -> meta)
          . csPending
      )
  let unresolved = Set.intersection dependencies pendingAfter
  if Set.null unresolved
    then pure False
    else do
      modify' $ \state ->
        state
          { csDeferredTypeEqualities =
              DeferredTypeEquality
                { dteSpan = sp
                , dteCtx = ctx
                , dteActual = actual
                , dteExpected = expected
                , dteEvidenceDependencies = unresolved
                }
                : csDeferredTypeEqualities state
          }
      pure True

-- | Compare two types now when possible, otherwise retain the comparison
-- behind the evidence metas that actually block it.  This is deliberately
-- narrower than expression coercion: binder annotations admit no transport or
-- representation-changing conversion.
expectTypeAfterPendingEvidence :: Ctx -> Span -> Value -> Value -> CheckM ()
expectTypeAfterPendingEvidence ctx sp actual expected = do
  compatible <- tryTypeCompatibility ctx sp actual expected
  unless compatible $ do
    dependencies <- pendingEvidenceComponent ctx [actual, expected]
    deferred <-
      if Set.null dependencies
        then pure False
        else deferTypeEqualityOnPendingEvidence ctx sp actual expected dependencies
    unless deferred (expectType ctx sp actual expected)

-- | Check an inferred term against an expected type and make universe
-- cumulativity explicit in KCore. Evidence is frozen only when the check
-- produced no diagnostic; later level-meta finalization substitutes through
-- both the node endpoints and the evidence assumptions via 'zonkTermWith'.
coerceTerm :: Ctx -> Span -> Term -> Value -> Value -> CheckM Term
coerceTerm ctx sp term actual expected = do
  exact <- gets csDefinitionalEqualityOnly
  if exact
    then expectType ctx sp actual expected >> pure term
    else coerceNonExact
  where
    coerceNonExact = do
      rejectedImplicitSchema <- recordExpectedImplicitRecursiveSchema ctx sp term actual expected
      if rejectedImplicitSchema
        then pure term
        else
          tryNominalSchemaLift ctx sp term actual expected >>= \case
            Just lifted -> pure lifted
            Nothing -> do
              before <- gets (length . csDiags)
              compatible <- tryTypeCompatibility ctx sp actual expected
              contextualCompatible <-
                if compatible
                  then pure False
                  else
                    tryCheckedBranchCompatibility
                      ctx
                      sp
                      actual
                      expected
              canonicalProofCompatible <-
                if compatible || contextualCompatible
                  then pure False
                  else
                    tryCanonicalStandardArithmeticProofCompatibility
                      ctx
                      sp
                      actual
                      expected
              if compatible || contextualCompatible || canonicalProofCompatible
                then do
                  compatibleTerm <- finishCompatible before
                  canonicalizeProviderEqualityProof
                    ctx
                    actual
                    expected
                    compatibleTerm
                else
                  tryCoherentTraitEvidenceTransport ctx sp term actual expected >>= \case
                    Just transported ->
                      canonicalizeProviderEqualityProof
                        ctx
                        actual
                        expected
                        transported
                    Nothing -> do
                      tryArithmeticIndexTransport ctx sp term actual expected >>= \case
                        ArithmeticIndexTransportApplied transported ->
                          canonicalizeProviderEqualityProof
                            ctx
                            actual
                            expected
                            transported
                        ArithmeticIndexTransportBlocked dependencies ->
                          deferBlockedEquality dependencies
                        ArithmeticIndexTransportNotApplicable -> do
                          tryRefinementCoercion ctx sp term actual expected >>= \case
                            Just refined -> pure refined
                            Nothing -> do
                              blockedEvidence <- pendingEvidenceComponent ctx [actual, expected]
                              if Set.null blockedEvidence
                                then expectType ctx sp actual expected
                                else void (deferBlockedEquality blockedEvidence)
                              pure term

    deferBlockedEquality dependencies = do
      deferred <-
        deferTypeEqualityOnPendingEvidence
          ctx
          sp
          actual
          expected
          dependencies
      unless deferred (expectType ctx sp actual expected)
      pure term

    finishCompatible before = do
      after <- gets (length . csDiags)
      actual' <- forceM actual
      expected' <- forceM expected
      case (after == before, actual', expected') of
        (True, VSort from, VSort to) -> do
          universeEvidenceFor ctx sp from to >>= \case
            Just evidence -> pure (universeLift evidence term)
            Nothing -> pure term
        ( True
          , actualPi@(
              VPiEvidenceM
                actualMode
                _
                actualIcit
                actualQuantity
                actualBorrowed
                _
                actualAssumption
                _
                actualDomain
                actualClosure
              )
          , expectedPi@(
              VPiEvidenceM
                expectedMode
                _
                expectedIcit
                expectedQuantity
                expectedBorrowed
                expectedName
                expectedAssumption
                _
                expectedDomain
                expectedClosure
              )
          )
            | actualIcit == expectedIcit
            , not actualBorrowed
            , not expectedBorrowed
            , actualMode /= expectedMode
                || actualQuantity /= expectedQuantity -> do
                -- §16.1.7.1 permits directed subsumption only at the Pi's
                -- outer quantity/mode. Its domain and result remain
                -- definitionally equal, so eta expansion is the complete
                -- explicit Core representation of that accepted coercion.
                compatibleState <- get
                definitionallyEqual <-
                  unifyDefinitional ctx actualPi expectedPi
                if definitionallyEqual
                  then pure term
                  else do
                    put compatibleState
                    withExpectedAssumption <-
                      extendLevelAssumption sp ctx expectedAssumption
                    withBothAssumptions <-
                      extendLevelAssumption
                        sp
                        withExpectedAssumption
                        actualAssumption
                    let bodyCtx =
                          bindCtxMQ
                            expectedMode
                            expectedQuantity
                            expectedName
                            (expectedIcit == Impl)
                            expectedDomain
                            withBothAssumptions
                        argument = CVar 0
                        argumentValue = VRigid (ctxLen ctx) []
                    coercedArgument <-
                      coerceTerm
                        bodyCtx
                        sp
                        argument
                        expectedDomain
                        actualDomain
                    coercedArgumentValue <- evalIn bodyCtx coercedArgument
                    actualResult <- clApp actualClosure coercedArgumentValue
                    expectedResult <- clApp expectedClosure argumentValue
                    coercedBody <-
                      coerceTerm
                        bodyCtx
                        sp
                        (CApp actualIcit (shiftTerm 1 0 term) coercedArgument)
                        actualResult
                        expectedResult
                    pure
                      ( CLamM
                          expectedMode
                          expectedIcit
                          expectedQuantity
                          expectedName
                          coercedBody
                      )
        _ -> pure term

-- | Freeze a direct proof of one authenticated provider-normalizable
-- equality as the same replayable certificate used by synthesized evidence.
-- The checked source proof is not trusted as normalization authority:
-- 'providerLawProof' must independently replay the exact semantic law through
-- either the checked source evidence closure or ordinary coherent selection,
-- then recheck its complete type against this goal. Unsupported or unrelated
-- equalities retain their original checked proof term.
canonicalizeProviderEqualityProof
  :: Ctx
  -> Value
  -> Value
  -> Term
  -> CheckM Term
canonicalizeProviderEqualityProof ctx sourceGoal targetGoal fallback = do
  goal' <- forceM targetGoal
  case goal' of
    VGlobI equality _ [(_, carrier), (_, lhs), (_, rhs)]
      | equality == prelEqType ->
          canonicalize carrier lhs rhs
    VGlobN equality [(_, carrier), (_, lhs), (_, rhs)]
      | equality == prelEqType ->
          canonicalize carrier lhs rhs
    VCtor equality [carrier, lhs, rhs]
      | equality == prelEqType ->
          canonicalize carrier lhs rhs
    _ -> pure fallback
  where
    canonicalize carrier lhs rhs = do
      sourceGoalTerm <- quoteIn ctx sourceGoal
      providerLawProof
        ctx
        (Just sourceGoalTerm)
        (Just fallback)
        targetGoal
        carrier
        lhs
        rhs
        >>= \case
          Just certificate -> pure certificate
          Nothing -> pure fallback

-- | Bridge two spellings of one coherent trait-evidence value by ordinary
-- propositional transport (§15.8.2, §16.1.8).  This does not extend
-- conversion: it obtains @lhs = rhs@ from the compiler-issued
-- @IsTrait G => IsSubsingleton G@ path, substitutes that equality through the
-- source type, and rechecks the generated result against the expected type.
--
-- Candidate discovery is deliberately narrow.  Both endpoints must be
-- in-scope implicit values of the same normalized, authenticated trait goal,
-- and replacing one exact local root in the actual type must definitionally
-- produce the expected type.  All other cases fail closed.
tryCoherentTraitEvidenceTransport
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Value
  -> CheckM (Maybe Term)
tryCoherentTraitEvidenceTransport ctx site source actual expected =
  transactional . withDefinitionalEqualityOnly $ do
    actualTerm <- quoteIn ctx actual >>= zonkTermM (ctxLen ctx)
    expectedTerm <- quoteIn ctx expected >>= zonkTermM (ctxLen ctx)
    evidenceCandidates <-
      coherentTraitEvidenceTerms ctx [actualTerm, expectedTerm]
    selectedCandidates <-
      fmap catMaybes . forM evidenceCandidates $ \(_, evidenceType) -> do
        -- Selecting the deterministic representative is a premise of this
        -- transport, so the selection itself must not recursively rely on the
        -- transport being constructed.  The instance head is the same
        -- normalized trait application and therefore requires only ordinary
        -- definitional checking.
        withDefinitionalEqualityOnly (instanceSearch ctx site evidenceType) >>= \case
          Nothing -> pure Nothing
          Just selected -> do
            selected' <- zonkTermM (ctxLen ctx) selected
            pure (Just (selected', evidenceType))
    let candidates =
          nubBy
            (\(left, _) (right, _) -> left == right)
            (evidenceCandidates ++ selectedCandidates)
    firstSuccessful actualTerm
      [ (fromTerm, fromType, toTerm, toType)
      | (fromTerm, fromType) <- candidates
      , (toTerm, toType) <- candidates
      , fromTerm /= toTerm
      ]
  where
    firstSuccessful _ [] = pure Nothing
    firstSuccessful actualTerm ((fromTerm, evidenceType, toTerm, toType) : rest) = do
      let rewritten = replaceTermRoot fromTerm toTerm actualTerm
      if rewritten == actualTerm
        then firstSuccessful actualTerm rest
        else do
          saved <- get
          -- Both endpoints were independently authenticated as trait goals.
          -- Ordinary unification here is still definitional equality; unlike
          -- 'unifyDefinitional', it may instantiate the fresh universe metas
          -- introduced when the two declaration occurrences were specialized.
          sameEvidenceType <- unify ctx evidenceType toType
          if not sameEvidenceType
            then put saved >> firstSuccessful actualTerm rest
            else do
              rewrittenType <- evalIn ctx rewritten
              -- Replacing the one authenticated evidence root must account for
              -- the complete mismatch. Allow schema metas to specialize, but
              -- do not introduce any propositional equality at this gate.
              matches <- unify ctx rewrittenType expected
              if not matches
                then put saved >> firstSuccessful actualTerm rest
                else do
                  direct <-
                    withDefinitionalEqualityOnly
                      (unifyDefinitional ctx actual expected)
                  if direct
                    then pure (Just source)
                    else
                      coherentEvidenceEquality
                        ctx
                        site
                        evidenceType
                        fromTerm
                        toTerm
                        >>= \case
                          Nothing -> put saved >> firstSuccessful actualTerm rest
                          Just proof -> do
                            transported <-
                              buildTransportAlongEquality
                                ctx
                                site
                                "coherent trait evidence"
                                source
                                actual
                                expected
                                evidenceType
                                fromTerm
                                toTerm
                                proof
                            pure (Just transported)

    transactional action = do
      saved <- get
      diagnostics <- gets (length . csDiags)
      result <- action
      diagnostics' <- gets (length . csDiags)
      case result of
        Just value | diagnostics == diagnostics' -> pure (Just value)
        _ -> put saved >> pure Nothing

-- | Exact implicit locals and projection chains rooted in them whose inferred
-- classifiers are authenticated trait goals. Coherent evidence is not
-- restricted to a whole implicit local: a supertrait projection is itself an
-- evidence value and may be the exact dictionary captured by an overloaded
-- operation. The generic typed projection oracle is supplemented by the
-- standard-operation decoder, whose resolved operation identity and checked
-- telescope independently recover the exact evidence slot even when a nested
-- supertrait projection cannot be reconstructed in isolation. Restricting
-- candidates to those two typed evidence shapes avoids turning arbitrary
-- endpoint subterms into new instance-search triggers. Nested-binder nodes and
-- terms whose classifier cannot be reconstructed fail closed.
coherentTraitEvidenceTerms
  :: Ctx
  -> [Term]
  -> CheckM [(Term, Value)]
coherentTraitEvidenceTerms ctx endpoints = do
  let depth = ctxLen ctx
      candidates =
        nub
          [ node
          | endpoint <- endpoints
          , (nodeDepth, node) <-
              foldTermWithDepth
                (\nodeDepth node -> [(nodeDepth, node)])
                depth
                endpoint
          , nodeDepth == depth
          , implicitEvidenceProjection node
          ]
  projected <-
    fmap catMaybes . forM candidates $ \candidate ->
      coreTermClassifierInCtx ctx candidate >>= \case
        Nothing -> pure Nothing
        Just evidenceType -> do
          authenticated <- isTraitGoal evidenceType
          pure
            ( if authenticated
                then Just (candidate, evidenceType)
                else Nothing
            )
  operationEvidence <-
    concat <$> mapM (coherentArithmeticEvidenceOccurrences ctx) endpoints
  pure
    ( nubBy
        (\(left, _) (right, _) -> left == right)
        (projected ++ operationEvidence)
    )
  where
    implicitEvidenceProjection = \case
      CVar index ->
        maybe
          False
          ceImplicitLocal
          (listToMaybe (drop index (ctxEntries ctx)))
      CProjM _ receiver _ -> implicitEvidenceProjection receiver
      CProjAtM _ receiver _ _ -> implicitEvidenceProjection receiver
      CSealE _ receiver -> implicitEvidenceProjection receiver
      _ -> False


-- | Recover the classifier of an already checked Core term without freshening
-- any declaration occurrence. This is an observational query over the current
-- lexical context; unsupported terms return 'Nothing' and cannot influence
-- elaboration state.
coreTermClassifierInCtx :: Ctx -> Term -> CheckM (Maybe Value)
coreTermClassifierInCtx ctx term = do
  state <- get
  evaluator <- ec_
  pure
    ( observationTermTypeAt
        state
        evaluator
        (ctxLen ctx)
        (map observationBinding (ctxEntries ctx))
        term
    )
  where
    observationBinding entry =
      ObservationBinding
        { obMode = ceMode entry
        , obOrigin = Nothing
        , obType = Just (ceType entry)
        , obUniverses = luiTelescope <$> ceLocalUniverses entry
        , obDefinition = Nothing
        }

termContainsRoot :: Term -> Term -> Bool
termContainsRoot root =
  getAny
    . foldTermWithDepth
      (\depth node -> Any (node == shiftTerm depth 0 root))
      0

replaceTermRoot :: Term -> Term -> Term -> Term
replaceTermRoot fromTerm toTerm =
  mapTermWithDepth
    (\depth node ->
      if node == shiftTerm depth 0 fromTerm
        then Just (shiftTerm depth 0 toTerm)
        else Nothing)
    0

-- | Construct the canonical equality between two values of one authenticated
-- trait-evidence type.  The proof is the checked
-- @IsSubsingleton.allEqual lhs rhs@ projection reached through the intrinsic
-- @IsTrait@ supertrait edge.
coherentEvidenceEquality
  :: Ctx
  -> Span
  -> Value
  -> Term
  -> Term
  -> CheckM (Maybe Term)
coherentEvidenceEquality ctx site evidenceType lhsTerm rhsTerm = do
  authenticated <- isTraitGoal evidenceType
  if not authenticated
    then pure Nothing
    else do
      subsingletonGoal <-
        globalValueM prelIsSubsingleton [(Expl, evidenceType)]
      intrinsicTraitSubsingletonEvidence ctx site subsingletonGoal >>= \case
        Nothing -> pure Nothing
        Just subsingletonEvidence -> do
          (allEqual, allEqualType) <-
            knownTraitMemberProjection
              ctx
              site
              prelIsSubsingleton
              "allEqual"
              subsingletonGoal
              subsingletonEvidence
          lhs <- evalIn ctx lhsTerm
          rhs <- evalIn ctx rhsTerm
          (proof, proofType) <-
            applyGeneratedCoreSpine
              ctx
              site
              allEqual
              allEqualType
              [ (Expl, lhsTerm, evidenceType)
              , (Expl, rhsTerm, evidenceType)
              ]
          equality <-
            globalValueM
              prelEqType
              [(Impl, evidenceType), (Expl, lhs), (Expl, rhs)]
          -- The intrinsic evidence and the allEqual member have already been
          -- authenticated by exact global identities and applied through their
          -- checked telescopes. Their independently freshened universe schemas
          -- may nevertheless contain distinct unsolved metas, so solve those
          -- metas here before comparing the exact equality endpoints.
          valid <- unify ctx proofType equality
          pure (if valid then Just proof else Nothing)

-- | Proof-producing §15.8/§16.1.8 transport for one nominal index.
-- The recognizer is deliberately semantic and fail-closed:
--
-- * both types must have the same resolved nominal head and exactly one
--   differing argument;
-- * both index endpoints must have the same checked carrier;
-- * the ordinary proposition solver must produce explicit equality evidence;
--   and
-- * the final 'subst' application is rechecked against its evolving telescope.
--
-- The proposition solver authenticates selected providers and emits a
-- replayable certificate where applicable. This path never makes an
-- arithmetic law definitional and never guesses from operation spellings.
tryArithmeticIndexTransport
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Value
  -> CheckM ArithmeticIndexTransportResult
tryArithmeticIndexTransport ctx site source actual0 expected0 =
  transactional $ do
    actual <- forceM actual0
    expected <- forceM expected0
    singleArithmeticNominalIndexDifference ctx actual expected >>= \case
      Nothing ->
        pure ArithmeticIndexTransportNotApplicable
      Just (carrier, lhs, rhs, lhsTerm, rhsTerm) -> do
        equality <- globalValueM prelEqType [(Impl, carrier), (Expl, lhs), (Expl, rhs)]
        equalityTerm <- quoteIn ctx equality >>= zonkTermM (ctxLen ctx)
        propProofTerm ctx equalityTerm equality >>= \case
          Nothing -> do
            dependencies <-
              pendingEvidenceComponentTerms ctx [lhsTerm, rhsTerm]
            pure
              ( if Set.null dependencies
                  then ArithmeticIndexTransportNotApplicable
                  else ArithmeticIndexTransportBlocked dependencies
              )
          Just proof -> do
            ArithmeticIndexTransportApplied
              <$> buildSingleIndexTransport
                ctx
                site
                source
                actual
                expected
                carrier
                rhs
                lhsTerm
                proof
  where
    transactional action = do
      saved <- get
      diagnostics <- gets (length . csDiags)
      result <- action
      diagnostics' <- gets (length . csDiags)
      case result of
        ArithmeticIndexTransportApplied value
          | diagnostics == diagnostics' ->
              pure (ArithmeticIndexTransportApplied value)
        ArithmeticIndexTransportApplied _
          | diagnostics /= diagnostics' -> do
              put saved
              pure ArithmeticIndexTransportNotApplicable
        ArithmeticIndexTransportBlocked dependencies
          | diagnostics == diagnostics' -> do
              let baselinePending =
                    Set.fromList
                      [ meta
                      | (meta, _, _, _, _) <- csPending saved
                      ]
                  retained =
                    Set.intersection baselinePending dependencies
              put saved
              pure
                ( if Set.null retained
                    then ArithmeticIndexTransportNotApplicable
                    else ArithmeticIndexTransportBlocked retained
                )
        _ -> put saved >> pure ArithmeticIndexTransportNotApplicable

-- | Compare only the checked semantic spines of one nominal family. Matching
-- arguments must already be definitionally identical after zonking; the
-- transport path never solves unrelated metas while searching for a plan.
singleNominalIndexDifference
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe (Value, Value, Value, Term, Term))
singleNominalIndexDifference ctx actual expected = do
  depth <- pure (ctxLen ctx)
  actualTerm <- quoteIn ctx actual >>= zonkTermM depth
  expectedTerm <- quoteIn ctx expected >>= zonkTermM depth
  definitions <- gets csGlobals
  dataFamilies <- gets csDatas
  case
      ( declaredNominalApplication definitions dataFamilies actualTerm
      , declaredNominalApplication definitions dataFamilies expectedTerm
      ) of
    (Just (actualHead, actualUniverses, actualArgs), Just (expectedHead, expectedUniverses, expectedArgs))
      | actualHead == expectedHead
      , map normalizeLevel actualUniverses == map normalizeLevel expectedUniverses
      , length actualArgs == length expectedArgs -> do
          differences <-
            nominalArgumentDifferences ctx actualArgs expectedArgs
          finishDifference
            definitions
            actualHead
            actualUniverses
            actualArgs
            differences
    _ -> pure Nothing
  where
    finishDifference definitions global universes arguments = \case
      [(index, lhsTerm, rhsTerm)] ->
        nominalArgumentDomain ctx definitions global universes arguments index
          >>= \case
            Nothing -> pure Nothing
            Just carrier -> do
              lhs <- evalIn ctx lhsTerm
              rhs <- evalIn ctx rhsTerm
              pure
                (Just (carrier, lhs, rhs, lhsTerm, rhsTerm))
      _ -> pure Nothing

-- | The arithmetic-only widening of 'singleNominalIndexDifference'.
--
-- Independently fresh declaration-occurrence universe metas do not change the
-- identity of a nominal family or of a Nat/Integer index. Reconcile those
-- metas only after the post-erasure semantic spines expose exactly one
-- syntactically differing argument and that argument's checked family domain
-- is the exact arithmetic carrier. This ordering is both the principality
-- boundary and a performance boundary: generic constructor compatibility must
-- not enter arithmetic provider search merely because two occurrence
-- universe metas can be aliased.
singleArithmeticNominalIndexDifference
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe (Value, Value, Value, Term, Term))
singleArithmeticNominalIndexDifference ctx actual expected = do
  exact <- singleNominalIndexDifference ctx actual expected
  case exact of
    Just difference@(carrier, _, _, _, _) -> do
      carrierTerm <-
        quoteIn ctx carrier >>= zonkTermM (ctxLen ctx)
      pure
        ( case arithmeticDomainForCarrier carrierTerm of
            Just _ -> Just difference
            Nothing -> Nothing
        )
    Nothing -> do
      let depth = ctxLen ctx
      actualTerm <- quoteIn ctx actual >>= zonkTermM depth
      expectedTerm <- quoteIn ctx expected >>= zonkTermM depth
      definitions <- gets csGlobals
      dataFamilies <- gets csDatas
      case
          ( declaredNominalApplication definitions dataFamilies actualTerm
          , declaredNominalApplication definitions dataFamilies expectedTerm
          ) of
        (Just (actualHead, actualUniverses, actualArgs), Just (expectedHead, expectedUniverses, expectedArgs))
          | actualHead == expectedHead
          , length actualUniverses == length expectedUniverses
          , length actualArgs == length expectedArgs
          , [(index, lhsTerm, rhsTerm)] <-
              syntacticArgumentDifferences actualArgs expectedArgs -> do
              nominalArgumentDomain
                ctx
                definitions
                actualHead
                actualUniverses
                actualArgs
                index
                >>= \case
                  Nothing -> pure Nothing
                  Just carrier -> do
                    carrierTerm <- quoteIn ctx carrier >>= zonkTermM depth
                    case arithmeticDomainForCarrier carrierTerm of
                      Nothing -> pure Nothing
                      Just _ -> do
                        aligned <-
                          alignNominalOccurrenceUniverses
                            actualUniverses
                            expectedUniverses
                        if not aligned
                          then pure Nothing
                          else do
                            lhs <- evalIn ctx lhsTerm
                            rhs <- evalIn ctx rhsTerm
                            pure
                              (Just (carrier, lhs, rhs, lhsTerm, rhsTerm))
        _ -> pure Nothing
  where
    syntacticArgumentDifferences actualArgs expectedArgs =
      catMaybes
        [ if actualIcit /= expectedIcit
              || stripIdentityWrappers actualArgument
                   /= stripIdentityWrappers expectedArgument
            then Just (index, actualArgument, expectedArgument)
            else Nothing
        | (index, ((actualIcit, actualArgument), (expectedIcit, expectedArgument))) <-
            zip [0 :: Int ..] (zip actualArgs expectedArgs)
        ]

nominalArgumentDifferences
  :: Ctx
  -> [(Icit, Term)]
  -> [(Icit, Term)]
  -> CheckM [(Int, Term, Term)]
nominalArgumentDifferences ctx actualArgs expectedArgs =
  fmap catMaybes . forM
    (zip [0 :: Int ..] (zip actualArgs expectedArgs)) $
      \(index, ((actualIcit, actualArgument), (expectedIcit, expectedArgument))) ->
        if actualIcit /= expectedIcit
          then pure (Just (index, actualArgument, expectedArgument))
          else do
            same <- definitionallySameArgument actualArgument expectedArgument
            pure
              ( if same
                  then Nothing
                  else Just (index, actualArgument, expectedArgument)
              )
  where
    definitionallySameArgument lhs0 rhs0
      | lhs == rhs = pure True
      | otherwise = do
          checkpoint <- get
          lhsValue <- evalIn ctx lhs
          rhsValue <- evalIn ctx rhs
          same <- unifyDefinitional ctx lhsValue rhsValue
          put checkpoint
          pure same
      where
        lhs = stripIdentityWrappers lhs0
        rhs = stripIdentityWrappers rhs0

nominalArgumentDomain
  :: Ctx
  -> Map GName GlobalDef
  -> GName
  -> [Level]
  -> [(Icit, Term)]
  -> Int
  -> CheckM (Maybe Value)
nominalArgumentDomain ctx definitions global universes arguments target =
  case Map.lookup global definitions of
    Nothing -> pure Nothing
    Just definition -> do
      (_, familyType) <- specializeGlobalAt ctx global definition universes
      go 0 familyType arguments
  where
    go _ _ [] = pure Nothing
    go index familyType ((argumentIcit, argumentTerm) : rest) = do
      forced <- forceM familyType
      case forced of
        VPiEvidenceM
          _
          _
          binderIcit
          _
          _
          _
          _
          _
          domain
          closure
            | binderIcit == argumentIcit ->
                if index == target
                  then pure (Just domain)
                  else do
                    argument <- evalIn ctx argumentTerm
                    result <- clApp closure argument
                    go (index + 1) result rest
        _ -> pure Nothing

-- | Reconcile only hidden-universe metas authenticated as fresh declaration
-- occurrence specializations.  These metas are elaboration choices rather
-- than source universe parameters, so aliasing a bare occurrence meta to the
-- corresponding level of the same nominal family is principal.  Complex
-- equations and every source/generalizable meta remain rigid here; the
-- ordinary universe solver owns those cases.
alignNominalOccurrenceUniverses :: [Level] -> [Level] -> CheckM Bool
alignNominalOccurrenceUniverses actual expected = do
  state <- get
  let installed = csLevelAssignments state
      occurrenceMetas = csLevelInstantiationMetas state
      normalizeWith aliases =
        normalizeLevel
          . substituteLevelMetas (Map.union aliases installed)
      derive aliases [] = Just aliases
      derive aliases ((actualLevel0, expectedLevel0) : rest) =
        let actualLevel = normalizeWith aliases actualLevel0
            expectedLevel = normalizeWith aliases expectedLevel0
         in if actualLevel == expectedLevel
              then derive aliases rest
              else
                assign aliases actualLevel expectedLevel >>= \aliases' ->
                  derive aliases' rest
      assign aliases (LMeta actualMeta) expectedLevel
        | actualMeta `Set.member` occurrenceMetas
        , actualMeta `notElem` levelMetas expectedLevel =
            Just (Map.insert actualMeta expectedLevel aliases)
      assign aliases actualLevel (LMeta expectedMeta)
        | expectedMeta `Set.member` occurrenceMetas
        , expectedMeta `notElem` levelMetas actualLevel =
            Just (Map.insert expectedMeta actualLevel aliases)
      assign _ _ _ = Nothing
  case derive Map.empty (zip actual expected) of
    Nothing -> pure False
    Just aliases -> do
      unless (Map.null aliases) (installLevelAssignments aliases)
      pure True

-- | Decompose only a checked declaration with nominal identity. This shared
-- recognizer is intentionally exact: a source spelling, constructor name, or
-- structurally similar application cannot enter nominal result planning or
-- proof transport.
declaredNominalApplication
  :: Map GName GlobalDef
  -> Map GName DataInfo
  -> Term
  -> Maybe (GName, [Level], [(Icit, Term)])
declaredNominalApplication definitions dataFamilies term =
  let (headTerm, arguments) = spineOfTerm (stripIdentityWrappers term)
   in case stripIdentityWrappers headTerm of
        CGlobal global universes
          | Map.member global dataFamilies
              || maybe False (isJust . gdNominalSummary)
                   (Map.lookup global definitions) ->
              Just (global, universes, arguments)
        _ -> Nothing

buildSingleIndexTransport
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Value
  -> Value
  -> Value
  -> Term
  -> Term
  -> CheckM Term
buildSingleIndexTransport ctx site source actual expected carrier rhs lhsTerm proof = do
  lhsTerm' <- zonkTermM (ctxLen ctx) lhsTerm
  rhsTerm <- quoteIn ctx rhs >>= zonkTermM (ctxLen ctx)
  buildTransportAlongEquality
    ctx
    site
    "arithmetic index"
    source
    actual
    expected
    carrier
    lhsTerm'
    rhsTerm
    proof

-- | The shared proof-transport constructor.  The caller supplies a checked
-- equality between @lhs@ and @rhs@; this function builds the dependent motive
-- by replacing exact occurrences of @lhs@ in the source type, applies the
-- checked prelude @subst@ telescope, and validates the result type.
buildTransportAlongEquality
  :: Ctx
  -> Span
  -> Text
  -> Term
  -> Value
  -> Value
  -> Value
  -> Term
  -> Term
  -> Term
  -> CheckM Term
buildTransportAlongEquality
  ctx
  site
  transportKind
  source
  actual
  expected
  carrier
  lhsTerm
  rhsTerm
  proof =
  buildTransportAlongEqualityWithType
    ctx
    site
    transportKind
    Nothing
    source
    actual
    expected
    carrier
    lhsTerm
    rhsTerm
    proof

-- | Variant of 'buildTransportAlongEquality' for a caller that retains the
-- exact checked Core spelling of the source type. This matters when evaluation
-- and quotation preserve conversion but normalize away the syntactic evidence
-- root from which the dependent motive must be abstracted.
buildTransportAlongEqualityFromType
  :: Ctx
  -> Span
  -> Text
  -> Term
  -> Term
  -> Value
  -> Value
  -> Value
  -> Term
  -> Term
  -> Term
  -> CheckM Term
buildTransportAlongEqualityFromType
  ctx
  site
  transportKind
  sourceType
  source
  actual
  expected
  carrier
  lhsTerm
  rhsTerm
  proof =
  buildTransportAlongEqualityWithType
    ctx
    site
    transportKind
    (Just sourceType)
    source
    actual
    expected
    carrier
    lhsTerm
    rhsTerm
    proof

buildTransportAlongEqualityWithType
  :: Ctx
  -> Span
  -> Text
  -> Maybe Term
  -> Term
  -> Value
  -> Value
  -> Value
  -> Term
  -> Term
  -> Term
  -> CheckM Term
buildTransportAlongEqualityWithType
  ctx
  site
  transportKind
  sourceType
  source
  actual
  expected
  carrier
  lhsTerm
  rhsTerm
  proof = do
  actualTerm <-
    case sourceType of
      Just checked -> zonkTermM (ctxLen ctx) checked
      Nothing -> quoteIn ctx actual >>= zonkTermM (ctxLen ctx)
  expectedTerm <- quoteIn ctx expected >>= zonkTermM (ctxLen ctx)
  carrierTerm <- quoteIn ctx carrier >>= zonkTermM (ctxLen ctx)
  lhs <- evalIn ctx lhsTerm
  rhs <- evalIn ctx rhsTerm
  classifier <- equandType ctx carrier >>= \case
    Just value -> pure value
    Nothing -> freshMetaV ctx
  resultLevel <- typeValueClassifierLevel ctx actual >>= \case
    Just level -> pure level
    Nothing -> do
      errAt site "E_INTERNAL_ARITHMETIC_TRANSPORT" Nothing
        "the indexed source type has no checked universe classifier"
      pure LZero
  let shiftedActual = shiftTerm 1 0 actualTerm
      shiftedNeedle = shiftTerm 1 0 lhsTerm
      motiveBody =
        mapTermWithDepth
          (\depth node ->
             if node == shiftTerm depth 0 shiftedNeedle
               then Just (CVar depth)
               else Nothing)
          0
          shiftedActual
      motive = CLamM Ordinary Expl Q0 "__arithmetic_index" motiveBody
      motiveType =
        CPiFormedM
          Ordinary
          FormationOrdinary
          Expl
          Q0
          False
          "__arithmetic_index"
          carrierTerm
          (CSort resultLevel)
  motiveValue <- evalIn ctx motiveType
  equality <- globalValueM prelEqType [(Impl, carrier), (Expl, lhs), (Expl, rhs)]
  globalTerm prelSubst >>= \case
    Nothing -> do
      errAt site "E_INTERNAL_MISSING_PRELUDE_DECLARATION" Nothing
        "the checked prelude has no subst declaration"
      pure source
    Just (substHead, substType) -> do
      (transported, transportedType) <-
        applyGeneratedCoreSpine
          ctx
          site
          substHead
          substType
          [ (Impl, carrierTerm, classifier)
          , (Impl, motive, motiveValue)
          , (Impl, lhsTerm, carrier)
          , (Impl, rhsTerm, carrier)
          , (Expl, proof, equality)
          , (Expl, source, actual)
          ]
      -- The motive, equality evidence, and subst application were all built
      -- through checked telescopes. Permit the independently fresh universe
      -- schemas in that generated application to specialize before requiring
      -- the exact transported result type.
      final <- unify ctx transportedType expected
      unless final $
        errAt site "E_INTERNAL_ARITHMETIC_TRANSPORT" Nothing
          ( "the generated " <> transportKind
              <> " subst result does not match its expected type: "
              <> renderTerm expectedTerm
          )
      pure transported

-- | One coherent 'RefinementView' witness together with its associated base.
-- The dictionary is selected by ordinary evidence resolution; associated
-- members are projected through their checked observation modes.
refinementViewWitness
  :: Ctx
  -> Span
  -> Value
  -> CheckM (Maybe (Term, Value))
refinementViewWitness ctx site target = do
  candidate <- refinementViewMayResolve ctx target
  if not candidate
    then pure Nothing
    else do
      goal <- globalValueM (gPrel "RefinementView") [(Expl, target)]
      traitEvidence ctx site goal >>= \case
        Nothing -> pure Nothing
        Just dictionary -> do
          baseMode <- traitMemberObservationMode (gPrel "RefinementView") "Base"
          base <- evalIn ctx (CProjM baseMode dictionary "Base") >>= forceM
          pure (Just (dictionary, base))

-- | Cheap semantic candidate filter for the implicit refinement conversion.
-- Ordinary conversion failure is a hot path, so it must not launch full
-- instance/universe search when no 'RefinementView' dictionary can possibly
-- exist. Checked instance heads provide the nominal discriminator; a
-- variable-headed instance remains a conservative wildcard. Local evidence is
-- admitted only when its checked trait identity is 'RefinementView' or reaches
-- it through the declared supertrait graph.
refinementViewMayResolve :: Ctx -> Value -> CheckM Bool
refinementViewMayResolve ctx target = do
  state <- get
  targetTerm <- quoteIn ctx target
  let refinementTrait = gPrel "RefinementView"
      targetHead = nominalDataHead targetTerm
      instanceCandidate entry
        | ieTrait entry /= refinementTrait = False
        | otherwise =
            case ieHead entry of
              [headTerm] ->
                case nominalDataHead headTerm of
                  Nothing -> True
                  Just candidateHead -> Just candidateHead == targetHead
              _ -> False
      reachesRefinement seen trait
        | trait == refinementTrait = True
        | trait `Set.member` seen = False
        | otherwise =
            case Map.lookup trait (csTraits state) of
              Nothing -> False
              Just info ->
                any
                  ( maybe False
                      (reachesRefinement (Set.insert trait seen))
                      . traitClosureHead
                      . snd
                  )
                  (tiSupers info)
  localCandidates <-
    forM
      [entry | entry <- ctxEntries ctx, ceImplicitLocal entry]
      $ \entry ->
        forceM (ceType entry) >>= \case
          VGlobI trait _ _ ->
            pure
              ( Map.member trait (csTraits state)
                  && reachesRefinement Set.empty trait
              )
          _ -> pure False
  pure (any instanceCandidate (csInstances state) || or localCandidates)
  where
    traitClosureHead = \case
      CLamM _ _ _ _ body -> traitClosureHead body
      CApp _ function _ -> traitClosureHead function
      CUniverseLift _ _ _ term -> traitClosureHead term
      CSchemaLift _ _ _ _ _ _ _ _ term -> traitClosureHead term
      CGlobal global _ -> Just global
      CGlob global -> Just global
      _ -> Nothing

-- | Build the target refinement exactly once from an already-checked base
-- term. 'IsProp P(x)' establishes uniqueness only; the separate @P(x)@
-- resolution is mandatory and may fail with the ordinary proof-demand
-- diagnostic. The hidden strict let is the stable representative required by
-- §16.1.9: predicate formation, evidence, and construction all refer to the
-- same source evaluation.
constructRefinement
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Term
  -> [(Term, Term)]
  -> CheckM (Maybe Term)
constructRefinement ctx site sourceTerm baseType dictionary premises = do
  baseTypeTerm <- quoteIn ctx baseType
  sourceValue <- evalIn ctx sourceTerm
  let sourceName = "__refinement_source"
      sourceCtx =
        case ctxEntries knownSourceCtx of
          entry : rest ->
            knownSourceCtx
              { ctxEntries =
                  entry {ceCoreQ = QW} : rest
              }
          [] -> knownSourceCtx
      knownSourceCtx
        | null premises =
            -- Closed/base introduction benefits from local delta reduction:
            -- the predicate solver may compute directly from the source RHS.
            bindCtxLet sourceName False baseType sourceValue ctx
        | otherwise =
            -- Widening reasons about the one stable projected value under an
            -- explicit source-predicate proof. Keep that value rigid while
            -- proving the target; unfolding the let here would replace the
            -- shared arithmetic atom by the source wrapper's destructor and
            -- destroy the relation between premise and goal.
            bindCtxMQ Ordinary QW sourceName False baseType ctx
      dictionary' = shiftTerm 1 0 dictionary
      trait = gPrel "RefinementView"
  predicateMode <- traitMemberObservationMode trait "Predicate"
  refineMode <- traitMemberObservationMode trait "refine"
  (proofCtx, proofBindings) <-
    foldM
      (bindPremise predicateMode)
      (sourceCtx, [])
      (zip [0 :: Int ..] premises)
  let proofCount = length proofBindings
      source = CVar proofCount
      dictionary'' = shiftTerm proofCount 0 dictionary'
      predicateTerm =
        CApp Expl (CProjM predicateMode dictionary'' "Predicate") source
  normalizedPredicateTerm <-
    transparentProofReduce (ctxLen proofCtx) 96 predicateTerm
  predicate <- evalIn proofCtx normalizedPredicateTerm >>= forceM
  -- Reduction exposes the selected Predicate implementation on Core syntax
  -- without consulting the local environment, so the hidden source remains
  -- CVar 0. Use that exact term for both proof requests. Reconstructing either
  -- request from the evaluated predicate would delta-reduce the hidden let to
  -- its outer RHS and make the generated evidence refer to a different
  -- representative than the value passed to refine.
  isPropGoalTerm <-
    globalAppM prelIsProp [(Expl, normalizedPredicateTerm)]
  isPropGoal <- evalIn proofCtx isPropGoalTerm
  resolveRequiredImplicitTerm proofCtx site isPropGoalTerm isPropGoal >>= \case
    Nothing -> pure Nothing
    Just predicateIsProp ->
      resolveRequiredImplicitTerm
        proofCtx
        site
        normalizedPredicateTerm
        predicate >>= \case
        Nothing -> pure Nothing
        Just proof -> do
          let body =
                CApp Impl
                  ( CApp Impl
                      (CApp Expl (CProjM refineMode dictionary'' "refine") source)
                      predicateIsProp
                  )
                  proof
              withProofs =
                foldr
                  ( \(name, proposition, evidence) rest ->
                      CLetM Ordinary Q0 name proposition evidence rest
                  )
                  body
                  proofBindings
          -- The hidden binding preserves single evaluation, but its
          -- capability must match the generated `refine` base argument.
          -- V1's RefinementView contract leaves that binder unrestricted;
          -- recording Q1 here would let generated Core move a linear source
          -- through an unrestricted call without the source QTT check.
          recordImplicitExpressionDemand site QW
          pure (Just (CLetM Ordinary QW sourceName baseTypeTerm sourceTerm withProofs))
  where
    bindPremise
      predicateMode
      (activeCtx, bindings)
      (index, (premiseDictionary, premiseEvidence)) = do
        let depthDelta = 1 + length bindings
            dictionaryHere = shiftTerm depthDelta 0 premiseDictionary
            evidenceHere = shiftTerm depthDelta 0 premiseEvidence
            sourceHere = CVar (length bindings)
            proposition =
              CApp Expl
                (CProjM predicateMode dictionaryHere "Predicate")
                sourceHere
        normalized <-
          transparentProofReduce (ctxLen activeCtx) 96 proposition
        propositionValue <- evalIn activeCtx normalized
        let name = "__refinement_premise_" <> T.pack (show index)
            nextCtx =
              bindCtxMQ Ordinary Q0 name True propositionValue activeCtx
        pure (nextCtx, bindings ++ [(name, normalized, evidenceHere)])

-- | A refinement obligation is not an inferable erased parameter: §16.1.9
-- requires an actual evidence value at this boundary. Ordinary implicit
-- resolution may return a fresh inference meta for an erased non-trait goal,
-- so make that speculative attempt transactional and retain it only when the
-- resulting evidence is already fully determined.
resolveRequiredImplicit
  :: Ctx
  -> Span
  -> Value
  -> CheckM (Maybe Term)
resolveRequiredImplicit ctx site =
  resolveRequiredImplicitWithTerm ctx site Nothing

resolveRequiredImplicitTerm
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> CheckM (Maybe Term)
resolveRequiredImplicitTerm ctx site goalTerm =
  resolveRequiredImplicitWithTerm ctx site (Just goalTerm)

resolveRequiredImplicitWithTerm
  :: Ctx
  -> Span
  -> Maybe Term
  -> Value
  -> CheckM (Maybe Term)
resolveRequiredImplicitWithTerm ctx site sourceGoal goal = do
  saved <- get
  preferred goal >>= \case
    Just evidence -> pure (Just evidence)
    Nothing -> do
      put saved
      fallback goal >>= \case
        Just evidence -> pure (Just evidence)
        Nothing -> do
          put saved
          goalTerm <- checkedGoalTerm goal
          transparentProofNormalize (ctxLen ctx) goalTerm >>= \case
            Nothing -> pure Nothing
            Just normalized -> do
              normalizedGoal <- evalIn ctx normalized
              attempt normalizedGoal >>= \case
                Just evidence -> pure (Just evidence)
                Nothing -> put saved >> pure Nothing
  where
    preferred
      | isJust sourceGoal = compilerOwnedProof
      | otherwise = attempt

    fallback
      | isJust sourceGoal = attempt
      | otherwise = compilerOwnedProof

    compilerOwnedProof candidate = do
      settleRequiredProofDependencies ctx candidate
      refreshedTerm <- checkedGoalTerm candidate
      refreshed <- evalIn ctx refreshedTerm >>= forceM
      proof <- propProofTerm ctx refreshedTerm refreshed
      case proof of
        Just evidence -> pure (Just evidence)
        Nothing -> isPropClosureFromTerm ctx site sourceGoal refreshed

    attempt candidate = do
      evidence <- resolveImplicitQ ctx site Q0 candidate
      evidence' <- zonkTermM (ctxLen ctx) evidence
      state <- get
      pure $
        if null (unsolvedMetasOf state evidence')
          then Just evidence'
          else Nothing

    checkedGoalTerm candidate =
      maybe (quoteIn ctx candidate) pure sourceGoal
        >>= zonkTermM (ctxLen ctx)

recordImplicitExpressionDemand :: Span -> Q -> CheckM ()
recordImplicitExpressionDemand site quantity =
  modify' $ \state ->
    state
      { csImplicitExpressionDemands =
          Map.insert site quantity (csImplicitExpressionDemands state)
      }

-- | Resolve only postponed evidence that the required proposition or its
-- active branch facts actually mention. This is the local proof-demand
-- boundary: arithmetic facts checked earlier in the same expression may still
-- contain deferred @Ord@/@FromInteger@ dictionaries, but unrelated flexible
-- goals must remain pending for their declaration boundary.
settleRequiredProofDependencies :: Ctx -> Value -> CheckM ()
settleRequiredProofDependencies ctx goal = do
  goalTerm <- quoteIn ctx goal
  facts <- gets csBoolFacts >>= scopedBoolFactsAt (ctxLen ctx)
  let factTerms = map fst facts
  state <- get
  let reachable =
        Set.fromList
          (concatMap (unsolvedMetasOf state) (goalTerm : factTerms))
      pending =
        Set.fromList
          [meta | (meta, _, _, _, _) <- csPending state]
      selected = Set.intersection reachable pending
  unless (Set.null selected) $ do
    settleUniquePendingTraitComponent selected
    settleSelectedPendingProofDependencies selected

type PendingEvidenceEntry = (MetaId, Value, Span, Ctx, [ScopedBoolFact])

-- | Solve a connected set of demanded trait obligations only when bounded
-- transactional search yields one principal assignment for the component's
-- non-evidence metas. This handles associated-member cycles such as
-- @Contains (Rangeable.Range ?a) Nat@: neither goal is independently rigid,
-- but only @Rangeable Nat@ lets the complete component resolve.
--
-- Candidate enumeration is shared with ordinary instance search. Failed or
-- ambiguous searches restore the exact baseline, and the finite search stops
-- after a small deterministic budget; exceeding it is a conservative miss.
settleUniquePendingTraitComponent :: Set MetaId -> CheckM ()
settleUniquePendingTraitComponent selected = do
  baseline <- get
  let entries =
        [entry | entry@(meta, _, _, _, _) <- csPending baseline, meta `Set.member` selected]
      selectedMetas = Set.fromList [meta | (meta, _, _, _, _) <- entries]
      maxDepth = maximum (0 : [ctxLen pendingCtx | (_, _, _, pendingCtx, _) <- entries])
      typeMetas =
        Set.toAscList
          ( Set.difference
              ( Set.unions
                  [ Set.fromList
                      (unsolvedMetasOf baseline (quote (ecOf baseline) (ctxLen pendingCtx) goal))
                  | (_, goal, _, pendingCtx, _) <- entries
                  ]
              )
              selectedMetas
          )
  rawSolutions <- pendingTraitComponentSolutions 24 entries
  let keyed =
        List.foldl'
          ( \solutions solution ->
              Map.insertWith
                (\_ existing -> existing)
                (pendingComponentTypeKey maxDepth typeMetas solution)
                solution
                solutions
          )
          Map.empty
          (take 65 rawSolutions)
  case Map.elems keyed of
    [solution] -> put solution
    _ -> put baseline

pendingComponentTypeKey :: Int -> [MetaId] -> CheckState -> Text
pendingComponentTypeKey depth metas state =
  T.intercalate
    "\x1f"
    [ maybe "?" renderStructuralTermKey
        (resolvedMetaCore state (ecOf state) depth meta)
    | meta <- metas
    ]

pendingTraitComponentSolutions
  :: Int
  -> [PendingEvidenceEntry]
  -> CheckM [CheckState]
pendingTraitComponentSolutions fuel entries
  | fuel <= 0 = pure []
  | otherwise = do
      baseline <- get
      active <- filterM pendingEntryIsUnsolved entries
      traitEntries <- filterM pendingEntryIsTrait active
      if null traitEntries
        then pure [baseline]
        else
          tryDeterministic baseline traitEntries >>= \case
            Just solutions -> pure (take 65 solutions)
            Nothing -> branchOnFlexible baseline traitEntries
  where
    tryDeterministic _ [] = pure Nothing
    tryDeterministic baseline (entry : rest) = do
      put baseline
      refreshed <- refreshPendingEntry entry
      rigid <- pendingTraitArgumentsRigid (pendingEntryCtx entry) refreshed
      resolved <-
        if rigid
          then
            resolvePendingGoal
              (pendingEntryCtx entry)
              (pendingEntrySite entry)
              (pendingEntryFacts entry)
              Nothing
              refreshed
          else
            resolvePendingFlexibleGoal
              (pendingEntryCtx entry)
              (pendingEntrySite entry)
              refreshed
      case resolved of
        Just evidence -> do
          solvePendingEntry entry refreshed evidence
          solutions <- pendingTraitComponentSolutions (fuel - 1) entries
          if null solutions
            then put baseline >> tryDeterministic baseline rest
            else pure (Just solutions)
        Nothing -> put baseline >> tryDeterministic baseline rest

    branchOnFlexible baseline candidates = do
      groups <- fmap catMaybes . forM candidates $ \entry -> do
        put baseline
        refreshed <- refreshPendingEntry entry
        rigid <- pendingTraitArgumentsRigid (pendingEntryCtx entry) refreshed
        if rigid
          then pure Nothing
          else do
            trials <- matchingInstanceTrialsForGoal (pendingEntryCtx entry) refreshed
            put baseline
            pure $
              if null trials
                then Nothing
                else Just (entry, refreshed, trials)
      case sortOn (\(entry, _, trials) -> (length trials, pendingEntryMeta entry)) groups of
        [] -> put baseline >> pure []
        (entry, refreshed, trials) : _ -> do
          branchSolutions <- forM trials $ \(_, evidence, trialState) -> do
            put trialState
            solvePendingEntry entry refreshed evidence
            pendingTraitComponentSolutions (fuel - 1) entries
          put baseline
          pure (take 65 (concat branchSolutions))

pendingEntryMeta :: PendingEvidenceEntry -> MetaId
pendingEntryMeta (meta, _, _, _, _) = meta

pendingEntrySite :: PendingEvidenceEntry -> Span
pendingEntrySite (_, _, site, _, _) = site

pendingEntryCtx :: PendingEvidenceEntry -> Ctx
pendingEntryCtx (_, _, _, pendingCtx, _) = pendingCtx

pendingEntryFacts :: PendingEvidenceEntry -> [ScopedBoolFact]
pendingEntryFacts (_, _, _, _, facts) = facts

pendingEntryIsUnsolved :: PendingEvidenceEntry -> CheckM Bool
pendingEntryIsUnsolved entry =
  gets $ \state ->
    case Map.lookup (pendingEntryMeta entry) (csMetas state) of
      Just Nothing -> True
      _ -> False

pendingEntryIsTrait :: PendingEvidenceEntry -> CheckM Bool
pendingEntryIsTrait entry =
  refreshPendingEntry entry >>= isTraitGoal

refreshPendingEntry :: PendingEvidenceEntry -> CheckM Value
refreshPendingEntry (_, goal, _, pendingCtx, _) =
  quoteIn pendingCtx goal
    >>= zonkTermM (ctxLen pendingCtx)
    >>= evalIn pendingCtx
    >>= forceM

solvePendingEntry :: PendingEvidenceEntry -> Value -> Term -> CheckM ()
solvePendingEntry entry goal evidence = do
  recordSelectedUniverseEvidence (pendingEntryCtx entry) goal evidence
  value <- evalIn (pendingEntryCtx entry) evidence
  solveMeta (pendingEntryMeta entry) value

matchingInstanceTrialsForGoal :: Ctx -> Value -> CheckM [InstanceTrial]
matchingInstanceTrialsForGoal ctx goal =
  forceM goal >>= \case
    VGlobI trait universes arguments -> do
      state <- get
      case traitSemanticSpineIn state trait arguments of
        Nothing -> pure []
        Just semanticArguments ->
          snd
            <$> matchingInstanceTrials
              0
              ctx
              trait
              universes
              (map snd semanticArguments)
    _ -> pure []

-- | Distinguish an unresolved flexible trait goal from a genuine open-instance
-- ambiguity. Candidate trials are isolated by 'matchingInstanceTrials'; the
-- only observable comparison here is the specialized checked goal each trial
-- produces. Two or more distinct specializations mean that global instance
-- order would choose the carrier, so finalization must report ambiguity
-- instead of the weaker "unsolved implicit" diagnostic. Candidates producing
-- the same specialization remain subject to the ordinary coherence check.
reportAmbiguousFlexibleInstanceGoal :: Ctx -> Span -> Value -> CheckM Bool
reportAmbiguousFlexibleInstanceGoal ctx site goal = do
  baseline <- get
  trials <- matchingInstanceTrialsForGoal ctx goal
  specialized <-
    forM trials $ \(entry, _, trialState) -> do
      put trialState
      goalTerm <- quoteIn ctx goal >>= zonkTermM (ctxLen ctx)
      pure (renderStructuralTermKey goalTerm, entry)
  put baseline
  let byGoal =
        Map.fromListWith
          (++)
          [(key, [entry]) | (key, entry) <- specialized]
      candidates =
        sortOn ieDict
          (nubBy (\left right -> ieDict left == ieDict right) (concat (Map.elems byGoal)))
  if Map.size byGoal < 2
    then pure False
    else do
      rels <- instanceRelateds candidates
      report $
        withPayload
          ( withPayloadField "candidates"
              (T.intercalate ", " (map (gKey . ieDict) candidates)) $
              withPayloadField "candidateKind" "global-instance-specialization" $
                withPayloadField "candidateSitesAvailable"
                  (if length rels == length candidates then "true" else "false") $
                  payloadKind "implicit-ambiguous"
          )
          $ withRelateds
              (related RoleObligationRequiredHere site "implicit goal raised here" : rels)
          $ diag SevError StageElaborate "E_IMPLICIT_AMBIGUOUS"
              (Just "kappa.implicit.ambiguous") site
              "multiple global instances satisfy this implicit goal by selecting distinct carrier types (§14.3.1, §16.3.3)"
      pure True

-- | Resolve a selected pending trait goal through the full ladder only when
-- its semantic head arguments are term-rigid. The ordinary pending policy
-- treats any nested meta as flexible, which is correct before a complete
-- application is known but too conservative for a local proof boundary:
-- checked @Ord Nat@ may still carry universe coercion evidence or later
-- dictionary metas without making its carrier ambiguous. A semantic argument
-- containing an unsolved term meta remains deferred, so @Ord ?a@ can never
-- select a global instance by declaration order.
settleSelectedPendingProofDependencies :: Set MetaId -> CheckM ()
settleSelectedPendingProofDependencies selected = do
  state <- get
  let (inside, outside) =
        List.partition
          (\(meta, _, _, _, _) -> meta `Set.member` selected)
          (csPending state)
  put state {csPending = outside}
  forM_ (reverse inside) $ \(meta, goal, site, pendingCtx, facts) -> do
    reopenSolvedPendingMeta meta
    refreshedTerm <-
      quoteIn pendingCtx goal >>= zonkTermM (ctxLen pendingCtx)
    refreshed <- evalIn pendingCtx refreshedTerm >>= forceM
    traitGoal <- isTraitGoal refreshed
    rigid <-
      if traitGoal
        then pendingTraitArgumentsRigid pendingCtx refreshed
        else pure False
    recordedLevelConstraint <-
      gets (fmap pleConstraint . Map.lookup meta . csPendingLevelEvidence)
    resolved <-
      if not traitGoal || rigid
        then
          resolvePendingGoal
            pendingCtx
            site
            facts
            recordedLevelConstraint
            refreshed
        else resolvePendingFlexibleGoal pendingCtx site refreshed
    case resolved of
      Just term -> do
        value <- evalIn pendingCtx term
        solveMeta meta value
        retirePendingLevelEvidence meta
      Nothing ->
        modify' $ \next ->
          next
            { csPending =
                (meta, goal, site, pendingCtx, facts) : csPending next
            }

pendingTraitArgumentsRigid :: Ctx -> Value -> CheckM Bool
pendingTraitArgumentsRigid ctx goal =
  forceM goal >>= \case
    VGlobI trait _ arguments -> do
      state <- get
      case traitSemanticSpineIn state trait arguments of
        Nothing -> pure False
        Just semanticArguments ->
          pure $
            all
              ( \(_, argument) ->
                  null
                    ( unsolvedMetasOf
                        state
                        (quote (ecOf state) (ctxLen ctx) argument)
                    )
              )
              semanticArguments
    _ -> pure False

-- | Expected-type refinement introduction for bidirectional forms (notably
-- literals) that cannot first infer a useful base type. Once a coherent target
-- view is selected, checking proceeds against its associated base and the
-- predicate obligations remain committed; a missing proof is not rewritten
-- into a literal-domain mismatch.
checkRefinementIntroduction
  :: Ctx
  -> Expr
  -> Value
  -> CheckM (Maybe Term)
checkRefinementIntroduction ctx expression expected = do
  saved <- get
  refinementViewWitness ctx (exprSpan expression) expected >>= \case
    Nothing -> put saved >> pure Nothing
    Just (dictionary, base) -> do
      same <- unifyDefinitional ctx base expected
      if same
        then put saved >> pure Nothing
        else do
          source <- check ctx expression base
          constructRefinement
            ctx
            (exprSpan expression)
            source
            base
            dictionary
            []
            >>= \case
              Nothing -> put saved >> pure Nothing
              result -> pure result

-- | The inferred-term half of §16.1.9. Try direct base-to-refinement first,
-- then refinement-to-base projection. Both attempts are transactional when
-- their associated base does not match, so ordinary mismatches retain their
-- original diagnostics and meta state.
tryRefinementCoercion
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Value
  -> CheckM (Maybe Term)
tryRefinementCoercion ctx site sourceTerm actual expected = do
  tryIntroduction >>= \case
    Just term -> pure (Just term)
    Nothing ->
      tryWidening >>= \case
        Just term -> pure (Just term)
        Nothing -> tryProjection
  where
    tryIntroduction = transactional $ do
      refinementViewWitness ctx site expected >>= \case
        Nothing -> pure Nothing
        Just (dictionary, base) -> do
          same <- unifyDefinitional ctx actual base
          if same
            then constructRefinement ctx site sourceTerm base dictionary []
            else pure Nothing
    tryWidening = transactional $ do
      refinementViewWitness ctx site actual >>= \case
        Nothing -> pure Nothing
        Just (sourceDictionary, sourceBase) ->
          refinementViewWitness ctx site expected >>= \case
            Nothing -> pure Nothing
            Just (targetDictionary, targetBase) -> do
              same <- unifyDefinitional ctx sourceBase targetBase
              if not same
                then pure Nothing
                else do
                  actualTerm <- quoteIn ctx actual
                  targetBaseTerm <- quoteIn ctx targetBase
                  sourceValue <- evalIn ctx sourceTerm
                  let sourceName = "__refinement_widen_source"
                      stableCtx =
                        bindCtxLet sourceName False actual sourceValue ctx
                      sourceDictionary' = shiftTerm 1 0 sourceDictionary
                      targetDictionary' = shiftTerm 1 0 targetDictionary
                      stableSource = CVar 0
                  targetBase' <-
                    evalIn stableCtx (shiftTerm 1 0 targetBaseTerm)
                  sourceMode <-
                    traitMemberObservationMode
                      (gPrel "RefinementView")
                      "refinementValue"
                  proofMode <-
                    traitMemberObservationMode
                      (gPrel "RefinementView")
                      "refinementProof"
                  let projected =
                        CApp Expl
                          (CProjM sourceMode sourceDictionary' "refinementValue")
                          stableSource
                      sourceProof =
                        CApp Expl
                          (CProjM proofMode sourceDictionary' "refinementProof")
                          stableSource
                  constructRefinement
                    stableCtx
                    site
                    projected
                    targetBase'
                    targetDictionary'
                    [(sourceDictionary', sourceProof)]
                    >>= \case
                      Nothing -> pure Nothing
                      Just body ->
                        pure
                          ( Just
                              ( CLetM
                                  Ordinary
                                  QW
                                  sourceName
                                  actualTerm
                                  sourceTerm
                                  body
                              )
                          )
    tryProjection = transactional $ do
      refinementViewWitness ctx site actual >>= \case
        Nothing -> pure Nothing
        Just (dictionary, base) -> do
          same <- unifyDefinitional ctx base expected
          if not same
            then pure Nothing
            else do
              mode <-
                traitMemberObservationMode
                  (gPrel "RefinementView")
                  "refinementValue"
              recordImplicitExpressionDemand site QW
              pure
                ( Just
                    ( CApp Expl
                        (CProjM mode dictionary "refinementValue")
                        sourceTerm
                    )
                )
    transactional action = do
      saved <- get
      result <- action
      case result of
        Nothing -> put saved >> pure Nothing
        Just value -> pure (Just value)

-- | §11.1.2.3B: commute a parametric forall through a type former only by
-- applying the selected 'PreservesParametricForall' method.  This recognizer
-- runs before ordinary implicit insertion: inserting the source forall's
-- binder first would destroy the very shape whose interchange is being
-- justified.  Semantic global identities, complete universe spines, binder
-- modes, and both occurrences of @F A@ must agree; every other shape declines.
tryParametricForallInterchange
  :: Ctx -> Span -> Term -> Value -> Value -> CheckM (Maybe Term)
tryParametricForallInterchange ctx site sourceTerm actual0 expected0 = do
  actual <- forceM actual0
  expected <- forceM expected0
  let level = ctxLen ctx
      rigid = VRigid level []
      parametricForall = \case
        VPiBoundFormedM Parametric FormationParametric Impl Q0 False _ _ domain closure ->
          Just (domain, closure)
        _ -> Nothing
      stripClassifierLifts = \case
        VUniverseLift _ _ _ inner -> stripClassifierLifts inner
        value -> value
      unaryGlobal value =
        case stripClassifierLifts value of
          VGlobI global universes [(Expl, argument)] ->
            Just (global, universes, argument)
          _ -> Nothing
      appliedGlobalToRigid value =
        case stripClassifierLifts value of
          VGlobI global universes [(Expl, argument)]
            | rigidThroughLift argument -> Just (global, universes)
          _ -> Nothing
      -- A cumulative lift around the freshly introduced parametric variable
      -- changes only its classifier.  It must not hide the exact @F A@ shape
      -- required by PreservesParametricForall, but no other wrapper is
      -- admitted by this recognizer.
      rigidThroughLift = \case
        VRigid binderLevel [] -> binderLevel == level
        VUniverseLift _ _ _ inner -> rigidThroughLift inner
        _ -> False
  case (parametricForall actual, unaryGlobal expected) of
    (Just (sourceDomain, sourceClosure), Just (outerGlobal, outerUniverses, expectedForall0)) -> do
      sourceBody <- clApp sourceClosure rigid >>= forceM
      expectedForall <- forceM expectedForall0
      case (unaryGlobal sourceBody, parametricForall expectedForall) of
        ( Just (sourceOuterGlobal, sourceOuterUniverses, sourceInner)
          , Just (targetDomain, targetClosure)
          )
            | sourceOuterGlobal == outerGlobal -> do
                targetBody <- clApp targetClosure rigid >>= forceM
                case (appliedGlobalToRigid sourceInner, appliedGlobalToRigid targetBody) of
                  (Just (sourceF, sourceFUniverses), Just (targetF, targetFUniverses))
                    | sourceF == targetF
                        -> do
                          build
                            sourceDomain targetDomain
                            sourceOuterGlobal sourceOuterUniverses outerUniverses
                            sourceF sourceFUniverses targetFUniverses
                  _ -> pure Nothing
        _ -> pure Nothing
    _ -> pure Nothing
  where
    build sourceDomain targetDomain outerGlobal sourceOuterUniverses targetOuterUniverses
          functionGlobal functionUniverses targetFunctionUniverses = do
      definitions <- gets csGlobals
      case (Map.lookup outerGlobal definitions, Map.lookup functionGlobal definitions) of
        (Just outerDefinition, Just functionDefinition) -> do
          attempted <- trySpec $ do
            sameDomain <- unifyDefinitional ctx sourceDomain targetDomain
            sameOuter <-
              unifyDefinitional ctx
                (VGlobI outerGlobal sourceOuterUniverses [])
                (VGlobI outerGlobal targetOuterUniverses [])
            sameFunction <-
              unifyDefinitional ctx
                (VGlobI functionGlobal functionUniverses [])
                (VGlobI functionGlobal targetFunctionUniverses [])
            if not (sameDomain && sameOuter && sameFunction)
              then pure Nothing
              else do
                (outerTerm, _) <-
                  specializeGlobalAt ctx outerGlobal outerDefinition sourceOuterUniverses
                outerValue <- evalIn ctx outerTerm
                evidenceGoal <-
                  globalValueM prelPreservesParametricForall [(Expl, outerValue)]
                dictionary0 <- resolveImplicitQ ctx site QW evidenceGoal
                stateAfterLookup <- get
                let dependencies =
                      Set.fromList
                        (unsolvedMetasOf stateAfterLookup dictionary0)
                flushPendingSelected dependencies
                dictionary <- zonkTermM (ctxLen ctx) dictionary0
                stateAfterResolution <- get
                if not (null (unsolvedMetasOf stateAfterResolution dictionary))
                  then pure Nothing
                  else do
                    (functionTerm, functionType) <-
                      specializeGlobalAt ctx functionGlobal functionDefinition functionUniverses
                    (method, methodType) <-
                      knownTraitMemberProjection
                        ctx
                        site
                        prelPreservesParametricForall
                        (gnameText prelPullForall)
                        evidenceGoal
                        dictionary
                    (application, applicationType) <-
                      applyGeneratedCoreSpine
                        ctx
                        site
                        method
                        methodType
                        [ (Expl, functionTerm, functionType)
                        , (Expl, sourceTerm, actual0)
                        ]
                    checked <-
                      coerceTerm ctx site application applicationType expected0
                    -- The selected dictionary is fixed above. Generated
                    -- universe-proof arguments inside the resulting method
                    -- application retain their ordinary pending-evidence
                    -- lifecycle and are replayed by the typed-Core verifier.
                    Just <$> zonkTermM (ctxLen ctx) checked
          pure (fromMaybe Nothing attempted)
        _ -> pure Nothing

-- | Reify a declaration-universe telescope only when an expected first-class
-- function type supplies its complete level binders (§11.1.2.3A.1).  The
-- generated eta expansion may additionally abstract implicit erased proof
-- binders whose assumptions discharge the declaration's generated evidence,
-- but it never abstracts an ordinary explicit argument after the schema has
-- been supplied.  Consequently a term function @(u : TypeLevel) -> ...@ is
-- not mistaken for a declaration schema and remains unsaturated when written
-- without @u@.
tryExpectedSchemaReification :: Ctx -> Span -> Expr -> Value -> CheckM (Maybe Term)
tryExpectedSchemaReification ctx site expression expected = do
  initial <- get
  resolved <- case expression of
    EVar name | isNothing (lookupCtx (nameText name) ctx) -> do
      lookupGlobalName (nameText name)
    _ -> pure Nothing
  put initial
  case resolved of
    Just global
      | Just definition <- Map.lookup global (csGlobals initial)
      , let telescope = gdUniverses definition
      , arity <- dutParameterCount telescope
      , arity > 0 -> do
          result <- build global definition arity ctx [] expected
          case result of
            Just term -> pure (Just term)
            Nothing -> put initial >> pure Nothing
    _ -> pure Nothing
  where
    build global definition arity current levelArguments target = do
      direct <-
        if length levelArguments == arity
          then tryDirect global definition current levelArguments target
          else pure Nothing
      case direct of
        Just body -> pure (Just body)
        Nothing -> do
          target' <- forceM target
          case target' of
            VPiBoundFormedM mode _formation ic quantity borrowed name assumption domain closure -> do
              let binderLevel = ctxLen current
                  rigid = VRigid binderLevel []
              levelBinder <- isTypeLevelValue domain
              let consumesSchemaLevel = length levelArguments < arity && ic == Expl && levelBinder
                  consumesEvidence = length levelArguments == arity && ic == Impl && quantity == Q0
              if not (consumesSchemaLevel || consumesEvidence)
                then pure Nothing
                else do
                  withAssumption <- extendLevelAssumption site current assumption
                  let next = bindCtxMQB mode quantity name (ic == Impl) borrowed domain withAssumption
                      nextLevels =
                        if consumesSchemaLevel
                          then levelArguments ++ [LVar binderLevel]
                          else levelArguments
                  codomain <- clApp closure rigid
                  build global definition arity next nextLevels codomain >>= \case
                    Nothing -> pure Nothing
                    Just body -> pure (Just (CLamM mode ic quantity name body))
            _ -> pure Nothing

    tryDirect global definition current levels target = do
      ec <- ec_
      let telescope = gdUniverses definition
          rawType = specializeDeclarationUniverses telescope levels (globalCoreType ec definition)
      sourceType <- evalIn current rawType
      before <- get
      (headTerm, saturatedType) <-
        insertAllImplicits current site (CGlobI global levels) sourceType
      saturated <- forceM saturatedType
      target' <- forceM target
      ec' <- ec_
      if convertible ec' (ctxLen current) saturated target'
        then pure (Just headTerm)
        else put before >> pure Nothing


-- Expected types must not silently choose a non-identity declaration schema
-- for a recursive call (§11.1.2.3A).  Recognize only the structurally direct
-- case: the recursive declaration's finalized result is the same nominal
-- family at its own declaration parameters, and the omitted occurrence was
-- recorded at that identity spine.  The SCC classifier remains the sole site
-- that emits the portable recursive-schema diagnostic.
recordExpectedImplicitRecursiveSchema :: Ctx -> Span -> Term -> Value -> Value -> CheckM Bool
recordExpectedImplicitRecursiveSchema ctx site term actual0 expected0 = do
  actual <- forceM actual0
  expected <- forceM expected0
  st <- get
  ec <- ec_
  let occurrenceHead = termGlobalHeadWithUniverses term
      sameArguments left right =
        length left == length right
          && and
            [ leftIcit == rightIcit && convertible ec (ctxLen ctx) leftValue rightValue
            | ((leftIcit, leftValue), (rightIcit, rightValue)) <- zip left right
            ]
      resultSchema definition = do
        let result = piResult (globalCoreType ec definition)
            (headTerm, _) = spineOfTerm result
        case headTerm of
          CGlobal family levels -> Just (family, map normalizeLevel levels)
          _ -> Nothing
      piResult = \case
        CPiBoundM _ _ _ _ _ _ _ body -> piResult body
        result -> result
  case (occurrenceHead, actual, expected) of
    ( Just (callee, occurrenceLevels)
      , VGlobI sourceFamily sourceLevels sourceArguments
      , VGlobI targetFamily targetLevels targetArguments
      )
        | sourceFamily == targetFamily
        , map normalizeLevel sourceLevels /= map normalizeLevel targetLevels
        , sameArguments sourceArguments targetArguments
        , Just calleeDefinition <- Map.lookup callee (csGlobals st)
        , let arity = dutParameterCount (gdUniverses calleeDefinition)
        , arity > 0
        , resultSchema calleeDefinition
            == Just (sourceFamily, map LParam [0 .. arity - 1])
        , map normalizeLevel occurrenceLevels == map normalizeLevel sourceLevels
        , Just caller <- csActiveUniverseDefinition st
        , Just sourceOccurrence <- listToMaybe
            [ occurrence
            | occurrence <- csRecursiveSchemaOccurrences st
            , rsoCaller occurrence == caller
            , rsoCallee occurrence == callee
            , not (rsoExplicit occurrence)
            , map normalizeLevel (rsoLevels occurrence) == map normalizeLevel occurrenceLevels
            ] -> do
              assumptions <- effectiveLevelAssumptions ctx
              modify' $ \current ->
                current
                  { csRecursiveSchemaOccurrences =
                      RecursiveSchemaOccurrence
                        (rsoCaller sourceOccurrence)
                        callee
                        targetLevels
                        False
                        assumptions
                        site
                        : csRecursiveSchemaOccurrences current
                  }
              pure True
    _ -> pure False

termGlobalHeadWithUniverses :: Term -> Maybe (GName, [Level])
termGlobalHeadWithUniverses = \case
  CApp _ function _ -> termGlobalHeadWithUniverses function
  CUniverseLift _ _ _ inner -> termGlobalHeadWithUniverses inner
  CSchemaLift _ _ _ _ _ _ _ _ inner -> termGlobalHeadWithUniverses inner
  CGlobal global universes -> Just (global, universes)
  _ -> Nothing

-- | The sole surface insertion point for cumulative nominal-family
-- subsumption. It runs before ordinary conversion so declaration-universe
-- roles cannot leak into definitional equality or instance matching.
tryNominalSchemaLift :: Ctx -> Span -> Term -> Value -> Value -> CheckM (Maybe Term)
tryNominalSchemaLift ctx site term actual0 expected0 = do
  actual <- forceM actual0
  expected <- forceM expected0
  case (actual, expected) of
    (VGlobI sourceFamily sourceLevels0 sourceArguments, VGlobI targetFamily targetLevels targetArguments)
      | sourceFamily == targetFamily
      , map normalizeLevel sourceLevels0 /= map normalizeLevel targetLevels
      , null (concatMap levelMetas (sourceLevels0 ++ targetLevels)) -> do
          globals <- gets csGlobals
          dirtyNominals <- gets csDirtyNominalSummaries
          let summary = Map.lookup sourceFamily globals >>= gdNominalSummary
              (sourceLevels, baseTerm) =
                case term of
                  CSchemaLift innerFamily innerSource _ _ _ _ innerSourceArguments innerTargetArguments inner
                    | innerFamily == sourceFamily
                    , length innerTargetArguments == length sourceArguments -> (innerSource, inner)
                  _ -> (sourceLevels0, term)
          case summary of
            Just checkedSummary
              | sourceFamily `Set.notMember` dirtyNominals
              , verifyNominalCumulativitySummary checkedSummary
              , ncsFamilyIdentity checkedSummary == gKey sourceFamily -> do
                  beforeValidation <- get
                  result <- validate checkedSummary sourceFamily sourceLevels targetLevels sourceArguments targetArguments
                  case result of
                    Right (roleEvidence, sourceArgumentTerms, alignedArguments) ->
                      pure . Just $
                        CSchemaLift sourceFamily sourceLevels targetLevels (ncsRoles checkedSummary)
                          roleEvidence (ncsCertificateId checkedSummary)
                          sourceArgumentTerms alignedArguments baseTerm
                    Left reason -> do
                      put beforeValidation
                      reportFailure sourceFamily checkedSummary sourceLevels targetLevels reason
                      pure (Just term)
            _ | sourceFamily `Set.member` dirtyNominals ->
              -- The family's header is complete but its declaration SCC has
              -- not yet materialized stable universe identities. Ordinary
              -- conversion may still prove this use judgmentally equal; a
              -- role action is deliberately unavailable until finalization.
              pure Nothing
            _ -> do
              reportMissingCertificate sourceFamily sourceLevels targetLevels
              pure (Just term)
    _ -> pure Nothing
  where
    validate summary family sourceLevels targetLevels sourceArguments targetArguments = do
      assumptions <- effectiveLevelAssumptions ctx
      definitions <- gets csGlobals
      ec <- ec_
      let familyConstraints =
            maybe []
              (\definition ->
                 declarationConstraintSummary
                   (dutParameterCount (gdUniverses definition))
                   (globalCoreType ec definition))
              (Map.lookup family definitions)
          familyParameterCount = length (ncsRoles summary)
          familyType = globalCoreType ec <$> Map.lookup family definitions
          sourceSemanticArguments =
            maybe sourceArguments
              (\ty -> nominalFamilyArguments familyParameterCount ty sourceArguments)
              familyType
          targetSemanticArguments =
            maybe targetArguments
              (\ty -> nominalFamilyArguments familyParameterCount ty targetArguments)
              familyType
          expectedUniverseArity = length (ncsRoles summary)
          expectedTermArity = ncsSaturationArity summary
          familyInterface =
            (\definition -> (gdUniverses definition, globalCoreType ec definition))
              <$> Map.lookup family definitions
          validUniverseArity = length sourceLevels == expectedUniverseArity && length targetLevels == expectedUniverseArity
          validSaturation =
            length sourceArguments == expectedTermArity
              && length targetArguments == expectedTermArity
          constraintsHold levels =
            all
              (\constraint ->
                proveLevelLeq assumptions
                  (substituteLevelParams levels (ucLower constraint))
                  (substituteLevelParams levels (ucUpper constraint)) == Proved
              )
              familyConstraints
      if not validUniverseArity
        then pure (Left "universe schema arity does not match the certified role vector")
        else if not validSaturation
          then pure . Left $
            "the nominal family application is not fully saturated (expected "
              <> T.pack (show expectedTermArity)
              <> " physical term arguments, found source="
              <> T.pack (show (length sourceArguments))
              <> ", target="
              <> T.pack (show (length targetArguments))
              <> ")"
          else if not (constraintsHold sourceLevels)
            then pure (Left "the source universe instance does not satisfy the declaration constraints")
            else if not (constraintsHold targetLevels)
              then pure (Left "the target universe instance does not satisfy the declaration constraints")
              else do
                aligned <- case familyInterface of
                  Nothing -> pure (Left "the nominal family has no finalized telescope for argument alignment")
                  Just (universeTelescope, termTelescope) ->
                    alignNominalArguments
                      universeTelescope termTelescope sourceLevels targetLevels
                      sourceArguments targetArguments
                case aligned of
                  Left reason -> pure (Left reason)
                  Right (sourceArgumentTerms, alignedArguments) -> do
                    evidence <- sequence
                      [ roleEvidence role source target
                      | (role, source, target) <- zip3 (ncsRoles summary) sourceLevels targetLevels
                      ]
                    case sequence evidence of
                      Nothing -> pure (Left "a declaration-universe role obligation is not proved in the required direction")
                      Just proved -> pure (Right (proved, sourceArgumentTerms, alignedArguments))

    -- §11.1.2.3A.2 alignment is dependent and directional. Rechecking the
    -- source argument at each target binder is what permits only ordinary
    -- conversion and the explicit universe/schema lifts produced by
    -- 'coerceTerm'; comparing already-evaluated argument pairs would both
    -- miss legal nested lifts and ignore substitutions from earlier fields.
    alignNominalArguments universeTelescope familyType sourceLevels targetLevels sourceArguments targetArguments = do
      sourceTelescope <-
        evalIn ctx (specializeDeclarationUniverses universeTelescope sourceLevels familyType)
      targetTelescope <-
        evalIn ctx (specializeDeclarationUniverses universeTelescope targetLevels familyType)
      go ctx sourceTelescope targetTelescope sourceArguments targetArguments [] []
      where
        go activeCtx sourceType targetType sourceArgs targetArgs sourceAligned targetAligned = do
          sourceForced <- forceM sourceType
          targetForced <- forceM targetType
          case (sourceForced, targetForced, sourceArgs, targetArgs) of
            ( VPiEvidenceM _ _ sourceIcit _ _ _ sourceAssumption sourceOrigin sourceDomain sourceClosure
              , VPiEvidenceM _ _ targetIcit _ _ _ targetAssumption targetOrigin targetDomain targetClosure
              , (sourceArgumentIcit, sourceArgument) : sourceRest
              , (targetArgumentIcit, targetArgument) : targetRest
              )
                | sourceIcit == targetIcit
                , sourceIcit == sourceArgumentIcit
                , targetIcit == targetArgumentIcit
                , (sourceOrigin == BinderGenerated) == (targetOrigin == BinderGenerated) -> do
                    sourceResult <- clApp sourceClosure sourceArgument
                    sourceTerm <- quoteIn activeCtx sourceArgument
                    if sourceOrigin == BinderGenerated
                      then do
                        targetResult <- clApp targetClosure targetArgument
                        targetTerm <- quoteIn activeCtx targetArgument
                        nextCtx <- extendLevelAssumption site activeCtx targetAssumption
                        go nextCtx sourceResult targetResult sourceRest targetRest
                          (sourceTerm : sourceAligned) (targetTerm : targetAligned)
                      else do
                        before <- gets (length . csDiags)
                        alignedTerm <- coerceTerm activeCtx site sourceTerm sourceDomain targetDomain
                        after <- gets (length . csDiags)
                        if after /= before
                          then pure (Left "a source family argument cannot be rechecked at its substituted target binder")
                          else do
                            alignedValue <- evalIn activeCtx alignedTerm
                            ec <- ec_
                            if not (convertible ec (ctxLen activeCtx) alignedValue targetArgument)
                              then pure (Left "the target family argument is not the canonical rechecked source argument")
                              else do
                                targetResult <- clApp targetClosure alignedValue
                                nextCtx <- extendLevelAssumption site activeCtx targetAssumption
                                go nextCtx sourceResult targetResult sourceRest targetRest
                                  (sourceTerm : sourceAligned) (alignedTerm : targetAligned)
            (_, _, [], []) -> pure (Right (reverse sourceAligned, reverse targetAligned))
            _ -> pure (Left "the saturated family arguments do not align with the finalized dependent telescope")

    -- Generated/user declaration-constraint proofs are ordinary implicit
    -- erased Pi arguments, but they are not nominal family term arguments.
    -- Walk the finalized family telescope so saturation, alignment, and the
    -- serialized schema-lift payload all use the same post-proof spine.
    nominalFamilyArguments parameterCount = go
      where
        go binder@(CPiEvidenceM _ _ expectedIcit _ _ _ _ _ _ codomain) ((actualIcit, argument) : rest)
          | actualIcit == expectedIcit =
              let remaining = go codomain rest
               in if isJust (declarationUniverseConstraintBinder parameterCount binder)
                    then remaining
                    else (actualIcit, argument) : remaining
        go _ arguments = arguments

    roleEvidence role source target = case role of
      Invariant -> do
        assumptions <- effectiveLevelAssumptions ctx
        pure $
          if proveLevelEq assumptions source target == Proved
          then Just SchemaInvariantEvidence
          else Nothing
      Covariant ->
        if proveLevelLeq emptyAssumptions (normalizeLevel source) (normalizeLevel target) == Proved
          then fmap SchemaCovariantEvidence <$> universeEvidenceFor ctx site source target
          else do
            assumptions <- effectiveLevelAssumptions ctx
            if proveLevelLeq assumptions source target == Proved
              then fmap SchemaCovariantEvidence <$> universeEvidenceFor ctx site source target
              else pure Nothing
      Irrelevant -> pure (Just SchemaIrrelevantEvidence)

    reportFailure family summary source target reason = do
      report $
        withPayload
          ( withPayloadField "family" (gKey family) $
              withPayloadField "sourceUniverseInstance" (renderLevels source) $
                withPayloadField "targetUniverseInstance" (renderLevels target) $
                  withPayloadField "certifiedRoles" (T.pack (show (ncsRoles summary))) $
                    withPayloadField "saturationArity" (T.pack (show (ncsSaturationArity summary))) $
                      withPayloadField "certificateIdentity" (unSchemaActionCertificateId (ncsCertificateId summary)) $
                        withPayloadField "checkerVersion" (T.pack (show (ncsCheckerVersion summary))) $
                          withSemanticVersionPayload (ncsSemanticVersions summary) $
                            withPayloadField "firstFailedObligation" reason $
                              withPayloadField "origin" "expected-type-checking" $
                                payloadKind "universe-schema-lift"
          ) $
            diag SevError StageElaborate "E_UNIVERSE_SCHEMA_LIFT_INVALID"
              (Just "kappa.universe.schema-lift") site
              ("cannot cumulatively use nominal family " <> gKey family <> ": " <> reason)

    reportMissingCertificate family source target =
      report $
        withPayload
          ( withPayloadField "family" (gKey family) $
              withPayloadField "sourceUniverseInstance" (renderLevels source) $
                withPayloadField "targetUniverseInstance" (renderLevels target) $
                  withPayloadField "firstFailedObligation" "no verified nominal action certificate is available" $
                    payloadKind "universe-schema-lift"
          ) $
            diag SevError StageElaborate "E_UNIVERSE_SCHEMA_LIFT_INVALID"
              (Just "kappa.universe.schema-lift") site
              ("nominal family " <> gKey family <> " has no verified cumulativity certificate")

    renderLevels = T.intercalate "," . map renderLevel

    withSemanticVersionPayload versions =
      withPayloadField "typeLevelAlgebraVersion" (renderVersion (tlsvAlgebra versions))
        . withPayloadField "levelConstructorNormalizerVersion" (renderVersion (tlsvConstructorNormalizer versions))
        . withPayloadField "levelRigidEntailmentVersion" (renderVersion (tlsvRigidEntailment versions))
        . withPayloadField "levelPrincipalInferenceVersion" (renderVersion (tlsvPrincipalInference versions))
        . withPayloadField "levelCertificateVersion" (renderVersion (tlsvCertificate versions))

    renderVersion = T.pack . show

-- | Freeze the derivation used by one successful cumulative subsumption.
-- A comparison can succeed either from assumptions already in lexical or
-- declaration scope, or provisionally from the exact residual constraint
-- registered by 'solveLevelInequality'.  The latter is what declaration
-- generalization turns into a hidden-universe telescope constraint.  Capture
-- only that matching judgment (and the assumptions under which it arose), so
-- unrelated pending constraints cannot become accidental evidence.
universeEvidenceFor :: Ctx -> Span -> Level -> Level -> CheckM (Maybe UniverseEvidence)
universeEvidenceFor ctx sp lower0 upper0 = do
  scoped <- effectiveLevelAssumptions ctx
  st <- get
  let assignments = csLevelAssignments st
      resolve = normalizeLevel . substituteLevelMetas assignments
      lower = resolve lower0
      upper = resolve upper0
      matches constraint =
        resolve (lcLhs constraint) == lower
          && resolve (lcRhs constraint) == upper
      direct = find matches (csLevelConstraints st)
      directOwner constraint =
        Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st)
          <|> csActiveUniverseDefinition st
      withConstraint constraint =
        foldr
          (uncurry insertAssumption)
          (insertAssumption (lcLhs constraint) (lcRhs constraint) scoped)
          (assumptionsList (lcAssumptions constraint))
  case proveLevelLeq scoped lower upper of
    Proved -> pure (Just (solverUniverseEvidence scoped lower0 upper0))
    _ -> case direct of
      Just constraint -> do
        -- Freezing evidence from a residual rigid-parameter judgment must
        -- install that judgment in the owning declaration telescope now.
        -- Meta-bearing judgments are still generalized at the SCC boundary;
        -- explicit schema parameters are already rigid and have no later
        -- meta-generalization pass that could recover the authority.
        installed <-
          case directOwner constraint of
            Just owner ->
              recordUniverseRequirementsForOwner owner
                (lcAssumptions constraint)
                [UniverseConstraint lower upper]
            Nothing -> pure False
        authority <-
          if installed
            then effectiveLevelAssumptions ctx
            else pure (withConstraint constraint)
        pure (Just (solverUniverseEvidence authority lower0 upper0))
      Nothing -> do
        report $
          withPayload
            ( withPayloadField "normalizedFailedConstraint" (renderLevel lower <> " <= " <> renderLevel upper) $
                withPayloadField "constraintOrigin" "cumulative subsumption" $
                  withPayloadField "levelAssumptions" (renderLevelAssumptions scoped) $
                    payloadKind "universe-constraint"
            ) $
              diag SevError StageElaborate "E_UNIVERSE_CONSTRAINT_UNSATISFIABLE"
                (Just "kappa.universe.constraint") sp
                "successful universe subsumption had no replayable proof or solver constraint"
        pure Nothing

reportUnsupported :: Span -> Text -> CheckM ()
reportUnsupported sp what =
  let msg = what <> " is not supported by this implementation"
   in report $
        withNote "see SPEC_COMPLIANCE.md for the implemented subset" $
          withPayload (unsupportedPayload msg) $
            diag SevError StageElaborate "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic") sp msg

unsupported :: Ctx -> Span -> Text -> CheckM (Term, Value)
unsupported ctx sp what = reportUnsupported sp what >> anyHole ctx

-- §6.5 conventional-handler rejections (§3.1.3 diagnostic codes). The
-- recovery values are well-typed placeholders so later stages do not
-- cascade.
badGrapheme :: Span -> Text -> CheckM (Term, Value)
badGrapheme sp why = do
  errAt sp "E_UNICODE_INVALID_GRAPHEME_LITERAL" (Just "kappa-hs.unicode.invalid-grapheme-literal")
    ("invalid grapheme literal: " <> why <> " (Spec §6.5)")
  grapheme <- globalValueM prelGrapheme []
  pure (CLit (LitGrapheme "?"), grapheme)

badByte :: Span -> Text -> CheckM (Term, Value)
badByte sp why = do
  errAt sp "E_UNICODE_INVALID_BYTE_LITERAL" (Just "kappa-hs.unicode.invalid-byte-literal")
    ("invalid byte literal: " <> why <> " (Spec §6.5)")
  byte <- globalValueM prelByte []
  pure (CLit (LitByte 0x3F), byte)

-- §6.1.6: an out-of-scope numeric-literal suffix is a compile-time
-- name-resolution error identifying the missing suffix name.
badLiteralSuffix :: Ctx -> Name -> CheckM (Term, Value)
badLiteralSuffix ctx name = do
  let n = nameText name
      sp = nameSpan name
  errAt sp "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
    ("the numeric-literal suffix '" <> n <> "' does not resolve to a term in scope (Spec §6.1.6)")
  anyHole ctx

-- ── Implicit resolution (§16.3.3) ────────────────────────────────────

resolveImplicit :: Ctx -> Span -> Value -> CheckM Term
resolveImplicit ctx sp goal = resolveImplicitQ ctx sp Q0 goal

-- | Resolve an implicit argument for a binder of quantity @q@ (§16.3.3).
-- The quantity distinguishes runtime implicits (which demand an actual
-- candidate, fixtures' @\@ω env : Env@ style) from erased ones (whose
-- values may be inferred later by unification).
resolveImplicitQ :: Ctx -> Span -> Q -> Value -> CheckM Term
resolveImplicitQ ctx sp q goal = do
  g <- forceM goal
  kindLike <- isKindLike (ctxLen ctx) g
  case g of
    _ | kindLike -> freshMetaFor ctx g -- type\/type-constructor params are inferred
    _ -> do
      isTrait <- isTraitGoal g
      isEq <- isEqGoal g
      isRow <- isRowGoal g
      flexed <- goalHasFlex g
      universeFlexed <- goalHasUniverseFlex ctx g
      levelRelation <- authenticatedLevelGoalRelation ctx goal
      let isLevelGoal = isJust levelRelation
          levelFlexed = maybe False relationHasMetas levelRelation
      -- An authenticated first-class level proposition whose endpoints are
      -- still inferable is part of universe inference, not an opaque trait
      -- search problem. Record its exact arithmetic judgment before
      -- postponing the proof term, so the principal level solver can choose
      -- the least endpoint assignment and final evidence search can then
      -- materialize the proof. Rigid false propositions still reach ordinary
      -- proof search and fail closed.
      when levelFlexed $
        pure levelRelation >>= \case
          Just (LevelOperatorLt, lower, upper) ->
            void (solveLevelInequality ctx (levelSucc lower) upper)
          Just (LevelOperatorLe, lower, upper) ->
            void (solveLevelInequality ctx lower upper)
          _ -> pure ()
      -- A rigid erased ordinary implicit still follows §16.3.3 step 1: an
      -- exact lexical implicit candidate wins.  Only a flexible goal is
      -- postponed immediately, because selecting a candidate before later
      -- operands constrain the goal would make application-spine order
      -- observable.  When no rigid local candidate exists, retain the normal
      -- inference meta; the owning boundary diagnoses it if it stays unsolved.
      if q == Q0 && not (isTrait || isEq || isRow || isLevelGoal)
        then if flexed
          then freshMetaFor ctx g
          else do
            localCandidate ctx sp q g >>= \case
              Just tm -> recordSelectedUniverseEvidence ctx g tm >> pure tm
              Nothing -> freshMetaFor ctx g
        else do
      -- §14.1.4: while elaborating a trait member's type, resolve a trait goal
      -- supplied by the current trait's premises to its 'this.__superN'
      -- projection. 'superThisCandidate' follows the declared transitive
      -- supertrait graph. Multiple diamond paths are coherent only when they
      -- instantiate the goal to the same Core type; in that case declaration
      -- order selects the canonical path. Distinct flexible carriers remain
      -- postponed until the surrounding application constrains them.
      -- 'csTraitSupers' is empty outside trait-member elaboration.
          eagerSuper <-
            if isTrait
              then superThisCandidate ctx g
              else pure Nothing
          case eagerSuper of
            Just tm -> pure tm
            Nothing ->
              if (isTrait || isEq || isRow || isLevelGoal)
                   && (flexed || universeFlexed || levelFlexed)
                then do
              -- postpone resolution until explicit arguments solve the head
              -- metavariables (§16.1.7.1 spine order); committing to a local
              -- candidate now could wrongly solve the metas
                  (mid, placeholder) <- freshMetaForWithId ctx g
                  bfs <- gets csBoolFacts
                  owner <- gets csActiveUniverseDefinition
                  modify' $ \st ->
                    st
                      { csPending = (mid, g, sp, ctx, bfs) : csPending st
                      , csPendingLevelEvidence =
                          case (owner, levelRelation) of
                            (Just declaration, Just relation) ->
                              Map.insert
                                mid
                                (PendingLevelEvidence declaration (relationConstraint relation))
                                (csPendingLevelEvidence st)
                            _ -> csPendingLevelEvidence st
                      }
                  pure placeholder
                else do
              -- a flex-headed goal type is not searchable evidence: its
              -- value is inferred by unification at the use site (§16.3.3)
                  gIsFlex <- do
                    gF <- forceM g
                    pure $ case gF of
                      VFlex {} -> True
                      _ -> False
                  if gIsFlex && not (isTrait || isEq || isLevelGoal)
                    then freshMetaFor ctx g
                    else resolveLadder g isTrait isEq isLevelGoal (relationConstraint <$> levelRelation)
  where
    relationHasMetas (_, lower, upper) =
      not (null (levelMetas lower) && null (levelMetas upper))

    relationConstraint (operator, lower, upper) =
      UniverseConstraint
        (if operator == LevelOperatorLt then levelSucc lower else lower)
        upper

    resolveLadder g isTrait isEq isLevelGoal levelConstraint = do
      -- §16.3.3 step 1: the local implicit context goes first.
      mLoc <- localCandidate ctx sp q g
      case mLoc of
        Just tm -> recordSelectedUniverseEvidence ctx g tm >> pure tm
        Nothing -> do
          cached <- lookupClosedEvidence ctx g
          case cached of
            Just tm -> recordSelectedUniverseEvidence ctx g tm >> pure tm
            Nothing -> do
              found <- nonLocalLadder g isTrait isEq isLevelGoal levelConstraint
              case found of
                Just tm -> do
                  rememberClosedEvidence ctx g tm
                  recordSelectedUniverseEvidence ctx g tm
                  pure tm
                Nothing -> unresolved g isTrait isEq isLevelGoal

    nonLocalLadder g isTrait isEq isLevelGoal levelConstraint = do
      -- Equality evidence is not a trait dictionary.  After local explicit
      -- candidates, try the compiler-owned equality/proposition solver before
      -- any dictionary machinery, so checked arithmetic and branch-refined
      -- propositions do not pay for unrelated instance search over large stuck
      -- goals.  The closed-evidence cache wraps this whole non-local ladder,
      -- but never caches proofs that depended on branch facts.
      mEqProp <-
        if isLevelGoal
          then authenticatedLevelPropositionProof ctx levelConstraint g
          else if isEq then propProof ctx g else pure Nothing
      case mEqProp of
        Just tm -> pure (Just tm)
        Nothing -> do
          mIntrinsicTrait <- compilerIntroducedTraitEvidence ctx sp g
          case mIntrinsicTrait of
            Just tm -> pure (Just tm)
            Nothing -> do
              mInst <- if isEq || isLevelGoal then pure Nothing else instanceSearch ctx sp g
              case mInst of
                Just tm -> pure (Just tm)
                Nothing -> do
                  -- §14.3.3: project trait goals out of in-scope evidence through
                  -- declared-supertrait conformance paths.
                  mSup <- if isTrait then superCandidate ctx sp g else pure Nothing
                  case mSup of
                    Just tm -> pure (Just tm)
                    Nothing -> do
                      mProp <- if isEq || isLevelGoal then pure Nothing else propProof ctx g
                      case mProp of
                        Just tm -> pure (Just tm)
                        Nothing -> do
                          -- §11.3.1A compiler-owned introduction rules for the
                          -- intrinsic row traits.
                          mRow <- rowProof g
                          case mRow of
                            Just tm -> pure (Just tm)
                            Nothing ->
                              -- §11.4/§14.4 h-prop closure under Pi: an
                              -- 'IsProp'/'IsSubsingleton' goal whose argument is a
                              -- (dependent) function type is discharged
                              -- structurally — 'IsProp' is closed under Pi,
                              -- bottoming out at 'IsProp (x = y)', which the
                              -- solver settles ONLY when 'IsSet a' evidence is in
                              -- reach (Spec §14.4: Kappa v1 equality is
                              -- intensional). This lets a forall-quantified
                              -- equational law over a set be settled through the
                              -- gated 'unsafeAssertProof' escape.
                              isPropClosure ctx sp g
    unresolved g isTrait isEq isLevelGoal = do
      isRow <- isRowGoal g
      disprovedLevelGoal <- if isLevelGoal then authenticatedLevelGoalDisproved ctx goal else pure False
      incompleteSelfAlreadyReported <-
        gets
          ( any
              (\diagnostic ->
                 dCode diagnostic == "E_DERIVE_INCOMPLETE_SELF"
                   && dPrimary diagnostic == sp)
              . csDiags
          )
      if disprovedLevelGoal
        -- The enclosing Pi carries the same authenticated level assumption.
        -- Its consumption emits the one canonical universe diagnostic.
        then freshMeta
        else if isTrait || isEq || isLevelGoal || q /= Q0
        then do
          gT <- quoteIn ctx g
          unless incompleteSelfAlreadyReported $
            errAt sp "E_UNSOLVED_IMPLICIT" (Just "kappa.implicit.unsolved")
              ("could not resolve implicit argument of type " <> renderTerm gT
                 <> (if isTrait || isEq || isRow then "" else "; a runtime implicit binder requires an implicit local candidate in scope (§16.3.3), and top-level terms are not candidates"))
          diagnosedEvidenceMeta
        else freshMeta

    diagnosedEvidenceMeta = do
      placeholder <- freshMeta
      case placeholder of
        CMeta meta ->
          modify' $ \state ->
            state
              { csDiagnosedPendingEvidence =
                  Set.insert meta (csDiagnosedPendingEvidence state)
              }
        _ -> pure ()
      pure placeholder

-- | Recognize a solver-disproved level-comparison proposition only through
-- the selected standard relation identity or the canonical transparent
-- 'LevelLe'/'LevelLt' aliases. This prevents a generic implicit-resolution
-- diagnostic from preceding the canonical universe-constraint error.
authenticatedLevelGoalDisproved :: Ctx -> Value -> CheckM Bool
authenticatedLevelGoalDisproved ctx goal = do
  authenticatedLevelGoalRelation ctx goal >>= \case
    Just (LevelOperatorLt, lower, upper) -> disproved (levelSucc lower) upper
    Just (LevelOperatorLe, lower, upper) -> disproved lower upper
    _ -> pure False
  where
    disproved lower upper = do
      assumptions <- effectiveLevelAssumptions ctx
      pure (proveLevelLeq assumptions lower upper == Disproved)

-- | Recover only the canonical TypeLevel relation represented by an equality
-- proof goal or by the transparent standard comparison aliases. Every head is
-- authenticated by resolved global identity; same-spelling user aliases do
-- not enter this path.
authenticatedLevelGoalRelation
  :: Ctx
  -> Value
  -> CheckM (Maybe (LevelOperatorIdentity, Level, Level))
authenticatedLevelGoalRelation ctx goal = do
  ec <- ec_
  term <- zonkTermM (ctxLen ctx) (quote ec (ctxLen ctx) goal)
  directLevelConstraintAlias ctx term >>= \case
    Just relation -> pure (Just relation)
    Nothing -> case boolEqualityTruePayload term of
      Nothing -> pure Nothing
      Just relation -> typeLevelRelationOf ctx relation

directLevelConstraintAlias
  :: Ctx
  -> Term
  -> CheckM (Maybe (LevelOperatorIdentity, Level, Level))
directLevelConstraintAlias ctx term =
  case spineOfTerm (stripIdentityWrappers term) of
    (CGlobal alias _, arguments)
      | alias == prelLevelLe || alias == prelLevelLt ->
          case reverse [argument | (Expl, argument) <- arguments] of
            upperTerm : lowerTerm : _ -> do
              lower <- coreTypeLevel ctx lowerTerm
              upper <- coreTypeLevel ctx upperTerm
              pure $ do
                lower' <- lower
                upper' <- upper
                pure
                  ( if alias == prelLevelLt then LevelOperatorLt else LevelOperatorLe
                  , normalizeLevel lower'
                  , normalizeLevel upper'
                  )
            _ -> pure Nothing
    _ -> pure Nothing

-- | §11.4/§14.4 compiler-owned introduction rule for the h-prop marker traits
-- 'IsProp'/'IsSubsingleton'.  Standard HoTT: an h-prop is closed under
-- dependent function types (Pi), and a propositional equality @x = y@ is itself
-- an h-prop /provided its type is a set/.  A goal @IsProp p@ is therefore
-- discharged by structural recursion on @p@:
--
--   * @p = (x : A) -> B x@  (a Pi, of either icity)  →
--         @isPropPi \@A \@(\\x. B x) (\\x -> <evidence for IsProp (B x)>)@
--   * @p = (x = y)@         (a propositional equality over @A@)  →
--         @isPropEq \@A \@x \@y <IsSet A evidence>@
--
-- The closure lemmas 'isPropPi'/'isPropEq' are admitted in the prelude (the
-- true HoTT facts, not derivable here without funext); this solver only wires
-- them together structurally, so the discharged obligation stays auditable.
--
-- SOUNDNESS (Spec §14.4): Kappa v1 equality is intensional and does NOT assume
-- UIP — @x = y@ is an h-prop only when @IsSet A@ is available.  The equality
-- base case therefore RESOLVES @IsSet A@ evidence through the ordinary evidence
-- ladder (local candidates, instance search, supertrait projection) and threads
-- it into 'isPropEq'.  If no @IsSet A@ evidence is in reach, the base case
-- FAILS (returns 'Nothing') — it never fabricates set-ness — so the surrounding
-- 'IsProp' goal stays unresolved and surfaces as 'E_UNSOLVED_IMPLICIT'.
--
-- It fires only for 'IsProp'/'IsSubsingleton' heads — every other class still
-- resolves through the ordinary dictionary ladder.
isPropClosure :: Ctx -> Span -> Value -> CheckM (Maybe Term)
isPropClosure ctx sp = isPropClosureFromTerm ctx sp Nothing

isPropClosureFromTerm
  :: Ctx
  -> Span
  -> Maybe Term
  -> Value
  -> CheckM (Maybe Term)
isPropClosureFromTerm ctx sp sourceGoal goal = do
  g <- forceM goal
  state <- get
  case g of
    VGlobI h _ arguments
      | h == prelIsProp || h == prelIsSubsingleton
      , Just [(_, pv)] <- traitSemanticSpineIn state h arguments ->
          propEvidence ctx [] (sourceGoal >>= isPropCorePayload h) pv
    _ -> pure Nothing
  where
    -- Build a Core term inhabiting @IsProp p@ for the forced proposition @p@,
    -- recursing under Pi binders.  All de-Bruijn levels are taken from the
    -- current context length, and every implicit/value argument is quoted at
    -- that level, so the returned term is well-scoped at the goal's site.
    --
    -- The @[Value]@ accumulator carries the DOMAINS of the Pi binders we have
    -- descended through, most-recent-first.  For a forall-quantified equational
    -- law @forall (x … : a). lhs = rhs@ the binders all have type @a@ (the
    -- carrier), so these domains are the authoritative carrier candidates for
    -- the equality base case — robust even when the equands are stuck terms
    -- (e.g. a recursive @listAppend@ on neutral arguments) whose own type
    -- cannot be read off structurally.
    propEvidence
      :: Ctx
      -> [Value]
      -> Maybe Term
      -> Value
      -> CheckM (Maybe Term)
    propEvidence cx doms sourceProposition pv = do
      ec <- ec_
      pF <- forceHLevelCarrier pv
      direct <- hLevelTraitEvidence cx sp prelIsProp pF
      case direct of
        Just evidence -> pure (Just evidence)
        Nothing -> do
          propositionGoal <- globalValueM prelIsProp [(Expl, pF)]
          focusedLocalDerivation (ctxLen ctx) cx sp propositionGoal >>= \case
            Just evidence -> pure (Just evidence)
            Nothing -> structuralEvidence cx doms sourceProposition ec pF

    structuralEvidence cx doms sourceProposition ec pF =
      case pF of
        -- h-props are closed under (dependent) function types.  The original
        -- binder's icity/quantity are irrelevant to propositionhood; we reuse
        -- the closure as the motive @P = \\x. cod@ and recurse on @cod@.
        VPiM mode _ic q _bw nm dom clo -> do
          let d = ctxLen cx
          cod <- clApp clo (VRigid d [])
          let cx' = bindCtxQ q nm False dom cx
          mEv <-
            propEvidence
              cx'
              (dom : doms)
              (sourceProposition >>= piCodomain)
              cod
          mPiHead <- globalType prelIsPropPi
          pure $ do
            ev <- mEv
            (piHead, _) <- mPiHead
            let aTm = quote ec d dom
                pTm = quote ec d (VLamM mode Expl Q0 nm clo)
                -- the hypothesis '(x : a) -> IsProp (p x)' is an EXPLICIT,
                -- unrestricted function in 'isPropPi'; building it as an
                -- explicit lambda (not an implicit @0 binder) keeps the
                -- recursion from introducing implicit-local candidates that
                -- would make a later same-type implicit goal ambiguous.
                hypTm = CLamM Ordinary Expl QW nm ev
            pure $
              CApp Expl
                (CApp Impl (CApp Impl piHead aTm) pTm)
                hypTm
        -- a propositional equality @x = y@ over @a@ is an h-prop — but ONLY
        -- when @a@ is a set.  Resolve @IsSet a@ evidence through the ordinary
        -- ladder and thread it into 'isPropEq'; without it, this base case fails
        -- (Spec §14.4 — no UIP for arbitrary @a@).
        --
        -- The carrier @a@ is the equands' OWN homogeneous type — @x, y : a@ —
        -- recovered by 'equandType', and we require @IsSet@ of THAT carrier and
        -- nothing else.  An earlier version also tried the enclosing binder
        -- domains and the types of any rigid merely OCCURRING in a stuck equand;
        -- that was UNSOUND.  The evidence ladder ('resolveImplicitQ' ->
        -- 'elabSpineArg') advances the goal by the resolved term's VALUE and
        -- never checks its TYPE against the goal, so threading @isPropEq \@aFake@
        -- is NOT rejected when @aFake \= a@.  A set-typed rigid merely occurring
        -- in a stuck equand (e.g. a @String@ @s@ in the @Bool@ equality
        -- @eqStr s s = False@) would then certify a non-h-prop and let
        -- 'unsafeAssertProof' forge a false equality, inhabiting @Void@.  So we
        -- never guess a carrier the equands do not actually have: if 'equandType'
        -- cannot read it, or it is not a set, the obligation fails honestly.
        _ | Just (aV0, xV, yV) <- canonicalEqualityPayload ec pF -> do
          -- Equality formation may retain a proof-carrying cumulative lift on
          -- its homogeneous carrier. H-level classification is invariant under
          -- that classifier lift, so search and construct the closure witness
          -- at the canonical forced carrier rather than making instance search
          -- depend on one occurrence's universe-evidence wrapper.
          aV <- forceM aV0
          mSet <- isSetEvidence cx sp aV
          case mSet of
            Nothing -> pure Nothing
            Just setTm -> do
              mEqHead <- globalType prelIsPropEq
              let d = ctxLen cx
                  semanticTerms =
                    (quote ec d aV, quote ec d xV, quote ec d yV)
                  (aTm, xTm, yTm) =
                    case sourceProposition >>= canonicalEqualityCorePayload of
                      Just (_, sourceCarrier, sourceLhs, sourceRhs) ->
                        (sourceCarrier, sourceLhs, sourceRhs)
                      Nothing -> semanticTerms
              pure $ do
                (eqHead, _) <- mEqHead
                pure $
                  CApp Impl
                    (CApp Impl (CApp Impl (CApp Impl eqHead aTm) xTm) yTm)
                    setTm
        _ -> pure Nothing

    -- Cumulativity changes only the classifier of a type. H-level closure is
    -- therefore stable through an authenticated universe lift, but the NbE
    -- value deliberately retains that proof wrapper for later reconstruction.
    -- Strip it only for the structural case split; source Core above remains
    -- available to retain the checked lift evidence in generated terms.
    forceHLevelCarrier value =
      forceM value >>= \case
        VUniverseLift _ _ _ inner -> forceHLevelCarrier inner
        forced -> pure forced

    isPropCorePayload expectedHead proposition = do
      let (headTerm, arguments) =
            spineOfTerm (stripIdentityWrappers proposition)
      guard
        ( termHeadGlob (stripIdentityWrappers headTerm)
            == Just expectedHead
        )
      listToMaybe (reverse [argument | (Expl, argument) <- arguments])

    piCodomain = \case
      CPiEvidenceM _ _ _ _ _ _ _ _ _ codomain -> Just codomain
      CPiM _ _ _ _ _ _ codomain -> Just codomain
      _ -> Nothing

-- | Silently resolve @IsSet a@ evidence for the equality base case of the
-- IsProp-under-Pi solver.  This is the ordinary local-then-non-local evidence
-- ladder (in-scope implicit candidates, supertrait projection, then registered
-- instances), but run as a /probe/: it never reports a diagnostic and returns
-- 'Nothing' when no evidence is in reach, so the caller can honestly fail the
-- 'IsProp (x = y)' obligation rather than fabricate set-ness (Spec §14.4).
isSetEvidence :: Ctx -> Span -> Value -> CheckM (Maybe Term)
isSetEvidence cx sp = hLevelTraitEvidence cx sp prelIsSet

-- | Probe one unary h-level trait through the ordinary evidence ladder.
-- Keeping the ladder shared prevents equality-match authorization and the
-- IsProp closure solver from disagreeing about which local, supertrait, or
-- registered instance evidence is in scope.
hLevelTraitEvidence
  :: Ctx
  -> Span
  -> GName
  -> Value
  -> CheckM (Maybe Term)
hLevelTraitEvidence cx sp trait carrier = do
  unaryTraitGoalForCarrier cx trait carrier >>= \case
    Nothing -> pure Nothing
    Just goalV -> do
      -- A carrier still carrying unsolved metavariables is underdetermined;
      -- declining here keeps instance selection from committing on a flexible
      -- head.
      flex <- goalHasFlex goalV
      if flex
        then pure Nothing
        else do
          mLoc <- localCandidate cx sp Q0 goalV
          case mLoc of
            Just tm -> pure (Just tm)
            Nothing -> do
              mCurrentTraitSuper <- superThisCandidate cx goalV
              case mCurrentTraitSuper of
                Just tm -> pure (Just tm)
                Nothing -> do
                  mSup <- superCandidate cx sp goalV
                  case mSup of
                    Just tm -> pure (Just tm)
                    Nothing -> instanceSearch cx sp goalV

-- | The TYPE of a neutral equand, used by the IsProp-under-Pi solver to recover
-- the carrier @a@ of a @x = y@ goal (the @=@ former's own implicit type slot is
-- unreliable, §isPropClosure).  A neutral is @head spine@; its type is the
-- head's type with each spine argument applied through the corresponding Pi
-- codomain.  Heads handled: a bound variable ('VRigid', type read off the
-- context binder) and a global ('VGlobN', e.g. a trait member or @stringAppend@,
-- type read off the globals table).  Any other shape (or a spine that outruns
-- its head's Pi telescope) yields 'Nothing', so the solver fails honestly rather
-- than guessing a carrier.
equandType :: Ctx -> Value -> CheckM (Maybe Value)
equandType cx v = do
  vf <- forceM v
  case vf of
    VFlex meta spine -> do
      classifier <- gets (Map.lookup meta . csMetaClassifiers)
      case classifier of
        Just info
          | micDepth info == ctxLen cx -> do
              headType <- evalIn cx (micType info)
              applySpineType headType spine
        _ -> do
          -- Postponed implicit evidence metas carry their exact checked goal in
          -- 'csPending' rather than 'csMetaClassifiers'. That goal is the
          -- authoritative classifier of the evidence term. Recover it only at
          -- the lexical depth where it was created, then walk any neutral
          -- application spine just as for a rigid or global head.
          pendingGoal <-
            gets
              ( listToMaybe
                  . mapMaybe
                    ( \(pendingMeta, goal, _, pendingCtx, _) ->
                        if pendingMeta == meta && ctxLen pendingCtx == ctxLen cx
                          then Just goal
                          else Nothing
                    )
                  . csPending
              )
          maybe (pure Nothing) (`applySpineType` spine) pendingGoal
    VRigid lvl spine -> do
      let idx = ctxLen cx - 1 - lvl
      case drop idx (ctxEntries cx) of
        (e : _) -> applySpineType (ceType e) spine
        [] -> pure Nothing
    VGlobI g universes spine -> do
      definition <- gets (Map.lookup g . csGlobals)
      case definition of
        Just gd -> do
          (_, hty) <- specializeGlobalAt cx g gd universes
          applySpineType hty spine
        Nothing -> pure Nothing
    -- a fully/partially applied primitive (e.g. @stringAppend@): a prim is
    -- registered as a prelude global carrying its declared type, with value
    -- @VPrim p []@ (see 'Kappa.Prelude.prim'). Unlike a 'VGlobN' spine — which
    -- carries every argument WITH its icity — a 'VPrim' stores ONLY its explicit
    -- arguments: an implicit (type) argument to a stuck prim is erased on
    -- application (see 'Kappa.Eval.evalApp', the @ic == Impl -> VPrim p args@
    -- case). So we must NOT walk the declared Pi telescope one-binder-per-stored-
    -- arg (that would consume an explicit value against an implicit binder and
    -- misalign the whole spine, leaving a stuck/partial codomain and falsely
    -- declining a true carrier). 'applyPrimTelescope' walks the telescope by
    -- binder icity instead, threading the explicit args and reconstructing the
    -- erased implicits from the explicit arguments' types.
    VPrim p args -> do
      mt <- globalType (GName preludeModule p)
      case mt of
        Just (_, hty) -> do
          -- The telescope walk solves fresh metas (and may speculatively touch
          -- pre-existing ones) to reconstruct the erased implicits. Carrier
          -- recovery is a read-only QUERY, so we run it transactionally: snapshot
          -- the complete checker state, recover and deeply zonk the carrier,
          -- then restore the snapshot. A baked result may escape only when it
          -- contains no transaction-local term or level meta; otherwise this
          -- read-only query declines rather than leaving dangling constraints.
          st0 <- get
          let allocationCutoff = csNextMeta st0
              depth = ctxLen cx
          r <- applyPrimTelescope hty args
          baked <- forM r $ \value -> do
            ec <- ec_
            zonkTermM depth (quote ec depth value)
          put st0
          case baked of
            Just term
              | all (< allocationCutoff) (metaIdsOf term)
              , all (< allocationCutoff) (levelMetasOfTerm term) ->
                  Just <$> evalIn cx term
            _ -> pure Nothing
        Nothing -> pure Nothing
    -- A literal's carrier is its (unique) type. The only one that arises as an
    -- equand under these laws is the String literal — e.g. @render@/
    -- @__debugRender@ reduce a concrete argument to a @String@ literal, and a
    -- forall-law over such a value is an h-prop because @String@ is a set. A
    -- 'LitInt' is intentionally NOT handled: its representation is shared by
    -- @Nat@/@Int@/@Integer@ (see 'Kappa.Core.Literal'), so its carrier is
    -- ambiguous and guessing one would be unsound. Other literals decline.
    VLit (LitStr _) -> Just <$> globalValueM prelString []
    _ -> pure Nothing
  where
    -- Walk @spine@ through the head type's Pi binders, substituting each
    -- argument into the codomain to obtain the result type.
    applySpineType :: Value -> Spine -> CheckM (Maybe Value)
    applySpineType ty [] = Just <$> forceM ty
    applySpineType ty ((_, arg) : rest) = do
      tf <- forceM ty
      case tf of
        VPi _ _ _ _ _ clo -> do
          cod <- clApp clo arg
          applySpineType cod rest
        _ -> pure Nothing

    -- Walk a primitive's declared type telescope to recover the type of a
    -- (possibly partial) @VPrim p args@ application. @args@ holds ONLY the
    -- explicit arguments (the erased implicits were dropped on application), so
    -- we descend the telescope by binder icity:
    --
    --   * an IMPLICIT binder has no stored argument — apply a fresh metavariable
    --     and continue. The meta is pinned below by unifying the recovered type
    --     of a later explicit argument against that argument's declared domain
    --     (which mentions this implicit). If nothing pins it, the meta stays
    --     flexible and the recovered carrier is a metavariable for which the
    --     downstream @IsSet@ search declines — never a concrete (possibly wrong)
    --     carrier, so this is soundness-safe.
    --
    --   * an EXPLICIT binder consumes the next stored argument; before applying
    --     it we recover the argument's own type and unify it with the binder's
    --     domain, which solves any implicit metas the domain mentions. For a prim
    --     like @__arrayIndexUnsafe : forall (@0 a). Array a -> Int -> a@ the array
    --     argument's type @Array Integer@ pins the erased @a := Integer@.
    applyPrimTelescope :: Value -> [Value] -> CheckM (Maybe Value)
    applyPrimTelescope ty args = do
      tf <- forceM ty
      case tf of
        VPi Impl _ _ _ _ clo -> do
          mv <- freshMetaV cx
          cod <- clApp clo mv
          applyPrimTelescope cod args
        VPi Expl _ _ _ dom clo -> case args of
          (a : rest) -> do
            mArgTy <- equandType cx a
            case mArgTy of
              Just argTy -> do
                compatible <- unify cx dom argTy
                if compatible
                  then do
                    cod <- clApp clo a
                    applyPrimTelescope cod rest
                  else pure Nothing
              Nothing -> pure Nothing
          -- a partially applied prim: no more explicit args to consume, so the
          -- equand's type is the remaining (function) type — return it as-is.
          [] -> Just <$> forceM tf
        -- the telescope is exhausted; any leftover stored args would indicate a
        -- mis-registered prim type, so decline rather than guess.
        _ -> case args of
          [] -> Just <$> forceM tf
          _ -> pure Nothing

-- NOTE: a 'rigidVarTypes' carrier-recovery fallback used to live here, feeding
-- the IsProp-under-Pi solver's equality base case extra carrier candidates — the
-- types of rigid variables merely OCCURRING in the equands. It was REMOVED as
-- UNSOUND: it let the solver grab a set-typed carrier FOREIGN to the equality
-- (e.g. 'IsSet String' from a 'String' rigid 's' inside the 'Bool' equality
-- 'eqStr s s = False'), and the evidence ladder ('resolveImplicitQ' ->
-- 'elabSpineArg') never type-checks the threaded 'isPropEq @aForeign' against
-- the goal, so 'unsafeAssertProof' could then forge a false equality, inhabiting
-- 'Void'. The equality base case now uses ONLY the equands' own homogeneous type
-- ('equandType'). Regression:
-- tests/conformance/equality/isprop-eq-foreign-carrier-rigid-rejected.kp.

-- | §22.4: a goal of shape @forall xs. IsTrait (tc x)@ is satisfied by
-- a synthesized witness whenever its head is the builtin 'IsTrait'
-- classifier; the witness carries no information.
isTraitWitness :: Ctx -> Value -> CheckM (Maybe Term)
isTraitWitness ctx goal = go (ctxLen ctx) goal
  where
    go lvl v = do
      vF <- forceM v
      case vF of
        VPiM mode ic q _ nm _ clo -> do
          cod <- clApp clo (VRigid lvl [])
          fmap (CLamM mode ic q nm) <$> go (lvl + 1) cod
        VGlobN (GName pm "IsTrait") [(_, target)]
          | pm == preludeModule -> do
              authenticated <- isTraitGoal target
              if authenticated
                then do
                  ec <- ec_
                  witness <- globalHeadM prelIsTraitWitness
                  pure (Just (CApp Impl witness (quote ec lvl target)))
                else pure Nothing
        _ -> pure Nothing

-- | Compiler-owned trait-classification evidence shared by immediate and
-- postponed implicit resolution. These rules are structural: they inspect
-- authenticated global identity and a complete source-arity application, and
-- never select from the open instance set or improve a flexible carrier.
compilerIntroducedTraitEvidence
  :: Ctx
  -> Span
  -> Value
  -> CheckM (Maybe Term)
compilerIntroducedTraitEvidence ctx site goal =
  intrinsicTraitSubsingletonEvidence ctx site goal >>= \case
    Just evidence -> pure (Just evidence)
    Nothing -> isTraitWitness ctx goal

-- | Compiler-issued §14.4 evidence for the intrinsic rule
-- @IsTrait G => IsSubsingleton G@. 'IsTrait' is an opaque classifier rather
-- than an ordinary dictionary declaration in 'csTraits', so this edge cannot
-- be traversed by 'supertraitProject'. The dedicated intrinsic has a checked
-- Core telescope and is shared by ordinary implicit resolution and coherent
-- evidence transport.
intrinsicTraitSubsingletonEvidence
  :: Ctx
  -> Span
  -> Value
  -> CheckM (Maybe Term)
intrinsicTraitSubsingletonEvidence ctx site goal =
  forceM goal >>= \case
    VGlobN subsingleton [(_, evidenceType)]
      | subsingleton == prelIsSubsingleton -> do
          authenticated <- isTraitGoal evidenceType
          blocked <- evidenceUniquenessDependencyBlocked evidenceType
          if blocked
            then do
              errOncePerSpan site "E_EVIDENCE_UNIQUENESS_CYCLE"
                (Just "kappa.evidence.uniqueness")
                "an evidence-uniqueness certificate depends on compiler-generated coherence for the same trait (§14.1.1A)"
              pure Nothing
            else if not authenticated
            then pure Nothing
            else do
              isTraitGoalValue <-
                globalValueM (gPrel "IsTrait") [(Expl, evidenceType)]
              isTraitWitness ctx isTraitGoalValue >>= \case
                Nothing -> pure Nothing
                Just traitWitness -> do
                  evidenceTypeTerm <- quoteIn ctx evidenceType
                  classifier <- equandType ctx evidenceType >>= \case
                    Just value -> pure value
                    Nothing -> freshMetaV ctx
                  globalTerm prelTraitSubsingletonWitness >>= \case
                    Nothing -> pure Nothing
                    Just (headTerm, headType) -> do
                      (evidence, evidenceType') <-
                        applyGeneratedCoreSpine
                          ctx
                          site
                          headTerm
                          headType
                          [ (Impl, evidenceTypeTerm, classifier)
                          , (Impl, traitWitness, isTraitGoalValue)
                          ]
                      valid <- unify ctx evidenceType' goal
                      pure (if valid then Just evidence else Nothing)
    _ -> pure Nothing

-- | Exact semantic-identity guard for the forbidden self-coherence edge in an
-- independent evidence-uniqueness certificate.  This is intentionally not a
-- spelling test: the fully checked trait head is compared with the active
-- declaration identities.
evidenceUniquenessDependencyBlocked :: Value -> CheckM Bool
evidenceUniquenessDependencyBlocked evidenceType = do
  active <- gets csEvidenceUniquenessStack
  forceM evidenceType >>= \case
    VGlobI trait _ _ -> pure (trait `elem` active)
    _ -> pure False

-- | Kind-like goals — @Type@, @Type -> Type@, … — are inferred from
-- use sites (metavariables), never searched as evidence (§16.3.3).
-- LOCKSTEP: @Kappa.Backend.Repr.runtimeErasedParam@ is the pure shared
-- backend-side classifier for quantity-0, kind-domain, and proof-only binders.
-- If the notion of kind-like changes here (e.g. a new sort-former), update that
-- shared classifier in lockstep or KBackendIR erasure can desync from the
-- elaborator.
isKindLike :: Int -> Value -> CheckM Bool
isKindLike lvl v = do
  t <- forceM v
  case t of
    VSort _ -> pure True
    VPi _ _ _ _ _ clo -> do
      cod <- clApp clo (VRigid lvl [])
      isKindLike (lvl + 1) cod
    _ -> pure False

-- | §11.1.6/§14.2.1 compile-time member classification. This is deliberately
-- broader than 'isParametricKind': a predicate such as
-- @(n : Nat) -> Type@ is not a v1 parametric kind, but its fully applied
-- result is compile-time and therefore it is a valid associated static
-- member. Exact checked global identities classify the intrinsic static
-- carriers; function spaces inherit the classification from their eventual
-- result.
isAssociatedStaticMemberType :: Int -> Value -> CheckM Bool
isAssociatedStaticMemberType lvl value =
  forceM value >>= \case
    VSort {} -> pure True
    VPi _ _ _ _ _ codomain -> do
      result <- clApp codomain (VRigid lvl [])
      isAssociatedStaticMemberType (lvl + 1) result
    VUniverseLift _ _ _ inner ->
      isAssociatedStaticMemberType lvl inner
    VGlobN global _ ->
      pure (global `Set.member` associatedStaticCarrierIdentities)
    _ -> pure False
  where
    associatedStaticCarrierIdentities =
      Set.fromList associatedStaticCarrierGlobals

observationForBinding :: ObservationMode -> Text -> Value -> CheckM ObservationJudgment
observationForBinding mode origin classifier = do
  classifier' <- case mode of
    Ordinary -> pure Nothing
    Parametric ->
      forceM classifier >>= \case
        VSort level -> pure (Just (ObservationType level))
        _ -> pure (Just ObservationTypeFormer)
  pure (ObservationJudgment mode origin classifier')

ordinaryObservation :: Text -> ObservationJudgment
ordinaryObservation origin = ObservationJudgment Ordinary origin Nothing

joinObservation :: ObservationJudgment -> ObservationJudgment -> ObservationJudgment
joinObservation left right = case (ojMode left, ojMode right) of
  (Parametric, _) -> left
  (_, Parametric) -> right
  _ -> left

-- | Derive an occurrence's KCore observation judgment from the exact finite
-- origin calculus of SS30.2.0.  This is the elaboration-side invocation of the
-- same pure analyzer used by the finalized KCore checkpoint.
observationJudgmentForTerm :: Ctx -> Term -> Value -> CheckM ObservationJudgment
observationJudgmentForTerm ctx term classifier = do
  establishedDependencies <- observationDependenciesForTerm ctx term classifier
  let mode = dependenciesMode establishedDependencies
      origin = case Set.lookupMin establishedDependencies of
        Nothing -> "ordinary-expression"
        Just dependency -> T.pack (show dependency)
  observationForBinding mode origin classifier

-- | The dependency set underlying 'observationJudgmentForTerm'. Declaration
-- generalization consumes the identities directly so it can distinguish a
-- newly-rigid candidate binder from unrelated outer parametric dependencies.
observationDependenciesForTerm :: Ctx -> Term -> Value -> CheckM DependencySet
observationDependenciesForTerm ctx term classifier = do
  st <- get
  ec <- ec_
  bindings <- forM (zip [0 ..] (ctxEntries ctx)) $ \(index, entry) -> do
    mode <-
      if ceModeProvisional entry
        then do
          parametricKind <- isParametricKind (ctxLen ctx) (ceType entry)
          pure (if parametricKind then Parametric else Ordinary)
        else pure (ceMode entry)
    pure
      ObservationBinding
        { obMode = mode
        , obOrigin =
            if mode == Parametric
              then Just (ParametricExternal index (fromMaybe (ceName entry) (ceObservationOrigin entry)))
              else Nothing
        , obType = Just (ceType entry)
        , obUniverses = luiTelescope <$> ceLocalUniverses entry
        , obDefinition = Nothing
        }
  let oracle = observationOracle st ec
      -- Observation is a finite structural analysis.  Whole-term NBE here
      -- would unfold recursive definitions before the dependency equations
      -- can use their already-finalized global summaries.
      rawDependencies = observationDependencies oracle bindings (Just classifier) term
      classifierRelative =
        classifierRelativeDependencies oracle bindings (ctxLen ctx) classifier rawDependencies
      dependencies =
        evidenceRelativeCallableDependencies ec (ctxLen ctx) classifier classifierRelative
      -- Term metas are not stable observation origins.  During application
      -- elaboration they can be solved by later operands in the same spine,
      -- so defer only these origins until the declaration is zonked and the
      -- finalized Core checkpoint reruns the same calculus.  In particular,
      -- do not discard 'ParametricAnalysisFailure': that is a real fail-closed
      -- source diagnostic rather than a deferred inference fact.
      establishedDependencies = Set.filter (\case ParametricMeta {} -> False; _ -> True) dependencies
  pure establishedDependencies

observationOracle :: CheckState -> EvalCtx -> ObservationOracle
observationOracle st ec =
  ObservationOracle
    { ooEvalCtx = ec
    , ooThisType = thisObservationType (csThis st)
    , ooGlobalMode = \global@(GName moduleName _) ->
        -- The active declaration's recursive self edge is an equation
        -- variable, not a fresh observation origin.  Taking it as ordinary
        -- here computes the least fixed point: every independent dependency
        -- in the body is still retained and determines the final summary.
        if Just global == csActiveUniverseDefinition st
          then Just Ordinary
          else
            (gdObservationMode <$> Map.lookup global (csGlobals st))
              <|> (Ordinary <$ guard (moduleName == primModule))
    , ooGlobalBody = \global -> do
        definition <- Map.lookup global (csGlobals st)
        if gdReducible definition then gdCoreBody definition else Nothing
    , ooGlobalPrimitive = \global ->
        maybe False (maybe False primitiveValue . gdValue)
          (Map.lookup global (csGlobals st))
    , ooMetaMode = metaObservationMode st ec
    , ooInferType = observationTermTypeAt st ec
    , ooProjectionMode = \receiverType field ->
        case force ec receiverType of
          VGlobN trait _ ->
            (Map.lookup trait (csTraits st) >>= Map.lookup field . tiMemberModes)
              <|> nominalHiddenProjectionMode st ec receiverType field
          _ ->
            nominalHiddenProjectionMode st ec receiverType field
    , ooProjectionType = \depth _receiver receiverType field ->
        observationTermTypeAt st ec (depth + 1)
          [ ObservationBinding
              { obMode = Ordinary
              , obOrigin = Nothing
              , obType = Just receiverType
              , obUniverses = Nothing
              , obDefinition = Nothing
              }
          ]
          (CProjM Ordinary (CVar 0) field)
    , ooProjectionTrait = \receiverType field ->
        case force ec receiverType of
          VGlobN trait _ -> do
            info <- Map.lookup trait (csTraits st)
            guard (Map.member field (tiMemberModes info))
            pure trait
          _ -> Nothing
    , ooConstructorType = \constructor universes ->
        case Map.lookup constructor (csCtors st) of
          Nothing -> Nothing
          Just info -> specializeConstructorType ec universes info
    , ooProvisionalUniverseMetadata = True
    , ooExpandingGlobals = Set.empty
    }
  where
    thisObservationType = \case
      Just (ThisType fields) -> Just (VRecordTQ (sortOn rfName fields))
      Just (ThisTraitSibs fields) -> Just (VRecordTQ (sortOn rfName fields))
      Just (ThisValue _ fields) -> Just (VRecordTQ (sortOn rfName fields))
      Nothing -> Nothing

    primitiveValue value = case force ec value of
      VPrim {} -> True
      VIOAction {} -> True
      _ -> False

metaObservationMode :: CheckState -> EvalCtx -> MetaId -> Maybe ObservationMode
metaObservationMode st ec meta = do
  classifier <- Map.lookup meta (csMetaClassifiers st)
  let depth = micDepth classifier
      environment = [VRigid level [] | level <- reverse [0 .. depth - 1]]
      classifierValue = eval ec environment (micType classifier)
  pure
    ( if isParametricKindValue ec depth classifierValue
        then Parametric
        else Ordinary
    )

observationTermTypeAt :: CheckState -> EvalCtx -> Int -> [ObservationBinding] -> Term -> Maybe Value
observationTermTypeAt st ec depth localBindings = go
  where
    globals = csGlobals st

    go = \case
      CGlobal global universes -> specializeGlobalType universes . gdType <$> Map.lookup global globals
      CVar index -> listToMaybe (drop index localBindings) >>= obType
      CLocal index universes -> do
        binding <- listToMaybe (drop index localBindings)
        telescope <- obUniverses binding
        ty <- obType binding
        if length universes == dutParameterCount telescope
          then Just (specializeLocalType telescope universes ty)
          else Nothing
      CProjM _ receiver field -> go receiver >>= projectionType receiver field
      CProjAtM _ receiver field _ -> go receiver >>= projectionType receiver field
      CSealE _ value -> go value
      CIf _ yes no -> sameType (go yes) (go no)
      CMatch _ _ resultAnnotation _ -> evalAt <$> resultAnnotation
      application@CApp {} ->
        let (headTerm, arguments) = spineOfTerm application
         in go headTerm >>= \headType -> applyArguments headType arguments
      _ -> Nothing

    applyArguments ty [] = Just ty
    applyArguments ty ((actualIcit, argument) : rest) =
      case force ec ty of
        VPiM _ expectedIcit _ _ _ _ (Closure closureEnv codomain)
          | actualIcit == expectedIcit ->
              applyArguments (eval ec (evalAt argument : closureEnv) codomain) rest
        _ -> Nothing

    projectionType receiver field receiverType =
      case force ec receiverType of
        VRecordTQ fields -> rfType <$> find ((== field) . rfName) fields
        VSigT _ inner -> projectionType receiver field inner
        VGlobI trait universes arguments ->
          case Map.lookup trait (csTraits st) of
            Just info
              | Just semanticArguments <- traitSemanticSpineIn st trait arguments
              , field `elem` tiMembers info -> do
                  member <- Map.lookup (memberGlobal trait field) globals
                  memberType <- specializeGlobalDefinitionTypePrefix ec universes member
                  let specializedMemberType = quote ec depth memberType
                      argumentTerms = map (quote ec depth . snd) semanticArguments
                  projectedType <-
                    specializeTraitMemberProjectionType depth (tiParamCount info)
                      argumentTerms receiver specializedMemberType
                  pure (evalAt projectedType)
              | Just semanticArguments <- traitSemanticSpineIn st trait arguments
              , Just super <- Map.lookup field (Map.fromList (tiSupers info)) ->
                  applySuper (eval ec [] super) (map snd semanticArguments)
            _ ->
              snd <$> nominalHiddenProjectionInfo st ec depth receiver receiverType field
        _ ->
          snd <$> nominalHiddenProjectionInfo st ec depth receiver receiverType field

    applySuper value [] = Just (force ec value)
    applySuper value (argument : arguments) =
      case force ec value of
        VLamM _ Expl _ _ (Closure closureEnv body) ->
          applySuper (eval ec (argument : closureEnv) body) arguments
        _ -> Nothing

    sameType (Just left) (Just right)
      | convertible ec depth (force ec left) (force ec right) = Just left
    sameType _ _ = Nothing

    specializeGlobalType universes value
      | null universes = value
      | otherwise =
          eval ec []
            (zonkTermWith (\_ _ -> Nothing) (substituteLevelParams universes) 0 (quote ec 0 value))

    -- Local declaration schemas are interpreted in the lexical term scope in
    -- which their type was recorded. Quoting at depth zero turns references to
    -- enclosing binders into malformed/out-of-scope terms and makes typed
    -- observation replay reject valid mutually recursive local declarations.
    -- Keep this identical to Backend.IR's finalized-Core type recovery.
    specializeLocalType telescope universes generalizedType =
      let raw = quote (ec {ecFacts = Map.empty}) depth generalizedType
          specialized =
            zonkTermWith
              (\_ _ -> Nothing)
              (instantiateLocalLevelParams (dutParameterCount telescope) universes)
              0
              raw
       in eval ec [VRigid level [] | level <- reverse [0 .. depth - 1]] specialized

    evalAt = eval ec [VRigid level [] | level <- reverse [0 .. depth - 1]]

-- | Recover a named erased constructor field from a nominal receiver using
-- the same checked constructor interfaces that authorized source projection.
-- Every constructor of the family must expose the same final hidden binder;
-- otherwise the typed analysis fails closed instead of inferring a field from
-- its spelling. Prior named source fields are instantiated as projections of
-- the receiver so dependent proof-field types retain their exact identity.
nominalHiddenProjectionInfo
  :: CheckState
  -> EvalCtx
  -> Int
  -> Term
  -> Value
  -> Text
  -> Maybe (ObservationMode, Value)
nominalHiddenProjectionInfo st ec depth receiverTerm receiverType field = do
  family <- case force ec receiverType of
    VGlobI global _ _ ->
      Just global
    _ -> Nothing
  dataInfo <- Map.lookup family (csDatas st)
  guard (not (null (diCtors dataInfo)))
  nominalHiddenProjectionInfoForConstructors
    st
    ec
    depth
    receiverTerm
    receiverType
    (diCtors dataInfo)
    field

-- | Recover a named erased constructor field over an authenticated subset of
-- a nominal family's constructors. Every preceding source binder is
-- instantiated by projecting that binder from the same receiver, so a
-- dependent field such as @proof : predicate value@ retains the exact
-- receiver-indexed type. Fresh constructor metas are deliberately not used:
-- they describe an arbitrary constructor occurrence rather than this value.
nominalHiddenProjectionInfoForConstructors
  :: CheckState
  -> EvalCtx
  -> Int
  -> Term
  -> Value
  -> [GName]
  -> Text
  -> Maybe (ObservationMode, Value)
nominalHiddenProjectionInfoForConstructors
  st ec depth receiverTerm receiverType constructors field = do
  (universes, familyArguments) <- case force ec receiverType of
    VGlobI _ selectedUniverses arguments ->
      Just (selectedUniverses, map snd arguments)
    _ -> Nothing
  guard (not (null constructors))
  results <-
    traverse
      (constructorField universes familyArguments)
      constructors
  case results of
    firstResult@(_, firstType) : rest -> do
      guard
        ( all
            (\(mode, fieldType) ->
               mode == fst firstResult
                 && convertible ec depth firstType fieldType)
            rest
        )
      pure firstResult
    [] -> Nothing
  where
    receiverValue =
      eval ec
        [VRigid level [] | level <- reverse [0 .. depth - 1]]
        receiverTerm

    constructorField universes familyArguments constructor = do
      info <- Map.lookup constructor (csCtors st)
      targetIndex <- case
        [ index
        | (index, sourceField) <- zip [0 :: Int ..] (ciSourceFields info)
        , sourceField == (Impl, Just field)
        ] of
          [] -> Nothing
          indices -> Just (last indices)
      constructorType <- specializeConstructorType ec (Just universes) info
      let sourceCount = length (ciSourceFields info)
          prefixCount = constructorPiCount constructorType - sourceCount
      guard (prefixCount >= 0 && prefixCount == length familyArguments)
      sourceType <- applyPrefix constructorType familyArguments
      selectSourceField targetIndex receiverValue sourceType (ciSourceFields info)

    constructorPiCount value = case force ec value of
      VPiM _ _ _ _ _ _ closure ->
        1 + constructorPiCount (clAppRigid closure)
      _ -> 0

    clAppRigid (Closure environment codomain) =
      eval ec (VRigid (length environment) [] : environment) codomain

    applyPrefix value [] = Just value
    applyPrefix value (argument : arguments) =
      case force ec value of
        VPiM _ _ _ _ _ _ (Closure environment codomain) ->
          applyPrefix (eval ec (argument : environment) codomain) arguments
        _ -> Nothing

    selectSourceField targetIndex root = go 0
      where
        go _ _ [] = Nothing
        go index value ((expectedIcit, expectedName) : rest) =
          case force ec value of
            VPiM mode actualIcit quantity _ actualName domain (Closure environment codomain) -> do
              guard (actualIcit == expectedIcit)
              guard (expectedName == Just actualName)
              if index == targetIndex
                then do
                  guard (actualIcit == Impl && quantity == Q0 && actualName == field)
                  pure (mode, domain)
                else do
                  name <- expectedName
                  let argument = VProjN mode root name
                  go (index + 1) (eval ec (argument : environment) codomain) rest
            _ -> Nothing

-- | Authenticate the observation mode of a named erased constructor field
-- without fabricating a receiver value.  Unlike the dependent field type,
-- the mode is fixed by the constructor telescope itself.  Looking it up
-- directly also keeps the observation oracle valid at arbitrary lexical
-- depths: a synthetic @CVar 0@ cannot instantiate a field whose type depends
-- on the actual nominal receiver and its preceding fields.
nominalHiddenProjectionMode
  :: CheckState
  -> EvalCtx
  -> Value
  -> Text
  -> Maybe ObservationMode
nominalHiddenProjectionMode st ec receiverType field = do
  family <- case force ec receiverType of
    VGlobI global _ _ -> Just global
    _ -> Nothing
  dataInfo <- Map.lookup family (csDatas st)
  guard (not (null (diCtors dataInfo)))
  modes <- traverse constructorMode (diCtors dataInfo)
  case modes of
    firstMode : rest
      | all (== firstMode) rest -> Just firstMode
    _ -> Nothing
  where
    constructorMode constructor = do
      info <- Map.lookup constructor (csCtors st)
      targetIndex <- case
        [ index
        | (index, sourceField) <- zip [0 :: Int ..] (ciSourceFields info)
        , sourceField == (Impl, Just field)
        ] of
          [] -> Nothing
          indices -> Just (last indices)
      -- Observation mode is invariant under declaration-universe
      -- specialization.  Inspecting the raw checked telescope avoids making a
      -- mode query depend on whether a provisional universe occurrence has
      -- already been finalized.
      let constructorType = eval ec [] (ciType info)
          sourceCount = length (ciSourceFields info)
          prefixCount = constructorPiCount constructorType - sourceCount
      guard (prefixCount >= 0)
      sourceType <- dropPrefix prefixCount constructorType
      selectMode targetIndex sourceType (ciSourceFields info)

    constructorPiCount value = case force ec value of
      VPiM _ _ _ _ _ _ closure ->
        1 + constructorPiCount (applyRigid closure)
      _ -> 0

    applyRigid (Closure environment codomain) =
      eval ec (VRigid (length environment) [] : environment) codomain

    dropPrefix 0 value = Just value
    dropPrefix count value = case force ec value of
      VPiM _ _ _ _ _ _ closure ->
        dropPrefix (count - 1) (applyRigid closure)
      _ -> Nothing

    selectMode _ _ [] = Nothing
    selectMode targetIndex value ((expectedIcit, expectedName) : rest) =
      case force ec value of
        VPiM mode actualIcit quantity _ actualName _ closure -> do
          guard (actualIcit == expectedIcit)
          guard (expectedName == Just actualName)
          if targetIndex == 0
            then do
              guard (actualIcit == Impl && quantity == Q0 && actualName == field)
              pure mode
            else
              selectMode (targetIndex - 1) (applyRigid closure) rest
        _ -> Nothing

constructorObservationSites :: EvalCtx -> Value -> [(ObservationMode, Value)]
constructorObservationSites ec = collect 0
  where
    collect level value = case force ec value of
      VPiM mode _ _ _ _ domain (Closure closureEnv codomain) ->
        (mode, domain) : collect (level + 1) (eval ec (VRigid level [] : closureEnv) codomain)
      _ -> []

specializeConstructorType :: EvalCtx -> Maybe [Level] -> CtorInfo -> Maybe Value
specializeConstructorType ec selectedUniverses info =
  case selectedUniverses of
    Nothing -> Just (eval ec [] (ciType info))
    Just universes ->
      let telescope = ciUniverses info
          rawType = ciType info
          provisionalMetas = nub (levelMetasOfTerm rawType)
          provisionalParameterArity = case levelParamsOfTerm rawType of
            [] -> 0
            parameters -> 1 + maximum parameters
          specialize substitution =
            Just (eval ec [] (zonkTermWith (\_ _ -> Nothing) substitution 0 rawType))
       in if dutParameterCount telescope > 0
            then
              if length universes == dutParameterCount telescope
                then specialize (substituteLevelParams universes)
                else Nothing
            else
              -- During header/SCC elaboration an inferred constructor has a
              -- provisional ordered raw-meta telescope while occurrences
              -- already carry its freshly instantiated spine.
              if not (null provisionalMetas) && length universes == length provisionalMetas
                then specialize
                  (substituteLevelMetas (Map.fromList (zip provisionalMetas universes)))
                else if null provisionalMetas && length universes == provisionalParameterArity
                  then specialize (substituteLevelParams universes)
                  else Nothing

aliasRhsObservation :: Ctx -> Text -> Term -> Value -> CheckM ObservationJudgment
aliasRhsObservation ctx aliasOrigin term classifier = do
  observation <- go ctx term classifier
  pure observation {ojOrigin = if ojMode observation == Parametric then aliasOrigin else ojOrigin observation}
  where
    -- A type alias exports the observation facet of its result, not the
    -- closed dependency set of the eta-expanded function value used to
    -- implement its source parameters.  Keep those parameters in scope while
    -- checking the terminal body so a transparent alias such as
    -- @type Keep (0 T : Type) = T@ retains T's parametric origin in the
    -- interface summary.  Ordinary application still uses the shared
    -- dependency calculus at each call site.
    go current (CLamM actualMode actualIcit quantity name body) ty =
      forceM ty >>= \case
        VPiM expectedMode expectedIcit _ borrowed _ domain closure
          | actualMode == expectedMode
          , actualIcit == expectedIcit -> do
              let rigid = VRigid (ctxLen current) []
                  current' =
                    bindCtxMQB actualMode quantity name (actualIcit == Impl) borrowed domain current
              result <- clApp closure rigid
              go current' body result
        _ -> observationJudgmentForTerm current (CLamM actualMode actualIcit quantity name body) ty
    go current body ty = observationJudgmentForTerm current body ty

-- | Resolve an independently source-prefixed let binding. The RHS judgment is
-- structural; an explicit ordinary prefix is an ordinary sink, while an
-- explicit parametric prefix is legal only for a parametric-kind classifier.
-- Quantity is intentionally absent from this decision (§12.1.1).
resolveLetObservation :: Ctx -> Span -> BinderPrefix -> Value -> ObservationJudgment -> CheckM ObservationJudgment
resolveLetObservation ctx sp prefix classifier inferred =
  case bpObservation prefix of
    Nothing -> pure inferred
    Just Ordinary -> do
      when (ojMode inferred == Parametric) $
        reportParametricPromotion sp "ordinary let binding" inferred
      observationForBinding Ordinary (ojOrigin inferred) classifier
    Just Parametric -> observationForBinding Parametric (ojOrigin inferred) classifier

-- | A declared universe-valued result also determines the exported global
-- facet. Runtime-result contracts are checked after traversing the leading
-- lambda telescope by the finalized-Core observation validator; they must not
-- overwrite the mode of the whole function value here. This is distinct from
-- an unannotated local alias, which infers and preserves its RHS facet.
resolveDeclaredResultObservation
  :: Ctx
  -> Span
  -> BinderPrefix
  -> Bool
  -> Value
  -> ObservationJudgment
  -> CheckM ObservationJudgment
resolveDeclaredResultObservation ctx sp prefix hasDeclaredResult classifier inferred = do
  typeProducing <- finalIsSort ctx classifier
  if hasDeclaredResult && typeProducing && isNothing (bpObservation prefix)
    then observationForBinding Ordinary "declared-ordinary-type-code-result" classifier
    else resolveLetObservation ctx sp prefix classifier inferred

-- | Check the terminal result of a source-declared function telescope at the
-- elaboration boundary.  The mode of the function value itself is not the
-- mode of its result: after pairing each Core lambda with its checked Pi, a
-- terminal @Type@ result is an ordinary observation sink.  Performing this
-- check here gives the source diagnostic once and prevents later level-scope
-- recovery from obscuring a genuine parametric-promotion error.
checkDeclaredOrdinaryResultObservation :: Span -> Term -> Value -> CheckM ()
checkDeclaredOrdinaryResultObservation site = go emptyCtx
  where
    go ctx term expected = case term of
      CLamM actualMode actualIcit quantity name body ->
        forceM expected >>= \case
          VPiBoundM expectedMode expectedIcit _ borrowed expectedName assumption domain closure
            | actualMode == expectedMode
            , actualIcit == expectedIcit -> do
                withAssumption <- extendLevelAssumption site ctx assumption
                let rigid = VRigid (ctxLen ctx) []
                    ctx' =
                      bindCtxMQB
                        actualMode quantity
                        (if name == "_" then expectedName else name)
                        (actualIcit == Impl) borrowed domain withAssumption
                codomain <- clApp closure rigid
                go ctx' body codomain
          _ -> pure ()
      _ -> do
        typeProducing <- finalIsSort ctx expected
        when typeProducing $ do
          observation <- observationJudgmentForTerm ctx term expected
          when (ojMode observation == Parametric) $
            reportParametricPromotion site "declared ordinary type-code result" observation

-- | §14.1.4: resolve a trait goal raised while elaborating a trait member's
-- TYPE against the current trait's supertrait premises ('csTraitSupers'). On a
-- successful unique unify (which pins any flex carrier in the goal to the
-- supertrait premise's carrier) the dictionary is the corresponding
-- 'this.__superN' projection from the trait evidence -- a closed term, so it
-- introduces no context binder that could perturb the operation's other
-- implicits. The normal declaration-specialized supertrait path search is
-- reused transitively. Diamond paths are accepted only when they produce the
-- same instantiated goal type, then declaration order selects the canonical
-- evidence projection. Inert outside
-- trait-member elaboration ('csTraitSupers' empty), so user code is unaffected.
superThisCandidate :: Ctx -> Value -> CheckM (Maybe Term)
superThisCandidate ctx goal = do
  supers <- gets csTraitSupers
  matches <- fmap catMaybes $ forM supers $ \candidate -> do
    st0 <- get
    projection <- project candidate
    solvedGoal <- traverse (const (forceM goal >>= quoteIn ctx)) projection
    put st0
    pure ((candidate,) <$> solvedGoal)
  case matches of
    [] -> pure Nothing
    ((candidate, solvedGoal) : rest)
      | all ((== solvedGoal) . snd) rest -> project candidate
      | otherwise -> pure Nothing
  where
    project (fld, premV) = do
      let direct = CProjM Ordinary (CGlob thisG) fld
      st0 <- get
      directMatch <- unify ctx premV goal
      if directMatch
        then pure (Just direct)
        else do
          put st0
          supertraitProject ctx 16 direct premV goal

-- | Whether a local context entry participates in §16.3.3's first search
-- tier. Besides source implicit binders, an explicit local root is eligible
-- exactly when its elaborated type is authenticated trait evidence. Global
-- bindings never enter 'Ctx', so this does not turn imported declarations
-- into ambient instances.
isLocalEvidenceCandidate :: CtxEntry -> CheckM Bool
isLocalEvidenceCandidate entry
  | ceImplicitLocal entry = pure True
  | otherwise = isTraitGoal (ceType entry)

localCandidate :: Ctx -> Span -> Q -> Value -> CheckM (Maybe Term)
localCandidate ctx sp q goal = go 0 [] (ctxEntries ctx)
  where
    -- anonymous binders are not referenceable and never shadow
    shadowName e = [ceName e | ceName e `notElem` ["_", "_ev"]]
    go _ _ [] = pure Nothing
    go i seen (e : rest) = do
      eligible <- isLocalEvidenceCandidate e
      if eligible && ceName e `notElem` seen
        then do
          st0 <- get
          ok <- unify ctx (ceType e) goal
          if ok
            then do
              -- Ambiguity is judged against the original flexible goal, not
              -- against the goal after the nearest candidate has solved its
              -- indices.  Otherwise local @C Int@ followed by local @C Bool@
              -- silently chooses the former for @C ?a@: solving @?a := Int@
              -- makes the latter appear not to match.  Preserve the selected
              -- candidate's unification state while probing competitors
              -- transactionally from the unsolved state.
              selected <- get
              put st0
              competing <- findNext (i + 1) (shadowName e ++ seen) rest
              put selected
              reportAmbiguous i competing
              checkCandidate i e
              pure (Just (CVar i))
            else put st0 >> go (i + 1) (shadowName e ++ seen) rest
        else go (i + 1) (shadowName e ++ seen) rest
    -- a second matching candidate in the same scope (no closure
    -- boundary between the two) is ambiguous unless the goal is authenticated
    -- trait evidence. Every fully applied trait goal carries compiler-issued
    -- @IsTrait G@ and therefore @IsSubsingleton G@ (§14.4), so same-scope
    -- candidates are coherent and the existing innermost-first order is the
    -- deterministic representative required by §16.3.3 step 1.
    reportAmbiguous i next = do
      coherentTraitGoal <- isTraitGoal goal
      let lvlOf ix = ctxLen ctx - 1 - ix
      forM_ next $ \j -> do
        let l1 = lvlOf i
            l2 = lvlOf j
            separated = any (\b -> l2 < b && b <= l1) (ctxBarriers ctx)
        unless (separated || coherentTraitGoal) $
          -- §3.1.1A: cite the goal site; the competing candidates are
          -- local context binders without stored source spans, so the
          -- payload records candidate names with sites unavailable.
          report $
            withPayload
              ( withPayloadField "candidates"
                  (T.intercalate ", " [candName i, candName j]) $
                  withPayloadField "candidateSitesAvailable" "false" $
                    payloadKind "implicit-ambiguous"
              )
              $ withRelated (related RoleObligationRequiredHere sp "implicit goal raised here")
              $ diag SevError StageElaborate "E_IMPLICIT_AMBIGUOUS" (Just "kappa.implicit.ambiguous") sp
                  "two implicit candidates in the same scope satisfy this implicit goal; the resolution is ambiguous (§16.3.3)"
    candName ix = case drop ix (ctxEntries ctx) of
      (e : _) -> ceName e
      [] -> "?"
    findNext _ _ [] = pure Nothing
    findNext j seen (e : rest) = do
      eligible <- isLocalEvidenceCandidate e
      if eligible && ceName e `notElem` seen
        then do
          st0 <- get
          ok <- unify ctx (ceType e) goal
          put st0
          if ok then pure (Just j) else findNext (j + 1) (shadowName e ++ seen) rest
        else findNext (j + 1) (shadowName e ++ seen) rest
    checkCandidate i e = do
      -- an erased candidate cannot satisfy a runtime implicit (§12.2)
      when (q /= Q0 && surfaceQuantityZero (ceQ e)) $
        errAt sp "E_QTT_ERASED_RUNTIME_USE" (Just "kappa.quantity.unsatisfied")
          ("the implicit candidate '" <> ceName e <> "' is erased (@0) and cannot satisfy a runtime implicit binder (§12.2)")
      -- a borrowed candidate may not be captured across a closure
      -- boundary (§16.3.3, §12.3.2). §3.1.1A requires the borrow
      -- introduction site AND the failing escape site as related
      -- origins: cite the candidate's recorded binder origin
      -- (RoleBorrowStart) and the capturing use site (RoleBorrowEscapeSite).
      let lvl = ctxLen ctx - 1 - i
      when (ceBorrow e && any (> lvl) (ctxBarriers ctx)) $ do
        let originKnown = ceOrigin e /= noSpan
            -- §3.1.1A line 610-611: when a required origin is
            -- unavailable, the payload records why.
            payload =
              withPayloadField "candidate" (ceName e) $
                if originKnown
                  then payloadKind "borrow-escape"
                  else
                    withPayloadField "introOriginAvailable" "false" $
                      withPayloadField "introOriginUnavailableReason"
                        "borrow introduction site untracked for this candidate kind" $
                        payloadKind "borrow-escape"
            withIntro =
              if originKnown
                then withRelated (related RoleBorrowStart (ceOrigin e)
                       ("'" <> ceName e <> "' borrowed here"))
                else id
        report $
          withPayload payload $
            withIntro $
              withRelated (related RoleBorrowEscapeSite sp
                "captured across this closure boundary here") $
                diag SevError StageElaborate "E_QTT_BORROW_ESCAPE"
                  (Just "kappa.borrow.escape") sp
                  ("the borrowed implicit candidate '" <> ceName e
                    <> "' may not be captured by a closure (§12.3.2)")

goalHasFlex :: Value -> CheckM Bool
goalHasFlex value = not . null <$> unsolvedMetaIdsIn value

-- | A checked evidence goal with a residual universe occurrence is no more
-- rigid than one with a residual term meta.  In particular, searching for
-- @Trait.{?u} a@ before the enclosing application has contributed and
-- principalized @a : Type ?u@ can reject the unique declaration instance at
-- the wrong occurrence level.  Keep the two notions separate because term
-- metas and level metas have distinct solvers, but feed either kind of
-- flexibility into the one generic postponed-evidence queue.
goalHasUniverseFlex :: Ctx -> Value -> CheckM Bool
goalHasUniverseFlex ctx value = do
  state <- get
  let assignments = csLevelAssignments state
      term =
        zonkLevels assignments
          (quote (ecOf state) (ctxLen ctx) value)
  pure (not (null (levelMetasOfTerm term)))

-- | Flush postponed trait goals after a body has been elaborated. A
-- goal whose head is still an unsolved metavariable is kept pending
-- (a later declaration's use site may determine the head, e.g. an
-- unannotated @let f x y = x + y@ used at @Int@); 'flushPendingFinal'
-- commits the survivors at the end of the module.
flushPending :: CheckM ()
flushPending = do
  flushPendingWith False False False
  flushDeferredTypeEqualities False

-- | Commit declaration-local inference choices before zonking and storing its
-- Core. Numeric defaulting belongs here (§6.1.5), while universe-flexible
-- proof goals remain deferred to the owning SCC's principalization.
flushPendingDeclaration :: CheckM ()
flushPendingDeclaration = do
  flushPendingWith False True False
  flushDeferredTypeEqualities False

flushPendingFinal :: CheckM ()
flushPendingFinal = do
  flushPendingWith True True False
  flushDeferredTypeEqualities True

-- | Close the dependency layers introduced by final evidence selection.
-- Selecting a polymorphic dictionary can instantiate a declaration-universe
-- schema and enqueue the dictionary's generated erased constraint proofs.
-- The first module-boundary solve necessarily precedes that selection, while
-- those nested proofs necessarily follow the resulting level assignments.
-- Iterate the two ordinary authorities until both queues are empty; every
-- pass consumes the current finite pending snapshot, and final-mode evidence
-- never defers an unsolved goal back onto that snapshot.
closeFinalEvidenceUniverses :: CheckM Bool
closeFinalEvidenceUniverses = do
  stateBefore <- get
  let pending = csPending stateBefore
      constraints = csLevelConstraints stateBefore
      pendingIds =
        Set.fromList [meta | (meta, _, _, _, _) <- pending]
      orphanedLevelEvidence =
        Set.difference
          (Map.keysSet (csPendingLevelEvidence stateBefore))
          pendingIds
  if not (Set.null orphanedLevelEvidence)
    then do
      errAt noSpan "E_INTERNAL" (Just "kappa.internal.compiler")
        ( "final evidence closure found authenticated level evidence without "
            <> "its pending goal"
        )
      pure False
    else
      if null pending && null constraints
        then finalizeLevelArtifacts >> pure True
        else do
          let beforeProgress = finalEvidenceProgressKey stateBefore
          solved <- solveDeferredLevelConstraints True
          if not solved
            then pure False
            else do
              flushPendingFinal
              stateAfter <- get
              let queuesRemain =
                    not (null (csPending stateAfter))
                      || not (null (csLevelConstraints stateAfter))
              if queuesRemain
                  && finalEvidenceProgressKey stateAfter == beforeProgress
                then do
                  errAt noSpan "E_INTERNAL" (Just "kappa.internal.compiler")
                    "final evidence and universe closure made no semantic progress"
                  pure False
                else closeFinalEvidenceUniverses
  where
    finalEvidenceProgressKey state =
      ( Set.fromList [meta | (meta, _, _, _, _) <- csPending state]
      , Map.keysSet (csPendingLevelEvidence state)
      , csLevelConstraintIndex state
      , csLevelAssignments state
      , Map.size (csMetas state)
      , Map.size (Map.filter isJust (csMetas state))
      )

-- | Commit every non-universe evidence choice after the complete header pass,
-- but retain flexible authenticated level propositions until declaration SCC
-- principalization has installed its final assignments. Calling the ordinary
-- final flush here used to either fabricate proof metas or diagnose valid
-- generated declaration constraints before their solver inputs existed.
flushPendingBeforeUniverseFinalization :: CheckM ()
flushPendingBeforeUniverseFinalization = do
  flushPendingWith True True True
  flushDeferredTypeEqualities False

flushPendingWith :: Bool -> Bool -> Bool -> CheckM ()
flushPendingWith final defaultNumerics deferLevelEvidence =
  flushPendingWithPolicy final defaultNumerics deferLevelEvidence True

-- | Resolve the current pending queue with an explicit policy for obligations
-- that remain unsolved. Ordinary declaration and module boundaries diagnose
-- such obligations. Scoped inference boundaries (notably existential
-- introduction) instead retain them for the enclosing boundary, after using
-- all locally available information to solve the reachable subset.
flushPendingWithPolicy :: Bool -> Bool -> Bool -> Bool -> CheckM ()
flushPendingWithPolicy final True deferLevelEvidence reportUnsolved = do
  -- §6.1.5 defaults a numeric literal only after ordinary term inference for
  -- its enclosing declaration. First close any coupled constraint component
  -- rooted in numeric evidence: all contextual equations are now available,
  -- and a unique principal solution such as @Rangeable ?a@ together with
  -- @Contains (Rangeable.Range ?a) Nat@ must determine @?a := Nat@ before
  -- defaulting. Isolated numeric evidence remains ambiguous and is left for
  -- the ordinary default below, so the open global instance set still cannot
  -- choose an otherwise unconstrained literal carrier.
  pending <- gets csPending
  settlePendingNumericComponents pending
  defaultPendingNumericGoals
  flushPendingWithPolicy final False deferLevelEvidence reportUnsolved
flushPendingWithPolicy final False deferLevelEvidence reportUnsolved = do
  when reportUnsolved $
    settlePendingEvidenceToFixedPoint final deferLevelEvidence
  flushPendingPass final deferLevelEvidence reportUnsolved

-- | Resolve pending evidence to a semantic fixed point before any diagnostic
-- pass. A proof can depend on evidence captured in its branch facts, and that
-- dependency may occur later in the insertion-ordered queue. Reporting during
-- the first traversal would therefore make source/elaboration order decide
-- whether an otherwise valid proof is accepted. Non-reporting passes retain
-- unresolved entries; solved entries and any evidence they unlock are
-- monotone, so an unchanged progress key is the exact stopping condition.
settlePendingEvidenceToFixedPoint :: Bool -> Bool -> CheckM ()
settlePendingEvidenceToFixedPoint final deferLevelEvidence = go Set.empty
  where
    go seen = do
      before <- pendingEvidenceProgressKey
      if before `Set.member` seen
        then pure ()
        else do
          flushPendingPass final deferLevelEvidence False
          after <- pendingEvidenceProgressKey
          if after == before
            then pure ()
            else go (Set.insert before seen)

pendingEvidenceProgressKey
  :: CheckM (Set MetaId, Set MetaId, Map LevelMeta Level)
pendingEvidenceProgressKey = do
  state <- get
  pure
    ( Set.fromList
        [ meta
        | (meta, _, _, _, _) <- csPending state
        ]
    , csSolvedMetas state
    , csLevelAssignments state
    )

flushPendingPass :: Bool -> Bool -> Bool -> CheckM ()
flushPendingPass final deferLevelEvidence reportUnsolved = do
  st <- get
  let pend = reverse (csPending st)
  put st {csPending = []}
  forM_ pend $ \(mid, goal, sp, ctx, bfs) -> do
    reopenSolvedPendingMeta mid
    stNow <- get
    case Map.lookup mid (csMetas stNow) of
      _ -> do
        -- §6.1.5 defaults an otherwise unconstrained numeric-literal carrier
        -- only after inference for the enclosing declaration has completed.
        -- Earlier checkpoints must retain the flexible goal so later context
        -- can choose another lawful carrier.
        -- A postponed goal captures semantic values before declaration-level
        -- universe principalization.  Reify and re-evaluate it through the
        -- current meta store before evidence search: merely forcing the old
        -- outer value leaves solved TypeLevel arguments embedded as stale
        -- flexes and can diagnose a proposition whose principalized form is
        -- already provable.
        g <- do
          ecNow <- ec_
          refreshed <- zonkTermM (ctxLen ctx) (quote ecNow (ctxLen ctx) goal)
          evalIn ctx refreshed >>= forceM
        ec <- ec_
        let quotedGoal = quote ec (ctxLen ctx) g
        equalityGoal <- isEqGoal g
        (unsolvedGoalMetas, proofRelevantLevelMetas) <-
          if equalityGoal
            then pendingProofRelevantMetas ctx bfs quotedGoal
            else do
              stGoal <- get
              pure
                ( unsolvedMetasOf stGoal quotedGoal
                , levelMetasOfTerm quotedGoal
                )
        let stillUniverseFlexible =
              not (null proofRelevantLevelMetas)
        principalLevels <-
          currentPrincipalLevelAssignmentsFor (Set.fromList unsolvedGoalMetas)
        firstClassLevelMetas <- gets csFirstClassLevelMetas
        recordedLevelConstraint <-
          gets (fmap pleConstraint . Map.lookup mid . csPendingLevelEvidence)
        -- Deferral is governed by the goal's own syntax. Traversing the
        -- semantic values behind global heads/dictionaries sees unrelated
        -- implementation metas and misclassifies a closed proposition as
        -- flexible, causing valid level obligations to be committed early.
        let stillFlex = not (null unsolvedGoalMetas)
            -- A first-class TypeLevel placeholder remains a term-level
            -- 'VFlex' until the boundary installs its level assignment. It is
            -- nevertheless determined for proposition solving when the exact
            -- level solver already has a principal image for that same stable
            -- meta identity. Do not send such a goal through the generic
            -- flexible-carrier path, which intentionally refuses global
            -- search and would skip authenticated TypeLevel propositions.
            principalLevelFlex =
              not (null unsolvedGoalMetas)
                && all (`Set.member` firstClassLevelMetas) unsolvedGoalMetas
                && maybe False
                     (\assignments -> all (`Map.member` assignments) unsolvedGoalMetas)
                     principalLevels
        -- deferral across declarations is safe only when no local
        -- implicit candidate could ever apply: the declaration's body
        -- is zonked and stored before the goal is finally committed,
        -- so a late local-candidate solution would leak local rigids
        -- into the stored term (see zonkTermM)
        let noLocalCandidates = not (any ceImplicitLocal (ctxEntries ctx))
            shouldDefer =
              (not final && isJust recordedLevelConstraint)
                || ( (stillFlex || stillUniverseFlexible)
                       && ( (not final
                               && (noLocalCandidates || (stillUniverseFlexible && not stillFlex)))
                              || (deferLevelEvidence && stillUniverseFlexible)
                          )
                   )
        -- Explicit operands later in the same spine may have made a postponed
        -- goal solvable. Always try the complete captured-context ladder
        -- before deciding to carry the goal across a declaration boundary;
        -- otherwise a universe-flexible but term-concrete local dictionary is
        -- left stuck precisely when a following explicit proof needs it.
        -- Equality goals bypass the generic flexible-trait guard: their
        -- ladder has no open-world instance choice, and its only meta
        -- assignment rule is the principal authenticated-Nat solver. This
        -- also lets branch normalization discard proof-only metas on paths
        -- that the checked branch fact has selected.
        let deferRecordedLevelProof =
              isJust recordedLevelConstraint
                && (not final || deferLevelEvidence)
        r <-
          if stillFlex
              && not principalLevelFlex
              && isNothing recordedLevelConstraint
              && not equalityGoal
            then resolvePendingFlexibleGoal ctx sp g
            else
              if deferRecordedLevelProof
                then resolvePendingGoalDeferringLevelProof ctx sp bfs recordedLevelConstraint g
                else resolvePendingGoal ctx sp bfs recordedLevelConstraint g
        case r of
          Just tm -> do
            v <- evalIn ctx tm
            solveMeta mid v
            retirePendingLevelEvidence mid
          Nothing
            | shouldDefer || not reportUnsolved ->
                modify' $ \s -> s {csPending = (mid, goal, sp, ctx, bfs) : csPending s}
            | otherwise -> do
                ambiguous <-
                  if stillFlex && not equalityGoal
                    then reportAmbiguousFlexibleInstanceGoal ctx sp g
                    else pure False
                unless ambiguous (emitUnsolvedGoal ctx sp g)
                modify' $ \state ->
                  state
                    { csDiagnosedPendingEvidence =
                        Set.insert mid (csDiagnosedPendingEvidence state)
                    }
                retirePendingLevelEvidence mid

-- | Replay conversions that were blocked on postponed evidence. A resolved
-- component must still satisfy the original equality. A component that
-- emitted an unsolved-evidence diagnostic already has its root error, so only
-- the redundant derivative mismatch is suppressed.
flushDeferredTypeEqualities :: Bool -> CheckM ()
flushDeferredTypeEqualities final = do
  state <- get
  let pending =
        Set.fromList
          [meta | (meta, _, _, _, _) <- csPending state]
      diagnosed = csDiagnosedPendingEvidence state
      ready obligation =
        final
          || Set.disjoint
               pending
               (dteEvidenceDependencies obligation)
      (readyNow, blocked) =
        List.partition ready (reverse (csDeferredTypeEqualities state))
  put
    state
      { csDeferredTypeEqualities =
          if final then [] else reverse blocked
      }
  forM_ readyNow $ \obligation ->
    unless
      ( not
          ( Set.disjoint
              diagnosed
              (dteEvidenceDependencies obligation)
          )
      )
      ( expectType
          (dteCtx obligation)
          (dteSpan obligation)
          (dteActual obligation)
          (dteExpected obligation)
      )

-- | A pending evidence meta may be filled indirectly while a later dependent
-- argument is unified (for example through @?d.Ref@).  That structural
-- equation is useful for constraining the surrounding application, but it is
-- not evidence selection and does not authenticate the candidate's type.
-- Reopen the placeholder at the pending boundary and run the ordinary ladder
-- from its captured checked goal.  Any values that already refer to the meta
-- retain its stable identity and observe the newly checked solution.
reopenSolvedPendingMeta :: MetaId -> CheckM ()
reopenSolvedPendingMeta meta =
  modify' $ \state ->
    state
      { csMetas =
          Map.adjust (const Nothing) meta (csMetas state)
      , csSolvedMetas = Set.delete meta (csSolvedMetas state)
      }

-- | Keep the generated-level-evidence side table aligned with 'csPending'.
-- Once the corresponding term meta is solved or diagnosed, its authenticated
-- relation has either become ordinary evidence or ceased to be actionable;
-- retaining it would make a completed module look inference-incomplete and
-- keep the entire level-assignment history alive downstream.
retirePendingLevelEvidence :: MetaId -> CheckM ()
retirePendingLevelEvidence meta =
  modify' $ \st ->
    st
      { csPendingLevelEvidence =
          Map.delete meta (csPendingLevelEvidence st)
      }

-- | Resolve only the selected pending evidence entries. The rest of the queue
-- remains untouched, and an unresolved selected entry is requeued rather than
-- diagnosed. This is the scoped counterpart of 'flushPendingDeclaration': it
-- performs evidence propagation without numeric defaulting, because a later
-- argument in the same enclosing expression may still determine the carrier.
flushPendingSelected :: Set MetaId -> CheckM ()
flushPendingSelected = flushPendingSelectedWithPolicy False

-- | Resolve only a selected pending component, optionally applying the
-- ordinary numeric-literal defaults inside that component. Most intermediate
-- conversion checkpoints must retain flexible numeric carriers, but a scoped
-- inference boundary such as existential sealing has no later payload
-- context: §13.2.11 requires @seal 5 as exists (a : Type). a@ to infer
-- @a := Int@ using the ordinary §6.1.5 default.
flushPendingSelectedWithPolicy :: Bool -> Set MetaId -> CheckM ()
flushPendingSelectedWithPolicy defaultNumerics selected = do
  st <- get
  let (inside, outside) =
        List.partition (\(mid, _, _, _, _) -> mid `Set.member` selected) (csPending st)
  put st {csPending = inside}
  flushPendingWithPolicy False defaultNumerics False False
  retained <- gets csPending
  modify' $ \state -> state {csPending = retained ++ outside}

-- | Find the connected component of postponed evidence that can block a
-- conversion involving the supplied values. Associated static members are
-- the motivating case: before its dictionary is selected,
-- @(?dictionary).Member@ cannot reduce far enough for conversion to inspect
-- the member result.
--
-- Connectivity is semantic, not source-name based. An evidence metavariable
-- is connected to every unsolved metavariable in its checked goal, and each
-- metavariable is connected to the unsolved metas in its creation-site
-- classifier. Taking the transitive closure also brings in numeric-literal
-- evidence sharing the carrier with a blocked trait goal. The caller can then
-- close exactly this component without committing unrelated declaration-wide
-- inference choices.
pendingEvidenceComponent :: Ctx -> [Value] -> CheckM (Set MetaId)
pendingEvidenceComponent ctx values = do
  st <- get
  ec <- ec_
  pendingEvidenceComponentFromSeed
    ctx
    ( Set.unions
        [ Set.fromList
            (unsolvedMetasOf st (quote ec (ctxLen ctx) value))
        | value <- values
        ]
    )

-- | A failed evidence search already owns the diagnostic for its exact
-- placeholder. Any conversion that still mentions that unsolved meta is
-- indeterminate recovery, not an independently established type mismatch.
-- This relation is structural and identity-based; unrelated errors and metas
-- solved after the root diagnostic are not suppressed.
conversionDependsOnDiagnosedEvidence :: Ctx -> [Value] -> CheckM Bool
conversionDependsOnDiagnosedEvidence ctx values = do
  state <- get
  evaluator <- ec_
  let dependencies =
        Set.unions
          [ Set.fromList
              ( unsolvedMetasOf
                  state
                  (quote evaluator (ctxLen ctx) value)
              )
          | value <- values
          ]
  pure
    ( not
        ( Set.disjoint
            dependencies
            (csDiagnosedPendingEvidence state)
        )
    )

-- | Term-preserving counterpart of 'pendingEvidenceComponent'. This is used
-- at proof-producing transport boundaries where NbE intentionally erases
-- proof arguments from semantic values, but the checked Core index still
-- contains the exact postponed evidence metavariable.
pendingEvidenceComponentTerms :: Ctx -> [Term] -> CheckM (Set MetaId)
pendingEvidenceComponentTerms ctx terms = do
  st <- get
  pendingEvidenceComponentFromSeed
    ctx
    ( Set.unions
        [Set.fromList (unsolvedMetasOf st term) | term <- terms]
    )

pendingEvidenceComponentFromSeed
  :: Ctx
  -> Set MetaId
  -> CheckM (Set MetaId)
pendingEvidenceComponentFromSeed _ rawSeed = do
  graph <- buildPendingEvidenceGraph
  pure (pendingEvidenceComponentIn graph rawSeed)

data PendingEvidenceGraph = PendingEvidenceGraph
  { pegPendingIds :: !(Set MetaId)
  , pegDependencies :: !(Map MetaId (Set MetaId))
  , pegReverseIndex :: !(Map MetaId (Set MetaId))
  , pegClassifierDependencies :: !(Map MetaId (Set MetaId))
  }

buildPendingEvidenceGraph :: CheckM PendingEvidenceGraph
buildPendingEvidenceGraph = do
  state <- get
  ec <- ec_
  let classifierDependencies =
        Map.map
          (Set.fromList . unsolvedMetasOf state . micType)
          (csMetaClassifiers state)
      closeClassifiers = closeClassifierDependencies classifierDependencies
      entries = csPending state
      dependencies =
        Map.fromList
          [ ( pendingEntryMeta entry
            , closeClassifiers
                ( Set.insert
                    (pendingEntryMeta entry)
                    ( Set.fromList
                        ( unsolvedMetasOf
                            state
                            (quote ec (ctxLen pendingCtx) goal)
                        )
                    )
                )
            )
          | entry@(_, goal, _, pendingCtx, _) <- entries
          ]
      reverseIndex =
        Map.fromListWith Set.union
          [ (meta, Set.singleton evidence)
          | (evidence, metas) <- Map.toList dependencies
          , meta <- Set.toList metas
          ]
  pure
    PendingEvidenceGraph
      { pegPendingIds =
          Set.fromList [pendingEntryMeta entry | entry <- entries]
      , pegDependencies = dependencies
      , pegReverseIndex = reverseIndex
      , pegClassifierDependencies = classifierDependencies
      }

closeClassifierDependencies
  :: Map MetaId (Set MetaId)
  -> Set MetaId
  -> Set MetaId
closeClassifierDependencies dependencies initial = close initial initial
  where
    close reached frontier
      | Set.null frontier = reached
      | otherwise =
          let discovered =
                Set.unions
                  [ Map.findWithDefault Set.empty meta dependencies
                  | meta <- Set.toList frontier
                  ]
              fresh = Set.difference discovered reached
           in close (Set.union reached fresh) fresh

pendingEvidenceComponentIn
  :: PendingEvidenceGraph
  -> Set MetaId
  -> Set MetaId
pendingEvidenceComponentIn graph rawSeed = close seed Set.empty
  where
    closeClassifiers =
      closeClassifierDependencies (pegClassifierDependencies graph)
    seed = closeClassifiers rawSeed
    close reachable evidence =
      let connected =
            Set.unions
              [ Map.findWithDefault Set.empty meta (pegReverseIndex graph)
              | meta <- Set.toList reachable
              ]
          evidence' = Set.union evidence connected
          reachable' =
            closeClassifiers
              ( Set.unions
                  ( reachable
                      : [ Map.findWithDefault Set.empty meta (pegDependencies graph)
                        | meta <- Set.toList evidence'
                        ]
                  )
              )
       in if reachable' == reachable && evidence' == evidence
            then evidence
            else close reachable' evidence'


-- | Commit only numeric-literal carrier choices without resolving or emitting
-- any pending evidence goal. A completed monadic action statement is an
-- inference boundary for an otherwise unconstrained overloaded literal: a
-- weak type variable captured by an earlier monadic bind is monomorphic, but
-- a later statement must not retroactively choose the first statement's
-- literal carrier. The pending goal itself remains for the ordinary evidence
-- ladder after its carrier has been fixed.
defaultPendingNumericGoals :: CheckM ()
defaultPendingNumericGoals = do
  pending <- gets csPending
  forM_ pending $ \(_, goal, _, _, _) -> forceM goal >>= defaultNumericLiteralGoal

defaultNumericLiteralGoal :: Value -> CheckM ()
defaultNumericLiteralGoal = \case
  VGlobN trait [(_, carrier)]
    | trait == gPrel traitFromInteger ->
        defaultCarrier carrier prelInt
    | trait == gPrel traitFromFloat ->
        -- Float is the surface alias; Double is the canonical runtime
        -- carrier and the declared FromFloat default (§6.1.5).
        defaultCarrier carrier prelDouble
  _ -> pure ()
  where
    -- The trait goal retains the carrier value captured when the literal was
    -- elaborated. That value may since have been solved to another meta by an
    -- enclosing expected-type check (for example @FromInteger ?lit@ followed
    -- by @Option ?lit ~ Option ?cell@). 'forceM' on the goal only exposes its
    -- global head; it deliberately does not normalize spine arguments. Chase
    -- the carrier itself so defaulting solves the current representative
    -- instead of overwriting an older alias and severing a valid equality.
    defaultCarrier carrier defaultGlobal = do
      carrier' <- forceM carrier
      case carrier' of
        VFlex meta [] -> do
          defaultType <- globalValueM defaultGlobal []
          void (solveMetaAcyclic meta defaultType)
        _ -> pure ()

-- | A pending evidence goal whose carrier is still flexible must not consult
-- the global instance set. Distinct concrete instances are disjoint once the
-- carrier is known, but all appear to match @C ?a@ and selecting the first one
-- makes declaration order decide the type of a monomorphic inferred binding.
-- Local evidence and the active trait's declared supertrait projections are
-- the only candidates that may legitimately determine such a carrier before
-- a later explicit operand or use site does.
resolvePendingFlexibleGoal :: Ctx -> Span -> Value -> CheckM (Maybe Term)
resolvePendingFlexibleGoal ctx sp goal = do
  -- A unique nearest local premise is source-provided evidence and may refine
  -- the flexible indices of its own goal (§16.3.3).  This is fundamentally
  -- different from consulting the unordered global instance set: local
  -- @Expose Int@ is authoritative for @Expose ?a@, while global @Eq Int@ and
  -- @Eq String@ must not make declaration order choose @?a@.  'localCandidate'
  -- probes all same-scope competitors against the original unsolved goal, so
  -- retaining its solution here is deterministic rather than a first-match
  -- shortcut.
  local <- localCandidate ctx sp Q0 goal
  case local of
    Just term -> pure (Just term)
    Nothing -> do
      intrinsic <-
        nonImprovingFlexibleCandidate
          goal
          (compilerIntroducedTraitEvidence ctx sp goal)
      case intrinsic of
        Just term -> pure (Just term)
        Nothing -> do
          -- Some compiler-owned introduction rules are structurally determined
          -- even while a nested proposition retains unrelated pending evidence.
          -- The important example is @IsProp (x = y)@: its proof depends on the
          -- authenticated equality carrier and @IsSet@ evidence, not on solving a
          -- dictionary occurring inside @x@ or @y@. Probe such rules
          -- transactionally and retain them only when they do not improve any
          -- metavariable already present in the goal. This is the same
          -- order-independence criterion used for polymorphic instances below.
          structural <-
            nonImprovingFlexibleCandidate goal (isPropClosure ctx sp goal)
          case structural of
            Just term -> pure (Just term)
            Nothing -> do
              traitGoal <- isTraitGoal goal
              if not traitGoal
                then pure Nothing
                else superCandidate ctx sp goal >>= \case
                  Just term -> pure (Just term)
                  Nothing -> superThisCandidate ctx goal >>= \case
                    Just term -> pure (Just term)
                    Nothing ->
                      nonImprovingFlexibleInstanceSearch ctx sp goal >>= \case
                        Just term -> pure (Just term)
                        Nothing -> pure Nothing

nonImprovingFlexibleCandidate
  :: Value
  -> CheckM (Maybe Term)
  -> CheckM (Maybe Term)
nonImprovingFlexibleCandidate goal search = do
  goalMetas <- unsolvedMetaIdsIn goal
  saved <- get
  found <- search
  after <- get
  let remainsUnsolved meta = case Map.lookup meta (csMetas after) of
        Just Nothing -> True
        _ -> False
  if isJust found && all remainsUnsolved goalMetas
    then pure found
    else put saved >> pure Nothing

-- | A polymorphic instance may discharge a goal without choosing any of its
-- still-flexible indices.  For example, @forall e. Releasable (IO e) File@
-- is valid evidence for @Releasable (IO ?e) File@ and leaves @?e@ for the
-- enclosing IO computation to determine.  The old all-or-nothing flexible
-- goal guard rejected this case along with the genuinely ambiguous @Eq ?a@.
--
-- Search transactionally and retain the result only when every metavariable
-- already present in the goal remains unsolved.  A concrete candidate such
-- as @C Int@ would solve @?a := Int@ and is therefore rolled back; a generic
-- candidate solves only its own fresh telescope metavariables in terms of the
-- goal and is safe to select.  This preserves the declaration-order
-- independence promised by the flexible-goal guard without excluding lawful
-- rank-1 polymorphic evidence.
nonImprovingFlexibleInstanceSearch :: Ctx -> Span -> Value -> CheckM (Maybe Term)
nonImprovingFlexibleInstanceSearch ctx sp goal =
  nonImprovingFlexibleCandidate goal (instanceSearch ctx sp goal)

-- | Replay the exact Boolean facts captured when a postponed obligation was
-- raised. The facts are lexical proof authority, so they are prepended only for
-- the duration of the proof-side action and never leak into later obligations.
withCapturedBoolFacts :: [ScopedBoolFact] -> CheckM a -> CheckM a
withCapturedBoolFacts captured action = do
  surrounding <- gets csBoolFacts
  modify' $ \state ->
    state {csBoolFacts = captured ++ surrounding}
  result <- action
  modify' $ \state ->
    state {csBoolFacts = surrounding}
  pure result

-- | Compute the observable meta dependencies used only by the pending-goal
-- flexibility guard. Equality itself is opaque, so normalize its two checked
-- endpoints under the captured facts and retain every dependency outside those
-- endpoints unchanged. A selected projection may thereby discard erased proof
-- payloads containing unrelated evidence metas without hiding a flexible
-- carrier or operation head. Evidence is still synthesized against the
-- original checked goal by 'resolvePendingGoal'.
pendingProofRelevantMetas
  :: Ctx
  -> [ScopedBoolFact]
  -> Term
  -> CheckM ([MetaId], [LevelMeta])
pendingProofRelevantMetas ctx captured goal = do
  stateBefore <- get
  let allOrdinary =
        Set.fromList (unsolvedMetasOf stateBefore goal)
      allLevels =
        Set.fromList (levelMetasOfTerm goal)
  case equalityExplicitEndpoints goal of
    Nothing -> pure (Set.toAscList allOrdinary, Set.toAscList allLevels)
    Just (left, right) -> do
      normalized <-
        withCapturedBoolFacts captured $
          canonicalizeTermsUnderCheckedBranchFacts ctx [left, right]
      case normalized of
        [left', right'] -> do
          stateAfter <- get
          let originalEndpointOrdinary =
                Set.fromList
                  ( unsolvedMetasOf stateBefore left
                      ++ unsolvedMetasOf stateBefore right
                  )
              normalizedEndpointOrdinary =
                Set.fromList
                  ( unsolvedMetasOf stateAfter left'
                      ++ unsolvedMetasOf stateAfter right'
                  )
              originalEndpointLevels =
                Set.fromList
                  (levelMetasOfTerm left ++ levelMetasOfTerm right)
              normalizedEndpointLevels =
                Set.fromList
                  (levelMetasOfTerm left' ++ levelMetasOfTerm right')
              relevantOrdinary =
                Set.union
                  (Set.difference allOrdinary originalEndpointOrdinary)
                  normalizedEndpointOrdinary
              relevantLevels =
                Set.union
                  (Set.difference allLevels originalEndpointLevels)
                  normalizedEndpointLevels
          pure
            ( Set.toAscList relevantOrdinary
            , Set.toAscList relevantLevels
            )
        _ -> pure (Set.toAscList allOrdinary, Set.toAscList allLevels)

resolvePendingGoal :: Ctx -> Span -> [ScopedBoolFact] -> Maybe UniverseConstraint -> Value -> CheckM (Maybe Term)
resolvePendingGoal =
  resolvePendingGoalWithLevelPolicy ResolveAuthenticatedLevelProof

-- | A declaration-owned level obligation may be known only because the
-- current provisional principal assignment chose concrete endpoints.  Before
-- that declaration's universe telescope is finalized, lexical evidence may
-- still discharge the goal, but compiler-generated proposition search must
-- leave the evidence meta intact so boundary generalization can replace it
-- with the exact generated proof binder.
resolvePendingGoalDeferringLevelProof
  :: Ctx
  -> Span
  -> [ScopedBoolFact]
  -> Maybe UniverseConstraint
  -> Value
  -> CheckM (Maybe Term)
resolvePendingGoalDeferringLevelProof =
  resolvePendingGoalWithLevelPolicy DeferAuthenticatedLevelProof

data AuthenticatedLevelProofPolicy
  = ResolveAuthenticatedLevelProof
  | DeferAuthenticatedLevelProof

resolvePendingGoalWithLevelPolicy
  :: AuthenticatedLevelProofPolicy
  -> Ctx
  -> Span
  -> [ScopedBoolFact]
  -> Maybe UniverseConstraint
  -> Value
  -> CheckM (Maybe Term)
resolvePendingGoalWithLevelPolicy levelPolicy ctx sp bfs recordedLevelConstraint g = do
  mLoc <- localCandidate ctx sp Q0 g
  -- §14.1.4: a postponed supertrait-operation dictionary (its carrier now
  -- pinned by the operation's args) resolves to the 'this.__superN'
  -- projection. Re-enter the goal's captured trait premises below as needed.
  mSuperThis <- do
    isTrait0 <- isTraitGoal g
    if isTrait0 then superThisCandidate ctx g else pure Nothing
  case mLoc <|> mSuperThis of
    Just tm -> do
      recordSelectedUniverseEvidence ctx g tm
      pure (Just tm)
    Nothing
      | DeferAuthenticatedLevelProof <- levelPolicy
      , isJust recordedLevelConstraint ->
          pure Nothing
    Nothing -> do
      mLevel <- authenticatedLevelPropositionProof ctx recordedLevelConstraint g
      case mLevel of
        Just tm -> do
          recordSelectedUniverseEvidence ctx g tm
          pure (Just tm)
        Nothing -> resolveNonLevelEvidence
  where
    resolveNonLevelEvidence = do
      cached <- lookupClosedEvidence ctx g
      case cached of
        Just tm -> do
          recordSelectedUniverseEvidence ctx g tm
          pure (Just tm)
        Nothing -> do
          isEq <- isEqGoal g
          isTrait <- isTraitGoal g
          let remember tm = do
                rememberClosedEvidence ctx g tm
                recordSelectedUniverseEvidence ctx g tm
                pure (Just tm)
          eqProp <-
            if isEq
              then withCapturedBoolFacts bfs (propProof ctx g)
              else pure Nothing
          case eqProp of
            -- Branch-refined proposition proofs are not promoted into the
            -- closed-evidence cache.
            Just tm -> pure (Just tm)
            Nothing -> do
              intrinsic <- compilerIntroducedTraitEvidence ctx sp g
              case intrinsic of
                Just tm -> remember tm
                Nothing -> do
                  mi <- if isEq then pure Nothing else instanceSearch ctx sp g
                  case mi of
                    Just tm -> remember tm
                    Nothing -> do
                      mSup <- if isTrait then superCandidate ctx sp g else pure Nothing
                      case mSup of
                        Just tm -> remember tm
                        Nothing -> do
                          prop <-
                            if isEq
                              then pure Nothing
                              else withCapturedBoolFacts bfs (propProof ctx g)
                          case prop of
                            Just tm -> pure (Just tm)
                            Nothing -> do
                              mRow <- rowProof g
                              case mRow of
                                Just tm -> remember tm
                                Nothing -> do
                                  mProp <- isPropClosure ctx sp g
                                  case mProp of
                                    Just tm -> remember tm
                                    Nothing -> pure Nothing

-- | Introduce evidence for the two compiler-authenticated first-class level
-- propositions.  The level solver decides the arithmetic judgment; the
-- transparent standard alias then unfolds to an equality proposition, whose
-- canonical erased witness is 'refl'.  Both checks are required: a user
-- function with the same source spelling cannot enter this path, and a rigid
-- false relation never receives fabricated evidence.
authenticatedLevelPropositionProof
  :: Ctx
  -> Maybe UniverseConstraint
  -> Value
  -> CheckM (Maybe Term)
authenticatedLevelPropositionProof ctx recorded goal = do
  constraint <- case recorded of
    Just constraint -> pure (Just constraint)
    Nothing ->
      fmap (fmap toConstraint) (authenticatedLevelGoalRelation ctx goal)
  case constraint of
    Nothing -> pure Nothing
    Just (UniverseConstraint lower0 upper0) -> do
      assumptions <- effectiveLevelAssumptions ctx
      assignments <- gets csLevelAssignments
      let relationLevels =
            lower0
              : upper0
              : concat
                  [ [lower, upper]
                  | (lower, upper) <- assumptionsList assumptions
                  ]
          requested =
            Set.fromList
              (concatMap (levelMetas . substituteLevelMetas assignments) relationLevels)
      principal <- currentPrincipalLevelAssignmentsFor requested
      let effectiveAssignments =
            maybe assignments (`Map.union` assignments) principal
          lower = substituteLevelMetas effectiveAssignments lower0
          upper = substituteLevelMetas effectiveAssignments upper0
          effectiveAssumptions =
            substituteLevelAssumptions effectiveAssignments assumptions
          proved = proveLevelLeq effectiveAssumptions lower upper
      if proved /= Proved
        then pure Nothing
        else Just <$> typeLevelPropositionCertificate ctx goal
  where
    toConstraint (operator, lower, upper) =
      UniverseConstraint
        (if operator == LevelOperatorLt then levelSucc lower else lower)
        upper

-- | Expose the equality proposition behind a standard level-relation alias.
-- Ordinary forcing is preferred.  During an early declaration checkpoint an
-- imported reducible alias can still be represented by its neutral global;
-- in that case unfold only the authenticated standard identity and only from
-- its checked monomorphic semantic body.
levelConstraintEqualityGoal :: Ctx -> Value -> CheckM (Maybe Value)
levelConstraintEqualityGoal ctx goal = do
  forced <- forceM goal
  case forced of
    VGlobN equality _ | equality == prelEqType -> pure (Just forced)
    VCtor equality _ | equality == prelEqType -> pure (Just forced)
    _ -> do
      ec <- ec_
      goalTerm <- zonkTermM (ctxLen ctx) (quote ec (ctxLen ctx) goal)
      case spineOfTerm goalTerm of
        (CGlobal alias universes, arguments)
          | alias == prelLevelLe || alias == prelLevelLt
          , null universes -> do
              definition <- gets (Map.lookup alias . csGlobals)
              case definition >>= gdValue of
                Just body
                  | maybe False gdReducible definition -> do
                      argumentValues <-
                        mapM
                          (\(icit, argument) -> (,) icit <$> evalIn ctx argument)
                          arguments
                      pure (Just (force ec (evalApp ec body argumentValues)))
                _ -> pure Nothing
        _ -> pure Nothing

-- | Emit an unsolved-implicit goal failure, applying §3.1.11 single-cause
-- cascade suppression so one ill-typed expression yields one diagnostic.
--
-- Two cascade shapes collapse to a single root cause:
--
--   * The goal's carrier still mentions an unsolved metavariable that an
--     earlier same-span type-equality mismatch reported against (the
--     mismatch could not be decided precisely because this carrier was
--     never solved). The mismatch is the downstream consequence: drop it
--     and keep the more informative unsolved-goal diagnostic. (e.g. an
--     overloaded value-position member whose result carrier `?m a` fails
--     against the declared result type while its trait goal is unsolved.)
--
--   * The goal's carrier is fully concrete and is exactly the type that an
--     earlier mismatch already rejected at the same site (e.g. a numeric
--     trait goal `Mul T` raised for an operand whose type `T` already
--     failed to unify with the numeric domain). Here the goal is the
--     downstream consequence: suppress it and keep the mismatch.
emitUnsolvedGoal :: Ctx -> Span -> Value -> CheckM ()
emitUnsolvedGoal ctx sp g = do
  ec <- ec_
  let gT = quote ec (ctxLen ctx) g
      gRendered = renderTerm gT
  ms <- unsolvedMetaIdsIn g
  let -- §3.1.11: unsolved metavariables now render as the stable hole
      -- `_` (never a raw `?mN` solver id). A same-span type-equality
      -- mismatch whose rendered expected/actual carries that hole is the
      -- downstream consequence of this goal's unsolved carrier (the
      -- unification was blocked precisely because a metavariable here was
      -- never solved). The structural condition is the goal still has
      -- unsolved metas ('not (null ms)') and the mismatch shows a hole.
      mentionsMeta d = any noteHasHole (dNotes d)
      -- a standalone `_` token (the rendered unsolved hole) inside an
      -- expected:/actual: note, as opposed to `_` embedded in an
      -- identifier or a `(x : _)`-style binder
      noteHasHole note = "_" `elem` T.words (T.map spaceP note)
      spaceP c = if c `elem` ("():," :: String) then ' ' else c
      isMismatch d = dCode d == "E_TYPE_EQUALITY_MISMATCH"
      -- the goal's trait arguments, rendered (e.g. the carrier `T` of
      -- `Mul T`): a concrete carrier already named in a mismatch note
      carrierTexts = case gT of
        CApp _ _ _ -> [renderTerm a | a <- spineArgs gT]
        _ -> []
      spineArgs = reverse . go
        where
          go (CApp _ f a) = a : go f
          go _ = []
  ds <- gets csDiags
  let sameStart d = spanStart (dPrimary d) == spanStart sp
      isDownstreamMismatch d = isMismatch d && sameStart d && mentionsMeta d
      hasDownstreamMismatch = not (null ms) && any isDownstreamMismatch ds
      concreteCarrierAlreadyRejected =
        null ms
          && not (null carrierTexts)
          && any
            ( \d ->
                isMismatch d
                  && posLine (spanStart (dPrimary d)) == posLine (spanStart sp)
                  && any (\ct -> any (ct `T.isInfixOf`) (dNotes d)) carrierTexts
            )
            ds
      goalMsg = "could not resolve implicit argument of type " <> gRendered
      emit = errAt sp "E_UNSOLVED_IMPLICIT" (Just "kappa.implicit.unsolved") goalMsg
      summarize d =
        Suppressed (dCode d) (dFamily d) (dPrimary d) (dMessage d)
  if hasDownstreamMismatch
    then do
      -- §3.1.10/§3.1.11: drop the downstream same-span mismatch and keep
      -- the unsolved goal, recording the dropped mismatch in the survivor's
      -- 'suppressed' summary so tooling can still show it.
      let dropped = [summarize d | d <- ds, isDownstreamMismatch d]
      modify' $ \st -> st {csDiags = filter (not . isDownstreamMismatch) (csDiags st)}
      report $
        withSuppressed dropped $
          diag SevError StageElaborate "E_UNSOLVED_IMPLICIT" (Just "kappa.implicit.unsolved") sp goalMsg
    else
      if concreteCarrierAlreadyRejected
        then
          -- the goal is the cascade of an already-reported mismatch:
          -- record its summary on that surviving root mismatch (§3.1.11).
          modify' $ \st ->
            let supp = Suppressed "E_UNSOLVED_IMPLICIT" (Just "kappa.implicit.unsolved") sp goalMsg
                onLine d = isMismatch d && posLine (spanStart (dPrimary d)) == posLine (spanStart sp)
                -- attach to the first matching root mismatch only
                attachOnce [] = []
                attachOnce (d : rest)
                  | onLine d = withSuppressed [supp] d : rest
                  | otherwise = d : attachOnce rest
             in st {csDiags = attachOnce (csDiags st)}
        else emit

-- | Cache key for globally reusable implicit evidence.  The key is the exact
-- de-Bruijn Core shape, not pretty-printed prose.  A key is produced only for
-- closed goals, because local rigids make evidence context-sensitive.  The
-- semantic epoch is part of the key, so global/trait/instance changes cannot
-- reuse stale evidence even if a future state mutation forgets to clear the
-- map eagerly.
closedEvidenceKey :: Ctx -> Value -> CheckM (Maybe EvidenceCacheKey)
closedEvidenceKey ctx goal = do
  branchLocal <- gets (not . null . csBoolFacts)
  if branchLocal || any ceImplicitLocal (ctxEntries ctx)
    then pure Nothing
    else do
      ec <- ec_
      st <- get
      let gT = quote ec (ctxLen ctx) goal
      pure $
        if termClosed gT
            && null (levelMetasOfTerm gT)
            && termCacheUniverseScoped st gT
          then
            Just
              ( EvidenceCacheKey
                  (csActiveUniverseDefinition st)
                  (T.pack (show (csNormEpoch st)) <> "\x1e" <> renderStructuralTermKey gT)
              )
          else Nothing

lookupClosedEvidence :: Ctx -> Value -> CheckM (Maybe Term)
lookupClosedEvidence ctx goal = do
  mk <- closedEvidenceKey ctx goal
  case mk of
    Nothing -> pure Nothing
    Just k -> gets (Map.lookup k . csEvidenceCache)

rememberClosedEvidence :: Ctx -> Value -> Term -> CheckM ()
rememberClosedEvidence ctx goal tm = do
  -- Branch facts are proof sources (§3.2.3), not global theorems.  Reusing a
  -- proof found under `if c then ...` outside that branch would be unsound even
  -- when the goal term itself is closed.  Positive closed-evidence caching is
  -- therefore restricted to the empty branch-fact environment.
  branchLocal <- gets (not . null . csBoolFacts)
  unless branchLocal $ do
    mk <- closedEvidenceKey ctx goal
    forM_ mk $ \k ->
      do
        st <- get
        when
          ( termClosed tm
              && null (levelMetasOfTerm tm)
              && termCacheUniverseScoped st tm
          ) $
          modify' $ \state ->
            state
              { csEvidenceCache =
                  boundedInsert maxEvidenceCacheEntries k tm (csEvidenceCache state)
              }

-- | Unsolved ordinary term metavariables. Universe metavariables share the
-- numeric identifier representation but have a separate solution table and
-- are classified by 'levelMetasOfTerm'; conflating the two commits deferred
-- universe obligations as though they contained flexible term evidence.
unsolvedMetasOf :: CheckState -> Term -> [MetaId]
unsolvedMetasOf st t =
  [ m
  | m <- nub (foldTerm ordinaryMeta (const []) t)
  , case Map.lookup m (csMetas st) of
      Just (Just _) -> False
      _ -> True
  ]
  where
    ordinaryMeta = \case
      CMeta meta -> [meta]
      _ -> []

registerDiscardedResult :: Ctx -> Span -> Value -> CheckM ()
registerDiscardedResult ctx sp ty =
  modify' $ \st ->
    st
      { csPendingDiscardedResults =
          PendingDiscardedResult sp ctx ty : csPendingDiscardedResults st
      }

-- | Commit §18.2 discard obligations after ordinary inference and postponed
-- evidence have reached their declaration boundary. A wholly unconstrained
-- payload specializes to Unit; solved payload types are handed to Usage, which
-- owns the structural QTT decision and diagnostics.
finalizeDiscardedResults :: CheckM ()
finalizeDiscardedResults = do
  st <- get
  let pending = reverse (csPendingDiscardedResults st)
  modify' $ \state -> state {csPendingDiscardedResults = []}
  unless (any ((== SevError) . dSeverity) (csDiags st)) $ do
    forM_ pending $ \PendingDiscardedResult {..} -> do
      -- A non-final expression supplies no observable payload context. When
      -- its entire payload type is still an unconstrained meta, choose Unit as
      -- the principal droppable specialization. This is the same contextual
      -- choice the desugaring's ignored lambda binder permits, and is required
      -- for polymorphic non-returning actions such as raise/reraise. Do not
      -- default metas nested inside an otherwise known payload type: those are
      -- real ambiguities in the value being discarded.
      finalizedType <- forceM pdrType >>= \case
        VFlex meta [] -> do
          unitType <- globalValueM prelUnit []
          solveMeta meta unitType
          pure unitType
        other -> pure other
      tyTm0 <- quoteIn pdrCtx finalizedType
      tyTm <- zonkTermM (ctxLen pdrCtx) tyTm0
      state <- get
      let unresolved = Set.fromList (unsolvedMetasOf state tyTm)
      if not (Set.null unresolved)
        then
          report $
            withPayload
              ( withPayloadField "metavariableKind" "discarded-result-type"
                  $ withPayloadField "sourceOrigin" (T.pack (show pdrSpan))
                  $ withPayloadField "constraints" "no remaining constraint determines the discarded result type"
                  $ withPayloadField "blockedObligations" "droppability"
                  $ withPayloadField "defaultingAttempted" "true"
                  $ withPayloadField "defaultingFailureReason" "no explicit defaulting rule applies"
                  $ withPayloadField "metavariables" (T.pack (show (Set.toAscList unresolved)))
                  $ payloadKind "unsolved-metavariable"
              )
              $ diag SevError StageElaborate "E_UNSOLVED_METAVARIABLE"
                (Just "kappa.type.unsolved-metavariable")
                pdrSpan
                "the discarded result type remains ambiguous, so its §12.2.6 droppability cannot be proved; bind it with an explicit type or constrain the action result (§18.2)"
        else
          case delaborateType pdrCtx pdrSpan tyTm of
            Just sourceType ->
              modify' $ \state ->
                state
                  { csDiscardedResultTypes =
                      Map.insert pdrSpan sourceType (csDiscardedResultTypes state)
                  }
            Nothing ->
              report $
                diag SevError StageElaborate "E_QTT_LINEAR_DROP"
                  (Just "kappa.quantity.positive-lower-bound")
                  pdrSpan
                  "the compiler cannot establish that this discarded result type is droppable (§12.2.6, §18.2)"

-- | Unsolved metavariable identifiers occurring in a value's quotation.
unsolvedMetaIdsIn :: Value -> CheckM [MetaId]
unsolvedMetaIdsIn v = do
  ec <- ec_
  let t = quote ec 0 v
  st <- get
  pure (unsolvedMetasOf st t)

-- | Replace solved metavariables by their solutions, quoted at the
-- correct binder depth. Run after 'flushPending' so terms stored as
-- globals (and instance dictionaries) contain no live 'CMeta' whose
-- solution mentions local rigids (premise dictionaries, §14.3.2).
zonkTermM :: Int -> Term -> CheckM Term
zonkTermM depth0 t0 = do
  ec <- ec_
  st <- get
  assignments <- gets csLevelAssignments
  let resolve = resolvedMetaCore st ec
      resolveLevel = substituteLevelMetas assignments
  pure (zonkTermWith resolve resolveLevel depth0 t0)

-- | Reify one solved typed metavariable back to Core. Evaluation is
-- intentionally transparent through 'CUniverseLift', so the meta store can
-- retain only the semantic value. The creation-site classifier and the
-- solver-selected proof are the authority for restoring that erased
-- cumulative use; callers must not infer it from the solved value's shape.
resolvedMetaCore :: CheckState -> EvalCtx -> Int -> MetaId -> Maybe Term
resolvedMetaCore st ec depth meta = do
  solution <- Map.lookup meta (ecMetas ec) >>= id
  let term0 = quote ec depth solution
      term =
        case Map.lookup meta (csMetaClassifiers st) of
          Just MetaClassifier {micDepth, micType}
            | depth >= micDepth ->
                etaLongAtClassifier
                  term0
                  (shiftTerm (depth - micDepth) 0 micType)
          _ -> term0
  pure $
    case Map.lookup meta (csMetaClassifiers st) >>= micUniverseCoercion of
      Just evidence -> universeLift evidence term
      Nothing -> term
  where
    -- NbE stores higher-order meta solutions extensionally. For a Miller
    -- equation such as @?P x = F x@ the semantic solution may therefore be
    -- the head @F@ even when @?P@'s authenticated Pi classifier has a
    -- different quantity or observation mode. Reifying that head verbatim
    -- produces ill-typed Core (notably for quantity-0 equality motives).
    --
    -- Eta-long reification is the standard typed boundary: every generated
    -- lambda takes its contract from the creation-site classifier and applies
    -- the semantic solution to the same binder. KCore independently checks
    -- the result, so this cannot turn an invalid semantic solution into an
    -- accepted artifact. Borrowed Pi binders have no lambda representation
    -- and therefore remain fail-closed.
    etaLongAtClassifier solutionTerm = \case
      CPiEvidenceM mode _ ic quantity False name _ _ _ codomain ->
        CLamM
          mode
          ic
          quantity
          name
          ( etaLongAtClassifier
              (CApp ic (shiftTerm 1 0 solutionTerm) (CVar 0))
              codomain
          )
      _ -> solutionTerm

isTraitGoal :: Value -> CheckM Bool
isTraitGoal v =
  forceM v >>= \case
    VGlobN g arguments -> do
      state <- get
      pure $
        if g == gPrel "IsTrait"
          then length arguments == 1
          else case Map.lookup g (csTraits state) of
            Just info ->
              maybe
                False
                ((== tiParamCount info) . length)
                (traitSemanticSpineIn state g arguments)
            Nothing -> False
    _ -> pure False

-- | Remove the physically present declaration-universe proof prefix from a
-- resolved trait application.  Instance heads, supertrait closures, and
-- member telescopes are defined over the trait's semantic source parameters;
-- generated/user level proofs are ordinary implicit Core arguments but are
-- not additional trait parameters.  The exact resolved global type is the
-- authority, so an ordinary implicit parameter can never be dropped merely
-- because its source shape resembles evidence.
traitSemanticSpineIn
  :: CheckState
  -> GName
  -> [(Icit, argument)]
  -> Maybe [(Icit, argument)]
traitSemanticSpineIn st trait arguments = do
  definition <- Map.lookup trait (csGlobals st)
  info <- Map.lookup trait (csTraits st)
  let semanticCount = tiParamCount info
      parameterCount = dutParameterCount (gdUniverses definition)
      proofCount =
        length
          ( declarationUniverseConstraints
              parameterCount
              (globalCoreType (ecOf st) definition)
          )
      (proofArguments, semanticArguments) = splitAt proofCount arguments
  if length arguments == semanticCount
    then
      -- Checker-owned semantic goals are built by 'globalValueM': the hidden
      -- universe instance is explicit in 'VGlobal', while generated
      -- declaration-constraint proofs are not materialized in the value spine.
      -- Exact source arity authenticates this representation.
      pure arguments
    else do
      -- Values evaluated from finalized Core carry the physical erased proof
      -- prefix. Validate that complete prefix before exposing source arguments.
      guard (length proofArguments == proofCount)
      guard (all ((== Impl) . fst) proofArguments)
      guard (length semanticArguments == semanticCount)
      pure semanticArguments

isEqGoal :: Value -> CheckM Bool
isEqGoal v =
  forceM v >>= \case
    VGlobN g _ | g == prelEqType -> pure True
    VCtor g _ | g == prelEqType -> pure True
    _ -> pure False

-- | Is the goal one of the §11.3.1A intrinsic row traits (solved by
-- compiler-owned introduction rules, postponed while its row is flex)?
isRowGoal :: Value -> CheckM Bool
isRowGoal v =
  forceM v >>= \case
    VGlobN (GName pm "LacksRec") _ | pm == preludeModule -> pure True
    _ -> pure False

-- | §11.3.1A compiler-owned introduction rules: @LacksRec r l@ is
-- solvable iff the normalized row tail @r@ contains no label @l@ —
-- for a closed residual row, decided structurally on its fields.
rowProof :: Value -> CheckM (Maybe Term)
rowProof goal = do
  g <- forceM goal
  case g of
    VGlobN (GName pm "LacksRec") [(_, rowV), (_, lblV)]
      | pm == preludeModule -> do
          row <- forceM rowV
          lbl <- forceM lblV
          case (row, lbl) of
            (VGlobN (GName pm2 "__closedRow") [(_, fieldsV)], VLit (LitStr l))
              | pm2 == preludeModule -> do
                  fsF <- forceM fieldsV
                  case fsF of
                    VRecordT fs
                      | l `notElem` map fst fs ->
                          Just <$> globalHeadM prelRowEvidence
                    _ -> pure Nothing
            _ -> pure Nothing
    _ -> pure Nothing

-- | Whether a forced value is an unsolved metavariable (a flexible head).
isFlexV :: Value -> Bool
isFlexV (VFlex _ _) = True
isFlexV _ = False

instanceSearch :: Ctx -> Span -> Value -> CheckM (Maybe Term)
instanceSearch ctx sp goal =
  searchDepth 0 ctx sp goal

searchDepth :: Int -> Ctx -> Span -> Value -> CheckM (Maybe Term)
searchDepth depth ctx sp goal
  | depth > 16 = pure Nothing -- §14.3.5 termination backstop
  | otherwise = do
      g <- forceM goal
      case g of
        VGlobI traitG goalUniverses spine -> do
          st <- get
          -- §14.3.1/§14.3.5: a PREMISE goal (depth > 0) whose trait arguments
          -- all force to bare unsolved metavars is underdetermined and MUST NOT
          -- drive instance selection. Without this, a recursive multi-premise
          -- instance (e.g. `(Eq e, Eq a) => Eq (Result e a)`) makes its premise
          -- goals `Eq ?e`/`Eq ?a` match the instance's own head, assigning the
          -- metavars and recursing with fan-out — an exponential blow-up up to
          -- the depth backstop. The cut is confined to premise resolution: a
          -- top-level use-site goal (depth 0) whose metavar is solved BY the
          -- matching instance still resolves, and determined goals
          -- (`Eq Integer`, `Eq a`, `Eq (Result ?e ?a)`) always resolve.
          case (Map.lookup traitG (csTraits st), traitSemanticSpineIn st traitG spine) of
            (Just _, Just semanticSpine) -> do
              spineFlex <- mapM (fmap isFlexV . forceM . snd) semanticSpine
              if depth > 0 && not (null semanticSpine) && and spineFlex
                then pure Nothing
                else do
                  (_, rawHits) <-
                    matchingInstanceTrials
                      depth
                      ctx
                      traitG
                      goalUniverses
                      (map snd semanticSpine)
                  let (incompleteSelfHits, hits) =
                        if csForbidIncompleteSelfEvidence st
                          then
                            List.partition
                              (\(entry, _, _) ->
                                Just (ieDict entry)
                                  == csActiveUniverseDefinition st)
                              rawHits
                          else ([], rawHits)
                  case sortOn (ieDict . first3) hits of
                    [(_, tm, selectedState)] -> put selectedState >> pure (Just tm)
                    [] -> do
                      put st
                      unless (null incompleteSelfHits) $
                        errOncePerSpan sp "E_DERIVE_INCOMPLETE_SELF" (Just "kappa.derive")
                          "instance completion cannot reify its own incomplete evidence value (§14.3.4A)"
                      pure Nothing
                    ((ie0, tm, selectedState) : rest) -> do
                      -- §33.2.1 step 3: equivalent evidence artifacts are
                      -- harmless overlap — select the deterministic
                      -- representative; only non-equivalent overlap is
                      -- incoherent
                      canonical <- forM ((ie0, tm, selectedState) : rest) $ \(ie, candidate, candidateState) -> do
                        put candidateState
                        normalized <- zonkTermM (ctxLen ctx) candidate
                        normalizedState <- get
                        pure (ie, normalized, normalizedState)
                      put st
                      ecu <- ec_
                      values <- mapM (evalIn ctx . second3) canonical
                      let equivalent = case values of
                            value : others -> all (convertible ecu (ctxLen ctx) value) others
                            [] -> False
                      case canonical of
                        (_, selectedTerm, selectedFinalState) : _ -> do
                          put selectedFinalState
                          unless equivalent $ do
                            -- a candidate whose dictionary value is not yet
                            -- defined (§14.3 pre-pass entry whose members are
                            -- checked later in this module) cannot be compared
                            -- for equivalence here; the declaration-level
                            -- §14.3/§33.2.1 coherence check judges that pair
                            -- definitively, so do not pre-judge the overlap
                            pending <- filterM (dictValuePending . ieDict) (map first3 canonical)
                            when (null pending) $ do
                              -- §3.1.1A: trait-coherence diagnostics MUST include
                              -- every surviving incoherent instance declaration
                              -- site.
                              rels <- instanceRelateds (map first3 canonical)
                              report $
                                withRelateds rels $
                                  diag SevError StageElaborate "E_INSTANCE_INCOHERENT" (Just "kappa-hs.trait.incoherent") sp
                                    "multiple instances match this trait obligation (§14.3.1 coherence)"
                          -- The sorted representative and its isolated state are
                          -- committed regardless of input instance order.
                          pure (Just selectedTerm)
                        [] -> put st >> pure Nothing
            _ -> pure Nothing
        _ -> pure Nothing
  where
    first3 (value, _, _) = value
    second3 (_, value, _) = value

type InstanceTrial = (InstanceEntry, Term, CheckState)

-- | Enumerate successful ordinary-instance candidates transactionally from
-- one baseline. This is the shared candidate authority for ordinary coherent
-- selection and bounded pending-component solving; neither caller may let one
-- candidate's metavariable assignments influence another candidate trial.
matchingInstanceTrials
  :: Int
  -> Ctx
  -> GName
  -> [Level]
  -> [Value]
  -> CheckM (CheckState, [InstanceTrial])
matchingInstanceTrials depth ctx trait goalUniverses goalArguments = do
  baseline <- get
  let candidates =
        sortOn ieDict
          [entry | entry <- csInstances baseline, ieTrait entry == trait]
  trials <- fmap catMaybes . forM candidates $ \entry -> do
    put baseline
    result <- tryInstance depth ctx goalUniverses goalArguments entry
    trialState <- get
    put baseline
    pure ((\term -> (entry, term, trialState)) <$> result)
  pure (baseline, trials)

-- | Whether an instance dictionary's value is still pending (its
-- declaration's members have not been checked yet — the §14.3
-- pre-pass registers heads ahead of the body pass).
dictValuePending :: GName -> CheckM Bool
dictValuePending g = gets (maybe True (isNothing . gdValue) . Map.lookup g . csGlobals)

-- | §3.1.1A: the declaration site of an instance, recovered from the
-- §14.3 pre-pass table ('csPreInstances' is keyed by declaration span)
-- by its dictionary global. Returns Nothing for instances with no
-- pre-pass entry (built-in/imported).
instanceDeclSite :: GName -> CheckM (Maybe Span)
instanceDeclSite dictG = do
  pre <- gets csPreInstances
  pure $ listToMaybe [sp | (sp, Just pii) <- Map.toList pre, piDictG pii == dictG]

-- | §3.1.1A trait-coherence related origins: every surviving incoherent
-- instance's declaration site (those with a known pre-pass span).
instanceRelateds :: [InstanceEntry] -> CheckM [RelatedOrigin]
instanceRelateds ies = do
  sites <- mapM (instanceDeclSite . ieDict) ies
  pure
    [ related RoleInstanceDeclarationSite s "a matching instance is declared here"
    | Just s <- sites
    ]

tryInstance :: Int -> Ctx -> [Level] -> [Value] -> InstanceEntry -> CheckM (Maybe Term)
tryInstance depth ctx goalUniverses goalArgs ie
  | length (ieHead ie) /= length goalArgs = pure Nothing
  | otherwise = do
      saved <- get
      (rawDictHead, rawDictType, specializeLevel, specialize) <- instantiateInstanceOccurrence ctx ie
      occurrenceState <- get
      let occurrenceLevelMetas =
            Set.intersection
              (Set.fromList (levelMetasOfTerm rawDictHead))
              ( Set.difference
                  (csLevelInstantiationMetas occurrenceState)
                  (csLevelInstantiationMetas saved)
              )
      metas <- forM [1 .. ieTeleLen ie] (const freshMeta)
      metaVs <- mapM (evalIn emptyCtx) metas
      ec <- ec_
      levelAssignments <- gets csLevelAssignments
      let resolveLevel = normalizeLevel . substituteLevelMetas levelAssignments
          instanceUniverses = map (resolveLevel . specializeLevel) (ieTraitUniverses ie)
          goalUniverses' = map resolveLevel goalUniverses
          headVs = [eval ec (reverse metaVs) (specialize t) | t <- ieHead ie]
      universeOk <-
        if length instanceUniverses /= length goalUniverses'
          then pure False
          else
            foldM
              (\ok (instanceUniverse, goalUniverse) ->
                 if ok
                   then solveLevelIdentity ctx instanceUniverse goalUniverse
                   else pure False)
              True
              (zip instanceUniverses goalUniverses')
      oks <-
        if universeOk
          then zipWithM (unifyInstanceArgument ctx (ieTrait ie)) headVs goalArgs
          else pure []
      if universeOk && and oks
        then do
          let premVs = [eval ec (reverse metaVs) (specialize p) | p <- iePremises ie]
          prems <- forM premVs $ \pv -> do
            mLoc <- localCandidate ctx noSpan Q0 pv
            case mLoc of
              Just t -> pure (Just t)
              Nothing -> do
                mi <- searchDepth (depth + 1) ctx noSpan pv
                case mi of
                  Just t -> pure (Just t)
                  Nothing -> do
                    -- §14.1.4: premise resolution is local implicit
                    -- resolution, so an in-scope evidence value may be
                    -- projected to any of its declared supertraits — e.g.
                    -- discharging an `Eq a` premise from a `Hashable a`
                    -- binder via Hashable's Eq supertrait field.
                    mSup <- superCandidate ctx noSpan pv
                    case mSup of
                      Just t -> pure (Just t)
                      Nothing -> propProof ctx pv
          if all isJust prems
            then do
              dictHead <- case rawDictType of
                Just dictionaryType ->
                  fst <$> insertDeclarationConstraintImplicits
                    ctx noSpan rawDictHead dictionaryType
                Nothing -> pure rawDictHead
              metaTms <- mapM (quoteIn ctx) =<< mapM (evalIn emptyCtx) metas
              -- the dictionary lambda binds only the head's type
              -- variables and then the premise dictionaries; the metas
              -- standing for premise slots are not applied
              let nFv = ieTeleLen ie - length (iePremises ie)
                  dict =
                    List.foldl' (\f a -> CApp Impl f a)
                      (List.foldl' (\f a -> CApp Impl f a) dictHead (take nFv metaTms))
                      (catMaybes prems)
              principalizeLevelOccurrence
                (ctxLen ctx)
                saved
                occurrenceLevelMetas
                dict >>= \case
                  Nothing -> put saved >> pure Nothing
                  Just (assignments, closedDict) -> do
                    installLevelAssignments assignments
                    pure (Just closedDict)
            else put saved >> pure Nothing
        else put saved >> pure Nothing

-- | The standard @Monotone (add k)@ instance also covers the source-level
-- eta form @\x -> x + k@ because the checked TypeLevel algebra makes addition
-- commutative.  Restrict this stronger comparison to an actual lambda at the
-- goal site: named user functions retain ordinary instance identity and can
-- select their own exact instance even when their implementation happens to
-- be extensionally equal to a standard operation.
unifyInstanceArgument :: Ctx -> GName -> Value -> Value -> CheckM Bool
unifyInstanceArgument ctx trait instanceArgument goalArgument = do
  saved <- get
  ordinary <- unify ctx instanceArgument goalArgument
  if ordinary
    then pure True
    else do
      put saved
      associated <-
        improveAssociatedProjection ctx instanceArgument goalArgument
      if associated
        then pure True
        else do
          put saved
          semantic <- case goalArgument of
            VLamM {} | trait == prelMonotone ->
              typeLevelEndofunctionsEqual ctx instanceArgument goalArgument
            _ -> pure False
          unless semantic (put saved)
          pure semantic

-- | Improve a stuck associated static-member projection while matching an
-- instance head. The receiver must be an evidence metavariable with an exact
-- checked trait classifier, and the projected field must be an authenticated
-- associated static member of that trait. Candidate dictionaries are tried from
-- one baseline, their actual member values are compared to the demanded
-- instance argument, and only one surviving candidate may be committed.
--
-- This is the bounded associated-type improvement needed by ordinary
-- constraints such as @Contains (Rangeable.Range ?v) Nat@: the unique
-- @Rangeable Nat@ dictionary exposes @Range = NumericRange Nat@ and thereby
-- determines @?v@. No field spelling, source declaration order, or partial
-- candidate state is used as semantic authority.
improveAssociatedProjection :: Ctx -> Value -> Value -> CheckM Bool
improveAssociatedProjection ctx demanded projected = do
  baseline <- get
  projected' <- forceM projected
  case projected' of
    VProjN _ (VFlex evidenceMeta []) field ->
      case Map.lookup evidenceMeta (csMetaClassifiers baseline) of
        Just classifier
          | micDepth classifier == ctxLen ctx -> do
              receiverType <- evalIn ctx (micType classifier) >>= forceM
              case receiverType of
                VGlobI receiverTrait receiverUniverses receiverSpine
                  | Just traitInfo <- Map.lookup receiverTrait (csTraits baseline)
                  , field `Set.member` tiAssociatedStaticMembers traitInfo
                  , Just semanticSpine <-
                      traitSemanticSpineIn baseline receiverTrait receiverSpine -> do
                      (_, trials) <-
                        matchingInstanceTrials
                          0
                          ctx
                          receiverTrait
                          receiverUniverses
                          (map snd semanticSpine)
                      matches <-
                        fmap catMaybes . forM trials $
                          \(_, dictionary, candidateState) -> do
                            put candidateState
                            memberValue <-
                              evalIn ctx
                                ( CProjM
                                    ( Map.findWithDefault
                                        Ordinary
                                        field
                                        (tiMemberModes traitInfo)
                                    )
                                    dictionary
                                    field
                                )
                                >>= forceM
                            matched <- unify ctx demanded memberValue
                            matchedState <- get
                            put baseline
                            pure
                              ( if matched
                                  then Just (dictionary, matchedState)
                                  else Nothing
                              )
                      case matches of
                        [(dictionary, selectedState)] -> do
                          put selectedState
                          dictionaryValue <- evalIn ctx dictionary
                          solved <- solveMetaAcyclic evidenceMeta dictionaryValue
                          unless solved (put baseline)
                          pure solved
                        _ -> put baseline >> pure False
                _ -> put baseline >> pure False
        _ -> put baseline >> pure False
    _ -> put baseline >> pure False

-- | Solve equality of two checked TypeLevel endofunctions at a fresh rigid
-- argument.  Only metas belonging to the candidate instance may be solved,
-- and their solutions must be independent of that argument; this is the
-- occurs-style condition that distinguishes a fixed partial application from
-- an arbitrary lambda.  The ordinary level solver supplies AC cancellation
-- and the same principal-solution discipline used at declaration boundaries.
typeLevelEndofunctionsEqual :: Ctx -> Value -> Value -> CheckM Bool
typeLevelEndofunctionsEqual ctx left right = do
  typeLevel <- globalValueM prelTypeLevel []
  ec <- ec_
  let binderLevel = ctxLen ctx
      variable = VRigid binderLevel []
      extended = bindCtxMQ Parametric Q0 "__level" False typeLevel ctx
  leftTerm <- quoteIn extended (vapp ec left Expl variable)
  rightTerm <- quoteIn extended (vapp ec right Expl variable)
  (_, leftIdentity) <- levelIdentityOfCheckedTerm extended leftTerm
  (_, rightIdentity) <- levelIdentityOfCheckedTerm extended rightTerm
  case (leftIdentity, rightIdentity) of
    (Right leftLevel, Right rightLevel) -> do
      let instanceMetas = Set.fromList (levelMetas leftLevel)
      assumptions <- effectiveLevelAssumptions extended
      let origin = ConstraintOrigin "TypeLevel endofunction identity" "instance head"
          constraints =
            [ LevelConstraint (-1) leftLevel rightLevel origin assumptions
            , LevelConstraint (-2) rightLevel leftLevel origin assumptions
            ]
      if Set.null instanceMetas
        then pure (normalizeLevel leftLevel == normalizeLevel rightLevel)
        else case solveLevelConstraintsFor instanceMetas constraints of
          Left _ -> pure False
          Right solution -> do
            let assignments = lsAssignments solution
                residualMetas = Set.fromList
                  [ meta
                  | constraint <- lsResidual solution
                  , meta <- levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint)
                  ]
                assignmentIsConstant meta = case Map.lookup meta assignments of
                  Just assigned ->
                    binderLevel
                      `notElem` levelVars (substituteLevelMetas assignments assigned)
                  Nothing -> False
                solvedLeft = normalizeLevel (substituteLevelMetas assignments leftLevel)
                solvedRight = normalizeLevel (substituteLevelMetas assignments rightLevel)
            if Set.null (Set.intersection instanceMetas residualMetas)
                && solvedLeft == solvedRight
                && all assignmentIsConstant (Set.toList instanceMetas)
              then installLevelAssignments assignments >> pure True
              else pure False
    _ -> pure False

-- | Freshen one instance occurrence through its dictionary declaration's
-- universe schema. During the header/body overlap the dictionary telescope is
-- intentionally still provisional: its interface contains source level metas
-- and the stable 'LParam' telescope is installed only at SCC
-- principalization. Treating the then-empty telescope as monomorphic lets the
-- first instance search pin those source metas globally. The dictionary global
-- is the schema authority, so instantiate it once and apply that exact
-- source-to-occurrence substitution to both the instance head and premises.
instantiateInstanceOccurrence
  :: Ctx
  -> InstanceEntry
  -> CheckM (Term, Maybe Value, Level -> Level, Term -> Term)
instantiateInstanceOccurrence ctx ie = do
  definition <- gets (Map.lookup (ieDict ie) . csGlobals)
  case definition of
    Just gd -> do
      (rawDictHead, rawDictType, universes) <- instantiateGlobal (ieDict ie) gd
      assignments <- gets csLevelAssignments
      finalizedMetaMap <-
        gets
          ( Map.findWithDefault Map.empty (ieDict ie)
              . csFinalizedGlobalUniverseMetaMaps
          )
      ec <- ec_
      let telescope = gdUniverses gd
          declarationLevels = Map.union finalizedMetaMap assignments
          rawDictionaryType =
            zonkTermWith
              (\_ _ -> Nothing)
              (substituteLevelMetas declarationLevels)
              0
              (globalCoreType ec gd)
          substituteLevel
            | dutParameterCount telescope > 0 =
                -- Late instance bodies can extend/finalize the dictionary
                -- schema after the pre-pass recorded 'ieHead' and
                -- 'ieTraitUniverses'. Those artifacts may therefore still
                -- mention the provisional source metas even though the
                -- dictionary type already uses stable 'LParam's. First apply
                -- the declaration's solved source-to-telescope map, then
                -- specialize that telescope at this occurrence. Reversing
                -- the order leaves a foreign declaration parameter in the
                -- caller's Core.
                substituteLevelParams universes
                  . substituteLevelMetas declarationLevels
            | otherwise =
                substituteLevelMetas
                  (Map.fromList (zip (nub (levelMetasOfTerm rawDictionaryType)) universes))
      pure
        ( rawDictHead
        , Just rawDictType
        , substituteLevel
        , zonkTermWith (\_ _ -> Nothing) substituteLevel 0
        )
    Nothing -> do
      universes <- instantiateUniverseTelescope (ieDict ie) (ieUniverses ie)
      pure
        ( CGlobI (ieDict ie) universes
        , Nothing
        , substituteLevelParams universes
        , zonkTermWith (\_ _ -> Nothing) (substituteLevelParams universes) 0
        )

-- | §14.3/§33.2.1 program-level coherence: when two instances of one
-- trait have unifiable heads, the overlap is harmless only if the
-- instantiated dictionary artifacts are definitionally equivalent
-- (structural coherence mode); otherwise the program is rejected at
-- the later declaration, whether or not any use site resolves
-- through the overlapping pair.
instanceOverlapIsIncoherent :: InstanceEntry -> InstanceEntry -> CheckM Bool
instanceOverlapIsIncoherent new prior
  | length (ieHead new) /= length (ieHead prior) = pure False
  | otherwise = do
      saved <- get
      (_, _, specializeLevel, specializeTerm) <- instantiateInstanceOccurrence emptyCtx new
      metas <- forM [1 .. ieTeleLen new] (const freshMeta)
      metaVs <- mapM (evalIn emptyCtx) metas
      ec <- ec_
      let goalUniverses = map specializeLevel (ieTraitUniverses new)
          goalArgs = [eval ec (reverse metaVs) (specializeTerm t) | t <- ieHead new]
      -- §33.2.1 step 1: the comparison set holds only candidates that
      -- survive §14.3.1 resolution — an instance whose premises are
      -- unsolvable at the shared instantiation is discarded before
      -- coherence is judged
      mOld <- tryInstance 0 emptyCtx goalUniverses goalArgs prior
      mNew <- tryInstance 0 emptyCtx goalUniverses goalArgs new
      equivalent <- case (mNew, mOld) of
        (Just tmN, Just tmO) -> do
          vN <- evalIn emptyCtx tmN
          vO <- evalIn emptyCtx tmO
          ecu <- ec_
          pure (convertible ecu 0 vN vO)
        _ -> pure True -- disjoint heads or a discarded candidate
      put saved
      pure (not equivalent)

-- Boolean-proposition normalization (§16.3.3 step 3): goals of shape
-- (lhs = rhs) decided by conversion yield refl.  Before falling back to full
-- conversion, recognize equality-to-Bool-literal goals and discharge them with
-- the same bounded arithmetic relation solver used by termination checking,
-- seeded from the active boolean branch facts.  This is the proof source for
-- checked arithmetic guarded by ordinary control flow, e.g. after
-- `if x < y then ... else x - y`, the else branch carries `y <= x`.
propProof :: Ctx -> Value -> CheckM (Maybe Term)
propProof ctx = propProofWithTerm ctx Nothing

-- | Proposition proof entry used when the caller still owns the checked Core
-- goal. Keeping that term is semantically significant: evaluating an
-- authenticated dictionary projection may expose a record value, and
-- reconstructing Core from that value would lose the selected dictionary
-- identity required by provider-driven arithmetic proof search.
propProofTerm :: Ctx -> Term -> Value -> CheckM (Maybe Term)
propProofTerm ctx goalTerm = propProofWithTerm ctx (Just goalTerm)

propProofWithTerm :: Ctx -> Maybe Term -> Value -> CheckM (Maybe Term)
propProofWithTerm ctx sourceGoal goal = do
  g <- forceM goal
  evaluation <- ec_
  case canonicalEqualityPayload evaluation g of
    Just (carrier, left, right) ->
      principalizeOrProve g carrier left right
    _ -> pure Nothing
  where
    principalizeOrProve equalityGoal carrier lhs rhs = do
      saved <- get
      principalized <-
        solvePrincipalNaturalEquality ctx sourceGoal equalityGoal carrier
      if not principalized
        then proveEquality equalityGoal carrier lhs rhs
        else
          propProofWithTerm ctx sourceGoal goal >>= \case
            Just proof -> pure (Just proof)
            Nothing -> put saved >> pure Nothing

    proveEquality equalityGoal carrier lhs rhs = do
      definitional <-
        cachedPropDecision ctx sourceGoal equalityGoal $ do
          ec <- ec_
          pure (convertible ec (ctxLen ctx) (force ec lhs) (force ec rhs))
      case definitional of
        Just proof -> pure (Just proof)
        Nothing -> do
          contextualEquality <-
            equalityFromCheckedBranchFacts ctx sourceGoal lhs rhs
          if contextualEquality
            then Just <$> generatedReflForGoalAtM ctx sourceGoal equalityGoal
            else
              booleanEqualityFromBranchFacts ctx sourceGoal equalityGoal >>= \case
                True -> Just <$> generatedReflForGoalAtM ctx sourceGoal equalityGoal
                False ->
                  equalityReflectionFromCheckedBranchFacts
                    ctx
                    equalityGoal
                    carrier >>= \case
                    Just proof -> pure (Just proof)
                    Nothing ->
                      equalityCompletenessFromCheckedEvidence
                        ctx
                        sourceGoal
                        equalityGoal >>= \case
                        Just proof -> pure (Just proof)
                        Nothing ->
                          generatedNoConfusionProof ctx equalityGoal lhs rhs >>= \case
                            Just proof -> pure (Just proof)
                            Nothing ->
                              coherentProviderOperationBridgeProof
                                ctx
                                sourceGoal
                                equalityGoal
                                carrier >>= \case
                                Just proof -> pure (Just proof)
                                Nothing ->
                                  providerLawProof ctx sourceGoal Nothing equalityGoal carrier lhs rhs >>= \case
                                    Just proof -> pure (Just proof)
                                    Nothing -> do
                                      providerNormalFormBridgeProof
                                        ctx
                                        sourceGoal
                                        equalityGoal
                                        carrier
                                        lhs
                                        rhs >>= \case
                                          Just proof -> pure (Just proof)
                                          Nothing -> do
                                            typeLevelEquality <- typeLevelValueEqualityProof ctx carrier lhs rhs
                                            typeLevelRelationEquality <- typeLevelLiteralRelationProof ctx lhs rhs
                                            if typeLevelEquality == Just True || typeLevelRelationEquality == Just True
                                              then Just <$> typeLevelPropositionCertificate ctx equalityGoal
                                              else arithmeticEqualityCertificate ctx sourceGoal equalityGoal carrier lhs rhs

-- | Normalize an arithmetic goal through the deterministic representative of
-- one coherent local trait-evidence value, prove the normalized goal through
-- the ordinary arithmetic certificate path, then transport that proof back
-- through the compiler-issued @IsSubsingleton@ equality. This is the explicit
-- §15.8.2 bridge: evidence coherence never becomes conversion, and a local
-- dictionary can affect arithmetic normalization only through a checked
-- equality to the representative selected by ordinary instance resolution.
coherentProviderOperationBridgeProof
  :: Ctx
  -> Maybe Term
  -> Value
  -> Value
  -> CheckM (Maybe Term)
coherentProviderOperationBridgeProof ctx sourceGoal equalityGoal carrier =
  transactional $ do
    goalTerm <-
      case sourceGoal of
        Just source -> zonkTermM (ctxLen ctx) source
        Nothing -> quoteIn ctx equalityGoal >>= zonkTermM (ctxLen ctx)
    evidenceCandidates <-
      coherentTraitEvidenceTerms ctx [goalTerm]
    firstCandidate
      goalTerm
      ( nubBy
          (\(left, _) (right, _) -> left == right)
          evidenceCandidates
      )
  where
    firstCandidate _ [] = pure Nothing
    firstCandidate goalTerm ((local, evidenceType) : rest) = do
      candidateState <- get
      withDefinitionalEqualityOnly
        (instanceSearch ctx noSpan evidenceType) >>= \case
          Nothing ->
            put candidateState >> firstCandidate goalTerm rest
          Just selected0 -> do
            selected <- zonkTermM (ctxLen ctx) selected0
            let canonicalGoal =
                  replaceTermRoot local selected goalTerm
            if canonicalGoal == goalTerm
              then
                put candidateState >> firstCandidate goalTerm rest
              else do
                canonicalGoalValue <- evalIn ctx canonicalGoal
                case equalityExplicitEndpoints canonicalGoal of
                  Nothing ->
                    put candidateState >> firstCandidate goalTerm rest
                  Just (canonicalLhsTerm, canonicalRhsTerm) -> do
                    canonicalLhs <- evalIn ctx canonicalLhsTerm
                    canonicalRhs <- evalIn ctx canonicalRhsTerm
                    arithmeticProof <-
                      arithmeticEqualityCertificate
                        ctx
                        (Just canonicalGoal)
                        canonicalGoalValue
                        carrier
                        canonicalLhs
                        canonicalRhs
                    canonicalProof <-
                      case arithmeticProof of
                        Just proof -> pure (Just proof)
                        Nothing -> do
                          definitionallyEqual <-
                            withDefinitionalEqualityOnly
                              (unifyDefinitional ctx canonicalLhs canonicalRhs)
                          if definitionallyEqual
                            then Just <$> generatedReflAtM ctx canonicalGoalValue
                            else pure Nothing
                    case canonicalProof of
                      Nothing ->
                        put candidateState >> firstCandidate goalTerm rest
                      Just canonicalProof ->
                        withDefinitionalEqualityOnly
                          (unifyDefinitional ctx canonicalGoalValue equalityGoal) >>= \case
                            True -> pure (Just canonicalProof)
                            False ->
                              coherentEvidenceEquality
                                ctx
                                noSpan
                                evidenceType
                                selected
                                local >>= \case
                                  Nothing ->
                                    put candidateState
                                      >> firstCandidate goalTerm rest
                                  Just bridge -> do
                                    transported <-
                                      buildTransportAlongEqualityFromType
                                        ctx
                                        noSpan
                                        "coherent provider evidence"
                                        canonicalGoal
                                        canonicalProof
                                        canonicalGoalValue
                                        equalityGoal
                                        evidenceType
                                        selected
                                        local
                                        bridge
                                    pure (Just transported)

    transactional action = do
      saved <- get
      diagnostics <- gets (length . csDiags)
      result <- action
      diagnostics' <- gets (length . csDiags)
      case result of
        Just proof | diagnostics == diagnostics' -> pure (Just proof)
        _ -> put saved >> pure Nothing

-- | Exact arithmetic-operation dictionary occurrences in one checked Core
-- proposition. The global operation identity and its checked implicit
-- telescope authenticate the trait/carrier/evidence slots; no source spelling
-- or projected field name is used as authority here.
coherentArithmeticEvidenceOccurrences
  :: Ctx
  -> Term
  -> CheckM [(Term, Value)]
coherentArithmeticEvidenceOccurrences ctx root =
  fmap catMaybes . forM candidates $ \(trait, carrierTerm, dictionary) -> do
    let depth = ctxLen ctx
    if not (termScopedAt depth carrierTerm && termScopedAt depth dictionary)
      then pure Nothing
      else
        coreTermClassifierInCtx ctx dictionary >>= \case
          Nothing -> pure Nothing
          Just evidenceType -> do
            authenticated <- isTraitGoal evidenceType
            exactTrait <-
              forceM evidenceType >>= \case
                VGlobN evidenceTrait _ -> pure (evidenceTrait == trait)
                _ -> pure False
            pure
              ( if authenticated && exactTrait
                  then Just (dictionary, evidenceType)
                  else Nothing
              )
  where
    candidates =
      nubBy
        (\(leftTrait, leftCarrier, leftDictionary)
           (rightTrait, rightCarrier, rightDictionary) ->
            leftTrait == rightTrait
              && leftCarrier == rightCarrier
              && leftDictionary == rightDictionary)
        ( foldTerm
            (maybeToList . standardArithmeticDirectProvider)
            (const [])
            root
        )

-- | Decide an ordinary equality after reducing both endpoints under the exact
-- checked facts of the current branch. This is proof synthesis, not a new
-- definitional-equality rule: the caller emits an explicit equality
-- introduction only after this local judgment succeeds.
equalityFromCheckedBranchFacts
  :: Ctx
  -> Maybe Term
  -> Value
  -> Value
  -> CheckM Bool
equalityFromCheckedBranchFacts ctx sourceGoal lhs rhs = do
  facts <- gets csBoolFacts
  if null facts
    then pure False
    else do
      let depth = ctxLen ctx
      sourceEndpoints <-
        case sourceGoal of
          Nothing -> pure Nothing
          Just goalTerm ->
            equalityExplicitEndpoints <$> zonkTermM depth goalTerm
      (lhsTerm, rhsTerm) <-
        case sourceEndpoints of
          Just endpoints -> pure endpoints
          Nothing ->
            (,) <$> (quoteIn ctx lhs >>= zonkTermM depth)
                <*> (quoteIn ctx rhs >>= zonkTermM depth)
      normalized <-
        canonicalizeTermsUnderExactCheckedBranchFacts
          ctx
          [lhsTerm, rhsTerm]
      case normalized of
        [lhsNormalized, rhsNormalized] -> do
          evaluation <- ec_
          lhsValue <- evalIn ctx lhsNormalized
          rhsValue <- evalIn ctx rhsNormalized
          let solved =
                convertible
                  evaluation
                  depth
                  (force evaluation lhsValue)
                  (force evaluation rhsValue)
          pure solved
        _ -> pure False

-- | Decode one checked application of the standard @Eq.==@ member. Source
-- spelling only narrows candidates: callers must authenticate each returned
-- dictionary against @Eq carrier@ with 'knownTraitMemberProjection' before
-- using a law. The direct accessor ABI carries the carrier explicitly;
-- projected forms retain no independently recoverable carrier here and are
-- therefore returned only to callers that already know it.
selectedEqOperation
  :: Term
  -> Maybe (Term, Term, [(Maybe Term, Term)])
selectedEqOperation condition = do
  let (headTerm, arguments) =
        spineOfTerm (stripIdentityWrappers condition)
      explicitArguments =
        [ argument
        | (Expl, argument) <- arguments
        ]
  (leftTerm, rightTerm) <- last2 explicitArguments
  dictionaries <-
    case stripIdentityWrappers headTerm of
      CProjM _ dictionary member
        | member == "==" ->
            Just [(Nothing, dictionary)]
      CProjAtM _ dictionary member _
        | member == "==" ->
            Just [(Nothing, dictionary)]
      globalHead
        | termHeadGlob globalHead
            `elem`
              [ Just (gPrel "==")
              , Just (memberGlobal (gPrel "Eq") "==")
              ]
        , sourceCarrier : dictionary : _ <-
            [argument | (Impl, argument) <- arguments] ->
            Just [(Just sourceCarrier, dictionary)]
      _ -> Nothing
  guard (not (null dictionaries))
  pure (leftTerm, rightTerm, dictionaries)

-- | Prove @eq x y = True@ from an ordinary equality proof using the exact
-- selected @Eq@ dictionary's checked @eqComplete@ member. This is a provider
-- application, not a conversion rule. In particular, the equality premise is
-- solved through the generic proposition prover, so a user-defined
-- one-constructor equality family can refine the endpoints through the same
-- no-confusion path as the standard equality family.
equalityCompletenessFromCheckedEvidence
  :: Ctx
  -> Maybe Term
  -> Value
  -> CheckM (Maybe Term)
equalityCompletenessFromCheckedEvidence ctx sourceGoal targetGoal = do
  checkedGoal <-
    case sourceGoal of
      Just source -> zonkTermM (ctxLen ctx) source
      Nothing -> quoteIn ctx targetGoal >>= zonkTermM (ctxLen ctx)
  case booleanLiteralEqualityPayload checkedGoal of
    Just (True, condition) ->
      case selectedEqOperation condition of
        Just (leftTerm, rightTerm, dictionaries) ->
          firstDictionary leftTerm rightTerm dictionaries
        Nothing -> pure Nothing
    _ -> pure Nothing
  where
    firstDictionary _ _ [] = pure Nothing
    firstDictionary leftTerm rightTerm ((Nothing, _) : rest) =
      firstDictionary leftTerm rightTerm rest
    firstDictionary leftTerm rightTerm ((Just carrierTerm, dictionary) : rest) = do
      saved <- get
      diagnosticCount <- gets (length . csDiags)
      tryDictionary leftTerm rightTerm carrierTerm dictionary >>= \case
        Just proof -> do
          diagnosticCount' <- gets (length . csDiags)
          if diagnosticCount' == diagnosticCount
            then pure (Just proof)
            else put saved >> firstDictionary leftTerm rightTerm rest
        Nothing -> put saved >> firstDictionary leftTerm rightTerm rest

    tryDictionary leftTerm rightTerm carrierTerm dictionary = do
      if not (termScopedAt (ctxLen ctx) carrierTerm)
        then pure Nothing
        else do
          carrier <- evalIn ctx carrierTerm
          left <- evalIn ctx leftTerm
          right <- evalIn ctx rightTerm
          unaryTraitGoalForCarrier ctx (gPrel "Eq") carrier >>= \case
            Nothing -> pure Nothing
            Just eqGoal -> do
              (eqComplete, eqCompleteType) <-
                knownTraitMemberProjection
                  ctx
                  noSpan
                  (gPrel "Eq")
                  "eqComplete"
                  eqGoal
                  dictionary
              equality <-
                globalValueM
                  prelEqType
                  [(Impl, carrier), (Expl, left), (Expl, right)]
              propProof ctx equality >>= \case
                Nothing -> pure Nothing
                Just equalityProof -> do
                  (proof, proofType) <-
                    applyGeneratedCoreSpine
                      ctx
                      noSpan
                      eqComplete
                      eqCompleteType
                      [ (Expl, leftTerm, carrier)
                      , (Expl, rightTerm, carrier)
                      , (Expl, equalityProof, equality)
                      ]
                  exact <- unifyDefinitional ctx proofType targetGoal
                  pure (if exact then Just proof else Nothing)

-- | §16.3.3 equality reflection. A true checked branch condition headed by
-- the selected prelude 'Eq.==' operation supplies ordinary equality evidence
-- only through that same dictionary's checked 'eqSound' member. The operation
-- spine supplies both operands and the selected dictionary; the dictionary is
-- then checked against the complete @Eq carrier@ telescope before its law is
-- used. A field spelling alone is never semantic authority.
--
-- Candidate search is deliberately transactional. Generated universe
-- specialization, coercion, or member application may allocate metas while
-- rejecting an unrelated implicit argument. No such state or diagnostics may
-- escape a failed candidate.
equalityReflectionFromCheckedBranchFacts
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe Term)
equalityReflectionFromCheckedBranchFacts ctx equalityGoal carrier = do
  let depth = ctxLen ctx
  capturedFacts <- gets csBoolFacts
  facts <- normalizeBoolFacts depth capturedFacts
  firstCondition capturedFacts
    [ condition
    | (condition, True) <- facts
    ]
  where
    firstCondition _ [] = pure Nothing
    firstCondition capturedFacts (condition : rest) =
      pure (selectedEqOperation condition) >>= \case
        Nothing -> firstCondition capturedFacts rest
        Just (leftTerm, rightTerm, dictionaries) ->
          firstDictionary capturedFacts condition leftTerm rightTerm dictionaries >>= \case
            Just proof -> pure (Just proof)
            Nothing -> firstCondition capturedFacts rest

    firstDictionary _ _ _ _ [] = pure Nothing
    firstDictionary capturedFacts condition leftTerm rightTerm ((sourceCarrier, dictionary) : rest) = do
      saved <- get
      diagnosticCount <- gets (length . csDiags)
      reflectWith capturedFacts condition leftTerm rightTerm sourceCarrier dictionary >>= \case
        Just proof -> do
          diagnosticCount' <- gets (length . csDiags)
          if diagnosticCount' == diagnosticCount
            then pure (Just proof)
            else put saved >> firstDictionary capturedFacts condition leftTerm rightTerm rest
        Nothing -> put saved >> firstDictionary capturedFacts condition leftTerm rightTerm rest

    reflectWith capturedFacts condition leftTerm rightTerm sourceCarrier dictionary =
      unaryTraitGoalForCarrier ctx (gPrel "Eq") carrier >>= \case
        Nothing -> pure Nothing
        Just eqGoal -> do
          carrierMatches <- case sourceCarrier of
            Nothing -> pure True
            Just sourceCarrierTerm -> do
              sourceCarrierValue <- evalIn ctx sourceCarrierTerm
              unifyDefinitional ctx sourceCarrierValue carrier
          conditionEstablished <-
            if carrierMatches
              then
                withCapturedBoolFacts capturedFacts
                  (proveBoolTermFromBranchFacts ctx True condition)
              else pure False
          if not conditionEstablished
            then pure Nothing
            else do
              booleanEqualityTerm <-
                booleanFactProposition ctx condition
              booleanEquality <- evalIn ctx booleanEqualityTerm
              branchProof <- generatedReflAtM ctx booleanEquality
              (eqSound, eqSoundType) <-
                knownTraitMemberProjection
                  ctx
                  noSpan
                  (gPrel "Eq")
                  "eqSound"
                  eqGoal
                  dictionary
              (proof, proofType) <-
                applyGeneratedCoreSpine
                  ctx
                  noSpan
                  eqSound
                  eqSoundType
                  [ (Expl, leftTerm, carrier)
                  , (Expl, rightTerm, carrier)
                  , (Expl, branchProof, booleanEquality)
                  ]
              exact <- unifyDefinitional ctx proofType equalityGoal
              contextual <-
                if exact
                  then pure False
                  else
                    withCapturedBoolFacts capturedFacts $
                      tryCanonicalStandardArithmeticCompatibility
                        ctx
                        noSpan
                        proofType
                        equalityGoal
              pure (if exact || contextual then Just proof else Nothing)

-- | §10.2.1 / §16.3.3 checked no-confusion proof search. Given an in-scope
-- local proof whose type is an ordinary one-constructor data family,
-- eliminate that proof through the exact checked constructor identity. The
-- constructor-result alignment installs only its dependency-ordered rigid
-- refinements; a candidate succeeds precisely when those ordinary conversion
-- facts make the requested standard-equality endpoints definitionally equal.
--
-- This is deliberately not tied to the standard equality family or its
-- constructor spelling. A user-defined @Equal a b@ with @Refl : Equal a a@
-- follows the identical path. Conversely, an arbitrary one-constructor
-- relation grants no authority: if its constructor result does not force the
-- requested endpoint equality, conversion fails and the complete speculative
-- checker state is restored.
generatedNoConfusionProof
  :: Ctx
  -> Value
  -> Value
  -> Value
  -> CheckM (Maybe Term)
generatedNoConfusionProof ctx equalityGoal lhs rhs =
  firstCandidate visibleProofs
  where
    visibleProofs =
      [ (index, entry)
      | (index, entry) <- zip [0 :: Int ..] (ctxEntries ctx)
      ]

    firstCandidate [] = pure Nothing
    firstCandidate (candidate : rest) = do
      saved <- get
      tryCandidate candidate >>= \case
        Just proof -> pure (Just proof)
        Nothing -> put saved >> firstCandidate rest

    tryCandidate (index, entry) = do
      premiseType <- forceM (ceType entry)
      family <- case premiseType of
        VGlobN identity _ -> pure (Just identity)
        VCtor identity _ -> pure (Just identity)
        _ -> pure Nothing
      state <- get
      case family >>= (`Map.lookup` csDatas state) of
        Just DataInfo {diCtors = [constructor]}
          | constructorInScope state constructor
          , Just constructorInfo <- Map.lookup constructor (csCtors state)
          , null (ciSourceFields constructorInfo) -> do
              surroundingFacts <- gets csFacts
              (fieldSlots, branchCtx, existentialModes, bridges, universes) <-
                ctorFieldTypesCtx
                  ctx
                  constructor
                  constructorInfo
                  premiseType
                  noSpan
              if not (null fieldSlots)
                then pure Nothing
                else do
                  evaluation <- ec_
                  if
                    convertible
                      evaluation
                      (ctxLen branchCtx)
                      (force evaluation lhs)
                      (force evaluation rhs)
                    then do
                      body <- generatedReflAtM branchCtx equalityGoal
                      premiseTypeTerm <- quoteIn ctx premiseType
                      equalityGoalTerm <- quoteIn ctx equalityGoal
                      modify' $ \current ->
                        current {csFacts = surroundingFacts}
                      pure
                        ( Just
                            ( CMatch
                                (CVar index)
                                (Just premiseTypeTerm)
                                (Just equalityGoalTerm)
                                [ CaseAlt
                                    (CPCtorM existentialModes bridges [] constructor universes [])
                                    Nothing
                                    body
                                ]
                            )
                        )
                    else pure Nothing
        _ -> pure Nothing

-- | Reify the exact equality supplied by one checked Boolean branch. This is
-- deliberately narrower than arithmetic consequence search: one endpoint must
-- be the resolved prelude 'True' or 'False' constructor, the carrier must be
-- resolved prelude 'Bool', and the other endpoint must be established with the
-- same polarity by the scoped branch-fact table. KCoreText independently
-- replays this judgment from the surrounding 'KTIf' before accepting the
-- generated ordinary 'refl'.
booleanEqualityFromBranchFacts
  :: Ctx
  -> Maybe Term
  -> Value
  -> CheckM Bool
booleanEqualityFromBranchFacts ctx sourceGoal equalityGoal = do
  -- The branch condition may have been recorded before its selected trait
  -- dictionaries were settled, while checking the equality goal can settle
  -- the corresponding occurrence independently. Demand only the pending
  -- evidence reachable from this goal or its active facts before comparing
  -- their Core shapes; unrelated pending obligations remain deferred.
  settleRequiredProofDependencies ctx equalityGoal
  let depth = ctxLen ctx
  rawGoal <- case sourceGoal of
    Just term -> pure term
    Nothing ->
      case neutralValueTerm depth equalityGoal of
        Just term -> pure term
        Nothing -> quoteIn ctx equalityGoal
  checkedGoal <- zonkTermM depth rawGoal
  case booleanLiteralEqualityPayload checkedGoal of
    Just (truth, condition) -> do
      facts <- exactBoolFacts depth =<< gets csBoolFacts
      branchFactTruthAt depth facts condition >>= \case
        Just established -> pure (established == truth)
        Nothing -> pure False
    Nothing -> pure False

-- | Apply §15.8.6's assignment rule to one checked Nat equality. The source
-- operations and assumptions pass through the same authenticated reifiers as
-- arithmetic certificates; only classifier-authenticated Nat metas are
-- assignable. The pure kernel requires a unique affine solution, so nonlinear,
-- underconstrained, partial, or non-natural equations leave every meta
-- untouched.
solvePrincipalNaturalEquality
  :: Ctx
  -> Maybe Term
  -> Value
  -> Value
  -> CheckM Bool
solvePrincipalNaturalEquality ctx sourceGoal equalityGoal carrier = do
  carrier' <- forceM carrier
  case carrier' of
    VGlobN natural [] | natural == prelNat -> solve
    _ -> pure False
  where
    solve = do
      let depth = ctxLen ctx
      rawGoal <- case sourceGoal of
        Just term -> zonkTermM depth term
        Nothing -> quoteIn ctx equalityGoal >>= zonkTermM depth
      normalizedGoal <- normalizeArithmeticCertificateTerm depth rawGoal
      arithmeticFactForDomain depth ArithmeticNatural normalizedGoal >>= \case
        Nothing -> pure False
        Just goalFact ->
          solvePrincipalNaturalFact ctx [normalizedGoal] goalFact

-- | Solve one classifier-authenticated Nat meta from an affine fact. The pure
-- kernel may return a term over rigid Nat variables, not merely a literal;
-- reification back to Core is deliberately restricted to total Nat addition
-- and multiplication by nonnegative literals. The caller must still rerun
-- ordinary conversion after installing the candidate.
solvePrincipalNaturalFact
  :: Ctx
  -> [Term]
  -> AFact
  -> CheckM Bool
solvePrincipalNaturalFact ctx sourceTerms goalFact = do
  let depth = ctxLen ctx
  state <- get
  assignable <-
    fmap catMaybes . forM (nub (concatMap (unsolvedMetasOf state) sourceTerms)) $ \meta ->
      case Map.lookup meta (csMetaClassifiers state) of
        Nothing -> pure Nothing
        Just classifier -> do
          classifierType <-
            zonkTermM (micDepth classifier) (micType classifier)
          pure
            ( if isNatType classifierType
                then Just (arithmeticMetaVariable meta, meta)
                else Nothing
            )
  if null assignable
    then pure False
    else do
      variables <- ctxArithmeticVariables ctx
      let naturalVariables =
            Set.fromList
              ( [ level
                | (level, kind) <- variables
                , kind == ArithmeticVariableNatural
                ]
                  ++ map fst assignable
              )
          assignableVariables = Set.fromList (map fst assignable)
          metasByVariable = Map.fromList assignable
      assumptions <-
        arithmeticCertificateAssumptions ctx ArithmeticNatural
      assumptionFacts <-
        arithmeticAssumptionFactsForDomain
          depth
          ArithmeticNatural
          assumptions
      rigidFacts <-
        arithmeticRigidFactsForDomain
          ctx
          ArithmeticNatural
          variables
      let derived =
            derivePrincipalAffineSubstitution
              ArithmeticNaturalSemantics
              naturalVariables
              assignableVariables
              (assumptionFacts ++ rigidFacts)
              goalFact
      case derived of
          Nothing -> pure False
          Just (variable, expression) ->
            case
              ( Map.lookup variable metasByVariable
              , naturalCoreOfArithmeticExpression depth expression
              )
              of
                (Just meta, Just candidate) -> do
                  candidateValue <- evalIn ctx candidate
                  solveMetaAcyclic meta candidateValue
                _ -> pure False

-- | Reconstruct the total affine Nat fragment admitted by
-- 'derivePrincipalAffineSubstitution'. Variable identities are de Bruijn
-- levels, so this inverse is exact at the current context depth.
naturalCoreOfArithmeticExpression :: Int -> AExpr -> Maybe Term
naturalCoreOfArithmeticExpression depth = \case
  AConst value
    | value >= 0 -> Just (CLit (LitInt value))
  AVar level
    | level >= 0
    , level < depth ->
        Just (CVar (depth - 1 - level))
  AScale coefficient expression
    | coefficient >= 0 -> do
        expression' <- naturalCoreOfArithmeticExpression depth expression
        pure
          ( case coefficient of
              0 -> CLit (LitInt 0)
              1 -> expression'
              _ ->
                CApp Expl
                  (CApp Expl (CGlob prelNatMultiply) (CLit (LitInt coefficient)))
                  expression'
          )
  AAdd lhs rhs ->
    CApp Expl . CApp Expl (CGlob prelNatAdd)
      <$> naturalCoreOfArithmeticExpression depth lhs
      <*> naturalCoreOfArithmeticExpression depth rhs
  _ -> Nothing

-- | Reify branch-local dependent-match equalities into the same arithmetic
-- fact language used by checked certificates.  A rigid fact is admitted only
-- when the lexical binder has the selected arithmetic classifier and the
-- replacement itself is recognized through the exact operation identities for
-- that domain.  Negative constructor facts and unrelated refinements remain
-- conversion-only information.
arithmeticRigidFactsForDomain
  :: Ctx
  -> ArithmeticDomain
  -> [(Int, ArithmeticVariableKind)]
  -> CheckM [AFact]
arithmeticRigidFactsForDomain ctx domain variables = do
  let depth = ctxLen ctx
  facts <- gets csFacts
  fmap catMaybes . forM variables $ \(level, kind) ->
    if arithmeticVariableBelongsToDomain domain kind
      then
        case Map.lookup level facts of
          Just (FactIs replacement) -> do
            replacementTerm <- quoteIn ctx replacement >>= zonkTermM depth
            normalized <-
              normalizeArithmeticCertificateTerm depth replacementTerm
            expression <-
              selectedArithmeticExpression domain depth normalized
            pure (AFact ACmpEq (AVar level) <$> expression)
          _ -> pure Nothing
      else pure Nothing

-- | Prepare one checked application whose result is an authenticated
-- application of the expected nominal family. Non-arithmetic parameters use
-- ordinary unification, as do fully determined or singly-flexible arithmetic
-- indices. An arithmetic argument with several current-plan placeholders uses
-- only the unique-principal affine solver: decomposing
-- @?m + ?n = n + k@ definitionally would choose one of several propositionally
-- valid assignments before the explicit operands constrain @?m@ and @?n@.
-- The completed application is still accepted only by 'coerceTerm', so this
-- phase grants neither conversion nor transport.
prepareNominalResultForCheckedApplication
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe AppResultPreparation)
prepareNominalResultForCheckedApplication ctx actual expected = do
  nominalArgumentPairs >>= \case
    Nothing -> do
      checkpoint <- get
      direct <- unify ctx actual expected
      unless direct (put checkpoint)
      pure
        ( if direct
            then Just AppResultDefinitionallyReady
            else Nothing
        )
    Just initialPairs -> do
      -- Result-planning placeholders belong to the produced application, not
      -- to its demanded type. Establish that ownership direction before
      -- symmetric unification: otherwise an older demanded meta can be solved
      -- to a younger result placeholder, which lets the latter escape its
      -- constructor/application scope when it is later skolemized.
      reconcileBarePlanningPairs initialPairs
      checkpoint <- get
      pairs <- fromMaybe initialPairs <$> nominalArgumentPairs
      underconstrained <-
        anyM underconstrainedArithmeticPair pairs
      direct <-
        if underconstrained
          then pure False
          else unify ctx actual expected
      if direct
        then pure (Just AppResultDefinitionallyReady)
        else do
          put checkpoint
          reconcileNonArithmeticPairs pairs
          principalize (1 + Map.size (csMetas checkpoint))
          prepared <- get
          stillUnderconstrained <-
            nominalArgumentPairs >>= \case
              Just currentPairs ->
                anyM underconstrainedArithmeticPair currentPairs
              Nothing -> pure False
          definitionallyReady <-
            if stillUnderconstrained
              then pure False
              else unify ctx actual expected
          unless definitionallyReady (put prepared)
          pure
            ( Just
                ( if definitionallyReady
                    then AppResultDefinitionallyReady
                    else AppResultNeedsCoercion
                )
            )
  where
    reconcileBarePlanningPairs = mapM_ reconcileBarePlanningPair

    -- The pair order is semantic: lhs is produced by the checked application,
    -- rhs is demanded by its context. A classifier-authenticated planning meta
    -- on the lhs is therefore solved toward rhs even when rhs is itself a
    -- flexible outer value. Only when lhs is not a planning placeholder may a
    -- rhs planning meta be solved in the opposite direction.
    reconcileBarePlanningPair (lhs, rhs) = do
      state <- get
      case (barePlanningMeta state lhs, barePlanningMeta state rhs) of
        (Just meta, _) -> solveTowards meta rhs
        (Nothing, Just meta) -> solveTowards meta lhs
        _ -> pure ()

    solveTowards meta target = do
      let depth = ctxLen ctx
      normalized <- normalizeArithmeticCertificateTerm depth target
      targetValue <- evalIn ctx normalized
      void (solveMetaAcyclic meta targetValue)

    barePlanningMeta state term =
      case stripIdentityWrappers term of
        CMeta meta
          | meta `Set.member` csApplicationPlanningMetas state
          , Just Nothing <- Map.lookup meta (csMetas state) ->
              Just meta
        _ -> Nothing

    principalize fuel
      | fuel <= 0 = pure ()
      | otherwise = do
          nominalArgumentPairs >>= \case
            Nothing -> pure ()
            Just pairs ->
              firstSolved pairs >>= \case
                False -> pure ()
                True -> principalize (fuel - 1)

    reconcileNonArithmeticPairs =
      mapM_ $ \(lhs, rhs) -> do
        natArithmeticPair lhs rhs >>= \case
          Just _ -> pure ()
          Nothing -> do
            state <- get
            let planning =
                  Set.intersection
                    (Set.fromList (unsolvedMetasOf state lhs ++ unsolvedMetasOf state rhs))
                    (csApplicationPlanningMetas state)
                directlyConstrained =
                  isBarePlanningPlaceholder planning lhs
                    || isBarePlanningPlaceholder planning rhs
                nominallyInjective =
                  sameDeclaredNominalHead state lhs rhs
            when
              ( Set.null planning
                  || directlyConstrained
                  || nominallyInjective
              ) $ do
                let depth = ctxLen ctx
                lhs' <- normalizeArithmeticCertificateTerm depth lhs
                rhs' <- normalizeArithmeticCertificateTerm depth rhs
                checkpoint <- get
                lhsValue <- evalIn ctx lhs'
                rhsValue <- evalIn ctx rhs'
                reconciled <- unify ctx lhsValue rhsValue
                unless reconciled (put checkpoint)

    isBarePlanningPlaceholder planning term =
      case stripIdentityWrappers term of
        CMeta meta -> meta `Set.member` planning
        _ -> False

    sameDeclaredNominalHead state lhs rhs =
      case
          ( declaredNominalApplication
              (csGlobals state)
              (csDatas state)
              lhs
          , declaredNominalApplication
              (csGlobals state)
              (csDatas state)
              rhs
          ) of
        (Just (lhsHead, _, _), Just (rhsHead, _, _)) ->
          lhsHead == rhsHead
        _ -> False

    underconstrainedArithmeticPair (lhs, rhs) =
      natArithmeticPair lhs rhs >>= \case
        Nothing -> pure False
        Just (lhs', _, rhs', _) -> do
          state <- get
          let unresolved =
                Set.fromList
                  (unsolvedMetasOf state lhs' ++ unsolvedMetasOf state rhs')
              planning =
                Set.intersection
                  unresolved
                  (csApplicationPlanningMetas state)
          pure (Set.size planning > 1)

    natArithmeticPair lhs rhs = do
      let depth = ctxLen ctx
      lhs' <- normalizeArithmeticCertificateTerm depth lhs
      rhs' <- normalizeArithmeticCertificateTerm depth rhs
      lhsExpression <- selectedNatArithmeticExpression depth lhs'
      rhsExpression <- selectedNatArithmeticExpression depth rhs'
      pure $ do
        lhsArithmetic <- lhsExpression
        rhsArithmetic <- rhsExpression
        pure (lhs', lhsArithmetic, rhs', rhsArithmetic)

    anyM _ [] = pure False
    anyM predicate (item : rest) =
      predicate item >>= \case
        True -> pure True
        False -> anyM predicate rest

    nominalArgumentPairs = do
      let depth = ctxLen ctx
      actualTerm <- quoteIn ctx actual >>= zonkTermM depth
      expectedTerm <- quoteIn ctx expected >>= zonkTermM depth
      state <- get
      pure $ do
        (actualFamily, _, actualArguments) <-
          declaredNominalApplication
            (csGlobals state)
            (csDatas state)
            actualTerm
        (expectedFamily, _, expectedArguments) <-
          declaredNominalApplication
            (csGlobals state)
            (csDatas state)
            expectedTerm
        guard (actualFamily == expectedFamily)
        guard (length actualArguments == length expectedArguments)
        guard
          ( and
              ( zipWith
                  (\(actualIcit, _) (expectedIcit, _) ->
                     actualIcit == expectedIcit)
                  actualArguments
                  expectedArguments
              )
          )
        pure
          ( zipWith
              (\(_, actualArgument) (_, expectedArgument) ->
                 (actualArgument, expectedArgument))
              actualArguments
              expectedArguments
          )

    firstSolved [] = pure False
    firstSolved ((lhs, rhs) : rest) =
      natArithmeticPair lhs rhs >>= \case
        Just (lhs', lhsArithmetic, rhs', rhsArithmetic) -> do
          solved <-
            solvePrincipalNaturalFact
              ctx
              [lhs', rhs']
              (AFact ACmpEq lhsArithmetic rhsArithmetic)
          if solved then pure True else firstSolved rest
        Nothing -> firstSolved rest

-- | Instantiate an exact law from one compiler-owned §15.8.2 provider.
-- Provider metadata names semantic trait/member identities.  The checked
-- member telescope remains the authority for the role schema: for a
-- commutativity provider we apply its law to the two operands and accept it
-- only when the resulting type is definitionally the exact equality goal.
-- Thus a malformed provider table, unrelated operation, or distinct evidence
-- closure cannot manufacture a proof.
providerLawProof
  :: Ctx
  -> Maybe Term
  -> Maybe Term
  -> Value
  -> Value
  -> Value
  -> Value
  -> CheckM (Maybe Term)
providerLawProof ctx sourceGoal sourceProof equalityGoal carrier _lhsValue _rhsValue =
  transactional $ do
    checkedProposition <-
      case sourceGoal of
        Just source -> zonkTermM (ctxLen ctx) source
        Nothing -> quoteIn ctx equalityGoal >>= zonkTermM (ctxLen ctx)
    replayGoal <- quoteIn ctx equalityGoal >>= zonkTermM (ctxLen ctx)
    directSourceCertificate replayGoal >>= \case
      Just certificate -> pure (Just certificate)
      Nothing -> do
        state <- get
        -- Synthesized provider search proves a closed equality already
        -- selected by the caller; it is not an assignment rule. In
        -- particular, commutativity must not turn @x + y = 4@ into one
        -- arbitrary split by instantiating source holes. An exact source law
        -- application is different: it was already checked by the ordinary
        -- application rule, so its existing metas may remain in the
        -- certificate until declaration finalization zonks them.
        if not (null (unsolvedMetasOf state checkedProposition))
          then pure Nothing
          else
            case fmap fst (equalityExplicitEndpoints checkedProposition) of
              Nothing -> pure Nothing
              Just sourceLhs ->
                firstProvider
                  checkedProposition
                  sourceLhs
                  standardProofNormalizationProviders
  where
    directSourceCertificate replayGoal =
      firstDirect standardProofNormalizationProviders
      where
        firstDirect [] = pure Nothing
        firstDirect (provider : rest) =
          case sourceProof of
            Just proof ->
              exactSourceLawProposition provider proof >>= \case
                Just sourceProposition
                  | Just (sourceLhs, _) <-
                      equalityExplicitEndpoints sourceProposition
                  , isJust (providerLawArguments provider sourceLhs) ->
                      exactSourceDictionary sourceProposition provider >>= \case
                        Just dictionary -> do
                          replayValid <-
                            providerReplayMatches
                              provider
                              dictionary
                              sourceProposition
                              replayGoal
                          if replayValid
                            then
                              Just
                                <$> makeProviderCertificate
                                  provider
                                  dictionary
                                  proof
                                  sourceProposition
                                  replayGoal
                            else firstDirect rest
                        Nothing -> firstDirect rest
                _ -> firstDirect rest
            Nothing -> firstDirect rest

    firstProvider _ _ [] = pure Nothing
    firstProvider checkedGoal sourceLhs (provider : rest) =
      case providerLawArguments provider sourceLhs of
        Nothing -> firstProvider checkedGoal sourceLhs rest
        Just arguments -> do
          candidateState <- get
          instantiateProvider checkedGoal arguments provider >>= \case
            Just proof -> pure (Just proof)
            Nothing -> do
              -- Provider candidates are alternatives, not a cumulative search
              -- context. A failed law application may allocate occurrence
              -- metas or constraints while checking its telescope; none of
              -- those facts may influence the next provider.
              put candidateState
              firstProvider checkedGoal sourceLhs rest

    instantiateProvider checkedGoal arguments provider
      | pnpLawIdentity provider
          /= memberGlobal (pnpLawOwner provider) (pnpLawField provider) =
          pure Nothing
      | otherwise = do
          callerState <- get
          unaryTraitGoalForCarrier
            ctx
            (pnpEvidenceTrait provider)
            carrier >>= \case
            Nothing -> pure Nothing
            Just providerGoal ->
              sourceDictionaryForProvider
                checkedGoal
                provider
                providerGoal >>= \case
                Nothing -> pure Nothing
                Just dictionary -> do
                  (law, lawType) <-
                    knownTraitMemberProjection
                      ctx
                      noSpan
                      (pnpLawOwner provider)
                      (pnpLawField provider)
                      providerGoal
                      dictionary
                  (proof, proofType) <-
                    applyGeneratedCoreSpine
                      ctx
                      noSpan
                      law
                      lawType
                      [ (Impl, argument, carrier)
                      | argument <- arguments
                      ]
                  providerEvidence <-
                    pendingEvidenceComponentTerms ctx [dictionary, proof]
                  flushPendingSelected providerEvidence
                  checkedProposition <-
                    quoteIn ctx proofType >>= zonkTermM (ctxLen ctx)
                  replayProposition <-
                    case sourceGoal of
                      Just source -> zonkTermM (ctxLen ctx) source
                      Nothing -> quoteIn ctx equalityGoal >>= zonkTermM (ctxLen ctx)
                  definitionallyValid <-
                    unifyDefinitional ctx proofType equalityGoal
                  providerReplayValid <-
                    providerReplayMatches
                      provider
                      dictionary
                      checkedProposition
                      replayProposition
                  -- The requested proposition was required to be closed before
                  -- provider search. Candidate selection is observational: its
                  -- complete state is restored below, while the independently
                  -- checked certificate must itself be meta-free. Comparing all
                  -- caller metas here would incorrectly couple this local query
                  -- to unrelated pending work elsewhere in the declaration.
                  if definitionallyValid
                    then
                      finishProviderArtifact
                        callerState
                        proof
                    else if providerReplayValid
                      then do
                        goal <-
                          case sourceGoal of
                            Just source -> zonkTermM (ctxLen ctx) source
                            Nothing -> quoteIn ctx equalityGoal >>= zonkTermM (ctxLen ctx)
                        finishProviderCertificate
                          callerState
                          provider
                          dictionary
                          proof
                          checkedProposition
                          goal
                      else pure Nothing

    finishProviderCertificate
      callerState
      provider
      dictionary
      proof
      checkedProposition
      goal = do
        certificateTerm <-
          makeProviderCertificate
            provider
            dictionary
            proof
            checkedProposition
            goal
        finishProviderArtifact callerState certificateTerm

    finishProviderArtifact callerState candidate =
      closeProviderLocalLevels callerState candidate >>= \case
        Nothing -> pure Nothing
        Just closedCandidate -> do
          checkedState <- get
          if
            providerArtifactEscapes
              callerState
              checkedState
              closedCandidate
            then pure Nothing
            else do
              -- Provider selection is an observational query. Its internal
              -- instance/universe freshening must not add constraints,
              -- caches, or assignments to the declaration currently being
              -- checked.
              put callerState
              pure (Just closedCandidate)

    makeProviderCertificate
      provider
      dictionary
      proof
      checkedProposition
      replayGoal = do
        dictionary' <- zonkTermM (ctxLen ctx) dictionary
        proof' <- zonkTermM (ctxLen ctx) proof
        let descriptor =
              ArithmeticNormalizationProvider
                { anpIdentity = pnpIdentity provider
                , anpTheory = pnpTheory provider
                , anpLawIdentity = pnpLawIdentity provider
                , anpNormalFormVersion = pnpNormalFormVersion provider
                , anpProviderVersion = pnpProviderVersion provider
                , anpCheckerVersion = pnpCheckerVersion provider
                }
        pure
          ( CArithmeticProof
              ArithmeticCertificate
                { acVersion = arithmeticCertificateVersion
                , acDomain = ArithmeticProviderLaw
                , acProviders =
                    [ ArithmeticProviderEvidence
                        (Just descriptor)
                        (pnpEvidenceTrait provider)
                        dictionary'
                    ]
                , acVariables = []
                , acAssumptions =
                    [ ArithmeticAssumption
                        True
                        checkedProposition
                        replayGoal
                        ( ArithmeticAssumptionProof
                            checkedProposition
                            proof'
                        )
                    ]
                , acGoal = checkedProposition
                , acReplayGoal = replayGoal
                }
          )

    -- Preserve the exact checked provider closure when the source proof is
    -- already an application of the authenticated law. Candidate discovery
    -- does not depend on a fixed implicit-argument offset: every implicit
    -- term is related to the selected operation through exact provider
    -- metadata. The preserved closure is the unique source implicit whose
    -- root occurs in that operation's checked dictionary argument. If the
    -- source is not that law (for example, @refl@), use ordinary coherent
    -- instance selection.
    sourceDictionaryForProvider checkedGoal provider providerGoal =
      exactSourceDictionary checkedGoal provider >>= \case
        Just dictionary -> pure (Just dictionary)
        Nothing -> traitEvidence ctx noSpan providerGoal

    exactSourceDictionary checkedGoal provider =
      case sourceProof of
        Just source
          | (headTerm, sourceArguments) <-
              spineOfTerm (stripIdentityWrappers source) ->
              case stripIdentityWrappers headTerm of
                CProjM _ dictionary member
                  | member == pnpLawField provider ->
                      checkedProviderDictionary provider dictionary
                CProjAtM _ dictionary member _
                  | member == pnpLawField provider ->
                      checkedProviderDictionary provider dictionary
                _
                  | termHeadGlob (stripIdentityWrappers headTerm)
                      == Just (pnpLawIdentity provider)
                  , Just operationDictionary <-
                      providerOperationDictionary checkedGoal provider ->
                      case
                        nub
                          [ candidate
                          | (Impl, candidate) <- sourceArguments
                          , termContainsRoot candidate operationDictionary
                          ]
                      of
                        [dictionary] ->
                          checkedProviderDictionary provider dictionary
                        _ -> pure Nothing
                _ -> pure Nothing
        _ -> pure Nothing

    -- Reconstruct the source proposition from the exact checked declaration
    -- telescope and supplied Core arguments. Quoting the evaluator result is
    -- insufficient here: transparent provider operations may reduce only on
    -- one neutral endpoint, producing a proposition that is convertible in
    -- the source checker but is not the syntactic type independently inferred
    -- for the recorded proof in KCoreText.
    exactSourceLawProposition provider source = do
      let (headTerm, arguments) =
            spineOfTerm (stripIdentityWrappers source)
      case stripIdentityWrappers headTerm of
        CGlobal law universes
          | law == pnpLawIdentity provider -> do
              definition <- gets (Map.lookup law . csGlobals)
              evaluator <- ec_
              case definition of
                Just globalDefinition -> do
                  let specializedType =
                        zonkTermWith
                          (\_ _ -> Nothing)
                          (substituteLevelParams universes)
                          0
                          (globalCoreType evaluator globalDefinition)
                  pure
                    ( applyCoreTypeArguments
                        (ctxLen ctx)
                        specializedType
                        arguments
                    )
                Nothing -> pure Nothing
        _ -> pure Nothing

    applyCoreTypeArguments _ result [] = Just result
    applyCoreTypeArguments depth typeTerm ((actualIcit, argument) : rest) =
      case typeTerm of
        CPiEvidenceM
          _
          _
          expectedIcit
          _
          _
          _
          _
          _
          _
          codomain
            | actualIcit == expectedIcit ->
                applyCoreTypeArguments
                  depth
                  (substTopTermAt depth argument codomain)
                  rest
        _ -> Nothing

    checkedProviderDictionary provider dictionary =
      unaryTraitGoalForCarrier
        ctx
        (pnpEvidenceTrait provider)
        carrier >>= \case
        Nothing -> pure Nothing
        Just providerGoal ->
          case stripIdentityWrappers dictionary of
            CVar index
              | Just entry <- listToMaybe (drop index (ctxEntries ctx)) -> do
                  valid <-
                    unifyDefinitional
                      ctx
                      (ceType entry)
                      providerGoal
                  pure (if valid then Just dictionary else Nothing)
            _ -> pure Nothing

    providerOperationDictionary checkedGoal provider = do
      (lhs, _) <- equalityExplicitEndpoints checkedGoal
      let (operationHead, operationArguments) =
            spineOfTerm (stripIdentityWrappers lhs)
      operation <- termHeadGlob (stripIdentityWrappers operationHead)
      guard (operation `elem` pnpOperationIdentities provider)
      case [argument | (Impl, argument) <- operationArguments] of
        _carrier : dictionary : _ -> Just dictionary
        _ -> Nothing

    -- Provider normalization is deliberately outside definitional equality.
    -- The checker may nevertheless certify the exact selected law when its
    -- checked proposition and the requested replay goal canonicalize to the
    -- same authenticated arithmetic term. KCoreText independently repeats
    -- this check from the recorded provider, law, evidence, and proof.
    providerReplayMatches provider dictionary checked replayed = do
      carrier' <- forceM carrier
      case carrier' of
        VGlobN natural [] | natural == prelNat -> do
          checkedFact <- providerArithmeticFact checked
          replayedFact <- providerArithmeticFact replayed
          pure (isJust checkedFact && checkedFact == replayedFact)
        _ -> pure False
      where
        -- Reify both the exact checked law and its replay through the selected
        -- provider closure. Primitive Nat operations use the ordinary
        -- arithmetic decoder; an overloaded operation is admitted only when
        -- its resolved semantic identity belongs to the provider and its
        -- dictionary is a projection rooted in the exact selected evidence.
        -- This is the source-checker counterpart of CoreText's independent
        -- provider-law replay check.
        providerArithmeticFact proposition =
          case equalityExplicitEndpoints proposition of
            Nothing -> pure Nothing
            Just (left, right) -> do
              leftExpression <- providerArithmeticExpression left
              rightExpression <- providerArithmeticExpression right
              pure (AFact ACmpEq <$> leftExpression <*> rightExpression)

        providerArithmeticExpression term =
          selectedArithmeticExpression
            ArithmeticNatural
            (ctxLen ctx)
            term >>= \case
              Just expression -> pure (Just expression)
              Nothing ->
                case spineOfTerm (stripIdentityWrappers term) of
                  (operationTerm, operationArguments)
                    | Just operation <-
                        termHeadGlob (stripIdentityWrappers operationTerm)
                    , operation `elem` pnpOperationIdentities provider
                    , Just operationDictionary <-
                        providerOperationEvidence
                          operationTerm
                          operationArguments
                    , termContainsRoot dictionary operationDictionary
                    , Just (left, right) <-
                        last2
                          [ argument
                          | (Expl, argument) <- operationArguments
                          ] -> do
                        leftExpression <-
                          providerArithmeticExpression left
                        rightExpression <-
                          providerArithmeticExpression right
                        pure (AAdd <$> leftExpression <*> rightExpression)
                  _ -> pure Nothing

        providerOperationEvidence operationTerm arguments =
          case stripIdentityWrappers operationTerm of
            CProjM _ selected _ -> Just selected
            CProjAtM _ selected _ _ -> Just selected
            _ ->
              case [argument | (Impl, argument) <- arguments] of
                _carrier : selected : _ -> Just selected
                _ -> Nothing

    providerArtifactEscapes callerState checkedState artifact =
      let terms = case artifact of
            CArithmeticProof certificate ->
              foldMapArithmeticCertificate (: []) certificate
            term -> [term]
          providerCutoff = csNextMeta callerState
          occurrenceMetas = csLevelInstantiationMetas checkedState
          unresolvedTermMeta =
            not . null . unsolvedMetasOf checkedState
          freshTermMeta term =
            any
              (>= providerCutoff)
              (foldTerm (\case CMeta meta -> [meta]; _ -> []) (const []) term)
          freshLevelMeta =
            any (>= providerCutoff) . levelMetasOfTerm
          unresolvedOccurrenceLevelMeta =
            any (`Set.member` occurrenceMetas) . levelMetasOfTerm
       in any
            ( \term ->
                unresolvedTermMeta term
                  || freshTermMeta term
                  || freshLevelMeta term
                  || unresolvedOccurrenceLevelMeta term
            )
            terms

    -- Instance search freshens a declaration's universe telescope before
    -- matching it against the exact provider goal. Those occurrence metas are
    -- query-local, but their equalities may remain in the pending level solver
    -- until the enclosing declaration closes. A portable certificate cannot
    -- retain them: obtain the principal solution of precisely their connected
    -- constraint component and substitute it into the candidate artifact
    -- without committing any assignment to the caller. Failure to establish a
    -- principal specialization is a conservative provider miss.
    closeProviderLocalLevels callerState candidate = do
      zonked <- zonkTermM (ctxLen ctx) candidate
      checkedState <- get
      let cutoff = csNextMeta callerState
          candidateMetas = Set.fromList (levelMetasOfTerm zonked)
          localOccurrenceMetas =
            Set.difference
              (csLevelInstantiationMetas checkedState)
              (csLevelInstantiationMetas callerState)
          localMetas =
            Set.filter
              ( \meta ->
                  meta >= cutoff
                    || meta `Set.member` localOccurrenceMetas
              )
              candidateMetas
      fmap snd
        <$> principalizeLevelOccurrence
          (ctxLen ctx)
          callerState
          localMetas
          zonked

    transactional action = do
      saved <- get
      diagnostics <- gets (length . csDiags)
      result <- action
      diagnostics' <- gets (length . csDiags)
      case result of
        Just proof | diagnostics == diagnostics' -> pure (Just proof)
        _ -> put saved >> pure Nothing

-- | Relate two provider-normalizable endpoints without adding a conversion
-- rule. Each side must independently reduce to the same checked intermediate
-- through one exact provider law (or ordinary definitional equality). The
-- resulting proof is the explicit transitive composition
--
-- @lhs = normal@ and @sym (rhs = normal)@.
--
-- This is the proof-term counterpart of §15.8.2 evidence canonicalization.
-- It is needed when one occurrence has already been reified to a canonical
-- operation while another is still projected from a coherent local evidence
-- closure. Provider metadata supplies the semantic operation/law identity;
-- no rendered trait, member, or operation spelling is inspected here.
providerNormalFormBridgeProof
  :: Ctx
  -> Maybe Term
  -> Value
  -> Value
  -> Value
  -> Value
  -> CheckM (Maybe Term)
providerNormalFormBridgeProof ctx sourceGoal equalityGoal carrier lhs rhs =
  transactional $ do
    carrier' <- forceM carrier
    case carrier' of
      VGlobN natural [] | natural == prelNat -> do
        goalTerm <-
          case sourceGoal of
            Just source -> zonkTermM (ctxLen ctx) source
            Nothing -> quoteIn ctx equalityGoal >>= zonkTermM (ctxLen ctx)
        case equalityExplicitEndpoints goalTerm of
          Nothing -> pure Nothing
          Just (lhsTerm, rhsTerm) ->
            firstBridge
              lhsTerm
              rhsTerm
              (providerReductionTargets lhsTerm ++ providerReductionTargets rhsTerm)
      _ -> pure Nothing
  where
    providerReductionTargets endpoint =
      nub
        [ target
        | provider <- standardProofNormalizationProviders
        , Just target <- [reductionTarget provider endpoint]
        ]

    reductionTarget provider endpoint =
      case (pnpLawRole provider, providerLawArguments provider endpoint) of
        (ProviderLeftIdentity, Just [target]) -> Just target
        (ProviderRightIdentity, Just [target]) -> Just target
        _ -> Nothing

    firstBridge _ _ [] = pure Nothing
    firstBridge lhsTerm rhsTerm (middleTerm : rest) = do
      candidateState <- get
      equalityProof lhsTerm middleTerm >>= \case
        Nothing -> put candidateState >> firstBridge lhsTerm rhsTerm rest
        Just (lhsProof, lhsEquality) ->
          equalityProof rhsTerm middleTerm >>= \case
            Nothing -> put candidateState >> firstBridge lhsTerm rhsTerm rest
            Just (rhsProof, rhsEquality) -> do
              carrierTerm <- quoteIn ctx carrier >>= zonkTermM (ctxLen ctx)
              classifier <- equandType ctx carrier >>= \case
                Just value -> pure value
                Nothing -> freshMetaV ctx
              globalTerm (gPrel "sym") >>= \case
                Nothing -> pure Nothing
                Just (symHead, symType) -> do
                  (reversedRhs, reversedRhsType) <-
                    applyGeneratedCoreSpine
                      ctx
                      noSpan
                      symHead
                      symType
                      [ (Impl, carrierTerm, classifier)
                      , (Impl, rhsTerm, carrier)
                      , (Impl, middleTerm, carrier)
                      , (Expl, rhsProof, rhsEquality)
                      ]
                  globalTerm (gPrel "trans") >>= \case
                    Nothing -> pure Nothing
                    Just (transHead, transType) -> do
                      (proof, proofType) <-
                        applyGeneratedCoreSpine
                          ctx
                          noSpan
                          transHead
                          transType
                          [ (Impl, carrierTerm, classifier)
                          , (Impl, lhsTerm, carrier)
                          , (Impl, middleTerm, carrier)
                          , (Impl, rhsTerm, carrier)
                          , (Expl, lhsProof, lhsEquality)
                          , (Expl, reversedRhs, reversedRhsType)
                          ]
                      exact <- unifyDefinitional ctx proofType equalityGoal
                      pure (if exact then Just proof else Nothing)

    equalityProof fromTerm toTerm = do
      from <- evalIn ctx fromTerm
      to <- evalIn ctx toTerm
      equality <-
        globalValueM
          prelEqType
          [(Impl, carrier), (Expl, from), (Expl, to)]
      equalityTerm <- quoteIn ctx equality >>= zonkTermM (ctxLen ctx)
      ec <- ec_
      if convertible ec (ctxLen ctx) (force ec from) (force ec to)
        then do
          proof <- generatedReflAtM ctx equality
          pure (Just (proof, equality))
        else
          providerLawProof
            ctx
            (Just equalityTerm)
            Nothing
            equality
            carrier
            from
            to >>= \case
              Nothing -> pure Nothing
              Just proof -> pure (Just (proof, equality))

    transactional action = do
      saved <- get
      diagnostics <- gets (length . csDiags)
      result <- action
      diagnostics' <- gets (length . csDiags)
      case result of
        Just proof | diagnostics == diagnostics' -> pure (Just proof)
        _ -> put saved >> pure Nothing

-- | Standard-library provider interface.  Every identity is the resolved
-- object identity installed by the authenticated embedded prelude.  More
-- theory kinds extend this table without adding source-name recognition to
-- the generic provider engine.
standardProofNormalizationProviders :: [ProofNormalizationProvider]
standardProofNormalizationProviders =
  [ additiveMonoidProvider
      "std.prelude.provider.additive-monoid.left-identity"
      ProviderLeftIdentity
      "addLeftIdentity"
  , additiveMonoidProvider
      "std.prelude.provider.additive-monoid.right-identity"
      ProviderRightIdentity
      "addRightIdentity"
  , ProofNormalizationProvider
      { pnpIdentity = "std.prelude.provider.commutative-additive-monoid"
      , pnpTheory = ArithmeticCommutativeMonoid
      , pnpLawRole = ProviderCommutative
      , pnpOperationIdentities =
          [ prelAddOp
          , prelAddMethod
          , prelNatAdd
          , memberGlobal prelAdd "add"
          ]
      , pnpEvidenceTrait = gPrel "CommutativeAdditiveMonoid"
      , pnpLawOwner = gPrel "CommutativeAdditiveMonoid"
      , pnpLawField = "addCommutative"
      , pnpLawIdentity =
          memberGlobal
            (gPrel "CommutativeAdditiveMonoid")
            "addCommutative"
      , pnpNormalFormVersion = 1
      , pnpProviderVersion = 1
      , pnpCheckerVersion = 1
      }
  ]
  where
    additiveMonoidProvider identity role field =
      ProofNormalizationProvider
        { pnpIdentity = identity
        , pnpTheory = ArithmeticMonoid
        , pnpLawRole = role
        , pnpOperationIdentities =
            [ prelAddOp
            , prelAddMethod
            , prelNatAdd
            , memberGlobal prelAdd "add"
            ]
        , pnpEvidenceTrait = gPrel "AdditiveMonoid"
        , pnpLawOwner = gPrel "AdditiveMonoid"
        , pnpLawField = field
        , pnpLawIdentity = memberGlobal (gPrel "AdditiveMonoid") field
        , pnpNormalFormVersion = 1
        , pnpProviderVersion = 1
        , pnpCheckerVersion = 1
        }

-- | Match the operation application named by the authenticated provider and
-- extract exactly the arguments demanded by its law role. The instantiated
-- member type is still checked against the complete equality goal, so merely
-- resembling an identity or commutativity law grants no authority.
providerLawArguments
  :: ProofNormalizationProvider
  -> Term
  -> Maybe [Term]
providerLawArguments provider application =
  case spineOfTerm (stripIdentityWrappers application) of
    (headTerm, arguments)
      | Just operation <- termHeadGlob (stripIdentityWrappers headTerm)
      , operation `elem` pnpOperationIdentities provider
      , Just (left, right) <-
          last2 [argument | (Expl, argument) <- arguments] ->
          Just $ case pnpLawRole provider of
            ProviderLeftIdentity -> [right]
            ProviderRightIdentity -> [left]
            ProviderCommutative -> [left, right]
    _ -> Nothing

equalityExplicitEndpoints :: Term -> Maybe (Term, Term)
equalityExplicitEndpoints term =
  case spineOfTerm (stripIdentityWrappers term) of
    (headTerm, arguments)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelEqType ->
          last2 [argument | (Expl, argument) <- arguments]
    _ -> Nothing

-- | Decode an equality between a checked Bool term and a resolved prelude Bool
-- literal. The literal may occur on either side; source spelling and arbitrary
-- same-named constructors carry no authority.
booleanLiteralEqualityPayload :: Term -> Maybe (Bool, Term)
booleanLiteralEqualityPayload term =
  case spineOfTerm (stripIdentityWrappers term) of
    (headTerm, arguments)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelEqType
      , carrier : _ <- [argument | (Impl, argument) <- arguments]
      , termHeadGlob (stripIdentityWrappers carrier) == Just prelBool
      , Just (lhs, rhs) <-
          last2 [argument | (Expl, argument) <- arguments] ->
          case (boolLiteral lhs, boolLiteral rhs) of
            (_, Just truth) -> Just (truth, lhs)
            (Just truth, _) -> Just (truth, rhs)
            _ -> Nothing
    _ -> Nothing
  where
    boolLiteral candidate =
      case stripIdentityWrappers candidate of
        CCtor constructor _ []
          | constructor == prelTrue -> Just True
          | constructor == prelFalse -> Just False
        CCtorI constructor _ _ []
          | constructor == prelTrue -> Just True
          | constructor == prelFalse -> Just False
        _ -> Nothing

-- | Freeze one solver-established first-class TypeLevel proposition as an
-- explicit proof certificate. Every lexical level assumption is retained as
-- its actual erased proof-binder proposition; KCoreText re-authenticates the
-- standard operations and independently replays the goal from exactly this
-- list. The certificate therefore cannot turn semantic equality into
-- definitional equality or capture an unrecorded ambient solver fact.
typeLevelPropositionCertificate :: Ctx -> Value -> CheckM Term
typeLevelPropositionCertificate ctx goal = do
  let depth = ctxLen ctx
  rawGoal <- quoteIn ctx goal >>= zonkTermM depth
  rawAssumptions <- typeLevelCertificateAssumptions ctx
  providers <-
    typeLevelCertificateProviders
      (rawGoal : [proposition | ArithmeticAssumption _ proposition _ _ <- rawAssumptions])
  normalizedGoal <- do
    normalized <- transparentProofNormalize depth rawGoal
    pure (fromMaybe rawGoal normalized)
  replayGoal <-
    canonicalizeTypeLevelCertificateProposition ctx normalizedGoal
  assumptions <-
    forM rawAssumptions $ \(ArithmeticAssumption truth proposition _ source) -> do
      normalized <- transparentProofNormalize depth proposition
      let checkedProposition = fromMaybe proposition normalized
      replayProposition <-
        canonicalizeTypeLevelCertificateProposition ctx checkedProposition
      normalizedSource <- case source of
        ArithmeticAssumptionProof sourceProposition evidence -> do
          sourceNormalized <- transparentProofNormalize depth sourceProposition
          pure
            ( ArithmeticAssumptionProof
                (fromMaybe sourceProposition sourceNormalized)
                evidence
            )
        ArithmeticAssumptionConversion sourceProposition -> do
          sourceNormalized <- transparentProofNormalize depth sourceProposition
          pure
            ( ArithmeticAssumptionConversion
                (fromMaybe sourceProposition sourceNormalized)
            )
        ArithmeticAssumptionBranch branchTruth condition -> do
          conditionNormalized <- transparentProofNormalize depth condition
          pure
            ( ArithmeticAssumptionBranch
                branchTruth
                (fromMaybe condition conditionNormalized)
            )
      pure
        ( ArithmeticAssumption
            truth
            checkedProposition
            replayProposition
            normalizedSource
        )
  pure
    ( CArithmeticProof
        ArithmeticCertificate
          { acVersion = arithmeticCertificateVersion
          , acDomain = ArithmeticTypeLevel
          , acProviders = providers
          , acVariables = []
          , acAssumptions = assumptions
          , acGoal = normalizedGoal
          , acReplayGoal = replayGoal
          }
    )

-- | Canonicalize only the replay side of an authenticated first-class
-- TypeLevel proposition. The checked proposition and its proof source retain
-- their exact source-level type. A transparent helper participates here only
-- after 'classifyLevelOperatorTerm' has recorded its semantic operation
-- identity in 'csLevelOperatorAliases'; arbitrary unfolding and spelling-based
-- recognition are deliberately excluded.
canonicalizeTypeLevelCertificateProposition :: Ctx -> Term -> CheckM Term
canonicalizeTypeLevelCertificateProposition ctx proposition =
  case spineOfTerm (stripIdentityWrappers proposition) of
    (headTerm, arguments)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelEqType
      , carrier : _ <- [argument | (Impl, argument) <- arguments]
      , termHeadGlob (stripIdentityWrappers carrier) == Just prelBool
      , Just (lhsIndex, lhs, rhsIndex, rhs) <- lastTwoExplicit arguments ->
          case (isTrueTerm lhs, isTrueTerm rhs) of
            (False, True) ->
              canonicalizeRelation lhs >>= \case
                Nothing -> pure proposition
                Just relation ->
                  pure
                    (rebuildApplication headTerm (replaceAt lhsIndex relation arguments))
            (True, False) ->
              canonicalizeRelation rhs >>= \case
                Nothing -> pure proposition
                Just relation ->
                  pure
                    (rebuildApplication headTerm (replaceAt rhsIndex relation arguments))
            _ -> pure proposition
    _ -> pure proposition
  where
    canonicalizeRelation relation =
      typeLevelRelationSpine relation >>= \case
        Nothing -> pure Nothing
        Just (_, arguments) ->
          case lastTwoExplicit arguments of
            Nothing -> pure Nothing
            Just (lhsIndex, lhs, rhsIndex, rhs) -> do
              lhsLevel <- coreTypeLevel ctx lhs
              rhsLevel <- coreTypeLevel ctx rhs
              pure $ do
                lhs' <- CLevel . normalizeLevel <$> lhsLevel
                rhs' <- CLevel . normalizeLevel <$> rhsLevel
                let (headTerm, _) = spineOfTerm relation
                pure
                  ( rebuildApplication
                      headTerm
                      ( replaceAt
                          rhsIndex
                          rhs'
                          (replaceAt lhsIndex lhs' arguments)
                      )
                  )

    lastTwoExplicit arguments =
      case reverse
        [ (index, argument)
        | (index, (Expl, argument)) <- zip [0 :: Int ..] arguments
        ]
      of
        (rhsIndex, rhs) : (lhsIndex, lhs) : _ ->
          Just (lhsIndex, lhs, rhsIndex, rhs)
        _ -> Nothing

    replaceAt index replacement =
      zipWith
        (\offset (icit, argument) ->
          (icit, if offset == index then replacement else argument))
        [0 :: Int ..]

    rebuildApplication =
      List.foldl' (\function (icit, argument) -> CApp icit function argument)

    isTrueTerm = \case
      CCtor constructor _ [] -> constructor == prelTrue
      CCtorI constructor _ _ [] -> constructor == prelTrue
      _ -> False

typeLevelCertificateAssumptions :: Ctx -> CheckM [ArithmeticAssumption Term]
typeLevelCertificateAssumptions ctx =
  fmap catMaybes . forM (zip [0 :: Int ..] (ctxEntries ctx)) $ \(index, entry) ->
    if ceMode entry == Ordinary
        && ceImplicitLocal entry
        && ceCoreQ entry == Q0
      then do
        authenticatedLevelGoalRelation ctx (ceType entry) >>= \case
          Nothing -> pure Nothing
          Just _ -> do
            proposition <- quoteIn ctx (ceType entry) >>= zonkTermM (ctxLen ctx)
            pure
              ( Just
                  ( ArithmeticAssumption
                      True
                      proposition
                      proposition
                      (ArithmeticAssumptionProof proposition (CVar index))
                  )
              )
      else pure Nothing

typeLevelCertificateProviders
  :: [Term]
  -> CheckM [ArithmeticProviderEvidence Term]
typeLevelCertificateProviders roots = do
  let candidates =
        nub
          [ (trait, dictionary)
          | root <- roots
          , (trait, dictionary) <-
              foldTerm providerCandidate (const []) root
          ]
  fmap catMaybes . forM candidates $ \(trait, dictionary) -> do
    standard <- standardTypeLevelDictionary trait dictionary
    pure
      ( if standard
          then Just (ArithmeticProviderEvidence Nothing trait dictionary)
          else Nothing
      )
  where
    providerCandidate term =
      case spineOfTerm (stripIdentityWrappers term) of
        (headTerm, arguments)
          | Just operation <- termHeadGlob (stripIdentityWrappers headTerm)
          , Just trait <- Map.lookup operation providerTraits
          , _carrier : dictionary : _ <-
              [argument | (Impl, argument) <- arguments] ->
              [(trait, dictionary)]
        _ -> []

    providerTraits =
      Map.fromList
        [ (gPrel "<", gPrel "Ord")
        , (gPrel "<=", gPrel "Ord")
        , (gPrel "add", gPrel "Add")
        , (gPrel "max", gPrel "Max")
        , (gPrel "succ", gPrel "Successor")
        , (gPrel "fromInteger", gPrel "FromInteger")
        ]

-- | Produce a replayable value-arithmetic proof without extending conversion.
-- Every accepted local atom and assumption is recorded in the certificate
-- context.  The independent KCore checker reifies the same authenticated
-- operations and reruns the pure arithmetic kernel; unsupported carriers,
-- polarities, provider heads, and unscoped atoms fail closed.
arithmeticEqualityCertificate
  :: Ctx
  -> Maybe Term
  -> Value
  -> Value
  -> Value
  -> Value
  -> CheckM (Maybe Term)
arithmeticEqualityCertificate ctx sourceGoal equalityGoal carrier lhs rhs = do
  carrier' <- forceM carrier
  let domains = case carrier' of
        VGlobN natural [] | natural == prelNat -> [ArithmeticNatural]
        VGlobN integer [] | integer == prelInteger || integer == prelInt ->
          [ArithmeticInteger]
        VGlobN boolean [] | boolean == prelBool ->
          [ArithmeticNatural, ArithmeticInteger]
        _ -> []
  case domains of
    [] -> pure Nothing
    _ -> do
      let depth = ctxLen ctx
      checkedGoal <- case sourceGoal of
        Just term -> zonkTermM depth term
        Nothing -> quoteIn ctx equalityGoal >>= zonkTermM depth
      replayGoal <- normalizeArithmeticCertificateGoal depth checkedGoal
      variables <- ctxArithmeticVariables ctx
      firstCertificate variables checkedGoal replayGoal domains
  where
    firstCertificate _ _ _ [] = pure Nothing
    firstCertificate variables checkedGoal replayGoal (domain : rest) = do
      arithmeticCertificateForDomain
        ctx
        domain
        variables
        checkedGoal
        replayGoal >>= \case
        Just certificate -> pure (Just (CArithmeticProof certificate))
        Nothing -> firstCertificate variables checkedGoal replayGoal rest

normalizeArithmeticCertificateTerm :: Int -> Term -> CheckM Term
normalizeArithmeticCertificateTerm depth term = do
  -- Certificate payloads cross the independent KCore boundary. Normalize the
  -- already checked source term all the way to canonical Core operations so
  -- replay does not depend on a source-level trait wrapper or dictionary
  -- spelling. Partial-operation domains are rechecked from the recorded
  -- assumptions by the arithmetic kernel; normalization grants no authority.
  finalized <- zonkTermM depth term
  instances <- gets csInstances
  pure
    ( simplifyDecisionTermAt depth
        (canonicalizeStandardArithmeticOperations instances finalized)
    )

-- | Put the arithmetic endpoints of a certificate goal into a definitionally
-- equal, bounded transparent normal form before they cross the KCore trust
-- boundary. This exposes ordinary transparent predicates and helpers to the
-- small portable arithmetic language without teaching KCore about generated
-- dictionaries or local definitions. Authenticated arithmetic heads remain
-- opaque and only their operands are normalized.
normalizeArithmeticCertificateGoal :: Int -> Term -> CheckM Term
normalizeArithmeticCertificateGoal depth rawGoal = do
  goal <- normalizeArithmeticCertificateTerm depth rawGoal
  case certificateGoalEndpoints goal of
    Nothing -> pure goal
    Just (GoalBooleanPredicate predicate) -> do
      reduced <- normalizeArithmeticPredicateTerm depth 24 predicate
      normalizeArithmeticCertificateTerm
        depth
        (replaceExplicitSubterm predicate reduced goal)
    Just (GoalArithmeticEquality lhs rhs) -> do
      lhs' <- normalizeArithmeticOperandTerm depth 24 lhs
      rhs' <- normalizeArithmeticOperandTerm depth 24 rhs
      normalizeArithmeticCertificateTerm
        depth
        ( replaceExplicitSubterm
            rhs
            rhs'
            (replaceExplicitSubterm lhs lhs' goal)
        )
  where
    certificateGoalEndpoints candidate =
      case spineOfTerm (stripIdentityWrappers candidate) of
        (headTerm, arguments)
          | termHeadGlob (stripIdentityWrappers headTerm) == Just prelEqType
          , carrier : _ <- [argument | (Impl, argument) <- arguments]
          , Just (lhs, rhs) <-
              last2 [argument | (Expl, argument) <- arguments] ->
              if isBoolType carrier
                then case (isTrueTerm lhs, isTrueTerm rhs) of
                  (False, True) -> Just (GoalBooleanPredicate lhs)
                  (True, False) -> Just (GoalBooleanPredicate rhs)
                  _ -> Nothing
                else case arithmeticDomainForCarrier carrier of
                  Just ArithmeticNatural ->
                    Just (GoalArithmeticEquality lhs rhs)
                  Just ArithmeticInteger ->
                    Just (GoalArithmeticEquality lhs rhs)
                  _ -> Nothing
        _ -> Nothing

    replaceExplicitSubterm target replacement = \case
      CUniverseLift lower upper evidence inner ->
        CUniverseLift
          lower
          upper
          evidence
          (replaceExplicitSubterm target replacement inner)
      CSchemaLift family source targetLevel roles roleEvidence certificate sourceArguments targetArguments inner ->
        CSchemaLift
          family
          source
          targetLevel
          roles
          roleEvidence
          certificate
          sourceArguments
          targetArguments
          (replaceExplicitSubterm target replacement inner)
      candidate ->
        let (headTerm, arguments) = spineOfTerm candidate
         in List.foldl'
              (\function (icit, argument) ->
                CApp
                  icit
                  function
                  ( if icit == Expl && argument == target
                      then replacement
                      else argument
                  ))
              headTerm
              arguments

    isBoolType candidate =
      termHeadGlob (stripIdentityWrappers candidate) == Just prelBool

    isTrueTerm = \case
      CCtor constructor _ [] -> constructor == prelTrue
      CCtorI constructor _ _ [] -> constructor == prelTrue
      _ -> False

data ArithmeticCertificateGoalEndpoints
  = GoalBooleanPredicate !Term
  | GoalArithmeticEquality !Term !Term

-- | Canonicalize the value operands of an already-authenticated arithmetic
-- predicate before it crosses the KCore boundary.  The independent verifier
-- has stable primitive identities but deliberately does not have permission
-- to unfold arbitrary source definitions.  Bounded delta/beta reduction here
-- therefore exposes transparent helpers such as @natMin@/@natClamp@ while
-- retaining the selected comparison head and its dictionary arguments.
normalizeArithmeticPredicateTerm :: Int -> Int -> Term -> CheckM Term
normalizeArithmeticPredicateTerm depth fuel term
  | fuel <= 0 = pure term
  | otherwise =
      case simplifyDecisionTerm term of
        candidate@CApp {}
          | authenticatedComparisonApplication candidate ->
              normalizeComparisonArguments candidate
        _ -> do
          reduced <- transparentProofReduce depth 48 term
          case simplifyDecisionTerm reduced of
            CIf condition thenTerm elseTerm ->
              CIf
                <$> normalizeArithmeticPredicateTerm depth (fuel - 1) condition
                <*> normalizeArithmeticPredicateTerm depth (fuel - 1) thenTerm
                <*> normalizeArithmeticPredicateTerm depth (fuel - 1) elseTerm
            candidate@CApp {}
              | authenticatedComparisonApplication candidate ->
                  normalizeComparisonArguments candidate
            candidate -> pure candidate
  where
    authenticatedComparisonApplication candidate =
      let (headTerm, _) = spineOfTerm (stripIdentityWrappers candidate)
       in authenticatedComparisonHead headTerm

    normalizeComparisonArguments candidate = do
      let (headTerm, arguments) =
            spineOfTerm (stripIdentityWrappers candidate)
      arguments' <-
        traverse
          (\case
            (Expl, argument) ->
              (Expl,)
                <$> normalizeArithmeticOperandTerm
                  depth
                  (fuel - 1)
                  argument
            implicit -> pure implicit)
          arguments
      pure
        ( List.foldl'
            (\function (icit, argument) -> CApp icit function argument)
            headTerm
            arguments'
        )

    authenticatedComparisonHead headTerm =
      termHeadGlob (stripIdentityWrappers headTerm)
        `elem`
          [ Just (gPrel "<")
          , Just (gPrel "<=")
          , Just (gPrel "==")
          , Just (gPrel "ltInt")
          , Just (gPrel "leInt")
          , Just (gPrel "eqInt")
          ]

normalizeArithmeticOperandTerm :: Int -> Int -> Term -> CheckM Term
normalizeArithmeticOperandTerm depth fuel term
  | fuel <= 0 = pure term
  | otherwise =
      case simplifyDecisionTerm term of
        candidate@CApp {}
          | authenticatedArithmeticApplication candidate ->
              normalizeApplicationArguments candidate
        _ -> do
          reduced <- transparentProofReduce depth 48 term
          case simplifyDecisionTerm reduced of
            CIf condition thenTerm elseTerm ->
              CIf
                <$> normalizeArithmeticPredicateTerm depth (fuel - 1) condition
                <*> normalizeArithmeticOperandTerm depth (fuel - 1) thenTerm
                <*> normalizeArithmeticOperandTerm depth (fuel - 1) elseTerm
            candidate@CApp {} ->
              normalizeApplicationArguments candidate
            candidate -> pure candidate
  where
    authenticatedArithmeticApplication candidate =
      case spineOfTerm (stripIdentityWrappers candidate) of
        (headTerm, _) ->
          case termHeadGlob (stripIdentityWrappers headTerm) of
            Just global ->
              global == prelNatAdd
                || global == prelNatMultiply
                || isJust (intArithPrim global)
            Nothing -> False

    normalizeApplicationArguments candidate = do
      let (headTerm, arguments) = spineOfTerm candidate
      arguments' <-
        traverse
          (\case
            (Expl, argument) ->
              (Expl,)
                <$> normalizeArithmeticOperandTerm
                  depth
                  (fuel - 1)
                  argument
            implicit -> pure implicit)
          arguments
      pure
        ( List.foldl'
            (\function (icit, argument) -> CApp icit function argument)
            headTerm
            arguments'
        )

arithmeticCertificateForDomain
  :: Ctx
  -> ArithmeticDomain
  -> [(Int, ArithmeticVariableKind)]
  -> Term
  -> Term
  -> CheckM (Maybe (ArithmeticCertificate Term))
arithmeticCertificateForDomain ctx domain variables goal replayGoal = do
  let depth = ctxLen ctx
      admittedVariables =
        [ (level, kind)
        | (level, kind) <- variables
        , arithmeticVariableBelongsToDomain domain kind
        ]
      admittedLevels = Set.fromList (map fst admittedVariables)
      naturalLevels =
        Set.fromList
          [ level
          | (level, kind) <- admittedVariables
          , kind == ArithmeticVariableNatural
          ]
  arithmeticFormulaForDomain depth domain replayGoal >>= \case
    Nothing -> pure Nothing
    Just goalFormula -> do
      assumptions <- arithmeticCertificateAssumptions ctx domain
      providers <-
        valueArithmeticCertificateProviders
          ctx
          domain
          (goal : map aaProposition assumptions)
      assumptionFormulas <-
        arithmeticAssumptionFormulasForDomain depth domain assumptions
      let factLevels = arithmeticFormulaVariables goalFormula
          assumptionLevels =
            Set.unions
              [ arithmeticFormulaVariables formula
              | (_, formula) <- assumptionFormulas
              ]
          scoped =
            Set.isSubsetOf (factLevels `Set.union` assumptionLevels) admittedLevels
          replay =
            if scoped
              then do
                semantics <- arithmeticSemanticsForDomain domain
                deriveArithmeticFormulaReplayWithAssumptions
                  semantics
                  naturalLevels
                  assumptionFormulas
                  True
                  goalFormula
              else Nothing
      pure $ do
        _ <- replay
        let certificateVariables =
              [ ArithmeticVariable kind (CVar (depth - 1 - level))
              | (level, kind) <- sortOn fst admittedVariables
              , level >= 0
              , level < depth
              ]
        pure
          ArithmeticCertificate
            { acVersion = arithmeticCertificateVersion
            , acDomain = domain
            , acProviders = providers
            , acVariables = certificateVariables
            , acAssumptions = assumptions
            , acGoal = goal
            , acReplayGoal = replayGoal
            }

-- | Retain the exact standard evidence whose overloaded operations occur in
-- a value-arithmetic certificate's checked propositions. Replay uses
-- canonical primitives, but the independent checker must still authenticate
-- the source-side operation/evidence pair instead of inferring standard
-- semantics from a member spelling.
standardArithmeticDirectProvider
  :: Term
  -> Maybe (GName, Term, Term)
standardArithmeticDirectProvider term = do
  let (headTerm, arguments) =
        spineOfTerm (stripIdentityWrappers term)
  operation <- termHeadGlob (stripIdentityWrappers headTerm)
  trait <- standardArithmeticOperationTrait operation
  carrier : dictionary : _ <-
    pure [argument | (Impl, argument) <- arguments]
  pure (trait, carrier, dictionary)

valueArithmeticCertificateProviders
  :: Ctx
  -> ArithmeticDomain
  -> [Term]
  -> CheckM [ArithmeticProviderEvidence Term]
valueArithmeticCertificateProviders ctx domain roots = do
  providerRoots <- transparentArithmeticProviderRoots roots
  normalizedCandidates <-
    forM (rawCandidates providerRoots) $ \(trait, dictionary) ->
      (trait,) <$> zonkTermM (ctxLen ctx) dictionary
  let candidates =
        nubBy
          (\(leftTrait, leftEvidence) (rightTrait, rightEvidence) ->
            leftTrait == rightTrait
              && renderStructuralTermKey leftEvidence
                == renderStructuralTermKey rightEvidence)
          normalizedCandidates
  fmap catMaybes . forM candidates $ \(trait, dictionary) -> do
    standard <-
      standardPreludeDictionary
        trait
        (\case
          [headType] -> arithmeticDomainForCarrier headType == Just domain
          _ -> False)
        dictionary
    pure
      ( if standard
          then Just (ArithmeticProviderEvidence Nothing trait dictionary)
          else Nothing
      )
  where
    rawCandidates candidateRoots =
      [ (trait, dictionary)
      | root <- candidateRoots
      , (trait, carrier, dictionary) <-
          foldTerm providerCandidate (const []) root
      , arithmeticDomainForCarrier carrier == Just domain
      ]

    -- Selected operations hidden in an ordinary transparent helper or a
    -- generated dictionary factory still need to be authenticated by the
    -- artifact. Follow only applied checked reducible definitions, stop at
    -- arithmetic operations themselves, and bound/cycle-check the closure.
    -- A dictionary factory may be saturated entirely by erased evidence, so
    -- requiring an explicit runtime argument would skip its selected methods.
    transparentArithmeticProviderRoots initial = do
      state <- get
      pure (go state 12 Set.empty initial initial)

    go _ 0 _ _ accumulated = accumulated
    go state fuel seen frontier accumulated =
      let callees =
            Set.fromList
              [ global
              | root <- frontier
              , global <-
                  foldTerm transparentCallee (const []) root
              , global `Set.notMember` seen
              ]
          bodies =
            [ body
            | global <- Set.toAscList callees
            , Just definition <- [Map.lookup global (csGlobals state)]
            , gdReducible definition
            , Just body <-
                [ Map.lookup global (csCoreBodies state)
                    <|> gdCoreBody definition
                ]
            ]
       in if null bodies
            then accumulated
            else
              go
                state
                (fuel - 1)
                (Set.union seen callees)
                bodies
                (accumulated ++ bodies)

    transparentCallee term =
      case spineOfTerm (stripIdentityWrappers term) of
        (headTerm, arguments)
          | not (null arguments)
          , Just global <- termHeadGlob (stripIdentityWrappers headTerm)
          , isNothing (standardArithmeticOperationTrait global)
          , isNothing (intArithPrim global)
          , isNothing (intCmpPrim global) ->
              [global]
        _ -> []

    providerCandidate term =
      case spineOfTerm (stripIdentityWrappers term) of
        (headTerm, arguments) ->
          case standardArithmeticDirectProvider term of
            Just provider -> [provider]
            Nothing -> maybeToList (projectedProvider headTerm arguments)

    projectedProvider headTerm _arguments = do
      (dictionary, member) <- case stripIdentityWrappers headTerm of
        CProjM _ dictionary' member' -> Just (dictionary', member')
        CProjAtM _ dictionary' member' _ -> Just (dictionary', member')
        _ -> Nothing
      trait <- standardArithmeticMemberTrait member
      carrier <-
        case domain of
          ArithmeticNatural -> Just (CGlob prelNat)
          ArithmeticInteger -> Just (CGlob prelInteger)
          ArithmeticTypeLevel -> Nothing
          ArithmeticProviderLaw -> Nothing
      pure (trait, carrier, dictionary)

standardArithmeticOperationTrait :: GName -> Maybe GName
standardArithmeticOperationTrait operation
  | operation
      `elem`
        [ gPrel "=="
        , memberGlobal (gPrel "Eq") "=="
        ] =
      Just (gPrel "Eq")
  | operation `elem` [gPrel "<", gPrel "<="] = Just prelOrd
  | operation `elem` [prelAddOp, prelAddMethod, memberGlobal prelAdd "add"] =
      Just prelAdd
  | operation
      `elem`
        [ gPrel "*"
        , gPrel "multiply"
        , memberGlobal (gPrel "Mul") "multiply"
        ] =
      Just (gPrel "Mul")
  | operation
      `elem`
        [ gPrel "-"
        , gPrel "subtract"
        , memberGlobal (gPrel "CheckedSub") "subtract"
        ] =
      Just (gPrel "CheckedSub")
  | operation
      `elem`
        [ gPrel "/"
        , gPrel "divide"
        , memberGlobal (gPrel "CheckedDiv") "divide"
        ] =
      Just (gPrel "CheckedDiv")
  | operation
      `elem`
        [ gPrel "%"
        , gPrel "modulo"
        , memberGlobal (gPrel "CheckedMod") "modulo"
        ] =
      Just (gPrel "CheckedMod")
  | otherwise = Nothing

standardArithmeticMemberTrait :: Text -> Maybe GName
standardArithmeticMemberTrait = \case
  "==" -> Just (gPrel "Eq")
  "<" -> Just prelOrd
  "<=" -> Just prelOrd
  "add" -> Just prelAdd
  "multiply" -> Just (gPrel "Mul")
  "subtract" -> Just (gPrel "CheckedSub")
  "divide" -> Just (gPrel "CheckedDiv")
  "modulo" -> Just (gPrel "CheckedMod")
  _ -> Nothing

arithmeticSemanticsForDomain :: ArithmeticDomain -> Maybe ArithmeticSemantics
arithmeticSemanticsForDomain = \case
  ArithmeticNatural -> Just ArithmeticNaturalSemantics
  ArithmeticInteger -> Just ArithmeticIntegerSemantics
  ArithmeticTypeLevel -> Nothing
  ArithmeticProviderLaw -> Nothing

arithmeticVariableBelongsToDomain
  :: ArithmeticDomain
  -> ArithmeticVariableKind
  -> Bool
arithmeticVariableBelongsToDomain domain kind =
  case (domain, kind) of
    (ArithmeticNatural, ArithmeticVariableNatural) -> True
    (ArithmeticInteger, ArithmeticVariableInteger) -> True
    _ -> False

ctxArithmeticVariables :: Ctx -> CheckM [(Int, ArithmeticVariableKind)]
ctxArithmeticVariables ctx =
  fmap catMaybes . forM (zip [0 :: Int ..] (ctxEntries ctx)) $ \(index, entry) -> do
    ty <- forceM (ceType entry)
    let level = ctxLen ctx - 1 - index
    pure $ case ty of
      VGlobN global []
        | global == prelNat ->
            Just (level, ArithmeticVariableNatural)
        | global == prelInteger || global == prelInt ->
            Just (level, ArithmeticVariableInteger)
      _ -> Nothing

arithmeticCertificateAssumptions
  :: Ctx
  -> ArithmeticDomain
  -> CheckM [ArithmeticAssumption Term]
arithmeticCertificateAssumptions ctx domain = do
  let depth = ctxLen ctx
  lexical <-
    fmap catMaybes . forM (zip [0 :: Int ..] (ctxEntries ctx)) $ \(index, entry) ->
      if ceMode entry == Ordinary && ceCoreQ entry == Q0
        then do
          proposition <- quoteIn ctx (ceType entry) >>= zonkTermM depth
          normalized <- normalizeArithmeticCertificateTerm depth proposition
          replay <- normalizeArithmeticCertificateGoal depth normalized
          replayFormulaResult <- arithmeticFormulaForDomain depth domain replay
          case replayFormulaResult of
            Just _ ->
              pure
                ( Just
                    ( ArithmeticAssumption
                        True
                        proposition
                        replay
                        (ArithmeticAssumptionProof proposition (CVar index))
                    )
                )
            _ -> pure Nothing
        else pure Nothing
  -- Certificate sources must remain the exact checked formulas that the
  -- independent KCore checker can recover from the emitted enclosing branch.
  -- Canonical operation lowering belongs to the separate proposition/replay
  -- fields below; applying it to the source would replace lexical selected
  -- operations with primitives and sever the source from the verified branch.
  -- The replay solver, rather than this collection boundary, decides whether
  -- bounded Boolean case analysis can establish the requested consequence.
  -- 'normalizeBoolFacts' additionally exposes transparently reduced aliases;
  -- those are useful to the local solver, but recording them as branch
  -- sources would let an elaborator-only reduction masquerade as lexical
  -- evidence in the portable artifact.
  scopedBranchFacts <- scopedBoolFactsAt depth =<< gets csBoolFacts
  let sourceBranchFacts =
        concat
          [ decomposeBoolFact 16 condition truth
          | (condition, truth) <- scopedBranchFacts
          ]
  branchFacts <-
    forM sourceBranchFacts $ \(condition, truth) -> do
      emittedCondition <- zonkTermM depth condition
      pure (emittedCondition, truth)
  branch <-
    fmap catMaybes . forM branchFacts $ \(condition, truth) -> do
      replayCondition <-
        normalizeArithmeticPredicateTerm depth 24 condition
      -- The branch source and the arithmetic replay have different trust
      -- roles.  KCore must be able to recover the proposition from the exact
      -- checked branch condition (including its selected dictionaries), while
      -- the solver consumes the normalized primitive form.  Building both
      -- from 'replayCondition' erased the source-side provider identity and
      -- made an otherwise valid certificate unverifiable.
      proposition <- booleanFactProposition ctx condition
      replayProposition <- booleanFactProposition ctx replayCondition
      replayNormalized <-
        normalizeArithmeticCertificateTerm depth replayProposition
      replayFormula <-
        arithmeticFormulaForDomain depth domain replayNormalized
      replay <-
        case
            replayFormula
              >>= arithmeticFormulaReplayTerm depth domain
          of
            Just replayCondition' ->
              booleanFactProposition ctx replayCondition'
                >>= normalizeArithmeticCertificateGoal depth
            Nothing ->
              normalizeArithmeticCertificateGoal depth replayNormalized
      arithmeticFormulaForDomain depth domain replay >>= \case
        Just _ ->
          pure
            ( Just
                ( ArithmeticAssumption
                    truth
                    proposition
                    replay
                    (ArithmeticAssumptionBranch truth condition)
                )
            )
        _ -> pure Nothing
  reflected <-
    fmap catMaybes . forM sourceBranchFacts $ \(condition, truth) ->
      if truth
        then reflectedArithmeticEqualityAssumption ctx domain condition
        else pure Nothing
  conversion <- arithmeticConversionAssumptions ctx domain
  pure
    ( nubBy
        (\left right ->
          aaTruth left == aaTruth right
            && renderStructuralTermKey (aaProposition left)
              == renderStructuralTermKey (aaProposition right))
        (lexical ++ branch ++ reflected ++ conversion)
    )

-- | Reconstruct the portable, domain-indexed Boolean term corresponding to
-- an already authenticated arithmetic formula.  Nat and Integer share the
-- exact integer primitive substrate, so replay must retain an explicit
-- @natToInt@ boundary around every open Nat comparison operand.  Reifying
-- from 'AFormula' is safe here because the formula was obtained through the
-- selected-evidence decoder above; this function grants no authority to a
-- source spelling and returns 'Nothing' for forms it cannot type faithfully.
arithmeticFormulaReplayTerm
  :: Int
  -> ArithmeticDomain
  -> AFormula
  -> Maybe Term
arithmeticFormulaReplayTerm depth domain = goFormula
  where
    goFormula = \case
      ATruth truth -> Just (boolTerm truth)
      AAtom (AFact comparison lhs rhs) -> do
        lhs' <- goExpression lhs
        rhs' <- goExpression rhs
        let comparisonTerm operation =
              binary
                operation
                (comparisonOperand lhs')
                (comparisonOperand rhs')
        pure $ case comparison of
          ACmpEq -> comparisonTerm (gPrel "eqInt")
          ACmpLt -> comparisonTerm (gPrel "ltInt")
          ACmpLe -> comparisonTerm (gPrel "leInt")
          ACmpNe ->
            CIf
              (comparisonTerm (gPrel "eqInt"))
              (boolTerm False)
              (boolTerm True)
      AAnd lhs rhs ->
        CIf
          <$> goFormula lhs
          <*> goFormula rhs
          <*> pure (boolTerm False)
      AOr lhs rhs ->
        CIf
          <$> goFormula lhs
          <*> pure (boolTerm True)
          <*> goFormula rhs
      ANot formula ->
        CIf
          <$> goFormula formula
          <*> pure (boolTerm False)
          <*> pure (boolTerm True)

    goExpression = \case
      AConst value
        | domain == ArithmeticInteger || value >= 0 ->
            Just (CLit (LitInt value))
      AVar level
        | level >= 0
        , level < depth ->
            Just (CVar (depth - 1 - level))
      AScale coefficient expression
        | domain == ArithmeticInteger || coefficient >= 0 ->
            binary (arithmeticGlobal "multiply")
              (CLit (LitInt coefficient))
              <$> goExpression expression
      AAdd lhs rhs ->
        binaryResult "add"
          <$> goExpression lhs
          <*> goExpression rhs
      ASub lhs rhs ->
        binaryResult "subtract"
          <$> goExpression lhs
          <*> goExpression rhs
      AMul lhs rhs ->
        binaryResult "multiply"
          <$> goExpression lhs
          <*> goExpression rhs
      ADiv lhs rhs ->
        binaryResult "divide"
          <$> goExpression lhs
          <*> goExpression rhs
      AMod lhs rhs ->
        binaryResult "modulo"
          <$> goExpression lhs
          <*> goExpression rhs
      ANeg expression
        | domain == ArithmeticInteger ->
            unary (gPrel "negInt") <$> goExpression expression
      AMax lhs rhs -> do
        lhs' <- goExpression lhs
        rhs' <- goExpression rhs
        pure
          ( CIf
              (binary (gPrel "leInt") (comparisonOperand lhs') (comparisonOperand rhs'))
              rhs'
              lhs'
          )
      AMin lhs rhs -> do
        lhs' <- goExpression lhs
        rhs' <- goExpression rhs
        pure
          ( CIf
              (binary (gPrel "leInt") (comparisonOperand lhs') (comparisonOperand rhs'))
              lhs'
              rhs'
          )
      AIf condition thenExpression elseExpression ->
        CIf
          <$> goFormula condition
          <*> goExpression thenExpression
          <*> goExpression elseExpression
      _ -> Nothing

    comparisonOperand = case domain of
      ArithmeticNatural -> unary prelNatToInt
      ArithmeticInteger -> id
      ArithmeticTypeLevel -> id
      ArithmeticProviderLaw -> id

    arithmeticGlobal operation = case (domain, operation) of
      (ArithmeticNatural, "add") -> prelNatAdd
      (ArithmeticNatural, "multiply") -> prelNatMultiply
      (_, "add") -> gPrel "addInt"
      (_, "subtract") -> gPrel "subInt"
      (_, "multiply") -> gPrel "mulInt"
      (_, "divide") -> gPrel "divInt"
      (_, "modulo") -> gPrel "modInt"
      _ -> gPrel operation

    binaryResult operation lhs rhs = case domain of
      ArithmeticNatural
        | operation == "add" || operation == "multiply" ->
            binary (arithmeticGlobal operation) lhs rhs
        | otherwise ->
            unary
              (gPrel "natOfInt")
              ( binary
                  (arithmeticGlobal operation)
                  (comparisonOperand lhs)
                  (comparisonOperand rhs)
              )
      _ -> binary (arithmeticGlobal operation) lhs rhs

    boolTerm truth =
      CCtorI (if truth then prelTrue else prelFalse) [] Nothing []
    unary function argument = CApp Expl (CGlob function) argument
    binary function lhs rhs =
      CApp Expl (CApp Expl (CGlob function) lhs) rhs

-- | Reify branch-local definitional refinements as explicit certificate
-- assumptions. The source checker admits only exact arithmetic locals whose
-- current 'FactIs' replacement makes the ordinary equality proposition
-- definitionally true. KCoreText does not trust that ambient fact: it repeats
-- the conversion check against the verified constructor-refinement
-- environment before replaying the arithmetic certificate.
arithmeticConversionAssumptions
  :: Ctx
  -> ArithmeticDomain
  -> CheckM [ArithmeticAssumption Term]
arithmeticConversionAssumptions ctx domain = do
  let depth = ctxLen ctx
      selectedKind = arithmeticVariableBelongsToDomain domain
      carrierGlobal = case domain of
        ArithmeticNatural -> Just prelNat
        ArithmeticInteger -> Just prelInteger
        ArithmeticTypeLevel -> Nothing
        ArithmeticProviderLaw -> Nothing
  variables <- ctxArithmeticVariables ctx
  facts <- gets csFacts
  case carrierGlobal of
    Nothing -> pure []
    Just global -> do
      carrierEntry <- globalTerm global
      equalityEntry <- globalTerm prelEqType
      case (carrierEntry, equalityEntry) of
        ( Just (carrierTerm, carrierKind)
          , Just (equalityTerm, equalityType)
          ) -> do
            carrier <- evalIn ctx carrierTerm
            fmap catMaybes . forM variables $ \(level, kind) ->
              case Map.lookup level facts of
                Just (FactIs replacement)
                  | selectedKind kind
                  , level >= 0
                  , level < depth -> do
                      let localTerm = CVar (depth - 1 - level)
                      replacementTerm <-
                        quoteIn ctx replacement >>= zonkTermM depth
                      local <- evalIn ctx localTerm
                      valid <- unifyDefinitional ctx local replacement
                      if not valid
                        then pure Nothing
                        else do
                          (proposition, _) <-
                            applyGeneratedCoreSpine
                              ctx
                              noSpan
                              equalityTerm
                              equalityType
                              [ (Impl, carrierTerm, carrierKind)
                              , (Expl, localTerm, carrier)
                              , (Expl, replacementTerm, carrier)
                              ]
                          proposition' <- zonkTermM depth proposition
                          pure
                            ( Just
                                ( ArithmeticAssumption
                                    True
                                    proposition'
                                    proposition'
                                    (ArithmeticAssumptionConversion proposition')
                                )
                            )
                _ -> pure Nothing
        _ -> pure []

-- | Turn a true checked @Eq.==@ branch fact into an ordinary arithmetic
-- equality assumption through the selected dictionary's checked @eqSound@
-- member. The tentative source-shape match grants no authority: the same
-- condition and dictionary must survive complete member reconstruction, and
-- the resulting proof must inhabit the exact ordinary equality proposition.
-- Recording that proof, rather than treating the Boolean spelling as an
-- arithmetic axiom, gives the independent KCore checker a self-contained
-- assumption source.
reflectedArithmeticEqualityAssumption
  :: Ctx
  -> ArithmeticDomain
  -> Term
  -> CheckM (Maybe (ArithmeticAssumption Term))
reflectedArithmeticEqualityAssumption ctx domain condition =
  case selectedEqConditionEndpoints condition of
    Nothing -> pure Nothing
    Just (left, right) -> transactionalAttempt (attempt left right)
  where
    transactionalAttempt action = do
      saved <- get
      diagnosticCount <- gets (length . csDiags)
      action >>= \case
        Just result -> do
          diagnosticCount' <- gets (length . csDiags)
          if diagnosticCount' == diagnosticCount
            then pure (Just result)
            else put saved >> pure Nothing
        Nothing -> put saved >> pure Nothing

    attempt left right = do
      let carrierGlobal = case domain of
            ArithmeticNatural -> Just prelNat
            ArithmeticInteger -> Just prelInteger
            ArithmeticTypeLevel -> Nothing
            ArithmeticProviderLaw -> Nothing
      case carrierGlobal of
        Nothing -> pure Nothing
        Just global -> do
          carrierEntry <- globalTerm global
          equalityEntry <- globalTerm prelEqType
          case (carrierEntry, equalityEntry) of
            ( Just (carrierTerm, carrierKind)
              , Just (equalityTerm, equalityType)
              ) -> do
                carrier <- evalIn ctx carrierTerm
                (proposition, _) <-
                  applyGeneratedCoreSpine
                    ctx
                    noSpan
                    equalityTerm
                    equalityType
                    [ (Impl, carrierTerm, carrierKind)
                    , (Expl, left, carrier)
                    , (Expl, right, carrier)
                    ]
                equalityGoal <- evalIn ctx proposition
                equalityReflectionFromCheckedBranchFacts
                  ctx
                  equalityGoal
                  carrier >>= \case
                    Nothing -> pure Nothing
                    Just evidence -> do
                      let depth = ctxLen ctx
                      checked <- zonkTermM depth proposition
                      replay <-
                        normalizeArithmeticCertificateGoal depth checked
                      arithmeticFormulaForDomain depth domain replay >>= \case
                        Nothing -> pure Nothing
                        Just _ -> do
                          evidence' <- zonkTermM depth evidence
                          pure
                            ( Just
                                ( ArithmeticAssumption
                                    True
                                    checked
                                    replay
                                    ( ArithmeticAssumptionProof
                                        checked
                                        evidence'
                                    )
                                )
                            )
            _ -> pure Nothing

-- | Recover only a candidate endpoint pair for equality reflection. A
-- projected member spelling is intentionally insufficient by itself; callers
-- must reconstruct and typecheck the exact prelude @Eq@ member through the
-- candidate dictionary before using the result.
selectedEqConditionEndpoints :: Term -> Maybe (Term, Term)
selectedEqConditionEndpoints condition = do
  let (headTerm, arguments) =
        spineOfTerm (stripIdentityWrappers condition)
      endpoints = last2 [argument | (Expl, argument) <- arguments]
  case stripIdentityWrappers headTerm of
    CProjM _ _ member
      | member == "==" -> endpoints
    CProjAtM _ _ member _
      | member == "==" -> endpoints
    globalHead
      | termHeadGlob globalHead
          `elem`
            [ Just (gPrel "==")
            , Just (memberGlobal (gPrel "Eq") "==")
            ] ->
          endpoints
    _ -> Nothing

-- | Reify the polarity-safe arithmetic consequences of already-authenticated
-- certificate assumptions. Proof replay and principal assignment share this
-- exact projection so neither solver gains ambient facts unavailable to the
-- other.
arithmeticAssumptionFactsForDomain
  :: Int
  -> ArithmeticDomain
  -> [ArithmeticAssumption Term]
  -> CheckM [AFact]
arithmeticAssumptionFactsForDomain depth domain assumptions =
  fmap (concat . catMaybes) . forM assumptions $
    \(ArithmeticAssumption truth _ replayProposition _) ->
      arithmeticFormulaForDomain depth domain replayProposition >>= \case
        Nothing -> pure Nothing
        Just formula ->
          pure (formulaAssumptionFacts truth formula)

-- | Preserve complete authenticated assumption formulas for the portable
-- Boolean arithmetic solver. The atomic projection above remains appropriate
-- for principal assignment, but implication may require case analysis over a
-- true disjunction or false conjunction.
arithmeticAssumptionFormulasForDomain
  :: Int
  -> ArithmeticDomain
  -> [ArithmeticAssumption Term]
  -> CheckM [(Bool, AFormula)]
arithmeticAssumptionFormulasForDomain depth domain assumptions =
  fmap catMaybes . forM assumptions $
    \(ArithmeticAssumption truth _ replayProposition _) ->
      arithmeticFormulaForDomain depth domain replayProposition >>= \case
        Nothing -> pure Nothing
        Just formula -> pure (Just (truth, formula))

booleanFactProposition :: Ctx -> Term -> CheckM Term
booleanFactProposition ctx condition = do
  boolEntry <- globalTerm prelBool
  equalityEntry <- globalTerm prelEqType
  case (boolEntry, equalityEntry) of
    (Just (boolTerm, boolKind), Just (equalityTerm, equalityType)) -> do
      boolType <- evalIn ctx boolTerm
      truth <- generatedCtorAtM ctx boolType prelTrue
      (proposition, _) <-
        applyGeneratedCoreSpine
          ctx
          noSpan
          equalityTerm
          equalityType
          [ (Impl, boolTerm, boolKind)
          , (Expl, condition, boolType)
          , (Expl, truth, boolType)
          ]
      zonkTermM (ctxLen ctx) proposition
    _ -> do
      errAt noSpan "E_INTERNAL_PRELUDE_INTERFACE" Nothing
        "compiler-generated boolean proposition requires Bool and equality interfaces"
      fst <$> anyHole ctx

arithmeticFactForDomain
  :: Int
  -> ArithmeticDomain
  -> Term
  -> CheckM (Maybe AFact)
arithmeticFactForDomain depth domain term =
  case spineOfTerm (stripIdentityWrappers term) of
    (headTerm, arguments)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelEqType -> do
          let implicit = [argument | (Impl, argument) <- arguments]
              explicit = [argument | (Expl, argument) <- arguments]
          case (listToMaybe implicit, last2 explicit) of
            (Just carrier, Just (left, right))
              | arithmeticCarrierForDomain domain carrier -> do
                  leftExpression <- selectedArithmeticExpression domain depth left
                  rightExpression <- selectedArithmeticExpression domain depth right
                  pure (AFact ACmpEq <$> leftExpression <*> rightExpression)
              | isBoolType carrier ->
                  case (stripIdentityWrappers left, stripIdentityWrappers right) of
                    (predicate, truth) | isTrueTerm truth ->
                      selectedArithmeticPredicateFactForDomain domain depth predicate
                    (truth, predicate) | isTrueTerm truth ->
                      selectedArithmeticPredicateFactForDomain domain depth predicate
                    _ -> pure Nothing
            _ -> pure Nothing
    _ -> pure Nothing
  where
    isTrueTerm = \case
      CCtor constructor _ [] -> constructor == prelTrue
      CCtorI constructor _ _ [] -> constructor == prelTrue
      _ -> False
    isBoolType candidate =
      termHeadGlob (stripIdentityWrappers candidate) == Just prelBool

-- | Reify the required quantifier-free Boolean arithmetic fragment while
-- preserving the authenticated atom decoder above. Connectives are accepted
-- only by resolved prelude identity or by their checked short-circuit Core
-- shape.
arithmeticFormulaForDomain
  :: Int
  -> ArithmeticDomain
  -> Term
  -> CheckM (Maybe AFormula)
arithmeticFormulaForDomain depth domain proposition =
  arithmeticFactForDomain depth domain proposition >>= \case
    Just fact -> pure (Just (AAtom fact))
    Nothing ->
      case booleanLiteralEqualityPayload proposition of
        Nothing -> pure Nothing
        Just (wanted, condition) -> do
          formula <- arithmeticBooleanFormula depth domain condition
          pure (if wanted then formula else ANot <$> formula)

arithmeticBooleanFormula
  :: Int
  -> ArithmeticDomain
  -> Term
  -> CheckM (Maybe AFormula)
arithmeticBooleanFormula depth domain term =
  case simplifyDecisionTerm term of
    CThunkE body _ ->
      arithmeticBooleanFormula depth domain body
    CForceE (CThunkE body _) _ ->
      arithmeticBooleanFormula depth domain body
    CCtor constructor _ []
      | constructor == prelTrue -> pure (Just (ATruth True))
      | constructor == prelFalse -> pure (Just (ATruth False))
    CCtorI constructor _ _ []
      | constructor == prelTrue -> pure (Just (ATruth True))
      | constructor == prelFalse -> pure (Just (ATruth False))
    CIf condition thenTerm elseTerm
      | isTrueTerm thenTerm
      , isFalseTerm elseTerm ->
          arithmeticBooleanFormula depth domain condition
      | isFalseTerm thenTerm
      , isTrueTerm elseTerm ->
          fmap ANot <$> arithmeticBooleanFormula depth domain condition
      | isFalseTerm elseTerm ->
          liftA2 (liftA2 AAnd)
            (arithmeticBooleanFormula depth domain condition)
            (arithmeticBooleanFormula depth domain thenTerm)
      | isTrueTerm thenTerm ->
          liftA2 (liftA2 AOr)
            (arithmeticBooleanFormula depth domain condition)
            (arithmeticBooleanFormula depth domain elseTerm)
    simplified -> do
      let (headTerm, arguments) =
            spineOfTerm (stripIdentityWrappers simplified)
          explicit = [argument | (Expl, argument) <- arguments]
          binary constructor =
            case last2 explicit of
              Just (lhs, rhs) ->
                liftA2 (liftA2 constructor)
                  (arithmeticBooleanFormula depth domain lhs)
                  (arithmeticBooleanFormula depth domain rhs)
              Nothing -> pure Nothing
      case termHeadGlob (stripIdentityWrappers headTerm) of
        Just operation
          | operation == prelAnd -> binary AAnd
          | operation == prelOr -> binary AOr
          | operation == prelNot ->
              case reverse explicit of
                argument : _ ->
                  fmap ANot <$> arithmeticBooleanFormula depth domain argument
                _ -> pure Nothing
        _ ->
          if domain == ArithmeticNatural
            then
              selectedNatRangeMembershipFacts depth simplified >>= \case
                Just facts -> pure (formulaFromFacts facts)
                Nothing -> atom simplified
            else atom simplified
  where
    atom candidate =
      fmap AAtom
        <$> selectedArithmeticPredicateFactForDomain domain depth candidate

    formulaFromFacts = \case
      [] -> Just (ATruth True)
      fact : rest ->
        Just (foldl' AAnd (AAtom fact) (map AAtom rest))

    isTrueTerm = \case
      CCtor constructor _ [] -> constructor == prelTrue
      CCtorI constructor _ _ [] -> constructor == prelTrue
      _ -> False

    isFalseTerm = \case
      CCtor constructor _ [] -> constructor == prelFalse
      CCtorI constructor _ _ [] -> constructor == prelFalse
      _ -> False

arithmeticCarrierForDomain :: ArithmeticDomain -> Term -> Bool
arithmeticCarrierForDomain domain carrier =
  case (domain, termHeadGlob (stripIdentityWrappers carrier)) of
    (ArithmeticNatural, Just global) -> global == prelNat
    (ArithmeticInteger, Just global) ->
      global == prelInteger || global == prelInt
    (ArithmeticTypeLevel, _) -> False
    _ -> False

selectedArithmeticExpression
  :: ArithmeticDomain
  -> Int
  -> Term
  -> CheckM (Maybe AExpr)
selectedArithmeticExpression domain depth = go (24 :: Int)
  where
    go fuel term
      | fuel <= 0 = pure Nothing
      | otherwise =
          direct term >>= \case
            Just expression -> pure (Just expression)
            Nothing ->
              case stripIdentityWrappers term of
                CIf condition thenTerm elseTerm -> do
                  conditionFormula <-
                    arithmeticBooleanFormula depth domain condition
                  thenExpression <- go (fuel - 1) thenTerm
                  elseExpression <- go (fuel - 1) elseTerm
                  pure
                    ( AIf
                        <$> conditionFormula
                        <*> thenExpression
                        <*> elseExpression
                    )
                _ -> do
                  reduced <- transparentProofReduce depth 48 term
                  if simplifyDecisionTerm reduced == simplifyDecisionTerm term
                    then pure Nothing
                    else go (fuel - 1) reduced

    direct term = do
      instances <- gets csInstances
      let canonical =
            canonicalizeStandardArithmeticOperations instances term
      case domain of
        ArithmeticNatural ->
          selectedNatArithmeticExpressionDirect depth canonical
        ArithmeticInteger -> pure (arithOf depth canonical)
        ArithmeticTypeLevel -> pure Nothing
        ArithmeticProviderLaw -> pure Nothing

arithmeticFactVariables :: AFact -> Set Int
arithmeticFactVariables (AFact _ lhs rhs) =
  arithmeticExpressionVariables lhs `Set.union` arithmeticExpressionVariables rhs

arithmeticFormulaVariables :: AFormula -> Set Int
arithmeticFormulaVariables = \case
  ATruth _ -> Set.empty
  AAtom fact -> arithmeticFactVariables fact
  AAnd lhs rhs -> binary lhs rhs
  AOr lhs rhs -> binary lhs rhs
  ANot formula -> arithmeticFormulaVariables formula
  where
    binary lhs rhs =
      arithmeticFormulaVariables lhs `Set.union` arithmeticFormulaVariables rhs

arithmeticExpressionVariables :: AExpr -> Set Int
arithmeticExpressionVariables = \case
  AConst _ -> Set.empty
  AVar variable -> Set.singleton variable
  AScale _ expression -> arithmeticExpressionVariables expression
  AAdd lhs rhs -> binary lhs rhs
  ASub lhs rhs -> binary lhs rhs
  AMul lhs rhs -> binary lhs rhs
  ADiv lhs rhs -> binary lhs rhs
  AMod lhs rhs -> binary lhs rhs
  ANeg expression -> arithmeticExpressionVariables expression
  AMax lhs rhs -> binary lhs rhs
  AMin lhs rhs -> binary lhs rhs
  AIf condition thenExpression elseExpression ->
    arithmeticFormulaVariables condition
      `Set.union` arithmeticExpressionVariables thenExpression
      `Set.union` arithmeticExpressionVariables elseExpression
  where
    binary lhs rhs =
      arithmeticExpressionVariables lhs `Set.union` arithmeticExpressionVariables rhs

-- | Decide equalities between propositions produced by the standard
-- @Ord TypeLevel@ comparisons. Open comparisons remain neutral in ordinary
-- evaluation, but their truth and the canonical equivalence
-- @x < y <=> succ x <= y@ are universe-solver judgments under the current
-- lexical assumptions. Authentication is semantic on every operation and
-- selected dictionary; user comparisons and user evidence cannot enter this
-- proof source.
typeLevelLiteralRelationProof :: Ctx -> Value -> Value -> CheckM (Maybe Bool)
typeLevelLiteralRelationProof ctx lhs rhs = do
  lhsPredicate <- predicate lhs
  rhsPredicate <- predicate rhs
  assumptions <- effectiveLevelAssumptions ctx
  let predicateMetas = \case
        Just (Right (lower, upper)) -> levelMetas lower ++ levelMetas upper
        _ -> []
      requested = Set.fromList (predicateMetas lhsPredicate ++ predicateMetas rhsPredicate)
  assignments <- currentPrincipalLevelAssignmentsFor requested
  let result = comparePredicates assumptions assignments lhsPredicate rhsPredicate
  pure result
  where
    predicate value =
      case boolValue value of
        Just literal -> pure (Just (Left literal))
        Nothing -> do
          relationTm <- do
            ec <- ec_
            zonkTermM (ctxLen ctx) (quote ec (ctxLen ctx) value)
          typeLevelRelationTerms relationTm >>= \case
            Nothing -> pure Nothing
            Just (op, loTm, hiTm) -> do
              finiteBelowOmega <-
                if op == LevelOperatorLt
                  then isFiniteTypeLevelTerm loTm >>= \finite ->
                    if not finite
                      then pure False
                      else (== Just LOmega) <$> coreTypeLevel ctx hiTm
                  else pure False
              if finiteBelowOmega
                then pure (Just (Left True))
                else do
                  lo <- coreTypeLevel ctx loTm
                  hi <- coreTypeLevel ctx hiTm
                  pure $ do
                    lo' <- lo
                    hi' <- hi
                    queryLhs <- case op of
                      LevelOperatorLt -> Just (levelSucc lo')
                      LevelOperatorLe -> Just lo'
                      _ -> Nothing
                    Just (Right (normalizeLevel queryLhs, normalizeLevel hi'))

    isFiniteTypeLevelTerm term = do
      let (headTerm, arguments) = spineOfTerm (stripIdentityWrappers term)
          explicitCount = length [() | (Expl, _) <- arguments]
      case stripIdentityWrappers headTerm of
        CGlob operation
          | operation == prelTypeLevelFromInteger -> pure (explicitCount == 1)
          | otherwise ->
              authenticatedStandardLevelOperator operation arguments >>= \case
                Just LevelOperatorFromInteger -> pure (explicitCount == 1)
                _ ->
                  resolveLevelOperatorAliasIdentity Set.empty operation >>= \identity ->
                    pure (identity == Just LevelOperatorFromInteger && explicitCount == 1)
        _ -> pure False

    comparePredicates assumptions assignments lhsPredicate rhsPredicate = do
      lhs' <- lhsPredicate
      rhs' <- rhsPredicate
      case (lhs', rhs') of
        (Left lhsTruth, Left rhsTruth) -> Just (lhsTruth == rhsTruth)
        (Right lhsRelation, Right rhsRelation)
          | lhsRelation == rhsRelation -> Just True
        _ -> do
          lhsTruth <- predicateTruth assumptions assignments lhs'
          rhsTruth <- predicateTruth assumptions assignments rhs'
          Just (lhsTruth == rhsTruth)

    predicateTruth _ _ (Left truth) = Just truth
    predicateTruth assumptions assignments (Right (lo, hi)) = do
      solution <- assignments
      let lo' = normalizeLevel (substituteLevelMetas solution lo)
          hi' = normalizeLevel (substituteLevelMetas solution hi)
      case proveLevelLeq assumptions lo' hi' of
        Proved -> Just True
        Disproved -> Just False
        Blocked _ -> Nothing
        ContradictoryAssumptions -> Nothing
        IndeterminateResourceLimit -> Nothing

    boolValue = \case
      VCtor g [] | g == prelTrue -> Just True
      VCtor g [] | g == prelFalse -> Just False
      _ -> Nothing

    typeLevelRelationTerms relation =
      typeLevelRelationSpine relation >>= \case
        Nothing -> pure Nothing
        Just (op, arguments) ->
          pure $ case reverse [argument | (Expl, argument) <- arguments] of
            hi : lo : _ -> Just (op, lo, hi)
            _ -> Nothing

-- | Decide equality between ordinary TypeLevel values through the certified
-- solver bridge. Both endpoints must translate through authenticated standard
-- operation and evidence identities; user functions and same-spelling values
-- fall back to ordinary conversion. Open endpoints are equal only when the
-- active lexical assumptions prove both directions after principal
-- substitution.
typeLevelValueEqualityProof :: Ctx -> Value -> Value -> Value -> CheckM (Maybe Bool)
typeLevelValueEqualityProof ctx carrier lhs rhs = do
  typeLevelCarrier <- isTypeLevelValue carrier
  if not typeLevelCarrier
    then pure Nothing
    else typeLevelValuesEqualAt ctx (ctxLen ctx) lhs rhs

-- | Compare two values under an independently established @TypeLevel@
-- classifier. The values remain ordinary first-class Core terms; this query
-- translates only the authenticated standard level algebra (or stable level
-- atoms already present in Core) and asks the shared principal/entailment
-- solver. An arbitrary binder depth is required while conversion descends
-- beneath Pi binders represented by semantic rigids rather than a materialized
-- source 'Ctx'.
typeLevelValuesEqualAt :: Ctx -> Int -> Value -> Value -> CheckM (Maybe Bool)
typeLevelValuesEqualAt ctx depth lhs rhs = do
  ec <- ec_
  lhsTerm <- zonkTermM depth (quote ec depth lhs)
  rhsTerm <- zonkTermM depth (quote ec depth rhs)
  lhsLevel <- coreTypeLevelAt depth ctx lhsTerm
  rhsLevel <- coreTypeLevelAt depth ctx rhsTerm
  case (lhsLevel, rhsLevel) of
    (Just lhs0, Just rhs0) -> do
      mAssignments <-
        currentPrincipalLevelAssignmentsFor . Set.fromList $
          levelMetas lhs0 ++ levelMetas rhs0
      assumptions <- effectiveLevelAssumptions ctx
      pure $ do
        assignments <- mAssignments
        let lhs' = normalizeLevel (substituteLevelMetas assignments lhs0)
            rhs' = normalizeLevel (substituteLevelMetas assignments rhs0)
        case (proveLevelLeq assumptions lhs' rhs', proveLevelLeq assumptions rhs' lhs') of
          (Proved, Proved) -> Just True
          (Disproved, _) -> Just False
          (_, Disproved) -> Just False
          _ -> Nothing
    _ -> pure Nothing

-- | Extract only an authenticated standard TypeLevel ordering application.
-- The exact eta-alias table is populated by typed elaboration; no rendered
-- identifier or field-name recognition participates here.
typeLevelRelationOf :: Ctx -> Term -> CheckM (Maybe (LevelOperatorIdentity, Level, Level))
typeLevelRelationOf ctx relation = do
  recognized <- typeLevelRelationSpine relation
  case recognized of
    Nothing -> pure Nothing
    Just (op, args) ->
      case lastTwo [arg | (Expl, arg) <- args] of
        Nothing -> pure Nothing
        Just (loTm, hiTm) -> do
          lo <- relationEndpoint loTm
          hi <- relationEndpoint hiTm
          pure $ case (lo, hi) of
            (Just lo', Just hi') -> Just (op, normalizeLevel lo', normalizeLevel hi')
            _ -> Nothing
  where
    relationEndpoint term =
      coreTypeLevel ctx term >>= \case
        Just level -> pure (Just level)
        Nothing -> do
          (_, identity) <- levelIdentityOfCheckedTerm ctx term
          pure (either (const Nothing) Just identity)

    lastTwo xs = case reverse xs of
      hi : lo : _ -> Just (lo, hi)
      _ -> Nothing

-- | Authenticate the operation/carrier/dictionary portion of a TypeLevel
-- comparison while retaining its operand spine for the caller. Operand
-- normalization is a separate concern: source level binders use the ordinary
-- TypeLevel bridge, while proof search consumes already-finalized Core.
typeLevelRelationSpine :: Term -> CheckM (Maybe (LevelOperatorIdentity, [(Icit, Term)]))
typeLevelRelationSpine relation = do
  aliases <- gets csLevelOperatorAliases
  case spineOfTerm (stripIdentityWrappers relation) of
    (headTerm, args)
      | Just opG <- termHeadGlob (stripIdentityWrappers headTerm)
      , Just op <- comparisonIdentity aliases opG
      , let implicitArgs = [arg | (Impl, arg) <- args]
      , typeArg : dictArg : _ <- implicitArgs
      , termHeadGlob (stripIdentityWrappers typeArg) == Just prelTypeLevel -> do
          standard <- standardTypeLevelDictionary prelOrd dictArg
          pure $ if standard then Just (op, args) else Nothing
    _ -> pure Nothing
  where
    comparisonIdentity aliases g
      | g == gPrel "<" = Just LevelOperatorLt
      | g == gPrel "<=" = Just LevelOperatorLe
      | otherwise = case Map.lookup g aliases of
          Just LevelOperatorLt -> Just LevelOperatorLt
          Just LevelOperatorLe -> Just LevelOperatorLe
          _ -> Nothing

-- | Authenticate a selected compiler-owned TypeLevel dictionary. This is the
-- common trust boundary for both solver-level operations and erased ordering
-- proofs: neither rendered member names nor a matching result type suffice.
standardTypeLevelDictionary :: GName -> Term -> CheckM Bool
standardTypeLevelDictionary trait dictionary = do
  instances <- gets csInstances
  pure $ case termHeadGlob (stripIdentityWrappers dictionary) of
    Just dictG ->
      dictG `gnameInModule` modTypeLevel
        && any
          ( \entry ->
              ieDict entry == dictG
                && ieTrait entry == trait
                && null (iePremises entry)
                && case ieHead entry of
                     [headType] -> termHeadGlob (stripIdentityWrappers headType) == Just prelTypeLevel
                     _ -> False
          )
          instances
    Nothing -> False

-- | Wrappers that are transparent to resolved semantic identity. Universe
-- lifts constrain classification but do not change the selected global head.
stripIdentityWrappers :: Term -> Term
stripIdentityWrappers = \case
  CUniverseLift _ _ _ inner -> stripIdentityWrappers inner
  CSchemaLift _ _ _ _ _ _ _ _ inner -> stripIdentityWrappers inner
  term -> term

-- | Translate the canonical compiler-owned TypeLevel value language from
-- finalized Core to the solver language.  This intentionally recognizes no
-- transparent user function: such aliases must first have been certified as
-- exact operations and appear only at the comparison head above.
coreTypeLevel :: Ctx -> Term -> CheckM (Maybe Level)
coreTypeLevel ctx = coreTypeLevelAt (ctxLen ctx) ctx

coreTypeLevelAt :: Int -> Ctx -> Term -> CheckM (Maybe Level)
coreTypeLevelAt depth ctx = go . stripIdentityWrappers
  where
    go = \case
      CLevel level -> pure (Just level)
      CVar index
        | let level = depth - 1 - index
        , level >= 0 -> pure (Just (LVar level))
      CMeta meta -> pure (Just (LMeta meta))
      CGlob g
        | g == prelTypeLevelZero || g == GName primModule "__typeLevelZero" -> pure (Just LZero)
        | g == prelTypeLevelOne -> pure (Just (finiteLevel (1 :: Integer)))
        | g == prelTypeLevelOmega || g == prelTypeLevelOmegaAlias || g == GName primModule "__typeLevelOmega" -> pure (Just LOmega)
      CGlobal g _
        | g == prelTypeLevelZero || g == GName primModule "__typeLevelZero" -> pure (Just LZero)
        | g == prelTypeLevelOne -> pure (Just (finiteLevel (1 :: Integer)))
        | g == prelTypeLevelOmega || g == prelTypeLevelOmegaAlias || g == GName primModule "__typeLevelOmega" -> pure (Just LOmega)
      CProjM _ (CGlob g) field
        | g == thisG
        , Just fieldId <- Map.lookup field (ctxLevelFieldIds ctx) ->
            pure (Just (LField fieldId field))
      CProjAtM _ (CGlob g) field _
        | g == thisG
        , Just fieldId <- Map.lookup field (ctxLevelFieldIds ctx) ->
            pure (Just (LField fieldId field))
      CProj (CGlob g) field
        | g == thisG
        , Just fieldId <- Map.lookup field (ctxLevelFieldIds ctx) ->
            pure (Just (LField fieldId field))
      term | Just level <- localProjectionLevelAt depth ctx term -> pure (Just level)
      term -> do
        let (headTerm, args) = spineOfTerm term
            explicit = [argument | (Expl, argument) <- args]
        operator <- typeLevelValueOperator headTerm args
        case (operator, explicit) of
          (Just LevelOperatorZero, []) -> pure (Just LZero)
          (Just LevelOperatorOne, []) -> pure (Just (finiteLevel (1 :: Integer)))
          (Just LevelOperatorFromInteger, [CLit (LitInt n)])
            | n >= 0 -> pure (Just (finiteLevel n))
          (Just LevelOperatorSucc, [argument]) -> fmap LSucc <$> go argument
          (Just LevelOperatorAdd, [lhs, rhs]) -> liftA2 (liftA2 LAdd) (go lhs) (go rhs)
          (Just LevelOperatorMax, [lhs, rhs]) -> liftA2 (liftA2 LMax) (go lhs) (go rhs)
          _ -> pure Nothing

    typeLevelValueOperator headTerm args = case stripIdentityWrappers headTerm of
      CGlob g
        | g == GName primModule "__typeLevelZero" || g == prelTypeLevelZero -> pure (Just LevelOperatorZero)
        | g == GName primModule "__typeLevelFinite" || g == GName primModule "__typeLevelFromNat" -> pure (Just LevelOperatorFromInteger)
        | g == prelTypeLevelFromInteger -> pure (Just LevelOperatorFromInteger)
        | g == GName primModule "__typeLevelSucc" || g == prelTypeLevelSucc -> pure (Just LevelOperatorSucc)
        | g == GName primModule "__typeLevelAdd" || g == prelTypeLevelAdd -> pure (Just LevelOperatorAdd)
        | g == GName primModule "__typeLevelMax" || g == prelTypeLevelMax -> pure (Just LevelOperatorMax)
        | otherwise -> authenticatedGlobal g args
      CGlobal g _
        | g == GName primModule "__typeLevelZero" || g == prelTypeLevelZero -> pure (Just LevelOperatorZero)
        | g == GName primModule "__typeLevelFinite" || g == GName primModule "__typeLevelFromNat" -> pure (Just LevelOperatorFromInteger)
        | g == prelTypeLevelFromInteger -> pure (Just LevelOperatorFromInteger)
        | g == GName primModule "__typeLevelSucc" || g == prelTypeLevelSucc -> pure (Just LevelOperatorSucc)
        | g == GName primModule "__typeLevelAdd" || g == prelTypeLevelAdd -> pure (Just LevelOperatorAdd)
        | g == GName primModule "__typeLevelMax" || g == prelTypeLevelMax -> pure (Just LevelOperatorMax)
        | otherwise -> authenticatedGlobal g args
      CProjM _ dictionary member -> authenticatedProjection dictionary member
      CProj dictionary member -> authenticatedProjection dictionary member
      _ -> pure Nothing

    authenticatedGlobal g args =
      case Map.lookup g globalOperators of
        Nothing -> resolveLevelOperatorAliasIdentity Set.empty g
        Just _ -> authenticatedStandardLevelOperator g args

    authenticatedProjection dictionary member =
      case Map.lookup member projectionOperators of
        Nothing -> pure Nothing
        Just (identity, trait) -> do
          standard <- standardTypeLevelDictionary trait dictionary
          pure (if standard then Just identity else Nothing)

    globalOperators = Map.fromList
      [ (gPrel "zero", (LevelOperatorZero, gPrel "Zero"))
      , (gPrel "one", (LevelOperatorOne, gPrel "One"))
      , (gPrel "fromInteger", (LevelOperatorFromInteger, gPrel "FromInteger"))
      , (prelSucc, (LevelOperatorSucc, prelSuccessor))
      , (gPrel "+", (LevelOperatorAdd, gPrel "Add"))
      , (gPrel "add", (LevelOperatorAdd, gPrel "Add"))
      , (prelMaxOp, (LevelOperatorMax, prelMax))
      ]

    projectionOperators = Map.fromList
      [ ("zero", (LevelOperatorZero, gPrel "Zero"))
      , ("one", (LevelOperatorOne, gPrel "One"))
      , ("fromInteger", (LevelOperatorFromInteger, gPrel "FromInteger"))
      , ("succ", (LevelOperatorSucc, prelSuccessor))
      , ("add", (LevelOperatorAdd, gPrel "Add"))
      , ("max", (LevelOperatorMax, prelMax))
      ]

-- | Preserve a TypeLevel-valued projection as a dependency on the resolved
-- local binder identity and field path. The caller has already checked the
-- complete term against the canonical TypeLevel carrier, so this recognizes
-- structural Core identity only; field spelling alone is never authority.
localProjectionLevel :: Ctx -> Term -> Maybe Level
localProjectionLevel ctx = localProjectionLevelAt (ctxLen ctx) ctx

localProjectionLevelAt :: Int -> Ctx -> Term -> Maybe Level
localProjectionLevelAt depth _ctx = go [] . stripIdentityWrappers
  where
    go path = \case
      CProjM _ receiver field -> go (field : path) receiver
      CProjAtM _ receiver field _ -> go (field : path) receiver
      CVar index
        | let root = depth - 1 - index
        , root >= 0 -> Just (LProjection root path)
      _ -> Nothing

localProjectionValueLevel :: Value -> Maybe Level
localProjectionValueLevel = go []
  where
    go path = \case
      VProjN _ receiver field -> go (field : path) receiver
      VRigid root [] | not (null path) -> Just (LProjection root path)
      _ -> Nothing

-- | Query the principal solution of the pending constraint set without
-- installing it.  Proof search must be order-independent, so it may observe
-- the joined solution but cannot commit a provisional lower bound before the
-- owning declaration/module boundary.
currentPrincipalLevelAssignments :: CheckM (Maybe (Map LevelMeta Level))
currentPrincipalLevelAssignments = do
  st <- get
  let prior = csLevelAssignments st
      constraints = zonkedPendingLevelConstraints prior st
  pure $ case solveLevelConstraints constraints of
    Left _ -> Nothing
    Right solution -> Just (Map.union (lsAssignments solution) prior)

-- | Query a principal assignment only for the connected component of the
-- requested metas. Proof search and postponed-goal classification must not be
-- made order-dependent by an unrelated declaration's pending or already
-- diagnosed universe constraint. Constraint solving itself couples
-- metavariables only through identities occurring in the same judgment, so
-- this transitive slice is exact rather than heuristic. An empty target set
-- requests the complete module snapshot for legacy callers.
currentPrincipalLevelAssignmentsFor
  :: Set LevelMeta
  -> CheckM (Maybe (Map LevelMeta Level))
currentPrincipalLevelAssignmentsFor requested = do
  st <- get
  let prior = csLevelAssignments st
      constraints0 = zonkedPendingLevelConstraints prior st
  pure (principalLevelAssignmentsWithin prior requested constraints0)

-- | Infer selected metas from an explicit constraint region. This is the
-- reusable transaction-local form of 'currentPrincipalLevelAssignmentsFor':
-- ambient metas may occur as rigid parameters in the resulting assignment,
-- but constraints outside the supplied region cannot influence it.
principalLevelAssignmentsWithin
  :: Map LevelMeta Level
  -> Set LevelMeta
  -> [LevelConstraint]
  -> Maybe (Map LevelMeta Level)
principalLevelAssignmentsWithin prior requested constraints0 =
  let
      targets =
        Set.unions
          [ Set.fromList (levelMetas (substituteLevelMetas prior (LMeta meta)))
          | meta <- Set.toList requested
          ]
      constraints
        | Set.null targets = []
        | otherwise = relevantConstraintClosure targets constraints0
   in if Set.null targets
        then Just prior
        else case inferPrincipalLevelsFor targets constraints of
          SolvedPrincipal solution -> Just (Map.union solution prior)
          Unsatisfiable -> Nothing
          BlockedByUnselectedMetas -> Nothing
          NoPointwiseLeastSolution _ -> Nothing
          OutsidePortableInferenceFragment -> Nothing
  where
    relevantConstraintClosure seeds constraints =
      let go known =
            let selected =
                  [ constraint
                  | constraint <- constraints
                  , not . Set.null $
                      Set.intersection known (constraintMetas constraint)
                  ]
                known' =
                  Set.unions (known : map constraintMetas selected)
             in if known' == known then selected else go known'
       in go seeds

    constraintMetas constraint =
      Set.fromList $
        levelMetas (lcLhs constraint)
          ++ levelMetas (lcRhs constraint)
          ++ concatMap
               (\(lower, upper) -> levelMetas lower ++ levelMetas upper)
               (assumptionsList (lcAssumptions constraint))

-- | Close one compiler-created universe occurrence against the exact
-- connected constraint component established while checking it. The caller
-- decides whether to install the returned assignments; this keeps the same
-- portable principalization authority reusable by transactional proof
-- searches and by successful instance trials.
principalizeLevelOccurrence
  :: Int
  -> CheckState
  -> Set LevelMeta
  -> Term
  -> CheckM (Maybe (Map LevelMeta Level, Term))
principalizeLevelOccurrence depth baseline selected candidate = do
  zonked <- zonkTermM depth candidate
  if Set.null selected
    then pure (Just (Map.empty, zonked))
    else do
      current <- get
      let baselineIdentities =
            Set.fromList (map lcIdentity (csLevelConstraints baseline))
          localConstraints =
            [ constraint
            | constraint <- zonkedPendingLevelConstraints (csLevelAssignments current) current
            , lcIdentity constraint `Set.notMember` baselineIdentities
            ]
          principal =
            principalLevelAssignmentsWithin
              (csLevelAssignments current)
              selected
              localConstraints
      case principal of
        Nothing -> pure Nothing
        Just assignments -> do
          let localAssignments = Map.restrictKeys assignments selected
              specialized =
                zonkTermWith
                  (\_ _ -> Nothing)
                  (substituteLevelMetas localAssignments)
                  depth
                  zonked
          closed <- zonkTermM depth specialized
          pure
            ( if
                Set.null
                  ( Set.intersection
                      selected
                      (Set.fromList (levelMetasOfTerm closed))
                  )
                then Just (localAssignments, closed)
                else Nothing
            )

zonkedPendingLevelConstraints
  :: Map LevelMeta Level
  -> CheckState
  -> [LevelConstraint]
zonkedPendingLevelConstraints prior st =
  [ substituteLevelConstraintMetas prior constraint
  | constraint <- reverse (csLevelConstraints st)
  ]

-- | Canonical observation form for a checked branch condition.
--
-- Match annotations are explicitly observe-only in Core. Constructor-pattern
-- universe spines are required checkpoint evidence, but once a match has been
-- checked they cannot affect which constructor branch is selected. Fresh
-- elaboration instances of either must therefore not split one semantic
-- branch fact into distinct identities. Constructor globals, payloads,
-- binders, guards, and term arguments remain exact.
branchDecisionObservationTerm :: Term -> Term
branchDecisionObservationTerm =
  eraseObserveOnlyAnnotations
    . mapPatternConstructorUniverses (\_ _ -> [])
    . simplifyDecisionTerm

branchFactKey :: Term -> Text
branchFactKey =
  renderStructuralTermKey . branchDecisionObservationTerm

-- | Put a checked branch condition into the local-definition normal form that
-- its enclosing context denotes.  This unfolds immutable local lets through
-- 'ctxEnv' but deliberately excludes branch/pattern facts: those facts are the
-- authority being recorded, not additional equations available while choosing
-- its identity.  Global applications and selected dictionaries remain headed
-- by their resolved symbols.
normalizeBranchConditionTerm :: Ctx -> Term -> CheckM Term
normalizeBranchConditionTerm ctx term = do
  state <- get
  let ec = (ecOf state) {ecFacts = Map.empty}
      normalized = quote ec (ctxLen ctx) (eval ec (ctxEnv ctx) term)
  zonkTermM (ctxLen ctx) normalized

-- | Reconstruct only already-neutral values as Core syntax.  This deliberately
-- does not call 'force' or 'quote': boolean branch facts may mention recursive
-- predicates, and using them as assumptions must not evaluate those predicates.
neutralValueTerm :: Int -> Value -> Maybe Term
neutralValueTerm lvl = \case
  VRigid l sp -> neutralSpine (CVar (lvl - 1 - l)) sp
  VFlex m sp -> neutralSpine (CMeta m) sp
  VGlobI g universes sp -> neutralSpine (CGlobI g universes) sp
  VSort level -> Just (CSort level)
  VLevel level -> Just (CLevel level)
  VUniverseLift _ _ evidence inner ->
    universeLift evidence <$> neutralValueTerm lvl inner
  VLit lit -> Just (CLit lit)
  VCtorI g universes arguments ->
    CCtorI g universes Nothing
      <$> traverse
        (\argument ->
          ConstructorArg (cvaIcit argument) (cvaPayload argument) (cvaName argument)
            <$> neutralValueTerm lvl (cvaValue argument))
        arguments
  VPrim p args ->
    foldM
      (\acc a -> CApp Expl acc <$> neutralValueTerm lvl a)
      (CGlob (GName primModule p))
      args
  VAppN ic f a -> CApp ic <$> neutralValueTerm lvl f <*> neutralValueTerm lvl a
  VProjN mode e f -> CProjM mode <$> neutralValueTerm lvl e <*> pure f
  _ -> Nothing
  where
    neutralSpine hd =
      foldM
        (\acc (ic, a) -> CApp ic acc <$> neutralValueTerm lvl a)
        hd

cachedPropDecision
  :: Ctx
  -> Maybe Term
  -> Value
  -> CheckM Bool
  -> CheckM (Maybe Term)
cachedPropDecision ctx sourceGoal goal decide = do
  -- Conversion can consult 'csFacts' for dependent-match refinements.  Those
  -- facts contain Values with no stable structural key, so proposition caching
  -- is disabled while they are active.  Boolean branch facts are local control
  -- assumptions; building a cache key for a branch-refined proposition would
  -- have to inspect the goal under those assumptions, which can otherwise
  -- unfold recursive user predicates before their totality is known.
  canCache <- gets (\st -> Map.null (csFacts st) && null (csBoolFacts st))
  proved <- if not canCache
    then decide
    else do
      mKey <- propDecisionKey ctx goal
      case mKey of
        Nothing -> decide
        Just key -> do
          cached <- gets (Map.lookup key . csPropCache)
          case cached of
            Just ok -> pure ok
            Nothing -> do
              ok <- decide
              modify' $ \st ->
                st {csPropCache = boundedInsert maxPropCacheEntries key ok (csPropCache st)}
              pure ok
  if proved
    then Just <$> generatedReflForGoalAtM ctx sourceGoal goal
    else pure Nothing

propDecisionKey :: Ctx -> Value -> CheckM (Maybe PropCacheKey)
propDecisionKey ctx goal = do
  let d = ctxLen ctx
  case neutralValueTerm d goal of
    Nothing -> pure Nothing
    Just goalTm -> do
      facts <- boolFactsDecisionKey d
      st <- get
      if not (null (unsolvedMetasOf st goalTm))
          || not (null (levelMetasOfTerm goalTm))
          || not (termCacheUniverseScoped st goalTm)
          || any (not . null . unsolvedMetasOf st . fst) facts
          || any (not . null . levelMetasOfTerm . fst) facts
          || any (not . termCacheUniverseScoped st . fst) facts
        then pure Nothing
        else do
          stableCtx <- ctxTypesMetaStable ctx
          if not stableCtx
            then pure Nothing
            else do
              natKey <- natLevelsDecisionKey ctx
              epoch <- gets csNormEpoch
              let factsKey = T.intercalate "\x1e" [prefix <> renderStructuralTermKey tm | (tm, prefix) <- facts]
              owner <- gets csActiveUniverseDefinition
              pure
                (Just (PropCacheKey epoch owner d (renderStructuralTermKey goalTm) factsKey natKey))

boolFactsDecisionKey :: Int -> CheckM [(Term, Text)]
boolFactsDecisionKey d = do
  facts <- scopedBoolFactsAt d =<< gets csBoolFacts
  let one (tm, truth) =
        (simplifyDecisionTerm tm, if truth then "T:" else "F:")
  pure (map one facts)

ctxTypesMetaStable :: Ctx -> CheckM Bool
ctxTypesMetaStable ctx = do
  ec <- ec_
  st <- get
  let d = ctxLen ctx
      tyStable e =
        let term = quote ec d (ceType e)
         in null (unsolvedMetasOf st term)
              && null (levelMetasOfTerm term)
              && termCacheUniverseScoped st term
  pure (all tyStable (ctxEntries ctx))

natLevelsDecisionKey :: Ctx -> CheckM Text
natLevelsDecisionKey ctx = do
  natLvls <- ctxNatLevels ctx
  pure (T.pack (show (Set.toAscList natLvls)))

proveBoolValueFromBranchFacts :: Ctx -> Bool -> Value -> CheckM Bool
proveBoolValueFromBranchFacts ctx want v = do
  let d = ctxLen ctx
  case neutralValueTerm d v of
    Nothing -> pure False
    Just term -> proveBoolTermFromBranchFacts ctx want term

proveBoolTermFromBranchFacts :: Ctx -> Bool -> Term -> CheckM Bool
proveBoolTermFromBranchFacts ctx want term = do
  let depth = ctxLen ctx
  -- Resolve solved metavariables in the goal: a deferred proof obligation
  -- captures fresh evidence/argument metas that are only solved later.
  -- Zonking retains the original selected dictionary applications while
  -- exposing those solutions to the term-based decision procedures.
  normalized <- zonkTermM depth term
  boolFacts <- normalizeBoolFacts depth =<< gets csBoolFacts
  arithmeticFacts <- arithmeticBranchFacts ctx
  naturalLevels <- ctxNatLevels ctx
  proveBoolValue
    naturalLevels
    boolFacts
    arithmeticFacts
    depth
    want
    normalized

arithmeticBranchFacts :: Ctx -> CheckM [AFact]
arithmeticBranchFacts ctx = do
  let d = ctxLen ctx
  natLvls <- ctxNatLevels ctx
  bfs <- normalizeBoolFacts d =<< gets csBoolFacts
  fmap concat $ forM bfs $ \(tm, truth) -> do
    rangeFacts <-
      if truth
        then selectedNatRangeMembershipFacts d tm
        else pure Nothing
    case rangeFacts of
      Just facts -> pure facts
      Nothing -> do
        mf <-
          selectedStandardOrderFact d tm >>= \case
            Just (_, fact) -> pure (Just fact)
            Nothing -> selectedArithmeticPredicateFact d tm
        pure $ case mf >>= if truth then Just else negateFactForNat natLvls of
          Just fact -> [fact]
          Nothing -> []

-- The complement of equality is not generally a single arithmetic fact.
-- For a variable whose type is known to be Nat, however, @n /= 0@ entails
-- @0 < n@. Keep this refinement local to authenticated Nat binders; applying
-- it to Int or to an arbitrary arithmetic expression would be unsound.
negateFactForNat :: Set Int -> AFact -> Maybe AFact
negateFactForNat natLvls = \case
  AFact ACmpEq (AVar lvl) (AConst 0)
    | lvl `Set.member` natLvls -> Just (AFact ACmpLt (AConst 0) (AVar lvl))
  AFact ACmpEq (AConst 0) (AVar lvl)
    | lvl `Set.member` natLvls -> Just (AFact ACmpLt (AConst 0) (AVar lvl))
  fact -> negateFact fact

normalizeBoolFacts :: Int -> [ScopedBoolFact] -> CheckM [(Term, Bool)]
normalizeBoolFacts d facts = do
  zonked <- zonkedBoolFacts d facts
  concat <$> forM zonked (\(tm, truth) -> do
    mtm <- transparentProofNormalize d tm
    let raw = simplifyDecisionTerm tm
        candidates = case mtm of
          Just norm | norm /= raw -> [(raw, truth), (norm, truth)]
          _ -> [(raw, truth)]
        decomposed = concatMap (uncurry (decomposeBoolFact 16)) candidates
    pure decomposed
    )

-- | Facts eligible to justify an ordinary branch-local @refl@. This path is
-- intentionally limited to the checked condition and the polarity-safe
-- consequences of its Boolean structure. Delta-normalized or arithmetic
-- consequences must use an explicit arithmetic certificate so KCore can
-- replay the derivation rather than accepting source-checker normalization as
-- conversion.
exactBoolFacts :: Int -> [ScopedBoolFact] -> CheckM [(Term, Bool)]
exactBoolFacts d facts =
  concatMap
    (\(term, truth) ->
       decomposeBoolFact 16 (simplifyDecisionTerm term) truth)
    <$> zonkedBoolFacts d facts

zonkedBoolFacts :: Int -> [ScopedBoolFact] -> CheckM [(Term, Bool)]
zonkedBoolFacts d facts = do
  rebased <- scopedBoolFactsAt d facts
  forM rebased $ \(term, truth) -> do
    -- Conditions are recorded before all selected evidence is necessarily
    -- settled. Zonking preserves the checked expression while making exact
    -- occurrences comparable at the later proof site.
    zonked <- zonkTermM d term
    pure (zonked, truth)

-- | Extract exactly the polarity-safe propositional consequences of the
-- standard boolean connectives (§16.4.2). A true conjunction proves both
-- conjuncts; a false disjunction refutes both disjuncts; negation flips
-- polarity. False conjunctions and true disjunctions remain atomic because
-- choosing one side would invent a fact. Resolved global identity, rather
-- than an operator spelling, is the authority for every decomposition.
decomposeBoolFact :: Int -> Term -> Bool -> [(Term, Bool)]
decomposeBoolFact fuel term truth
  | fuel <= 0 = [(term, truth)]
  | otherwise =
      case stripIdentityWrappers term of
        CThunkE body _ ->
          decomposeBoolFact (fuel - 1) body truth
        CForceE (CThunkE body _) _ ->
          decomposeBoolFact (fuel - 1) body truth
        CIf condition thenTerm elseTerm
          | truth
          , isFalseTerm elseTerm ->
              decomposeBoolFact (fuel - 1) condition True
                ++ decomposeBoolFact (fuel - 1) thenTerm True
          | not truth
          , isTrueTerm thenTerm ->
              decomposeBoolFact (fuel - 1) condition False
                ++ decomposeBoolFact (fuel - 1) elseTerm False
          | isFalseTerm thenTerm
          , isTrueTerm elseTerm ->
              decomposeBoolFact (fuel - 1) condition (not truth)
        _ -> decomposeSpine
  where
    decomposeSpine =
      case spineOfTerm (stripIdentityWrappers term) of
        (headTerm, arguments)
          | termHeadGlob (stripIdentityWrappers headTerm) == Just prelAnd
          , truth
          , Just (left, right) <- last2 [argument | (Expl, argument) <- arguments] ->
              decomposeBoolFact (fuel - 1) left True
                ++ decomposeBoolFact (fuel - 1) right True
          | termHeadGlob (stripIdentityWrappers headTerm) == Just prelOr
          , not truth
          , Just (left, right) <- last2 [argument | (Expl, argument) <- arguments] ->
              decomposeBoolFact (fuel - 1) left False
                ++ decomposeBoolFact (fuel - 1) right False
          | termHeadGlob (stripIdentityWrappers headTerm) == Just prelNot
          , [argument] <- [candidate | (Expl, candidate) <- arguments] ->
              decomposeBoolFact (fuel - 1) argument (not truth)
        _ -> [(term, truth)]

    isTrueTerm = \case
      CCtor constructor _ [] -> constructor == prelTrue
      _ -> False

    isFalseTerm = \case
      CCtor constructor _ [] -> constructor == prelFalse
      _ -> False

-- | Weaken branch facts into a descendant lexical context. A fact can only be
-- consumed at its original depth or below it; seeing it from a shallower
-- context would mean it escaped the branch/binder scope that established it,
-- so such a fact is rejected rather than guessed at.
scopedBoolFactsAt :: Int -> [ScopedBoolFact] -> CheckM [(Term, Bool)]
scopedBoolFactsAt targetDepth = fmap catMaybes . mapM rebase
  where
    rebase (ScopedBoolFact sourceDepth term truth)
      | targetDepth >= sourceDepth =
          pure (Just (shiftTerm (targetDepth - sourceDepth) 0 term, truth))
      | otherwise = pure Nothing

proveBoolValue :: Set Int -> [(Term, Bool)] -> [AFact] -> Int -> Bool -> Term -> CheckM Bool
proveBoolValue natLvls boolFacts facts d want t = do
  exactBranchFact <- branchFactTruthAt d boolFacts t
  case exactBranchFact of
    Just truth -> pure (truth == want)
    Nothing -> do
      mRaw <- proveBoolValueAttempt natLvls boolFacts facts d want t
      case mRaw of
        Just ok -> pure ok
        Nothing -> do
          mNorm <- transparentProofNormalize d t
          case mNorm of
            Just t' -> do
              normalizedBranchFact <- branchFactTruthAt d boolFacts t'
              case normalizedBranchFact of
                Just truth -> pure (truth == want)
                Nothing ->
                  fromMaybe False
                    <$> proveBoolValueAttempt natLvls boolFacts facts d want t'
            Nothing -> pure False

-- | Match an exact checked branch fact modulo Core definitional equality.
-- Structural keys remain the fast path in 'evalBoolTermWithFacts', but
-- cumulative lifts, selected reducible wrappers, and checked literal
-- elaboration can give definitionally equal conditions different retained
-- syntax.  The evaluator comparison is bounded and uses the same rigid local
-- environment as ordinary conversion; it does not derive a new Boolean fact
-- or inspect names.
branchFactTruthAt :: Int -> [(Term, Bool)] -> Term -> CheckM (Maybe Bool)
branchFactTruthAt depth facts target = do
  ec <- ec_
  let environment =
        [VRigid level [] | level <- reverse [0 .. depth - 1]]
      targetValue = eval ec environment target
      matches (condition, _) =
        convertible ec depth (eval ec environment condition) targetValue
  pure (snd <$> find matches facts)

proveBoolValueAttempt :: Set Int -> [(Term, Bool)] -> [AFact] -> Int -> Bool -> Term -> CheckM (Maybe Bool)
proveBoolValueAttempt natLvls boolFacts facts d want t = do
  case simplifyDecisionTerm t of
    CCtor g _ [] | g == prelTrue -> pure (Just want)
    CCtor g _ [] | g == prelFalse -> pure (Just (not want))
    _ -> do
      case evalBoolTermWithFacts d boolFacts (6 :: Int) t of
        Just got -> pure (Just (got == want))
        Nothing -> do
          mRangeFacts <- selectedNatRangeMembershipFacts d t
          rangeResult <- case mRangeFacts of
            Just rangeFacts -> do
              proved <- mapM (proveFact natLvls facts) rangeFacts
              pure (if and proved == want then Just True else Nothing)
            Nothing -> pure Nothing
          case rangeResult of
            Just result -> pure (Just result)
            Nothing -> do
          -- Branch-refined equality proofs first consume only the visible
          -- boolean/arithmetic shape of the target proposition plus active
          -- branch facts. The caller may then try one bounded transparent
          -- normalization pass through definitions already marked reducible
          -- by the ordinary totality/opacity machinery.
              mf <- selectedArithmeticPredicateFact d t
              case mf >>= if want then Just else negateFact of
                Just fact -> do
                  ok <- proveFact natLvls facts fact
                  pure (if ok then Just True else Nothing)
                Nothing -> pure Nothing

-- | Decode a boolean arithmetic predicate only after authenticating the
-- selected provider and member identity. Primitive comparisons are already
-- self-authenticating through their wired-in global identities. Trait methods
-- additionally require the exact coherent dictionary selected by elaboration;
-- a user dictionary or an unrelated field with the same source label is never
-- admitted to the arithmetic solver.
selectedArithmeticPredicateFact :: Int -> Term -> CheckM (Maybe AFact)
selectedArithmeticPredicateFact depth term =
  boolRelBranchM depth term >>= \case
    Just primitive -> pure (Just primitive)
    Nothing ->
      selectedStandardCheckedPredicateFact
        ArithmeticNatural
        depth
        term

-- | Domain-indexed certificate entry point for selected arithmetic
-- predicates. A still-selected standard order application carries its
-- carrier explicitly, so reject a certificate-domain mismatch before trying
-- representation-level primitive recognition. This prevents a Nat proof from
-- being replayed as Integer arithmetic (or conversely) merely because both
-- lower to the same integer comparison primitives.
selectedArithmeticPredicateFactForDomain
  :: ArithmeticDomain
  -> Int
  -> Term
  -> CheckM (Maybe AFact)
selectedArithmeticPredicateFactForDomain domain depth term =
  selectedStandardOrderFact depth term >>= \case
    Just (selectedDomain, fact) ->
      pure (if selectedDomain == domain then Just fact else Nothing)
    Nothing -> do
      selectedPrimitiveArithmeticPredicateFact domain depth term >>= \case
        Just fact -> pure (Just fact)
        Nothing ->
          selectedStandardCheckedPredicateFact domain depth term >>= \case
            Just fact -> pure (Just fact)
            Nothing -> case domain of
              ArithmeticNatural -> selectedArithmeticPredicateFact depth term
              ArithmeticInteger -> boolRelBranchM depth term
              ArithmeticTypeLevel -> pure Nothing
              ArithmeticProviderLaw -> pure Nothing

-- | Decode the canonical primitive comparison emitted after an authenticated
-- standard order call has been lowered.  Primitive identity authenticates the
-- relation, while the Nat domain additionally requires both operands to pass
-- through the checked @natToInt@ bridge.  This keeps Nat and Integer
-- certificates disjoint even though their exact runtime comparison primitive
-- is shared.
selectedPrimitiveArithmeticPredicateFact
  :: ArithmeticDomain
  -> Int
  -> Term
  -> CheckM (Maybe AFact)
selectedPrimitiveArithmeticPredicateFact domain depth term =
  case spineOfTerm (stripIdentityWrappers term) of
    (headTerm, arguments)
      | Just operation <- termHeadGlob (stripIdentityWrappers headTerm)
      , Just comparison <-
          lookup
            operation
            [ (gPrel "ltInt", ACmpLt)
            , (gPrel "leInt", ACmpLe)
            , (gPrel "eqInt", ACmpEq)
            ]
      , Just (left, right) <-
          last2 [argument | (Expl, argument) <- arguments] -> do
          logicalDomain <- case domain of
            ArithmeticNatural ->
              pure (Just PrimitiveComparisonNatural)
            ArithmeticInteger ->
              pure (Just PrimitiveComparisonInteger)
            ArithmeticTypeLevel -> pure Nothing
            ArithmeticProviderLaw -> pure Nothing
          leftExpression <- case logicalDomain of
            Nothing -> pure Nothing
            Just selected ->
              decodePrimitiveComparisonOperandM
                natBridgePayload
                decodeExpression
                selected
                left
          rightExpression <- case logicalDomain of
            Nothing -> pure Nothing
            Just selected ->
              decodePrimitiveComparisonOperandM
                natBridgePayload
                decodeExpression
                selected
                right
          pure
            ( AFact comparison
                <$> leftExpression
                <*> rightExpression
            )
    _ -> pure Nothing
  where
    decodeExpression selected =
      selectedArithmeticExpression
        ( case selected of
            PrimitiveComparisonNatural -> ArithmeticNatural
            PrimitiveComparisonInteger -> ArithmeticInteger
        )
        depth

    natBridgePayload operand =
      case spineOfTerm (stripIdentityWrappers operand) of
        (headTerm, arguments)
          | termHeadGlob (stripIdentityWrappers headTerm)
              == Just prelNatToInt
          , [payload] <- [argument | (Expl, argument) <- arguments] ->
              Just payload
        _ -> Nothing

data StandardCheckedPredicateSemantics
  = CheckedSubtractionDomain
  | CheckedNonzeroDomain

data StandardCheckedPredicate = StandardCheckedPredicate
  { scpTrait :: !GName
  , scpMember :: !Text
  , scpDomains :: ![ArithmeticDomain]
  , scpSemantics :: !StandardCheckedPredicateSemantics
  }

-- | Reify the normative §28.2.3 domains of the standard checked operations.
-- The operation member, selected dictionary identity, checked carrier head,
-- and supported arithmetic domain are all authenticated before a fact reaches
-- the generic arithmetic kernel. A same-spelled user field or custom
-- dictionary therefore fails closed.
selectedStandardCheckedPredicateFact
  :: ArithmeticDomain
  -> Int
  -> Term
  -> CheckM (Maybe AFact)
selectedStandardCheckedPredicateFact domain depth term =
  firstDescriptor standardCheckedPredicates
  where
    stateMemberOwners state = csBareTraitMembers state
    (headTerm, arguments) = spineOfTerm (stripIdentityWrappers term)
    explicitArguments = [argument | (Expl, argument) <- arguments]
    implicitArguments = [argument | (Impl, argument) <- arguments]

    firstDescriptor [] = pure Nothing
    firstDescriptor (descriptor : rest)
      | domain `notElem` scpDomains descriptor = firstDescriptor rest
      | otherwise = do
          state <- get
          let trait = scpTrait descriptor
              member = scpMember descriptor
              qualifiedMember = memberGlobal trait member
              selectedGlobal candidate =
                case termHeadGlob (stripIdentityWrappers candidate) of
                  Just global ->
                    global == qualifiedMember
                      || Map.lookup global (stateMemberOwners state)
                           == Just (trait, member)
                  Nothing -> False
              globalCall = do
                guard (selectedGlobal headTerm)
                carrier : dictionary : _ <- pure implicitArguments
                guard (arithmeticDomainForCarrier carrier == Just domain)
                (left, right) <- last2 explicitArguments
                pure (dictionary, left, right)
              projectedCall =
                case stripIdentityWrappers headTerm of
                  CProjM _ dictionary projectedMember
                    | projectedMember == member -> do
                        (left, right) <- last2 explicitArguments
                        pure (dictionary, left, right)
                  CProjAtM _ dictionary projectedMember _
                    | projectedMember == member -> do
                        (left, right) <- last2 explicitArguments
                        pure (dictionary, left, right)
                  _ -> Nothing
          case globalCall <|> projectedCall of
            Nothing -> firstDescriptor rest
            Just (dictionary, left, right) -> do
              standard <-
                standardPreludeDictionary
                  trait
                  (\case
                    [carrier] ->
                      arithmeticDomainForCarrier carrier == Just domain
                    _ -> False)
                  dictionary
              if not standard
                then firstDescriptor rest
                else do
                  leftExpression <-
                    selectedArithmeticExpression domain depth left
                  rightExpression <-
                    selectedArithmeticExpression domain depth right
                  pure $ do
                    left' <- leftExpression
                    right' <- rightExpression
                    pure $ case scpSemantics descriptor of
                      CheckedSubtractionDomain ->
                        AFact ACmpLe right' left'
                      CheckedNonzeroDomain ->
                        AFact ACmpNe right' (AConst 0)

standardCheckedPredicates :: [StandardCheckedPredicate]
standardCheckedPredicates =
  [ StandardCheckedPredicate
      (gPrel "CheckedSub")
      "subDefined"
      [ArithmeticNatural]
      CheckedSubtractionDomain
  , StandardCheckedPredicate
      (gPrel "CheckedDiv")
      "divDefined"
      [ArithmeticNatural, ArithmeticInteger]
      CheckedNonzeroDomain
  , StandardCheckedPredicate
      (gPrel "CheckedMod")
      "modDefined"
      [ArithmeticNatural, ArithmeticInteger]
      CheckedNonzeroDomain
  ]

-- | Reify the normative §20.2.1 equations for canonical Nat ranges. Every
-- semantic step is authenticated: the selected @Contains@ dictionary must be
-- the prelude instance for @(NumericRange Nat, Nat)@, and the range value must
-- be built by the selected prelude @Rangeable Nat@ instance (or already be its
-- checked constructor result). A same-spelled user member or range constructor
-- cannot enter this proof source.
selectedNatRangeMembershipFacts :: Int -> Term -> CheckM (Maybe [AFact])
selectedNatRangeMembershipFacts depth term = do
  selectedNatRangeMembershipOperands term >>= \case
    Nothing -> pure Nothing
    Just (rangeValue, value) -> do
      decodedRange <- decodeSelectedNatRange depth rangeValue
      case decodedRange of
        Nothing -> pure Nothing
        Just (lower, upper, exclusive) -> do
          lowerExpression <- selectedNatArithmeticExpression depth lower
          valueExpression <- selectedNatArithmeticExpression depth value
          upperExpression <- selectedNatArithmeticExpression depth upper
          pure $ do
            lower' <- lowerExpression
            value' <- valueExpression
            upper' <- upperExpression
            pure
              [ AFact ACmpLe lower' value'
              , AFact
                  (if exclusive then ACmpLt else ACmpLe)
                  value'
                  upper'
              ]

-- | Authenticate one selected @Contains (NumericRange Nat) Nat@ application
-- and recover its range/value operands. Dictionary discovery is by checked
-- instance identity, not by a source-spine position: generated erased proof
-- arguments may be interleaved with ordinary implicits.
selectedNatRangeMembershipOperands :: Term -> CheckM (Maybe (Term, Term))
selectedNatRangeMembershipOperands term = do
  state <- get
  let containsTrait = gPrel "Contains"
      containsMember = memberGlobal containsTrait "contains"
      arguments = snd (spineOfTerm (stripIdentityWrappers term))
      explicitArguments = [argument | (Expl, argument) <- arguments]
      implicitArguments = [argument | (Impl, argument) <- arguments]
      selectedContainsGlobal candidate =
        case termHeadGlob (stripIdentityWrappers candidate) of
          Just global ->
            global == containsMember
              || Map.lookup global (csBareTraitMembers state)
                   == Just (containsTrait, "contains")
          Nothing -> False
      globalCall candidate = do
        guard (selectedContainsGlobal candidate)
        (rangeValue, value) <- last2 explicitArguments
        pure (implicitArguments, rangeValue, value)
      projectedCall candidate = case stripIdentityWrappers candidate of
        CProjM _ dictionary "contains" -> do
          (rangeValue, value) <- last2 explicitArguments
          pure ([dictionary], rangeValue, value)
        CProjAtM _ dictionary "contains" _ -> do
          (rangeValue, value) <- last2 explicitArguments
          pure ([dictionary], rangeValue, value)
        _ -> Nothing
      headTerm = fst (spineOfTerm (stripIdentityWrappers term))
  case globalCall headTerm <|> projectedCall headTerm of
    Nothing -> pure Nothing
    Just (dictionaryCandidates, rangeValue, value) -> do
      selectedDictionary <-
        uniqueStandardPreludeDictionaryArgument
          containsTrait
          (\case
            [container, item] ->
              isNumericRangeNatType container && isNatType item
            _ -> False)
          dictionaryCandidates
      case selectedDictionary of
        Nothing -> pure Nothing
        Just _ -> pure (Just (rangeValue, value))

decodeSelectedNatRange :: Int -> Term -> CheckM (Maybe (Term, Term, Bool))
decodeSelectedNatRange depth rangeValue = do
  normalized <- transparentProofReduce depth 48 rangeValue
  case decodedConstructor normalized of
    Just decoded -> pure (Just decoded)
    Nothing -> decodeRangeCall rangeValue
  where
    decodedConstructor = \case
      CCtorI constructor _ _ arguments
        | constructor == prelNumericRange
        , [lower, upper, exclusive] <-
            [caTerm argument | argument <- arguments, caPayload argument]
        , Just exclusiveValue <- boolLiteralTerm exclusive ->
            Just (lower, upper, exclusiveValue)
      _ -> Nothing

    decodeRangeCall term =
      case spineOfTerm (stripIdentityWrappers term) of
        (headTerm, arguments)
          | Just operator <- termHeadGlob (stripIdentityWrappers headTerm)
          , operator == gPrel ".." || operator == gPrel "..<"
          , [lower, upper] <- [argument | (Expl, argument) <- arguments] -> do
              dictionary <-
                uniqueStandardPreludeDictionaryArgument
                  (gPrel "Rangeable")
                  (\case
                    [headType] -> isNatType headType
                    _ -> False)
                  [argument | (Impl, argument) <- arguments]
              pure $
                case dictionary of
                  Just _ -> Just (lower, upper, operator == gPrel "..<")
                  Nothing -> Nothing
        _ -> pure Nothing

    boolLiteralTerm = \case
      CCtor constructor _ []
        | constructor == prelTrue -> Just True
        | constructor == prelFalse -> Just False
      _ -> Nothing

isNatType :: Term -> Bool
isNatType term =
  termHeadGlob (stripIdentityWrappers term) == Just prelNat

isNumericRangeNatType :: Term -> Bool
isNumericRangeNatType term =
  case spineOfTerm (stripIdentityWrappers term) of
    (headTerm, arguments)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelNumericRange ->
          case reverse [argument | (_, argument) <- arguments] of
            item : _ -> isNatType item
            _ -> False
    _ -> False

-- | Authenticate a selected premise-free standard dictionary against its
-- checked trait head. This shared helper is intentionally structural: callers
-- supply semantic head predicates over resolved Core, never rendered names.
standardPreludeDictionary
  :: GName
  -> ([Term] -> Bool)
  -> Term
  -> CheckM Bool
standardPreludeDictionary trait validHead dictionary = do
  instances <- gets csInstances
  pure (standardPreludeDictionaryIn instances trait validHead dictionary)

-- | Select one authenticated dictionary from an application implicit spine.
-- Generated universe-relation proofs and other erased implicits may precede
-- or follow source dictionaries, so semantic consumers must not recover
-- evidence by a fixed argument offset. Exactly one checked prelude instance
-- must match; absence and ambiguity both fail closed.
uniqueStandardPreludeDictionaryArgument
  :: GName
  -> ([Term] -> Bool)
  -> [Term]
  -> CheckM (Maybe Term)
uniqueStandardPreludeDictionaryArgument trait validHead candidates = do
  instances <- gets csInstances
  pure $ case
    [ candidate
    | candidate <- candidates
    , standardPreludeDictionaryIn instances trait validHead candidate
    ] of
      [dictionary] -> Just dictionary
      _ -> Nothing

standardPreludeDictionaryIn
  :: [InstanceEntry]
  -> GName
  -> ([Term] -> Bool)
  -> Term
  -> Bool
standardPreludeDictionaryIn instances trait validHead dictionary =
  case termHeadGlob (stripIdentityWrappers dictionary) of
    Just dictionaryGlobal ->
      dictionaryGlobal `gnameInModule` preludeModule
        && any
          ( \entry ->
              ieDict entry == dictionaryGlobal
                && ieTrait entry == trait
                && null (iePremises entry)
                && validHead (ieHead entry)
          )
          instances
    Nothing -> False

transparentProofNormalize :: Int -> Term -> CheckM (Maybe Term)
transparentProofNormalize d t = do
  st <- get
  if not (null (unsolvedMetasOf st t))
    then pure Nothing
    else do
      t' <- transparentProofReduce d (96 :: Int) t
      let raw = simplifyDecisionTerm t
          norm = simplifyDecisionTerm t'
      pure (if norm /= raw then Just norm else Nothing)

-- | Bounded, non-strict proof-side reduction.
--
-- Runtime evaluation of Kappa is strict, but proposition solving must not
-- force arbitrary user arguments just to learn that a transparent proof
-- predicate ignores them.  This reducer unfolds only definitions that the
-- ordinary totality machinery has already marked conversion-reducible, then
-- performs beta/projection/known-branch reduction on Core syntax without
-- evaluating function arguments first.  If the fuel runs out, it returns the
-- best neutral term it has instead of claiming a proof.
transparentProofReduce :: Int -> Int -> Term -> CheckM Term
transparentProofReduce d fuel0 t0 = go fuel0 (simplifyDecisionTermAt d t0)
  where
    go fuel t
      | fuel <= 0 = pure (simplifyDecisionTermAt d t)
      | otherwise = do
          -- Preserve authenticated arithmetic providers before unfolding
          -- their library implementation. Provider decoders need the selected
          -- dictionary identity; reducing past it would retain operational
          -- behavior while discarding the authority used by proof synthesis.
          primitiveCompare <- primitiveOrderedCompareArgsRaw d t
          case primitiveCompare of
            Just _ -> reduceProtectedApplication fuel t
            Nothing -> selectedStandardOrderFact d t >>= \case
              Just _ -> reduceProtectedApplication fuel t
              Nothing -> do
                let simplified = simplifyDecisionTermAt d t
                if simplified /= t
                  then
                    -- Beta/iota reduction can expose a selected provider
                    -- application. Give the semantic recognizers first right
                    -- of refusal before generic delta reduction unfolds away
                    -- its checked dictionary identity.
                    go (fuel - 1) simplified
                  else case t of
                    CGlobal g universes ->
                      maybe (pure (CGlobal g universes)) (go (fuel - 1))
                        =<< unfoldReducibleGlobal d g universes
                    application@CApp {}
                      | trustedNaturalBridgeApplication application ->
                          reduceTrustedNaturalBridge (fuel - 1) application
                      | trustedIntegerPrimitiveApplication application ->
                          reduceProtectedApplication fuel application
                      | otherwise -> reduceApp fuel application
                    CProjM mode e f -> do
                      e' <- go (fuel - 1) e
                      case e' of
                        CRecordV fs | Just x <- lookup f fs -> go (fuel - 1) x
                        CCtorI constructor _ _ arguments ->
                          typedConstructorProjection constructor arguments f >>= \case
                            Just x -> go (fuel - 1) x
                            Nothing -> pure (CProjM mode e' f)
                        CSealE ls inner | f `notElem` ls -> go (fuel - 1) (CProjM mode inner f)
                        _ -> pure (CProjM mode e' f)
                    CProjAtM mode e f i -> do
                      e' <- go (fuel - 1) e
                      case e' of
                        CRecordV fs | Just x <- lookup f fs -> go (fuel - 1) x
                        CCtorI constructor _ _ arguments ->
                          typedConstructorProjection constructor arguments f >>= \case
                            Just x -> go (fuel - 1) x
                            Nothing -> pure (CProjAtM mode e' f i)
                        CSealE ls inner | f `notElem` ls -> go (fuel - 1) (CProjAtM mode inner f i)
                        _ -> pure (CProjAtM mode e' f i)
                    CIf c th el -> do
                      c' <- go (fuel - 1) c
                      case c' of
                        CCtor g _ [] | g == prelTrue -> go (fuel - 1) th
                        CCtor g _ [] | g == prelFalse -> go (fuel - 1) el
                        _ -> pure (CIf c' th el)
                    CMatch s ann resultAnn alts -> do
                      s' <- go (fuel - 1) s
                      case s' of
                        CIf condition thenBranch elseBranch ->
                          go
                            (fuel - 1)
                            ( CIf
                                condition
                                (CMatch thenBranch ann resultAnn alts)
                                (CMatch elseBranch ann resultAnn alts)
                            )
                        _ ->
                          transparentSelectorProjection s' alts >>= \case
                            Just projection -> go (fuel - 1) projection
                            Nothing -> reduceKnownMatch (fuel - 1) s' ann resultAnn alts
                    CLet _ _ _ rhs body ->
                      go (fuel - 1) (substTopTermAt d rhs body)
                    CLetRecM mode q n a rhs body ->
                      pure (CLetRecM mode q n a rhs body)
                    CForceE delayed resultType -> do
                      delayed' <- go (fuel - 1) delayed
                      case delayed' of
                        CThunkE body _ -> go (fuel - 1) body
                        _ -> pure (CForceE delayed' resultType)
                    other -> pure other

    -- Keep the authenticated operation and every implicit evidence argument
    -- intact, but do not freeze ordinary value operands underneath it.
    -- Dependent projections and known-constructor matches may otherwise remain
    -- hidden below a selected comparison forever, preventing the surrounding
    -- branch fact from reaching a fixed point.
    reduceProtectedApplication fuel application = do
      let (headTerm, arguments) = spineOfTerm application
      arguments' <-
        traverse
          (\case
            (Expl, argument) -> (Expl,) <$> go (fuel - 1) argument
            implicit -> pure implicit)
          arguments
      let reduced =
            List.foldl'
              (\function (icit, argument) -> CApp icit function argument)
              headTerm
              arguments'
      pure (fromMaybe reduced (foldTrustedIntegerPrimitive reduced))

    trustedIntegerPrimitiveApplication application =
      case spineOfTerm (stripIdentityWrappers application) of
        (headTerm, _) ->
          maybe
            False
            ( \global ->
                isJust (intArithPrim global)
                  || isJust (intCmpPrim global)
            )
            (termHeadGlob (stripIdentityWrappers headTerm))

    -- The standard Nat-to-Integer bridge is an exact compiler-wired pure
    -- operation. Reducing its sole operand is therefore safe even though the
    -- generic non-strict reducer leaves arbitrary function arguments opaque.
    -- This exposes known constructor projections selected by branch facts;
    -- only a resulting Nat literal is folded by the shared authenticated
    -- bridge rule.
    trustedNaturalBridgeApplication application =
      case spineOfTerm (stripIdentityWrappers application) of
        (headTerm, [(Expl, _)]) ->
          termHeadGlob (stripIdentityWrappers headTerm)
            `elem`
              [ Just prelNatToInt
              , Just (GName primModule (gKey prelNatToInt))
              ]
        _ -> False

    reduceTrustedNaturalBridge fuel application =
      case spineOfTerm (stripIdentityWrappers application) of
        (headTerm, [(Expl, operand)]) -> do
          operand' <- go fuel operand
          let reduced = CApp Expl headTerm operand'
          pure
            (fromMaybe reduced (canonicalTrustedNaturalLiteralBridge reduced))
        _ -> pure application

    -- Keep neutral integer primitives visible to the arithmetic reifier, but
    -- do not strand a branch decision once every operand is a closed literal.
    -- The exact primitive identity authorizes evaluation through the same pure
    -- runtime table used by conversion; partial operations such as division by
    -- zero return 'Nothing' and therefore remain neutral.
    foldTrustedIntegerPrimitive application = do
      let (headTerm, arguments) =
            spineOfTerm (stripIdentityWrappers application)
      global@(GName _ operation) <-
        termHeadGlob (stripIdentityWrappers headTerm)
      guard
        ( isJust (intArithPrim global)
            || isJust (intCmpPrim global)
        )
      operands <-
        traverse literalValue
          [argument | (Expl, argument) <- arguments]
      result <- evalPurePrim operation operands
      literalTerm result

    literalValue = \case
      CLit literal -> Just (VLit literal)
      _ -> Nothing

    literalTerm = \case
      VLit literal -> Just (CLit literal)
      VCtorI constructor universes [] ->
        Just (CCtorI constructor universes Nothing [])
      _ -> Nothing

    reduceApp fuel t = do
      let (hd0, args0) = spineOfTerm t
      hd <- go (fuel - 1) hd0
      applySpine (fuel - 1) hd args0

    applySpine fuel hd args
      | fuel <= 0 = pure (List.foldl' (\f (ic, a) -> CApp ic f a) hd args)
      | otherwise = case (hd, args) of
          (CLam lamIc _ _ body, (argIc, arg) : rest)
            | lamIc == argIc -> go (fuel - 1) (List.foldl' (\f (ic, a) -> CApp ic f a) (substTopTermAt d arg body) rest)
          (CProjM mode e f, _) -> do
            hd' <- go (fuel - 1) (CProjM mode e f)
            if hd' == hd
              then pure (List.foldl' (\f (ic, a) -> CApp ic f a) hd args)
              else applySpine (fuel - 1) hd' args
          (CProjAtM mode e f i, _) -> do
            hd' <- go (fuel - 1) (CProjAtM mode e f i)
            if hd' == hd
              then pure (List.foldl' (\f (ic, a) -> CApp ic f a) hd args)
              else applySpine (fuel - 1) hd' args
          (CGlobal g universes, _) -> do
            mBody <- unfoldReducibleGlobal d g universes
            case mBody of
              Just body -> applySpine (fuel - 1) body args
              Nothing -> pure (List.foldl' (\f (ic, a) -> CApp ic f a) hd args)
          _ -> pure (List.foldl' (\f (ic, a) -> CApp ic f a) hd args)

    reduceKnownMatch fuel scrutinee annotation resultAnnotation = select
      where
        preserve alternatives =
          pure (simplifyDecisionTerm (CMatch scrutinee annotation resultAnnotation alternatives))

        select [] = preserve []
        select alternatives@(CaseAlt pattern' guardTerm body : rest) =
          case matchCorePattern pattern' scrutinee of
            CorePatternMismatch -> select rest
            CorePatternUndecided -> preserve alternatives
            CorePatternMatched bindings -> do
              let instantiate =
                    instantiateCorePatternBody d bindings
                  body' = instantiate body
              case guardTerm of
                Nothing -> go fuel body'
                Just guardBody -> do
                  guard' <- go fuel (instantiate guardBody)
                  case guard' of
                    CCtor constructor _ []
                      | constructor == prelTrue -> go fuel body'
                      | constructor == prelFalse -> select rest
                    _ -> preserve alternatives

    -- A transparent named projection over a single-constructor family is
    -- commonly elaborated as a one-arm match. Preserve that ordinary
    -- eliminator semantics when its scrutinee is neutral: the exact checked
    -- constructor identity and source-field table authenticate the rewrite.
    -- Any richer match remains neutral and is handled by 'reduceKnownMatch'.
    transparentSelectorProjection scrutinee = \case
      [ CaseAlt
          (CPCtorM [] [] hidden constructor _ patterns)
          Nothing
          (CVar selectedIndex)
        ] -> do
          state <- get
          pure $ do
            constructorInfo <- Map.lookup constructor (csCtors state)
            dataInfo <- Map.lookup (ciData constructorInfo) (csDatas state)
            guard (diCtors dataInfo == [constructor])
            let explicitFields =
                  [fieldName | (Expl, fieldName) <- ciSourceFields constructorInfo]
            guard (length patterns == length explicitFields)
            source <-
              interleaveConstructorSourceBinders
                hidden
                (zip explicitFields patterns)
            let slots =
                  concatMap
                    ( \case
                        Left _ -> [Nothing]
                        Right (Just fieldName, CPVarM mode _) ->
                          [Just (fieldName, mode)]
                        Right (_, pattern') ->
                          replicate (patBindersC pattern') Nothing
                    )
                    source
                binderCount = length slots
                sourceIndex =
                  binderCount - selectedIndex - 1
            guard (sourceIndex >= 0)
            (fieldName, mode) <- slots `atMay` sourceIndex >>= id
            pure (CProjM mode scrutinee fieldName)
      _ -> pure Nothing

    -- A saturated typed constructor occurrence carries the complete checked Pi
    -- spine, including stable source-field identities. Reduce a named
    -- projection only when the exact constructor interface confirms one unique
    -- source field and the occurrence carries one matching named argument.
    -- Untyped legacy constructors and malformed/ambiguous spines stay neutral.
    typedConstructorProjection constructor arguments field = do
      state <- get
      pure $ do
        constructorInfo <- Map.lookup constructor (csCtors state)
        guard
          ( length
              [ ()
              | (_, Just sourceField) <- ciSourceFields constructorInfo
              , sourceField == field
              ]
              == 1
          )
        case
          [ caTerm argument
          | argument <- arguments
          , caName argument == Just field
          ] of
          [value] -> Just value
          _ -> Nothing

    atMay values index =
      case drop index values of
        value : _ -> Just value
        [] -> Nothing

unfoldReducibleGlobal :: Int -> GName -> [Level] -> CheckM (Maybe Term)
unfoldReducibleGlobal d g universes = do
  st <- get
  case Map.lookup g (csGlobals st) of
    Just gd | gdReducible gd, Just body <- gdValue gd ->
      -- Prefer the raw (un-normalized) recorded core body. The bounded
      -- syntactic reducer 'transparentProofReduce' steps through it itself,
      -- and it deliberately does NOT descend into stuck `if`/`match`
      -- branches — so a recursive definition applied to a neutral argument
      -- unfolds at most once per step and is bounded by that reducer's fuel.
      -- Quoting 'gdValue' instead would *fully* normalize the body (running
      -- every stuck branch via 'quote'/'closRun', which is unbounded) and
      -- diverges for such a recursive function (e.g. a §3.2.3 branch-fact
      -- normalization that unfolds a recursive predicate). The core body is
      -- closed and definitionally equal to the value's normal form, so
      -- non-recursive helpers still reduce identically.
      case specializeGlobalDefinitionBody universes gd of
        Just coreTm -> pure (Just coreTm)
        Nothing -> do
          ec <- ec_
          pure
            ( Just
                ( zonkTermWith
                    (\_ _ -> Nothing)
                    (substituteLevelParams universes)
                    0
                    (quote ec d body)
                )
            )
    _ -> pure Nothing

evalBoolTermWithFacts :: Int -> [(Term, Bool)] -> Int -> Term -> Maybe Bool
evalBoolTermWithFacts _ _ 0 _ = Nothing
evalBoolTermWithFacts d facts depth t0 =
  let factMap =
        Map.fromListWith
          (\new _old -> new)
          [(branchFactKey tm, truth) | (tm, truth) <- facts]
      go = evalBoolTermWithFacts d facts (depth - 1)
      t = simplifyDecisionTerm t0
   in case t of
        CCtor g _ [] | g == prelTrue -> Just True
        CCtor g _ [] | g == prelFalse -> Just False
        _ | Just truth <- Map.lookup (branchFactKey t) factMap -> Just truth
        CIf c th el -> do
          truth <- go c
          go (if truth then th else el)
        _ | Just p <- boolNotArg t -> not <$> go p
        _ -> Nothing

-- ── Quantities (surface → core) ──────────────────────────────────────

emptyBinderPrefix :: BinderPrefix -> Bool
emptyBinderPrefix (BinderPrefix observation quantity borrow) =
  isNothing observation && isNothing quantity && isNothing borrow

surfaceQuantityZero :: Maybe S.Quantity -> Bool
surfaceQuantityZero = \case
  Just S.QZero -> True
  _ -> False

surfaceQuantityPositive :: Maybe S.Quantity -> Bool
surfaceQuantityPositive = \case
  Just S.QOne -> True
  Just S.QAtLeastOne -> True
  _ -> False

qOf :: Maybe S.Quantity -> Q
qOf = \case
  Nothing -> QW
  Just S.QZero -> Q0
  Just S.QOne -> Q1
  Just S.QOmega -> QW
  Just S.QAtMostOne -> QLe1
  Just S.QAtLeastOne -> QGe1
  Just (S.QTerm _) -> QW -- symbolic quantities: approximated as ω

renderCoreQ :: Q -> Text
renderCoreQ = \case
  Q0 -> "0"
  Q1 -> "1"
  QW -> "ω"
  QLe1 -> "<=1"
  QGe1 -> ">=1"

renderObservationMode :: ObservationMode -> Text
renderObservationMode = \case
  Ordinary -> "ordinary"
  Parametric -> "parametric"

binderQ :: Binder -> Q
binderQ b = case bpQuantity (bPrefix b) of
  Just q -> qOf (Just q)
  Nothing
    | isJust (bpBorrow (bPrefix b)) -> QW -- borrowed reads (approximation)
    | bImplicit b -> QW
    | otherwise -> QW

-- | The recursive §11.1.2.3B parametric-kind grammar.  This is a judgment
-- over elaborated KCore values, not a source-name or quantity heuristic.
isParametricKind :: Int -> Value -> CheckM Bool
isParametricKind lvl value =
  forceM value >>= \case
    VSort _ -> pure True
    VPiBoundFormedM Parametric FormationParametric _ Q0 False _ _ dom clo -> do
      domainOk <- isParametricKind lvl dom
      if not domainOk
        then pure False
        else clApp clo (VRigid lvl []) >>= isParametricKind (lvl + 1)
    _ -> pure False

-- | Resolve the independent observation-mode and quantity defaults of
-- §12.1.1 after the binder domain has been elaborated.  @ordinaryDefault@
-- is the pre-existing quantity rule for a non-parametric-kind domain (for
-- example an implicit coerced proposition may supply Q0).
resolveBinderModeQ :: Ctx -> Binder -> Value -> Q -> CheckM (ObservationMode, Q)
resolveBinderModeQ ctx binder domain ordinaryDefault = do
  paramKind <- isParametricKind (ctxLen ctx) domain
  let prefix = bPrefix binder
      mode = fromMaybe (if paramKind then Parametric else Ordinary) (bpObservation prefix)
      q = maybe (if paramKind then Q0 else ordinaryDefault) (qOf . Just) (bpQuantity prefix)
  validateQuantityExpression ctx (bpQuantity prefix)
  when paramKind $
    modify' $ \st -> st {csStaticKindBinders = Set.insert (bSpan binder) (csStaticKindBinders st)}
  pure (mode, q)

-- | Check §12.1.1 quantity expressions at the shared binder boundary.  The
-- portable-v1 restriction is semantic, not a parser shortcut: a statically
-- classified Quantity expression is admitted, but an expression mentioning
-- an object-phase local is a value-dependent multiplicity and is rejected by
-- §12.2.10.  Reject that dependency before checking the expression's
-- classifier so a runtime condition does not cascade into unrelated numeric
-- evidence failures in its branches.
validateQuantityExpression :: Ctx -> Maybe S.Quantity -> CheckM ()
validateQuantityExpression ctx = \case
  Just (S.QTerm expression) -> do
    let localOccurrences =
          [ (name, entry)
          | name <- freeVarOccurrences expression
          , Just (_, entry) <- [lookupCtx (nameText name) ctx]
          ]
    runtimeOccurrences <-
      filterM (fmap not . metaPhaseType . ceType . snd) localOccurrences
    case find (isJust . ceVarInfo . snd) runtimeOccurrences of
      Just _ -> do
        -- Mutable current values have a more precise static-position rule
        -- than the general object-phase quantity restriction. Check the
        -- complete expression under the static read barrier so the ordinary
        -- mutable-facet machinery emits E_VAR_IN_STATIC_POSITION and its
        -- structured payload, without also reporting the less specific
        -- value-dependent-quantity mismatch.
        quantityType <- globalValueM (gPrel "Quantity") []
        void (check (withVarReadBlock VarReadStaticPosition ctx) expression quantityType)
      Nothing | ((name, _) : _) <- runtimeOccurrences ->
        report $
          withPayload
            ( withPayloadField "runtimeDependency" (nameText name) $
                payloadKind "value-dependent-quantity"
            ) $
            withRelated (related RoleUseSite (nameSpan name) "object-phase value used by this quantity expression") $
              diag SevError StageElaborate "E_TYPE_EQUALITY_MISMATCH"
                (Just "kappa.type.mismatch") (exprSpan expression)
                "a portable-v1 binder quantity may not depend on an object-phase runtime value (§12.1.1, §12.2.10)"
      Nothing -> do
        quantityType <- globalValueM (gPrel "Quantity") []
        void (check (withVarReadBlock VarReadStaticPosition ctx) expression quantityType)
  _ -> pure ()

-- | The binder's annotation with suspension sugar applied: a
-- @(thunk x : T)@ binder has type @Thunk T@ (§16.2.4).
binderTypeExpr :: Binder -> Maybe Expr
binderTypeExpr b = case (bSusp b, bType b) of
  (Just SuspThunk, Just t) ->
    Just (EApp (EVar (Name "Thunk" (bSpan b))) [ArgExplicit t])
  (Just SuspLazy, Just t) ->
    Just (EApp (EVar (Name "Need" (bSpan b))) [ArgExplicit t])
  (_, mt) -> mt

-- | Reject the superseded bounded-binder dialect @(u : TypeLevel < k)@ at
-- the shared binder boundary and recover as @(u : TypeLevel)@. Recognition
-- is gated by resolved declaration identity: a shadowed/user-defined
-- @TypeLevel@ or @<@ is an ordinary expression and receives its ordinary
-- diagnostics. Bounds in portable v1 are separate erased proof binders.
normalizeBinderDomain :: Ctx -> Binder -> Expr -> CheckM Expr
normalizeBinderDomain ctx binder domain = fst <$> normalizeBinderDomainWithRecovery ctx binder domain

-- | Elaborate a binder annotation using the same proposition-coercion rule
-- as Pi formation. In particular, an implicit erased binder such as
-- @(@0 p : u < k)@ has the proposition type @(u < k) = True@ everywhere:
-- signatures, named definitions, and anonymous lambdas must not elaborate
-- the same source annotation through different typing rules.
inferBinderDomainType :: Ctx -> Binder -> Expr -> CheckM (Term, Level)
inferBinderDomainType ctx binder domain = withGeneralizableBareTypeLevels $ do
  normalized <- normalizeBinderDomain ctx binder domain
  if bImplicit binder
    then do
      (tm, lvl, _) <- inferTypeBoolProp' ctx normalized
      pure (tm, lvl)
    else inferType ctx normalized

normalizeBinderDomainWithRecovery :: Ctx -> Binder -> Expr -> CheckM (Expr, Bool)
normalizeBinderDomainWithRecovery ctx binder domain =
  case domain of
    EApp opHead [ArgExplicit levelTy@(EVar levelName), ArgExplicit _]
      | Just op <- operatorHeadName opHead
      , nameText op == "<"
      , nameText levelName == "TypeLevel"
      , isNothing (lookupCtx "<" ctx)
      , isNothing (lookupCtx "TypeLevel" ctx) -> do
          opIdentity <- lookupGlobalName "<"
          levelIdentity <- lookupGlobalName "TypeLevel"
          if opIdentity == Just (gPrel "<") && levelIdentity == Just prelTypeLevel
            then do
              errAt (bSpan binder) "E_UNIVERSE_LEVEL_EXPRESSION" (Just "kappa.universe.level-expression")
                "bounded level-binder syntax is not supported; bind TypeLevel and add a separate erased proof such as (@0 p : u < k) (§11.1.2.6)"
              pure (levelTy, True)
            else pure (domain, False)
    _ -> pure (domain, False)
  where
    operatorHeadName = \case
      EVar op -> Just op
      EOpRef _ op _ -> Just op
      _ -> Nothing

-- ── Elaboration ──────────────────────────────────────────────────────

insertAllImplicits :: Ctx -> Span -> Term -> Value -> CheckM (Term, Value)
insertAllImplicits ctx sp tm ty = do
  t <- forceM ty
  case t of
    VPiBoundM _ Impl q _ _ assumption dom clo -> do
      arg <- resolveImplicitQ ctx sp q dom
      argV <- evalIn ctx arg
      ty' <- clApp clo argV
      nextCtx <- extendLevelAssumptionFromSynthesized sp ctx assumption arg
      insertAllImplicits nextCtx sp (CApp Impl tm arg) ty'
    _ -> pure (tm, t)

-- | Expected-type-directed saturation for a bare polymorphic value. The
-- terminal result is unified before any value/evidence slot is committed, so
-- a slot whose classifier starts flexible is reclassified after the expected
-- type has fixed it. This is the zero-explicit-argument counterpart of
-- 'elabAppChecked': in particular, @witness : forall a. (@value : a) -> a@
-- checked at @Trait T@ must synthesize coherent @Trait T@ evidence rather than
-- leave an unconstrained erased value meta.
insertAllImplicitsAgainstExpected
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Value
  -> CheckM (Maybe Term)
insertAllImplicitsAgainstExpected initialCtx site headTerm headType expected = do
  baseline <- get
  align initialCtx headTerm headType expected >>= \case
    Nothing -> put baseline >> pure Nothing
    result -> pure result
  where
    -- A bare overloaded value may itself be checked at a polymorphic type:
    --
    --   empty : forall a. Alternative f => f a
    --   expected: forall m. m
    --
    -- Align the matching source and target binders before selecting the
    -- remaining evidence. This preserves the full source-visible member
    -- telescope (so explicit @a remains legal) while making omitted binders
    -- expected-directed. Formation and provenance are intentionally absent:
    -- like ordinary conversion, this rule compares the semantic function
    -- binder rather than metadata recording how that binder was elaborated.
    align activeCtx currentTerm sourceType targetType = do
      sourceShape <- peelCapturesM sourceType
      targetShape <- peelCapturesM targetType
      case (sourceShape, targetShape) of
        -- A completely flexible expectation does not establish that the
        -- caller wants the terminal result of an implicit telescope.  Keep
        -- the value first-class and constrain the expectation to its full
        -- inferred type.  Saturating here turns an endpoint such as a
        -- @forall@-function into an arbitrarily instantiated point before a
        -- surrounding dependent application can determine the carrier.
        -- Once the target has any rigid structure, the ordinary directed
        -- saturation rules below remain authoritative.
        (VPiBoundM _ Impl quantity _ _ _ domain _, VFlex _ []) -> do
          planning <-
            applicationImplicitIsPlanningParameter
              activeCtx
              quantity
              domain
          specializationHead <- case resolvedEtaTermHead currentTerm of
            Nothing -> pure False
            Just global -> gets $ \state ->
              Map.member global (csCtors state)
                || Map.member global (csTraitMemberOwners state)
                || Map.member global (csBareTraitMembers state)
          if planning && not specializationHead
            then do
              compatible <- unify activeCtx sourceShape targetShape
              pure (if compatible then Just currentTerm else Nothing)
            else saturate activeCtx currentTerm sourceShape targetType
        (_, VFlex _ []) -> do
          compatible <- unify activeCtx sourceShape targetShape
          pure (if compatible then Just currentTerm else Nothing)
        ( VPiEvidenceM sourceMode _sourceFormation Impl sourceQuantity sourceBorrowed _ sourceAssumption _sourceOrigin sourceDomain sourceClosure
          , VPiEvidenceM targetMode _targetFormation Impl targetQuantity targetBorrowed targetName targetAssumption _targetOrigin targetDomain targetClosure
          ) -> do
                sameDomain <- unifyDefinitional activeCtx sourceDomain targetDomain
                if not
                    ( sourceMode == targetMode
                        && sourceMode == Parametric
                        && sourceQuantity == Q0
                        && sourceQuantity == targetQuantity
                        && sourceBorrowed == targetBorrowed
                        && sourceAssumption == targetAssumption
                        && sameDomain
                    )
                  then pure Nothing
                  else do
                    withAssumption <-
                      extendLevelAssumption site activeCtx targetAssumption
                    let binderLevel = ctxLen activeCtx
                        rigid = VRigid binderLevel []
                        nextCtx =
                          bindCtxMQB
                            targetMode
                            targetQuantity
                            targetName
                            True
                            targetBorrowed
                            targetDomain
                            withAssumption
                        applied =
                          CApp Impl (shiftTerm 1 0 currentTerm) (CVar 0)
                    sourceResult <- clApp sourceClosure rigid
                    targetResult <- clApp targetClosure rigid
                    align nextCtx applied sourceResult targetResult >>= \case
                      Nothing -> pure Nothing
                      Just body ->
                        pure
                          ( Just
                              ( CLamM
                                  targetMode
                                  Impl
                                  targetQuantity
                                  targetName
                                  body
                              )
                          )
        (_, VPi {}) ->
          -- An application head is checked against the function type demanded
          -- by its remaining arguments. Evidence selection stays in
          -- 'elabAppChecked', where the complete spine can validate arity and
          -- roll back malformed calls without leaking speculative obligations.
          pure Nothing
        _ -> saturate activeCtx currentTerm sourceShape targetType

    saturate activeCtx currentTerm sourceType targetType = do
      (rawSlots, terminal) <- peel activeCtx sourceType []
      slots <- annotateDependencies rawSlots terminal
      if null slots
        then pure Nothing
        else do
          compatible <- unify activeCtx terminal targetType
          if not compatible
            then pure Nothing
            else rebuild currentTerm slots >>= \case
              Nothing -> pure Nothing
              Just saturated ->
                Just <$> coerceTerm activeCtx site saturated terminal targetType

    peel activeCtx currentType accumulated =
      forceM currentType >>= \case
        binder@(VPiBoundM mode icit quantity _ _ assumption domain closure) -> do
          omittedExplicit <-
            if icit == Expl && mode == Parametric && quantity == Q0
              then isKindLike (ctxLen activeCtx) domain
              else pure False
          if icit /= Impl && not omittedExplicit
            then pure (reverse accumulated, binder)
            else do
              placeholder <- freshMetaFor activeCtx domain
              placeholderValue <- evalIn activeCtx placeholder
              resultType <- clApp closure placeholderValue
              nextCtx <-
                extendLevelAssumptionFromSynthesized
                  site
                  activeCtx
                  assumption
                  placeholder
              peel
                nextCtx
                resultType
                (ExpectedImplicitSlot activeCtx icit quantity placeholder placeholderValue domain True : accumulated)
        terminal -> pure (reverse accumulated, terminal)

    rebuild current [] = pure (Just current)
    rebuild current (ExpectedImplicitSlot activeCtx icit quantity placeholder placeholderValue domain dependent : rest) = do
      argument <-
        resolveReclassifiedImplicit
          activeCtx
          site
          quantity
          placeholder
          placeholderValue
          domain
          dependent
      case argument of
        Nothing -> pure Nothing
        Just selected ->
          rebuild (CApp icit current selected) rest

    annotateDependencies slots terminal =
      forM (zip [0 :: Int ..] slots) $ \(index, slot) -> do
        let laterDomains =
              [ laterDomain
              | ExpectedImplicitSlot _ _ _ _ _ laterDomain _ <-
                  drop (index + 1) slots
              ]
        dependencies <-
          fmap concat (mapM unsolvedMetaIdsIn (terminal : laterDomains))
        pure $
          case slot of
            ExpectedImplicitSlot activeCtx icit quantity placeholder placeholderValue domain _ ->
              let placeholderMeta = case placeholder of
                    CMeta meta -> Just meta
                    _ -> Nothing
               in ExpectedImplicitSlot
                    activeCtx
                    icit
                    quantity
                    placeholder
                    placeholderValue
                    domain
                    (maybe True (`elem` dependencies) placeholderMeta)

data ExpectedImplicitSlot = ExpectedImplicitSlot
  !Ctx
  !Icit
  !Q
  !Term
  !Value
  !Value
  !Bool

-- | Select an implicit after surrounding constraints have had a chance to
-- solve its classifier. Kind-like and ordinary erased inference slots retain
-- their placeholder. A slot that has become a trait/proposition (or any
-- runtime implicit) enters the normal evidence ladder, and the selected value
-- is reconciled with the placeholder already threaded through later domains
-- and the terminal result.
resolveReclassifiedImplicit
  :: Ctx
  -> Span
  -> Q
  -> Term
  -> Value
  -> Value
  -> Bool
  -> CheckM (Maybe Term)
resolveReclassifiedImplicit ctx site quantity placeholder placeholderValue domain dependent = do
  domain' <- forceM domain
  kindLike <- isKindLike (ctxLen ctx) domain'
  traitLike <- isTraitGoal domain'
  equalityLike <- isEqGoal domain'
  rowLike <- isRowGoal domain'
  levelLike <- isJust <$> authenticatedLevelGoalRelation ctx domain'
  let requiresResolution =
        quantity /= Q0
          || traitLike
          || equalityLike
          || rowLike
          || levelLike
  selected <-
    if kindLike || not requiresResolution
      then pure placeholder
      else
        if equalityLike
          then resolveLocalOrPostponeEqualityEvidence ctx site quantity domain'
          else resolveImplicitQ ctx site quantity domain'
  selectedValue <- checkedArgumentValue ctx site domain' selected
  reconciled <-
    if not dependent
      then pure True
      else do
        placeholderForced <- forceM placeholderValue
        case (placeholder, placeholderForced) of
          (CMeta expectedMeta, VFlex actualMeta [])
            | expectedMeta == actualMeta -> do
                solved <- solveMetaAcyclic expectedMeta selectedValue
                if solved
                  then pure True
                  else unify ctx placeholderForced selectedValue
          _ -> unify ctx placeholderForced selectedValue
  when kindLike (validateInferredKindArgument ctx site placeholder domain')
  pure (if reconciled then Just selected else Nothing)

-- | Equality implicit selection follows §16.3.3's ordinary local-first rule.
-- An exact lexical proof is stable and must win immediately. Only when no such
-- proof exists do we delay the slot: a branch fact can contain selected
-- dictionary metas that settle at the enclosing declaration boundary, and
-- resolving that non-local proof eagerly would compare the wrong
-- pre-settlement fact key. Both expected-directed saturation and ordinary
-- application planning use this one timing rule.
resolveLocalOrPostponeEqualityEvidence
  :: Ctx
  -> Span
  -> Q
  -> Value
  -> CheckM Term
resolveLocalOrPostponeEqualityEvidence ctx site quantity goal =
  localCandidate ctx site quantity goal >>= \case
    Just proof -> recordSelectedUniverseEvidence ctx goal proof >> pure proof
    Nothing -> postponeEqualityEvidence ctx site goal

postponeEqualityEvidence :: Ctx -> Span -> Value -> CheckM Term
postponeEqualityEvidence ctx site goal = do
  (meta, placeholder) <- freshMetaForWithId ctx goal
  facts <- gets csBoolFacts
  modify' $ \state ->
    state {csPending = (meta, goal, site, ctx, facts) : csPending state}
  pure placeholder

-- | Discharge only the authenticated declaration-constraint prefix of a
-- global interface. Compiler-generated consumers often know the following
-- declaration-specific implicit arguments already; feeding those directly to
-- the raw head would instead consume the first hidden 'LevelLe' proof slot.
-- The authenticated assumption plus 'BinderGenerated' provenance is typed
-- Core authority for this prefix, so this does not rely on generated binder
-- names or source spelling and never skips a source-written proof binder.
insertDeclarationConstraintImplicits
  :: Ctx -> Span -> Term -> Value -> CheckM (Term, Value)
insertDeclarationConstraintImplicits ctx sp tm ty = do
  forced <- forceM ty
  case forced of
    VPiEvidenceM _ _ Impl q _ _ assumption@(Just _) BinderGenerated domain closure -> do
      proof <- resolveImplicitQ ctx sp q domain
      proofValue <- checkedArgumentValue ctx sp domain proof
      resultType <- clApp closure proofValue
      nextCtx <- extendLevelAssumptionFromSynthesized sp ctx assumption proof
      insertDeclarationConstraintImplicits nextCtx sp (CApp Impl tm proof) resultType
    _ -> pure (tm, forced)

-- | Whether a bare derivation request has the rigid expected goal required by
-- §16.3.2A. Ordinary and universe metavariables both make the request
-- under-directed; an explicit @derive (G)@ is checked by the normal type
-- elaborator and does not use this guard.
deriveGoalRigid :: Ctx -> Value -> CheckM Bool
deriveGoalRigid _ goal =
  forceM goal >>= \case
    VFlex {} -> pure False
    _ -> pure True

-- | The unified expression-level derivation entry point (§16.3.2A). This is
-- deliberately built from the checker's existing semantic authorities:
-- definitional conversion for exact lexical facts, ordinary trait evidence,
-- checked proposition solvers, and the purpose-keyed inhabitance analysis.
-- No source spelling is proof authority, and every selected local remains an
-- ordinary Core variable so QTT/borrow checking sees its real use.
synthesizeDerivation :: Ctx -> Span -> Value -> CheckM Term
synthesizeDerivation = synthesizeDerivationWithFuel 32

-- | Bounded derivation search.  Independently-unique evidence can itself
-- contain trait-valued fields, so construction participates in the same
-- search budget as Pi introduction.  Exhaustion is a normal fail-closed
-- derivation failure, never permission to invent a field.
synthesizeDerivationWithFuel :: Int -> Ctx -> Span -> Value -> CheckM Term
synthesizeDerivationWithFuel fuel ctx site goal0
  | fuel <= 0 = do
      goal <- forceM goal0
      goalTerm <- quoteIn ctx goal
      errAt site "E_DERIVE_UNSOLVED" (Just "kappa.derive")
        ("derivation search exhausted while solving " <> renderTerm goalTerm)
      freshMetaFor ctx goal
  | otherwise = synthesizeDerivationBody fuel ctx site goal0

synthesizeDerivationBody :: Int -> Ctx -> Span -> Value -> CheckM Term
synthesizeDerivationBody fuel ctx site goal0 = do
  goal <- forceM goal0
  exact <- exactDerivationLocals ctx goal
  case exact of
    [candidate] -> selectExact goal candidate
    first : rest -> do
      coherent <- derivationGoalCoherent ctx site goal
      if coherent
        then selectExact goal first
        else do
          equality <- isEqGoal goal
          let code =
                if equality
                  then "E_DERIVE_PROOF_RELEVANT_CHOICE"
                  else "E_DERIVE_AMBIGUOUS"
              names = map (ceName . snd) (first : rest)
          report $
            withPayload
              (withPayloadField "candidates" (T.intercalate ", " names) $
                payloadKind "derive-ambiguous") $
              diag SevError StageElaborate code (Just "kappa.derive") site
                "derivation would have to choose observably among distinct local inhabitants (§16.3.2A)"
          freshMetaFor ctx goal
    [] -> deriveWithoutExact goal
  where
    selectExact goal (index, entry)
      | ceName entry `elem` ["_", "_ev"] = pure (CVar index)
      | otherwise = do
          let expansion = EVar (Name (ceName entry) site)
          modify' $ \state ->
            state
              { csExpansions =
                  Map.insert site expansion (csExpansions state)
              }
          check ctx expansion goal

    deriveWithoutExact goal = do
      traitGoal <- isTraitGoal goal
      existingEvidence <-
        if traitGoal
          then traitEvidence ctx site goal
          else pure Nothing
      case existingEvidence of
        Just term -> pure term
        Nothing -> do
          structuralEvidence <-
            if traitGoal
              then
                isPropClosure ctx site goal >>= \case
                  Just evidence -> pure (Just evidence)
                  Nothing ->
                    hLevelProviderDerivation
                      (synthesizeDerivationWithFuel (fuel - 1))
                      ctx
                      site
                      goal
              else pure Nothing
          case structuralEvidence of
            Just term -> pure term
            Nothing -> do
              constructed <-
                if traitGoal
                  then
                    constructIndependentlyUniqueEvidence
                      (synthesizeDerivationWithFuel (fuel - 1))
                      ctx
                      site
                      goal
                  else pure Nothing
              maybe (deriveByIntroduction traitGoal goal) pure constructed

    deriveByIntroduction traitGoal goal =
      forceM goal >>= \case
            VPiBoundM mode icit quantity borrowed name assumption domain closure -> do
              withAssumption <- extendLevelAssumption site ctx assumption
              let level = ctxLen ctx
                  nextCtx =
                    bindCtxMQB
                      mode
                      quantity
                      name
                      (icit == Impl)
                      borrowed
                      domain
                      withAssumption
              codomain <- clApp closure (VRigid level [])
              body <- synthesizeDerivationWithFuel (fuel - 1) nextCtx site codomain
              pure (CLamM mode icit quantity name body)
            _ -> do
              proved <- propProof ctx goal
              case proved of
                Just proof -> pure proof
                Nothing
                  | traitGoal -> unsolved goal
                  | otherwise -> do
                      representative <- inhabContractibleRepresentative ctx goal
                      case representative of
                        Just term -> pure term
                        Nothing -> do
                          environment <- mkInhabEnv ctx
                          summary <-
                            inhabitanceSummary environment SourceReachability goal
                          case summary of
                            Finite _ -> do
                              errAt site "E_DERIVE_AMBIGUOUS" (Just "kappa.derive")
                                "the derivation goal has several observable inhabitants (§16.3.2A)"
                              freshMetaFor ctx goal
                            _ -> unsolved goal

    unsolved goal = do
      goalTerm <- quoteIn ctx goal
      errAt site "E_DERIVE_UNSOLVED" (Just "kappa.derive")
        ("no admissible derivation plan solved " <> renderTerm goalTerm)
      freshMetaFor ctx goal

-- | Construct one complete dictionary only for a trait whose independently
-- checked uniqueness certificate authorizes fresh evidence (§14.1.1A).  The
-- certificate does not inhabit fields: every supertrait and member is solved
-- in declaration order from its exact generated projection type.  Failure is
-- transactional so ordinary derivation can issue the single root diagnostic.
constructIndependentlyUniqueEvidence
  :: (Ctx -> Span -> Value -> CheckM Term)
  -> Ctx
  -> Span
  -> Value
  -> CheckM (Maybe Term)
constructIndependentlyUniqueEvidence recurse ctx site goal = do
  normalized <- forceM goal
  state <- get
  case normalized of
    VGlobI trait traitUniverses arguments
      | Just info <- Map.lookup trait (csTraits state)
      , tiEvidenceConstructionMode info == IndependentlyUnique
      , Just semanticArguments <- traitSemanticSpineIn state trait arguments -> do
          baseline <- get
          fields <-
            constructSupers
              trait
              traitUniverses
              semanticArguments
              []
              (tiSupers info)
          result <- case fields of
            Nothing -> pure Nothing
            Just supers ->
              constructMembers
                info
                trait
                traitUniverses
                semanticArguments
                supers
                (tiMembers info)
          diagnostics <- gets csDiags
          if isJust result && length diagnostics == length (csDiags baseline)
            then pure (CRecordV . sortOn fst <$> result)
            else put baseline >> pure Nothing
    _ -> pure Nothing
  where
    constructSupers _ _ _ done [] = pure (Just done)
    constructSupers trait traitUniverses semanticArguments done ((field, closedGoal) : rest) = do
      evaluation <- ec_
      specialized <- specializeDeclarationComponent trait traitUniverses closedGoal
      function <- evalIn ctx specialized
      superGoal <-
        forceM
          ( evalApp
              evaluation
              function
              [(Expl, argument) | (_, argument) <- semanticArguments]
          )
      proof <- recurse ctx site superGoal
      constructSupers trait traitUniverses semanticArguments (done ++ [(field, proof)]) rest

    constructMembers _ _ _ _ done [] = pure (Just done)
    constructMembers info trait traitUniverses semanticArguments done (member : rest) = do
      memberType <-
        instantiateTraitMemberType
          ctx
          site
          trait
          traitUniverses
          member
          (map snd semanticArguments)
          done
      proof <- recurse ctx site memberType
      constructMembers info trait traitUniverses semanticArguments (done ++ [(member, proof)]) rest

-- | Exact lexical candidates include explicit as well as implicit locals, as
-- required by §16.3.2A. Conversion is a read-only query over the current
-- semantic environment; shadowed spellings and mutable-cell roots are not
-- silently turned into current-value reads.
exactDerivationLocals :: Ctx -> Value -> CheckM [(Int, CtxEntry)]
exactDerivationLocals ctx goal =
  fmap catMaybes . forM visible $ \candidate@(_, entry) -> do
    saved <- get
    matches <- unify ctx (ceType entry) goal
    put saved
    pure (candidate <$ guard matches)
  where
    visible = go Set.empty 0 (ctxEntries ctx)
    go _ _ [] = []
    go shadowed index (entry : rest)
      | ceName entry `Set.member` shadowed =
          go shadowed (index + 1) rest
      | otherwise =
          let name = ceName entry
              shadowed' =
                if name `elem` ["_", "_ev"]
                  then shadowed
                  else Set.insert name shadowed
              candidate =
                isNothing (ceVarInfo entry)
                  && name /= "this"
           in (if candidate then [(index, entry)] else [])
                ++ go shadowed' (index + 1) rest

-- | Bounded focused elimination over lexical terms. A candidate is selected
-- only by its checked Pi type: leading arguments are discharged by checked
-- local values, and the resulting codomain must unify with the requested
-- goal. The selected source application is then elaborated normally and
-- recorded as the derive expansion, so QTT and borrow analysis account for
-- every local use. This is the common leaf rule for structural providers such
-- as pointwise h-level closure; neither candidate nor argument spelling is
-- semantic authority.
focusedLocalDerivation :: Int -> Ctx -> Span -> Value -> CheckM (Maybe Term)
focusedLocalDerivation sourceDepth ctx site goal =
  focusedDerivation sourceDepth ctx site goal localRoots
  where
    localRoots =
      [ (CVar index, Just expression, dependencies, ceType entry)
      | (index, entry) <- visibleDerivationLocals ctx
      , let expression = EVar (Name (ceName entry) site)
            dependencies =
              [ expression
              | ctxLen ctx - 1 - index < sourceDepth
              ]
      ]

-- | Apply only compiler-owned structural providers, by resolved global
-- identity and checked type. This is deliberately the same focused planner as
-- lexical theorem application: provider names never participate in matching,
-- and all source-local arguments remain visible to QTT/borrow analysis.
hLevelProviderDerivation
  :: (Ctx -> Span -> Value -> CheckM Term)
  -> Ctx
  -> Span
  -> Value
  -> CheckM (Maybe Term)
hLevelProviderDerivation recurse ctx site goal = do
  normalized <- forceM goal
  state <- get
  case normalized of
    VGlobI trait _ arguments
      | trait == prelIsSet
      , Just [(_, carrier)] <- traitSemanticSpineIn state trait arguments -> do
          roots <- fmap catMaybes . forM providerIdentities $ \provider ->
            globalTypeIn ctx site provider >>= \case
              Just (term, ty) -> pure (Just (term, Nothing, [], ty))
              Nothing -> pure Nothing
          focusedDerivation (ctxLen ctx) ctx site goal roots >>= \case
            Just evidence -> pure (Just evidence)
            Nothing ->
              derivePiClosure carrier >>= \case
                Just evidence -> pure (Just evidence)
                Nothing -> deriveEqHedbergClosure carrier
    _ -> pure Nothing
  where
    providerIdentities =
      [ gPrel "__deriveHedbergProvider"
      , gPrel "__derivePiIsSetProvider"
      , gPrel "__deriveSigmaIsSetProvider"
      ]

    -- The focused planner above consumes a complete pointwise proof when one
    -- is already lexical.  Ordinary structural closure must also be able to
    -- /construct/ that proof.  Do so only through the exact compiler-owned Pi
    -- provider and its checked ABI: an ordinary, explicit, unrestricted,
    -- unborrowed dependent function.  Other Pi modes remain outside this
    -- provider's contract and fail closed rather than being coerced to it.
    derivePiClosure carrier = do
      carrier' <- forceM carrier
      case carrier' of
        VPiM Ordinary Expl QW False name domain closure -> do
          let depth = ctxLen ctx
              argument = VRigid depth []
              pointwiseCtx =
                bindCtxMQB Ordinary Q0 name True False domain ctx
          codomain <- clApp closure argument
          pointwiseGoal <-
            unaryTraitGoalForCarrier pointwiseCtx prelIsSet codomain
          case pointwiseGoal of
            Nothing -> pure Nothing
            Just fiberGoal -> do
              beforeFiber <- get
              diagnosticCount <- gets (length . csDiags)
              fiberEvidence <- recurse pointwiseCtx site fiberGoal
              diagnostics <- gets csDiags
              if length diagnostics /= diagnosticCount
                then put beforeFiber >> pure Nothing
                else do
                  ec <- ec_
                  globalTypeIn ctx site (gPrel "__derivePiIsSetProvider") >>= \case
                    Nothing -> pure Nothing
                    Just (provider, _) -> do
                      let domainTerm = quote ec depth domain
                          familyTerm =
                            quote ec depth
                              (VLamM Ordinary Expl QW name closure)
                          pointwiseTerm =
                            CLamM Ordinary Impl Q0 name fiberEvidence
                      pure . Just $
                        CApp Expl
                          (CApp Impl
                            (CApp Impl provider domainTerm)
                            familyTerm)
                          pointwiseTerm
        _ -> pure Nothing

    -- A completed @Eq a@ dictionary contains precisely the data needed by
    -- Hedberg: its checked comparator plus @eqSound@/@eqComplete@ construct a
    -- @Reflects (x = y) (x == y)@ value through the ordinary @eqReflect@
    -- theorem, and @reflectsDec@ turns that certificate into @Dec (x = y)@.
    -- Compose those checked declarations with the existing compiler-owned
    -- Hedberg provider.  No trait/member spelling is inspected: every global
    -- and dictionary facet is selected by resolved identity and checked
    -- against its telescope.  The candidate is transactional because an
    -- incomplete Eq dictionary must not leave metas or diagnostics behind.
    deriveEqHedbergClosure carrier = do
      baseline <- get
      diagnosticCount <- gets (length . csDiags)
      result <- buildEqHedbergClosure carrier
      diagnostics <- gets csDiags
      if isJust result && length diagnostics == diagnosticCount
        then pure result
        else put baseline >> pure Nothing

    buildEqHedbergClosure carrier = do
      unaryTraitGoalForCarrier ctx (gPrel "Eq") carrier >>= \case
        Nothing -> pure Nothing
        Just eqGoal -> do
          traitEvidence ctx site eqGoal >>= \case
            Nothing -> pure Nothing
            Just eqEvidence ->
              globalTypeIn ctx site (gPrel "__deriveHedbergProvider") >>= \case
                Nothing -> pure Nothing
                Just (provider, providerType) -> do
                  carrierTerm <- quoteIn ctx carrier
                  typeValueClassifierLevel ctx carrier >>= \case
                    Nothing -> pure Nothing
                    Just carrierLevel -> do
                      (providerAtCarrier, providerAtCarrierType) <-
                        applyGeneratedCoreSpine
                          ctx
                          site
                          provider
                          providerType
                          [(Impl, carrierTerm, VSort carrierLevel)]
                      forceM providerAtCarrierType >>= \case
                        VPiBoundM _ Expl _ _ _ _ decisionType resultClosure -> do
                          buildEqDecision carrier eqGoal eqEvidence decisionType >>= \case
                            Nothing -> pure Nothing
                            Just decision -> do
                              resultType <- clApp resultClosure =<< evalIn ctx decision
                              (proof, actualType) <-
                                applyGeneratedCoreSpine
                                  ctx
                                  site
                                  providerAtCarrier
                                  providerAtCarrierType
                                  [(Expl, decision, decisionType)]
                              exact <- unifyDefinitional ctx actualType resultType
                              goalExact <- unifyDefinitional ctx actualType goal
                              pure (proof <$ guard (exact && goalExact))
                        _ -> pure Nothing

    -- Build the decision procedure against the provider's exact checked
    -- domain.  This validates modes, borrowed inputs, and result type before
    -- constructing either lambda; a future prelude ABI change therefore
    -- disables the candidate instead of manufacturing ill-typed Core.
    buildEqDecision carrier eqGoal eqEvidence decisionType =
      forceM decisionType >>= \case
        VPiBoundM modeX Expl quantityX True nameX _ domainX closureX -> do
          domainMatches <- unifyDefinitional ctx domainX carrier
          if not domainMatches
            then pure Nothing
            else do
              let depth = ctxLen ctx
                  ctxX =
                    bindCtxMQB
                      modeX
                      quantityX
                      nameX
                      False
                      True
                      domainX
                      ctx
                  xValue = VRigid depth []
              clApp closureX xValue >>= forceM >>= \case
                VPiBoundM modeY Expl quantityY True nameY _ domainY closureY -> do
                  domainMatchesY <- unifyDefinitional ctxX domainY carrier
                  if not domainMatchesY
                    then pure Nothing
                    else do
                      let ctxY =
                            bindCtxMQB
                              modeY
                              quantityY
                              nameY
                              False
                              True
                              domainY
                              ctxX
                          yValue = VRigid (depth + 1) []
                      expectedResult <- clApp closureY yValue
                      reflectedDecision
                        ctxY
                        carrier
                        eqGoal
                        (shiftTerm 2 0 eqEvidence)
                        (CVar 1)
                        (CVar 0) >>= \case
                          Nothing -> pure Nothing
                          Just (body, bodyType) -> do
                            resultMatches <-
                              unifyDefinitional ctxY bodyType expectedResult
                            pure $
                              if resultMatches
                                then
                                  Just
                                    ( CLamM modeX Expl quantityX nameX
                                        (CLamM modeY Expl quantityY nameY body)
                                    )
                                else Nothing
                _ -> pure Nothing
        _ -> pure Nothing

    reflectedDecision activeCtx carrier eqGoal eqEvidence x y =
      typeValueClassifierLevel activeCtx carrier >>= \case
        Nothing -> pure Nothing
        Just carrierLevel -> do
          carrierTerm <- quoteIn activeCtx carrier
          globalTypeIn activeCtx site (gPrel "eqReflect") >>= \case
            Nothing -> pure Nothing
            Just (reflect, reflectType) -> do
              (reflected, reflectedType) <-
                applyGeneratedCoreSpine
                  activeCtx
                  site
                  reflect
                  reflectType
                  [ (Impl, carrierTerm, VSort carrierLevel)
                  , (Impl, eqEvidence, eqGoal)
                  , (Expl, x, carrier)
                  , (Expl, y, carrier)
                  ]
              globalTypeIn activeCtx site (gPrel "reflectsDec") >>= \case
                Nothing -> pure Nothing
                Just (toDecision, toDecisionType) -> do
                  forceM reflectedType >>= \case
                    VGlobI reflects _ [(_, proposition), (_, boolean)]
                      | reflects == gPrel "Reflects" -> do
                          propositionTerm <- quoteIn activeCtx proposition
                          booleanTerm <- quoteIn activeCtx boolean
                          typeValueClassifierLevel activeCtx proposition >>= \case
                            Nothing -> pure Nothing
                            Just propositionLevel -> do
                              booleanType <- globalValueM prelBool []
                              (decision, decisionType) <-
                                applyGeneratedCoreSpine
                                  activeCtx
                                  site
                                  toDecision
                                  toDecisionType
                                  [ (Impl, propositionTerm, VSort propositionLevel)
                                  , (Impl, booleanTerm, booleanType)
                                  , (Expl, reflected, reflectedType)
                                  ]
                              pure (Just (decision, decisionType))
                    _ -> pure Nothing

-- | Shared typed application planner for lexical roots and exact
-- compiler-owned providers. A root optionally carries source syntax; when it
-- does, the final application is re-elaborated normally. Provider roots are
-- already checked globals and are assembled directly from typed Core
-- applications. In both cases every lexical argument is recorded as a source
-- dependency before usage checking.
focusedDerivation
  :: Int
  -> Ctx
  -> Span
  -> Value
  -> [(Term, Maybe Expr, [Expr], Value)]
  -> CheckM (Maybe Term)
focusedDerivation sourceDepth ctx site goal roots = do
  baseline <- get
  select baseline roots >>= \case
    Nothing -> put baseline >> pure Nothing
    Just (term, expression, dependencies) -> do
      selected <- maybe (pure term) (\source -> check ctx source goal) expression
      forM_ (dependencyExpression dependencies) $ \expansion ->
        modify' $ \state ->
          state
            { csExpansions = Map.insert site expansion (csExpansions state)
            }
      pure (Just selected)
  where
    select _ [] = pure Nothing
    select baselineState ((term, expression, dependencies, candidateType) : rest) = do
      put baselineState
      plan 8 term expression dependencies candidateType >>= \case
        Just selected -> pure (Just selected)
        Nothing -> select baselineState rest

    plan 0 _ _ _ _ = pure Nothing
    plan fuel term expression dependencies candidateType = do
      beforeGoal <- get
      matches <- unify ctx candidateType goal
      if matches
        then pure (Just (term, expression, dependencies))
        else do
          put beforeGoal
          forceM candidateType >>= \case
            VPiBoundM _ icit _ _ _ _ domain closure ->
              applyOne fuel icit term expression dependencies domain closure arguments
            _ -> pure Nothing

    arguments = visibleDerivationLocals ctx

    applyOne _ _ _ _ _ _ _ [] = pure Nothing
    applyOne fuel icit term expression dependencies domain closure ((argumentIndex, argumentEntry) : rest) = do
      beforeArgument <- get
      matches <- unify ctx (ceType argumentEntry) domain
      if matches
        then do
          let argumentLevel = ctxLen ctx - 1 - argumentIndex
              argumentExpression = EVar (Name (ceName argumentEntry) site)
          codomain <- clApp closure (VRigid argumentLevel [])
          let appliedTerm = CApp icit term (CVar argumentIndex)
              appliedExpression =
                fmap
                  ( \source ->
                      EApp source
                        [ case icit of
                            Impl -> ArgImplicit argumentExpression
                            Expl -> ArgExplicit argumentExpression
                        ]
                  )
                  expression
              appliedDependencies =
                dependencies
                  ++ [ argumentExpression
                     | argumentLevel < sourceDepth
                     ]
          plan (fuel - 1) appliedTerm appliedExpression appliedDependencies codomain >>= \case
            Just selected -> pure (Just selected)
            Nothing -> put beforeArgument >> applyOne fuel icit term expression dependencies domain closure rest
        else put beforeArgument >> applyOne fuel icit term expression dependencies domain closure rest

    dependencyExpression = \case
      [] -> Nothing
      [expression] -> Just expression
      expressions -> Just (ETuple expressions site)

visibleDerivationLocals :: Ctx -> [(Int, CtxEntry)]
visibleDerivationLocals ctx = go Set.empty 0 (ctxEntries ctx)
  where
    go _ _ [] = []
    go shadowed index (entry : rest)
      | ceName entry `Set.member` shadowed =
          go shadowed (index + 1) rest
      | otherwise =
          let name = ceName entry
              referenceable =
                name `notElem` ["_", "_ev", "this"]
                  && isNothing (ceVarInfo entry)
              shadowed' = Set.insert name shadowed
           in (if referenceable then [(index, entry)] else [])
                ++ go shadowed' (index + 1) rest

-- | Multiple exact inhabitants may be merged only when the goal is already
-- known coherent: authenticated trait evidence, direct h-level evidence, or
-- the structural IsProp closure. The query never assumes UIP for arbitrary
-- equality fibers.
derivationGoalCoherent :: Ctx -> Span -> Value -> CheckM Bool
derivationGoalCoherent ctx site goal = do
  traitGoal <- isTraitGoal goal
  if traitGoal
    then pure True
    else do
      direct <- hLevelTraitEvidence ctx site prelIsProp goal
      case direct of
        Just _ -> pure True
        Nothing -> do
          propositionGoal <- globalValueM prelIsProp [(Expl, goal)]
          isJust <$> isPropClosure ctx site propositionGoal

-- | Synthesize a type for @expr@, elaborating it to a core 'Term' along the
-- way. Used wherever the term determines its own type (a variable, literal,
-- application, projection, …). The dual is 'check'. This is a long @case@
-- over 'Expr' constructors — one (or a few) arms per surface form, in
-- roughly the 'Expr' family order from "Kappa.Syntax"; the arms that need
-- an expected type to proceed (a bare lambda, say) defer to 'check'.
infer :: Ctx -> Expr -> CheckM (Term, Value)
infer ctx expr = case expr of
  EDerive Nothing sp -> do
    errAt sp "E_DERIVE_EXPECTED_TYPE_REQUIRED" (Just "kappa.derive")
      "bare 'derive' requires a rigid expected type (§16.3.2A)"
    anyHole ctx
  EDerive (Just goalExpression) sp -> do
    (goalTerm, _) <- inferType ctx goalExpression
    goal <- evalIn ctx goalTerm
    term <- synthesizeDerivation ctx sp goal
    pure (term, goal)
  EUniverseInstantiation base universes sp ->
    inferUniverseInstantiation False ctx base universes sp
  EApp (EVar n) arguments@[ArgExplicit levelExpr]
    | nameText n == "Type" -> do
        bound <- nameHasOrdinaryBinding ctx n
        if bound
          then do
            (function, functionType) <- resolveOrdinaryTermName ctx n
            elabSpine ctx (nameSpan n) function functionType arguments
          else inferUniverseApp ctx levelExpr
  -- §21.4: a hygienic capture occurrence in spliced syntax refers to
  -- its recorded binder by level, immune to later shadowing
  EVar n
    | Just (lvl, ty) <- Map.lookup (nameText n) (ctxHyg ctx) ->
        pure (CVar (ctxLen ctx - 1 - lvl), ty)
  -- §13.2.1 sibling references: inside a dependent record type,
  -- literal, or update, an unshadowed 'this' denotes the record
  EVar n
    | nameText n == "this"
    , Nothing <- lookupCtx "this" ctx -> do
        mthis <- gets csThis
        case mthis of
          Just (ThisType fields) ->
            pure (CGlob thisG, VRecordTQ (sortOn rfName fields))
          Just (ThisTraitSibs fields) ->
            pure (CGlob thisG, VRecordTQ (sortOn rfName fields))
          Just (ThisValue vals tys) ->
            pure (CRecordV (sortOn fst vals), VRecordTQ (sortOn rfName tys))
          Nothing -> resolveName ctx n
  EVar n
    | nameText n == "Type" -> do
        bound <- nameHasOrdinaryBinding ctx n
        if bound
          then resolveOrdinaryTermName ctx n
          else do
            level <- bareTypeLevel (nameSpan n)
            pure (CSort level, VSort (levelSucc level))
  -- §13.2.1: a bare identifier in a sibling-reference position is
  -- shorthand for 'this.label' when that reading is unambiguous (the
  -- name resolves to nothing else)
  EVar n
    | Nothing <- lookupCtx (nameText n) ctx
    , nameText n /= "this"
    , Nothing <- sortName (nameText n) -> do
        mthis <- gets csThis
        let sib = case mthis of
              Just (ThisType fields) -> isJust (find ((== nameText n) . rfName) fields)
              Just (ThisTraitSibs fields) -> isJust (find ((== nameText n) . rfName) fields)
              Just (ThisValue _ tys) -> isJust (find ((== nameText n) . rfName) tys)
              Nothing -> False
            -- §14.2.1: trait-body sibling members shadow globals
            override = case mthis of
              Just (ThisTraitSibs _) -> True
              _ -> False
        mg <- lookupGlobalName (nameText n)
        if sib && (override || isNothing mg)
          then case mthis of
            -- §14.2.1: an associated static member projects from the trait
            -- evidence directly — NOT via the user-spellable name 'this',
            -- which a member parameter may shadow (e.g. Iterator's
            -- @next : (1 this : it) -> Option (item : Item, rest : it)@,
            -- whose `this` binder must not capture the sibling `Item`).
            Just (ThisTraitSibs fields)
              | Just field <- find ((== nameText n) . rfName) fields ->
                  pure (CProjM (rfMode field) (CGlob thisG) (nameText n), rfType field)
            _ -> infer ctx (EDot (EVar (Name "this" (nameSpan n))) (DotName n))
          else do
            st <- get
            case resolveModuleObjectName st (nameText n) of
              Just moduleName -> pure (moduleObjectFor moduleName)
              Nothing -> resolveName ctx n
  EVar n
    | Just lvl <- sortName (nameText n) -> do
        bound <- nameHasOrdinaryBinding ctx n
        if bound
          then resolveOrdinaryTermName ctx n
          else pure (CSort lvl, VSort (levelSucc lvl))
    | Just (_, e) <- lookupCtx (nameText n) ctx
    , Just _ <- ceVarInfo e -> varReadBlocked ctx n (nameSpan n)
    | otherwise -> resolveName ctx n
  ERefFacet n sp -> inferRefFacet ctx n sp
  EVarRead n sp -> inferVarRead ctx n sp
  EHole mn sp -> do
    -- §16.3.2 inference direction: no expected type is known here, so the
    -- hole's type is a fresh meta (shared across occurrences for a named
    -- hole). It may still be solved later by unification at the use site.
    -- Named-hole diagnostics are therefore committed only at the enclosing
    -- declaration boundary; anonymous @_@ is never a solvable shared
    -- obligation and remains an immediate user hole.
    (tm, ty, _) <- holeMetas ctx mn sp
    when (isNothing mn) $ do
      tyT <- quoteIn ctx ty
      reportUnsolvedHole ctx mn sp tyT
    pure (tm, ty)
  EIntLit v msuf sp -> elabIntLit ctx v msuf sp Nothing
  EFloatLit v msuf sp -> elabFloatLit ctx v msuf sp Nothing
  EStringLit sl parts sp -> elabString ctx sl parts sp
  EQuotedLit ql sp
    | Nothing <- qlPrefix ql
    , Just txt <- qlText ql
    , [c] <- T.unpack txt -> do
        scalar <- globalValueM prelUnicodeScalar []
        pure (CLit (LitScalar c), scalar)
    -- §6.5 conventional 'g' handler: requires a text view containing
    -- exactly one extended grapheme cluster (UAX #29, pinned UCD).
    | Just "g" <- qlPrefix ql ->
        case qlText ql of
          Just txt
            | isSingleGrapheme txt -> do
                grapheme <- globalValueM prelGrapheme []
                pure (CLit (LitGrapheme txt), grapheme)
            | T.null txt -> badGrapheme sp "the payload is empty"
            | otherwise ->
                badGrapheme sp
                  "the payload does not contain exactly one extended grapheme cluster"
          Nothing -> badGrapheme sp "the payload has no valid text view"
    -- §6.5 conventional 'b' handler: requires a byte view containing
    -- exactly one byte.
    | Just "b" <- qlPrefix ql ->
        case qlBytes ql of
          Just [w] -> do
            byte <- globalValueM prelByte []
            pure (CLit (LitByte w), byte)
          Just [] -> badByte sp "the payload is empty"
          Just _ -> badByte sp "the payload contains more than one byte"
          Nothing -> badByte sp "the payload has no single-byte view"
    | otherwise -> snd <$> ((,) () <$> unsupported ctx sp "this quoted-literal form")
  EUnit _ -> do
    unit <- globalValueM prelUnit []
    unitTerm <- generatedCtorAtM ctx unit prelUnit
    pure (unitTerm, unit)
  ETuple es _ -> do
    rs <- mapM (infer ctx) es
    let fields = [(tupleField i, tm) | (i, (tm, _)) <- zip [0 :: Int ..] rs]
        ftys = [(tupleField i, ty) | (i, (_, ty)) <- zip [0 :: Int ..] rs]
    pure (CRecordV fields, VRecordT ftys)
  ERecordLit items sp -> elabRecordLit ctx items sp
  ERecordType fs mtail sp -> do
    let names = [nameText (rtfName f) | f <- fs]
    -- §13.2.1: bare sibling-reference shorthand counts toward the
    -- field-dependency graph when the bare reading is unambiguous
    bareSibs <-
      filterM
        (\l -> do
           mg <- lookupGlobalName l
           pure (isNothing mg && isNothing (lookupCtx l ctx) && isNothing (sortName l)))
        names
    let baseDeps f =
          nub
            ( [l | l <- surfaceThisRefs (rtfType f), l `elem` names]
                ++ [l | l <- surfaceVarNames (rtfType f), l `elem` bareSibs]
            )
        dependencyMap = Map.fromList [(nameText (rtfName f), baseDeps f) | f <- fs]
        evidenceProviders =
          [ nameText (rtfName f)
          | f <- fs
          , rtfImplicit f
          , surfaceQuantityZero (bpQuantity (rtfPrefix f))
          ]
        reaches start target = go Set.empty start
          where
            go seen current
              | current == target = True
              | current `Set.member` seen = False
              | otherwise =
                  any (go (Set.insert current seen)) (Map.findWithDefault [] current dependencyMap)
        deps f =
          let label = nameText (rtfName f)
           in nub
                ( baseDeps f
                    ++ [ provider
                       | provider <- evidenceProviders
                       , provider /= label
                       , not (reaches provider label)
                       ]
                )
        ordered = topoFields [(nameText (rtfName f), deps f, f) | f <- fs]
    forM_ (duplicatesOf names) $ \n ->
      errAt sp "E_RECORD_DUPLICATE_FIELD" (Just "kappa-hs.record.duplicate-field")
        ("record type has duplicate field '" <> n <> "'")
    -- §13.2.1: an explicit field type of an open record may not refer
    -- to a field that would come only from the residual row
    let residualRefs =
          if isJust mtail
            then nub [(nameText (rtfName f), l) | f <- fs, l <- surfaceThisRefs (rtfType f), l `notElem` names]
            else []
    forM_ residualRefs $ \(fn, l) ->
      errOnce sp "E_RECORD_DEPENDENCY_INVALID" (Just "kappa-hs.record.dependency-invalid")
        ( "the explicit field '" <> fn <> "' refers to '" <> l
            <> "', which is not an explicitly listed field of this open record (§13.2.1)"
        )
    -- recovery: the invalid labels stand for opaque placeholders so
    -- the rest of the telescope still elaborates
    phantoms <- forM (nub (map snd residualRefs)) $ \l -> RecordField l Ordinary FormationOrdinary QW Nothing <$> freshMetaV ctx
    case ordered of
      Nothing -> do
        errAt sp "E_RECORD_DEPENDENCY_CYCLE" (Just "kappa-hs.record.dependency-cycle")
          "the field-dependency graph of this record type contains a cycle (§13.2.1)"
        fields <- forM names $ \n -> RecordField n Ordinary FormationOrdinary QW Nothing <$> freshMeta
        finish LZero fields
      Just fsOrdered -> do
        -- §13.2.1: elaborate the telescope in dependency order; later
        -- field types see earlier fields through 'this'
        fields <- goDep ctx phantoms fsOrdered
        -- §11.1: the record type lives in the max universe level of its
        -- field types (a `(ty : Type)` field forces Type1, not Type0).
        let lvl = foldr levelMax LZero [l | (_, _, _, _, _, _, l) <- fields]
        finish lvl [RecordField (nameText (rtfName f)) mode formation q bound t | (f, mode, formation, q, bound, t, _) <- fields]
     where
      goDep _ _ [] = pure []
      goDep levelCtx done (f : rest) = do
        -- §13.2.1: a record field's type sees earlier fields through
        -- 'this'. §14.2.1: when this record type appears INSIDE a trait
        -- member signature, the trait's associated static members must
        -- stay in scope too (e.g. Iterator's
        -- @next : … -> Option (item : Item, rest : it)@ projects the
        -- sibling @Item@), so keep the trait-sibling mode and add the
        -- record's own fields to it rather than shadowing it.
        outer <- gets csThis
        let thisMode = case outer of
              -- An existential/package payload record is flattened into the
              -- same signature telescope as its witnesses (§13.2.11).  Its
              -- fields therefore see both the outer witness prefix and the
              -- record fields already formed here through the same `this`
              -- root; replacing the outer mode would make valid witness
              -- references disappear while elaborating the payload.
              Just (ThisType sibs) -> ThisType (sibs ++ done)
              Just (ThisTraitSibs sibs) -> ThisTraitSibs (sibs ++ done)
              _ -> ThisType done
        -- §11.4.2: a record/tuple field whose declared type is a bare boolean
        -- expression (e.g. `ok : id == 1`) is coerced to `(id == 1) = True`.
        (t0, rawLvl) <- withThis (Just thisMode) (inferTypeBoolProp levelCtx (rtfType f))
        -- §13.2.1/§16.1.7.1: a suspension-marked field declares the
        -- suspension type; literals insert the suspension at the field
        t <- case rtfSusp f of
          Just SuspThunk -> globalAppM prelThunk [(Expl, t0)]
          Just SuspLazy -> globalAppM prelNeed [(Expl, t0)]
          Nothing -> pure t0
        tV <- evalIn levelCtx t
        let fieldBinder =
              Binder
                (rtfImplicit f)
                (rtfPrefix f)
                (rtfSusp f)
                NoReceiver
                False
                (Just (rtfName f))
                False
                (Just (rtfType f))
                Nothing
                (nameSpan (rtfName f))
        (mode, q) <- resolveBinderModeQ levelCtx fieldBinder tV QW
        when (rtfOpaque f && q /= Q0) $
          errAt (nameSpan (rtfName f)) "E_QTT_QUANTITY_UNSATISFIED" (Just "kappa.quantity.unsatisfied")
            "an opaque record member must have quantity 0 in portable v1 (§13.2.1)"
        formation <- selectFormationMode levelCtx mode tV
        let contributed = formationContribution formation rawLvl
            (t', lvl) = case formation of
              FormationParametric -> (t, contributed)
              FormationOrdinary -> formationCeilingTerm levelCtx contributed t
        unless (null (levelFields lvl)) $
          reportUnboundedTelescope levelCtx (nameSpan (rtfName f)) "record telescope" (nameText (rtfName f)) lvl
        mBound <-
          withThis (Just thisMode) (levelAssumptionFromExpr levelCtx (Just t') (rtfType f))
        nextCtx0 <- extendLevelAssumption (nameSpan (rtfName f)) levelCtx mBound
        nextCtx <- registerLevelField nextCtx0 (nameText (rtfName f)) tV
        let field = RecordField (nameText (rtfName f)) mode formation q mBound tV
        ((f, mode, formation, q, mBound, t', lvl) :) <$> goDep nextCtx (field : done) rest
      finish lvl fields = case mtail of
        -- §13.2.10: opaque members make the closed record a signature
        Nothing
          | opaqs@(_ : _) <- sort [nameText (rtfName f) | f <- fs, rtfOpaque f] ->
              pure (CSigT opaqs (CRecordTQ fields), VSort lvl)
        Nothing -> pure (CRecordTQ fields, VSort lvl)
        -- §11.3.1A: open record with a contextual row tail
        Just tailE -> do
          recRow <- globalValueM prelRecRow []
          rowTm <- check ctx tailE recRow
          openRecHead <- globalHeadM prelOpenRec
          pure
            ( CApp Expl (CApp Expl openRecHead rowTm)
                (CRecordTQ (sortOn rfName fields))
            , VSort lvl
            )
  -- §14.2.1 associated static member family application:
  -- @Trait.Member args@ selects the member global owned by that resolved trait,
  -- then uses the ordinary application spine to instantiate trait parameters
  -- and coherent evidence. Do not route this form through §7.4 method sugar:
  -- an associated type has no receiver-marked runtime binder.
  EApp (EDot (EVar traitName) (DotName memberName)) args -> do
    traitStaticMemberHead traitName memberName >>= \case
      Just (traitArity, memberTerm, memberType) ->
        elabSpine ctx (nameSpan memberName) memberTerm memberType
          (associatedStaticMemberArgs traitArity args)
      Nothing ->
        explicitRefFacetApp ctx (EDot (EVar traitName) (DotName memberName)) args >>= \case
          Just checked -> pure checked
          Nothing -> do
            (functionTerm, functionType) <-
              infer ctx (EDot (EVar traitName) (DotName memberName))
            elabSpine ctx (nameSpan memberName) functionTerm functionType args
  -- carrier-prefixed comprehension (§20.9): a type-valued head applied
  -- to a comprehension literal selects a collection carrier
  EApp f args
    | not (null args)
    , ArgExplicit (EComprehension k cs y csp) <- last args -> do
        st0 <- get
        let preArgs = init args
        mPrefix <- carrierPrefix ctx f preArgs
        case mPrefix of
          Just prefix -> elabComprehensionC ctx k cs y csp (Just prefix)
          Nothing -> do
            put st0
            (fTm, fTy) <- infer ctx f
            elabSpine ctx (exprSpan f) fTm fTy args
  EApp f args ->
    canonicalReflectionQuery ctx f >>= \case
      Just query -> elabReflQuery ctx (exprSpan f) query args Nothing
      Nothing -> inferOrdinaryApplication ctx f args
  EDot e m -> elabDot ctx e m
  EQDot e m -> elabSafeNav ctx e m
  EElvis l r sp -> elabElvis ctx l r sp
  EIs e cref -> elabIs ctx e cref
  EAscription e tyE _ -> do
    (tyTm, _) <- inferType ctx tyE
    tyV <- evalIn ctx tyTm
    tm <- check ctx e tyV
    pure (tm, tyV)
  EArrow b body -> do
    allowInout <- gets csAllowInoutBinderContext
    unless allowInout $
      rejectInoutBinderContext "anonymous function type" b
    domE0 <- case binderTypeExpr b of
      Just t -> pure t
      Nothing -> pure (EUnit (bSpan b))
    (domE, recoveredBoundSyntax) <- normalizeBinderDomainWithRecovery ctx b domE0
    -- §11.4.2: only an *implicit* binder annotation `(@x : b)` admits the
    -- boolean-proposition coercion `b ⟼ (b = True)`; explicit binders do not.
    (domTm, domLvl, coerced) <-
      withGeneralizableBareTypeLevels $
        if bImplicit b
          then inferTypeBoolProp' ctx domE
          else (\(tm, lvl) -> (tm, lvl, False)) <$> inferType ctx domE
    domV <- evalIn ctx domTm
    let nm = maybe "_" nameText (bName b)
        ic = if bImplicit b then Impl else Expl
        ordinaryDefault = if coerced then Q0 else binderQ b
    (mode, q) <- resolveBinderModeQ ctx b domV ordinaryDefault
    mLevelBound <- levelAssumptionFromExpr ctx (Just domTm) domE
    ctxWithBound <- extendLevelAssumption (bSpan b) ctx mLevelBound
    let
        -- implicit Pi binders join the local implicit context (§16.3.3); a
        -- proof bound governs only later telescope components and the body.
        ctx' = bindCtxMQ mode q nm (bImplicit b) domV ctxWithBound
    -- A declared proof theorem may place an authenticated TypeLevel
    -- comparison directly in its codomain. This remains narrower than a
    -- general Bool-as-Type coercion.
    (codTm, codLvl, codomainCoerced) <- inferTypeBoolProp' ctx' body
    when codomainCoerced $ do
      authenticated <- case boolEqualityTruePayload codTm of
        Just relation -> isJust <$> typeLevelRelationSpine relation
        Nothing -> pure False
      unless authenticated $
        errAt (exprSpan body) "E_NOT_A_TYPE" (Just "kappa.type.mismatch")
          "only an authenticated TypeLevel comparison may be used as a bare proposition-valued function codomain (§11.4.2)"
    let (codTm', codCeiling) = formationCeilingTerm ctx' codLvl codTm
        binderLevel = ctxLen ctx
    levelBinder <- isTypeLevelValue domV
    formation <- selectFormationMode ctx mode domV
    let domContribution = formationContribution formation domLvl
    let escapesLevel = levelBinder && binderLevel `elem` levelVars codCeiling
    when (escapesLevel && not recoveredBoundSyntax) $
      reportUnboundedTelescope ctx' (bSpan b) "dependent function" nm codCeiling
    -- §11.1: a Pi type lives in the max of its domain's and codomain's
    -- universe levels (predicative stratification), so e.g.
    -- `(s : Type) -> s` lands in Type1, not Type0.
    let resultLevel = levelMax domContribution (if escapesLevel then LZero else codCeiling)
    let piTm = CPiBoundFormedM mode formation ic q (isJust (bpBorrow (bPrefix b))) nm mLevelBound domTm codTm'
    annotatedPi <- annotateExplicitBorrowRegion ctx b piTm
    pure
      (annotatedPi, VSort resultLevel)
  EForall bs body _ -> elabForall ctx bs body
  EExists bs body sp -> elabExists ctx bs body sp
  ETraitArrow c rest -> do
    -- §11.4.2: the left of `b => T` admits the boolean-proposition coercion
    -- `b ⟼ (b = True)`, elaborating to `(@0 _ : b = True) -> T`.  An ordinary
    -- trait obligation `C => T` keeps the §16.3 evidence quantity (QW).
    (cTm, cLvl, coerced) <- inferTypeBoolProp' ctx c
    cV <- evalIn ctx cTm
    let q = if coerced then Q0 else QW
    mBound <- levelAssumptionFromExpr ctx (Just cTm) c
    withBound <- extendLevelAssumption (exprSpan c) ctx mBound
    -- The evidence binder joins the local implicit context (§16.3.3), and a
    -- certified TypeLevel proposition governs the dependent remainder.
    let ctx' = bindCtxMQ Ordinary q "_ev" True cV withBound
    (restTm, restLvl) <- inferType ctx' rest
    pure (CPiBoundFormedM Ordinary FormationOrdinary Impl q False "_ev" mBound cTm restTm, VSort (levelMax cLvl restLvl))
  EOptionSugar t _ -> do
    -- `Option t : Type (level of t)` (Option : Type u -> Type u)
    (tm, lvl) <- inferType ctx t
    option <- globalAppM prelOption [(Expl, tm)]
    pure (option, VSort lvl)
  EVariant arms mtail sp -> elabVariant ctx arms mtail sp Nothing
  -- §18.5.1: a lambda label names a return target consumable by
  -- @return@L@ inside the body.
  ELambda mlbl bs body sp -> elabLambda (ctx {ctxReturnTarget = nameText <$> mlbl}) bs body sp Nothing
  ELet binds body _ -> elabLet ctx binds body Nothing
  EBlock ds fin sp -> elabBlock ctx ds fin sp Nothing
  EIf alts mels sp -> do
    resT <- freshMetaV ctx
    tm <- checkIf ctx alts mels sp resT
    pure (tm, resT)
  EMatch scrut cases sp -> do
    resT <- freshMetaV ctx
    tm <- checkMatch ctx scrut cases sp resT
    pure (tm, resT)
  -- a do-scope label is only consumable by defer@label, which is
  -- rejected as unsupported at its use site, so the label is inert here
  -- a do block in expression position is a NESTED completion boundary: a
  -- `return@outer` cannot cross it at runtime (it is run as a do value), so
  -- reset the return target here (the function/lambda body do is elaborated
  -- directly by checkAgainstSig/elabLambda, which preserve it). §18.5/§18.8.
  EDo mlbl items sp -> elabDo (ctx {ctxReturnTarget = Nothing}) mlbl items sp Nothing
  EThunk e sp
    -- §5.2: soft keywords shadowed by a local binding are ordinary names
    | Just _ <- lookupCtx "thunk" ctx ->
        infer ctx (EApp (EVar (Name "thunk" sp)) [ArgExplicit e])
    | otherwise -> do
        (tm, ty) <- infer (withVarReadBlock VarReadCrossesBoundary ctx) e
        thunkT <- globalValueM prelThunk [(Expl, ty)]
        suspensionType <- quoteIn ctx thunkT
        pure (CThunkE tm (Just suspensionType), thunkT)
  ELazy e sp
    | Just _ <- lookupCtx "lazy" ctx ->
        infer ctx (EApp (EVar (Name "lazy" sp)) [ArgExplicit e])
    | otherwise -> do
        (tm, ty) <- infer (withVarReadBlock VarReadCrossesBoundary ctx) e
        needT <- globalValueM prelNeed [(Expl, ty)]
        suspensionType <- quoteIn ctx needT
        pure (CLazyE tm (Just suspensionType), needT)
  EForce e sp | Just _ <- lookupCtx "force" ctx ->
    infer ctx (EApp (EVar (Name "force" sp)) [ArgExplicit e])
  EForce e sp -> do
    (tm, ty) <- infer ctx e
    t <- forceM ty
    case t of
      VGlobN g [(_, a)] | g == prelThunk -> do
        resultType <- quoteIn ctx a
        pure (CForceE tm (Just resultType), a)
      VGlobN g [(_, a)] | g == prelNeed -> do
        resultType <- quoteIn ctx a
        pure (CForceE tm (Just resultType), a)
      _ -> do
        errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch") "force expects a Thunk or Need value"
        anyHole ctx
  EListLit es _ -> do
    elemT <- freshMetaV ctx
    tms <- mapM (\e -> check ctx e elemT) es
    listT <- globalValueM prelList [(Expl, elemT)]
    nil <- generatedCtorAtM ctx listT prelNil
    list <- foldM (\tailTerm headTerm -> generatedCtorApplyAtM ctx listT prelCons [headTerm, tailTerm]) nil (reverse tms)
    pure (list, listT)
  -- §20.5/§20.5.1: a map literal resolves duplicate keys (default: keep last),
  -- mirroring the map-comprehension lowering, so `{ 1: 10, 1: 20 }` keeps 20.
  EMapLit kvs sp -> do
    eqLam <- pairEqLam sp
    comb <- conflictLam ctx Nothing sp
    let entry (k, v) =
          ERecordLit
            [RecItem False (Name "key" sp) (Just k), RecItem False (Name "value" sp) (Just v)]
            sp
        entriesE = EListLit (map entry kvs) sp
    infer ctx (prelApp1 sp "__mapFromEntries" [prelApp1 sp "__mapResolve" [entriesE, eqLam, comb]])
  -- §20.1/§20.3.1: a set literal holds each element at most once, mirroring the
  -- set-comprehension lowering, so `{| 7, 7, 8 |}` has two elements.
  ESetLit es sp -> do
    eqLam <- pairEqLam sp
    infer ctx (prelApp1 sp "__setFromList" [prelApp1 sp "__distinctBy" [EListLit es sp, eqLam]])
  ESectionLeft e op sp ->
    infer ctx (lam1 sp "__x" (\x -> EApp (EVar op) [ArgExplicit e, ArgExplicit x]))
  ESectionRight op e sp ->
    infer ctx (lam1 sp "__x" (\x -> EApp (EVar op) [ArgExplicit x, ArgExplicit e]))
  -- §5.5.1: a bare `(op)` with more than one callable fixity in scope is
  -- ambiguous unless an expected type selects exactly one fixity. The
  -- type-directed disambiguation lives in `check` (a function-typed
  -- position picks the prefix or infix reading by arity); reaching `infer`
  -- means there is no such expected type, so a multi-fixity bare operator
  -- here is the ambiguous case. `(infix op)`/`(prefix op)`/`(postfix op)`
  -- carry an explicit fixity tag and are never ambiguous.
  EOpRef Nothing op sp -> do
    multi <- gets csMultiFixOps
    if nameText op `Set.member` multi
      then do
        report $
          diag SevError StageElaborate "E_OPERATOR_FIXITY_AMBIGUOUS" (Just "kappa.name.ambiguous") sp
            ( "bare operator '(" <> nameText op <> ")' is ambiguous: more than one "
                <> "callable fixity for '" <> nameText op <> "' is in scope and no expected "
                <> "type selects one; write '(infix " <> nameText op <> ")', '(prefix "
                <> nameText op <> ")', or '(postfix " <> nameText op
                <> ")', or supply a type annotation (Spec §5.5.1)"
            )
        anyHole ctx
      else infer ctx (EVar op)
  -- Fixity selection determines parsing and call origin, not a separate
  -- declaration namespace. Reuse ordinary variable resolution so trait
  -- siblings, local declarations, and imported operators resolve exactly as
  -- the same callable written in function position.
  EOpRef _ op _ -> infer ctx (EVar op)
  EReceiverSection ms args sp ->
    infer ctx . lam1 sp "__x" $ \x ->
      let base = List.foldl' EDot x ms
       in case args of
            [] -> base
            _ -> EApp base args
  ETry e excepts mfin sp -> elabTry ctx e excepts mfin sp
  ETryMatch e cases excepts mfin sp -> do
    tmp <- freshNameM "__scrut"
    let tn = Name tmp sp
        inner =
          EDo Nothing
            [ DoBind (LetBind False emptyPrefix (PVar tn) Nothing e sp)
            , DoExpr (EMatch (EVar tn) cases sp)
            ]
            sp
    elabTry ctx inner excepts mfin sp
  EHandle deep lblE scrutE cases sp -> elabHandle ctx deep lblE scrutE cases sp Nothing
  EEffRow entries mtail sp -> elabEffRow ctx entries mtail sp
  ESeal e tyE sp -> elabSeal ctx e tyE sp
  ESealExists ws e tyE sp -> elabSealExistsExplicit ctx ws e tyE sp
  EOpenExists e ns pat body sp -> elabOpenExists ctx e ns pat body sp
  EQuote e sp -> elabQuote ctx e sp Nothing
  ECodeQuote e sp -> elabCodeQuote ctx e sp Nothing
  ECodeEscape e sp -> elabCodeEscape ctx e sp
  ESplice e sp -> elabSplice ctx e sp Nothing
  ESpliceInQuote _ sp -> do
    errAt sp "E_QUOTE_SPLICE_OUTSIDE_QUOTE" (Just "kappa.syntax.quotation")
      "the in-quote splice form '${...}' is meaningful only inside a syntax quote '{ ... } (§21.1)"
    anyHole ctx
  EQuoteHole i sp -> case Map.lookup i (ctxQuoteSlots ctx) of
    Just ty -> pure (CGlob (GName primModule "__quoteHole"), ty)
    Nothing -> do
      errAt sp "E_INTERNAL" Nothing "quote grafting slot escaped its quote"
      anyHole ctx
  EBang _ _ sp -> do
    -- §3.1.5A: a splice is a desugaring construct; the diagnostic blames
    -- the user-written splice site as primary and records the desugaring
    -- provenance as a desugared-from related origin.
    report $
      withRelated (related RoleDesugaredFrom sp "monadic splice '!e' desugars to a do-block bind") $
        diag SevError StageElaborate "E_SPLICE_OUTSIDE_DO" Nothing sp
          "monadic splice '!' is only valid inside a do block"
    anyHole ctx
  ERecordPatch e items sp -> elabPatch ctx e items sp
  EComprehension k cs y sp -> elabComprehension ctx k cs y sp
  -- §12.3.1/§31.1: the capture set is part of type identity; encode
  -- as a left-nested '__captures' spine in canonical (sorted) order
  ECaptures e regions _ -> do
    (tTm, _) <- inferType ctx e
    rs <- forM regions $ \rn -> do
      (rTm, rTy) <- infer ctx (EVar rn)
      regionT <- globalValueM prelRegion []
      expectType ctx (nameSpan rn) rTy regionT
      pure rTm
    capturesHead <- globalHeadM prelCaptures
    let sorted = sortOn renderTerm (nub rs)
        capTm =
          List.foldl'
            (\acc r -> CApp Expl (CApp Expl capturesHead acc) r)
            tTm
            sorted
    pure (capTm, VSort LZero)
  EKindQualified sel n sp -> elabKindQualified ctx sel n sp
  EModuleSig name sp -> do
    st <- get
    case resolveModuleObjectName st (nameText name) of
      Just moduleName -> pure (moduleSignatureType moduleName, VSort LZero)
      Nothing -> do
        errAt sp "E_STATIC_OBJECT_UNRESOLVED" (Just "kappa.name.unresolved")
          ("no module named '" <> nameText name <> "' is in scope for moduleSig (Spec §7.5)")
        anyHole ctx
  EImpossible sp -> do
    -- §17.1.4: accepted iff the enclosing match arm's §30.2.7-refined fiber is
    -- provably uninhabited ('csImpossibleScrut', set while checking arm bodies).
    fiberEmpty <- gets (\st -> csImpossibleScrut st == Just True)
    unless fiberEmpty $
      errAt sp "E_IMPOSSIBLE_REACHABLE" (Just "kappa.pattern.unreachable")
        "'impossible' is not provably unreachable here (§17.1.4)"
    anyHole ctx
  EOpChain {} -> do
    -- the resolver re-associates every chain (§5.5.2); reaching one here
    -- means a resolution diagnostic was already emitted for it
    anyHole ctx
  where
    tupleField i = "_" <> T.pack (show (i + 1))
    lam1 sp nm f =
      ELambda Nothing [simpleBinder (Name nm sp)] (f (EVar (Name nm sp))) sp

-- | Verify @expr@ against an @expected0@ type and elaborate it to a core
-- 'Term'. Used wherever the context already knows the type (a typed @let@
-- body, a lambda checked against a function type). Knowing the expectation
-- lets 'check' handle forms 'infer' cannot, so it matches on the /pair/
-- @(expr, expected)@ to catch those (e.g. a lambda against a 'VPi'). Any
-- form with no rule for the @(expr, expected)@ pair falls through to
-- 'infer', inserts any still-missing implicit arguments, then 'unify's the
-- result against the expectation — the generic "switch direction" step.
-- | Recover the nominal family identity from a checked semantic value while
-- preserving explicit universe applications and proof-carrying lifts. This is
-- shared by expected-constructor selection and branch-evidence classification;
-- neither caller may infer nominal identity from source spelling.
nominalFamilyValueHead :: Value -> Maybe GName
nominalFamilyValueHead = \case
  VGlobI family _ _ -> Just family
  VGlobN family _ -> Just family
  VUniverseLift _ _ _ value -> nominalFamilyValueHead value
  VAppN _ function _ -> nominalFamilyValueHead function
  _ -> Nothing

-- | Resolve an unqualified spelling shared by several trait-member
-- projections when the checking direction supplies a rigid expected type.
-- Candidate viability is established by the ordinary checked projection
-- type and implicit-evidence planner; source spelling alone grants no
-- preference.  Exactly one viable semantic projection is required.
checkExpectedTraitMember
  :: Ctx
  -> Name
  -> Value
  -> CheckM (Maybe Term)
checkExpectedTraitMember ctx name expected = do
  baseline <- get
  let spelling = nameText name
      candidates = fromMaybe [] (Map.lookup spelling (csScopeAmbig baseline))
      traitCandidates =
        [ candidate
        | candidate <- candidates
        , Map.member candidate (csTraitMemberOwners baseline)
        ]
  if null candidates || length traitCandidates /= length candidates
    then pure Nothing
    else do
      attempts <- forM traitCandidates $ \candidate -> do
        put baseline
        result <- trySpec $ do
          globalTermIn ctx (nameSpan name) candidate >>= \case
            Nothing -> do
              errAt (nameSpan name) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
                ("trait-member projection '" <> gKey candidate <> "' is unavailable")
              freshMetaFor ctx expected
            Just (headTerm, headType) ->
              insertAllImplicitsAgainstExpected
                ctx
                (nameSpan name)
                headTerm
                headType
                expected >>= \case
                  Just term -> flushPending >> pure term
                  Nothing -> do
                    term <- coerceTerm ctx (nameSpan name) headTerm headType expected
                    flushPending
                    pure term
        stateAfter <- get
        pure ((candidate,, stateAfter) <$> result)
      put baseline
      case catMaybes attempts of
        [(_, term, selectedState)] -> put selectedState >> pure (Just term)
        [] -> pure Nothing
        viable -> do
          let names = map (gKey . \(candidate, _, _) -> candidate) viable
          report $
            withPayload
              ( withPayloadField "name" spelling $
                  withPayloadField "candidates" (T.intercalate ", " names) $
                    payloadKind "name-ambiguous"
              ) $
              diag SevError StageElaborate "E_NAME_AMBIGUOUS" (Just "kappa.name.ambiguous")
                (nameSpan name)
                ( "trait member '" <> spelling
                    <> "' remains ambiguous at the expected type; viable projections are "
                    <> T.intercalate " and " names
                    <> " (qualify the member, Spec §7.1, §14.2.1)"
                )
          Just <$> freshMetaFor ctx expected

check :: Ctx -> Expr -> Value -> CheckM Term
check ctx expr expected0 = do
  expected <- forceM expected0
  let expectedStartsImplicit = case expected of
        VPiBoundM _ Impl _ _ _ _ _ _ -> True
        _ -> False
  canonicalRefl <- case expr of
    EVar name
      | nameText name == gnameText prelRefl
      , Nothing <- lookupCtx (nameText name) ctx ->
          resolveCtor ctx (CtorRef Nothing name) >>= \case
            Just (constructor, _) -> pure (constructor == prelRefl)
            Nothing -> pure False
    _ -> pure False
  canonicalSummon <- case expr of
    EVar name
      | nameText name == "summon"
      , Nothing <- lookupCtx (nameText name) ctx ->
          (== Just (gPrel "summon")) <$> lookupGlobalName (nameText name)
    _ -> pure False
  canonicalReflection <- case expr of
    EApp function _ -> canonicalReflectionQuery ctx function
    _ -> pure Nothing
  case (expr, expected) of
    (EDerive explicitGoal sp, _) ->
      case explicitGoal of
        Nothing -> do
          rigid <- deriveGoalRigid ctx expected
          if rigid
            then synthesizeDerivation ctx sp expected
            else do
              errAt sp "E_DERIVE_EXPECTED_TYPE_REQUIRED" (Just "kappa.derive")
                "bare 'derive' requires a rigid expected type (§16.3.2A)"
              freshMetaFor ctx expected
        Just goalExpression -> do
          (goalTerm, _) <- inferType ctx goalExpression
          goal <- evalIn ctx goalTerm
          term <- synthesizeDerivation ctx sp goal
          coerceTerm ctx sp term goal expected
    (EVar n, VGlobN g [])
      | nameText n == "ω"
      , g == prelTypeLevel -> globalHeadM prelTypeLevelOmega
    -- Constructor resolution, not spelling, authorizes the checked proof
    -- bridge. The spelling guard is only a cheap candidate filter before the
    -- ordinary constructor resolver establishes the exact semantic identity.
    (EVar _, _)
      | canonicalRefl
      , not expectedStartsImplicit -> do
          proved <- propProof ctx expected
          case proved of
            Just proof -> pure proof
            Nothing ->
              expectedConstructorApplicationHead ctx expr expected >>= \case
                Just (headTerm, headType) -> do
                  (term, actual) <-
                    insertAllImplicits ctx (exprSpan expr) headTerm headType
                  coerceTerm ctx (exprSpan expr) term actual expected
                Nothing -> checkFallthrough expected
    -- A bare @summon@ is expected-type directed, so it reaches checking
    -- without an explicit 'EApp' node. Authenticate the resolved prelude
    -- global before applying the same incomplete-self exclusion as the
    -- application path below (§14.3.4A). Locals with this spelling remain
    -- ordinary values.
    (EVar _, _)
      | canonicalSummon ->
          withIncompleteSelfEvidenceForbidden (checkFallthrough expected)
    -- §16.3.2 a hole in checking position. The expected type is known, so
    -- the unsolved-hole diagnostic states it directly. A named hole shares
    -- one type metavariable across its occurrences: unifying that shared
    -- meta with this occurrence's expected type both records the agreed
    -- type (first occurrence) and enforces that later occurrences receive a
    -- definitionally equal expected type. An incompatible later occurrence
    -- fails that unification and is reported as kappa.hole.inconsistent.
    (EHole mn sp, _) -> do
      (tm, ty, mnh) <- holeMetas ctx mn sp
      ok <- unify ctx ty expected
      when (isJust mn && ok) $
        recordHoleClassifier ctx tm expected
      case (mn, mnh) of
        (Just n, Just nh)
          | not ok
          , (_ : _ : _) <- nhOccs nh ->
              -- a repeat occurrence whose expected type disagrees with the
              -- type the earlier occurrences fixed (the shared meta is
              -- already solved): §16.3.2 inconsistent named hole.
              reportInconsistentHole ctx n sp nh expected
        _ -> pure ()
      -- Named holes remain assignable until the declaration boundary (for
      -- example by the principal arithmetic rule of §15.8.6). Anonymous
      -- holes are never shared and are diagnosed at this occurrence.
      when (isNothing mn) $ do
        tyT <- quoteIn ctx expected
        reportUnsolvedHole ctx mn sp tyT
      pure tm
    (ELambda l bs body sp, VPiBoundM mode Impl q _ nm assumption dom clo)
      | not (firstImplicit bs) -> do
          withBound <- extendLevelAssumption sp ctx assumption
          let ctx' = bindCtxMQ mode q nm True dom withBound
          cod <- clApp clo (VRigid (ctxLen ctx) [])
          inner <- check ctx' (ELambda l bs body sp) cod
          pure (CLamM mode Impl q nm inner)
    -- §12.3.1: a closure literal introduces at the underlying type, but its
    -- structurally inferred hidden environment must be contained in the
    -- user-written upper bound.  Merely stripping the wrapper here used to
    -- accept a closure that captured t at `captures (s)`.
    (ELambda {}, captureType@(VGlobI captureHead _ _))
      | captureHead == prelCaptures ->
          checkCaptureAnnotatedLambda ctx expr captureType
    (ELambda mlbl bs body sp, _) -> do
      -- §18.5.1: an explicit lambda label, else (anonymous) a reset so a
      -- `return@outer` cannot cross this user-written lambda boundary.
      (tm, ty) <- elabLambda (ctx {ctxReturnTarget = nameText <$> mlbl}) bs body sp (Just expected)
      expectType ctx sp ty expected
      pure tm
    (_, VPiBoundM mode Impl q _ nm assumption dom clo)
      | not (isHole expr) -> do
          -- Preserve a function value that already has the expected implicit
          -- telescope. Implicit-Pi introduction is an eta fallback, not a
          -- mandate to saturate and rebuild every bare function reference.
          -- The speculative check retains successful inference effects and
          -- rolls back both metas and diagnostics before genuine eta
          -- expansion on a mismatch.
          trySpec (do
            (term, actual) <- infer ctx expr
            coerceTerm ctx (exprSpan expr) term actual expected) >>= \case
              Just direct -> pure direct
              Nothing -> do
                -- Eta-introduction is itself a coercion attempt.  Its
                -- implicit search and region instantiations must therefore
                -- be transactional: a failed higher-rank coercion must not
                -- replace the direct type mismatch with incidental
                -- ambiguity/capture diagnostics from the attempted eta
                -- expansion.
                trySpec (do
                  withBound <- extendLevelAssumption (exprSpan expr) ctx assumption
                  let ctx' = bindCtxMQ mode q nm True dom withBound
                  cod <- clApp clo (VRigid (ctxLen ctx) [])
                  inner <- check ctx' expr cod
                  pure (CLamM mode Impl q nm inner)) >>= \case
                    Just etaExpanded -> pure etaExpanded
                    Nothing -> do
                      (term, actual) <- infer ctx expr
                      -- Neither directed coercion closed.  Diagnose the
                      -- original higher-rank types without instantiating
                      -- either implicit telescope; incidental implicit
                      -- search is not part of this mismatch.
                      withDefinitionalEqualityOnly $
                        coerceTerm ctx (exprSpan expr) term actual expected
    (EVar n, VSort _)
      | Nothing <- lookupCtx (nameText n) ctx -> do
          (tm, level) <- inferType ctx (EVar n)
          coerceTerm ctx (nameSpan n) tm (VSort level) expected
    -- §6.6: in type position `()` is surface syntax for the type `Unit`
    -- (the would-be empty record), distinct from the unique `Unit` value
    -- it denotes in term position. A `()` checked against a universe is
    -- therefore the type `Unit`, which inhabits that universe.
    (EUnit _, VSort _) -> globalHeadM prelUnit
    -- §5.5.1: a bare parenthesized operator at a function-typed
    -- position selects the fixity the expected explicit arity calls
    -- for — unary `(-)` is the prefix reading (negate); otherwise the
    -- reference eta-expands so trailing implicit obligations (the
    -- §28.2.1 checked-arithmetic proofs) insert at the application
    (e, VPi Expl _ _ _ _ _)
      | Just n <- bareOpRef e
      , isOpSpelling (nameText n)
      , Nothing <- lookupCtx (nameText n) ctx -> do
          arity <- explicitArity (ctxLen ctx) expected
          let sp = nameSpan n
          if arity == 1 && nameText n == "-"
            then check ctx (EVar (Name "negate" sp)) expected
            else do
              let vars = [Name ("__op" <> T.pack (show i)) sp | i <- [1 .. arity]]
                  lam =
                    ELambda Nothing (map simpleBinder vars)
                      (EApp (EVar n) [ArgExplicit (EVar v) | v <- vars]) sp
              check ctx lam expected
    -- §18.1.14: Eff r is a monadic carrier, so canonical Applicative.pure in
    -- an Eff-typed position injects through the Eff kernel. Authenticate the
    -- resolved projection identity; an imported same-spelling declaration is
    -- an ordinary application.
    (EApp _ [ArgExplicit _], _)
      | Just (carrier, aT) <- monadActionViewValue expected
      , nominalFamilyValueHead carrier == Just prelEff ->
          canonicalApplicativePurePayload ctx expr >>= \case
            Just payload -> do
              tm <- check ctx payload aT
              generatedEffPureAtM ctx expected tm
            Nothing -> checkFallthrough expected
    -- Inside any typed do block, canonical @pure@ denotes the enclosing
    -- carrier's selected Applicative introduction. This includes IO and the
    -- evidence-driven STM/user carriers: @pure@ is the trait member for those carriers too, and
    -- routing them through generic application inference would discard the
    -- already-known carrier before instance selection. Authenticate the
    -- resolved global before selecting evidence; a local/imported
    -- same-spelling function remains an ordinary application.
    (EApp pureHead [ArgExplicit payload], _)
      | ctxInDo ctx
      , Just (carrier, resultType) <- monadActionViewValue expected -> do
          resolvedHead <- staticGlobalExpr ctx pureHead
          if resolvedHead == Just (gPrel "pure")
            then do
              sourceType <-
                carrierSourceArgument ctx (exprSpan expr) carrier resultType
              payloadTerm <- check ctx payload sourceType
              if nominalFamilyValueHead carrier == Just prelElab
                then do
                  universes <- elabCarrierUniverses expected
                  elabPureAt ctx universes sourceType payloadTerm
                else
                  generatedApplicativePureAtM
                    ctx
                    (exprSpan expr)
                    carrier
                    sourceType
                    payloadTerm
                    expected
            else checkFallthrough expected
    -- §21.1: a quote checked against its Syntax index elaborates the
    -- payload at the index's object type
    (EQuote qe sp, VGlobN (GName pm "Syntax") [(_, tT)])
      | pm == preludeModule -> do
          (tm, _) <- elabQuote ctx qe sp (Just tT)
          pure tm
    -- §23.2: a code quote checked against 'Code t' elaborates its
    -- payload at t
    (ECodeQuote qe sp, VGlobN (GName pm "Code") [(_, tT)])
      | pm == preludeModule -> do
          (tm, _) <- elabCodeQuote ctx qe sp (Just tT)
          pure tm
    -- §21.2: a splice's expected type directs both the admissible
    -- argument types and the elaboration of the produced syntax
    (ESplice se sp, _) -> do
      (tm, ty) <- elabSplice ctx se sp (Just expected)
      expectType ctx sp ty expected
      pure tm
    -- §18.9 threading pun (corpus): a bare variable checked against a
    -- single-field record type whose field has the same spelling is the
    -- record literal `(n = n)` (e.g. `pure file : IO (1 file : File)`)
    (EVar n, VRecordT [(f, ft)])
      | nameText n == f
      , Just (i, entry) <- lookupCtx (nameText n) ctx
      , not (ceVarBind entry) -> do
          ok <- unify ctx (ceType entry) ft
          if ok
            then pure (CRecordV [(f, CVar i)])
            else do
              (tm, ty) <- infer ctx expr
              expectType ctx (nameSpan n) ty expected
              pure tm
    -- (x : T) checked against a universe is a single-field record type
    -- (§13.1); the parser cannot distinguish it from an ascription
    (EAscription (EVar _) _ sp, VSort _) -> do
      (tm, level) <- inferType ctx expr
      coerceTerm ctx sp tm (VSort level) expected
    -- §7.2: an application checked against a universe is a type
    -- position, so its head prefers the type facet of a same-spelling
    -- data family; arguments of sort 'Type' recurse through this same
    -- case, covering nested parenthesized type applications such as
    -- 'Wrap (Wrap Integer)' or 'List (Wrap Integer)'.
    (EApp _ _, VSort _) -> do
      (tm, level) <- inferType ctx expr
      coerceTerm ctx (exprSpan expr) tm (VSort level) expected
    (EIf alts mels sp, _) -> checkIf ctx alts mels sp expected
    -- §18.1.21: a handler eliminates into the expected target carrier `m`
    -- (which may be `IO e` or another carrier, not only `Eff r`); thread the
    -- expectation in so non-Eff clause bodies type-check.
    (EHandle deep lblE scrutE cases sp, _) -> do
      (tm, ty) <- elabHandle ctx deep lblE scrutE cases sp (Just expected)
      expectType ctx sp ty expected
      pure tm
    (EMatch scrut cases sp, _) -> checkMatch ctx scrut cases sp expected
    (EDo mlbl items sp, _) -> do
      -- nested do in checked expression position: reset the return target
      -- (a `return@outer` cannot cross this do-value boundary at runtime).
      (tm, ty) <- elabDo (ctx {ctxReturnTarget = Nothing}) mlbl items sp (Just expected)
      expectType ctx sp ty expected
      pure tm
    (ELet binds body _, _) -> do
      (tm, ty) <- elabLet ctx binds body (Just expected)
      expectType ctx (exprSpan body) ty expected
      pure tm
    (EBlock decls result sp, _) -> do
      (tm, ty) <- elabBlock ctx decls result sp (Just expected)
      expectType ctx sp ty expected
      pure tm
    -- operator/receiver sections check as their lambda desugaring so
    -- the expected type guides the receiver (§16.1.6)
    (ESectionLeft e op sp, _) ->
      check ctx (lamSection sp "__x" (\x -> EApp (EVar op) [ArgExplicit e, ArgExplicit x])) expected
    (ESectionRight op e sp, _) ->
      check ctx (lamSection sp "__x" (\x -> EApp (EVar op) [ArgExplicit x, ArgExplicit e])) expected
    (EReceiverSection ms args sp, _) ->
      check ctx
        ( lamSection sp "__x" $ \x ->
            let base = List.foldl' EDot x ms
             in case args of
                  [] -> base
                  _ -> EApp base args
        )
        expected
    (EThunk e _, VGlobN global [(_, a)])
      | global == prelThunk -> do
          body <- check (withVarReadBlock VarReadCrossesBoundary ctx) e a
          suspensionType <- quoteIn ctx expected
          pure (CThunkE body (Just suspensionType))
    (ELazy e _, VGlobN global [(_, a)])
      | global == prelNeed -> do
          body <- check (withVarReadBlock VarReadCrossesBoundary ctx) e a
          suspensionType <- quoteIn ctx expected
          pure (CLazyE body (Just suspensionType))
    (_, VGlobN g [(_, a)])
      | g == prelThunk -> suspendOrInfer CThunkE expected a
    (_, VGlobN g [(_, a)])
      | g == prelNeed -> suspendOrInfer CLazyE expected a
    -- expected-type-directed injection (§13.1.3) must see literals too
    (_, VVariantT members)
      | not (isVariant expr) -> do
          (tm, ty) <- infer ctx expr
          (tm1, ty1) <- insertAllImplicits ctx (exprSpan expr) tm ty
          injectInto ctx tm1 ty1 members expected (exprSpan expr)
    -- §21.6 convenience reflection queries: an 'Elab'-typed position
    -- keeps the ordinary action; any other position runs the
    -- elaboration-time query at the call site ('elabReflQuery')
    (EApp f args, _)
      | Just query <- canonicalReflection -> do
          (tm, ty) <-
            elabReflQuery ctx (exprSpan f) query args (Just expected)
          expectType ctx (exprSpan expr) ty expected
          pure tm
    -- §21.9: 'pure' in an Elab-typed position lifts a meta-phase value
    -- through the elaboration-time Applicative (the prelude 'pure' is
    -- the IO instance; carrier-polymorphic 'pure' is not modelled). Keep this
    -- after reflection dispatch: the syntactic one-argument shape alone does
    -- not authorize skipping another authenticated application rule.
    (EApp _ [ArgExplicit _], _)
      | Just (carrier, aT) <- monadActionViewValue expected
      , nominalFamilyValueHead carrier == Just prelElab ->
          canonicalApplicativePurePayload ctx expr >>= \case
            Just payload -> do
              tm <- check ctx payload aT
              universes <- elabCarrierUniverses expected
              elabPureAt ctx universes aT tm
            Nothing -> checkFallthrough expected
    -- §16.1.7.1/§12.2.1: an all-explicit application checked against a
    -- known expected type pre-unifies its result type with the
    -- expectation, so arguments see solved domains (binder quantities
    -- through polymorphic wrappers, literal defaulting, dependent
    -- constructor indices)
    -- §20.9: a carrier-prefixed comprehension in checked position
    -- still selects its sink through the type-valued prefix (the
    -- generic application path would apply the data constructor)
    (EApp f args, _)
      | not (null args)
      , ArgExplicit (EComprehension k cs y csp) <- last args -> do
          st0 <- get
          mPrefix <- carrierPrefix ctx f (init args)
          case mPrefix of
            Just prefix -> do
              (tm, ty) <- elabComprehensionC ctx k cs y csp (Just prefix)
              expectType ctx csp ty expected
              pure tm
            Nothing -> do
              put st0
              (tm, ty) <- infer ctx expr
              (tm1, ty1) <- insertAllImplicits ctx (exprSpan expr) tm ty
              expectType ctx (exprSpan expr) ty1 expected
              pure tm1
    -- §5.5.1: `(-) e` at a non-function expected type selects the
    -- prefix fixity — the application of bare `(-)` to one explicit
    -- argument in a saturated position is negation
    (EApp hd [ArgExplicit a], _)
      | Just n <- bareOpRef hd
      , nameText n == "-"
      , Nothing <- lookupCtx "-" ctx
      , notPi expected -> do
          checkRefinementIntroduction ctx expr expected >>= \case
            Just refined -> pure refined
            Nothing ->
              check ctx
                (EApp (EVar (Name "negate" (nameSpan n))) [ArgExplicit a])
                expected
    (EApp f args, _)
      | not (null args) ->
          if all isExplicitArg args
            then do
              -- A selected refinement view determines the base type against
              -- which an ordinary explicit application is checked. Mixed
              -- spines containing @payload are already source-directed at
              -- their implicit slots and go straight to 'elabAppChecked'.
              checkRefinementIntroduction ctx expr expected >>= \case
                Just refined -> pure refined
                Nothing -> do
                  mproj <- projectionHead ctx f
                  mRecvProj <-
                    maybe
                      (projRecvApp ctx f args)
                      (const (pure Nothing))
                      mproj
                  case (mproj, mRecvProj) of
                    (_, Just (tm, ty)) -> do
                      expectType ctx (exprSpan expr) ty expected
                      pure tm
                    (Just _, _) -> do
                      (tm, ty) <- infer ctx expr
                      (tm1, ty1) <-
                        insertAllImplicits ctx (exprSpan expr) tm ty
                      special <-
                        projDescriptorMismatch ctx expr ty1 expected
                      unless special $
                        expectType ctx (exprSpan expr) ty1 expected
                      pure tm1
                    _ ->
                      elabAppChecked ctx f args expected (exprSpan expr)
            else elabAppChecked ctx f args expected (exprSpan expr)
    (EIntLit v msuf sp, _) -> do
      checkRefinementIntroduction ctx expr expected >>= \case
        Just refined -> pure refined
        Nothing -> do
          (tm, ty) <- elabIntLit ctx v msuf sp (Just expected)
          expectType ctx sp ty expected
          pure tm
    (EFloatLit v msuf sp, _) -> do
      checkRefinementIntroduction ctx expr expected >>= \case
        Just refined -> pure refined
        Nothing -> do
          (tm, ty) <- elabFloatLit ctx v msuf sp (Just expected)
          expectType ctx sp ty expected
          pure tm
    (EVariant arms mtail sp, _) -> do
      (tm, ty) <- elabVariant ctx arms mtail sp (Just expected)
      expectType ctx sp ty expected
      pure tm
    -- §13.2.1 dependent record literals: sibling references through
    -- 'this' (in field types or initializers) need telescope-ordered
    -- elaboration
    -- §13.2.10: a signature type with opaque members is introduced
    -- only through 'seal ... as ...', never by a direct record literal
    (ERecordLit _ lsp, VSigT _ _) -> do
      errAt lsp "E_SEAL_DIRECT_LITERAL_FOR_SIGNATURE" (Just "kappa-hs.seal.direct-literal")
        "a record literal cannot introduce a signature type with opaque members; use 'seal ... as ...' (§13.2.10)"
      fst <$> anyHole ctx
    -- A record literal checked against a nominal refinement must see the
    -- selected view's base telescope before its field literals default.
    -- Recognition remains dictionary-driven through 'RefinementView'; a
    -- same-shaped nominal type without coherent evidence falls through.
    (ERecordLit _ _, VGlobI _ _ _) ->
      checkRefinementIntroduction ctx expr expected >>= \case
        Just refined -> pure refined
        Nothing -> checkFallthrough expected
    (ERecordLit items lsp, VRecordTQ qfs) -> do
      -- Record introduction is bidirectional even for a non-dependent
      -- telescope: overloaded field expressions (numeric literals, trait
      -- methods, constructors) must see the declared field type before they
      -- default. The telescope-ordered path also handles dependent siblings,
      -- quantities, and observation modes, so it is the single checked-record
      -- rule rather than a special case selected from source shape.
      fst <$> elabDependentRecordLitQ ctx items qfs lsp
    (ERecordLit items lsp, VRecordT fs) ->
      fst <$> elabDependentRecordLit ctx items fs lsp
    -- a parenthesized list in type position is the tuple type (§13.1)
    (ETuple {}, VSort _) -> do
      (tm, level) <- inferType ctx expr
      coerceTerm ctx (exprSpan expr) tm (VSort level) expected
    (ETuple es sp, VRecordT fs)
      | length es == length fs -> do
          -- expected-type-directed punning (§13.1.2): a parenthesized
          -- list of bare names matching the record's field names is the
          -- punned record literal
          let punVars = [(nameText n, EVar n) | EVar n <- es]
          tms <-
            if length punVars == length es && sort (map fst punVars) == map fst fs
              then forM fs $ \(fn, fty) ->
                check ctx (fromMaybe (ETuple es sp) (lookup fn punVars)) fty
              else zipWithM (\e (_, t) -> check ctx e t) es fs
          pure (CRecordV (zip (map fst fs) tms))
    -- expected-type-directed constructor selection: when the expected
    -- type is a data type declaring a constructor with the bare head's
    -- spelling and ordinary resolution would yield a same-spelling
    -- constructor of a *different* data type (or nothing at all), the
    -- expected type's constructor is selected — constructors are
    -- static members of their data type (§7.2) and the unqualified
    -- spelling abbreviates that selection in checked position
    (e, expectedFamily)
      | Just (hn, args) <- bareCtorHead e
      , Nothing <- lookupCtx (nameText hn) ctx
      , Just dgName <- nominalFamilyValueHead expectedFamily -> do
          st0 <- get
          mExpectedConstructor <- case Map.lookup dgName (csDatas st0) of
            Just di
              | (ctorG : _) <-
                  [ c
                  | c <- diCtors di
                  , gnameText c == nameText hn
                  , constructorInScope st0 c
                  ] ->
                  -- The expected family establishes the constructor identity,
                  -- including the ordinary same-spelling case.  This is more
                  -- than name retargeting: its complete family spine is the
                  -- source of the hidden constructor arguments below.
                  pure (Just ctorG)
            _ -> pure Nothing
          case mExpectedConstructor of
            Just ctorG -> case Map.lookup ctorG (csCtors st0) of
              Just ci ->
                globalTerm ctorG >>= \case
                  Just (hTm, hTy) ->
                    applyExpectedConstructorFamilyPrefix ctx ci expected hTm hTy >>= \case
                      Just (seededTerm, seededType) -> do
                        (tm, ty) <- elabSpine ctx (exprSpan e) seededTerm seededType args
                        (tm1, ty1) <- insertAllImplicits ctx (exprSpan e) tm ty
                        coerceTerm ctx (exprSpan e) tm1 ty1 expected
                      Nothing -> checkFallthrough expected
                  Nothing -> checkFallthrough expected
              Nothing -> checkFallthrough expected
            Nothing -> checkFallthrough expected
    _ -> checkFallthrough expected
  where
    checkFallthrough expected = do
      tryExpectedSchemaReification ctx (exprSpan expr) expr expected >>= \case
        Just reified -> pure reified
        Nothing -> do
          overloaded <- case expr of
            EVar name
              | Nothing <- lookupCtx (nameText name) ctx ->
                  checkExpectedTraitMember ctx name expected
            _ -> pure Nothing
          case overloaded of
            Just selected -> pure selected
            Nothing -> ordinaryFallthrough expected
    ordinaryFallthrough expected = do
          saved <- get
          (tm, ty) <- infer ctx expr
          afterInfer <- get
          rawProof <-
            if termHeadGlob tm == Just prelRawProof
              then do
                -- Discard the independently freshened occurrence before
                -- rebuilding it from the expected proposition. Replay the
                -- ordinary semantic-identity gate so opt-in audit records and
                -- rejection diagnostics are preserved.
                put saved
                gateUnsafeResolved prelRawProof (exprSpan expr)
                Just <$> generatedRawProofAtM ctx (exprSpan expr) expected
              else pure Nothing
          -- Authenticate `refl` after ordinary name/constructor resolution. This
          -- avoids source-spelling privilege and also covers qualified references.
          -- Discard the speculative constructor metas when the proposition bridge
          -- supplies the checked canonical witness.
          resolvedRefl <- case termHeadGlob tm of
            Just constructor -> pure (constructor == prelRefl)
            Nothing -> do
              value <- evalIn ctx tm
              pure $ case value of
                VCtorI constructor _ _ -> constructor == prelRefl
                _ -> False
          case rawProof of
            Just proof -> pure proof
            Nothing -> do
              proved <-
                if resolvedRefl
                  then put saved >> propProof ctx expected
                  else pure Nothing
              case proved of
                Just proof -> pure proof
                Nothing -> do
                  put afterInfer
                  tryParametricForallInterchange ctx (exprSpan expr) tm ty expected >>= \case
                    Just interchanged -> pure interchanged
                    Nothing -> do
                      directed <- case expr of
                        -- This planner is the zero-explicit-argument
                        -- counterpart of 'elabAppChecked'. Applications
                        -- already have a complete-spine transaction and must
                        -- not be replanned after inference: doing so can
                        -- commit a flexible carrier/evidence choice before
                        -- its explicit arguments are checked.
                        EVar {} ->
                          insertAllImplicitsAgainstExpected
                            ctx
                            (exprSpan expr)
                            tm
                            ty
                            expected
                        _ -> pure Nothing
                      case directed of
                        Just directedTerm -> pure directedTerm
                        Nothing -> do
                          (tm1, ty1) <- insertAllImplicits ctx (exprSpan expr) tm ty
                          missingLevel <- unsaturatedExplicitLevelArgument ctx expr ty1 expected
                          special <- if missingLevel then pure True else projDescriptorMismatch ctx expr ty1 expected
                          if special
                            then pure tm1
                            else coerceTerm ctx (exprSpan expr) tm1 ty1 expected
    -- a bare (possibly applied) capitalized head
    bareCtorHead = \case
      EVar n | upperHead n -> Just (n, [])
      EApp (EVar n) args | upperHead n -> Just (n, args)
      _ -> Nothing
    upperHead n = case T.uncons (nameText n) of
      Just (c, _) -> c >= 'A' && c <= 'Z'
      Nothing -> False
    isOpSpelling t = case T.uncons t of
      Just (c, _) ->
        not (c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= '\128')
      Nothing -> False
    notPi = \case
      VPi {} -> False
      _ -> True
    bareOpRef = \case
      EVar n -> Just n
      EOpRef Nothing n _ -> Just n
      _ -> Nothing
    explicitArity lvl v = do
      t <- forceM v
      case t of
        VPi Expl _ _ _ _ clo -> do
          cod <- clApp clo (VRigid lvl [])
          (1 +) <$> explicitArity (lvl + 1) cod
        VPi Impl _ _ _ _ clo -> do
          cod <- clApp clo (VRigid lvl [])
          explicitArity (lvl + 1) cod
        _ -> pure (0 :: Int)
    -- §16.1.5: a fully applied projection in descriptor-typed position
    -- gets the dedicated diagnostic rather than a plain mismatch
    projDescriptorMismatch c ex actual expect = case expect of
      VGlobN (GName pm dn) _
        | pm == preludeModule
        , dn `elem` ["Projector", "Getter", "Opener", "Setter", "Sinker"]
        , EApp f args <- ex -> do
            mproj <- projectionHead c f
            case mproj of
              Just (_, pj) | projFullApp pj args -> do
                ok <- unify c actual expect
                if ok
                  then pure False
                  else do
                    errAt (exprSpan ex) "E_PROJECTION_DESCRIPTOR_VALUE_EXPECTED"
                      (Just "kappa-hs.projection.descriptor")
                      "a fully applied projection denotes its focus value, not a first-class descriptor; use the unapplied projection name (§16.1.5)"
                    pure True
              _ -> pure False
      _ -> pure False
    -- A declaration schema may be eta-reified from an expected bounded
    -- telescope, but an ordinary explicit TypeLevel parameter remains an
    -- ordinary application slot.  Diagnose the bare-function use at that
    -- slot boundary instead of presenting it as an unrelated equality
    -- mismatch (§11.1.2.3A.1, §16.1.7.1).
    unsaturatedExplicitLevelArgument c ex actual expect = do
      actual' <- forceM actual
      expected' <- forceM expect
      case (ex, actual', expected') of
        (EVar _, VPiM _ Expl _ _ _ domain _, VPiM {}) -> pure False
        (EVar _, VPiM _ Expl _ _ _ domain _, _) -> do
          levelDomain <- isTypeLevelValue domain
          when levelDomain $
            errAt (exprSpan ex) "E_APPLICATION_ARGUMENT_MISMATCH"
              (Just "kappa.application.argument-mismatch")
              "an explicit TypeLevel argument is required; expected-type schema reification does not supply ordinary explicit arguments (§11.1.2.3A.1)"
          pure levelDomain
        _ -> pure False
    -- §16.1.7.1: a failed suspension insertion at an application
    -- boundary is an application-argument error
    suspInsert wrap expd a = do
      retag <- gets csArgIndexRetag
      nBefore <- gets (length . csDiags)
      body <- check ctx expr a
      suspensionType <- quoteIn ctx expd
      when retag (retagNewMismatches nBefore)
      pure (wrap body (Just suspensionType))
    -- §16.1.7.1 suspension insertion in Thunk/Need position.  Elaborate the
    -- expression ONCE (inference): if it is already a suspension (its type
    -- unifies with the expected Thunk/Need type), use it as-is; if its type is
    -- the content type @a@, suspend the already-elaborated term; otherwise (the
    -- expression needs expected-type-directed checking — e.g. a bare literal or
    -- a variant injection) fall back to checking it against @a@.  Reusing the
    -- inferred term is essential: without it a nested chain of Thunk-argument
    -- operators (e.g. `||`/`&&`) re-elaborated its tail at every level once for
    -- the speculative inference and again for the checking insertion, which is
    -- EXPONENTIAL in nesting depth (the H-4 self-hosting pathology).
    suspendOrInfer wrap expd a = do
      saved <- get
      retag <- gets csArgIndexRetag
      nBefore <- gets (length . csDiags)
      (tm, ty) <- infer ctx expr
      afterInfer <- get
      okT <- unify ctx ty expd -- already a Thunk/Need value?
      if okT
        then pure tm
        else do
          put afterInfer -- discard the failed unification, keep the inference
          okA <- unify ctx ty a -- a plain value of the content type?
          if okA
            then do
              -- suspend the already-elaborated term (no re-elaboration); retag
              -- any mismatch diagnostics from the inference to the argument
              -- index, exactly as the checking-mode 'suspInsert' would, so the
              -- diagnostic code/family is identical to the pre-fix path.
              when retag (retagNewMismatches nBefore)
              suspensionType <- quoteIn ctx expd
              pure (wrap tm (Just suspensionType))
            else put saved >> suspInsert wrap expd a -- needs checking-mode against a
    firstImplicit (b : _) = bImplicit b
    firstImplicit [] = False
    isExplicitArg = \case
      ArgExplicit _ -> True
      _ -> False
    isHole = \case
      EHole {} -> True
      _ -> False
    isVariant = \case
      EVariant {} -> True
      _ -> False

-- helper shared by section desugarings
lamSection :: Span -> Text -> (Expr -> Expr) -> Expr
lamSection sp nm f =
  ELambda Nothing [simpleBinder (Name nm sp)] (f (EVar (Name nm sp))) sp

-- expected-type-directed injection / widening (§13.1.3)
injectInto :: Ctx -> Term -> Value -> [Value] -> Value -> Span -> CheckM Term
injectInto ctx tm ty members expected sp = do
  t <- forceM ty
  case t of
    VVariantT src -> do
      srcTags <- mapM (tagOf ctx) src
      tgtTags <- mapM (tagOf ctx) members
      if all (`elem` tgtTags) srcTags
        then pure tm
        else do
          expectType ctx sp ty expected
          pure tm
    _ -> do
      tag <- tagOf ctx t
      tags <- mapM (tagOf ctx) members
      if tag `elem` tags
        then pure (CInject tag tm)
        else do
          expectType ctx sp ty expected
          pure tm

-- | Stable member identity of a variant member type (§31.3): rendered
-- from the alias-normalized type so @Int@ and @Integer@ coincide.
tagOf :: Ctx -> Value -> CheckM Text
tagOf ctx v = do
  ec <- ec_
  pure (semanticTypeTag ec (ctxLen ctx) v)

inferType :: Ctx -> Expr -> CheckM (Term, Level)
-- A conditional type needs a fresh result ceiling before either branch is
-- checked. Inferring through the generic expression path would solve its
-- result meta from the first branch and only lift later branches, making the
-- principal universe depend on source order. The level solver instead joins
-- every branch constraint to the least ceiling (for example max u v).
inferType ctx (EIf alts mels sp) =
  do
    resultLevel <- freshLevelMeta
    tm <- checkIf (withVarReadBlock VarReadStaticPosition ctx) alts mels sp (VSort resultLevel)
    pure (tm, resultLevel)
-- A match in type position selects the type facet in its arms
-- (dependent-match types, §17.1.4) and uses the same least-ceiling join as a
-- conditional. Hard-coding Type0 here rejects valid higher-universe arms.
inferType ctx (EMatch scrut cases msp) =
  do
    resultLevel <- freshLevelMeta
    tm <- checkMatch (withVarReadBlock VarReadStaticPosition ctx) scrut cases msp (VSort resultLevel)
    pure (tm, resultLevel)
inferType ctx e =
  do
    (tm, ty) <- inferT ctx e
    goSortType ctx e tm ty

-- | Reduce an elaborated type-position @(term, inferred-type)@ pair to a
-- @(term, universe-level)@ pair, or raise @E_NOT_A_TYPE@.  Shared by
-- 'inferType' and the §11.4.2 boolean-proposition coercion below.
goSortType :: Ctx -> Expr -> Term -> Value -> CheckM (Term, Level)
goSortType ctx e tm0 ty0 = do
  -- A type-former occurrence is a complete application boundary.  Omitted
  -- implicit parameters, including generated erased universe-constraint
  -- proofs, are synthesized here before deciding whether the expression is a
  -- type.  Keeping raw Pis here would make a constrained nominal family cease
  -- to be usable as a type unless callers wrote compiler-generated proofs.
  (tm, ty) <- insertAllImplicits ctx (exprSpan e) tm0 ty0
  t <- forceM ty
  case t of
    VSort n -> pure (tm, n)
    VFlex m [] -> do
      -- An unresolved classifier used in a type position is not evidence that
      -- the type is small. Give it a source-observable universe choice and
      -- let the enclosing declaration SCC principalize/generalize that level.
      -- Defaulting here to Type0 monomorphized inferred outer binders when a
      -- nested local annotation mentioned them.
      level <- freshGeneralizableLevelMeta
      solveMeta m (VSort level)
      pure (tm, level)
    -- compatibility accommodation for the external corpus: `IO a`
    -- written for `IO ?e a` (§18.1 IO : Type -> Type -> Type); the
    -- missing error parameter becomes a fresh metavariable
    VPi Expl _ _ _ _ _
      | CApp Expl headTm@(CGlobal g _) argTm <- tm
      , g == prelIO -> do
          m <- freshMeta
          pure (CApp Expl (CApp Expl headTm m) argTm, LZero)
    other -> do
      oT <- quoteIn ctx other
      errAt (exprSpan e) "E_NOT_A_TYPE" (Just "kappa.type.mismatch")
        ("expected a type; this expression has type " <> renderTerm oT)
      pure (tm, LZero)

-- | §11.4.2 Boolean-to-type coercion.  In the three sugar positions — an
-- implicit binder annotation @(\@x : b)@, the left of @b => T@, and a bare
-- boolean record/tuple field type — a @Bool@-typed expression @b@ in type
-- position is coerced to the proposition @(b = True)@.  Elaboration proceeds
-- exactly like 'inferType', except that when the expression classifies not as
-- a type but as a value of type @Bool@ (and ONLY @Bool@), we re-elaborate
-- @(b = True)@ via the ordinary @=@ propositional-equality construction
-- instead of raising @E_NOT_A_TYPE@.  Any other non-type expression (a bare
-- @Int@, an ADT value, a partially applied function, a @String@, …) still
-- raises @E_NOT_A_TYPE@ exactly as before — there is no general value→type
-- coercion.
inferTypeBoolProp :: Ctx -> Expr -> CheckM (Term, Level)
inferTypeBoolProp ctx e = (\(tm, lvl, _) -> (tm, lvl)) <$> inferTypeBoolProp' ctx e

-- | As 'inferTypeBoolProp', but also report whether the boolean-proposition
-- coercion actually fired.  The implicit-binder site (§11.4.2) uses the flag
-- to set the binder's quantity to @0@ when no quantity was written, since the
-- resulting @b = True@ is an erased compile-time proposition (§16.3, §13.2.1).
inferTypeBoolProp' :: Ctx -> Expr -> CheckM (Term, Level, Bool)
inferTypeBoolProp' ctx e = do
  old <- gets csAllowSchemaLevelTerms
  modify' $ \st -> st {csAllowSchemaLevelTerms = True}
  result@(tm, _, _) <- inferTypeBoolPropRaw
  modify' $ \st -> st {csAllowSchemaLevelTerms = old}
  when (termContainsSchemaLevel tm) $ do
    authenticated <- schemaLevelTermsAuthenticated tm
    unless authenticated $
      errAt (exprSpan e) "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
        "a declaration-universe parameter may occur here only in a compiler-authenticated erased level-comparison proposition (§11.1.2.3A.1)"
  pure result
  where
    inferTypeBoolPropRaw
      | EMatch {} <- e = (\(tm, lvl) -> (tm, lvl, False)) <$> inferType ctx e
      | otherwise = do
          (tm0, ty0) <- inferT ctx e
          (tm, ty) <- insertAllImplicits ctx (exprSpan e) tm0 ty0
          t <- forceM ty
          case t of
            -- the expression has type `Bool` (no spine; `Bool` is parameterless):
            -- coerce `b` to the proposition `(b = True)` using the primitive `=`
            -- type-former. Do not re-elaborate @b@: doing so would create a second
            -- set of evidence metas, and a signature could then retain a different
            -- (half-zonked) dictionary term from its definition annotation. At this
            -- point all explicit operands have constrained the first elaboration, so
            -- resolve and zonk its pending evidence before embedding it in the type.
            VGlobI g _ [] | g == prelBool -> do
              flushPending
              boolTm <- zonkTermM (ctxLen ctx) tm
              boolHead <- globalHeadM prelBool
              eqTm <- globalType prelEqType >>= \case
                Just (headTm, _) -> pure headTm
                Nothing -> do
                  errAt (exprSpan e) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
                    "the canonical equality declaration is unavailable while elaborating a Bool proposition"
                  pure (CGlob prelEqType)
              boolType <- globalValueM prelBool []
              trueTerm <- generatedCtorAtM ctx boolType prelTrue
              let propTm =
                    CApp Expl
                      (CApp Expl
                        (CApp Impl eqTm boolHead)
                        boolTm)
                      trueTerm
              pure (propTm, LZero, True)
            -- not `Bool`: ordinary type-position behavior (including E_NOT_A_TYPE).
            _ -> (\(tm', lvl') -> (tm', lvl', False)) <$> goSortType ctx e tm ty

    termContainsSchemaLevel = getAny . foldTerm termHasLevel (const mempty)
    termHasLevel = \case
      CLevel _ -> Any True
      _ -> Any False

-- | Check the §11.1.2.3A.1 capability boundary structurally. A schema-level
-- value is legal only below a proposition whose comparison head, TypeLevel
-- carrier, and selected Ord dictionary all authenticate by identity. The
-- elaborator calls this at every type-forming boundary, including an outer Pi
-- whose codomain contains a later proof binder, so requiring the whole term to
-- be one comparison incorrectly rejects valid nested telescopes.
--
-- Authenticated proposition subtrees are opaque to the residual scan. Any
-- CLevel left after pruning them occurred outside the capability and is
-- rejected. Same-spelling user operations remain excluded because
-- 'typeLevelRelationSpine' is the sole trust boundary.
schemaLevelTermsAuthenticated :: Term -> CheckM Bool
schemaLevelTermsAuthenticated term = do
  authenticated <- filterM authenticates candidates
  let prune _ candidate
        | candidate `elem` authenticated = Just (CSort LZero)
        | otherwise = Nothing
      residual = mapTermWithDepth prune 0 term
  pure (not (containsSchemaLevel residual))
  where
    candidates =
      nub
        [ candidate
        | candidate <- foldTerm (: []) (const []) term
        , isJust (boolEqualityTruePayload candidate)
        ]

    authenticates candidate = case boolEqualityTruePayload candidate of
      Just relation -> isJust <$> typeLevelRelationSpine relation
      Nothing -> pure False

    containsSchemaLevel = getAny . foldTerm termHasLevel (const mempty)
    termHasLevel = \case
      CLevel _ -> Any True
      _ -> Any False

-- type-position inference: prefer the type facet for head names (§7.2).
inferT :: Ctx -> Expr -> CheckM (Term, Value)
inferT ctx0 e = case e of
  EUniverseInstantiation base universes sp ->
    inferUniverseInstantiation True ctx base universes sp
  EApp (EVar n) arguments@[ArgExplicit levelExpr]
    | nameText n == "Type" -> do
        bound <- nameHasOrdinaryBinding ctx n
        if bound
          then do
            (function, functionType) <- inferT ctx (EVar n)
            elabTypeSpine ctx (nameSpan n) function functionType arguments
          else inferUniverseApp ctx levelExpr
  EVar n
    | nameText n == "Type" -> do
        bound <- nameHasOrdinaryBinding ctx n
        if bound
          then infer ctx (EVar n)
          else do
            level <- bareTypeLevel (nameSpan n)
            pure (CSort level, VSort (levelSucc level))
  -- in type position a universe spelling (incl. '*') is the universe
  EVar n
    | Just lvl <- sortName (nameText n) -> do
        bound <- nameHasOrdinaryBinding ctx n
        if bound
          then infer ctx (EVar n)
          else pure (CSort lvl, VSort (levelSucc lvl))
  EVar n
    | Nothing <- lookupCtx (nameText n) ctx
    , Nothing <- sortName (nameText n) -> do
        mthis <- gets csThis
        case mthis of
          -- §13.2.1/§13.2.11: dependent record and existential telescope
          -- siblings are ordinary type-position bindings too.  Existential
          -- witnesses deliberately have no local CVar; their stable Core
          -- representation is the same `this.field` projection used by
          -- dependent records.
          Just (ThisType fields)
            | isJust (find ((== nameText n) . rfName) fields) -> infer ctx e
          -- §14.2.1: trait-body sibling members shadow same-spelling
          -- globals, also in type position.
          Just (ThisTraitSibs fields)
            | isJust (find ((== nameText n) . rfName) fields) -> infer ctx e
          Just (ThisValue _ fields)
            | isJust (find ((== nameText n) . rfName) fields) -> infer ctx e
          _ -> do
            mg <- lookupGlobalName (nameText n)
            case mg of
              Just g -> do
                mt <- globalTypeIn ctx (nameSpan n) g
                case mt of
                  Just r -> pure r
                  Nothing -> infer ctx e
              Nothing -> infer ctx e
  -- compatibility accommodation for the external corpus: the corpus
  -- writes the §12.4 sized array as 'Array n elem' over the prelude
  -- collection carrier 'Array : Type -> Type'. The size index is kept
  -- for definitional equality inside a phantom '__sizedOf n elem'
  -- element, so 'Array n a ≡ Array m a' iff 'n ≡ m'.
  EApp (EVar hd) [ArgExplicit nE, ArgExplicit elemE]
    | nameText hd == "Array"
    , Nothing <- lookupCtx "Array" ctx -> do
        mg <- lookupGlobalName "Array"
        if mg /= Just prelArray
          then do
            (fTm, fTy) <- inferT ctx (EVar hd)
            elabTypeSpine ctx (nameSpan hd) fTm fTy [ArgExplicit nE, ArgExplicit elemE]
          else do
            natType <- globalValueM prelNat []
            nTm <- check ctx nE natType
            (elemTm, elemLvl) <- inferType ctx elemE
            sized <- globalAppM prelSizedOf [(Expl, nTm), (Expl, elemTm)]
            array <- globalAppM prelArray [(Expl, sized)]
            pure (array, VSort elemLvl)
  -- §11.3.1 row constraints take field labels: 'LacksRec r age'
  -- elaborates the label to a string literal
  EApp (EVar hd) [ArgExplicit rowE, ArgExplicit (EVar lbl)]
    | nameText hd == "LacksRec"
    , Nothing <- lookupCtx "LacksRec" ctx
    , Nothing <- lookupCtx (nameText lbl) ctx -> do
        recRow <- globalValueM prelRecRow []
        rowTm <- check ctx rowE recRow
        lacks <- globalAppM prelLacksRec [(Expl, rowTm), (Expl, CLit (LitStr (nameText lbl)))]
        pure (lacks, VSort LZero)
  -- §14.2.1 associated static member family application in type position.
  -- Resolve the member through its declaring trait identity before elaborating
  -- its ordinary checked application spine; receiver-dot sugar is inapplicable
  -- because associated types have no receiver-marked runtime binder.
  EApp (EDot (EVar traitName) (DotName memberName)) args -> do
    traitStaticMemberHead traitName memberName >>= \case
      Just (traitArity, memberTerm, memberType) ->
        withArgFlatFor e
          ( elabTypeSpine ctx (nameSpan memberName) memberTerm memberType
              (associatedStaticMemberArgs traitArity args)
          )
      Nothing -> do
        let functionExpr = EDot (EVar traitName) (DotName memberName)
        (functionTerm, functionType) <- inferT ctx functionExpr
        withArgFlatFor functionExpr
          (elabTypeSpine ctx (nameSpan memberName) functionTerm functionType args)
  EApp f args -> do
    (fTm, fTy) <- inferT ctx f
    withArgFlatFor f (elabTypeSpine ctx (exprSpan f) fTm fTy args)
  -- a parenthesized tuple in type position is a positional record type
  -- (§13.1): (Integer, String) ≡ (_1 : Integer, _2 : String)
  ETuple es _ -> do
    fieldsL <- forM (zip [1 :: Int ..] es) $ \(i, fe) -> do
      -- §11.4.2: a positional tuple field that is a bare boolean expression is
      -- coerced to its `(b = True)` proposition, the same as a named field.
      (t, lvl) <- inferTypeBoolProp ctx fe
      pure (("_" <> T.pack (show i), t), lvl)
    let fields = map fst fieldsL
        lvl = foldr levelMax LZero (map snd fieldsL)
    pure (CRecordT fields, VSort lvl)
  -- §7.2: in type position a module-qualified name selects the TYPE
  -- facet of a same-spelling data family (term position prefers the
  -- constructor facet)
  EDot base (DotName m)
    | Just segNames <- dottedPathOf base
    , (b : restSegs) <- map nameText segNames
    , Nothing <- lookupCtx b ctx -> do
        st <- get
        let mmn = case Map.lookup b (csModuleAliases st) of
              Just target
                | null restSegs -> Just target
              _
                | ModuleName (b : restSegs) == csModule st -> Just (csModule st)
                | Map.member (ModuleName (b : restSegs)) (csModuleExports st) ->
                    Just (ModuleName (b : restSegs))
                | null restSegs && Map.member (ModuleName [b]) (csModuleExports st) ->
                    Just (ModuleName [b])
                | otherwise -> Nothing
        case mmn of
          Just mn
            | g <- GName mn (nameText m)
            , Map.member g (csGlobals st) -> do
                mr <- globalTypeIn ctx (nameSpan m) g
                case mr of
                  Just r -> pure r
                  Nothing -> infer ctx e
          _ -> infer ctx e
  _ -> infer ctx e
  where
    ctx = withVarReadBlock VarReadStaticPosition ctx0
    dottedPathOf = \case
      EVar b -> Just [b]
      EDot b (DotName n) -> (++ [n]) <$> dottedPathOf b
      _ -> Nothing

elabForall :: Ctx -> [Binder] -> Expr -> CheckM (Term, Value)
elabForall ctx0 bs0 body = do
  (tm, lvl) <- go ctx0 bs0
  -- §11.1/§11.3: the quantified type lives in the modal formation ceiling.
  -- An unannotated `forall a.` binds `a : Type ?u`, where ?u is fresh; the
  -- declaration boundary later solves or generalizes that level.
  pure (tm, VSort lvl)
  where
    go ctx [] = inferType ctx body
    go ctx (b : rest) = do
      (domTm, domLvl, coerced, mSource) <- case bType b of
        Just t -> do
          domE <- normalizeBinderDomain ctx b t
          (tm, lvl, wasCoerced) <- withGeneralizableBareTypeLevels $
            if bImplicit b then inferTypeBoolProp' ctx domE else (\(x, l) -> (x, l, False)) <$> inferType ctx domE
          pure (tm, lvl, wasCoerced, Just domE)
        Nothing -> do
          level <- freshGeneralizableLevelMeta
          pure (CSort level, levelSucc level, False, Nothing)
      domV <- evalIn ctx domTm
      let nm = maybe "_" nameText (bName b)
          -- §11.3: every source @forall@ binder is implicit and quantity 0.
          -- Writing the domain changes domain inference, not application.
          ic = Impl
          ordinaryDefault = Q0
      (mode, q) <- resolveBinderModeQ ctx b domV ordinaryDefault
      mBound <- case mSource of
        Just source -> levelAssumptionFromExpr ctx (Just domTm) source
        _ -> pure Nothing
      ctxWithBound <- extendLevelAssumption (bSpan b) ctx mBound
      let ctx' = bindCtxMQ mode q nm True domV ctxWithBound
      (restTm, restLvl) <- go ctx' rest
      formation <- selectFormationMode ctx mode domV
      let domContribution = formationContribution formation domLvl
      let (restTm', restCeiling) = formationCeilingTerm ctx' restLvl restTm
      levelBinder <- isTypeLevelValue domV
      let escapes = levelBinder && ctxLen ctx `elem` levelVars restCeiling
      when escapes $
        reportUnboundedTelescope ctx' (bSpan b) "forall telescope" nm restCeiling
      pure
        ( CPiBoundFormedM mode formation ic q False nm mBound domTm restTm'
        , levelMax domContribution (if escapes then LZero else restCeiling)
        )

-- | §13.2.11 anonymous existential package types. @exists (a1:S1)
-- ... (an:Sn). T@ is surface sugar that elaborates to the §13.2.10
-- sealed-package machinery: a closed signature type whose first members
-- are the hidden witnesses (each an @opaque 0@ member) and whose
-- remaining member(s) are the payload view of @T@:
--
--   * a record/signature payload contributes its fields directly,
--     under their source labels (these are source-addressable);
--   * any other payload becomes one anonymous payload member under the
--     internal label '⟨payload⟩' (not source-addressable).
--
-- Witness binder names are binders only (Spec.md 13321): each elaborates
-- to an internal member label '⟨wit_i⟩' that source code cannot spell,
-- so witnesses are never projectable and never rendered as public
-- fields (Spec.md 13314, 13316-13317). The binder name resolves to its
-- witness during elaboration through the §13.2.1 'this'-sibling
-- machinery; we then rename those @this.<binder>@ projections to the
-- internal label so the field telescope refers to the witness by its
-- canonical internal name. Witnesses being @opaque 0@ are erased static
-- metadata (§31.2). Internal labels are position-based so alpha-equivalent
-- existential types elaborate to the same shape (Spec.md 13322).
elabExists :: Ctx -> [Binder] -> Expr -> Span -> CheckM (Term, Value)
elabExists ctx bs body sp = do
  -- distinct witness names (§13.2.11 surface-name restriction)
  let witNames = [maybe "_" nameText (bName b) | b <- bs]
  forM_ (duplicatesOf (filter (/= "_") witNames)) $ \n ->
    errAt sp "E_RECORD_DUPLICATE_FIELD" (Just "kappa-hs.record.duplicate-field")
      ("an 'exists' type binds the witness name '" <> n <> "' more than once (§13.2.11)")
  -- binder name -> internal witness label (positional). Anonymous '_'
  -- binders still occupy a witness slot but carry no source name.
  let labelOf = zip witNames (map existsWitLabel [0 ..])
  -- elaborate the witness telescope, each field seeing earlier witnesses
  -- through 'this' (the package), then the payload view
  (witFields, bodyCtx) <- goWits labelOf ctx [] (zip3 [0 ..] witNames bs)
  -- (internal label, type) oldest-first, with binder names exposed under
  -- 'this' for resolving later witness/body references
  let witDone = [RecordField n mode formation q bound v | (n, _, mode, formation, q, bound, _, v, _) <- witFields]
  (rawBodyLvl, payloadFields0) <- withThis (Just (ThisType witDone)) (payloadView bodyCtx)
  let bodyLvl = formationCeiling bodyCtx rawBodyLvl
      payloadFields0' =
        [ if rfName field == existsPayloadLabel
            then field {rfType = fst (formationCeilingTerm bodyCtx rawBodyLvl (rfType field))}
            else field
        | field <- payloadFields0
        ]
  unless (null (levelFields bodyLvl)) $
    reportUnboundedTelescope bodyCtx sp "existential telescope" "payload" bodyLvl
  -- rename binder-name 'this' projections in the payload to the internal
  -- witness labels, mirroring the witness telescope
  let payloadFields =
        [ field
            { rfType = renameThisLabels labelOf (rfType field)
            , rfLevelAssumption = renameLevelFieldAssumption labelOf (rfLevelAssumption field)
            }
        | field <- payloadFields0'
        ]
      allFields = [RecordField lbl mode formation q bound t | (_, lbl, mode, formation, q, bound, t, _, _) <- witFields] ++ payloadFields
      fields = allFields
      opaqs = sort [lbl | (_, lbl, _, _, _, _, _, _, _) <- witFields]
      -- §11.1: the existential's universe is the max over the witness
      -- domains and the body; unannotated witnesses use a fresh level.
      lvl = foldr levelMax LZero (bodyLvl : [wl | (_, _, _, _, _, _, _, _, wl) <- witFields])
  pure (CSigT opaqs (CRecordTQ fields), VSort lvl)
  where
    -- each witness field, elaborated with prior witnesses in 'this'.
    -- The accumulator threads (binderName, type) so the binder name
    -- resolves to its witness; the produced field type is rewritten so
    -- its 'this' projections name the internal labels instead.
    goWits _ levelCtx _ [] = pure ([], levelCtx)
    goWits labelOf levelCtx done ((i, nm, b) : rest) = do
      let thisMode = Just (ThisType (reverse done))
      (t0, rawWlvl) <- withThis thisMode $ case bType b of
        Just t -> withGeneralizableBareTypeLevels $
          normalizeBinderDomain levelCtx b t >>= inferType levelCtx
        Nothing -> do
          level <- freshGeneralizableLevelMeta
          pure (CSort level, levelSucc level)
      let t0' = renameThisLabels labelOf t0
      tV <- evalIn levelCtx t0'
      (mode, q) <- resolveBinderModeQ levelCtx b tV QW
      formation <- selectFormationMode levelCtx mode tV
      let contributed = formationContribution formation rawWlvl
          (t0'', wlvl) = case formation of
            FormationParametric -> (t0', contributed)
            FormationOrdinary -> formationCeilingTerm levelCtx contributed t0'
      unless (null (levelFields wlvl)) $
        reportUnboundedTelescope levelCtx (bSpan b) "existential telescope" nm wlvl
      mBound0 <-
        withThis thisMode $ case bType b of
          Just t -> levelAssumptionFromExpr levelCtx (Just t0') t
          Nothing -> pure Nothing
      let mBound = renameLevelFieldAssumption labelOf mBound0
      nextCtx0 <- extendLevelAssumption (bSpan b) levelCtx mBound
      nextCtx <- registerLevelField nextCtx0 nm tV
      -- expose the witness under its binder name for later references,
      -- but record the field under its internal label
      let lbl = existsWitLabel i
          ent = (nm, lbl, mode, formation, q, mBound, t0'', tV, wlvl)
      (later, finalCtx) <- goWits labelOf nextCtx (RecordField nm mode formation q mBound tV : done) rest
      pure (ent : later, finalCtx)
    -- the payload view of the existential body (§13.2.11), with the
    -- universe level the body type inhabits
    payloadView bodyCtx = do
      (tTm, bodyLvl) <- inferType bodyCtx body
      tV <- forceM =<< evalIn bodyCtx tTm
      flds <- case tV of
        -- record/signature payload: contribute its fields directly,
        -- under their source labels (source-addressable, Spec.md 13324)
        VRecordTQ fs -> recFields fs
        VSigT _ inner ->
          forceM inner >>= \case
            VRecordTQ fs -> recFields fs
            _ -> anonPayload tTm
        _ -> anonPayload tTm
      pure (bodyLvl, flds)
      where
        recFields fs = forM fs $ \field -> do
          fty <- quoteIn bodyCtx (rfType field)
          pure field {rfType = fty}
        -- one anonymous payload slot at quantity ω under the internal
        -- '⟨payload⟩' label (Spec.md 13316-13317, 13279-13280: not
        -- 'value', not source-addressable)
        anonPayload tTm = pure [RecordField existsPayloadLabel Ordinary FormationOrdinary QW Nothing tTm]

-- | Rewrite @this.<binderName>@ projections to @this.<internalLabel>@
-- inside an elaborated existential member type, per the binder->label
-- map. Only projections rooted at the §13.2.1 'this' neutral are
-- renamed (other projections keep their labels).
renameThisLabels :: [(Text, Text)] -> Term -> Term
renameThisLabels labelOf =
  zonkTermWith (\_ _ -> Nothing) renameLevel 0 . go
  where
    renameLevel = normalizeLevel . \case
      LField identity field ->
        LField identity (fromMaybe field (lookup field labelOf))
      LSucc level -> LSucc (renameLevel level)
      LAdd lhs rhs -> LAdd (renameLevel lhs) (renameLevel rhs)
      LMax lhs rhs -> LMax (renameLevel lhs) (renameLevel rhs)
      other -> other
    go t = case t of
      CUniverseLift from to evidence inner ->
        CUniverseLift from to evidence (go inner)
      CSchemaLift family source target roles evidence certificate sourceArguments targetArguments inner ->
        CSchemaLift family (map renameLevel source) (map renameLevel target) roles
          (map (mapSchemaRoleEvidence renameLevel) evidence) certificate
          (map go sourceArguments) (map go targetArguments) (go inner)
      CProjM mode e f
        | CGlob g <- e, g == thisG, Just lbl <- lookup f labelOf -> CProjM mode e lbl
        | otherwise -> CProjM mode (go e) f
      -- P0.4: renaming a this-label invalidates the fixed offset, so DROP to a
      -- name-based CProj when renamed; otherwise keep the CProjAt index.
      CProjAtM mode e f i
        | CGlob g <- e, g == thisG, Just lbl <- lookup f labelOf -> CProjM mode e lbl
        | otherwise -> CProjAtM mode (go e) f i
      CLamM mode ic q n b -> CLamM mode ic q n (go b)
      CPiEvidenceM mode formation ic q brw n assumption origin a b ->
        CPiEvidenceM mode formation ic q brw n assumption origin (go a) (go b)
      CApp ic f a -> CApp ic (go f) (go a)
      CCtorI g universes ann arguments ->
        CCtorI g universes (fmap go ann)
          [argument {caTerm = go (caTerm argument)} | argument <- arguments]
      CMatch s ann resultAnn alts ->
        CMatch
          (go s)
          (fmap go ann)
          (fmap go resultAnn)
          [CaseAlt p (fmap go gd) (go b) | CaseAlt p gd b <- alts]
      CRecordTQ fs -> CRecordTQ (map (fmap go) fs)
      CRecordV fs -> CRecordV [(n, go x) | (n, x) <- fs]
      CVariantT ms -> CVariantT (map go ms)
      CInject tag e -> CInject tag (go e)
      CLetM mode q n a b c -> CLetM mode q n (go a) (go b) (go c)
      CLetRecM mode q n a b c -> CLetRecM mode q n (go a) (go b) (go c)
      CLetPolyM mode q n telescope a b c ->
        CLetPolyM mode q n telescope (go a) (go b) (go c)
      CLetRecPolyM mode q n telescope a b c ->
        CLetRecPolyM mode q n telescope (go a) (go b) (go c)
      CLetRecGroupM telescope definitions body ->
        CLetRecGroupM telescope
          [definition {clrdType = go (clrdType definition), clrdRhs = go (clrdRhs definition)} | definition <- definitions]
          (go body)
      CSealE ls e -> CSealE ls (go e)
      CSigT ls e -> CSigT ls (go e)
      CThunkE e suspensionType -> CThunkE (go e) (go <$> suspensionType)
      CLazyE e suspensionType -> CLazyE (go e) (go <$> suspensionType)
      CForceE e resultType -> CForceE (go e) (go <$> resultType)
      CIf a b c -> CIf (go a) (go b) (go c)
      CQuote qs slots -> CQuote qs (map go slots)
      CGlobal _ _ -> t
      CLocal _ _ -> t
      CVar _ -> t
      CSort _ -> t
      CLevel _ -> t
      CLit _ -> t
      CMeta _ -> t
      CDo _ _ -> t

-- | Existential alpha-renaming applies to authenticated level assumptions as
-- well as their field types. Keeping either endpoint under a source witness
-- label would detach the proof metadata from the canonical hidden telescope.
renameLevelFieldAssumption
  :: [(Text, Text)]
  -> Maybe (Level, Level)
  -> Maybe (Level, Level)
renameLevelFieldAssumption labelOf = fmap (\(lower, upper) -> (renameLevel lower, renameLevel upper))
  where
    renameLevel = normalizeLevel . \case
      LField identity field ->
        LField identity (fromMaybe field (lookup field labelOf))
      LSucc level -> LSucc (renameLevel level)
      LAdd lhs rhs -> LAdd (renameLevel lhs) (renameLevel rhs)
      LMax lhs rhs -> LMax (renameLevel lhs) (renameLevel rhs)
      other -> other
-- | Preserve whether the enclosing call has a resolved ordinary-function
-- head while checking its argument. Nested applications must not replace that
-- outer diagnostic context with the nested expression's head classification.
withArgFlatFor :: Expr -> CheckM a -> CheckM a
withArgFlatFor function action = do
  previous <- gets csArgFlatOk
  checkingOuterArgument <- gets csArgIndexRetag
  ordinaryFunction <-
    if checkingOuterArgument
      then pure previous
      else case function of
        EOpRef {} -> pure False
        EVar name ->
          lookupGlobalName (nameText name) >>= \case
            Just global -> gets (not . Map.member global . csCtors)
            Nothing -> pure False
        _ -> pure False
  modify' $ \state -> state {csArgFlatOk = ordinaryFunction}
  result <- action
  modify' $ \state -> state {csArgFlatOk = previous}
  pure result

-- | Run an explicit-argument check with §16.1.7.1/§16.1.8 argument-index
-- retagging enabled, restoring the prior flag afterward. A mismatch
-- raised while checking an explicit argument against its parameter type
-- is reclassified as an application-argument error (see 'expectType').
withArgIndexRetag :: CheckM a -> CheckM a
withArgIndexRetag act = do
  old <- gets csArgIndexRetag
  modify' $ \st -> st {csArgIndexRetag = True}
  r <- act
  modify' $ \st -> st {csArgIndexRetag = old}
  pure r

-- | Check one explicit argument @e@ of quantity @q@ against the binder
-- domain @dom@, shared by the two application-spine algorithms (the
-- 'Slot'-folding 'step' and the recursive 'elabSpine'). The argument is
-- checked under the binder's demand ('demandOfQ') with argument-index
-- retagging enabled (§16.1.7.1) so any equality mismatch is attributed
-- to this argument slot. A non-type argument supplied to a type-former's
-- @Type@ slot is an application-argument error rather than a plain
  -- mismatch (§16.1), so when @dom@ is a universe the freshly emitted
  -- mismatches are retagged via 'retagNewMismatches'; for the ordinary
  -- (non-sort) domain this branch is a no-op.
checkExplicitArg :: Ctx -> ObservationMode -> Q -> Expr -> Value -> CheckM Term
checkExplicitArg ctx mode q e dom = do
  domF <- forceM dom
  nBefore <- gets (length . csDiags)
  let ctx' =
        if q == Q0
          then withVarReadBlock VarReadStaticPosition ctx
          else ctx
  let underArgumentDemand =
        withArgIndexRetag . withDemand (demandOfQ q)
      checkArgument = underArgumentDemand (check ctx' e dom)
      inferArgument = underArgumentDemand (infer ctx' e)
  -- Generic application uses the ordinary checking relation. In particular,
  -- §12.1.1 permits outer-Pi observation subsumption for a transparent
  -- higher-order/type-former argument. Exact higher-kinded matching is a
  -- separate §14.3.2 rule and remains confined to 'instCheckHeadArgs'.
  -- A dependent application-planning meta must first see the operand's exact
  -- synthesized type.  Using only the directed checking relation here can
  -- discard information before a later evidence slot is selected: for
  -- example, capture-set subsumption may check @T captures (r)@ at @T@ and
  -- thereby ask for @DynamicType T@ instead of the capability-indexed
  -- @DynamicType (T captures (r))@.  Pin only metas authenticated as members
  -- of this application plan, and only when definitional conversion accepts
  -- the exact inferred type.  All other cases retain the ordinary checked
  -- path (including expected-type-directed literals and coercions).
  stateBeforeExact <- get
  planningFlexible <- do
    state <- get
    let domainTerm = quote (ecOf state) (ctxLen ctx) domF
        unsolved = Set.fromList (unsolvedMetasOf state domainTerm)
    pure
      (not
        ( Set.null
            (Set.intersection unsolved (csApplicationPlanningMetas state))
        ))
  exactArgument <-
    if planningFlexible && principalPlanningSynthesis e
      then do
        diagnosticsBeforeExact <- gets (length . csDiags)
        (term, actual) <- inferArgument
        actualShape <- peelCapturesM actual
        let synthesizedIsCallable = case actualShape of
              VPi {} -> True
              _ -> False
        exact <-
          if synthesizedIsCallable
            then pure False
            else unifyDefinitional ctx actual dom
        diagnosticsAfterExact <- gets (length . csDiags)
        if exact && diagnosticsAfterExact == diagnosticsBeforeExact
          then pure (Just term)
          else put stateBeforeExact >> pure Nothing
      else pure Nothing
  aTm <- maybe checkArgument pure exactArgument
  finishExplicitArgument ctx mode q e aTm domF
  case domF of
    VSort _ -> retagNewMismatches nBefore
    _ -> pure ()
  pure aTm

-- | Whether an explicit operand may soundly pin an application-planning meta
-- from its synthesized type. Unsuffixed overloaded literals have no principal
-- carrier in isolation: inference applies the §6.1.5 default, while checking
-- deliberately leaves @FromInteger ?a@ / @FromFloat ?a@ pending for later
-- operands and the expected result. An ascription or suffix makes the carrier
-- source-determined again and therefore follows the ordinary exact probe.
principalPlanningSynthesis :: Expr -> Bool
principalPlanningSynthesis = \case
  EIntLit _ Nothing _ -> False
  EFloatLit _ Nothing _ -> False
  _ -> True

-- | Record the observation/erasure obligations shared by ordinary checked
-- arguments and the exact inferred arguments used in instance heads.
finishExplicitArgument
  :: Ctx
  -> ObservationMode
  -> Q
  -> Expr
  -> Term
  -> Value
  -> CheckM ()
finishExplicitArgument ctx mode q expression term classifier = do
  when (q == Q0) $
    modify' $ \state ->
      state
        { csErasedArgumentSpans =
            Set.insert (exprSpan expression) (csErasedArgumentSpans state)
        }
  when (mode == Ordinary) $ do
    observation <- observationJudgmentForTerm ctx term classifier
    when (ojMode observation == Parametric) $
      reportParametricPromotion
        (exprSpan expression)
        "ordinary application argument"
        observation

-- | Instance-head higher-kinded arguments need both an exact check and the
-- classifier that the argument actually synthesized.  Retaining only the
-- expected trait-parameter classifier makes occurrence-local result ceilings
-- look source-owned and can publish a spuriously polymorphic dictionary.
--
-- Inference is transactional because an expected-directed form may not
-- synthesize on its own.  Such a form falls back to the established exact
-- checker; an inferred form contributes only source-owned classifier levels
-- that predate the probe.
inferExactExplicitArg
  :: Ctx
  -> ObservationMode
  -> Q
  -> Expr
  -> Value
  -> CheckM (Term, Set LevelMeta)
inferExactExplicitArg ctx mode q expression expected = do
  before <- get
  let preexistingMetaLimit = csNextMeta before
  diagnosticsBefore <- gets (length . csDiags)
  let ctx' =
        if q == Q0
          then withVarReadBlock VarReadStaticPosition ctx
          else ctx
      inferArgument =
        withArgIndexRetag
          (withDemand (demandOfQ q) (infer ctx' expression))
  (_term, actual) <- inferArgument
  compatible <- unifyDefinitional ctx actual expected
  diagnosticsAfter <- gets (length . csDiags)
  if compatible && diagnosticsAfter == diagnosticsBefore
    then do
      actualTerm <- quoteIn ctx actual >>= zonkTermM (ctxLen ctx)
      let sourceClassifierLevels =
            Set.filter (< preexistingMetaLimit)
              (Set.fromList (levelMetasOfTerm actualTerm))
      -- Classifier discovery is observational. Fresh global-occurrence metas
      -- and constraints created by this probe are implementation choices,
      -- never generated-dictionary schema parameters.
      put before
      checked <-
        withDefinitionalEqualityOnly
          (checkExplicitArg ctx mode q expression expected)
      expectedClassifierLevels <- unresolvedExpectedClassifierLevels ctx expected
      pure (checked, Set.union sourceClassifierLevels expectedClassifierLevels)
    else do
      put before
      term' <-
        withDefinitionalEqualityOnly
          (checkExplicitArg ctx mode q expression expected)
      expectedClassifierLevels <- unresolvedExpectedClassifierLevels ctx expected
      pure (term', expectedClassifierLevels)

-- | Preserve the unsolved part of a higher-kinded trait parameter's checked
-- classifier.  Exact checking has already assigned every level forced by a
-- monomorphic argument, so the residual metas are precisely the abstract
-- classifier dimensions that the generated instance dictionary must own.
-- Reading the expected classifier after checking avoids treating fresh
-- occurrence metas from the observational inference probe as source schema.
unresolvedExpectedClassifierLevels :: Ctx -> Value -> CheckM (Set LevelMeta)
unresolvedExpectedClassifierLevels ctx expected = do
  expectedTerm <- quoteIn ctx expected >>= zonkTermM (ctxLen ctx)
  pure (Set.fromList (levelMetasOfTerm expectedTerm))

checkObservedExpr
  :: Ctx
  -> Text
  -> ObservationMode
  -> Expr
  -> Value
  -> CheckM Term
checkObservedExpr ctx construct mode expression expected = do
  diagnosticsBefore <- gets (length . csDiags)
  term <- check ctx expression expected
  when (mode == Ordinary) $ do
    expected' <- forceM expected
    observation <- observationJudgmentForTerm ctx term expected'
    diagnosticsAfter <- gets csDiags
    let nestedPromotion =
          any
            ((== "E_PARAMETRIC_TYPE_PROMOTION") . dCode)
            (take (length diagnosticsAfter - diagnosticsBefore) diagnosticsAfter)
    when (ojMode observation == Parametric && not nestedPromotion) $
      reportParametricPromotion (exprSpan expression) construct observation
  pure term

withDefinitionalEqualityOnly :: CheckM a -> CheckM a
withDefinitionalEqualityOnly act = do
  old <- gets csDefinitionalEqualityOnly
  modify' $ \st -> st {csDefinitionalEqualityOnly = True}
  result <- act
  modify' $ \st -> st {csDefinitionalEqualityOnly = old}
  pure result

reportParametricPromotion :: Span -> Text -> ObservationJudgment -> CheckM ()
reportParametricPromotion sp demandedConstruct judgment =
  report $
    withPayload
      ( withPayloadField "witnessOrigin" origin $
          maybe id (withPayloadField "witnessLevel" . renderLevel) level $
            withPayloadField "witnessExpression" origin $
              withPayloadField "useSite" (T.pack (show sp)) $
                withPayloadField "demandedConstructKind" demandedConstruct $
                  withPayloadField "witnessSourceKind" "binder-or-projection" $
                    withPayloadField "generatedUse" "false" $
                      withPayloadField "nearestAnnotation" origin $
                        withPayloadField "expectedCapability" "ordinary-type-code" $
                          withPayloadField "actualCapability" "parametric-type-witness" $
                            payloadKind "parametric-type-promotion"
      ) $
      diag SevError StageElaborate "E_PARAMETRIC_TYPE_PROMOTION"
        (Just "kappa.type.parametric-promotion") sp
        "a parametric observation cannot be used where ordinary observation is required (§11.1.2.3B)"
  where
    origin = ojOrigin judgment
    level = case ojClassifier judgment of
      Just (ObservationType rho) -> Just rho
      _ -> Nothing

-- | Infer an ordinary application after syntax-directed application forms
-- (reflection queries, comprehensions, and associated static members) have
-- already had their chance to intercept it. Keeping this path explicit lets a
-- checked reflection query fall back to the ordinary action application
-- without recursively re-entering the convenience query rule.
inferOrdinaryApplication :: Ctx -> Expr -> [Arg] -> CheckM (Term, Value)
inferOrdinaryApplication ctx function arguments = do
  explicitRefFacetApp ctx function arguments >>= \case
    Just result -> pure result
    Nothing -> do
      projection <- projectionHead ctx function
      receiverProjection <-
        maybe
          (projRecvApp ctx function arguments)
          (const (pure Nothing))
          projection
      case (projection, receiverProjection) of
        (_, Just result) -> pure result
        (Just (global, info), _) ->
          elabProjApp ctx (exprSpan function) global info arguments
        _ -> withApplicationEvidenceScope $ do
          diagnosticsBefore <- gets (length . csDiags)
          (functionTerm, functionType) <- infer ctx function
          recordMultishotOpApplication
            ctx
            function
            arguments
            (exprSpan (EApp function arguments))
          headUnresolved <- case function of
            EVar {} -> do
              diagnostics <- gets csDiags
              pure
                ( any
                    ((== "E_NAME_UNRESOLVED") . dCode)
                    (take (length diagnostics - diagnosticsBefore) diagnostics)
                )
            _ -> pure False
          if headUnresolved
            -- Recovery (§3.1.14): once the head is unresolved, argument types
            -- are unknowable and must not emit a diagnostic cascade.
            then anyHole ctx
            else do
              let elaborateApplication =
                    withArgFlatFor function
                      ( elabSpineWith
                          ctx
                          (exprSpan function)
                          functionTerm
                          functionType
                          arguments
                      )
                  selectedSummon =
                    termHeadGlob (stripIdentityWrappers functionTerm)
                      == Just (gPrel "summon")
              (application, resultType) <-
                if selectedSummon
                  then withIncompleteSelfEvidenceForbidden elaborateApplication
                  else elaborateApplication
              canonical <-
                canonicalizeProviderEqualityProof
                  ctx
                  resultType
                  resultType
                  application
              pure (canonical, resultType)

-- | One planned argument slot of a checked application spine
-- ('elabAppChecked'): a kind-like implicit placeholder, an evidence
-- implicit resolved after result-type pre-unification, or an explicit
-- argument expression checked against its (pre-solved) domain.
data AppSlot
  = SlotKind ObservationMode Term Value
  | SlotInfer ObservationMode Term Value
  | SlotEvid ObservationMode Q Value Term Value
  | SlotImpl ObservationMode Q Expr Value MetaId Value
  | -- | An explicit argument slot, carrying the placeholder meta's id
    -- and value plus a 'Bool' that records whether the function's
    -- codomain actually depends on this argument. When 'False' (a
    -- non-dependent arrow), the placeholder meta is solved directly
    -- (O(1)) instead of unified (O(size)), since it never reaches the
    -- result type — see 'step'.
    SlotExpl ObservationMode Q Expr Value MetaId Value Bool
  | SlotReady Icit Term

data AppResultPreparation
  = AppResultDefinitionallyReady
  | AppResultNeedsCoercion

-- | Check an all-explicit application against an expected function
-- type by peeling the callee's Pi spine with placeholder metas. Result
-- preparation first solves every uniquely determined index so argument
-- lambdas see refined domains; explicit arguments then settle any remaining
-- placeholders, and the ordinary coercion path makes the final decision.
-- Falls back to infer-then-coerce when the nominal shape does not match.
elabAppChecked
  :: Ctx
  -> Expr
  -> [Arg]
  -> Value
  -> Span
  -> CheckM Term
elabAppChecked ctx f args expected sp = withArgFlatFor f $ do
  explicitRefFacetApp ctx f args >>= \case
    Just (tm, ty) -> do
      expectType ctx sp ty expected
      pure tm
    Nothing ->
      checkedMonadRefMethodApp ctx f args expected sp >>= \case
        Just tm -> pure tm
        Nothing -> checkedApplication
  where
    checkedApplication = do
          st0 <- get
          seeded <- expectedConstructorApplicationHead ctx f expected
          (fTm, fTy) <- maybe (infer ctx f) pure seeded
          planningMetasBefore <- gets csApplicationPlanningMetas
          plan <- peel fTy args []
          done <- case plan of
            Nothing -> pure Nothing
            Just (slots, resTy) -> do
              preparation <-
                prepareNominalResultForCheckedApplication ctx resTy expected
              case preparation of
                Nothing -> pure Nothing
                Just resultPreparation -> do
                  earlyEvidence <- earlyEvidenceDependencies slots
                  prepared <- traverse (prepareSlot earlyEvidence) slots
                  mtm <- case sequence prepared of
                    Nothing -> pure Nothing
                    Just readySlots ->
                      foldM
                        (\acc slot -> maybe (pure Nothing) (`step` slot) acc)
                        (Just fTm)
                        readySlots
                  case mtm of
                    Nothing -> pure Nothing
                    Just tm -> do
                      mapM_ validateKindSlot slots
                      case resultPreparation of
                        AppResultDefinitionallyReady ->
                          pure (Just tm)
                        AppResultNeedsCoercion ->
                          Just <$> coerceTerm ctx sp tm resTy expected
          modify' $ \state ->
            state {csApplicationPlanningMetas = planningMetasBefore}
          case done of
            Just tm -> do
              normalized <- canonicalizeSelectedNatOperation ctx tm
              canonicalizeProviderEqualityProof
                ctx
                expected
                expected
                normalized
            Nothing -> do
              put st0
              (tm, ty) <- infer ctx (EApp f args)
              (tm1, ty1) <- insertAllImplicits ctx sp tm ty
              coerceTerm ctx sp tm1 ty1 expected
    peel ty as0 acc = do
      tyF <- forceM ty
      case tyF of
        -- Generated declaration constraints precede the source telescope but
        -- are never supplied by a surface @payload. Resolve them and retry the
        -- same surface argument, matching 'elabSpineArgGeneral'.
        VPiEvidenceM mode _ Impl q _ _ _ BinderGenerated dom clo
          | ArgImplicit {} : _ <- as0 -> do
              (mid, m) <- freshMetaForWithId ctx dom
              mV <- evalIn ctx m
              ty' <- clApp clo mV
              modify' $ \state ->
                state
                  { csApplicationPlanningMetas =
                      Set.insert mid (csApplicationPlanningMetas state)
                  }
              peel ty' as0 (SlotEvid mode q dom m mV : acc)
        -- A supplied implicit is planned with a placeholder exactly like an
        -- explicit operand. Result-type pre-unification may determine its
        -- domain, but the source payload is still checked against that domain
        -- under §16.1.7.2 before the placeholder is reconciled.
        VPiBoundM mode Impl q _ _ _ dom clo
          | ArgImplicit e : as <- as0 -> do
              (mid, placeholder) <- freshMetaForWithId ctx dom
              modify' $ \state ->
                state
                  { csApplicationPlanningMetas =
                      Set.insert mid (csApplicationPlanningMetas state)
                  }
              placeholderValue <- evalIn ctx placeholder
              ty' <- clApp clo placeholderValue
              peel
                ty'
                as
                (SlotImpl mode q e dom mid placeholderValue : acc)
        -- kind-like implicits become bare placeholders; evidence
        -- implicits keep the ordinary resolution ladder, run after
        -- the result type has been unified with the expectation so
        -- the goal sees solved metas (§16.1.7.1, §6.1.5). Trailing
        -- implicits (e.g. §28.2.1 proof obligations) are saturated
        -- like 'insertAllImplicits' does on the inference path.
        VPiM mode Impl q _ _ dom clo -> do
          planningPlaceholder <-
            applicationImplicitIsPlanningParameter ctx q dom
          kindLike <- isKindLike (ctxLen ctx) dom
          (mid, m) <- freshMetaForWithId ctx dom
          when planningPlaceholder $
            modify' $ \state ->
              state
                { csApplicationPlanningMetas =
                    Set.insert mid (csApplicationPlanningMetas state)
                }
          mV <- evalIn ctx m
          ty' <- clApp clo mV
          let slot
                | kindLike = SlotKind mode m dom
                | planningPlaceholder = SlotInfer mode m dom
                | otherwise = SlotEvid mode q dom m mV
          peel ty' as0 (slot : acc)
        VPiM mode Expl q _ _ dom clo@(Closure _ cloBody)
          | (ArgExplicit e : as) <- as0 -> do
              (mid, placeholder) <- freshMetaForWithId ctx dom
              modify' $ \state ->
                state
                  { csApplicationPlanningMetas =
                      Set.insert mid (csApplicationPlanningMetas state)
                  }
              mV <- evalIn ctx placeholder
              ty' <- clApp clo mV
              let dep = coreUsesVar0 cloBody
              peel ty' as ((SlotExpl mode q e dom mid mV dep) : acc)
        _
          | [] <- as0 -> pure (Just (reverse acc, tyF))
          | otherwise -> pure Nothing
    step tm (SlotKind _ m _) = do
      pure (Just (CApp Impl tm m))
    step tm (SlotInfer _ placeholder _) = do
      pure (Just (CApp Impl tm placeholder))
    step tm (SlotEvid _ q dom placeholder placeholderValue) =
      resolveEvidenceSlot q dom placeholder placeholderValue >>= \case
        Just evidence -> pure (Just (CApp Impl tm evidence))
        Nothing -> pure Nothing
    step tm (SlotReady icit argument) =
      pure (Just (CApp icit tm argument))
    step _ SlotImpl {} = pure Nothing
    step _ SlotExpl {} = pure Nothing

    prepareSlot _ slot@SlotKind {} = pure (Just slot)
    prepareSlot _ slot@SlotInfer {} = pure (Just slot)
    prepareSlot early slot@(SlotEvid _ q dom placeholder placeholderValue) =
      case placeholder of
        CMeta meta
          | meta `Set.member` early ->
              fmap (SlotReady Impl) <$>
                resolveEvidenceSlot q dom placeholder placeholderValue
        _ -> pure (Just slot)
    prepareSlot _ slot@SlotReady {} = pure (Just slot)
    prepareSlot _ (SlotImpl mode q expression dom mid placeholderValue) = do
      flushPendingDeclaration
      domain <- forceM dom
      diagnosticsBefore <- gets (length . csDiags)
      argument <- checkExplicitArg ctx mode q expression domain
      retagExplicitImplicitFailure diagnosticsBefore
      argumentValue <-
        checkedArgumentValue ctx (exprSpan expression) domain argument
      placeholder <- forceM placeholderValue
      reconciled <-
        reconcileTypeLevelPlanningPlaceholder ctx mid placeholder argumentValue >>= \case
          Just solved -> pure solved
          Nothing -> case placeholder of
            VFlex meta [] | meta == mid -> do
              solved <- solveMetaAcyclic mid argumentValue
              if solved
                then pure True
                else unify ctx placeholder argumentValue
            _ -> unify ctx placeholder argumentValue
      pure (SlotReady Impl argument <$ guard reconciled)
    prepareSlot _ (SlotExpl mode q e dom mid mV dep) = do
      aTm <- checkExplicitArg ctx mode q e dom
      aV <- checkedArgumentValue ctx (exprSpan e) dom aTm
      -- The placeholder meta 'mid' was substituted into the result type
      -- in 'peel'. When the codomain depends on this argument we must
      -- 'unify' (it may meet an existing structure in the result). When
      -- it does NOT (a non-dependent arrow — the common case for
      -- operator/application chains), 'mid' appears nowhere in the
      -- result, so a direct O(1) 'solveMeta' is equivalent to the full
      -- 'unify' (which would otherwise 'quote' the whole argument value,
      -- costing O(size) per slot → O(n²) over a deep chain) yet keeps
      -- the meta-solution state byte-identical for downstream rendering
      -- and §3.1.11 cascade suppression.
      mVf <- forceM mV
      reconciled <-
        reconcileTypeLevelPlanningPlaceholder ctx mid mVf aV >>= \case
          Just solved -> pure solved
          Nothing -> case mVf of
            -- The placeholder was created for THIS explicit argument and is
            -- not in scope for the argument's domain, so the checked argument
            -- cannot contain it. If result pre-unification did not constrain
            -- the placeholder, direct solving is equivalent to unify's flex
            -- case but avoids quoting the whole argument value.
            VFlex m [] | m == mid -> do
              ok <- solveMetaAcyclic mid aV
              if ok
                then pure True
                else unify ctx mVf aV
            _ | dep -> unify ctx mVf aV
            _ -> pure True
      pure (SlotReady Expl aTm <$ guard reconciled)

    resolveEvidenceSlot q dom placeholder placeholderValue = do
      -- §3.2.3 proof obligations are postponed to the pending queue even when
      -- fully solved: branch facts may themselves depend on evidence metas.
      isEq <- isEqGoal dom
      evidence <-
        if isEq
          then resolveLocalOrPostponeEqualityEvidence ctx sp q dom
          else resolveImplicitQ ctx sp q dom
      evidenceValue <- evalIn ctx evidence
      placeholderForced <- forceM placeholderValue
      reconciled <- case (placeholder, placeholderForced) of
        -- The placeholder belongs to this evidence slot. Directly solving an
        -- unconstrained occurrence avoids normalizing a delayed proof merely
        -- to wire it into the checked application.
        (CMeta expectedMeta, VFlex actualMeta [])
          | expectedMeta == actualMeta -> do
              solved <- solveMetaAcyclic expectedMeta evidenceValue
              if solved
                then pure True
                else unify ctx placeholderForced evidenceValue
        _ -> unify ctx placeholderForced evidenceValue
      pure (evidence <$ guard reconciled)

    -- A dictionary must move into the preparation phase only when a later
    -- source operand's domain observes one of its associated projections.
    -- Unrelated evidence retains the historical assembly order, avoiding
    -- premature instance selection for ordinary parametric applications.
    earlyEvidenceDependencies slots = do
      state <- get
      let domainMetas slot = case slot of
            SlotImpl _ _ _ domain _ _ -> metasIn domain
            SlotExpl _ _ _ domain _ _ _ -> metasIn domain
            _ -> Set.empty
          metasIn value =
            Set.fromList
              (unsolvedMetasOf state (quote (ecOf state) (ctxLen ctx) value))
          go [] = (Set.empty, Set.empty)
          go (slot : rest) =
            let (early, later) = go rest
                here = case slot of
                  SlotEvid _ _ _ (CMeta meta) _
                    | meta `Set.member` later -> Set.singleton meta
                  _ -> Set.empty
             in (Set.union here early, Set.union (domainMetas slot) later)
      pure (fst (go slots))

    -- Kind-like implicits are inferred from later result/argument
    -- unification, but their inferred values must still inhabit their
    -- declared kinds. Solving @a@ in @(@0 a : Type u)@ to @Int@ therefore
    -- contributes @0 <= u@. If no classifier can be recovered, retain the
    -- blocked level meta; later proof/defaulting gates then fail closed.
    validateKindSlot = \case
      SlotKind _ meta expectedKind ->
        validateInferredKindArgument ctx sp meta expectedKind
      _ -> pure ()

-- | Reconcile the two representations of a checked @TypeLevel@ application
-- placeholder. The planner substitutes an 'LMeta' through the dependent
-- codomain while retaining the same stable id as a term meta. A supplied
-- argument fixes this private occurrence exactly, so commit its level graph
-- edge and checked semantic value together.
--
-- This helper is deliberately limited to metas authenticated as placeholders
-- of the current application plan. Declaration and general inference metas
-- continue to wait for complete constraint sets at principalization
-- boundaries.
reconcileTypeLevelPlanningPlaceholder
  :: Ctx
  -> MetaId
  -> Value
  -> Value
  -> CheckM (Maybe Bool)
reconcileTypeLevelPlanningPlaceholder ctx expectedMeta placeholder argument =
  case (placeholder, argument) of
    (VFlex meta [], VLevel candidate)
      | meta == expectedMeta ->
          reconcile meta candidate
    (VLevel (LMeta meta), VLevel candidate)
      | meta == expectedMeta ->
          reconcile meta candidate
    _ -> pure Nothing
  where
    reconcile meta candidate = do
      state <- get
      let authenticated =
            meta `Set.member` csApplicationPlanningMetas state
              && meta `Set.member` csFirstClassLevelMetas state
      if not authenticated
        then pure Nothing
        else do
          let assignments = csLevelAssignments state
              current =
                normalizeLevel
                  (substituteLevelMetas assignments (LMeta meta))
              candidate' =
                normalizeLevel
                  (substituteLevelMetas assignments candidate)
          levelOk <-
            if current == LMeta meta
              then
                if meta `elem` levelMetas candidate'
                  then pure False
                  else
                    installLevelAssignments (Map.singleton meta candidate')
                      >> pure True
              else solveLevelIdentity ctx current candidate'
          termOk <-
            if levelOk
              then solveMetaAcyclic expectedMeta (VLevel candidate')
              else pure False
          pure (Just termOk)

-- | Seed the uniform hidden family prefix of a constructor before planning a
-- checked application spine. The older expected-constructor arm in 'check'
-- runs after the generic all-explicit application arm, so nested GADT
-- applications such as @Step (Done 0) : V False@ otherwise allocate fresh
-- metas for family parameters that the constructor result constrains away.
--
-- Identity comes from the expected nominal family and its constructor table;
-- source spelling is only used to choose among that family's declared
-- constructors. A malformed or non-nominal expected type returns 'Nothing'
-- and the ordinary checked-application path remains fail closed.
expectedConstructorApplicationHead
  :: Ctx
  -> Expr
  -> Value
  -> CheckM (Maybe (Term, Value))
expectedConstructorApplicationHead ctx expression expected = do
  expected' <- forceM expected
  case (expression, expected') of
    (EVar name, VGlobN family _)
      | Nothing <- lookupCtx (nameText name) ctx -> do
          st <- get
          case Map.lookup family (csDatas st) >>= declaredConstructor st (nameText name) of
            Just (constructor, info) ->
              globalTerm constructor >>= \case
                Just (headTerm, headType) ->
                  applyExpectedConstructorFamilyPrefix ctx info expected headTerm headType
                Nothing -> pure Nothing
            Nothing -> pure Nothing
    _ -> pure Nothing
  where
    declaredConstructor st spelling dataInfo =
      listToMaybe
        [ (constructor, info)
        | constructor <- diCtors dataInfo
        , gnameText constructor == spelling
        , constructorInScope st constructor
        , Just info <- [Map.lookup constructor (csCtors st)]
        ]

validateInferredKindArgument :: Ctx -> Span -> Term -> Value -> CheckM ()
validateInferredKindArgument ctx sp meta expectedKind =
  forceM expectedKind >>= \case
    VSort ceiling -> do
      inferredValue <- evalIn ctx meta >>= forceM
      inferred <- typeValueClassifierLevel ctx inferredValue
      forM_ inferred $ \actual -> do
        assumptions <- effectiveLevelAssumptions ctx
        ok <- case proveLevelLeq assumptions actual ceiling of
          -- Cumulativity alone does not need to retain a tautology such as
          -- @0 <= ?u@. Principal inference does: the edge selects the least
          -- first-class TypeLevel argument compatible with every inferred
          -- kind slot, and the level solver joins sibling lower bounds before
          -- 'installLevelAssignments' reflects the result into the term meta.
          -- Record only meta-bearing ceilings here; rigid successful checks
          -- remain ordinary conversion facts with no deferred state.
          Proved | not (null (levelMetas ceiling)) -> do
            insertLevelConstraint assumptions
              (ConstraintOrigin "inferred kind argument" "implicit kind argument")
              actual ceiling
            pure True
          _ -> solveLevelInequality ctx actual ceiling
        if not ok
          then
            errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
              ( "inferred type argument has classifier Type " <> renderLevel actual
                  <> ", which does not fit the declared binder universe Type "
                  <> renderLevel ceiling <> " (§11.1.2.4)"
              )
          else
            universeEvidenceFor ctx sp actual ceiling >>= \case
              Just evidence -> recordInferredMetaUniverseCoercion meta evidence
              Nothing -> pure ()
    _ -> pure ()

-- | Attach a cumulative proof only to the typed inference meta whose
-- creation-site classifier was checked above. Non-meta generated arguments
-- are coerced directly by 'coerceTerm'; recovery terms deliberately do not
-- acquire guessed metadata.
recordInferredMetaUniverseCoercion :: Term -> UniverseEvidence -> CheckM ()
recordInferredMetaUniverseCoercion term evidence =
  case term of
    CMeta meta ->
      modify' $ \st ->
        st
          { csMetaClassifiers =
              Map.adjust
                (\classifier ->
                   classifier
                     { micUniverseCoercion =
                         micUniverseCoercion classifier <|> Just evidence
                     })
                meta
                (csMetaClassifiers st)
          }
    _ -> pure ()

-- | Recover the universe classifying an inferred type argument. This is a
-- read-only classifier over NbE values, backed by declared global/local types
-- and structural type formers. It deliberately returns 'Nothing' for stuck
-- eliminators instead of inventing a universe.
typeValueClassifierLevel :: Ctx -> Value -> CheckM (Maybe Level)
typeValueClassifierLevel ctx value0 = do
  value <- forceM value0
  case value of
    VSort rho -> pure (Just (levelSucc rho))
    VGlobN {} -> neutralClassifier value
    VRigid {} -> neutralClassifier value
    VRecordTQ fields -> structuralFields [(rfFormation f, rfType f) | f <- fields]
    VVariantT members -> foldLevels <$> traverse (typeValueClassifierLevel ctx) members
    VPiBoundFormedM mode formation _ q _ nm _ dom clo -> do
      domLevel <- typeValueClassifierLevel ctx dom
      let lvl = ctxLen ctx
          ctx' = bindCtxMQ mode q nm False dom ctx
      cod <- clApp clo (VRigid lvl [])
      codLevel <- typeValueClassifierLevel ctx' cod
      case (domLevel, codLevel) of
        (Just alpha, Just beta) -> do
          pure (Just (levelMax (formationContribution formation alpha) beta))
        _ -> pure Nothing
    VSigT _ inner -> typeValueClassifierLevel ctx inner
    _ -> pure Nothing
  where
    neutralClassifier value =
      equandType ctx value >>= \case
        Nothing -> pure Nothing
        Just ty -> forceM ty >>= \case
          VSort rho -> pure (Just rho)
          _ -> pure Nothing

    structuralFields fields = do
      levels <- forM fields $ \(formation, fieldTy) -> do
        typeValueClassifierLevel ctx fieldTy >>= \case
          Nothing -> pure Nothing
          Just alpha -> pure (Just (formationContribution formation alpha))
      pure (foldLevels levels)

    foldLevels levels =
      foldl levelMax LZero <$> sequence levels

-- | Specialize a unary universe-polymorphic trait at the classifier universe
-- of its carrier. Compiler-generated evidence lookup must use the declaration
-- schema's exact universe telescope: allocating an unconstrained occurrence
-- meta here can leak a spurious low-universe constraint into the surrounding
-- declaration. Traits with another source parameter shape must provide their
-- own checked construction rule.
unaryTraitGoalForCarrier
  :: Ctx
  -> GName
  -> Value
  -> CheckM (Maybe Value)
unaryTraitGoalForCarrier ctx trait carrier = do
  carrierLevel <- typeValueClassifierLevel ctx carrier
  definition <- gets (Map.lookup trait . csGlobals)
  pure $ do
    level <- carrierLevel
    global <- definition
    guard (dutParameterCount (gdUniverses global) == 1)
    pure (VGlobI trait [level] [(Expl, carrier)])

-- | Is the value a (possibly parameterized) type former — i.e. is its
-- final codomain a universe?
finalIsSort :: Ctx -> Value -> CheckM Bool
finalIsSort ctx v0 = go (ctxLen ctx) (8 :: Int) v0
  where
    go _ 0 _ = pure False
    go lvl fuel v = do
      vf <- forceM v
      case vf of
        VSort _ -> pure True
        VPi _ _ _ _ _ clo -> clApp clo (VRigid lvl []) >>= go (lvl + 1) (fuel - 1)
        _ -> pure False

-- | Apply a rewrite to every diagnostic reported since a marker.
-- @nBefore@ is the @length csDiags@ captured before the elaboration
-- step whose newly-added diagnostics are to be re-tagged; @retag@ is
-- the per-diagnostic rewrite (applied only to the new prefix, leaving
-- the older diagnostics untouched). Shared skeleton for the
-- count-and-rollback re-tag idiom (§3.1.4).
retagNew :: Int -> (Diagnostic -> Diagnostic) -> CheckM ()
retagNew nBefore retag = modify' $ \st ->
  let ds = csDiags st
      (new, old) = splitAt (length ds - nBefore) ds
   in st {csDiags = map retag new ++ old}

-- | Re-tag type mismatches reported since the marker as
-- application-argument errors (a literal in a Type parameter slot).
retagNewMismatches :: Int -> CheckM ()
retagNewMismatches nBefore = retagNew nBefore $ \d ->
  if dCode d == "E_TYPE_EQUALITY_MISMATCH"
    then d {dCode = "E_APPLICATION_ARGUMENT_MISMATCH", dFamily = Just "kappa.application.argument-mismatch"}
    else d

-- | A @let? ... else@ expression arm is checked against the whole
-- @m Void@ terminal contract (§18.2.1). Expected-directed checking is needed
-- to select @m@ before resolving overloaded operations, but it can expose an
-- inner numeric-literal witness failure for a branch such as @pure 42@. At
-- this boundary the primary failure is that the completed action is not an
-- @m Void@ action, so retain all unrelated diagnostics and reclassify only
-- that contextual literal failure as the enclosing type mismatch.
retagTerminalFailureArmMismatch :: Int -> CheckM ()
retagTerminalFailureArmMismatch nBefore = retagNew nBefore $ \diagnostic ->
  if dFamily diagnostic == Just "kappa.type.literal-domain-mismatch"
    then
      diagnostic
        { dCode = "E_TYPE_EQUALITY_MISMATCH"
        , dFamily = Just "kappa.type.mismatch"
        }
    else diagnostic

-- | §3.1.4/§16.1.7.2: re-tag any error diagnostics reported since the
-- marker with the portable @E_EXPLICIT_IMPLICIT_CLASSIFIER_MISMATCH@
-- code (family @kappa.application.explicit-implicit-classifier@). This
-- is the general rewrite for a failed elaboration of an explicit
-- implicit argument's @\@payload@ against the selected implicit
-- binder's demanded type or classifier: §16.1.7.2 step 6 says the
-- explicit implicit argument fails for that binder when the selected
-- elaboration mode fails, and §3.2 lists typing, classifier mismatch,
-- quantity mismatch, unresolved name, and ambiguous name as in-scope
-- payload-failure kinds — so the payload-internal code (whatever it
-- happens to be) is replaced rather than special-cased on its spelling.
retagExplicitImplicitFailure :: Int -> CheckM ()
retagExplicitImplicitFailure nBefore = retagNew nBefore $ \d ->
  if isError d && dFamily d /= Just "kappa.var.mutable-binding"
    then
      d
        { dCode = "E_EXPLICIT_IMPLICIT_CLASSIFIER_MISMATCH"
        , dFamily = Just "kappa.application.explicit-implicit-classifier"
        }
    else d

-- ── Projection applications (§16.1.5, §16.1.6) ───────────────────────

-- | Resolve an application head to a projection facet, if any.
projectionHead :: Ctx -> Expr -> CheckM (Maybe (GName, ProjInfo))
projectionHead ctx e = do
  mg <- staticGlobalExpr ctx e
  st <- get
  pure $ do
    g <- mg
    pj <- Map.lookup g (csProjections st)
    pure (g, pj)

projectionInfoOfExpr :: Ctx -> Expr -> CheckM (Maybe ProjInfo)
projectionInfoOfExpr ctx = \case
  EVar hn ->
    case lookupCtx (nameText hn) ctx of
      Just (_, e) -> pure (ceProjInfo e)
      Nothing -> do
        mg <- lookupGlobalName (nameText hn)
        st <- get
        pure $ mg >>= (`Map.lookup` csProjections st)
  e@EDot {} -> do
    mg <- staticGlobalExpr ctx e
    st <- get
    pure $ mg >>= (`Map.lookup` csProjections st)
  EAscription e _ _ -> projectionInfoOfExpr ctx e
  _ -> pure Nothing

-- | Resolve a source expression only when it is a static global path:
-- an unshadowed name, an import alias member, or a fully-qualified module path.
-- This is used by semantic recognizers such as projection facets; ordinary
-- field selection remains in 'elabDot'.
staticGlobalExpr :: Ctx -> Expr -> CheckM (Maybe GName)
staticGlobalExpr ctx = \case
  EVar hn
    | Nothing <- lookupCtx (nameText hn) ctx ->
        lookupGlobalName (nameText hn)
  -- Parenthesized operator references are ordinary static declaration
  -- references.  Keeping this case here (rather than recognizing a spelling
  -- in universe-instantiation code) makes @(=).{u}@ and any user-defined
  -- operator declaration follow the same resolved-identity path as @Box.{u}@.
  EOpRef _ hn _
    | Nothing <- lookupCtx (nameText hn) ctx ->
        lookupGlobalName (nameText hn)
  EDot base (DotName member) -> do
    st <- get
    case base of
      EVar (Name alias _)
        | Nothing <- lookupCtx alias ctx
        , Just mn <- Map.lookup alias (csModuleAliases st) ->
            pure (visibleMember st mn member)
      _ -> case modulePathOf base of
        Just segs@(firstSeg : _)
          | Nothing <- lookupCtx firstSeg ctx ->
              pure (visibleMember st (ModuleName segs) member)
        _ -> pure Nothing
  EAscription e _ _ -> staticGlobalExpr ctx e
  _ -> pure Nothing
  where
    visibleMember st mn member =
      let g = GName mn (nameText member)
       in if memberVisible st mn (nameText member)
            && (Map.member g (csGlobals st) || Map.member g (csCtors st) || Map.member g (csProjections st))
            then Just g
            else Nothing
    modulePathOf = \case
      EVar (Name s _) -> Just [s]
      EDot inner (DotName (Name s _)) -> (++ [s]) <$> modulePathOf inner
      _ -> Nothing

-- | Does a projection-head application supply every declared binder?
projFullApp :: ProjInfo -> [Arg] -> Bool
projFullApp pj args =
  all isExpl args && length args == length (pjIsPlace pj) && or (pjIsPlace pj)
  where
    isExpl = \case
      ArgExplicit _ -> True
      _ -> False

-- | Application of a named projection (§9.1.1): a full application in
-- declaration order supplies the place binders directly; otherwise the
-- ordinary term facet (descriptor) is applied (§16.1.5).
elabProjApp :: Ctx -> Span -> GName -> ProjInfo -> [Arg] -> CheckM (Term, Value)
elabProjApp ctx sp g pj args = do
  mt <- globalTerm g
  case mt of
    Nothing -> anyHole ctx
    Just (dTm, dTy) -> do
      (application, resultType) <-
        if projFullApp pj args
          then do
            let split = zip (pjIsPlace pj) args
                ordArgs = [a | (False, a) <- split]
                placePairs =
                  [ (nm, e)
                  | ((True, ArgExplicit e), nm) <-
                      zip [p | p@(True, _) <- split] (pjPlaceNames pj)
                  ]
            (dTm1, dTy1) <- elabSpine ctx sp dTm dTy ordArgs
            applyDescriptor ctx sp dTm1 dTy1 (RootsSeparate placePairs)
          else elabSpine ctx sp dTm dTy args
      canonical <-
        canonicalizeProviderEqualityProof
          ctx
          resultType
          resultType
          application
      pure (canonical, resultType)

-- | §7.4 receiver-projection sugar with trailing arguments: a
-- selector-form projection whose declaration has exactly one
-- receiver-marked @place@ binder is eligible for method-call sugar —
-- the receiver fills the place slot and the call-site arguments fill
-- the remaining binders in declaration order. A record field of the
-- receiver with the same name keeps §7.3 precedence.
projRecvApp :: Ctx -> Expr -> [Arg] -> CheckM (Maybe (Term, Value))
projRecvApp ctx (EDot recv (DotName mn)) args
  | all (\case ArgExplicit _ -> True; _ -> False) args
  , Nothing <- lookupCtx (nameText mn) ctx = do
      mg <- lookupGlobalName (nameText mn)
      st <- get
      case mg >>= \g -> (,) g <$> Map.lookup g (csProjections st) of
        Just (g, pj)
          | length (filter id (pjIsPlace pj)) == 1
          , length (pjIsPlace pj) == length args + 1
          , length (pjIsPlace pj) > 1 -> do
              shadowed <- fieldShadows
              if shadowed
                then pure Nothing
                else do
                  let fullArgs = weave (pjIsPlace pj) args
                  Just <$> elabProjApp ctx (exprSpan recv) g pj fullArgs
        _ -> pure Nothing
  where
    weave [] _ = []
    weave (True : rest) as = ArgExplicit recv : weave rest as
    weave (False : rest) (a : as) = a : weave rest as
    weave (False : rest) [] = weave rest [] -- unreachable by the length guard
    fieldShadows = do
      st0 <- get
      (_, rty) <- infer ctx recv
      rtyF <- forceM rty
      inner <- case rtyF of
        VSigT _ i -> forceM i
        t -> pure t
      put st0
      pure $ case inner of
        VRecordT fs -> nameText mn `elem` map fst fs
        _ -> False
projRecvApp _ _ _ = pure Nothing

-- | How the place arguments of a descriptor application are supplied.
data RootsSupply
  = RootsSeparate ![(Text, Expr)] -- ^ full application: place binder ↦ argument
  | RootsSingle !Expr -- ^ §16.1.5 single roots argument

-- | The accessor capabilities of a structural bundle record type
-- (§16.1.6): @Just [(field, roots, focus)]@ when every field is an
-- accessor descriptor.
bundleCapsM :: [(Text, Value)] -> CheckM (Maybe [(Text, Value, Value)])
bundleCapsM fs
  | null fs = pure Nothing
  | otherwise = do
      caps <- forM fs $ \(nm, tv) -> do
        t <- forceM tv
        pure $ case t of
          VGlobN (GName pm former) [(_, roots), (_, focus)]
            | pm == preludeModule
            , lookup nm capFormers == Just former ->
                Just (nm, roots, focus)
          _ -> Nothing
      pure (sequence caps)
  where
    capFormers = [("get", "Getter"), ("open", "Opener"), ("set", "Setter"), ("sink", "Sinker")]

-- | If the callee elaborates to a projector or accessor-bundle
-- descriptor, elaborate the §16.1.5/§16.1.6 descriptor application.
descriptorApp :: Ctx -> Span -> Term -> Value -> Expr -> Maybe PlaceDemand -> CheckM (Maybe (Term, Value))
descriptorApp ctx sp fTm fTy e mdemand = case fTy of
  VGlobN (GName pm "Projector") [_, _]
    | pm == preludeModule -> Just <$> run
  VRecordT caps -> do
    mb <- bundleCapsM caps
    case mb of
      Just _ -> Just <$> run
      Nothing -> pure Nothing
  _ -> pure Nothing
  where
    run = maybe id withDemand mdemand (applyDescriptor ctx sp fTm fTy (RootsSingle e))

-- | Apply a descriptor value to its roots (§16.1.5/§16.1.6): validate
-- the place pack, select the eliminator for the surrounding demand, and
-- yield the focus.
applyDescriptor :: Ctx -> Span -> Term -> Value -> RootsSupply -> CheckM (Term, Value)
applyDescriptor ctx sp dTm dTy0 supply = do
  dTy <- forceM dTy0
  case dTy of
    VGlobN (GName pm "Projector") [(_, rootsV), (_, focusV)]
      | pm == preludeModule -> do
          placeTms <- elabRootsSupply ctx sp rootsV supply
          focusV' <- case placeTms of
            [single] -> substThisInto ctx single focusV
            _ -> pure focusV
          pure (foldl (CApp Expl) dTm placeTms, focusV')
    VRecordT capFs -> do
      mcaps <- bundleCapsM capFs
      case mcaps of
        Just caps@((_, rootsV, focusV) : _) -> do
          demand <- gets csDemand
          let want = case demand of
                DemandRead -> "get"
                DemandConsume -> "sink"
                DemandOpen -> "open"
              capNames = [nm | (nm, _, _) <- caps]
          placeTms <- elabRootsSupply ctx sp rootsV supply
          unless (want `elem` capNames) $
            errAt sp "E_PROJECTION_CAPABILITY_REQUIRED" (Just "kappa-hs.projection.capability")
              ( "this use requires the '" <> capabilityWord demand
                  <> "' capability, but the accessor bundle provides only: "
                  <> T.intercalate ", " capNames <> " (§16.1.6)"
              )
          -- the value facet of the application always reads through
          -- 'get' when available (under '~' the §18.9 threading reads
          -- the focus and fills through 'set'/'open' at usage level)
          let readCap
                | demand == DemandConsume && "sink" `elem` capNames = "sink"
                | "get" `elem` capNames = "get"
                | otherwise = ""
          tm <-
            if T.null readCap
              then fst <$> anyHole ctx
              else pure (foldl (CApp Expl) (CProjM Ordinary dTm readCap) placeTms)
          focusV' <- case placeTms of
            [single] -> substThisInto ctx single focusV
            _ -> pure focusV
          pure (tm, focusV')
        _ -> do
          errAt sp "E_PROJECTION_DESCRIPTOR_VALUE_EXPECTED" (Just "kappa-hs.projection.descriptor")
            "expected a projector or accessor-bundle descriptor value here (§16.1.5)"
          anyHole ctx
    _ -> do
      errAt sp "E_PROJECTION_DESCRIPTOR_VALUE_EXPECTED" (Just "kappa-hs.projection.descriptor")
        "expected a projector or accessor-bundle descriptor value here (§16.1.5)"
      anyHole ctx
  where
    capabilityWord = \case
      DemandRead -> "get"
      DemandConsume -> "sink"
      DemandOpen -> "open"

-- | Elaborate the roots of a descriptor application in place-pack mode
-- (§16.1.5): each supplied field must be a stable place expression of
-- the corresponding field type. Returns the place terms in canonical
-- (lexicographic) root order.
elabRootsSupply :: Ctx -> Span -> Value -> RootsSupply -> CheckM [Term]
elabRootsSupply ctx _sp rootsV supply = do
  rootsF <- forceM rootsV
  let rfs = case rootsF of
        VRecordT fs -> fs
        _ -> []
  case supply of
    RootsSeparate pairs ->
      forM rfs $ \(nm, fty) ->
        case lookup nm pairs of
          Just e -> elabPlaceArg ctx e fty
          Nothing -> fst <$> anyHole ctx
    RootsSingle e -> case rfs of
      [(nm, fty)] -> case e of
        ERecordLit items isp -> do
          let fields = [(nameText fn, fe) | RecItem _ fn (Just fe) <- items]
          case fields of
            [(fn, fe)]
              | fn == nm, length items == 1 -> (: []) <$> elabPlaceArg ctx fe fty
            _ -> do
              errAt isp "E_PROJECTION_ROOTS_PACK_MISMATCH" (Just "kappa-hs.projection.roots")
                ("the roots record literal must supply exactly the field '" <> nm <> "' (§16.1.5)")
              (: []) . fst <$> anyHole ctx
        _ -> (: []) <$> elabPlaceArg ctx e fty
      _ -> case e of
        ERecordLit items isp -> do
          let fields = [(nameText fn, fe) | RecItem _ fn (Just fe) <- items]
          if sort (map fst fields) /= map fst rfs || length items /= length fields
            then do
              errAt isp "E_PROJECTION_ROOTS_PACK_MISMATCH" (Just "kappa-hs.projection.roots")
                ( "the roots record literal must supply exactly the fields: "
                    <> T.intercalate ", " (map fst rfs) <> " (§16.1.5)"
                )
              mapM (const (fst <$> anyHole ctx)) rfs
            else forM rfs $ \(nm, fty) ->
              case lookup nm fields of
                Just fe -> elabPlaceArg ctx fe fty
                Nothing -> fst <$> anyHole ctx
        _ -> do
          errAt (exprSpan e) "E_PROJECTION_DESCRIPTOR_ROOTS_LITERAL_REQUIRED" (Just "kappa-hs.projection.roots")
            "the roots argument of a multi-root projector descriptor application must be a closed record literal (§16.1.5)"
          _ <- infer ctx e
          mapM (const (fst <$> anyHole ctx)) rfs

-- | One root of a place pack: must be a stable place expression
-- (§12.4.1) of the root field's type.
elabPlaceArg :: Ctx -> Expr -> Value -> CheckM Term
elabPlaceArg ctx e fty
  | Just root <- mutableVarPlaceRoot ctx e = do
      infoFields <- mutableBindingLookupFields ctx root "user-written"
      errMutableBinding (exprSpan e) "E_UNSUPPORTED" (nameText root) "var-place"
        (infoFields ++ [("sourceOperation", "~"), ("repair", "use '~' only at an inout do-item rewrite site")])
        "mutable var-place arguments such as '~x' or '~x.f' require read/modify/write elaboration over the hidden cell; this implementation rejects raw projection-root use rather than elaborating it as a current-value read (§18.6.1, §18.9)"
      fst <$> anyHole ctx
  | stablePlaceExpr e = withDemand DemandRead (check ctx e fty)
  | otherwise = do
      errAt (exprSpan e) "E_PROJECTION_ROOT_INVALID" (Just "kappa-hs.projection.roots")
        "a projection place argument must be a stable place expression (§12.4.1, §16.1.5)"
      _ <- withDemand DemandRead (infer ctx e)
      fst <$> anyHole ctx

-- | Syntactic stable-place check (§12.4.1 subset: variables and
-- record\/constructor field paths).
stablePlaceExpr :: Expr -> Bool
stablePlaceExpr = \case
  EVar _ -> True
  EDot e (DotName _) -> stablePlaceExpr e
  EAscription e _ _ -> stablePlaceExpr e
  _ -> False

mutableVarPlaceRoot :: Ctx -> Expr -> Maybe Name
mutableVarPlaceRoot ctx = \case
  EVar n ->
    if maybe False (isJust . ceVarInfo . snd) (lookupCtx (nameText n) ctx)
      then Just n
      else Nothing
  EDot e (DotName _) -> mutableVarPlaceRoot ctx e
  EAscription e _ _ -> mutableVarPlaceRoot ctx e
  _ -> Nothing

elabSpine :: Ctx -> Span -> Term -> Value -> [Arg] -> CheckM (Term, Value)
elabSpine ctx sp fTm fTy args =
  withApplicationEvidenceScope $ do
    (application, resultType) <-
      elabSpineWith ctx sp fTm fTy args
    canonical <-
      canonicalizeProviderEqualityProof
        ctx
        resultType
        resultType
        application
    pure (canonical, resultType)

-- | Evidence synthesized while elaborating one application belongs to that
-- application's recovered Core. If the application is structurally invalid,
-- the recovery hole contains no use of newly synthesized dictionaries, so
-- retain only obligations that existed before both callee elaboration and
-- spine checking. Callers that infer the head themselves wrap the complete
-- operation in this scope; 'elabSpine' supplies the same invariant when given
-- an already checked head.
withApplicationEvidenceScope :: CheckM a -> CheckM a
withApplicationEvidenceScope action = do
  pending0 <- gets csPending
  diagCount0 <- gets (length . csDiags)
  result <- action
  diags <- gets csDiags
  let freshCount = max 0 (length diags - diagCount0)
      structurallyInvalid = any applicationShapeFailure (take freshCount diags)
  when structurallyInvalid $ do
    let preexisting = Set.fromList [mid | (mid, _, _, _, _) <- pending0]
    modify' $ \st ->
      let retainedPending =
            filter
              (\(mid, _, _, _, _) -> Set.member mid preexisting)
              (csPending st)
          retainedIds =
            Set.fromList [mid | (mid, _, _, _, _) <- retainedPending]
       in st
            { csPending = retainedPending
            , csPendingLevelEvidence =
                Map.restrictKeys (csPendingLevelEvidence st) retainedIds
            }
  pure result

-- | Complete inference may connect an overloaded literal to a later operand
-- through associated members. For example, after checking both arguments of
-- @contains (0 .. 5) value@ with @value : Nat@, the pending component contains
-- @FromInteger ?a@, @Rangeable ?a@, and
-- @Contains (Rangeable.Range ?a) Nat@. Defaulting the literal before solving
-- that complete component would incorrectly commit @?a := Int@.
--
-- Close only components rooted in numeric evidence retained by the current
-- inference boundary, and only when another pending obligation is connected.
-- An isolated @FromInteger ?a@ remains subject to the ordinary
-- declaration-level default, and unrelated flexible trait goals cannot infer
-- their carriers from the open global instance set.
-- 'settleUniquePendingTraitComponent' provides the bounded transactional
-- search and commits only one principal assignment for the component's
-- non-evidence metas.
settlePendingNumericComponents :: [PendingEvidenceEntry] -> CheckM ()
settlePendingNumericComponents pendingEntries = do
  numericRoots <-
    Set.fromList . map pendingEntryMeta . catMaybes
      <$> forM pendingEntries
        (\entry -> do
           numeric <- pendingEntryIsNumericLiteral entry
           pure (if numeric then Just entry else Nothing)
        )
  improvementAnchorEntries <-
    Set.fromList . map pendingEntryMeta . catMaybes
      <$> forM pendingEntries
        (\entry -> do
           associated <- pendingEntryUsesAssociatedEvidenceProjection entry
           rigidArgument <- pendingEntryHasRigidSemanticArgument entry
           pure (if associated || rigidArgument then Just entry else Nothing)
        )
  components <- pendingEvidenceComponentsFromRoots numericRoots
  pending <- gets csPending
  forM_ components $ \component -> do
    active <-
      filterM
        pendingEntryIsUnsolved
        [ entry
        | entry <- pending
        , pendingEntryMeta entry `Set.member` component
        ]
    -- 'pendingTraitComponentSolutions' has an explicit 24-step search
    -- budget. A larger active component cannot reach a complete solution
    -- within that budget, so fail closed without paying for a search whose
    -- result is predetermined to be inconclusive.
    when
      ( length active > 1
          && length active <= 24
          && not
               (Set.disjoint component improvementAnchorEntries)
      )
      (settleUniquePendingTraitComponent component)

-- | Compute connected pending-evidence components for a set of roots in one
-- indexed graph pass. Re-running 'pendingEvidenceComponentFromSeed' once per
-- numeric literal made declaration finalization quadratic on large generated
-- declarations. The graph here is the same semantic graph: an evidence node
-- is connected through unsolved metas in its checked goal and transitively
-- through those metas' creation-site classifiers.
pendingEvidenceComponentsFromRoots :: Set MetaId -> CheckM [Set MetaId]
pendingEvidenceComponentsFromRoots roots = do
  graph <- buildPendingEvidenceGraph
  let componentFrom root =
        pendingEvidenceComponentIn graph (Set.singleton root)
      collect remaining
        | Set.null remaining = []
        | otherwise =
            let root = Set.findMin remaining
                component = componentFrom root
             in component : collect (Set.difference remaining component)
  pure (collect (Set.intersection roots (pegPendingIds graph)))

pendingEntryIsNumericLiteral :: PendingEvidenceEntry -> CheckM Bool
pendingEntryIsNumericLiteral entry =
  refreshPendingEntry entry >>= \case
    VGlobN trait _
      | trait == gPrel traitFromInteger
          || trait == gPrel traitFromFloat ->
          pure True
    VGlobI trait _ _
      | trait == gPrel traitFromInteger
          || trait == gPrel traitFromFloat ->
          pure True
    _ -> pure False

-- | A rigid semantic trait argument is an ordinary instance-search input, not
-- a guess from the ambient instance set.  It may therefore anchor bounded
-- complete-component improvement.  For example,
-- @Contains (NumericRange ?a) Nat@ has a rigid second argument that rules out
-- the Integer instance and yields one principal assignment for @?a@.  Goals
-- such as @FromInteger ?a@ or @Sized ?a@ have no such anchor and remain
-- subject to the normal defaulting/ambiguity boundary.
pendingEntryHasRigidSemanticArgument
  :: PendingEvidenceEntry
  -> CheckM Bool
pendingEntryHasRigidSemanticArgument entry =
  refreshPendingEntry entry >>= \case
    VGlobI trait _ arguments -> do
      state <- get
      pure $ case traitSemanticSpineIn state trait arguments of
        Nothing -> False
        Just semanticArguments ->
          any
            ( \(_, argument) ->
                null
                  ( unsolvedMetasOf
                      state
                      ( quote
                          (ecOf state)
                          (ctxLen (pendingEntryCtx entry))
                          argument
                      )
                  )
            )
            semanticArguments
    _ -> pure False

-- | Does a pending goal depend on an authenticated associated static member
-- of another evidence placeholder? This is the typed dependency that permits
-- complete-component improvement before numeric defaulting. A mere pair of
-- ordinary goals such as @FromInteger ?a@ and @Sized ?a@ has no such edge and
-- must not let the currently imported instance set choose @?a@.
pendingEntryUsesAssociatedEvidenceProjection
  :: PendingEvidenceEntry
  -> CheckM Bool
pendingEntryUsesAssociatedEvidenceProjection (_, goal, _, pendingCtx, _) = do
  goalTerm <-
    quoteIn pendingCtx goal >>= zonkTermM (ctxLen pendingCtx)
  state <- get
  pure
    ( getAny
        (foldTerm (projectionNode state) (const mempty) goalTerm)
    )
  where
    projectionNode state = \case
      CProjM _ receiver field ->
        Any (authenticatedAssociatedMember state receiver field)
      CProjAtM _ receiver field _ ->
        Any (authenticatedAssociatedMember state receiver field)
      _ -> mempty

    authenticatedAssociatedMember state receiver field =
      isJust $ do
        evidenceMeta <- case stripIdentityWrappers receiver of
          CMeta meta -> Just meta
          _ -> Nothing
        classifier <- Map.lookup evidenceMeta (csMetaClassifiers state)
        trait <- termHeadGlob (stripIdentityWrappers (micType classifier))
        traitInfo <- Map.lookup trait (csTraits state)
        guard (field `Set.member` tiAssociatedStaticMembers traitInfo)

applicationShapeFailure :: Diagnostic -> Bool
applicationShapeFailure diagnostic =
  dCode diagnostic
    `elem`
      [ "E_APPLICATION_NONCALLABLE"
      , "E_APPLICATION_ARGUMENT_MISMATCH"
      , "E_CONSTRUCTOR_ARITY_MISMATCH"
      , "E_NAMED_ARG_MISSING"
      , "E_NAMED_ARG_DUPLICATE"
      , "E_NAMED_ARG_UNKNOWN"
      ]

-- | Type-position application uses the same §16.1.7.1 spine discipline as
-- term application. In particular, an ordinary surface operand never fills
-- an implicit binder positionally: omitted implicits are synthesized, while
-- an explicitly supplied implicit is written @\@payload@.
elabTypeSpine :: Ctx -> Span -> Term -> Value -> [Arg] -> CheckM (Term, Value)
elabTypeSpine = elabSpineWith

elabSpineWith :: Ctx -> Span -> Term -> Value -> [Arg] -> CheckM (Term, Value)
elabSpineWith ctx sp fTm fTy0 [] = do
  -- §16.1.7.1 processes implicit binders even after the last surface
  -- argument. Only a residual explicit binder denotes partial application.
  -- This matters for calls such as @summon Goal@: the explicit goal is
  -- followed by trait and evidence implicits which must be resolved at that
  -- application site rather than escaping in the inferred result type.
  (callableType, _) <- peelCapturesWithRegionsM fTy0
  callableType' <- forceM callableType
  case callableType' of
    VPiBoundM mode Impl q _ _ assumption dom clo -> do
      kindLike <- isKindLike (ctxLen ctx) dom
      implicit <- synthesizeApplicationImplicit ctx sp q dom
      implicitValue <- checkedArgumentValue ctx sp dom implicit
      resultType <- clApp clo implicitValue
      nextCtx <- extendLevelAssumption sp ctx assumption
      result <- elabSpineWith nextCtx sp (CApp Impl fTm implicit) resultType []
      when kindLike (validateInferredKindArgument ctx sp implicit dom)
      pure result
    -- A capture wrapper is transparent only while eliminating a callable.
    -- Once the surface argument spine is complete, it is the result value's
    -- hidden environment and must remain in the inferred type.
    _ -> do
      canonical <- canonicalizeSelectedNatOperation ctx fTm
      (canonical,) <$> forceM fTy0
elabSpineWith ctx sp fTm fTy0 (arg : rest) = do
  -- §12.3.1: a capture-annotated callable applies at its underlying type
  (fTy, captureRegions) <- peelCapturesWithRegionsM fTy0
  case arg of
    -- §18.9.3/§18.9.6: '~' is valid only inside a do block; recover
    -- with a hole so the broken spine does not cascade a type mismatch
    ArgInout _ msp | not (ctxInDo ctx) -> do
      errAt msp "E_QTT_INOUT_MARKER_UNEXPECTED" (Just "kappa-hs.qtt.inout-marker")
        "a call-site '~' marker is valid only inside a do block (§18.9.3, §18.9.6)"
      anyHole ctx
    _ -> do
      -- §16.1.5/§16.1.6: a descriptor-typed callee consumes its roots
      -- argument in place-pack mode. A raw '~' marker is deliberately not
      -- accepted here: §18.9 gives '~' meaning only to the do-item inout
      -- rewrite after resolving InoutParam metadata. That rewrite strips the
      -- marker before ordinary descriptor application is checked.
      mdesc <- case arg of
        ArgExplicit e -> descriptorApp ctx sp fTm fTy e Nothing
        _ -> pure Nothing
      case mdesc of
        Just (tm', ty') -> elabSpineWith ctx sp tm' ty' rest
        Nothing -> elabSpineArg ctx sp captureRegions fTm fTy arg rest

-- | Classify omitted source-level forall parameters uniformly in inferred and
-- expected applications. Erased data/kind indices are constrained by later
-- arguments; trait, equality, row, and level goals are evidence and continue
-- through implicit resolution.
applicationImplicitIsPlanningParameter :: Ctx -> Q -> Value -> CheckM Bool
applicationImplicitIsPlanningParameter ctx q domain = do
  kindLike <- isKindLike (ctxLen ctx) domain
  traitLike <- isTraitGoal domain
  equalityLike <- isEqGoal domain
  rowLike <- isRowGoal domain
  levelLike <- isJust <$> authenticatedLevelGoalRelation ctx domain
  pure
    ( kindLike
        || ( q == Q0
               && not
                    ( traitLike
                        || equalityLike
                        || rowLike
                        || levelLike
                    )
           )
    )

synthesizeApplicationImplicit :: Ctx -> Span -> Q -> Value -> CheckM Term
synthesizeApplicationImplicit ctx site q domain = do
  planning <- applicationImplicitIsPlanningParameter ctx q domain
  if planning
    then freshMetaFor ctx domain
    else resolveImplicitQ ctx site q domain

-- | Reify the canonical semantic identity of the standard Nat operation at
-- the point where its selected evidence is still explicit in Core. This is
-- not arithmetic conversion: it only replaces a fully applied method call
-- whose exact Add-Nat dictionary is the authenticated prelude instance with
-- the source definition that instance delegates to. User dictionaries,
-- partial calls, and every other carrier are preserved verbatim.
canonicalizeSelectedNatOperation :: Ctx -> Term -> CheckM Term
canonicalizeSelectedNatOperation ctx application = do
  finalized <- zonkTermM (ctxLen ctx) application
  instances <- gets csInstances
  pure (fromMaybe application (canonicalStandardBinaryOperation instances finalized))

-- | Revisit selected operations after evidence solving. An application can
-- be elaborated while its dictionary is still a metavariable and only later
-- become a coherent standard arithmetic provider. Module finalization runs
-- this monotone pass over every surviving artifact so early elaboration order
-- cannot decide whether one semantic operation is canonicalized. Every
-- rewrite authenticates the exact trait, carrier, and selected dictionary.
canonicalizeStandardArithmeticOperations :: [InstanceEntry] -> Term -> Term
canonicalizeStandardArithmeticOperations instances = fixedPoint
  where
    rewrite =
      mapTermWithDepth
        (\_ term -> case term of
           -- A certificate deliberately separates its canonical conclusion
           -- from the exact provider proposition that justified it. Module
           -- finalization normalizes the conclusion and replay material
           -- together so the proof term keeps the same type as its
           -- canonicalized surroundings. The checked provider proposition
           -- and proof source remain exact; the independent verifier checks
           -- their authenticated relation to the replay goal.
           CArithmeticProof certificate ->
             Just
               ( CArithmeticProof
                   certificate
                     { acGoal =
                         fixedPoint (acGoal certificate)
                     , acReplayGoal =
                         fixedPoint (acReplayGoal certificate)
                     , acAssumptions =
                         map canonicalizeAssumption
                           (acAssumptions certificate)
                     }
               )
           _ -> canonicalStandardArithmeticOperation instances term)
        0
    fixedPoint term =
      let term' = rewrite term
       in if term' == term then term else fixedPoint term'

    canonicalizeAssumption assumption =
      assumption
        { aaReplayProposition =
            fixedPoint (aaReplayProposition assumption)
        }

canonicalStandardArithmeticOperation :: [InstanceEntry] -> Term -> Maybe Term
canonicalStandardArithmeticOperation instances term =
  canonicalTrustedNaturalLiteralBridge term
    <|> canonicalTrustedIntegerPrimitive term
    <|> canonicalStandardBooleanOperation term
    <|> canonicalStandardFromIntegerOperation instances term
    <|> canonicalStandardBinaryOperation instances term
    <|> canonicalStandardComparisonOperation instances term

-- | Compute the exact closed Nat-to-Integer bridge used by the standard Nat
-- arithmetic dictionaries. Nat literals and Integer literals share the exact
-- arbitrary-precision Core literal payload, so this removes only a checked,
-- resolved bridge application; open operands and user functions stay opaque.
canonicalTrustedNaturalLiteralBridge :: Term -> Maybe Term
canonicalTrustedNaturalLiteralBridge application =
  case spineOfTerm (stripIdentityWrappers application) of
    (headTerm, [(Expl, literal@(CLit (LitInt value)))])
      | value >= 0
      , termHeadGlob (stripIdentityWrappers headTerm)
          `elem`
            [ Just prelNatToInt
            , Just (GName primModule (gKey prelNatToInt))
            ] ->
          Just literal
    _ -> Nothing

-- | Expose the exact short-circuit Core semantics of the resolved prelude
-- Boolean combinators. The right operand of conjunction/disjunction remains
-- forced only in the selected branch, so this is a semantic identity
-- normalization rather than an eager Boolean rewrite.
canonicalStandardBooleanOperation :: Term -> Maybe Term
canonicalStandardBooleanOperation application =
  case spineOfTerm (stripIdentityWrappers application) of
    (headTerm, arguments)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelOr
      , Just (left, right) <-
          last2 [argument | (Expl, argument) <- arguments] ->
          Just (CIf left trueTerm (CForceE right (Just (CGlob prelBool))))
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelAnd
      , Just (left, right) <-
          last2 [argument | (Expl, argument) <- arguments] ->
          Just (CIf left (CForceE right (Just (CGlob prelBool))) falseTerm)
      | termHeadGlob (stripIdentityWrappers headTerm) == Just prelNot
      , [argument] <- [candidate | (Expl, candidate) <- arguments] ->
          Just (CIf argument falseTerm trueTerm)
    _ -> Nothing
  where
    trueTerm = CCtorI prelTrue [] Nothing []
    falseTerm = CCtorI prelFalse [] Nothing []

-- | Retry proof-type compatibility after replacing only fully authenticated
-- standard arithmetic operations with their canonical primitive semantics.
-- This is proof-normalization authority, not a value conversion rule:
-- selected dictionary identity and checked instance heads authorize every
-- rewrite, while user operations and user equality families remain opaque.
-- Callers that move a value between the original types must still construct
-- explicit equality transport. As with ordinary compatibility, the attempt is
-- transactional.
tryCanonicalStandardArithmeticCompatibility
  :: Ctx
  -> Span
  -> Value
  -> Value
  -> CheckM Bool
tryCanonicalStandardArithmeticCompatibility ctx source actual expected =
  tryCompatibilityAfterCanonicalization
    ctx
    source
    (canonicalizeEqualityGoalUnderCheckedBranchFacts ctx)
    (canonicalizeTermsUnderCheckedBranchFacts ctx)
    actual
    expected

-- | Provider normalization may identify two checked propositions, but it is
-- not a conversion rule for values indexed by those propositions. Restrict
-- this compatibility path to proofs of the resolved built-in equality family;
-- 'canonicalizeProviderEqualityProof' then replaces the fallback with a
-- replayable checked certificate whenever the normalized endpoints differ.
tryCanonicalStandardArithmeticProofCompatibility
  :: Ctx
  -> Span
  -> Value
  -> Value
  -> CheckM Bool
tryCanonicalStandardArithmeticProofCompatibility ctx source actual expected = do
  actualIsEquality <- isEqGoal actual
  expectedIsEquality <- isEqGoal expected
  if actualIsEquality && expectedIsEquality
    then tryCanonicalStandardArithmeticCompatibility ctx source actual expected
    else pure False

-- | Contextual conversion available to ordinary value checking. Unlike
-- provider/arithmetic normalization, these rewrites are justified solely by
-- the exact checked branch facts in lexical scope and are independently
-- replayed by KCore verification of that branch. No selected operation is
-- replaced by a canonical representative here.
tryCheckedBranchCompatibility
  :: Ctx
  -> Span
  -> Value
  -> Value
  -> CheckM Bool
tryCheckedBranchCompatibility ctx source actual expected =
  tryCompatibilityAfterCanonicalization
    ctx
    source
    (canonicalizeEqualityGoalUnderCheckedBranchFactsOnly ctx)
    (canonicalizeTermsUnderCheckedBranchFactsOnly ctx)
    actual
    expected

tryCompatibilityAfterCanonicalization
  :: Ctx
  -> Span
  -> (Term -> CheckM Term)
  -> ([Term] -> CheckM [Term])
  -> Value
  -> Value
  -> CheckM Bool
tryCompatibilityAfterCanonicalization
  ctx
  source
  canonicalizeEndpoint
  canonicalizeTerms
  actual
  expected = do
  before <- get
  let depth = ctxLen ctx
  actualTerm <- quoteIn ctx actual >>= zonkTermM depth
  expectedTerm <- quoteIn ctx expected >>= zonkTermM depth
  actualEndpointCanonical <-
    canonicalizeEndpoint actualTerm
  expectedEndpointCanonical <-
    canonicalizeEndpoint expectedTerm
  normalized <-
    canonicalizeTerms [actualEndpointCanonical, expectedEndpointCanonical]
  case normalized of
    [actualCanonical, expectedCanonical] ->
      if actualCanonical == actualTerm && expectedCanonical == expectedTerm
        then pure False
        else do
          actualValue <- evalIn ctx actualCanonical
          expectedValue <- evalIn ctx expectedCanonical
          compatible <-
            withUniverseDiagnosticSpan source
              (unify ctx actualValue expectedValue)
          unless compatible (put before)
          pure compatible
    _ -> pure False

-- | Canonicalize only the two explicit endpoints of a checked equality goal.
-- The bounded transparent reducer deliberately does not descend through
-- arbitrary application operands: doing so would force unrelated user calls.
-- Equality endpoints are different because their complete standard-equality
-- spine has already authenticated both positions as proof-relevant terms.
-- Rebuilding preserves every implicit carrier/evidence argument verbatim.
canonicalizeEqualityGoalUnderCheckedBranchFacts
  :: Ctx
  -> Term
  -> CheckM Term
canonicalizeEqualityGoalUnderCheckedBranchFacts ctx goal =
  canonicalizeEqualityGoalWith
    (canonicalizeTermsUnderCheckedBranchFacts ctx)
    goal

canonicalizeEqualityGoalUnderCheckedBranchFactsOnly
  :: Ctx
  -> Term
  -> CheckM Term
canonicalizeEqualityGoalUnderCheckedBranchFactsOnly ctx goal =
  canonicalizeEqualityGoalWith
    (canonicalizeTermsUnderCheckedBranchFactsOnly ctx)
    goal

canonicalizeEqualityGoalWith
  :: ([Term] -> CheckM [Term])
  -> Term
  -> CheckM Term
canonicalizeEqualityGoalWith canonicalize goal =
  case equalityExplicitEndpoints goal of
    Nothing -> pure goal
    Just (left, right) ->
      canonicalize [left, right] >>= \case
        [left', right'] ->
          pure (replaceLastTwoExplicitArguments left' right' goal)
        _ -> pure goal

replaceLastTwoExplicitArguments :: Term -> Term -> Term -> Term
replaceLastTwoExplicitArguments left right goal =
  let (headTerm, arguments) = spineOfTerm goal
      explicitCount = length [() | (Expl, _) <- arguments]
      replace index = \case
        (Expl, _)
          | index == explicitCount - 2 -> (Expl, left)
          | index == explicitCount - 1 -> (Expl, right)
        argument -> argument
      (_, arguments') =
        List.mapAccumL
          (\index argument ->
             (index + if fst argument == Expl then 1 else 0, replace index argument))
          0
          arguments
   in List.foldl'
        (\function (icit, argument) -> CApp icit function argument)
        headTerm
        arguments'

-- | Canonicalize checked terms under the current scoped branch facts.
-- Authentication of arithmetic and Boolean heads happens before contextual
-- rewriting, so both type compatibility and proof synthesis consume exactly
-- the same local semantic authority.
canonicalizeTermsUnderCheckedBranchFacts
  :: Ctx
  -> [Term]
  -> CheckM [Term]
canonicalizeTermsUnderCheckedBranchFacts ctx terms = do
  instances <- gets csInstances
  canonicalizeTermsUnderBranchFactsWith
    24
    normalizeBoolFacts
    (canonicalizeStandardArithmeticOperations instances)
    ctx
    terms

canonicalizeTermsUnderCheckedBranchFactsOnly
  :: Ctx
  -> [Term]
  -> CheckM [Term]
canonicalizeTermsUnderCheckedBranchFactsOnly =
  canonicalizeTermsUnderBranchFactsWith 24 normalizeBoolFacts id

-- | Substitute only branch propositions that are already present in the
-- checked condition (including polarity-safe Boolean decomposition). This is
-- the §16.3.3 step-3 boundary that may justify ordinary @refl@: it neither
-- unfolds a different predicate to expose arithmetic subgoals nor derives a
-- Presburger consequence. Those cases must proceed to the proof-producing
-- §15.8 solver and carry an independently checked certificate.
canonicalizeTermsUnderExactCheckedBranchFacts
  :: Ctx
  -> [Term]
  -> CheckM [Term]
canonicalizeTermsUnderExactCheckedBranchFacts ctx terms = do
  instances <- gets csInstances
  canonicalizeTermsUnderBranchFactsWith
    0
    exactBoolFacts
    (canonicalizeStandardArithmeticOperations instances)
    ctx
    terms

canonicalizeTermsUnderBranchFactsWith
  :: Int
  -> (Int -> [ScopedBoolFact] -> CheckM [(Term, Bool)])
  -> (Term -> Term)
  -> Ctx
  -> [Term]
  -> CheckM [Term]
canonicalizeTermsUnderBranchFactsWith
  reductionFuel
  selectFacts
  canonicalizeStandard
  ctx
  terms = do
  let depth = ctxLen ctx
  rigidFacts <- checkedRigidFactTerms ctx
  branchFacts0 <- selectFacts depth =<< gets csBoolFacts
  let branchFacts =
        [ (canonicalizeStandard proposition, truth)
        | (proposition, truth) <- branchFacts0
        ]
      normalizeOne fuel current
        | fuel <= 0 =
            normalizeCheckedBranchFacts
              depth
              canonicalizeStandard
              branchFacts
              (canonicalizeStandard (substituteCheckedRigidFacts depth rigidFacts current))
        | otherwise = do
            let underRigidFacts =
                  substituteCheckedRigidFacts depth rigidFacts current
            underFacts <-
              normalizeCheckedBranchFacts
                depth
                canonicalizeStandard
                branchFacts
                (canonicalizeStandard underRigidFacts)
            reduced <- transparentProofReduce depth 48 underFacts
            let next =
                  canonicalizeStandard
                    (simplifyDecisionTermAt depth reduced)
            if next == current
              then pure next
              else normalizeOne (fuel - 1) next
  mapM (normalizeOne reductionFuel) terms

-- | Quote the positive constructor/index refinements established by the
-- current checked patterns.  The map key is a rigid level, not a source name;
-- negative constructor exclusions are intentionally not substitutions.
checkedRigidFactTerms :: Ctx -> CheckM (Map Int Term)
checkedRigidFactTerms ctx = do
  facts <- gets csFacts
  fmap Map.fromList . fmap catMaybes . forM (Map.toList facts) $ \case
    (level, FactIs replacement)
      | level >= 0
      , level < ctxLen ctx -> do
          term <- quoteIn ctx replacement >>= zonkTermM (ctxLen ctx)
          pure (Just (level, term))
    _ -> pure Nothing

-- | Replay positive rigid facts in Core while preserving de Bruijn scope.
-- At a node depth @d@, @CVar i@ denotes rigid level @d - 1 - i@. A quoted
-- replacement lives at the enclosing depth and is weakened only across the
-- binders traversed by this rewrite. This is the syntactic replay of the same
-- certified facts already consumed by conversion-time evaluation.
substituteCheckedRigidFacts :: Int -> Map Int Term -> Term -> Term
substituteCheckedRigidFacts enclosingDepth facts =
  mapTermWithDepth rewrite enclosingDepth
  where
    rewrite nodeDepth = \case
      CVar index
        | let level = nodeDepth - 1 - index
        , Just replacement <- Map.lookup level facts ->
            Just (shiftTerm (nodeDepth - enclosingDepth) 0 replacement)
      _ -> Nothing

-- | Normalize a term under the exact Boolean facts in the current branch.
-- Facts are already scoped, zonked, and decomposed by 'normalizeBoolFacts'.
-- Structural keys are the same collision-free Core keys used by the Boolean
-- decision procedure; no source spelling or operation name participates.
--
-- This is contextual conversion only. It does not add a global reduction
-- rule, and callers must discard every meta assignment when the enclosing
-- compatibility attempt fails.
normalizeCheckedBranchFacts
  :: Int
  -> (Term -> Term)
  -> [(Term, Bool)]
  -> Term
  -> CheckM Term
normalizeCheckedBranchFacts depth canonicalizeStandard facts term = do
  evalContext <- ec_
  pure (fixedPoint evalContext term)
  where
    fixedPoint evalContext current =
      let nodes =
            foldTermWithDepth
              (\nodeDepth node -> [(nodeDepth, node)])
              depth
              current
          agreedTruth nodeDepth node =
            case nub
              [ truth
              | (proposition, truth) <- facts
              , let delta = nodeDepth - depth
              , delta >= 0
              , let propositionAtNode =
                      shiftTerm delta 0 proposition
                    sameCheckedObservation =
                      branchDecisionObservationTerm propositionAtNode
                        == branchDecisionObservationTerm node
                    environment =
                      [ VRigid level []
                      | level <- reverse [0 .. nodeDepth - 1]
                      ]
                    propositionValue =
                      eval
                        evalContext
                        environment
                        ( branchDecisionObservationTerm
                            propositionAtNode
                        )
                    nodeValue =
                      eval
                        evalContext
                        environment
                        (branchDecisionObservationTerm node)
              , sameCheckedObservation
                  || convertible evalContext nodeDepth propositionValue nodeValue
              ] of
              [truth] -> Just truth
              _ -> Nothing
          truthByNode =
            Map.fromList
              [ ((nodeDepth, branchFactKey node), truth)
              | (nodeDepth, node) <- nodes
              , Just truth <- [agreedTruth nodeDepth node]
              ]
          rewrite nodeDepth node =
            case Map.lookup
              (nodeDepth, branchFactKey node)
              truthByNode of
              Just True -> Just (CCtorI prelTrue [] Nothing [])
              Just False -> Just (CCtorI prelFalse [] Nothing [])
              Nothing -> Nothing
          next =
            canonicalizeStandard
              ( simplifyDecisionTermAt depth
                  (mapTermWithDepth rewrite depth current)
              )
       in if next == current
            then current
            else fixedPoint evalContext next

-- | Evaluation quotes a wired-in primitive value through the internal
-- @__prim@ module. Final Core and certificates use the corresponding checked
-- @std.prelude@ identity instead. The shared primitive classifiers authorize
-- exactly this finite integer-operation family; no user spelling or arbitrary
-- internal global is rewritten.
canonicalTrustedIntegerPrimitive :: Term -> Maybe Term
canonicalTrustedIntegerPrimitive = \case
  CGlobal global universes
    | Just canonical <- canonicalTrustedIntPrimitive global
    , global /= canonical ->
        Just (CGlobal canonical universes)
  _ -> Nothing

-- | Lower one fully selected standard @FromInteger Nat@ application to the
-- canonical Nat literal consumed by the arithmetic reifier. The selected
-- dictionary, checked instance head, and nonnegative literal jointly provide
-- the authority; user dictionaries and negative literals remain untouched.
-- This rewrite runs before enclosing order operations in the fixed-point pass,
-- so a literal does not become hidden below @natToInt@ first.
canonicalStandardFromIntegerOperation
  :: [InstanceEntry]
  -> Term
  -> Maybe Term
canonicalStandardFromIntegerOperation instances application = do
  let trait = gPrel traitFromInteger
      (headTerm, arguments) =
        spineOfTerm (stripIdentityWrappers application)
      explicitArguments =
        [argument | (Expl, argument) <- arguments]
      implicitArguments =
        [argument | (Impl, argument) <- arguments]
      exactAccessor global =
        global == gPrel "fromInteger"
          || global == memberGlobal trait "fromInteger"
      selectedDictionary =
        case stripIdentityWrappers headTerm of
          CProjM _ dictionary "fromInteger" -> Just dictionary
          CProjAtM _ dictionary "fromInteger" _ -> Just dictionary
          candidate
            | Just global <- termHeadGlob candidate
            , exactAccessor global
            , carrier : dictionary : _ <- implicitArguments
            , isNatType carrier ->
                Just dictionary
          _ -> Nothing
  [CLit (LitInt literal)] <- pure explicitArguments
  guard (literal >= 0)
  dictionary <- selectedDictionary
  guard
    ( standardPreludeDictionaryIn
        instances
        trait
        (\case
          [headType] -> isNatType headType
          _ -> False)
        dictionary
    )
  pure (CLit (LitInt literal))

canonicalStandardBinaryOperation :: [InstanceEntry] -> Term -> Maybe Term
canonicalStandardBinaryOperation instances application =
  case spineOfTerm (stripIdentityWrappers application) of
    (headTerm, arguments)
      | Just (operation, trait, dictionary, selectedDomain, proofArguments) <-
          selectedOperation headTerm arguments
      , Just (left, right) <-
          last2 [argument | (Expl, argument) <- arguments]
      , Just domain <-
          selectedDomain <|> uniqueDictionaryDomain trait dictionary
      , operationIsTotal operation
          || any checkedProofArgument proofArguments
      , standardPreludeDictionaryIn
          instances
          trait
          (\case
             [headType] -> arithmeticDomainForCarrier headType == Just domain
             _ -> False)
          dictionary ->
          lower domain operation left right
    _ -> Nothing
  where
    selectedOperation headTerm arguments =
      globalOperation headTerm arguments
        <|> projectedOperation headTerm arguments

    globalOperation headTerm arguments = do
      operation <- termHeadGlob (stripIdentityWrappers headTerm)
      (operationKind, trait) <- operationDescriptor operation
      carrier : dictionary : proofArguments <-
        pure [argument | (Impl, argument) <- arguments]
      domain <- arithmeticDomainForCarrier carrier
      pure
        ( operationKind
        , trait
        , dictionary
        , Just domain
        , proofArguments
        )

    projectedOperation headTerm arguments = case headTerm of
      CProjM _ dictionary member -> do
        (operationKind, trait) <- projectedDescriptor member
        pure
          ( operationKind
          , trait
          , dictionary
          , Nothing
          , [argument | (Impl, argument) <- arguments]
          )
      CProjAtM _ dictionary member _ -> do
        (operationKind, trait) <- projectedDescriptor member
        pure
          ( operationKind
          , trait
          , dictionary
          , Nothing
          , [argument | (Impl, argument) <- arguments]
          )
      _ -> Nothing

    operationIsTotal = \case
      ArithmeticAdd -> True
      ArithmeticMultiply -> True
      ArithmeticSubtract -> False
      ArithmeticDivide -> False
      ArithmeticModulo -> False

    -- A checked operation may be lowered to its primitive implementation only
    -- after its erased domain argument has been discharged.  Before zonking,
    -- an unresolved proof is represented by a Core metavariable; preserving
    -- that application keeps the exact proof dependency available to delayed
    -- conversion.  The application checker has already checked every
    -- non-meta argument against the selected method telescope, so no source
    -- spelling or untyped proof assertion is trusted here.
    checkedProofArgument proof =
      not
        ( getAny
            ( foldTerm
                (\case
                   CMeta _ -> Any True
                   _ -> Any False)
                (const mempty)
                proof
            )
        )

    operationDescriptor operation
      | operation `elem` [prelAddOp, prelAddMethod, memberGlobal prelAdd "add"] =
          Just (ArithmeticAdd, prelAdd)
      | operation `elem` [gPrel "*", gPrel "multiply", memberGlobal (gPrel "Mul") "multiply"] =
          Just (ArithmeticMultiply, gPrel "Mul")
      | operation `elem` [gPrel "-", gPrel "subtract", memberGlobal (gPrel "CheckedSub") "subtract"] =
          Just (ArithmeticSubtract, gPrel "CheckedSub")
      | operation `elem` [gPrel "/", gPrel "divide", memberGlobal (gPrel "CheckedDiv") "divide"] =
          Just (ArithmeticDivide, gPrel "CheckedDiv")
      | operation `elem` [gPrel "%", gPrel "modulo", memberGlobal (gPrel "CheckedMod") "modulo"] =
          Just (ArithmeticModulo, gPrel "CheckedMod")
      | otherwise = Nothing

    projectedDescriptor member
      | member == "add" = Just (ArithmeticAdd, prelAdd)
      | member == "multiply" = Just (ArithmeticMultiply, gPrel "Mul")
      | member == "subtract" = Just (ArithmeticSubtract, gPrel "CheckedSub")
      | member == "divide" = Just (ArithmeticDivide, gPrel "CheckedDiv")
      | member == "modulo" = Just (ArithmeticModulo, gPrel "CheckedMod")
      | otherwise = Nothing

    uniqueDictionaryDomain trait dictionary =
      case
          [ domain
          | domain <- [ArithmeticNatural, ArithmeticInteger]
          , standardPreludeDictionaryIn
              instances
              trait
              (\case
                [headType] ->
                  arithmeticDomainForCarrier headType == Just domain
                _ -> False)
              dictionary
          ] of
        [domain] -> Just domain
        _ -> Nothing

    lower domain operation left right = case (domain, operation) of
      (ArithmeticNatural, ArithmeticAdd) ->
        Just (binary (CGlob prelNatAdd) left right)
      (ArithmeticNatural, ArithmeticMultiply) ->
        Just (binary (CGlob prelNatMultiply) left right)
      (ArithmeticNatural, ArithmeticSubtract) ->
        Just (naturalPrimitive "subInt" left right)
      (ArithmeticNatural, ArithmeticDivide) ->
        Just (naturalPrimitive "divInt" left right)
      (ArithmeticNatural, ArithmeticModulo) ->
        Just (naturalPrimitive "modInt" left right)
      (ArithmeticInteger, ArithmeticAdd) ->
        Just (integerPrimitive "addInt" left right)
      (ArithmeticInteger, ArithmeticMultiply) ->
        Just (integerPrimitive "mulInt" left right)
      (ArithmeticInteger, ArithmeticSubtract) ->
        Just (integerPrimitive "subInt" left right)
      (ArithmeticInteger, ArithmeticDivide) ->
        Just (integerPrimitive "divInt" left right)
      (ArithmeticInteger, ArithmeticModulo) ->
        Just (integerPrimitive "modInt" left right)
      (ArithmeticTypeLevel, _) -> Nothing
      (ArithmeticProviderLaw, _) -> Nothing

    binary function left right = CApp Expl (CApp Expl function left) right
    unary function argument = CApp Expl function argument
    integerPrimitive primitive =
      binary (CGlob (gPrel primitive))
    naturalPrimitive primitive left right =
      unary
        (CGlob (gPrel "natOfInt"))
        ( binary
            (CGlob (gPrel primitive))
            (unary (CGlob prelNatToInt) left)
            (unary (CGlob prelNatToInt) right)
        )

data StandardArithmeticOperation
  = ArithmeticAdd
  | ArithmeticMultiply
  | ArithmeticSubtract
  | ArithmeticDivide
  | ArithmeticModulo

-- | Canonicalize the public standard equality and order combinators while
-- their selected dictionary is still explicit. KCore arithmetic certificates
-- deliberately recognize only primitive comparison identities; this
-- evidence-checked lowering is the bridge from overloaded source semantics
-- to that portable representation.
canonicalStandardComparisonOperation :: [InstanceEntry] -> Term -> Maybe Term
canonicalStandardComparisonOperation instances application = do
  (headTerm, arguments) <-
    pure (spineOfTerm (stripIdentityWrappers application))
  (comparison, trait, dictionary, carrier) <-
    selectedComparison headTerm arguments
  (left, right) <- last2 [argument | (Expl, argument) <- arguments]
  domain <- arithmeticDomainForCarrier carrier
  guard
    ( standardPreludeDictionaryIn
        instances
        trait
        (\case
           [headType] -> arithmeticDomainForCarrier headType == Just domain
           _ -> False)
        dictionary
    )
  let primitive = CGlob (gPrel comparison)
      convert = case domain of
        ArithmeticNatural ->
          \operand -> CApp Expl (CGlob prelNatToInt) operand
        ArithmeticInteger -> id
        ArithmeticTypeLevel -> id
        ArithmeticProviderLaw -> id
  pure
    ( CApp Expl
        (CApp Expl primitive (convert left))
        (convert right)
    )
  where
    selectedComparison headTerm arguments =
      selectedGlobal headTerm arguments
        <|> selectedProjection headTerm arguments

    selectedGlobal headTerm arguments = do
      operation <- termHeadGlob (stripIdentityWrappers headTerm)
      (comparison, trait) <- comparisonDescriptor operation
      carrier : dictionary : _ <-
        pure [argument | (Impl, argument) <- arguments]
      pure (comparison, trait, dictionary, carrier)

    selectedProjection headTerm arguments = do
      (dictionary, member) <- case stripIdentityWrappers headTerm of
        CProjM _ dictionary' member' -> Just (dictionary', member')
        CProjAtM _ dictionary' member' _ -> Just (dictionary', member')
        _ -> Nothing
      (comparison, trait) <- projectedComparisonDescriptor member
      domain <-
        uniqueDictionaryDomain trait dictionary
      pure (comparison, trait, dictionary, arithmeticCarrierTerm domain)

    comparisonDescriptor operation
      | operation
          `elem`
            [ gPrel "=="
            , memberGlobal (gPrel "Eq") "=="
            ] =
          Just ("eqInt", gPrel "Eq")
      | operation == gPrel "<" =
          Just ("ltInt", prelOrd)
      | operation == gPrel "<=" =
          Just ("leInt", prelOrd)
      | otherwise = Nothing

    projectedComparisonDescriptor member
      | member == "==" = Just ("eqInt", gPrel "Eq")
      | member == "<" = Just ("ltInt", prelOrd)
      | member == "<=" = Just ("leInt", prelOrd)
      | otherwise = Nothing

    uniqueDictionaryDomain trait dictionary =
      case
          [ domain
          | domain <- [ArithmeticNatural, ArithmeticInteger]
          , standardPreludeDictionaryIn
              instances
              trait
              (\case
                [headType] ->
                  arithmeticDomainForCarrier headType == Just domain
                _ -> False)
              dictionary
          ] of
        [domain] -> Just domain
        _ -> Nothing

    arithmeticCarrierTerm = \case
      ArithmeticNatural -> CGlob prelNat
      ArithmeticInteger -> CGlob prelInteger
      ArithmeticTypeLevel -> CGlob prelTypeLevel
      ArithmeticProviderLaw -> CGlob prelUnit

arithmeticDomainForCarrier :: Term -> Maybe ArithmeticDomain
arithmeticDomainForCarrier carrier =
  case termHeadGlob (stripIdentityWrappers carrier) of
    Just global
      | global == prelNat -> Just ArithmeticNatural
      | global == prelInteger || global == prelInt -> Just ArithmeticInteger
    _ -> Nothing

-- | Authenticate the compiler-owned prelude instance for one Nat trait.
-- Instance identity, trait identity, premise closure, and checked head carrier
-- must all agree; rendered dictionary/member spellings are not authority.
standardNaturalDictionary :: GName -> Term -> CheckM Bool
standardNaturalDictionary trait =
  standardPreludeDictionary
    trait
    (\case
      [headType] -> isNatType headType
      _ -> False)

-- | Reify a Nat arithmetic expression without erasing the authority that
-- selected its overloaded operations. The shared termination reifier handles
-- already-canonical Core. Numeric literals may additionally occur as a
-- checked @FromInteger Nat@ method application; admit that form only after
-- authenticating the exact coherent standard dictionary. This keeps
-- arithmetic proof normalization provider-driven instead of unfolding an
-- arbitrary same-shaped function.
selectedNatArithmeticExpression :: Int -> Term -> CheckM (Maybe AExpr)
selectedNatArithmeticExpression =
  selectedArithmeticExpression ArithmeticNatural

selectedNatArithmeticExpressionDirect :: Int -> Term -> CheckM (Maybe AExpr)
selectedNatArithmeticExpressionDirect depth term =
  case arithOf depth term of
    Just expression -> pure (Just expression)
    Nothing ->
      case spineOfTerm (stripIdentityWrappers term) of
        (headTerm, arguments)
          | [CLit (LitInt literal)] <-
              [argument | (Expl, argument) <- arguments]
          , literal >= 0
          , Just dictionary <- selectedFromIntegerDictionary headTerm arguments -> do
              standard <- standardNaturalDictionary (gPrel traitFromInteger) dictionary
              pure (if standard then Just (AConst literal) else Nothing)
        _ -> pure Nothing
  where
    selectedFromIntegerDictionary headTerm arguments =
      case stripIdentityWrappers headTerm of
        CProjM _ dictionary member
          | member == "fromInteger" -> Just dictionary
        CProjAtM _ dictionary member _
          | member == "fromInteger" -> Just dictionary
        candidate
          | termHeadGlob candidate
              `elem`
                [ Just (gPrel "fromInteger")
                , Just (memberGlobal (gPrel traitFromInteger) "fromInteger")
                ] ->
              case [argument | (Impl, argument) <- arguments] of
                carrier : dictionary : _
                  | isNatType carrier -> Just dictionary
                _ -> Nothing
        _ -> Nothing

elabSpineArg :: Ctx -> Span -> [Value] -> Term -> Value -> Arg -> [Arg] -> CheckM (Term, Value)
elabSpineArg ctx sp captureRegions fTm fTy arg rest = do
  case (arg, fTy) of
    -- PROVENANCE GATE (§4.2/§14.4): the §28.2 'unsafeAssertProof' escape has
    -- type @forall (@0 p). (@_ : IsProp p) -> (@0 reason : String) -> p@.  Its
    -- '@0 reason : String' documentation binder parses as an ERASED IMPLICIT,
    -- so the ordinary ladder would try to /search/ it from local candidates —
    -- and inside a forall-quantified law (e.g. a lawful 'Monoid' appendAssoc)
    -- the law's own 'String'-typed binders are exactly such candidates, two or
    -- more of which make resolution spuriously ambiguous.  When the user wrote
    -- the reason explicitly (@unsafeAssertProof "…"@), that explicit string IS
    -- the intended 'reason': fill the binder with it directly, bypassing the
    -- candidate search.  This gate is keyed on the CALLEE'S IDENTITY
    -- ('unsafeAssertProof'/'__unsafeAssertProof'), never on the goal type being
    -- 'String' — so a genuine 'String' type-former index elsewhere (which is a
    -- real ambiguity, e.g. a higher-ranked '∀ s:String' coercion) is untouched.
    (ArgExplicit e, VPiBoundM mode Impl q _ _ assumption dom clo)
      | isUnsafeAssertProofHead fTm -> do
          domF <- forceM dom
          case domF of
            VGlobN dg [] | dg == prelString -> do
              aTm <- checkExplicitArg ctx mode q e dom
              aV <- checkedArgumentValue ctx (exprSpan e) dom aTm
              ty' <- clApp clo aV
              nextCtx <- extendLevelAssumption sp ctx assumption
              elabSpineWith nextCtx sp (CApp Impl fTm aTm) ty' rest
            _ -> elabSpineArgGeneral ctx sp captureRegions fTm fTy arg rest
    _ -> elabSpineArgGeneral ctx sp captureRegions fTm fTy arg rest

-- | Whether a (possibly applied) callee term is headed by the §28.2
-- 'unsafeAssertProof' escape or its '__unsafeAssertProof' primitive.  Used to
-- provenance-gate the special handling of its erased 'reason : String' binder.
isUnsafeAssertProofHead :: Term -> Bool
isUnsafeAssertProofHead = go
  where
    go = \case
      CApp _ f _ -> go f
      CGlob g ->
        g == GName preludeModule "unsafeAssertProof"
          || g == GName preludeModule "__unsafeAssertProof"
      _ -> False

elabSpineArgGeneral :: Ctx -> Span -> [Value] -> Term -> Value -> Arg -> [Arg] -> CheckM (Term, Value)
elabSpineArgGeneral ctx sp captureRegions fTm fTy arg rest = do
  case (arg, fTy) of
    -- Declaration-universe constraints are solver-owned prefix binders
    -- (§11.1.2.3A).  An explicit implicit source argument names the next
    -- user telescope slot; it must not be consumed as evidence merely
    -- because the finalized declaration acquired a generated constraint
    -- prefix after its source was checked.  The authenticated assumption and
    -- generated origin are typed Core authority for this distinction, shared with
    -- 'insertDeclarationConstraintImplicits'.
    (ArgImplicit _, VPiEvidenceM _ _ Impl q _ _ assumption@(Just _) BinderGenerated domain closure) -> do
      proof <- resolveImplicitQ ctx sp q domain
      proofValue <- checkedArgumentValue ctx sp domain proof
      resultType <- clApp closure proofValue
      nextCtx <- extendLevelAssumptionFromSynthesized sp ctx assumption proof
      elabSpineWith nextCtx sp (CApp Impl fTm proof) resultType (arg : rest)
    (ArgImplicit e, VPiBoundM mode Impl q _ _ assumption dom clo) -> do
      -- §16.1.7.2: the explicit implicit argument's payload is elaborated
      -- against the selected implicit binder's demanded type 'dom'. If
      -- that elaboration fails, §3.1.4 mandates the portable
      -- E_EXPLICIT_IMPLICIT_CLASSIFIER_MISMATCH code in place of whatever
      -- payload-internal diagnostic 'check' raised (a general rewrite,
      -- not a per-kind special case). Resolve evidence postponed by earlier
      -- explicit operands first: a dependent proof domain may project a
      -- member from that dictionary, and checking it against an unresolved
      -- dictionary meta would compare two merely syntactically different
      -- predicates (§16.1.7.1 spine order).
      flushPendingDeclaration
      dom' <- forceM dom
      n0 <- gets (length . csDiags)
      aTm <- checkExplicitArg ctx mode q e dom'
      retagExplicitImplicitFailure n0
      aV <- checkedArgumentValue ctx (exprSpan e) dom' aTm
      ty' <- clApp clo aV
      nextCtx <- extendLevelAssumption sp ctx assumption
      elabSpineWith nextCtx sp (CApp Impl fTm aTm) ty' rest
    -- §16.1.7.1: an ordinary surface operand does not fill an implicit
    -- binder, including in type position. Synthesize the binder and retry the
    -- same operand against the next explicit binder. The only source form
    -- that supplies this binder is 'ArgImplicit' (@\@payload@) above.
    (ArgExplicit e, VPiBoundM mode Impl q _ _ assumption dom clo) -> do
      kindLike <- isKindLike (ctxLen ctx) dom
      iTm <- synthesizeApplicationImplicit ctx sp q dom
      iV <- checkedArgumentValue ctx sp dom iTm
      ty' <- clApp clo iV
      nextCtx <- extendLevelAssumption sp ctx assumption
      result <- elabSpineWith nextCtx sp (CApp Impl fTm iTm) ty' (ArgExplicit e : rest)
      when kindLike (validateInferredKindArgument ctx sp iTm dom)
      pure result
    (_, VPiBoundM _ Impl q _ _ assumption dom clo) -> do
      kindLike <- isKindLike (ctxLen ctx) dom
      iTm <- synthesizeApplicationImplicit ctx sp q dom
      iV <- checkedArgumentValue ctx sp dom iTm
      ty' <- clApp clo iV
      nextCtx <- extendLevelAssumption sp ctx assumption
      result <- elabSpineWith nextCtx sp (CApp Impl fTm iTm) ty' (arg : rest)
      when kindLike (validateInferredKindArgument ctx sp iTm dom)
      pure result
    (ArgExplicit e, VPiBoundM mode Expl q borrowed _ assumption dom clo) -> do
      aTm <- checkExplicitArg ctx mode q e dom
      when borrowed $
        solveAnonymousBorrowRegion ctx sp captureRegions dom aTm
      aV <- checkedArgumentValue ctx (exprSpan e) dom aTm
      ty' <- clApp clo aV
      nextCtx <- extendLevelAssumption sp ctx assumption
      elabSpineWith nextCtx sp (CApp Expl fTm aTm) ty' rest
    -- a '~place' marker against a callable parameter: the place value
    -- is not an ordinary argument form.  §18.9.3 gives '~' meaning only
    -- through the do-item inout rewrite after resolving InoutParam metadata.
    (ArgInout e msp, VPi Expl _ _ _ _ _)
      | Just root <- mutableVarPlaceRoot ctx e -> do
          infoFields <- mutableBindingLookupFields ctx root "user-written"
          errMutableBinding msp "E_QTT_INOUT_MARKER_UNEXPECTED" (nameText root) "var-place"
            (infoFields ++ [("sourceOperation", "~"), ("repair", "use '~' only at a resolved inout do-item rewrite site")])
            "call-site '~' marker requires resolved inout-parameter metadata at this argument position (§18.9.3)"
          anyHole ctx
    (ArgInout _ msp, VPi Expl _ _ _ _ _) -> do
      errAt msp "E_QTT_INOUT_MARKER_UNEXPECTED" (Just "kappa-hs.qtt.inout-marker")
        "call-site '~' marker requires resolved inout-parameter metadata at this argument position (§18.9.3)"
      anyHole ctx
    -- An explicitly supplied implicit argument constrains an otherwise
    -- unknown callee in the same way an ordinary argument below constrains it
    -- to an explicit Pi. This is required for genuinely polymorphic higher-
    -- order terms such as @\function -> function @x@: the surrounding call
    -- may determine @function@'s complete type only after this lambda has
    -- been checked. The source @-sign is direct evidence for implicitness;
    -- its erased quantity is the ordinary §11.3 forall contract.
    (ArgImplicit e, VFlex m []) -> do
      (aTm0, aTy0) <- infer ctx e
      (aTm, aTy) <- insertAllImplicits ctx (exprSpan e) aTm0 aTy0
      aTyF <- forceM aTy
      paramKind <- isParametricKind (ctxLen ctx) aTyF
      let mode = if paramKind then Parametric else Ordinary
          formation = if paramKind then FormationParametric else FormationOrdinary
      codM <- freshMeta
      domT <- quoteIn ctx aTyF
      piV <- evalIn ctx (CPiFormedM mode formation Impl Q0 False "_a" domT codM)
      solveMeta m piV
      aV <- evalIn ctx aTm
      case piV of
        VPiM _ _ _ _ _ _ clo -> do
          ty' <- clApp clo aV
          elabSpineWith ctx sp (CApp Impl fTm aTm) ty' rest
        _ -> anyHole ctx
    (ArgExplicit e, VFlex m []) -> do
      (aTm0, aTy0) <- infer ctx e
      (aTm, aTy) <- insertAllImplicits ctx (exprSpan e) aTm0 aTy0
      aTyF <- forceM aTy
      paramKind <- isParametricKind (ctxLen ctx) aTyF
      let mode = if paramKind then Parametric else Ordinary
          q = if paramKind then Q0 else QW
          formation = if paramKind then FormationParametric else FormationOrdinary
      codM <- freshMeta
      domT <- quoteIn ctx aTyF
      piV <- evalIn ctx (CPiFormedM mode formation Expl q False "_a" domT codM)
      solveMeta m piV
      aV <- evalIn ctx aTm
      case piV of
        VPiM _ _ _ _ _ _ clo -> do
          ty' <- clApp clo aV
          elabSpineWith ctx sp (CApp Expl fTm aTm) ty' rest
        _ -> anyHole ctx
    (ArgNamedBlock items bsp, _) -> elabNamedBlock ctx fTm fTy items bsp rest
    -- §18.9.3: '~' has no fallback term-level meaning.
    (ArgInout _ msp, _) -> do
      errAt msp "E_QTT_INOUT_MARKER_UNEXPECTED" (Just "kappa-hs.qtt.inout-marker")
        "call-site '~' marker requires resolved inout-parameter metadata at this argument position (§18.9.3)"
      anyHole ctx
    (ArgImplicit e, _) -> do
      errAt (exprSpan e) "E_APPLICATION_ARGUMENT_MISMATCH" (Just "kappa.application.argument-mismatch")
        "an explicit implicit argument was supplied, but the callee has no implicit parameter here (§16.1.7.1)"
      -- recovery: do not cascade a type mismatch from the broken spine
      anyHole ctx
    (ArgExplicit e, _)
      -- a saturated constructor given extra arguments (§10.1.1)
      | Just _ <- termHeadCtor fTm -> do
          errAt (exprSpan e) "E_CONSTRUCTOR_ARITY_MISMATCH" (Just "kappa.constructor.arity")
            "too many arguments in constructor application"
          anyHole ctx
      -- a data-type head applied in term position selects its
      -- same-named constructor (§2.8.3 static-object term facet)
      | CGlob dg <- fTm -> do
          st <- get
          case Map.lookup dg (csDatas st) of
            Just di
              | (ctorG : _) <- [c | c <- diCtors di, gnameText c == gnameText dg] -> do
                  mt <- globalTerm ctorG
                  case mt of
                    Just (cTm, cTy) -> elabSpineWith ctx sp cTm cTy (ArgExplicit e : rest)
                    Nothing -> noncallable e
            _ -> noncallable e
      | otherwise -> noncallable e
      where
        noncallable e' = do
          fT <- quoteIn ctx fTy
          fTz <- zonkTermM (ctxLen ctx) fT
          let calleeR = renderTerm fTz
          -- §3.1.1A: an application diagnostic MUST include the call site
          -- and the callee type site. The call site is the application
          -- span 'sp'; the callee type is exposed both as a related
          -- origin (call-site) and in the §3.2 payload.
          report $
            withPayload
              ( withPayloadField "calleeType" calleeR $
                  payloadKind "application-non-callable"
              )
              $ withRelated (related RoleCallSite sp ("callee type: " <> calleeR))
              $ withNote ("callee type: " <> calleeR)
              $ diag SevError StageElaborate "E_APPLICATION_NONCALLABLE" (Just "kappa-hs.application.non-callable")
                  (exprSpan e')
                  "this expression is not callable"
          anyHole ctx
  where
    termHeadCtor = \case
      CApp _ f _ -> termHeadCtor f
      CLam _ _ _ b -> termHeadCtor b
      CCtor g _ _ -> Just g
      _ -> Nothing

-- | Solve the single omitted region selected by an explicit borrowed
-- argument. The capture wrapper around the borrowed Pi is the typed authority
-- tying that region parameter to this application; arbitrary unsolved Region
-- implicits, non-borrowed parameters, and ambiguous capture sets remain
-- unsolved and receive the ordinary implicit-inference diagnostic.
solveAnonymousBorrowRegion :: Ctx -> Span -> [Value] -> Value -> Term -> CheckM ()
solveAnonymousBorrowRegion ctx site regions argumentType argument = do
  metas <- fmap nub . fmap catMaybes $ forM regions $ \region ->
    forceM region >>= \case
      VFlex meta [] -> do
        solution <- gets (Map.lookup meta . csMetas)
        pure $ case solution of
          Just Nothing -> Just meta
          _ -> Nothing
      _ -> pure Nothing
  case metas of
    [meta] -> do
      let directRegion = borrowedArgumentRegion argument
      case directRegion of
        Just witness -> do
          solved <- solveMetaAcyclic meta witness
          unless solved $
            errAt site "E_INTERNAL_ANONYMOUS_REGION" (Just "kappa.internal.compiler")
              "the inferred borrow-region identity would create a cyclic Core witness"
        Nothing -> do
          typeLevel <- typeValueClassifierLevel ctx argumentType
          intrinsic <- globalTerm prelBorrowRegionOf
          case (typeLevel, intrinsic) of
            (Just level, Just (headTerm, headType)) -> do
              argumentTypeTerm <- quoteIn ctx argumentType
              (witnessTerm, witnessType) <-
                applyGeneratedCoreSpine
                  ctx
                  site
                  headTerm
                  headType
                  [ (Impl, argumentTypeTerm, VSort level)
                  , (Expl, argument, argumentType)
                  ]
              regionType <- globalValueM prelRegion []
              expectType ctx site witnessType regionType
              witness <- evalIn ctx witnessTerm
              solved <- solveMetaAcyclic meta witness
              unless solved $
                errAt site "E_INTERNAL_ANONYMOUS_REGION" (Just "kappa.internal.compiler")
                  "the inferred anonymous borrow region would create a cyclic Core witness"
            _ ->
              errAt site "E_INTERNAL_ANONYMOUS_REGION" (Just "kappa.internal.compiler")
                "the compiler-owned anonymous borrow-region witness is unavailable or ill-typed"
    _ -> pure ()
  where
    -- A stable projection preserves the explicit borrow region of its root.
    -- Recover that identity from typed Core before falling back to the
    -- compiler-owned anonymous-region witness.
    borrowedArgumentRegion = \case
      CVar index ->
        case drop index (ctxEntries ctx) of
          entry : _ ->
            Map.findWithDefault
              Nothing
              (ceName entry)
              (ctxBorrowCaptureRegions ctx)
          [] -> Nothing
      CProj receiver _ -> borrowedArgumentRegion receiver
      CProjAt receiver _ _ -> borrowedArgumentRegion receiver
      CUniverseLift _ _ _ value -> borrowedArgumentRegion value
      CSchemaLift _ _ _ _ _ _ _ _ value -> borrowedArgumentRegion value
      CSealE _ value -> borrowedArgumentRegion value
      _ -> Nothing

-- named constructor application (§10.1.1): supplied fields + defaults in
-- constructor order.
elabNamedBlock :: Ctx -> Term -> Value -> [(Name, Maybe Expr)] -> Span -> [Arg] -> CheckM (Term, Value)
elabNamedBlock ctx fTm fTy items sp rest = do
  st <- get
  mCtorG <- case ctorOf fTm of
    Just g -> pure (Just g)
    Nothing -> case fTm of
      -- a local rebinding of a constructor (§16.1.7.2): the binding's
      -- definiens reveals the constructor
      CVar i -> case drop i (ctxEnv ctx) of
        (v : _) -> do
          v' <- forceM v
          pure (valueCtorOf v')
        [] -> pure Nothing
      _ -> pure Nothing
  forM_ (duplicatesOf [nameText n | (n, _) <- items]) $ \dn ->
    case mCtorG of
      -- §3.2: a malformed *constructor* application uses the
      -- standardized family 'kappa.constructor.arity'; §3.1.4 then
      -- mandates the recoverable portable alias E_CONSTRUCTOR_ARITY_MISMATCH
      -- (wired via 'requiredAliasTable'). The implementation-specific
      -- code carries the precise duplicate/missing/unknown distinction.
      Just g | Map.member g (csCtors st) ->
        errAt sp "E_NAMED_ARG_DUPLICATE" (Just "kappa.constructor.arity")
          ("named argument '" <> dn <> "' is supplied more than once")
      -- §16.1.7.2: on an ordinary callee a malformed block is a
      -- telescope mismatch
      _ -> blockMismatch
  case mCtorG of
    Just g | Just ci <- Map.lookup g (csCtors st) -> do
      let fieldNames = mapMaybe fst (ciFields ci)
      forM_ items $ \(n, _) ->
        unless (nameText n `elem` fieldNames) $
          errAt (nameSpan n) "E_NAMED_ARG_UNKNOWN" (Just "kappa.constructor.arity")
            ("constructor has no named parameter '" <> nameText n <> "'")
      let supplied = [(nameText n, fromMaybe (EVar n) me) | (n, me) <- items]
      args <- forM (ciFields ci) $ \(mname, mdef) ->
        case mname >>= \fn -> lookup fn supplied of
          Just e -> pure (Just (mname, False, Left e))
          Nothing -> case mdef of
            -- field default (§10.1.1): elaborated here, at the
            -- application site, against the field's type, with the
            -- earlier field arguments in scope
            Just d -> pure (Just (mname, True, Left d))
            Nothing -> do
              errAt sp "E_NAMED_ARG_MISSING" (Just "kappa.constructor.arity")
                ("missing constructor argument" <> maybe "" (\n -> " '" <> n <> "'") mname)
              -- Keep the constructor spine saturated during recovery.  If we
              -- simply omit this slot, the named application retains a
              -- function type and checking it at the constructor result emits
              -- a second, downstream type mismatch.  The fresh term stands
              -- only for the already-diagnosed missing argument and is checked
              -- by the same dependent spine logic as a supplied/defaulted
              -- field.
              recovery <- freshMeta
              pure (Just (mname, False, Right recovery))
      -- run the spine with mixed surface/core arguments
      goSpine ctx fTm fTy (catMaybes args)
    -- ordinary function: match named items against the remaining
    -- explicit Pi binder names (§16.1.7.2); a label supplied twice is
    -- a malformed block
    _ -> do
      forM_ (duplicatesOf [nameText n | (n, _) <- items]) $ \_ -> blockMismatch
      goPiNamed fTm fTy [(nameText n, fromMaybe (EVar n) me) | (n, me) <- items]
  where
    -- §16.1.7.2: one diagnostic per malformed block on an ordinary
    -- callee (a telescope mismatch, not a named-argument code)
    blockMismatch =
      errOncePerSpan sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
        "the named-argument block does not match the callee's remaining parameter telescope (§16.1.7.2)"
    ctorOf = \case
      CLam _ _ _ b -> ctorOf b
      CCtor g _ _ -> Just g
      CGlob g -> Just g
      _ -> Nothing
    valueCtorOf = \case
      VCtor g _ -> Just g
      VLam _ _ _ (Closure _ body) -> ctorOf body
      VGlobN g _ -> Just g
      _ -> Nothing
    goPiNamed tm ty0 remaining = do
      ty <- forceM ty0
      case ty of
        VPi Impl q _ _ dom clo -> do
          iTm <- resolveImplicitQ ctx sp q dom
          iV <- checkedArgumentValue ctx sp dom iTm
          ty' <- clApp clo iV
          goPiNamed (CApp Impl tm iTm) ty' remaining
        VPi Expl _ _ nm dom clo
          | Just e <- lookup nm remaining -> do
              aTm <- check ctx e dom
              aV <- checkedArgumentValue ctx (exprSpan e) dom aTm
              ty' <- clApp clo aV
              goPiNamed (CApp Expl tm aTm) ty' [(n, x) | (n, x) <- remaining, n /= nm]
          | not (null remaining) -> do
              blockMismatch
              anyHole ctx
        _
          | null remaining, null rest -> pure (tm, ty)
          | null remaining -> do
              -- §16.1.7.2: the named-argument block is the final
              -- argument of its application site
              blockMismatch
              anyHole ctx
          | otherwise -> do
              blockMismatch
              anyHole ctx
    goSpine _ tm ty [] = elabSpineWith ctx sp tm ty rest
    goSpine ctxAcc tm ty0 (a@(_, _, _) : as) = do
      ty <- forceM ty0
      case ty of
        VPi Impl q _ _ dom clo -> do
          iTm <- resolveImplicitQ ctx sp q dom
          iV <- checkedArgumentValue ctx sp dom iTm
          ty' <- clApp clo iV
          goSpine ctxAcc (CApp Impl tm iTm) ty' (a : as)
        VPi Expl _ _ _ dom clo -> do
          let (mname, isDefault, payload) = a
              argCtx = if isDefault then ctxAcc else ctx
          (aTm, aV) <- case payload of
            Left e -> do
              aTm0 <- check argCtx e dom
              aV <- checkedArgumentValue argCtx (exprSpan e) dom aTm0
              if isDefault
                then do
                  -- a default's term lives under the accumulated field
                  -- bindings; re-quote its value at the outer depth
                  aTm1 <- quoteIn ctx aV
                  pure (aTm1, aV)
                else pure (aTm0, aV)
            Right coreTm -> (,) coreTm <$> checkedArgumentValue argCtx sp dom coreTm
          ty' <- clApp clo aV
          let ctxAcc' = case mname of
                Just fn -> bindCtxLet fn False dom aV ctxAcc
                Nothing -> ctxAcc
          goSpine ctxAcc' (CApp Expl tm aTm) ty' as
        _ -> do
          errAt sp "E_CONSTRUCTOR_ARITY_MISMATCH" (Just "kappa.constructor.arity")
            "too many constructor arguments"
          pure (tm, ty)

-- ── Literals (§6.1.5, §6.1.6) ────────────────────────────────────────

elabIntLit :: Ctx -> Integer -> Maybe Name -> Span -> Maybe Value -> CheckM (Term, Value)
elabIntLit ctx v msuf sp mexp = case msuf of
  Just suf -> do
    known <- prefixResolves ctx (nameText suf)
    if not known
      then badLiteralSuffix ctx suf
      else do
        (fTm, fTy) <- resolveName ctx suf
        admits <- suffixDomAdmits ctx traitFromInteger numericLitDomains fTy
        if admits
          then elabSpine ctx sp fTm fTy [ArgExplicit (EIntLit v Nothing sp)] -- payload : Nat
          else do
            -- §6.1.6: the literal payload is the suffix application's
            -- argument; a parameter type admitting no integer literal
            -- is an application-argument mismatch
            errAt sp "E_APPLICATION_ARGUMENT_MISMATCH" (Just "kappa.application.argument-mismatch")
              ("the suffix function's parameter type admits no integer literal payload (§6.1.6)")
            anyHole ctx
  Nothing -> do
    expected <- maybe (pure Nothing) (fmap Just . forceM) mexp
    case expected of
      Just t
        | isNumHead t -> pure (CLit (LitInt v), t)
        | VFlex {} <- t -> do
            -- Checking against a contextual metavariable is not the same as
            -- inferring without context.  Retain the FromInteger obligation
            -- so later uses can determine the carrier; the ordinary boundary
            -- default still applies to a genuinely unconstrained literal.
            goal <- globalValueM (gPrel traitFromInteger) [(Expl, t)]
            dict <- resolveImplicitQ ctx sp QW goal
            pure (CApp Expl (CProjM Ordinary dict "fromInteger") (CLit (LitInt v)), t)
        | Just other <- nonDefault t -> do
            -- FromInteger elaboration (§6.1.5)
            dict <- resolveLiteralWitness ctx sp traitFromInteger "integer" other
            pure (CApp Expl (CProjM Ordinary dict "fromInteger") (CLit (LitInt v)), other)
      _ -> do
        intType <- globalValueM prelInt []
        pure (CLit (LitInt v), intType) -- defaulting (§6.1.5)
  where
    isNumHead = \case
      VGlobN (GName _ n) [] -> n `elem` numericLitDomains
      _ -> False
    nonDefault = \case
      VFlex {} -> Nothing
      t@(VGlobN (GName _ n) [])
        | n `elem` floatLitDomains -> Just t
      t@VGlobN {} -> Just t
      _ -> Nothing

elabFloatLit :: Ctx -> Double -> Maybe Name -> Span -> Maybe Value -> CheckM (Term, Value)
elabFloatLit ctx v msuf sp mexp = case msuf of
  Just suf -> do
    known <- prefixResolves ctx (nameText suf)
    if not known
      then badLiteralSuffix ctx suf
      else do
        (fTm, fTy) <- resolveName ctx suf
        admits <- suffixDomAdmits ctx traitFromFloat floatLitDomains fTy
        if admits
          then elabSpine ctx sp fTm fTy [ArgExplicit (EFloatLit v Nothing sp)]
          else do
            errAt sp "E_APPLICATION_ARGUMENT_MISMATCH" (Just "kappa.application.argument-mismatch")
              ("the suffix function's parameter type admits no float literal payload (§6.1.6)")
            anyHole ctx
  Nothing -> do
    expected <- maybe (pure Nothing) (fmap Just . forceM) mexp
    case expected of
      Just t
        | isFloatHead t -> pure (CLit (LitDouble v), t)
        | Just other <- nonDefault t -> do
            -- FromFloat elaboration (§6.1.5)
            dict <- resolveLiteralWitness ctx sp traitFromFloat "float" other
            pure (CApp Expl (CProjM Ordinary dict "fromFloat") (CLit (LitDouble v)), other)
      _ -> do
        doubleType <- globalValueM prelDouble []
        pure (CLit (LitDouble v), doubleType) -- defaulting (§6.1.5)
  where
    isFloatHead = \case
      VGlobN (GName _ n) [] -> n `elem` floatLitDomains
      _ -> False
    nonDefault = \case
      VFlex {} -> Nothing
      t@VGlobN {} -> Just t
      _ -> Nothing

-- | Resolve a numeric-literal witness (@FromInteger T@ / @FromFloat T@)
-- at a concrete expected type @T@ (§6.1.5). When @T@ admits no such
-- witness, the failure is a literal-domain mismatch, not a generic
-- unsolved implicit: §3.1.4 (Spec.md:928-929) mandates the portable
-- alias @E_NUMERIC_LITERAL_DOMAIN_MISMATCH@ — "emitted when literal
-- elaboration fails because the surrounding expected type or selected
-- literal witness is not compatible with the literal domain" — backed by
-- the §3.2.3 @kappa.type.literal-domain-mismatch@ family ("integer,
-- floating, … literal elaboration fails because the surrounding context
-- expects an incompatible domain or because no suitable literal witness
-- is available"). The primary message foregrounds the user-visible
-- mismatch and notes the missing witness, per §3.2.3's rendering rule.
--
-- The goal carrier @T@ here is always concrete (the caller's
-- @nonDefault@ guard rejects flex/defaultable types), so the witness
-- goal is never postponed; we run the ordinary §16.3.3 resolution ladder
-- (local implicits, then instance search, then supertrait projection)
-- and only divert the *failure* diagnostic.
resolveLiteralWitness :: Ctx -> Span -> Text -> Text -> Value -> CheckM Term
resolveLiteralWitness ctx sp traitName litKind other = do
  goal <- globalValueM (gPrel traitName) [(Expl, other)]
  mLoc <- localCandidate ctx sp Q0 goal
  mTm <- case mLoc of
    Just tm -> pure (Just tm)
    Nothing -> do
      mInst <- instanceSearch ctx sp goal
      case mInst of
        Just tm -> pure (Just tm)
        Nothing -> superCandidate ctx sp goal
  case mTm of
    Just tm -> pure tm
    Nothing -> do
      tT <- quoteIn ctx other
      let article = if litKind == "integer" then "an " else "a "
      errAt sp "E_NUMERIC_LITERAL_DOMAIN_MISMATCH" (Just "kappa.type.literal-domain-mismatch")
        ( "expected " <> renderTerm tT <> " but found " <> article <> litKind
            <> " literal; " <> renderTerm tT <> " has no " <> traitName
            <> " witness, so it admits no " <> litKind <> " literal domain (§6.1.5)"
        )
      freshMeta

-- | Does the suffix function's first explicit parameter admit the
-- literal payload (§6.1.6)? Either a literal-typed parameter or one
-- with the corresponding literal-trait instance.
suffixDomAdmits :: Ctx -> Text -> [Text] -> Value -> CheckM Bool
suffixDomAdmits ctx traitName litHeads = goPeel (ctxLen ctx)
  where
    goPeel lvl ty = do
      t <- forceM ty
      case t of
        VPi Impl _ _ _ _ clo -> clApp clo (VRigid lvl []) >>= goPeel (lvl + 1)
        VPi Expl _ _ _ dom _ -> do
          d <- forceM dom
          case d of
            VGlobN (GName _ n) []
              | n `elem` litHeads -> pure True
            VGlobN {} -> do
              goal <- globalValueM (gPrel traitName) [(Expl, d)]
              isJust <$> instanceSearch ctx (Span "" (Pos 0 0) (Pos 0 0)) goal
            _ -> pure True
        _ -> pure True

elabString :: Ctx -> StringLit -> [InterpPart] -> Span -> CheckM (Term, Value)
elabString ctx sl parts sp = case (slPrefix sl, parts) of
  (Nothing, _) ->
    -- interpolation applies only to prefixed strings (§6.3.4)
    case slFragments sl of
      [FragLit t] -> do
        stringType <- globalValueM prelString []
        pure (CLit (LitStr t), stringType)
      [] -> do
        stringType <- globalValueM prelString []
        pure (CLit (LitStr ""), stringType)
      _ -> do
        errAt sp "E_INTERNAL" Nothing "plain string with interpolation fragments"
        anyHole ctx
  (Just "f", _) -> do
    -- conventional f-string: concatenate shows of interpolations
    strTy <- globalValueM prelString []
    appendHead <- globalHeadM prelStringAppend
    pieces <- forM (zip [0 ..] (slFragments sl)) $ \(i, frag) -> case frag of
      FragLit t -> pure (CLit (LitStr t))
      FragInterp _ _ -> interpPiece i
      FragInterpFmt _ _ _ -> interpPiece i
    let appendG a b = CApp Expl (CApp Expl appendHead a) b
    pure (foldr appendG (CLit (LitStr "")) pieces, strTy)
    where
      interpPiece i = case [ipExpr p | p <- parts, ipIndex p == i] of
        [e] -> do
          (tm, ty) <- infer ctx e
          (tm1, ty1) <- insertAllImplicits ctx sp tm ty
          showGoal <- globalValueM prelShow [(Expl, ty1)]
          showDict <- resolveImplicit ctx sp showGoal
          pure (CApp Expl (CProjM Ordinary showDict "show") tm1)
        _ -> pure (CLit (LitStr ""))
  (Just "type", _)
    -- §6.3.5: the conventional `type"…"` prefix handler. `type` is a soft
    -- keyword (§5.2) that cannot be an ordinary binding, so the
    -- implementation provides this built-in type-producing handler: the
    -- string content is parsed and elaborated as a type expression,
    -- yielding that Type. (Literal content; an interpolation fragment is
    -- reported, since splicing a runtime value into a static type is not a
    -- meaningful type-producing form here.)
    | all (\f -> case f of FragLit _ -> True; _ -> False) (slFragments sl) -> do
        let content = T.concat [t | FragLit t <- slFragments sl]
        case parseExprText "<type-prefix>" content of
          Left d -> do
            report d {dMessage = "type\"…\" content does not parse as a type (§6.3.5): " <> dMessage d}
            anyHole ctx
          Right tyE -> do
            (tyTm, lvl) <- inferType ctx tyE
            pure (tyTm, VSort lvl)
    | otherwise -> do
        errAt sp "E_PREFIX_HANDLER_TYPE" (Just "kappa.macro.failure")
          "the conventional type\"…\" handler (§6.3.5) takes literal type-expression content; it does not support ${…} interpolation (a runtime value cannot be spliced into a static type)"
        anyHole ctx
  (Just p, _) -> do
    -- §6.3.4.3: the prefix is resolved by ordinary term name
    -- resolution and must elaborate to an 'Elab (InterpolatedMacro t)'
    -- handler; the §6.3.4.5 fragment pipeline runs at elaboration time
    resolvable <- prefixResolves ctx p
    if resolvable
      then elabPrefixHandler ctx sl parts sp p
      else do
        errAt sp "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
          ("unresolved name '" <> p <> "' used as a string-literal prefix (Spec §6.3.4)")
        stringType <- globalValueM prelString []
        pure (CLit (LitStr ""), stringType)

-- | §6.3.4.3–5: run a prefixed string through its 'InterpolatedMacro'
-- handler at elaboration time and splice the produced syntax.
elabPrefixHandler :: Ctx -> StringLit -> [InterpPart] -> Span -> Text -> CheckM (Term, Value)
elabPrefixHandler ctx sl parts sp p = do
  let bail = anyHole ctx
  (hTm, hTy) <- infer ctx (EVar (Name p sp))
  (hTm1, hTy1) <- insertAllImplicits ctx sp hTm hTy
  hTyF <- forceM hTy1
  case hTyF of
    VGlobN g [(_, inner)]
      | g == prelElab -> do
          innerF <- forceM inner
          case innerF of
            VGlobN (GName pm2 "InterpolatedMacro") [(_, tV)]
              | pm2 == preludeModule -> do
                  frags <- fragmentValues
                  hV <- evalRT ctx hTm1
                  rDict <- runElab ctx sp hV
                  case rDict of
                    Left () -> bail
                    Right dictV -> do
                      ec <- ecRT_
                      let methodV = vproj ec Ordinary dictV "buildInterpolated"
                      action <- vappRT methodV [listValue frags]
                      res <- runElab ctx sp action
                      case res of
                        Left () -> bail
                        Right sv -> do
                          mtm <- spliceSyntaxValue ctx sp tV sv
                          case mtm of
                            Nothing -> bail
                            Just tm -> pure (tm, tV)
            _ -> badHandler hTyF >> bail
    VGlobN (GName pm "InterpolatedMacro") _
      | pm == preludeModule -> do
          errAt sp "E_PREFIX_RUNTIME_HANDLER" (Just "kappa.macro.failure")
            "a runtime 'InterpolatedMacro' value is not a valid prefixed-string handler; handler evidence must be meta-phase, an 'Elab (InterpolatedMacro _)' term (§6.3.4.3)"
          bail
    _ -> badHandler hTyF >> bail
  where
    badHandler ty = do
      tT <- quoteIn ctx ty
      errAt sp "E_PREFIX_HANDLER_TYPE" (Just "kappa.macro.failure")
        ("the prefixed-string handler '" <> p
           <> "' must elaborate to 'Elab (InterpolatedMacro _)'; this term has type "
           <> renderTerm tT <> " (§6.3.4.3)")
    -- §6.3.4.4 fragment construction (literal merging and escape
    -- decoding already performed by the lexer)
    fragmentValues =
      forM (zip [0 ..] (slFragments sl)) $ \(i, frag) -> case frag of
        FragLit t -> pure (VCtor prelLit [VLit (LitStr t)])
        FragInterp _ isp -> interpValue i isp Nothing
        FragInterpFmt _ isp fmt -> interpValue i isp (Just fmt)
    interpValue i isp mfmt = do
      payload <- case [ipExpr q | q <- parts, ipIndex q == i] of
        [e] -> do
          -- elaborate for diagnostics and the fragment's type index;
          -- the handler receives the quoted surface syntax (§6.3.4.4)
          (tm0, ty0) <- infer ctx e
          _ <- insertAllImplicits ctx isp tm0 ty0
          pure e
        _ -> pure (EUnit isp)
      qs <- mkQuotedSyntax ctx payload isp
      let quoteV = VQuote qs []
      pure $ case mfmt of
        Nothing -> VCtor prelInterp [quoteV]
        Just fmt -> VCtor prelInterpFmt [quoteV, VLit (LitStr fmt)]

-- ── Records, projections, patches ────────────────────────────────────

elabRecordLit :: Ctx -> [RecItem] -> Span -> CheckM (Term, Value)
elabRecordLit ctx items sp = do
  rs <- forM items $ \it -> do
    let n = riName it
        mv = riValue it
        q = qOf (riQuantity it)
    let e = fromMaybe (EVar n) mv -- punning
    (tm, ty) <- infer ctx e
    (tm1, ty1) <- insertAllImplicits ctx (nameSpan n) tm ty
    observation <- observationJudgmentForTerm ctx tm1 ty1
    when (ojMode observation == Parametric) $
      reportParametricPromotion (nameSpan n) "record-field" observation
    pure (nameText n, q, tm1, ty1)
  forM_ (duplicatesOf [n | (n, _, _, _) <- rs]) $ \n ->
    errAt sp "E_RECORD_DUPLICATE_FIELD" (Just "kappa-hs.record.duplicate-field")
      ("record literal has duplicate field '" <> n <> "'")
  -- evaluate fields in source order via lets, assemble canonically
  let sorted = sortOn (\(n, _, _, _) -> n) rs
  pure
    ( CRecordV [(n, tm) | (n, _, tm, _) <- sorted]
    , VRecordTQ [RecordField n Ordinary FormationOrdinary q Nothing ty | (n, q, _, ty) <- sorted]
    )

-- | Project one named source field from an authenticated constructor subset.
--
-- Constructor result unification determines family parameters and indices,
-- but it cannot determine preceding payload binders that do not occur in the
-- result. A later dependent field must therefore be instantiated with the
-- exact projection terms of those preceding binders. This routine walks the
-- checked source telescope in declaration order, recursively constructs those
-- projections, and only then reads the requested field type.
--
-- The same result drives both explicit payload projection and erased hidden
-- projection, keeping the term used in the dependent type identical to the
-- term returned at the source projection site. Constructor subsets with
-- inconsistent field order, mode, quantity, or type fail closed.
nominalConstructorSourceFieldProjection
  :: Ctx
  -> Term
  -> Value
  -> [GName]
  -> Text
  -> Span
  -> CheckM (Maybe (Term, ObservationMode, Icit, Q, Value))
nominalConstructorSourceFieldProjection
  ctx receiverTerm receiverType constructors targetName site =
    go Set.empty targetName
  where
    go seen fieldName
      | fieldName `Set.member` seen = pure Nothing
      | otherwise = do
          state <- get
          details <-
            forM constructors $ \constructor ->
              case Map.lookup constructor (csCtors state) of
                Nothing -> pure Nothing
                Just info -> do
                  (universes, _, arguments, namedBinders, explicitFields) <-
                    instantiateConstructorForFields
                      ctx constructor info receiverType site
                  let sourceCount = length (ciSourceFields info)
                      sourceBinders =
                        drop (length namedBinders - sourceCount) namedBinders
                      sourceEntries =
                        [ (sourceIcit, binder)
                        | (sourceIcit, sourceName) <- ciSourceFields info
                        , binder@(_, binderName, _, _, _) <- sourceBinders
                        , sourceName == Just binderName
                        ]
                      indexedEntries = zip [0 :: Int ..] sourceEntries
                  case find
                    (\(_, (_, (_, binderName, _, _, _))) ->
                      binderName == fieldName)
                    indexedEntries of
                    Nothing -> pure Nothing
                    Just
                      ( targetSourceIndex
                        , ( targetIcit
                          , (targetArgumentIndex, _, targetMode, targetQuantity, targetType)
                          )
                        ) -> do
                          hydrated <-
                            and <$> forM
                              (take targetSourceIndex sourceEntries)
                              (\(priorIcit, (argumentIndex, priorName, priorMode, _, _)) -> do
                                priorTerm <-
                                  case priorIcit of
                                    Impl ->
                                      pure
                                        (Just (CProjM priorMode receiverTerm priorName))
                                    Expl ->
                                      fmap (\(term, _, _, _, _) -> term)
                                        <$> go (Set.insert fieldName seen) priorName
                                case (priorTerm, drop argumentIndex arguments) of
                                  (Just exactTerm, argument : _) -> do
                                    argumentValue <- evalIn ctx (caTerm argument)
                                    exactValue <- evalIn ctx exactTerm
                                    unify ctx argumentValue exactValue
                                  _ -> pure False)
                          if not hydrated
                            then pure Nothing
                            else do
                              targetType' <- forceM targetType
                              let explicitIndex =
                                    elemIndex
                                      targetArgumentIndex
                                      [ index
                                      | (index, _, _, _) <- explicitFields
                                      ]
                              pure
                                ( Just
                                    ( constructor
                                    , universes
                                    , info
                                    , namedBinders
                                    , length explicitFields
                                    , explicitIndex
                                    , targetMode
                                    , targetIcit
                                    , targetQuantity
                                    , targetType'
                                    )
                                )
          evalContext <- ec_
          case sequence details of
            Just
              ( first@(_, _, _, _, _, _, firstMode, firstIcit, firstQuantity, firstType)
                  : rest
                )
                | all
                    (\(_, _, _, _, _, _, mode, icit, quantity, fieldType) ->
                      mode == firstMode
                        && icit == firstIcit
                        && quantity == firstQuantity
                        && convertible
                          evalContext
                          (ctxLen ctx)
                          firstType
                          fieldType)
                    rest -> do
                      projection <- case firstIcit of
                        Impl ->
                          pure (Just (CProjM firstMode receiverTerm fieldName))
                        Expl -> do
                          annotation <- quoteIn ctx receiverType
                          let makeAlt
                                ( constructor
                                  , universes
                                  , info
                                  , namedBinders
                                  , arity
                                  , Just fieldIndex
                                  , _
                                  , _
                                  , _
                                  , _
                                  ) =
                                  syntheticConstructorPatternLayout
                                    site
                                    constructor
                                    universes
                                    info
                                    namedBinders
                                    [ if index == fieldIndex
                                        then CPVarM Ordinary "__field"
                                        else CPWild
                                    | index <- [0 .. arity - 1]
                                    ]
                                    >>= \case
                                      Just layout ->
                                        pure $ do
                                          binderIndex <-
                                            listToMaybe
                                              (drop fieldIndex (scplExplicitBinderIndices layout))
                                              >>= id
                                          pure
                                            ( CaseAlt
                                                (scplPattern layout)
                                                Nothing
                                                (CVar binderIndex)
                                            )
                                      Nothing -> pure Nothing
                              makeAlt _ = pure Nothing
                          alternatives <- traverse makeAlt (first : rest)
                          pure
                            ( CMatch receiverTerm (Just annotation) Nothing
                                <$> sequence alternatives
                            )
                      pure
                        ( fmap
                            (\term ->
                              ( term
                              , firstMode
                              , firstIcit
                              , firstQuantity
                              , firstType
                              ))
                            projection
                        )
            _ -> pure Nothing

-- | Names that occur more than once (each reported once).
duplicatesOf :: [Text] -> [Text]
duplicatesOf ns = nub [n | n <- ns, length (filter (== n) ns) > 1]

elabDot :: Ctx -> Expr -> DotMember -> CheckM (Term, Value)
elabDot ctx e member = do
  let mname = case member of
        DotName n -> n
        DotOperator n -> n
  -- effect-operation selection label.op (§18.1.15, §7.3) — scoped or top-level
  merged <- effMerged ctx
  case e of
    EVar ln
      | Just eli <- Map.lookup (nameText ln) merged
      , Just op <- find ((== nameText mname) . eoiName) (eliOps eli) ->
          effOpSelection ctx (nameSpan mname) eli op
    _ -> elabDotOrdinary ctx e member mname

elabDotOrdinary :: Ctx -> Expr -> DotMember -> Name -> CheckM (Term, Value)
elabDotOrdinary ctx e member mname = do
  -- reified module objects: (module a).b chains (§2.8.6)
  case modObjPathOf e of
    Just segs -> elabModuleMember ctx (segs ++ [nameText mname]) (nameSpan mname)
    Nothing -> do
      -- fully-qualified module path, e.g. std.prelude.Bool or main.T (§8.3)
      mPath <- case modulePathOf e of
        Just segs@(s0 : _) | Nothing <- lookupCtx s0 ctx -> do
          let mn = ModuleName segs
              g = GName mn (nameText mname)
          st <- get
          if (Map.member g (csGlobals st) || Map.member g (csCtors st))
            && memberVisible st mn (nameText mname)
            then do
              -- §4.5: a bare fully-qualified reference (@std.prelude.__eqProof@)
              -- resolves straight to 'globalTerm'; gate the raw-admit
              -- intrinsics here so it cannot bypass the soundness gate.
              gateUnsafeResolved g (nameSpan mname)
              globalTerm g
            else pure Nothing
        _ -> pure Nothing
      case mPath of
        Just r -> pure r
        Nothing -> elabDotUnqualified ctx e member mname
  where
    modulePathOf = \case
      EVar (Name s _) -> Just [s]
      EDot inner (DotName (Name s _)) -> (++ [s]) <$> modulePathOf inner
      _ -> Nothing
    modObjPathOf = \case
      EKindQualified SelModule (Name s _) _ -> Just [s]
      EDot inner (DotName (Name s _)) -> (++ [s]) <$> modObjPathOf inner >>= ensureModObj
      _ -> Nothing
      where
        ensureModObj segs = Just segs

-- visibility of a member of another module (§8.5): only exported names
-- are accessible from outside the defining module
memberVisible :: CheckState -> ModuleName -> Text -> Bool
memberVisible st mn nm =
  mn == csModule st
    || case Map.lookup mn (csModuleExports st) of
      Just ex -> nm `elem` ex
      Nothing -> True -- prelude and unknown modules: unrestricted

-- a member completion of a reified module path: either a deeper module
-- object or nothing nameable (§2.8.6)
elabModuleMember :: Ctx -> [Text] -> Span -> CheckM (Term, Value)
elabModuleMember ctx segs sp = do
  st <- get
  if Map.member (ModuleName segs) (csModuleExports st) || ModuleName segs == csModule st
    then pure (moduleObjectFor (ModuleName segs))
    else do
      errAt sp "E_STATIC_OBJECT_UNRESOLVED" (Just "kappa.name.unresolved")
        ("no module named '" <> T.intercalate "." segs <> "' is in this compilation unit (Spec §2.8.6)")
      anyHole ctx

-- §2.8.6 kind-qualified static-object expressions: select the named
-- facet; an unknown subject is E_STATIC_OBJECT_UNRESOLVED.
elabKindQualified :: Ctx -> KindSelector -> Name -> Span -> CheckM (Term, Value)
elabKindQualified ctx sel name sp = do
 let n = nameText name
     nsp = nameSpan name
 merged <- effMerged ctx
 case sel of
  SelModule -> do
    st <- get
    case resolveModuleObjectName st n of
      Just mn -> pure (moduleObjectFor mn)
      Nothing -> do
        errAt sp "E_STATIC_OBJECT_UNRESOLVED" (Just "kappa.name.unresolved")
          ("no module named '" <> n <> "' is in scope (Spec §2.8.6)")
        anyHole ctx
  -- §7.1.1: resolution is by ordinary lookup in the selected position,
  -- so lexically scoped declarations precede globals: a §9.3.1.1
  -- scoped-effect declaration provides both a type facet (its effect
  -- interface, §7.6) and an effect-label facet (its canonical self
  -- label)
  SelEffectLabel
    | Just eli <- Map.lookup n merged -> do
        labelHead <- globalHeadM (eliLabel eli)
        labelType <- globalValueM prelEffLabel []
        pure (labelHead, labelType)
  SelType
    | Just (i, e) <- lookupCtx n ctx -> do
        t <- forceM (ceType e)
        case t of
          VSort _ -> do
            observation <- observationForBinding (ceMode e) (fromMaybe (ceName e) (ceObservationOrigin e)) (ceType e)
            when (ojMode observation == Parametric) $
              reportParametricPromotion nsp "static-object-reification" observation
            pure (CVar i, ceType e)
          _ -> do
            errAt nsp "E_STATIC_OBJECT_KIND_MISMATCH" (Just "kappa-hs.static-object.kind")
              ("'" <> n <> "' is not a type in this scope; the 'type' selector does not apply (Spec §7.1.1)")
            anyHole ctx
  _ -> do
    mg <- lookupGlobalName n
    -- §2.8.3/§7.1.1: the selector must agree with the named facet — a
    -- trait has no type facet, so `type C` on a trait is rejected, and
    -- `trait T` on a non-trait declaration is rejected
    isTrait <- case mg of
      Just g -> gets (Map.member g . csTraits)
      Nothing -> pure False
    isLabelG <- case mg of
      Just g -> do
        mt <- gets (fmap gdType . Map.lookup g . csGlobals)
        case mt of
          Just tv ->
            forceM tv >>= \case
              VGlobN lg [] -> pure (lg == prelEffLabel)
              _ -> pure False
          Nothing -> pure False
      Nothing -> pure False
    if sel == SelType && isTrait
      then do
        errAt nsp "E_STATIC_OBJECT_KIND_MISMATCH" (Just "kappa-hs.static-object.kind")
          ("'" <> n <> "' names a trait; the 'type' selector does not apply (Spec §2.8.3)")
        anyHole ctx
      else if sel == SelTrait && isJust mg && not isTrait
        then do
          errAt nsp "E_STATIC_OBJECT_KIND_MISMATCH" (Just "kappa-hs.static-object.kind")
            ("'" <> n <> "' does not name a trait; the 'trait' selector requires a trait declaration (Spec §7.1.1)")
          anyHole ctx
      else if sel == SelEffectLabel && isJust mg && not isLabelG
        then do
          errAt nsp "E_STATIC_OBJECT_KIND_MISMATCH" (Just "kappa-hs.static-object.kind")
            ("'" <> n <> "' does not name an effect label; the 'effectLabel' selector requires an effect-label declaration (Spec §7.1.1)")
          anyHole ctx
      else do
        mr <- case mg of
          Just g -> globalTypeIn ctx nsp g
          Nothing -> pure Nothing
        case mr of
          Just r -> pure r
          Nothing -> do
            errAt nsp "E_STATIC_OBJECT_UNRESOLVED" (Just "kappa.name.unresolved")
              ("kind-qualified name does not resolve to a static object: '" <> n <> "' (Spec §2.8.6)")
            anyHole ctx

-- | §2.8.4: the manifest value of a receiver term — resolved through
-- local definientia, module-level lets without widening signatures,
-- record projections of such, and direct (immediately-used) results.
-- A binding under a widening signature forgets static-object identity.
manifestValue :: Ctx -> Term -> CheckM (Maybe Value)
manifestValue ctx tm = case tm of
  CGlob g -> do
    st <- get
    if Map.member g (csManifest st) || Map.member g (csDatas st)
      then case Map.lookup g (csGlobals st) >>= gdValue of
        Just v -> Just <$> forceM v
        Nothing -> pure (Just (VGlobN g []))
      else pure Nothing
  CProj t f -> do
    mv <- manifestValue ctx t
    -- §13.2.10: transparent members of a sealed package stay manifest;
    -- opaque members forget static-object identity
    let unwrap v =
          forceM v >>= \case
            VSealV ls r | f `notElem` ls -> unwrap r
            v' -> pure v'
    mv' <- traverse unwrap mv
    case mv' of
      Just (VRecordV fs) | Just v <- lookup f fs -> Just <$> forceM v
      _ -> pure Nothing
  -- P0.4: a fixed-offset projection manifests by NAME exactly like CProj (the
  -- catch-all's eager evalIn would wrongly manifest a non-manifest projection).
  CProjAt t f _ -> do
    mv <- manifestValue ctx t
    let unwrap v =
          forceM v >>= \case
            VSealV ls r | f `notElem` ls -> unwrap r
            v' -> pure v'
    mv' <- traverse unwrap mv
    case mv' of
      Just (VRecordV fs) | Just v <- lookup f fs -> Just <$> forceM v
      _ -> pure Nothing
  CVar i -> case drop i (ctxEnv ctx) of
    (v : _) -> do
      v' <- forceM v
      pure $ case v' of
        VRigid {} -> Nothing -- an opaque binder, not a let definiens
        _ -> Just v'
    [] -> pure Nothing
  _ -> Just <$> (evalIn ctx tm >>= forceM)

-- a reified module object (§2.8.6): a record carrying the module
-- identity in a tag field, so member access through rebindings works
moduleObjectFor :: ModuleName -> (Term, Value)
moduleObjectFor (ModuleName segs) =
  let moduleName = ModuleName segs
      tag = moduleObjectTag moduleName
   in (CRecordV [(tag, CRecordV [])], evalModuleSignatureType moduleName)

-- | Resolve the contextual module declaration used by both @module M@ and
-- @moduleSig M@. Module aliases are lexical declarations; an unaliased
-- one-component module name is accepted only when its interface is present.
resolveModuleObjectName :: CheckState -> Text -> Maybe ModuleName
resolveModuleObjectName st name =
  Map.lookup name (csModuleAliases st)
    <|> let direct = ModuleName [name]
         in if direct == csModule st || Map.member direct (csModuleExports st)
              then Just direct
              else Nothing

-- | The current Core representation of a module signature is deliberately
-- nominal and contextual. The hidden field records the resolved module
-- identity; it is not a structural approximation of the exported facets.
-- Member projection recognizes this checked type and delegates to
-- 'moduleMember', which consults the canonical interface tables and freshly
-- instantiates the selected declaration's universe schema.
moduleSignatureType :: ModuleName -> Term
moduleSignatureType moduleName =
  CRecordT [(moduleObjectTag moduleName, CRecordT [])]

evalModuleSignatureType :: ModuleName -> Value
evalModuleSignatureType moduleName =
  VRecordT [(moduleObjectTag moduleName, VRecordT [])]

moduleObjectTag :: ModuleName -> Text
moduleObjectTag (ModuleName segments) =
  "__module:" <> T.intercalate "." segments

-- member access on a reified module object (§2.8.6/§8.5)
moduleMember :: Ctx -> ModuleName -> Name -> CheckM (Term, Value)
moduleMember ctx modName mname = do
  st <- get
  let g = GName modName (nameText mname)
  -- §4.5: a reified module-object member resolves straight to 'globalTerm';
  -- gate the raw-admit intrinsics here too so this path cannot bypass it.
  gateUnsafeResolved g (nameSpan mname)
  mt <-
    if memberVisible st modName (nameText mname)
      then case (Map.member g (csDatas st), Map.lookup g (csGlobals st)) of
        -- a member naming a data type denotes the type facet; term
        -- applications fall through to its same-named constructor
        (True, Just gd) -> do
          (headTerm, ty, _) <- instantiateGlobal g gd
          pure (Just (headTerm, ty))
        _ -> globalTerm g
      else pure Nothing
  case mt of
    Just r -> pure r
    Nothing -> do
      errAt (nameSpan mname) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
        ("module object has no exported member '" <> nameText mname <> "' (Spec §2.8.6, §8.5)")
      anyHole ctx

elabDotUnqualified :: Ctx -> Expr -> DotMember -> Name -> CheckM (Term, Value)
elabDotUnqualified ctx e member mname = do
  -- module-qualified reference?
  case e of
    EVar (Name base _) -> do
      st <- get
      case lookupCtx base ctx of
        Just (i, _) -> do
          -- a local rebinding of a reified type object (§2.8.3): its
          -- definiens names the data type, select the constructor
          mv <- case drop i (ctxEnv ctx) of
            (v : _) -> Just <$> forceM v
            [] -> pure Nothing
          case mv of
            Just (VGlobN d _)
              | Just di <- Map.lookup d (csDatas st)
              , (ctorG : _) <- [c | c <- diCtors di, gnameText c == nameText mname] -> do
                  mt <- globalTerm ctorG
                  case mt of
                    Just r -> pure r
                    Nothing -> ordinary mname
            _ -> ordinary mname
        Nothing ->
          case Map.lookup base (csModuleAliases st) of
            Just modName -> do
              let g = GName modName (nameText mname)
              -- §4.5: an aliased qualified reference (@import std.prelude as P@,
              -- then @P.__eqProof@) resolves straight to 'globalTerm'; gate the
              -- raw-admit intrinsics here so it cannot bypass the soundness gate.
              gateUnsafeResolved g (nameSpan mname)
              mt <-
                if memberVisible st modName (nameText mname)
                  then globalTerm g
                  else pure Nothing -- private members are not accessible (§8.5)
              case mt of
                Just r -> pure r
                Nothing -> do
                  -- §3.1.4/§8.3.1A: when the alias spelling 'base' also
                  -- names a same-spelling type/constructor/declaration,
                  -- the qualified name resolved through the alias rather
                  -- than that declaration, and the alias collision is the
                  -- primary repairable cause (repair: rename the alias or
                  -- qualify the type). Report the §3.1.4-mandated portable
                  -- code; otherwise the alias is unambiguous and the
                  -- member is simply absent.
                  mShadow <- shadowedDeclKind base
                  case mShadow of
                    Just kind ->
                      errAt (nameSpan mname) "E_MODULE_ALIAS_TYPE_COLLISION"
                        (Just "kappa.name.module-alias-collision")
                        ( "qualified name '" <> base <> "." <> nameText mname
                            <> "' resolves through module alias '" <> base
                            <> "' (denoting " <> moduleNameText modName
                            <> "), which shadows the same-spelling " <> kind
                            <> " '" <> base
                            <> "'; the alias has no exported member '"
                            <> nameText mname
                            <> "'. Rename the alias or qualify the "
                            <> kind <> " (Spec §8.3.1A, §3.1.4)"
                        )
                    Nothing ->
                      errAt (nameSpan mname) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
                        ("module '" <> base <> "' has no exported member '" <> nameText mname <> "' (Spec §8.5)")
                  anyHole ctx
            Nothing -> do
              -- Qualified trait member: @Trait.member@ denotes the generated
              -- projection accessor.  This is a namespace selection by the
              -- resolved trait identity, not method-call sugar on the trait
              -- constructor value (§14.2.1).
              mg <- lookupGlobalName base
              stx <- get
              case mg >>= \trait -> (trait,) <$> Map.lookup trait (csTraits stx) of
                Just (trait, info)
                  | nameText mname `elem` tiMembers info ->
                      globalTerm (memberGlobal trait (nameText mname)) >>= \case
                        Just result -> pure result
                        Nothing -> anyHole ctx
                _ -> do
                  -- Static member of a type: @T.C@ selects a constructor
                  -- (§7.3). A rebound reified type object follows the same
                  -- resolved data identity.
                  mDataG <- case mg of
                    Just tyG
                      | Map.member tyG (csDatas stx) -> pure (Just tyG)
                      | Just gd <- Map.lookup tyG (csGlobals stx)
                      , Just v <- gdValue gd -> do
                          v' <- forceM v
                          pure $ case v' of
                            VGlobN d _ | Map.member d (csDatas stx) -> Just d
                            _ -> Nothing
                    _ -> pure Nothing
                  case mDataG of
                    Just tyG
                      | Just di <- Map.lookup tyG (csDatas stx)
                      , Just ctorG <- lookupCtorIn di (nameText mname) -> do
                          globalTerm ctorG >>= \case
                            Just result -> pure result
                            Nothing -> anyHole ctx
                    _ -> ordinary mname
              where
                lookupCtorIn di nm =
                  case [c | c <- diCtors di, gnameText c == nm] of
                    (c : _) -> Just c
                    [] -> Nothing
    _ -> ordinary mname
  where
    ordinary mn0 = do
      (tm, ty) <- infer ctx e
      (tm1, ty1) <- insertAllImplicits ctx (exprSpan e) tm ty
      -- §2.8.3/§2.8.6: a receiver VALUE that is a reified type object
      -- selects static constructors; a reified module object selects
      -- module members. Only §2.8.4 manifest bindings (no widening
      -- signature) preserve the identity.
      mrv <- manifestValue ctx tm1
      st0 <- get
      case fromMaybe (VRecordV []) mrv of
        VGlobN d _
          | Just di <- Map.lookup d (csDatas st0)
          , (ctorG : _) <- [c | c <- diCtors di, gnameText c == nameText mn0] -> do
              mt <- globalTerm ctorG
              case mt of
                Just r -> pure r
                Nothing -> ordinaryAt mn0 tm1 ty1
        VRecordV [(tag, _)]
          | Just modTxt <- T.stripPrefix "__module:" tag ->
              moduleMember ctx (ModuleName (T.splitOn "." modTxt)) mn0
        _ -> ordinaryAt mn0 tm1 ty1

    ordinaryAt mn0 tm1 ty1 = do
      t0 <- forceM ty1
      -- §13.2.10: package-member selection sees the signature's
      -- underlying record type (opacity is enforced by the value)
      t <- case t0 of
        VSigT _ inner -> forceM inner
        _ -> pure t0
      case t of
        VRecordT [(tag, VRecordT [])]
          | Just moduleText <- T.stripPrefix "__module:" tag ->
              moduleMember ctx (ModuleName (T.splitOn "." moduleText)) mn0
        VRecordTQ fields
          | Just field <- find ((== nameText mn0) . rfName) fields -> do
              fty' <- substThisInto ctx tm1 (rfType field)
              let f = nameText mn0
                  names = map rfName fields
                  proj
                    | names == sort names
                    , Just i <- elemIndex f names = CProjAtM (rfMode field) tm1 f i
                    | otherwise = CProjM (rfMode field) tm1 f
              pure (proj, fty')
        VRecordT fs
          | Just fty <- lookup (nameText mn0) fs -> do
              -- §13.2.1: a dependent field type sees the receiver as 'this'
              fty' <- substThisInto ctx tm1 fty
              -- P0.4: this is the ONLY statically-known CLOSED record layout,
              -- so emit a fixed-offset projection — the field's index in the
              -- record's slot order.  The K_REC value's slots follow `fs`
              -- order; for NAMED records that order is `sortOn fst` (the
              -- canonical layout), so the index is the field's position in
              -- `fs`.  CRUCIALLY we only do this when `fs` is *already*
              -- sorted: tuples are the one closed record whose value is built
              -- POSITIONALLY (`_1`.._n), which diverges from lexicographic
              -- order at arity >= 10 (`_10` < `_2`).  Emitting a fixed offset
              -- there would read the wrong slot, so any unsorted layout falls
              -- back to the name-based CProj (kproj).  Every other projection
              -- site (open/sealed/dict/derived) keeps CProj too, and the
              -- backend treats CProjAt == CProj when it cannot use an offset.
              let f = nameText mn0
                  names = map fst fs
                  proj
                    | names == sort names
                    , Just i <- elemIndex f names = CProjAtM Ordinary tm1 f i
                    | otherwise = CProjM Ordinary tm1 f
              pure (proj, fty')
          | otherwise -> do
              -- a record receiver without the field: try method sugar,
              -- otherwise report the missing field (§13.1.4)
              mg <- lookupGlobalName (nameText mn0)
              case mg of
                Just _ -> methodSugar tm1 t mn0
                Nothing -> do
                  -- §3.1.11 / §13.2.11: internal existential labels are
                  -- not source-addressable fields, so they are excluded
                  -- from the user-facing field list (a package that
                  -- exposes only such labels lists no fields).
                  let visibleFields = [n | (n, _) <- fs, not (isExistsInternalLabel n)]
                  errAt (nameSpanOf member) "E_RECORD_PROJECTION_MISSING_FIELD"
                    (Just "kappa.name.unresolved")
                    ("record has no field '" <> nameText mn0
                       <> "' (fields: " <> T.intercalate ", " visibleFields <> ")")
                  anyHole ctx
        -- §11.3.1A: explicit-prefix projection on an open record
        VGlobN (GName pm "__openRec") [_, (_, prefixV)]
          | pm == preludeModule -> do
              pf <- forceM prefixV
              case pf of
                VRecordT fs
                  | Just fty <- lookup (nameText mn0) fs -> do
                      fty' <- substThisInto ctx tm1 fty
                      pure (CProjM Ordinary tm1 (nameText mn0), fty')
                _ -> methodSugar tm1 t mn0
        -- trait-dictionary member projection d.(==) (§14.2.1)
        VGlobI headG headUniverses spine -> do
          st <- get
          let semanticSpine = traitSemanticSpineIn st headG spine
          -- a member INHERITED from a supertrait is reached
          -- through the dictionary's '__superN' evidence fields.
          msuper <-
            case (Map.lookup headG (csTraits st), semanticSpine) of
              (Just ti, Just arguments) | nameText mn0 `notElem` tiMembers ti ->
                supertraitMemberProject ctx 8 headG headUniverses (map snd arguments) tm1 (nameText mn0)
              _ -> pure Nothing
          case (Map.lookup headG (csTraits st), semanticSpine) of
            (Just ti, Just arguments)
              | nameText mn0 `elem` tiMembers ti -> do
                  let memberMode = Map.findWithDefault Ordinary (nameText mn0) (tiMemberModes ti)
                      projected = CProjM memberMode tm1 (nameText mn0)
                  memberTypeOf
                    ctx
                    (nameSpanOf member)
                    (tiParamCount ti)
                    headG
                    (nameText mn0)
                    tm1
                    t
                    projected
            (Just _, Nothing) -> do
              errAt (nameSpanOf member) "E_TRAIT_MEMBER_TELESCOPE_MISMATCH" (Just "kappa.internal.compiler")
                "trait dictionary carries a malformed declaration-evidence prefix"
              anyHole ctx
            _ | Just hit <- msuper -> pure hit
            _ ->
              -- named-field projection on single-constructor data
              -- (§10.2), or on a §7.4.1 flow-refined subset of the
              -- constructors when the receiver is a refined variable
              case Map.lookup headG (csDatas st) of
                Just di
                  | ctors <- projectableCtors ctx di
                  , not (null ctors) ->
                      nominalConstructorSourceFieldProjection
                        ctx
                        tm1
                        t
                        ctors
                        (nameText mn0)
                        (nameSpanOf member)
                        >>= \case
                          Just (projected, _, Expl, _, fieldType) ->
                            pure (projected, fieldType)
                          _ ->
                            hiddenConstructorFieldProjection
                              headG tm1 t mn0
                              >>= \case
                                Just projected -> pure projected
                                Nothing -> methodSugar tm1 t mn0
                _ ->
                  hiddenConstructorFieldProjection headG tm1 t mn0 >>= \case
                    Just projected -> pure projected
                    Nothing -> methodSugar tm1 t mn0
        _ -> methodSugar tm1 t mn0

    -- method-call sugar (§7.4): recv.name args → name recv (receiver
    -- insertion at the first explicit binder).
    methodSugar recvTm recvTy mn0 = do
      mg <- lookupGlobalName (nameText mn0)
      case mg of
        Just g -> do
          st <- get
          mt <- globalTerm g
          case (Map.lookup g (csProjections st), mt) of
            -- receiver-projection sugar (§7.4): the receiver place
            -- supplies the unique place binder
            (Just pj, Just (dTm, dTy))
              | [pn] <- pjPlaceNames pj
              , pjIsPlace pj == [True] ->
                  applyDescriptor ctx (nameSpanOf member) dTm dTy (RootsSeparate [(pn, e)])
            (_, Just (fTm, fTy)) -> case Map.lookup g (csReceivers st) of
              -- §7.4: eligibility requires exactly one explicit
              -- receiver-marked binder; the receiver is inserted at it
              Just [i] -> applyRecvAt i fTm fTy recvTm recvTy
              Just _ -> do
                errAt (nameSpanOf member) "E_UNRESOLVED_MEMBER" (Just "kappa.name.unresolved")
                  ("'" <> nameText mn0
                     <> "' does not have exactly one receiver-marked binder, so it is not eligible for method-call sugar (§7.4)")
                anyHole ctx
              -- §7.4: a callable without a receiver-marked binder is
              -- not eligible for method-call sugar
              Nothing -> do
                errAt (nameSpanOf member) "E_UNRESOLVED_MEMBER" (Just "kappa.name.unresolved")
                  ("'" <> nameText mn0
                     <> "' has no receiver-marked binder, so it is not eligible for method-call sugar (§7.4)")
                anyHole ctx
            (_, Nothing) -> failMember recvTy mn0
        Nothing -> failMember recvTy mn0

    -- receiver insertion at the receiver-marked explicit binder
    -- (§7.4): preceding explicit binders become wrapper-lambda
    -- parameters filled by the remaining call-site arguments
    applyRecvAt recvIdx fTm0 fTy0 recvTm0 recvTy = go ctx (0 :: Int) fTm0 fTy0
      where
        go c depth accTm ty0 = do
          ty <- forceM ty0
          case ty of
            VPi Impl q _ _ dom clo -> do
              iTm <- resolveImplicitQ c (nameSpanOf member) q dom
              iV <- evalIn c iTm
              ty' <- clApp clo iV
              go c depth (CApp Impl accTm iTm) ty'
            VPi Expl _ _ _ dom clo
              | depth == recvIdx -> do
                  let recvTm = shiftTerm (ctxLen c - ctxLen ctx) 0 recvTm0
                  expectType c (exprSpan e) recvTy dom
                  rV <- evalIn c recvTm
                  ty' <- clApp clo rV
                  pure (CApp Expl accTm recvTm, ty')
            VPiBoundFormedM mode formation Expl q _ nm _ dom clo -> do
              let c' = bindCtxQ q nm False dom c
              cod <- clApp clo (VRigid (ctxLen c) [])
              (body, bodyTy) <- go c' (depth + 1) (CApp Expl (shiftTerm 1 0 accTm) (CVar 0)) cod
              domTm <- quoteIn c dom
              bodyTyTm <- quoteIn c' bodyTy
              piV <- evalIn c (CPiFormedM mode formation Expl q False nm domTm bodyTyTm)
              pure (CLamM mode Expl q nm body, piV)
            _ -> do
              errAt (nameSpanOf member) "E_APPLICATION_NONCALLABLE" (Just "kappa-hs.application.non-callable")
                "member is not callable with a receiver"
              anyHole ctx

    failMember recvTy mn0 = do
      recvF <- forceM recvTy
      case recvF of
        -- an unsolved flex receiver type usually means the receiver
        -- itself did not elaborate (e.g. an unresolved name); a member
        -- error on '?m' would be cascade noise (§3.1.14 recovery
        -- hygiene) — but only when the receiver actually reported
        VFlex {} -> do
          ds <- gets csDiags
          let recvSp = exprSpan e
              within dd =
                spanFile (dPrimary dd) == spanFile recvSp
                  && spanStart (dPrimary dd) >= spanStart recvSp
                  && spanEnd (dPrimary dd) <= spanEnd recvSp
          unless (any (\dd -> isError dd && within dd) ds) $
            report $
              diag SevError StageElaborate "E_UNRESOLVED_MEMBER" (Just "kappa.name.unresolved")
                (nameSpanOf member)
                ("no member '" <> nameText mn0 <> "' is known on this receiver (its type is undetermined, §7.3)")
        _ -> do
          rT <- quoteIn ctx recvF
          report $
            withNote ("receiver type: " <> renderTerm rT) $
              diag SevError StageElaborate "E_UNRESOLVED_MEMBER" (Just "kappa.name.unresolved")
                (nameSpanOf member)
                ("no member '" <> nameText mn0 <> "' on this receiver (§7.3)")
      anyHole ctx

    -- which constructors a field projection may assume (§10.2 single
    -- constructor, or the §7.4.1 flow-refined subset for a refined
    -- variable receiver)
    projectableCtors c di
      | [ctorG] <- diCtors di = [ctorG]
      | EVar n <- e
      , Just gs <- ctxRefinementOf c (nameText n)
      , not (null gs)
      , all (`elem` diCtors di) gs =
          gs
      | otherwise = []

    -- Named erased constructor fields remain part of typed KCore even though
    -- source patterns and KBackendIR expose only the runtime payload view.
    -- Project them directly from the complete checked constructor spine. The
    -- source-field table excludes family parameters and generated evidence,
    -- so a same-spelled interface binder cannot be mistaken for a field.
    hiddenConstructorFieldProjection dataHead receiverTerm receiverType fieldName = do
      state <- get
      case Map.lookup dataHead (csDatas state) of
        Just dataInfo
          | constructors <- projectableCtors ctx dataInfo
          , not (null constructors)
          , all (declaresHiddenField state) constructors -> do
              nominalConstructorSourceFieldProjection
                ctx
                receiverTerm
                receiverType
                constructors
                (nameText fieldName)
                (nameSpan fieldName)
                >>= \case
                  Just (projected, _, Impl, Q0, fieldType) ->
                    pure (Just (projected, fieldType))
                  _ -> pure Nothing
        _ -> pure Nothing
      where
        declaresHiddenField state constructor =
          case Map.lookup constructor (csCtors state) of
            Just info ->
              (Impl, Just (nameText fieldName)) `elem` ciSourceFields info
            Nothing -> False

    nameSpanOf = \case
      DotName n -> nameSpan n
      DotOperator n -> nameSpan n

memberTypeOf
  :: Ctx
  -> Span
  -> Int
  -> GName
  -> Text
  -> Term
  -> Value
  -> Term
  -> CheckM (Term, Value)
memberTypeOf ctx site parameterCount traitG member dictTm dictionaryType projected = do
  dictionaryHead <- forceM dictionaryType
  state <- get
  case dictionaryHead of
    VGlobI actualTrait traitUniverses spine
      | actualTrait == traitG
      , Just arguments <- traitSemanticSpineIn state traitG spine
      , length arguments == parameterCount -> do
          -- A generated member accessor has the owning trait's declaration
          -- universes as its leading schema prefix. Select that exact prefix
          -- from the checked receiver and freshen only the member-local
          -- suffix. The evaluator and backend use the same prefix rule via
          -- 'specializeGlobalDefinitionTypePrefix'.
          mt <-
            globalTermWithUniversePrefix
              ctx
              site
              (memberGlobal traitG member)
              traitUniverses
          case mt of
            Just (memberTerm, ty) -> do
              let args = map snd arguments
              argumentTerms <- mapM (quoteIn ctx) args
              argumentTypes <-
                traitParameterClassifiers ctx site traitG traitUniverses arguments
              case argumentTypes of
                Nothing -> malformed
                  ("trait member '" <> member <> "' has an argument without a checked classifier")
                Just classifiers ->
                  -- Preserve the receiver's exact hidden-universe
                  -- instantiation. Reconstructing the trait head here would
                  -- freshen a distinct schema and let the accessor drift away
                  -- from the dictionary it projects.
                  applyGeneratedCoreSpine
                    ctx
                    site
                    memberTerm
                    ty
                    ( [ (Impl, term, classifier)
                      | (term, classifier) <- zip argumentTerms classifiers
                      ]
                        ++ [(Impl, dictTm, dictionaryHead)]
                    )
            Nothing -> pure (projected, VSort LZero)
    _ -> malformed
      ("trait member '" <> member <> "' received a dictionary with a mismatched trait classifier")
  where
    malformed message = do
      errAt site "E_TRAIT_MEMBER_TELESCOPE_MISMATCH" (Just "kappa.internal.compiler") message
      pure (projected, VSort LZero)

-- | Recover a trait application's semantic parameter classifiers from the
-- owning trait declaration itself. Re-inferring them from argument values is
-- incomplete for higher-kinded aliases and stuck type formers; the checked
-- Pi telescope is the authoritative classifier and is already specialized by
-- the receiver's exact universe prefix.
traitParameterClassifiers
  :: Ctx
  -> Span
  -> GName
  -> [Level]
  -> [(Icit, Value)]
  -> CheckM (Maybe [Value])
traitParameterClassifiers ctx site trait universes arguments = do
  state <- get
  let definition = Map.lookup trait (csGlobals state)
  case definition of
    Nothing -> pure Nothing
    Just global -> do
      let parameterCount = dutParameterCount (gdUniverses global)
          proofCount =
            length
              ( declarationUniverseConstraints
                  parameterCount
                  (globalCoreType (ecOf state) global)
              )
      (_, specializedType) <- specializeGlobalAt ctx trait global universes
      peelProofs proofCount ctx specializedType >>= \case
        Nothing -> pure Nothing
        Just (activeCtx, semanticType) ->
          peelArguments activeCtx semanticType arguments
  where
    peelProofs 0 activeCtx ty = pure (Just (activeCtx, ty))
    peelProofs remaining activeCtx ty = do
      forced <- forceM ty
      case forced of
        VPiBoundM _ Impl quantity _ _ assumption domain closure -> do
          proof <- resolveImplicitQ activeCtx site quantity domain
          proofValue <- checkedArgumentValue activeCtx site domain proof
          codomain <- clApp closure proofValue
          nextCtx <- extendLevelAssumption site activeCtx assumption
          peelProofs (remaining - 1) nextCtx codomain
        _ -> pure Nothing

    peelArguments _ _ [] = pure (Just [])
    peelArguments activeCtx ty ((actualIcit, argument) : rest) = do
      forced <- forceM ty
      case forced of
        VPiBoundM _ expectedIcit _ _ _ assumption domain closure
          | actualIcit == expectedIcit -> do
              codomain <- clApp closure argument
              nextCtx <- extendLevelAssumption site activeCtx assumption
              fmap (domain :) <$> peelArguments nextCtx codomain rest
        _ -> pure Nothing

-- | Instantiate a trait member's checked projection telescope while a
-- dictionary is still being assembled.  Unlike 'memberTypeOf', this boundary
-- does not require every semantic trait argument to have a reifiable equand
-- classifier: provisional universe/TypeLevel arguments may legitimately lack
-- one until declaration closeout.  Generated declaration constraints are
-- discharged by provenance, semantic parameters are applied in order, and the
-- final dictionary binder receives exactly the preceding checked fields.
instantiateTraitMemberType
  :: Ctx
  -> Span
  -> GName
  -> [Level]
  -> Text
  -> [Value]
  -> [(Text, Term)]
  -> CheckM Value
instantiateTraitMemberType ctx site trait traitUniverses member arguments doneFields = do
  globalTermWithUniversePrefix
    ctx
    site
    (memberGlobal trait member)
    traitUniverses >>= \case
      Nothing -> pure (VSort LZero)
      Just (_, projectionType) -> peelGenerated ctx projectionType arguments
  where
    peelGenerated activeCtx ty remaining = do
      forced <- forceM ty
      case forced of
        VPiBoundM _ Impl quantity _ _ assumption@(Just _) domain closure -> do
          proof <- resolveImplicitQ activeCtx site quantity domain
          proofValue <- checkedArgumentValue activeCtx site domain proof
          codomain <- clApp closure proofValue
          nextCtx <- extendLevelAssumption site activeCtx assumption
          peelGenerated nextCtx codomain remaining
        _ -> peelSemantic activeCtx forced remaining

    peelSemantic _ ty [] =
      case ty of
        VPi Impl _ _ _ _ closure -> do
          fields <-
            forM doneFields $ \(field, term) ->
              (,) field <$> evalIn ctx term
          clApp closure (VRecordV (sortOn fst fields))
        _ -> pure ty
    peelSemantic activeCtx ty (argument : rest) =
      case ty of
        VPi Impl _ _ _ _ closure -> do
          codomain <- clApp closure argument
          peelGenerated activeCtx codomain rest
        _ -> pure ty

-- | Specialize a declaration at an authenticated leading universe prefix.
-- Trait-member accessors are the primary user: their owning trait occurrence
-- fixes the prefix, while levels introduced by the member signature remain
-- independently polymorphic at each projection.
globalTermWithUniversePrefix
  :: Ctx
  -> Span
  -> GName
  -> [Level]
  -> CheckM (Maybe (Term, Value))
globalTermWithUniversePrefix ctx site global prefix = do
  definition <- gets (Map.lookup global . csGlobals)
  case definition of
    Nothing -> pure Nothing
    Just gd -> do
      let total = dutParameterCount (gdUniverses gd)
      state <- get
      let finalized =
            global `Set.member` csFinalizedUniverseInterfaces state
          hasProvisionalLevels =
            not . null . levelMetasOfTerm $
              zonkLevels
                (csLevelAssignments state)
                (globalCoreType (ecOf state) gd)
      if not finalized || hasProvisionalLevels
        then instantiateProvisionalMember gd
        else if length prefix > total
        then do
          errAt site "E_TRAIT_MEMBER_TELESCOPE_MISMATCH" (Just "kappa.internal.compiler")
            ( "trait-member declaration '" <> gnameText global
                <> "' has " <> T.pack (show total)
                <> " universe parameters, fewer than its owning trait occurrence's "
                <> T.pack (show (length prefix))
                <> "-parameter prefix"
            )
          pure Nothing
        else do
          suffix <- replicateM (total - length prefix) freshLevelInstantiationMeta
          let universes = prefix ++ suffix
          recordRecursiveSchemaOccurrence (Just ctx) False site global universes
          Just <$> specializeGlobalAt ctx global gd universes
  where
    instantiateProvisionalMember definition = do
      state <- get
      let assignments = csLevelAssignments state
          unspecializedType =
            zonkLevels assignments (globalCoreType (ecOf state) definition)
          unspecializedInterfaceTerms =
            map
              (zonkLevels assignments)
              (globalUniverseInterfaceTerms state global definition)
          publishedCount = dutParameterCount (gdUniverses definition)
      if publishedCount > 0
        then
          if length prefix > publishedCount
            then malformed publishedCount
            else do
              publishedSuffix <-
                replicateM (publishedCount - length prefix) freshLevelInstantiationMeta
              let publishedUniverses = prefix ++ publishedSuffix
                  specializePublished =
                    zonkTermWith
                      (\_ _ -> Nothing)
                      (substituteLevelParams publishedUniverses)
                      0
                  rawType = specializePublished unspecializedType
                  rawInterfaceTerms =
                    map specializePublished unspecializedInterfaceTerms
                  sourceMetas =
                    nub (concatMap levelMetasOfTerm rawInterfaceTerms)
              closeProvisionalOccurrence
                sourceMetas
                Map.empty
                publishedUniverses
                rawType
        else do
          let rawType = unspecializedType
              rawInterfaceTerms = unspecializedInterfaceTerms
              sourceMetas =
                nub (concatMap levelMetasOfTerm rawInterfaceTerms)
              ownerMetas =
                traitMemberOwnerUniverseMetas state global rawType
          if length ownerMetas /= length prefix
            then malformed (length ownerMetas)
            else
              closeProvisionalOccurrence
                sourceMetas
                (Map.fromList (zip ownerMetas prefix))
                prefix
                rawType
      where
        malformed found = do
          errAt site "E_TRAIT_MEMBER_TELESCOPE_MISMATCH" (Just "kappa.internal.compiler")
            ( "provisional trait-member declaration '" <> gnameText global
                <> "' exposes " <> T.pack (show found)
                <> " owning-trait universe positions, but the checked receiver has "
                <> T.pack (show (length prefix))
            )
          pure Nothing

        closeProvisionalOccurrence sourceMetas pinned headUniverses rawType = do
          registerProvisionalGlobalUniverseMetas global sourceMetas
          active <- gets csActiveUniverseDefinition
          baseline <- get
          (_, specializedType0) <-
            if active == Just global
              then do
                let selected =
                      [ Map.findWithDefault (LMeta meta) meta pinned
                      | meta <- sourceMetas
                      ]
                    substitution =
                      Map.fromList (zip sourceMetas selected)
                pure
                  ( selected
                  , zonkTermWith
                      (\_ _ -> Nothing)
                      (substituteLevelMetas substitution)
                      0
                      rawType
                  )
              else
                instantiateProvisionalUniversesWith
                  ProvisionalGlobalFacet
                  global
                  sourceMetas
                  pinned
                  rawType
          specializedType <-
            if active == Just global
              then pure (Just specializedType0)
              else do
                materializeProvisionalUniverseConstraintsFor (Set.singleton global)
                current <- get
                let newlyFresh =
                      Set.difference
                        (csLevelInstantiationMetas current)
                        (csLevelInstantiationMetas baseline)
                    baselineOccurrences =
                      Set.fromList
                        (map puiIdentity (csProvisionalUniverseInstantiations baseline))
                    localOccurrences =
                      Set.difference
                        ( Set.fromList
                            (map puiIdentity (csProvisionalUniverseInstantiations current))
                        )
                        baselineOccurrences
                principalizeLevelOccurrence
                  0
                  baseline
                  newlyFresh
                  specializedType0 >>= \case
                    Just (principal, closedType) -> do
                      installLevelAssignments principal
                      retireProvisionalUniverseOccurrences localOccurrences
                      pure (Just closedType)
                    Nothing -> do
                      errAt
                        site
                        "E_UNIVERSE_NO_PRINCIPAL_SOLUTION"
                        (Just "kappa.universe.no-principal-solution")
                        ( "the provisional universe occurrence of trait member '"
                            <> gnameText global
                            <> "' has no principal specialization"
                        )
                      pure Nothing
          case specializedType of
            Nothing -> pure Nothing
            Just closedType -> do
              recordRecursiveSchemaOccurrence
                (Just ctx)
                False
                site
                global
                headUniverses
              ty <- evalIn emptyCtx closedType
              pure (Just (CGlobI global headUniverses, ty))

-- | Apply compiler-generated Core arguments through a checked member
-- telescope. Generated universe proofs are synthesized in declaration order,
-- but may remain pending until later supplied arguments constrain their level
-- metas. Every supplied term is checked against the evolving domain; direct
-- CApp construction would bypass exactly that dependency.
applyGeneratedCoreSpine
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> [(Icit, Term, Value)]
  -> CheckM (Term, Value)
applyGeneratedCoreSpine initialCtx site = go initialCtx
  where
    go activeCtx term ty arguments = do
      forced <- forceM ty
      case (forced, arguments) of
        (VPiBoundM _ Impl q _ _ assumption@(Just _) domain closure, _) -> do
          proof <- resolveImplicitQ activeCtx site q domain
          proofValue <- checkedArgumentValue activeCtx site domain proof
          resultType <- clApp closure proofValue
          nextCtx <- extendLevelAssumption site activeCtx assumption
          go nextCtx (CApp Impl term proof) resultType arguments
        (_, []) -> pure (term, forced)
        (VPiBoundM _ expectedIcit _ _ _ assumption domain closure, (actualIcit, argument, actualType) : rest)
          | actualIcit == expectedIcit -> do
              kindLike <- isKindLike (ctxLen activeCtx) domain
              argument' <- coerceTerm activeCtx site argument actualType domain
              argumentValue <- checkedArgumentValue activeCtx site domain argument'
              resultType <- clApp closure argumentValue
              nextCtx <- extendLevelAssumption site activeCtx assumption
              result <- go nextCtx (CApp actualIcit term argument') resultType rest
              when kindLike (validateInferredKindArgument activeCtx site argument' domain)
              pure result
        (VPiBoundM _ Impl q _ _ assumption domain closure, arguments') -> do
          implicit <- resolveImplicitQ activeCtx site q domain
          implicitValue <- checkedArgumentValue activeCtx site domain implicit
          resultType <- clApp closure implicitValue
          nextCtx <- extendLevelAssumption site activeCtx assumption
          go nextCtx (CApp Impl term implicit) resultType arguments'
        _ -> do
          errAt site "E_INTERNAL_GENERATED_APPLICATION" Nothing
            "compiler-generated trait-member application does not match its checked telescope"
          anyHole activeCtx

typeArgumentClassifier :: Ctx -> Span -> Value -> Value -> CheckM Value
typeArgumentClassifier ctx site carrier value = do
  value' <- forceM value
  fromCreationSite <- case value' of
    VFlex meta [] -> do
      classifier <- gets (Map.lookup meta . csMetaClassifiers)
      case classifier of
        Just info -> traverse (evalIn ctx) (metaClassifierTermInContext ctx info)
        _ -> pure Nothing
    _ -> pure Nothing
  case fromCreationSite of
    Just classifier -> forceM classifier
    Nothing ->
      typeValueClassifierLevel ctx value' >>= \case
        Just level -> pure (VSort level)
        Nothing -> carrierArgumentClassifier ctx site carrier value'

-- | Transport a metavariable's checked creation-site classifier through a
-- lexical context extension. Context entries are de Bruijn binders prepended
-- after the metavariable was created, so weakening by the exact depth delta
-- preserves every reference to the original context. A shallower or
-- unrelated context has no such transport and fails closed.
metaClassifierTermInContext :: Ctx -> MetaClassifier -> Maybe Term
metaClassifierTermInContext ctx classifier = do
  let creationDepth = micDepth classifier
      currentDepth = ctxLen ctx
  guard (creationDepth <= currentDepth)
  pure (shiftTerm (currentDepth - creationDepth) 0 (micType classifier))

-- | Recover the source type argument whose cumulative image inhabits a
-- carrier's input universe. Generalized Applicative/Monad members quantify
-- over that source type and insert the lift themselves; passing the already
-- lifted carrier argument would apply the modality twice and leave malformed
-- Core once the member's universe telescope is principalized.
--
-- The inverse is used only for an explicit proof-carrying 'VUniverseLift' at
-- this typed carrier-argument boundary. The reconstructed member application
-- is subsequently checked against the exact expected action type, which is
-- the authoritative target-domain validation even while level metas remain
-- unsolved here. All other values are already source arguments and remain
-- unchanged.
carrierSourceArgument :: Ctx -> Span -> Value -> Value -> CheckM Value
carrierSourceArgument _ctx _site _carrier argument = do
  exposed <- exposeSolvedMetas 64 Set.empty argument
  case exposed of
    VUniverseLift _ _ _ source -> pure source
    _ -> pure exposed
  where
    -- Ordinary forcing deliberately erases cumulative lifts for conversion.
    -- Here the lift is the information being inverted, so dereference solved
    -- term metas without crossing any other semantic constructor.
    exposeSolvedMetas fuel seen value
      | fuel <= (0 :: Int) = pure value
      | otherwise =
          case value of
            VFlex meta spine
              | meta `Set.notMember` seen -> do
                  solution <- gets (Map.lookup meta . csMetas)
                  case solution of
                    Just (Just solved) -> do
                      context <- ec_
                      exposeSolvedMetas
                        (fuel - 1)
                        (Set.insert meta seen)
                        (evalApp context solved spine)
                    _ -> pure value
            _ -> pure value

carrierArgumentClassifier :: Ctx -> Span -> Value -> Value -> CheckM Value
carrierArgumentClassifier ctx site carrier sourceType =
  equandType ctx carrier >>= traverse forceM >>= \case
    Just (VPiBoundM _ _ _ _ _ _ domain _) -> pure domain
    _ -> do
      carrierTerm <- tryQuoteIn ctx carrier
      sourceTerm <- tryQuoteIn ctx sourceType
      report $
        maybe id (withNote . ("source type: " <>) . renderTerm) sourceTerm $
          maybe id (withNote . ("carrier: " <>) . renderTerm) carrierTerm $
            diag SevError StageElaborate "E_INTERNAL_GENERATED_APPLICATION" Nothing site
              "compiler-generated monadic application has no checked carrier argument domain"
      freshMetaV ctx

memberGlobal :: GName -> Text -> GName
memberGlobal (GName m t) member = GName m (t <> "." <> member)

-- | Resolve @Trait.Member@ only when both source components identify an
-- associated static member of that exact trait. The returned head is the
-- generated member global, whose checked telescope remains responsible for
-- trait arguments, evidence selection, and universe constraints.
traitStaticMemberHead :: Name -> Name -> CheckM (Maybe (Int, Term, Value))
traitStaticMemberHead traitName memberName = do
  resolvedTrait <- lookupGlobalName (nameText traitName)
  state <- get
  case resolvedTrait >>= \trait -> (trait,) <$> Map.lookup trait (csTraits state) of
    Just (trait, info)
      | nameText memberName `Set.member` tiAssociatedStaticMembers info ->
          fmap
            (fmap (\(memberTerm, memberType) -> (tiParamCount info, memberTerm, memberType)))
            (globalTerm (memberGlobal trait (nameText memberName)))
    _ -> pure Nothing

-- | @Trait.Member p1 ... pn rest@ is the source-level associated-family
-- spelling used by the standard range/refinement interfaces. The generated
-- accessor ABI keeps the trait parameters implicit so ordinary evidence
-- projections remain ergonomic. Reclassify exactly that checked trait prefix;
-- the normal spine then resolves the dictionary and applies any residual
-- arguments to the projected compile-time member. This is keyed by resolved
-- trait/member metadata, never by a member spelling.
associatedStaticMemberArgs :: Int -> [Arg] -> [Arg]
associatedStaticMemberArgs traitArity =
  zipWith reclassify [0 :: Int ..]
  where
    reclassify index argument
      | index < traitArity =
          case argument of
            ArgExplicit expression -> ArgImplicit expression
            _ -> argument
      | otherwise = argument

-- | Project a compiler-selected trait member through the same checked member
-- telescope used by source dot projection. This keeps generated desugarings
-- from bypassing declaration-universe proof insertion.
knownTraitMemberProjection
  :: Ctx
  -> Span
  -> GName
  -> Text
  -> Value
  -> Term
  -> CheckM (Term, Value)
knownTraitMemberProjection ctx site trait member dictionaryType dictionary = do
  traits <- gets csTraits
  case Map.lookup trait traits of
    Just info
      | member `elem` tiMembers info -> do
          let mode = Map.findWithDefault Ordinary member (tiMemberModes info)
              projected = CProjM mode dictionary member
          memberTypeOf
            ctx
            site
            (tiParamCount info)
            trait
            member
            dictionary
            dictionaryType
            projected
    _ -> do
      errAt site "E_INTERNAL_MISSING_PRELUDE_DECLARATION" Nothing
        ("selected trait '" <> gnameText trait <> "' has no member '" <> member <> "'")
      anyHole ctx

-- §14.2.1 / §14.1.4: project a member that a trait INHERITS from a
-- (transitive) supertrait. Given evidence 'evTm' of trait 'headG' applied
-- to 'spineArgs' whose own 'tiMembers' lack 'member', search the trait's
-- supertrait premises ('tiSupers') for one whose dictionary carries
-- 'member' (directly or further up the chain) and build the projection
-- chain through the '__superN' evidence fields. Depth-bounded to match
-- 'supertraitProject'. Returns the
-- projection term and the member's instantiated type.
supertraitMemberProject ::
  Ctx -> Int -> GName -> [Level] -> [Value] -> Term -> Text -> CheckM (Maybe (Term, Value))
supertraitMemberProject _ 0 _ _ _ _ _ = pure Nothing
supertraitMemberProject ctx depth headG headUniverses spineArgs evTm member = do
  st <- get
  case Map.lookup headG (csTraits st) of
    Nothing -> pure Nothing
    Just ti -> anyPath (tiSupers ti)
      where
        anyPath [] = pure Nothing
        anyPath ((fn, supClosed) : rest) = do
          ec <- ec_
          specializedSuper <- specializeDeclarationComponent headG headUniverses supClosed
          supF <- evalIn ctx specializedSuper
          supV <- forceM (evalApp ec supF [(Expl, a) | a <- spineArgs])
          case supV of
            VGlobI supG supUniverses supSpine -> do
              current <- get
              let evTm' = CProjM Ordinary evTm fn
              case (Map.lookup supG (csTraits current), traitSemanticSpineIn current supG supSpine) of
                (Just sti, Just supArguments)
                  | member `elem` tiMembers sti -> do
                      let projected = CProjM (Map.findWithDefault Ordinary member (tiMemberModes sti)) evTm' member
                      hit <-
                        memberTypeOf
                          ctx
                          noSpan
                          (tiParamCount sti)
                          supG
                          member
                          evTm'
                          supV
                          projected
                      pure (Just hit)
                (Just _, Just supArguments) -> do
                  let supArgs = map snd supArguments
                  found <-
                    supertraitMemberProject
                      ctx
                      (depth - 1)
                      supG
                      supUniverses
                      supArgs
                      evTm'
                      member
                  case found of
                    Just hit -> pure (Just hit)
                    Nothing -> anyPath rest
                _ -> anyPath rest
            _ -> anyPath rest

-- Elvis `l ?: r` (§16.1.2): unwrap an Option left operand, with the
-- right operand as the None fallback.
elabElvis :: Ctx -> Expr -> Expr -> Span -> CheckM (Term, Value)
elabElvis ctx l r sp = do
  (lTm, lTy) <- infer ctx l
  (lTm1, lTy1) <- insertAllImplicits ctx (exprSpan l) lTm lTy
  t <- forceM lTy1
  case t of
    VGlobI g optionUniverses [(_, payloadTy)]
      | g == prelOption -> do
      rTm <- check ctx r payloadTy
      let alts =
            [ CaseAlt (CPCtorM [] [] [] prelSome optionUniverses [CPVarM Ordinary "__elvis"]) Nothing (CVar 0)
            , CaseAlt (CPCtorM [] [] [] prelNone optionUniverses []) Nothing rTm
            ]
      sTyTm <- quoteIn ctx t
      payloadTyTm <- quoteIn ctx payloadTy
      pure (CMatch lTm1 (Just sTyTm) (Just payloadTyTm) alts, payloadTy)
    _ -> do
      lT <- quoteIn ctx t
      report $
        withNote ("left operand type: " <> renderTerm lT) $
          diag SevError StageElaborate "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch") sp
            "the left operand of the Elvis operator '?:' must have type Option T (§16.1.2)"
      _ <- check ctx r t
      pure (lTm1, t)

-- safe navigation e?.m (§16.1.1.2)
elabSafeNav :: Ctx -> Expr -> DotMember -> CheckM (Term, Value)
elabSafeNav ctx e member = do
  (pTm, pTy) <- infer ctx e
  (pTm1, pTy1) <- insertAllImplicits ctx (exprSpan e) pTm pTy
  t <- forceM pTy1
  case t of
    VGlobI g optionUniverses [(_, payloadTy)]
      | g == prelOption -> do
      -- bind __x : payload, elaborate body member access
      let nm = "__nav"
          ctx' = bindCtx nm False payloadTy ctx
      (bodyTm, bodyTy) <- elabDot ctx' (EVar (Name nm (memberSpan member))) member
      bodyT <- forceM bodyTy
      (unwrappedTm, resTy, needsWrap) <- case bodyT of
        VGlobN g [(_, u)] | g == prelOption -> pure (bodyTm, u, False)
        VFlex {} -> do
          errAt (memberSpan member) "E_SAFE_NAVIGATION_AMBIGUOUS" (Just "kappa.type.mismatch")
            "the result type of '?.' is undetermined; annotate the member type (§16.1.1.2)"
          pure (bodyTm, bodyT, False)
        u -> pure (bodyTm, u, True)
      optionT <- globalValueM prelOption [(Expl, resTy)]
      wrapTm <-
        if needsWrap
          then generatedCtorApplyAtM ctx optionT prelSome [unwrappedTm]
          else pure unwrappedTm
      noneTerm <- generatedCtorAtM ctx optionT prelNone
      let alts =
            [ CaseAlt (CPCtorM [] [] [] prelSome optionUniverses [CPVarM Ordinary "__nav"]) Nothing wrapTm
            , CaseAlt (CPCtorM [] [] [] prelNone optionUniverses []) Nothing noneTerm
            ]
      sTyTm <- quoteIn ctx t
      optionTyTm <- quoteIn ctx optionT
      pure (CMatch pTm1 (Just sTyTm) (Just optionTyTm) alts, optionT)
    VFlex {} -> do
      errAt (exprSpan e) "E_SAFE_NAVIGATION_AMBIGUOUS" (Just "kappa.type.mismatch")
        "the receiver type of '?.' is undetermined here, so the navigation is ambiguous; annotate the receiver (§16.1.1.2)"
      anyHole ctx
    _ -> do
      errAt (exprSpan e) "E_SAFE_NAVIGATION_RECEIVER_NOT_OPTION" (Just "kappa.type.mismatch")
        "the receiver of '?.' must have type Option T (§16.1.1.2)"
      anyHole ctx
  where
    memberSpan = \case
      DotName n -> nameSpan n
      DotOperator n -> nameSpan n

elabIs :: Ctx -> Expr -> CtorRef -> CheckM (Term, Value)
elabIs ctx e cref = do
  (tm, ty) <- infer ctx e
  (tm1, _) <- insertAllImplicits ctx (exprSpan e) tm ty
  mg <- resolveCtor ctx cref
  case mg of
    Just (g, ci) -> do
      boolT <- globalValueM prelBool []
      trueTm <- generatedCtorAtM ctx boolT prelTrue
      falseTm <- generatedCtorAtM ctx boolT prelFalse
      (universes, _, _, namedBinders, explicitFields) <-
        instantiateConstructorForFields ctx g ci ty noSpan
      patternLayout <-
        syntheticConstructorPatternLayout
          (exprSpan e)
          g
          universes
          ci
          namedBinders
          (replicate (length explicitFields) CPWild)
      let alts =
            [ CaseAlt
                (maybe CPWild scplPattern patternLayout)
                Nothing
                trueTm
            , CaseAlt CPWild Nothing falseTm
            ]
      sTyTm <- quoteIn ctx ty
      boolTyTm <- quoteIn ctx boolT
      pure (CMatch tm1 (Just sTyTm) (Just boolTyTm) alts, boolT)
    Nothing -> anyHole ctx

resolveCtor :: Ctx -> CtorRef -> CheckM (Maybe (GName, CtorInfo))
resolveCtor ctx reference@(CtorRef _ n) = do
  resolved <- resolveCtorWithoutDiagnostic ctx reference
  when (isNothing resolved) $
    errAt (nameSpan n) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
      ("unresolved constructor '" <> nameText n <> "'")
  pure resolved

-- | Resolve a constructor from checked lexical/module identity without
-- committing to a constructor-only diagnostic. Ambiguous @let C p... = rhs@
-- syntax uses this at the checker boundary: absence means the ordinary named
-- function reading, while a result selects the constructor-pattern reading.
resolveCtorWithoutDiagnostic
  :: Ctx
  -> CtorRef
  -> CheckM (Maybe (GName, CtorInfo))
resolveCtorWithoutDiagnostic ctx (CtorRef mqual n) = do
  st <- get
  let candidates = case mqual of
        Nothing ->
          map fst (unqualifiedConstructorCandidates st n)
        Just q ->
          [ ctorG
          | (dg, di) <- Map.toList (csDatas st)
          , sourceNameResolvesTo st dg (nameText q)
          , inScope st dg
          , ctorG <- diCtors di
          , sourceNameResolvesTo st ctorG (nameText n)
          ]
  case candidates of
    (g : _) -> do
      pure ((,) g <$> Map.lookup g (csCtors st))
    [] -> do
      -- §2.8.4/§7.6: a rebound type object preserves its identity for
      -- dotted lookup — the qualifier may be a local or module binding
      -- whose manifest value is a data type constructor
      mDataG <- case mqual of
        Just q -> do
          mv <- case lookupCtx (nameText q) ctx of
            Just (i, _) -> manifestValue ctx (CVar i)
            Nothing -> do
              mg <- lookupGlobalName (nameText q)
              case mg of
                Just g -> manifestValue ctx (CGlob g)
                Nothing -> pure Nothing
          case mv of
            Just (VGlobN dg []) | Map.member dg (csDatas st) -> pure (Just dg)
            _ -> pure Nothing
        Nothing -> pure Nothing
      case mDataG of
        Just dg
          | Just di <- Map.lookup dg (csDatas st)
          , (ctorG : _) <- [c | c <- diCtors di, gnameText c == nameText n] ->
              pure ((,) ctorG <$> Map.lookup ctorG (csCtors st))
        _ -> pure Nothing
  where
    inScope = constructorInScope

selectConstructorPatternLet
  :: Ctx
  -> Span
  -> LetDef
  -> CheckM (Maybe ConstructorPatternCandidate)
selectConstructorPatternLet ctx declarationSpan definition =
  case ldConstructorPatternCandidate definition of
    Just candidate@(ConstructorPatternCandidate pattern' _) ->
      case pattern' of
        PCtor reference _ _ ->
          resolveCtorWithoutDiagnostic ctx reference >>= \case
            Just _ -> do
              modify' $ \state ->
                state
                  { csConstructorPatternLetSpans =
                      Set.insert
                        declarationSpan
                        (csConstructorPatternLetSpans state)
                  }
              pure (Just candidate)
            Nothing -> pure Nothing
        _ -> pure Nothing
    Nothing -> pure Nothing

-- | Resolve an unqualified constructor spelling to checked constructor
-- identities without emitting a diagnostic. Pattern parsing deliberately
-- leaves a bare lowercase atom as 'PVar'; this lookup is the semantic
-- disambiguation boundary that lets ordinary lowercase constructors (notably
-- the standard @refl@) enter the same constructor-pattern path as uppercase
-- constructors. Callers must make decisions from the returned 'GName' and
-- 'CtorInfo', never from the spelling alone.
unqualifiedConstructorCandidates
  :: CheckState
  -> Name
  -> [(GName, CtorInfo)]
unqualifiedConstructorCandidates state name =
  case resolvedIdentity >>= \identity -> (identity,) <$> Map.lookup identity (csCtors state) of
    Just candidate -> [candidate]
    Nothing -> []
  where
    source = nameText name
    own = GName (csModule state) source
    resolvedIdentity =
      Map.lookup source (csLocalDeclScope state)
        <|> (own <$ guard (Map.member own (csGlobals state) || Map.member own (csCtors state)))
        <|> Map.lookup source (csScope state)

sourceNameResolvesTo :: CheckState -> GName -> Text -> Bool
sourceNameResolvesTo state identity source =
  gnameText identity == source
    || Map.lookup source (csLocalDeclScope state) == Just identity

-- record patch (§13.2.5): closed records, '='-updates and ':='-extends.
elabPatch :: Ctx -> Expr -> [PatchItem] -> Span -> CheckM (Term, Value)
elabPatch = elabPatchWith False

-- @nested@ selects the §13.2.5 path diagnostic for unknown fields.
elabPatchWith :: Bool -> Ctx -> Expr -> [PatchItem] -> Span -> CheckM (Term, Value)
elabPatchWith _ ctx e [PatchSection recv rhs] sp = elabSectionUpdate ctx e recv rhs sp
elabPatchWith nested ctx e items sp = do
  (tm, ty) <- infer ctx e
  (tm1, ty1) <- insertAllImplicits ctx (exprSpan e) tm ty
  t <- forceM ty1
  dep <- case t of
    VRecordTQ qfs -> do
      depTy <- recordTypeIsDependent ctx [(rfName field, rfType field) | field <- qfs]
      let depVal =
            isNothing (lookupCtx "this" ctx)
              && not
                (null (concat [surfaceThisRefs v | PatchUpdate _ (PatchValue v) <- items]))
      pure (depTy || depVal)
    _ -> pure False
  case t of
    VRecordTQ qfs | dep -> elabDependentPatch ctx tm1 qfs items sp
    VRecordTQ qfs -> do
      let fs = [(rfName field, rfType field) | field <- qfs]
      let updateNames = [nameText n | PatchUpdate [(False, n)] _ <- items]
          extendNames = [nameText n | PatchExtend n _ <- items]
          -- nested paths (§13.2.5): group by head segment
          nestedHeads =
            foldr (\n acc -> if nameText n `elem` map nameText acc then acc else n : acc) []
              [h | PatchUpdate ((False, h) : _ : _) _ <- items]
      forM_ (duplicatesOf updateNames) $ \n ->
        errAt sp "E_RECORD_PATCH_DUPLICATE_PATH" (Just "kappa-hs.record.patch-duplicate")
          ("record patch updates field '" <> n <> "' more than once (§13.2.5)")
      forM_ (duplicatesOf extendNames) $ \n ->
        errAt sp "E_ROW_EXTENSION_DUPLICATE_LABEL" (Just "kappa-hs.row.extension-duplicate")
          ("row extension introduces label '" <> n <> "' more than once (§13.2.6)")
      forM_ [h | h <- nestedHeads, nameText h `elem` updateNames] $ \h ->
        errAt (nameSpan h) "E_RECORD_PATCH_PREFIX_CONFLICT" (Just "kappa-hs.record.patch-prefix-conflict")
          ("record patch both replaces '" <> nameText h <> "' and updates a path beneath it (§13.2.5)")
      groupUps <- forM nestedHeads $ \h -> do
        let subItems =
              [ PatchUpdate restPath v
              | PatchUpdate ((False, h0) : restPath@(_ : _)) v <- items
              , nameText h0 == nameText h
              ]
        if nameText h `elem` map fst fs
          then do
            (htm, _) <- elabPatchWith True ctx (EDot e (DotName h)) subItems sp
            pure (Just (nameText h, htm, Nothing))
          else do
            errAt (nameSpan h) "E_RECORD_PATCH_UNKNOWN_PATH" (Just "kappa.name.unresolved")
              ("record patch path starts at unknown field '" <> nameText h <> "' (§13.2.5)")
            pure Nothing
      results0 <- forM items $ \case
        PatchUpdate [(False, n)] (PatchValue v) -> do
          case find ((== nameText n) . rfName) qfs of
            Just field -> do
              vt <- checkObservedExpr ctx "ordinary record patch field" (rfMode field) v (rfType field)
              pure (Just (nameText n, vt, Nothing))
            Nothing -> do
              if nested
                then
                  errAt (nameSpan n) "E_RECORD_PATCH_UNKNOWN_PATH" (Just "kappa.name.unresolved")
                    ("record patch path names unknown field '" <> nameText n <> "' (§13.2.5)")
                else
                  errAt (nameSpan n) "E_UNKNOWN_FIELD" (Just "kappa.name.unresolved")
                    ("record has no field '" <> nameText n <> "'")
              pure Nothing
        PatchUpdate ((False, _) : _ : _) _ -> pure Nothing -- grouped above
        PatchUpdate _ _ -> do
          unsupportedAt sp "implicit patch paths are not supported by this implementation"
          pure Nothing
        -- §13.2.6 row extension: the label must be absent; the result
        -- row gains the field
        PatchExtend n v ->
          case find ((== nameText n) . rfName) qfs of
            Just field -> do
              errAt (nameSpan n) "E_ROW_EXTENSION_EXISTING_FIELD" (Just "kappa.row.lacks-failed")
                ("row extension ':=' introduces '" <> nameText n <> "', but the record already has that field (§13.2.6)")
              vt <- checkObservedExpr ctx "ordinary record extension field" (rfMode field) v (rfType field)
              pure (Just (nameText n, vt, Nothing))
            Nothing -> do
              (vt0, vty0) <- infer ctx v
              (vt, vty) <- insertAllImplicits ctx (exprSpan v) vt0 vty0
              pure (Just (nameText n, vt, Just vty))
        PatchSection _ _ -> do
          -- a projection-section item mixed with other patch items
          errAt sp "E_PROJECTION_UPDATE_TARGET_UNSUPPORTED" (Just "kappa-hs.projection.update")
            "a projection-section update must be the only item of its update (§13.2.5, §30.2.2.4)"
          pure Nothing
        -- §13.2.5: record updates do not admit field punning
        PatchPun n -> do
          errAt (nameSpan n) "E_RECORD_PATCH_INVALID_ITEM" (Just "kappa-hs.record.patch-invalid")
            ("a record update item must be written 'field = value'; punning '" <> nameText n <> "' is not admitted (§13.2.5)")
          pure Nothing
      let entries = catMaybes (results0 ++ groupUps)
          ups = [(n, vt) | (n, vt, _) <- entries]
          news =
            foldl
              (\acc p -> if fst p `elem` map fst acc then acc else acc ++ [p])
              []
              [(n, (vt, vty)) | (n, vt, Just vty) <- entries, n `notElem` map fst fs]
          allFields = sortOn rfName (qfs ++ [RecordField n Ordinary FormationOrdinary QW Nothing vty | (n, (_, vty)) <- news])
          fields =
            [ ( n
              , fromMaybe
                  (maybe (CProjM (rfMode field) tm1 n) fst (lookup n news))
                  (lookup n ups)
              )
            | field <- allFields
            , let n = rfName field
            ]
      pure (CRecordV fields, VRecordTQ allFields)
    -- §13.2.6 row extension over an open record (§11.3.1A)
    VGlobN (GName pm "__openRec") [(_, rowV), (_, prefixV)]
      | pm == preludeModule -> do
          pf <- forceM prefixV
          case pf of
            VRecordT fs -> elabOpenPatch ctx tm1 rowV fs items sp
            _ -> do
              errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                "record patch requires a record"
              anyHole ctx
    -- Named single-constructor data values expose their constructor
    -- fields through ordinary projection (§10.2). Treat updates over
    -- those fields as a match-and-rebuild, mirroring a closed-record
    -- update without requiring packages to model every entity as a
    -- core row record.
    VGlobN dataG _ -> elabCtorFieldPatch nested ctx e tm1 ty1 dataG items sp
    _ -> do
      errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch") "record patch requires a closed record"
      anyHole ctx

elabCtorFieldPatch :: Bool -> Ctx -> Expr -> Term -> Value -> GName -> [PatchItem] -> Span -> CheckM (Term, Value)
elabCtorFieldPatch nested ctx e tm1 ty1 dataG items sp = do
  st <- get
  case Map.lookup dataG (csDatas st) of
    Just di | [ctorG] <- diCtors di -> case Map.lookup ctorG (csCtors st) of
      Just ci -> do
        (ctorUniverses, ctorType, constructorArguments, namedBinders, indexedFieldSlots) <-
          instantiateConstructorForFields ctx ctorG ci ty1 sp
        let fieldSlots = [(mode, quantity, fieldType) | (_, mode, quantity, fieldType) <- indexedFieldSlots]
            fieldArgumentIndices = [index | (index, _, _, _) <- indexedFieldSlots]
            fieldTys = map (\(_, _, fieldType) -> fieldType) fieldSlots
        let fieldNames0 = map fst (ciFields ci)
            namedFields =
              [ (n, fty)
              | (Just n, fty) <- zip fieldNames0 fieldTys
              ]
            namedNames = map fst namedFields
        if length namedFields /= length fieldTys || null namedFields
          then notCtorPatchable
          else do
            let updateNames = [nameText n | PatchUpdate [(False, n)] _ <- items]
                nestedHeads =
                  foldr (\n acc -> if nameText n `elem` map nameText acc then acc else n : acc) []
                    [h | PatchUpdate ((False, h) : _ : _) _ <- items]
            forM_ (duplicatesOf updateNames) $ \n ->
              errAt sp "E_RECORD_PATCH_DUPLICATE_PATH" (Just "kappa-hs.record.patch-duplicate")
                ("record patch updates field '" <> n <> "' more than once (§13.2.5)")
            forM_ (duplicatesOf [nameText n | PatchExtend n _ <- items]) $ \n ->
              errAt sp "E_RECORD_PATCH_INVALID_ITEM" (Just "kappa-hs.record.patch-invalid")
                ("constructor-field patch cannot extend field '" <> n <> "'; ':=' is only defined for row records (§13.2.6)")
            forM_ [h | h <- nestedHeads, nameText h `elem` updateNames] $ \h ->
              errAt (nameSpan h) "E_RECORD_PATCH_PREFIX_CONFLICT" (Just "kappa-hs.record.patch-prefix-conflict")
                ("record patch both replaces '" <> nameText h <> "' and updates a path beneath it (§13.2.5)")
            groupUps <- forM nestedHeads $ \h -> do
              let subItems =
                    [ PatchUpdate restPath v
                    | PatchUpdate ((False, h0) : restPath@(_ : _)) v <- items
                    , nameText h0 == nameText h
                    ]
              if nameText h `elem` namedNames
                then do
                  (htm, _) <- elabPatchWith True ctx (EDot e (DotName h)) subItems sp
                  pure (Just (nameText h, htm))
                else do
                  errAt (nameSpan h) "E_RECORD_PATCH_UNKNOWN_PATH" (Just "kappa.name.unresolved")
                    ("record patch path starts at unknown field '" <> nameText h <> "' (§13.2.5)")
                  pure Nothing
            directUps <- forM items $ \case
              PatchUpdate [(False, n)] (PatchValue v) -> do
                case lookup (nameText n) namedFields of
                  Just fty -> do
                    vt <- check ctx v fty
                    pure (Just (nameText n, vt))
                  Nothing -> do
                    if nested
                      then
                        errAt (nameSpan n) "E_RECORD_PATCH_UNKNOWN_PATH" (Just "kappa.name.unresolved")
                          ("record patch path names unknown field '" <> nameText n <> "' (§13.2.5)")
                      else
                        errAt (nameSpan n) "E_UNKNOWN_FIELD" (Just "kappa.name.unresolved")
                          ("constructor has no field '" <> nameText n <> "'")
                    pure Nothing
              PatchUpdate ((False, _) : _ : _) _ -> pure Nothing
              PatchUpdate _ _ -> do
                unsupportedAt sp "implicit patch paths are not supported by this implementation"
                pure Nothing
              PatchExtend n _ -> do
                errAt (nameSpan n) "E_RECORD_PATCH_INVALID_ITEM" (Just "kappa-hs.record.patch-invalid")
                  ("constructor-field patch cannot extend field '" <> nameText n <> "'; ':=' is only defined for row records (§13.2.6)")
                pure Nothing
              PatchSection _ _ -> do
                errAt sp "E_PROJECTION_UPDATE_TARGET_UNSUPPORTED" (Just "kappa-hs.projection.update")
                  "a projection-section update must be the only item of its update (§13.2.5, §30.2.2.4)"
                pure Nothing
              PatchPun n -> do
                errAt (nameSpan n) "E_RECORD_PATCH_INVALID_ITEM" (Just "kappa-hs.record.patch-invalid")
                  ("a record update item must be written 'field = value'; punning '" <> nameText n <> "' is not admitted (§13.2.5)")
                pure Nothing
            let updates = Map.fromList (catMaybes (directUps ++ groupUps))
                pats =
                  [ case mn of
                      Just n -> CPVarM Ordinary ("__patch_" <> n)
                      Nothing -> CPWild
                  | mn <- fieldNames0
                  ]
            patternLayout <-
              syntheticConstructorPatternLayout
                sp
                ctorG
                ctorUniverses
                ci
                namedBinders
                pats
            case patternLayout of
              Nothing -> anyHole ctx
              Just layout -> do
                let binderCount = scplBinderCount layout
                    binderIndices = scplExplicitBinderIndices layout
                    argAt fieldIndex fieldName =
                      case fieldName >>= (`Map.lookup` updates) of
                        Just updated -> shiftTerm binderCount 0 updated
                        Nothing ->
                          case listToMaybe (drop fieldIndex binderIndices) >>= id of
                            Just binderIndex -> CVar binderIndex
                            Nothing ->
                              -- The all-named-field check above guarantees one
                              -- flat binder per explicit source field. Retain a
                              -- well-scoped recovery term after the internal
                              -- diagnostic so no guessed offset reaches codegen.
                              CRecordV []
                    fieldArguments =
                      Map.fromList
                        [ (argumentIndex, argAt fieldIndex fieldName)
                        | (fieldIndex, (fieldName, argumentIndex)) <-
                            zip [0 :: Int ..] (zip fieldNames0 fieldArgumentIndices)
                        ]
                    completeArguments =
                      [ argument
                          { caTerm =
                              Map.findWithDefault
                                (shiftTerm binderCount 0 (caTerm argument))
                                argumentIndex
                                fieldArguments
                          }
                      | (argumentIndex, argument) <- zip [0 :: Int ..] constructorArguments
                      ]
                when (any isNothing binderIndices) $
                  errAt
                    sp
                    "E_INTERNAL_CONSTRUCTOR_TELESCOPE"
                    (Just "kappa.internal.compiler")
                    "constructor patch fields do not each introduce one branch binder"
                sTyTm <- quoteIn ctx ty1
                let rebuilt =
                      CCtorI ctorG ctorUniverses (Just ctorType)
                        completeArguments
                resultTyTm <- quoteIn ctx ty1
                pure
                  ( CMatch tm1 (Just sTyTm) (Just resultTyTm)
                      [CaseAlt (scplPattern layout) Nothing rebuilt]
                  , ty1
                  )
      Nothing -> notCtorPatchable
    _ -> notCtorPatchable
  where
    notCtorPatchable = do
      errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch") "record patch requires a closed record"
      anyHole ctx

-- | Row extension and explicit-prefix update on an open record
-- (§13.2.6, §11.3.1A): 'rec.{ l := v }' requires 'LacksRec r l'
-- evidence in scope and appends the field to the explicit prefix.
elabOpenPatch :: Ctx -> Term -> Value -> [(Text, Value)] -> [PatchItem] -> Span -> CheckM (Term, Value)
elabOpenPatch ctx tm1 rowV fs items sp = do
  results <- forM items $ \case
    PatchExtend n v
      | Just fty <- lookup (nameText n) fs -> do
          errAt (nameSpan n) "E_ROW_EXTENSION_EXISTING_FIELD" (Just "kappa.row.lacks-failed")
            ("row extension ':=' introduces '" <> nameText n <> "', but the record already has that field (§13.2.6)")
          vt <- check ctx v fty
          pure (Just (nameText n, vt, Nothing))
      | otherwise -> do
          -- §13.2.1 uniqueness side condition: the residual row must
          -- be known to lack the new label
          goal <-
            globalValueM prelLacksRec
              [(Expl, rowV), (Expl, VLit (LitStr (nameText n)))]
          saved <- get
          _ <- resolveImplicitQ ctx (nameSpan n) QW goal
          after <- get
          when (length (csDiags after) /= length (csDiags saved)) $ do
            put saved
            errAt (nameSpan n) "E_ROW_EXTENSION_MISSING_LACKS_CONSTRAINT" (Just "kappa.row.lacks-failed")
              ( "extending the open row with '" <> nameText n
                  <> "' requires a 'LacksRec r " <> nameText n <> "' constraint in scope (§13.2.1, §13.2.6)"
              )
          (vt0, vty0) <- infer ctx v
          (vt, vty) <- insertAllImplicits ctx (exprSpan v) vt0 vty0
          pure (Just (nameText n, vt, Just vty))
    PatchUpdate [(_, n)] (PatchValue v)
      | Just fty <- lookup (nameText n) fs -> do
          vt <- check ctx v fty
          pure (Just (nameText n, vt, Nothing))
    _ -> do
      errAt sp "E_RECORD_PATCH_INVALID_ITEM" (Just "kappa-hs.record.patch-invalid")
        "this update item is not supported on an open record (§13.2.5)"
      pure Nothing
  let entries = catMaybes results
      newFields = [(n, vty) | (n, _, Just vty) <- entries]
  prefixTms <- mapM (\(n, v) -> (,) n <$> quoteIn ctx v) (sortOn fst (fs ++ newFields))
  prefixV' <- evalIn ctx (CRecordT prefixTms)
  rowExtendHead <- globalHeadM prelRowExtend
  let tm' =
        foldl
          ( \acc (n, vt, isNew) -> case isNew of
              Just _ ->
                CApp Expl
                  (CApp Expl
                     (CApp Expl rowExtendHead acc)
                     (CLit (LitStr n)))
                  vt
              Nothing -> acc
          )
          tm1
          entries
  openRecT <- globalValueM prelOpenRec [(Expl, rowV), (Expl, prefixV')]
  pure (tm', openRecT)

-- | Projection-section update @lhs.{ (.member args) = rhs }@
-- (§13.2.5, §30.2.2.4): the member must resolve to a stable field, a
-- single-leaf selector projection, or an accessor bundle providing
-- @set@; the update rebuilds the root.
elabSectionUpdate :: Ctx -> Expr -> Expr -> Expr -> Span -> CheckM (Term, Value)
elabSectionUpdate ctx baseE recv rhs sp = case recv of
  EReceiverSection members sArgs _ -> do
    (baseTm, baseTy0) <- infer ctx baseE
    baseTy <- forceM baseTy0
    let mHead = receiverHeadExpr members
    mpj <- case mHead of
      Just headE -> projectionInfoOfExpr ctx headE
      Nothing -> pure Nothing
    case (baseTy, members, mpj) of
      -- a plain stable field: FillPlace, i.e. the ordinary update
      (VRecordT fs, [DotName mn], _)
        | nameText mn `elem` map fst fs, null sArgs ->
            elabPatchWith False ctx baseE [PatchUpdate [(False, mn)] (PatchValue rhs)] sp
      (_, _, Just pj)
        | pjSelector pj ->
            case (sArgs, nub (pjYields pj)) of
              -- unique static leaf: FillProjector equiv nested field update
              ([], [(_, path@(_ : _))]) ->
                case members of
                  [DotName mn] ->
                    elabPatchWith False ctx baseE
                      [PatchUpdate [(False, Name seg (nameSpan mn)) | seg <- path] (PatchValue rhs)] sp
                  _ -> unsupportedTarget (baseTm, baseTy)
              ([], [(_, [])]) -> do
                rhsTm <- check ctx rhs baseTy
                pure (rhsTm, baseTy)
              _ -> unsupportedTarget (baseTm, baseTy)
        | otherwise -> do
            mDesc <- case mHead of
              Just headE -> Just <$> infer ctx headE
              Nothing -> pure Nothing
            case mDesc of
              Nothing -> unsupportedTarget (baseTm, baseTy)
              Just (dTm0, dTy0) -> do
                (dTm1, dTy1) <- elabSpine ctx sp dTm0 dTy0 sArgs
                dTyF <- forceM dTy1
                mcaps <- case dTyF of
                  VRecordT capFs -> bundleCapsM capFs
                  _ -> pure Nothing
                case [(r, f) | ("set", r, f) <- fromMaybe [] mcaps] of
                  ((rootsV, focusV) : _) -> do
                    rootsF <- forceM rootsV
                    case rootsF of
                      VRecordT [(_, sV)] -> expectType ctx (exprSpan baseE) baseTy sV
                      _ -> pure ()
                    rhsTm <- check ctx rhs focusV
                    pure (CApp Expl (CApp Expl (CProjM Ordinary dTm1 "set") baseTm) rhsTm, baseTy)
                  [] -> unsupportedTarget (baseTm, baseTy)
      _ -> unsupportedTarget (baseTm, baseTy)
  _ -> do
    (baseTm, baseTy) <- infer ctx baseE
    unsupportedTarget (baseTm, baseTy)
  where
    receiverHeadExpr = \case
      [] -> Nothing
      DotName n : rest -> Just (foldl (\acc m -> EDot acc m) (EVar n) rest)
      DotOperator {} : _ -> Nothing

    unsupportedTarget (baseTm, baseTy) = do
      errAt sp "E_PROJECTION_UPDATE_TARGET_UNSUPPORTED" (Just "kappa-hs.projection.update")
        "the projection-section update target must resolve to a stable place, a selector projection, or an accessor bundle providing 'set' (§13.2.5, §30.2.2.4)"
      pure (baseTm, baseTy)

-- | §13.2.10 sealed packages: @seal e as S@. The ascribed type must be
-- a closed record type; opaque members of S keep their defining
-- equations hidden behind the resulting package value.
elabSeal :: Ctx -> Expr -> Expr -> Span -> CheckM (Term, Value)
elabSeal ctx e tyE sp = do
  (sTm, _) <- inferType ctx tyE
  sV <- forceM =<< evalIn ctx sTm
  case sV of
    VGlobN (GName pm "__openRec") _
      | pm == preludeModule -> do
          errAt sp "E_SEAL_OPEN_RECORD_ASCRIPTION" (Just "kappa-hs.seal.open-record")
            "the ascribed type of 'seal ... as ...' must be a closed record type; an open record with a residual row is not a sealing signature (§13.2.10)"
          anyHole ctx
    -- §13.2.11 existential introduction: an existential signature is a
    -- §13.2.10 signature whose opaque members are the internal witness
    -- labels. Sealing an ordinary expression against it uses the
    -- existential-specific payload-checking mode (Spec.md 13347-13364).
    VSigT ls inner
      | any isExistsInternalLabel ls ->
          forceM inner >>= \case
            VRecordTQ fs -> elabSeal'Exists ctx e sV ls fs witBinderNames sp
            _ -> notRecord
    VSigT ls inner ->
      forceM inner >>= \case
        VRecordTQ fs -> doSeal ls fs sV
        _ -> notRecord
    VRecordTQ fs -> doSeal [] fs sV
    _ -> notRecord
  where
    -- the surface witness binder names, recoverable only when the
    -- ascription is written directly as 'exists ...' (used to support the
    -- §13.2.11 compatibility full-surface-package spelling, 13417-13428)
    witBinderNames = case tyE of
      EExists bs _ _ -> [maybe "_" nameText (bName b) | b <- bs]
      _ -> []
    notRecord = do
      errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
        "the ascribed type of 'seal ... as ...' must elaborate to a closed record type (§13.2.10)"
      anyHole ctx
    -- record-literal payload: elaborate the retained fields in
    -- dependency order against the signature's field types (§13.2.10
    -- signature matching), inferring the hidden extras
    doSeal ls fs sV
      | ERecordLit items lsp <- e = do
          let supplied = [(nameText n, fromMaybe (EVar n) me) | RecItem _ n me <- items]
          forM_ (duplicatesOf (map fst supplied)) $ \n ->
            errAt lsp "E_RECORD_DUPLICATE_FIELD" (Just "kappa-hs.record.duplicate-field")
              ("record literal has duplicate field '" <> n <> "'")
          let missing = [rfName field | field <- fs, rfName field `notElem` map fst supplied]
          if not (null missing)
            then do
              errAt lsp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                ( "the sealed expression does not provide the signature field(s) "
                    <> T.intercalate ", " (map (\n -> "'" <> n <> "'") missing)
                    <> " (§13.2.10)"
                )
              anyHole ctx
            else do
              annotated <- forM fs $ \field -> do
                let nm = rfName field
                    fty = rfType field
                ftyTm <- quoteIn ctx fty
                let fe = fromMaybe (EVar (Name nm lsp)) (lookup nm supplied)
                    deps =
                      nub (thisDepsOf ftyTm ++ levelFieldDepsOf ftyTm ++ [l | l <- surfaceThisRefs fe, l `elem` map rfName fs])
                pure (nm, deps, (field, fe))
              case topoFields annotated of
                Nothing -> do
                  errAt lsp "E_RECORD_DEPENDENCY_CYCLE" (Just "kappa-hs.record.dependency-cycle")
                    "the sibling references of this record literal form a cycle (§13.2.1)"
                  anyHole ctx
                Just ordered -> do
                  retained <- goLit [] [] ordered
                  -- hidden extras are discarded by the seal (§13.2.10);
                  -- they still elaborate
                  forM_ [fe | (nm, fe) <- supplied, nm `notElem` map rfName fs] $ \fe ->
                    void (withThis Nothing (infer ctx fe))
                  pure (CSealE ls (CRecordV (sortOn fst retained)), sV)
      | otherwise = do
          (eTm0, eTy0) <- infer ctx e
          (eTm, eTy1) <- insertAllImplicits ctx (exprSpan e) eTm0 eTy0
          eTy <- forceM eTy1
          mefs <- case eTy of
            VRecordTQ efs -> pure (Just efs)
            VSigT _ inner ->
              forceM inner >>= \case
                VRecordTQ efs -> pure (Just efs)
                _ -> pure Nothing
            _ -> pure Nothing
          case mefs of
            Nothing -> do
              expectType ctx (exprSpan e) eTy sV
              pure (CSealE ls eTm, sV)
            Just efs -> do
              forM_ fs $ \field -> case find ((== rfName field) . rfName) efs of
                Nothing ->
                  errAt (exprSpan e) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                    ("the sealed expression does not provide the signature field '" <> rfName field <> "' (§13.2.10)")
                Just actualField -> do
                  aty' <- substThisInto ctx eTm (rfType actualField)
                  fty' <- substThisInto ctx eTm (rfType field)
                  expectType ctx (exprSpan e) aty' fty'
              pure (CSealE ls eTm, sV)
    goLit _ _ [] = pure []
    goLit doneV doneT ((field, fe) : rest) = do
      let nm = rfName field
      fty' <- substThisInto ctx (CRecordV (sortOn fst doneV)) (rfType field)
      tm <- withThis (Just (ThisValue doneV doneT)) (check ctx fe fty')
      let field' = field {rfType = fty'}
      ((nm, tm) :) <$> goLit ((nm, tm) : doneV) (field' : doneT) rest

-- | §13.2.11 existential introduction (Spec.md 13347-13364).
--
-- @seal e as exists (a1:S1)...(an:Sn). T@ where the operand is an
-- ordinary expression: create fresh witness metavariables for the
-- hidden witnesses, check the payload against @T@ with those metas
-- substituted for the witness 'this'-references, and solve the witnesses
-- from that checking problem. All witnesses must be solved before the
-- seal is accepted (Spec.md 13363-13364).
--
-- The signature fields are the internal witness labels (opaque) followed
-- by the payload view; a non-record payload is the single internal
-- @⟨payload⟩@ field, while a record-shaped payload exposes its source
-- labels. @witTerms@ supplies the witness terms positionally — fresh
-- metas for the direct form, or the explicitly supplied witnesses for
-- 'ESealExists' (Spec.md 13378-13391).
elabSeal'Exists :: Ctx -> Expr -> Value -> [Text] -> [RecordField Value] -> [Text] -> Span -> CheckM (Term, Value)
elabSeal'Exists ctx e sV witLabels fs witBinderNames sp = do
  -- Witness fields are exactly the opaque members 'witLabels'; the
  -- payload label '⟨payload⟩' is internal but NOT opaque.
  let anonPayload = case payFs of
        [payField] -> rfName payField == existsPayloadLabel
        _ -> False
  -- §13.2.11 compatibility full-surface-package spelling (13417-13428):
  -- when the ascription is a literal 'exists' and the operand is a record
  -- literal mentioning witness binder names, the witness-named fields
  -- supply the witnesses and the rest is the payload. Available only for
  -- record-shaped payloads (13431-13432).
  case e of
    ERecordLit items _
      | not (null witBinderNames)
      , let suppliedNames = [nameText n | RecItem _ n _ <- items]
      , any (`elem` witBinderNames) suppliedNames ->
          if anonPayload
            then do
              errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                "the compatibility record-package spelling of 'seal' is not available for a non-record existential payload; use direct payload introduction or 'seal exists (...) . e as ...' (§13.2.11)"
              anyHole ctx
            else sealCompat items
    _ -> do
      -- direct payload introduction: fresh witness metas, solved by
      -- checking the payload (Spec.md 13352, 13359-13361). Witnesses form a
      -- dependent telescope, so each placeholder is classified at its
      -- substituted domain before later witnesses are introduced.
      witTerms <- freshWitnessTerms [] witFs
      elabSealExistsCore ctx e sV witLabels fs sp witTerms
  where
    witFs = filter ((`elem` witLabels) . rfName) fs
    payFs = filter ((`notElem` witLabels) . rfName) fs
    -- the record-literal compatibility spelling: bind witness-named
    -- fields as explicit witnesses (positionally, by binder order), then
    -- check the remaining payload fields
    sealCompat items = do
      let supplied = [(nameText n, fromMaybe (EVar n) me) | RecItem _ n me <- items]
          -- explicit witness assignments in binder order
          witWs =
            [ (Name bn sp, we)
            | (bn, _) <- zip witBinderNames witFs
            , Just we <- [lookup bn supplied]
            ]
          -- the payload sub-record (witness fields removed)
          payItems = [it | it@(RecItem _ n _) <- items, nameText n `notElem` witBinderNames]
      witTerms <- goCompatWits [] (zip witFs witWs)
      elabSealExistsCore ctx (ERecordLit payItems (exprSpan e)) sV witLabels fs sp witTerms
    goCompatWits _ [] = pure []
    goCompatWits done ((field, (_, we)) : rest) = do
      let thisRecv = CRecordV (sortOn fst done)
      wty' <- substThisInto ctx thisRecv (rfType field)
      wt <- checkObservedExpr ctx "ordinary existential witness field" (rfMode field) we wty'
      let lbl = rfName field
      ((lbl, wt) :) <$> goCompatWits ((lbl, wt) : done) rest
    freshWitnessTerms _ [] = pure []
    freshWitnessTerms done (field : rest) = do
      let thisRecv = CRecordV (sortOn fst done)
      witnessType <- substThisInto ctx thisRecv (rfType field)
      witness <- freshMetaFor ctx witnessType
      let labelled = (rfName field, witness)
      (labelled :) <$> freshWitnessTerms (labelled : done) rest

-- | The shared core: with the witness terms already chosen (metas for
-- the direct form, supplied terms for the explicit-witness form), check
-- the payload, enforce that all witnesses are solved, and build the
-- sealed package value.
elabSealExistsCore ::
  Ctx -> Expr -> Value -> [Text] -> [RecordField Value] -> Span -> [(Text, Term)] -> CheckM (Term, Value)
elabSealExistsCore ctx e sV witLabels fs sp witTerms = do
  pendingBefore <- gets (Set.fromList . map pendingMeta . csPending)
  let payFs = filter ((`notElem` witLabels) . rfName) fs
      thisRecv = CRecordV (sortOn fst witTerms)
  payVals <- case payFs of
    -- one anonymous non-record payload: check e against its type with
    -- the witnesses substituted (Spec.md 13316-13317, 13360)
    [payField]
      | rfName payField == existsPayloadLabel -> do
          payTy' <- substThisInto ctx thisRecv (rfType payField)
          eTm <- check ctx e payTy'
          pure [(rfName payField, eTm)]
    -- record-shaped payload: e must provide each source-labeled field
    _ -> do
      (eTm0, eTy0) <- infer ctx e
      (eTm, eTy1) <- insertAllImplicits ctx (exprSpan e) eTm0 eTy0
      eTy <- forceM eTy1
      mefs <- case eTy of
        VRecordTQ efs -> pure (Just efs)
        VSigT _ inner ->
          forceM inner >>= \case
            VRecordTQ efs -> pure (Just efs)
            _ -> pure Nothing
        _ -> pure Nothing
      case mefs of
        Nothing -> do
          errAt (exprSpan e) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
            "the sealed expression does not have a record type matching the existential payload view (§13.2.11)"
          pure [(rfName field, eTm) | field <- payFs]
        Just efs -> do
          forM_ payFs $ \field -> case find ((== rfName field) . rfName) efs of
            Nothing ->
              errAt (exprSpan e) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                ("the sealed expression does not provide the payload field '" <> rfName field <> "' (§13.2.11)")
            Just actualField -> do
              aty' <- substThisInto ctx eTm (rfType actualField)
              fty' <- substThisInto ctx thisRecv (rfType field)
              expectType ctx (exprSpan e) aty' fty'
          pure [(rfName field, CProjM (rfMode field) eTm (rfName field)) | field <- payFs]
  -- §13.2.11 13363-13364: sealing is a scoped inference boundary. Resolve
  -- exactly the payload obligations connected to a witness, including chains
  -- through other newly-created evidence metas, but do not flush unrelated
  -- obligations from the enclosing declaration.
  pendingAfter <- gets csPending
  witnessTermsZonked <- mapM (zonkTermM (ctxLen ctx) . snd) witTerms
  ec <- ec_
  let witnessMetas =
        Set.fromList
          (concatMap metaIdsOf (map snd witTerms ++ witnessTermsZonked))
      newPending =
        [ entry
        | entry <- pendingAfter
        , pendingMeta entry `Set.notMember` pendingBefore
        ]
      entryMetas (mid, goal, _, goalCtx, _) =
        Set.insert mid (Set.fromList (metaIdsOf (quote ec (ctxLen goalCtx) goal)))
      reachable roots remaining =
        let (connected, rest) =
              List.partition (not . Set.disjoint roots . entryMetas) remaining
            roots' = Set.unions (roots : map entryMetas connected)
         in if null connected then roots else reachable roots' rest
      reachableMetas = reachable witnessMetas newPending
      selected =
        Set.fromList
          [ pendingMeta entry
          | entry <- newPending
          , not (Set.disjoint reachableMetas (entryMetas entry))
          ]
  flushPendingSelectedWithPolicy True selected
  -- Check the fully-zonked witness, not only the outer 'CMeta': a solved meta
  -- may alias another unsolved meta, which is still not an inferred witness.
  forM_ witTerms $ \(lbl, wt) -> do
    wt' <- zonkTermM (ctxLen ctx) wt
    state <- get
    unless (null (unsolvedMetasOf state wt')) $
      errAt sp "E_UNSOLVED_IMPLICIT" (Just "kappa.implicit.unsolved")
        ( "the existential witness "
            <> lbl
            <> " could not be inferred; use the explicit-witness 'seal exists (...) . e as ...' form or annotate the payload (§13.2.11)"
        )
  pure (CSealE witLabels (CRecordV (sortOn fst (witTerms ++ payVals))), sV)
  where
    pendingMeta (mid, _, _, _, _) = mid

-- | §13.2.11 explicit-witness introduction (Spec.md 13376-13415):
-- @seal exists (a1 = w1, ..., an = wn). e as exists (b1:S1)...(bn:Sn). T@.
-- The witness assignments are checked sequentially against the binder
-- telescope (positionally — witness labels are canonical and internal),
-- then the payload is checked with those witnesses supplied.
elabSealExistsExplicit :: Ctx -> [(Name, Expr)] -> Expr -> Expr -> Span -> CheckM (Term, Value)
elabSealExistsExplicit ctx ws e tyE sp = do
  (sTm, _) <- inferType ctx tyE
  sV <- forceM =<< evalIn ctx sTm
  case sV of
    VSigT ls inner
      | any isExistsInternalLabel ls ->
          forceM inner >>= \case
            VRecordTQ fs -> do
              let witFs = filter ((`elem` ls) . rfName) fs
              when (length ws /= length witFs) $
                errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                  ( "this explicit-witness 'seal' supplies "
                      <> T.pack (show (length ws))
                      <> " witness(es) but the existential type has "
                      <> T.pack (show (length witFs))
                      <> " (§13.2.11)"
                  )
              -- check each witness assignment against its (dependent)
              -- type, threading earlier witnesses through 'this'
              witTerms <- goWits [] (zip witFs ws)
              elabSealExistsCore ctx e sV ls fs sp witTerms
            _ -> notExists sV
    _ -> notExists sV
  where
    notExists sV = do
      _ <- pure sV
      errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
        "the ascribed type of 'seal exists (...) . e as ...' must be an existential type (§13.2.11)"
      anyHole ctx
    goWits _ [] = pure []
    goWits done ((field, (_, we)) : rest) = do
      let thisRecv = CRecordV (sortOn fst done)
      wty' <- substThisInto ctx thisRecv (rfType field)
      wt <- checkObservedExpr ctx "ordinary existential witness field" (rfMode field) we wty'
      let lbl = rfName field
      ((lbl, wt) :) <$> goWits ((lbl, wt) : done) rest

-- | §13.2.11 existential elimination (Spec.md 13469-13540):
-- @open e as exists (a1, ..., an). pat in body@. The witnesses are
-- introduced as rigid quantity-0 locals bound to the (opaque) witness
-- selections of the package; the payload view is bound by @pat@; @body@
-- is elaborated in that extended scope; the opened witnesses must not
-- escape the inferred result type.
--
-- Following the normative schematic elaboration (Spec.md 13528-13536),
-- we emit @let 0 a_i = pkg.⟨wit_i⟩@ for each witness and a single
-- irrefutable @match@ binding the payload pattern.
elabOpenExists :: Ctx -> Expr -> [Name] -> Pattern -> Expr -> Span -> CheckM (Term, Value)
elabOpenExists ctx e ns pat body sp = do
  (eTm, eTy) <- infer ctx e
  eTyF <- forceM eTy
  case eTyF of
    VSigT ls inner
      | any isExistsInternalLabel ls ->
          forceM inner >>= \case
            VRecordTQ fs -> openWith eTm eTyF ls fs
            _ -> notExists
    _ -> notExists
  where
    notExists = do
      errAt (exprSpan e) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
        "the operand of 'open ... as exists ...' must have an existential type (§13.2.11)"
      anyHole ctx
    openWith eTm pkgTy ls fs = do
      let witFs = filter ((`elem` ls) . rfName) fs
          payFs = filter ((`notElem` ls) . rfName) fs
          names = map nameText ns
          nWit = length witFs
      when (length ns /= nWit) $
        errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
          ( "this 'open' binds "
              <> T.pack (show (length ns))
              <> " witness(es) but the existential type has "
              <> T.pack (show nWit)
              <> " (§13.2.11)"
          )
      forM_ (duplicatesOf (filter (/= "_") names)) $ \n ->
        errAt sp "E_RECORD_DUPLICATE_FIELD" (Just "kappa-hs.record.duplicate-field")
          ("'open ... as exists' binds the witness name '" <> n <> "' more than once (§13.2.11)")
      -- Schematic elaboration (Spec.md 13528-13536): bind the package as
      -- an outer let so all witness/payload selections refer to it by a
      -- properly-shifting de Bruijn variable, then bind each opened
      -- witness as a quantity-0 local and the payload via 'pat'.
      let ctxP = bindCtx "__pkg" False pkgTy ctx
          pkgLvl = ctxLen ctx -- de Bruijn LEVEL of __pkg
          pkgAt c = CVar (ctxLen c - 1 - pkgLvl)
      -- bind each opened witness as a rigid quantity-0 local; record its
      -- de Bruijn level so we can later detect escape in the result type
      (ctxW, witAccRev) <- foldM (bindWit pkgAt) (ctxP, []) (zip names witFs)
      let witAcc = reverse witAccRev -- (level, typeTerm) per witness, oldest-first
          witLvls = map fst witAcc
      -- the payload view (Spec.md 13535)
      (payTm, payTy) <- case payFs of
        [payField]
          | rfName payField == existsPayloadLabel -> do
              payTy' <- substThisInto ctxW (pkgAt ctxW) (rfType payField)
              pure (CProjM (rfMode payField) (pkgAt ctxW) (rfName payField), payTy')
        _ -> do
          payT' <- substThisInto ctxW (pkgAt ctxW) (VRecordTQ (sortOn rfName payFs))
          pure
            ( CRecordV
                (sortOn fst [(rfName field, CProjM (rfMode field) (pkgAt ctxW) (rfName field)) | field <- payFs])
            , payT'
            )
      (patC, ctx2, patternRefinements) <- elabPattern ctxW pat payTy
      (bodyTm, bodyTy, bodyTyTm) <-
        withPatternRefinements patternRefinements $ do
          checkIrrefutable ctxW pat payTy sp
          (bodyTm, bodyTy) <- infer ctx2 body
          -- §13.2.11 13517-13524: opened witnesses must not escape the result
          bodyTyTm <- quoteIn ctx2 bodyTy
          pure (bodyTm, bodyTy, bodyTyTm)
      let n2 = ctxLen ctx2
          escaping = [nm | (nm, lvl) <- zip names witLvls, nm /= "_", varUsedAt (n2 - 1 - lvl) bodyTyTm]
      forM_ escaping $ \nm ->
        errAt sp "E_EXISTENTIAL_WITNESS_ESCAPE" (Just "kappa-hs.exists.escape")
          ("the opened existential witness '" <> nm <> "' escapes in the result type of 'open' (§13.2.11)")
      -- assemble: let __pkg = e in (let 0 a_i = __pkg.<wit_i>)* in
      --           (match payload case pat -> body). At witness-let i's
      --           rhs position, __pkg is i binders up (index i).
      pkgTyTm <- quoteIn ctx pkgTy
      -- The payload type is quoted in exactly the witness/package scope that
      -- the assembled lets recreate, so the match keeps a valid checked
      -- scrutinee annotation through normalization and backend validation.
      payTyTm <- quoteIn ctxW payTy
      let assemble payload =
            foldr
              (\(i, (nm, field), wtyTm) b ->
                 CLetM (rfMode field) (rfQ field) nm wtyTm
                   (CProjM (rfMode field) (CVar i) (rfName field)) b)
              payload
              (zip3 [0 ..] (zip names witFs) (map snd witAcc))
          close payload = CLetM Ordinary QW "__pkg" pkgTyTm eTm (assemble payload)
          payMatch = CMatch payTm (Just payTyTm) Nothing [CaseAlt patC Nothing bodyTm]
          whole = close payMatch
          removedBinders = ctxLen ctx2 - ctxLen ctx
          loweredBodyType = shiftTerm (-removedBinders) 0 bodyTyTm
          typeMatch = CMatch payTm (Just payTyTm) Nothing [CaseAlt patC Nothing bodyTyTm]
          wholeType = close typeMatch
      resultType <-
        if not (null escaping)
          then globalValueM prelUnit []
          else
            if termScopedAt (ctxLen ctx) loweredBodyType
              then evalIn ctx loweredBodyType
              else evalIn ctx wholeType
      pure (whole, resultType)
    -- bind one opened witness as a quantity-0 local; returns the extended
    -- context and the witness's (de Bruijn LEVEL, quoted type term)
    bindWit pkgAt (c, acc) (nm, field) = do
      wty' <- substThisInto c (pkgAt c) (rfType field)
      wtyTm <- quoteIn c wty'
      let lvl = ctxLen c
          c' = bindCtxMQ (rfMode field) (rfQ field) nm False wty' c
      pure (c', (lvl, wtyTm) : acc)

-- | Whether the de Bruijn /index/ @ix@ (relative to the term's top
-- scope) is referenced by any @CVar@ in the term, incrementing the
-- target under each binder. Used by 'elabOpenExists' to detect witness
-- escape in the inferred result type.
varUsedAt :: Int -> Term -> Bool
varUsedAt = go
  where
    go ix = \case
      CVar i -> i == ix
      CLevel _ -> False
      CUniverseLift _ _ _ inner -> go ix inner
      CSchemaLift _ _ _ _ _ _ sourceArguments targetArguments inner ->
        any (go ix) sourceArguments || any (go ix) targetArguments || go ix inner
      CLam _ _ _ b -> go (ix + 1) b
      CPi _ _ _ _ a b -> go ix a || go (ix + 1) b
      CApp _ f a -> go ix f || go ix a
      CCtor _ _ as -> any (go ix) as
      CMatch s _ _ alts -> go ix s || or [maybe False (go (ix + patBindersC p)) g || go (ix + patBindersC p) b | CaseAlt p g b <- alts]
      CRecordT fs -> any (go ix . snd) fs
      CRecordV fs -> any (go ix . snd) fs
      CProj x _ -> go ix x
      CProjAt x _ _ -> go ix x
      CVariantT ms -> any (go ix) ms
      CInject _ x -> go ix x
      CLet _ _ a b c -> go ix a || go ix b || go (ix + 1) c
      CLetRec _ _ a b c -> go ix a || go (ix + 1) b || go (ix + 1) c
      CLetPolyM _ _ _ _ a b c -> go ix a || go ix b || go (ix + 1) c
      CLetRecPolyM _ _ _ _ a b c -> go ix a || go (ix + 1) b || go (ix + 1) c
      CLetRecGroupM _ definitions body ->
        let count = length definitions
         in any (\definition -> go ix (clrdType definition) || go (ix + count) (clrdRhs definition)) definitions
              || go (ix + count) body
      CSealE _ x -> go ix x
      CSigT _ x -> go ix x
      CThunkE x suspensionType -> go ix x || maybe False (go ix) suspensionType
      CLazyE x suspensionType -> go ix x || maybe False (go ix) suspensionType
      CForceE x resultType -> go ix x || maybe False (go ix) resultType
      CIf a b c -> go ix a || go ix b || go ix c
      CQuote _ slots -> any (go ix) slots
      CGlob _ -> False
      CLocal i _ -> i == ix
      CSort _ -> False
      CLit _ -> False
      CMeta _ -> False
      CDo _ _ -> False

-- | A record literal against a §13.2.1 dependent record type (or one
-- whose initializers use sibling references): fields elaborate in
-- dependency order; each initializer sees the earlier siblings as
-- 'this' and checks against its field type with 'this' substituted.
elabDependentRecordLit :: Ctx -> [RecItem] -> [(Text, Value)] -> Span -> CheckM (Term, Value)
elabDependentRecordLit ctx items fs =
  elabDependentRecordLitQ ctx items [RecordField n Ordinary FormationOrdinary QW Nothing t | (n, t) <- fs]

elabDependentRecordLitQ :: Ctx -> [RecItem] -> [RecordField Value] -> Span -> CheckM (Term, Value)
elabDependentRecordLitQ ctx items qfs sp = do
  let fs = [(rfName f, rfType f) | f <- qfs]
  let supplied = [(nameText n, fromMaybe (EVar n) me) | RecItem _ n me <- items]
  forM_ items $ \it ->
    case (riQuantity it, find ((== nameText (riName it)) . rfName) qfs) of
      (Just written, Just field)
        | qOf (Just written) /= rfQ field ->
            errAt (nameSpan (riName it)) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
              ( "record field '" <> nameText (riName it)
                  <> "' is written with quantity " <> renderCoreQ (qOf (Just written))
                  <> ", but the expected field quantity is " <> renderCoreQ (rfQ field)
              )
      _ -> pure ()
  forM_ (duplicatesOf (map fst supplied)) $ \n ->
    errAt sp "E_RECORD_DUPLICATE_FIELD" (Just "kappa-hs.record.duplicate-field")
      ("record literal has duplicate field '" <> n <> "'")
  if sort (map fst supplied) /= sort (map fst fs)
    then do
      errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
        ( "record literal fields do not match the expected record type (expected: "
            <> T.intercalate ", " (map fst fs) <> ")"
        )
      pure (CRecordV [], VRecordTQ qfs)
    else do
      annotated <- forM qfs $ \field -> do
        let nm = rfName field
            fty = rfType field
        ftyTm <- quoteIn ctx fty
        let e = fromMaybe (EVar (Name nm sp)) (lookup nm supplied)
            deps =
              nub (thisDepsOf ftyTm ++ levelFieldDepsOf ftyTm ++ [l | l <- surfaceThisRefs e, l `elem` map fst fs])
        pure (nm, deps, (field, e))
      case topoFields annotated of
        Nothing -> do
          errAt sp "E_RECORD_DEPENDENCY_CYCLE" (Just "kappa-hs.record.dependency-cycle")
            "the sibling references of this record literal form a cycle (§13.2.1)"
          anyHole ctx
        Just ordered -> do
          allFields <- goLit [] [] ordered
          pure (CRecordV (sortOn fst allFields), VRecordTQ qfs)
  where
    goLit _ _ [] = pure []
    goLit doneV doneT ((field, e) : rest) = do
      let nm = rfName field
          fty = rfType field
      fty' <- substThisInto ctx (CRecordV (sortOn fst doneV)) fty
      tm <-
        withThis (Just (ThisValue doneV doneT))
          (checkObservedExpr ctx "ordinary record field" (rfMode field) e fty')
      let field' = field {rfType = fty'}
      ((nm, tm) :) <$> goLit ((nm, tm) : doneV) (field' : doneT) rest

-- | A record update on a §13.2.1 dependent record: updated fields check
-- against their field types with 'this' bound to the evolving record;
-- a non-updated field whose type depends on an updated field must still
-- be well-typed after the update (else it needed repair).
elabDependentPatch :: Ctx -> Term -> [RecordField Value] -> [PatchItem] -> Span -> CheckM (Term, Value)
elabDependentPatch ctx baseTm qfs items sp = do
  let fs = [(rfName field, rfType field) | field <- qfs]
  ups <- fmap catMaybes . forM items $ \case
    PatchUpdate [(_, n)] (PatchValue v)
      | nameText n `elem` map fst fs -> pure (Just (nameText n, v))
      | otherwise -> do
          errAt (nameSpan n) "E_UNKNOWN_FIELD" (Just "kappa.name.unresolved")
            ("record has no field '" <> nameText n <> "'")
          pure Nothing
    it -> do
      unsupportedAt (patchItemSpan it sp)
        "this update form is not supported on a dependent record"
      pure Nothing
  forM_ (duplicatesOf (map fst ups)) $ \n ->
    errAt sp "E_RECORD_PATCH_DUPLICATE_PATH" (Just "kappa-hs.record.patch-duplicate")
      ("record patch updates field '" <> n <> "' more than once (§13.2.5)")
  annotated <- forM qfs $ \field -> do
    let nm = rfName field
        fty = rfType field
    ftyTm <- quoteIn ctx fty
    let dependencies = nub (thisDepsOf ftyTm ++ levelFieldDepsOf ftyTm)
    pure (nm, dependencies, (field, dependencies))
  case topoFields annotated of
    Nothing -> do
      errAt sp "E_RECORD_DEPENDENCY_CYCLE" (Just "kappa-hs.record.dependency-cycle")
        "the field-dependency graph of this record type contains a cycle (§13.2.1)"
      anyHole ctx
    Just ordered -> do
      allFields <- goUp ups [] [] ordered
      -- staleness (§13.2.5): a kept field whose type mentions an
      -- updated sibling keeps its old value of the OLD instantiation
      let newRec = CRecordV (sortOn fst allFields)
      forM_ ordered $ \(field, deps) ->
        let nm = rfName field
            fty = rfType field
         in
        when (nm `notElem` map fst ups && not (null (deps `intersect` map fst ups))) $ do
          oldTy <- substThisInto ctx baseTm fty
          newTy <- substThisInto ctx newRec fty
          ok <- unify ctx oldTy newTy
          unless ok $
            errAt sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
              ( "the dependent field '" <> nm
                  <> "' is stale after this update; it must be repaired in the same update (§13.2.5)"
              )
      pure (newRec, VRecordTQ qfs)
  where
    goUp _ _ _ [] = pure []
    goUp ups doneV doneT ((field, _) : rest) = do
      let nm = rfName field
      fty' <- substThisInto ctx (CRecordV (sortOn fst doneV)) (rfType field)
      tm <- case lookup nm ups of
        Just v ->
          withThis (Just (ThisValue doneV doneT))
            (checkObservedExpr ctx "ordinary dependent record patch field" (rfMode field) v fty')
        Nothing -> pure (CProjM (rfMode field) baseTm nm)
      let field' = field {rfType = fty'}
      ((nm, tm) :) <$> goUp ups ((nm, tm) : doneV) (field' : doneT) rest
    patchItemSpan it dflt = case it of
      PatchUpdate ((_, n) : _) _ -> nameSpan n
      PatchExtend n _ -> nameSpan n
      _ -> dflt

-- ── Variants ─────────────────────────────────────────────────────────

elabVariant :: Ctx -> [VariantArm] -> Maybe Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabVariant ctx arms mtail sp mexpected = do
  when (isJust mtail) . void $ unsupported ctx sp "open variant rows"
  expected <- traverse forceM mexpected
  case (arms, expected) of
    -- single arm in term position: injection
    ([VariantArm payload mty], Just (VVariantT members)) -> do
      (tm, ty) <- case mty of
        Just tyE -> do
          (tyTm, _) <- inferType ctx tyE
          tyV <- evalIn ctx tyTm
          (,tyV) <$> check ctx payload tyV
        Nothing -> infer ctx payload
      tm2 <- injectInto ctx tm ty members (VVariantT members) sp
      pure (tm2, VVariantT members)
    -- §13.1.3: a single non-type arm with no expected union type is
    -- an injection the term grammar does not admit standalone
    ([VariantArm payload Nothing], Nothing) -> do
      st0 <- get
      n0 <- gets (length . csDiags)
      r <- inferType ctx payload
      n1 <- gets (length . csDiags)
      if n1 == n0
        then pure (CVariantT [fst r], VSort LZero)
        else do
          put st0
          errAt sp "E_EXPECTED_SYNTAX_TOKEN" (Just "kappa-hs.parse.error")
            "a union injection (| e |) is admitted only against an expected union type (§13.1.3)"
          anyHole ctx
    _ -> do
      -- type formation: every arm is a type
      memberTms <- forM arms $ \(VariantArm e mty) -> do
        when (isJust mty) $
          errAt sp "E_VARIANT_ARM" Nothing "variant type arms do not take ascriptions"
        fst <$> inferType ctx e
      memberVs <- mapM (evalIn ctx) memberTms
      tags <- mapM (tagOf ctx) memberVs
      let canon = map snd (sortOn fst (zip tags memberTms))
      when (length (nub tags) /= length tags) $
        errAt sp "E_VARIANT_DUPLICATE" (Just "kappa-hs.variant.duplicate-member")
          "duplicate variant member types"
      pure (CVariantT canon, VSort LZero)

-- ── Lambdas, lets, blocks ────────────────────────────────────────────

elabLambda :: Ctx -> [Binder] -> Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabLambda = elabLambdaWith False False

elabNamedDeclLambda :: Ctx -> [Binder] -> Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabNamedDeclLambda = elabLambdaWith True False

elabLambdaWith :: Bool -> Bool -> Ctx -> [Binder] -> Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabLambdaWith allowInoutBinders provisionalInference ctx0 bs0 body0 sp mexpected = do
  unless allowInoutBinders $
    forM_ bs0 (rejectInoutBinderContext "lambda or anonymous function")
  -- Wrong-facet repairs such as `readRef x` -> `readRef (ref x)` must be
  -- diagnosed before the closure boundary turns the same source occurrence into
  -- a generic current-read-crosses-boundary error.  Keep only repairs that do
  -- not lift any current reads out of the lambda.
  (pre, body1) <- liftCurrentReadsExpr ctx0 (exprSpan body0) body0
  let body = if null pre then body1 else body0
  -- the lambda is a closure boundary: borrowed implicit locals from
  -- the surrounding scope may not be captured into it (§16.3.3)
  go body (pushCtxBarrier (withVarReadBlock VarReadCrossesBoundary ctx0)) bs0 mexpected
  where
    -- §18.5.1: the lambda body do IS the labeled lambda's completion
    -- boundary, so elaborate an EDo body directly with ctxReturnTarget
    -- preserved (the generic EDo path resets it as a nested do).
    go body ctx [] mexp = case (body, mexp) of
      (EDo mlbl items isp, Just t) -> do
        (tm, ty') <- elabDo ctx mlbl items isp (Just t)
        expectType ctx isp ty' t
        pure (tm, t)
      (EDo mlbl items isp, Nothing) -> do
        (tm, ty) <- elabDo ctx mlbl items isp Nothing
        insertAllImplicits ctx (exprSpan body) tm ty
      (_, Just t) -> do
        (_, _, captureAnnotated) <- captureAnnotationView t
        tm <- case (body, captureAnnotated) of
          (ELambda {}, True) -> checkCaptureAnnotatedLambda ctx body t
          _ -> check ctx body t
        pure (tm, t)
      (_, Nothing) -> do
        (tm, ty) <- infer ctx body
        insertAllImplicits ctx (exprSpan body) tm ty
    go body ctx (b : rest) mexp = do
      -- Capture annotations are part of function-type identity, but they are
      -- transparent to introduction: a lambda still introduces the Pi they
      -- delimit.  Explicit borrow-region arrows synthesize these wrappers, so
      -- every binder-peeling step must use the same elimination view.
      (mexp', expectedCaptureRegions) <- case mexp of
        Nothing -> pure (Nothing, [])
        Just expectedValue -> do
          (underlying, regions) <- peelCapturesWithRegionsM expectedValue
          pure (Just underlying, regions)
      case mexp' of
        Just expectedPi@(VPiBoundM mode ic q borrowed nm assumption dom clo)
          | ic == (if bImplicit b then Impl else Expl) -> do
              -- check declared annotation against expected domain
              forM_ (binderTypeExpr b) $ \tyE -> do
                (tyTm, _) <- inferBinderDomainType ctx b tyE
                tyV <- evalIn ctx tyTm
                expectType ctx (bSpan b) dom tyV
              withBound <- extendLevelAssumption (bSpan b) ctx assumption
              let bn = binderName b nm
                  ctx'0 = bindCtxMQ mode q bn (bImplicit b) dom withBound
              ctx' <- recordBinderCaptureRegion ctx b borrowed expectedCaptureRegions ctx'0
              cod <- clApp clo (VRigid (ctxLen ctx) [])
              (inner, _) <- go body ctx' rest (Just cod)
              pure (CLamM mode ic q bn inner, expectedPi)
        _ -> do
          domV <- case binderTypeExpr b of
            Just tyE -> do
              (tyTm, _) <- inferBinderDomainType ctx b tyE
              evalIn ctx tyTm
            Nothing
              | bUnitBinder b -> globalValueM prelUnit []
              | allowInoutBinders || provisionalInference -> do
                  -- A source-unannotated parameter at a named declaration
                  -- boundary is still known to range over types. Record that
                  -- classifier at allocation time so local/top-level
                  -- generalization can authenticate and abstract the carrier
                  -- meta without reconstructing authority from source shape.
                  level <- freshGeneralizableLevelMeta
                  freshMetaFor ctx (VSort level) >>= evalIn ctx
              | otherwise -> freshMetaV ctx
          let bn = binderName b "_"
              ic = if bImplicit b then Impl else Expl
              inferredDomain = isNothing (binderTypeExpr b) && not (bUnitBinder b)
          (mode, q) <-
            if provisionalInference && inferredDomain && isNothing (bpObservation (bPrefix b))
              then pure (Parametric, maybe Q0 (qOf . Just) (bpQuantity (bPrefix b)))
              else resolveBinderModeQ ctx b domV (binderQ b)
          let ctx'0 = bindCtxMQ mode q bn (bImplicit b) domV ctx
              ctx'1 =
                if provisionalInference && inferredDomain && isNothing (bpObservation (bPrefix b))
                  then ctx'0 {ctxEntries = markProvisional (ctxEntries ctx'0)}
                  else ctx'0
          ctx' <- recordBinderCaptureRegion ctx b False [] ctx'1
          (inner, innerTy) <- go body ctx' rest Nothing
          domTm <- quoteIn ctx domV
          innerTyTm <- quoteIn ctx' innerTy
          formation <- selectFormationMode ctx mode domV
          piV <- evalIn ctx (CPiFormedM mode formation ic q False bn domTm innerTyTm)
          case mexp' of
            Just t -> expectType ctx sp piV t
            Nothing -> pure ()
          pure (CLamM mode ic q bn inner, piV)

    binderName b dflt = maybe (if bUnitBinder b then "_" else dflt) nameText (bName b)

    markProvisional (entry : entries) = entry {ceModeProvisional = True} : entries
    markProvisional [] = []

-- Finalize source-unannotated local lambda contracts after the enclosing
-- local-let body has constrained their domain metas. This is the local SCC
-- analogue of 'finalizeGeneratedTelescope': observation and quantity are
-- derived from the solved domain, and the lambda and Pi are rewritten as one
-- atomic contract so they cannot disagree at KCore.
finalizeLocalLambdaContracts :: Bool -> Ctx -> [Binder] -> Term -> Term -> CheckM (Term, Term)
finalizeLocalLambdaContracts defaultUnsolved ctx0 binders0 rhs0 ty0 = do
  rhs <- zonkTermM (ctxLen ctx0) rhs0
  ty <- zonkTermM (ctxLen ctx0) ty0
  go ctx0 binders0 rhs ty
  where
    go _ [] rhs ty = pure (rhs, ty)
    go ctx (binder : binders) (CLamM oldMode ic oldQ name body) (CPiEvidenceM _ oldFormation tyIcit _ borrowed tyName assumption origin domain codomain)
      | ic == tyIcit = do
          domainValue0 <- evalIn ctx domain >>= forceM
          case domainValue0 of
            VFlex _ [] | not defaultUnsolved -> do
              let ctx' = bindCtxMQB oldMode oldQ name (ic == Impl) borrowed domainValue0 ctx
              (body', codomain') <- go ctx' binders body codomain
              pure
                ( CLamM oldMode ic oldQ name body'
                , CPiEvidenceM oldMode oldFormation tyIcit oldQ borrowed tyName assumption origin domain codomain'
                )
            _ -> do
              domainValue <- case domainValue0 of
                VFlex meta [] -> do
                  dependentDefault <- defaultDependentDomain ctx binder
                  case dependentDefault of
                    Just value -> do
                      solveMeta meta value
                      pure value
                    Nothing
                      | defaultsDirectlyToType binder -> do
                      -- This inferred local parameter is a source-visible
                          -- non-lowercase declaration parameter (the canonical
                          -- @A@ in @let id A x = x@).  Section 11.3.3 assigns
                          -- that parameter the direct Type default.
                          level <- freshGeneralizableLevelMeta
                          solveMeta meta (VSort level)
                          pure (VSort level)
                    Nothing ->
                      -- A lowercase value parameter does not itself become a
                      -- type witness merely because its carrier is flexible.
                      -- Keep the carrier meta for hidden generalization (or a
                      -- still-pending evidence goal/use site) and finalize the
                      -- source binder as the least-permissive ordinary value.
                      pure domainValue0
                value -> pure value
              domainTerm <- quoteIn ctx domainValue
              parametricKind <- isParametricKind (ctxLen ctx) domainValue
              let inferred = isNothing (binderTypeExpr binder) && not (bUnitBinder binder)
                  mode
                    | inferred = fromMaybe (if parametricKind then Parametric else Ordinary) (bpObservation (bPrefix binder))
                    | otherwise = oldMode
                  quantity
                    | inferred = case bpQuantity (bPrefix binder) of
                        Just sourceQuantity -> qOf (Just sourceQuantity)
                        Nothing -> if mode == Parametric then Q0 else QW
                    | otherwise = oldQ
                  ctx' = bindCtxMQB mode quantity name (ic == Impl) borrowed domainValue ctx
              formation <- selectFormationMode ctx mode domainValue
              (body', codomain') <- go ctx' binders body codomain
              pure
                ( CLamM mode ic quantity name body'
                , CPiEvidenceM mode formation tyIcit quantity borrowed tyName assumption origin domainTerm codomain'
                )
    go _ _ rhs ty = pure (rhs, ty)

    -- §11.3's dependent named-parameter default: after an inferred type
    -- parameter, an otherwise-unconstrained lowercase value parameter is a
    -- value of that type (the canonical @let id A x = x@ telescope). This is
    -- semantic context, not name matching against a particular spelling: the
    -- predecessor must itself have a sort classifier.
    defaultDependentDomain ctx binder
      | Just name <- bName binder
      , Just (first, _) <- T.uncons (nameText name)
      , isLower first =
          case (ctxEntries ctx, ctxEnv ctx) of
            (entry : _, value : _) -> do
              classifier <- forceM (ceType entry)
              pure $ case classifier of
                VSort _ -> Just value
                _ -> Nothing
            _ -> pure Nothing
      | otherwise = pure Nothing

    defaultsDirectlyToType binder =
      case bName binder >>= (fmap fst . T.uncons . nameText) of
        Just first -> not (isLower first)
        Nothing -> False

-- | Principalize and generalize one completed local declaration boundary.
-- Only level metas allocated while elaborating this declaration and still
-- observable in its type can enter the local telescope. Dependency-use metas
-- remain minimizable occurrence choices, and outer declaration parameters are
-- already rigid 'LParam's (§11.1.2.3A.1, §11.1.2.4A).
generalizeLocalDeclarationMetas
  :: Int
  -> Ctx
  -> Span
  -> [Text]
  -> Term
  -> Term
  -> CheckM (Term, Term)
generalizeLocalDeclarationMetas firstMeta ctx diagnosticSpan declarations ty0 rhs0 = do
  ty <- zonkTermM (ctxLen ctx) ty0
  rhs <- zonkTermM (ctxLen ctx) rhs0
  st <- get
  -- Evidence obligations outrank fresh declaration generalization. A meta
  -- mentioned by a postponed goal is constrained by that goal, even when the
  -- goal cannot yet be selected. Excluding it prevents @newRef None@ from
  -- quantifying over the enclosing monad while leaving unrelated universe
  -- proofs deferred until their level variables are principalized.
  pendingMetas <-
    nub . concat
      <$> mapM (unsolvedMetaIdsIn . pendingGoal) (csPending st)
  let ordinaryMetas = nub . foldTerm collect (const [])
      collect = \case
        CMeta meta -> [meta]
        _ -> []
      localUnsolved meta =
        meta >= firstMeta
          && meta `notElem` pendingMetas
          && case Map.lookup meta (csMetas st) of
            Just (Just _) -> False
            _ -> True
      candidates =
        sort
          [ meta
          | meta <- ordinaryMetas ty
          , localUnsolved meta
          , Just classifier <- [Map.lookup meta (csMetaClassifiers st)]
          , micDepth classifier == ctxLen ctx
          ]

  binders <- selectBinders st ordinaryMetas [] candidates
  if null binders
    then pure (ty, rhs)
    else do
      let metas = map lmbMeta binders
          binderCount = length binders
          abstractAll = abstractMetas metas binderCount
          tyBody = abstractAll ty
          rhsBody = abstractAll rhs
          ty' = foldr makePi tyBody binders
          rhs' = foldr makeLambda rhsBody binders
      validateRigidGeneralization diagnosticSpan declarations ctx binders rhs' ty'
      pure (ty', rhs')
  where
    pendingGoal (_, goal, _, _, _) = goal

    selectBinders _ _ selected [] = pure selected
    selectBinders st ordinaryMetas selected remaining =
      case find (ready st ordinaryMetas (map lmbMeta selected)) remaining of
        Nothing -> pure selected
        Just meta ->
          case Map.lookup meta (csMetaClassifiers st) of
            Nothing -> pure selected
            Just classifier -> do
              let prior = map lmbMeta selected
                  classifier0 =
                    zonkTermWith
                      (resolvedMetaCore st (ecOf st))
                      (substituteLevelMetas (csLevelAssignments st))
                      (ctxLen ctx)
                      (micType classifier)
              classifierValue <- evalIn ctx classifier0
              kindLike <- isKindLike (ctxLen ctx) classifierValue
              if not kindLike
                then selectBinders st ordinaryMetas selected (filter (/= meta) remaining)
                else do
                  formation <- selectFormationMode ctx Parametric classifierValue
                  let domain = abstractMetas prior (length prior) classifier0
                      binder =
                        LocalMetaBinder
                          { lmbMeta = meta
                          , lmbFormation = formation
                          , lmbName = "__generalized" <> T.pack (show (length selected))
                          , lmbDomain = domain
                          }
                  selectBinders st ordinaryMetas (selected ++ [binder]) (filter (/= meta) remaining)

    ready st ordinaryMetas selected meta =
      case Map.lookup meta (csMetaClassifiers st) of
        Nothing -> False
        Just classifier ->
          let dependencies =
                [ dependency
                | dependency <- ordinaryMetas (micType classifier)
                , case Map.lookup dependency (csMetas st) of
                    Just (Just _) -> False
                    _ -> True
                ]
           in all (`elem` selected) dependencies

    abstractMetas metas binderCount term =
      zonkTermWith replace id 0 (shiftTerm binderCount 0 term)
      where
        positions = Map.fromList (zip metas [0 ..])
        replace depth meta = do
          position <- Map.lookup meta positions
          pure (CVar (depth + binderCount - position - 1))

    makePi binder body =
      CPiBoundFormedM Parametric (lmbFormation binder) Impl Q0 False
        (lmbName binder) Nothing (lmbDomain binder) body
    makeLambda binder body = CLamM Parametric Impl Q0 (lmbName binder) body

-- | Recheck a candidate local declaration abstraction with each selected
-- metavariable represented by the rigid parametric binder that will actually
-- appear in Core. The term was already typechecked before abstraction, so the
-- remaining proof obligation is the finite observation judgment: the newly
-- rigid binder must not reach an ordinary sink, and analysis failure is
-- rejected rather than changing the declaration's inferred observation mode.
validateRigidGeneralization
  :: Span
  -> [Text]
  -> Ctx
  -> [LocalMetaBinder]
  -> Term
  -> Term
  -> CheckM ()
validateRigidGeneralization diagnosticSpan declarations = go
  where
    go _ [] _ _ = pure ()
    go ctx (candidate : candidates) (CLamM mode icit quantity name body) typeTerm = do
      typeValue <- evalIn ctx typeTerm >>= forceM
      case typeValue of
        VPiBoundM expectedMode expectedIcit expectedQuantity borrowed _ assumption domain closure
          | mode == expectedMode
          , icit == expectedIcit
          , quantity == expectedQuantity -> do
              withAssumption <- extendLevelAssumption diagnosticSpan ctx assumption
              let rigid = VRigid (ctxLen withAssumption) []
                  nextCtx =
                    bindCtxMQB mode quantity name (icit == Impl) borrowed domain withAssumption
              codomain <- clApp closure rigid
              dependencies <- observationDependenciesForTerm nextCtx body codomain
              let escaped =
                    find
                      ( \case
                          ParametricExternal 0 _ -> True
                          dependency -> dependencyIsAnalysisFailure dependency
                      )
                      (Set.toAscList dependencies)
              case escaped of
                Just dependency -> reportEscape candidate candidates dependency
                Nothing -> do
                  codomainTerm <- quoteIn nextCtx codomain
                  go nextCtx candidates body codomainTerm
        _ -> reportEscape candidate candidates (ParametricAnalysisFailure [] "generalized binder telescope is malformed")
    go _ (candidate : candidates) _ _ =
      reportEscape candidate candidates (ParametricAnalysisFailure [] "generalized term is not a lambda telescope")

    reportEscape candidate remaining dependency = do
      owner <- gets csModule
      let qualifiedDeclarations = qualifyDeclarationIdentities owner declarations
          declarationIdentity = fromMaybe "<anonymous>" (listToMaybe qualifiedDeclarations)
          declarationSccIdentity = T.intercalate "," qualifiedDeclarations
      report $
        withPayload
          ( withPayloadField "declarationIdentity" declarationIdentity $
              withPayloadField "declarationSccIdentity" declarationSccIdentity $
                withPayloadField "failedCandidateKind" "type" $
                  withPayloadField "declarations" (T.intercalate "," qualifiedDeclarations) $
              withPayloadField "sccIdentities" (T.intercalate "," qualifiedDeclarations) $
                withPayloadField "candidateMetavariables"
                  (T.intercalate "," (map (T.pack . show . lmbMeta) (candidate : remaining))) $
                    withPayloadField "candidateClassifiers"
                      (T.intercalate "," (map (renderTerm . lmbDomain) (candidate : remaining))) $
                        withPayloadField "rigidParametricBinders"
                          (T.intercalate "," (map lmbName (candidate : remaining))) $
                            withPayloadField "escapingDependency" (T.pack (show dependency)) $
                              withPayloadField "candidateKind" "type" $
                                withPayloadField "sourceOrigin" (T.pack (show diagnosticSpan)) $
                                  withPayloadField "nearestMonomorphicAnnotation" "none" $
                                    payloadKind "generalization-parametric-escape"
          ) $
          diag SevError StageElaborate "E_GENERALIZATION_PARAMETRIC_ESCAPE"
            (Just "kappa.generalization.parametric-escape") diagnosticSpan
            "candidate declaration generalization observes a rigid parametric binder in an ordinary position (§11.3.3)"

-- | Source-unannotated lambda parameters are finalized as part of the named
-- declaration boundary, so they require the same rigid observation replay as
-- free-meta abstraction. Anonymous lambdas outside a declaration never call
-- this function and therefore remain ordinary inference sites rather than
-- accidental generalization boundaries.
validateInferredLambdaGeneralization
  :: Span
  -> [Text]
  -> Ctx
  -> [Binder]
  -> Term
  -> Term
  -> CheckM ()
validateInferredLambdaGeneralization diagnosticSpan declarations = go 0
  where
    go _ _ [] _ _ = pure ()
    go index ctx (sourceBinder : sourceBinders) (CLamM mode icit quantity name body) typeTerm = do
      typeValue <- evalIn ctx typeTerm >>= forceM
      case typeValue of
        VPiBoundM expectedMode expectedIcit expectedQuantity borrowed _ assumption domain closure
          | mode == expectedMode
          , icit == expectedIcit
          , quantity == expectedQuantity -> do
              withAssumption <- extendLevelAssumption diagnosticSpan ctx assumption
              let rigid = VRigid (ctxLen withAssumption) []
                  nextCtx =
                    bindCtxMQB mode quantity name (icit == Impl) borrowed domain withAssumption
                  candidate =
                    isNothing (binderTypeExpr sourceBinder)
                      && not (bUnitBinder sourceBinder)
                      && mode == Parametric
              codomain <- clApp closure rigid
              dependencies <- observationDependenciesForTerm nextCtx body codomain
              let escaped =
                    find
                      ( \case
                          ParametricExternal 0 _ -> candidate
                          dependency -> candidate && dependencyIsAnalysisFailure dependency
                      )
                      (Set.toAscList dependencies)
              case escaped of
                Just dependency -> reportEscape ctx index name domain dependency
                Nothing -> do
                  codomainTerm <- quoteIn nextCtx codomain
                  go (index + 1) nextCtx sourceBinders body codomainTerm
        _ ->
          when (isNothing (binderTypeExpr sourceBinder) && not (bUnitBinder sourceBinder)) $
            reportEscape ctx index name (VSort LZero)
              (ParametricAnalysisFailure [] "finalized inferred binder telescope is malformed")
    go index ctx (sourceBinder : _) _ _ =
      when (isNothing (binderTypeExpr sourceBinder) && not (bUnitBinder sourceBinder)) $
        reportEscape ctx index "<missing>" (VSort LZero)
          (ParametricAnalysisFailure [] "finalized declaration is not a lambda telescope")

    reportEscape ctx index name domain dependency = do
      domainTerm <- quoteIn ctx domain
      owner <- gets csModule
      let qualifiedDeclarations = qualifyDeclarationIdentities owner declarations
          declarationIdentity = fromMaybe "<anonymous>" (listToMaybe qualifiedDeclarations)
          declarationSccIdentity = T.intercalate "," qualifiedDeclarations
      report $
        withPayload
          ( withPayloadField "declarationIdentity" declarationIdentity $
              withPayloadField "declarationSccIdentity" declarationSccIdentity $
                withPayloadField "failedCandidateKind" "type" $
                  withPayloadField "declarations" (T.intercalate "," qualifiedDeclarations) $
              withPayloadField "sccIdentities" (T.intercalate "," qualifiedDeclarations) $
                withPayloadField "candidateMetavariables" ("inferred-binder:" <> T.pack (show index)) $
                  withPayloadField "candidateClassifiers" (renderTerm domainTerm) $
                    withPayloadField "rigidParametricBinders" name $
                      withPayloadField "escapingDependency" (T.pack (show dependency)) $
                        withPayloadField "candidateKind" "type" $
                          withPayloadField "sourceOrigin" (T.pack (show diagnosticSpan)) $
                            withPayloadField "nearestMonomorphicAnnotation" "none" $
                              payloadKind "generalization-parametric-escape"
          ) $
          diag SevError StageElaborate "E_GENERALIZATION_PARAMETRIC_ESCAPE"
            (Just "kappa.generalization.parametric-escape") diagnosticSpan
            "candidate declaration generalization observes a rigid parametric binder in an ordinary position (§11.3.3)"

qualifyDeclarationIdentities :: ModuleName -> [Text] -> [Text]
qualifyDeclarationIdentities owner =
  map $ \declaration ->
    if declaration == "<anonymous>"
      || declaration == "<local-declaration>"
      || (moduleNameText owner <> ".") `T.isPrefixOf` declaration
      then declaration
      else moduleNameText owner <> "." <> declaration

generalizeLocalDeclarationUniverses
  :: Int
  -> Int
  -> Ctx
  -> Span
  -> [Text]
  -> Term
  -> Term
  -> CheckM (DeclarationUniverseTelescope, Term, Term)
generalizeLocalDeclarationUniverses firstMeta firstConstraint ctx diagnosticSpan declarations ty0 rhs0 =
  projectResult
    <$> generalizeLocalDeclarationUniversesWithRoles
      firstMeta firstConstraint ctx diagnosticSpan declarations [ty0] ty0 rhs0
  where
    projectResult (telescope, ty, rhs, _) = (telescope, ty, rhs)

-- | Collapse unconditional atomic equality cycles among inferred declaration
-- metas before choosing the hidden telescope. In the TypeLevel order,
-- @u <= v@ and @v <= u@ imply @u = v@ by antisymmetry, so retaining both as
-- independent schema parameters would be non-principal and would publish two
-- mutually interchangeable proof binders. Explicit schema parameters never
-- enter @candidates@ and therefore remain distinct source identities.
collapseInferredGeneralizableLevelEqualities
  :: Int
  -> Set LevelMeta
  -> CheckM ()
collapseInferredGeneralizableLevelEqualities firstConstraint candidates
  | Set.null candidates = pure ()
  | otherwise = do
      state <- get
      let assignments = csLevelAssignments state
          edges =
            [ (lower, upper)
            | constraint <- csLevelConstraints state
            , lcIdentity constraint >= firstConstraint
            , null (assumptionsList (lcAssumptions constraint))
            , LMeta lower <-
                [normalizeLevel (substituteLevelMetas assignments (lcLhs constraint))]
            , LMeta upper <-
                [normalizeLevel (substituteLevelMetas assignments (lcRhs constraint))]
            , lower `Set.member` candidates
            , upper `Set.member` candidates
            ]
          vertices =
            Set.toAscList
              (Set.fromList (concat [[lower, upper] | (lower, upper) <- edges]))
          graph =
            [ (meta, meta, [upper | (lower, upper) <- edges, lower == meta])
            | meta <- vertices
            ]
          aliases =
            Map.fromList
              [ (meta, LMeta representative)
              | component <- stronglyConnComp graph
              , let members = case component of
                      AcyclicSCC member -> [member]
                      CyclicSCC cyclicMembers -> sort cyclicMembers
              , representative <- take 1 members
              , meta <- drop 1 members
              ]
      unless (Map.null aliases) (installLevelAssignments aliases)

generalizeLocalDeclarationUniversesWithRoles
  :: Int
  -> Int
  -> Ctx
  -> Span
  -> [Text]
  -> [Term]
  -> Term
  -> Term
  -> CheckM (DeclarationUniverseTelescope, Term, Term, [LevelMeta])
generalizeLocalDeclarationUniversesWithRoles firstMeta firstConstraint ctx diagnosticSpan declarations roleTerms0 ty0 rhs0 = do
  (telescope, ty, rhs, retained, constraints) <-
    generalizeLocalDeclarationUniversesWithRolesRaw
      firstMeta firstConstraint ctx diagnosticSpan declarations roleTerms0 ty0 rhs0
  let (tyWithProofs, rhsWithProofs) =
        prependGeneratedConstraintBinders
          (dutParameterCount telescope)
          constraints
          ty
          rhs
  pure (telescope, tyWithProofs, rhsWithProofs, retained)

-- | Principalize a local declaration boundary without choosing where its
-- generated proof telescope is attached. Ordinary local declarations use the
-- wrapper above. A mutually recursive group attaches the same authenticated
-- constraints to each member and rechecks the SCC against those final member
-- contracts, rather than wrapping and then destructuring a record under a
-- proof lambda.
generalizeLocalDeclarationUniversesWithRolesRaw
  :: Int
  -> Int
  -> Ctx
  -> Span
  -> [Text]
  -> [Term]
  -> Term
  -> Term
  -> CheckM
       ( DeclarationUniverseTelescope
       , Term
       , Term
       , [LevelMeta]
       , [UniverseConstraint]
       )
generalizeLocalDeclarationUniversesWithRolesRaw firstMeta firstConstraint _ctx diagnosticSpan declarations roleTerms0 ty0 rhs0 = do
  st0 <- get
  let explicitCount = csActiveLocalUniverseSchemaCount st0
      assignments0 = csLevelAssignments st0
      roleTerms = map (zonkLevels assignments0) roleTerms0
      localMeta meta = meta >= firstMeta
      occurrenceMetas = csLevelInstantiationMetas st0
      roles = mconcat (map declarationUniverseRoles roleTerms)
      candidateGeneralizable =
        Set.filter
          (\meta -> localMeta meta && meta `Set.notMember` occurrenceMetas)
          (durGeneralizable roles)
      generalizable = maybe candidateGeneralizable (const Set.empty) explicitCount
      explicitMinimizable = maybe Set.empty (const candidateGeneralizable) explicitCount
      occurrenceMinimizable = Set.filter localMeta occurrenceMetas
      minimizable =
        Set.filter localMeta
          ( Set.difference
              (Set.unions [durMinimizable roles, explicitMinimizable, occurrenceMinimizable])
              generalizable
          )
      localConstraints0 =
        [ substituteLevelConstraintMetas assignments0 constraint
        | constraint <- csLevelConstraints st0
        , lcIdentity constraint >= firstConstraint
        ]
  unless (Set.null minimizable) $
    do
      let declarationIdentities =
            map (localDeclarationDiagnosticIdentity st0 diagnosticSpan) declarations
          -- Completeness of an explicit schema is a separate source contract
          -- from principal minimization. Preserve the old provenance check:
          -- a source-generalizable level that the detailed rules did not
          -- determine cannot be accepted merely because zero is the checked
          -- least value for an otherwise unconstrained selected meta.
          explicitUnresolved = case (explicitCount, solveLevelConstraintsFor minimizable localConstraints0) of
            (Just _, Right solution) ->
              let solved = lsAssignments solution
               in Set.intersection candidateGeneralizable
                    (Set.filter (`Map.notMember` solved) minimizable)
            _ -> Set.empty
      inferred <-
        inferPrincipalAtDeclarationBoundary
          diagnosticSpan declarationIdentities (isJust explicitCount) minimizable localConstraints0
      case inferred of
        PrincipalBoundarySolved candidate -> do
          unless (Set.null explicitUnresolved) $
            reportNoPrincipalUniverseDiagnostic
              diagnosticSpan declarationIdentities True explicitUnresolved localConstraints0
              Nothing
              "an explicit local declaration universe schema is incomplete (§11.1.2.3A.1)"
          -- Continue with the principal recovery assignment after an explicit
          -- schema diagnostic so later terms remain well scoped without making
          -- the invalid schema successful.
          installLevelAssignments candidate
        PrincipalBoundaryDeferred -> pure ()
        PrincipalBoundaryRejected -> pure ()
  collapseInferredGeneralizableLevelEqualities firstConstraint generalizable
  st <- get
  let assignments = csLevelAssignments st
      finalizedRoleTerms = map (zonkLevels assignments) roleTerms0
      ty = zonkLevels assignments ty0
      rhs = zonkLevels assignments rhs0
      retained = case explicitCount of
        Just _ -> []
        Nothing ->
          nub
            [ meta
            | meta <- concatMap levelMetasOfTerm finalizedRoleTerms
            , meta `Set.member` generalizable
            ]
      parameterSubstitution =
        Map.fromList (zip retained (map LParam [0 ..]))
      localParameterCount = fromMaybe (length retained) explicitCount
      abstractLevel = case explicitCount of
        Just _ -> id
        Nothing ->
          substituteLevelMetas parameterSubstitution
            . abstractLocalLevelParams localParameterCount
      transform = case explicitCount of
        Just _ -> id
        Nothing -> zonkTermWith (\_ _ -> Nothing) abstractLevel 0
      constraints =
        [ substituteLevelConstraintMetas assignments constraint
        | constraint <- csLevelConstraints st
        , lcIdentity constraint >= firstConstraint
        ]
      constraintMetas constraint =
        nub (levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint))
      generalizedConstraint constraint =
        let metas = constraintMetas constraint
         in not (null metas)
              && null (assumptionsList (lcAssumptions constraint))
              && all (`elem` retained) metas
      explicitConstraint constraint =
        let levels = [lcLhs constraint, lcRhs constraint]
            parameters = nub (concatMap levelParams levels)
         in null (assumptionsList (lcAssumptions constraint))
              && null (constraintMetas constraint)
              && any (< localParameterCount) parameters
      selected = case explicitCount of
        Just _ -> filter explicitConstraint constraints
        Nothing -> filter generalizedConstraint constraints
      selectedIds = Set.fromList (map lcIdentity selected)
      selectedConstraints =
        dedupeUniverseConstraints $
          [ candidate
          | constraint <- orderLevelConstraintsBySignatureOccurrence st selected
          , let candidate =
                  UniverseConstraint
                    (abstractLevel (lcLhs constraint))
                    (abstractLevel (lcRhs constraint))
          , proveLevelLeq
              emptyAssumptions
              (ucLower candidate)
              (ucUpper candidate)
              /= Proved
          ]
      telescope =
        DeclarationUniverseTelescope
          localParameterCount
          (isJust explicitCount)
  unless (Set.null selectedIds) $
    modify' $ \current ->
      reindexLevelConstraints $
        current
        { csLevelConstraints =
            filter ((`Set.notMember` selectedIds) . lcIdentity) (csLevelConstraints current)
        , csLevelConstraintOwners =
            Map.withoutKeys (csLevelConstraintOwners current) selectedIds
        , csLevelConstraintSpans =
            Map.withoutKeys (csLevelConstraintSpans current) selectedIds
        }
  pure
    ( telescope
    , transform ty
    , transform rhs
    , retained
    , selectedConstraints
    )
  where
    localDeclarationDiagnosticIdentity state span' declaration =
      moduleNameText (csModule state)
        <> "::local:"
        <> declaration
        <> "@"
        <> T.pack (spanFile span')
        <> ":"
        <> T.pack (show (posLine (spanStart span')))
        <> ":"
        <> T.pack (show (posCol (spanStart span')))

elabLet :: Ctx -> [LetBind] -> Expr -> Maybe Value -> CheckM (Term, Value)
elabLet ctx binds body expected =
  elabLetItems ctx (map LocalLetBinding binds) body expected

elabLetItems :: Ctx -> [LocalLetItem] -> Expr -> Maybe Value -> CheckM (Term, Value)
elabLetItems ctx0 binds body mexpected =
  elabLetItemsWith ctx0 binds $ \ctx ->
    case mexpected of
      Just expected -> (,expected) <$> check ctx body expected
      Nothing -> do
        -- Trailing implicits resolve against the let-local implicit context,
        -- not the caller's (§16.3.3).
        (term, ty) <- infer ctx body
        insertAllImplicits ctx (exprSpan body) term ty

-- | Elaborate local declarations around an already-typed continuation. This
-- is the sequencing primitive shared by ordinary let expressions and blocks:
-- block-only declarations can update the lexical checker environment between
-- let groups without hoisting through earlier source items.
elabLetItemsWith
  :: Ctx
  -> [LocalLetItem]
  -> (Ctx -> CheckM (Term, Value))
  -> CheckM (Term, Value)
elabLetItemsWith ctx0 binds finish = go ctx0 binds []
  where
    mkLet (_, mode, q, n, telescope, tyT, rhs, isRec, _) b
      | dutParameterCount telescope > 0 && isRec = CLetRecPolyM mode q n telescope tyT rhs b
      | dutParameterCount telescope > 0 = CLetPolyM mode q n telescope tyT rhs b
      | isRec = CLetRecM mode q n tyT rhs b
      | otherwise = CLetM mode q n tyT rhs b
    sourceBinders = \case
      ELambda _ binders _ _ -> binders
      _ -> []
    wrapLets bindings bodyTm = do
      -- The continuation may constrain an unannotated local lambda, and
      -- evidence/numeric obligations outrank declaration generalization.
      -- Settle everything currently solvable before the one final contract
      -- rewrite at this declaration boundary.
      flushPendingDeclaration
      finalized <- mapM finalizeBinding bindings
      pure (List.foldl' (flip mkLet) bodyTm finalized)
    finalizeBinding binding@(bindingCtx, mode, q, name, telescope, tyTm, rhsTm, isRec, binders)
      | null binders = pure binding
      | otherwise = do
          (rhsTm', tyTm') <- finalizeLocalLambdaContracts True bindingCtx binders rhsTm tyTm
          validationCtx <-
            if isRec
              then do
                tyValue <- evalIn bindingCtx tyTm'
                let recursiveValue = VRigid (ctxLen bindingCtx) []
                    bound
                      | dutParameterCount telescope > 0 =
                          bindCtxLetUniverseMode
                            name False tyValue recursiveValue telescope
                            Nothing Nothing mode Nothing bindingCtx
                      | otherwise =
                          bindCtxLetProjOpMode
                            name False tyValue recursiveValue
                            Nothing Nothing mode Nothing bindingCtx
                pure (setTopCoreQ q bound)
              else pure bindingCtx
          validateInferredLambdaGeneralization
            (maybe noSpan bSpan (listToMaybe binders))
            [name]
            validationCtx
            binders
            rhsTm'
            tyTm'
          pure (bindingCtx, mode, q, name, telescope, tyTm', rhsTm', isRec, binders)
    finalizeResolvedLambda ctx rhs rhsTm rhsTy
      | null binders = pure (rhsTm, rhsTy)
      | otherwise = do
          rhsTyTm <- quoteIn ctx rhsTy
          -- A local declaration is a generalization boundary (§11.1.2.3A.1,
          -- §11.3.3).  Close its inferred parameter contract before exposing
          -- it to the continuation; otherwise the first use can solve a
          -- shared hole and accidentally monomorphize every later use.
          -- Obligations produced by the RHS have already participated in
          -- inference, while constraints from the continuation must see a
          -- freshly instantiated declaration telescope.
          (rhsTm', rhsTyTm') <- finalizeLocalLambdaContracts True ctx binders rhsTm rhsTyTm
          rhsTy' <- evalIn ctx rhsTyTm'
          pure (rhsTm', rhsTy')
      where
        binders = sourceBinders rhs
    -- §11.3.3: elaborate a LOCAL let's type annotation, implicitly
    -- universalizing free ASCII-lowercase identifiers that resolve to
    -- NEITHER a global NOR an enclosing binder (so a block-local
    -- `let idf : a -> a = \x -> x` is polymorphic, just like a top-level
    -- signature). A name already in scope is NOT re-universalized — it
    -- resolves to that binder. Returns the (universalized) type term and
    -- its value.
    elabLocalSig ctx tyE = do
      fvs <-
        filterM
          ( \v -> do
              mg <- lookupGlobalName v
              schemaLevel <- gets (Map.lookup v . csActiveUniverseSchema)
              pure (isNothing mg && isNothing schemaLevel && isNothing (lookupCtx v ctx))
          )
          (nub (freeLower tyE))
      if null fvs
        then do
          (tyTm, _) <- inferType ctx tyE
          (,) tyTm <$> evalIn ctx tyTm
        else do
          kvs <- mapM (const (freshMetaV ctx)) fvs
          let ctxU = foldl (\c (v, k) -> bindCtxMQProvisional Parametric Q0 v False k c) ctx (zip fvs kvs)
          (tyTm0, _) <- inferType ctxU tyE
          universalBinders <- forM (zip fvs kvs) $ \(v, kv) -> do
            kv' <- forceM kv
            kind <- case kv' of
              VFlex m [] -> do
                level <- freshLevelMeta
                solveMeta m (VSort level)
                pure (VSort level)
              _ -> pure kv'
            kindTm <- quoteIn ctx kind
            markGeneralizableLevelTerm kindTm
            paramKind <- isParametricKind (ctxLen ctx) kind
            pure (v, if paramKind then Parametric else Ordinary, if paramKind then FormationParametric else FormationOrdinary, if paramKind then Q0 else QW, kindTm)
          let tyTm = foldr (\(v, mode, formation, q, kT) acc -> CPiFormedM mode formation Impl q False v kT acc) tyTm0 universalBinders
          (,) tyTm <$> evalIn ctx tyTm
    go ctx [] acc = do
      (bodyTm, bodyTy) <- finish ctx
      whole <- wrapLets acc bodyTm
      pure (whole, bodyTy)
    go ctx (LocalLetRecursiveGroup rawGroup : rest) acc = do
      (group, sharedSchema, completeExplicitSchema) <- prepareLocalRecursiveGroup rawGroup
      case sharedSchema of
        Nothing -> elabLocalRecursiveGroup ctx group rest acc (pure ()) completeExplicitSchema
        Just schema ->
          withLocalDeclarationUniverseSchema False (Just schema) $ \restore ->
            elabLocalRecursiveGroup ctx group rest acc restore completeExplicitSchema
    go ctx (LocalLetBinding binding : rest) acc =
      case explicitLocalSchema binding of
        Nothing -> goBinding go ctx binding rest acc
        Just (schema, stripped) ->
          withLocalDeclarationUniverseSchema False (Just schema) $ \restore ->
            goBinding
              (\nextCtx nextBindings nextAcc -> restore >> go nextCtx nextBindings nextAcc)
              ctx stripped rest acc

    elabLocalRecursiveGroup ctx group rest acc restoreSchema completeExplicitSchema = do
      firstMeta <- gets csNextMeta
      firstConstraint <- gets csNextLevelConstraint
      errorsBeforeGroup <-
        gets (length . filter ((== SevError) . dSeverity) . csDiags)
      explicitSchemaCount <- gets csActiveLocalUniverseSchemaCount
      signatures <- forM group $ \binding -> case binding of
        LetBind _ prefix (PVar name) (Just tyExpr) rhs@ELambda {} bindingSpan -> do
          (typeTerm, typeValue) <- elabLocalSig ctx tyExpr
          pure (nameText name, prefix, rhs, bindingSpan, typeTerm, typeValue)
        _ -> do
          errAt (lbSpan binding) "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
            "a local recursive declaration group requires named functions with preceding signatures"
          typeValue <- freshMetaV ctx
          typeTerm <- quoteIn ctx typeValue
          pure ("__invalid", emptyPrefix, lbExpr binding, lbSpan binding, typeTerm, typeValue)
      let roleTerms = [typeTerm | (_, _, _, _, typeTerm, _) <- signatures]
          provisionalMetas =
            Set.toAscList . durGeneralizable . mconcat $
              map declarationUniverseRoles roleTerms
          provisionalUniverses = map LMeta provisionalMetas
          provisionalSubstitution =
            Map.fromList (zip provisionalMetas (map LParam [0 ..]))
          abstractProvisional =
            zonkTermWith
              (\_ _ -> Nothing)
              (substituteLevelMetas provisionalSubstitution)
              0
          provisionalTelescope =
            DeclarationUniverseTelescope
              (fromMaybe (length provisionalUniverses) explicitSchemaCount)
              (isJust explicitSchemaCount)
          provisionalCurrentInstance = case explicitSchemaCount of
            Just count -> map LParam [0 .. count - 1]
            Nothing -> provisionalUniverses
          provisionalTypes =
            Map.fromList
              [ (name, abstractProvisional typeTerm)
              | (name, _, _, _, typeTerm, _) <- signatures
              ]
      provisionalTypeValues <-
        traverse (evalIn ctx) provisionalTypes
      let bindRecursiveMember telescope types modes context (name, prefix, _, _, _, _) =
            let ty = Map.findWithDefault (VSort LZero) name types
                mode = Map.findWithDefault Ordinary name modes
                level = ctxLen context
                bound =
                  bindCtxLetUniverseMode
                    name False ty (VRigid level []) telescope
                    Nothing Nothing mode Nothing context
             in setTopCoreQ (qOf (bpQuantity prefix)) bound
          provisionalModes = Map.fromList [(name, Ordinary) | (name, _, _, _, _, _) <- signatures]
          groupCtx =
            foldl'
              (bindRecursiveMember provisionalTelescope provisionalTypeValues provisionalModes)
              ctx
              signatures
          memberLevels =
            Map.fromList
              [ (ctxLen ctx + ordinal, name)
              | (ordinal, (name, _, _, _, _, _)) <- zip [0 ..] signatures
              ]
      previousLocalScope <- gets csActiveLocalRecursiveSchemaScope
      previousLocalOccurrences <- gets csLocalRecursiveSchemaOccurrences
      modify' $ \state ->
        state
          { csActiveLocalRecursiveSchemaScope = Nothing
          , csLocalRecursiveSchemaOccurrences = []
          -- The schema names remain lexically visible in member bodies, but
          -- nested local declarations do not own the recursive SCC's
          -- telescope. The group boundary reinstates this marker only while
          -- it principalizes and publishes the shared schema.
          , csActiveLocalUniverseSchemaCount = Nothing
          }
      checked <- forM (zip [0 ..] signatures) $ \(ordinal, (name, prefix, rhs, bindingSpan, typeTerm, typeValue)) -> do
        modify' $ \state ->
          state
            { csActiveLocalRecursiveSchemaScope =
                Just
                  ( LocalRecursiveSchemaScope
                      (ctxLen ctx + ordinal)
                      memberLevels
                      provisionalCurrentInstance
                  )
            }
        term <- check groupCtx rhs typeValue
        inferred <- observationJudgmentForTerm groupCtx term typeValue
        observation <- resolveLetObservation groupCtx bindingSpan prefix typeValue inferred
        formation <- selectFormationMode groupCtx (ojMode observation) typeValue
        pure (name, prefix, typeTerm, term, ojMode observation, formation)
      provisionalRecursiveOccurrences <- gets (reverse . csLocalRecursiveSchemaOccurrences)
      modify' $ \state -> state {csActiveLocalRecursiveSchemaScope = Nothing}
      let groupType =
            CRecordTQ
              [ RecordField name mode formation (qOf (bpQuantity prefix)) Nothing typeTerm
              | (name, prefix, typeTerm, _, mode, formation) <- checked
              ]
          groupRhs = CRecordV [(name, term) | (name, _, _, term, _, _) <- checked]
      modify' $ \state ->
        state {csActiveLocalUniverseSchemaCount = explicitSchemaCount}
      (telescope, groupType', groupRhs0', retainedMetas, sharedConstraints) <-
        generalizeLocalDeclarationUniversesWithRolesRaw
          firstMeta
          firstConstraint
          ctx
          (case signatures of (_, _, _, bindingSpan, _, _) : _ -> bindingSpan; [] -> noSpan)
          [name | (name, _, _, _, _, _) <- signatures]
          roleTerms
          groupType
          groupRhs
      modify' $ \state ->
        state {csActiveLocalUniverseSchemaCount = Nothing}
      levelAssignments <- gets csLevelAssignments
      let inferredProjection =
            urpRetainedPositions
              <$> deriveUniverseReferenceProjection
                    levelAssignments
                    provisionalMetas
                    retainedMetas
          universeProjection = case explicitSchemaCount of
            Just count -> [0 .. count - 1]
            Nothing -> fromMaybe [] inferredProjection
          expectedProjectionCount = dutParameterCount telescope
      when (length universeProjection /= expectedProjectionCount) $
        report $
          diag SevError StageElaborate "E_UNIVERSE_NO_PRINCIPAL_SOLUTION"
            (Just "kappa.universe.no-principal-solution")
            (Span "<local-universe-inference>" (Pos 1 1) (Pos 1 1))
            "local recursive declaration universe projection does not match its principal telescope"
      let provisionalGroupRhs =
            rewriteLocalRecursiveUniverseSpines
              (length signatures)
              universeProjection
              groupRhs0'
          baseFinalizedFields = case groupType' of
            CRecordTQ fields -> fields
            _ -> []
          addSharedConstraints field =
            let (fieldType, _) =
                  prependGeneratedConstraintBinders
                    (dutParameterCount telescope)
                    sharedConstraints
                    (rfType field)
                    (CRecordV [])
             in field {rfType = fieldType}
          finalizedFields =
            if null sharedConstraints
              then baseFinalizedFields
              else map addSharedConstraints baseFinalizedFields
          finalizedTypes = Map.fromList [(rfName field, rfType field) | field <- finalizedFields]
          provisionalFinalizedRhs = case provisionalGroupRhs of
            CRecordV fields -> Map.fromList fields
            _ -> Map.empty
          finalizedModes = Map.fromList [(name, mode) | (name, _, _, _, mode, _) <- checked]
      finalizedTypeValues <- traverse (evalIn ctx) finalizedTypes
      let groupCtxFinal =
            foldl'
              (bindRecursiveMember telescope finalizedTypeValues finalizedModes)
              ctx
              signatures
      errorsAfterProvisional <-
        gets (length . filter ((== SevError) . dSeverity) . csDiags)
      finalizedRhs <-
        if null sharedConstraints || errorsAfterProvisional > errorsBeforeGroup
          then do
            classifyLocalRecursiveSchemaOccurrences
              telescope
              completeExplicitSchema
              memberLevels
              retainedMetas
              universeProjection
              provisionalRecursiveOccurrences
            pure provisionalFinalizedRhs
          else do
            -- Generated SCC constraints are member contracts, not a wrapper
            -- around the temporary record used for principalization. Replay
            -- valid bodies under those final contracts so ordinary implicit
            -- insertion supplies both recursive and external proof spines.
            modify' $ \state ->
              state
                { csActiveLocalRecursiveSchemaScope = Nothing
                , csLocalRecursiveSchemaOccurrences = []
                }
            replayed <- forM (zip [0 ..] signatures) $
              \(ordinal, (name, _, rhs, _, _, _)) -> do
                modify' $ \state ->
                  state
                    { csActiveLocalRecursiveSchemaScope =
                        Just
                          ( LocalRecursiveSchemaScope
                              (ctxLen ctx + ordinal)
                              memberLevels
                              (map LParam [0 .. dutParameterCount telescope - 1])
                          )
                    }
                let expected =
                      Map.findWithDefault (VSort LZero) name finalizedTypeValues
                (name,) <$> check groupCtxFinal rhs expected
            replayedOccurrences <-
              gets (reverse . csLocalRecursiveSchemaOccurrences)
            classifyLocalRecursiveSchemaOccurrences
              telescope
              (isJust explicitSchemaCount)
              memberLevels
              []
              [0 .. dutParameterCount telescope - 1]
              replayedOccurrences
            pure (Map.fromList replayed)
      modify' $ \state ->
        state
          { csActiveLocalRecursiveSchemaScope = previousLocalScope
          , csLocalRecursiveSchemaOccurrences = previousLocalOccurrences
          }
      restoreSchema
      (bodyTerm, bodyType) <- go groupCtxFinal rest []
      let recursiveTerm =
            CLetRecGroupM
              telescope
              [ CoreLocalRecDef
                  mode
                  (qOf (bpQuantity prefix))
                  name
                  (Map.findWithDefault typeTerm name finalizedTypes)
                  (Map.findWithDefault term name finalizedRhs)
              | (name, prefix, typeTerm, term, mode, _) <- checked
              ]
              bodyTerm
      whole <- wrapLets acc recursiveTerm
      pure (whole, bodyType)

    -- Recursive RHSs were checked under the provisional shared telescope.
    -- Project only references to this SCC's member binders; nested locals and
    -- outer declarations retain their independently-owned universe spines.
    rewriteLocalRecursiveUniverseSpines memberCount projection =
      mapTermWithDepth rewrite 0
      where
        rewrite depth = \case
          CLocal index universes
            | index >= depth
            , index < depth + memberCount
            , all (< length universes) projection ->
                Just (CLocal index [universes !! position | position <- projection])
          _ -> Nothing

    classifyLocalRecursiveSchemaOccurrences
      telescope
      completeExplicitScc
      memberLevels
      retainedMetas
      projection
      occurrences = do
        state <- get
        let arity = dutParameterCount telescope
            sourceLevels = map LParam [0 .. arity - 1]
            retainedSubstitution =
              Map.fromList
                (zip retainedMetas (map LParam [0 ..]))
            normalizeOccurrenceLevel =
              normalizeLevel
                . substituteLevelMetas retainedSubstitution
                . substituteLevelMetas (csLevelAssignments state)
            normalizeAssumptions =
              substituteLevelAssumptions retainedSubstitution
                . substituteLevelAssumptions (csLevelAssignments state)
            projectLevels levels
              | all (< length levels) projection =
                  [levels !! position | position <- projection]
              | otherwise = levels
            memberName level =
              Map.findWithDefault
                ("local#" <> T.pack (show level))
                level
                memberLevels
        when (arity > 0) $
          forM_ occurrences $ \occurrence -> do
            let targetLevels =
                  projectLevels (map normalizeOccurrenceLevel (lrsoLevels occurrence))
                assumptions = normalizeAssumptions (lrsoAssumptions occurrence)
                identity =
                  length sourceLevels == length targetLevels
                    && and (zipWith (==) (map normalizeLevel sourceLevels) targetLevels)
                pointwise =
                  length sourceLevels == length targetLevels
                    && and
                      [ proveLevelLeq assumptions target source == Proved
                      | (target, source) <- zip targetLevels sourceLevels
                      ]
                caller = memberName (lrsoCaller occurrence)
                callee = memberName (lrsoCallee occurrence)
                payload =
                  withPayloadField "caller" caller
                    . withPayloadField "callee" callee
                    . withPayloadField "sourceInstance"
                        (T.intercalate ", " (map renderLevel sourceLevels))
                    . withPayloadField "targetInstance"
                        (T.intercalate ", " (map renderLevel targetLevels))
            unless identity $
              if not (lrsoExplicit occurrence) || not completeExplicitScc
                then
                  report $
                    withPayload
                      ( payload
                          ( withPayloadField "completeExplicitRecursiveScc"
                              (if completeExplicitScc then "true" else "false")
                              (payloadKind "universe-recursive-schema-implicit")
                          )
                      ) $
                      diag SevError StageElaborate
                        "E_UNIVERSE_RECURSIVE_SCHEMA_IMPLICIT"
                        (Just "kappa.universe.recursive-schema")
                        (lrsoSpan occurrence)
                        "a non-identity recursive local declaration-schema call requires an explicit .{...} instance and a complete explicit SCC schema (§11.1.2.3A)"
                else unless pointwise $
                  report $
                    withPayload
                      (payload (payloadKind "universe-recursive-schema-increase")) $
                      diag SevError StageElaborate
                        "E_UNIVERSE_RECURSIVE_SCHEMA_INCREASE"
                        (Just "kappa.universe.recursive-schema")
                        (lrsoSpan occurrence)
                        "a recursive local declaration-schema instance must be pointwise same-or-lower than the current SCC instance (§11.1.2.3A)"

    explicitLocalSchema (LetBind implicit prefix (PVar name) annotation rhs sp) =
      case nameUniverseSchema name of
        Nothing -> Nothing
        Just schema ->
          let strippedName = Name (nameText name) (nameSpan name)
           in Just (schema, LetBind implicit prefix (PVar strippedName) annotation rhs sp)
    explicitLocalSchema _ = Nothing

    -- All members of a recursive local SCC share one declaration-universe
    -- telescope. Canonical names are internal, deterministic, and not
    -- source-spellable, so replacing a source schema name cannot capture an
    -- ordinary binder. A member without a written schema shares the explicit
    -- SCC telescope for identity calls, but the SCC is not "complete
    -- explicit" for the non-identity recursion rule.
    prepareLocalRecursiveGroup group =
      case [(binding, schema) | binding <- group, Just schema <- [bindingSchema binding]] of
        [] -> pure (group, Nothing, False)
        ((_, sourceCanonical) : _) -> do
          let expected = length (usParameters sourceCanonical)
              canonical = internalizeUniverseSchema sourceCanonical
              completeExplicit = all (isJust . bindingSchema) group
          forM_ group $ \binding ->
            case bindingSchema binding of
              Just schema
                | length (usParameters schema) == expected -> pure ()
                | otherwise -> schemaMismatch binding expected (length (usParameters schema))
              Nothing -> pure ()
          pure
            ( map (canonicalizeBindingSchema sourceCanonical canonical) group
            , Just canonical
            , completeExplicit
            )

    bindingSchema LetBind {lbPattern = PVar name} = nameUniverseSchema name
    bindingSchema _ = Nothing

    schemaMismatch :: LetBind -> Int -> Int -> CheckM ()
    schemaMismatch binding expected found =
      errAt (lbSpan binding) "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
        ( "members of one local recursive SCC must expose alpha-equivalent universe schemas; expected "
            <> T.pack (show expected) <> " parameters but found " <> T.pack (show found)
        )

    canonicalizeBindingSchema sourceCanonical canonical binding@LetBind {lbPattern = PVar name} =
      let source = fromMaybe sourceCanonical (nameUniverseSchema name)
          renaming =
            Map.fromList
              (zip (map nameText (usParameters source)) (map nameText (usParameters canonical)))
          rename = renameFreeVarOccurrences renaming
          canonicalName = case nameUniverseSchema name of
            Nothing -> Name (nameText name) (nameSpan name)
            Just _ -> NameWithUniverseSchema (nameText name) (nameSpan name) canonical
       in binding
            { lbPattern = PVar canonicalName
            , lbType = fmap rename (lbType binding)
            , lbExpr = rename (lbExpr binding)
            }
    canonicalizeBindingSchema _ _ binding = binding

    -- an annotated local function may refer to itself (§9.2 mirrored
    -- locally): elaborate the lambda under its own binder
    goBinding continue ctx (LetBind implocal prefix (PVar n) (Just tyE) rhs@ELambda {} sp) rest acc = do
      firstMeta <- gets csNextMeta
      firstConstraint <- gets csNextLevelConstraint
      (tyTm, tyV) <- elabLocalSig ctx tyE
      let q = qOf (bpQuantity prefix)
      typeProducing <- finalIsSort ctx tyV
      let allowParametricRhs = typeProducing && bpObservation prefix /= Just Ordinary
      if allowParametricRhs
        then do
          tm <- check ctx rhs tyV
          (telescope, tyTm', tm') <-
            generalizeLocalDeclarationUniverses
              firstMeta firstConstraint ctx sp [nameText n] tyTm tm
          tyV' <- evalIn ctx tyTm'
          rhsV <- evalIn ctx tm'
          inferredObservation <- observationJudgmentForTerm ctx tm' tyV'
          observation <- resolveLetObservation ctx sp prefix tyV' inferredObservation
          let bindLocal
                | dutParameterCount telescope > 0 =
                    bindCtxLetUniverseMode (nameText n) implocal tyV' rhsV telescope Nothing Nothing (ojMode observation) (Just (ojOrigin observation)) ctx
                | otherwise =
                    bindCtxLetProjOpMode (nameText n) implocal tyV' rhsV Nothing Nothing (ojMode observation) (Just (ojOrigin observation)) ctx
              ctx' = setTopCoreQ q bindLocal
          continue ctx' rest ((ctx, ojMode observation, q, nameText n, telescope, tyTm', tm', False, sourceBinders rhs) : acc)
        else do
          let ctxRec = bindCtx (nameText n) implocal tyV ctx
          tm <- check ctxRec rhs tyV
          (telescope, tyTm', tm') <-
            generalizeLocalDeclarationUniverses
              firstMeta firstConstraint ctx sp [nameText n] tyTm tm
          tyV' <- evalIn ctx tyTm'
          inferredObservation <- observationJudgmentForTerm ctxRec tm' tyV'
          observation <- resolveLetObservation ctxRec sp prefix tyV' inferredObservation
          _ <- pure sp
          let ctxFinal
                | dutParameterCount telescope > 0 =
                    bindCtxLetUniverseMode (nameText n) implocal tyV' (VRigid (ctxLen ctx) []) telescope Nothing Nothing (ojMode observation) (Just (ojOrigin observation)) ctx
                | otherwise =
                    bindCtxLetProjOpMode (nameText n) implocal tyV' (VRigid (ctxLen ctx) []) Nothing Nothing (ojMode observation) (Just (ojOrigin observation)) ctx
          continue ctxFinal rest ((ctx, ojMode observation, q, nameText n, telescope, tyTm', tm', True, sourceBinders rhs) : acc)
    goBinding continue ctx (LetBind implocal prefix pat0 mty rhs sp) rest acc = do
      firstMeta <- gets csNextMeta
      firstConstraint <- gets csNextLevelConstraint
      -- §9.1.2: a let pattern that is a bare capitalized name not naming
      -- any constructor in scope is an ordinary (rebinding) binder,
      -- e.g. `let M = type MaybeBox` (§2.8.3)
      pat <- do
        st <- get
        let isCtor n = any (\g -> gnameText g == nameText n) (Map.keys (csCtors st))
            -- applies recursively inside tuple/record let patterns:
            -- `let (F = G, value = v) = pkg` rebinds the type object
            -- under G (§2.8.4)
            normRebind p = case p of
              PCtor (CtorRef Nothing n) [] _
                | not (isCtor n) -> PVar n
              PTuple ps tsp -> PTuple (map normRebind ps) tsp
              PRecord items mr rsp ->
                PRecord [(o, f, fmap normRebind mp) | (o, f, mp) <- items] mr rsp
              _ -> p
        pure (normRebind pat0)
      (rhsTm0, rhsTy0) <- case mty of
        Just tyE -> do
          (_, tyV) <- elabLocalSig ctx tyE
          typeProducing <- finalIsSort ctx tyV
          let allow = typeProducing && bpObservation prefix /= Just Ordinary
          tm <- check ctx rhs tyV
          pure (tm, tyV)
        Nothing -> do
          (tm, ty) <- case rhs of
            ELambda _ binders lambdaBody lambdaSpan ->
              elabLambdaWith False True ctx binders lambdaBody lambdaSpan Nothing
            _ -> infer ctx rhs
          -- Preserve an inferred polymorphic value at the semantic local
          -- declaration boundary.  Call sites still instantiate its implicit
          -- telescope through the normal application/elimination path.
          pure (tm, ty)
      (rhsTm, rhsTy) <- finalizeResolvedLambda ctx rhs rhsTm0 rhsTy0
      case pat of
        PVar n -> do
          rhsTyTm0 <- quoteIn ctx rhsTy
          (rhsTyTm, rhsTmGeneralized) <-
            if isNothing mty
              then generalizeLocalDeclarationMetas firstMeta ctx sp [nameText n] rhsTyTm0 rhsTm
              else pure (rhsTyTm0, rhsTm)
          (telescope, rhsTyTm', rhsTm') <-
            generalizeLocalDeclarationUniverses
              firstMeta firstConstraint ctx sp [nameText n] rhsTyTm rhsTmGeneralized
          rhsTy' <- evalIn ctx rhsTyTm'
          rhsV <- evalIn ctx rhsTm'
          mPj <- if implocal then pure Nothing else projectionInfoOfExpr ctx rhs
          mOp <- if implocal then pure Nothing else operationValueInfoOfExpr ctx rhs
          inferredObservation <- observationJudgmentForTerm ctx rhsTm' rhsTy'
          observation <- resolveLetObservation ctx sp prefix rhsTy' inferredObservation
          let q = qOf (bpQuantity prefix)
              ctx0'
                | dutParameterCount telescope > 0 =
                    bindCtxLetUniverseMode (nameText n) implocal rhsTy' rhsV telescope mPj mOp (ojMode observation) (Just (ojOrigin observation)) ctx
                | otherwise =
                    bindCtxLetProjOpMode (nameText n) implocal rhsTy' rhsV mPj mOp (ojMode observation) (Just (ojOrigin observation)) ctx
              ctxQ = setTopCoreQ q ctx0'
              ctx1 = if implocal then setTopPrefix sp prefix ctxQ else ctxQ
              -- §7.4.3 stable alias: `let q = p` transports refinement
              ctx' = case rhs of
                EVar pn | Just _ <- lookupCtx (nameText pn) ctx ->
                  addCtxAlias (nameText n) (nameText pn) ctx1
                _ -> ctx1
          continue ctx' rest ((ctx, ojMode observation, q, nameText n, telescope, rhsTyTm', rhsTm', False, sourceBinders rhs) : acc)
        PWild _ -> do
          rhsTyTm <- quoteIn ctx rhsTy
          rhsV <- evalIn ctx rhsTm
          let ctx' = bindCtxLet "_" False rhsTy rhsV ctx
          continue ctx' rest ((ctx, Ordinary, QW, "_", emptyDeclarationUniverseTelescope, rhsTyTm, rhsTm, False, sourceBinders rhs) : acc)
        _ -> do
          rhsTyF <- forceM rhsTy
          let mProj = case (pat, rhsTyF) of
                -- a variables-only tuple/record pattern over a closed
                -- record type destructures by projection, so the
                -- binding normalizes for definitional equality (§31.1)
                (PTuple ps _, VRecordTQ fs)
                  | Just ns <- mapM patVarName ps
                  , length ns == length fs ->
                      Just (zip ns fs)
                (PRecord items Nothing _, VRecordTQ fs)
                  | Just ns <- mapM recItemVar items
                  , sort (map fst ns) == sort (map rfName fs) ->
                      Just
                        [ (fromMaybe Nothing (lookup (rfName field) ns), field)
                        | field <- fs
                        ]
                _ -> Nothing
          case mProj of
            Just named -> do
              rhsTyTm <- quoteIn ctx rhsTy
              rhsV <- evalIn ctx rhsTm
              let scrutN = "__scrut"
                  ctxS = bindCtxLet scrutN False rhsTy rhsV ctx
              let bindFields c _ [] = pure (c, [])
                  bindFields c i ((mn, field) : restFs) = do
                    let f = rfName field
                        mode = rfMode field
                        fieldQ = rfQ field
                        projTm = CProjM mode (CVar i) f
                    projV <- evalIn c projTm
                    fldTy <- substThisInto c (CVar i) (rfType field)
                    fldTyTm <- quoteIn c fldTy
                    let nm = maybe "_" nameText mn
                        c' =
                          setTopCoreQ fieldQ
                            (bindCtxLetProjOpMode nm False fldTy projV Nothing Nothing mode (Just nm) c)
                    (cFin, more) <- bindFields c' (i + 1) restFs
                    pure (cFin, (mode, fieldQ, nm, fldTyTm, projTm) : more)
              (ctxFin, projBinds) <- bindFields ctxS 0 named
              (bodyTm, bodyTy) <- goUnder ctxFin rest
              checkIrrefutable ctx pat rhsTy sp
              let inner = foldr (\(mode, fieldQ, nm, tyT, tm) b -> CLetM mode fieldQ nm tyT tm b) bodyTm projBinds
                  whole = CLetM Ordinary (qOf (bpQuantity prefix)) scrutN rhsTyTm rhsTm inner
              wrapped <- wrapLets acc whole
              pure (wrapped, bodyTy)
            Nothing -> do
              -- irrefutable destructuring: elaborate as single-case
              -- match by rewriting `let pat = rhs; rest` to
              -- `match rhs case pat -> ...`
              (patC, ctx', patternRefinements) <- elabPattern ctx pat rhsTy
              (bodyTm, bodyTy) <-
                withPatternRefinements patternRefinements $ do
                  body <- goUnder ctx' rest
                  checkIrrefutable ctx pat rhsTy sp
                  pure body
              rhsTyTm' <- quoteIn ctx rhsTy
              bodyTyTm <- quoteIn ctx bodyTy
              let matchTm = CMatch rhsTm (Just rhsTyTm') (Just bodyTyTm) [CaseAlt patC Nothing bodyTm]
              wrapped <- wrapLets acc matchTm
              pure (wrapped, bodyTy)
      where
        patVarName = \case
          PVar n -> Just (Just n)
          PWild _ -> Just Nothing
          _ -> Nothing
        recItemVar (False, f, mp) = case mp of
          Nothing -> Just (nameText f, Just f)
          Just (PVar n) -> Just (nameText f, Just n)
          Just (PWild _) -> Just (nameText f, Nothing)
          _ -> Nothing
        recItemVar _ = Nothing
        goUnder c rs = case rs of
          [] -> finish c
          _ -> go c rs []
elabBlock :: Ctx -> [Decl] -> Maybe Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabBlock ctx0 ds0 mfin sp mexpected =
  withLocalNominalEscapeBoundary ctx0 sp $
    case mfin of
      Nothing -> do
        errAt sp "E_BLOCK_NO_RESULT" Nothing "a pure block must end with an expression (§9.3.1)"
        anyHole ctx0
      Just fin -> go ctx0 [] ds0 fin
  where
    finish ctx fin = case mexpected of
      Just expected -> (,expected) <$> check ctx fin expected
      Nothing -> do
        (term, ty) <- infer ctx fin
        insertAllImplicits ctx (exprSpan fin) term ty

    -- Declarations are sequential (§9.3.1). Accumulate only the ordinary
    -- let-like run before the next declaration that changes static scope,
    -- then elaborate that run around a continuation for the remaining block.
    go ctx signatures declarations fin = do
      (bindings, signatures', remaining) <- collectLetRun ctx signatures [] declarations
      if not (null bindings)
        then
          elabLetItemsWith ctx (groupLocalRecursiveBindings bindings) $ \nextCtx ->
            go nextCtx signatures' remaining fin
        else case remaining of
          [] -> finish ctx fin
          DEffect mods effectDecl declarationSpan : rest
            | dmScoped mods && not (effIsLabelDecl effectDecl) -> do
                (nextCtx, wrap) <- elabScopedEffect ctx effectDecl declarationSpan
                (term, ty) <- go nextCtx signatures' rest fin
                pure (wrap term, ty)
            | dmScoped mods && effIsLabelDecl effectDecl -> do
                nextCtx <- elabScopedEffectLabel ctx effectDecl declarationSpan
                go nextCtx signatures' rest fin
          DData mods dataDecl declarationSpan : rest ->
            withLocalDataDeclaration ctx mods dataDecl declarationSpan $
              go ctx signatures' rest fin
          declaration : rest -> do
            unsupportedAt (declSpan declaration)
              "this local declaration form is not supported inside block by this implementation"
            go ctx signatures' rest fin

    collectLetRun _ signatures acc [] = pure (reverse acc, signatures, [])
    collectLetRun activeCtx signatures acc declarations@(d : rest) = case d of
      -- A signature is a sequential declaration but does not itself emit
      -- Core. Its contract remains available to a later definition.
      DSig _ n tyE _ ->
        collectLetRun activeCtx ((nameText n, n, tyE) : signatures) acc rest
      DLet mods definition dsp
        | Just _ <- ldConstructorPatternCandidate definition -> do
            let governed =
                  case ldName definition of
                    Just name ->
                      any
                        (\(source, _, _) -> source == nameText name)
                        signatures
                    Nothing -> False
            if governed
              then
                collectLetRun
                  activeCtx
                  signatures
                  acc
                  (DLet mods definition {ldConstructorPatternCandidate = Nothing} dsp : rest)
              else do
                selected <- selectConstructorPatternLet activeCtx dsp definition
                case selected of
                  Just (ConstructorPatternCandidate pattern' rhs) ->
                    collectLetRun
                      activeCtx
                      signatures
                      ( LocalLetBinding
                          ( LetBind
                              False
                              (ldPrefix definition)
                              pattern'
                              (ldResultType definition)
                              rhs
                              dsp
                          )
                          : acc
                      )
                      rest
                  Nothing ->
                    collectLetRun
                      activeCtx
                      signatures
                      acc
                      (DLet mods definition {ldConstructorPatternCandidate = Nothing} dsp : rest)
      DLet _ (LetDef (Just n) _ Nothing _ _ [] mty Nothing rhs) dsp -> do
        (headerName, annotation, rhs') <- localHeader n mty rhs signatures dsp
        collectLetRun activeCtx signatures
          (LocalLetBinding (LetBind False emptyPrefix (PVar headerName) annotation rhs' sp) : acc)
          rest
      DLet _ (LetDef (Just n) _ Nothing _ _ bs mty _ rhs) dsp -> do
        -- local named function: elaborate as lambda
        let lam0 = ELambda Nothing bs (maybe rhs (\t -> EAscription rhs t dsp) mty) dsp
        (headerName, annotation, lam) <- localHeader n Nothing lam0 signatures dsp
        collectLetRun activeCtx signatures
          (LocalLetBinding (LetBind False emptyPrefix (PVar headerName) annotation lam sp) : acc)
          rest
      DLet _ (LetDef Nothing imp (Just p) _ prefix [] mty Nothing rhs) _ ->
        collectLetRun activeCtx signatures
          (LocalLetBinding (LetBind imp prefix p mty rhs sp) : acc)
          rest
      -- a local type alias is a type-level let binding (§9.3.1, §10.2)
      DTypeAlias _ n params mkind (Just rhs) dsp ->
        let resultKind = fromMaybe (EVar (Name "Type" dsp)) mkind
            body = case params of
              [] -> rhs
              bs -> ELambda Nothing bs rhs dsp
            ann = Just (foldr EArrow resultKind params)
            parametricPrefix = BinderPrefix (Just Parametric) (Just S.QZero) Nothing
         in collectLetRun activeCtx signatures
              (LocalLetBinding (LetBind False parametricPrefix (PVar n) ann body sp) : acc)
              rest
      _ -> pure (reverse acc, signatures, declarations)
    localHeader definitionName inlineType rhs sigs declarationSpan = do
      let signature =
            listToMaybe
              [ (signatureName, signatureType)
              | (text, signatureName, signatureType) <- sigs
              , text == nameText definitionName
              ]
          signatureSchema = signature >>= nameUniverseSchema . fst
          definitionSchema = nameUniverseSchema definitionName
          schemaArity = maybe 0 (length . usParameters)
      case signature of
        Just _
          | Just _ <- definitionSchema
          , schemaArity signatureSchema /= schemaArity definitionSchema ->
              errAt declarationSpan "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
                ( "the signature and definition of local declaration '" <> nameText definitionName
                    <> "' must expose alpha-equivalent universe schemas; signature has "
                    <> T.pack (show (schemaArity signatureSchema)) <> " parameters and definition has "
                    <> T.pack (show (schemaArity definitionSchema))
                )
        _ -> pure ()
      let canonicalSource = signatureSchema <|> definitionSchema
          canonicalSchema = internalizeUniverseSchema <$> canonicalSource
          definitionSource = definitionSchema <|> signatureSchema
          annotationSource =
            if isJust inlineType
              then definitionSource
              else signatureSchema
          renameFrom source =
            renameFreeVarOccurrences . Map.fromList $ case (source, canonicalSchema) of
              (Just sourceSchema, Just canonical) ->
                zip
                  (map nameText (usParameters sourceSchema))
                  (map nameText (usParameters canonical))
              _ -> []
          headerName = case canonicalSchema of
            Nothing -> Name (nameText definitionName) (nameSpan definitionName)
            Just schema -> NameWithUniverseSchema (nameText definitionName) (nameSpan definitionName) schema
          annotation = fmap (renameFrom annotationSource) (inlineType <|> fmap snd signature)
      pure (headerName, annotation, renameFrom definitionSource rhs)

    -- Signed local declarations are dependency-sorted by semantic SCC.  A
    -- cyclic singleton is just as much an SCC as a mutually recursive group:
    -- both must elaborate under one shared local-universe telescope so every
    -- recursive occurrence carries an explicit 'CLocal' specialization.
    -- Unsigned/non-function bindings remain source-sequential boundaries.
    groupLocalRecursiveBindings [] = []
    groupLocalRecursiveBindings items@(item : rest)
      | isSignedFunction item =
          let (run, suffix) = span isSignedFunction items
              bindings = [binding | LocalLetBinding binding <- run]
              names = Set.fromList (mapMaybe localBindingName bindings)
              dependencies binding =
                [ dependency
                | occurrence <-
                    maybe [] freeVarOccurrencesScoped (lbType binding)
                      ++ freeVarOccurrencesScoped (lbExpr binding)
                , let dependency = nameText occurrence
                , dependency `Set.member` names
                ]
              graph =
                [ (binding, name, dependencies binding)
                | binding <- bindings
                , Just name <- [localBindingName binding]
                ]
              emit = \case
                AcyclicSCC binding -> [LocalLetBinding binding]
                CyclicSCC members -> [LocalLetRecursiveGroup members]
           in concatMap emit (stronglyConnComp graph)
                ++ groupLocalRecursiveBindings suffix
      | otherwise = item : groupLocalRecursiveBindings rest

    isSignedFunction = \case
      LocalLetBinding LetBind {lbPattern = PVar _, lbType = Just _, lbExpr = ELambda {}} -> True
      _ -> False
    localBindingName LetBind {lbPattern = PVar name} = Just (nameText name)
    localBindingName _ = Nothing

-- | Enforce §9.3.1.1/§30.1.1 at the common lexical boundary for both pure
-- blocks and do blocks. Scoped declarations remain in the semantic tables so
-- malformed downstream Core cannot forget their status, but a successful
-- result may not expose an identity introduced by this scope. Runtime values
-- whose interface omits the family remain admissible; compile-time values and
-- monadic compile-time payloads additionally inspect their result term.
withLocalNominalEscapeBoundary
  :: Ctx
  -> Span
  -> CheckM (Term, Value)
  -> CheckM (Term, Value)
withLocalNominalEscapeBoundary outerCtx site action = do
  before <- gets (Map.keysSet . csScopedLocalNominals)
  result@(term, resultType) <- action
  st <- get
  let introduced = Map.keysSet (csScopedLocalNominals st) `Set.difference` before
  unless (Set.null introduced) $ do
    resultTypeTerm <- quoteIn outerCtx resultType
    typeDependencies <- expandedGlobalsOfTermM resultTypeTerm
    inspectTerm <- resultMayCarryCompileTimeValue resultType
    termDependencies <-
      if inspectTerm then expandedGlobalsOfTermM term else pure Set.empty
    let escaped =
          Set.intersection introduced (Set.union typeDependencies termDependencies)
    unless (Set.null escaped) $ do
      let escapedNames = sort (map gnameText (Set.toList escaped))
          declarationSites =
            [ related RoleDeclarationSite declarationSite
                "scoped local nominal declared here"
            | identity <- Set.toList escaped
            , Just declarationSite <- [Map.lookup identity (csScopedLocalNominals st)]
            ]
          diagnostic =
            withPayload
              ( withPayloadField "phase" "local-nominal-escape-check" $
                  withPayloadField "escapedIdentities" (T.intercalate "," escapedNames) $
                    payloadKind "local-nominal-scope-escape"
              ) $
              diag SevError StageElaborate "E_LOCAL_NOMINAL_SCOPE_ESCAPE"
                (Just "kappa-hs.local-nominal.scope-escape") site
                ( "this block result transparently exposes scoped local nominal "
                    <> T.intercalate ", " escapedNames
                    <> "; scoped local families and their nominal-scope dependencies may not escape their lexical block (§9.3.1.1, §30.1.1)"
                )
      report (withRelateds declarationSites diagnostic)
  pure result
  where
    resultMayCarryCompileTimeValue value =
      forceM value >>= \case
        VSort {} -> pure True
        VGlobN global arguments
          | global `elem` [prelIO, prelEff, prelSTM, prelElab]
          , not (null arguments) ->
              resultMayCarryCompileTimeValue (snd (last arguments))
        _ -> pure False

-- | Elaborate one block-local data family through the ordinary typed data
-- pipeline while giving it a declaration-site identity distinct from every
-- source-spelled module declaration.  The generated family remains in the
-- semantic environment because escaped ordinary local families are legal;
-- only its source spelling is restored at the lexical boundary (§30.1.1).
--
withLocalDataDeclaration
  :: Ctx
  -> DeclMods
  -> DataDecl
  -> Span
  -> CheckM a
  -> CheckM a
withLocalDataDeclaration ctx mods dataDecl declarationSpan continuation = do
  validateLocalNominalModifiers mods declarationSpan
  (captureCtx, captureTele, captures) <- localDataCaptureTelescope ctx dataDecl
  renamed <- renameLocalDataDeclaration dataDecl declarationSpan
  let declaration = DData noMods renamed declarationSpan
      sourceNames =
        (nameText (ddName dataDecl), nameText (ddName renamed))
          : zip
              (map (nameText . cdName) (ddCtors dataDecl))
              (map (nameText . cdName) (ddCtors renamed))
  currentModule <- gets csModule
  savedLocalScope <- gets csLocalDeclScope
  savedCaptures <- gets csLocalNominalCaptures
  let localScope =
        foldl'
          (\scope (source, generated) ->
             Map.insert source (GName currentModule generated) scope)
          savedLocalScope
          sourceNames
      dataIdentity = GName currentModule (nameText (ddName renamed))
      ctorIdentities =
        Set.fromList
          [ GName currentModule (nameText (cdName constructor))
          | constructor <- ddCtors renamed
          ]
      allIdentities = Set.insert dataIdentity ctorIdentities
      capturePositions = Map.fromList (zip (map lncLevel captures) [0 ..])
      syntheticCaptures =
        [ LocalNominalCapture (lncName capture) position
        | (capture, position) <- zip captures [0 ..]
        ]
      remapExisting existing =
        case traverse (\capture ->
                LocalNominalCapture (lncName capture)
                  <$> Map.lookup (lncLevel capture) capturePositions) existing of
          Just remapped -> remapped
          Nothing -> existing
      headerCaptures =
        foldl'
          (\table identity -> Map.insert identity syntheticCaptures table)
          (Map.map remapExisting savedCaptures)
          (Set.toList allIdentities)
  modify' $ \st ->
    st
      { csLocalDeclScope = localScope
      , csLocalNominalCaptures = headerCaptures
      , csScopeNameCache = Nothing
      }
  beforeGlobals <- gets (Map.keysSet . csGlobals)
  beforeCtors <- gets (Map.keysSet . csCtors)
  withLocalDeclarationUniverseSchema True (nameUniverseSchema (ddName renamed)) $ \restoreSchema -> do
    headerDataIn captureCtx captureTele renamed declarationSpan
    positivityPass [declaration]
    flushPendingFinal
    generalizeDeclarationUniverses
      beforeGlobals
      beforeCtors
      (Set.singleton dataIdentity)
      ctorIdentities
      Set.empty
    restoreSchema
  modify' $ \st ->
    let finalCaptures =
          foldl'
            (\table identity -> Map.insert identity captures table)
            savedCaptures
            (Set.toList allIdentities)
        scoped =
          if dmScoped mods
            then foldl' (\table identity -> Map.insert identity declarationSpan table)
                   (csScopedLocalNominals st) (Set.toList allIdentities)
            else csScopedLocalNominals st
     in st
          { csLocalNominalCaptures = finalCaptures
          , csScopedLocalNominals = scoped
          }
  result <- continuation
  modify' $ \st ->
    st
      { csLocalDeclScope = savedLocalScope
      , csScopeNameCache = Nothing
      }
  pure result
  where
    validateLocalNominalModifiers declarationMods site = do
      when (dmVisibility declarationMods /= VisDefault) $
        errAt site "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
          "public/private modifiers are not permitted on local declarations (§9.3.1)"
      when (dmOpaque declarationMods) $
        errAt site "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
          "opaque is not permitted on local declarations (§9.3.1)"

-- | Declaration-site names are stable for one checker run and unspellable by
-- source lookup.  Preserve the written universe schema: it is part of the
-- declaration interface, not of textual symbol identity.
renameLocalDataDeclaration :: DataDecl -> Span -> CheckM DataDecl
renameLocalDataDeclaration declaration declarationSpan = do
  dataText <- stableGeneratedNameAt "local-data" (nameText (ddName declaration)) declarationSpan
  constructorTexts <-
    forM (ddCtors declaration) $ \constructor ->
      if nameText (cdName constructor) == nameText (ddName declaration)
        then pure dataText
        else stableGeneratedNameAt "local-constructor" (nameText (cdName constructor)) (nameSpan (cdName constructor))
  let renameName text source =
        case nameUniverseSchema source of
          Nothing -> Name text (nameSpan source)
          Just schema -> NameWithUniverseSchema text (nameSpan source) schema
      renamedConstructors =
        [ constructor {cdName = renameName text (cdName constructor)}
        | (constructor, text) <- zip (ddCtors declaration) constructorTexts
        ]
  pure
    declaration
      { ddName = renameName dataText (ddName declaration)
      , ddCtors = renamedConstructors
      }

-- | Conservative source-level capture set for local data interfaces. Names
-- bound by the data/constructor telescopes are removed before consulting the
-- semantic local context. False negatives would be unsound; false positives
-- only take the explicit fail-closed path above.
localDataCaptures :: Ctx -> DataDecl -> [Text]
localDataCaptures ctx declaration =
  sort . nub $
    [ occurrence
    | expression <- expressionsIn declaration
    , name <- freeVarOccurrences expression
    , let occurrence = nameText name
    , occurrence `Set.notMember` declarationBinders
    , isJust (lookupCtx occurrence ctx)
    ]
  where
    declarationBinders =
      Set.fromList $
        mapMaybe (fmap nameText . bName) (ddParams declaration)
          ++ concatMap
               (mapMaybe (fmap nameText . bName) . cdBinders)
               (ddCtors declaration)
    expressionsIn :: Data a => a -> [Expr]
    expressionsIn value =
      case cast value of
        Just expression -> [expression]
        Nothing -> concat (gmapQ expressionsIn value)

-- | Build the exact closure-converted capture telescope of a local data
-- family. Direct source references select semantic binder levels; types of
-- those binders add their transitive dependencies. References to an earlier
-- local nominal add that family's already-closed capture set rather than its
-- source spelling.
localDataCaptureTelescope
  :: Ctx
  -> DataDecl
  -> CheckM (Ctx, Telescope, [LocalNominalCapture])
localDataCaptureTelescope original declaration = do
  st <- get
  let directNames = localDataCaptures original declaration
      directLevels =
        [ ctxLen original - index - 1
        | name <- directNames
        , Just (index, _) <- [lookupCtx name original]
        ]
      nominalLevels =
        [ lncLevel capture
        | name <- freeDeclarationNames declaration
        , Just nominal <- [Map.lookup name (csLocalDeclScope st)]
        , capture <- Map.findWithDefault [] nominal (csLocalNominalCaptures st)
        ]
  levels <- closeCaptureLevels (Set.fromList (directLevels ++ nominalLevels))
  let ordered = sort (Set.toList levels)
      positions = Map.fromList (zip ordered [0 ..])
  (captureCtx, telescope) <- foldM (appendCapture positions) (emptyCtx, []) ordered
  let captures =
        [ LocalNominalCapture (ceName (entryAtLevel level)) level
        | level <- ordered
        ]
  pure (captureCtx, telescope, captures)
  where
    entryAtLevel level = ctxEntries original !! (ctxLen original - level - 1)

    freeDeclarationNames :: Data a => a -> [Text]
    freeDeclarationNames value =
      case cast value of
        Just expression -> map nameText (freeVarOccurrences expression)
        Nothing -> concat (gmapQ freeDeclarationNames value)

    closeCaptureLevels selected = do
      dependencies <- fmap Set.unions $
        forM (Set.toList selected) $ \level -> do
          typeTerm <- quoteIn original (ceType (entryAtLevel level))
          pure (ambientTermLevels (ctxLen original) typeTerm)
      let next = Set.union selected dependencies
      if next == selected then pure selected else closeCaptureLevels next

    appendCapture positions (captureCtx, telescope) oldLevel = do
      rawType <- quoteIn original (ceType (entryAtLevel oldLevel))
      let newDepth = length telescope
          closedType = reindexAmbientTerm (ctxLen original) positions newDepth rawType
          sourceEntry = entryAtLevel oldLevel
      unless (termScopedAt newDepth closedType) $
        report $
          withPayload
            ( withPayloadField "capture" (ceName sourceEntry) $
                payloadKind "local-declaration-capture-interface"
            ) $
            diag SevError StageElaborate "E_LOCAL_DECLARATION_CAPTURE_INTERFACE"
              (Just "kappa.internal.compiler") (ceOrigin sourceEntry)
              ( "the capture type of '" <> ceName sourceEntry
                  <> "' could not be closed over the local declaration's semantic capture telescope"
              )
      typeValue <- evalIn captureCtx closedType
      let mode = ceMode sourceEntry
          quantity = ceCoreQ sourceEntry
          borrowed = ceBorrow sourceEntry
      formation <- selectFormationMode captureCtx mode typeValue
      let
          telescopeEntry =
            TelescopeEntry Impl mode formation quantity borrowed (ceName sourceEntry) closedType Nothing
          nextCtx = bindCtxMQB mode quantity (ceName sourceEntry) True borrowed typeValue captureCtx
      pure (nextCtx, telescope ++ [telescopeEntry])

-- | Free declaration-site binder levels mentioned by a typed term, including
-- levels embedded in universe indices and replayable lift evidence.
ambientTermLevels :: Int -> Term -> Set Int
ambientTermLevels ambient term =
  Set.fromList (termLevels ++ solverLevels)
  where
    termLevels = foldTermWithDepth termVariable 0 term
    termVariable depth = \case
      CVar index | index >= depth -> [ambient - (index - depth) - 1]
      CLocal index _ | index >= depth -> [ambient - (index - depth) - 1]
      _ -> []
    solverLevels =
      [ level
      | level <- foldTerm levelVariables (const []) term
      , level >= 0
      , level < ambient
      ]
    levelVariables = \case
      CGlobal _ universes -> concatMap levelVars universes
      CLocal _ universes -> concatMap levelVars universes
      CSort level -> levelVars level
      CLevel level -> levelVars level
      CUniverseLift from to evidence _ ->
        concatMap levelVars
          ( from : to
              : concatMap
                  (\step -> uesLower step : uesUpper step
                    : concatMap (\(lower, upper) -> [lower, upper]) (uesAssumptions step))
                  (ueSteps evidence)
          )
      _ -> []

-- | Rebase a term from an arbitrary declaration-site context to the ordered
-- capture telescope. Bound variables introduced inside the term remain bound;
-- ambient term indices and absolute level variables are transported together.
reindexAmbientTerm :: Int -> Map Int Int -> Int -> Term -> Term
reindexAmbientTerm oldAmbient positions newAmbient =
  zonkTermWith (\_ _ -> Nothing) reindexLevel 0
    . mapTermWithDepth reindexVariable 0
  where
    reindexVariable depth = \case
      CVar index | index >= depth ->
        let oldLevel = oldAmbient - (index - depth) - 1
         in CVar . (depth +) . (newAmbient - 1 -) <$> Map.lookup oldLevel positions
      CLocal index universes | index >= depth ->
        let oldLevel = oldAmbient - (index - depth) - 1
         in (\newLevel -> CLocal (depth + newAmbient - newLevel - 1) universes)
              <$> Map.lookup oldLevel positions
      _ -> Nothing

    reindexLevel = normalizeLevel . go
    go = \case
      LZero -> LZero
      LFinite value -> LFinite value
      LOmega -> LOmega
      LSucc level -> LSucc (go level)
      LAdd left right -> LAdd (go left) (go right)
      LMax left right -> LMax (go left) (go right)
      LNeutral atom -> LNeutral (mapNeutralLevelAtomLevels go atom)
      LVar level -> LVar (reindexAbsolute level)
      LProjection level fields -> LProjection (reindexAbsolute level) fields
      LParam parameter -> LParam parameter
      LField identity field -> LField identity field
      LMeta meta -> LMeta meta

    reindexAbsolute level
      | level < oldAmbient = Map.findWithDefault level level positions
      | otherwise = newAmbient + level - oldAmbient

-- ── Algebraic effects (§9.3.1.1, §18.1.14–§18.1.22) ──────────────────
--
-- Runtime model (realized by 'Kappa.Eval.evalEffPrim'): an @Eff r a@
-- value is a tree — @__EffPure v@, or @__EffOp label op payload cont@
-- with @cont@ the captured continuation from the operation site
-- (§30.2.2.7 OpCall). Handlers elaborate to @__handleEff@ applications;
-- the continuation is an ordinary closure, so resumption is naturally
-- re-entrant (one-shot/multi-shot discipline is enforced statically by
-- 'Kappa.Usage').

-- | §9.3.1.1/§18.1.15: a local @scoped effect l : E@ introduces a fresh
-- effect label @l@ for the lexical scope that shares the operations and
-- interface of an effect @E@ already in scope (scoped or top-level).
elabScopedEffectLabel :: Ctx -> EffectDecl -> Span -> CheckM Ctx
elabScopedEffectLabel ctx eff dsp = do
  let lblName = nameText (effName eff)
  case effLabelType eff of
    Just ifaceE -> do
      visible <- effMerged ctx
      mresolved <- resolveEffectLabelInterface ctx dsp ifaceE visible
      case mresolved of
        Just (base, universes, args) -> do
          st0 <- get
          identity <- stableGeneratedNameAt "scoped-effect-label" lblName dsp
          let labelG = GName (csModule st0) (identity <> ".label")
          labelType <- globalValueM prelEffLabel []
          addGlobal labelG (GlobalDef labelType Nothing False)
          recordCoreBody labelG (CLit (LitStr (effLabelKey labelG)))
          let alias =
                base
                  { eliLabel = labelG
                  , eliFixedArgs = Just args
                  , eliFixedUniverses = Just universes
                  }
          pure ctx {ctxEffLabels = Map.insert lblName alias (ctxEffLabels ctx)}
        Nothing -> pure ctx
    Nothing -> do
      errAt dsp "E_EFFECT_LABEL_FORM" (Just "kappa-hs.effect.label")
        ("'scoped effect " <> lblName <> " : E' requires a concrete application of a named effect in scope (§18.1.15)")
      pure ctx

-- | §18.1.15 effect type parameters (e.g. @effect State (s : Type)@): bind
-- each parameter as a local in @ctx@ (so later parameters and the operation
-- signatures may reference earlier ones) and retain their complete telescope
-- contracts. Reconstructing these binders as parametric quantity-zero binders
-- used to change explicitly ordinary effect parameters during operation
-- selection and handler skolemization.
elabEffParams :: Ctx -> [Binder] -> CheckM (Ctx, Telescope)
elabEffParams ctx binders = do
  params <- elabTele ctx binders
  ctx' <- extendTeleCtx ctx params
  pure (ctx', params)

-- | Elaborate an effect interface's parameters and operations (§18.1.15),
-- shared by the top-level and scoped forms. Returns the parameter binders, the
-- interface kind term (@k0 -> … -> Type@, just @Type@ when unparameterized),
-- and the operation metadata (each operation's payload/result type quoted
-- under the parameter binders).
elabEffInterface :: Ctx -> EffectDecl -> CheckM (Telescope, Term, [EffOpInfo])
elabEffInterface ctx eff = do
  (ctxP, params) <- elabEffParams ctx (effParams eff)
  let ifaceKindTm = foldr telePi (CSort LZero) params
  ops <- fmap catMaybes . forM (effOps eff) $ \op -> do
    (tyTm, _) <- inferType ctxP (eoType op)
    tyV <- evalIn ctxP tyTm >>= forceM
    -- §18.1.15/§18.1.21: an operation signature is, after elaborating outer
    -- foralls, @forall (impl…). Π(x₁:A₁)…(xₙ:Aₙ). B@. Peel the leading IMPLICIT
    -- binders as the operation's own implicit parameters (bound in the local
    -- context so the argument/result types may reference them), then every
    -- explicit Pi as an argument, leaving @B@ as the final codomain.
    let peelImpl ctxC accI t = case t of
          VPiBoundFormedM mode formation Impl q borrowed inm assumption dom clo -> do
            kT <- quoteIn ctxC dom
            let entry = TelescopeEntry Impl mode formation q borrowed inm kT assumption
                ctxC' = bindCtxMQB mode q inm True borrowed dom ctxC
            res <- clApp clo (VRigid (ctxLen ctxC) []) >>= forceM
            peelImpl ctxC' (accI ++ [entry]) res
          _ -> pure (ctxC, accI, t)
        peelArgs ctxC accA t = case t of
          VPiBoundFormedM mode formation Expl q borrowed name assumption dom clo -> do
            argT <- quoteIn ctxC dom
            let entry = TelescopeEntry Expl mode formation q borrowed name argT assumption
                ctxC' = bindCtxMQB mode q name False borrowed dom ctxC
            res <- clApp clo (VRigid (ctxLen ctxC) []) >>= forceM
            peelArgs ctxC' (accA ++ [entry]) res
          _ -> do
            resT <- quoteIn ctxC t
            pure (accA, resT)
    (ctxI, implicits, afterImpl) <- peelImpl ctxP [] tyV
    (args, resT) <- peelArgs ctxI [] afterImpl
    if null args
      then do
        errAt (eoSpan op) "E_EFFECT_OP_SIGNATURE" (Just "kappa-hs.effect.operation")
          "an effect operation signature must elaborate to a function type (§18.1.15)"
        pure Nothing
      else
        pure
          ( Just
              EffOpInfo
                { eoiName = nameText (eoName op)
                , eoiQ = maybe Q1 (qOf . Just) (eoQuantity op) -- §18.1.17 one-shot default
                , eoiImplicits = implicits
                , eoiArgs = args
                , eoiResT = resT
                }
          )
  pure (params, ifaceKindTm, ops)

-- | §18.1.16/§18.1.17: record the MULTI-SHOT operation names (resumption
-- quantity ω or 1+) of an effect declaration, for the §34.3.3 native-backend
-- capability gate (rt-multishot-effects absent).  Called for both scoped and top-level
-- effect declarations so scoped-effect multi-shot ops are covered too.
recordMultishotOps :: [EffOpInfo] -> CheckM ()
recordMultishotOps ops =
  let names = [eoiName op | op <- ops, eoiQ op `elem` [QW, QGe1]]
   in unless (null names) $
        modify' $ \st -> st {csMultishotOps = foldr Set.insert (csMultishotOps st) names}

elabScopedEffect :: Ctx -> EffectDecl -> Span -> CheckM (Ctx, Term -> Term)
elabScopedEffect ctx eff dsp = do
  let nm = nameText (effName eff)
  st0 <- get
  identity <- stableGeneratedNameAt "scoped-effect" nm dsp
  let ifaceG = GName (csModule st0) identity
      labelG = GName (csModule st0) (identity <> ".label")
  firstMeta <- gets csNextMeta
  firstConstraint <- gets csNextLevelConstraint
  withActiveUniverseDefinition ifaceG $
    withLocalDeclarationUniverseSchema False (nameUniverseSchema (effName eff)) $ \_restore -> do
      (params, ifaceKindTm, ops) <- elabEffInterface ctx eff
      recordMultishotOps ops
      ifaceKindV <- evalIn ctx ifaceKindTm
      -- The interface is a (possibly parameterized) local type constructor;
      -- the label is an opaque value of type EffLabel whose identity is its
      -- global name (§18.1.18 handler matching is by label identity).
      addGlobal ifaceG (GlobalDef ifaceKindV Nothing False)
      labelT <- globalValueM prelEffLabel []
      addGlobal labelG (GlobalDef labelT Nothing False)
      recordCoreBody labelG (CLit (LitStr (effLabelKey labelG)))
      let rawInfo =
            EffLabelInfo
              { eliLabel = labelG
              , eliIface = ifaceG
              , eliParams = params
              , eliFixedArgs = Nothing
              , eliFixedUniverses = Nothing
              , eliOps = ops
              }
          roleTerms =
            [ effectOperationInterfaceTerm rawInfo operation
            | operation <- ops
            ]
      (telescope, ifaceKindTm', _, retained) <-
        generalizeLocalDeclarationUniversesWithRoles
          firstMeta
          firstConstraint
          ctx
          (nameSpan (effName eff))
          [nm]
          roleTerms
          ifaceKindTm
          ifaceKindTm
      assignments <- gets csLevelAssignments
      let parameterCount = dutParameterCount telescope
          abstractLevel =
            if dutExplicit telescope
              then substituteLevelMetas assignments
              else
                substituteLevelMetas (Map.fromList (zip retained (map LParam [0 ..])))
                  . abstractLocalLevelParams parameterCount
                  . substituteLevelMetas assignments
          transform = zonkTermWith (\_ _ -> Nothing) abstractLevel 0
          transformLevel level =
            case transform (CSort level) of
              CSort transformed -> transformed
              _ -> level
          transformAssumption =
            fmap (\(lower, upper) -> (transformLevel lower, transformLevel upper))
          transformEntry entry =
            entry
              { teDomain = transform (teDomain entry)
              , teLevelAssumption = transformAssumption (teLevelAssumption entry)
              }
          transformOperation operation =
            operation
              { eoiImplicits = map transformEntry (eoiImplicits operation)
              , eoiArgs = map transformEntry (eoiArgs operation)
              , eoiResT = transform (eoiResT operation)
              }
          info =
            rawInfo
              { eliParams = map transformEntry params
              , eliOps = map transformOperation ops
              }
      ifaceKindV' <- evalIn ctx ifaceKindTm'
      modify' $ \st ->
        st
          { csGlobals =
              Map.adjust
                (\definition -> definition {gdType = ifaceKindV', gdUniverses = telescope})
                ifaceG
                (csGlobals st)
          , csEffectInterfaces = Map.insert ifaceG info (csEffectInterfaces st)
          , csFinalizedUniverseInterfaces =
              Set.insert ifaceG (csFinalizedUniverseInterfaces st)
          }
      -- A scoped effect interface owns a declaration-universe schema even
      -- though its source spelling is lexical.  The generated local and every
      -- operation occurrence cross that same semantic interface boundary.
      ifaceValue <- globalValueM ifaceG []
      ifaceHead <- globalHeadM ifaceG
      let boundCtx
            | parameterCount > 0 =
                bindCtxLetUniverseMode
                  nm False ifaceKindV' ifaceValue telescope
                  Nothing Nothing Ordinary Nothing ctx
            | otherwise =
                bindCtxLetProjOpMode
                  nm False ifaceKindV' ifaceValue Nothing Nothing Ordinary Nothing ctx
          ctx' =
            (setTopCoreQ Q0 boundCtx)
              { ctxEffLabels = Map.insert nm info (ctxEffLabels ctx)
              }
          wrap body
            | parameterCount > 0 =
                CLetPolyM Ordinary Q0 nm telescope ifaceKindTm' ifaceHead body
            | otherwise = CLetM Ordinary Q0 nm ifaceKindTm' ifaceHead body
      pure (ctx', wrap)

-- | Effect-label resolution (§18.1): a §9.3.1.1 lexically scoped effect in
-- 'ctxEffLabels' wins; otherwise a module-level (top-level) @effect@
-- declaration in 'csModEffLabels' is visible everywhere in the module.
-- | §18.1.18: the unique runtime identity string of an effect label (its
-- fully-qualified global name), used as the native label token.
effLabelKey :: GName -> Text
effLabelKey (GName (ModuleName segs) nm) = T.intercalate "." (segs ++ [nm])

lookupEffLabelM :: Ctx -> Text -> CheckM (Maybe EffLabelInfo)
lookupEffLabelM ctx nm = case Map.lookup nm (ctxEffLabels ctx) of
  Just e -> pure (Just e)
  Nothing -> gets (Map.lookup nm . csModEffLabels)

-- | The scoped (§9.3.1.1) and top-level (§18.1) effect labels visible here,
-- merged (scoped wins), for use in pure pattern guards.
effMerged :: Ctx -> CheckM (Map Text EffLabelInfo)
effMerged ctx = gets (\st -> Map.union (ctxEffLabels ctx) (csModEffLabels st))

-- | §18.1: elaborate a TOP-LEVEL @effect@ declaration. Like a scoped effect
-- it mints an opaque interface type + label value and computes the operation
-- signatures, but it registers them as module globals and records the
-- interface in 'csModEffLabels' (visible module-wide) and the type name in
-- the import scope, rather than as a lexically scoped local.
elabTopEffect :: EffectDecl -> Span -> CheckM ()
elabTopEffect eff _dsp = do
  let nm = nameText (effName eff)
  already <- gets (Map.member nm . csModEffLabels)
  unless already $ do
    st0 <- get
    let ifaceG = GName (csModule st0) nm
        labelG = GName (csModule st0) (nm <> ".label")
    (params, ifaceKindTm, ops) <- elabEffInterface emptyCtx eff
    recordMultishotOps ops
    ifaceKindV <- evalIn emptyCtx ifaceKindTm
    addGlobal ifaceG (GlobalDef ifaceKindV Nothing False)
    labelT <- globalValueM prelEffLabel []
    addGlobal labelG (GlobalDef labelT Nothing False)
    -- §18.1.18: the label's runtime identity is its (unique) global name.
    -- The interpreter uses the neutral global; the native backend has no
    -- neutral globals, so record a string-token core body for it (label
    -- equality in the native effect runtime is string equality).
    recordCoreBody labelG (CLit (LitStr (effLabelKey labelG)))
    -- the effect type name resolves module-wide as its interface (type
    -- constructor when parameterized, §18.1.15)
    modify' $ \st -> st {csScope = Map.insert nm ifaceG (csScope st)}
    let info =
          EffLabelInfo
            { eliLabel = labelG
            , eliIface = ifaceG
            , eliParams = params
            , eliFixedArgs = Nothing
            , eliFixedUniverses = Nothing
            , eliOps = ops
            }
    modify' $ \st ->
      st
        { csModEffLabels = Map.insert nm info (csModEffLabels st)
        , csEffectInterfaces = Map.insert ifaceG info (csEffectInterfaces st)
        }

-- | §18.1.15: a top-level @effect label l : E@ mints a fresh effect label
-- @l@ that shares the operations and interface of an existing effect @E@
-- (so several labels can name distinct instances of one effect). The new
-- label gets its own identity; its operations and interface are E's.
elabTopEffectLabel :: EffectDecl -> Span -> CheckM ()
elabTopEffectLabel eff sp = do
  let lblName = nameText (effName eff)
  unless (null (effParams eff)) $
    reportUnsupported sp "effect-label declaration parameters"
  case effLabelType eff of
    Just ifaceE -> do
      visible <- gets csModEffLabels
      mresolved <- resolveEffectLabelInterface emptyCtx sp ifaceE visible
      case mresolved of
        Just (base, universes, args) -> do
          already <- gets (Map.member lblName . csModEffLabels)
          unless already $ do
            st0 <- get
            let labelG = GName (csModule st0) (lblName <> ".label")
            labelT <- globalValueM prelEffLabel []
            addGlobal labelG (GlobalDef labelT Nothing False)
            recordCoreBody labelG (CLit (LitStr (effLabelKey labelG)))
            -- same interface + operations as E, but a fresh label identity
            modify' $ \st ->
              let alias =
                    base
                      { eliLabel = labelG
                      , eliFixedArgs = Just args
                      , eliFixedUniverses = Just universes
                      }
               in st {csModEffLabels = Map.insert lblName alias (csModEffLabels st)}
        Nothing -> pure ()
    Nothing ->
      errAt sp "E_EFFECT_LABEL_FORM" (Just "kappa-hs.effect.label")
        ("'effect label " <> lblName <> " : E' requires a concrete application of a named top-level effect (§18.1.15)")

-- | Elaborate and identify the interface of an effect-label declaration.
-- The type expression must be fully applied to a proper type, and its
-- normalized head must be the symbol identity of a visible effect interface.
-- This deliberately does not recognize source spellings.
resolveEffectLabelInterface
  :: Ctx
  -> Span
  -> Expr
  -> Map Text EffLabelInfo
  -> CheckM (Maybe (EffLabelInfo, [Level], [Value]))
resolveEffectLabelInterface ctx sp ifaceE visible = do
  (ifaceTm, _) <- inferType ctx ifaceE
  ifaceV <- evalIn ctx ifaceTm >>= forceM
  case ifaceV of
    VGlobI ifaceG universes spine
      | Just base <- find ((== ifaceG) . eliIface) (Map.elems visible)
      , length spine == length (eliParams base) ->
          pure (Just (base, universes, map snd spine))
    _ -> do
      errAt sp "E_EFFECT_LABEL_FORM" (Just "kappa-hs.effect.label")
        "an effect-label interface must normalize to a fully applied, visible effect constructor (§18.1.15)"
      pure Nothing

-- | Effect-row syntax @<[l1 : E1, ... | tail]>@ (§18.1.14): rows are
-- neutral spines of @__effRowCons label iface rest@.
elabEffRow :: Ctx -> [(Name, Expr)] -> Maybe Expr -> Span -> CheckM (Term, Value)
elabEffRow ctx entries mtail _sp = do
  rowNilHead <- globalHeadM prelEffRowNil
  rowConsHead <- globalHeadM prelEffRowCons
  parts <- fmap catMaybes . forM entries $ \(ln, ifE) -> do
    meli <- lookupEffLabelM ctx (nameText ln)
    case meli of
      Just eli -> do
        ifTm <- check ctx ifE (VSort LZero)
        labelHead <- globalHeadM (eliLabel eli)
        pure (Just (labelHead, ifTm))
      Nothing -> do
        errAt (nameSpan ln) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
          ("unresolved effect label '" <> nameText ln <> "' (not a scoped (§9.3.1.1) or top-level (§18.1) effect)")
        pure Nothing
  tailTm <- case mtail of
    Nothing -> pure rowNilHead
    Just te -> do
      effRowT <- globalValueM prelEffRow []
      check ctx te effRowT
  let row =
        foldr
          (\(l, t) acc -> CApp Expl (CApp Expl (CApp Expl rowConsHead l) t) acc)
          tailTm
          parts
  effRowT <- globalValueM prelEffRow []
  pure (row, effRowT)

-- | A non-dependent function-type value (level-safe: the codomain is
-- captured in the closure environment).
nonDepPiV :: Q -> Value -> Value -> Value
nonDepPiV q dom cod =
  VPiEvidenceM Ordinary FormationOrdinary Expl q False "_" Nothing BinderSourceWritten dom
    (Closure [cod] (CVar 1))

nonDepPiModeV :: ObservationMode -> FormationMode -> Q -> Bool -> Value -> Value -> Value
nonDepPiModeV mode formation q borrowed dom cod =
  VPiEvidenceM mode formation Expl q borrowed "_" Nothing BinderSourceWritten dom
    (Closure [cod] (CVar 1))

effTyVM :: Value -> Value -> CheckM Value
effTyVM row a = globalValueM prelEff [(Expl, row), (Expl, a)]

effCarrierVM :: Value -> CheckM Value
effCarrierVM row = globalValueM prelEff [(Expl, row)]

-- | Instantiate an operation's payload and result types at concrete effect
-- parameter VALUES (outer-to-inner). The stored types are de Bruijn under the
-- parameter binders, so the eval environment lists the parameters
-- innermost-first.
instOpTypes :: EvalCtx -> [Value] -> EffOpInfo -> ([Value], Value)
instOpTypes ec ps op =
  let step (values, bound) entry =
        let domain = eval ec (reverse (ps ++ bound)) (teDomain entry)
            -- Handler clause binders are introduced immediately after the
            -- operation's implicit skolems. These rigids keep later argument
            -- domains and the result type scoped over the same telescope.
            rigid = VRigid (length ps + length bound) []
         in (values ++ [domain], bound ++ [rigid])
      (arguments, argumentRigids) = foldl' step ([], []) (eoiArgs op)
   in (arguments, eval ec (reverse (ps ++ argumentRigids)) (eoiResT op))

-- | The field name of the @i@-th tuple component (§6.6 tuples are records with
-- @_1@, @_2@, … fields), used to bundle a multi-argument operation payload.
effTupleField :: Int -> Text
effTupleField i = "_" <> T.pack (show (i + 1))

-- | §4b reserved field on a handler's @ops@ record carrying the set of
-- tail-resumptive operation names (a sub-record @{ opName -> Unit }@). The
-- runtime @do_perform@ projects it to take the constant-@Cont@-depth fast
-- path. The @__@ prefix keeps it disjoint from every user operation name
-- (operations are source identifiers), so @kproj(ops, opName)@ never sees
-- it; the interpreter's @lookup opn fs@ likewise ignores it.
tailResumptiveField :: Text
tailResumptiveField = "__tailResumptive"

-- | An operation selection @label.op@ (§18.1.15). Canonical effect labels
-- quantify over the interface parameters; an explicit @effect label l : E
-- args@ has those parameters specialized at its declaration site.
effOpSelection :: Ctx -> Span -> EffLabelInfo -> EffOpInfo -> CheckM (Term, Value)
effOpSelection ctx opSp rawEffectInfo rawOperation = do
  effHead <- globalHeadM prelEff
  rowConsHead <- globalHeadM prelEffRowCons
  rowNilHead <- globalHeadM prelEffRowNil
  (ifaceHead, ifaceUniverses) <-
    case (eliFixedArgs rawEffectInfo, eliFixedUniverses rawEffectInfo) of
      (Nothing, Nothing) ->
        globalHeadWithUniversesM (eliIface rawEffectInfo)
      (Just _, Just universes) -> do
        definition <- gets (Map.lookup (eliIface rawEffectInfo) . csGlobals)
        case definition of
          Just gd -> do
            (headTerm, _) <- specializeGlobalAt ctx (eliIface rawEffectInfo) gd universes
            pure (headTerm, universes)
          Nothing -> do
            errAt opSp "E_INTERNAL" Nothing
              "effect-label metadata refers to an interface without a global declaration"
            pure (CGlobI (eliIface rawEffectInfo) universes, universes)
      _ -> do
        errAt opSp "E_INTERNAL" Nothing
          "effect-label metadata must fix interface arguments and declaration universes together"
        globalHeadWithUniversesM (eliIface rawEffectInfo)
  (eli, op) <-
    specializeEffectOperationMetadata
      (eliIface rawEffectInfo)
      ifaceUniverses
      rawEffectInfo
      rawOperation
  labelHead <- globalHeadM (eliLabel eli)
  let info = effectOpValueInfo eli op
  when (isMultishotOpValue info) $
    recordRecognizedMultishotOp opSp info
  (allParams, args, resT, ifaceApp) <- case eliFixedArgs eli of
    Nothing -> do
      let params = map asOperationImplicit (eliParams eli) ++ eoiImplicits op
          np = length params
          ne = length (eliParams eli)
          iface extra =
            foldl
              (\f (i, entry) -> CApp (teIcit entry) f (CVar (np - 1 - i + extra)))
              ifaceHead
              (zip [0 .. ne - 1] (eliParams eli))
      pure (params, eoiArgs op, eoiResT op, iface)
    Just paramVs -> do
      -- Operation metadata is stored under the effect parameter telescope.
      -- Evaluate it in the fixed argument environment and re-quote it under
      -- only the operation's own implicit binders. This handles dependent
      -- operation signatures without source-level substitution heuristics.
      ec <- ec_
      let goImplicits c accVals accTerms [] = pure (c, accVals, accTerms)
          goImplicits c accVals accTerms (entry : rest) = do
            let kindV = eval ec (reverse (paramVs ++ accVals)) (teDomain entry)
            kindTm <- quoteIn c kindV
            let rigid = VRigid (ctxLen c) []
                entry' = entry {teDomain = kindTm}
            goImplicits
              (bindCtxMQB (teMode entry) (teQ entry) (teName entry) True (teBorrow entry) kindV c)
              (accVals ++ [rigid])
              (accTerms ++ [entry'])
              rest
      (ctxI, opImplVs, opImpls) <- goImplicits ctx [] [] (eoiImplicits op)
      let specializeArgs c values [] = do
            let env = reverse (paramVs ++ opImplVs ++ values)
            result <- quoteIn c (eval ec env (eoiResT op))
            pure ([], result)
          specializeArgs c values (entry : rest) = do
            let env = reverse (paramVs ++ opImplVs ++ values)
                domain = eval ec env (teDomain entry)
            domainTm <- quoteIn c domain
            let rigid = VRigid (ctxLen c) []
                entry' = entry {teDomain = domainTm}
                c' = bindCtxMQB (teMode entry) (teQ entry) (teName entry) False (teBorrow entry) domain c
            (later, result) <- specializeArgs c' (values ++ [rigid]) rest
            pure (entry' : later, result)
      (args, res) <- specializeArgs ctxI [] (eoiArgs op)
      fixedArgs <- traverse (quoteIn ctx) paramVs
      let np = length opImpls
          iface extra =
            foldl
              (\f (entry, arg) -> CApp (teIcit entry) f (shiftTerm (np + extra) 0 arg))
              ifaceHead
              (zip (eliParams eli) fixedArgs)
      pure (opImpls, args, res, iface)
  let na = length args
      -- TERM payload: the single argument when n = 1, else the tuple.
      payload
        | na == 1 = CVar 0
        | otherwise = CRecordV [(effTupleField i, CVar (na - 1 - i)) | i <- [0 .. na - 1]]
  let
      rowT extra =
        CApp Expl
          (CApp Expl (CApp Expl rowConsHead labelHead) (ifaceApp extra))
          rowNilHead
      -- TYPE: forall params opImpls. A₁ -> … -> Aₙ -> Eff <[label : iface params]> B.
      -- The result and each later domain are already scoped under the complete
      -- preceding telescope, so folding the stored binders is capture-safe.
      effCod = CApp Expl (CApp Expl effHead (rowT na)) resT
      -- The resumption body sits under its result binder. Transport both the
      -- payload classifier and the Eff result through that binder before
      -- building the intrinsic telescope; otherwise a dependent result type
      -- can accidentally refer to the preceding operation argument.
      resumeResult =
        generatedEffPureCore
          (shiftTerm 1 0 resT)
          (shiftTerm 1 0 effCod)
          (CVar 0)
      payloadSite = case args of
        [entry] ->
          ( teMode entry
          , teFormation entry
          , teQ entry
          , shiftTerm 1 0 (teDomain entry)
          )
        _ ->
          ( Ordinary
          , FormationOrdinary
          , Q1
          , CRecordTQ
              [ RecordField
                  (effTupleField i)
                  (teMode entry)
                  (teFormation entry)
                  (teQ entry)
                  (teLevelAssumption entry)
                  (shiftTerm (na - i) 0 (teDomain entry))
              | (i, entry) <- zip [0 ..] args
              ]
          )
      continuationType =
        CPiBoundFormedM Ordinary FormationOrdinary Expl Q1 False "__result" Nothing resT
          (shiftTerm 1 0 effCod)
      intrinsicPi (mode, formation, quantity, name, domain) codomain =
        CPiBoundFormedM mode formation Expl quantity False name Nothing domain
          (shiftTerm 1 0 codomain)
      -- '__EffOp' is a compiler-owned constructor with no source declaration.
      -- Its occurrence-local telescope is therefore the typed authority for
      -- the payload package. A tuple payload retains every operation
      -- argument's independent observation mode and quantity.
      effectTreeType =
        foldr intrinsicPi effCod
          [ (Ordinary, FormationOrdinary, QW, "__label", CGlobal prelEffLabel [])
          , (Ordinary, FormationOrdinary, QW, "__operation", CGlobal prelString [])
          , let (mode, formation, quantity, domain) = payloadSite
             in (mode, formation, quantity, "__payload", domain)
          , (Ordinary, FormationOrdinary, Q1, "__resume", continuationType)
          ]
      opCall =
        CCtorI prelEffOp [] (Just effectTreeType)
          [ ConstructorArg Expl True Nothing labelHead
          , ConstructorArg Expl True Nothing (CLit (LitStr (eoiName op)))
          , ConstructorArg Expl True Nothing payload
          , ConstructorArg Expl True Nothing (CLamM Ordinary Expl Q1 "__r" resumeResult)
          ]
      argArrows = foldr telePi effCod args
      tyTerm = foldr telePi argArrows allParams
      -- TERM: \@params @opImpls -> \x₁ … \xₙ -> __EffOp label op PAYLOAD k.
      opBody = foldr (\entry acc -> CLamM (teMode entry) Expl (teQ entry) (teName entry) acc) opCall args
      tm = foldr (\entry acc -> CLamM (teMode entry) (teIcit entry) (teQ entry) (teName entry) acc) opBody allParams
  tyV <- evalIn ctx tyTerm
  pure (tm, tyV)
  where
    -- Effect-interface parameters are inferred at operation selection, so the
    -- selected operation exposes them implicitly while preserving their mode
    -- and quantity. Their interface-constructor explicitness remains recorded
    -- separately on 'eliParams' for the row application itself.
    asOperationImplicit entry = entry {teIcit = Impl}

effectOpValueInfo :: EffLabelInfo -> EffOpInfo -> EffectOpValueInfo
effectOpValueInfo eli op =
  EffectOpValueInfo
    { eoviLabel = eliLabel eli
    , eoviName = eoiName op
    , eoviQ = eoiQ op
    , eoviArity = length (eoiArgs op)
    }

isMultishotOpValue :: EffectOpValueInfo -> Bool
isMultishotOpValue info = eoviQ info `elem` [QW, QGe1]

operationValueInfoOfExpr :: Ctx -> Expr -> CheckM (Maybe EffectOpValueInfo)
operationValueInfoOfExpr ctx = \case
  EAscription e _ _ -> operationValueInfoOfExpr ctx e
  EDot (EVar ln) member -> do
    merged <- effMerged ctx
    let opname = case member of
          DotName n -> nameText n
          DotOperator n -> nameText n
    pure $ do
      eli <- Map.lookup (nameText ln) merged
      op <- find ((== opname) . eoiName) (eliOps eli)
      pure (effectOpValueInfo eli op)
  EVar n ->
    case lookupCtx (nameText n) ctx of
      Just (_, entry) -> pure (ceOpValueInfo entry)
      Nothing -> do
        mg <- lookupGlobalName (nameText n)
        case mg of
          Nothing -> pure Nothing
          Just g -> gets (Map.lookup g . csEffectOpValueGlobals)
  EApp f args
    | all isImplicitArg args -> operationValueInfoOfExpr ctx f
  _ -> pure Nothing
  where
    isImplicitArg = \case
      ArgImplicit {} -> True
      _ -> False

recordMultishotOpApplication :: Ctx -> Expr -> [Arg] -> Span -> CheckM ()
recordMultishotOpApplication ctx f args sp = do
  minfo <- operationValueInfoOfExpr ctx f
  forM_ minfo $ \info ->
    when (isMultishotOpValue info && explicitArgCount args >= eoviArity info) $
      recordRecognizedMultishotOp sp info
  where
    explicitArgCount = length . mapMaybe (\case
      ArgExplicit _ -> Just ()
      _ -> Nothing)

-- | Split an effect-row value at a label: the matching interface and
-- the residual row (§18.1.21 SplitEff, by §18.1.18 label identity).
splitEffRow :: GName -> Value -> CheckM (Maybe (Value, Value))
splitEffRow labelG row0 = do
  row <- forceM row0
  case row of
    VGlobN (GName _ "__effRowCons") [(_, l), (_, e), (_, rest)] -> do
      lF <- forceM l
      case lF of
        VGlobN lg []
          | lg == labelG -> pure (Just (e, rest))
        _ -> do
          minner <- splitEffRow labelG rest
          case minner of
            Just (e', rest') -> do
              rebuilt <- globalValueM prelEffRowCons [(Expl, l), (Expl, e), (Expl, rest')]
              pure (Just (e', rebuilt))
            Nothing -> pure Nothing
    _ -> pure Nothing

-- | @[deep] handle label expr with case ...@ (§18.1.21–§18.1.22). The
-- target carrier is @Eff r@ for the residual row @r@ in v1.
elabHandle :: Ctx -> Bool -> Expr -> Expr -> [HandlerCase] -> Span -> Maybe Value -> CheckM (Term, Value)
elabHandle ctx deep lblE scrutE cases sp mexpected = do
  mEli <- case lblE of
    EVar ln -> lookupEffLabelM ctx (nameText ln)
    _ -> pure Nothing
  case mEli of
    Nothing -> do
      errAt (exprSpan lblE) "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
        "'handle' requires an effect label in scope (a §9.3.1.1 scoped or §18.1 top-level effect)"
      anyHole ctx
    Just eli -> do
      (scrutTm0, scrutTy0) <- infer ctx scrutE
      (scrutTm, scrutTy1) <- insertAllImplicits ctx (exprSpan scrutE) scrutTm0 scrutTy0
      scrutTy <- forceM scrutTy1
      case scrutTy of
        VGlobN g [(_, row), (_, aT)]
          | g == prelEff -> do
          handleEffHead <- globalHeadM prelHandleEff
          labelHead <- globalHeadM (eliLabel eli)
          msplit <- splitEffRow (eliLabel eli) row
          -- the matched interface fixes the effect's type parameters (§18.1.15):
          -- @<[l : State Int]>@ gives @State Int@, so the parameters are @[Int]@.
          (residual, ifaceUniverses, paramVs) <- case msplit of
            Just (ifaceV0, rest) -> do
              ifaceV <- forceM ifaceV0
              let (universes, ps) = case ifaceV of
                    VGlobI g us spn | g == eliIface eli -> (us, map snd spn)
                    _ -> ([], [])
              pure (rest, universes, ps)
            Nothing -> do
              errAt (exprSpan scrutE) "E_EFFECT_LABEL_NOT_IN_ROW" (Just "kappa.effect.row-mismatch")
                "the handled computation's effect row does not contain the handled label (§18.1.21)"
              emptyRow <- globalValueM prelEffRowNil []
              pure (emptyRow, fromMaybe [] (eliFixedUniverses eli), [])
          ecH <- ec_
          -- Bind an operation's own implicit parameters as erased Core
          -- lambdas/Pis. They erase before the runtime handler ABI applies
          -- payload and resumption, but retaining them in typed Core is
          -- essential: clause argument/result types may mention the skolems,
          -- and an outer lexical capture must remain correctly indexed under
          -- those binders. Omitting the telescope made later typed checkpoints
          -- see an unannotated `k` and fail closed on ordinary clause bodies.
          let goBOI c accInOrder binders [] = pure (c, accInOrder, binders)
              goBOI c accInOrder binders (entry : rest) = do
                let kindV = eval ecH (reverse (paramVs ++ accInOrder)) (teDomain entry)
                kindTm <- quoteIn c kindV
                let binder =
                      ( teMode entry
                      , teFormation entry
                      , teQ entry
                      , teBorrow entry
                      , teName entry
                      , teLevelAssumption entry
                      , kindTm
                      )
                    c' = bindCtxMQB (teMode entry) (teQ entry) (teName entry) True (teBorrow entry) kindV c
                goBOI c' (accInOrder ++ [VRigid (ctxLen c) []]) (binders ++ [binder]) rest
              bindOpImplicits c0 = goBOI c0 [] []
              wrapImplicitLambda (mode, _, q, _, name, _, _) body =
                CLamM mode Impl q name body
              wrapImplicitPi (mode, formation, q, borrowed, name, assumption, domain) codomain =
                CPiEvidenceM mode formation Impl q borrowed name assumption BinderSourceWritten domain codomain
              annotateClause name clauseType clause =
                CLetM Ordinary QW name clauseType clause (CVar 0)
          bT <- freshMetaV ctx
          -- §18.1.21: the handler eliminates into a target carrier `m`. By
          -- default (and for an `Eff r` expectation) that is `Eff residual`;
          -- when the surrounding context expects a NON-Eff carrier (e.g.
          -- `IO e`), use it directly — the §30.2.2.7 handler kernel is
          -- carrier-agnostic (it applies the clauses/return and threads the
          -- resumption, never imposing Eff).
          resultTy <- case mexpected of
            Just t -> do
              tf <- forceM t
              case tf of
                VGlobN g _ | g == prelEff -> effTyVM residual bT
                _ -> pure tf
            Nothing -> effTyVM residual bT
          -- exactly one return clause (§18.1.21)
          retLam0 <- case [(pat, body, csp) | HandlerReturn pat body csp <- cases] of
            [(pat, body, _)] ->
              handlerClauseLam ctx QW pat aT (\c' -> check c' body resultTy)
            [] -> do
              errAt sp "E_HANDLER_RETURN_MISSING" (Just "kappa-hs.effect.handler")
                "a handler requires exactly one 'case return x -> ...' clause (§18.1.21)"
              fallback <- generatedEffPureAtM ctx resultTy (CVar 0)
              pure (CLamM Ordinary Expl QW "__x" fallback)
            (_ : (_, _, csp2) : _) -> do
              errAt csp2 "E_HANDLER_RETURN_DUPLICATE" (Just "kappa-hs.effect.handler")
                "a handler permits only one 'case return x -> ...' clause (§18.1.21)"
              fallback <- generatedEffPureAtM ctx resultTy (CVar 0)
              pure (CLamM Ordinary Expl QW "__x" fallback)
          retType <- quoteIn ctx (nonDepPiV QW aT resultTy)
          let retLam = annotateClause "__handlerReturnClause" retType retLam0
          -- one operation clause per declared operation (§18.1.21)
          let opClauses =
                [(onm, argPats, kn, body, csp) | HandlerOp onm argPats kn body csp <- cases]
          forM_ (eliOps eli) $ \op ->
            unless (any (\(onm, _, _, _, _) -> nameText onm == eoiName op) opClauses) $
              errAt sp "E_HANDLER_OP_MISSING" (Just "kappa-hs.effect.handler")
                ("this handler has no clause for operation '" <> eoiName op <> "' (§18.1.21)")
          clauseTms <- fmap catMaybes . forM opClauses $ \(onm, argPats, kn, body, csp) ->
            case find ((== nameText onm) . eoiName) (eliOps eli) of
              Nothing -> do
                errAt (nameSpan onm) "E_HANDLER_OP_UNKNOWN" (Just "kappa-hs.effect.handler")
                  ("the handled effect declares no operation '" <> nameText onm <> "' (§18.1.21)")
                pure Nothing
              Just rawOp -> do
                (_, op) <-
                  specializeEffectOperationMetadata
                    (eliIface eli)
                    ifaceUniverses
                    eli
                    rawOp
                -- skolemize the operation's own implicit parameters, then take
                -- its argument/result types at the effect's actual type
                -- parameters plus those skolems (§18.1.15/§18.1.21)
                (ctxSk, skolemVs, implicitBinders) <- bindOpImplicits ctx (eoiImplicits op)
                let (opArgVs, opResV) = instOpTypes ecH (paramVs ++ skolemVs) op
                    nArgs = length opArgVs
                when (length argPats /= nArgs) $
                  errAt csp "E_HANDLER_OP_ARITY" (Just "kappa-hs.effect.handler")
                    ( "operation '" <> nameText onm <> "' takes " <> T.pack (show nArgs)
                        <> " argument(s) but this clause binds " <> T.pack (show (length argPats)) <> " (§18.1.21)")
                forM_ (zip argPats (eoiArgs op)) $ \(argPat, entry) ->
                  when (teBorrow entry) $
                    mapM_ (recordPatternBinderBorrow . nameSpan) (surfPatVars argPat)
                -- shallow k resumes in the unhandled carrier; deep k is
                -- already re-handled (§18.1.21/§18.1.22)
                shallowResultTy <- effTyVM row aT
                let kTy
                      | deep = nonDepPiV Q1 opResV resultTy
                      | otherwise = nonDepPiV Q1 opResV shallowResultTy
                    -- The runtime handler ABI always supplies this slot even
                    -- for an abortive source operation. Its generated binder
                    -- is therefore runtime-relevant while source use remains
                    -- governed by the recorded operation quantity.
                    runtimeKQ = if eoiQ op == Q0 then QW else eoiQ op
                    -- bind the resumption `k` (at its declared quantity) and
                    -- check the body in the target carrier
                    mkK cArgs = do
                      recordHandlerOpQuantity (nameSpan kn) (eoiQ op)
                      let cK = bindCtx (nameText kn) False kTy cArgs
                          -- The runtime handler ABI always calls an operation
                          -- clause as `clause payload k`.  A q=0 resumption is
                          -- unusable by the surface program (enforced from the
                          -- recorded handler quantity), but the ABI slot must
                          -- still be present so the second runtime application
                          -- has a closure to call rather than the clause's Eff
                          -- result.  Therefore only the generated slot uses a
                          -- runtime-relevant quantity.
                      inner <- check cK body resultTy
                      pure (CLamM Ordinary Expl runtimeKQ (nameText kn) inner)
                (lam0, clauseType0) <- case (argPats, opArgVs) of
                  -- single argument: the payload IS the value (§18.1.21)
                  ([p], [argV])
                    | [entry] <- eoiArgs op -> do
                        clause <- handlerClauseLamM
                          ctxSk
                          (teMode entry)
                          (teQ entry)
                          (teBorrow entry)
                          p
                          argV
                          mkK
                        clauseType <- quoteIn ctxSk $
                          nonDepPiModeV
                            (teMode entry)
                            (teFormation entry)
                            (teQ entry)
                            (teBorrow entry)
                            argV
                            (nonDepPiV runtimeKQ kTy resultTy)
                        pure (clause, clauseType)
                  -- n ≥ 2 arguments: the payload is the tuple (x₁,…,xₙ);
                  -- destructure it positionally to bind the clause parameters
                  (ps, _) -> do
                    let tupTy =
                          VRecordTQ
                            [ RecordField (effTupleField i) (teMode entry) (teFormation entry) (teQ entry) (teLevelAssumption entry) v
                            | (i, (entry, v)) <- zip [0 ..] (zip (eoiArgs op) opArgVs)
                            ]
                        c0 = bindCtx "__payload" False tupTy ctxSk
                    (patC, cArgs, patternRefinements) <- elabPattern c0 (PTuple ps csp) tupTy
                    inner <- withPatternRefinements patternRefinements (mkK cArgs)
                    tupTyTm <- quoteIn c0 tupTy
                    clauseType <- quoteIn ctxSk $
                      nonDepPiV QW tupTy (nonDepPiV runtimeKQ kTy resultTy)
                    pure
                      ( CLamM Ordinary Expl QW "__payload"
                          (CMatch (CVar 0) (Just tupTyTm) Nothing [CaseAlt patC Nothing inner])
                      , clauseType
                      )
                let lam =
                      annotateClause "__handlerOperationClause"
                        (foldr wrapImplicitPi clauseType0 implicitBinders)
                        (foldr wrapImplicitLambda lam0 implicitBinders)
                -- §4b tail-resumptive detection (Usage.tailResumptiveClause):
                -- a clause whose only `resume` is `k v` in tail position runs
                -- IN PLACE — the runtime keeps the op-site→handler segment on
                -- f->k (no sever, no heap Resumption, constant Cont depth).
                -- Restricted to DEEP handlers: the fast path leaves this
                -- KK_HANDLER linked beneath the resumed body, which re-handles
                -- it (deep semantics); a shallow handler must NOT auto-reinstall,
                -- so it falls back to the general 4a path (honesty: never
                -- mis-optimize).  Multi-shot ops (eoiQ ≠ Q1) are likewise never
                -- tail-resumptive — their k may be used more than once.
                let isTail = deep && eoiQ op == Q1 && tailResumptiveClause kn body
                pure (Just (eoiName op, lam, isTail))
          tailFields <- forM [(nm, isTail) | (nm, _, isTail) <- clauseTms, isTail] $ \(nm, _) -> do
            unitType <- globalValueM prelUnit []
            unitTm <- generatedCtorAtM ctx unitType prelUnit
            pure (nm, unitTm)
          boolT <- globalValueM prelBool []
          deepTm <- generatedCtorAtM ctx boolT (prelBoolV deep)
          let opsRec0 = CRecordV (sortOn fst [(nm, lam) | (nm, lam, _) <- clauseTms])
              -- a reserved field carrying the tail-resumptive op set as a
              -- record { opName -> Unit }.  do_perform projects it (a NON-op
              -- key, so it never collides with kproj(ops, opName)) to choose
              -- the fast path; absent/empty ⇒ every op takes the general path.
              tailRec = CRecordV tailFields
              opsRec = case opsRec0 of
                CRecordV fs -> CRecordV (fs ++ [(tailResumptiveField, tailRec)])
                other -> other
              tm =
                List.foldl'
                  (CApp Expl)
                  handleEffHead
                  [deepTm, labelHead, retLam, opsRec, scrutTm]
          pure (tm, resultTy)
        _ -> do
          errAt (exprSpan scrutE) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
            "the handled computation of 'handle' must have an Eff type (§18.1.21)"
          anyHole ctx

-- | A one-argument clause lambda binding a surface pattern: simple
-- variable patterns bind directly; other patterns go through a match.
handlerClauseLam ::
  Ctx -> Q -> Pattern -> Value -> (Ctx -> CheckM Term) -> CheckM Term
handlerClauseLam ctx q = handlerClauseLamM ctx Ordinary q False

-- | Build one handler ABI lambda while checking its surface pattern with the
-- exact source binder contract. The ABI always supplies one payload value, but
-- the source binding may independently be parametric, linear/affine, or
-- borrowed; those properties must survive in both Core and the local context.
handlerClauseLamM ::
  Ctx -> ObservationMode -> Q -> Bool -> Pattern -> Value -> (Ctx -> CheckM Term) -> CheckM Term
handlerClauseLamM ctx mode q borrowed pat ty mkBody = case pat of
  PVar n -> do
    recordPatternBinderFacts ctx (nameSpan n) q ty
    let ctx' = bindCtxMQB mode q (nameText n) False borrowed ty ctx
    CLamM mode Expl q (nameText n) <$> mkBody ctx'
  PWild _ -> do
    let ctx' = bindCtxMQB mode q "__w" False borrowed ty ctx
    CLamM mode Expl q "__w" <$> mkBody ctx'
  _ -> do
    let scrutinee = VRigid (ctxLen ctx) []
        ctx0 = bindCtxMQB mode q "__scrut" False borrowed ty ctx
    (patC, ctx', patternRefinements) <-
      elabPatternFrom mode q (Just scrutinee) ctx0 pat ty
    body <- withPatternRefinements patternRefinements (mkBody ctx')
    tyTm <- quoteIn ctx0 ty
    pure (CLamM mode Expl q "__scrut" (CMatch (CVar 0) (Just tyTm) Nothing [CaseAlt patC Nothing body]))

-- | A @do@ block in an @Eff row a@ position (§18.1.14: Eff is the
-- monadic carrier): items elaborate to @__effBind@ chains.
elabEffDo :: Ctx -> Value -> Value -> [DoItem] -> Span -> CheckM (Term, Value)
elabEffDo ctx0 row aT items0 sp = do
  inner <- go ctx0 items0
  doscopeHead <- globalHeadM prelEffDoscope
  resultTy <- effTyVM row aT
  -- §18.7/§32.2.19 Stage-4a/4b: when the block registers exit actions (defer or
  -- using), delimit it with a do-scope so those finalizers run masked-LIFO on
  -- EVERY way out — normal completion AND a handler's §32.2.20 abandonment of
  -- the captured segment.  Both lower (Backend/C, Backend/LLVM) to the runtime's
  -- krt2_doscope / krt2_defer nodes (the SAME OP_DOSCOPE/OP_DEFER machinery the
  -- IO do-kernel uses), and the interpreter reduces them through evalEffPrim — so
  -- no new runtime primitive is introduced.  A block with no exit actions is
  -- left as-is (no needless frame).
  let tm
        | any isExitItem items0 = CApp Expl doscopeHead inner
        | otherwise = inner
  pure (tm, resultTy)
  where
    isExitItem DoDefer {} = True
    isExitItem DoUsing {} = True
    isExitItem _ = False
    effT = effTyVM row
    go c [] = do
      errAt sp "E_DO_EMPTY" (Just "kappa-hs.do.empty")
        "a do block must end with an expression item (§18.2)"
      unitType <- globalValueM prelUnit []
      unitTm <- generatedCtorAtM c unitType prelUnit
      expected <- effT unitType
      generatedEffPureAtM c expected unitTm
    go c [DoExpr e] = do
      -- final item: an Eff computation of the result type, or (corpus
      -- accommodation, as in the IO kernel) a pure result value
      let eD = e
      st0 <- get
      n0 <- gets (length . csDiags)
      expected <- effT aT
      tm0 <- check c eD expected
      n1 <- gets (length . csDiags)
      if n1 == n0
        then pure tm0
        else do
          put st0
          tm <- check c eD aT
          generatedEffPureAtM c expected tm
    -- a final statement-if is the result expression (§18.2)
    go c [DoIf alts mels isp] =
      let toExpr its = case its of
            [DoExpr e] -> e
            _ -> EDo Nothing its isp
          ifE = EIf [(cnd, toExpr body) | (cnd, body) <- alts] (toExpr <$> mels) isp
       in go c [DoExpr ifE]
    go c (item : rest) = case item of
      DoExpr e -> do
        bT <- freshMetaV c
        expected <- effT bT
        tm <- check c (e) expected
        registerDiscardedResult c (exprSpan e) bT
        contTm <- CLamM Ordinary Expl QW "__u" <$> go (bindCtx "__u" False bT c) rest
        effBindTm tm contTm
      DoBind (LetBind _ _ pat mty rhs bsp) -> do
        bT <- case mty of
          Just tyE -> do
            (tyTm, _) <- inferType c tyE
            evalIn c tyTm
          Nothing -> freshMetaV c
        expected <- effT bT
        rhsTm <- check c (rhs) expected
        checkIrrefutable c pat bT bsp
        contTm <- handlerClauseLam c Q1 pat bT (\c' -> go c' rest)
        effBindTm rhsTm contTm
      DoLet (LetBind _ _ pat mty rhs bsp) -> do
        -- §18.3.1: a `let` RHS inside a do block may contain `!`; desugar
        -- it like the DoBind branch above so it is not rejected as a bare
        -- splice (E_SPLICE_OUTSIDE_DO).
        let rhsD = rhs
        (rhsTm, rhsTy) <- case mty of
          Just tyE -> do
            (tyTm, _) <- inferType c tyE
            tyV <- evalIn c tyTm
            tm <- check c rhsD tyV
            pure (tm, tyV)
          Nothing -> do
            (tm, ty) <- infer c rhsD
            insertAllImplicits c bsp tm ty
        checkIrrefutable c pat rhsTy bsp
        case pat of
          PVar n -> do
            rhsV <- evalIn c rhsTm
            tyTm <- quoteIn c rhsTy
            observation <- observationJudgmentForTerm c rhsTm rhsTy
            let c' = bindCtxLetProjOpMode (nameText n) False rhsTy rhsV Nothing Nothing (ojMode observation) (Just (ojOrigin observation)) c
            CLetM (ojMode observation) QW (nameText n) tyTm rhsTm <$> go c' rest
          _ -> do
            tyTm <- quoteIn c rhsTy
            let c0 = bindCtx "__b" False rhsTy c
            (patC, c', patternRefinements) <- elabPattern c0 pat rhsTy
            body <- withPatternRefinements patternRefinements (go c' rest)
            sTyTm <- quoteIn c0 rhsTy
            pure (CLetM Ordinary QW "__b" tyTm rhsTm (CMatch (CVar 0) (Just sTyTm) Nothing [CaseAlt patC Nothing body]))
      -- §18.7 Stage-4a: `defer e` in an Eff do-block.  Lower to an `__effDefer`
      -- node sequenced before the rest; the whole block is wrapped in
      -- `__effDoscope` (above), so the registered action runs masked-LIFO on
      -- every exit — including a handler's §32.2.20 abandonment.  Only a bare
      -- `defer` (no @L label) is supported here in the minimal lift.
      DoDefer Nothing e _ -> do
        unitT <- globalValueM prelUnit []
        expected <- effT unitT
        eTm <- check c (e) expected
        contTm <- CLamM Ordinary Expl QW "__u" <$> go (bindCtx "__u" False unitT c) rest
        deferHead <- globalHeadM prelEffDefer
        let deferTm = CApp Expl deferHead eTm
        effBindTm deferTm contTm
      -- §19.5/§32.2.19 Stage-4b: `using pat <- acquire` in an Eff do-block.  The
      -- resource is acquired (an Eff action), `pat` is bound (borrowed) for the
      -- rest of the scope, and its `release` (from the required
      -- `Releasable (Eff row) a` instance) is registered as an exit action via
      -- `__effDefer` — so it runs masked-LIFO on EVERY exit, including a handler's
      -- §32.2.20 abandonment of the captured segment (the block is wrapped in
      -- `__effDoscope`).  This reuses the SAME krt2_doscope/krt2_defer machinery
      -- as `defer`, with no new runtime primitive.  Unlike the IO kernel's KUsing
      -- (which threads krt2_acquire_release for the interruptible-acquire mask),
      -- the pure Eff carrier has no interruption, so the acquire-then-register is
      -- already a single uninterruptible step.
      DoUsing mq pat rhs usp -> do
        forM_ mq $ \qsp ->
          errAt qsp "E_QTT_USING_EXPLICIT_QUANTITY" (Just "kappa-hs.qtt.using-quantity")
            "a 'using' item always binds with borrowed access at the default quantity ω; explicit quantity or borrow markers are not permitted (§9.3, §18.2)"
        rT <- freshMetaV c
        deferHead <- globalHeadM prelEffDefer
        bindHead <- globalHeadM prelEffBind
        acquireTy <- effT rT
        acquireTm <- check c (rhs) acquireTy
        -- Releasable (m := Eff row) (a := rT); `release : a -> m Unit`
        mTyV <- effCarrierVM row
        releasableGoal <- globalValueM prelReleasable [(Expl, mTyV), (Expl, rT)]
        dictTm <- resolveImplicit c usp releasableGoal
        let releaseTm = CProjM Ordinary dictTm "release"
        checkIrrefutable c pat rT usp
        -- The continuation receives the acquired resource at a STABLE binder
        -- `__res` (de Bruijn 0), so `release __res` always references the whole
        -- resource regardless of whether `pat` is a var or a destructuring
        -- pattern.  We then register `release __res` via `__effDefer` and bind
        -- `pat` from `__res` for the rest of the scope (under the `\__u`
        -- continuation of the defer bind), so the rest's de Bruijn indices line
        -- up past the intervening binders — exactly as the `DoExpr` / `DoDefer`
        -- continuations above thread `rest`.
        let cRes = bindCtx "__res" False rT c
        restAfterDefer <- do
          -- inside `\__res -> __effBind (__effDefer (release __res)) (\__u -> …)`
          -- the context has `__res` (db 1 after `__u`); bind `pat` to `__res` so
          -- the rest sees the surface name, then build the rest.
          unitT <- globalValueM prelUnit []
          let cU = bindCtx "__u" False unitT cRes
          (patC, cBound, patternRefinements) <- elabPattern cU pat rT
          restBody <-
            withPatternRefinements patternRefinements (go cBound rest)
          resTyTm <- quoteIn cU rT
          -- `__res` sits at db 1 under `\__u`; match `pat` against it.
          pure (CMatch (CVar 1) (Just resTyTm) Nothing [CaseAlt patC Nothing restBody])
        let releaseAppTm = CApp Expl (shiftTerm 1 0 releaseTm) (CVar 0) -- `release __res`
            deferTm = CApp Expl deferHead releaseAppTm
            contTm =
              CLamM Ordinary Expl Q1 "__res"
                (CApp Expl (CApp Expl bindHead deferTm) (CLamM Ordinary Expl QW "__u" restAfterDefer))
        effBindTm acquireTm contTm
      -- §18.6 mutable cells and the loop family (`var`, `:=`, `while`, `for`,
      -- `break`, `continue`) are not yet supported in an Eff do-block: an Eff
      -- carrier elaborates to the §30.2.2.7 free-monad tree (interpreted by
      -- 'Kappa.Eval.evalEffPrim' as the differential oracle), and this
      -- Eff carrier. Mutable cells are handled by the do-kernel carriers that
      -- provide lawful MonadRef evidence; lifting them into the §30.2.2.7 Eff
      -- free-monad tree would need a separate Eff-level reference operation and
      -- would otherwise diverge interpreter-vs-native.
      -- `using` and `defer`
      -- ARE supported (above): they carry exit-action frames only, with no
      -- mutable state, so the interpreter and native backends agree.
      other -> do
        unsupportedAt (doItemSpan other)
          "this do-item form (var / assignment / while / for / break / continue) is not yet supported in an Eff-typed do block by this implementation; only let / bind / expression / if / defer / using are (§18.6/§32.2.19)"
        go c rest
    effBindTm m f = do
      bindHead <- globalHeadM prelEffBind
      pure (CApp Expl (CApp Expl bindHead m) f)

-- | Conservative Appendix G.2 applicability check. The dependency set is
-- lexical, but the resulting term is elaborated normally: names do not select
-- any operation, and every pattern still passes the ordinary irrefutability,
-- exhaustiveness, quantity, and borrow judgments.
applicativeDoShape
  :: [DoItem]
  -> Maybe ([(Pattern, Expr)], [LetBind], Expr, Set Text)
applicativeDoShape = go Set.empty [] []
  where
    go bound actions lets = \case
      [DoExpr finalExpression] ->
        Just (reverse actions, reverse lets, finalExpression, bound)
      DoBind binding : rest
        | let dependencies =
                Set.fromList
                  (map nameText (freeVarOccurrencesScoped (lbExpr binding)))
        , Set.null (Set.intersection bound dependencies) ->
            let introduced =
                  Set.fromList (map nameText (surfPatVars (lbPattern binding)))
             in go
                  (Set.union bound introduced)
                  ((lbPattern binding, lbExpr binding) : actions)
                  lets
                  rest
      DoLet binding : rest ->
        let introduced =
              Set.fromList (map nameText (surfPatVars (lbPattern binding)))
         in go
              (Set.union bound introduced)
              actions
              (binding : lets)
              rest
      _ -> Nothing

-- | Whether any expression in a user-carrier do block requires semantic
-- lifting. Independent binds remain eligible for Applicative lowering, but the
-- fast path must not bypass mutable-current reads, explicit splices, generated
-- reads, or reference-facet effects.
doItemsRequireEffectAwareLifting :: Ctx -> [DoItem] -> Bool
doItemsRequireEffectAwareLifting ctx = any go
  where
    exprNeedsLift e =
      exprHasCurrentRead ctx e
        || exprHasBang e
        || exprHasGeneratedVarRead e
        || not (Set.null (collectRefFacets e))
    exprHasGeneratedVarRead = \case
      EVarRead {} -> True
      _ -> False
    go = \case
      DoBind binding -> exprNeedsLift (lbExpr binding)
      DoVar _ _ rhs _ -> exprNeedsLift rhs
      DoWhile _ condition body mElse _ ->
        exprNeedsLift condition || any go body || maybe False (any go) mElse
      DoFor _ _ src body mels _ ->
        exprNeedsLift src || any go body || maybe False (any go) mels
      DoIf alts mels _ ->
        any (\(cnd, body) -> exprNeedsLift cnd || any go body) alts
          || maybe False (any go) mels
      DoExpr e -> exprNeedsLift e
      DoLet lb -> exprNeedsLift (lbExpr lb)
      DoLetQ _ rhs mElse _ ->
        exprNeedsLift rhs || maybe False (exprNeedsLift . snd) mElse
      DoAssign _ _ rhs _ -> exprNeedsLift rhs
      DoUsing _ _ rhs _ -> exprNeedsLift rhs
      DoDefer _ e _ -> exprNeedsLift e
      _ -> False

-- | The Monad lowering additionally owns sequencing forms whose typing depends
-- on completed action boundaries, even if their expressions need no lifting.
monadDoNeedsStructuredElaboration :: Ctx -> [DoItem] -> Bool
monadDoNeedsStructuredElaboration ctx items =
  doItemsRequireEffectAwareLifting ctx items
    || any structurallyTyped items
    || any isDiscardedExpression (dropLast items)
  where
    dropLast [] = []
    dropLast [_] = []
    dropLast (item : rest) = item : dropLast rest
    isDiscardedExpression DoExpr {} = True
    isDiscardedExpression DoIf {} = True
    isDiscardedExpression _ = False
    structurallyTyped = \case
      DoBind {} -> True
      DoVar {} -> True
      DoWhile {} -> True
      DoFor {} -> True
      DoReturn {} -> True
      DoBreak {} -> True
      DoContinue {} -> True
      _ -> False

-- | Authenticate a source application as the canonical prelude
-- @Applicative.pure@ projection. The source spelling only identifies a lookup
-- candidate; the resolved Core head is the authority.
canonicalApplicativePurePayload :: Ctx -> Expr -> CheckM (Maybe Expr)
canonicalApplicativePurePayload ctx = \case
  EApp headExpression [ArgExplicit payload] -> do
    resolvedHead <- staticGlobalExpr ctx headExpression
    pure (payload <$ guard (resolvedHead == Just (gPrel "pure")))
  _ -> pure Nothing

-- | Prefer the first expected-directed elaboration, but retry from the complete
-- checker state when it emits errors and retain whichever branch emits fewer.
-- Failed speculative checks may allocate metas, constraints, evidence, and
-- diagnostics, so rolling back only a subset of 'CheckState' is unsound.
preferCheckByErrors :: CheckM Term -> CheckM Term -> CheckM Term
preferCheckByErrors primary fallback = do
  checkpoint <- get
  baselineErrors <- gets (length . filter isError . csDiags)
  primaryTerm <- primary
  primaryErrors <- gets (length . filter isError . csDiags)
  if primaryErrors == baselineErrors
    then pure primaryTerm
    else do
      primaryState <- get
      put checkpoint
      fallbackTerm <- fallback
      fallbackErrors <- gets (length . filter isError . csDiags)
      if fallbackErrors < primaryErrors
        then pure fallbackTerm
        else put primaryState >> pure primaryTerm

-- | Elaborate one proven-independent user-carrier do block with Applicative
-- operations only (§G.2). Actions are checked before their pattern lambdas are
-- built, so pattern checking observes the exact carrier result types. The
-- checked n-ary function is applied through the selected @liftA2@ member at
-- every step; no tuple-shaped inference shortcut or hard-coded carrier is
-- involved. The separately checked default @(<*>)@ remains available to user
-- programs and instances but is not needed by this lowering.
elabApplicativeDo
  :: Ctx
  -> Value
  -> [(Pattern, Expr)]
  -> [LetBind]
  -> Expr
  -> Set Text
  -> Span
  -> CheckM (Maybe (Term, Value))
elabApplicativeDo ctx expected actions lets finalExpression boundNames site = do
  purePayload <- canonicalApplicativePurePayload ctx finalExpression
  let finalDependencies =
        Set.fromList
          (map nameText (freeVarOccurrencesScoped finalExpression))
      finalIsIndependent =
        Set.null (Set.intersection boundNames finalDependencies)
      (carrier, resultType) =
        fromMaybe (expected, expected) (monadActionViewValue expected)
  case actions of
    [] -> Just . (,expected) <$> check ctx (wrapLets finalExpression) expected
    _ -> do
      checkedActions <- mapM (checkUnknownAction carrier) actions
      case purePayload of
        Just payload ->
          build carrier resultType checkedActions (wrapLets payload)
        Nothing
          | finalIsIndependent && null lets -> do
              resultName <- pure (Name "__applicative_do_result" site)
              finalAction <-
                checkKnownAction
                  carrier
                  resultType
                  (PVar resultName, finalExpression)
              build
                carrier
                resultType
                (checkedActions ++ [finalAction])
                (EVar resultName)
          | otherwise -> pure Nothing
  where
    wrapLets payload = case lets of
      [] -> payload
      orderedLets -> ELet orderedLets payload site

    checkUnknownAction carrier (pattern', expression) = do
      valueType <- freshMetaV ctx
      checkKnownAction carrier valueType (pattern', expression)

    checkKnownAction carrier valueType (pattern', expression) = do
      actionType <-
        case monadResultType carrier valueType of
          Just ty -> pure ty
          Nothing -> do
            errAt site "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
              "this Applicative do block has a higher-order carrier shape this implementation cannot apply (§G.2)"
            pure expected
      term <- check ctx expression actionType
      defaultPendingNumericGoals
      valueType' <- forceM valueType
      pure (pattern', term, valueType')

    build carrier resultType checked body = do
      unitType <- globalValueM prelUnit []
      (prepared, argumentTypes) <-
        case checked of
          [single] -> do
            unitTerm <- generatedCtorAtM ctx unitType prelUnit
            unitActionType <-
              case monadResultType carrier unitType of
                Just ty -> pure ty
                Nothing -> pure expected
            unitAction <-
              generatedApplicativePureAtM
                ctx
                site
                carrier
                unitType
                unitTerm
                unitActionType
            pure
              ( [single, (PWild site, unitAction, unitType)]
              , [third single, unitType]
              )
          many -> pure (many, map third many)
      function <- buildFunction ctx prepared body resultType
      functionType <- applicativeFunctionType argumentTypes resultType
      applicativeGoal <- globalValueM prelApplicative [(Expl, carrier)]
      dictionary <- resolveImplicit ctx site applicativeGoal
      (liftA2Member, liftA2Type) <-
        knownTraitMemberProjection
          ctx
          site
          prelApplicative
          "liftA2"
          applicativeGoal
          dictionary
      let firstAction = prepared !! 0
          secondAction = prepared !! 1
          suffixTypes = drop 2 argumentTypes
      firstResultType <- applicativeFunctionType suffixTypes resultType
      lifted <-
        applyApplicativeMember
          carrier
          liftA2Member
          liftA2Type
          [third firstAction, third secondAction, firstResultType]
          [ (function, functionType)
          , (second firstAction, actionType carrier (third firstAction))
          , (second secondAction, actionType carrier (third secondAction))
          ]
      (finalTerm, finalType) <-
        foldM
          (applyRemaining liftA2Member liftA2Type carrier resultType)
          (lifted, actionType carrier firstResultType)
          (zip (drop 2 prepared) (tailsAfter suffixTypes))
      coerced <- coerceTerm ctx site finalTerm finalType expected
      pure (Just (coerced, expected))

    buildFunction current [] body resultType = check current body resultType
    buildFunction current ((pattern', _, valueType) : rest) body resultType =
      handlerClauseLam current QW pattern' valueType $ \next ->
        buildFunction next rest body resultType

    applicativeFunctionType argumentTypes resultType = do
      resultTerm <- quoteIn ctx resultType
      typeTerm <- go 0 argumentTypes resultTerm
      evalIn ctx typeTerm
      where
        go depth [] resultTerm = pure (shiftTerm depth 0 resultTerm)
        go depth (argumentType : rest) resultTerm = do
          domain <- shiftTerm depth 0 <$> quoteIn ctx argumentType
          codomain <- go (depth + 1) rest resultTerm
          pure
            ( CPiBoundFormedM
                Ordinary
                FormationOrdinary
                Expl
                QW
                False
                "__applicative_do_argument"
                Nothing
                domain
                codomain
            )

    applyApplicativeMember carrier member memberType typeArguments explicitArguments = do
      sources <- mapM (carrierSourceArgument ctx site carrier) typeArguments
      classifiers <-
        mapM (typeArgumentClassifier ctx site carrier) sources
      sourceTerms <- mapM (quoteIn ctx) sources
      let implicitArguments =
            [ (Impl, term, classifier)
            | (term, classifier) <- zip sourceTerms classifiers
            ]
          explicitSpine =
            [ (Expl, term, ty)
            | (term, ty) <- explicitArguments
            ]
      fst <$>
        applyGeneratedCoreSpine
          ctx
          site
          member
          memberType
          (implicitArguments ++ explicitSpine)

    applyRemaining liftA2Member liftA2Type carrier resultType (current, _) ((_, action, valueType), suffixTypes) = do
      nextResultType <- applicativeFunctionType suffixTypes resultType
      currentValueType <- applicativeFunctionType (valueType : suffixTypes) resultType
      applicationFunctionType <-
        applicativeFunctionType
          [currentValueType, valueType]
          nextResultType
      let applicationFunction =
            CLamM Ordinary Expl QW "__applicative_do_function" $
              CLamM Ordinary Expl QW "__applicative_do_value" $
                CApp Expl (CVar 1) (CVar 0)
      next <-
        applyApplicativeMember
          carrier
          liftA2Member
          liftA2Type
          [currentValueType, valueType, nextResultType]
          [ (applicationFunction, applicationFunctionType)
          , (current, actionType carrier currentValueType)
          , (action, actionType carrier valueType)
          ]
      pure (next, actionType carrier nextResultType)

    actionType carrier valueType =
      fromMaybe expected (monadResultType carrier valueType)

    tailsAfter values = [drop index values | index <- [1 .. length values]]
    second (_, value, _) = value
    third (_, _, value) = value

-- | A @do@ block whose result type is a user monad @m@ (one with a
-- @Monad@ instance) that is not one of the kernel carriers IO\/STM\/Eff\/
-- Elab. §18.8 specifies @do@ over an arbitrary enclosing monad; for a
-- control-flow-free block this is exactly the classic monadic
-- desugaring, so the items are rewritten to surface @(>>=)@\/lambda
-- applications and elaborated through the ordinary trait-method path
-- (which inserts the @Monad m@ dictionary). The supported item set
-- mirrors 'elabEffDo' — bind\/let\/expression\/statement-if; abrupt
-- control-flow items (which would need the §18.8 completion protocol
-- realized over @m@) are rejected here, exactly as in an Eff-typed do.
elabMonadDo :: Ctx -> Value -> [DoItem] -> Span -> CheckM (Term, Value)
elabMonadDo ctx me items0 sp
  | monadDoNeedsStructuredElaboration ctx items0 = do
      tm <- direct items0
      pure (tm, me)
  | otherwise = do
      e <- desugar items0
      tm <- check ctx e me
      pure (tm, me)
  where
    (mTy, resT) = case monadActionViewValue me of
      Just r -> r
      Nothing -> (me, me)

    bindOp = EVar (Name ">>=" sp)
    mkLam pat body = case pat of
      PVar n -> ELambda Nothing [simpleBinder n] body sp
      PWild _ -> ELambda Nothing [simpleBinder (Name "__u" sp)] body sp
      _ ->
        ELambda Nothing [simpleBinder (Name "__x" sp)]
          (EMatch (EVar (Name "__x" sp)) [MatchCase pat Nothing body sp] sp)
          sp
    mkBind pat act rest = EApp bindOp [ArgExplicit act, ArgExplicit (mkLam pat rest)]
    ifToExpr alts mels isp =
      let toExpr its = case its of
            [DoExpr e] -> e
            _ -> EDo Nothing its isp
       in EIf [(cnd, toExpr body) | (cnd, body) <- alts] (toExpr <$> mels) isp
    desugar [] = do
      errAt sp "E_DO_EMPTY" (Just "kappa-hs.do.empty")
        "a do block must end with an expression item (§18.2)"
      pure (EVar (Name "__u" sp))
    desugar [DoExpr e] = pure (e)
    desugar [DoIf alts mels isp] = pure (ifToExpr alts mels isp)
    desugar (item : rest) = case item of
      DoExpr e -> mkBind (PWild sp) (e) <$> desugar rest
      DoBind (LetBind _ _ pat _ rhs _) -> mkBind pat (rhs) <$> desugar rest
      DoAssign n True _ asp -> do
        errAt asp "E_ASSIGN_NOT_VAR" (Just "kappa-hs.do.assign-non-var")
          ("'" <> nameText n <> " <- ...' is mutable-var assignment syntax; use 'let "
             <> nameText n <> " <- ...' for monadic bind (§18.2)")
        desugar rest
      DoLet lb@(LetBind _ _ _ _ _ bsp) -> (\r -> ELet [lb] r bsp) <$> desugar rest
      DoIf alts mels isp -> mkBind (PWild sp) (ifToExpr alts mels isp) <$> desugar rest
      -- a refutable `let? p = rhs [else rp -> fe]` is a match over the pure rhs:
      -- the bound continuation on a match, the else (or Alternative.empty) on
      -- a miss. This also drives the
      -- §16.1 residue check on `p` (so a discarded relevant residue is rejected).
      DoLetQ pat rhs mElse dsp -> do
        rest' <- desugar rest
        let elseArm = case mElse of
              Just (rp, fe) -> MatchCase rp Nothing fe dsp
              Nothing ->
                MatchCase (PWild dsp) Nothing
                  (EDot (EVar (Name "Alternative" dsp)) (DotName (Name "empty" dsp)))
                  dsp
        pure (EMatch (rhs) [MatchCase pat Nothing rest' dsp, elseArm] dsp)
      other -> do
        unsupportedAt (doItemSpan other)
          "this do-item form is not supported in a user-monad do block by this implementation (§18.8)"
        desugar rest

    actionTy a =
      case monadResultType mTy a of
        Just ty -> pure ty
        Nothing -> do
          errAt sp "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
            "this user-monad do block has a higher-order monad shape this implementation cannot apply (§18.8)"
          pure me

    monadBind c a b act lam = do
      aSource <- carrierSourceArgument c sp mTy a
      bSource <- carrierSourceArgument c sp mTy b
      aTm <- quoteIn c aSource
      bTm <- quoteIn c bSource
      aClassifier <- typeArgumentClassifier c sp mTy aSource
      bClassifier <- typeArgumentClassifier c sp mTy bSource
      actionType <-
        case monadResultType mTy a of
          Just value -> pure value
          Nothing -> freshMetaV c
      resultActionType <-
        case monadResultType mTy b of
          Just value -> pure value
          Nothing -> freshMetaV c
      resultActionTypeTerm <- quoteIn c resultActionType
      continuationType <-
        evalIn c
          (CPiBoundFormedM Ordinary FormationOrdinary Expl QW False "_" Nothing
            aTm
            (shiftTerm 1 0 resultActionTypeTerm))
      monadGoal <- globalValueM prelMonad [(Expl, mTy)]
      monadDict <- resolveImplicit c sp monadGoal
      (bindMember, bindMemberType) <-
        knownTraitMemberProjection c sp prelMonad ">>=" monadGoal monadDict
      (application, actualResult) <-
        applyGeneratedCoreSpine
          c
          sp
          bindMember
          bindMemberType
          [ (Impl, aTm, aClassifier)
          , (Impl, bTm, bClassifier)
          , (Expl, act, actionType)
          , (Expl, lam, continuationType)
          ]
      coerceTerm c sp application actualResult resultActionType

    monadPure c a val = do
      source <- carrierSourceArgument c sp mTy a
      expectedAction <- actionTy a
      generatedApplicativePureAtM c sp mTy source val expectedAction

    checkAction c resultTy expression =
      canonicalApplicativePurePayload c expression >>= \case
        Just payload -> do
          source <- carrierSourceArgument c sp mTy resultTy
          check c payload source >>= monadPure c resultTy
        Nothing -> actionTy resultTy >>= check c expression

    bindDiscard target c a act rest =
      bindDiscardFrom target c c a act rest

    bindDiscardFrom target c cCont a act rest = do
      body <- directGo target (bindCtx "__u" False a cCont) rest
      monadBind c a target act (CLamM Ordinary Expl QW "__u" body)

    bindPattern target c pat a act rest =
      bindPatternFrom target c c pat a Nothing act rest

    bindPatternFrom target c cCont pat a mrhs act rest = do
      checkIrrefutable cCont pat a (patternSpan pat)
      lam <-
        handlerClauseLam cCont QW pat a $ \c' -> do
          cAliased <- case mrhs of
            Just rhs -> aliasCurrentReadPattern cCont pat rhs c'
            Nothing -> pure c'
          directGo target cAliased rest
      monadBind c a target act lam

    direct = directGo resT ctx

    directGo target c [] = do
      forceM target >>= \case
        VGlobN g [] | g == prelUnit -> do
          source <- carrierSourceArgument c sp mTy target
          unitTm <- generatedCtorAtM c source prelUnit
          monadPure c target unitTm
        _ -> do
          errAt sp "E_DO_EMPTY" (Just "kappa-hs.do.empty")
            "a do block must end with an expression item (§18.2)"
          fst <$> anyHole c
    directGo target c [DoIf alts mels isp] = directGo target c [DoExpr (ifToExpr alts mels isp)]
    directGo target c [DoExpr e0] = do
      rewriteVarInoutStatement c e0 >>= \case
          Just items -> directGo target c items
          Nothing -> do
            (pre, e) <- liftCurrentReadsExpr c (exprSpan e0) e0
            if not (null pre)
              then directGo target c (pre ++ [DoExpr e])
            else
              preferCheckByErrors
                (checkAction c target e)
                (do
                  source <- carrierSourceArgument c sp mTy target
                  valTm <- check c e source
                  monadPure c target valTm)
    directGo target c (item : rest) = case item of
      DoExpr e0 -> do
        rewriteVarInoutStatement c e0 >>= \case
          Just items -> directGo target c (items ++ rest)
          Nothing -> do
            (pre, e) <- liftCurrentReadsExpr c (exprSpan e0) e0
            if not (null pre)
              then directGo target c (pre ++ DoExpr e : rest)
              else do
                a <- freshMetaV c
                tm <- checkAction c a e
                registerDiscardedResult c (exprSpan e) a
                defaultPendingNumericGoals
                writes <- writtenRefFacetsExecutedExpr c e
                escapes <- escapedRefFacetsExecutedExpr c e
                let cAfter = applyVarCurrentEffects writes escapes c
                bindDiscardFrom target c cAfter a tm rest
      DoBind (LetBind implocal prefix pat mty rhs0 bsp) -> do
        rewritten <-
          if isNothing mty && not implocal && emptyBinderPrefix prefix
            then rewriteVarInoutBind VarInoutMonadic c pat rhs0
            else pure Nothing
        case rewritten of
          Just items -> directGo target c (items ++ rest)
          Nothing -> do
            (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
            if not (null pre)
              then directGo target c (pre ++ DoBind (LetBind implocal prefix pat mty rhs bsp) : rest)
              else do
                a <- case mty of
                  Just tyE -> do
                    (tyTm, _) <- inferType c tyE
                    evalIn c tyTm
                  Nothing -> freshMetaV c
                rhsTm <- checkAction c a rhs
                writes <- writtenRefFacetsExecutedExpr c rhs
                escapes <- escapedRefFacetsExecutedExpr c rhs
                let cAfter = applyVarCurrentEffects writes escapes c
                bindPatternFrom target c cAfter pat a (Just rhs) rhsTm rest
      DoLet (LetBind implocal prefix pat mty rhs0 bsp) -> do
        rewritten <-
          if isNothing mty && not implocal && emptyBinderPrefix prefix
            then rewriteVarInoutBind VarInoutPure c pat rhs0
            else pure Nothing
        case rewritten of
          Just items -> directGo target c (items ++ rest)
          Nothing -> do
            (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
            if not (null pre)
              then directGo target c (pre ++ DoLet (LetBind implocal prefix pat mty rhs bsp) : rest)
              else do
                -- A pure @let@ remains a semantic local-declaration boundary
                -- inside a structured user-monad block.  Reuse the ordinary
                -- local-let elaborator so inferred type and universe metas may
                -- be generalized after the complete RHS is checked.  In
                -- contrast, the @DoBind@ branch above deliberately introduces
                -- only a weak monomorphic continuation variable.
                escapes <- escapedRefFacetsExpr c rhs
                fst <$>
                  elabLetItemsWith
                    c
                    [LocalLetBinding (LetBind implocal prefix pat mty rhs bsp)]
                    ( \cDef -> do
                        let cEsc = foldr escapeVarCurrent cDef (Set.toList escapes)
                        cAliased <- aliasCurrentReadPattern c pat rhs cEsc
                        (,target) <$> directGo target cAliased rest
                    )
      DoVar n mty rhs0 vsp -> do
        (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
        if not (null pre)
          then directGo target c (pre ++ DoVar n mty rhs vsp : rest)
          else do
            refDict <- requireMonadRef c (nameSpan n) mTy
            (rhsTm, rhsTy) <- case mty of
              Just tyE -> do
                (tyTm, _) <- inferType c tyE
                tyV <- evalIn c tyTm
                tm <- check c rhs tyV
                pure (tm, tyV)
              Nothing -> do
                -- Keep the initializer's type flexible until the remainder of
                -- the do block has been checked.  A later static use of an
                -- immutable snapshot can legitimately determine an overloaded
                -- initializer (for example @var u = 0; let u0 = u; Type u0@).
                -- Numeric defaulting belongs at the declaration boundary, not
                -- at the mutable binding itself.
                tyV <- freshMetaV c
                tm <- check c rhs tyV
                pure (tm, tyV)
            rhsTyTm <- quoteIn c rhsTy
            refTy <- monadRefRefType c refDict rhsTyTm
            loweringW <- builtinIOMonadRefLowering c mTy refDict
            escapes <- escapedRefFacetsExpr c rhs
            let newAct = monadRefNewAction refDict rhsTyTm rhsTm
                refInfo =
                  VarRefInfo
                    rhsTy
                    rhsTyTm
                    refDict
                    mTy
                    (monadRefDiagnosticRefType rhsTy)
                    loweringW
                cVar = foldr escapeVarCurrent (bindCtxVar (nameText n) refTy refInfo c) (Set.toList escapes)
            recordMutableBindingFields c (nameSpan n) refTy refInfo
            body <- directGo target cVar rest
            monadBind c refTy target newAct (CLamM Ordinary Expl QW (nameText n) body)
      DoAssign n True rhs asp ->
        case lookupCtx (nameText n) c of
          Just (_, entry) | isJust (ceVarInfo entry) ->
            directAssign target c n True rhs asp rest
          _ -> directAssign target c n True rhs asp rest
      DoAssign n False rhs asp ->
        directAssign target c n False rhs asp rest
      DoIf alts mels isp -> do
        lifted <- liftCurrentReadsStmtIf c alts mels isp
        case lifted of
          Just items -> directGo target c (items ++ rest)
          Nothing -> directGo target c (DoExpr (ifToExpr alts mels isp) : rest)
      DoWhile ml cond0 body mels wsp ->
        directWhile target c ml cond0 body mels wsp rest
      DoFor ml pat source body Nothing fsp
        | doSuiteContainsReturn body
        , not (doSuiteContainsLoopControl body) ->
            directReturningFor target c ml pat source body fsp rest
      DoDecl declaration -> case declaration of
        -- Local type aliases are erased let-bindings and remain declaration
        -- boundaries inside a mutable user-monad do block. Reuse the same
        -- elaboration shape as pure blocks so a level index observes an
        -- immutable snapshot, while a direct mutable current facet is still
        -- rejected by the static-position checkpoint.
        DTypeAlias _ name parameters resultKind (Just rhs) declarationSpan ->
          let kind = fromMaybe (EVar (Name "Type" declarationSpan)) resultKind
              body = case parameters of
                [] -> rhs
                binders -> ELambda Nothing binders rhs declarationSpan
              annotation = Just (foldr EArrow kind parameters)
              prefix = BinderPrefix (Just Parametric) (Just S.QZero) Nothing
              binding = LetBind False prefix (PVar name) annotation body declarationSpan
           in fst <$> elabLetItemsWith c [LocalLetBinding binding]
                (\nextCtx -> (,target) <$> directGo target nextCtx rest)
        DLet _ (LetDef (Just name) _ Nothing _ prefix [] annotation Nothing rhs) declarationSpan ->
          let binding = LetBind False prefix (PVar name) annotation rhs declarationSpan
           in fst <$> elabLetItemsWith c [LocalLetBinding binding]
                (\nextCtx -> (,target) <$> directGo target nextCtx rest)
        _ -> do
          unsupportedAt (declSpan declaration)
            "this local declaration form is not supported in a mutable user-monad do block by this implementation"
          directGo target c rest
      other -> do
        unsupportedAt (doItemSpan other)
          "this do-item form is not supported in a mutable user-monad do block by this implementation (§18.8)"
        directGo target c rest

    -- The return-only completion fragment used by an early-exit iterator
    -- loop.  @None@ is normal fallthrough and @Some r@ is the enclosing
    -- function's return completion.  Keeping this channel typed avoids a
    -- Dynamic payload or a privileged exception path; every action is still
    -- assembled through the selected Monad dictionary.
    returningControlGo target c = go
      where
        controlType = globalValueM prelOption [(Expl, target)]
        normal = do
          ty <- controlType
          none <- generatedCtorAtM c ty prelNone
          monadPure c ty none
        returned expression = do
          payload <- check c expression target
          ty <- controlType
          some <- generatedCtorApplyAtM c ty prelSome [payload]
          monadPure c ty some
        go [] = normal
        go (DoReturn label payload returnSpan : _) = do
          forM_ label $ \name ->
            unless (Just (nameText name) == ctxReturnTarget c) $
              errAt
                (nameSpan name)
                "E_LABEL_UNRESOLVED"
                (Just "kappa-hs.do.label-unresolved")
                ( "return@" <> nameText name
                    <> " does not target the enclosing named function or labeled lambda (\16718.5/\16718.5.1)"
                )
          case payload of
            Just expression -> returned expression
            Nothing -> do
              unitType <- globalValueM prelUnit []
              expectType c returnSpan unitType target
              unitTerm <- generatedCtorAtM c unitType prelUnit
              ty <- controlType
              some <- generatedCtorApplyAtM c ty prelSome [unitTerm]
              monadPure c ty some
        go (DoIf alternatives fallback _ : rest) =
          branch alternatives
          where
            branch [] = go (fromMaybe [] fallback ++ rest)
            branch ((condition, body) : more) = do
              boolType <- globalValueM prelBool []
              conditionTerm <- check c condition boolType
              trueAction <- go (body ++ rest)
              falseAction <- branch more
              pure (CIf conditionTerm trueAction falseAction)
        go (DoExpr expression : rest) = do
          valueType <- freshMetaV c
          action <- checkAction c valueType expression
          registerDiscardedResult c (exprSpan expression) valueType
          ty <- controlType
          continuation <- go rest
          monadBind
            c
            valueType
            ty
            action
            (CLamM Ordinary Expl QW "__returning_for_unit" (shiftTerm 1 0 continuation))
        go (DoBind (LetBind _ _ pattern' annotation actionExpression bindSpan) : rest) = do
          valueType <- case annotation of
            Just typeExpression -> fst <$> inferType c typeExpression >>= evalIn c
            Nothing -> freshMetaV c
          action <- checkAction c valueType actionExpression
          checkIrrefutable c pattern' valueType bindSpan
          ty <- controlType
          continuation <-
            handlerClauseLam c QW pattern' valueType $ \next ->
              returningControlGo target next rest
          monadBind c valueType ty action continuation
        go (DoLet binding : rest) =
          fst <$>
            elabLetItemsWith
              c
              [LocalLetBinding binding]
              (\next -> (,target) <$> returningControlGo target next rest)
        go (item : rest) = do
          unsupportedAt
            (doItemSpan item)
            "this do-item form is not yet part of the typed return-completion fragment for an arbitrary-Monad iterator loop (\16718.8.5-\16718.8.14)"
          go rest

    directReturningFor target c _label pattern' source body loopSpan rest = do
      (sourceTerm0, sourceType0) <- infer c source
      (sourceTerm, sourceType) <-
        insertAllImplicits c (exprSpan source) sourceTerm0 sourceType0
      iteratorGoal <- globalValueM (gPrel "Iterator") [(Expl, sourceType)]
      iteratorDictionary <- resolveImplicit c loopSpan iteratorGoal
      let itemTypeTerm = CProjM Parametric iteratorDictionary "Item"
          nextTerm = CProjM Ordinary iteratorDictionary "next"
      itemType <- evalIn c itemTypeTerm
      sourceTypeTerm <- quoteIn c sourceType
      let stepPayloadTypeTerm =
            CRecordT
              [ ("item", itemTypeTerm)
              , ("rest", sourceTypeTerm)
              ]
      stepPayloadType <- evalIn c stepPayloadTypeTerm
      stepType <- globalValueM prelOption [(Expl, stepPayloadType)]
      stepTypeTerm <- quoteIn c stepType
      stepUniverses <- optionUniverses stepType
      controlType <- globalValueM prelOption [(Expl, target)]
      controlTypeTerm <- quoteIn c controlType
      controlUniverses <- optionUniverses controlType
      resultActionType <- actionTy controlType
      resultActionTypeTerm <- quoteIn c resultActionType
      loopActionType <- actionTy controlType
      loopActionTypeTerm <- quoteIn c loopActionType
      let loopTypeTerm =
            CPiBoundFormedM
              Ordinary
              FormationOrdinary
              Expl
              Q1
              False
              "__iterator"
              Nothing
              sourceTypeTerm
              (shiftTerm 1 0 loopActionTypeTerm)
      loopType <- evalIn c loopTypeTerm
      loopName <- freshNameM "__returning_for"
      let cLoop = bindCtx loopName False loopType c
          cIterator = bindCtxMQ Ordinary Q1 "__iterator" False sourceType cLoop
          stepTerm = CApp Expl (shiftTerm 2 0 nextTerm) (CVar 0)
          cStep = bindCtx "__step" False stepPayloadType cIterator
          itemProjection = CProjM Ordinary (CVar 0) "item"
          restProjectionUnderCompletion = CProjM Ordinary (CVar 1) "rest"
          cItem = bindCtx "__item" False itemType cStep
      (patternCore, cBody, patternRefinements) <-
        elabPattern cItem pattern' itemType
      bodyAction <-
        withPatternRefinements patternRefinements $
          returningControlGo target cBody body
      itemTypeInStep <- quoteIn cStep itemType
      actionTypeInItem <- quoteIn cItem loopActionType
      let boundBody =
            CLetM Ordinary QW "__item" itemTypeInStep itemProjection
              ( CMatch
                  (CVar 0)
                  (Just (shiftTerm 1 0 itemTypeInStep))
                  (Just actionTypeInItem)
                  [CaseAlt patternCore Nothing bodyAction]
              )
          cCompletion = bindCtx "__completion" False controlType cStep
          cReturned = bindCtx "__returned" False target cCompletion
      propagateReturn <- monadPure cReturned controlType (CVar 1)
      let recursiveCall = CApp Expl (CVar 3) restProjectionUnderCompletion
      completionActionTypeInCompletion <- quoteIn cCompletion loopActionType
      let continueOrReturn =
            CMatch
              (CVar 0)
              (Just (shiftTerm 1 0 controlTypeTerm))
              (Just completionActionTypeInCompletion)
              [ CaseAlt
                  (CPCtorM [] [] [] prelSome controlUniverses [CPVarM Ordinary "__returned"])
                  Nothing
                  propagateReturn
              , CaseAlt
                  (CPCtorM [] [] [] prelNone controlUniverses [])
                  Nothing
                  recursiveCall
              ]
      stepSomeBody <-
        monadBind
          cStep
          controlType
          controlType
          boundBody
          (CLamM Ordinary Expl QW "__completion" continueOrReturn)
      normalAtEnd <- do
        none <- generatedCtorAtM cIterator controlType prelNone
        monadPure cIterator controlType none
      let loopRhs =
            CLamM Ordinary Expl Q1 "__iterator" $
              CMatch
                stepTerm
                (Just (shiftTerm 2 0 stepTypeTerm))
                (Just (shiftTerm 2 0 resultActionTypeTerm))
                [ CaseAlt
                    (CPCtorM [] [] [] prelSome stepUniverses [CPVarM Ordinary "__step"])
                    Nothing
                    stepSomeBody
                , CaseAlt
                    (CPCtorM [] [] [] prelNone stepUniverses [])
                    Nothing
                    normalAtEnd
                ]
          loopCall = CApp Expl (CVar 0) (shiftTerm 1 0 sourceTerm)
          cDone = bindCtx "__completion" False controlType cLoop
          cReturn = bindCtx "__returned" False target cDone
      returnedAction <- monadPure cReturn target (CVar 0)
      normalAction <- directGo target cDone rest
      targetActionType <- actionTy target >>= quoteIn cDone
      let consumeCompletion =
            CMatch
              (CVar 0)
              (Just (shiftTerm 2 0 controlTypeTerm))
              (Just targetActionType)
              [ CaseAlt
                  (CPCtorM [] [] [] prelSome controlUniverses [CPVarM Ordinary "__returned"])
                  Nothing
                  returnedAction
              , CaseAlt
                  (CPCtorM [] [] [] prelNone controlUniverses [])
                  Nothing
                  normalAction
              ]
      loopResult <-
        monadBind
          cLoop
          controlType
          target
          loopCall
          (CLamM Ordinary Expl QW "__completion" consumeCompletion)
      pure (CLetRecM Ordinary QW loopName loopTypeTerm loopRhs loopResult)
      where
        optionUniverses value =
          forceM value >>= \case
            VGlobI global universes [_]
              | global == prelOption -> pure universes
            _ -> do
              errAt
                loopSpan
                "E_INTERNAL_PRELUDE_INTERFACE"
                (Just "kappa.internal.compiler")
                "the compiler-generated return completion did not have the canonical Option identity"
              pure []

    doSuiteContainsReturn = any go
      where
        go = \case
          DoReturn {} -> True
          DoIf alternatives fallback _ ->
            any (doSuiteContainsReturn . snd) alternatives
              || maybe False doSuiteContainsReturn fallback
          DoWhile _ _ nested fallback _ ->
            doSuiteContainsReturn nested
              || maybe False doSuiteContainsReturn fallback
          DoFor _ _ _ nested fallback _ ->
            doSuiteContainsReturn nested
              || maybe False doSuiteContainsReturn fallback
          DoExpr (EDo _ nested _) -> doSuiteContainsReturn nested
          _ -> False

    doSuiteContainsLoopControl = any go
      where
        go = \case
          DoBreak {} -> True
          DoContinue {} -> True
          DoIf alternatives fallback _ ->
            any (doSuiteContainsLoopControl . snd) alternatives
              || maybe False doSuiteContainsLoopControl fallback
          DoWhile _ _ nested fallback _ ->
            doSuiteContainsLoopControl nested
              || maybe False doSuiteContainsLoopControl fallback
          DoFor _ _ _ nested fallback _ ->
            doSuiteContainsLoopControl nested
              || maybe False doSuiteContainsLoopControl fallback
          DoExpr (EDo _ nested _) -> doSuiteContainsLoopControl nested
          _ -> False

    directAssign target c n monadic rhs0 asp rest = do
      (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
      if not (null pre)
        then directGo target c (pre ++ DoAssign n monadic rhs asp : rest)
        else case lookupCtx (nameText n) c of
          Just (i, entry)
            | Just info <- ceVarInfo entry -> do
                        let evidenceShift = i + 1
                            refDict = shiftTerm evidenceShift 0 (vriMonadRefDict info)
                            aTm = shiftTerm evidenceShift 0 (vriStoredTypeTerm info)
                            a = vriStoredType info
                            refTm = CVar i
                        rhsActTy <- actionTy a
                        rhsTm <- if monadic then check c rhs rhsActTy else check c rhs a
                        writes <-
                          if monadic
                            then Set.insert (nameText n) <$> writtenRefFacetsExecutedExpr c rhs
                            else pure (Set.singleton (nameText n))
                        escapes <-
                          if monadic
                            then escapedRefFacetsExecutedExpr c rhs
                            else escapedRefFacetsExpr c rhs
                        let cAfter = applyVarCurrentEffects writes escapes c
                        if monadic
                          then do
                            unitT <- globalValueM prelUnit []
                            let cAssign = bindCtx "__assign" False a c
                                cAfterAssign = bindCtx "__assign" False a cAfter
                                refTm' = shiftTerm 1 0 refTm
                                aTm' = shiftTerm 1 0 aTm
                                refDict' = shiftTerm 1 0 refDict
                                writeAct = monadRefWriteAction refDict' aTm' refTm' (CVar 0)
                            writeThen <- bindDiscardFrom target cAssign cAfterAssign unitT writeAct rest
                            monadBind c a target rhsTm (CLamM Ordinary Expl QW "__assign" writeThen)
                          else do
                            unitT <- globalValueM prelUnit []
                            let writeAct = monadRefWriteAction refDict aTm refTm rhsTm
                            bindDiscardFrom target c cAfter unitT writeAct rest
          Just _ -> do
            errAt asp "E_ASSIGN_NOT_VAR" (Just "kappa-hs.do.assign-non-var")
              ("'" <> nameText n <> "' is not a mutable var binding (§18.6.1)")
            directGo target c rest
          Nothing -> do
            if monadic
              then
                errAt asp "E_ASSIGN_NOT_VAR" (Just "kappa-hs.do.assign-non-var")
                  ("'" <> nameText n <> " <- ...' is mutable-var assignment syntax; use 'let "
                     <> nameText n <> " <- ...' for monadic bind (§18.2)")
              else
                errAt asp "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
                  ("unresolved name '" <> nameText n <> "'")
            directGo target c rest

    directWhile target c _ml cond0 body mels _wsp rest = do
      when (any isAbruptLoopItem body || maybe False (any isAbruptLoopItem) mels) $
        unsupportedAt (exprSpan cond0)
          "break/continue/return inside a user-monad while body requires the §18.8 completion protocol and is not part of this direct MonadRef lowering"
      boolT <- globalValueM prelBool []
      unitT <- globalValueM prelUnit []
      (pre, cond') <- liftCurrentReadsExpr c (exprSpan cond0) cond0
      let generatedAction = not (null pre)
          condD =
            if null pre
              then cond'
              else EDo Nothing (pre ++ [DoExpr cond']) (exprSpan cond0)
      condEither <-
        if generatedAction
          then do
            condActTy <- actionTy boolT
            Right <$> check c condD condActTy
          else do
            st0 <- get
            n0 <- gets (length . csDiags)
            pureCond <- check c condD boolT
            n1 <- gets (length . csDiags)
            if n1 == n0
              then pure (Left pureCond)
              else do
                put st0
                condActTy <- actionTy boolT
                Right <$> check c condD condActTy
      condWrites <- writtenRefFacetsExecutedExpr c condD
      condEscapes <- case condEither of
        Right {} -> escapedRefFacetsExecutedExpr c condD
        Left {} -> escapedRefFacetsExpr c condD
      let cCond = applyVarCurrentEffects condWrites condEscapes c
      bodyAct <- directGo unitT cCond body
      elseAct <- case mels of
        Just els -> directGo unitT cCond els
        Nothing -> do
          unitTm <- generatedCtorAtM c unitT prelUnit
          monadPure c unitT unitTm
      bodyWrites <- doItemsVarWrites cCond body
      elseWrites <- maybe (pure Set.empty) (doItemsVarWrites cCond) mels
      bodyEscapes <- doItemsVarEscapes cCond body
      elseEscapes <- maybe (pure Set.empty) (doItemsVarEscapes cCond) mels
      let cAfter =
            applyVarCurrentEffects
              (Set.union bodyWrites elseWrites)
              (Set.union bodyEscapes elseEscapes)
              cCond
      loopTy <- actionTy unitT
      loopTyTm <- quoteIn c loopTy
      loopName <- freshNameM "__loop"
      let cLoop = bindCtx loopName False loopTy c
          cAfterLoop = bindCtx loopName False loopTy cAfter
          shiftTo c' = shiftTerm (ctxLen c' - ctxLen c) 0
          seqBodyThenLoop c' loopIx =
            monadBind c' unitT unitT (shiftTo c' bodyAct) (CLamM Ordinary Expl QW "__u" (CVar (loopIx + 1)))
      loopRhs <- case condEither of
        Left condTm -> do
          thenAct <- seqBodyThenLoop cLoop 0
          pure (CIf (shiftTo cLoop condTm) thenAct (shiftTo cLoop elseAct))
        Right condAct -> do
          let cCond = bindCtx "__cond" False boolT cLoop
          thenAct <- seqBodyThenLoop cCond 1
          let branch = CIf (CVar 0) thenAct (shiftTo cCond elseAct)
          monadBind cLoop boolT unitT (shiftTo cLoop condAct) (CLamM Ordinary Expl QW "__cond" branch)
      after <- bindDiscardFrom target cLoop cAfterLoop unitT (CVar 0) rest
      pure (CLetRecM Ordinary QW loopName loopTyTm loopRhs after)

    isAbruptLoopItem = \case
      DoBreak {} -> True
      DoContinue {} -> True
      DoReturn {} -> True
      DoIf alts mels _ ->
        any (any isAbruptLoopItem . snd) alts || maybe False (any isAbruptLoopItem) mels
      DoWhile _ _ body mels _ ->
        any isAbruptLoopItem body || maybe False (any isAbruptLoopItem) mels
      DoFor _ _ _ body mels _ ->
        any isAbruptLoopItem body || maybe False (any isAbruptLoopItem) mels
      DoExpr (EDo _ body _) -> any isAbruptLoopItem body
      _ -> False

doItemSpan :: DoItem -> Span
doItemSpan = \case
  DoBind lb -> lbSpan lb
  DoLet lb -> lbSpan lb
  DoLetQ _ _ _ s -> s
  DoVar _ _ _ s -> s
  DoAssign _ _ _ s -> s
  DoExpr e -> exprSpan e
  DoUsing _ _ _ s -> s
  DoDefer _ _ s -> s
  DoReturn _ _ s -> s
  DoBreak _ s -> s
  DoContinue _ s -> s
  DoWhile _ _ _ _ s -> s
  DoFor _ _ _ _ _ s -> s
  DoIf _ _ s -> s
  DoDecl d -> declSpan d

declSpan :: Decl -> Span
declSpan = \case
  DSig _ _ _ sp -> sp
  DLet _ _ sp -> sp
  DData _ _ sp -> sp
  DTypeAlias _ _ _ _ _ sp -> sp
  DTrait _ _ sp -> sp
  DInstance _ sp -> sp
  DDerive _ sp -> sp
  DEffect _ _ sp -> sp
  DFixity _ sp -> sp
  DImport _ sp -> sp
  DExport _ sp -> sp
  DExpect _ _ sp -> sp
  DPattern _ _ sp -> sp
  DProjection _ _ _ _ _ sp -> sp
  DTopSplice _ sp -> sp
  DUnsafeAssert _ _ sp -> sp

-- ── if / match ───────────────────────────────────────────────────────

checkIf :: Ctx -> [(Expr, Expr)] -> Maybe Expr -> Span -> Value -> CheckM Term
checkIf ctx alts mels sp resT = do
  boolT <- globalValueM prelBool []
  go boolT ctx alts
  where
    applyCondEffects base cond = do
      writes <- writtenRefFacetsExecutedExpr base cond
      escapes <- escapedRefFacetsExecutedExpr base cond
      pure (applyVarCurrentEffects writes escapes base)
    go _ c [] = case mels of
      Just e -> check c e resT
      Nothing -> do
        errAt sp "E_IF_MISSING_ELSE" (Just "kappa-hs.control.if-missing-else")
          "if without else is only permitted as a do-block statement (§16.4, §18.4)"
        generatedCtorAtM c resT prelUnit
    go boolT c ((cnd, t) : rest) = do
      -- §7.4.1 flow refinement: constructor tests in the condition
      -- refine their subjects in the condition's own conjuncts and in
      -- the then-branch
      refs <- condRefines c cnd
      let ctxR = refineCtx refs c
      cTm <- check ctxR cnd boolT
      ctxREff <- applyCondEffects ctxR cnd
      branchCondition <- normalizeBranchConditionTerm ctxREff cTm
      -- §7.4.1/§16.1.8: a bare rigid Bool condition is branch-local
      -- equality evidence (b = True in then, b = False in else),
      -- consulted by conversion through the rigid-fact table
      let mLvl = case cnd of
            EVar n -> case lookupCtx (nameText n) c of
              Just (i, _) -> case drop i (ctxEnv c) of
                (VRigid l [] : _) -> Just l
                _ -> Nothing
              Nothing -> Nothing
            _ -> Nothing
          withFact ctorName act = do
            -- the condition's value is boolean branch-refinement
            -- evidence in the branch (a §3.2.3 proof source); rigid
            -- conditions additionally feed conversion's fact table
            oldBool <- gets csBoolFacts
            modify' $ \st ->
              st
                { csBoolFacts =
                    ScopedBoolFact (ctxLen ctxREff) branchCondition
                      (ctorName == ("True" :: Text))
                      : csBoolFacts st
                }
            r <- case mLvl of
              Nothing -> act
              Just l -> do
                oldFacts <- gets csFacts
                modify' $ \st ->
                  st {csFacts = Map.insert l (FactIs (VCtor (gPrel ctorName) [])) (csFacts st)}
                r0 <- act
                modify' $ \st -> st {csFacts = oldFacts}
                pure r0
            modify' $ \st -> st {csBoolFacts = oldBool}
            pure r
      tTm <- withFact "True" (check ctxREff t resT)
      -- the negative side refines the subject to the complementary
      -- constructors of its data type (§7.4.1 lacks-refinement); a bare
      -- `x is C` condition — or its §16.4.2 negation `not (x is C)` —
      -- licenses the complement
      negs <- condRefinesElse c cnd
      ctxFalseEff <- applyCondEffects (refineCtx negs c) cnd
      eTm <- withFact "False" (go boolT ctxFalseEff rest)
      pure (CIf cTm tTm eTm)

-- | Only a whole-condition single `x is C` test yields a usable
-- complement (a failed conjunction proves nothing positive), and
-- only a UNIQUE residual constructor is a usable fact: a wider
-- residual would invent a positive fact the test never proved.
complementRefines :: [(Text, [GName])] -> CheckM [(Text, [GName])]
complementRefines refs = fmap concat . forM refs $ \(x, gs) -> do
  st <- get
  case nub [ciData ci | g <- gs, Just ci <- [Map.lookup g (csCtors st)]] of
    [dataG]
      | Just di <- Map.lookup dataG (csDatas st)
      , [residual] <- [cg | cg <- diCtors di, cg `notElem` gs] ->
          pure [(x, [residual])]
    _ -> pure []

-- | §7.4.1/§7.4.2 refinements induced by an if-condition: `x is C`
-- refines x to {C}; conjunction collects both sides; disjunction
-- refines a subject to the union of constructors when both sides
-- refine it. The positive (then-side) refinements; see
-- 'condRefinesElse' for the negative (else-side) ones.
condRefines :: Ctx -> Expr -> CheckM [(Text, [GName])]
condRefines ctx = fmap fst . condRefinesBoth ctx

-- | §16.4.2: `not e` swaps the branch refinements: `if not a then t
-- else f ≡ if a then f else t`. So the else-side refinements of a
-- condition are the then-side refinements of its negation. Only a bare
-- (possibly negated) `x is C` test yields a usable complement; a failed
-- conjunction/disjunction proves nothing positive.
condRefinesElse :: Ctx -> Expr -> CheckM [(Text, [GName])]
condRefinesElse ctx = fmap snd . condRefinesBoth ctx

-- | The (then-side, else-side) constructor refinements a condition
-- induces. Resolving `not` here (rather than only in the if/match
-- checkers) means the negation laws compose through `&&`/`||`/thunks
-- exactly as the positive refinements do.
condRefinesBoth :: Ctx -> Expr -> CheckM ([(Text, [GName])], [(Text, [GName])])
condRefinesBoth ctx = go
  where
    go = \case
      EIs (EVar n) cref -> do
        mg <- quietCtor cref
        let pos = [(nameText n, [g]) | Just g <- [mg]]
        neg <- complementRefines pos
        pure (pos, neg)
      -- §16.4.2 negation: `not e` swaps the then/else refinements.
      EApp f [ArgExplicit e] -> do
        isNot <- exprResolvesToGlobal ctx f prelNot
        if isNot
          then do
            (pos, neg) <- go e
            pure (neg, pos)
          else pure ([], [])
      EApp f [ArgExplicit l, ArgExplicit r] -> do
        isAnd <- exprResolvesToGlobal ctx f prelAnd
        isOr <- if isAnd then pure False else exprResolvesToGlobal ctx f prelOr
        if isAnd
          then do
            (lp, _) <- go l
            (rp, _) <- go r
            -- a failed conjunction proves nothing positive (§7.4.1)
            pure (lp ++ rp, [])
          else if isOr
            then do
              (lp, _) <- go l
              (rp, _) <- go r
              pure ([(x, gs ++ gs') | (x, gs) <- lp, (x', gs') <- rp, x == x'], [])
            else pure ([], [])
      EThunk e _ -> go e
      _ -> pure ([], [])
    quietCtor (CtorRef mqual n) = do
      st <- get
      let inScope = constructorInScope st
          cands = case mqual of
            Nothing ->
              [g | (g, _) <- Map.toList (csCtors st), gnameText g == nameText n, inScope g]
            Just q ->
              [ ctorG
              | (dg, di) <- Map.toList (csDatas st)
              , gnameText dg == nameText q
              , inScope dg
              , ctorG <- diCtors di
              , gnameText ctorG == nameText n
              ]
      pure (case cands of (g : _) -> Just g; [] -> Nothing)

exprResolvesToGlobal :: Ctx -> Expr -> GName -> CheckM Bool
exprResolvesToGlobal ctx expr expected = do
  st0 <- get
  n0 <- gets (length . csDiags)
  tm <- fst <$> infer ctx expr
  n1 <- gets (length . csDiags)
  put st0
  pure (n1 == n0 && headGlobalOf tm == Just expected)

checkMatch :: Ctx -> Expr -> [MatchCase] -> Span -> Value -> CheckM Term
checkMatch ctx scrut cases sp resT = do
  hasAp <- or <$> mapM caseUsesActive cases
  if hasAp
    then do
      lowered <- lowerActiveMatch ctx scrut cases sp
      check ctx lowered resT
    else checkMatchPlain ctx scrut cases sp resT
  where
    caseUsesActive = \case
      MatchCase pat _ _ _ -> patUsesActive pat
      MatchImpossible _ -> pure False
    patUsesActive pat = case pat of
      PCtor cref ps _ | not (null ps) -> do
        mc <- peekCtor ctx cref
        case mc of
          Just _ -> pure False
          Nothing -> do
            mAp <- lookupActivePattern cref
            case mAp of
              Just _ -> pure True
              Nothing -> isJust <$> lookupGlobalName (nameText (crName cref))
      PActive {} -> pure True
      _ -> pure False

-- | 'resolveCtor' without the unresolved-constructor diagnostic: used
-- while classifying possible active-pattern heads (§17.3.2).
peekCtor :: Ctx -> CtorRef -> CheckM (Maybe (GName, CtorInfo))
peekCtor ctx cref = do
  st0 <- get
  r <- resolveCtor ctx cref
  case r of
    Just _ -> pure r
    Nothing -> put st0 >> pure Nothing

-- | Find an active pattern by (unqualified) head name; same-module
-- definitions take precedence over imported ones (§17.3).
lookupActivePattern :: CtorRef -> CheckM (Maybe APInfo)
lookupActivePattern (CtorRef _ n) = do
  st <- get
  let nm = nameText n
      cands = [(g, i) | (g, i) <- Map.toList (csActive st), gnameText g == nm]
      own = [i | (GName m _, i) <- cands, m == csModule st]
  pure $ case own ++ map snd cands of
    (i : _) -> Just i
    [] -> Nothing

-- | Lower a match containing active-pattern cases (§17.3.2) into
-- nested matches over the pattern functions' results: Option results
-- test Some/None, Match results thread the Miss residue into the
-- remaining cases, and total view results match the view value
-- directly (consecutive cases with the same head share one view
-- match, preserving exhaustiveness over the view type).
lowerActiveMatch :: Ctx -> Expr -> [MatchCase] -> Span -> CheckM Expr
lowerActiveMatch ctx scrut cases sp = case scrut of
  EVar _ -> goCases scrut cases
  _ -> do
    sv <- freshNameM "__apscrut"
    let svn = Name sv sp
    inner <- goCases (EVar svn) cases
    pure (ELet [LetBind False emptyPrefix (PVar svn) Nothing scrut sp] inner sp)
  where
    goCases se cs = do
      classified <- mapM classify cs
      build se classified
    classify c@(MatchImpossible _) = pure (CPlain c)
    classify c@(MatchCase pat mguard body csp) = case pat of
      PCtor cref ps _ | not (null ps) -> do
        mc <- peekCtor ctx cref
        case mc of
          Just _ -> pure (CPlain c)
          Nothing -> do
            mAp <- lookupActivePattern cref
            case mAp of
              Just info -> case mapM activePatArgExpr (init ps) of
                Just args -> pure (CActive (crName cref) info args (last ps) mguard body csp)
                Nothing -> do
                  unsupportedAt csp "this active-pattern argument form is not supported by this implementation"
                  pure (CBad csp)
              Nothing -> do
                mg <- lookupGlobalName (nameText (crName cref))
                case mg of
                  Just _ -> do
                    errAt csp "E_PATTERN_HEAD_NOT_CONSTRUCTOR_OR_ACTIVE_PATTERN" (Just "kappa-hs.pattern.head")
                      ("'" <> nameText (crName cref)
                         <> "' is neither a constructor nor an active pattern, so it cannot head a pattern (§17.3.2)")
                    pure (CBad csp)
                  Nothing -> pure (CPlain c)
      PActive cref args vp psp -> do
        mAp <- lookupActivePattern cref
        case mAp of
          Just info -> pure (CActive (crName cref) info args vp mguard body psp)
          Nothing -> do
            errAt psp "E_PATTERN_HEAD_NOT_CONSTRUCTOR_OR_ACTIVE_PATTERN" (Just "kappa-hs.pattern.head")
              ("'" <> nameText (crName cref) <> "' is not an active pattern (§17.3.2)")
            pure (CBad psp)
      _ -> pure (CPlain c)
    apApp n args se = EApp (EVar n) (map ArgExplicit (args ++ [se]))
    pcon nm ps = PCtor (CtorRef Nothing (Name nm sp)) ps sp
    pconMember owner nm ps =
      PCtor (CtorRef (Just (Name owner sp)) (Name nm sp)) ps sp

    build se classified = case classified of
      [] -> pure (EMatch se [] sp)
      (CBad _ : rest) -> build se rest
      (CPlain _ : _) -> do
        let (plains, rest) = span isPlain classified
            plainCases = [c | CPlain c <- plains]
        if null rest
          then pure (EMatch se plainCases sp)
          else do
            r <- freshNameM "__apk"
            let rn = Name r sp
            inner <- build (EVar rn) rest
            pure (EMatch se (plainCases ++ [MatchCase (PVar rn) Nothing inner sp]) sp)
      (CActive n info args vp mguard body csp : rest) -> case apResult info of
        APOption -> do
          inner <- build se rest
          pure $
            EMatch (apApp n args se)
              [ MatchCase (pcon "Some" [vp]) mguard body csp
              , MatchCase (PWild sp) Nothing inner sp
              ]
              sp
        APMatch -> do
          r <- freshNameM "__apresid"
          let rn = Name r sp
          inner <- build (EVar rn) rest
          pure $
            EMatch (apApp n args se)
              [ MatchCase (pconMember "Match" "Hit" [vp]) mguard body csp
              , MatchCase (pconMember "Match" "Miss" [PVar rn]) Nothing inner sp
              ]
              sp
        APTotal -> do
          let sameHead = \case
                CActive n2 i2 _ _ _ _ _ -> nameText n2 == nameText n && apResult i2 == APTotal
                _ -> False
              (run, rest') = span sameHead (CActive n info args vp mguard body csp : rest)
              viewCases = [MatchCase vp' g' b' c' | CActive _ _ _ vp' g' b' c' <- run]
          extra <-
            if null rest'
              then pure []
              else do
                inner <- build se rest'
                pure [MatchCase (PWild sp) Nothing inner sp]
          pure (EMatch (apApp n args se) (viewCases ++ extra) sp)
      where
        isPlain = \case
          CPlain _ -> True
          _ -> False

-- | One classified match case during active-pattern lowering.
data CaseClass
  = CPlain !MatchCase
  | CActive !Name !APInfo ![Expr] !Pattern !(Maybe Expr) !Expr !Span
  | CBad !Span

-- | Rewrite @let? P args (vp) = e@ over an active pattern P into the
-- corresponding match on @P args e@ (§17.3.2). A Match-result pattern
-- threads a residue, which a plain @let?@ cannot receive.
rewriteActiveLetQ :: Ctx -> Pattern -> Expr -> Span -> CheckM (Pattern, Expr)
rewriteActiveLetQ ctx pat rhs dsp = case pat of
  PCtor cref ps psp | not (null ps) -> do
    mc <- peekCtor ctx cref
    case mc of
      Just _ -> pure (pat, rhs)
      Nothing -> do
        mAp <- lookupActivePattern cref
        case mAp of
          Nothing -> pure (pat, rhs)
          Just info -> case mapM activePatArgExpr (init ps) of
            Nothing -> pure (pat, rhs)
            Just args -> do
              let app = EApp (EVar (crName cref)) (map ArgExplicit (args ++ [rhs]))
                  vp = last ps
              case apResult info of
                APOption -> pure (PCtor (CtorRef Nothing (Name "Some" psp)) [vp] psp, app)
                APMatch -> do
                  errAt dsp "E_ACTIVE_PATTERN_MATCH_RESULT_NOT_ALLOWED_IN_PLAIN_LET_QUESTION"
                    (Just "kappa-hs.pattern.active")
                    "a Match-result active pattern threads a residue on a miss and may not be used in a plain 'let?'; use a match with a residue case instead (§17.3.2)"
                  pure
                    ( PCtor
                        (CtorRef (Just (Name "Match" psp)) (Name "Hit" psp))
                        [vp]
                        psp
                    , app
                    )
                APTotal -> pure (vp, app)
  _ -> pure (pat, rhs)

-- | Convert an active-pattern argument (written in pattern position)
-- to the expression it denotes (§17.3.2).
activePatArgExpr :: Pattern -> Maybe Expr
activePatArgExpr = \case
  PLit (LInt v msuf) psp -> Just (EIntLit v ((`Name` psp) <$> msuf) psp)
  PLit (LFloat v msuf) psp -> Just (EFloatLit v ((`Name` psp) <$> msuf) psp)
  PVar n -> Just (EVar n)
  _ -> Nothing

-- | Recover a lexical rigid through an explicit, proof-carrying universe
-- coercion.  The wrapper changes only the classifier level and therefore
-- preserves the term identity used by branch-local flow facts.  No other
-- neutral/application shape is accepted.
rigidLevelThroughUniverseLift :: Value -> Maybe Int
rigidLevelThroughUniverseLift = \case
  VRigid level [] -> Just level
  VUniverseLift _ _ _ inner -> rigidLevelThroughUniverseLift inner
  _ -> Nothing

checkMatchPlain :: HasCallStack => Ctx -> Expr -> [MatchCase] -> Span -> Value -> CheckM Term
checkMatchPlain ctx scrut cases sp resT = do
  (sTm, sTy) <- infer ctx scrut
  (sTm1, sTy1) <- insertAllImplicits ctx (exprSpan scrut) sTm sTy
  sTyForced <- forceM sTy1
  scrutineeBoolCondition <-
    if nominalFamilyValueHead sTyForced == Just prelBool
      then Just <$> normalizeBranchConditionTerm ctx sTm1
      else pure Nothing
  -- Match annotations describe the eliminator at its enclosing scope. Quote
  -- them before checking any arm: branch facts may force an outer neutral to
  -- a constructor containing arm-local rigids, and such a value must never
  -- escape through Core metadata. Unsolved metas in these snapshots remain
  -- available to the ordinary final zonking pass.
  sTyTm <- quoteIn ctx sTy1
  resTyTm <- quoteIn ctx resT
  -- a variable scrutinee yields branch-local rigid facts: the matched
  -- nullary constructor on the success side, the lacks-set on later
  -- cases (dependent-match normalization, §7.4.1)
  let mLvl = case scrut of
        EVar n -> case lookupCtx (nameText n) ctx of
          Just (i, _) -> case drop i (ctxEnv ctx) of
            (value : _) -> rigidLevelThroughUniverseLift value
            _ -> Nothing
          Nothing -> Nothing
        _ -> Nothing
      -- §13.1.4: in a variant match, a `(| ..rest |)` clause's binder has type
      -- `Variant r`, where r is the scrutinee's members MINUS those matched by
      -- earlier clauses. We thread the covered member tags through the fold and
      -- narrow the residual binder accordingly.
      variantResidual c = case c of
        PVariant Nothing Nothing _ (Just restN) _ -> Just restN
        _ -> Nothing
      goCase (accAlts, checkedCases, prior, covered) c = case c of
        MatchImpossible isp -> do
          empty <- matchRemainderEmpty ctx sTy1 Nothing checkedCases
          unless empty $
            errAt isp "E_INDEXED_IMPOSSIBLE_REACHABLE" (Just "kappa.proof.impossible-reachable")
              "'case impossible' requires the remaining scrutinee type to be uninhabited (§17.1.5)"
          pure (accAlts, checkedCases, prior, covered)
        MatchCase (PWild patternSite) mguard body caseSite
          | not (null [() | (_, Nothing) <- checkedCases]) -> do
              state <- get
              case residualCatchAllPatterns state sTy1 checkedCases patternSite of
                Just residuals ->
                  foldM
                    goCase
                    (accAlts, checkedCases, prior, covered)
                    [MatchCase pattern' mguard body caseSite | pattern' <- residuals]
                Nothing ->
                  checkCase accAlts checkedCases prior covered (PWild patternSite) mguard body
        MatchCase pat mguard body _ ->
          checkCase accAlts checkedCases prior covered pat mguard body
      checkCase accAlts checkedCases prior covered pat mguard body = do
          sVarF <- forceM sTy1
          (patC, ctx', patternRefinements) <- case (variantResidual pat, sVarF) of
            (Just restN, VVariantT members) -> do
              memberTags <- mapM (tagOf ctx) members
              let residual = [m | (m, t) <- zip members memberTags, t `notElem` covered]
              pure
                ( CPInjectRestM Ordinary covered
                , bindCtx (nameText restN) False (VVariantT residual) ctx
                , emptyPatternRefinements
                )
            _ -> do
              scrutineeValue <- evalIn ctx sTm1
              scrutineeObservation <- observationJudgmentForTerm ctx sTm1 sTy1
              elabPatternFrom
                (ojMode scrutineeObservation)
                QW
                (Just scrutineeValue)
                ctx
                pat
                sTy1
          surroundingFacts <- gets csFacts
          let PatternRefinements branchRefinements = patternRefinements
          modify' $ \state ->
            state {csFacts = Map.union branchRefinements surroundingFacts}
          -- Replay the checked, serialized constructor-result equations into
          -- conversion facts for this branch.  The pattern certificate is the
          -- durable authority here: transient elaboration facts may have been
          -- created before existential pattern binders extended the context,
          -- while each 'ConstructorForcedEquality' is quoted at exactly the
          -- final branch depth.  This is generic GADT refinement, so a
          -- user-defined @Equal a b@/@Refl : Equal a a@ follows the same path
          -- as the standard equality family.
          certifiedRefinements <- rootConstructorForcedRefinements ctx' patC
          modify' $ \state ->
            state
              { csFacts =
                  Map.union certifiedRefinements (csFacts state)
              }
          -- §17.1.7: a variable scrutinee is flow-refined to this arm's
          -- constructor inside the arm, mirroring `if … is C`. This lets
          -- member projection on the scrutinee (`match b case Full v ->
          -- b.val`) consult the refined constructor set (§7.4.1).
          let ctx'' = case (scrut, patC) of
                (EVar n, CPCtor g _ _) -> refineCtx [(nameText n, [g])] ctx'
                _ -> ctx'
          -- §7.4.1 dependent-match value refinement: in this arm the
          -- scrutinee equals its constructor pattern, so substitute the
          -- complete typed constructor value for the scrutinee rigid via
          -- 'FactIs'. Nullary constructors still carry declaration universes
          -- and hidden erased arguments; rebuilding them through the
          -- payload-only 'VCtor' compatibility view would discard those facts.
          -- The reconstruction is conservative: anything outside a plain
          -- binder shape records no positive fact (only the 'FactNot'
          -- lacks-fact), which is always sound — it just forgoes refinement.
          fact <- case patC of
            CPCtor _ _ _ -> do
              complete <- constructorPatternFact ctx sTy1 patC
              pure $ case complete of
                Just value -> Just (FactIs value)
                Nothing | not (null prior) -> Just (FactNot prior)
                Nothing -> Nothing
            _ | not (null prior) -> pure (Just (FactNot prior))
            _ -> pure Nothing
          forM_ ((,) <$> mLvl <*> fact) $ \(l, f) ->
            modify' $ \st -> st {csFacts = Map.insert l f (csFacts st)}
          -- Matching a checked Bool expression establishes the same scoped
          -- proposition as an if-condition. This must cover non-variable
          -- scrutinees too: indexed result construction in the arm may need
          -- the fact that the exact checked expression is True or False.
          oldBool <- gets csBoolFacts
          forM_ ((,) <$> scrutineeBoolCondition <*> boolPatternTruth patC) $ \(condition, truth) ->
            modify' $ \state ->
              state
                { csBoolFacts =
                    ScopedBoolFact (ctxLen ctx) condition truth
                      : csBoolFacts state
                }
          boolT <- globalValueM prelBool []
          gTm <- traverse (\g -> check ctx'' g boolT) mguard
          branchGuard <- traverse (normalizeBranchConditionTerm ctx'') gTm
          -- §17.1.9: the arm's guard holds while checking its body, so push
          -- it as boolean evidence (a §3.2.3 proof source consulted by
          -- conversion through 'csBoolFacts'); e.g. `case _ if y <= x ->
          -- x - y` discharges the checked-subtraction obligation. The
          -- if-expression and try-match paths already do this.
          forM_ branchGuard $ \gt ->
            modify' $ \st ->
              st {csBoolFacts = ScopedBoolFact (ctxLen ctx'') gt True : csBoolFacts st}
          -- §17.1.4: a bare `impossible` body is accepted exactly when this
          -- arm's §30.2.7-refined fiber is provably uninhabited. Expose that
          -- verdict to the body via 'csImpossibleScrut' (saved/restored).
          oldImp <- gets csImpossibleScrut
          fiberEmpty <- branchFiberEmpty ctx' sTy1 patC
          modify' $ \st -> st {csImpossibleScrut = Just fiberEmpty}
          -- A bare §17.1.4 `impossible` has no Core value. Once this exact
          -- constructor fiber is proved empty, omit the dead alternative
          -- instead of manufacturing a polymorphic hole or an unverifiable
          -- universal inhabitant in KCoreText. The residual match still traps
          -- fail-closed if an invalid runtime representation reaches it.
          bTm <- case body of
            EImpossible _ | fiberEmpty -> pure Nothing
            _ -> Just <$> check ctx'' body resT
          modify' $ \st ->
            st
              { csFacts = surroundingFacts
              , csBoolFacts = oldBool
              , csImpossibleScrut = oldImp
              }
          let prior' = prior ++ [g | CPCtor g _ _ <- [patC]]
              covered' = covered ++ [t | CPInject t _ <- [patC]]
              alts' = case bTm of
                Nothing -> accAlts
                Just branch -> accAlts ++ [CaseAlt patC gTm branch]
          pure (alts', checkedCases ++ [(patC, gTm)], prior', covered')
      boolPatternTruth = \case
        CPCtor constructor _ []
          | constructor == prelTrue -> Just True
          | constructor == prelFalse -> Just False
        _ -> Nothing
  nErrsBefore <- gets (length . filter isError . csDiags)
  (alts, checkedCases, _, _) <- foldM goCase ([], [], [], []) cases
  nErrsAfter <- gets (length . filter isError . csDiags)
  when (nErrsAfter == nErrsBefore) $
    checkEqualityMatchHLevel
      ctx
      sp
      sTm1
      sTy1
      sTyTm
      resTyTm
      checkedCases
  -- §16.4.1: a flow-refined variable scrutinee (e.g. after `if e is C`)
  -- only needs the refined constructor subset covered for exhaustiveness.
  let scrutRefined = case scrut of
        EVar n -> ctxRefinementOf ctx (nameText n)
        _ -> Nothing
  -- §3.1: a match whose arms already failed to type against the
  -- scrutinee gets no piled-on exhaustiveness diagnostic
  when (nErrsAfter == nErrsBefore) $
    checkExhaustive ctx sp sTy1 scrutRefined checkedCases
  -- KBackendIR Stage 0: retain both the scrutinee's monomorphic type and the
  -- checked result motive. Later representation and KCoreText passes consume
  -- these outer-scope annotations rather than reconstructing them from arm
  -- syntax.
  sTyTm' <- zonkTermM (ctxLen ctx) sTyTm
  resTyTm' <- zonkTermM (ctxLen ctx) resTyTm
  unless (termScopedAt (ctxLen ctx) resTyTm') $
    error
      ( "Kappa.Check.checkMatchPlain: internal error: match result motive escaped its enclosing scope"
          <> "\npre-zonk: " <> show resTyTm
          <> "\npost-zonk: " <> show resTyTm'
          <> "\n"
          <> prettyCallStack callStack
      )
  pure (CMatch sTm1 (Just sTyTm') (Just resTyTm') alts)

-- | Enforce §11.4.1 without privileging the prelude equality spelling. A
-- reflexive relation is recognized from its checked declaration identity and
-- constructor telescope: one fieldless constructor returns the same
-- constructor-bound endpoint in two family positions, and that endpoint's
-- binder domain is another family argument. Eliminating a self-fiber into a
-- motive that contains the matched proof would then require K/UIP. Ordinary
-- path induction (distinct endpoints or a proof-independent motive) remains
-- available, while direct IsProp evidence for the fiber or IsSet evidence for
-- the endpoint carrier authorizes the stronger elimination.
checkEqualityMatchHLevel
  :: Ctx
  -> Span
  -> Term
  -> Value
  -> Term
  -> Term
  -> [(CorePat, Maybe Term)]
  -> CheckM ()
checkEqualityMatchHLevel
  ctx
  site
  scrutinee
  scrutineeType
  scrutineeTypeTerm
  motive
  checkedCases = do
    classification <- reflexiveSelfFiber ctx scrutineeType
    case classification of
      Nothing -> pure ()
      Just (constructor, carrier)
        | not (any (matchesConstructor constructor . fst) checkedCases) ->
            pure ()
        | not (termContainsAtScope scrutinee motive) ->
            pure ()
        | otherwise -> do
            propEvidence <-
              hLevelTraitEvidence ctx site prelIsProp scrutineeType
            setEvidence <- isSetEvidence ctx site carrier
            when (isNothing propEvidence && isNothing setEvidence) $ do
              carrierTerm <- quoteIn ctx carrier
              let relevance =
                    case stripIdentityWrappers scrutinee of
                      CVar index ->
                        case drop index (ctxEntries ctx) of
                          entry : _
                            | ceCoreQ entry == Q0 -> "erased"
                          _ -> "runtime-relevant"
                      _ -> "runtime-relevant"
                  payload =
                    withPayloadField "matchedEqualityProof" (renderTerm scrutinee)
                      $ withPayloadField "equalityType" (renderTerm scrutineeTypeTerm)
                      $ withPayloadField "endpointType" (renderTerm carrierTerm)
                      $ withPayloadField "inferredMotive" (renderTerm motive)
                      $ withPayloadField "requiredPrinciple" "K/UIP/proof-irrelevance"
                      $ withPayloadField
                          "missingEvidence"
                          "IsProp (matched equality type) or IsSet (endpoint type)"
                      $ withPayloadField
                          "hLevelEvidenceConsidered"
                          "direct/local/supertrait/registered IsProp and IsSet evidence"
                      $ withPayloadField "sourceOrigin" (T.pack (show site))
                      $ withPayloadField "scrutineeRelevance" relevance
                      $ payloadKind "equality-match-requires-hlevel"
              report $
                withPayload payload $
                  diag
                    SevError
                    StageElaborate
                    "E_EQUALITY_MATCH_REQUIRES_ISSET"
                    (Just "kappa.equality.match-requires-hlevel")
                    site
                    "proof-dependent elimination of this reflexive equality fiber requires IsProp evidence for the fiber or IsSet evidence for its endpoint carrier (§11.4.1)"
  where
    matchesConstructor expected = \case
      CPCtorM _ _ _ actual _ _ -> actual == expected
      _ -> False

-- | Recover the endpoint carrier of a structurally reflexive self-fiber.
-- Every decision is made from checked identities and typed telescopes. A
-- malformed, ambiguous, or more general singleton family is left
-- unclassified rather than being granted equality elimination rules.
reflexiveSelfFiber :: Ctx -> Value -> CheckM (Maybe (GName, Value))
reflexiveSelfFiber ctx scrutineeType = do
  forced <- forceM scrutineeType
  case forced of
    VGlobI family _ arguments -> do
      dataInfo <- gets (Map.lookup family . csDatas)
      constructors <- gets csCtors
      case dataInfo >>= singleConstructor of
        Nothing -> pure Nothing
        Just constructor ->
          case Map.lookup constructor constructors >>= reflexiveEndpointPositions family of
            Just (carrierPosition, leftPosition, rightPosition)
              | maximum [carrierPosition, leftPosition, rightPosition]
                  < length arguments -> do
                  let values = map snd arguments
                      carrier = values !! carrierPosition
                      leftEndpoint = values !! leftPosition
                      rightEndpoint = values !! rightPosition
                  evaluation <- ec_
                  pure $
                    if convertible
                         evaluation
                         (ctxLen ctx)
                         (force evaluation leftEndpoint)
                         (force evaluation rightEndpoint)
                      then Just (constructor, carrier)
                      else Nothing
            _ -> pure Nothing
    _ -> pure Nothing
  where
    singleConstructor DataInfo {diCtors = [constructor]} = Just constructor
    singleConstructor _ = Nothing

reflexiveEndpointPositions
  :: GName
  -> CtorInfo
  -> Maybe (Int, Int, Int)
reflexiveEndpointPositions family constructor = do
  guard (ciData constructor == family)
  guard (null (ciSourceFields constructor))
  let (binders, result) = constructorTelescope (ciType constructor)
      (headTerm, resultArguments) =
        spineOfTerm (stripIdentityWrappers result)
      arguments =
        [stripIdentityWrappers argument | (_, argument) <- resultArguments]
  guard (termHeadGlob (stripIdentityWrappers headTerm) == Just family)
  (leftPosition, rightPosition, endpointVariable) <-
    case
        [ (left, right, variable)
        | (left, leftTerm) <- zip [0 :: Int ..] arguments
        , (right, rightTerm) <- zip [0 :: Int ..] arguments
        , left < right
        , leftTerm == rightTerm
        , CVar variable <- [leftTerm]
        ]
      of
        [positions] -> Just positions
        _ -> Nothing
  let binderCount = length binders
      binderPosition = binderCount - endpointVariable - 1
  guard (binderPosition >= 0 && binderPosition < binderCount)
  let endpointDomain =
        shiftTerm
          (binderCount - binderPosition)
          0
          (binders !! binderPosition)
      carrierPositions =
        [ position
        | (position, argument) <- zip [0 :: Int ..] arguments
        , argument == stripIdentityWrappers endpointDomain
        ]
  carrierPosition <- case carrierPositions of
    [position] -> Just position
    _ -> Nothing
  pure (carrierPosition, leftPosition, rightPosition)
  where
    constructorTelescope = go []
      where
        go domains (CPiEvidenceM _ _ _ _ _ _ _ _ domain codomain) =
          go (domains ++ [domain]) codomain
        go domains result = (domains, result)

-- | Does a term from the surrounding scope occur in another term at that
-- scope? The needle is shifted under each traversed binder before comparison,
-- so dependent motives remain detectable beneath Pi/lambda/match nodes.
termContainsAtScope :: Term -> Term -> Bool
termContainsAtScope needle =
  getAny . foldTermWithDepth occurrence 0
  where
    normalizedNeedle = stripIdentityWrappers needle
    occurrence depth candidate =
      Any
        ( stripIdentityWrappers candidate
            == shiftTerm depth 0 normalizedNeedle
        )

-- | Reconstruct the constructor occurrence established by a plain constructor
-- branch. An ordinary constructor with no existential, bridge, or hidden
-- source slots uses its exact runtime-shaped 'VCtor' value; this is the shape
-- transparent recursive equations eliminate. Constructors with hidden erased
-- arguments need the complete typed occurrence instead. Retaining only runtime
-- payload fields for that second class loses information, so a valid
-- constructor eta proof such as
--
-- @
-- match x
-- case Mk value -> refl
-- @
--
-- could not reduce when the equality reconstructed @x@ through named hidden
-- proof projections. The pattern elaborator has already introduced one rigid
-- branch-local slot for every result-undetermined implicit constructor
-- argument and one slot for every explicit field. Re-specialize the exact
-- constructor identity against the scrutinee type, then pair those slots with
-- the checked constructor spine. Result-undetermined generated family/index
-- arguments deliberately do not produce a positive fact: re-specializing such
-- a GADT branch can duplicate arithmetic/universe solving and the fact is not
-- required for refutation or exhaustiveness. Hidden quantity-zero SOURCE
-- fields are safe, however, and are exactly what constructor eta needs. This
-- is semantic reconstruction: source names never choose an argument, and any
-- arity/meta mismatch fails closed.
constructorPatternFact
  :: Ctx
  -> Value
  -> CorePat
  -> CheckM (Maybe Value)
constructorPatternFact outerCtx scrutineeType pattern' =
  case pattern' of
    CPCtorM existentialModes bridges hidden constructor patternUniverses fields
      | all plainPatternBinder fields -> do
          let plainRuntimeShape =
                null existentialModes
                  && null bridges
                  && null hidden
                  && all plainPatternBinder fields
          if plainRuntimeShape
            then
              pure
                ( Just
                    ( VCtor
                        constructor
                        [ VRigid (ctxLen outerCtx + index) []
                        | index <- [0 .. length fields - 1]
                        ]
                    )
                )
            else do
              constructors <- gets csCtors
              case Map.lookup constructor constructors of
                Nothing -> pure Nothing
                Just constructorInfo -> do
                  (_freshUniverses, _constructorType, arguments, namedBinders, explicitFields) <-
                    instantiateConstructorForFields
                      outerCtx
                      constructor
                      constructorInfo
                      scrutineeType
                      noSpan
                  let baseLevel = ctxLen outerCtx
                      existentialValues =
                        [ VRigid (baseLevel + index) []
                        | index <- [0 .. length existentialModes - 1]
                        ]
                      sourceFieldCount = length (ciSourceFields constructorInfo)
                      sourceStart = length namedBinders - sourceFieldCount
                      (prefixBinders, sourceBinders)
                        | sourceStart >= 0 = splitAt sourceStart namedBinders
                        | otherwise = (namedBinders, [])
                      sourceSlots =
                        interleaveConstructorSourceBinders hidden fields
                      sourceValues =
                        [ VRigid
                            ( baseLevel
                                + length existentialModes
                                + constructorBridgeBinderCount bridges
                                + index
                            )
                            []
                        | index <- [0 .. sourceFieldCount - 1]
                        ]
                      sourceByArgument = do
                        slots <- sourceSlots
                        guard (length slots == sourceFieldCount)
                        guard (length sourceBinders == sourceFieldCount)
                        guard (length sourceValues == sourceFieldCount)
                        guard
                          ( all
                              ( \(argumentIndex, _, _, _, _) ->
                                  argumentIndex >= 0
                                    && argumentIndex < length arguments
                              )
                              sourceBinders
                          )
                        guard
                          ( and
                              [ sourceSlotMatches
                                  (caIcit (arguments !! argumentIndex))
                                  slot
                              | ((argumentIndex, _, _, _, _), slot) <-
                                  zip sourceBinders slots
                              ]
                          )
                        pure
                          ( Map.fromList
                              [ (argumentIndex, value)
                              | ((argumentIndex, _, _, _, _), value) <-
                                  zip sourceBinders sourceValues
                              ]
                          )
                      unresolvedPrefixArguments =
                        [ argumentIndex
                        | (argumentIndex, _, _, _, _) <- prefixBinders
                        , argumentIndex >= 0
                        , Just argument <- [listToMaybe (drop argumentIndex arguments)]
                        , CMeta _ <- [stripIdentityWrappers (caTerm argument)]
                        ]
                      step sourceArguments (remainingExistentials, built) (argumentIndex, argument) =
                        case Map.lookup argumentIndex sourceArguments of
                          Just sourceValue ->
                            pure
                              ( remainingExistentials
                              , built ++ [constructorValueArg argument sourceValue]
                              )
                          Nothing ->
                            case stripIdentityWrappers (caTerm argument) of
                              CMeta _
                                | existentialValue : rest <- remainingExistentials ->
                                    pure
                                      ( rest
                                      , built ++ [constructorValueArg argument existentialValue]
                                      )
                              _ -> do
                                argumentValue <- evalIn outerCtx (caTerm argument)
                                pure
                                  ( remainingExistentials
                                  , built ++ [constructorValueArg argument argumentValue]
                                  )
                  case sourceByArgument of
                    Nothing -> pure Nothing
                    Just sourceArguments
                      | length explicitFields /= length fields
                          || length unresolvedPrefixArguments /= length existentialModes ->
                          pure Nothing
                      | otherwise -> do
                          (remainingExistentials, builtArguments) <-
                            foldM
                              (step sourceArguments)
                              (existentialValues, [])
                              (zip [0 :: Int ..] arguments)
                          pure $ do
                            guard (null remainingExistentials)
                            guard (length builtArguments == length arguments)
                            pure (VCtorI constructor patternUniverses builtArguments)
    _ -> pure Nothing
  where
    constructorValueArg argument value =
      ConstructorValueArg
        (caIcit argument)
        (caPayload argument)
        (caName argument)
        value
    sourceSlotMatches icit = \case
      Left _ -> icit == Impl
      Right _ -> icit == Expl

-- | §30.2.7 / §17.1.5: is the (refined) scrutinee type provably uninhabited?
-- Generalizes the old "zero-constructor data type" check into the full
-- conservative inhabitance fragment: 'Void'/'Unit'/'Bool', closed
-- sum/product/record cardinality, and GADT family-argument refinement all flow
-- through 'inhabitanceSummary'. Only an exact 'Empty' result is load-bearing;
-- everything else (including the old non-data fall-through) stays rejected.
scrutineeEmpty :: Ctx -> Value -> CheckM Bool
scrutineeEmpty ctx ty = do
  env <- mkInhabEnv ctx
  s <- inhabitanceSummary env SourceReachability ty
  pure (isEmpty s)

-- | Run the purpose-keyed inhabitance query against a completed checker state.
-- This is the public analysis boundary used by completion tooling, artifact
-- verification, and the standard harness. The query runs transactionally:
-- speculative evidence search and GADT refinement cannot alter the supplied
-- compilation state.
inhabitanceSummaryForState
  :: CheckState
  -> InhabitancePurpose
  -> Value
  -> InhabitanceSummary
inhabitanceSummaryForState state purpose ty =
  evalState
    (mkInhabEnv emptyCtx >>= \environment -> inhabitanceSummary environment purpose ty)
    state

-- | Scope-indexed exact symbolic-cardinality query (§30.2.7A). The depth is
-- the lexical KCore depth of the supplied type value.
symbolicCardinalityForState
  :: CheckState
  -> Int
  -> Value
  -> Maybe CardExpr
symbolicCardinalityForState state depth ty =
  evalState
    (mkInhabEnv emptyCtx >>= \environment -> symbolicCardinality environment depth ty)
    state

-- | Derive and independently replay a compiler-owned ordinal-representation
-- certificate. Source 'OrdinalRepresentation' evidence is deliberately not a
-- prerequisite for the required structural fragment and cannot create a
-- certificate by itself.
ordinalRepresentationForState
  :: CheckState
  -> RepresentationContext
  -> Int
  -> Value
  -> Maybe OrdinalRepresentationCertificate
ordinalRepresentationForState state context depth ty =
  evalState deriveAndReplay state
  where
    deriveAndReplay = do
      initial <- get
      candidate <- deriveOrdinalRepresentationCertificate context depth ty
      put initial
      replay <- deriveOrdinalEncoding depth Set.empty ty
      put initial
      pure $ do
        certificate <- candidate
        (encoding, erasedFields) <- replay
        guard (encoding == orcEncoding certificate)
        guard (sort erasedFields == sort (orcErasedFields certificate))
        guard (verifyOrdinalRepresentationCertificate certificate == Right ())
        pure certificate

exactNaturalRepresentationForState
  :: CheckState
  -> RepresentationContext
  -> Int
  -> Value
  -> Maybe ExactNaturalRepresentationCertificate
exactNaturalRepresentationForState state context depth ty =
  evalState deriveAndReplay state
  where
    deriveAndReplay = do
      initial <- get
      candidate <-
        deriveExactNaturalRepresentationCertificate context depth ty
      put initial
      replay <- deriveExactNaturalRepresentationCertificate context depth ty
      put initial
      pure $ do
        certificate <- candidate
        replayed <- replay
        guard (replayed == certificate)
        guard (verifyExactNaturalRepresentationCertificate certificate == Right ())
        pure certificate

refinementRepresentationForState
  :: CheckState
  -> RepresentationContext
  -> Int
  -> Value
  -> Maybe RefinementRepresentationCertificate
refinementRepresentationForState state context depth ty =
  evalState deriveAndReplay state
  where
    deriveAndReplay = do
      initial <- get
      candidate <-
        deriveRefinementRepresentationCertificate context depth ty
      put initial
      replay <- deriveRefinementRepresentationCertificate context depth ty
      put initial
      pure $ do
        certificate <- candidate
        replayed <- replay
        guard (replayed == certificate)
        guard (verifyRefinementRepresentationCertificate certificate == Right ())
        pure certificate

deriveOrdinalRepresentationCertificate
  :: RepresentationContext
  -> Int
  -> Value
  -> CheckM (Maybe OrdinalRepresentationCertificate)
deriveOrdinalRepresentationCertificate context depth ty = do
  evaluation <- ec_
  normalized <- forceM ty
  representedType <- pure (quote evaluation depth normalized)
  cardinality <- symbolicCardinalityForCurrentState depth normalized
  derived <- deriveOrdinalEncoding depth Set.empty normalized
  pure $ do
    exactCardinality <- cardinality
    (encoding, erasedFields) <- derived
    guard
      ( ordinalEncodingCardinality encoding
          == Just (normalizeCardExpr exactCardinality)
      )
    pure
      OrdinalRepresentationCertificate
        { orcContext = context
        , orcRepresentedType = representedType
        , orcTypeIdentity =
            representationTypeIdentity context representedType
        , orcSourceEvidenceIdentity = Nothing
        , orcCardinalityExpression = normalizeCardExpr exactCardinality
        , orcEncoding = encoding
        , orcErasedFields = sort (nub erasedFields)
        , orcProfileRestrictions = commonRepresentationRestrictions
        , orcCertificateVersion = 1
        , orcCheckerVersion = 1
        }

symbolicCardinalityForCurrentState :: Int -> Value -> CheckM (Maybe CardExpr)
symbolicCardinalityForCurrentState depth ty = do
  environment <- mkInhabEnv emptyCtx
  symbolicCardinality environment depth ty

deriveOrdinalEncoding
  :: Int
  -> Set GName
  -> Value
  -> CheckM (Maybe (OrdinalEncoding, [ConstructorFieldPath]))
deriveOrdinalEncoding depth seen ty = do
  normalized <- forceM ty
  case normalized of
    VGlobal family _ [(_, index)]
      | family == prelFin -> do
          evaluation <- ec_
          let cardinality = case force evaluation index of
                VLit (LitInt value)
                  | value >= 0 -> cardLiteral (fromInteger value)
                value -> cardIndex (quote evaluation depth value)
          erased <- directErasedFields depth normalized
          pure (Just (OrdinalFin cardinality, erased))
    VGlobal family _ [(_, base), (_, predicate)]
      | family == prelRefined ->
          deriveRefinedOrdinalEncoding depth seen normalized base predicate
    VRecordT fields -> do
      children <- mapM (deriveOrdinalEncoding depth seen . snd) fields
      pure $ do
        derived <- sequence children
        pure
          ( OrdinalRecord (map fst derived)
          , concatMap snd derived
          )
    VVariantT members -> do
      children <- mapM (deriveOrdinalEncoding depth seen) members
      pure $ do
        derived <- sequence children
        pure
          ( OrdinalVariant (map fst derived)
          , concatMap snd derived
          )
    VGlobal family _ _
      | family `Set.member` seen -> pure Nothing
      | otherwise -> deriveNominalOrdinalEncoding depth seen family normalized
    _ -> do
      environment <- mkInhabEnv emptyCtx
      summary <-
        inhabitanceSummary environment SourceReachability normalized
      pure $
        if summary == Contractible
          then Just (OrdinalContractible, [])
          else Nothing

deriveRefinedOrdinalEncoding
  :: Int
  -> Set GName
  -> Value
  -> Value
  -> Value
  -> CheckM (Maybe (OrdinalEncoding, [ConstructorFieldPath]))
deriveRefinedOrdinalEncoding depth seen represented base predicate = do
  range <- canonicalNatRangeBounds depth base predicate
  case range of
    Just (lower, upper) -> do
      erased <- directErasedFields depth represented
      pure (Just (OrdinalInclusiveRange lower upper, erased))
    Nothing -> do
      accepted <- finiteRefinementOrdinals base predicate
      baseEncoding <- deriveOrdinalEncoding depth seen base
      erased <- directErasedFields depth represented
      pure $ do
        ordinals <- accepted
        (encoding, baseErased) <- baseEncoding
        pure
          ( OrdinalFiltered encoding ordinals
          , erased ++ baseErased
          )

deriveNominalOrdinalEncoding
  :: Int
  -> Set GName
  -> GName
  -> Value
  -> CheckM (Maybe (OrdinalEncoding, [ConstructorFieldPath]))
deriveNominalOrdinalEncoding depth seen family represented = do
  state <- get
  case Map.lookup family (csDatas state) of
    Nothing -> pure Nothing
    Just info -> do
      let seen' = Set.insert family seen
      arms <- mapM (deriveArm seen') (diCtors info)
      pure $ do
        derivedArms <- sequence arms
        let reachable = catMaybes derivedArms
        (constructors, erased, _) <-
          foldM appendArm ([], [], cardLiteral 0) reachable
        pure (OrdinalData constructors, erased)
  where
    deriveArm seen' constructor =
      inhabCtorFiber emptyCtx represented constructor >>= \case
        CtorContradiction -> pure (Just Nothing)
        CtorIndexUnknown -> pure Nothing
        CtorRefined fieldTypes -> do
          fields <- mapM (deriveOrdinalEncoding depth seen') fieldTypes
          directErased <- erasedFieldsForConstructor depth constructor fieldTypes
          pure $ do
            derived <- sequence fields
            pure
              ( Just
                  ( constructor
                  , map fst derived
                  , directErased ++ concatMap snd derived
                  )
              )

    appendArm (constructors, erased, offset) (constructor, fields, armErased) = do
      armCardinality <-
        foldM
          (\productSoFar field ->
            cardMul productSoFar
              <$> ordinalEncodingCardinality field)
          (cardLiteral 1)
          fields
      pure
        ( constructors
            ++ [ConstructorOrdinalEncoding constructor offset fields]
        , erased ++ armErased
        , cardAdd offset armCardinality
        )

directErasedFields
  :: Int
  -> Value
  -> CheckM [ConstructorFieldPath]
directErasedFields depth represented = do
  normalized <- forceM represented
  state <- get
  case normalized of
    VGlobal family _ _
      | Just info <- Map.lookup family (csDatas state) ->
          concat
            <$> mapM
              (\constructor ->
                inhabCtorFiber emptyCtx normalized constructor >>= \case
                  CtorRefined fields ->
                    erasedFieldsForConstructor depth constructor fields
                  _ -> pure [])
              (diCtors info)
    _ -> pure []

erasedFieldsForConstructor
  :: Int
  -> GName
  -> [Value]
  -> CheckM [ConstructorFieldPath]
erasedFieldsForConstructor depth constructor fieldTypes = do
  evaluation <- ec_
  constructorInfo <- gets (Map.lookup constructor . csCtors)
  pure $ case constructorInfo of
    Nothing -> []
    Just info ->
      [ ConstructorFieldPath constructor sourceIndex
      | (sourceIndex, ((icit, quantity), fieldType)) <-
          zip [0 :: Int ..]
            (zip (constructorSourceContracts info) fieldTypes)
      , not
          (Repr.runtimeConstructorField
            evaluation
            depth
            icit
            quantity
            fieldType)
      ]

constructorSourceContracts :: CtorInfo -> [(Icit, Q)]
constructorSourceContracts info =
  drop (length binders - length (ciSourceFields info)) binders
  where
    binders = collect (ciType info)
    collect = \case
      CPiBoundM _ icit quantity _ _ _ _ body ->
        (icit, quantity) : collect body
      _ -> []

deriveExactNaturalRepresentationCertificate
  :: RepresentationContext
  -> Int
  -> Value
  -> CheckM (Maybe ExactNaturalRepresentationCertificate)
deriveExactNaturalRepresentationCertificate context depth ty = do
  evaluation <- ec_
  normalized <- forceM ty
  state <- get
  case normalized of
    VGlobal family _ _
      | Just info <- Map.lookup family (csDatas state) -> do
          shapes <- mapM (constructorRuntimeShape depth normalized) (diCtors info)
          evidence <-
            selectedRepresentationEvidenceIdentity
              context
              depth
              (gPrel "ExactNaturalRepresentation")
              normalized
          let zeros =
                [ (constructor, erased)
                | (constructor, [], erased) <- catMaybes shapes
                ]
              successors =
                [ (constructor, fieldIndex, erased)
                | (constructor, [(fieldIndex, fieldType)], erased) <- catMaybes shapes
                , convertible evaluation depth fieldType normalized
                ]
          pure $ do
            (zeroConstructor, zeroErased) <- single zeros
            (successorConstructor, recursiveIndex, successorErased) <-
              single successors
            evidenceIdentity <- evidence
            let representedType = quote evaluation depth normalized
                recursiveField =
                  ConstructorFieldPath successorConstructor recursiveIndex
                certificate =
                  ExactNaturalRepresentationCertificate
                    { enrcContext = context
                    , enrcRepresentedType = representedType
                    , enrcTypeIdentity =
                        representationTypeIdentity context representedType
                    , enrcEvidenceIdentity = evidenceIdentity
                    , enrcZeroConstructor = zeroConstructor
                    , enrcSuccessorConstructor = successorConstructor
                    , enrcRecursiveField = recursiveField
                    , enrcErasedFields =
                        sort (nub (zeroErased ++ successorErased))
                    , enrcProfileRestrictions =
                        commonRepresentationRestrictions
                    , enrcCertificateVersion = 1
                    , enrcCheckerVersion = 1
                    }
            guard
              (verifyExactNaturalRepresentationCertificate certificate
                == Right ())
            pure certificate
    _ -> pure Nothing

constructorRuntimeShape
  :: Int
  -> Value
  -> GName
  -> CheckM
      (Maybe
        ( GName
        , [(Int, Value)]
        , [ConstructorFieldPath]
        ))
constructorRuntimeShape depth represented constructor =
  inhabCtorFiber emptyCtx represented constructor >>= \case
    CtorRefined fieldTypes -> do
      evaluation <- ec_
      constructorInfo <- gets (Map.lookup constructor . csCtors)
      pure $ do
        info <- constructorInfo
        let contracts = constructorSourceContracts info
        guard (length contracts == length fieldTypes)
        let runtime =
              [ (sourceIndex, fieldType)
              | (sourceIndex, ((icit, quantity), fieldType)) <-
                  zip [0 :: Int ..] (zip contracts fieldTypes)
              , Repr.runtimeConstructorField
                  evaluation
                  depth
                  icit
                  quantity
                  fieldType
              ]
            erased =
              [ ConstructorFieldPath constructor sourceIndex
              | (sourceIndex, ((icit, quantity), fieldType)) <-
                  zip [0 :: Int ..] (zip contracts fieldTypes)
              , not
                  (Repr.runtimeConstructorField
                    evaluation
                    depth
                    icit
                    quantity
                    fieldType)
              ]
        pure (constructor, runtime, erased)
    _ -> pure Nothing

deriveRefinementRepresentationCertificate
  :: RepresentationContext
  -> Int
  -> Value
  -> CheckM (Maybe RefinementRepresentationCertificate)
deriveRefinementRepresentationCertificate context depth ty = do
  evaluation <- ec_
  normalized <- forceM ty
  case normalized of
    VGlobal family _ [(_, base), (_, _predicate)]
      | family == prelRefined -> do
          state <- get
          saved <- get
          goal <-
            globalValueM
              (gPrel "RefinementView")
              [(Expl, normalized)]
          selectedDictionary <- traitEvidence emptyCtx noSpan goal
          selectedEvidence <- case selectedDictionary of
            Just dictionary -> do
              baseMode <-
                traitMemberObservationMode
                  (gPrel "RefinementView")
                  "Base"
              selectedBase <-
                evalIn emptyCtx (CProjM baseMode dictionary "Base")
                  >>= forceM
              baseMatches <- unify emptyCtx selectedBase base
              if baseMatches
                then do
                  zonkedDictionary <- zonkTermM depth dictionary
                  pure
                    (Just
                      (Kappa.Representation.representationEvidenceIdentity
                        context
                        zonkedDictionary))
                else pure Nothing
            _ -> pure Nothing
          put saved
          case Map.lookup family (csDatas state) >>= single . diCtors of
            Nothing -> pure Nothing
            Just constructor -> do
              shape <- constructorRuntimeShape depth normalized constructor
              case shape of
                Just (_, [(baseIndex, baseFieldType)], erased) -> do
                  baseFieldMatches <-
                    unify emptyCtx baseFieldType base
                  pure $ do
                    guard baseFieldMatches
                    evidenceIdentity <- selectedEvidence
                    let representedType = quote evaluation depth normalized
                        baseType = quote evaluation depth (force evaluation base)
                        certificate =
                          RefinementRepresentationCertificate
                            { rrcContext = context
                            , rrcRepresentedType = representedType
                            , rrcTypeIdentity =
                                representationTypeIdentity context representedType
                            , rrcRefinementEvidenceIdentity = evidenceIdentity
                            , rrcBaseType = baseType
                            , rrcBaseTypeIdentity =
                                representationTypeIdentity context baseType
                            , rrcConstructor = constructor
                            , rrcRetainedBaseField =
                                ConstructorFieldPath constructor baseIndex
                            , rrcErasedEvidenceFields = sort (nub erased)
                            , rrcProfileRestrictions =
                                sort
                                  (RequireUnboxedRefinement
                                    : commonRepresentationRestrictions)
                            , rrcCertificateVersion = 1
                            , rrcCheckerVersion = 1
                            }
                    guard
                      (verifyRefinementRepresentationCertificate certificate
                        == Right ())
                    pure certificate
                _ -> pure Nothing
    _ -> pure Nothing

selectedRepresentationEvidenceIdentity
  :: RepresentationContext
  -> Int
  -> GName
  -> Value
  -> CheckM (Maybe Text)
selectedRepresentationEvidenceIdentity context depth trait represented = do
  saved <- get
  goal <- globalValueM trait [(Expl, represented)]
  selected <- traitEvidence emptyCtx noSpan goal
  identity <- case selected of
    Nothing -> pure Nothing
    Just evidence -> do
      zonkedEvidence <- zonkTermM depth evidence
      pure
        (Just
          (Kappa.Representation.representationEvidenceIdentity
            context
            zonkedEvidence))
  put saved
  pure identity

commonRepresentationRestrictions :: [BackendProfileRestriction]
commonRepresentationRestrictions =
  [ InternalValuesOnly
  , ExcludeDynamicBoundary
  , ExcludeForeignBoundary
  , ExcludeExportedAbi
  ]

single :: [a] -> Maybe a
single [value] = Just value
single _ = Nothing

-- | Build the §30.2.7 query interface over the current 'CheckState' and
-- elaboration context. Each callback is side-effect free /from the caller's
-- point of view/: the speculative GADT unification and the evidence probe save
-- and restore 'CheckState', so neither leaks meta solutions nor diagnostics.
mkInhabEnv :: Ctx -> CheckM (InhabEnv CheckM)
mkInhabEnv ctx =
  pure
    InhabEnv
      { ieForce = forceM
      , ieExactFiniteFamilyCardinality = inhabExactFiniteFamilyCardinality
      , ieExactSymbolicFamilyCardinality = inhabExactSymbolicFamilyCardinality
      , ieRuntimeRecordField = inhabRuntimeRecordField ctx
      , ieInstantiateRecordField = inhabInstantiateRecordField ctx
      , ieRecordFieldDependencies = inhabRecordFieldDependencies ctx
      , ieContractibleRepresentative =
          inhabContractibleRepresentative ctx
      , ieClassifyHead = inhabClassifyHead
      , ieCtorFiber = inhabCtorFiber ctx
      , ieRuntimeCtorFieldMask = inhabRuntimeCtorFieldMask ctx
      , ieIsEmptyEvidence = inhabHasEvidence ctx (gPrel "IsEmpty")
      , ieIsContrEvidence = inhabHasEvidence ctx (gPrel "IsContr")
      , ieIsSubsingletonEvidence = \t -> do
          a <- inhabHasEvidence ctx (gPrel "IsSubsingleton") t
          if a then pure True else inhabHasEvidence ctx (gPrel "IsProp") t
      , ieEqualityVerdict = inhabEqualityVerdict ctx
      }

inhabInstantiateRecordField
  :: Ctx
  -> [(Text, Term)]
  -> RecordField Value
  -> CheckM Value
inhabInstantiateRecordField ctx representatives field =
  substThisInto
    ctx
    (CRecordV (sortOn fst representatives))
    (rfType field)

inhabRecordFieldDependencies
  :: Ctx
  -> RecordField Value
  -> CheckM [Text]
inhabRecordFieldDependencies ctx field = do
  fieldType <- quoteIn ctx (rfType field)
  pure
    ( nub
        (thisDepsOf fieldType ++ levelFieldDepsOf fieldType)
    )

-- | Materialize the representative promised by a Contractible summary.
-- Construction goes through checked constructor/evidence interfaces and is
-- zonked before speculative checker state is restored. A missing witness is a
-- conservative analysis failure, never an invented inhabitant.
inhabContractibleRepresentative
  :: Ctx
  -> Value
  -> CheckM (Maybe Term)
inhabContractibleRepresentative ctx ty = do
  saved <- get
  representative <- derive Set.empty ty
  zonked <- traverse (zonkTermM (ctxLen ctx)) representative
  put saved
  pure zonked
  where
    derive seen candidate = do
      normalized <- forceM candidate
      equality <- inhabEqualityVerdict ctx normalized
      cardinality <- inhabExactFiniteFamilyCardinality normalized
      case (equality, cardinality) of
        (Just False, _) ->
          Just <$> generatedReflForGoalAtM ctx Nothing normalized
        (_, Just 1) ->
          finiteFamilyRepresentative normalized
        _ ->
          evidenceCenter normalized >>= \case
            Just center -> pure (Just center)
            Nothing ->
              case normalized of
                VRecordTQ fields -> recordRepresentative seen fields
                VGlobal family _ _
                  | family `Set.member` seen -> pure Nothing
                  | otherwise ->
                      nominalRepresentative
                        (Set.insert family seen)
                        normalized
                _ -> pure Nothing

    evidenceCenter candidate = do
      goal <- globalValueM (gPrel "IsContr") [(Expl, candidate)]
      traitEvidence ctx noSpan goal >>= \case
        Nothing -> pure Nothing
        Just dictionary ->
          Just . fst
            <$> knownTraitMemberProjection
              ctx
              noSpan
              (gPrel "IsContr")
              "center"
              goal
              dictionary

    recordRepresentative seen = go []
      where
        go done [] =
          pure (Just (CRecordV (sortOn fst done)))
        go done (field : rest) = do
          dependencies <- inhabRecordFieldDependencies ctx field
          if any (`notElem` map fst done) dependencies
            then pure Nothing
            else do
              fieldType <-
                inhabInstantiateRecordField ctx done field
              environment <- mkInhabEnv ctx
              summary <-
                inhabitanceSummary
                  environment
                  SourceReachability
                  fieldType
              if summary /= Contractible
                then pure Nothing
                else
                  derive seen fieldType >>= \case
                    Nothing -> pure Nothing
                    Just value ->
                      go ((rfName field, value) : done) rest

    nominalRepresentative seen candidate = do
      classification <- inhabClassifyHead candidate
      case classification of
        Nothing -> finiteFamilyRepresentative candidate
        Just (IsData _ constructors) -> do
          environment <- mkInhabEnv ctx
          arms <-
            forM constructors $ \constructor ->
              inhabCtorFiber ctx candidate constructor >>= \case
                CtorContradiction ->
                  pure (Empty, Nothing)
                CtorIndexUnknown ->
                  pure (Unknown, Nothing)
                CtorRefined fieldTypes -> do
                  summaries <-
                    mapM
                      (inhabitanceSummary
                        environment
                        SourceReachability)
                      fieldTypes
                  let armSummary =
                        foldr
                          multiplySummaries
                          Contractible
                          summaries
                  payload <-
                    if armSummary == Contractible
                      then mapM (derive seen) fieldTypes
                      else pure []
                  constructorTerm <-
                    case sequence payload of
                      Nothing -> pure Nothing
                      Just values ->
                        Just
                          <$> generatedCtorApplyAtM
                            ctx
                            candidate
                            constructor
                            values
                  pure (armSummary, constructorTerm)
          pure $
            case
              [ value
              | (summary, Just value) <- arms
              , summary == Contractible
              ]
            of
              [value]
                | all
                    (\(summary, _) ->
                      summary == Empty
                        || summary == Contractible)
                    arms ->
                    Just value
              _ -> Nothing

    finiteFamilyRepresentative candidate = do
      cardinality <- inhabExactFiniteFamilyCardinality candidate
      case cardinality of
        Just 1 -> do
          normalized <- forceM candidate
          case normalized of
            VGlobal family _ _
              | family == prelFin -> do
                  state <- get
                  let constructor =
                        Map.lookup family (csDatas state)
                          >>= listToMaybe . diCtors
                  traverse
                    (\ctor ->
                      generatedCtorApplyAtM
                        ctx
                        candidate
                        ctor
                        [CLit (LitInt 0)])
                    constructor
            _ -> pure Nothing
        _ -> pure Nothing

-- | Mandatory runtime-erasure decisions for inhabitance use the same checked
-- representation predicate as KBackendIR lowering. The source inhabitance of
-- an erased field is still accounted for by 'Kappa.Inhabitance'; this callback
-- says only whether the field has a runtime slot.
inhabRuntimeRecordField :: Ctx -> Int -> RecordField Value -> CheckM Bool
inhabRuntimeRecordField ctx fieldOffset field = do
  evaluation <- ec_
  pure
    ( not
        ( Repr.runtimeErasedParam
            evaluation
            (ctxLen ctx + fieldOffset)
            (rfQ field)
            (rfType field)
        )
    )

inhabRuntimeCtorFieldMask
  :: Ctx
  -> Value
  -> GName
  -> CheckM (Maybe [Bool])
inhabRuntimeCtorFieldMask ctx represented constructor =
  inhabCtorFiber ctx represented constructor >>= \case
    CtorRefined fieldTypes -> do
      evaluation <- ec_
      constructorInfo <- gets (Map.lookup constructor . csCtors)
      pure $ do
        info <- constructorInfo
        let contracts = constructorSourceContracts info
        guard (length contracts == length fieldTypes)
        pure
          [ Repr.runtimeConstructorField
              evaluation
              (ctxLen ctx + fieldOffset)
              icit
              quantity
              fieldType
          | (fieldOffset, ((icit, quantity), fieldType)) <-
              zip [0 :: Int ..] (zip contracts fieldTypes)
          ]
    _ -> pure Nothing

-- | Exact finite-family cardinalities required by §30.2.7. Recognition uses
-- resolved global identity and a normalized closed Nat index. Open indices are
-- retained by the separate symbolic-cardinality query and therefore remain
-- conservative in this concrete interval query.
inhabExactFiniteFamilyCardinality :: Value -> CheckM (Maybe Natural)
inhabExactFiniteFamilyCardinality value = do
  normalized <- forceM value
  direct <- pure $ case normalized of
    VGlobal family _ [(_, VLit (LitInt cardinality))]
      | family == prelFin
      , cardinality >= 0 ->
          Just (fromInteger cardinality)
    _ -> Nothing
  case direct of
    Just cardinality -> pure (Just cardinality)
    Nothing -> do
      symbolic <- inhabExactSymbolicFamilyCardinality 0 normalized
      pure $ case symbolic of
        Just (CardLiteral cardinality) -> Just cardinality
        _ -> Nothing

inhabExactSymbolicFamilyCardinality :: Int -> Value -> CheckM (Maybe CardExpr)
inhabExactSymbolicFamilyCardinality depth value = do
  normalized <- forceM value
  evaluation <- ec_
  case normalized of
    VGlobal family _ [(_, index)]
      | family == prelFin ->
          pure (Just (natCardinalityExpression evaluation depth index))
    VGlobal family _ [(_, base), (_, predicate)]
      | family == prelRefined ->
          refinementCardinality evaluation depth base predicate
    _ -> pure Nothing
  where
    natCardinalityExpression evaluation depth' index =
      case force evaluation index of
        VLit (LitInt cardinality)
          | cardinality >= 0 -> cardLiteral (fromInteger cardinality)
        normalizedIndex -> cardIndex (quote evaluation depth' normalizedIndex)

    refinementCardinality evaluation depth' base predicate = do
      base' <- forceM base
      range <- canonicalNatRangeCardinality depth' base' predicate
      case range of
        Just cardinality -> pure (Just cardinality)
        Nothing -> finiteRefinementCardinality base' predicate

    canonicalNatRangeCardinality depth' base predicate = do
      bounds <- canonicalNatRangeBounds depth' base predicate
      pure $ do
        (lower, upper) <- bounds
        let lowerCardinality = natTermCardinality lower
            upperCardinality = natTermCardinality upper
        pure
          ( cardIf
              (CardLe lowerCardinality upperCardinality)
              (cardAdd (cardGuardedSub upperCardinality lowerCardinality) (cardLiteral 1))
              (cardLiteral 0)
          )

    natTermCardinality = \case
      CLit (LitInt cardinality)
        | cardinality >= 0 -> cardLiteral (fromInteger cardinality)
      term -> cardIndex term

    finiteRefinementCardinality base predicate =
      fmap (cardLiteral . fromIntegral . length) <$> finiteRefinementOrdinals base predicate

-- | Recognize the exact standard inclusive-Nat-range refinement shape. The
-- operation/member dictionaries are authenticated by selected instance
-- identity in 'selectedNatRangeMembershipOperands' and
-- 'decodeSelectedNatRange'; source spellings have no authority here.
canonicalNatRangeBounds
  :: Int
  -> Value
  -> Value
  -> CheckM (Maybe (Term, Term))
canonicalNatRangeBounds depth base predicate = do
  evaluation <- ec_
  base' <- forceM base
  case base' of
    VGlobN natural [] | natural == prelNat ->
      case stripIdentityWrappers (quote evaluation depth predicate) of
        CLam _ _ _ body
          | Just (True, membership) <- booleanLiteralEqualityPayload body -> do
              operands <- selectedNatRangeMembershipOperands membership
              decoded <- case operands of
                Just (rangeValue, member)
                  | stripIdentityWrappers member == CVar 0 ->
                      decodeSelectedNatRange (depth + 1) rangeValue
                _ -> pure Nothing
              pure $ do
                (lowerWithBinder, upperWithBinder, exclusive) <- decoded
                guard (not exclusive)
                let lower = shiftTerm (-1) 0 lowerWithBinder
                    upper = shiftTerm (-1) 0 upperWithBinder
                guard (termScopedAt depth lower)
                guard (termScopedAt depth upper)
                pure (lower, upper)
        _ -> pure Nothing
    _ -> pure Nothing

-- | Completely enumerate the required bounded @Refined (Fin n)@ fragment.
-- Candidate values are built by ordinary constructor elaboration against the
-- checked @Fin n@ expectation, so family arguments and erased proof evidence
-- are never fabricated by the analysis.
finiteRefinementOrdinals
  :: Value
  -> Value
  -> CheckM (Maybe [Natural])
finiteRefinementOrdinals base predicate = do
  evaluation <- ec_
  base' <- forceM base
  case base' of
    VGlobal family _ [(_, VLit (LitInt bound))]
      | family == prelFin
      , bound >= 0
      , bound <= 256 -> do
          state <- get
          case Map.lookup prelFin (csDatas state) >>= listToMaybe . diCtors of
            Nothing -> pure Nothing
            Just constructor -> do
              environment <- mkInhabEnv emptyCtx
              verdicts <-
                forM [0 .. bound - 1] $ \ordinal -> do
                  saved <- get
                  let errorsBefore = length (filter isError (csDiags saved))
                  candidate <-
                    generatedCtorValueAtM
                      emptyCtx
                      base'
                      constructor
                      [VLit (LitInt ordinal)]
                  errorsAfter <- gets (length . filter isError . csDiags)
                  put saved
                  if errorsAfter /= errorsBefore
                    then pure (fromInteger ordinal, Unknown)
                    else do
                      let fiber =
                            vapp evaluation
                              (force evaluation predicate)
                              Expl
                              candidate
                      verdict <-
                        inhabitanceSummary
                          environment
                          SourceReachability
                          fiber
                      pure (fromInteger ordinal, verdict)
              pure $
                if all (refinementVerdictKnown . snd) verdicts
                  then Just [ordinal | (ordinal, Contractible) <- verdicts]
                  else Nothing
    _ -> pure Nothing
  where
    refinementVerdictKnown Empty = True
    refinementVerdictKnown Contractible = True
    refinementVerdictKnown _ = False

-- | Classify a forced head: a closed data type registered in 'csDatas' is the
-- only structural case the analysis reasons about. Everything else (type
-- families, abstract/opaque heads, primitives) is reported as "not a data
-- type", which the analysis turns into 'Unknown'.
inhabClassifyHead :: Value -> CheckM (Maybe HeadClass)
inhabClassifyHead t = do
  st <- get
  pure $ case t of
    VGlobN g _ -> case Map.lookup g (csDatas st) of
      Just di -> Just (IsData t (diCtors di))
      Nothing -> Nothing
    _ -> Nothing

-- | Is a (demanded scrutinee index) value GROUND — free of any rigid skolem?
--
-- Soundness hinges on this for the §30.2.7 GADT rule: a constructor's
-- result-index unify-failure means 'Empty' ONLY when the demanded index is
-- ground. A surviving 'VRigid' (a free/abstract index variable like the @b@ in
-- @Tag b@) makes the index non-ground, so a unify-failure there is merely
-- "absent for this instantiation", not a contradiction.
--
-- We FORCE at every node so that (a) solved metavariables are followed to their
-- solutions and (b) a rigid pinned by a branch-local @FactIs@ (§7.4.1 dependent
-- match) resolves to its witness — only a genuinely free 'VRigid' counts.
-- Unsolved 'VFlex' metas are GROUND-COMPATIBLE: unification can still solve them,
-- and any such solve is itself a reachable inhabitant, so they never block the
-- 'Empty' verdict on their own.
--
-- Conservative on the fringes: a recursion-budget exhaustion, an opaque closure
-- (@VLam@/@VPi@/@VThunkV@/…), or any other shape we cannot cheaply prove rigid-
-- free is treated as NON-ground (returns 'False'), which can only refuse an
-- 'Empty' verdict — never fabricate one.
--
-- Residual hole (documented, not load-bearing for the cases we gate): an
-- unsolved 'VFlex' that a /later/ unification would have resolved to a rigid is
-- still counted ground here. Today the only producers of the demanded scrutinee
-- index for this query are real source types, whose abstract indices are 'VRigid'
-- (not metas), so this does not arise; it would need a metas-as-indices caller
-- to ever bite.
noRigidSkolemForced :: EvalCtx -> Value -> Bool
noRigidSkolemForced ec = go (1000 :: Int)
  where
    go fuel v
      | fuel <= 0 = False -- budget exhausted: fail closed (treat as non-ground)
      | otherwise = case force ec v of
          VRigid _ _ -> False -- a surviving free skolem: NOT ground
          VFlex _ sp -> all (go (fuel - 1) . snd) sp -- unsolved meta head is fine; check its args
          VGlobN _ sp -> all (go (fuel - 1) . snd) sp
          VCtor _ args -> all (go (fuel - 1)) args
          VLit _ -> True
          VSort _ -> True
          VInject _ w -> go (fuel - 1) w
          VRecordT fs -> all (go (fuel - 1) . snd) fs
          VRecordV fs -> all (go (fuel - 1) . snd) fs
          VVariantT ms -> all (go (fuel - 1)) ms
          VPrim _ args -> all (go (fuel - 1)) args
          VAppN _ f a -> go (fuel - 1) f && go (fuel - 1) a
          -- Anything else (binders/closures/suspensions/neutral projections and
          -- matches we did not unfold) is conservatively NON-ground: we refuse
          -- the Empty verdict rather than risk hiding a rigid inside it.
          _ -> False

-- | Speculatively refine one constructor against the demanded scrutinee type
-- (§17.1.2 family-argument refinement). Three-way result (see 'CtorFiber'):
--
--   * 'CtorRefined' — unification succeeded; the constructor's field types under
--     the branch-local equalities forced by unification.
--   * 'CtorContradiction' — unification failed and the demanded scrutinee index
--     is GROUND (carries no rigid skolem). A real no-confusion contradiction, so
--     this arm is 'Empty'.
--   * 'CtorIndexUnknown' — unification failed but the demanded index carries a
--     rigid/free skolem (e.g. an abstract @Tag b@). The failure only rules the
--     constructor out for /this/ instantiation, not all of them, so emptiness is
--     'Unknown'. Concluding 'Empty' here is the §30.2.7 soundness bug.
--
-- Runs under a saved/restored 'CheckState' so neither the meta solutions nor any
-- diagnostics escape. The ground-ness probe ('noRigidSkolem') reads only the
-- ORIGINAL demanded scrutinee type (forced in the restored state) — never the
-- post-unification metas — so the rigid/ground classification is independent of
-- the speculative solve.
inhabCtorFiber :: Ctx -> Value -> GName -> CheckM CtorFiber
inhabCtorFiber ctx scrutTy c = do
  st <- get
  mci <- gets (Map.lookup c . csCtors)
  case mci of
    -- Constructor not registered: we cannot refine it, so fail OPEN. Reporting a
    -- contradiction here would let an unresolved/absent constructor masquerade as
    -- a no-confusion Empty (an unsound accept of `impossible`/omission); 'Unknown'
    -- is strictly safer and costs no legitimate acceptance.
    Nothing -> put st >> pure CtorIndexUnknown
    Just ci -> do
      nBefore <- gets (length . filter isError . csDiags)
      ctype <- evalIn emptyCtx =<< instantiateCtorType c ci
      (result, binders, natMetas) <- peelCtorResult ctype [] Set.empty
      let fieldCount = length (ciSourceFields ci)
          fields = drop (length binders - fieldCount) binders
      -- Decide unify success/failure WITH per-position clash tracking, so the
      -- ground-ness probe can target only the family-argument positions that
      -- actually disagreed (§17.1.2). Each clash records the (ctorResultArg,
      -- scrutineeArg) pair, forced in the PRE-speculation state.
      (ok, clashPairs) <- unifyHeadByPosition result scrutTy
      nAfter <- gets (length . filter isError . csDiags)
      put st -- discard speculative meta solutions and diagnostics
      if ok && nAfter == nBefore
        then pure (CtorRefined fields)
        else failureVerdict st natMetas clashPairs
  where
    -- A unify-failure is a genuine no-confusion contradiction ('Empty') only
    -- when every DISAGREEING family-argument position is PROVABLY APART — the
    -- two sides diverge at a pair of distinct constructor heads, with no rigid
    -- or meta shielding the divergence (so no instantiation could reconcile
    -- them). Examples that ARE apart: `Z` vs `S n`, `True` vs `b`-position when
    -- the OTHER index already clashed on ground heads. A rigid sitting AT the
    -- divergence (e.g. `Box m` vs `Box (S n)` — the whole index is the rigid `m`)
    -- is NOT apart: emptiness is undecidable ('CtorIndexUnknown', §30.2.7). A
    -- rigid in a position that UNIFIED (the `a` of `Vec a Z` vs `Vec a (S n)`)
    -- never enters 'clashPairs', so it cannot downgrade the verdict — fixing the
    -- §30.2.x over-rejection. Classification reads the pre-speculation forcing
    -- (captured into the pairs), so speculative metas can't perturb it.
    --
    -- @clashPairs@ empty ⇒ we could not localize the disagreement (heads/arities
    -- differ, or a non-data result); fall back to probing the WHOLE scrutinee for
    -- rigids, preserving the conservative pre-existing behavior.
    -- A constructor's result family-arguments must ALL equal the scrutinee's for
    -- it to apply, so a SINGLE provably-apart family-argument position already
    -- rules the constructor out for EVERY instantiation ⇒ the fiber is Empty.
    -- Hence 'any', not 'all': in `Pair True b` vs `FT : Pair False True`, the
    -- first index clashes on ground heads (`True` vs `False`) — Empty — even
    -- though the second clash (`True` vs rigid `b`) is on its own undecidable.
    -- Only when NO clashing position is provably apart (every disagreement is
    -- shielded by a rigid/meta) is emptiness undecidable ('CtorIndexUnknown').
    failureVerdict st natMetas clashPairs
      | null clashPairs =
          pure $
            if noRigidSkolemForced (ecOf st) scrutTy
              then CtorContradiction
              else CtorIndexUnknown
      | otherwise = do
          apart <- or <$> mapM (valuesProvablyApart st natMetas) clashPairs
          pure (if apart then CtorContradiction else CtorIndexUnknown)

    -- Structural no-confusion handles visible constructor clashes. Logical
    -- Nat arithmetic can also prove two family arguments apart without
    -- reducing an open expression to constructors (for example @0@ versus
    -- @n + 1@). Reify through the shared authenticated arithmetic domain and
    -- use only bounds justified by Nat-typed rigids in the current context.
    -- A failed translation/proof remains 'False', preserving the fail-closed
    -- reachability direction. Distinct nominal inhabitants of @Type@ are not
    -- treated as apart (§30.2.7 preserves room for path extensions).
    valuesProvablyApart st natMetas (left, right)
      | groundlyApart (constructorInScope st) (ecOf st) left right = pure True
      | otherwise =
          firstProvenDomain
            [ArithmeticNatural, ArithmeticInteger]
      where
        firstProvenDomain [] = pure False
        firstProvenDomain (domain : rest) =
          arithmeticApart domain >>= \case
            True -> pure True
            False -> firstProvenDomain rest

        arithmeticApart domain = do
          let depth = ctxLen ctx
              evaluation = ecOf st
              leftTerm = quote evaluation depth (force evaluation left)
              rightTerm = quote evaluation depth (force evaluation right)
          leftExpression <-
            selectedArithmeticExpression domain depth leftTerm
          rightExpression <-
            selectedArithmeticExpression domain depth rightTerm
          case (leftExpression, rightExpression, arithmeticSemanticsForDomain domain) of
            (Just lhs, Just rhs, Just semantics) -> do
              variables <- ctxArithmeticVariables ctx
              assumptions <- arithmeticCertificateAssumptions ctx domain
              assumptionFormulas <-
                arithmeticAssumptionFormulasForDomain
                  depth
                  domain
                  assumptions
              let admittedLevels =
                    Set.fromList
                      [ level
                      | (level, kind) <- variables
                      , arithmeticVariableBelongsToDomain domain kind
                      ]
                      `Set.union`
                        if domain == ArithmeticNatural
                          then Set.map arithmeticMetaVariable natMetas
                          else Set.empty
                  naturalLevels =
                    Set.fromList
                      [ level
                      | (level, kind) <- variables
                      , kind == ArithmeticVariableNatural
                      ]
                      `Set.union`
                        if domain == ArithmeticNatural
                          then Set.map arithmeticMetaVariable natMetas
                          else Set.empty
                  goal =
                    ANot
                      (AAtom (AFact ACmpEq lhs rhs))
                  mentionedLevels =
                    arithmeticFormulaVariables goal
                      `Set.union`
                        Set.unions
                          [ arithmeticFormulaVariables formula
                          | (_, formula) <- assumptionFormulas
                          ]
                  replay =
                    deriveArithmeticFormulaReplayWithAssumptions
                      semantics
                      naturalLevels
                      assumptionFormulas
                      True
                      goal
              pure
                ( Set.isSubsetOf mentionedLevels admittedLevels
                    && isJust replay
                )
            _ -> pure False

    -- Instantiate the complete constructor telescope with fresh metas and
    -- return every binder domain in source order. The caller selects the final
    -- @ciSourceFields@ suffix: constructor parameters and generated premises
    -- are interface binders, while that suffix includes both explicit runtime
    -- fields and implicit quantity-zero proof fields. Source inhabitance must
    -- account for the latter before runtime erasure.
    peelCtorResult t acc natMetas = do
      t' <- forceM t
      case t' of
        VPi Impl _ _ _ dom clo -> do
          (m, natMetas') <- freshCtorMeta dom natMetas
          r <- clApp clo m
          peelCtorResult r (acc ++ [dom]) natMetas'
        VPi Expl _ _ _ dom clo -> do
          (m, natMetas') <- freshCtorMeta dom natMetas
          r <- clApp clo m
          peelCtorResult r (acc ++ [dom]) natMetas'
        result -> pure (result, acc, natMetas)

    freshCtorMeta domain natMetas = do
      (meta, term) <- freshMetaForWithId ctx domain
      value <- evalIn ctx term
      domain' <- forceM domain
      let natMetas' = case domain' of
            VGlobN g [] | g == prelNat -> Set.insert meta natMetas
            _ -> natMetas
      pure (value, natMetas')

    -- Unify the constructor result against the scrutinee. When both sides are
    -- the same data head with matching arity, unify each family-argument
    -- position independently and record (ctorResultArg, scrutineeArg) — forced
    -- in the PRE-speculation state — for the positions that FAILED. Otherwise
    -- fall back to a single whole-type unify and report no localized clash (the
    -- caller then probes the whole scrutinee).
    unifyHeadByPosition result scrut = do
      rf <- forceM result
      sf <- forceM scrut
      case (rf, sf) of
        (VGlobN dh rsp, VGlobN sh ssp)
          | dh == sh, length rsp == length ssp -> do
              results <- zipWithM unifyPos rsp ssp
              let ok = all fst results
                  clashPairs =
                    [ pair
                    | (positionUnified, pair) <- results
                    , not positionUnified
                    ]
              pure (ok, clashPairs)
        _ -> do
          ok <- unify ctx result scrut
          pure (ok, [])
    -- Constructor parameters are aligned in dependent-telescope order. Force
    -- the current pair only after all preceding positions have solved their
    -- parameters: for @refl : x = x@ against @A = B@, the second endpoint
    -- must be compared as the already-selected @A@ versus @B@, not as the
    -- pre-telescope meta @?x@ versus @B@. A failed position is speculative and
    -- restores only its own changes; successful earlier positions remain in
    -- force for later dependent positions until the enclosing fiber query
    -- restores its complete transaction.
    unifyPos (_, ra) (_, sa) = do
      positionState <- get
      let positionEvaluation = ecOf positionState
          pair =
            ( force positionEvaluation ra
            , force positionEvaluation sa
            )
      unified <- unify ctx ra sa
      unless unified (put positionState)
      pure (unified, pair)

-- | Rigidity-aware structural no-confusion: are these two values PROVABLY
-- distinct — diverging at a pair of different constructor heads, with neither
-- side a rigid skolem or meta at (or above) the point of divergence?
--
-- This is the decidable half of GADT no-confusion (§17.1.2 / §30.2.7). It
-- returns 'True' only when /no/ instantiation of the free variables could make
-- the two sides equal, so concluding the refined fiber 'Empty' is sound:
--
--   * @Z@ vs @S n@ ⇒ True (distinct ground constructor heads; the @n@ below the
--     @S@ is irrelevant — the heads already disagree).
--   * @True@ vs @False@ ⇒ True (distinct nullary constructors / literals).
--   * a 'VRigid' or 'VFlex' against ANYTHING ⇒ False (the variable could be
--     instantiated to match; emptiness is undecidable here).
--   * same constructor head ⇒ recurse pairwise; apart iff some argument is apart
--     (this never fires for a genuine unify-failure root, but keeps the check
--     total and lets a nested ground clash like @S Z@ vs @S (S n)@ be detected).
--   * anything we cannot cheaply classify (closures, Pi, neutral projections) ⇒
--     False (conservative: refuse the 'Empty' verdict rather than fabricate it).
groundlyApart :: (GName -> Bool) -> EvalCtx -> Value -> Value -> Bool
groundlyApart constructorVisible ec = go (1000 :: Int)
  where
    go fuel a b
      | fuel <= 0 = False
      | otherwise = case (force ec a, force ec b) of
          -- Either side a free variable / unsolved meta: could be instantiated
          -- to match, so NOT provably apart.
          (VRigid _ _, _) -> False
          (_, VRigid _ _) -> False
          (VFlex _ _, _) -> False
          (_, VFlex _ _) -> False
          -- Distinct literals are apart; equal literals agree.
          (VLit l1, VLit l2) -> l1 /= l2
          (VLit (LitInt n), VCtor g args)
            | g == prelNatZero -> n /= 0 || not (null args)
            | g == prelNatSucc ->
                n <= 0
                  || case args of
                    [predecessor] -> go (fuel - 1) (VLit (LitInt (n - 1))) predecessor
                    _ -> True
          (VCtor g args, VLit (LitInt n))
            | g == prelNatZero -> n /= 0 || not (null args)
            | g == prelNatSucc ->
                n <= 0
                  || case args of
                    [predecessor] -> go (fuel - 1) predecessor (VLit (LitInt (n - 1)))
                    _ -> True
          -- Data constructors (the index-argument representation, e.g. `Z` is
          -- `VCtor Z []`, `S m` is `VCtor S [m]`). Different heads ⇒ apart
          -- (no-confusion). Same head ⇒ apart iff some argument is apart; the
          -- rigid `m` under a SHARED head (`S m` vs `S k`) is therefore not a
          -- clash, while `Z` vs `S m` clashes at the head regardless of `m`.
          (VCtor g1 as1, VCtor g2 as2)
            | g1 /= g2 ->
                constructorVisible g1 && constructorVisible g2
            | length as1 /= length as2 ->
                constructorVisible g1
            | otherwise -> or (zipWith (go (fuel - 1)) as1 as2)
          -- Same nominal type-application head (e.g. nested `Vec a (S n)` vs
          -- `Vec a Z` appearing as an index): recurse pairwise. Different type
          -- heads are NOT treated as apart — nominal type constructors are not
          -- assumed injective/disjoint at the value level here (conservative).
          (VGlobN g1 sp1, VGlobN g2 sp2)
            | g1 == g2
            , length sp1 == length sp2 ->
                or (zipWith (\(_, x) (_, y) -> go (fuel - 1) x y) sp1 sp2)
          -- Anything else: not cheaply decidable ⇒ conservatively NOT apart.
          _ -> False

-- | §30.2.7 proof-classification evidence: does the /local/ context carry an
-- explicit @C t'@ binder (e.g. @IsEmpty t@) with @t'@ convertible to the
-- analyzed type? This is the conservative, side-effect-free "context contains
-- explicit evidence" rule — it consults only in-scope implicit binders and
-- never triggers instance search, so it cannot fabricate evidence.
inhabHasEvidence :: Ctx -> GName -> Value -> CheckM Bool
inhabHasEvidence ctx traitG ty = do
  ec <- ec_
  t <- forceM ty
  let lvl = ctxLen ctx
      matches e = case ceType e of
        -- a single-parameter proof trait applied to the analyzed type:
        -- `IsEmpty t'` with t' convertible to t. The last spine entry is the
        -- type argument; require a non-empty spine (a bare trait head carries
        -- no type to match against).
        VGlobN g sp
          | g == traitG
          , (_, arg) : _ <- reverse sp -> convertible ec lvl arg t
        _ -> False
  pure (any (\e -> ceImplicitLocal e && matches e) (ctxEntries ctx))

-- | §17.1.4: is the fiber selected by this arm's pattern provably uninhabited?
--
--   * A constructor pattern @C ..@ refines the scrutinee's family arguments;
--     the fiber is 'Empty' when @C@'s result type cannot unify with a GROUND
--     scrutinee index (the contradictory-GADT case, e.g. @Never : Choice False@
--     under a @Choice True@ scrutinee), or when @C@'s retained field types
--     multiply to 'Empty'. A unify-failure against an ABSTRACT (rigid-indexed)
--     scrutinee — @Tag b@, @Vec n a@ — is /not/ empty: the constructor is
--     present for some instantiation of the free index, so the arm is reachable
--     ('CtorIndexUnknown', §30.2.7).
--   * Any other pattern (wildcard, variable, tuple, record, …) does not narrow
--     by a constructor, so the arm's fiber is just the whole refined scrutinee
--     type and we defer to its summary.
branchFiberEmpty :: Ctx -> Value -> CorePat -> CheckM Bool
branchFiberEmpty ctx scrutTy = \case
  CPCtor g _ _ -> do
    env <- mkInhabEnv ctx
    fiber <- inhabCtorFiber ctx scrutTy g
    case fiber of
      CtorContradiction -> pure True -- ground-index no-confusion: arm is Empty
      CtorIndexUnknown -> pure False -- rigid index: arm reachable, not empty
      CtorRefined fieldTys -> do
        ss <- mapM (inhabitanceSummary env SourceReachability) fieldTys
        pure (any isEmpty ss)
  CPAs _ p -> branchFiberEmpty ctx scrutTy p
  _ -> scrutineeEmpty ctx scrutTy

-- | §30.2.7 equality classification. @Just True@ is a checked no-confusion
-- refutation. @Just False@ is a definitionally-equal pair whose path type is
-- known proposition-valued through selected IsProp/IsSet evidence.
inhabEqualityVerdict :: Ctx -> Value -> CheckM (Maybe Bool)
inhabEqualityVerdict ctx t = do
  case eqComponents t of
    Nothing -> pure Nothing
    Just (carrier, l, r) -> do
      -- Equality reachability may be queried inside the same branch that
      -- established one endpoint's Boolean value. Settle only evidence
      -- reachable from this equality and the active branch facts before
      -- comparing their selected Core identities.
      settleRequiredProofDependencies ctx t
      st <- get
      carrier' <- forceM carrier
      l' <- forceM l
      r' <- forceM r
      let evaluation = ecOf st
          canonicalNatCarrier = case carrier' of
            VGlobN carrierGlobal [] -> carrierGlobal == prelNat
            _ -> False
          canonicalBoolCarrier = case carrier' of
            VGlobN carrierGlobal [] -> carrierGlobal == prelBool
            _ -> False
          definitelyApart =
            ( canonicalNatCarrier
                && groundlyApart
                  (constructorInScope st)
                  evaluation
                  l'
                  r'
            )
              || case (ctorHead st l', ctorHead st r') of
                -- distinct visible constructors of the same algebraic data
                -- type: the equality type is uninhabited (no-confusion).
                (Just (c1, d1), Just (c2, d2)) -> d1 == d2 && c1 /= c2
                _ -> False
      branchApart <-
        if canonicalBoolCarrier
          then do
            leftTrue <- proveBoolValueFromBranchFacts ctx True l'
            leftFalse <- proveBoolValueFromBranchFacts ctx False l'
            rightTrue <- proveBoolValueFromBranchFacts ctx True r'
            rightFalse <- proveBoolValueFromBranchFacts ctx False r'
            pure
              ( (leftTrue && rightFalse)
                  || (leftFalse && rightTrue)
              )
          else pure False
      proposition <-
        inhabResolvableEvidence ctx (gPrel "IsProp") t
      setCarrier <-
        inhabResolvableEvidence ctx (gPrel "IsSet") carrier'
      if definitelyApart || branchApart
        then pure (Just True)
        else
          pure $
            if convertible evaluation (ctxLen ctx) l' r'
                && (proposition || setCarrier)
              then Just False
              else Nothing
  where
    eqComponents v = case v of
      VGlobN eqG sp
        | eqG == prelEqType
        , [(_, carrier), (_, l), (_, r)] <- drop (length sp - 3) sp ->
            Just (carrier, l, r)
      VCtor eqG [carrier, l, r] | eqG == prelEqType -> Just (carrier, l, r)
      _ -> Nothing
    -- a fully-saturated constructor value's (ctor, parent-data) pair
    ctorHead st = \case
      VCtor c _
        | constructorInScope st c ->
            (\ci -> (c, ciData ci)) <$> Map.lookup c (csCtors st)
      _ -> Nothing

-- | Side-effect-free ordinary evidence availability for an inhabitance query.
-- This uses the same local/instance/supertrait selection as source
-- elaboration, then restores all speculative metas and diagnostics.
inhabResolvableEvidence :: Ctx -> GName -> Value -> CheckM Bool
inhabResolvableEvidence ctx trait represented = do
  saved <- get
  result <-
    trySpec $ do
      goal <- globalValueM trait [(Expl, represented)]
      traitEvidence ctx noSpan goal
  put saved
  pure $
    case result of
      Just (Just _) -> True
      _ -> False

-- exhaustiveness (§17.1): closed ADTs / Bool / variants / records /
-- tuples; literal scrutinees require a catch-all.
-- | The @Maybe [GName]@ argument is the §16.4.1 flow-refined
-- constructor set of the scrutinee (e.g. after `if e is C`): when
-- present, only that subset of the data type's constructors must be
-- covered for exhaustiveness. 'Nothing' means "no refinement in scope",
-- so the full constructor set is required (the conservative default).
matchRemainderEmpty
  :: Ctx
  -> Value
  -> Maybe [GName]
  -> [(CorePat, Maybe Term)]
  -> CheckM Bool
matchRemainderEmpty ctx ty mRefined alts = do
  t <- forceM ty
  wholeScrutineeEmpty <- scrutineeEmpty ctx t
  let unguarded = [p | (p, Nothing) <- alts]
  if wholeScrutineeEmpty || any corePatternCatchAll unguarded
    then pure True
    else case t of
      VGlobN g _ -> do
        st <- get
        case Map.lookup g (csDatas st) of
          Nothing -> pure False
          Just di -> do
            let uncovered = uncoveredDataConstructors st di mRefined alts
            and <$> mapM (constructorFiberEmpty ctx t) uncovered
      VVariantT members -> do
        tags <- mapM (tagOf ctx) members
        let covered = concatMap corePatternCoveredTags unguarded
        pure
          ( any corePatternHasVariantRest unguarded
              || null (tags \\ covered)
          )
      VRecordT _ -> do
        st <- get
        let tupleRows = [[p] | p@CPTuple {} <- unguarded]
            tupleComplete = not (null tupleRows) && not (wildUseful st tupleRows 1)
        pure
          ( tupleComplete
              || any coreRecordPatternIrrefutable unguarded
          )
      _ -> pure False

checkExhaustive :: Ctx -> Span -> Value -> Maybe [GName] -> [(CorePat, Maybe Term)] -> CheckM ()
checkExhaustive ctx sp ty mRefined alts = do
  t <- forceM ty
  wholeScrutineeEmpty <- scrutineeEmpty ctx t
  let catchAll = any corePatternCatchAll [p | (p, Nothing) <- alts]
  if wholeScrutineeEmpty || catchAll
    then pure ()
    else case t of
      VGlobN g _ -> do
        st <- get
        case Map.lookup g (csDatas st) of
          Just di -> do
            let uncovered = uncoveredDataConstructors st di mRefined alts
            missing <- filterM (fmap not . constructorFiberEmpty ctx t) uncovered
            unless (null missing) $
              report $
                withNote ("missing cases: " <> T.intercalate ", " (map gnameText missing)) $
                  diag SevError StageElaborate "E_PATTERN_NON_EXHAUSTIVE" (Just "kappa.pattern.non-exhaustive") sp
                    "match is not exhaustive"
          Nothing -> requireCatchAll
      VVariantT members -> do
        tags <- mapM (tagOf ctx) members
        let covered = concat [corePatternCoveredTags p | (p, Nothing) <- alts]
            hasRest = any corePatternHasVariantRest [p | (p, Nothing) <- alts]
            missing = tags \\ covered
        unless (null missing || hasRest) $
          report $
            withNote ("missing member types: " <> T.intercalate ", " missing) $
              diag SevError StageElaborate "E_PATTERN_NON_EXHAUSTIVE" (Just "kappa.pattern.non-exhaustive") sp
                "variant match is not exhaustive"
      VRecordT _ -> do
        st <- get
        let unguarded = [p | (p, Nothing) <- alts]
            tupleRows = [[p] | p@CPTuple {} <- unguarded]
            tupleComplete = not (null tupleRows) && not (wildUseful st tupleRows 1)
        unless (tupleComplete || any coreRecordPatternIrrefutable unguarded) requireCatchAll
      _ -> requireCatchAll
  where
    requireCatchAll =
      report $
        diag SevError StageElaborate "E_PATTERN_NON_EXHAUSTIVE" (Just "kappa.pattern.non-exhaustive") sp
          "match requires a catch-all case for this scrutinee type (§17.1)"

uncoveredDataConstructors
  :: CheckState
  -> DataInfo
  -> Maybe [GName]
  -> [(CorePat, Maybe Term)]
  -> [GName]
uncoveredDataConstructors st di mRefined alts =
  [ c
  | c <- ctorsToCover
  , let arity = ctorArity st c
  , wildUseful st (specializeRows st (KCtor c) arity rows) arity
  ]
  where
    allCtors = diCtors di
    ctorsToCover = case mRefined of
      Just constructors
        | not (null constructors)
        , all (`elem` allCtors) constructors -> constructors
      _ -> allCtors
    rows = [[pattern'] | (pattern', Nothing) <- alts]

-- | Is an uncovered constructor's refined fiber provably empty? This is the
-- common judgment used by omission exhaustiveness and terminal
-- @case impossible@ remainder checking.
constructorFiberEmpty :: Ctx -> Value -> GName -> CheckM Bool
constructorFiberEmpty ctx scrutTy constructor = do
  env <- mkInhabEnv ctx
  inhabCtorFiber ctx scrutTy constructor >>= \case
    CtorContradiction -> pure True
    CtorIndexUnknown -> pure False
    CtorRefined fieldTypes -> do
      summaries <-
        mapM
          (inhabitanceSummary env SourceReachability)
          fieldTypes
      pure (any isEmpty summaries)

corePatternCatchAll :: CorePat -> Bool
corePatternCatchAll = \case
  CPWild -> True
  CPVar _ -> True
  CPAs _ pattern' -> corePatternCatchAll pattern'
  CPOr patterns _ -> any corePatternCatchAll patterns
  _ -> False

corePatternIrrefutableSubpattern :: CorePat -> Bool
corePatternIrrefutableSubpattern = \case
  CPWild -> True
  CPVar _ -> True
  CPAs _ pattern' -> corePatternIrrefutableSubpattern pattern'
  CPTuple patterns -> all corePatternIrrefutableSubpattern patterns
  CPRecord fields _ -> all (corePatternIrrefutableSubpattern . snd) fields
  _ -> False

corePatternCoveredTags :: CorePat -> [Text]
corePatternCoveredTags = \case
  CPInject tag pattern'
    | corePatternIrrefutableSubpattern pattern' -> [tag]
  CPOr patterns _ -> concatMap corePatternCoveredTags patterns
  _ -> []

corePatternHasVariantRest :: CorePat -> Bool
corePatternHasVariantRest = \case
  CPInjectRest _ -> True
  _ -> False

coreRecordPatternIrrefutable :: CorePat -> Bool
coreRecordPatternIrrefutable = \case
  CPRecord fields _ -> all (corePatternIrrefutableSubpattern . snd) fields
  CPTuple patterns -> all corePatternIrrefutableSubpattern patterns
  CPAs _ pattern' -> coreRecordPatternIrrefutable pattern'
  CPOr patterns _ -> any coreRecordPatternIrrefutable patterns
  pattern' -> corePatternCatchAll pattern'

-- §17.1 exhaustiveness for nested constructor patterns, via pattern-
-- matrix usefulness (Maranget-style, over-approximating coverage for
-- record, variant and as-patterns so positives never regress): a match
-- is non-exhaustive iff the all-wildcard row is useful w.r.t. the
-- unguarded rows.
data PatKey = KCtor !GName | KTup !Int | KLit !Literal
  deriving stock (Eq)

ctorArity :: CheckState -> GName -> Int
ctorArity st c = case Map.lookup c (csCtors st) of
  Just ci -> length (ciFields ci)
  Nothing -> 0

-- unwrap as/or patterns into plain alternatives for the first column
expandRow :: [CorePat] -> [[CorePat]]
expandRow [] = [[]]
expandRow (p : ps) = case p of
  CPAs _ q -> expandRow (q : ps)
  CPOr qs _ -> concat [expandRow (q : ps) | q <- qs]
  _ -> [p : ps]

-- a first-column pattern this analysis treats as matching anything
isWildLike :: CheckState -> CorePat -> Bool
isWildLike st = \case
  CPWild -> True
  CPVar _ -> True
  CPRecord {} -> True -- over-approximation
  CPInject {} -> True -- nested variant injections: over-approximation
  CPInjectRest _ -> True
  -- an arity-mismatched constructor pattern was already diagnosed;
  -- do not cascade a non-exhaustiveness report
  CPCtor c _ ps -> length ps /= ctorArity st c
  _ -> False

patKey :: CheckState -> CorePat -> Maybe (PatKey, Int)
patKey st = \case
  CPCtor c _ ps | length ps == ctorArity st c -> Just (KCtor c, length ps)
  CPTuple ps -> Just (KTup (length ps), length ps)
  CPLit l -> Just (KLit l, 0)
  _ -> Nothing

subPats :: CorePat -> [CorePat]
subPats = \case
  CPCtor _ _ ps -> ps
  CPTuple ps -> ps
  _ -> []

specializeRows :: CheckState -> PatKey -> Int -> [[CorePat]] -> [[CorePat]]
specializeRows st k a rows =
  [ row'
  | row0 <- rows
  , row <- expandRow row0
  , Just row' <- [spec row]
  ]
  where
    spec [] = Nothing
    spec (p : ps)
      | isWildLike st p = Just (replicate a CPWild ++ ps)
      | Just (k', _) <- patKey st p, k' == k = Just (subPats p ++ ps)
      | otherwise = Nothing

defaultRows :: CheckState -> [[CorePat]] -> [[CorePat]]
defaultRows st rows =
  [ ps
  | row0 <- rows
  , (p : ps) <- expandRow row0
  , isWildLike st p
  ]

-- is the all-wildcard row of width n useful w.r.t. the matrix?
wildUseful :: CheckState -> [[CorePat]] -> Int -> Bool
wildUseful _ rows 0 = null rows
wildUseful st rows n =
  let firsts = [p | row0 <- rows, (p : _) <- expandRow row0]
      keys = nub (mapMaybe (patKey st) firsts)
      tupleKeys = [(key, arity) | (key@KTup {}, arity) <- keys]
      constructorKeys = [(key, arity) | (key@KCtor {}, arity) <- keys]
      completeSignature = case tupleKeys of
        signature@((KTup arity, _) : _)
          | all (\case (KTup otherArity, _) -> otherArity == arity; _ -> False) signature ->
              Just signature
        _ -> case constructorKeys of
          signature@((KCtor constructor, _) : _) ->
            case Map.lookup constructor (csCtors st) >>= \info ->
              Map.lookup (ciData info) (csDatas st) of
              Just dataInfo
                | all (\dataConstructor -> KCtor dataConstructor `elem` map fst signature)
                    (diCtors dataInfo) ->
                    Just signature
              _ -> Nothing
          _ -> Nothing
   in case completeSignature of
        Just signature ->
          or
            [ wildUseful st (specializeRows st k a rows) (a + n - 1)
            | (k, a) <- signature
            ]
        Nothing -> wildUseful st (defaultRows st rows) (n - 1)

-- | Expand a binder-free catch-all into the finite constructor/product
-- skeletons not covered by preceding unguarded rows. This is a typed pattern
-- certificate, not an exhaustiveness guess: expansion is available only for
-- closed nominal sums and structural products whose complete constructor
-- signature is known, and is bounded to keep elaboration predictable. The
-- resulting source patterns are re-elaborated normally, so nested branch
-- refinements are serialized in the emitted Core alternatives.
residualCatchAllPatterns
  :: CheckState
  -> Value
  -> [(CorePat, Maybe Term)]
  -> Span
  -> Maybe [Pattern]
residualCatchAllPatterns state scrutineeType preceding site = do
  candidates <- finitePatternSkeletons state 64 scrutineeType
  let covered = [pattern' | (pattern', Nothing) <- preceding]
      residuals =
        [ candidate
        | candidate <- candidates
        , not (any (`corePatternCovers` candidate) covered)
        ]
  mapM (skeletonSourcePattern state site) residuals

finitePatternSkeletons :: CheckState -> Int -> Value -> Maybe [CorePat]
finitePatternSkeletons state budget = go budget . force (ecOf state)
  where
    go remaining value
      | remaining <= 0 = Nothing
      | otherwise = case value of
          VUniverseLift _ _ _ inner -> go remaining (force (ecOf state) inner)
          VRecordTQ fields -> do
            alternatives <- mapM (go remaining . rfType) fields
            products <- boundedCartesian remaining alternatives
            pure (map CPTuple products)
          VRecordT fields -> do
            alternatives <- mapM (go remaining . snd) fields
            products <- boundedCartesian remaining alternatives
            pure (map CPTuple products)
          VGlobN family _ -> nominal remaining family
          VGlobI family _ _ -> nominal remaining family
          _ -> Nothing
    nominal remaining family = do
      dataInfo <- Map.lookup family (csDatas state)
      guard (not (null (diCtors dataInfo)))
      constructors <- mapM constructorSkeleton (diCtors dataInfo)
      guard (length constructors <= remaining)
      pure constructors
    constructorSkeleton constructor = do
      info <- Map.lookup constructor (csCtors state)
      pure
        ( CPCtorM
            []
            []
            []
            constructor
            []
            (replicate (length (ciFields info)) CPWild)
        )

boundedCartesian :: Int -> [[a]] -> Maybe [[a]]
boundedCartesian budget alternatives =
  let cardinality = product (map length alternatives)
   in if cardinality > budget
        then Nothing
        else Just (sequence alternatives)

corePatternCovers :: CorePat -> CorePat -> Bool
corePatternCovers covering candidate = case covering of
  CPWild -> True
  CPVar _ -> True
  CPAs _ nested -> corePatternCovers nested candidate
  CPOr alternatives _ -> any (`corePatternCovers` candidate) alternatives
  CPCtor constructor _ fields -> case candidate of
    CPCtor candidateConstructor _ candidateFields ->
      constructor == candidateConstructor
        && length fields == length candidateFields
        && and (zipWith corePatternCovers fields candidateFields)
    _ -> False
  CPTuple fields -> case candidate of
    CPTuple candidateFields ->
      length fields == length candidateFields
        && and (zipWith corePatternCovers fields candidateFields)
    _ -> False
  CPLit literal -> case candidate of
    CPLit candidateLiteral -> literal == candidateLiteral
    _ -> False
  _ -> False

skeletonSourcePattern :: CheckState -> Span -> CorePat -> Maybe Pattern
skeletonSourcePattern state site = \case
  CPWild -> Just (PWild site)
  CPTuple fields -> PTuple <$> mapM (skeletonSourcePattern state site) fields <*> pure site
  CPCtor constructor _ fields -> do
    info <- Map.lookup constructor (csCtors state)
    nested <- mapM (skeletonSourcePattern state site) fields
    let qualifier = Name (gnameText (ciData info)) site
        constructorName = Name (gnameText constructor) site
    pure
      ( PCtor
          (CtorRef (Just qualifier) constructorName)
          nested
          site
      )
  _ -> Nothing

checkIrrefutable :: Ctx -> Pattern -> Value -> Span -> CheckM ()
checkIrrefutable ctx pat ty sp = do
  ok <- irrefutableFor ctx pat ty
  unless ok $
    errAt sp "E_REFUTABLE_LET_PATTERN" (Just "kappa-hs.pattern.refutable-binding")
      "let bindings require an irrefutable pattern (§9.1.2); use match or let? instead"

irrefutableFor :: Ctx -> Pattern -> Value -> CheckM Bool
irrefutableFor ctx pat ty = case pat of
  PWild _ -> pure True
  PVar _ -> pure True
  PAs _ p -> irrefutableFor ctx p ty
  PTyped p _ _ -> irrefutableFor ctx p ty
  PTuple patterns _ -> do
    forced <- forceM ty
    case forced of
      VRecordTQ fields
        | length patterns == length fields ->
            and
              <$> zipWithM
                (irrefutableFor ctx)
                patterns
                (map rfType fields)
      _ -> pure False
  PUnit _ -> pure True
  PRecord fields _ _ -> do
    forced <- forceM ty
    case forced of
      VRecordTQ recordFields ->
        and
          <$> forM
            fields
            ( \(_, sourceName, nested) ->
                case find ((== nameText sourceName) . rfName) recordFields of
                  Just field ->
                    maybe
                      (pure True)
                      (\pattern' -> irrefutableFor ctx pattern' (rfType field))
                      nested
                  Nothing -> pure False
            )
      _ -> pure False
  PCtorNamed cref fields sp -> do
    resolveCtorWithoutDiagnostic ctx cref >>= \case
      Nothing -> pure False
      Just (_, constructorInfo) -> do
        let supplied =
              [ (nameText fieldName, fromMaybe (PVar fieldName) nested)
              | (fieldName, nested) <- fields
              ]
            positional =
              [ maybe (PWild sp) id (fieldName >>= (`lookup` supplied))
              | (fieldName, _) <- ciFields constructorInfo
              ]
        irrefutableFor ctx (PCtor cref positional sp) ty
  PCtor cref patterns sp -> do
    forced <- forceM ty
    resolved <- resolveCtorWithoutDiagnostic ctx cref
    case (forced, resolved) of
      (VGlobN dataIdentity _, Just (constructor, constructorInfo))
        | ciData constructorInfo == dataIdentity -> do
            state <- get
            case Map.lookup dataIdentity (csDatas state) of
              Just dataInfo -> do
                selectedEmpty <- constructorFiberEmpty ctx forced constructor
                siblingFibersEmpty <-
                  and
                    <$> mapM
                      (constructorFiberEmpty ctx forced)
                      (filter (/= constructor) (diCtors dataInfo))
                if not selectedEmpty && siblingFibersEmpty
                  then do
                    (sourceSlots, constructorCtx, _, _, _) <-
                      ctorFieldTypesCtx
                        ctx
                        constructor
                        constructorInfo
                        forced
                        sp
                    let explicitTypes =
                          [ fieldType
                          | ConstructorExplicitPatternSlot _ _ fieldType _ <-
                              sourceSlots
                          ]
                    if length patterns /= length explicitTypes
                      then pure False
                      else
                        and
                          <$> zipWithM
                            (irrefutableFor constructorCtx)
                            patterns
                            explicitTypes
                  else pure False
              _ -> pure False
      _ -> pure False
  POr patterns _ ->
    or <$> mapM (\pattern' -> irrefutableFor ctx pattern' ty) patterns
  _ -> pure False

-- | Branch-local conversion facts established while elaborating a pattern.
-- The map uses rigid de Bruijn levels, so it remains valid while the pattern
-- continuation extends the context with its binders. It is deliberately
-- opaque outside this module: callers can only install it with
-- 'withPatternRefinements', which enforces lexical save/restore.
newtype PatternRefinements = PatternRefinements (Map Int RigidFact)

emptyPatternRefinements :: PatternRefinements
emptyPatternRefinements = PatternRefinements Map.empty

withPatternRefinements :: PatternRefinements -> CheckM a -> CheckM a
withPatternRefinements (PatternRefinements refinements) action = do
  surrounding <- gets csFacts
  modify' $ \state ->
    state {csFacts = Map.union refinements surrounding}
  result <- action
  modify' $ \state -> state {csFacts = surrounding}
  pure result

-- pattern elaboration: produce core pattern, extended context, and the exact
-- active refinement context for the lexical continuation.
elabPattern :: Ctx -> Pattern -> Value -> CheckM (CorePat, Ctx, PatternRefinements)
elabPattern = elabPatternFrom Ordinary QW Nothing

-- | Elaborate a pattern from a checked producer.  The producer's observation
-- mode and semantic value are part of the pattern judgment: binding a field is
-- an alias of that projection, not a fresh unrelated rigid.  This is required
-- both for parametric-mode preservation and for dependent record fields such as
-- @value : this.A@ to normalize through an earlier @A@ pattern binder.
elabPatternFrom :: ObservationMode -> Q -> Maybe Value -> Ctx -> Pattern -> Value -> CheckM (CorePat, Ctx, PatternRefinements)
elabPatternFrom rootMode rootQ rootValue ctx0 pat0 ty0 = do
  surrounding <- gets csFacts
  (p, ctx) <- goSlot ctx0 pat0 (rootMode, rootQ, ty0) rootValue
  refinements <- gets csFacts
  modify' $ \state -> state {csFacts = surrounding}
  forM_ (duplicatesOf (corePatNames p)) $ \n ->
    errAt (patternSpan pat0) "E_DUPLICATE_PATTERN_BINDER" (Just "kappa-hs.pattern.duplicate-binder")
      ("pattern binds '" <> n <> "' more than once (§17.2)")
  pure (p, ctx, PatternRefinements refinements)
  where
    corePatNames :: CorePat -> [Text]
    corePatNames = \case
      CPVar n -> [n]
      CPAs n p -> n : corePatNames p
      CPCtor _ _ ps -> concatMap corePatNames ps
      CPTuple ps -> concatMap corePatNames ps
      CPRecord fs mr -> concatMap (corePatNames . snd) fs ++ [nm | Just nm <- [mr], not (T.null nm)]
      CPInject _ p -> corePatNames p
      -- or-pattern alternatives bind the same names; count one side
      CPOr (p : _) _ -> corePatNames p
      _ -> []
    -- §17.2.3/§17.1: the FULL ordered binder layout that 'matchPat' actually
    -- returns for a pattern, with @Nothing@ for an erased existential-skolem
    -- placeholder slot and @Just name@ for a real named binder. This must match
    -- 'matchPat' / 'patBindersC' exactly: interface existentials and bridge
    -- binders come first, while omitted source implicits retain their declared
    -- positions among explicit fields. Or-pattern perms are built over THIS
    -- list (not the name-only 'corePatNames'), so they index the same slots
    -- 'matchPat' produces.
    corePatBinderSlots :: CorePat -> [Maybe Text]
    corePatBinderSlots = \case
      CPVar n -> [Just n]
      CPAs n p -> Just n : corePatBinderSlots p
      CPCtorM existentialModes bridges hidden _ _ patterns ->
        replicate
          (length existentialModes + constructorBridgeBinderCount bridges)
          Nothing
          ++ case
            interleaveConstructorSourceBinders
              hidden
              (map corePatBinderSlots patterns)
          of
            Just source ->
              concatMap (either (const [Nothing]) id) source
            Nothing ->
              -- Malformed compiler metadata must not associate an alternative's
              -- user binder with a different runtime slot.
              replicate
                (length hidden + sum (map patBindersC patterns))
                Nothing
      CPTuple ps -> concatMap corePatBinderSlots ps
      CPRecord fs mr -> concatMap (corePatBinderSlots . snd) fs ++ [Just nm | Just nm <- [mr], not (T.null nm)]
      CPInject _ p -> corePatBinderSlots p
      CPInjectRest _ -> [Nothing]
      CPOr (p : _) _ -> corePatBinderSlots p
      _ -> []
    go ctx pat tyIn = goSlot ctx pat (Ordinary, QW, tyIn) Nothing

    goSlot ctx pat (slotMode, slotQ, tyIn) knownValue = do
      ty <- forceM tyIn
      case pat of
        PWild sp -> do
          when (slotQ == Q1 || slotQ == QGe1) $
            errOnce sp "E_QTT_LINEAR_DROP"
              (Just "kappa.quantity.positive-lower-bound")
              "wildcard or omitted pattern field discards a value whose quantity requires at least one runtime use (§12.2.5–§12.2.6)"
          pure (CPWild, ctx)
        PVar n -> do
          -- A bare lowercase atom is parsed as a variable because the parser
          -- has no symbol table. Resolve it here: a checked nullary
          -- constructor is a constructor pattern, while every other name
          -- remains a fresh pattern binder.
          state <- get
          case
              [ (constructor, info)
              | (constructor, info) <- unqualifiedConstructorCandidates state n
              , null (ciFields info)
              ]
            of
              ((constructor, info) : _) -> do
                (sourceSlots, ctxEx, existentialModes, refinements, universes) <-
                  ctorFieldTypesCtx ctx constructor info ty (nameSpan n)
                let explicitSlots =
                      [()
                      | ConstructorExplicitPatternSlot {} <- sourceSlots
                      ]
                unless (null explicitSlots) $
                  errAt
                    (nameSpan n)
                    "E_PATTERN_CONSTRUCTOR_ARITY_MISMATCH"
                    (Just "kappa.pattern.constructor-arity")
                    "constructor pattern arity mismatch: expected explicit fields"
                (_, hidden, ctx') <-
                  goCtorListSlots ctxEx [] sourceSlots 0
                let constructorPattern =
                      CPCtorM
                        existentialModes
                        refinements
                        hidden
                        constructor
                        universes
                        []
                recordKnownConstructorRefinement ctx ty knownValue constructorPattern
                pure (constructorPattern, ctx')
              [] -> do
                recordPatternBinderFacts ctx (nameSpan n) slotQ ty
                let ctx' = case knownValue of
                      Just value -> bindCtxLetProjOpMode (nameText n) False ty value Nothing Nothing slotMode (Just (nameText n)) ctx
                      Nothing -> bindCtxMQ slotMode slotQ (nameText n) False ty ctx
                pure (CPVarM slotMode (nameText n), ctx')
        PUnit _ -> do
          unitType <- globalValueM prelUnit []
          compatible <- unify ctx ty unitType
          unless compatible $
            patternTypeMismatch ctx pat ty "the unit pattern requires a Unit scrutinee"
          let unitPattern = CPCtorM [] [] [] prelUnit [] []
          recordKnownConstructorRefinement ctx ty knownValue unitPattern
          pure (unitPattern, ctx)
        PLit l _ -> do
          -- §17.2.1: literal patterns are runtime scalar tests. Admit exactly
          -- the canonical scalar carrier identities (transparent aliases have
          -- already been forced), never a same-spelled user declaration.
          unless (literalPatternTypeAgrees (coreLit l) ty) $
            patternTypeMismatch ctx pat ty "literal pattern and scrutinee types differ"
          pure (CPLit (coreLit l), ctx)
        PAs n p -> do
          recordPatternBinderFacts ctx (nameSpan n) slotQ ty
          let ctx1 = case knownValue of
                Just value -> bindCtxLetProjOpMode (nameText n) False ty value Nothing Nothing slotMode (Just (nameText n)) ctx
                Nothing -> bindCtxMQ slotMode slotQ (nameText n) False ty ctx
          (p', ctx2) <- goSlot ctx1 p (slotMode, slotQ, ty) knownValue
          pure (CPAsM slotMode (nameText n) p', ctx2)
        PTyped p tyE _ -> do
          (tyTm, _) <- inferType ctx tyE
          tyV <- evalIn ctx tyTm
          compatible <- unify ctx tyV ty
          unless compatible $
            patternTypeMismatch ctx pat ty "typed pattern and scrutinee types differ"
          goSlot ctx p (slotMode, slotQ, tyV) knownValue
        PTuple ps _ -> do
          let arity = length ps
          slots <- case ty of
            VRecordTQ fields
              | length fields == arity ->
                  pure [(rfMode field, rfQ field, rfType field) | field <- fields]
              | otherwise -> do
                  patternTypeMismatch ctx pat ty
                    ("tuple pattern has arity " <> T.pack (show arity)
                       <> " but its scrutinee has arity " <> T.pack (show (length fields)))
                  padding <- mapM (const ((Ordinary, QW,) <$> freshMetaV ctx)) [length fields .. arity - 1]
                  pure (take arity ([(rfMode field, rfQ field, rfType field) | field <- fields] ++ padding))
            _ -> do
              patternTypeMismatch ctx pat ty "tuple pattern requires a tuple scrutinee"
              mapM (const ((Ordinary, QW,) <$> freshMetaV ctx)) ps
          knownFields <- case (knownValue, ty) of
            (Just value, VRecordTQ fields)
              | length fields == arity -> do
                  ec <- ec_
                  pure [Just (vproj ec (rfMode field) value (rfName field)) | field <- fields]
            _ -> pure (replicate (length ps) Nothing)
          (ps', ctx') <- goListSlotsKnown ctx (zip3 ps slots knownFields)
          pure (CPTuple ps', ctx')
        PRecord fs mrest _ -> do
          fields <- case ty of
            VRecordTQ fts -> pure fts
            _ -> pure []
          ec <- ec_
          let requested =
                [ (nameText n, fromMaybe (PVar n) mp)
                | (_, n, mp) <- fs
                ]
              selected =
                [ ( field
                  , pattern'
                  , case knownValue of
                      Just value -> Just (vproj ec (rfMode field) value (rfName field))
                      Nothing -> Nothing
                  )
                | field <- fields
                , Just pattern' <- [lookup (rfName field) requested]
                ]
          (ps', ctx') <-
            goRecordFields knownValue ctx selected
          let names = map (rfName . (\(field, _, _) -> field)) selected
              patternedFields = zip names ps'
          case mrest of
            Just (PatRestBind restN) -> do
              -- ..rest binds the remaining fields as a record (§17.2.5)
              let remaining = [field | field <- fields, rfName field `notElem` names]
                  ctx'' = bindCtx (nameText restN) False (VRecordTQ remaining) ctx'
              pure (CPRecordM patternedFields (Just (Ordinary, nameText restN)), ctx'')
            Just PatRestDiscard -> pure (CPRecordM patternedFields (Just (Ordinary, "")), ctx')
            Nothing -> pure (CPRecordM patternedFields Nothing, ctx')
        POr ps sp -> do
          surrounding <- gets csFacts
          rs <- forM ps $ \p -> do
            modify' $ \state -> state {csFacts = surrounding}
            goSlot ctx p (slotMode, slotQ, ty) knownValue
          -- Alternative-specific GADT equations are not valid in the shared
          -- continuation unless every alternative proves the same equation
          -- under the canonical binder permutation. That intersection is not
          -- represented yet, so retain only the facts that preceded the
          -- or-pattern. This is the conservative branch join.
          modify' $ \state -> state {csFacts = surrounding}
          let pats = map fst rs
          case rs of
            [] -> pure (CPWild, ctx)
            (firstResult@(p1, ctx1) : _) -> do
              -- §17.2.3: every alternative must bind the SAME SET of names,
              -- with corresponding binders at definitionally-equal types. The
              -- body uses the first alternative's binder order (canonical); for
              -- each alternative we record the permutation from its own
              -- structural binder order to canonical, so a reordered binding
              -- (e.g. `A p q | B q p`) still resolves correctly at runtime.
              let alternatives = zip ps rs
                  sourceNames sourcePattern =
                    map nameText (surfPatVars sourcePattern)
                  canonical =
                    maybe [] (sourceNames . fst) (listToMaybe alternatives)
                  structNames (sourcePattern, _) = sourceNames sourcePattern
                  binderSlots sourcePattern corePattern =
                    let visible = sourceNames sourcePattern
                     in [ case slot of
                            Just name
                              | name `elem` visible -> Just name
                            _ -> Nothing
                        | slot <- corePatBinderSlots corePattern
                        ]
                  -- Full binder layout (placeholders included) for perm building.
                  canonSlots =
                    case alternatives of
                      (sourcePattern, (corePattern, _)) : _ ->
                        binderSlots sourcePattern corePattern
                      [] -> []
                  nSlots = length canonSlots
                  -- Map a canonical full-binder position @j@ to the matching
                  -- slot index in alternative @r@'s OWN full binder list.
                  --   * a named slot maps to the alternative's slot with the
                  --     same name (alternatives bind the same name set);
                  --   * an erased placeholder slot maps positionally to the
                  --     alternative's k-th placeholder (any erased unit is fine,
                  --     but positional keeps a stable, total mapping even when
                  --     alternatives carry differing existential arities).
                  permFor (sourcePattern, (corePattern, _)) =
                    let altSlots = binderSlots sourcePattern corePattern
                        altPlaceholders = [i | (i, Nothing) <- zip [0 ..] altSlots]
                        -- canonical-placeholder ordinal among canonical Nothings
                        canonPlaceholderOrd j =
                          length [() | (k, Nothing) <- zip [0 ..] canonSlots, k < j]
                     in [ case canonSlots !! j of
                            Just nm ->
                              fromMaybe j (elemIndex (Just nm) altSlots)
                            Nothing ->
                              let o = canonPlaceholderOrd j
                               in if o < length altPlaceholders
                                    then altPlaceholders !! o
                                    else j
                        | j <- [0 .. nSlots - 1]
                        ]
                  typesOf (_, c) =
                    [ (ceName e, ceType e)
                    | e <- take (ctxLen c - ctxLen ctx) (ctxEntries c)
                    ]
              ec <- ec_
              if not
                ( all
                    (\alternative -> sort (structNames alternative) == sort canonical)
                    alternatives
                )
                then do
                  errAt sp "E_OR_PATTERN_BINDER_MISMATCH" (Just "kappa-hs.pattern.or-bindings")
                    "all alternatives of an or-pattern must bind the same set of names (§17.2.3)"
                  pure
                    ( CPOr pats (map (const [0 .. nSlots - 1]) alternatives)
                    , ctx1
                    )
                else do
                  -- §17.2.3 binder-type agreement (best-effort at the scrutinee
                  -- context depth; catches e.g. `I (n:Integer) | S (s:String)`)
                  let t1 = typesOf firstResult
                  forM_ (drop 1 rs) $ \r -> do
                    let ti = typesOf r
                    forM_ canonical $ \nm ->
                      case (lookup nm t1, lookup nm ti) of
                        (Just a, Just b) ->
                          unless (convertible ec (ctxLen ctx) a b) $
                            errAt sp "E_OR_PATTERN_BINDER_MISMATCH" (Just "kappa-hs.pattern.or-bindings")
                              ( "or-pattern binder '" <> nm
                                  <> "' has incompatible types across alternatives (§17.2.3)")
                        _ -> pure ()
                  let perms = map permFor alternatives
                  pure (CPOr pats perms, ctx1)
        PVariant mn mtyE isWild mrest _ -> case ty of
          VVariantT members -> case (mn, mtyE, mrest) of
            (_, Just tyE, Nothing) -> do
              (tyTm, _) <- inferType ctx tyE
              tyV <- evalIn ctx tyTm
              tag <- tagOf ctx tyV
              tags <- mapM (tagOf ctx) members
              unless (tag `elem` tags) $
                errAt (patternSpan pat) "E_VARIANT_MEMBER" (Just "kappa-hs.variant.unknown-member")
                  "variant pattern type is not a member of the scrutinee union"
              if isWild
                then pure (CPInject tag CPWild, ctx)
                else case mn of
                  Just n ->
                    let ctx' = case knownValue of
                          Just value -> bindCtxLetProjOpMode (nameText n) False tyV value Nothing Nothing slotMode (Just (nameText n)) ctx
                          Nothing -> bindCtxMQ slotMode slotQ (nameText n) False tyV ctx
                     in pure (CPInject tag (CPVarM slotMode (nameText n)), ctx')
                  Nothing -> pure (CPInject tag CPWild, ctx)
            (Just n, Nothing, Nothing)
              | [single] <- members -> do
                  tag <- tagOf ctx single
                  let ctx' = case knownValue of
                        Just value -> bindCtxLetProjOpMode (nameText n) False single value Nothing Nothing slotMode (Just (nameText n)) ctx
                        Nothing -> bindCtxMQ slotMode slotQ (nameText n) False single ctx
                   in pure (CPInject tag (CPVarM slotMode (nameText n)), ctx')
              | otherwise -> do
                  errAt (nameSpan n) "E_VARIANT_AMBIGUOUS" (Just "kappa-hs.variant.ambiguous")
                    "untyped variant pattern requires a singleton union (§13.1.7)"
                  pure (CPWild, ctx)
            (Nothing, Nothing, Just restN) -> do
              let ctx' = case knownValue of
                    Just value -> bindCtxLetProjOpMode (nameText restN) False ty value Nothing Nothing slotMode (Just (nameText restN)) ctx
                    Nothing -> bindCtxMQ slotMode slotQ (nameText restN) False ty ctx
               in pure (CPInjectRestM slotMode [], ctx')
            _ -> do
              errAt (patternSpan pat) "E_VARIANT_PATTERN" Nothing "malformed variant pattern"
              pure (CPWild, ctx)
          _ -> do
            errAt (patternSpan pat) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
              "variant pattern requires a union scrutinee"
            pure (CPWild, ctx)
        PCtorNamed cref fields sp -> do
          mr <- resolveCtor ctx cref
          case mr of
            Nothing -> pure (CPWild, ctx)
            Just (_, ci) -> do
              let fieldNames = mapMaybe fst (ciFields ci)
              forM_ fields $ \(n, _) ->
                unless (nameText n `elem` fieldNames) $
                  errAt (nameSpan n) "E_PATTERN_FIELD_UNKNOWN" (Just "kappa.pattern.constructor-arity")
                    ("constructor has no named field '" <> nameText n <> "'")
              let posPats =
                    [ case lookup fn [(nameText n, fromMaybe (PVar n) mp) | (n, mp) <- fields] of
                        Just p -> p
                        Nothing -> PWild sp
                    | Just fn <- map fst (ciFields ci)
                    ]
              goSlot ctx (PCtor cref posPats sp) (slotMode, slotQ, tyIn) knownValue
        PCtor cref ps sp -> do
          mr <- resolveCtor ctx cref
          case mr of
            Nothing -> pure (CPWild, ctx)
            Just (g, ci) -> do
              -- §17.1: the cases' constructor patterns must belong to
              -- the (known) scrutinee type
              case ty of
                VGlobN h _ | h /= ciData ci -> do
                  hT <- quoteIn ctx ty
                  errOnce sp "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                    ("constructor pattern of type '" <> gnameText (ciData ci)
                       <> "' cannot match a scrutinee of type '" <> renderTerm hT <> "' (§17.1)")
                _ -> pure ()
              -- §17.1: unpacking a GADT constructor binds its EXISTENTIAL
              -- indices (the implicit params not pinned by the scrutinee type)
              -- as fresh rigid skolems in 'ctxEx'. The field patterns — and any
              -- inner match over a field whose type mentions such a skolem — must
              -- elaborate under that extended context so the skolem has a valid de
              -- Bruijn level and stays abstract (cannot be destructively solved by
              -- a sub-match arm). See 'ctorFieldTypesCtx'.
              (sourceSlots, ctxEx, existentialModes, refinements, universes) <-
                ctorFieldTypesCtx ctx g ci ty sp
              let explicitSlots =
                    [ slot
                    | slot@ConstructorExplicitPatternSlot {} <- sourceSlots
                    ]
              when (length ps /= length explicitSlots) $
                errAt sp "E_PATTERN_CONSTRUCTOR_ARITY_MISMATCH" (Just "kappa.pattern.constructor-arity")
                  ("constructor pattern arity mismatch: expected "
                     <> T.pack (show (length explicitSlots))
                     <> ", got "
                     <> T.pack (show (length ps)))
              -- Surplus binders get fresh metas, not Type: after the
              -- arity diagnostic the bodies must not cascade (§3.1).
              padTys <- mapM (const (freshMetaV ctxEx)) (drop (length explicitSlots) ps)
              let slots =
                    sourceSlots
                      ++ [ ConstructorExplicitPatternSlot Ordinary QW t Nothing
                         | t <- padTys
                         ]
              (ps', hidden, ctx') <- goCtorListSlots ctxEx ps slots 0
              let constructorPattern =
                    CPCtorM existentialModes refinements hidden g universes ps'
              recordKnownConstructorRefinement ctx ty knownValue constructorPattern
              pure (constructorPattern, ctx')
        PActive _ _ _ sp -> do
          unsupportedAt sp "active patterns are not supported by this implementation"
          pure (CPWild, ctx)
        POpChain {} -> do
          errAt (patternSpan pat) "E_INTERNAL" Nothing "operator pattern not re-associated"
          pure (CPWild, ctx)

    goList ctx [] = pure ([], ctx)
    goList ctx ((p, t) : rest) = do
      (p', ctx') <- go ctx p t
      (ps, ctx'') <- goList ctx' rest
      pure (p' : ps, ctx'')

    goListSlots ctx [] = pure ([], ctx)
    goListSlots ctx ((p0, (mode, q, t)) : rest) = do
      let p = case (q, p0) of
            (Q0, PCtor (CtorRef Nothing n) [] psp) -> PVar (n {nameSpan = psp})
            _ -> p0
      (p', ctx') <- goSlot ctx p (mode, q, t) Nothing
      ctxQ <- case p of
        PVar n -> setNewestPatternObservation 1 mode q (nameText n) ctx'
        PAs n _ -> setNewestPatternObservation 2 mode q (nameText n) ctx'
        _ -> pure ctx'
      let p'' = case p' of
            CPVarM _ name -> CPVarM mode name
            CPAsM _ name inner -> CPAsM mode name inner
            other -> other
      (ps, ctx'') <- goListSlots ctxQ rest
      pure (p'' : ps, ctx'')

    -- Constructor field types are instantiated before their source patterns
    -- are elaborated. Retain every placeholder used by the dependent suffix:
    -- its semantic identity must become the rigid identity of that pattern
    -- binder before later fields and erased comparison binders are checked.
    goCtorListSlots ctx patterns [] _ = do
      recoveryTypes <- mapM (const (freshMetaV ctx)) patterns
      (recovery, ctx') <-
        goListSlots
          ctx
          (zip patterns [(Ordinary, QW, ty) | ty <- recoveryTypes])
      pure (recovery, [], ctx')
    goCtorListSlots
      ctx
      patterns
      (ConstructorHiddenPatternSlot mode q t witness assumption : rest)
      explicitPrefix = do
        t' <- quoteIn ctx t >>= zonkTermM (ctxLen ctx) >>= evalIn ctx
        let level = ctxLen ctx
            bound =
              bindCtxMQ
                mode
                q
                "_ctor_implicit"
                True
                t'
                ctx
        extended <-
          extendLevelAssumption
            (patternSpan pat0)
            bound
            assumption
        connectConstructorWitness extended t' witness level
        (remainingPatterns, hidden, finalCtx) <-
          goCtorListSlots extended patterns rest explicitPrefix
        pure
          ( remainingPatterns
          , ConstructorHiddenBinder explicitPrefix mode : hidden
          , finalCtx
          )
    goCtorListSlots
      ctx
      []
      (ConstructorExplicitPatternSlot _ _ _ _ : rest)
      explicitPrefix = do
        (patterns, hidden, finalCtx) <-
          goCtorListSlots ctx [] rest (explicitPrefix + 1)
        pure (CPWild : patterns, hidden, finalCtx)
    goCtorListSlots
      ctx
      (p0 : sourcePatterns)
      (ConstructorExplicitPatternSlot mode q t fieldWitness : rest)
      explicitPrefix = do
        let sourcePattern = case (q, p0) of
              (Q0, PCtor (CtorRef Nothing n) [] psp) ->
                PVar (n {nameSpan = psp})
              _ -> p0
        (p, hiddenWitnessAlias) <-
          case (sourcePattern, q, patternPrincipalBinder sourcePattern) of
            (PWild _, quantity, Nothing)
              | quantity == Q0 || quantity == QW -> do
                  hidden <- freshNameM "#ctor_field"
                  pure
                    ( PAs (Name hidden (patternSpan sourcePattern)) sourcePattern
                    , True
                    )
            _ -> pure (sourcePattern, False)
        -- Earlier constructor fields may just have fixed first-class level
        -- metas that occur in this dependent field's type. Reify through the
        -- current assignment map before binding the field so its context entry
        -- carries the finalized rigid schema instance.
        t' <- quoteIn ctx t >>= zonkTermM (ctxLen ctx) >>= evalIn ctx
        (p', ctx') <- goSlot ctx p (mode, q, t') Nothing
        ctxQ <-
          if hiddenWitnessAlias
            then pure ctx'
            else case p of
              PVar n -> setNewestPatternObservation 1 mode q (nameText n) ctx'
              PAs n _ -> setNewestPatternObservation 2 mode q (nameText n) ctx'
              _ -> pure ctx'
        forM_ fieldWitness $ \witness ->
          case patternPrincipalBinder p >>= (`lookupCtx` ctxQ) of
            Just (index, _) -> do
              let level = ctxLen ctxQ - index - 1
              connectConstructorWitness ctxQ t' witness level
            Nothing -> pure ()
        let p'' = case p' of
              CPVarM _ name -> CPVarM mode name
              CPAsM _ name inner -> CPAsM mode name inner
              other -> other
        (ps, hidden, ctx'') <-
          goCtorListSlots
            ctxQ
            sourcePatterns
            rest
            (explicitPrefix + 1)
        pure (p'' : ps, hidden, ctx'')

    connectConstructorWitness activeCtx classifierValue witness level = do
      let meta = case witness of
            ConstructorLevelWitness identity -> identity
            ConstructorTermWitness identity -> identity
      classifier <-
        quoteIn activeCtx classifierValue
          >>= zonkTermM (ctxLen activeCtx)
      let promoteClassifier state =
            state
              { csMetaClassifiers =
                  Map.adjust
                    (\metadata ->
                       metadata
                         { micDepth = ctxLen activeCtx
                         , micType = classifier
                         })
                    meta
                    (csMetaClassifiers state)
              }
      case witness of
        ConstructorLevelWitness identity -> do
          state <- get
          let current =
                normalizeLevel
                  ( substituteLevelMetas
                      (csLevelAssignments state)
                      (LMeta identity)
                  )
          case current of
            LMeta root -> do
              let promoted =
                    closeLevelDependents
                      (csLevelAssignmentDependents state)
                      (Set.singleton root)
              modify' $ \next ->
                let promotedState = promoteClassifier next
                 in promotedState
                      { csMetaClassifiers =
                          Map.mapWithKey
                            ( \dependent metadata ->
                                if dependent `Set.member` promoted
                                  then metadata {micDepth = ctxLen activeCtx}
                                  else metadata
                            )
                            (csMetaClassifiers promotedState)
                      }
              installLevelAssignments (Map.singleton root (LVar level))
            LVar existing
              | existing == level -> do
                  modify' promoteClassifier
                  void (solveMetaAcyclic identity (VRigid level []))
            _ -> do
              modify' promoteClassifier
              void (solveLevelIdentity activeCtx current (LVar level))
        ConstructorTermWitness identity -> do
          unsolved <-
            gets $ \state ->
              case Map.lookup identity (csMetas state) of
                Just Nothing -> True
                _ -> False
          when unsolved $ do
            modify' promoteClassifier
            solveMeta identity (VRigid level [])

    closeLevelDependents dependents roots = go roots roots
      where
        go seen frontier
          | Set.null frontier = seen
          | otherwise =
              let next =
                    Set.unions
                      [ Map.findWithDefault Set.empty meta dependents
                      | meta <- Set.toList frontier
                      ]
                      `Set.difference` seen
               in go (seen `Set.union` next) next

    patternPrincipalBinder = \case
      PVar n -> Just (nameText n)
      PAs n _ -> Just (nameText n)
      PTyped p _ _ -> patternPrincipalBinder p
      _ -> Nothing

    -- A nested constructor pattern refines the exact checked producer just as
    -- a root constructor branch does. The producer identity comes from the
    -- semantic value threaded by 'elabPatternFrom', while the replacement is
    -- reconstructed from the checked constructor certificate. If either side
    -- is not representable as a rigid substitution, retain no positive fact.
    recordKnownConstructorRefinement activeCtx classifier known pattern' =
      case known >>= rigidLevelThroughUniverseLift of
        Nothing -> pure ()
        Just rigid ->
          constructorPatternFact activeCtx classifier pattern' >>= \case
            Nothing -> pure ()
            Just replacement ->
              modify' $ \state ->
                state
                  { csFacts =
                      Map.insert rigid (FactIs replacement) (csFacts state)
                  }

    goListSlotsKnown ctx [] = pure ([], ctx)
    goListSlotsKnown ctx ((p0, slot@(_, q, _), known) : rest) = do
      let p = case (q, p0) of
            (Q0, PCtor (CtorRef Nothing n) [] psp) -> PVar (n {nameSpan = psp})
            _ -> p0
      (p', ctx') <- goSlot ctx p slot known
      (ps, ctx'') <- goListSlotsKnown ctx' rest
      pure (p' : ps, ctx'')

    goRecordFields _ ctx [] = pure ([], ctx)
    goRecordFields recordValue ctx ((field, pattern', known) : rest) = do
      fieldType <- case recordValue of
        Nothing -> pure (rfType field)
        Just root -> do
          rootTerm <- quoteIn ctx root
          substThisInto ctx rootTerm (rfType field)
      let slot = (rfMode field, rfQ field, fieldType)
          normalizedPattern = case (rfQ field, pattern') of
            (Q0, PCtor (CtorRef Nothing n) [] psp) -> PVar (n {nameSpan = psp})
            _ -> pattern'
      (patternCore, ctx') <- goSlot ctx normalizedPattern slot known
      (patterns, ctx'') <- goRecordFields recordValue ctx' rest
      pure (patternCore : patterns, ctx'')

    setNewestPatternObservation count mode q origin c = do
      let update e = e {ceMode = mode, ceCoreQ = q, ceObservationOrigin = Just origin}
          (bound, rest) = splitAt count (ctxEntries c)
      pure c {ctxEntries = map update bound ++ rest}

    coreLit = \case
      LInt v _ -> LitInt v
      LFloat v _ -> LitDouble v
      LString s -> LitStr s
      LScalar c -> LitScalar c
    literalPatternTypeAgrees lit = \case
      VFlex {} -> True
      VGlobN headIdentity [] -> headIdentity `elem` literalPatternHeads lit
      _ -> False

    literalPatternHeads = \case
      LitInt _ -> [prelInteger, prelInt, prelNat]
      LitDouble _ -> [prelDouble]
      LitStr _ -> [prelString]
      LitScalar _ -> [prelUnicodeScalar]
      -- These Core literals have no surface pattern form today.
      LitByte _ -> []
      LitBytes _ -> []
      LitGrapheme _ -> []

    patternTypeMismatch patternCtx pattern' actual summary = do
      actualTerm <- quoteIn patternCtx actual
      errOnce (patternSpan pattern') "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
        (summary <> ": got '" <> renderTerm actualTerm <> "' (§17.2.1)")

-- instantiate the constructor's field types against the scrutinee type
-- (GADT-lite: unify the constructor's result with the scrutinee type).
--
-- This is the value-only variant used by callers that consume the field types
-- as plain values (record-field projection, field-instance probing, record-patch
-- elaboration). It instantiates EVERY telescope binder (implicit and explicit)
-- with a fresh meta, exactly as before — it does NOT skolemize existentials and
-- does NOT extend the context. Keeping it meta-based is important: these callers
-- quote field types against the ORIGINAL context, so a field type must never
-- reference a skolem bound at a level outside that context (which would quote to
-- a negative de Bruijn index). The pattern-match path that DOES need rigid
-- existentials uses 'ctorFieldTypesCtx', which returns the extended context.
ctorFieldTypes :: Ctx -> GName -> CtorInfo -> Value -> Span -> CheckM [Value]
ctorFieldTypes ctx ctorG ci scrutTy sp = do
  map (\(_, _, ty) -> ty) <$> ctorFieldTypesWithQ ctx ctorG ci scrutTy sp

ctorFieldTypesWithQ :: Ctx -> GName -> CtorInfo -> Value -> Span -> CheckM [(ObservationMode, Q, Value)]
ctorFieldTypesWithQ ctx ctorG ci scrutTy sp = do
  (_, _, fields) <- ctorFieldInstantiationWithQ ctx ctorG ci scrutTy sp
  pure fields

-- | Instantiate one constructor occurrence, retaining the exact declaration-
-- universe spine and specialized constructor type that produced its field
-- types. Rebuilders must reuse this identity: independently freshening a
-- constructor after the result was unified with the scrutinee disconnects its
-- hidden universe arguments from the value being reconstructed.
ctorFieldInstantiationWithQ
  :: Ctx
  -> GName
  -> CtorInfo
  -> Value
  -> Span
  -> CheckM ([Level], Term, [(ObservationMode, Q, Value)])
ctorFieldInstantiationWithQ ctx ctorG ci scrutTy _ = do
  (universes, constructorType, _, _, fields) <-
    instantiateConstructorForFields ctx ctorG ci scrutTy noSpan
  pure (universes, constructorType, [(mode, quantity, ty) | (_, mode, quantity, ty) <- fields])

-- | Instantiate the complete semantic constructor spine while retaining the
-- exact term used at every binder. Constructor-field reconstruction must
-- preserve these hidden family/index/evidence arguments and replace only the
-- explicit source-field positions.
instantiateConstructorForFields
  :: Ctx
  -> GName
  -> CtorInfo
  -> Value
  -> Span
  -> CheckM
       ( [Level]
       , Term
       , [ConstructorArg]
       , [(Int, Text, ObservationMode, Q, Value)]
       , [(Int, ObservationMode, Q, Value)]
       )
instantiateConstructorForFields ctx ctorG ci scrutTy _ = do
  (universes, constructorType0) <- instantiateCtor ctorG ci
  ctype <- evalIn emptyCtx constructorType0
  (arguments0, namedBinders, fields) <- peel 0 ctype [] [] []
  constructorType <- zonkTermM 0 constructorType0
  arguments <- forM arguments0 $ \argument -> do
    term <- zonkTermM (ctxLen ctx) (caTerm argument)
    pure argument {caTerm = term}
  pure (universes, constructorType, arguments, namedBinders, fields)
  where
    peel level t arguments namedBinders fields = do
      t' <- forceM t
      case t' of
        VPiM mode icit quantity _ name domain closure -> do
          -- Every constructor placeholder has an authoritative Pi domain.
          -- Retain it so unification can enforce the placeholder's lexical
          -- creation depth and cannot solve an outer constructor argument with
          -- a branch-local pattern rigid.
          metaTerm <- freshMetaFor ctx domain
          metaValue <- evalIn ctx metaTerm
          result <- clApp closure metaValue
          ec <- ec_
          let payload =
                icit == Expl
                  || Repr.runtimeConstructorField ec level icit quantity domain
              argumentIndex = length arguments
              argument = ConstructorArg icit payload (Just name) metaTerm
              namedBinders' =
                namedBinders ++ [(argumentIndex, name, mode, quantity, domain)]
              fields' =
                if icit == Expl
                  then fields ++ [(argumentIndex, mode, quantity, domain)]
                  else fields
          peel (level + 1) result (arguments ++ [argument]) namedBinders' fields'
        result -> do
          alignConstructorResultUniverses ctx result scrutTy
          _ <- unify ctx result scrutTy
          pure (arguments, namedBinders, fields)

-- | Build a compiler-generated constructor eliminator from the same checked
-- source-field telescope used to instantiate the constructor.  This is the
-- single offset authority for synthetic projections, @is@ tests, and
-- match-and-rebuild updates: omitted implicit fields introduce hidden branch
-- slots at their declared positions, and explicit binder indices are computed
-- from that complete layout.
--
-- The constructor identity and instantiated Pi binders authenticate the
-- layout.  Any disagreement with 'ciSourceFields' reports an internal error and
-- returns 'Nothing'; callers must not guess a prefix/suffix offset.
syntheticConstructorPatternLayout
  :: Span
  -> GName
  -> [Level]
  -> CtorInfo
  -> [(Int, Text, ObservationMode, Q, Value)]
  -> [CorePat]
  -> CheckM (Maybe SyntheticConstructorPatternLayout)
syntheticConstructorPatternLayout
  site
  constructor
  universes
  info
  namedBinders
  explicitPatterns =
    case sourceBinders of
      Nothing -> invalid
      Just source ->
        case build 0 0 source explicitPatterns [] [] [] of
          Just (binderCount, hidden, patterns, positions) ->
            pure
              ( Just
                  SyntheticConstructorPatternLayout
                    { scplPattern =
                        CPCtorM [] [] hidden constructor universes patterns
                    , scplExplicitBinderIndices =
                        [ fmap (\position -> binderCount - position - 1) entry
                        | entry <- positions
                        ]
                    , scplBinderCount = binderCount
                    }
              )
          Nothing -> invalid
  where
    sourceCount = length (ciSourceFields info)
    sourceBinders
      | sourceCount > length namedBinders = Nothing
      | otherwise = do
          let suffix = drop (length namedBinders - sourceCount) namedBinders
          guard (length suffix == sourceCount)
          let source = zip (ciSourceFields info) suffix
          guard
            ( and
                [ maybe True (== binderName) sourceName
                | ((_, sourceName), (_, binderName, _, _, _)) <- source
                ]
            )
          pure source

    build
      binderOffset
      explicitPrefix
      []
      []
      hidden
      patterns
      positions =
        Just
          ( binderOffset
          , reverse hidden
          , reverse patterns
          , reverse positions
          )
    build
      binderOffset
      explicitPrefix
      (((Impl, _), (_, _, mode, _, _)) : source)
      patterns
      hidden
      builtPatterns
      positions =
        build
          (binderOffset + 1)
          explicitPrefix
          source
          patterns
          (ConstructorHiddenBinder explicitPrefix mode : hidden)
          builtPatterns
          positions
    build
      binderOffset
      explicitPrefix
      (((Expl, _), (_, _, mode, _, _)) : source)
      (pattern' : patterns)
      hidden
      builtPatterns
      positions =
        let checkedPattern = setOuterMode mode pattern'
            binderCount = patBindersC checkedPattern
            position
              | binderCount == 1 = Just binderOffset
              | otherwise = Nothing
         in build
              (binderOffset + binderCount)
              (explicitPrefix + 1)
              source
              patterns
              hidden
              (checkedPattern : builtPatterns)
              (position : positions)
    build _ _ _ _ _ _ _ = Nothing

    setOuterMode mode = \case
      CPVarM _ name -> CPVarM mode name
      CPAsM _ name pattern' -> CPAsM mode name pattern'
      pattern' -> pattern'

    invalid = do
      errAt
        site
        "E_INTERNAL_CONSTRUCTOR_TELESCOPE"
        (Just "kappa.internal.compiler")
        ( "generated constructor pattern for "
            <> gnameText constructor
            <> " does not match its checked source-field telescope"
        )
      pure Nothing

-- | A GADT constructor result and its scrutinee may intentionally disagree in
-- ordinary indices: that disagreement is the branch refinement. Their hidden
-- declaration-universe spine is still the identity of the same nominal family
-- instance and must be retained even when ordinary unification fails and rolls
-- back its tentative work. Record that independent identity first so emitted
-- constructor patterns specialize against the finalized scrutinee schema.
alignConstructorResultUniverses :: Ctx -> Value -> Value -> CheckM ()
alignConstructorResultUniverses ctx result0 scrutinee0 = do
  result <- forceM result0
  scrutinee <- forceM scrutinee0
  case (result, scrutinee) of
    (VGlobI resultFamily resultUniverses _, VGlobI scrutineeFamily scrutineeUniverses _)
      | resultFamily == scrutineeFamily
      , length resultUniverses == length scrutineeUniverses ->
          forM_ (zip resultUniverses scrutineeUniverses) $ \(resultUniverse, scrutineeUniverse) ->
            void (solveLevelIdentity ctx resultUniverse scrutineeUniverse)
    _ -> pure ()

-- | Instantiate a constructor's field types against the demanded scrutinee
-- type, and return the context EXTENDED with fresh rigid skolems for the
-- constructor's existential parameters.
--
-- §17.1 GADT unpacking: a constructor like @MkP : forall (s : Bool). Tag s -> P@
-- binds an EXISTENTIAL index @s@ — it appears in a field type (@Tag s@) but is
-- NOT pinned by the result type @P@, so unifying the result with the scrutinee
-- leaves it free. We instantiate every implicit binder with a fresh meta and
-- unify the result with the scrutinee (this SOLVES the indices that the result
-- determines, e.g. @n@ in @Vec a (S n)@ against @Vec a (S Z)@). Any implicit
-- meta that remains UNSOLVED afterwards is genuinely existential: we promote it
-- to a fresh RIGID skolem bound as a real context entry (proper de Bruijn
-- level, so the field types — and any later quote of them — stay well-scoped).
--
-- Why a rigid skolem rather than a leftover meta: the pattern variable bound at
-- @Tag s@ may be scrutinized by an INNER match whose arms would otherwise each
-- destructively solve the shared existential meta (@?s := True@ from a @TT@
-- arm), and that solution would persist into a SIBLING arm's §30.2.7
-- reachability query (@branchFiberEmpty@), making a genuinely-inhabited fiber
-- look ground-and-Empty — the existential-index @impossible@ exploit. As a
-- rigid skolem, @s@ is unsolvable, so the inner match sees @Tag s@ abstract and
-- the §30.2.7 rigid-index rule correctly reports the fiber Unknown (reachable).
-- Skolemizing ONLY the result-undetermined binders keeps the
-- determined-from-scrutinee indices solved, so ordinary GADT refinement (and the
-- ground-index no-confusion that powers exhaustiveness) is unaffected.
-- Returns the field types, the extended context, AND the observation mode of
-- every existential skolem promoted. The caller threads those modes into the
-- emitted 'CPCtorM' so Core matching accounts for the SAME number
-- of erased slots below the field binders — keeping the arm body's de Bruijn
-- indices for outer-bound variables valid during interpretation (otherwise they are
-- inflated by @nEx@ with no matching binder; see 'CPCtor').
ctorFieldTypesCtx
  :: Ctx
  -> GName
  -> CtorInfo
  -> Value
  -> Span
  -> CheckM
       ( [ConstructorSourcePatternSlot]
       , Ctx
       , [ObservationMode]
       , [ConstructorBridge]
       , [Level]
       )
ctorFieldTypesCtx ctx ctorG ci scrutTy site = do
  (universes, constructorType) <- instantiateCtor ctorG ci
  ctype <- evalIn emptyCtx constructorType
  (result, binders) <- peel ctype []
  let sourceCount = length (ciSourceFields ci)
      prefixCount = length binders - sourceCount
      (prefixBinders, sourceBinders)
        | prefixCount >= 0 = splitAt prefixCount binders
        | otherwise = ([], binders)
      implicitBinders =
        [ binder
        | binder@(Impl, _, _, _, _, _, _, _) <- binders
        ]
  planningBefore <- gets csApplicationPlanningMetas
  modify' $ \state ->
    state
      { csApplicationPlanningMetas =
          Set.union
            planningBefore
            (Set.fromList [meta | (_, meta, _, _, _, _, _, _) <- implicitBinders])
      }
  _ <- prepareNominalResultForCheckedApplication ctx result scrutTy
  modify' $ \state ->
    state {csApplicationPlanningMetas = planningBefore}
  alignConstructorResultUniverses ctx result scrutTy
  (forcedEqualities, definitionallyCompatible) <-
    alignConstructorResultIndices ctx result scrutTy
  -- Constructor parameters that result alignment did not solve are
  -- existential to this pattern branch, including indices that occur in the
  -- result only through a non-invertible refinement such as @k + 1 = m@.
  -- Classifying by source occurrence alone leaves such parameters as flexible
  -- metas shared by sibling arms. Classifying after alignment instead keeps
  -- parameters determined by the scrutinee solved while promoting every
  -- genuinely branch-local remainder to a rigid skolem.
  metasAfterAlignment <- gets csMetas
  let remainsUnsolved (meta, _, _, _, _) =
        case Map.lookup meta metasAfterAlignment of
          -- Symmetric unification may represent a determined equality by
          -- solving an older demanded meta to this fresh constructor meta.
          -- Such a placeholder is semantically part of the scrutinee and must
          -- not become a branch-local skolem. Only an unsolved placeholder
          -- unreachable from the demanded type is genuinely existential.
          Just Nothing ->
            not (metaOccursInValue metasAfterAlignment meta scrutTy)
          _ -> False
      prefixImplicitMetas =
        [ (meta, mode, quantity, domain, assumption)
        | (Impl, meta, mode, quantity, domain, assumption, _, _) <-
            prefixBinders
        ]
      existentialMetas = filter remainsUnsolved prefixImplicitMetas
  ctx' <- foldM promoteExistential ctx existentialMetas
  refinements <- forM forcedEqualities $ \(left, right) ->
    ConstructorForcedEquality
      <$> quoteIn ctx' left
      <*> quoteIn ctx' right
  propositionalBridges <-
    if definitionallyCompatible
      then pure []
      else
        constructorPropositionalBridge ctx' result scrutTy >>= \case
          Just bridge -> pure [bridge]
          -- Failure to find a bridge is UnknownCompatibility (§30.2.7), not a
          -- refutation and not a source rejection. Keep the branch without
          -- conversion facts or lexical bridge evidence; reachability and the
          -- branch body must then justify any stronger claim independently.
          Nothing -> pure []
  ctx'' <- foldM bindPropositionalBridge ctx' propositionalBridges
  sourceSlots <-
    if prefixCount < 0
      || length sourceBinders /= sourceCount
      || map firstIcit sourceBinders /= map fst (ciSourceFields ci)
      then do
        errAt
          site
          "E_INTERNAL_CONSTRUCTOR_TELESCOPE"
          (Just "kappa.internal.compiler")
          "constructor source-field metadata does not match its finalized telescope"
        pure []
      else pure (map sourceSlot sourceBinders)
  assignments <- gets csLevelAssignments
  let universes' = map (normalizeLevel . substituteLevelMetas assignments) universes
  pure
    ( sourceSlots
    , ctx''
    , [mode | (_, mode, _, _, _) <- existentialMetas]
    , refinements ++ propositionalBridges
    , universes'
    )
  where
    -- Bind a fresh rigid skolem for a genuinely existential implicit param and
    -- solve its meta to that skolem (so field types mentioning it force to the
    -- rigid variable). Threads the extended context.
    promoteExistential cx (m, mode, q, dom, assumption) = do
      let level = ctxLen cx
          skol = VRigid level []
      extended <-
        extendLevelAssumption
          noSpan
          (bindCtxMQ mode q "_ex" False dom cx)
          assumption
      classifierTerm <- quoteIn extended dom
      modify' $ \state ->
        state
          { csMetaClassifiers =
              Map.adjust
                (\classifier ->
                   classifier
                     { micDepth = ctxLen extended
                     , micType = classifierTerm
                     })
                m
                (csMetaClassifiers state)
          }
      solveMeta m skol
      pure extended
    freshInstantiationMeta domain = do
      (meta, term) <- freshMetaForWithId ctx domain
      levelField <- isTypeLevelValue domain
      value <-
        if levelField
          then pure (VLevel (LMeta meta))
          else evalIn ctx term
      pure
        ( meta
        , value
        , if levelField
            then ConstructorLevelWitness meta
            else ConstructorTermWitness meta
        )
    firstIcit (icit, _, _, _, _, _, _, _) = icit
    sourceSlot = \case
      ( Expl
        , _
        , mode
        , quantity
        , domain
        , _
        , witness
        , dependent
        ) ->
          ConstructorExplicitPatternSlot
            mode
            quantity
            domain
            ( case witness of
                -- A first-class level field has one identity in both the term
                -- and level languages. Its branch binder must own that identity
                -- even when no later constructor field mentions it: the branch
                -- body can still use the field directly as a universe argument.
                ConstructorLevelWitness _ -> Just witness
                ConstructorTermWitness _
                  | dependent -> Just witness
                  | otherwise -> Nothing
            )
      ( Impl
        , _
        , mode
        , quantity
        , domain
        , assumption
        , witness
        , _
        ) ->
          ConstructorHiddenPatternSlot
            mode
            quantity
            domain
            witness
            assumption
    bindPropositionalBridge cx = \case
      ConstructorPropositionalBridge bridgeType _ -> do
        bridgeTypeValue <- evalIn cx bridgeType
        -- A constructor bridge is ordinary erased equality evidence. Its
        -- certificate is checked before this binder is introduced; consumers
        -- may therefore use it exactly like source-written @0 proof evidence
        -- without enlarging definitional equality.
        pure (bindCtxMQ Ordinary Q0 "__bridge" True bridgeTypeValue cx)
      ConstructorForcedEquality {} -> pure cx
    peel t acc = do
      t' <- forceM t
      case t' of
        VPiBoundM mode icit q _ _ assumption dom clo -> do
          (m, mv, witness) <- freshInstantiationMeta dom
          r <- clApp clo mv
          metas <- gets csMetas
          let dependent = metaOccursInValue metas m r
          peel
            r
            ( acc
                ++ [ ( icit
                     , m
                     , mode
                     , q
                     , dom
                     , assumption
                     , witness
                     , dependent
                     )
                   ]
            )
        result -> pure (result, acc)

-- | Orient a residual definitional equation toward an acyclic branch-local
-- rigid substitution. Either source direction may expose the rigid.
orientRigidRefinement
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe (Int, Value))
orientRigidRefinement ctx left0 right0 = do
  left <- forceM left0
  right <- forceM right0
  rightToLeft <- directedRigidRefinement ctx right left
  case rightToLeft of
    Just refinement -> pure (Just refinement)
    Nothing -> directedRigidRefinement ctx left right

directedRigidRefinement
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe (Int, Value))
directedRigidRefinement ctx candidate0 replacement0 = do
  candidate <- forceM candidate0
  replacement <- forceM replacement0
  ec <- ec_
  pure (orient ec candidate replacement)
  where
    orient ec (VRigid rigid []) replacement
      | rigid < ctxLen ctx
      , not (rigidOccurs ec rigid replacement) =
          Just (rigid, replacement)
    orient _ _ _ = Nothing

    rigidOccurs ec rigid value =
      let depth = ctxLen ctx
          index = depth - rigid - 1
       in index >= 0 && mentionsVar index (quote ec depth value)

-- | Recover the root constructor's checked definitional equations at the
-- final pattern context depth.  Propositional bridges remain lexical proof
-- binders and never become conversion facts; only equations already certified
-- as 'ConstructorForcedEquality' may orient a rigid variable.
rootConstructorForcedRefinements
  :: Ctx
  -> CorePat
  -> CheckM (Map Int RigidFact)
rootConstructorForcedRefinements ctx = \case
  CPCtorM _ bridges _ _ _ _ ->
    foldM addBridge Map.empty bridges
  _ -> pure Map.empty
  where
    addBridge refinements = \case
      ConstructorForcedEquality leftTerm rightTerm -> do
        left <- evalIn ctx leftTerm
        right <- evalIn ctx rightTerm
        directedRigidRefinement ctx left right >>= \case
          Nothing -> pure refinements
          Just (rigid, replacement) ->
            pure (Map.insert rigid (FactIs replacement) refinements)
      ConstructorPropositionalBridge {} -> pure refinements

-- | Align one constructor result with the demanded family instance from left
-- to right. Successful unification solves ordinary constructor parameters.
-- A remaining equation is admitted as an active constructor-index equality
-- only when one side is a branch-local rigid and the other side does not
-- contain it. This is the generic dependent-constructor rule: the standard
-- equality type receives no special treatment, and a user-defined
-- @Equal a b@ / @Refl@ declaration has the same behavior.
--
-- The facts are installed only while deriving later equations. The caller
-- serializes the dependency-ordered equations into the Core pattern and
-- restores the surrounding fact table before returning.
alignConstructorResultIndices
  :: Ctx
  -> Value
  -> Value
  -> CheckM ([(Value, Value)], Bool)
alignConstructorResultIndices ctx result0 demanded0 = do
  result <- forceM result0
  demanded <- forceM demanded0
  ec <- ec_
  case (result, demanded) of
    (VGlobI resultFamily resultUniverses resultArguments, VGlobI demandedFamily demandedUniverses demandedArguments)
      | resultFamily == demandedFamily
      , length resultUniverses == length demandedUniverses
      , Just pairs <-
          globalSpineRelevantPairs
            ec
            resultFamily
            resultArguments
            demandedArguments ->
          alignPairs pairs
    _ -> do
      aligned <- unify ctx result demanded
      pure ([], aligned)
  where
    alignPairs [] = pure ([], True)
    alignPairs ((resultArgument, demandedArgument) : rest) = do
      (here, hereAligned) <- alignValue resultArgument demandedArgument
      (later, laterAligned) <- alignPairs rest
      pure (here ++ later, hereAligned && laterAligned)

    alignValue left0 right0 = do
      saved <- get
      unified <- unify ctx left0 right0
      if unified
        then pure ([], True)
        else do
          put saved
          left <- forceM left0
          right <- forceM right0
          orientRigidRefinement ctx left right >>= \case
            Just (rigid, replacement) -> do
              modify' $ \state ->
                state
                  { csFacts =
                      Map.insert rigid (FactIs replacement) (csFacts state)
                  }
              pure ([(VRigid rigid [], replacement)], True)
            Nothing -> do
              structured <- alignStructured left right
              unless (snd structured) (put saved)
              pure structured

    alignStructured left right = do
      ec <- ec_
      dataFamilies <- gets csDatas
      case (left, right) of
        (VGlobI leftGlobal leftUniverses leftArguments, VGlobI rightGlobal rightUniverses rightArguments)
          | leftGlobal == rightGlobal
          , Map.member leftGlobal dataFamilies
          , leftUniverses == rightUniverses
          , Just pairs <-
              globalSpineRelevantPairs
                ec
                leftGlobal
                leftArguments
                rightArguments ->
              alignPairs pairs
        (VCtorI leftConstructor leftUniverses leftArguments, VCtorI rightConstructor rightUniverses rightArguments)
          | leftConstructor == rightConstructor
          , leftUniverses == rightUniverses
          , length leftArguments == length rightArguments ->
              alignPairs
                [ (cvaValue leftArgument, cvaValue rightArgument)
                | (leftArgument, rightArgument) <-
                    zip leftArguments rightArguments
                ]
        (VCtor leftConstructor leftArguments, VCtor rightConstructor rightArguments)
          | leftConstructor == rightConstructor
          , length leftArguments == length rightArguments ->
              alignPairs (zip leftArguments rightArguments)
        _ -> pure ([], False)

-- | Build the portable-v1 fallback after definitional constructor-result
-- alignment fails: one explicit equality bridge between corresponding
-- arguments of the same nominal family. The shared index-difference query
-- supplies the checked carrier; ordinary proposition search supplies and
-- records the selected arithmetic provider/certificate. The resulting proof
-- is a lexical erased binder and never enters 'csFacts'.
constructorPropositionalBridge
  :: Ctx
  -> Value
  -> Value
  -> CheckM (Maybe ConstructorBridge)
constructorPropositionalBridge ctx result demanded =
  singleNominalIndexDifference ctx result demanded >>= \case
    Nothing -> pure Nothing
    Just (carrier, lhs, rhs, _, _) -> do
      equality <-
        globalValueM
          prelEqType
          [(Impl, carrier), (Expl, lhs), (Expl, rhs)]
      equalityTerm <- quoteIn ctx equality >>= zonkTermM (ctxLen ctx)
      propProofTerm ctx equalityTerm equality >>= \case
        Nothing -> pure Nothing
        Just proof ->
          pure
            ( Just
                (ConstructorPropositionalBridge equalityTerm proof)
            )

-- ── try / do ─────────────────────────────────────────────────────────

ioTypeM :: Value -> Value -> CheckM Value
ioTypeM e a = globalValueM prelIO [(Expl, e), (Expl, a)]

monadResultType :: Value -> Value -> Maybe Value
monadResultType mTy a = case mTy of
  VGlobI g universes args ->
    Just (VGlobI g universes (args ++ [(Expl, a)]))
  VFlex m args -> Just (VFlex m (args ++ [(Expl, a)]))
  VRigid l args -> Just (VRigid l (args ++ [(Expl, a)]))
  _ -> Nothing

-- | Decompose one already-forced application of a first-order monad carrier.
-- The carrier retains its complete checked prefix (including generated
-- universe and evidence arguments); only the final explicit result argument
-- is removed. This is the inverse of 'monadResultType'.
monadActionViewValue :: Value -> Maybe (Value, Value)
monadActionViewValue = \case
  VGlobI g universes args
    | Just (pre, (Expl, a)) <- unsnoc args ->
        Just (VGlobI g universes pre, a)
  VFlex m args
    | Just (pre, (Expl, a)) <- unsnoc args ->
        Just (VFlex m pre, a)
  VRigid l args
    | Just (pre, (Expl, a)) <- unsnoc args ->
        Just (VRigid l pre, a)
  _ -> Nothing
  where
    unsnoc [] = Nothing
    unsnoc [x] = Just ([], x)
    unsnoc (x : xs) = do
      (pre, lastArg) <- unsnoc xs
      Just (x : pre, lastArg)

monadActionView :: Value -> CheckM (Maybe (Value, Value))
monadActionView ty0 = do
  ty <- forceM ty0
  pure (monadActionViewValue ty)

requireMonadRef :: Ctx -> Span -> Value -> CheckM Term
requireMonadRef ctx sp mTyV = do
  obligation <- globalValueM prelMonadRef [(Expl, mTyV)]
  resolveImplicit ctx sp obligation

monadRefRefType :: Ctx -> Term -> Term -> CheckM Value
monadRefRefType ctx dictTm aTm = do
  mode <- traitMemberObservationMode prelMonadRef "Ref"
  evalIn ctx (CApp Expl (CProjM mode dictTm "Ref") aTm)

-- | Source-facing associated-cell type for mutable-binding diagnostics.
-- Type checking retains the exact selected dictionary projection above;
-- diagnostics name the authenticated public MonadRef associated member so
-- payloads remain stable across evidence-local projection binders.
monadRefDiagnosticRefType :: Value -> Value
monadRefDiagnosticRefType storedType =
  VGlobN prelRef [(Expl, storedType)]

-- | Read a selected trait member's checked observation mode from the trait
-- declaration. Generated dictionary projections must use the same structural
-- fact as source projections; defaulting a kind-valued member to 'Ordinary'
-- would manufacture a promotion error at the finalized-Core checkpoint.
traitMemberObservationMode :: GName -> Text -> CheckM ObservationMode
traitMemberObservationMode trait member = do
  traits <- gets csTraits
  pure $ fromMaybe Ordinary $ do
    info <- Map.lookup trait traits
    Map.lookup member (tiMemberModes info)

monadRefNewAction :: Term -> Term -> Term -> Term
monadRefNewAction dictTm aTm initTm =
  CApp Expl (CApp Impl (CProjM Ordinary dictTm "newRef") aTm) initTm

monadRefReadAction :: Term -> Term -> Term -> Term
monadRefReadAction dictTm aTm refTm =
  CApp Expl (CApp Impl (CProjM Ordinary dictTm "readRef") aTm) refTm

monadRefWriteAction :: Term -> Term -> Term -> Term -> Term
monadRefWriteAction dictTm aTm refTm rhsTm =
  CApp Expl (CApp Expl (CApp Impl (CProjM Ordinary dictTm "writeRef") aTm) refTm) rhsTm

freshRefCellId :: CheckM RefCellId
freshRefCellId = do
  n <- gets csNextRefCellId
  modify' $ \st -> st {csNextRefCellId = n + 1}
  pure (RefCellId n)

termHeadGlob :: Term -> Maybe GName
termHeadGlob = \case
  CApp _ f _ -> termHeadGlob f
  CUniverseLift _ _ _ term -> termHeadGlob term
  CGlob g -> Just g
  CGlobal g _ -> Just g
  CCtor g _ [] -> Just g
  CCtorI g _ _ [] -> Just g
  _ -> Nothing

-- | Recover a resolved declaration identity through the eta-expanded Core
-- representation used for constructors and generated accessors. This is
-- intentionally distinct from 'termHeadGlob': expected-type planning needs
-- the semantic owner even after binders or checked arguments have been
-- recorded around the global head.
resolvedEtaTermHead :: Term -> Maybe GName
resolvedEtaTermHead = \case
  CLamM _ _ _ _ body -> resolvedEtaTermHead body
  CApp _ function _ -> resolvedEtaTermHead function
  CUniverseLift _ _ _ term -> resolvedEtaTermHead term
  CGlob global -> Just global
  CGlobal global _ -> Just global
  CCtor constructor _ _ -> Just constructor
  CCtorI constructor _ _ _ -> Just constructor
  _ -> Nothing

isIOCarrierValue :: Value -> CheckM Bool
isIOCarrierValue mTy0 = do
  mTy <- forceM mTy0
  pure $ case mTy of
    VGlobI g _ [(Expl, _)] -> g == prelIO
    _ -> False

isIOMonadRefInstance :: InstanceEntry -> Bool
isIOMonadRefInstance ie =
  ieTrait ie == prelMonadRef
    && case ieDict ie of
      GName mn _ | mn == preludeModule -> case ieHead ie of
        [carrier] -> termHeadGlob carrier == Just prelIO
        _ -> False
      _ -> False

builtinIOMonadRefLowering :: Ctx -> Value -> Term -> CheckM (Maybe RefLoweringWitness)
builtinIOMonadRefLowering _ctx mTy dictTm = do
  isIO <- isIOCarrierValue mTy
  insts <- gets csInstances
  case termHeadGlob dictTm of
    Just dictG
      | isIO
      , any (\ie -> ieDict ie == dictG && isIOMonadRefInstance ie) insts -> do
          Just . BuiltinIORefWitness <$> freshRefCellId
    _ -> pure Nothing

refReadWitnessFromInfo :: VarRefInfo -> Maybe RefActionWitness
refReadWitnessFromInfo info = BuiltinIORefRead <$> vriLoweringWitness info

refWriteWitnessFromInfo :: VarRefInfo -> Maybe RefActionWitness
refWriteWitnessFromInfo info = BuiltinIORefWrite <$> vriLoweringWitness info

data ExplicitRefOp = ExplicitRefRead | ExplicitRefWrite
  deriving (Eq)

data RefOpEvidence = RefOpBare | RefOpCarrier Term | RefOpDict Term

refOpOfTerm :: Ctx -> Term -> CheckM (Maybe (ExplicitRefOp, RefOpEvidence))
refOpOfTerm ctx term =
  case spineOfTerm (stripIdentityWrappers term) of
    (CGlobal global _, arguments)
      | Just operation <- refOperationGlobal global -> do
          definitions <- gets csGlobals
          ec <- ec_
          pure $ do
            definition <- Map.lookup global definitions
            let memberType = globalCoreType ec definition
            let evidence =
                  case selectedMonadRefDictionary memberType arguments of
                    Just dictionary -> RefOpDict dictionary
                    Nothing ->
                      case sourceArgumentsOf memberType arguments of
                        Just [] -> RefOpBare
                        Just [carrier] -> RefOpCarrier carrier
                        _ -> RefOpBare
            pure (operation, evidence)
    (CProjM _ dictionary member, _arguments)
      | Just operation <- refOperationMember member -> do
          dictionaryType <- knownRefEvidenceType ctx dictionary
          case dictionaryType of
            Nothing -> pure Nothing
            Just ty -> do
              ty' <- forceM ty
              pure $ case ty' of
                VGlobI trait _ _ | trait == prelMonadRef ->
                  Just (operation, RefOpDict dictionary)
                _ -> Nothing
    _ -> pure Nothing
  where
    -- Recognition is by the exact selected declaration identity. A record or
    -- unrelated trait field that merely happens to be named readRef/writeRef
    -- is not a MonadRef operation.
    refOperationGlobal global
      | global == prelReadRef
          || global == memberGlobal prelMonadRef "readRef" =
          Just ExplicitRefRead
      | global == prelWriteRef
          || global == memberGlobal prelMonadRef "writeRef" =
          Just ExplicitRefWrite
      | otherwise = Nothing

    refOperationMember = \case
      "readRef" -> Just ExplicitRefRead
      "writeRef" -> Just ExplicitRefWrite
      _ -> Nothing

    -- A projected method is recognized only from a receiver whose checked
    -- type is the canonical MonadRef trait application. The source field
    -- spelling alone is never semantic authority: an unrelated record or
    -- trait member named readRef/writeRef therefore remains ordinary code.
    knownRefEvidenceType current = \case
      CVar index ->
        pure (ceType <$> indexMaybe index (ctxEntries current))
      CGlobal global universes -> do
        definitions <- gets csGlobals
        case Map.lookup global definitions of
          Nothing -> pure Nothing
          Just definition -> do
            (_, ty) <- specializeGlobalAt current global definition universes
            pure (Just ty)
      CUniverseLift _ _ _ inner -> knownRefEvidenceType current inner
      CSchemaLift _ _ _ _ _ _ _ _ inner -> knownRefEvidenceType current inner
      _ -> pure Nothing

    indexMaybe index entries =
      case drop index entries of
        entry : _ -> Just entry
        [] -> Nothing

    -- Align the checked application with its typed declaration telescope.
    -- Generated declaration-universe proof binders are authenticated by
    -- BinderGenerated and do not occupy semantic member-prefix positions.
    -- The remaining source binders begin with MonadRef's carrier and selected
    -- dictionary, followed by the member's own parameters.
    sourceArgumentsOf typeTerm = go typeTerm []
      where
        go _ collected [] = Just (reverse collected)
        go (CPiEvidenceM _ _ expectedIcit _ _ _ _ origin _ codomain)
            collected ((actualIcit, argument) : rest)
          | expectedIcit == actualIcit =
              go codomain
                (if origin == BinderGenerated then collected else argument : collected)
                rest
        go _ _ _ = Nothing

    -- Select evidence by the checked member telescope, never by a positional
    -- guess. MonadRef members may carry other evidence (notably Monad m)
    -- before the selected MonadRef m dictionary. Each supplied argument is
    -- substituted through the dependent codomain so the next binder domain is
    -- inspected at the exact occurrence instantiation.
    selectedMonadRefDictionary = go
      where
        go _ [] = Nothing
        go
          (CPiEvidenceM _ _ expectedIcit _ _ _ _ _ domain codomain)
          ((actualIcit, argument) : rest)
          | expectedIcit == actualIcit =
              if termHeadGlob (stripIdentityWrappers domain) == Just prelMonadRef
                then Just argument
                else go (substTopTermAt 0 argument codomain) rest
        go _ _ = Nothing

termMatchesValue :: Ctx -> Term -> Value -> CheckM Bool
termMatchesValue ctx actual0 expected0 = do
  actualV <- forceM =<< evalIn ctx actual0
  expectedV <- forceM expected0
  -- Carrier/dictionary recognition is a typed conversion judgment, not a
  -- source-shape comparison. In particular, an explicit occurrence may carry
  -- fresh declaration-universe levels and verified lifts which must be
  -- related to the mutable cell's selected evidence before principalization.
  unify ctx actualV expectedV

termMatchesTerm :: Ctx -> Term -> Term -> CheckM Bool
termMatchesTerm ctx actual0 expected0 = do
  actual <- zonkTermM (ctxLen ctx) actual0
  expected <- zonkTermM (ctxLen ctx) expected0
  go actual expected
  where
    go actual expected
      | actual == expected = pure True
      | otherwise =
        case matchingResolvedApplications actual expected of
          Just argumentPairs ->
            and <$> mapM (uncurry go) argumentPairs
          Nothing -> do
            expectedV <- forceM =<< evalIn ctx expected
            termMatchesValue ctx actual expectedV
    matchingResolvedApplications actual expected =
      let (actualHead, actualArguments) =
            spineOfTerm (stripIdentityWrappers actual)
          (expectedHead, expectedArguments) =
            spineOfTerm (stripIdentityWrappers expected)
       in case (actualHead, expectedHead) of
            (CGlobal actualGlobal actualUniverses, CGlobal expectedGlobal expectedUniverses)
              | actualGlobal == expectedGlobal
              , map normalizeLevel actualUniverses == map normalizeLevel expectedUniverses
              , map fst actualArguments == map fst expectedArguments
              , length actualArguments == length expectedArguments ->
                  Just (zip (map snd actualArguments) (map snd expectedArguments))
            _ -> Nothing

refEvidenceMatchesCarrierDict :: Ctx -> Value -> Term -> RefOpEvidence -> CheckM Bool
refEvidenceMatchesCarrierDict ctx expectedCarrier expectedDict = \case
  RefOpBare -> pure True
  RefOpCarrier actualCarrier -> do
    carrierMatches <- termMatchesValue ctx actualCarrier expectedCarrier
    if carrierMatches
      then pure True
      else do
        -- A reducible carrier alias may preserve the selected MonadRef
        -- dictionary even when direct carrier conversion is temporarily
        -- blocked by occurrence-local universe evidence. Dictionary identity
        -- is the stronger, coherence-checked proof needed by this lowering:
        -- synthesize evidence for the explicit carrier and require it to be
        -- convertible to the mutable binding's already selected evidence.
        actualCarrierValue <- forceM =<< evalIn ctx actualCarrier
        actualGoal <- globalValueM prelMonadRef [(Expl, actualCarrierValue)]
        actualDict <- resolveImplicit ctx noSpan actualGoal
        termMatchesTerm ctx actualDict expectedDict
  RefOpDict actualDict -> termMatchesTerm ctx actualDict expectedDict

checkedMonadRefMethodApp :: Ctx -> Expr -> [Arg] -> Value -> Span -> CheckM (Maybe Term)
checkedMonadRefMethodApp ctx f args expected sp = do
  st0 <- get
  result <-
    case ordinaryRefReadArgs args of
      Just (headArgs, refE) -> do
        mop <- resolveRefOpExpr ctx f headArgs
        case mop of
          Just (ExplicitRefRead, ev) -> checkedRead ev refE
          _ -> pure Nothing
      Nothing ->
        case ordinaryRefWriteArgs args of
          Just (headArgs, refE, rhsE) -> do
            mop <- resolveRefOpExpr ctx f headArgs
            case mop of
              Just (ExplicitRefWrite, ev) -> checkedWrite ev refE rhsE
              _ -> pure Nothing
          Nothing -> pure Nothing
  case result of
    Just term -> pure (Just term)
    Nothing -> put st0 >> pure Nothing
  where
    checkedRead ev refE = do
      monadActionView expected >>= \case
        Just (mTy, aTy) -> do
          refDict <- requireMonadRef ctx sp mTy
          matches <- refEvidenceMatchesCarrierDict ctx mTy refDict ev
          if not matches
            then pure Nothing
            else do
              aTm <- quoteIn ctx aTy
              refTy <- monadRefRefType ctx refDict aTm
              refTm <- check ctx refE refTy
              pure (Just (monadRefReadAction refDict aTm refTm))
        Nothing -> pure Nothing
    checkedWrite ev refE rhsE = do
      monadActionView expected >>= \case
        Just (mTy, resultTy) -> do
          unitT <- globalValueM prelUnit []
          unitOk <- unify ctx resultTy unitT
          if not unitOk
            then pure Nothing
            else do
              refDict <- requireMonadRef ctx sp mTy
              matches <- refEvidenceMatchesCarrierDict ctx mTy refDict ev
              if not matches
                then pure Nothing
                else do
                  aTm <- freshMeta
                  aTy <- evalIn ctx aTm
                  refTy <- monadRefRefType ctx refDict aTm
                  refTm <- check ctx refE refTy
                  rhsTm <- check ctx rhsE aTy
                  pure (Just (monadRefWriteAction refDict aTm refTm rhsTm))
        Nothing -> pure Nothing

checkedMonadRefExpr :: Ctx -> Expr -> Value -> CheckM (Maybe Term)
checkedMonadRefExpr ctx expr expected = case expr of
  EAscription e _ _ -> checkedMonadRefExpr ctx e expected
  EApp f args -> checkedMonadRefMethodApp ctx f args expected (exprSpan expr)
  _ -> pure Nothing

ordinaryRefReadArgs :: [Arg] -> Maybe ([Arg], Expr)
ordinaryRefReadArgs = go []
  where
    go prefix = \case
      ArgImplicit e : rest -> go (prefix ++ [ArgImplicit e]) rest
      [ArgExplicit e]
        | Nothing <- refFacetExpr e -> Just (prefix, e)
      _ -> Nothing

ordinaryRefWriteArgs :: [Arg] -> Maybe ([Arg], Expr, Expr)
ordinaryRefWriteArgs = go []
  where
    go prefix = \case
      ArgImplicit e : rest -> go (prefix ++ [ArgImplicit e]) rest
      [ArgExplicit refE, ArgExplicit rhsE]
        | Nothing <- refFacetExpr refE -> Just (prefix, refE, rhsE)
      _ -> Nothing

refFacetExpr :: Expr -> Maybe (Name, Span)
refFacetExpr = \case
  ERefFacet n sp -> Just (n, sp)
  EAscription e _ _ -> refFacetExpr e
  _ -> Nothing

refFacetReadArgs :: [Arg] -> Maybe ([Arg], Name, Span)
refFacetReadArgs = go []
  where
    go prefix = \case
      ArgImplicit e : rest -> go (prefix ++ [ArgImplicit e]) rest
      [ArgExplicit e]
        | Just (n, sp) <- refFacetExpr e -> Just (prefix, n, sp)
      _ -> Nothing

refFacetWriteArgsWithHead :: [Arg] -> Maybe ([Arg], Name, Expr, Span)
refFacetWriteArgsWithHead = go []
  where
    go prefix = \case
      ArgImplicit e : rest -> go (prefix ++ [ArgImplicit e]) rest
      [ArgExplicit refE, ArgExplicit rhs]
        | Just (n, sp) <- refFacetExpr refE -> Just (prefix, n, rhs, sp)
      _ -> Nothing

explicitRefFacetApp :: Ctx -> Expr -> [Arg] -> CheckM (Maybe (Term, Value))
explicitRefFacetApp ctx f args = do
  st0 <- get
  result <- case (refFacetReadArgs args, refFacetWriteArgsWithHead args) of
    (Just (headArgs, n, sp), _) -> do
      mop <- resolveRefOpExpr ctx f headArgs
      case mop of
        Just (ExplicitRefRead, ev) ->
          withVar n sp ev $ \_i info refDict aTm refTm -> do
            case monadResultType (vriMonadType info) (vriStoredType info) of
              Just actionTy -> do
                recordRecognizedRefOp sp "readRef"
                pure (Just (monadRefReadAction refDict aTm refTm, actionTy))
              Nothing -> unsupportedRefFacet ctx n sp
        _ -> pure Nothing
    (_, Just (headArgs, n, rhs, sp)) -> do
      mop <- resolveRefOpExpr ctx f headArgs
      case mop of
        Just (ExplicitRefWrite, ev) ->
          withVar n sp ev $ \_i info refDict aTm refTm -> do
            rhsTm <- check ctx rhs (vriStoredType info)
            unitT <- globalValueM prelUnit []
            case monadResultType (vriMonadType info) unitT of
              Just actionTy -> do
                recordRecognizedRefOp sp "writeRef"
                pure (Just (monadRefWriteAction refDict aTm refTm rhsTm, actionTy))
              Nothing -> unsupportedRefFacet ctx n sp
        _ -> pure Nothing
    _ -> pure Nothing
  case result of
    Just checked -> pure (Just checked)
    Nothing -> put st0 >> pure Nothing
  where
    withVar n _facetSp ev k =
      case lookupCtx (nameText n) ctx of
        Just (i, entry)
          | Just info <- ceVarInfo entry -> do
              let evidenceShift = i + 1
                  refDict = shiftTerm evidenceShift 0 (vriMonadRefDict info)
                  aTm = shiftTerm evidenceShift 0 (vriStoredTypeTerm info)
                  refTm = CVar i
              matches <- refEvidenceMatchesCarrierDict ctx (vriMonadType info) refDict ev
              if matches
                then k i info refDict aTm refTm
                else pure Nothing
        _ -> pure Nothing

recognizedRefReadRoot :: Ctx -> Expr -> CheckM (Maybe Text)
recognizedRefReadRoot ctx = \case
  EVarRead n _ -> pure (varCurrentRootOf ctx (nameText n))
  EAscription e _ _ -> recognizedRefReadRoot ctx e
  EApp f args
    | Just (headArgs, n, _) <- refFacetReadArgs args -> do
        ok <- resolvedRefOpMatchesMutable ctx f headArgs ExplicitRefRead n
        pure (if ok then varCurrentRootOf ctx (nameText n) else Nothing)
  _ -> pure Nothing

refReadWitnessOfExpr :: Ctx -> Expr -> CheckM (Maybe RefActionWitness)
refReadWitnessOfExpr ctx = \case
  EVarRead n _ -> pure (witnessFor n)
  EAscription e _ _ -> refReadWitnessOfExpr ctx e
  EApp f args
    | Just (headArgs, n, _) <- refFacetReadArgs args -> do
        ok <- resolvedRefOpMatchesMutable ctx f headArgs ExplicitRefRead n
        pure (if ok then witnessFor n else Nothing)
  _ -> pure Nothing
  where
    witnessFor n =
      case lookupCtx (nameText n) ctx of
        Just (_, entry)
          | Just info <- ceVarInfo entry -> refReadWitnessFromInfo info
        _ -> Nothing

recognizedRefWriteName :: Ctx -> Expr -> CheckM (Maybe Text)
recognizedRefWriteName ctx = \case
  EAscription e _ _ -> recognizedRefWriteName ctx e
  EApp f args
    | Just (headArgs, n, _, _) <- refFacetWriteArgsWithHead args -> do
        ok <- resolvedRefOpMatchesMutable ctx f headArgs ExplicitRefWrite n
        pure (if ok then Just (nameText n) else Nothing)
  _ -> pure Nothing

writtenRefFacetsExecutedExpr :: Ctx -> Expr -> CheckM (Set Text)
writtenRefFacetsExecutedExpr ctx expr = do
  base <- writtenRefWritesInExecutedExpr ctx expr
  multi <- multishotOpExecutedExpr ctx expr
  pure $
    if multi
      then Set.union base (Map.keysSet (ctxVarCurrentVersions ctx))
      else base

writtenRefWritesInExecutedExpr :: Ctx -> Expr -> CheckM (Set Text)
writtenRefWritesInExecutedExpr ctx = go
  where
    unionsM = fmap Set.unions . sequence
    goLet (LetBind {}) = pure Set.empty
    goCase = \case
      MatchCase _ mg body _ -> unionsM [maybe (pure Set.empty) go mg, go body]
      MatchImpossible {} -> pure Set.empty
    goExcept (ExceptCase _ mg body _) = unionsM [maybe (pure Set.empty) go mg, go body]
    goHandler = \case
      HandlerReturn _ body _ -> go body
      HandlerOp _ _ _ body _ -> go body
    goDecl = \case
      DTopSplice e _ -> go e
      DUnsafeAssert _ inner _ -> goDecl inner
      _ -> pure Set.empty
    go = \case
      EAscription e _ _ -> go e
      EBang _ e _ -> go e
      EDo _ items _ -> doItemsVarWrites ctx items
      EIf alts mels _ -> do
        condWrites <- unionsM [go cond | (cond, _) <- alts]
        branchWrites <- unionsM [go body | (_, body) <- alts]
        elseWrites <- maybe (pure Set.empty) go mels
        pure (Set.unions [condWrites, branchWrites, elseWrites])
      EMatch scrut cases _ ->
        unionsM (go scrut : map goCase cases)
      ETry scrut excepts mfin _ ->
        unionsM (go scrut : map goExcept excepts ++ [maybe (pure Set.empty) go mfin])
      ETryMatch scrut cases excepts mfin _ ->
        unionsM (go scrut : map goCase cases ++ map goExcept excepts ++ [maybe (pure Set.empty) go mfin])
      EHandle _ _ scrut cases _ ->
        unionsM (go scrut : map goHandler cases)
      ELet binds body _ ->
        unionsM (map goLet binds ++ [go body])
      EBlock decls mres _ ->
        unionsM (map goDecl decls ++ [maybe (pure Set.empty) go mres])
      e -> maybe Set.empty Set.singleton <$> recognizedRefWriteName ctx e

applyVarCurrentEffects :: Set Text -> Set Text -> Ctx -> Ctx
applyVarCurrentEffects writes escapes ctx =
  foldr escapeVarCurrent
    (foldr invalidateVarCurrent ctx (Set.toList writes))
    (Set.toList escapes)

-- | §18.6.2 current-value facts do not survive an operation site whose
-- declared resumption quantity permits multi-shot reuse. Recognition consumes
-- checker-recorded spans produced by resolved effect-label identity and
-- operation metadata, not by rediscovering @label.op@ source spelling.
multishotOpExecutedExpr :: Ctx -> Expr -> CheckM Bool
multishotOpExecutedExpr _ctx expr = do
  ops <- gets csRecognizedMultishotOps
  pure (recognizedMultishotInExpr ops expr)

recognizedMultishotInExpr :: Map Span (GName, Text) -> Expr -> Bool
recognizedMultishotInExpr ops = go
  where
    hit sp = Map.member sp ops
    hitMember = \case
      DotName op -> hit (nameSpan op)
      DotOperator op -> hit (nameSpan op)
    anyMap p = any p
    goArg = \case
      ArgExplicit e -> go e
      ArgImplicit e -> go e
      ArgInout e _ -> go e
      ArgNamedBlock fields _ -> any (maybe False go . snd) fields
    goLet (LetBind _ _ _ _ rhs _) = go rhs
    goCase = \case
      MatchCase _ mg body _ -> maybe False go mg || go body
      MatchImpossible {} -> False
    goExcept (ExceptCase _ mg body _) = maybe False go mg || go body
    goHandler = \case
      HandlerReturn _ body _ -> go body
      HandlerOp _ _ _ body _ -> go body
    goDecl = \case
      DLet _ ld _ -> go (ldBody ld)
      DTopSplice e _ -> go e
      DUnsafeAssert _ inner _ -> goDecl inner
      _ -> False
    goDo = \case
      DoBind lb -> go (lbExpr lb)
      DoLet lb -> go (lbExpr lb)
      DoLetQ _ rhs mElse _ -> go rhs || maybe False (go . snd) mElse
      DoVar _ mty rhs _ -> maybe False go mty || go rhs
      DoAssign _ _ rhs _ -> go rhs
      DoExpr e -> go e
      DoUsing _ _ rhs _ -> go rhs
      DoDefer {} -> False
      DoReturn _ me _ -> maybe False go me
      DoBreak {} -> False
      DoContinue {} -> False
      DoWhile _ cond body mels _ -> go cond || any goDo body || maybe False (any goDo) mels
      DoFor _ _ src body mels _ -> go src || any goDo body || maybe False (any goDo) mels
      DoIf alts mels _ ->
        any (\(cond, body) -> go cond || any goDo body) alts || maybe False (any goDo) mels
      DoDecl d -> goDecl d
    goCompClause = \case
      S.CFor _ _ _ src _ -> go src
      S.CLet _ _ mty rhs _ -> maybe False go mty || go rhs
      S.CIf e -> go e
      S.COrderBy keys _ -> any (go . snd) keys
      S.CSkip e _ -> go e
      S.CTake e _ -> go e
      S.CDistinct me _ -> maybe False go me
      S.CGroupBy key aggs _ _ -> go key || any (\(_, e, mu) -> go e || maybe False go mu) aggs
      S.CJoin _ _ src on _ _ -> go src || go on
    goYield = \case
      YieldExpr e -> go e
      YieldPair k v -> go k || go v
    goPatch = \case
      PatchUpdate _ (PatchValue e) -> go e
      PatchExtend _ e -> go e
      PatchSection a b -> go a || go b
      PatchPun {} -> False
    goOpElem = \case
      ChainOperand e -> go e
      ChainOp {} -> False
    go = \case
      EVar {} -> False
      ERefFacet {} -> False
      EVarRead {} -> False
      EHole {} -> False
      EIntLit {} -> False
      EFloatLit {} -> False
      EStringLit _ parts _ -> any (go . ipExpr) parts
      EQuotedLit {} -> False
      EUnit {} -> False
      ETuple es _ -> any go es
      ERecordLit items _ -> any (\(RecItem _ _ mv) -> maybe False go mv) items
      ERecordType {} -> False
      EUniverseInstantiation base levels _ -> go base || any go levels
      eApp@(EApp f args) -> hit (exprSpan eApp) || go f || any goArg args
      EDot recv member -> hitMember member || go recv
      EQDot recv member -> hitMember member || go recv
      ERecordPatch recv items _ -> go recv || any goPatch items
      EReceiverSection _ args _ -> any goArg args
      ESectionLeft e _ _ -> go e
      ESectionRight _ e _ -> go e
      EOpRef {} -> False
      EOpChain elems -> any goOpElem elems
      EElvis a b _ -> go a || go b
      ELambda {} -> False
      ELet binds body _ -> any goLet binds || go body
      EBlock decls mres _ -> any goDecl decls || maybe False go mres
      EDo _ items _ -> any goDo items
      EIf alts mels _ ->
        anyMap (\(cond, body) -> go cond || go body) alts || maybe False go mels
      EMatch scrut cases _ -> go scrut || any goCase cases
      ETry scrut excepts mfin _ -> go scrut || any goExcept excepts || maybe False go mfin
      ETryMatch scrut cases excepts mfin _ ->
        go scrut || any goCase cases || any goExcept excepts || maybe False go mfin
      EHandle _ lbl scrut cases _ -> go lbl || go scrut || any goHandler cases
      EIs e _ -> go e
      EThunk {} -> False
      ELazy {} -> False
      EForce e _ -> go e
      ESeal a b _ -> go a || go b
      EOpenExists e _ _ body _ -> go e || go body
      ESealExists bs a b _ -> any (go . snd) bs || go a || go b
      EListLit es _ -> any go es
      ESetLit es _ -> any go es
      EMapLit kvs _ -> any (\(k, v) -> go k || go v) kvs
      EComprehension _ clauses yield _ -> any goCompClause clauses || goYield yield
      EArrow {} -> False
      EForall {} -> False
      EExists {} -> False
      ETraitArrow {} -> False
      EEffRow {} -> False
      EVariant arms mtail _ ->
        any (\(VariantArm e mty) -> go e || maybe False go mty) arms || maybe False go mtail
      EOptionSugar {} -> False
      EAscription e _ _ -> go e
      ECaptures e _ _ -> go e
      EBang _ e _ -> go e
      EQuote {} -> False
      ECodeQuote {} -> False
      ECodeEscape e _ -> go e
      ESplice e _ -> go e
      ESpliceInQuote {} -> False
      EQuoteHole {} -> False
      EImpossible {} -> False
      EKindQualified {} -> False
      EModuleSig {} -> False

-- | Elaborate a reference-operation head transactionally. A successful typed
-- recognition keeps the fresh universe instantiation and selected evidence
-- alive for its caller; a failed/speculative recognition restores the exact
-- prior state. Returning evidence terms after restoring their level metas
-- would leave dangling occurrence identities.
resolveRefOpExpr :: Ctx -> Expr -> [Arg] -> CheckM (Maybe (ExplicitRefOp, RefOpEvidence))
resolveRefOpExpr ctx f headArgs = do
  st0 <- get
  n0 <- gets (length . csDiags)
  r <- do
    (headTerm, headType) <- infer ctx f
    (tm0, _) <-
      if null headArgs
        then pure (headTerm, headType)
        else elabSpine ctx (exprSpan f) headTerm headType headArgs
    evidenceComponent <- pendingEvidenceComponentTerms ctx [tm0]
    flushPendingSelected evidenceComponent
    tm <- zonkTermM (ctxLen ctx) tm0
    refOpOfTerm ctx tm
  n1 <- gets (length . csDiags)
  case r of
    Just recognized | n1 == n0 -> pure (Just recognized)
    _ -> put st0 >> pure Nothing

-- | Read-only semantic recognition for refinement/escape analyses. Compare
-- selected evidence while the speculative universe instantiation is live,
-- then restore the checker state and return only the stable Boolean result.
resolvedRefOpMatchesMutable
  :: Ctx
  -> Expr
  -> [Arg]
  -> ExplicitRefOp
  -> Name
  -> CheckM Bool
resolvedRefOpMatchesMutable ctx f headArgs expectedOp name = do
  st0 <- get
  mop <- resolveRefOpExpr ctx f headArgs
  matched <- case mop of
    Just (actualOp, evidence) | actualOp == expectedOp ->
      refOpMatchesMutable ctx name evidence
    _ -> pure False
  put st0
  pure matched

refOpMatchesMutable :: Ctx -> Name -> RefOpEvidence -> CheckM Bool
refOpMatchesMutable ctx n evidence =
  case lookupCtx (nameText n) ctx of
    Just (i, entry)
      | Just info <- ceVarInfo entry -> do
          let expected0 = shiftTerm (i + 1) 0 (vriMonadRefDict info)
          case evidence of
            RefOpBare -> pure True
            RefOpCarrier actualM -> termMatchesValue ctx actualM (vriMonadType info)
            RefOpDict actual0 -> termMatchesTerm ctx actual0 expected0
    _ -> pure False

aliasCurrentReadPattern :: Ctx -> Pattern -> Expr -> Ctx -> CheckM Ctx
aliasCurrentReadPattern before pat rhs after =
  case pat of
    PVar qn -> do
      mroot <- currentReadAliasRoot before rhs
      pure $ maybe after (\root -> addVarCurrentAlias (nameText qn) root after) mroot
    _ -> pure after

currentReadAliasRoot :: Ctx -> Expr -> CheckM (Maybe Text)
currentReadAliasRoot ctx rhs = do
  direct <- recognizedRefReadRoot ctx rhs
  pure $ direct <|> aliasRoot rhs
  where
    aliasRoot = \case
      EAscription e _ _ -> aliasRoot e
      EVar n ->
        let root = refineRoot ctx (nameText n)
         in if isVarCurrentKey root then Just root else Nothing
      _ -> Nothing

unsupportedRefFacet :: Ctx -> Name -> Span -> CheckM (Maybe (Term, Value))
unsupportedRefFacet ctx n sp = do
  errAt sp "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
    ("mutable variable '" <> nameText n <> "' uses a higher-order monad shape this implementation cannot apply for explicit ref-facet operations (§18.6.1)")
  Just <$> anyHole ctx

escapedRefFacetsExpr :: Ctx -> Expr -> CheckM (Set Text)
escapedRefFacetsExpr _ e =
  pure (collectRefFacets e)

escapedRefFacetsExecutedExpr :: Ctx -> Expr -> CheckM (Set Text)
escapedRefFacetsExecutedExpr ctx = go
  where
    unionsM = fmap Set.unions . sequence
    pureEsc = pure . collectRefFacets
    goLet (LetBind _ _ _ _ rhs _) = pureEsc rhs
    goCase = \case
      MatchCase _ mg body _ -> unionsM [maybe (pure Set.empty) pureEsc mg, go body]
      MatchImpossible {} -> pure Set.empty
    goExcept (ExceptCase _ mg body _) = unionsM [maybe (pure Set.empty) pureEsc mg, go body]
    goHandler = \case
      HandlerReturn _ body _ -> go body
      HandlerOp _ _ _ body _ -> go body
    goDecl = \case
      DLet _ ld _ -> pureEsc (ldBody ld)
      DTopSplice e _ -> go e
      DUnsafeAssert _ inner _ -> goDecl inner
      _ -> pure Set.empty
    go = \case
      EAscription e _ _ -> go e
      EBang _ e _ -> go e
      EDo _ items _ -> doItemsVarEscapes ctx items
      EIf alts mels _ -> do
        condEscapes <- unionsM [go cond | (cond, _) <- alts]
        branchEscapes <- unionsM [go body | (_, body) <- alts]
        elseEscapes <- maybe (pure Set.empty) go mels
        pure (Set.unions [condEscapes, branchEscapes, elseEscapes])
      EMatch scrut cases _ ->
        unionsM (pureEsc scrut : map goCase cases)
      ETry scrut excepts mfin _ ->
        unionsM (go scrut : map goExcept excepts ++ [maybe (pure Set.empty) go mfin])
      ETryMatch scrut cases excepts mfin _ ->
        unionsM (go scrut : map goCase cases ++ map goExcept excepts ++ [maybe (pure Set.empty) go mfin])
      EHandle _ lbl scrut cases _ ->
        unionsM (pureEsc lbl : go scrut : map goHandler cases)
      ELet binds body _ ->
        unionsM (map goLet binds ++ [go body])
      EBlock decls mres _ ->
        unionsM (map goDecl decls ++ [maybe (pure Set.empty) go mres])
      EApp f args
        | Just (headArgs, n, _) <- refFacetReadArgs args -> do
            ok <- resolvedRefOpMatchesMutable ctx f headArgs ExplicitRefRead n
            if ok
              then pure (Set.unions (collectRefFacets f : map collectRefFacets headArgs))
              else pure (collectRefFacets (EApp f args))
        | Just (headArgs, n, rhs, _) <- refFacetWriteArgsWithHead args -> do
            ok <- resolvedRefOpMatchesMutable ctx f headArgs ExplicitRefWrite n
            if ok
              then pure (Set.unions (collectRefFacets f : collectRefFacets rhs : map collectRefFacets headArgs))
              else pure (collectRefFacets (EApp f args))
      e -> pure (collectRefFacets e)

collectRefFacets :: Data a => a -> Set Text
collectRefFacets x =
  case (cast x :: Maybe Expr) of
    Just (ERefFacet n _) -> Set.singleton (nameText n)
    _ -> Set.unions (gmapQ collectRefFacets x)

doItemsVarWrites :: Ctx -> [DoItem] -> CheckM (Set Text)
doItemsVarWrites ctx = foldM go Set.empty
  where
    addExecuted acc e = Set.union acc <$> writtenRefFacetsExecutedExpr ctx e
    go acc = \case
      DoAssign n monadic rhs _ -> do
        acc1 <- pure (Set.insert (nameText n) acc)
        if monadic then addExecuted acc1 rhs else pure acc1
      DoExpr e -> addExecuted acc e
      DoBind lb -> addExecuted acc (lbExpr lb)
      DoLet {} -> pure acc
      DoLetQ {} -> pure acc
      DoIf alts mels _ -> do
        condWrites <- foldM (\s (cond, _) -> addExecuted s cond) Set.empty alts
        branchWrites <- foldM (\s (_, body) -> Set.union s <$> doItemsVarWrites ctx body) Set.empty alts
        elseWrites <- maybe (pure Set.empty) (doItemsVarWrites ctx) mels
        pure (Set.unions [acc, condWrites, branchWrites, elseWrites])
      DoWhile _ cond body mels _ -> do
        condWrites <- writtenRefFacetsExecutedExpr ctx cond
        bodyWrites <- doItemsVarWrites ctx body
        elseWrites <- maybe (pure Set.empty) (doItemsVarWrites ctx) mels
        pure (Set.unions [acc, condWrites, bodyWrites, elseWrites])
      DoFor _ _ src body mels _ -> do
        srcWrites <- writtenRefFacetsExecutedExpr ctx src
        bodyWrites <- doItemsVarWrites ctx body
        elseWrites <- maybe (pure Set.empty) (doItemsVarWrites ctx) mels
        pure (Set.unions [acc, srcWrites, bodyWrites, elseWrites])
      DoUsing _ _ rhs _ -> addExecuted acc rhs
      DoDefer {} -> pure acc
      DoReturn {} -> pure acc
      DoDecl _ -> pure acc
      DoBreak {} -> pure acc
      DoContinue {} -> pure acc
      DoVar {} -> pure acc

doItemsVarEscapes :: Ctx -> [DoItem] -> CheckM (Set Text)
doItemsVarEscapes ctx = foldM go Set.empty
  where
    addExpr acc e = Set.union acc <$> escapedRefFacetsExpr ctx e
    addExecuted acc e = Set.union acc <$> escapedRefFacetsExecutedExpr ctx e
    go acc = \case
      DoAssign _ monadic rhs _ ->
        if monadic then addExecuted acc rhs else addExpr acc rhs
      DoExpr e -> addExecuted acc e
      DoBind lb -> addExecuted acc (lbExpr lb)
      DoLet lb -> addExpr acc (lbExpr lb)
      DoLetQ _ rhs mElse _ -> do
        acc1 <- addExpr acc rhs
        maybe (pure acc1) (addExpr acc1 . snd) mElse
      DoIf alts mels _ -> do
        condEscapes <- foldM (\s (cond, _) -> addExecuted s cond) Set.empty alts
        branchEscapes <- foldM (\s (_, body) -> Set.union s <$> doItemsVarEscapes ctx body) Set.empty alts
        elseEscapes <- maybe (pure Set.empty) (doItemsVarEscapes ctx) mels
        pure (Set.unions [acc, condEscapes, branchEscapes, elseEscapes])
      DoWhile _ cond body mels _ -> do
        acc1 <- addExecuted acc cond
        bodyEscapes <- doItemsVarEscapes ctx body
        elseEscapes <- maybe (pure Set.empty) (doItemsVarEscapes ctx) mels
        pure (Set.unions [acc1, bodyEscapes, elseEscapes])
      DoFor _ _ src body mels _ -> do
        acc1 <- addExpr acc src
        bodyEscapes <- doItemsVarEscapes ctx body
        elseEscapes <- maybe (pure Set.empty) (doItemsVarEscapes ctx) mels
        pure (Set.unions [acc1, bodyEscapes, elseEscapes])
      DoUsing _ _ rhs _ -> addExecuted acc rhs
      DoDefer _ e _ -> addExpr acc e
      DoReturn _ me _ -> maybe (pure acc) (addExpr acc) me
      DoDecl _ -> pure acc
      DoBreak {} -> pure acc
      DoContinue {} -> pure acc
      DoVar _ _ rhs _ -> addExpr acc rhs

elabTry :: Ctx -> Expr -> [ExceptCase] -> Maybe Expr -> Span -> CheckM (Term, Value)
elabTry ctx body excepts mfin sp = do
  errT <- freshMetaV ctx
  resT <- freshMetaV ctx
  bodyTy <- ioTypeM errT resT
  bodyTm <- check ctx body bodyTy
  errT' <- forceM errT
  -- handlers discharge the body's error type; the try expression's own
  -- error type is whatever the handlers / finalizer may still raise
  outErr <- if null excepts then pure errT' else freshMetaV ctx
  caught <-
    if null excepts
      then pure bodyTm
      else do
        -- \err -> match err cases
        --
        -- The handler body is elaborated as an ordinary expression in the
        -- handler context rather than by directly building Core 'CaseAlt's.
        -- That is important for §18.6.1 current-value reads in exception
        -- guards: a guarded handler lowers to the same branch-local
        -- expression shape as a guarded match, so a guard such as
        -- `except e if flag -> ...` gets a normal nearest-do lifting point
        -- inside the handler action.  Directly checking the guard as a pure
        -- CaseAlt guard would incorrectly reject the mutable current read.
        let nm = "__err"
            errN = Name nm sp
            ctx' = bindCtx nm False errT' ctx
            handlerExpr =
              EMatch
                (EVar errN)
                [MatchCase pat mguard hbody csp | ExceptCase pat mguard hbody csp <- excepts]
                sp
        (pre, handlerExpr') <- liftCurrentReadsExpr ctx' sp handlerExpr
        let handlerBody =
              if null pre
                then handlerExpr'
                else EDo Nothing (pre ++ [DoExpr handlerExpr']) sp
        handlerBodyTy <- ioTypeM outErr resT
        handlerBodyTm <- check ctx' handlerBody handlerBodyTy
        let handlerTm = CLamM Ordinary Expl QW nm handlerBodyTm
        catchHead <- globalHeadM prelCatchIO
        pure (CApp Expl (CApp Expl catchHead bodyTm) handlerTm)
  final <- case mfin of
    Nothing -> pure caught
    Just finE -> do
      unitT <- globalValueM prelUnit []
      finTy <- ioTypeM outErr unitT
      finTm <- check ctx finE finTy
      finallyHead <- globalHeadM prelFinallyIO
      pure (CApp Expl (CApp Expl finallyHead caught) finTm)
  resultTy <- ioTypeM outErr resT
  pure (final, resultTy)

-- do blocks (§18.2): the carrier is IO in this implementation.
--
-- @loops@ tracks the enclosing loops of this do-scope (one entry per
-- loop, @Just label@ when labeled) so @break@\/@continue@ are resolved
-- at compile time: a labeled form must name an enclosing labeled loop
-- (§18.2.5) and an unlabeled form must occur inside some loop body
-- (§18.6 "Using them outside a loop body is a compile-time error").
-- The loop's @else@ suite runs after normal completion, so the loop
-- itself is not in scope as a target there. Each do-expression starts a
-- fresh scope: targets never cross a first-class do-value boundary.
elabDo :: Ctx -> Maybe Name -> [DoItem] -> Span -> Maybe Value -> CheckM (Term, Value)
elabDo ctx0 mlabel items0 _sp mexpected =
  withLocalNominalEscapeBoundary ctx0 _sp $ do
  -- §18.9.3: '~' inout markers are admissible within this do elaboration
    let ctx = ctx0 {ctxInDo = True, ctxVarReadBlock = Nothing}
    me <- traverse forceM mexpected
    case me of
      -- an Eff-typed do sequences algebraic-effect computations
      -- (§18.1.14); it elaborates to __effBind chains, not the IO kernel
      Just (VGlobN g [(_, row), (_, a)])
        | g == prelEff -> do
          items <- liftDoItems ctx items0
          elabEffDo ctx row a items _sp
      -- an Elab-typed do sequences elaboration-time actions (§21.9); it
      -- elaborates to __elabBind chains run by the Elab evaluator
      Just (VGlobN g [(_, a)])
        | g == prelElab ->
            do
              items <- liftDoItems ctx items0
              elabElabDo ctx a items _sp
      -- §18.8: a do-block whose result is a user monad `m a` (m has a
      -- Monad instance) and is not a kernel carrier (IO/STM handled by
      -- elabDoIO; Eff/Elab above) elaborates by the classic monadic
      -- desugaring to (>>=)/pure.
      Just t
        | Just (mV, _) <- monadActionViewValue t -> do
            kernelCarrier <- isKernelDoCarrierM mV
            if kernelCarrier
              then elabDoIO ctx me items0
              else
                if doItemsRequireEffectAwareLifting ctx items0
                  then elabMonadDo ctx t items0 _sp
                  else
                    case applicativeDoShape items0 of
                      Just (actions, lets, finalExpression, boundNames) ->
                        elabApplicativeDo
                          ctx
                          t
                          actions
                          lets
                          finalExpression
                          boundNames
                          _sp >>= \case
                            Just result -> pure result
                            Nothing -> elabMonadDo ctx t items0 _sp
                      Nothing -> elabMonadDo ctx t items0 _sp
      _ -> elabDoIO ctx me items0
  where
    elabDoIO = elabDoIOItems (nameText <$> mlabel) _sp

ioCarrierErrorType :: Value -> Maybe Value
ioCarrierErrorType carrier = do
  guard (nominalFamilyValueHead carrier == Just prelIO)
  snd <$> monadActionViewValue carrier

isKernelDoCarrierM :: Value -> CheckM Bool
isKernelDoCarrierM carrier = do
  forced <- forceM carrier
  pure (maybe False (`elem` doKernelCarriers) (nominalFamilyValueHead forced))

elabDoIOItems :: Maybe Text -> Span -> Ctx -> Maybe Value -> [DoItem] -> CheckM (Term, Value)
elabDoIOItems mlabel _sp ctx mexp items = do
  (errT, resT, doTy) <- case mexp of
    Just expd
      | Just (carrier, a) <- monadActionViewValue expd
      , Just e <- ioCarrierErrorType carrier ->
          pure (e, a, Nothing)
    -- pure-result do (corpus): a do block in a position expecting a
    -- known non-IO type sequences pure statements; the §18.8 kernel
    -- passes pure statement values through, so it runs unchanged
    Just expd | not (isFlexHead expd) -> do
      e <- freshMetaV ctx
      pure (e, expd, Just expd)
    _ -> do
      e <- freshMetaV ctx
      a <- freshMetaV ctx
      pure (e, a, Nothing)
  kitems <- goItems [] ctx errT resT items
  fallbackTy <- ioTypeM errT resT
  pure (CDo mlabel kitems, fromMaybe fallbackTy doTy)
  where
    expectedMonadType = fst <$> (mexp >>= monadActionViewValue)

    -- The surviving kernel do carrier is IO. STM uses its selected Monad
    -- evidence and is eliminated by 'elabMonadDo' before this point.
    wrapTy :: Value -> Value -> CheckM Value
    wrapTy errT x = case expectedMonadType >>= (`monadResultType` x) of
      Just actionType -> pure actionType
      Nothing -> ioTypeM errT x

    -- §18.8 pure-result do (corpus accommodation): a do-block elaborated at a
    -- KNOWN non-IO, non-STM, non-flex type sequences PURE statements (lets and a
    -- final pure expression) — the block's value IS that pure result.  Crucially
    -- this is NOT a monadic carrier: there is no bind, no effect sequencing.  So
    -- a statement here must be checked at the BARE pure type, never the
    -- IO-wrapped type.  Otherwise an IO action @IO errT a@ would unify with the
    -- pure result @resT@ (a := resT) and the whole block would be handed back at
    -- the pure type @resT@ — exactly the §4.5 forge: a plain module's
    -- @do { throwIO Unit } : Void@ (or the desugared @do { tmp <- throwIO Unit;
    -- tmp } : Void@ from a @!@-splice) extracting a pure inhabitant of @Void@.
    -- 'pureResult' gates the IO-wrap acceptance off and rejects monadic binds in
    -- this mode (§18.3.1 / §18.2: a monadic bind requires a monadic carrier).
    pureResult :: Bool
    pureResult =
      isJust mexp
        && isNothing expectedMonadType
        && maybe False (not . isFlexHead) mexp

    doMonadType :: Value -> CheckM (Maybe Value)
    doMonadType errT = case mexp of
      Just _ -> pure expectedMonadType
      Nothing -> Just <$> globalValueM prelIO [(Expl, errT)]
    actionTypeFor :: Value -> Value -> Value -> CheckM Value
    actionTypeFor fallbackErr mTy a =
      case monadResultType mTy a of
        Just ty -> pure ty
        Nothing -> do
          errAt _sp "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
            "this MonadRef carrier has a higher-order monad shape this implementation cannot apply (§18.6.1)"
          ioTypeM fallbackErr a
    tryUnify :: Ctx -> Value -> Value -> CheckM Bool
    tryUnify c left right = do
      checkpoint <- get
      solved <- unify c left right
      unless solved (put checkpoint)
      pure solved
    isKernelActionType :: Value -> CheckM Bool
    isKernelActionType ty = do
      forced <- forceM ty
      pure (nominalFamilyValueHead forced == Just prelIO)
    projectionPatternFields :: Pattern -> Value -> CheckM (Maybe ([(Maybe Name, Text)], [(Text, Value)]))
    projectionPatternFields pat ty0 = do
      ty <- forceM ty0
      pure $ case (pat, ty) of
        (PTuple ps _, VRecordT fs)
          | Just ns <- mapM patVarName ps
          , length ns == length fs ->
              Just (zip ns (map fst fs), fs)
        (PRecord recItems Nothing _, VRecordT fs)
          | Just ns <- mapM recItemVar recItems
          , sort (map fst ns) == map fst fs ->
              Just ([(fromMaybe Nothing (lookup f ns), f) | (f, _) <- fs], fs)
        _ -> Nothing
      where
        patVarName = \case
          PVar n -> Just (Just n)
          PWild _ -> Just Nothing
          _ -> Nothing
        recItemVar (False, f, mp) = case mp of
          Nothing -> Just (nameText f, Just f)
          Just (PVar n) -> Just (nameText f, Just n)
          Just (PWild _) -> Just (nameText f, Nothing)
          _ -> Nothing
        recItemVar _ = Nothing
    validateProjectionPattern :: Pattern -> [(Maybe Name, Text)] -> CheckM ()
    validateProjectionPattern pat named =
      forM_ (duplicatesOf [nameText n | (Just n, _) <- named]) $ \n ->
        errAt (patternSpan pat) "E_DUPLICATE_PATTERN_BINDER" (Just "kappa-hs.pattern.duplicate-binder")
          ("pattern binds '" <> n <> "' more than once (§17.2)")
    projectedFieldItems :: Ctx -> Q -> [(Maybe Name, Text)] -> [(Text, Value)] -> CheckM (Ctx, [KItem])
    projectedFieldItems c0 q named fs = go c0 0 named
      where
        go c _ [] = pure (c, [])
        go c scrutIx ((mn, f) : rest) = do
          let recv = CVar scrutIx
              projTm = CProjM Ordinary recv f
          projV <- evalIn c projTm
          fldTy <- case lookup f fs of
            Just t -> substThisInto c recv t
            Nothing -> freshMetaV c
          let (patC, cNext, bump) = case mn of
                Just n -> (CPVarM Ordinary (nameText n), bindCtxLet (nameText n) False fldTy projV c, 1)
                Nothing -> (CPWild, c, 0)
          (cFin, more) <- go cNext (scrutIx + bump) rest
          pure (cFin, KLet q patC projTm : more)
    goItems :: [Maybe Text] -> Ctx -> Value -> Value -> [DoItem] -> CheckM [KItem]
    goItems = goItemsWith mlabel [] True True

    -- The active and enclosing do-scope labels are distinct from loop labels:
    -- @defer@ may target either kind of do frame, while @break@/@continue@
    -- may target only loops. Reachability-warning state and permission for the
    -- outer statement-result discard are explicit so nested statement-position
    -- do scopes stay transparent to completion without duplicating warnings.
    goItemsWith
      :: Maybe Text
      -> [Maybe Text]
      -> Bool
      -> Bool
      -> [Maybe Text]
      -> Ctx
      -> Value
      -> Value
      -> [DoItem]
      -> CheckM [KItem]
    goItemsWith _ _ _ _ _ _ _ _ [] = pure []
    goItemsWith scopeLabel enclosingDoScopes warnReachability allowFinalActionDiscard loops c errT resT (item : rest) = do
      let goItems =
            goItemsWith
              scopeLabel
              enclosingDoScopes
              warnReachability
              allowFinalActionDiscard
          lastItem = null rest
          withLoop ml = (nameText <$> ml) : loops
          continueAfterAbrupt completionKind abruptSpan = do
            when (warnReachability && not (null rest)) $ do
              let unreachableSpan =
                    let firstSpan = doItemSpan (head rest)
                        lastSpan = doItemSpan (last rest)
                    in if spanFile firstSpan == spanFile lastSpan
                        then Span (spanFile firstSpan) (spanStart firstSpan) (spanEnd lastSpan)
                        else firstSpan
                  payload =
                    withPayloadField "completionKind" completionKind
                      $ withPayloadField "unreachableRange" (T.pack (show unreachableSpan))
                      $ payloadKind "do-item-unreachable"
              report
                $ withPayload payload
                $ withRelated
                    (related (RoleOther "abrupt-control") abruptSpan "this item makes the following do-items unreachable")
                $ diag
                    SevWarning
                    StageElaborate
                    "W_DO_ITEM_UNREACHABLE"
                    (Just "kappa.do.unreachable-item")
                    unreachableSpan
                    "do-items after abrupt control are unreachable (§18.2.2)"
            goItemsWith
              scopeLabel
              enclosingDoScopes
              False
              allowFinalActionDiscard
              loops
              c
              errT
              resT
              rest
          checkLoopTarget what ml sp = case ml of
            Just l ->
              unless (Just (nameText l) `elem` loops) $
                errAt (nameSpan l) "E_LABEL_UNRESOLVED" (Just "kappa-hs.do.label-unresolved")
                  (what <> "@" <> nameText l
                     <> " does not target an enclosing labeled loop of this do-scope (§18.2.5)")
            Nothing ->
              when (null loops) $
                errAt sp "E_BREAK_OUTSIDE_LOOP" (Just "kappa-hs.do.break-outside-loop")
                  ("'" <> what
                     <> "' is valid only within the body of a loop of this do-scope (§18.6)")
          continueReturn ml me rsp = do
            -- §18.5/§18.5.1: `return@L` targets the enclosing named function
            -- or labeled lambda L. Resolution is confined to the current
            -- function/lambda body and does not cross a user-written lambda
            -- boundary, so the only reachable target is the innermost
            -- enclosing one (`ctxReturnTarget`). When L names it, the abrupt
            -- Return targets exactly the construct that bare `return` does
            -- here (the current body's completion), so it lowers to the same
            -- KReturn; a label naming anything else is a compile-time error.
            forM_ ml $ \l ->
              unless (Just (nameText l) == ctxReturnTarget c) $
                errAt (nameSpan l) "E_LABEL_UNRESOLVED" (Just "kappa-hs.do.label-unresolved")
                  ("return@" <> nameText l
                     <> " does not target the enclosing named function or labeled lambda; return resolution is confined to the current function/lambda body and does not cross a lambda boundary (§18.5/§18.5.1)")
            tm <- case me of
              Just e -> do
                -- a `return` payload ordinarily carries this do-scope's
                -- result type; per the §18.8 completion kernel an abrupt
                -- Return targets the enclosing function instead, so a
                -- payload typed for the outer return context is also
                -- accepted (e.g. `if c then pure () else do return 0`)
                st0 <- get
                n0 <- gets (length . csDiags)
                tm0 <- check c (e) resT
                n1 <- gets (length . csDiags)
                if n1 == n0
                  then pure tm0
                  else do
                    put st0
                    retT <- freshMetaV c
                    check c (e) retT
              Nothing -> do
                unitT <- globalValueM prelUnit []
                expectType c rsp unitT resT
                generatedCtorAtM c unitT prelUnit
            ks <- continueAfterAbrupt "return" rsp
            pure (KReturn tm : ks)
          continueFor ml pat src body mels fsp = do
            -- §18.6/§20.2: a 'for' generator iterates any source the
            -- comprehension as-if list model understands. The common case
            -- is a List source, which is checked directly against
            -- 'List elemT' exactly as before (no double elaboration, so
            -- the §12 usage analysis on 'src' is unaffected). Non-List
            -- sources (Array/Set/Map/Option/Query/range) are detected by a
            -- side-effect-free probe of the inferred source type and
            -- materialized to the element list via the matching prelude
            -- conversion.
            let src' = src
            elemT <- freshMetaV c
            srcKind <- probeForSrcKind c src'
            let listSrc = case srcKind of
                  SKArray -> prelApp1 fsp "__arrayToList" [src']
                  SKSet -> prelApp1 fsp "__setToList" [src']
                  SKMap -> prelApp1 fsp "__mapToList" [src']
                  SKOption -> prelApp1 fsp "__optionToList" [src']
                  SKQuery -> prelApp1 fsp "__queryToList" [src']
                  SKRange -> prelApp1 fsp "rangeToList" [src']
                  SKIntoQuery ->
                    prelApp1 fsp "__intoQueryToListAs" [src']
                  _ -> src'
            listT <- globalValueM prelList [(Expl, elemT)]
            srcTm <- check c listSrc listT
            srcWrites <- writtenRefFacetsExecutedExpr c src'
            srcEscapes <- escapedRefFacetsExpr c src'
            let cSrc = applyVarCurrentEffects srcWrites srcEscapes c
            checkIrrefutable cSrc pat elemT fsp
            (patC, c', patternRefinements) <- elabPattern cSrc pat elemT
            unitT <- globalValueM prelUnit []
            bodyKs <-
              withPatternRefinements patternRefinements $
                goItems (withLoop ml) c' errT unitT body
            elsKs <- traverse (goItems loops cSrc errT unitT) mels
            bodyWrites <-
              withPatternRefinements patternRefinements $
                doItemsVarWrites c' body
            elseWrites <- maybe (pure Set.empty) (doItemsVarWrites cSrc) mels
            bodyEscapes <-
              withPatternRefinements patternRefinements $
                doItemsVarEscapes c' body
            elseEscapes <- maybe (pure Set.empty) (doItemsVarEscapes cSrc) mels
            let cAfter =
                  applyVarCurrentEffects
                    (Set.union bodyWrites elseWrites)
                    (Set.union bodyEscapes elseEscapes)
                    cSrc
            ks <- goItems loops cAfter errT resT rest
            pure (KFor (nameText <$> ml) patC srcTm bodyKs elsKs : ks)
          continueIf alts mels _isp = do
            -- §7.4.1: `x is C` conditions refine their subject inside the
            -- guarded suite
            --
            -- §16.4.2/§18.6.2: an `if`/`elif` chain in the IO do-kernel tests
            -- its conditions in order, with no user code running between two
            -- conditions and no loop back-edge into the chain. So when
            -- `alt_k`'s suite runs, every earlier condition `c_1 … c_{k-1}`
            -- evaluated False and `c_k` evaluated True, all at the chain's
            -- single straight-line test sequence. We therefore thread the
            -- accumulated negation `¬c_1 ∧ … ∧ ¬c_{k-1}` (as `(c_i, False)`
            -- boolean evidence and as the §7.4.1 complement refinements of
            -- each earlier `x is C`) into `alt_k`'s suite alongside its own
            -- `(c_k, True)`. The trailing `else` gets `¬c_1 ∧ … ∧ ¬c_n`. Each
            -- such fact is provably true on the branch it is pushed into: the
            -- per-alt `(c_k, True)` is exactly the existing sound then-suite
            -- fact, and a negation is sound under exactly the same conditions
            -- (same straight-line, back-edge-free chain). The `var`-staleness
            -- caveat is handled by §18.6.2 VarCurrent representatives:
            -- generated/recognized reads alias a versioned current-value
            -- root, and assignments or write-containing joins advance the
            -- version before the following do-items are checked.
            -- 'goAlts' threads the accumulated false-evidence forward and
            -- returns it (as 'elseBool'/'elseCtx') so the trailing else suite
            -- can reuse the same facts without re-elaborating the conditions.
            unitT <- globalValueM prelUnit []
            let branchResultT = if lastItem then resT else unitT
                applyCondEffects base cond = do
                  writes <- writtenRefFacetsExecutedExpr base cond
                  escapes <- escapedRefFacetsExecutedExpr base cond
                  pure (applyVarCurrentEffects writes escapes base)
                goAlts accBool accCtx [] = pure ([], accBool, accCtx)
                goAlts accBool accCtx ((cond, body) : moreAlts) = do
                  -- positive refinements of THIS condition, on top of the
                  -- complement refinements accumulated from earlier conditions
                  refs <- condRefines accCtx cond
                  let cR = refineCtx refs accCtx
                  boolT <- globalValueM prelBool []
                  condTm <- check cR cond boolT
                  cREff <- applyCondEffects cR cond
                  branchCondition <- normalizeBranchConditionTerm cREff condTm
                  -- this suite runs with `c_k` True and every earlier `c_i`
                  -- False, so both kinds of fact hold (§3.2.3 proof source)
                  oldBool <- gets csBoolFacts
                  modify' $ \st ->
                    st
                      { csBoolFacts =
                          ScopedBoolFact (ctxLen cREff) branchCondition True
                            : accBool ++ csBoolFacts st
                      }
                  bodyKs <-
                    goItemsWith
                      scopeLabel
                      enclosingDoScopes
                      warnReachability
                      (isJust mels)
                      loops
                      cREff
                      errT
                      branchResultT
                      body
                  modify' $ \st -> st {csBoolFacts = oldBool}
                  -- thread this condition's FALSE evidence into the remaining
                  -- elif suites and the final else: `accCtx` for the §7.4.1
                  -- complement refinements (`condRefinesElse accCtx cond`,
                  -- mirroring the if-expression else-branch), `accBool` for the
                  -- bare `(condTm, False)` boolean fact
                  negs <- condRefinesElse accCtx cond
                  let accCtxFalse = refineCtx negs accCtx
                      accBool' =
                        ScopedBoolFact
                          (ctxLen accCtxFalse)
                          branchCondition
                          False
                          : accBool
                  accCtx' <- applyCondEffects accCtxFalse cond
                  (restAlts, elseBool, elseCtx) <- goAlts accBool' accCtx' moreAlts
                  pure ((condTm, bodyKs) : restAlts, elseBool, elseCtx)
            (alts', elseBool, elseCtx) <- goAlts [] c alts
            elsKs <-
              traverse
                ( \body -> do
                    oldBool <- gets csBoolFacts
                    modify' $ \st -> st {csBoolFacts = elseBool ++ csBoolFacts st}
                    ks <-
                      goItemsWith
                        scopeLabel
                        enclosingDoScopes
                        warnReachability
                        True
                        loops
                        elseCtx
                        errT
                        branchResultT
                        body
                    modify' $ \st -> st {csBoolFacts = oldBool}
                    pure ks
                )
                mels
            when (lastItem && isNothing mels) $
              expectType c _isp unitT resT
            -- §8.2.2A postdominating refinement: when every branch except
            -- one completes abruptly, the surviving branch's facts hold
            -- for the rest of this do-scope
            cAfter <- case (alts, mels) of
              ([(cond, thenB)], Just elseB)
                | abruptSuite elseB -> do
                    refs <- condRefines c cond
                    pure (refineCtx refs c)
                | abruptSuite thenB -> do
                    negs <- condRefinesElse c cond
                    pure (refineCtx negs c)
              _ -> pure c
            condWrites <- foldM (\s (cond, _) -> Set.union s <$> writtenRefFacetsExecutedExpr c cond) Set.empty alts
            altWrites <- foldM (\s (_, body) -> Set.union s <$> doItemsVarWrites c body) Set.empty alts
            elseWrites <- maybe (pure Set.empty) (doItemsVarWrites c) mels
            condEscapes <- foldM (\s (cond, _) -> Set.union s <$> escapedRefFacetsExecutedExpr c cond) Set.empty alts
            altEscapes <- foldM (\s (_, body) -> Set.union s <$> doItemsVarEscapes c body) Set.empty alts
            elseEscapes <- maybe (pure Set.empty) (doItemsVarEscapes c) mels
            let cAfterJoin =
                  applyVarCurrentEffects
                    (Set.unions [condWrites, altWrites, elseWrites])
                    (Set.unions [condEscapes, altEscapes, elseEscapes])
                    cAfter
            ks <- goItems loops cAfterJoin errT resT rest
            pure (KIf alts' elsKs : ks)
          continueDefer ml e _dsp = do
            -- §18.7: `defer e` schedules onto the current do-scope;
            -- `defer@L e` schedules onto the enclosing do-scope labeled L
            -- (which may be outer, so the action stays pending across inner
            -- scope exits and runs only when L itself exits). The labeled
            -- do-scopes enclosing this point are this do-block (mlabel) and
            -- every enclosing labeled loop body (loops); a label naming
            -- none of them is a compile-time error rather than a defer that
            -- never fires.
            forM_ ml $ \l ->
              unless
                ( Just (nameText l) == scopeLabel
                    || Just (nameText l) `elem` enclosingDoScopes
                    || Just (nameText l) `elem` loops
                ) $
                errAt (nameSpan l) "E_LABEL_UNRESOLVED" (Just "kappa-hs.do.label-unresolved")
                  ("defer@" <> nameText l
                     <> " does not target an enclosing labeled do-scope (explicit 'do' or loop) of this do-scope (§18.7)")
            unitT <- globalValueM prelUnit []
            deferTy <- ioTypeM errT unitT
            eTm <- check c e deferTy
            escapes <- escapedRefFacetsExpr c e
            let cAfter = foldr escapeVarCurrent c (Set.toList escapes)
            ks <- goItems loops cAfter errT resT rest
            pure (KDefer (nameText <$> ml) eTm : ks)
          continueUsing mq pat rhs usp = do
            -- §9.3: using always binds its pattern with borrowed access at
            -- the default quantity ω; an explicit prefix is rejected
            forM_ mq $ \qsp ->
              errAt qsp "E_QTT_USING_EXPLICIT_QUANTITY" (Just "kappa-hs.qtt.using-quantity")
                "a 'using' item always binds with borrowed access at the default quantity ω; explicit quantity or borrow markers are not permitted (§9.3, §18.2)"
            -- §19.5/§18.8.5 resource-scoped bind: `acquire` yields an owned
            -- resource of type `m A`; `pat` is bound (borrowed) for the rest
            -- of the scope, and the resource's `release` (resolved from the
            -- required `Releasable m A` instance) is attached to scope exit,
            -- running on EVERY exit path (normal/return/break/continue/error)
            -- in LIFO order with any `defer`s — realized by the protected
            -- exit machinery (KUsing), not a source rewrite to `defer` (which
            -- would move the resource before the borrowed use, §19.5).
            aT <- freshMetaV c
            acquireTy <- ioTypeM errT aT
            acquireTm <- check c rhs acquireTy
            -- Releasable (m := IO errT) (a := aT); `release : a -> m Unit`
            mTyV <- globalValueM prelIO [(Expl, errT)]
            releasableGoal <- globalValueM prelReleasable [(Expl, mTyV), (Expl, aT)]
            dictTm <- resolveImplicit c usp releasableGoal
            let releaseTm = CProjM Ordinary dictTm "release"
            checkIrrefutable c pat aT usp
            (patC, cBound, patternRefinements) <- elabPattern c pat aT
            writes <- writtenRefFacetsExecutedExpr c rhs
            escapes <- escapedRefFacetsExecutedExpr c rhs
            let cAfter = applyVarCurrentEffects writes escapes cBound
            ks <-
              withPatternRefinements patternRefinements $
                goItems loops cAfter errT resT rest
            pure (KUsing patC acquireTm releaseTm : ks)
      case item of
        -- §18.8.3.1: a nested `do` block in statement position is a child
        -- scope that is TRANSPARENT to abrupt completion. Its items are
        -- elaborated under the SAME lexical completion context (enclosing
        -- `loops` and `ctxReturnTarget`), so a `break`/`continue`/`return@L`
        -- inside it that targets an enclosing loop or function resolves and
        -- propagates outward. (A first-class do VALUE — `let x = do …`, or a
        -- spliced `!doVal` — stays opaque: it is elaborated through the
              -- ordinary value path, which resets the completion context.) STM
              -- blocks are evidence-driven user-monad blocks and do not reach
              -- this IO kernel.
        DoExpr e0 -> do
          rewriteVarInoutStatement c e0 >>= \case
            Just items -> goItems loops c errT resT (items ++ rest)
            Nothing -> do
              (pre, e) <- liftCurrentReadsExpr c (exprSpan e0) e0
              if not (null pre)
                then goItems loops c errT resT (pre ++ DoExpr e : rest)
                else case e of
                  EDo innerLbl innerItems _ -> do
                        aT <- if lastItem then pure resT else freshMetaV c
                        subItems <-
                          goItemsWith
                            (nameText <$> innerLbl)
                            (scopeLabel : enclosingDoScopes)
                            warnReachability
                            allowFinalActionDiscard
                            loops
                            c
                            errT
                            aT
                            innerItems
                        unless lastItem $
                          registerDiscardedResult c (exprSpan e) aT
                        ks <- goItems loops c errT resT rest
                        pure (KSubDo (nameText <$> innerLbl) subItems : ks)
                  _ | pureResult -> do
                        -- §18.8 pure-result do: statements are PURE values, not IO actions.
                        -- The final statement IS the block's result (checked at the pure
                        -- 'resT'); a non-final statement is a discarded pure value.  No
                        -- IO-wrap acceptance here — that is what closes the §4.5 forge
                        -- (@do { throwIO Unit } : Void@ / a @!@-splice's lifted bind), since an
                        -- @IO errT _@ action no longer unifies with the pure result.
                        tm <-
                          if lastItem
                            then check c e resT
                            else do
                              aT <- freshMetaV c
                              tm0 <- check c e aT
                              registerDiscardedResult c (exprSpan e) aT
                              pure tm0
                        escapes <- escapedRefFacetsExpr c e
                        let cAfter = foldr escapeVarCurrent c (Set.toList escapes)
                        (KExpr tm :) <$> goItems loops cAfter errT resT rest
                  _ -> do
                        aT <- if lastItem then pure resT else freshMetaV c
                        let eD = e
                        ioT <- wrapTy errT aT
                        canonicalPure <- canonicalApplicativePurePayload c eD
                        let structuralAction = case eD of
                              EIf {} -> True
                              EMatch {} -> True
                              _ -> False
                        -- statements are IO actions (§18.2); the corpus also
                        -- sequences pure expressions as statements, and the §18.8
                        -- kernel passes pure statement values through unchanged, so
                        -- an inferable statement may also check at the bare type
                        tm <- case () of
                          _ | isJust canonicalPure -> check c eD ioT
                            | structuralAction ->
                                preferCheckByErrors
                                  (check c eD ioT)
                                  (check c eD aT)
                            | otherwise -> case eD of
                              _ | statementInferable eD -> do
                                checkedMonadRefExpr c eD ioT >>= \case
                                  Just tm0 -> pure tm0
                                  Nothing -> do
                                    (tm0, ty0) <- infer c eD
                                    (tm1, ty1) <- insertAllImplicits c (exprSpan eD) tm0 ty0
                                    actionShaped <- isKernelActionType ty1
                                    okIO <-
                                      if actionShaped
                                        then tryUnify c ty1 ioT
                                        else pure False
                                    if okIO
                                      then pure tm1
                                      else do
                                        okPure <- tryUnify c ty1 aT
                                        okDiscard <-
                                          if okPure
                                            then pure True
                                            else do
                                              -- A final action of a unit-result do-scope
                                              -- may have a non-unit result; it is
                                              -- discarded by the established completion
                                              -- accommodation.
                                              unitT <- globalValueM prelUnit []
                                              isUnit <- tryUnify c aT unitT
                                              if allowFinalActionDiscard && isUnit && actionShaped
                                                then do
                                                  b <- freshMetaV c
                                                  discardTy <- ioTypeM errT b
                                                  ok <- tryUnify c ty1 discardTy
                                                  when ok $
                                                    registerDiscardedResult c (exprSpan eD) b
                                                  pure ok
                                                else pure False
                                        unless okDiscard $ expectType c (exprSpan eD) ty1 ioT
                                        pure tm1
                              _ -> check c eD ioT
                        unless lastItem $
                          registerDiscardedResult c (exprSpan eD) aT
                        writes <- writtenRefFacetsExecutedExpr c eD
                        escapes <- escapedRefFacetsExecutedExpr c eD
                        let cAfter = applyVarCurrentEffects writes escapes c
                        (KExpr tm :) <$> goItems loops cAfter errT resT rest
        DoBind (LetBind implocal prefix pat mty rhs0 bsp) -> do
          rewritten <-
            if isNothing mty && not implocal && emptyBinderPrefix prefix
              then rewriteVarInoutBind VarInoutMonadic c pat rhs0
              else pure Nothing
          case rewritten of
            Just items -> goItems loops c errT resT (items ++ rest)
            Nothing -> do
              (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
              if not (null pre)
                then goItems loops c errT resT (pre ++ DoBind (LetBind implocal prefix pat mty rhs bsp) : rest)
                else do
                  aT <- case mty of
                    Just tyE -> do
                      (tyTm, _) <- inferType c tyE
                      evalIn c tyTm
                    Nothing -> freshMetaV c
                  let rhsD = rhs
                      -- §18.8 pure-result do: there is no monadic carrier, so the IO-wrap
                      -- acceptance of the bind RHS is OFF (an @IO errT _@ action must NOT
                      -- satisfy a bind in a pure block — that was the §4.5 forge route:
                      -- @do { tmp <- throwIO Unit; tmp } : Void@). A source bind requires
                      -- a checked monadic carrier and selected evidence; arbitrary nominal
                      -- application shape is not evidence of bind semantics.
                  bindRhsTy <- if pureResult then pure aT else wrapTy errT aT
                  rhsTm <- check c rhsD bindRhsTy
                  writes <- writtenRefFacetsExecutedExpr c rhsD
                  escapes <- escapedRefFacetsExecutedExpr c rhsD
                  let cExec = applyVarCurrentEffects writes escapes c
                  checkIrrefutable cExec pat aT bsp
                  mProj <- if implocal then pure Nothing else projectionPatternFields pat aT
                  case mProj of
                    Just (named, fs) -> do
                      validateProjectionPattern pat named
                      scrutN <- freshNameM "__scrut"
                      let cScrut = bindCtx scrutN False aT cExec
                          q = qOf (bpQuantity prefix)
                      (cFields, fieldItems) <- projectedFieldItems cScrut q named fs
                      ks <- goItems loops cFields errT resT rest
                      pure (KBind QW (CPVarM Ordinary scrutN) rhsTm Nothing : fieldItems ++ ks)
                    Nothing -> do
                      (patC, cBound, patternRefinements) <-
                        elabPattern cExec pat aT
                      ks <- withPatternRefinements patternRefinements $ do
                        cAliased <-
                          aliasCurrentReadPattern cExec pat rhsD cBound
                        let c' =
                              markImplicitLocal
                                bsp
                                implocal
                                prefix
                                cExec
                                cAliased
                        goItems loops c' errT resT rest
                      readW <- refReadWitnessOfExpr c rhsD
                      pure (KBind (qOf (bpQuantity prefix)) patC rhsTm readW : ks)
        DoLet (LetBind implocal prefix pat mty rhs0 bsp) -> do
          rewritten <-
            if isNothing mty && not implocal && emptyBinderPrefix prefix
              then rewriteVarInoutBind VarInoutPure c pat rhs0
              else pure Nothing
          case rewritten of
            Just items -> goItems loops c errT resT (items ++ rest)
            Nothing -> do
              (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
              if not (null pre)
                then goItems loops c errT resT (pre ++ DoLet (LetBind implocal prefix pat mty rhs bsp) : rest)
                else do
              -- §18.3.1: `let pat = expr` inside `do` may contain `!`. The
              -- spliced computation is sequenced first and `pat` is then bound
              -- to its value; desugar `!` here exactly as the bind/expr items
              -- do, so it does not reach `infer`/`check` as a bare splice
              -- (E_SPLICE_OUTSIDE_DO). The KLet runtime runs splices via evalK.
                  let rhsD = rhs
                  (rhsTm, rhsTy) <- case mty of
                    Just tyE -> do
                      (tyTm, _) <- inferType c tyE
                      tyV <- evalIn c tyTm
                      tm <- check c rhsD tyV
                      pure (tm, tyV)
                    Nothing -> do
                      (tm, ty) <- infer c rhsD
                      insertAllImplicits c bsp tm ty
                  checkIrrefutable c pat rhsTy bsp
                  mProj <- if implocal then pure Nothing else projectionPatternFields pat rhsTy
                  case mProj of
                    Just (named, fs) -> do
                      validateProjectionPattern pat named
                      scrutN <- freshNameM "__scrut"
                      rhsV <- evalIn c rhsTm
                      let cScrut = bindCtxLet scrutN False rhsTy rhsV c
                          q = qOf (bpQuantity prefix)
                      (cFields, fieldItems) <- projectedFieldItems cScrut q named fs
                      ks <- goItems loops cFields errT resT rest
                      pure (KLet QW (CPVarM Ordinary scrutN) rhsTm : fieldItems ++ ks)
                    Nothing -> do
                      (patC, cBound, patternRefinements) <-
                        elabPattern c pat rhsTy
                      ks <- withPatternRefinements patternRefinements $ do
                        cDef <- case pat of
                          PVar qn -> do
                            rhsV <- evalIn c rhsTm
                            mPj <-
                              if implocal
                                then pure Nothing
                                else projectionInfoOfExpr c rhs
                            mOp <-
                              if implocal
                                then pure Nothing
                                else operationValueInfoOfExpr c rhs
                            let cDef0 =
                                  bindCtxLetProjOp
                                    (nameText qn)
                                    implocal
                                    rhsTy
                                    rhsV
                                    mPj
                                    mOp
                                    c
                            escapes <- escapedRefFacetsExpr c rhs
                            aliasCurrentReadPattern
                              c
                              pat
                              rhs
                              (foldr escapeVarCurrent cDef0 (Set.toList escapes))
                          _ -> pure cBound
                        let cBound' = case (pat, rhs) of
                              -- §7.4.3 stable alias: `let q = p` transports refinement
                              (PVar qn, EVar pn)
                                | Just _ <- lookupCtx (nameText pn) c ->
                                    addCtxAlias (nameText qn) (nameText pn) cDef
                              _ -> cDef
                            c' =
                              markImplicitLocal
                                bsp
                                implocal
                                prefix
                                c
                                cBound'
                        goItems loops c' errT resT rest
                      pure (KLet (qOf (bpQuantity prefix)) patC rhsTm : ks)
        DoLetQ pat0 rhs00 mElse dsp -> do
          (pre, rhs0) <- liftCurrentReadsExpr c (exprSpan rhs00) rhs00
          if not (null pre)
            then goItems loops c errT resT (pre ++ DoLetQ pat0 rhs0 mElse dsp : rest)
            else do
              (pat, rhs) <- rewriteActiveLetQ c pat0 rhs0 dsp
              (rhsTm, rhsTy) <- infer c rhs
              (patC, c', patternRefinements) <-
                elabPattern c pat rhsTy
              mElse' <- forM mElse $ \(rp, fe) -> do
                (rpC, c2, fallbackRefinements) <-
                  elabPattern c rp rhsTy
                feTm <-
                  withPatternRefinements fallbackRefinements $
                    case fe of
                      EDo failLabel failItems failSpan
                        | abruptSuite failItems -> do
                            failKs <-
                              goItemsWith
                                (nameText <$> failLabel)
                                (scopeLabel : enclosingDoScopes)
                                warnReachability
                                False
                                loops
                                c2
                                errT
                                resT
                                failItems
                            pure (CDo (nameText <$> failLabel) failKs)
                      _ -> do
                        voidT <- globalValueM (GName preludeModule "Void") []
                        fallbackTy <- wrapTy errT voidT
                        -- The failure arm has an exact terminal contract.
                        -- Checking it expected-first lets overloaded @pure@,
                        -- @throwError@, and user operations select the
                        -- enclosing carrier before evidence search; inferring
                        -- first would report a spurious ambiguous carrier and
                        -- only then discover the intended @m Void@ mismatch.
                        diagnosticsBefore <- gets (length . csDiags)
                        failureTerm <- check c2 fe fallbackTy
                        retagTerminalFailureArmMismatch diagnosticsBefore
                        pure failureTerm
                pure (rpC, feTm)
              ks <-
                withPatternRefinements patternRefinements $
                  goItems loops c' errT resT rest
              pure (KLetQ patC rhsTm mElse' : ks)
        DoVar n mty rhs0 vsp -> do
          (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
          if not (null pre)
            then goItems loops c errT resT (pre ++ DoVar n mty rhs vsp : rest)
            else do
              mMonadType <- doMonadType errT
              case mMonadType of
                Nothing -> do
                  errAt vsp "E_UNSUPPORTED" (Just "kappa.unsupported.deterministic")
                    "'var' requires a do-block carrier with MonadRef evidence; this pure/non-reference do carrier is not supported for mutable variables (§18.6.1)"
                  goItems loops c errT resT rest
                Just mTy -> do
                  refDict <- requireMonadRef c (nameSpan n) mTy
                  (rhsTm1, rhsTy1) <- case mty of
                    Just tyE -> do
                      (tyTm, _) <- inferType c tyE
                      tyV <- evalIn c tyTm
                      tm <- check c rhs tyV
                      pure (tm, tyV)
                    Nothing -> do
                      tyV <- freshMetaV c
                      tm <- check c rhs tyV
                      pure (tm, tyV)
                  rhsTyTm <- quoteIn c rhsTy1
                  refTy <- monadRefRefType c refDict rhsTyTm
                  escapes <- escapedRefFacetsExpr c rhs
                  loweringW <- builtinIOMonadRefLowering c mTy refDict
                  let newAct = monadRefNewAction refDict rhsTyTm rhsTm1
                      refInfo =
                        VarRefInfo
                          rhsTy1
                          rhsTyTm
                          refDict
                          mTy
                          (monadRefDiagnosticRefType rhsTy1)
                          loweringW
                      c' = foldr escapeVarCurrent (bindCtxVar (nameText n) refTy refInfo c) (Set.toList escapes)
                  recordMutableBindingFields c (nameSpan n) refTy refInfo
                  ks <- goItems loops c' errT resT rest
                  pure (KVarItem (nameText n) rhsTm1 newAct (BuiltinIORefNew <$> loweringW) : ks)
        DoAssign n monadic rhs0 asp -> do
          (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
          if not (null pre)
            then goItems loops c errT resT (pre ++ DoAssign n monadic rhs asp : rest)
            else do
              mref <- pure (lookupCtx (nameText n) c)
              case mref of
                Just (i, entry) -> do
                  case ceVarInfo entry of
                    Just info -> do
                      let evidenceShift = i + 1
                          refDict = shiftTerm evidenceShift 0 (vriMonadRefDict info)
                          aTm = shiftTerm evidenceShift 0 (vriStoredTypeTerm info)
                          a = vriStoredType info
                      let refTm = CVar i
                      rhsActionTy <- actionTypeFor errT (vriMonadType info) a
                      rhsTm <-
                        if monadic
                          then check c (rhs) rhsActionTy
                          else check c (rhs) a
                      escapes <-
                        if monadic
                          then escapedRefFacetsExecutedExpr c rhs
                          else escapedRefFacetsExpr c rhs
                      writes <-
                        if monadic
                          then Set.insert (nameText n) <$> writtenRefFacetsExecutedExpr c rhs
                          else pure (Set.singleton (nameText n))
                      let cAfter = applyVarCurrentEffects writes escapes c
                      ks <- goItems loops cAfter errT resT rest
                      if monadic
                        then do
                          let refTm' = shiftTerm 1 0 refTm
                              aTm' = shiftTerm 1 0 aTm
                              refDict' = shiftTerm 1 0 refDict
                              writeAct = monadRefWriteAction refDict' aTm' refTm' (CVar 0)
                              writeItem = KAssign refTm' False (CVar 0) writeAct (refWriteWitnessFromInfo info)
                          pure (KSubDo Nothing [KBind QW (CPVarM Ordinary "__assign") rhsTm Nothing, writeItem] : ks)
                        else do
                          let writeAct = monadRefWriteAction refDict aTm refTm rhsTm
                          pure (KAssign refTm False rhsTm writeAct (refWriteWitnessFromInfo info) : ks)
                    Nothing -> do
                      errAt asp "E_ASSIGN_NOT_VAR" (Just "kappa-hs.do.assign-non-var")
                        ("'" <> nameText n <> "' is not a mutable var binding (§18.6.1)")
                      goItems loops c errT resT rest
                Nothing -> do
                  if monadic
                    then
                      errAt asp "E_ASSIGN_NOT_VAR" (Just "kappa-hs.do.assign-non-var")
                        ("'" <> nameText n <> " <- ...' is mutable-var assignment syntax; use 'let "
                           <> nameText n <> " <- ...' for monadic bind (§18.2)")
                    else
                      errAt asp "E_NAME_UNRESOLVED" (Just "kappa.name.unresolved")
                        ("unresolved name '" <> nameText n <> "'")
                  goItems loops c errT resT rest
        DoReturn ml me0 rsp -> do
          case me0 of
            Just e0 -> do
              (pre, e) <- liftCurrentReadsExpr c (exprSpan e0) e0
              if not (null pre)
                then goItems loops c errT resT (pre ++ DoReturn ml (Just e) rsp : rest)
                else continueReturn ml (Just e) rsp
            Nothing -> continueReturn ml Nothing rsp
        DoBreak ml bsp -> do
          checkLoopTarget "break" ml bsp
          (KBreak (nameText <$> ml) :) <$> continueAfterAbrupt "break" bsp
        DoContinue ml csp -> do
          checkLoopTarget "continue" ml csp
          (KContinue (nameText <$> ml) :) <$> continueAfterAbrupt "continue" csp
        DoWhile ml cond0 body mels _wsp -> do
          let generatedAction = exprHasCurrentRead c cond0
          cond <- if generatedAction
            then do
              (pre, cond') <- liftCurrentReadsExpr c (exprSpan cond0) cond0
              pure (EDo Nothing (pre ++ [DoExpr cond']) (exprSpan cond0))
            else pure cond0
          -- §18.6: a `while` condition may have type `Bool` or type
          -- `m Bool`; a condition with current-value reads is wrapped as a
          -- nested do action so those reads run once per loop iteration.
          let condD = cond
          boolT <- globalValueM prelBool []
          condTm <-
            if generatedAction
              then do
                boolActionTy <- wrapTy errT boolT
                actTm <- check c condD boolActionTy
                pure (KCondAction actTm)
              else do
                st0 <- get
                n0 <- gets (length . csDiags)
                pureTm <- check c condD boolT
                n1 <- gets (length . csDiags)
                if n1 == n0
                  then pure (KCondPure pureTm)
                  else do
                    put st0
                    boolActionTy <- wrapTy errT boolT
                    actTm <- check c condD boolActionTy
                    pure (KCondAction actTm)
          condWrites <- writtenRefFacetsExecutedExpr c condD
          condEscapes <- case condTm of
            KCondAction {} -> escapedRefFacetsExecutedExpr c condD
            KCondPure {} -> escapedRefFacetsExpr c condD
          let cCond = applyVarCurrentEffects condWrites condEscapes c
          unitT <- globalValueM prelUnit []
          bodyKs <- goItems (withLoop ml) cCond errT unitT body
          elsKs <- traverse (goItems loops cCond errT unitT) mels
          written <- Set.unions . maybeToList <$> traverse (doItemsVarWrites cCond) mels
          bodyWritten <- doItemsVarWrites cCond body
          escaped <- Set.unions . maybeToList <$> traverse (doItemsVarEscapes cCond) mels
          bodyEscaped <- doItemsVarEscapes cCond body
          let cAfter =
                applyVarCurrentEffects
                  (Set.union written bodyWritten)
                  (Set.union escaped bodyEscaped)
                  cCond
          ks <- goItems loops cAfter errT resT rest
          pure (KWhile (nameText <$> ml) condTm bodyKs elsKs : ks)
        DoFor ml pat src0 body mels fsp -> do
          (pre, src) <- liftCurrentReadsExpr c (exprSpan src0) src0
          if not (null pre)
            then goItems loops c errT resT (pre ++ DoFor ml pat src body mels fsp : rest)
            else continueFor ml pat src body mels fsp
        DoIf alts mels isp -> do
          lifted <- liftCurrentReadsStmtIf c alts mels isp
          case lifted of
            Just items -> goItems loops c errT resT (items ++ rest)
            Nothing -> continueIf alts mels isp
        DoDefer ml e0 dsp
          | exprHasCurrentRead c e0 ->
              -- §18.7 schedules the computation value `e0`; it does not
              -- evaluate the deferred action's argument expressions at the
              -- registration site.  Current-value reads therefore belong to a
              -- nested do-scope inside the deferred action, so they run during
              -- unwinding in the action's stored environment.
              continueDefer ml (EDo Nothing [DoExpr e0] (exprSpan e0)) dsp
          | otherwise ->
              continueDefer ml e0 dsp
        DoUsing mq pat rhs0 usp -> do
          (pre, rhs) <- liftCurrentReadsExpr c (exprSpan rhs0) rhs0
          if not (null pre)
            then goItems loops c errT resT (pre ++ DoUsing mq pat rhs usp : rest)
            else continueUsing mq pat rhs usp
        DoDecl d -> do
          case d of
            DLet mods definition dsp
              | Just _ <- ldConstructorPatternCandidate definition -> do
                  selected <- selectConstructorPatternLet c dsp definition
                  case selected of
                    Just (ConstructorPatternCandidate pattern' rhs) ->
                      goItems
                        loops
                        c
                        errT
                        resT
                        ( DoLet
                            ( LetBind
                                False
                                (ldPrefix definition)
                                pattern'
                                (ldResultType definition)
                                rhs
                                dsp
                            )
                            : rest
                        )
                    Nothing ->
                      goItems
                        loops
                        c
                        errT
                        resT
                        ( DoDecl
                            ( DLet
                                mods
                                definition
                                  { ldConstructorPatternCandidate = Nothing
                                  }
                                dsp
                            )
                            : rest
                        )
            DLet _ (LetDef (Just n) _ Nothing _ _ [] mty Nothing rhs) dsp ->
              goItems loops c errT resT (DoLet (LetBind False emptyPrefix (PVar n) mty rhs dsp) : rest)
            DData mods dataDeclaration declarationSpan ->
              withLocalDataDeclaration c mods dataDeclaration declarationSpan $
                goItems loops c errT resT rest
            _ -> do
              unsupportedAt (declSpan d)
                "this local declaration form inside do is not supported by this implementation"
              goItems loops c errT resT rest


-- | Does this do-suite have no normal completion that can reach a following
-- item? This is deliberately conservative: only source forms whose every
-- branch is structurally abrupt are accepted.
abruptSuite :: [DoItem] -> Bool
abruptSuite items = case reverse items of
  (DoReturn {} : _) -> True
  (DoBreak {} : _) -> True
  (DoContinue {} : _) -> True
  (DoExpr e : _) -> abruptExpr e
  (DoIf alts (Just els) _ : _) ->
    all (abruptSuite . snd) alts && abruptSuite els
  _ -> False

-- | Expression counterpart of 'abruptSuite'. Match failure and
-- 'impossible' are non-normal completions too, so exhaustiveness is not a
-- prerequisite here; every explicit arm must nevertheless be abrupt.
abruptExpr :: Expr -> Bool
abruptExpr = \case
  EDo _ inner _ -> abruptSuite inner
  EImpossible {} -> True
  EMatch _ cases _ -> all abruptMatchCase cases
  EIf alts (Just els) _ ->
    all (abruptExpr . snd) alts && abruptExpr els
  EAscription e _ _ -> abruptExpr e
  ECaptures e _ _ -> abruptExpr e
  _ -> False
  where
    abruptMatchCase = \case
      MatchCase _ _ body _ -> abruptExpr body
      MatchImpossible {} -> True

-- | Is the (forced) value headed by an unsolved metavariable?
isFlexHead :: Value -> Bool
isFlexHead = \case
  VFlex {} -> True
  _ -> False

-- | Statement shapes that elaborate soundly by inference, allowing the
-- pure-statement accommodation in 'elabDo' (variants, literals and other
-- expected-type-directed forms keep the plain IO checking path).
statementInferable :: Expr -> Bool
statementInferable = \case
  EApp f _ -> statementInferable f
  EVar {} -> True
  EOpRef {} -> True
  EDot {} -> True
  EQDot {} -> True
  EOpChain {} -> True
  EIf {} -> True
  EMatch {} -> True
  EUnit {} -> True
  ETuple {} -> True
  EIntLit {} -> True
  EFloatLit {} -> True
  EStringLit {} -> True
  _ -> False

data VarInoutTarget = VarInoutTarget
  { vitRoot :: !Name
  , vitPath :: ![Name]
  , vitMutableRoot :: !Bool
  , vitWriteBack :: !VarInoutWriteBack
  , vitSuccessor :: !Text
  , vitTemp :: !Name
  }

data VarInoutWriteBack
  = VarInoutPath
  | VarInoutSection !Expr
  | VarInoutUnsupported !Span

data VarInoutRewriteMode = VarInoutMonadic | VarInoutPure

rewriteVarInoutStatement :: Ctx -> Expr -> CheckM (Maybe [DoItem])
rewriteVarInoutStatement = rewriteVarInoutCall VarInoutMonadic Nothing

rewriteVarInoutBind :: VarInoutRewriteMode -> Ctx -> Pattern -> Expr -> CheckM (Maybe [DoItem])
rewriteVarInoutBind mode ctx pat = rewriteVarInoutCall mode (Just pat) ctx

rewriteVarInoutCall :: VarInoutRewriteMode -> Maybe Pattern -> Ctx -> Expr -> CheckM (Maybe [DoItem])
rewriteVarInoutCall mode mUserPat ctx expr = case expr of
  EApp f args
    | any isInoutArg args -> do
        minfos <- resolvedInoutParams ctx f
        case minfos of
          Nothing -> do
            mapM_ reportUnexpectedInout [sp | ArgInout _ sp <- args]
            pure (Just [])
          Just infos -> rewriteWith infos f args (exprSpan expr)
  EAscription e ty sp -> do
    rewriteVarInoutCall mode mUserPat ctx e >>= \case
      Nothing -> pure Nothing
      Just items -> pure (Just (map (ascribeFirst ty sp) items))
  _ -> pure Nothing
  where
    isInoutArg = \case
      ArgInout {} -> True
      _ -> False

    ascribeFirst ty sp = \case
      DoBind lb -> DoBind lb {lbExpr = EAscription (lbExpr lb) ty sp}
      DoLet lb -> DoLet lb {lbExpr = EAscription (lbExpr lb) ty sp}
      item -> item

    rewriteWith infos f args sp = do
      let annotated = annotateExplicitArgs infos args
      if any unresolvedInout annotated
        then do
          mapM_ reportUnexpectedInout [isp | (ArgInout _ isp, Nothing) <- annotated]
          pure (Just [])
        else do
          targetResults <- forM annotated $ \(arg, mi) -> case (arg, mi) of
            (ArgInout place isp, Just info) -> do
              n0 <- gets (length . csDiags)
              mt <- inoutPlaceTargetM ctx place
              n1 <- gets (length . csDiags)
              pure (arg, mi, (\target -> (info, isp, target)) <$> mt, n1 > n0)
            _ -> pure (arg, mi, Nothing, False)
          let targets0 = [target | (_, _, Just target, _) <- targetResults]
          if length targets0 /= length [() | (ArgInout _ _, _) <- annotated]
            then do
              mapM_
                (\(arg, mi, mt, diagnosed) -> case (arg, mi, mt, diagnosed) of
                    (ArgInout place _, Just _, Nothing, False) -> reportInvalidInoutPlace place
                    _ -> pure ())
                targetResults
              pure (Just [])
            else do
              hasOverlap <- checkVarInoutOverlap targets0
              if hasOverlap
                then pure (Just [])
                else do
                  case [usp | (_, _, (_, _, _, VarInoutUnsupported usp)) <- targets0] of
                    usp : _ -> do
                      errAt usp "E_UNSUPPORTED" (Just "kappa-hs.projection.descriptor")
                        "this '~' projection has multiple possible yielded places; lowering it requires the generic OpenProjector zipper path, which is not implemented yet (§18.9.4, §30.2.2.3)"
                      pure (Just [])
                    [] -> do
                      targets' <- forM targets0 $ \(info, _, (root, path, mutableRoot, writeBack)) -> do
                        tmp <- freshNameM ("__inout_" <> iopSuccessor info)
                        pure (VarInoutTarget root path mutableRoot writeBack (iopSuccessor info) (Name tmp sp))
                      residual <- residualBindItems sp targets' mUserPat
                      res <- freshNameM "__inout_result"
                      let resN = Name res sp
                          callArgs = map stripInout args
                          bind = case mode of
                            VarInoutMonadic ->
                              DoBind $
                                LetBind False emptyPrefix (PVar resN) Nothing (EApp f callArgs) sp
                            VarInoutPure ->
                              DoLet $
                                LetBind False emptyPrefix (PVar resN) Nothing (EApp f callArgs) sp
                          successorLets =
                            [ DoLet $
                                LetBind False emptyPrefix (PVar (vitTemp t)) Nothing
                                  (EDot (EVar resN) (DotName (Name (vitSuccessor t) sp)))
                                  sp
                            | t <- targets'
                            ]
                      assigns <- restoreTargets targets'
                      pure (Just (bind : successorLets ++ assigns ++ residual resN))

    unresolvedInout = \case
      (ArgInout _ _, Nothing) -> True
      _ -> False

    reportUnexpectedInout isp =
      errAt isp "E_QTT_INOUT_MARKER_UNEXPECTED" (Just "kappa-hs.qtt.inout-marker")
        "call-site '~' marker requires resolved inout-parameter metadata at this argument position (§18.9.3)"

    reportInvalidInoutPlace place =
      errAt (exprSpan place) "E_PROJECTION_ROOT_INVALID" (Just "kappa-hs.projection.roots")
        "a '~' inout argument must be a stable place, mutable var-place, or supported projection/accessor place (§18.9.3)"

    stripInout = \case
      ArgInout e _ -> ArgExplicit e
      a -> a

    restoreTargets = fmap concat . mapM restoreGroup . groupTargets
      where
        groupTargets = foldl insertGroup []
        insertGroup [] t = [(vitRoot t, vitMutableRoot t, [t])]
        insertGroup ((root, mutableRoot, ts) : rest) t
          | nameText (vitRoot t) == nameText root
          , vitMutableRoot t == mutableRoot = (root, mutableRoot, ts ++ [t]) : rest
          | otherwise = (root, mutableRoot, ts) : insertGroup rest t
        restoreGroup (_, True, [t])
          | [] <- vitPath t
          , VarInoutPath <- vitWriteBack t =
              pure [DoAssign (vitRoot t) False (EVar (vitTemp t)) (nameSpan (vitRoot t))]
        restoreGroup (_, False, [t])
          | [] <- vitPath t
          , VarInoutPath <- vitWriteBack t =
              pure
                [ DoLet $
                    LetBind False emptyPrefix (PVar (vitRoot t)) Nothing (EVar (vitTemp t)) (nameSpan (vitRoot t))
                ]
        restoreGroup (root, True, ts) = do
          old <- freshNameM ("__inout_old_" <> nameText root)
          let oldN = Name old (nameSpan root)
              rhs =
                ERecordPatch
                  (EVar oldN)
                  [ restorePatchItem oldN t
                  | t <- ts
                  ]
                  (nameSpan root)
          pure
            [ DoBind (LetBind False emptyPrefix (PVar oldN) Nothing (EVarRead root (nameSpan root)) (nameSpan root))
            , DoAssign root False rhs (nameSpan root)
            ]
        restoreGroup (root, False, ts) = do
          let rhs =
                ERecordPatch
                  (EVar root)
                  [ restorePatchItem root t
                  | t <- ts
                  ]
                  (nameSpan root)
          pure
            [ DoLet $
                LetBind False emptyPrefix (PVar root) Nothing rhs (nameSpan root)
            ]

        restorePatchItem baseRoot t =
          case (vitPath t, vitWriteBack t) of
            ([], VarInoutSection recv) -> PatchSection recv (EVar (vitTemp t))
            _ -> PatchUpdate [(False, n) | n <- vitPath t] (restorePatchValue baseRoot t)

        restorePatchValue baseRoot t =
          case vitWriteBack t of
            VarInoutPath -> PatchValue (EVar (vitTemp t))
            VarInoutSection recv ->
              PatchValue $
                ERecordPatch
                  (placeExpr baseRoot (vitPath t))
                  [PatchSection recv (EVar (vitTemp t))]
                  (nameSpan baseRoot)
            VarInoutUnsupported _ -> PatchValue (EVar (vitTemp t))

        placeExpr root path =
          foldl (\acc n -> EDot acc (DotName n)) (EVar root) path

    checkVarInoutOverlap targets =
      case overlapPairs of
        ((startSp, conflictSp) : _) -> do
          report $
            withRelateds
              [ related RoleBorrowStart startSp "place first borrowed by an inout argument here"
              , related RoleBorrowConflict conflictSp "overlapping inout argument here"
              ]
              $ diag SevError StageElaborate "E_QTT_BORROW_OVERLAP" (Just "kappa.borrow.overlap") conflictSp
                  "two '~' inout arguments of the same call have overlapping place footprints (§18.9.3, §12.4)"
          pure True
        [] -> pure False
      where
        overlapPairs =
          [ (isp1, isp2)
              | ((_, isp1, (root1, path1, _, _)), rest') <- zip targets (drop 1 (List.tails targets))
              , (_, isp2, (root2, path2, _, _)) <- rest'
          , nameText root1 == nameText root2
          , pathsOverlapText (map nameText path1) (map nameText path2)
          ]
        pathsOverlapText a b = a `List.isPrefixOf` b || b `List.isPrefixOf` a

    residualBindItems _sp targets mUserPat0 =
      case mUserPat0 of
        Nothing -> pure (\_ -> [])
        Just pat
          | inoutEmptyBindPattern pat -> pure (\_ -> [])
          | otherwise -> do
              validateResidualPattern targets pat
              pure $ \resN ->
                [ DoLet $
                    LetBind False emptyPrefix pat Nothing (EVar resN) (patternSpan pat)
                ]

    validateResidualPattern targets pat = do
      let successorNames = Set.fromList (map vitSuccessor targets)
          rootNames = Set.fromList (map (nameText . vitRoot) targets)
          bound = Set.fromList (map nameText (surfPatVars pat))
          rootConflicts = Set.toList (Set.intersection rootNames bound)
          successorConflicts = residualSuccessorFields successorNames pat
      case rootConflicts of
        n : _ ->
          errAt (patternSpan pat) "E_QTT_INOUT_RESIDUAL_PATTERN" (Just "kappa.inout.restoration")
            ("the residual pattern of an inout call must not bind the marked place '" <> n <> "' (§18.9.4)")
        [] -> pure ()
      case successorConflicts of
        n : _ ->
          errAt (patternSpan pat) "E_QTT_INOUT_RESIDUAL_PATTERN" (Just "kappa.inout.restoration")
            ("the residual pattern of an inout call must not bind threaded successor field '" <> n <> "' (§18.9.4)")
        [] -> pure ()
      unless (residualPatternSupported pat) $
        errAt (patternSpan pat) "E_QTT_INOUT_RESIDUAL_PATTERN" (Just "kappa.inout.restoration")
          "a non-empty residual result of an inout call must be matched with an anonymous record pattern in this implementation (§18.9.4)"
      where
        residualSuccessorFields successors = \case
          PRecord fs mrest _ ->
            [nameText f | (_, f, _) <- fs, nameText f `Set.member` successors]
              ++ case mrest of
                   Just (PatRestBind _) -> [".."]
                   _ -> []
          PTyped p _ _ -> residualSuccessorFields successors p
          _ -> []
        residualPatternSupported = \case
          PRecord _ mrest _ -> case mrest of
            Just (PatRestBind _) -> False
            _ -> True
          PTyped p _ _ -> residualPatternSupported p
          _ -> False

annotateExplicitArgs :: [Maybe InoutParamInfo] -> [Arg] -> [(Arg, Maybe InoutParamInfo)]
annotateExplicitArgs infos = go infos
  where
    go _ [] = []
    go ps (arg : rest) = case arg of
      ArgImplicit _ -> (arg, Nothing) : go ps rest
      ArgNamedBlock {} -> (arg, Nothing) : go ps rest
      ArgExplicit {} -> case ps of
        p : ps' -> (arg, p) : go ps' rest
        [] -> (arg, Nothing) : go [] rest
      ArgInout {} -> case ps of
        p : ps' -> (arg, p) : go ps' rest
        [] -> (arg, Nothing) : go [] rest

resolvedInoutParams :: Ctx -> Expr -> CheckM (Maybe [Maybe InoutParamInfo])
resolvedInoutParams ctx f = do
  st0 <- get
  n0 <- gets (length . csDiags)
  r <- do
    (tm, _) <- infer ctx f
    case headGlobalOf tm of
      Nothing -> pure Nothing
      Just g -> gets (Map.lookup g . csInoutParams)
  n1 <- gets (length . csDiags)
  put st0
  pure (if n1 == n0 then r else Nothing)

inoutPlaceTarget :: Ctx -> Expr -> Maybe (Name, [Name], Bool, VarInoutWriteBack)
inoutPlaceTarget ctx = go []
  where
    go acc = \case
      EVar n
        | Just (_, entry) <- lookupCtx (nameText n) ctx ->
            Just (n, acc, isJust (ceVarInfo entry), VarInoutPath)
      EDot e (DotName fld) -> go (fld : acc) e
      EAscription e _ _ -> go acc e
      _ -> Nothing

inoutPlaceTargetM :: Ctx -> Expr -> CheckM (Maybe (Name, [Name], Bool, VarInoutWriteBack))
inoutPlaceTargetM ctx e =
  case inoutPlaceTarget ctx e of
    Just target -> pure (Just target)
    Nothing -> projectionInoutTarget ctx e

projectionInoutTarget :: Ctx -> Expr -> CheckM (Maybe (Name, [Name], Bool, VarInoutWriteBack))
projectionInoutTarget ctx = \case
  EAscription e _ _ -> projectionInoutTarget ctx e
  EApp f args
    | all isExplicitArg args -> do
        mpj <- projectionInfoOfExpr ctx f
        case mpj of
          Just pj
            | pjSelector pj
            , length args == length (pjIsPlace pj)
            , [(rootName, suffix)] <- nub (pjYields pj)
            , Just rootExpr <- lookup rootName (projectionPlaceArgs pj args) -> do
                inoutPlaceTargetM ctx rootExpr >>= \case
                  Just (root, path, mutableRoot, _) ->
                    let sp = exprSpan rootExpr
                     in pure (Just (root, path ++ [Name fld sp | fld <- suffix], mutableRoot, VarInoutPath))
                  Nothing -> pure Nothing
          Just pj
            | pjSelector pj
            , length args == length (pjIsPlace pj)
            , let yields = nub (pjYields pj)
            , not (null yields)
            , [rootName] <- nub [root | (root, _) <- yields]
            , Just rootExpr <- lookup rootName (projectionPlaceArgs pj args) -> do
                inoutPlaceTargetM ctx rootExpr >>= \case
                  Just (root, path, mutableRoot, _) ->
                    pure (Just (root, path, mutableRoot, VarInoutUnsupported (exprSpan f)))
                  Nothing -> pure Nothing
          Just pj
            | not (pjSelector pj)
            , length args == length (pjIsPlace pj)
            , [(_, rootExpr)] <- projectionPlaceArgs pj args -> do
                mrecv <- accessorInoutSection ctx (exprSpan f) f pj args
                case mrecv of
                  Nothing -> pure Nothing
                  Just recv ->
                    inoutPlaceTargetM ctx rootExpr >>= \case
                      Just (root, path, mutableRoot, _) ->
                        pure (Just (root, path, mutableRoot, VarInoutSection recv))
                      Nothing -> pure Nothing
          _ -> pure Nothing
    | otherwise -> pure Nothing
  _ -> pure Nothing
  where
    isExplicitArg = \case
      ArgExplicit _ -> True
      _ -> False

    projectionPlaceArgs pj args =
      zip (pjPlaceNames pj) [e | (True, ArgExplicit e) <- zip (pjIsPlace pj) args]

    projectionOrdArgs pj args =
      [a | (False, a) <- zip (pjIsPlace pj) args]

    accessorInoutSection ctx0 sp f0 pj args0 = do
      (fTm0, fTy0) <- infer ctx0 f0
      (_dTm, dTy) <- elabSpine ctx0 sp fTm0 fTy0 (projectionOrdArgs pj args0)
      dTyF <- forceM dTy
      mcaps <- case dTyF of
        VRecordT capFs -> bundleCapsM capFs
        _ -> pure Nothing
      case mcaps of
        Just caps
          | "open" `elem` [nm | (nm, _, _) <- caps] ->
              pure (receiverSectionOf f0 (projectionOrdArgs pj args0) sp)
          | otherwise -> do
              errAt (exprSpan f0) "E_PROJECTION_CAPABILITY_REQUIRED" (Just "kappa-hs.projection.capability")
                ( "this use requires the 'open' capability, but the accessor bundle provides only: "
                    <> T.intercalate ", " [nm | (nm, _, _) <- caps] <> " (§16.1.6, §18.9.3)"
                )
              pure Nothing
        Nothing -> pure Nothing

    receiverSectionOf f0 ordArgs sp =
      case receiverMembersOf f0 of
        Just members -> Just (EReceiverSection members ordArgs sp)
        Nothing -> Nothing

    receiverMembersOf = \case
      EVar n -> Just [DotName n]
      EDot base (DotName n) -> (++ [DotName n]) <$> receiverMembersOf base
      EAscription e _ _ -> receiverMembersOf e
      _ -> Nothing

inoutEmptyBindPattern :: Pattern -> Bool
inoutEmptyBindPattern = \case
  PWild _ -> True
  PUnit _ -> True
  _ -> False

-- | §16.3.3: an implicit do-binding @let (\@x : T) = e@ joins the local
-- implicit context for the remaining items. @before@ is the context the
-- pattern was elaborated in; the entries added on top of it are marked.
-- @binderSp@ is the do-binding's source span; for a @\@&@-borrowed
-- implicit local it is recorded as the §3.1.1A introduction origin so a
-- later borrow-escape diagnostic can cite where the candidate was
-- borrowed.
markImplicitLocal :: Span -> Bool -> BinderPrefix -> Ctx -> Ctx -> Ctx
markImplicitLocal _ False _ _ after = after
markImplicitLocal binderSp True (BinderPrefix _ mq mb) before after =
  let es = ctxEntries after
      (new, old) = splitAt (length es - ctxLen before) es
      mark e =
        e
          { ceImplicitLocal = True
          , ceQ = mq
          , ceBorrow = isJust mb
          , ceOrigin = if isJust mb then binderSp else ceOrigin e
          }
   in after {ctxEntries = map mark new ++ old}

-- | Spec §18.3.1 monadic splice (`!`).  The normative elaboration of `!e` is
-- the translation @Splice_m[-]@: a `!e` occurring in a do-item is LIFTED to a
-- monadic bind @tmp <- e@ in the nearest enclosing do-block, and the occurrence
-- is replaced by @tmp@ (`Splice_m[!e] = e`).  Because the lift is a real bind,
-- the spliced result stays MONADIC-typed and left-to-right effect order is
-- preserved.
--
-- This is NOT a pure IO-result extraction.  Extracting `!e` purely was
-- unsound: composed with @throwIO : forall e a. e -> IO e a@ it forges a pure
-- inhabitant of the free @a@.  The bind-lift dissolves this: a bind keeps the
-- item monadic, so @do { !(throwIO Unit) }@ has type @IO _ _@ which is not
-- @Void@ — a plain type error.  It also removes the old synthesized splice-head
-- entirely, so there is no sentinel name a user could spell (via backticks) to
-- route around 'gateUnsafeIntrinsic'.
--
-- 'liftBangsExpr' realizes @Splice_m[-]@ for a single expression: it returns the
-- ordered list of @tmp <- operand@ binds that must be sequenced BEFORE the
-- expression, together with the bang-free residual.  The do-kernels splice those
-- binds in via 'liftDoItems' (the per-do-scope pre-pass).
--
-- Branch-locality (§18.3.1): @Splice_m[if c then t else f] = Splice_m[c] >>= \\c'
-- -> if c' then Splice_m[t] else Splice_m[f]@ — bangs in an /untaken/ branch must
-- NOT run.  So a bang inside an @if@/@match@ branch is NOT hoisted above the
-- conditional; instead the whole conditional is rebuilt with each branch wrapped
-- as a nested @do@ (its own monadic scope) and the conditional itself is bound to
-- a fresh temp.  Only the scrutinee/condition bangs (evaluated unconditionally)
-- are hoisted ahead.

-- | @liftBangsExpr sp e@ = @(binds, residual)@ where @binds@ are @tmp <- act@
-- do-items to sequence before the expression (left-to-right) and @residual@ is
-- @e@ with every (unconditional) splice replaced by its bound temp.  Realizes
-- @Splice_m[-]@.
shortCircuitBoolApp :: Ctx -> Expr -> CheckM (Maybe Expr)
shortCircuitBoolApp ctx e@(EApp f [ArgExplicit l, ArgExplicit r]) = do
  isAnd <- exprResolvesToGlobal ctx f prelAnd
  if isAnd
    then do
      let sp = exprSpan e
      pure (Just (EIf [(l, r)] (Just (EVar (Name "False" sp))) sp))
    else do
      isOr <- exprResolvesToGlobal ctx f prelOr
      if isOr
        then do
          let sp = exprSpan e
          pure (Just (EIf [(l, EVar (Name "True" sp))] (Just r) sp))
        else pure Nothing
shortCircuitBoolApp _ _ = pure Nothing

liftBangsExpr :: Ctx -> Span -> Expr -> CheckM ([DoItem], Expr)
liftBangsExpr ctx _ = go
  where
    -- bind a (residual) computation to a fresh temp and yield the temp
    bindTo :: Span -> Expr -> CheckM ([DoItem], Expr)
    bindTo bsp act = do
      t <- freshNameM "__bang"
      let tn = Name t bsp
      pure ([DoBind (LetBind False emptyPrefix (PVar tn) Nothing act bsp)], EVar tn)

    go :: Expr -> CheckM ([DoItem], Expr)
    go = \case
      -- §18.3.1 splice: `!e` lifts to `tmp <- e`, occurrence becomes `tmp`.
      EBang _ e bsp -> do
        (bs, e') <- go e
        (bs2, t) <- bindTo bsp e'
        pure (bs ++ bs2, t)
      -- §18.3.1 immediate-application splice: an /open/ `!f x y` is sugar for
      -- `!(f x y)` — the whole maximal application spine is the splice operand.
      -- The parser yields @EApp (EBang False f) args@; bind the whole
      -- application `f x y` as the computation.  A /closed/ `(!f) x`
      -- (EBang True) falls through to the ordinary EApp rule below, so `f` is
      -- spliced first and the result applied to `x`.
      EApp (EBang False f bsp) args -> do
        (bsF, f') <- go f
        (bsA, args') <- goArgs args
        (bs2, t) <- bindTo bsp (EApp f' args')
        pure (bsF ++ bsA ++ bs2, t)
      e@(EApp f args) -> do
        shortCircuitBoolApp ctx e >>= \case
          Just e' -> go e'
          Nothing -> do
            (bsF, f') <- go f
            (bsA, args') <- goArgs args
            pure (bsF ++ bsA, EApp f' args')
      EStringLit sl parts lsp -> do
        (bs, parts') <- goInterpParts parts
        pure (bs, EStringLit sl parts' lsp)
      ERecordLit items lsp -> do
        (bs, items') <- goRecItems items
        pure (bs, ERecordLit items' lsp)
      ERecordPatch base items psp -> do
        (bsB, base') <- go base
        (bsI, items') <- goPatchItems items
        pure (bsB ++ bsI, ERecordPatch base' items' psp)
      EQDot e m -> do
        (bs, e') <- go e
        pure (bs, EQDot e' m)
      EOpChain elems -> do
        (bs, elems') <- goOpElems elems
        pure (bs, EOpChain elems')
      EElvis l r esp
        | exprHasBang r -> do
            (bsL, l') <- go l
            tmp <- freshNameM "__elvis"
            let tn = Name tmp esp
                somePat = PCtor (CtorRef Nothing (Name "Some" esp)) [PVar tn] esp
                nonePat = PCtor (CtorRef Nothing (Name "None" esp)) [] esp
                matchE =
                  EMatch
                    l'
                    [ MatchCase somePat Nothing (wrapBranchDo (EVar tn)) esp
                    , MatchCase nonePat Nothing (wrapBranchDo r) esp
                    ]
                    esp
            (bs2, t) <- bindTo esp matchE
            pure (bsL ++ bs2, t)
        | otherwise -> do
            (bsL, l') <- go l
            pure (bsL, EElvis l' r esp)
      -- §18.3.1 conditional: branch-local.  Hoist condition bangs; recurse into
      -- each branch as its own monadic scope.  If NO branch contains a bang the
      -- conditional is left as a pure residual (only its conditions are lifted).
      EIf alts mels esp -> do
        (bsC, ifE, monadic) <- goIfBranches alts mels esp
        if monadic
          then do
            (bs2, t) <- bindTo esp ifE
            pure (bsC ++ bs2, t)
          else pure (bsC, ifE)
      EMatch scrut cases msp
        | any caseHasBang cases -> do
            (bsS, scrut') <- go scrut
            cases' <- traverse wrapCaseDo (lowerGuardedCases scrut' cases msp)
            (bs2, t) <- bindTo msp (EMatch scrut' cases' msp)
            pure (bsS ++ bs2, t)
        | otherwise -> do
            (bsS, scrut') <- go scrut
            pure (bsS, EMatch scrut' cases msp)
      EAscription e t asp -> do
        (bs, e') <- go e
        pure (bs, EAscription e' t asp)
      ETuple es tsp -> do
        (bs, es') <- goList es
        pure (bs, ETuple es' tsp)
      EListLit es lsp -> do
        (bs, es') <- goList es
        pure (bs, EListLit es' lsp)
      ESetLit es ssp -> do
        (bs, es') <- goList es
        pure (bs, ESetLit es' ssp)
      EMapLit kvs msp -> do
        (bs, kvs') <- goPairs kvs
        pure (bs, EMapLit kvs' msp)
      EDot e m -> do
        (bs, e') <- go e
        pure (bs, EDot e' m)
      EIs e cref -> do
        (bs, e') <- go e
        pure (bs, EIs e' cref)
      e@EThunk {} -> pure ([], e)
      e@ELazy {} -> pure ([], e)
      EForce e fsp -> do
        (bs, e') <- go e
        pure (bs, EForce e' fsp)
      ESeal e ty ssp -> do
        (bs, e') <- go e
        pure (bs, ESeal e' ty ssp)
      ESealExists ws e ty ssp -> do
        (bsW, ws') <- goWitnesses ws
        (bsE, e') <- go e
        pure (bsW ++ bsE, ESealExists ws' e' ty ssp)
      ETry e excepts mfin tsp -> do
        (bsE, e') <- go e
        (bsF, mfin') <- goMaybe mfin
        excepts' <- traverse wrapExceptDo excepts
        pure (bsE ++ bsF, ETry e' excepts' mfin' tsp)
      ETryMatch e cases excepts mfin tsp -> do
        (bsE, e') <- go e
        (bsF, mfin') <- goMaybe mfin
        cases' <- traverse wrapCaseDo cases
        excepts' <- traverse wrapExceptDo excepts
        pure (bsE ++ bsF, ETryMatch e' cases' excepts' mfin' tsp)
      EVariant arms mtail vsp -> do
        (bsA, arms') <- goVariantArms arms
        (bsT, mtail') <- goMaybe mtail
        pure (bsA ++ bsT, EVariant arms' mtail' vsp)
      -- any other form: no bang extraction here.  A bang surviving inside an
      -- unsupported form reaches 'infer'/'check' as a bare 'EBang' and is
      -- rejected by the centralized E_SPLICE_OUTSIDE_DO check (§18.3.1: a bang
      -- outside a monadic do-context is ill-formed).
      e -> pure ([], e)

    goArgs :: [Arg] -> CheckM ([DoItem], [Arg])
    goArgs = fmap (\(bs, as) -> (concat bs, as)) . fmap unzip . traverse goArg

    goArg :: Arg -> CheckM ([DoItem], Arg)
    goArg = \case
      ArgExplicit e -> do (bs, e') <- go e; pure (bs, ArgExplicit e')
      ArgImplicit e -> do (bs, e') <- go e; pure (bs, ArgImplicit e')
      ArgInout e asp -> do (bs, e') <- go e; pure (bs, ArgInout e' asp)
      ArgNamedBlock fields asp -> do
        rs <- traverse
          (\(n, me) -> do
              (bs, me') <- goMaybe me
              pure (bs, (n, me')))
          fields
        pure (concatMap fst rs, ArgNamedBlock (map snd rs) asp)

    goList :: [Expr] -> CheckM ([DoItem], [Expr])
    goList es = do
      rs <- traverse go es
      pure (concatMap fst rs, map snd rs)

    goMaybe :: Maybe Expr -> CheckM ([DoItem], Maybe Expr)
    goMaybe = \case
      Nothing -> pure ([], Nothing)
      Just e -> do
        (bs, e') <- go e
        pure (bs, Just e')

    goPairs :: [(Expr, Expr)] -> CheckM ([DoItem], [(Expr, Expr)])
    goPairs kvs = do
      rs <- traverse
        (\(k, v) -> do
            (bsK, k') <- go k
            (bsV, v') <- go v
            pure (bsK ++ bsV, (k', v')))
        kvs
      pure (concatMap fst rs, map snd rs)

    goInterpParts :: [InterpPart] -> CheckM ([DoItem], [InterpPart])
    goInterpParts parts = do
      rs <- traverse
        (\(InterpPart i e) -> do
            (bs, e') <- go e
            pure (bs, InterpPart i e'))
        parts
      pure (concatMap fst rs, map snd rs)

    goRecItems :: [RecItem] -> CheckM ([DoItem], [RecItem])
    goRecItems items = do
      rs <- traverse
        (\it -> do
            (bs, me') <- goMaybe (riValue it)
            pure (bs, it {riValue = me'}))
        items
      pure (concatMap fst rs, map snd rs)

    goPatchItems :: [PatchItem] -> CheckM ([DoItem], [PatchItem])
    goPatchItems items = do
      rs <- traverse goPatchItem items
      pure (concatMap fst rs, map snd rs)

    goPatchItem :: PatchItem -> CheckM ([DoItem], PatchItem)
    goPatchItem = \case
      PatchUpdate path (PatchValue e) -> do
        (bs, e') <- go e
        pure (bs, PatchUpdate path (PatchValue e'))
      PatchExtend n e -> do
        (bs, e') <- go e
        pure (bs, PatchExtend n e')
      PatchSection recv e -> do
        (bsR, recv') <- go recv
        (bsE, e') <- go e
        pure (bsR ++ bsE, PatchSection recv' e')
      PatchPun n -> pure ([], PatchPun n)

    goOpElems :: [OpElem] -> CheckM ([DoItem], [OpElem])
    goOpElems elems = do
      rs <- traverse
        (\case
            ChainOperand e -> do
              (bs, e') <- go e
              pure (bs, ChainOperand e')
            ChainOp n -> pure ([], ChainOp n))
        elems
      pure (concatMap fst rs, map snd rs)

    goWitnesses :: [(Name, Expr)] -> CheckM ([DoItem], [(Name, Expr)])
    goWitnesses ws = do
      rs <- traverse
        (\(n, e) -> do
            (bs, e') <- go e
            pure (bs, (n, e')))
        ws
      pure (concatMap fst rs, map snd rs)

    goVariantArms :: [VariantArm] -> CheckM ([DoItem], [VariantArm])
    goVariantArms arms = do
      rs <- traverse
        (\(VariantArm e mt) -> do
            (bsE, e') <- go e
            (bsT, mt') <- goMaybe mt
            pure (bsE ++ bsT, VariantArm e' mt'))
        arms
      pure (concatMap fst rs, map snd rs)

    -- Conditions are evaluated left-to-right only until a branch is selected.
    -- Binds for later `elif` conditions are therefore inserted into the false
    -- continuation, not hoisted before the whole conditional.
    goIfBranches :: [(Expr, Expr)] -> Maybe Expr -> Span -> CheckM ([DoItem], Expr, Bool)
    goIfBranches [] mels esp = do
      let e = fromMaybe (EUnit esp) mels
      pure ([], e, maybe False exprHasBang mels)
    goIfBranches ((c, t) : rest) mels esp = do
      (bsC, c') <- go c
      (mfalse0, falseMonadic) <- case rest of
        [] -> do
          let elseMonadic = maybe False exprHasBang mels
              melse = (\e -> if elseMonadic then wrapBranchDo e else e) <$> mels
          pure (melse, elseMonadic)
        _ -> do
          (bsRest, restIf, restMonadic) <- goIfBranches rest mels esp
          let falseExpr
                | null bsRest = restIf
                | otherwise = EDo Nothing (bsRest ++ [DoExpr restIf]) (exprSpan restIf)
          pure (Just falseExpr, restMonadic || not (null bsRest))
      let monadic = exprHasBang t || falseMonadic
          t' = if monadic then wrapBranchDo t else t
          mfalse = case mfalse0 of
            Nothing -> Nothing
            Just f
              | monadic && not falseMonadic -> Just (wrapBranchDo f)
              | otherwise -> Just f
      pure (bsC, EIf [(c', t')] mfalse esp, monadic)

    -- wrap a branch result expression as a single-item `do` so 'liftDoItems'
    -- (run over the nested suite later) sequences its bangs in that branch's
    -- own monadic scope.  A bang-free branch is wrapped too; the trivial
    -- one-item do `do { e }` elaborates identically to `e` in the monad.
    wrapBranchDo :: Expr -> Expr
    wrapBranchDo e = EDo Nothing [DoExpr e] (exprSpan e)

    wrapCaseDo :: MatchCase -> CheckM MatchCase
    wrapCaseDo = \case
      MatchCase p g b csp -> pure (MatchCase p g (wrapBranchDo b) csp)
      other -> pure other

    lowerGuardedCases :: Expr -> [MatchCase] -> Span -> [MatchCase]
    lowerGuardedCases scrut cases msp = go cases
      where
        go [] = []
        go (MatchCase p (Just g) b csp : rest) =
          let fallback = EMatch scrut (go rest) msp
           in MatchCase p Nothing (EIf [(g, b)] (Just fallback) csp) csp : go rest
        go (MatchCase p Nothing b csp : rest) = MatchCase p Nothing b csp : go rest
        go (MatchImpossible sp : rest) = MatchImpossible sp : go rest

    wrapExceptDo :: ExceptCase -> CheckM ExceptCase
    wrapExceptDo (ExceptCase p g b csp)
      | maybe False exprHasBang g || exprHasBang b =
          pure (ExceptCase p g (wrapBranchDo b) csp)
      | otherwise =
          pure (ExceptCase p g b csp)

    caseHasBang = \case
      MatchCase _ g b _ -> maybe False exprHasBang g || exprHasBang b
      _ -> False

-- | Does an expression contain a monadic splice `!` that 'liftBangsExpr' would
-- lift in the CURRENT do-scope?  Used to decide whether an @if@/@match@ branch
-- must be hoisted (branch-local sequencing).  It does NOT descend into nested
-- `do`-blocks or lambdas: a `!` there belongs to that inner monadic scope, not
-- this one (§18.3.1: `!` does not cross lambda/do/quote/type boundaries).
exprHasBang :: Expr -> Bool
exprHasBang = go
  where
    go = \case
      EBang {} -> True
      EApp f as -> go f || any goA as
      EStringLit _ parts _ -> any (go . ipExpr) parts
      ERecordLit items _ -> any goRecItem items
      ERecordPatch base items _ -> go base || any goPatchItem items
      EQDot e _ -> go e
      EOpChain elems -> any goOpElem elems
      EElvis l r _ -> go l || go r
      EIf alts mels _ -> any (\(c, t) -> go c || go t) alts || maybe False go mels
      EMatch s cs _ -> go s || any goMatchCase cs
      EAscription e _ _ -> go e
      ETuple es _ -> any go es
      EListLit es _ -> any go es
      ESetLit es _ -> any go es
      EMapLit kvs _ -> any (\(k, v) -> go k || go v) kvs
      EDot e _ -> go e
      EIs e _ -> go e
      EThunk {} -> False
      ELazy {} -> False
      EForce e _ -> go e
      ESeal e _ _ -> go e
      ESealExists ws e _ _ -> any (go . snd) ws || go e
      ETry e excepts mfin _ ->
        go e || any goExcept excepts || maybe False go mfin
      ETryMatch e cases excepts mfin _ ->
        go e || any goMatchCase cases || any goExcept excepts || maybe False go mfin
      -- a `!` under a lambda / nested do / quote belongs to that inner scope.
      _ -> False
    goA = \case
      ArgExplicit e -> go e
      ArgImplicit e -> go e
      ArgInout e _ -> go e
      ArgNamedBlock fields _ -> any (maybe False go . snd) fields
    goRecItem (RecItem _ _ me) = maybe False go me
    goPatchItem = \case
      PatchUpdate _ (PatchValue e) -> go e
      PatchExtend _ e -> go e
      PatchSection recv e -> go recv || go e
      PatchPun _ -> False
    goOpElem = \case
      ChainOperand e -> go e
      ChainOp _ -> False
    goMatchCase = \case
      MatchCase _ mg b _ -> maybe False go mg || go b
      MatchImpossible _ -> False
    goExcept (ExceptCase _ mg b _) = maybe False go mg || go b

-- | Does an expression contain a mutable-variable current-value occurrence for
-- the supplied do-elaboration context?  The shadow set records binders whose
-- source names override outer mutable bindings.
exprHasCurrentRead :: Ctx -> Expr -> Bool
exprHasCurrentRead ctx = go Set.empty
  where
    current shadow n =
      nameText n `Set.notMember` shadow
        && maybe False (isJust . ceVarInfo . snd) (lookupCtx (nameText n) ctx)
    go shadow = \case
      EVar n -> current shadow n
      ERefFacet {} -> False
      EVarRead {} -> False
      EApp f as -> go shadow f || any (goArg shadow) as
      EStringLit _ parts _ -> any (go shadow . ipExpr) parts
      ERecordLit items _ -> any (goRecItem shadow) items
      ERecordPatch base items _ -> go shadow base || any (goPatchItem shadow) items
      EReceiverSection {} -> False
      ESectionLeft {} -> False
      ESectionRight {} -> False
      EQDot e _ -> go shadow e
      EOpChain elems -> any (goOpElem shadow) elems
      EElvis l r _ -> go shadow l || go shadow r
      ELet binds body _ -> goLetBinds shadow binds body
      EBlock decls mres _ -> goBlock shadow decls mres
      EIf alts mels _ -> any (\(c, t) -> go shadow c || go shadow t) alts || maybe False (go shadow) mels
      EMatch s cs _ -> go shadow s || any (goCase shadow) cs
      EHandle _ label scrut cases _ -> go shadow label || go shadow scrut || any (goHandler shadow) cases
      EAscription e _ _ -> go shadow e
      ETuple es _ -> any (go shadow) es
      EListLit es _ -> any (go shadow) es
      ESetLit es _ -> any (go shadow) es
      EMapLit kvs _ -> any (\(k, v) -> go shadow k || go shadow v) kvs
      EDot e _ -> go shadow e
      EIs e _ -> go shadow e
      EThunk {} -> False
      ELazy {} -> False
      EForce e _ -> go shadow e
      ESeal e _ _ -> go shadow e
      EOpenExists pkg ws pat body _ ->
        let shadow' = Set.unions [shadow, Set.fromList (map nameText ws), Set.fromList (map nameText (surfPatVars pat))]
         in go shadow pkg || go shadow' body
      ESealExists ws e _ _ -> any (go shadow . snd) ws || go shadow e
      EComprehension _ clauses yield _ -> goComp shadow clauses yield
      ETry e excepts mfin _ ->
        go shadow e || any (goExcept shadow) excepts || maybe False (go shadow) mfin
      ETryMatch e cases excepts mfin _ ->
        go shadow e || any (goCase shadow) cases || any (goExcept shadow) excepts || maybe False (go shadow) mfin
      EVariant arms mtail _ ->
        any (go shadow . vaExpr) arms || maybe False (go shadow) mtail
      EBang {} -> True
      -- Nested do/lambda/quote/type-like forms own their own lifting context or
      -- are no-read positions (§18.3.1).
      _ -> False
    goArg shadow = \case
      ArgExplicit e -> go shadow e
      ArgImplicit e -> go shadow e
      ArgInout _ _ -> False
      ArgNamedBlock fields _ -> any (maybe False (go shadow) . snd) fields
    goLetBinds shadow [] body = go shadow body
    goLetBinds shadow (LetBind _ _ pat _ rhs _ : rest) body =
      go shadow rhs || goLetBinds (Set.union shadow (Set.fromList (map nameText (surfPatVars pat)))) rest body
    goBlock shadow [] mres = maybe False (go shadow) mres
    goBlock shadow (d : ds) mres = case d of
      DLet _ ld _ ->
        let hasBody
              | null (ldBinders ld) = go shadow (ldBody ld)
              | otherwise = False
            shadow' = Set.union shadow (Set.fromList (map nameText (letDefVars ld)))
         in hasBody || goBlock shadow' ds mres
      _ -> goBlock shadow ds mres
    letDefVars ld =
      maybeToList (ldName ld)
        ++ maybe [] surfPatVars (ldPattern ld)
    goRecItem shadow (RecItem _ _ me) = maybe False (go shadow) me
    goPatchItem shadow = \case
      PatchUpdate _ (PatchValue e) -> go shadow e
      PatchExtend _ e -> go shadow e
      PatchSection recv e -> go shadow recv || go shadow e
      PatchPun _ -> False
    goOpElem shadow = \case
      ChainOperand e -> go shadow e
      ChainOp _ -> False
    goCase shadow = \case
      MatchCase p g b _ ->
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
         in maybe False (go shadow') g || go shadow' b
      MatchImpossible _ -> False
    goHandler shadow = \case
      HandlerReturn p b _ ->
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
         in go shadow' b
      HandlerOp _ ps k b _ ->
        let shadow' = Set.unions (shadow : Set.singleton (nameText k) : map (Set.fromList . map nameText . surfPatVars) ps)
         in go shadow' b
    goExcept shadow (ExceptCase p g b _) =
      let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
       in maybe False (go shadow') g || go shadow' b
    goComp shadow clauses yield =
      let (hit, shadow') = foldl goClause (False, shadow) clauses
       in hit || goYield shadow' yield
    goClause (hit, shadow) = \case
      S.CFor _ _ pat src _ ->
        (hit || go shadow src, Set.union shadow (Set.fromList (map nameText (surfPatVars pat))))
      S.CLet _ pat _ rhs _ ->
        (hit || go shadow rhs, Set.union shadow (Set.fromList (map nameText (surfPatVars pat))))
      S.CIf e -> (hit || go shadow e, shadow)
      S.COrderBy keys _ -> (hit || any (go shadow . snd) keys, shadow)
      S.CSkip e _ -> (hit || go shadow e, shadow)
      S.CTake e _ -> (hit || go shadow e, shadow)
      S.CDistinct me _ -> (hit || maybe False (go shadow) me, shadow)
      S.CGroupBy key aggs into _ ->
        ( hit || go shadow key || any (\(_, e, mu) -> go shadow e || maybe False (go shadow) mu) aggs
        , Set.insert (nameText into) shadow
        )
      S.CJoin _ pat src on into _ ->
        ( hit || go shadow src || go shadow on
        , Set.unions [shadow, Set.fromList (map nameText (surfPatVars pat)), maybe Set.empty (Set.singleton . nameText) into]
        )
    goYield shadow = \case
      YieldExpr e -> go shadow e
      YieldPair k v -> go shadow k || go shadow v

-- | Context-aware companion to 'liftBangsExpr' for §18.6.1 current-value
-- occurrences of surface mutable variables.  Each bare occurrence of a mutable
-- binding in ordinary value position becomes a generated MonadRef.readRef action
-- bound immediately before the residual expression; @ref x@ remains a pure atom.
liftCurrentReadsExpr :: Ctx -> Span -> Expr -> CheckM ([DoItem], Expr)
liftCurrentReadsExpr ctx _ = go Set.empty
  where
    current shadow n =
      nameText n `Set.notMember` shadow
        && maybe False (isJust . ceVarInfo . snd) (lookupCtx (nameText n) ctx)

    bindRead :: Span -> Name -> CheckM ([DoItem], Expr)
    bindRead bsp n = do
      t <- freshNameM "__var"
      let tn = Name t bsp
      pure ([DoBind (LetBind False emptyPrefix (PVar tn) Nothing (EVarRead n bsp) bsp)], EVar tn)

    go :: Set Text -> Expr -> CheckM ([DoItem], Expr)
    go shadow = \case
      EVar n
        | current shadow n -> bindRead (nameSpan n) n
        | otherwise -> pure ([], EVar n)
      e@ERefFacet {} -> pure ([], e)
      e@EVarRead {} -> pure ([], e)
      EBang _ e bsp -> do
        (bs, e') <- go shadow e
        (bs2, t) <- bindToWith "__bang" bsp e'
        pure (bs ++ bs2, t)
      EApp (EBang False f bsp) args -> do
        (bsF, f') <- go shadow f
        args0 <- repairWrongFacet shadow f args
        (bsA, args') <- goArgs shadow args0
        (bs2, t) <- bindToWith "__bang" bsp (EApp f' args')
        pure (bsF ++ bsA ++ bs2, t)
      e@(EApp f args) -> do
        shortCircuitBoolApp ctx e >>= \case
          Just e' -> go shadow e'
          Nothing -> do
            args0 <- repairWrongFacet shadow f args
            (bsF, f') <- go shadow f
            modes <- implicitRuntimeModes shadow f args0
            (bsA, args') <- goArgsWith shadow modes args0
            pure (bsF ++ bsA, EApp f' args')
      EStringLit sl parts lsp -> do
        (bs, parts') <- goInterpParts shadow parts
        pure (bs, EStringLit sl parts' lsp)
      ERecordLit items lsp -> do
        (bs, items') <- goRecItems shadow items
        pure (bs, ERecordLit items' lsp)
      ERecordPatch base items psp -> do
        (bsB, base') <- go shadow base
        (bsI, items') <- goPatchItems shadow items
        pure (bsB ++ bsI, ERecordPatch base' items' psp)
      e@EReceiverSection {} -> pure ([], e)
      e@ESectionLeft {} -> pure ([], e)
      e@ESectionRight {} -> pure ([], e)
      EQDot e m -> do
        (bs, e') <- go shadow e
        pure (bs, EQDot e' m)
      EOpChain elems -> do
        (bs, elems') <- goOpElems shadow elems
        pure (bs, EOpChain elems')
      EElvis l r esp
        | goHas shadow r -> do
            (bsL, l') <- go shadow l
            tmp <- freshNameM "__elvis"
            let tn = Name tmp esp
                somePat = PCtor (CtorRef Nothing (Name "Some" esp)) [PVar tn] esp
                nonePat = PCtor (CtorRef Nothing (Name "None" esp)) [] esp
                matchE =
                  EMatch
                    l'
                    [ MatchCase somePat Nothing (wrapBranchDo (EVar tn)) esp
                    , MatchCase nonePat Nothing (wrapBranchDo r) esp
                    ]
                    esp
            (bs2, t) <- bindTo esp matchE
            pure (bsL ++ bs2, t)
        | otherwise -> do
            (bsL, l') <- go shadow l
            pure (bsL, EElvis l' r esp)
      EIf alts mels esp -> do
        (bsC, ifE, monadic) <- goIfBranches shadow alts mels esp
        if monadic
          then do
            (bs2, t) <- bindTo esp ifE
            pure (bsC ++ bs2, t)
          else pure (bsC, ifE)
      ELet binds body lsp -> do
        (bsB, binds', shadow') <- goLetBinds shadow binds
        (bsBody, body') <- go shadow' body
        pure (bsB ++ bsBody, ELet binds' body' lsp)
      EBlock decls mres bsp -> do
        (bsD, decls', shadow') <- goBlockDecls shadow decls
        (bsR, mres') <- goMaybe shadow' mres
        pure (bsD ++ bsR, EBlock decls' mres' bsp)
      EMatch scrut cases msp
        | any (caseHasCurrentRead shadow) cases -> do
            (bsS, scrut') <- go shadow scrut
            let cases' = map wrapCaseDo (lowerGuardedCases scrut' cases msp)
            (bs2, t) <- bindTo msp (EMatch scrut' cases' msp)
            pure (bsS ++ bs2, t)
        | otherwise -> do
            (bsS, scrut') <- go shadow scrut
            pure (bsS, EMatch scrut' cases msp)
      EAscription e t asp -> do
        (bs, e') <- go shadow e
        pure (bs, EAscription e' t asp)
      ETuple es tsp -> do
        (bs, es') <- goList shadow es
        pure (bs, ETuple es' tsp)
      EListLit es lsp -> do
        (bs, es') <- goList shadow es
        pure (bs, EListLit es' lsp)
      ESetLit es ssp -> do
        (bs, es') <- goList shadow es
        pure (bs, ESetLit es' ssp)
      EMapLit kvs msp -> do
        (bs, kvs') <- goPairs shadow kvs
        pure (bs, EMapLit kvs' msp)
      EDot e m -> do
        (bs, e') <- go shadow e
        pure (bs, EDot e' m)
      EIs e cref -> do
        (bs, e') <- go shadow e
        pure (bs, EIs e' cref)
      EHandle deep label scrut cases hsp -> do
        (bsL, label') <- go shadow label
        (bsS, scrut') <- go shadow scrut
        cases' <- traverse (goHandlerCase shadow) cases
        pure (bsL ++ bsS, EHandle deep label' scrut' cases' hsp)
      e@EThunk {} -> pure ([], e)
      e@ELazy {} -> pure ([], e)
      EForce e fsp -> do
        (bs, e') <- go shadow e
        pure (bs, EForce e' fsp)
      ESeal e ty ssp -> do
        (bs, e') <- go shadow e
        pure (bs, ESeal e' ty ssp)
      EOpenExists pkg ws pat body osp -> do
        (bsPkg, pkg') <- go shadow pkg
        let shadow' = Set.unions [shadow, Set.fromList (map nameText ws), Set.fromList (map nameText (surfPatVars pat))]
        body' <- wrapBodyDo shadow' body
        pure (bsPkg, EOpenExists pkg' ws pat body' osp)
      ESealExists ws e ty ssp -> do
        (bsW, ws') <- goWitnesses shadow ws
        (bsE, e') <- go shadow e
        pure (bsW ++ bsE, ESealExists ws' e' ty ssp)
      EComprehension kind clauses yield csp -> do
        (bsC, clauses', shadow') <- goCompClauses shadow clauses
        (bsY, yield') <- goCompYield shadow' yield
        pure (bsC ++ bsY, EComprehension kind clauses' yield' csp)
      ETry e excepts mfin tsp -> do
        (bsE, e') <- go shadow e
        mfin' <- traverse (wrapBodyDo shadow) mfin
        let excepts' = map (wrapExceptDo shadow) excepts
        pure (bsE, ETry e' excepts' mfin' tsp)
      ETryMatch e cases excepts mfin tsp -> do
        (bsE, e') <- go shadow e
        mfin' <- traverse (wrapBodyDo shadow) mfin
        let cases' = map wrapCaseDo cases
            excepts' = map (wrapExceptDo shadow) excepts
        pure (bsE, ETryMatch e' cases' excepts' mfin' tsp)
      EVariant arms mtail vsp -> do
        (bsA, arms') <- goVariantArms shadow arms
        (bsT, mtail') <- goMaybe shadow mtail
        pure (bsA ++ bsT, EVariant arms' mtail' vsp)
      e -> pure ([], e)

    bindTo :: Span -> Expr -> CheckM ([DoItem], Expr)
    bindTo = bindToWith "__var"

    bindToWith :: Text -> Span -> Expr -> CheckM ([DoItem], Expr)
    bindToWith prefix bsp act = do
      t <- freshNameM prefix
      let tn = Name t bsp
      pure ([DoBind (LetBind False emptyPrefix (PVar tn) Nothing act bsp)], EVar tn)

    repairWrongFacet :: Set Text -> Expr -> [Arg] -> CheckM [Arg]
    repairWrongFacet shadow f args = do
      st0 <- get
      let (headArgs, _) = span isImplicitArg args
      resolvedRefHead f headArgs >>= \case
        Nothing -> pure args
        Just api -> do
          before <- gets (length . csDiags)
          rewritten <- rewriteRefArg api args
          after <- gets (length . csDiags)
          if after > before
            then pure rewritten
            else put st0 >> pure args
      where
        isImplicitArg = \case
          ArgImplicit {} -> True
          _ -> False

        rewriteRefArg _ [] = pure []
        rewriteRefArg api (ArgImplicit e : rest) =
          (ArgImplicit e :) <$> rewriteRefArg api rest
        rewriteRefArg api (ArgExplicit e : rest)
          | Just (n, rebuild) <- currentRefArg e = do
              matches <- refHeadMatchesMutable n api
              if matches
                then do
                  infoFields <- mutableBindingLookupFields ctx n "user-written"
                  errMutableBinding
                    (nameSpan n)
                    "E_VAR_REF_REQUIRED"
                    (nameText n)
                    "current-value"
                    ( infoFields
                        ++ [ ("sourceOperation", fst api)
                           , ("repair", "ref " <> nameText n)
                           ]
                    )
                    ( "'" <> nameText n <> "' is a mutable variable's current-value facet here; "
                        <> fst api <> " requires the reference facet, written 'ref "
                        <> nameText n <> "' (§18.6.1)"
                    )
                  pure (ArgExplicit (rebuild (ERefFacet n (nameSpan n))) : rest)
                else (ArgExplicit e :) <$> rewriteRefArg api rest
        rewriteRefArg _ args0 = pure args0

        currentRefArg = \case
          EVar n
            | current shadow n -> Just (n, id)
          EAscription e ty sp ->
            (\(n, rebuild) -> (n, \r -> EAscription (rebuild r) ty sp)) <$> currentRefArg e
          _ -> Nothing

    resolvedRefHead :: Expr -> [Arg] -> CheckM (Maybe (Text, RefOpEvidence))
    resolvedRefHead f headArgs =
      fmap refHead <$> resolveRefOpExpr ctx f headArgs

    refHead :: (ExplicitRefOp, RefOpEvidence) -> (Text, RefOpEvidence)
    refHead = \case
      (ExplicitRefRead, ev) -> ("readRef", ev)
      (ExplicitRefWrite, ev) -> ("writeRef", ev)

    refHeadMatchesMutable :: Name -> (Text, RefOpEvidence) -> CheckM Bool
    refHeadMatchesMutable n (_, evidence) =
      case lookupCtx (nameText n) ctx of
        Just (i, entry)
          | Just info <- ceVarInfo entry -> do
              let expected0 = shiftTerm (i + 1) 0 (vriMonadRefDict info)
              refEvidenceMatchesCarrierDict ctx (vriMonadType info) expected0 evidence
        _ -> pure False

    goArgs shadow = fmap (\(bs, as) -> (concat bs, as)) . fmap unzip . traverse (goArg shadow)
    goArgsWith shadow modes args =
      fmap (\(bs, as) -> (concat bs, as)) . fmap unzip $
        traverse (uncurry (goArgWith shadow)) (zip (modes ++ repeat False) args)
    goArg shadow = \case
      ArgExplicit e -> do (bs, e') <- go shadow e; pure (bs, ArgExplicit e')
      ArgImplicit e -> pure ([], ArgImplicit e)
      ArgInout e asp -> pure ([], ArgInout e asp)
      ArgNamedBlock fields asp -> do
        rs <- traverse
          (\(n, me) -> do
              (bs, me') <- goMaybe shadow me
              pure (bs, (n, me')))
          fields
        pure (concatMap fst rs, ArgNamedBlock (map snd rs) asp)
    goArgWith shadow mode = \case
      ArgImplicit e
        | mode -> do (bs, e') <- go shadow e; pure (bs, ArgImplicit e')
        | otherwise -> pure ([], ArgImplicit e)
      a -> goArg shadow a

    implicitRuntimeModes :: Set Text -> Expr -> [Arg] -> CheckM [Bool]
    implicitRuntimeModes shadow f args = do
      st0 <- get
      n0 <- gets (length . csDiags)
      modes <- do
        mfTy <- calleeRuntimeType shadow f
        maybe (pure (map (const False) args)) (`goTy` args) mfTy
      n1 <- gets (length . csDiags)
      put st0
      pure $
        if n1 == n0
          then modes
          else map (const False) args
      where
        calleeRuntimeType sh = \case
          EVar n
            | current sh n
            , Just (_, entry) <- lookupCtx (nameText n) ctx
            , Just info <- ceVarInfo entry ->
                pure (Just (vriStoredType info))
          EAscription _ ty _ -> do
            (tyTm, _) <- inferType ctx ty
            Just <$> evalIn ctx tyTm
          ECaptures e _ _ -> calleeRuntimeType sh e
          e -> do
            (_fTm, fTy) <- infer ctx e
            pure (Just fTy)

        goTy _ [] = pure []
        goTy ty0 as@(a : rest) = do
          ty <- forceM ty0
          case ty of
            VPi Impl q _ _ _dom clo -> case a of
              ArgImplicit _ -> do
                v <- freshMetaV ctx
                ty' <- clApp clo v
                ((q /= Q0) :) <$> goTy ty' rest
              _ -> do
                v <- freshMetaV ctx
                ty' <- clApp clo v
                goTy ty' as
            VPi Expl _ _ _ _dom clo -> do
              v <- freshMetaV ctx
              ty' <- clApp clo v
              (False :) <$> goTy ty' rest
            _ -> pure (map (const False) as)

    goList shadow es = do
      rs <- traverse (go shadow) es
      pure (concatMap fst rs, map snd rs)
    goMaybe shadow = \case
      Nothing -> pure ([], Nothing)
      Just e -> do
        (bs, e') <- go shadow e
        pure (bs, Just e')
    goPairs shadow kvs = do
      rs <- traverse
        (\(k, v) -> do
            (bsK, k') <- go shadow k
            (bsV, v') <- go shadow v
            pure (bsK ++ bsV, (k', v')))
        kvs
      pure (concatMap fst rs, map snd rs)
    goInterpParts shadow parts = do
      rs <- traverse
        (\(InterpPart i e) -> do
            (bs, e') <- go shadow e
            pure (bs, InterpPart i e'))
        parts
      pure (concatMap fst rs, map snd rs)
    goRecItems shadow items = do
      rs <- traverse
        (\it -> do
            (bs, me') <- goMaybe shadow (riValue it)
            pure (bs, it {riValue = me'}))
        items
      pure (concatMap fst rs, map snd rs)
    goPatchItems shadow items = do
      rs <- traverse (goPatchItem shadow) items
      pure (concatMap fst rs, map snd rs)
    goPatchItem shadow = \case
      PatchUpdate path (PatchValue e) -> do
        (bs, e') <- go shadow e
        pure (bs, PatchUpdate path (PatchValue e'))
      PatchExtend n e -> do
        (bs, e') <- go shadow e
        pure (bs, PatchExtend n e')
      PatchSection recv e -> do
        (bsR, recv') <- go shadow recv
        (bsE, e') <- go shadow e
        pure (bsR ++ bsE, PatchSection recv' e')
      PatchPun n -> pure ([], PatchPun n)
    goOpElems shadow elems = do
      rs <- traverse
        (\case
            ChainOperand e -> do
              (bs, e') <- go shadow e
              pure (bs, ChainOperand e')
            ChainOp n -> pure ([], ChainOp n))
        elems
      pure (concatMap fst rs, map snd rs)
    goWitnesses shadow ws = do
      rs <- traverse
        (\(n, e) -> do
            (bs, e') <- go shadow e
            pure (bs, (n, e')))
        ws
      pure (concatMap fst rs, map snd rs)
    goVariantArms shadow arms = do
      rs <- traverse
        (\(VariantArm e mt) -> do
            (bsE, e') <- go shadow e
            (bsT, mt') <- goMaybe shadow mt
            pure (bsE ++ bsT, VariantArm e' mt'))
        arms
      pure (concatMap fst rs, map snd rs)

    goLetBinds shadow [] = pure ([], [], shadow)
    goLetBinds shadow (LetBind im pf pat ty rhs bsp : rest) = do
      (bsR, rhs') <- go shadow rhs
      let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars pat)))
      (bsRest, rest', shadowFinal) <- goLetBinds shadow' rest
      pure (bsR ++ bsRest, LetBind im pf pat ty rhs' bsp : rest', shadowFinal)

    goBlockDecls shadow [] = pure ([], [], shadow)
    goBlockDecls shadow (d : ds) = case d of
      DLet mods ld sp
        | null (ldBinders ld) -> do
            (bs, body') <- go shadow (ldBody ld)
            let ld' = ld {ldBody = body'}
                shadow' = Set.union shadow (Set.fromList (map nameText (letDefVars ld)))
            (bsRest, ds', shadowFinal) <- goBlockDecls shadow' ds
            pure (bs ++ bsRest, DLet mods ld' sp : ds', shadowFinal)
        | otherwise -> do
            let shadow' = Set.union shadow (Set.fromList (map nameText (letDefVars ld)))
            (bsRest, ds', shadowFinal) <- goBlockDecls shadow' ds
            pure (bsRest, d : ds', shadowFinal)
      _ -> do
        (bsRest, ds', shadowFinal) <- goBlockDecls shadow ds
        pure (bsRest, d : ds', shadowFinal)

    letDefVars ld =
      maybeToList (ldName ld)
        ++ maybe [] surfPatVars (ldPattern ld)

    wrapBodyDo shadow body
      | goHas shadow body = do
          (bs, body') <- go shadow body
          pure (EDo Nothing (bs ++ [DoExpr body']) (exprSpan body))
      | otherwise = pure body

    goHandlerCase shadow = \case
      HandlerReturn pat body hsp -> do
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars pat)))
        body' <- wrapBodyDo shadow' body
        pure (HandlerReturn pat body' hsp)
      HandlerOp op pats k body hsp -> do
        let shadow' = Set.unions (shadow : Set.singleton (nameText k) : map (Set.fromList . map nameText . surfPatVars) pats)
        body' <- wrapBodyDo shadow' body
        pure (HandlerOp op pats k body' hsp)

    goCompClauses shadow [] = pure ([], [], shadow)
    goCompClauses shadow (cl : rest) = do
      (bs, cl', shadow') <- goCompClause shadow cl
      (bsRest, rest', shadowFinal) <- goCompClauses shadow' rest
      pure (bs ++ bsRest, cl' : rest', shadowFinal)

    goCompClause shadow = \case
      S.CFor ref borrowed pat src csp -> do
        (bs, src') <- go shadow src
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars pat)))
        pure (bs, S.CFor ref borrowed pat src' csp, shadow')
      S.CLet ref pat mty rhs csp -> do
        (bs, rhs') <- go shadow rhs
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars pat)))
        pure (bs, S.CLet ref pat mty rhs' csp, shadow')
      S.CIf e -> do
        (bs, e') <- go shadow e
        pure (bs, S.CIf e', shadow)
      S.COrderBy keys csp -> do
        rs <- traverse (\(desc, e) -> do (bs, e') <- go shadow e; pure (bs, (desc, e'))) keys
        pure (concatMap fst rs, S.COrderBy (map snd rs) csp, shadow)
      S.CSkip e csp -> do
        (bs, e') <- go shadow e
        pure (bs, S.CSkip e' csp, shadow)
      S.CTake e csp -> do
        (bs, e') <- go shadow e
        pure (bs, S.CTake e' csp, shadow)
      S.CDistinct me csp -> do
        (bs, me') <- goMaybe shadow me
        pure (bs, S.CDistinct me' csp, shadow)
      S.CGroupBy key aggs into csp -> do
        (bsK, key') <- go shadow key
        rs <-
          traverse
            (\(n, e, mu) -> do
                (bsE, e') <- go shadow e
                (bsU, mu') <- goMaybe shadow mu
                pure (bsE ++ bsU, (n, e', mu')))
            aggs
        pure (bsK ++ concatMap fst rs, S.CGroupBy key' (map snd rs) into csp, Set.insert (nameText into) shadow)
      S.CJoin left pat src on into csp -> do
        (bsS, src') <- go shadow src
        (bsO, on') <- go shadow on
        let shadow' = Set.unions [shadow, Set.fromList (map nameText (surfPatVars pat)), maybe Set.empty (Set.singleton . nameText) into]
        pure (bsS ++ bsO, S.CJoin left pat src' on' into csp, shadow')

    goCompYield shadow = \case
      YieldExpr e -> do
        (bs, e') <- go shadow e
        pure (bs, YieldExpr e')
      YieldPair k v -> do
        (bsK, k') <- go shadow k
        (bsV, v') <- go shadow v
        pure (bsK ++ bsV, YieldPair k' v')

    goIfBranches shadow [] mels esp = do
      let e = fromMaybe (EUnit esp) mels
      pure ([], e, maybe False (goHas shadow) mels)
    goIfBranches shadow ((c, t) : rest) mels esp = do
      (bsC, c') <- go shadow c
      (mfalse0, falseMonadic) <- case rest of
        [] -> do
          let elseMonadic = maybe False (goHas shadow) mels
              melse = (\e -> if elseMonadic then wrapBranchDo e else e) <$> mels
          pure (melse, elseMonadic)
        _ -> do
          (bsRest, restIf, restMonadic) <- goIfBranches shadow rest mels esp
          let falseExpr
                | null bsRest = restIf
                | otherwise = EDo Nothing (bsRest ++ [DoExpr restIf]) (exprSpan restIf)
          pure (Just falseExpr, restMonadic || not (null bsRest))
      let monadic = goHas shadow t || falseMonadic
          t' = if monadic then wrapBranchDo t else t
          mfalse = case mfalse0 of
            Nothing -> Nothing
            Just f
              | monadic && not falseMonadic -> Just (wrapBranchDo f)
              | otherwise -> Just f
      pure (bsC, EIf [(c', t')] mfalse esp, monadic)

    wrapBranchDo e = EDo Nothing [DoExpr e] (exprSpan e)
    caseHasCurrentRead shadow = \case
      MatchCase p g b _ ->
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
         in maybe False (exprHasCurrentReadIn shadow') g || exprHasCurrentReadIn shadow' b
      MatchImpossible _ -> False
    exprHasCurrentReadIn shadow = goHas shadow
    goHas shadow = \case
      EVar n -> current shadow n
      ERefFacet {} -> False
      EVarRead {} -> False
      EApp f as -> goHas shadow f || any (goHasArg shadow) as
      EStringLit _ parts _ -> any (goHas shadow . ipExpr) parts
      ERecordLit items _ -> any (\(RecItem _ _ me) -> maybe False (goHas shadow) me) items
      ERecordPatch base items _ -> goHas shadow base || any (goHasPatch shadow) items
      EReceiverSection {} -> False
      ESectionLeft {} -> False
      ESectionRight {} -> False
      EQDot e _ -> goHas shadow e
      EOpChain elems -> any (\case ChainOperand e -> goHas shadow e; ChainOp _ -> False) elems
      EElvis l r _ -> goHas shadow l || goHas shadow r
      ELet binds body _ -> goHasLetBinds shadow binds body
      EBlock decls mres _ -> goHasBlock shadow decls mres
      EIf alts mels _ -> any (\(c, t) -> goHas shadow c || goHas shadow t) alts || maybe False (goHas shadow) mels
      EMatch s cs _ -> goHas shadow s || any (caseHasCurrentRead shadow) cs
      EHandle _ label scrut cases _ -> goHas shadow label || goHas shadow scrut || any (goHasHandler shadow) cases
      EAscription e _ _ -> goHas shadow e
      ETuple es _ -> any (goHas shadow) es
      EListLit es _ -> any (goHas shadow) es
      ESetLit es _ -> any (goHas shadow) es
      EMapLit kvs _ -> any (\(k, v) -> goHas shadow k || goHas shadow v) kvs
      EDot e _ -> goHas shadow e
      EIs e _ -> goHas shadow e
      EThunk {} -> False
      ELazy {} -> False
      EForce e _ -> goHas shadow e
      ESeal e _ _ -> goHas shadow e
      EOpenExists pkg ws pat body _ ->
        let shadow' = Set.unions [shadow, Set.fromList (map nameText ws), Set.fromList (map nameText (surfPatVars pat))]
         in goHas shadow pkg || goHas shadow' body
      ESealExists ws e _ _ -> any (goHas shadow . snd) ws || goHas shadow e
      EComprehension _ clauses yield _ -> goHasComp shadow clauses yield
      ETry e excepts mfin _ -> goHas shadow e || any (goHasExcept shadow) excepts || maybe False (goHas shadow) mfin
      ETryMatch e cases excepts mfin _ -> goHas shadow e || any (caseHasCurrentRead shadow) cases || any (goHasExcept shadow) excepts || maybe False (goHas shadow) mfin
      EVariant arms mtail _ -> any (goHas shadow . vaExpr) arms || maybe False (goHas shadow) mtail
      EBang {} -> True
      _ -> False
    goHasArg shadow = \case
      ArgExplicit e -> goHas shadow e
      ArgImplicit e -> goHas shadow e
      ArgInout _ _ -> False
      ArgNamedBlock fields _ -> any (maybe False (goHas shadow) . snd) fields
    goHasLetBinds shadow [] body = goHas shadow body
    goHasLetBinds shadow (LetBind _ _ pat _ rhs _ : rest) body =
      goHas shadow rhs || goHasLetBinds (Set.union shadow (Set.fromList (map nameText (surfPatVars pat)))) rest body
    goHasBlock shadow [] mres = maybe False (goHas shadow) mres
    goHasBlock shadow (d : ds) mres = case d of
      DLet _ ld _ ->
        let hasBody
              | null (ldBinders ld) = goHas shadow (ldBody ld)
              | otherwise = False
            shadow' = Set.union shadow (Set.fromList (map nameText (letDefVars ld)))
         in hasBody || goHasBlock shadow' ds mres
      _ -> goHasBlock shadow ds mres
    goHasPatch shadow = \case
      PatchUpdate _ (PatchValue e) -> goHas shadow e
      PatchExtend _ e -> goHas shadow e
      PatchSection recv e -> goHas shadow recv || goHas shadow e
      PatchPun _ -> False
    goHasExcept shadow (ExceptCase p g b _) =
      let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
       in maybe False (goHas shadow') g || goHas shadow' b
    goHasHandler shadow = \case
      HandlerReturn p b _ ->
        let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
         in goHas shadow' b
      HandlerOp _ ps k b _ ->
        let shadow' = Set.unions (shadow : Set.singleton (nameText k) : map (Set.fromList . map nameText . surfPatVars) ps)
         in goHas shadow' b
    goHasComp shadow clauses yield =
      let (hit, shadow') = foldl goHasClause (False, shadow) clauses
       in hit || goHasYield shadow' yield
    goHasClause (hit, shadow) = \case
      S.CFor _ _ pat src _ ->
        (hit || goHas shadow src, Set.union shadow (Set.fromList (map nameText (surfPatVars pat))))
      S.CLet _ pat _ rhs _ ->
        (hit || goHas shadow rhs, Set.union shadow (Set.fromList (map nameText (surfPatVars pat))))
      S.CIf e -> (hit || goHas shadow e, shadow)
      S.COrderBy keys _ -> (hit || any (goHas shadow . snd) keys, shadow)
      S.CSkip e _ -> (hit || goHas shadow e, shadow)
      S.CTake e _ -> (hit || goHas shadow e, shadow)
      S.CDistinct me _ -> (hit || maybe False (goHas shadow) me, shadow)
      S.CGroupBy key aggs into _ ->
        ( hit || goHas shadow key || any (\(_, e, mu) -> goHas shadow e || maybe False (goHas shadow) mu) aggs
        , Set.insert (nameText into) shadow
        )
      S.CJoin _ pat src on into _ ->
        ( hit || goHas shadow src || goHas shadow on
        , Set.unions [shadow, Set.fromList (map nameText (surfPatVars pat)), maybe Set.empty (Set.singleton . nameText) into]
        )
    goHasYield shadow = \case
      YieldExpr e -> goHas shadow e
      YieldPair k v -> goHas shadow k || goHas shadow v
    lowerGuardedCases :: Expr -> [MatchCase] -> Span -> [MatchCase]
    lowerGuardedCases scrut cases msp = goCases cases
      where
        goCases [] = []
        goCases (MatchCase p (Just g) b csp : rest) =
          let fallback = EMatch scrut (goCases rest) msp
           in MatchCase p Nothing (EIf [(g, b)] (Just fallback) csp) csp : goCases rest
        goCases (MatchCase p Nothing b csp : rest) = MatchCase p Nothing b csp : goCases rest
        goCases (MatchImpossible sp : rest) = MatchImpossible sp : goCases rest
    wrapCaseDo = \case
      MatchCase p g b csp -> MatchCase p g (wrapBranchDo b) csp
      other -> other
    wrapExceptDo shadow ex@(ExceptCase p g b csp) =
      let shadow' = Set.union shadow (Set.fromList (map nameText (surfPatVars p)))
       in if goHas shadow' b then ExceptCase p g (wrapBranchDo b) csp else ex

liftCurrentReadsStmtIf :: Ctx -> [(Expr, [DoItem])] -> Maybe [DoItem] -> Span -> CheckM (Maybe [DoItem])
liftCurrentReadsStmtIf ctx alts mels isp = do
  (changed, items) <- go alts mels
  pure (if changed then Just items else Nothing)
  where
    go [] mElse = pure (False, fromMaybe [] mElse)
    go ((cond, body) : rest) mElse = do
      (pre, cond') <- liftCurrentReadsExpr ctx (exprSpan cond) cond
      (falseChanged, falseItems) <- case rest of
        [] -> pure (False, mElse)
        _ -> do
          (ch, items) <- go rest mElse
          pure (ch, Just items)
      let changed = not (null pre) || falseChanged
      pure (changed, pre ++ [DoIf [(cond', body)] falseItems isp])

-- | Spec §18.3.1 pre-pass: lift every monadic splice `!` in a do-scope's item
-- list to a preceding @tmp <- act@ bind.  Run once per do-scope (each kernel,
-- below) so that no 'EBang' reaches term elaboration except one that is genuinely
-- outside a monadic context (rejected by E_SPLICE_OUTSIDE_DO).
--
-- Each item's bang-binds are spliced in immediately before the item, in
-- left-to-right operand order.  Nested do-suites carried inside @while@/@for@/
-- statement-@if@ are RE-LIFTED in their own scope (so a bang inside a loop body
-- runs each iteration, not once before the loop).
liftDoItems :: Ctx -> [DoItem] -> CheckM [DoItem]
liftDoItems ctx = fmap concat . traverse liftOne
  where
    -- lift one item: `pre ++ [item']` where `pre` are the hoisted binds.
    liftOne :: DoItem -> CheckM [DoItem]
    liftOne item = case item of
      DoExpr e -> withPre e $ \e' -> pure [DoExpr e']
      DoBind (LetBind im pf pat ty rhs bsp) ->
        withPre rhs $ \rhs' -> pure [DoBind (LetBind im pf pat ty rhs' bsp)]
      DoLet (LetBind im pf pat ty rhs bsp) ->
        withPre rhs $ \rhs' -> pure [DoLet (LetBind im pf pat ty rhs' bsp)]
      DoLetQ pat rhs mElse dsp ->
        withPre rhs $ \rhs' -> pure [DoLetQ pat rhs' mElse dsp]
      DoAssign n monadic rhs asp ->
        withPre rhs $ \rhs' -> pure [DoAssign n monadic rhs' asp]
      DoVar n mty rhs vsp ->
        withPre rhs $ \rhs' -> pure [DoVar n mty rhs' vsp]
      DoDefer ml e dsp
        | exprHasBang e ->
            -- `defer e` stores `e` as an action (§18.7/§18.8.8).  Splices
            -- inside that action are part of the action's execution, not the
            -- registration step, so give them an inner do-scope instead of
            -- hoisting them before the `defer` item.
            pure [DoDefer ml (EDo Nothing [DoExpr e] (exprSpan e)) dsp]
        | otherwise ->
            pure [DoDefer ml e dsp]
      DoUsing mq pat rhs usp ->
        withPre rhs $ \rhs' -> pure [DoUsing mq pat rhs' usp]
      DoReturn ml (Just e) rsp ->
        withPre e $ \e' -> pure [DoReturn ml (Just e') rsp]
      DoReturn ml Nothing rsp -> pure [DoReturn ml Nothing rsp]
      -- the condition is evaluated each iteration; lift it INSIDE a fresh nested
      -- scope only if it carries a bang (so the splice re-runs per iteration),
      -- otherwise keep it as-is.  Body and else suites are their own scopes.
      DoWhile ml cond body mels wsp -> do
        cond' <- liftWhileCond cond
        body' <- liftDoItems ctx body
        mels' <- traverse (liftDoItems ctx) mels
        pure [DoWhile ml cond' body' mels' wsp]
      DoFor ml pat src body mels fsp ->
        withPre src $ \src' -> do
          body' <- liftDoItems ctx body
          mels' <- traverse (liftDoItems ctx) mels
          pure [DoFor ml pat src' body' mels' fsp]
      DoIf alts mels isp -> do
        -- Later `elif` conditions are evaluated only when earlier conditions
        -- are false, so their lifted binds belong in the false continuation.
        liftStmtIf alts mels isp
      -- items with no expression subterm to lift
      _ -> pure [item]

    -- run the lift over an expression and feed the residual to a continuation;
    -- the hoisted binds are prepended to whatever items the continuation yields.
    withPre :: Expr -> (Expr -> CheckM [DoItem]) -> CheckM [DoItem]
    withPre e k = do
      (pre, e') <- liftBangsExpr ctx (exprSpan e) e
      rest <- k e'
      pure (pre ++ rest)

    liftStmtIf :: [(Expr, [DoItem])] -> Maybe [DoItem] -> Span -> CheckM [DoItem]
    liftStmtIf [] mels _ =
      maybe (pure []) (liftDoItems ctx) mels
    liftStmtIf ((c, body) : rest) mels isp = do
      (pre, c') <- liftBangsExpr ctx (exprSpan c) c
      body' <- liftDoItems ctx body
      falseItems <- case rest of
        [] -> traverse (liftDoItems ctx) mels
        _ -> Just <$> liftStmtIf rest mels isp
      pure (pre ++ [DoIf [(c', body')] falseItems isp])

    -- A `while` condition may be pure `Bool` or monadic `m Bool` (§18.6).  A
    -- bang there must re-run each iteration, so wrap the lifted condition as a
    -- fresh `do` whose final value is the (residual) boolean — keeping the
    -- splice binds inside the per-iteration scope.  No bang: leave it unchanged.
    liftWhileCond :: Expr -> CheckM Expr
    liftWhileCond cond
      | exprHasBang cond = do
          (pre, cond') <- liftBangsExpr ctx (exprSpan cond) cond
          pure (EDo Nothing (pre ++ [DoExpr cond']) (exprSpan cond))
      | otherwise = pure cond

-- ── §21 Syntax, macros, and Elab ─────────────────────────────────────
--
-- Design (Spec §21, §22, §6.3.4.3–5, §20.9):
--
--   * 'Syntax t' is compile-time-only. A quote @'{ e }@ elaborates to
--     'CQuote': the SURFACE payload (with @${...}@ sub-splices replaced
--     by numbered 'EQuoteHole' grafting slots), §21.4 hygiene metadata,
--     and one elaborated term of type @Syntax _@ per slot. Quotation
--     type-checks the payload to assign the Syntax index (and to
--     surface malformed-payload diagnostics) but discharges no final
--     object-level obligations; the payload TERM is discarded and the
--     surface syntax kept (§21.1).
--   * Hygiene (§21.4): every payload occurrence of a quote-site LOCAL
--     binder (not rebound inside the payload) is renamed to a fresh
--     hygienic spelling and recorded as a 'QuoteCapture' with its
--     context LEVEL. Splicing validates each capture against the
--     splice-site context (binder still present at that level, same
--     spelling) — one rule covering local-binder escape and
--     borrow-scope escape — then resolves capture occurrences by level
--     through 'ctxHyg', immune to later shadowing.
--   * @$(m)@ (§21.2) admits @m : Elab (Syntax t)@ or the bare-Syntax
--     sugar @m : Syntax t@ (treated as @pure m@). The elaborated
--     argument is EVALUATED at elaboration time (runtime-mode NbE over
--     compile-time values) and the resulting action is run by
--     'runElab', a CheckM interpreter over stuck @__elab*@ primitive
--     applications: pure/bind, the §21.5 reflection queries, the
--     §21.9 diagnostics, and §22 shape reflection. The produced
--     Syntax is grafted ('substQuoteHoles') and re-elaborated at the
--     splice site exactly as if written there (§30.1); the grafted
--     expansion is recorded in 'csExpansions' so the §12.2 usage
--     analysis charges the expanded object-level uses at each splice.
--   * Elab-typed @do@ blocks lower to @__elabBind@ chains; @pure@
--     into an Elab position lifts via @__elabPure@ (§21.9).
--   * Prefixed strings (§6.3.4.3–5) resolve their handler term at type
--     @Elab (InterpolatedMacro t)@, run @buildInterpolated@ over the
--     §6.3.4.4 fragment list at elaboration time, and splice the
--     result; bare object-phase 'InterpolatedMacro' values are
--     rejected. Comprehension carriers with 'FromComprehensionRaw' /
--     'FromComprehensionPlan' instances run the sink hook the same
--     way (§20.9), raw preferred, after checking the instance's
--     'Item' member against the yielded item type.
--
-- §21.8 restrictions: package mode provides no IO capability to the
-- evaluator by construction (no IO primitive reduces outside the
-- §18.8 kernel). Termination of macro execution is bounded by the
-- evaluator's fuel; see SPEC_COMPLIANCE.md for the provided subset.

-- | The runtime-mode evaluation context for elaboration-time
-- execution (§21.8, §30.2.4): every global unfolds.
ecRT_ :: CheckM EvalCtx
ecRT_ = gets (\st -> EvalCtx (Globals (csGlobals st)) (csMetas st) True (csFacts st))

evalRT :: Ctx -> Term -> CheckM Value
evalRT ctx t = do
  ec <- ecRT_
  pure (eval ec (ctxEnv ctx) t)

forceRT :: Value -> CheckM Value
forceRT v = do
  ec <- ecRT_
  pure (force ec v)

vappRT :: Value -> [Value] -> CheckM Value
vappRT f as = do
  ec <- ecRT_
  pure (List.foldl' (\g a -> vapp ec g Expl a) f as)

-- | Run an elaboration speculatively: keep its result only when it
-- reported no new diagnostics; otherwise restore the full state.
trySpec :: CheckM a -> CheckM (Maybe a)
trySpec act = do
  st0 <- get
  n0 <- gets (length . csDiags)
  r <- act
  n1 <- gets (length . csDiags)
  if n1 == n0 then pure (Just r) else put st0 >> pure Nothing

-- | Prefer an expected-directed elaboration, but admit a compatibility
-- alternative when that alternative succeeds without diagnostics. If both
-- paths fail, retain the primary result and its diagnostics. This is the
-- diagnostic-preserving counterpart of 'trySpec': callers must not replace a
-- precise checked failure with a noisier inference failure merely because a
-- legacy accommodation was attempted second.
preferPrimaryElaboration :: CheckM a -> CheckM a -> CheckM a
preferPrimaryElaboration primary alternative = do
  initial <- get
  diagnosticCount <- gets (length . csDiags)
  primaryResult <- primary
  primaryState <- get
  primaryDiagnosticCount <- gets (length . csDiags)
  if primaryDiagnosticCount == diagnosticCount
    then pure primaryResult
    else do
      put initial
      trySpec alternative >>= \case
        Just alternativeResult -> pure alternativeResult
        Nothing -> put primaryState >> pure primaryResult

syntaxTypeM :: Value -> CheckM Value
syntaxTypeM t = globalValueM prelSyntax [(Expl, t)]

elabTypeM :: Value -> CheckM Value
elabTypeM t = globalValueM prelElab [(Expl, t)]

elabPrimitiveAt :: Text -> [Level] -> Term
elabPrimitiveAt name universes = CGlobI (GName primModule name) universes

elabPureAt :: Ctx -> [Level] -> Value -> Term -> CheckM Term
elabPureAt ctx universes valueType value = do
  valueTypeTerm <- quoteIn ctx valueType
  pure (CApp Expl (CApp Impl (elabPrimitiveAt "__elabPure" universes) valueTypeTerm) value)

elabCarrierUniverses :: Value -> CheckM [Level]
elabCarrierUniverses carrier =
  forceM carrier >>= \case
    VGlobI global universes _ | global == prelElab -> pure universes
    _ -> pure []

-- | Elaborate a syntax quote @'{ payload }@ (§21.1).
elabQuote :: Ctx -> Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabQuote ctx payload0 sp mexp = do
  let spliceList = collectSplices payload0
      slotIdx = Map.fromList [(ssp, i) | (i, (ssp, _)) <- zip [0 ..] spliceList]
      payload = replaceSplices slotIdx payload0
  -- the sub-splice slots: each must be a meta-phase Syntax value (an
  -- Elab action is not run implicitly inside a quote, §21.1)
  slots <- forM spliceList $ \(ssp, se) -> do
    (tm0, ty0) <- infer ctx se
    (tm1, ty1) <- insertAllImplicits ctx ssp tm0 ty0
    ty1F <- forceM ty1
    case ty1F of
      VGlobN (GName pm "Syntax") [(_, t)]
        | pm == preludeModule -> pure (tm1, t)
      VGlobN g _
        | g == prelElab -> do
            errAt ssp "E_QUOTE_SPLICE_ELAB" (Just "kappa.syntax.quotation")
              "an 'Elab (Syntax _)' action is not run implicitly inside a quote; bind it in the surrounding Elab computation first and splice the resulting 'Syntax' value (§21.1)"
            (tm1,) <$> freshMetaV ctx
      _ -> do
        tT <- quoteIn ctx ty1F
        errAt ssp "E_QUOTE_SPLICE_TYPE" (Just "kappa.syntax.quotation")
          ("a '${...}' splice inside a quote requires a 'Syntax' value; this expression has type " <> renderTerm tT <> " (§21.1)")
        (tm1,) <$> freshMetaV ctx
  -- type-directed payload checking sufficient to assign the Syntax
  -- index; the elaborated term is discarded (§21.1: quotation records
  -- syntax, final obligations are discharged at splice sites)
  let ctxQ = withVarReadBlock VarReadCrossesBoundary ctx {ctxQuoteSlots = Map.fromList (zip [0 ..] (map snd slots))}
  tV <- case mexp of
    Just t -> do
      _ <- check ctxQ payload t
      pure t
    Nothing -> do
      (tm0, ty0) <- infer ctxQ payload
      (_, ty1) <- insertAllImplicits ctxQ sp tm0 ty0
      pure ty1
  qs <- mkQuotedSyntax ctx payload sp
  syntaxTy <- syntaxTypeM tV
  pure (CQuote qs (map fst slots), syntaxTy)

-- | Elaborate a §23.2 staged-code quotation @.< e >.@: if @e : t@ the
-- quote has type @Code t@. The interpreter models generative code by
-- its present-stage value ('__codeQuote'); captured present-stage
-- variables follow the §23.3 lift-based cross-stage persistence of a
-- simple variable occurrence (the value environment is captured, so
-- §23.7 scope safety holds by construction). The §12.3.2 escape rules
-- treat the quote like a closure over its payload ('Kappa.Usage').
elabCodeQuote :: Ctx -> Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabCodeQuote ctx e _sp mexp = do
  tV <- maybe (freshMetaV ctx) pure mexp
  tm <- check (withVarReadBlock VarReadCrossesBoundary ctx) {ctxCodeDepth = ctxCodeDepth ctx + 1} e tV
  quoteHead <- globalHeadM prelCodeQuote
  codeTy <- globalValueM prelCode [(Expl, tV)]
  pure (CApp Expl quoteHead tm, codeTy)

-- | Elaborate a §23.2 escape @.~c@: requires @c : Code t@ and an
-- enclosing code quote.
elabCodeEscape :: Ctx -> Expr -> Span -> CheckM (Term, Value)
elabCodeEscape ctx e sp = do
  when (ctxCodeDepth ctx == 0) $
    errAt sp "E_CODE_ESCAPE_OUTSIDE_QUOTE" (Just "kappa-hs.staging.escape")
      "the escape '.~c' splices a staged subterm and is only meaningful inside a '.< ... >.' code quote (§23.2)"
  tV <- freshMetaV ctx
  codeTy <- globalValueM prelCode [(Expl, tV)]
  tm <- check ctx {ctxCodeDepth = max 0 (ctxCodeDepth ctx - 1)} e codeTy
  escapeHead <- globalHeadM prelCodeEscape
  pure (CApp Expl escapeHead tm, tV)

-- | §21.4 hygiene metadata: rename quote-site local references to
-- fresh hygienic spellings and record (spelling, original, level).
mkQuotedSyntax :: Ctx -> Expr -> Span -> CheckM QuotedSyntax
mkQuotedSyntax ctx payload sp = do
  let bound = boundNamesIn payload
      occ = nub [nameText n | n <- freeVarOccurrences payload]
      capturable =
        [ (nm, i)
        | nm <- occ
        , nm `notElem` bound
        , Just (i, _) <- [lookupCtx nm ctx]
        ]
  caps <- forM capturable $ \(nm, i) -> do
    h <- freshNameM (nm <> "__hyg")
    pure (QuoteCapture h nm (ctxLen ctx - 1 - i))
  let ren = Map.fromList [(qcOrig c, qcHyg c) | c <- caps]
  pure (QuotedSyntax (renameVarOccurrences ren payload) caps sp)

-- | Elaborate a splice @$(m)@ (§21.2): execute the elaboration-time
-- action and elaborate the produced syntax at the splice site.
elabSplice :: Ctx -> Expr -> Span -> Maybe Value -> CheckM (Term, Value)
elabSplice ctx me sp mexp = do
  tV <- maybe (freshMetaV ctx) forceM mexp
  let bail = (\t -> (t, tV)) <$> freshMeta
  phaseOk <- splicePhaseCheck ctx me
  if not phaseOk
    then bail
    else do
      syntaxTy <- syntaxTypeM tV
      elabSyntaxTy <- elabTypeM syntaxTy
      rA <- trySpec (check ctx me elabSyntaxTy)
      mtm <- case rA of
        Just tm -> pure (Just tm)
        Nothing -> do
          rB <- trySpec (check ctx me syntaxTy)
          case rB of
            Just tm -> do
              universes <- elabCarrierUniverses elabSyntaxTy
              pure . Just =<< elabPureAt ctx universes syntaxTy tm
            Nothing -> do
              r <- trySpec $ do
                (tm0, ty0) <- infer ctx me
                insertAllImplicits ctx sp tm0 ty0
              tyDesc <- case r of
                Just (_, ty) -> do
                  tT <- quoteIn ctx ty
                  pure ("; this expression has type " <> renderTerm tT)
                Nothing -> pure ""
              errAt sp "E_SPLICE_REQUIRES_SYNTAX" (Just "kappa-hs.syntax.splice")
                ("a splice '$(...)' requires an 'Elab (Syntax t)' action or a meta-phase 'Syntax t' value"
                   <> tyDesc <> " (§21.2)")
              pure Nothing
      case mtm of
        Nothing -> bail
        Just tm -> do
          v <- evalRT ctx tm
          res <- runElab ctx sp v
          case res of
            Left () -> bail
            Right sv -> do
              mtmS <- spliceSyntaxValue ctx sp tV sv
              case mtmS of
                Nothing -> bail
                Just tmS -> pure (tmS, tV)

-- | Elaborate a produced 'Syntax' value at a splice site (§21.2):
-- graft, validate hygiene, record the expansion, re-elaborate.
spliceSyntaxValue :: Ctx -> Span -> Value -> Value -> CheckM (Maybe Term)
spliceSyntaxValue ctx sp tV sv = do
  mq <- graftQuoteV ctx sp sv
  case mq of
    Nothing -> pure Nothing
    Just qs -> do
      ok <- validateCaptures ctx sp (qsCaptures qs)
      if not ok
        then pure Nothing
        else do
          let ctx' = extendHyg ctx (qsCaptures qs)
              back = Map.fromList [(qcHyg c, qcOrig c) | c <- qsCaptures qs]
          modify' $ \st ->
            st {csExpansions = Map.insert sp (renameVarOccurrences back (qsExpr qs)) (csExpansions st)}
          Just <$> check ctx' (qsExpr qs) tV

-- | The §21.6 convenience reflection queries that may be run directly
-- by the elaborator in ordinary term positions.
reflQueryNames :: [Text]
reflQueryNames = ["defEqSyntax", "headSymbolSyntax", "typeOfSyntax"]

-- | Authenticate a convenience query by exact resolved declaration identity.
-- A same-spelling local, alias declaration, or member is an ordinary value.
-- An ascribed expression is deliberately excluded: its asserted type must be
-- checked by the ordinary application path before any convenience behavior.
canonicalReflectionQuery :: Ctx -> Expr -> CheckM (Maybe GName)
canonicalReflectionQuery ctx expression
  | staticQueryHead expression = do
      resolved <- staticGlobalExpr ctx expression
      pure $ do
        global@(GName owner name) <- resolved
        guard (owner == preludeModule && name `elem` reflQueryNames)
        pure global
  | otherwise = pure Nothing
  where
    staticQueryHead = \case
      EVar {} -> True
      EDot {} -> True
      _ -> False

-- | §21.6: delaborate a first-order TYPE term back to surface syntax (for
-- 'typeOfSyntax'). Covers the type-expression forms — universes, type
-- constructors/names, type application (implicit args inferred away),
-- saturated type-level constructors, and de Bruijn variables (resolved
-- through the binder stack, then the context). A form that is not a
-- first-order type expression yields Nothing, so the query fails gracefully
-- rather than fabricating syntax.
delaborateType :: Ctx -> Span -> Term -> Maybe Expr
delaborateType ctx dsp = delaborateTypeWithEnv ctx dsp []

-- | Delaborate a checked type under an explicitly named synthetic binder
-- environment. Compiler-owned declaration generators use this to abstract a
-- selected semantic field while still sending the resulting ordinary syntax
-- back through the normal checker. The environment is de Bruijn order
-- (nearest binder first), matching 'ctxEntries'.
delaborateTypeWithEnv :: Ctx -> Span -> [Text] -> Term -> Maybe Expr
delaborateTypeWithEnv ctx dsp initialEnv = go initialEnv
  where
    nm t = Name t dsp
    go env tm = case tm of
      CSort _ -> Just (EVar (nm "Type"))
      CGlob g -> Just (EVar (nm (gnameText g)))
      CGlobal g _ -> Just (EVar (nm (gnameText g)))
      CUniverseLift _ _ _ inner -> go env inner
      CSchemaLift _ _ _ _ _ _ _ _ inner -> go env inner
      CVar i
        | i < length env -> Just (EVar (nm (env !! i)))
        | otherwise -> case drop (i - length env) (ctxEntries ctx) of
            (e : _) -> Just (EVar (nm (ceName e)))
            [] -> Nothing
      CLit (LitInt value) -> Just (EIntLit value Nothing dsp)
      CLit (LitDouble value) -> Just (EFloatLit value Nothing dsp)
      CApp Impl f _ -> go env f
      CApp Expl f a -> do
        fE <- go env f
        aE <- go env a
        pure (EApp fE [ArgExplicit aE])
      CPiEvidenceM mode _ ic q borrowed binderName _ _ domain codomain -> do
        domainE <- go env domain
        let surfaceName
              | binderName == "_" = "__discarded" <> T.pack (show (length env))
              | otherwise = binderName
            binder =
              Binder
                { bImplicit = ic == Impl
                , bPrefix =
                    BinderPrefix
                      (case mode of
                         Ordinary -> Nothing
                         Parametric -> Just Parametric)
                      (Just (surfaceQuantity q))
                      (if borrowed then Just (BorrowMark Nothing) else Nothing)
                , bSusp = Nothing
                , bReceiver = NoReceiver
                , bInout = False
                , bName = Just (nm surfaceName)
                , bUnitBinder = False
                , bType = Just domainE
                , bDefault = Nothing
                , bSpan = dsp
                }
        EArrow binder <$> go (surfaceName : env) codomain
      CCtor g _ args -> do
        argEs <- mapM (go env) args
        pure (foldl (\acc e -> EApp acc [ArgExplicit e]) (EVar (nm (gnameText g))) argEs)
      CRecordTQ fields -> ERecordType <$> recordFields env fields <*> pure Nothing <*> pure dsp
      _ -> Nothing

    recordFields _ [] = Just []
    recordFields env (field : rest) = do
      fieldType <- go env (rfType field)
      later <- recordFields (rfName field : env) rest
      let mode =
            case rfMode field of
              Ordinary -> Nothing
              Parametric -> Just Parametric
          prefix =
            BinderPrefix
              mode
              (Just (surfaceQuantity (rfQ field)))
              Nothing
      pure
        ( RecTypeField
            False
            False
            prefix
            Nothing
            (nm (rfName field))
            fieldType
            : later
        )

    surfaceQuantity = \case
      Q0 -> S.QZero
      Q1 -> S.QOne
      QW -> S.QOmega
      QLe1 -> S.QAtMostOne
      QGe1 -> S.QAtLeastOne

-- | §21.6: the convenience reflection operations are elaboration-time
-- queries. In an 'Elab'-typed position an application is an ordinary
-- 'Elab' action; in any other position the elaborator runs the query
-- at the call site and residualizes its result (the standardized
-- queries consume only meta-phase 'Syntax' operands and answer with
-- portable first-order results, so no §21.2 generic coercion arises).
elabReflQuery :: Ctx -> Span -> GName -> [Arg] -> Maybe Value -> CheckM (Term, Value)
elabReflQuery ctx querySpan canonicalQuery args mexp =
  case mexp of
    Just expected -> do
      actionExpected <- expectedIsElab expected
      if actionExpected
        then ordinaryResolvedApplication expected
        else inferAndResidualize
    Nothing -> inferAndResidualize
  where
    expectedIsElab expected = do
      expectedTerm <- quoteIn ctx expected
      pure
        ( termHeadGlob (stripIdentityWrappers expectedTerm)
            == Just prelElab
        )

    ordinaryResolvedApplication expected = do
      (term, actual) <- inferQueryApplication
      (saturated, saturatedType) <-
        insertAllImplicits ctx querySpan term actual
      checked <-
        coerceTerm ctx querySpan saturated saturatedType expected
      pure (checked, expected)

    resolveQueryHead = do
      gateUnsafeResolved canonicalQuery querySpan
      globalTerm canonicalQuery >>= \case
        Just (term, classifier) -> pure (term, classifier)
        Nothing -> do
          errAt
            querySpan
            "E_INTERNAL_MISSING_PRELUDE_DECLARATION"
            Nothing
            ( "the canonical reflection query '"
                <> gnameText canonicalQuery
                <> "' has no checked global interface"
            )
          anyHole ctx

    inferQueryApplication = do
      (fTm, fTy) <- resolveQueryHead
      (term, resultType) <- elabSpine ctx querySpan fTm fTy args
      resultTypeForced <- forceM resultType
      pure (term, resultTypeForced)

    inferAndResidualize = do
      (tm1, ty1F) <- inferQueryApplication
      residualizeQuery tm1 ty1F

    residualizeQuery tm1 = \case
      VGlobN g [(_, rT)]
        | g == prelElab
        , termHeadGlob (stripIdentityWrappers tm1) == Just canonicalQuery -> do
            v <- evalRT ctx tm1
            res <- runElab ctx querySpan v
            case res of
              Left () -> (,rT) <$> freshMeta
              Right rv -> do
                rTm <- quoteIn ctx rv
                pure (rTm, rT)
      ty -> pure (tm1, ty)

-- | §21.6: elaborate a reflected syntax value at the current call site
-- (shared by the convenience reflection queries). Ill-scoped or
-- ill-typed payloads fail with ordinary structured diagnostics
-- (§21.6.1).
elabReflPayload :: Ctx -> Span -> Value -> CheckM (Maybe (Term, Ctx))
elabReflPayload ctx sp sv = do
  mq <- graftQuoteV ctx sp sv
  case mq of
    Nothing -> pure Nothing
    Just qs -> do
      ok <- validateCaptures ctx sp (qsCaptures qs)
      if not ok
        then pure Nothing
        else do
          let ctx' = extendHyg ctx (qsCaptures qs)
          -- a payload that elaborates as a type is reflected as the
          -- type expression (so 'defEqSyntax' relates a same-spelling
          -- data family's type facet to its rebound static object,
          -- §7.6); other payloads elaborate as ordinary terms
          mty <- trySpec (fst <$> inferType ctx' (qsExpr qs))
          case mty of
            Just tyTm -> pure (Just (tyTm, ctx'))
            Nothing -> do
              (tm0, ty0) <- infer ctx' (qsExpr qs)
              (tm1, _) <- insertAllImplicits ctx' sp tm0 ty0
              pure (Just (tm1, ctx'))

-- | The global declaration head of an elaborated core term, if any
-- (§21.6 'headSymbol': None for variables, binders, locals, and
-- literals).
headGlobalOf :: Term -> Maybe GName
headGlobalOf = \case
  CApp _ f _ -> headGlobalOf f
  CGlob g@(GName m _) | m /= primModule -> Just g
  CCtor g _ _ -> Just g
  _ -> Nothing

-- | A §21.6 'Symbol' value: resolved declaration identity.
symbolValue :: GName -> Value
symbolValue (GName (ModuleName segs) n) =
  VPrim "__symbolV" [VLit (LitStr (T.intercalate "." segs <> "::" <> n))]

-- | §21.9 phase check: object-phase runtime locals cannot enter an
-- elaboration-time splice argument (only meta-phase carriers may).
splicePhaseCheck :: Ctx -> Expr -> CheckM Bool
splicePhaseCheck ctx me = do
  let bound = boundNamesIn me
      occs =
        [ (n, i)
        | n <- freeVarOccurrences me
        , nameText n `notElem` bound
        , not (Map.member (nameText n) (ctxHyg ctx))
        , Just (i, _) <- [lookupCtx (nameText n) ctx]
        ]
  bad <- filterM (\(_, i) -> not <$> metaPhaseType (ceType (ctxEntries ctx !! i))) occs
  case bad of
    [] -> pure True
    ((n, _) : _) -> do
      errAt (nameSpan n) "E_ELAB_PHASE" (Just "kappa-hs.macro.phase")
        ("the object-phase runtime binding '" <> nameText n
           <> "' cannot be captured by an elaboration-time splice; object-phase terms enter 'Elab' only through meta-phase carriers such as 'Syntax' (§21.9)")
      pure False

-- | Is a local's type a meta-phase carrier admissible inside 'Elab'?
metaPhaseType :: Value -> CheckM Bool
metaPhaseType v = do
  t <- forceM v
  case t of
    -- type, row, quantity, and region parameters are erased
    -- classifier-level entities; mentioning them does not smuggle an
    -- object-phase runtime value into Elab (§21.9)
    VSort _ -> pure True
    VGlobN (GName pm g) args
      | pm == preludeModule
      , g `elem`
          [ "Syntax", "Elab", "SyntaxOrigin", "SyntaxFragment"
          , "RawComprehension", "ComprehensionPlan"
          , "RecRow", "EffRow", "Quantity", "Region", "EffLabel"
          ] ->
          pure True
      | pm == preludeModule
      , g `elem` ["List", "Option"]
      , ((_, a) : _) <- args ->
          metaPhaseType a
    VGlobN (GName m _) _ | m == shapeModule -> pure True
    _ -> pure False

-- | Graft a syntax value: force the slot values to quotes and
-- substitute them into the payload's grafting holes (§21.2).
graftQuoteV :: Ctx -> Span -> Value -> CheckM (Maybe QuotedSyntax)
graftQuoteV ctx sp v0 = do
  v <- forceRT v0
  case v of
    VQuote qs slots -> do
      subs <- mapM (graftQuoteV ctx sp) slots
      case sequence subs of
        Nothing -> pure Nothing
        Just qss ->
          pure $
            Just
              QuotedSyntax
                { qsExpr = substQuoteHoles (Map.fromList (zip [0 ..] (map qsExpr qss))) (qsExpr qs)
                , qsCaptures = qsCaptures qs ++ concatMap qsCaptures qss
                , qsSpan = qsSpan qs
                }
    _ -> do
      errAt sp "E_SPLICE_REQUIRES_SYNTAX" (Just "kappa-hs.syntax.splice")
        "the elaboration-time action did not produce a 'Syntax' value this implementation can splice (§21.2)"
      pure Nothing

-- | §21.4: every free hygienic binder of spliced syntax must still be
-- valid at the splice site.
validateCaptures :: Ctx -> Span -> [QuoteCapture] -> CheckM Bool
validateCaptures ctx sp caps = do
  let n = ctxLen ctx
      entryOk c =
        let i = n - 1 - qcLevel c
         in i >= 0 && i < n && ceName (ctxEntries ctx !! i) == qcOrig c
      bad = [c | c <- caps, not (entryOk c)]
  forM_ (take 1 bad) $ \c ->
    errAt sp "E_SYNTAX_SCOPE_ESCAPE" (Just "kappa-hs.syntax.scope-escape")
      ("this Syntax value mentions the local binder '" <> qcOrig c
         <> "' (or its borrow region) whose scope has ended; a Syntax value may escape a lexical scope only while every free hygienic binder it references remains valid, and splicing requires those binders at the splice site (§21.4)")
  pure (null bad)

extendHyg :: Ctx -> [QuoteCapture] -> Ctx
extendHyg ctx caps = ctx {ctxHyg = foldr ins (ctxHyg ctx) caps}
  where
    n = ctxLen ctx
    ins c m = case drop (n - 1 - qcLevel c) (ctxEntries ctx) of
      e : _ -> Map.insert (qcHyg c) (qcLevel c, ceType e) m
      [] -> m

-- | Run an elaboration-time action value (§21.9, §30.2.4): interpret
-- the stuck @__elab*@ primitive applications under CheckM.
runElab :: Ctx -> Span -> Value -> CheckM (Either () Value)
runElab ctx sp v0 = do
  v <- forceRT v0
  case v of
    VPrim "__elabPure" [x] -> pure (Right x)
    VPrim "__elabBind" [m, k] -> do
      r <- runElab ctx sp m
      case r of
        Left e -> pure (Left e)
        Right x -> runElab ctx sp =<< vappRT k [x]
    VPrim "renderSyntax" [s] -> do
      mq <- graftQuoteV ctx sp s
      pure $ case mq of
        Just qs -> Right (VLit (LitStr (renderExprSrc (qsExpr qs))))
        Nothing -> Left ()
    VPrim "syntaxOrigin" [s] -> do
      sV <- forceRT s
      let osp = case sV of
            VQuote qs _ -> qsSpan qs
            _ -> sp
      pure (Right (VPrim "__syntaxOriginV" [VLit (LitStr (T.pack (show osp)))]))
    VPrim "normalizeSyntax" [s] -> pure (Right s)
    VPrim "whnfSyntax" [s] -> pure (Right s)
    -- §21.6 'typeOfSyntax': elaborate the payload at the current call site,
    -- infer its type, and reify that type back to a 'Syntax Type' by
    -- delaborating the inferred type term to surface syntax. The query
    -- commits no constraints (state restored).
    VPrim "typeOfSyntax" [s] -> do
      mq <- graftQuoteV ctx sp s
      case mq of
        Nothing -> pure (Left ())
        Just qs -> do
          ok <- validateCaptures ctx sp (qsCaptures qs)
          if not ok
            then pure (Left ())
            else do
              let ctx' = extendHyg ctx (qsCaptures qs)
              st0 <- get
              mr <- trySpec (infer ctx' (qsExpr qs))
              put st0
              case mr of
                Nothing -> pure (Left ())
                Just (_, tyV) -> do
                  tyTm <- quoteIn ctx' tyV
                  case delaborateType ctx' (qsSpan qs) tyTm of
                    Just tyE -> pure (Right (VQuote (QuotedSyntax tyE [] (qsSpan qs)) []))
                    Nothing -> pure (Left ())
    -- §21.6 'defEqSyntax': elaborate both syntax values at the current
    -- call site and answer the same Boolean that 'defEq' would for the
    -- resulting cores; the query commits no constraints
    VPrim "defEqSyntax" [s1, s2] -> do
      m1 <- elabReflPayload ctx sp s1
      m2 <- elabReflPayload ctx sp s2
      case (m1, m2) of
        (Just (tm1, ctx1), Just (tm2, ctx2)) -> do
          st0 <- get
          v1 <- evalRT ctx1 tm1
          v2 <- evalRT ctx2 tm2
          eq <- unify ctx v1 v2
          put st0
          pure (Right (VCtor (prelBoolV eq) []))
        _ -> pure (Left ())
    -- §21.6 'headSymbolSyntax': Some s only when the elaborated core
    -- has a global declaration head ('sameSymbol' then compares
    -- resolved declaration identity, not spelling — a module alias
    -- path resolves to the same symbol)
    VPrim "headSymbolSyntax" [s] -> do
      m <- elabReflPayload ctx sp s
      case m of
        Nothing -> pure (Left ())
        Just (tm, _) -> do
          symbolType <- globalValueM prelSymbol []
          symbolLevel <- gets (Map.lookup prelSymbol . csGlobals) >>= \case
            Just definition -> forceM (gdType definition) >>= \case
              VSort level -> pure level
              _ -> pure LZero
            Nothing -> pure LZero
          let resultType = VGlobI prelOption [symbolLevel] [(Expl, symbolType)]
          result <- case headGlobalOf tm of
            Just g -> generatedCtorValueAtM ctx resultType prelSome [symbolValue g]
            Nothing -> generatedCtorValueAtM ctx resultType prelNone []
          pure (Right result)
    VPrim "withSyntaxOrigin" [_, s] -> pure (Right s)
    VPrim "warnElab" [m] -> do
      msg <- strValue m
      report (diag SevWarning StageElaborate "W_MACRO_DIAGNOSTIC" (Just "kappa.macro.failure") sp msg)
      pure (Right unitValue)
    VPrim "warnElabWith" [c, m, _] -> do
      code <- strValue c
      msg <- strValue m
      report (diag SevWarning StageElaborate code (Just "kappa.macro.failure") sp msg)
      pure (Right unitValue)
    VPrim "failElab" [m] -> do
      msg <- strValue m
      errAt sp "E_MACRO_FAILURE" (Just "kappa.macro.failure") msg
      pure (Left ())
    VPrim "failElabWith" [c, m, _] -> do
      code <- strValue c
      msg <- strValue m
      errAt sp code (Just "kappa.macro.failure") msg
      pure (Left ())
    VPrim "__stringSyntax" [s] -> do
      txt <- strValue s
      pure (Right (literalQuote (EStringLit (StringLit Nothing 0 False [FragLit txt]) [] sp)))
    VPrim "__natSyntax" [n] -> do
      nF <- forceRT n
      pure $ case nF of
        VLit (LitInt i) -> Right (literalQuote (EIntLit i Nothing sp))
        _ -> Right (literalQuote (EIntLit 0 Nothing sp))
    VPrim "__boolSyntax" [b] -> do
      bF <- forceRT b
      let nm = case bF of
            VCtor (GName _ "True") [] -> "True"
            _ -> "False"
      pure (Right (literalQuote (EVar (Name nm sp))))
    VPrim "__unitSyntax" [] -> pure (Right (literalQuote (EUnit sp)))
    VPrim "__shapeInspectAdt" [tyV, _] -> shapeInspectAdtOp ctx sp tyV
    VPrim "__shapeInspectRecord" [tyV, target] -> shapeInspectRecordOp ctx sp tyV target
    VPrim "__shapeRequireFieldInstances" [tcV, tyV, _] -> shapeRequireFieldsOp ctx sp tcV tyV
    VPrim "__shapeMatchAdt" [shapeV, scrutV, cb] -> shapeMatchAdtOp ctx sp shapeV scrutV cb
    VPrim "__shapeMatchAdt2" [shapeV, lV, rV, cbS, cbD] -> shapeMatchAdt2Op ctx sp shapeV lV rV cbS cbD
    _ -> do
      errAt sp "E_ELAB_STUCK" (Just "kappa.macro.failure")
        "this elaboration-time action could not be executed by the Elab evaluator (§21.9; see SPEC_COMPLIANCE.md for the provided subset)"
      pure (Left ())
  where
    literalQuote e = VQuote (QuotedSyntax e [] sp) []
    unitValue = VCtor prelUnit []
    strValue x = do
      xF <- forceRT x
      pure $ case xF of
        VLit (LitStr s) -> s
        _ -> ""

-- | Elab-typed do blocks (§21.9): lower to '__elabBind' chains.
elabElabDo :: Ctx -> Value -> [DoItem] -> Span -> CheckM (Term, Value)
elabElabDo ctx0 aTy items0 sp = do
  resultTy <- elabTypeM aTy
  resultUniverses <- elabCarrierUniverses resultTy
  tm <- go resultUniverses ctx0 items0
  pure (tm, resultTy)
  where
    bindPrim ctx resultUniverses inputType inputCarrier m k = do
      inputUniverses <- elabCarrierUniverses inputCarrier
      inputTypeTerm <- quoteIn ctx inputType
      resultTypeTerm <- quoteIn ctx aTy
      let headTerm =
            CApp Impl
              (CApp Impl (elabPrimitiveAt "__elabBind" (inputUniverses ++ resultUniverses)) inputTypeTerm)
              resultTypeTerm
      pure (CApp Expl (CApp Expl headTerm m) k)
    badForm resultUniverses ctx isp rest = do
      errAt isp "E_ELAB_DO_FORM" (Just "kappa-hs.do.elab")
        "this do item form is not available in an 'Elab' do block (§21.9)"
      go resultUniverses ctx rest
    go resultUniverses ctx = \case
      [] -> do
        errAt sp "E_ELAB_DO_FORM" (Just "kappa-hs.do.elab")
          "an 'Elab' do block must end with an expression of the block's Elab type (§21.9)"
        freshMeta
      [DoExpr e] -> elabTypeM aTy >>= check ctx e
      [item] -> badForm resultUniverses ctx (doItemSpan item) []
      (item : rest) -> case item of
        DoExpr e -> do
          bTy <- freshMetaV ctx
          expected <- elabTypeM bTy
          mTm <- check ctx e expected
          restTm <- go resultUniverses (bindCtx "_" False bTy ctx) rest
          bindPrim ctx resultUniverses bTy expected mTm (CLamM Ordinary Expl QW "_" restTm)
        DoBind (LetBind _ _ pat mty rhs bsp) -> bindItem resultUniverses ctx pat mty rhs bsp rest
        DoAssign n True _ asp -> do
          errAt asp "E_ASSIGN_NOT_VAR" (Just "kappa-hs.do.assign-non-var")
            ("'" <> nameText n <> " <- ...' is mutable-var assignment syntax; use 'let "
               <> nameText n <> " <- ...' for monadic bind (§18.2)")
          go resultUniverses ctx rest
        DoAssign n False rhs asp -> letItem resultUniverses ctx (PVar n) Nothing rhs asp rest
        DoLet (LetBind _ _ pat mty rhs bsp) -> letItem resultUniverses ctx pat mty rhs bsp rest
        other -> badForm resultUniverses ctx (doItemSpan other) rest
    patBinder bsp = \case
      PVar n -> pure (nameText n)
      PWild _ -> pure "_"
      _ -> do
        errAt bsp "E_ELAB_DO_FORM" (Just "kappa-hs.do.elab")
          "only variable and wildcard binders are supported in 'Elab' do binds (§21.9)"
        pure "_"
    bindItem resultUniverses ctx pat mty rhs bsp rest = do
      bTy <- case mty of
        Just tyE -> do
          (tyTm, _) <- inferType ctx tyE
          evalIn ctx tyTm
        Nothing -> freshMetaV ctx
      expected <- elabTypeM bTy
      rhsTm <- check ctx rhs expected
      nm <- patBinder bsp pat
      restTm <- go resultUniverses (bindCtx nm False bTy ctx) rest
      bindPrim ctx resultUniverses bTy expected rhsTm (CLamM Ordinary Expl QW nm restTm)
    letItem resultUniverses ctx pat mty rhs bsp rest = do
      -- §18.3.1: a `let` RHS inside a do block may contain `!`; desugar it
      -- like bindItem so it is not rejected as a bare splice.
      let rhsD = rhs
      (rhsTm, rhsTy) <- case mty of
        Just tyE -> do
          (tyTm, _) <- inferType ctx tyE
          tyV <- evalIn ctx tyTm
          tm <- check ctx rhsD tyV
          pure (tm, tyV)
        Nothing -> do
          (tm0, ty0) <- infer ctx rhsD
          insertAllImplicits ctx bsp tm0 ty0
      nm <- patBinder bsp pat
      rhsV <- evalIn ctx rhsTm
      observation <- observationJudgmentForTerm ctx rhsTm rhsTy
      restTm <- go resultUniverses (bindCtxLetProjOpMode nm False rhsTy rhsV Nothing Nothing (ojMode observation) (Just (ojOrigin observation)) ctx) rest
      tyTm' <- quoteIn ctx rhsTy
      pure (CLetM (ojMode observation) QW nm tyTm' rhsTm restTm)

-- ── §22 Derivation-shape reflection ──────────────────────────────────

gShape :: Text -> GName
gShape = GName shapeModule

shapeFamily :: Maybe DiagnosticFamily
shapeFamily = Just "kappa.deriving.shape"

listValue :: [Value] -> Value
listValue = foldr (\x t -> VCtor prelCons [x, t]) (VCtor prelNil [])

valueList :: Value -> CheckM [Value]
valueList v = do
  vF <- forceRT v
  case vF of
    VCtor (GName _ "::") [h, t] -> (h :) <$> valueList t
    _ -> pure []

shapeFieldValue :: Maybe Text -> Int -> Value
shapeFieldValue mname i =
  VCtor
    (gShape "ShapeField")
    [ maybe (VCtor prelNone []) (\n -> VCtor prelSome [VLit (LitStr n)]) mname
    , VLit (LitStr renderName)
    ]
  where
    renderName = fromMaybe ("_" <> T.pack (show (i + 1))) mname

-- | The §22.1 constructor summaries of a data type.
shapeCtorValues :: GName -> CheckM [Value]
shapeCtorValues g = do
  st <- get
  let ctorGs = maybe [] diCtors (Map.lookup g (csDatas st))
  pure
    [ VCtor
        (gShape "ShapeConstructor")
        [ VLit (LitStr (gnameText cg))
        , VLit (LitStr (gnameText cg))
        , VLit (LitInt (fromIntegral tag))
        , listValue
            [ shapeFieldValue mname i
            | (i, (mname, _)) <- zip [0 ..] (maybe [] ciFields (Map.lookup cg (csCtors st)))
            ]
        ]
    | (tag, cg) <- zip [0 :: Int ..] ctorGs
    ]

-- | §22.1 'inspectAdt': the inspected head must be a data type whose
-- representation is visible at this elaboration site.
shapeInspectAdtOp :: Ctx -> Span -> Value -> CheckM (Either () Value)
shapeInspectAdtOp _ctx sp tyV = do
  t <- forceRT tyV
  st <- get
  case t of
    VGlobN g _
      | Just di <- Map.lookup g (csDatas st) -> do
          let GName declMod _ = g
              opaque = Map.member g (csOpaqueDatas st)
          if opaque && declMod /= csModule st
            then do
              errAt sp "KAPPA_DERIVING_SHAPE_OPAQUE_REPRESENTATION" shapeFamily
                ("the representation of '" <> gnameText g
                   <> "' is opaque outside its defining module; shape inspection requires a representation ordinary code at this site could match on (§22.1)")
              pure (Left ())
            else do
              ctorVs <- shapeCtorValues g
              st' <- get
              let ctorGs = diCtors di
                  fieldCounts =
                    [maybe 0 (length . ciFields) (Map.lookup cg (csCtors st')) | cg <- ctorGs]
                  kindName
                    | length ctorGs == 1 = "ProductAdt"
                    | all (== 0) fieldCounts = "EnumAdt"
                    | otherwise = "SumAdt"
              pure $
                Right $
                  VCtor
                    (gShape "AdtShape")
                    [ VLit (LitStr (gnameText g))
                    , VLit (LitStr (gnameText g))
                    , VCtor (gShape "ShapeRepresentationVisible") []
                    , VCtor (gShape kindName) []
                    , listValue ctorVs
                    ]
    _ -> do
      tT <- quoteIn emptyCtx t
      errAt sp "KAPPA_DERIVING_SHAPE_NOT_DATA" shapeFamily
        ("shape inspection requires a data type; '" <> renderTerm tT <> "' is not one (§22.1)")
      pure (Left ())

-- | §22.1 'inspectRecord': closed records only; field order follows
-- the written order of the inspected alias when known (§22.2).
shapeInspectRecordOp :: Ctx -> Span -> Value -> Value -> CheckM (Either () Value)
shapeInspectRecordOp _ctx sp tyV target = do
  t <- forceRT tyV
  case t of
    VRecordT fs -> do
      written <- targetFieldOrder target
      let names = map fst fs
          ordered = case written of
            Just ws | sort ws == sort names -> ws
            _ -> names
      pure $
        Right $
          VCtor
            (gShape "RecordShape")
            [listValue [shapeFieldValue (Just nm) i | (i, nm) <- zip [0 ..] ordered]]
    VGlobN (GName pm "__openRec") _
      | pm == preludeModule -> do
          errAt sp "KAPPA_DERIVING_SHAPE_NOT_CLOSED_RECORD" shapeFamily
            "Phase 0 record shape inspection requires a closed record type; open record types are reserved for a later phase (§22.1)"
          pure (Left ())
    _ -> do
      tT <- quoteIn emptyCtx t
      errAt sp "KAPPA_DERIVING_SHAPE_NOT_CLOSED_RECORD" shapeFamily
        ("record shape inspection requires a closed record type; '" <> renderTerm tT <> "' is not one (§22.1)")
      pure (Left ())
  where
    targetFieldOrder tv = do
      tvF <- forceRT tv
      case tvF of
        VQuote qs _
          | EVar n <- qsExpr qs -> do
              mg <- lookupGlobalName (nameText n)
              case mg of
                Just g -> gets (Map.lookup g . csRecordOrders)
                Nothing -> pure Nothing
        _ -> pure Nothing

-- | §22.4 'requireRuntimeFieldInstances': probe ordinary implicit
-- resolution for @tc F@ at every constructor field type @F@.
shapeRequireFieldsOp :: Ctx -> Span -> Value -> Value -> CheckM (Either () Value)
shapeRequireFieldsOp ctx sp tcV tyV = do
  t <- forceRT tyV
  st <- get
  case t of
    VGlobN g _
      | Just di <- Map.lookup g (csDatas st) -> do
          fieldTys <- concat <$> mapM (ctorFieldTypesOf t) (diCtors di)
          missing <- filterM (fmap not . satisfiable) fieldTys
          case missing of
            [] -> pure (Right (VCtor prelUnit []))
            ((cg, mname, fTy) : _) -> do
              fT <- quoteIn ctx fTy
              errAt sp "KAPPA_DERIVING_SHAPE_MISSING_RUNTIME_FIELD_INSTANCE" shapeFamily
                ("no instance satisfies the required trait obligation for field '"
                   <> fromMaybe "_" mname <> "' of constructor '" <> gnameText cg
                   <> "' (field type " <> renderTerm fT <> ") of data type '" <> gnameText g <> "' (§22.4)")
              pure (Left ())
    _ -> do
      errAt sp "KAPPA_DERIVING_SHAPE_NOT_DATA" shapeFamily
        "field-instance checking requires a data type shape (§22.4)"
      pure (Left ())
  where
    ctorFieldTypesOf tV cg = do
      st <- get
      case Map.lookup cg (csCtors st) of
        Nothing -> pure []
        Just ci -> do
          doms <- ctorFieldTypes ctx cg ci tV sp
          pure [(cg, mname, fTy) | ((mname, _), fTy) <- zip (ciFields ci) doms]
    satisfiable (_, _, fTy) = do
      ec <- ecRT_
      goal <- forceM (vapp ec tcV Expl fTy)
      r <- trySpec $ do
        mLoc <- localCandidate ctx sp Q0 goal
        case mLoc of
          Just _ -> pure True
          Nothing -> isJust <$> instanceSearch ctx sp goal
      pure (fromMaybe False r)

-- | Field arity of a shape-constructor summary value.
shapeCtorInfo :: Value -> CheckM (Text, Int, [Value])
shapeCtorInfo cv = do
  cvF <- forceRT cv
  case cvF of
    VCtor (GName _ "ShapeConstructor") [nmV, _, _, fieldsV] -> do
      nmF <- forceRT nmV
      let nm = case nmF of
            VLit (LitStr s) -> s
            _ -> "?"
      fields <- valueList fieldsV
      pure (nm, length fields, fields)
    _ -> pure ("?", 0, [])

-- | §22.5 'matchAdt': construct an exhaustive match over the
-- scrutinee syntax, one branch per constructor, branch bodies
-- produced by the elaboration-time callback.
shapeMatchAdtOp :: Ctx -> Span -> Value -> Value -> Value -> CheckM (Either () Value)
shapeMatchAdtOp ctx sp shapeV scrutV cb = do
  mscrut <- graftQuoteV ctx sp scrutV
  shapeF <- forceRT shapeV
  case (mscrut, shapeF) of
    (Just scrutQ, VCtor (GName _ "AdtShape") [_, _, _, _, ctorsV]) -> do
      ctorVs <- valueList ctorsV
      branches <- runBranches ctorVs scrutQ
      pure $ case branches of
        Nothing -> Left ()
        Just (cases, caps) ->
          Right $
            VQuote
              (QuotedSyntax (EMatch (qsExpr scrutQ) cases sp) (qsCaptures scrutQ ++ caps) sp)
              []
    _ -> do
      errAt sp "KAPPA_DERIVING_SHAPE_NOT_DATA" shapeFamily
        "matchAdt requires an inspected data shape (§22.5)"
      pure (Left ())
  where
    runBranches [] _ = pure (Just ([], []))
    runBranches (cv : rest) scrutQ = do
      (nm, arity, fields) <- shapeCtorInfo cv
      let boundFields = listValue [VCtor (gShape "BoundField") [f] | f <- fields]
      r <- runElab ctx sp =<< vappRT cb [cv, boundFields]
      case r of
        Left () -> pure Nothing
        Right bodyV -> do
          mbody <- graftQuoteV ctx sp bodyV
          case mbody of
            Nothing -> pure Nothing
            Just bodyQ -> do
              more <- runBranches rest scrutQ
              pure $ do
                (cases, caps) <- more
                let pat = PCtor (CtorRef Nothing (Name nm sp)) (replicate arity (PWild sp)) sp
                pure
                  ( MatchCase pat Nothing (qsExpr bodyQ) sp : cases
                  , qsCaptures bodyQ ++ caps
                  )

-- | §22.5 'matchAdt2': a tupled match comparing two values of the
-- same data type, same-constructor and different-constructor branches.
shapeMatchAdt2Op :: Ctx -> Span -> Value -> Value -> Value -> Value -> Value -> CheckM (Either () Value)
shapeMatchAdt2Op ctx sp shapeV lV rV cbSame cbDiff = do
  ml <- graftQuoteV ctx sp lV
  mr <- graftQuoteV ctx sp rV
  shapeF <- forceRT shapeV
  case (ml, mr, shapeF) of
    (Just lQ, Just rQ, VCtor (GName _ "AdtShape") [_, _, _, _, ctorsV]) -> do
      ctorVs <- valueList ctorsV
      let pairs = [(c1, c2) | c1 <- ctorVs, c2 <- ctorVs]
      branches <- runPairs pairs
      pure $ case branches of
        Nothing -> Left ()
        Just (cases, caps) ->
          -- close the tupled match with a catch-all duplicating the
          -- last different-constructor body, so exhaustiveness over
          -- the tuple scrutinee is syntactically evident (§22.5)
          let diffBodies =
                [ body
                | MatchCase (PTuple [PCtor c1 _ _, PCtor c2 _ _] _) _ body _ <- cases
                , nameText (crName c1) /= nameText (crName c2)
                ]
              catchAll = [MatchCase (PWild sp) Nothing b sp | b <- take 1 (reverse diffBodies)]
           in Right $
                VQuote
                  ( QuotedSyntax
                      (EMatch (ETuple [qsExpr lQ, qsExpr rQ] sp) (cases ++ catchAll) sp)
                      (qsCaptures lQ ++ qsCaptures rQ ++ caps)
                      sp
                  )
                  []
    _ -> do
      errAt sp "KAPPA_DERIVING_SHAPE_NOT_DATA" shapeFamily
        "matchAdt2 requires an inspected data shape (§22.5)"
      pure (Left ())
  where
    runPairs [] = pure (Just ([], []))
    runPairs ((c1, c2) : rest) = do
      (nm1, ar1, fields1) <- shapeCtorInfo c1
      (nm2, ar2, _) <- shapeCtorInfo c2
      r <-
        if nm1 == nm2
          then do
            let fieldPairs = listValue [VCtor (gShape "BoundFieldPair") [f] | f <- fields1]
            runElab ctx sp =<< vappRT cbSame [c1, fieldPairs]
          else runElab ctx sp =<< vappRT cbDiff [c1, c2]
      case r of
        Left () -> pure Nothing
        Right bodyV -> do
          mbody <- graftQuoteV ctx sp bodyV
          case mbody of
            Nothing -> pure Nothing
            Just bodyQ -> do
              more <- runPairs rest
              pure $ do
                (cases, caps) <- more
                let pat =
                      PTuple
                        [ PCtor (CtorRef Nothing (Name nm1 sp)) (replicate ar1 (PWild sp)) sp
                        , PCtor (CtorRef Nothing (Name nm2 sp)) (replicate ar2 (PWild sp)) sp
                        ]
                        sp
                pure
                  ( MatchCase pat Nothing (qsExpr bodyQ) sp : cases
                  , qsCaptures bodyQ ++ caps
                  )

-- ── Comprehensions (§20) ─────────────────────────────────────────────
--
-- Lowered per the §20.10 normative algebra, realized directly over
-- lists (the §20.10.11 as-if rule). A first pass infers the plan
-- (source kinds, use mode, cardinality, orderedness, row-entry
-- quantities) against a state snapshot; a second pass desugars to
-- surface syntax and elaborates once.

-- | How a generator source is iterated (§20.10.2 built-in obligations).
data SrcKind
  = SKList
  | SKArray
  | SKSet
  | SKMap
  | SKOption
  | SKQuery
  | SKRange
  | SKIntoQuery
  | SKUnknown
  deriving stock (Eq, Show)

-- | Cardinality approximation (§20.10.1).
data QCard = CZero | COne | CZeroOrOne | COneOrMore | CZeroOrMore
  deriving stock (Eq, Show)

cardName :: QCard -> Text
cardName = \case
  CZero -> "QZero"
  COne -> "QOne"
  CZeroOrOne -> "QZeroOrOne"
  COneOrMore -> "QOneOrMore"
  CZeroOrMore -> "QZeroOrMore"

cardIv :: QCard -> (Int, Maybe Int)
cardIv = \case
  CZero -> (0, Just 0)
  COne -> (1, Just 1)
  CZeroOrOne -> (0, Just 1)
  COneOrMore -> (1, Nothing)
  CZeroOrMore -> (0, Nothing)

cardOf :: (Int, Maybe Int) -> QCard
cardOf = \case
  (0, Just 0) -> CZero
  (1, Just 1) -> COne
  (0, Just 1) -> CZeroOrOne
  (1, Nothing) -> COneOrMore
  _ -> CZeroOrMore

mulCard :: QCard -> QCard -> QCard
mulCard a b =
  let (al, ah) = cardIv a
      (bl, bh) = cardIv b
      hi = case (ah, bh) of
        (Just x, Just y) -> Just (min 1 (x * y))
        (Just 0, _) -> Just 0
        (_, Just 0) -> Just 0
        _ -> Nothing
   in cardOf (min 1 (al * bl), hi)

filterCard :: QCard -> QCard
filterCard c = let (_, h) = cardIv c in cardOf (0, h)

-- | May the inferred cardinality be checked against the demanded one
-- (interval subset, §20.10.1)?
cardSub :: QCard -> QCard -> Bool
cardSub a b =
  let (al, ah) = cardIv a
      (bl, bh) = cardIv b
      hiOk = case (ah, bh) of
        (_, Nothing) -> True
        (Just x, Just y) -> x <= y
        (Nothing, Just _) -> False
   in al >= bl && hiOk

cardManyHi :: QCard -> Bool
cardManyHi c = case snd (cardIv c) of
  Nothing -> True
  Just h -> h > 1

cardZeroLo :: QCard -> Bool
cardZeroLo c = fst (cardIv c) == 0

-- | What pass 1 learned about one generator source.
data SrcInfo = SrcInfo
  { siKind :: !SrcKind
  , siItem :: !Value
  , siOrdered :: !Bool
  , siOneShot :: !Bool
  , siCard :: !QCard
  , siItemLinear :: !Bool
  }

-- | Classify a do-block 'for' generator source by its inferred type,
-- rolling back ALL elaboration side effects (diagnostics, metavariables,
-- usage). The real elaboration of the source happens once afterwards, so
-- this probe must leave no trace (§12 usage analysis in particular must
-- see the source exactly once). A source whose type does not resolve to
-- a known collection carrier is reported as 'SKUnknown' and handled by
-- the ordinary 'List elemT' check, preserving the prior behaviour.
probeForSrcKind :: Ctx -> Expr -> CheckM SrcKind
probeForSrcKind ctx src = do
  st0 <- get
  n0 <- gets (length . csDiags)
  (_, srcTy) <- infer ctx src
  n1 <- gets (length . csDiags)
  k <-
    if n1 /= n0
      then pure SKUnknown -- inference failed; let the real check report it
      else siKind <$> sourceInfo ctx srcTy
  put st0 -- discard every side effect of the probe
  pure k

sourceInfo :: Ctx -> Value -> CheckM SrcInfo
sourceInfo ctx ty = do
  t <- forceM ty
  case t of
    VGlobN g [(_, a)]
      | g == prelList -> pure (SrcInfo SKList a True False CZeroOrMore False)
      | g == prelArray -> pure (SrcInfo SKArray a True False CZeroOrMore False)
      | g == prelSet -> pure (SrcInfo SKSet a False False CZeroOrMore False)
      | g == prelOption -> pure (SrcInfo SKOption a True False CZeroOrOne False)
      | g == prelNumericRange -> pure (SrcInfo SKRange a True False CZeroOrMore False)
    VGlobN g [(_, k), (_, v)]
      | g == prelMap ->
          pure (SrcInfo SKMap (VRecordT [("key", k), ("value", v)]) False False CZeroOrMore False)
    VGlobN g [(_, m), (_, q), (_, a)]
      | g == prelQueryCore -> do
          (oneShot, card) <- decodeQueryMode m
          lin <- decodeLinearQuantity q
          pure (SrcInfo SKQuery a True oneShot card lin)
    _ -> associatedRangeItem ctx t >>= \case
        Just item ->
          -- The selected Rangeable dictionary may still be an inference meta
          -- here; the generated toQuery application below is the authority that
          -- must resolve coherent IntoQuery evidence for its associated range.
          pure (SrcInfo SKIntoQuery item True False CZeroOrMore False)
        Nothing -> do
          -- §20.2/§23.7: an associated range result need not reduce physically
          -- to the canonical NumericRange declaration. Source iteration is
          -- governed by selected IntoQuery evidence, so use that checked
          -- interface as the semantic fallback instead of guessing that an
          -- unknown source is a List. This also admits user-defined IntoQuery
          -- sources without relying on carrier or member spellings.
          goal <- globalValueM prelIntoQuery [(Expl, t)]
          traitEvidence ctx noSpan goal >>= \case
            Nothing -> do
              item <- freshMetaV ctx
              pure (SrcInfo SKUnknown item True False CZeroOrMore False)
            Just dictionary -> do
              (itemTerm, _) <-
                knownTraitMemberProjection
                  ctx
                  noSpan
                  prelIntoQuery
                  "IntoItem"
                  goal
                  dictionary
              item <- evalIn ctx itemTerm
              pure (SrcInfo SKIntoQuery item True False CZeroOrMore False)

-- | Recognize the exact @Rangeable.Range@ associated member even while its
-- dictionary is still an inference meta. The field label is authenticated by
-- the resolved Rangeable trait metadata before it is consulted; an unrelated
-- record or trait member named @Range@ cannot enter this path.
associatedRangeItem :: Ctx -> Value -> CheckM (Maybe Value)
associatedRangeItem ctx = \case
  VProjN _ receiver member -> do
    state <- get
    let authenticated =
          Map.lookup prelRangeable (csTraits state) >>= \info -> do
            guard
              ( member == "Range"
                  && member `elem` tiMembers info
              )
    case authenticated of
      Nothing -> pure Nothing
      Just () ->
        equandType ctx receiver >>= traverse forceM >>= \case
          Just (VGlobI trait _ spine)
            | trait == prelRangeable
            , Just [(_, item)] <- traitSemanticSpineIn state trait spine ->
                pure (Just item)
          _ -> pure Nothing
  _ -> pure Nothing

decodeQueryMode :: Value -> CheckM (Bool, QCard)
decodeQueryMode m0 = do
  m <- forceM m0
  case m of
    VCtor (GName _ "QueryMode") [u0, c0] -> do
      u <- forceM u0
      c <- forceM c0
      let oneShot = case u of
            VCtor (GName _ "OneShot") _ -> True
            _ -> False
          card = case c of
            VCtor (GName _ "QZero") _ -> CZero
            VCtor (GName _ "QOne") _ -> COne
            VCtor (GName _ "QZeroOrOne") _ -> CZeroOrOne
            VCtor (GName _ "QOneOrMore") _ -> COneOrMore
            _ -> CZeroOrMore
      pure (oneShot, card)
    _ -> pure (False, CZeroOrMore)

-- | Is the quantity value the linear quantity @1@?
decodeLinearQuantity :: Value -> CheckM Bool
decodeLinearQuantity q0 = do
  q <- forceM q0
  pure $ case q of
    VPrim "__quantityOfNat" [VLit (LitInt 1)] -> True
    _ -> False

-- | Does the variable occur (syntactically) in the expression?
occursVar :: Text -> Expr -> Bool
occursVar v = go
  where
    go = \case
      EVar (Name n _) -> n == v
      EApp f as -> go f || any goA as
      EDot b _ -> go b
      EQDot b _ -> go b
      EOpChain els -> or [go x | ChainOperand x <- els]
      ETuple es _ -> any go es
      ERecordLit is _ -> or [go e | RecItem _ _ (Just e) <- is]
      ERecordPatch b items _ ->
        go b
          || or
            [ case it of
                PatchUpdate _ (PatchValue e) -> go e
                PatchExtend _ e -> go e
                PatchSection a e -> go a || go e
                PatchPun _ -> False
            | it <- items
            ]
      EListLit es _ -> any go es
      ESetLit es _ -> any go es
      EMapLit kvs _ -> any (\(k, w) -> go k || go w) kvs
      EIf alts mels _ -> any (\(c, t) -> go c || go t) alts || maybe False go mels
      EMatch s cs _ -> go s || or [maybe False go g || go b | MatchCase _ g b _ <- cs]
      ELambda _ _ b _ -> go b
      ELet bs b _ -> any (go . lbExpr) bs || go b
      EAscription e _ _ -> go e
      ESectionLeft e _ _ -> go e
      ESectionRight _ e _ -> go e
      EElvis a b _ -> go a || go b
      EIs e _ -> go e
      EThunk e _ -> go e
      ELazy e _ -> go e
      EForce e _ -> go e
      EBang _ e _ -> go e
      EStringLit _ parts _ -> any (go . ipExpr) parts
      EDo _ items _ -> any goItem items
      EComprehension _ cls yy _ ->
        any goClause cls || any go (yieldExprsOf yy)
      _ -> False
    goA = \case
      ArgExplicit e -> go e
      ArgImplicit e -> go e
      ArgInout e _ -> go e
      ArgNamedBlock fs _ -> or [maybe False go me | (_, me) <- fs]
    goItem = \case
      DoBind lb -> go (lbExpr lb)
      DoLet lb -> go (lbExpr lb)
      DoLetQ _ e mfb _ -> go e || maybe False (go . snd) mfb
      DoExpr e -> go e
      _ -> True -- conservative for loops/var/defer items
    goClause = \case
      S.CFor _ _ _ src _ -> go src
      S.CLet _ _ _ rhs _ -> go rhs
      S.CIf e -> go e
      S.COrderBy ks _ -> any (go . snd) ks
      S.CSkip e _ -> go e
      S.CTake e _ -> go e
      S.CDistinct me _ -> maybe False go me
      S.CGroupBy k aggs _ _ -> go k || or [go e || maybe False go mu | (_, e, mu) <- aggs]
      S.CJoin _ _ src cond _ _ -> go src || go cond

yieldExprsOf :: CompYield -> [Expr]
yieldExprsOf = \case
  YieldExpr e -> [e]
  YieldPair k v -> [k, v]

-- | Surface pattern variables, in binding order.
surfPatVars :: Pattern -> [Name]
surfPatVars = \case
  PWild _ -> []
  PVar n -> [n]
  PLit _ _ -> []
  PAs n p -> n : surfPatVars p
  PCtor _ ps _ -> concatMap surfPatVars ps
  PCtorNamed _ fs _ -> concatMap surfPatVars [p | (_, Just p) <- fs]
  PActive _ _ p _ -> surfPatVars p
  PTuple ps _ -> concatMap surfPatVars ps
  PUnit _ -> []
  PRecord fs mrest _ ->
    concatMap (\(_, n, mp) -> maybe [n] surfPatVars mp) fs
      ++ [n | Just (PatRestBind n) <- [mrest]]
  PTyped p _ _ -> surfPatVars p
  POr ps _ -> case ps of
    (p : _) -> surfPatVars p
    [] -> []
  POpChain p chain _ -> surfPatVars p ++ concatMap (surfPatVars . snd) chain
  PVariant mb _ _ mrest _ -> maybe [] pure mb ++ maybe [] pure mrest

-- | Per-clause pass-1 annotation consumed by the desugaring pass.
data CAnn = CAnn
  { caKind :: !SrcKind -- ^ generator/join source kind
  , caForceRefut :: !Bool -- ^ desugar with a wildcard fallback case
  }

defaultAnn :: CAnn
defaultAnn = CAnn SKUnknown False

-- | Pass-1 result: plan metadata plus pending diagnostics.
data CompPlan = CompPlan
  { cpAnns :: ![CAnn]
  , cpOneShot :: !Bool
  , cpCard :: !QCard
  , cpItemLinear :: !Bool
  , cpDiags :: ![(Span, Text, Maybe Text, Text)]
  }

-- | Pass 1: infer the comprehension plan. Elaboration side effects
-- (diagnostics, metas) are rolled back; only the plan survives.
planComp :: Ctx -> [S.CompClause] -> CompYield -> Span -> CheckM CompPlan
planComp ctx0 clauses yld _sp = do
  st0 <- get
  plan <- go ctx0 [] True False COne [] [] clauses
  put st0
  pure plan
  where
    linsOf row = [v | (v, True) <- row]
    directComponent v = goD
      where
        goD = \case
          EVar (Name n _) -> n == v
          ETuple es _ -> any goD es
          ERecordLit is _ -> or [goD e | RecItem _ _ (Just e) <- is]
          EAscription e _ _ -> goD e
          _ -> False
    pend csp code fam msg = (csp, code, fam, msg)
    dropMsg what vs csp =
      pend csp "E_QUERY_ROW_NOT_DROPPABLE" (Just "kappa.quantity.unsatisfied")
        (what <> " may discard the current row, but linear row entry '"
           <> T.intercalate "', '" vs <> "' is not droppable (§20.10.4)")
    go _ctx row _ordered oneShot card anns diags [] = do
      -- the yielded item carries quantity 1 only when a linear row
      -- entry flows into it as a direct component (not when an
      -- application consumes the entry and yields its result)
      let lins = linsOf row
          itemLinear = not (null [v | v <- lins, any (directComponent v) (yieldExprsOf yld)])
      pure (CompPlan (reverse anns) oneShot card itemLinear (reverse diags))
    go ctx row ordered oneShot card anns diags (c : cs) = case c of
      S.CFor refut _ pat src csp -> do
        (_, srcTy) <- infer ctx src
        si <- sourceInfo ctx srcTy
        irr <- irrefutableFor ctx pat (siItem si)
        let lins = linsOf row
            refutD =
              [ pend csp "E_QUERY_FOR_REFUTABLE" (Just "kappa-hs.query.refutable-for")
                  "the pattern of a 'for' clause must be irrefutable for the element type; use the refutable form 'for?' instead (§20.4)"
              | not refut && not irr
              ]
            dropD = [dropMsg "the refutable generator 'for?'" lins csp | refut, not (null lins)]
            dupD =
              [ pend csp "E_QUERY_ROW_NOT_DUPLICABLE" (Just "kappa.quantity.unsatisfied")
                  ("a nested 'for' over a zero-or-many source may drop or duplicate the current row, but linear row entry '"
                     <> T.intercalate "', '" lins <> "' is neither droppable nor duplicable (§20.10.4)")
              | not refut
              , not (null lins)
              , cardManyHi (siCard si) || cardZeroLo (siCard si)
              ]
        (_, ctx', patternRefinements) <-
          elabPattern ctx pat (siItem si)
        let row' = row ++ [(nameText n, siItemLinear si) | n <- surfPatVars pat]
        withPatternRefinements patternRefinements $
          go ctx' row' (ordered && siOrdered si) (oneShot || siOneShot si)
            (mulCard card (siCard si))
            (CAnn (siKind si) (not irr) : anns)
            (reverse (refutD ++ dropD ++ dupD) ++ diags)
            cs
      S.CLet refut pat mty rhs csp -> do
        rhsTy <- case mty of
          Just tyE -> do
            (tyTm, _) <- inferType ctx tyE
            tyV <- evalIn ctx tyTm
            _ <- check ctx rhs tyV
            pure tyV
          Nothing -> snd <$> infer ctx rhs
        irr <- irrefutableFor ctx pat rhsTy
        let lins = linsOf row
            refutD =
              [ pend csp "E_REFUTABLE_LET_PATTERN" (Just "kappa-hs.pattern.refutable-binding")
                  "a 'let' comprehension clause requires an irrefutable pattern; use 'let?' instead (§20.4.1)"
              | not refut && not irr
              ]
            dropD = [dropMsg "the refutable binding 'let?'" lins csp | refut, not (null lins)]
        (_, ctx', patternRefinements) <- elabPattern ctx pat rhsTy
        let row' = row ++ [(nameText n, False) | n <- surfPatVars pat]
        withPatternRefinements patternRefinements $
          go ctx' row' ordered oneShot (if refut then filterCard card else card)
            (CAnn SKUnknown (not irr) : anns)
            (reverse (refutD ++ dropD) ++ diags)
            cs
      S.CIf cond -> do
        let lins = linsOf row
            dropD =
              [ pend (exprSpan cond) "E_QUERY_ROW_NOT_DROPPABLE" (Just "kappa.quantity.unsatisfied")
                  ("an 'if' filter may drop the current row, but linear row entry '"
                     <> T.intercalate "', '" lins <> "' is not droppable (§20.10.4)")
              | not (null lins)
              ]
        go ctx row ordered oneShot (filterCard card) (defaultAnn : anns) (dropD ++ diags) cs
      S.COrderBy keys csp -> do
        let lins = linsOf row
        consumed <- concat <$> mapM (consumesLin ctx lins . snd) keys
        let consD =
              [ pend csp "E_QUERY_ORDER_KEY_CONSUMES" (Just "kappa-hs.query.order-key")
                  ("an 'order by' key is checked in a non-consuming context, but this key consumes linear row entry '"
                     <> T.intercalate "', '" (nub consumed) <> "' (§20.6.1)")
              | not (null consumed)
              ]
        go ctx row True oneShot card (defaultAnn : anns) (consD ++ diags) cs
      S.CSkip _ csp -> pagingClause ctx row ordered oneShot card anns diags cs "skip" csp
      S.CTake _ csp -> pagingClause ctx row ordered oneShot card anns diags cs "take" csp
      S.CDistinct _ csp -> do
        let lins = linsOf row
            dropD = [dropMsg "'distinct' deduplication" lins csp | not (null lins)]
        go ctx row ordered oneShot (filterCard card) (defaultAnn : anns) (dropD ++ diags) cs
      S.CGroupBy key aggs n csp -> do
        (_, kTy) <- infer ctx key
        aggTys <- forM aggs $ \(an, ae, _) -> do
          (_, aTy) <- infer ctx ae
          pure (nameText an, aTy)
        let keyD =
              [ pend csp "E_QUERY_GROUP_KEY_FIELD" (Just "kappa-hs.query.group")
                  "the group record always contains the field 'key'; an aggregate may not be named 'key' (§20.7)"
              | any ((== "key") . fst) aggTys
              ]
            recTy = VRecordT (sortOn fst (("key", kTy) : aggTys))
            ctx' = bindCtx (nameText n) False recTy ctx
        go ctx' [(nameText n, False)] False oneShot CZeroOrMore (defaultAnn : anns) (keyD ++ diags) cs
      S.CJoin left pat src cond mInto csp -> do
        (_, srcTy) <- infer ctx src
        si <- sourceInfo ctx srcTy
        let lins = linsOf row
        case (left, mInto) of
          (True, Just into) -> do
            let captured = [v | v <- lins, occursVar v src || occursVar v cond]
                capD =
                  [ pend csp "E_QUERY_LEFT_JOIN_LINEAR_CAPTURE" (Just "kappa-hs.query.left-join")
                      ("the delayed inner query of a 'left join ... into' may not capture linear row entry '"
                         <> T.intercalate "', '" captured <> "' (§20.8)")
                  | not (null captured)
                  ]
                qTy =
                  VGlobN prelQueryCore
                    [ (Expl, VCtor prelQueryMode [VCtor prelReusable [], VCtor prelQZeroOrMore []])
                    , (Expl, VPrim "__omegaQ" [])
                    , (Expl, siItem si)
                    ]
                ctx' = bindCtx (nameText into) False qTy ctx
                row' = row ++ [(nameText into, False)]
            go ctx' row' (ordered && siOrdered si) (oneShot || siOneShot si) card
              (CAnn (siKind si) False : anns) (capD ++ diags) cs
          _ -> do
            let dupD =
                  [ pend csp "E_QUERY_ROW_NOT_DUPLICABLE" (Just "kappa.quantity.unsatisfied")
                      ("a 'join' may drop or duplicate the current row, but linear row entry '"
                         <> T.intercalate "', '" lins <> "' is neither droppable nor duplicable (§20.10.4)")
                  | not (null lins)
                  ]
            (_, ctx', patternRefinements) <-
              elabPattern ctx pat (siItem si)
            let row' = row ++ [(nameText nm, siItemLinear si) | nm <- surfPatVars pat]
            withPatternRefinements patternRefinements $
              go ctx' row' (ordered && siOrdered si) (oneShot || siOneShot si)
                (mulCard card (filterCard (siCard si)))
                (CAnn (siKind si) False : anns) (dupD ++ diags) cs
    pagingClause ctx row ordered oneShot card anns diags cs what csp = do
      let lins = linsOf row
          ordD =
            [ pend csp "E_QUERY_UNORDERED_PAGING" (Just "kappa.query.orderedness")
                ("'" <> what <> "' requires an Ordered pipeline, but the pipeline is unordered here; insert an 'order by' before paging (§20.6.2)")
            | not ordered
            ]
          dropD = [dropMsg ("'" <> what <> "' paging") lins csp | not (null lins)]
      go ctx row ordered oneShot (filterCard card) (defaultAnn : anns) (ordD ++ dropD ++ diags) cs

-- | Which linear row entries does an ordering/distinct key expression
-- consume? Direct arguments at borrow-or-unrestricted callee binders
-- are non-consuming; quantity-1/>=1 binders and bare moves consume.
consumesLin :: Ctx -> [Text] -> Expr -> CheckM [Text]
consumesLin _ [] _ = pure []
consumesLin ctx lins e0 = case e0 of
  EVar (Name v _) -> pure [v | v `elem` lins]
  EDot b _ -> case b of
    EVar _ -> pure [] -- borrowed place read (§12.4 approximation)
    _ -> consumesLin ctx lins b
  EAscription e _ _ -> consumesLin ctx lins e
  EApp (EVar f) args -> do
    st0 <- get
    (_, fTy0) <- resolveName ctx f
    fTy <- forceM fTy0
    put st0
    let explQs = piExplQs fTy
        explArgs = [e | ArgExplicit e <- args]
        slot (mq, arg) = case arg of
          EVar (Name v _)
            | v `elem` lins ->
                pure [v | mq `elem` [Just Q1, Just QGe1, Nothing]]
          _ -> consumesLin ctx lins arg
    concat <$> mapM slot (zip (map Just explQs ++ repeat Nothing) explArgs)
  _ -> pure [v | v <- lins, occursVar v e0]
  where
    piExplQs ty = case ty of
      VPi Expl q _ _ _ clo -> q : piExplQs (peek clo)
      VPi Impl _ _ _ _ clo -> piExplQs (peek clo)
      _ -> []
    -- peeking under the binder with a dummy is enough for quantities
    peek (Closure env body) =
      eval (EvalCtx (Globals Map.empty) Map.empty False Map.empty) (VSort LZero : env) body

-- | The elaborated carrier prefix of a prefixed comprehension (§20.9):
-- the prefix term and its (forced) type.
type CarrierPrefix = (Term, Value)

elabComprehension :: Ctx -> CompKind -> [S.CompClause] -> CompYield -> Span -> CheckM (Term, Value)
elabComprehension ctx kind clauses yld sp = elabComprehensionC ctx kind clauses yld sp Nothing

elabComprehensionC :: Ctx -> CompKind -> [S.CompClause] -> CompYield -> Span -> Maybe CarrierPrefix -> CheckM (Term, Value)
elabComprehensionC ctx kind clauses yld sp mCarrier = do
  plan <- planComp ctx clauses yld sp
  forM_ (cpDiags plan) $ \(dsp, code, fam, msg) -> errAt dsp code fam msg
  lowered <- desugarComp ctx (zip clauses (cpAnns plan ++ repeat defaultAnn)) yld sp
  case mCarrier of
    Just prefix -> collectCarrier ctx kind plan lowered prefix sp
    Nothing -> case kind of
      CompList -> infer ctx lowered
      CompSet -> do
        eqLam <- pairEqLam sp
        infer ctx (prelApp1 sp "__setFromList" [prelApp1 sp "__distinctBy" [lowered, eqLam]])
      CompMap mconf -> do
        eqLam <- pairEqLam sp
        comb <- conflictLam ctx mconf sp
        infer ctx (prelApp1 sp "__mapFromEntries" [prelApp1 sp "__mapResolve" [lowered, eqLam, comb]])
      CompCarrier _ -> infer ctx lowered

prelApp1 :: Span -> Text -> [Expr] -> Expr
prelApp1 sp n es = EApp (EVar (Name n sp)) (map ArgExplicit es)

-- | @\\a b -> a == b@.
pairEqLam :: Span -> CheckM Expr
pairEqLam sp = do
  a <- freshNameM "__a"
  b <- freshNameM "__b"
  let an = Name a sp
      bn = Name b sp
  pure $
    ELambda Nothing [simpleBinder an, simpleBinder bn]
      (EApp (EOpRef Nothing (Name "==" sp) sp) [ArgExplicit (EVar an), ArgExplicit (EVar bn)])
      sp

-- | The map-conflict combine function (§20.5.1); default keep last.
conflictLam :: Ctx -> Maybe OnConflict -> Span -> CheckM Expr
conflictLam ctx mconf sp = case fromMaybe KeepLast mconf of
  KeepLast -> two (\_ b -> EVar b)
  KeepFirst -> two (\a _ -> EVar a)
  CombineWith f -> pure f
  CombineUsing w -> case ctorRefOfExpr w of
    Just cref -> do
      a <- freshNameM "__old"
      b <- freshNameM "__new"
      x <- freshNameM "__x"
      let an = Name a sp
          bn = Name b sp
          xn = Name x sp
          wrap e = EApp w [ArgExplicit e]
          appended = prelApp1 sp "append" [wrap (EVar an), wrap (EVar bn)]
      pure $
        ELambda Nothing [simpleBinder an, simpleBinder bn]
          (EMatch appended [MatchCase (PCtor cref [PVar xn] sp) Nothing (EVar xn) sp] sp)
          sp
    Nothing -> do
      _ <- unsupported ctx sp "this 'combine using' wrapper form"
      two (\_ b -> EVar b)
  where
    two f = do
      a <- freshNameM "__old"
      b <- freshNameM "__new"
      let an = Name a sp
          bn = Name b sp
      pure (ELambda Nothing [simpleBinder an, simpleBinder bn] (f an bn) sp)

ctorRefOfExpr :: Expr -> Maybe CtorRef
ctorRefOfExpr = \case
  EVar n -> Just (CtorRef Nothing n)
  EDot (EVar q) (DotName n) -> Just (CtorRef (Just q) n)
  _ -> Nothing

-- | Speculatively elaborate the head of a possible carrier-prefixed
-- comprehension (§20.9). 'Just' when the prefix is type-valued: either
-- a fully applied result type or a unary @Type -> Type@ sink head. The
-- caller restores elaboration state when this returns 'Nothing'.
carrierPrefix :: Ctx -> Expr -> [Arg] -> CheckM (Maybe CarrierPrefix)
carrierPrefix ctx f preArgs = do
  let headE = if null preArgs then f else EApp f preArgs
  case f of
    EVar _ -> goInfer headE
    EDot _ _ -> goInfer headE
    EApp _ _ -> goInfer headE
    _ -> pure Nothing
  where
    goInfer headE = do
      n0 <- gets (length . csDiags)
      -- §7.2: a carrier prefix is a type expression, so a same-spelling
      -- data family selects its TYPE facet (inferT), not the constructor
      (hTm, hTy) <- inferT ctx headE
      n1 <- gets (length . csDiags)
      hTy' <- forceM hTy
      if n1 /= n0
        then pure Nothing
        else case hTy' of
          VSort _ -> pure (Just (hTm, hTy'))
          VPi Expl _ _ _ dom _ -> do
            domF <- forceM dom
            case domF of
              VSort _ -> pure (Just (hTm, hTy'))
              _ -> pure Nothing
          _ -> pure Nothing

-- | Terminal collection through an explicit carrier prefix (§20.9).
collectCarrier :: Ctx -> CompKind -> CompPlan -> Expr -> CarrierPrefix -> Span -> CheckM (Term, Value)
collectCarrier ctx kind plan lowered (prefTm, prefTy) sp = do
  (listTm0, listTy) <- infer ctx lowered
  itemV <- elemOfList listTy
  candidate <- case prefTy of
    VSort _ -> evalIn ctx prefTm
    VPi Expl _ _ _ _ _ -> do
      itemTm <- quoteIn ctx itemV
      evalIn ctx (CApp Expl prefTm itemTm)
    _ -> freshMetaV ctx
  cand <- forceM candidate
  -- §20.9 custom sinks: a FromComprehensionRaw instance is preferred
  -- over FromComprehensionPlan; both run their Elab hook here
  mSink <- sinkHook cand itemV
  case mSink of
    Just r -> pure r
    Nothing -> builtinCarrier listTm0 listTy itemV candidate cand
  where
    sinkHook cand itemV = do
      rawGoal <- globalValueM prelFromComprehensionRaw [(Expl, cand)]
      mRaw <- trySpec (instanceSearch ctx sp rawGoal)
      mPlan <-
        case mRaw of
          Just (Just _) -> pure Nothing
          _ -> do
            planGoal <- globalValueM prelFromComprehensionPlan [(Expl, cand)]
            fmap ((,) planGoal) <$> trySpec (instanceSearch ctx sp planGoal)
      let chosen = case (mRaw, mPlan) of
            (Just (Just dict), _) ->
              Just
                ( prelFromComprehensionRaw
                , rawGoal
                , dict
                , "fromComprehensionRaw"
                , "__rawComprehension"
                )
            (_, Just (planGoal, Just dict)) ->
              Just
                ( prelFromComprehensionPlan
                , planGoal
                , dict
                , "fromComprehensionPlan"
                , "__comprehensionPlan"
                )
            _ -> Nothing
      case chosen of
        Nothing -> pure Nothing
        Just (trait, goal, dictTm, method, token) -> do
          -- the associated Item must be definitionally equal to the
          -- normalized yielded item type (§20.9). Use the checked member
          -- telescope selected for this exact trait goal; evaluating a raw
          -- dictionary projection here would discard its specialized
          -- universe/evidence spine.
          (itemTerm, _) <-
            knownTraitMemberProjection ctx sp trait "Item" goal dictTm
          -- Associated static members are compile-time computations. The
          -- checked accessor above preserves the selected trait/evidence and
          -- universe spine; normalize that exact application so an instance
          -- definition such as @Item = row@ exposes its specialized result.
          -- Ordinary evaluation intentionally leaves global definitions
          -- opaque and would compare two unrelated neutrals here.
          itemMember <- evalRT ctx itemTerm
          normalizedItemMember <- forceM itemMember
          normalizedYieldItem <- forceM itemV
          okItem <- unify ctx normalizedItemMember normalizedYieldItem
          if not okItem
            then do
              iT <- quoteIn ctx =<< forceM itemMember
              yT <- quoteIn ctx =<< forceM itemV
              errAt sp "E_SINK_ITEM_MISMATCH" (Just "kappa-hs.query.sink")
                ("the selected sink's associated 'Item' type '" <> renderTerm iT
                   <> "' is not definitionally equal to the yielded item type '" <> renderTerm yT <> "' (§20.9)")
              Just <$> anyHole ctx
            else do
              (methodTerm, _) <-
                knownTraitMemberProjection ctx sp trait method goal dictTm
              methodValue <- evalRT ctx methodTerm
              action <- vappRT methodValue [VPrim token []]
              res <- runElab ctx sp action
              case res of
                Left () -> Just <$> anyHole ctx
                Right sv -> do
                  mtm <- spliceSyntaxValue ctx sp cand sv
                  case mtm of
                    Nothing -> Just <$> anyHole ctx
                    Just tm -> pure (Just (tm, cand))
    builtinCarrier listTm0 listTy _itemV candidate cand = case cand of
      VGlobN (GName _ "QueryCore") [(_, m), (_, q), (_, a)] -> do
        -- §20.9: the Query carriers cannot silently discard map/set
        -- collection metadata
        case kind of
          CompMap _ -> do
            errAt sp "E_QUERY_METADATA_LOSS" (Just "kappa-hs.query.sink")
              "a 'Query { ... }' map comprehension is ill-formed: the Query carrier would silently discard the map metadata (§20.9)"
          CompSet -> do
            errAt sp "E_QUERY_METADATA_LOSS" (Just "kappa-hs.query.sink")
              "a 'Query {| ... |}' set comprehension is ill-formed: the Query carrier would silently discard the set metadata (§20.9)"
          _ -> pure ()
        (expOneShot, expCard) <- decodeQueryMode m
        expLinear <- decodeLinearQuantity q
        when (cpOneShot plan && not expOneShot) $
          errAt sp "E_QUERY_MODE_MISMATCH" (Just "kappa-hs.query.mode")
            "this comprehension's plan is one-shot, but the carrier requires a reusable query; use 'OnceQuery [ ... ]' or an explicitly indexed 'QueryCore' carrier (§20.9)"
        unless (cardSub (cpCard plan) expCard) $
          errAt sp "E_QUERY_CARDINALITY_MISMATCH" (Just "kappa-hs.query.cardinality")
            ("the inferred plan cardinality " <> cardName (cpCard plan)
               <> " cannot be checked against the demanded cardinality " <> cardName expCard
               <> "; cardinality may only be widened (§20.10.1)")
        when (cpItemLinear plan && not expLinear) $
          errAt sp "E_QUERY_ITEM_QUANTITY_MISMATCH" (Just "kappa-hs.query.item-quantity")
            "the yielded item is available only at linear quantity 1, but the carrier demands unrestricted (ω) items (§20.9)"
        listTm <- checkAsList listTm0 listTy a
        converted <- globalAppM prelQueryFromList [(Expl, listTm)]
        pure (converted, candidate)
      VGlobN (GName _ "Array") [(_, a)] -> do
        listTm <- checkAsList listTm0 listTy a
        converted <- globalAppM prelArrayFromList [(Expl, listTm)]
        pure (converted, candidate)
      VGlobN (GName _ "List") [(_, a)] -> do
        listTm <- checkAsList listTm0 listTy a
        pure (listTm, candidate)
      VGlobN (GName _ "Set") [(_, a)] -> do
        listTm <- checkAsList listTm0 listTy a
        converted <- globalAppM prelSetFromList [(Expl, listTm)]
        pure (converted, candidate)
      _ -> unsupported ctx sp "this comprehension carrier"
    elemOfList ty = do
      t <- forceM ty
      case t of
        VGlobN (GName _ "List") [(_, a)] -> pure a
        _ -> freshMetaV ctx
    checkAsList tm ty a = do
      listT <- globalValueM prelList [(Expl, a)]
      expectType ctx sp ty listT
      pure tm

-- | Pass 2: desugar the clause pipeline over lists (§20.10.11 as-if).
-- The pipeline expression has type @List Row@ where @Row@ is the tuple
-- of the variables bound so far.
desugarComp :: Ctx -> [(S.CompClause, CAnn)] -> CompYield -> Span -> CheckM Expr
desugarComp ctx clauses yld sp = do
  (vars, pipe) <- foldM step ([], EListLit [EUnit sp] sp) clauses
  yf <- perRow vars (yieldElem yld)
  pure (prelApp1 sp "__pipeMap" [pipe, yf])
  where
    yieldElem = \case
      YieldExpr e -> e
      YieldPair k v ->
        ERecordLit [RecItem False (Name "key" sp) (Just k), RecItem False (Name "value" sp) (Just v)] sp

    rowE vars = case vars of
      [] -> EUnit sp
      [v] -> EVar v
      vs -> ETuple (map EVar vs) sp
    rowP vars = case vars of
      [] -> PWild sp
      [v] -> PVar v
      vs -> PTuple (map PVar vs) sp

    perRow vars body = do
      r <- freshNameM "__row"
      let rn = Name r sp
      pure $
        ELambda Nothing [simpleBinder rn]
          (EMatch (EVar rn) [MatchCase (rowP vars) Nothing body sp] sp)
          sp

    cmap f l = prelApp1 sp "__pipeConcatMap" [l, f]

    wrapSrc k src = case k of
      SKQuery -> prelApp1 sp "__queryToList" [src]
      SKSet -> prelApp1 sp "__setToList" [src]
      SKMap -> prelApp1 sp "__mapToList" [src]
      SKOption -> prelApp1 sp "__optionToList" [src]
      SKArray -> prelApp1 sp "__arrayToList" [src]
      SKRange -> prelApp1 sp "rangeToList" [src]
      SKIntoQuery ->
        prelApp1 sp "__intoQueryToListAs" [src]
      _ -> src

    -- element function: match one element against the pattern, emit
    -- the extended row on success (wildcard fallback when filtering)
    elemLam pat filtering successBody = do
      el <- freshNameM "__el"
      let en = Name el sp
          cases =
            MatchCase pat Nothing successBody sp
              : [MatchCase (PWild sp) Nothing (EListLit [] sp) sp | filtering]
      pure (ELambda Nothing [simpleBinder en] (EMatch (EVar en) cases sp) sp)

    step (vars, pipe) (clause, ann) = case clause of
      S.CFor refut _ pat src _ -> do
        let vars' = vars ++ surfPatVars pat
            filtering = refut || caForceRefut ann
        ef <- elemLam pat filtering (EListLit [rowE vars'] sp)
        f <- perRow vars (cmap ef (wrapSrc (caKind ann) src))
        pure (vars', cmap f pipe)
      S.CLet refut pat mty rhs _ -> do
        let vars' = vars ++ surfPatVars pat
            filtering = refut || caForceRefut ann
            rhs' = maybe rhs (\t -> EAscription rhs t sp) mty
            cases =
              MatchCase pat Nothing (EListLit [rowE vars'] sp) sp
                : [MatchCase (PWild sp) Nothing (EListLit [] sp) sp | filtering]
        f <- perRow vars (EMatch rhs' cases sp)
        pure (vars', cmap f pipe)
      S.CIf cond -> do
        f <- perRow vars (EIf [(cond, EListLit [rowE vars] sp)] (Just (EListLit [] sp)) sp)
        pure (vars, cmap f pipe)
      S.COrderBy keys _ -> do
        -- decorate-sort-undecorate: pair each row with its key tuple,
        -- stably sort on the keys, then drop the decoration (§20.6.1)
        let keyTuple = case keys of
              [(_, k)] -> k
              _ -> ETuple (map snd keys) sp
        deco <- perRow vars (ETuple [keyTuple, rowE vars] sp)
        cmp <- decoCmpLam keys
        und <- undecorateLam
        pure
          ( vars
          , prelApp1 sp "__pipeMap"
              [prelApp1 sp "__sortBy" [prelApp1 sp "__pipeMap" [pipe, deco], cmp], und]
          )
      S.CSkip n _ -> pure (vars, prelApp1 sp "__listDrop" [n, pipe])
      S.CTake n _ -> pure (vars, prelApp1 sp "__listTake" [n, pipe])
      S.CDistinct Nothing _ -> do
        eqLam <- rowEqLam vars
        pure (vars, prelApp1 sp "__distinctBy" [pipe, eqLam])
      S.CDistinct (Just k) _ -> do
        -- decorate with the key, dedupe on it via Eq, undecorate
        deco <- perRow vars (ETuple [k, rowE vars] sp)
        pure (vars, prelApp1 sp "__distinctOnFst" [prelApp1 sp "__pipeMap" [pipe, deco]])
      S.CGroupBy key aggs n _ -> do
        kf <- perRow vars key
        eqLam <- pairEqLam sp
        let groups = prelApp1 sp "__groupBy" [pipe, kf, eqLam]
        g <- freshNameM "__g"
        let gn = Name g sp
            gRows = EDot (EVar gn) (DotName (Name "rows" sp))
        aggItems <- forM aggs $ \(an, ae, mUsing) -> do
          valF <- perRow vars ae
          body <- case mUsing of
            Nothing -> pure (prelApp1 sp "__aggFold" [gRows, valF])
            Just w -> case ctorRefOfExpr w of
              Just cref -> do
                r <- freshNameM "__r"
                x <- freshNameM "__x"
                let rn = Name r sp
                    xn = Name x sp
                    wrapF =
                      ELambda Nothing [simpleBinder rn]
                        (EApp w [ArgExplicit (EApp valF [ArgExplicit (EVar rn)])])
                        sp
                    folded = prelApp1 sp "__aggFold" [gRows, wrapF]
                pure (EMatch folded [MatchCase (PCtor cref [PVar xn] sp) Nothing (EVar xn) sp] sp)
              Nothing -> do
                _ <- unsupported ctx (exprSpan w) "this aggregate 'using' wrapper form"
                pure (prelApp1 sp "__aggFold" [gRows, valF])
          pure (RecItem False an (Just body))
        let rec' =
              ERecordLit
                (RecItem False (Name "key" sp) (Just (EDot (EVar gn) (DotName (Name "key" sp)))) : aggItems)
                sp
            gLam = ELambda Nothing [simpleBinder gn] rec' sp
        pure ([n], prelApp1 sp "__pipeMap" [groups, gLam])
      S.CJoin True pat src cond (Just into) _ -> do
        let vars' = vars ++ [into]
        ef <- elemLamKeep pat cond
        let matches = cmap ef (wrapSrc (caKind ann) src)
            qVal = prelApp1 sp "__queryOfMatches" [matches]
            inner = ELet [LetBind False emptyPrefix (PVar into) Nothing qVal sp] (EListLit [rowE vars'] sp) sp
        f <- perRow vars inner
        pure (vars', cmap f pipe)
      S.CJoin _ pat src cond _ _ -> do
        let vars' = vars ++ surfPatVars pat
        ef <- elemLam pat True (EIf [(cond, EListLit [rowE vars'] sp)] (Just (EListLit [] sp)) sp)
        f <- perRow vars (cmap ef (wrapSrc (caKind ann) src))
        pure (vars', cmap f pipe)

    -- left join: keep the matching element itself (§20.8)
    elemLamKeep pat cond = do
      el <- freshNameM "__el"
      let en = Name el sp
          succBody = EIf [(cond, EListLit [EVar en] sp)] (Just (EListLit [] sp)) sp
          cases =
            [ MatchCase pat Nothing succBody sp
            , MatchCase (PWild sp) Nothing (EListLit [] sp) sp
            ]
      pure (ELambda Nothing [simpleBinder en] (EMatch (EVar en) cases sp) sp)

    -- row equality: componentwise (==) over the row tuple (§20.6.3)
    rowEqLam vars = do
      ra <- freshNameM "__ra"
      rb <- freshNameM "__rb"
      asV <- mapM (const (freshNameM "__qa")) vars
      bsV <- mapM (const (freshNameM "__qb")) vars
      let ran = Name ra sp
          rbn = Name rb sp
          aNames = map (`Name` sp) asV
          bNames = map (`Name` sp) bsV
          eqOne a b = EApp (EOpRef Nothing (Name "==" sp) sp) [ArgExplicit (EVar a), ArgExplicit (EVar b)]
          trueE = EVar (Name "True" sp)
          falseE = EVar (Name "False" sp)
          conj = foldr (\(a, b) acc -> EIf [(eqOne a b, acc)] (Just falseE) sp) trueE (zip aNames bNames)
          body =
            EMatch (EVar ran)
              [MatchCase (rowP aNames) Nothing (EMatch (EVar rbn) [MatchCase (rowP bNames) Nothing conj sp] sp) sp]
              sp
      pure (ELambda Nothing [simpleBinder ran, simpleBinder rbn] body sp)

    -- lexicographic stable comparator over decorated (keys, row)
    -- pairs (§20.6.1); 'desc' swaps the comparison operands
    decoCmpLam keys = do
      ra <- freshNameM "__pa"
      rb <- freshNameM "__pb"
      asV <- mapM (const (freshNameM "__ka")) keys
      bsV <- mapM (const (freshNameM "__kb")) keys
      let ran = Name ra sp
          rbn = Name rb sp
          aNames = map (`Name` sp) asV
          bNames = map (`Name` sp) bsV
          keyP ns = case ns of
            [v] -> PVar v
            vs -> PTuple (map PVar vs) sp
          pairP ns = PTuple [keyP ns, PWild sp] sp
          cmpOne desc a b =
            let (x, y) = if desc then (b, a) else (a, b)
             in prelApp1 sp "compare" [EVar x, EVar y]
          chain [] = prelApp1 sp "compare" [EIntLit 0 Nothing sp, EIntLit 0 Nothing sp]
          chain [(desc, a, b)] = cmpOne desc a b
          chain ((desc, a, b) : restK) =
            EMatch (cmpOne desc a b)
              [ MatchCase (PCtor (CtorRef Nothing (Name "EQ" sp)) [] sp) Nothing (chain restK) sp
              , MatchCase (PVar (Name "__o" sp)) Nothing (EVar (Name "__o" sp)) sp
              ]
              sp
          keyed = [(desc, a, b) | ((desc, _), (a, b)) <- zip keys (zip aNames bNames)]
          body =
            EMatch (EVar ran)
              [ MatchCase (pairP aNames) Nothing
                  (EMatch (EVar rbn) [MatchCase (pairP bNames) Nothing (chain keyed) sp] sp)
                  sp
              ]
              sp
      pure (ELambda Nothing [simpleBinder ran, simpleBinder rbn] body sp)

    -- drop the (keys, row) decoration after sorting
    undecorateLam = do
      p <- freshNameM "__p"
      r <- freshNameM "__r"
      let pn = Name p sp
          rn = Name r sp
      pure $
        ELambda Nothing [simpleBinder pn]
          (EMatch (EVar pn) [MatchCase (PTuple [PWild sp, PVar rn] sp) Nothing (EVar rn) sp] sp)
          sp

-- ── Declarations ─────────────────────────────────────────────────────

data DeclarationUniverseRoles = DeclarationUniverseRoles
  { durGeneralizable :: !(Set LevelMeta)
  , durMinimizable :: !(Set LevelMeta)
  }

-- | The source declaration interface used while a global's universe schema is
-- still provisional. A type alias exposes its manifest type value in addition
-- to the classifier stored in 'gdType'. Generated trait dictionaries and
-- member declarations own separate schemas and are deliberately excluded.
-- Deriving an early spine from 'gdType' alone makes aliases whose universes
-- occur only in their definiens appear monomorphic until it is too late to
-- repair retained uses.
globalUniverseInterfaceTerms :: CheckState -> GName -> GlobalDef -> [Term]
globalUniverseInterfaceTerms st global definition =
  globalCoreType ec definition
    : manifestTerms ++ effectTerms ++ instanceTerms
  where
    ec = ecOf st
    manifestTerms
      | global `Set.member` csUniverseInterfaceValues st =
          maybe [] (pure . quote ec 0) (gdValue definition)
      | otherwise = []
    effectTerms = effectUniverseInterfaceTerms st global
    -- The normalized instance head and premises are part of the dictionary's
    -- public declaration identity (§14.3.2). NbE-quoting 'gdType' preserves
    -- their ordinary type shape but deliberately erases 'CUniverseLift'
    -- evidence. The instance table is therefore the authority for classifier
    -- metas introduced by cumulative head arguments; omitting it lets those
    -- occurrence choices escape principalization and later be mistaken for
    -- declaration-local parameters.
    instanceTerms = instanceUniverseInterfaceTerms st global

globalCoreType :: EvalCtx -> GlobalDef -> Term
globalCoreType ec definition =
  fromMaybe (quote ec 0 (gdType definition)) (gdCoreType definition)

instanceUniverseInterfaceTerms :: CheckState -> GName -> [Term]
instanceUniverseInterfaceTerms st global =
  Map.findWithDefault [] global (csInstanceUniverseInterfaces st)

setCheckInstances :: [InstanceEntry] -> CheckState -> CheckState
setCheckInstances entries st =
  st
    { csInstances = entries
    , csInstanceUniverseInterfaces =
        Map.fromListWith
          (flip (++))
          [ ( ieDict entry
            , map CSort (ieTraitUniverses entry)
                ++ iePremises entry
                ++ ieHead entry
            )
          | entry <- entries
          ]
    }

-- | A source type alias exposes its defining value as part of the static
-- declaration interface. Levels occurring only in that value still need a
-- declaration schema even when the outer classifier itself is @Type0@.
-- Identity is recorded during alias elaboration, so type-producing ordinary
-- functions cannot be mistaken for interface equations.
globalValueIsUniverseInterface :: Set GName -> GName -> GlobalDef -> Bool
globalValueIsUniverseInterface aliases global definition =
  global `Set.member` aliases && isJust (gdValue definition)

-- | Before signed term bodies have been checked, every declaration whose
-- semantic interface depends (transitively) on one of those terms must remain
-- provisional as well. Finalizing only the signed term itself freezes caller
-- lifts and result classifiers against an incomplete callee schema. Constructor
-- facets participate independently but follow a deferred parent data facet.
declarationUniverseDeferralClosure :: CheckState -> Set GName -> Set GName
declarationUniverseDeferralClosure st roots = go roots
  where
    globals =
      Map.filterWithKey
        (\(GName owner _) _ -> owner == csModule st)
        (csGlobals st)
    constructors =
      Map.filterWithKey
        (\(GName owner _) _ -> owner == csModule st)
        (csCtors st)
    traitTerms global =
      maybe [] (map snd . tiSupers) (Map.lookup global (csTraits st))
    globalDependencies global definition =
      Set.unions . map globalsOfTerm $
        globalUniverseInterfaceTerms st global definition
          ++ traitTerms global
          ++ maybe [] pure (Map.lookup global (csCoreBodies st))
    constructorDependencies info = globalsOfTerm (ciType info)
    go known =
      let dependentGlobals =
            Map.keysSet
              ( Map.filterWithKey
                  (\global definition ->
                     not . Set.null $
                       Set.intersection known (globalDependencies global definition))
                  globals
              )
          dependentConstructors =
            Map.keysSet
              ( Map.filter
                  (\info ->
                     ciData info `Set.member` known
                       || not (Set.null (Set.intersection known (constructorDependencies info))))
                  constructors
              )
          next = Set.unions [known, dependentGlobals, dependentConstructors]
       in if next == known then known else go next

constraintMetaClosure :: Set LevelMeta -> [LevelConstraint] -> Set LevelMeta
constraintMetaClosure roots constraints =
  reachableLevelMetas (levelMetaAdjacency (map constraintLevelMetas constraints)) roots

constraintLevelMetas :: LevelConstraint -> Set LevelMeta
constraintLevelMetas constraint =
  Set.fromList (levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint))

-- | Treat each constraint's metavariables as one hyperedge. A star is enough
-- to preserve hypergraph connectivity and avoids materializing a quadratic
-- clique for constraints with several metas.
levelMetaAdjacency :: [Set LevelMeta] -> Map LevelMeta (Set LevelMeta)
levelMetaAdjacency =
  Map.fromListWith Set.union . concatMap connect
  where
    connect metas =
      case Set.minView metas of
        Nothing -> []
        Just (pivot, rest) ->
          (pivot, rest)
            : [ (meta, Set.singleton pivot)
              | meta <- Set.toList rest
              ]

reachableLevelMetas
  :: Map LevelMeta (Set LevelMeta)
  -> Set LevelMeta
  -> Set LevelMeta
reachableLevelMetas adjacency roots = go roots roots
  where
    go visited frontier
      | Set.null frontier = visited
      | otherwise =
          let neighbours =
                Set.unions
                  [ Map.findWithDefault Set.empty meta adjacency
                  | meta <- Set.toList frontier
                  ]
              fresh = Set.difference neighbours visited
           in go (Set.union visited fresh) fresh

-- | Connected components of the selected-meta constraint graph. Unselected
-- metas remain available as rigid dependencies inside each component, but do
-- not connect otherwise independent occurrence choices merely because those
-- occurrences specialize the same declaration parameter.
selectedConstraintGroups
  :: Set LevelMeta
  -> [LevelConstraint]
  -> [(Set LevelMeta, [LevelConstraint])]
selectedConstraintGroups selected constraints =
  [ (component, reverse (Map.findWithDefault [] componentId groupedReversed))
  | (componentId, component) <- zip [0 :: Int ..] components
  ]
  where
    entries =
      [ (constraint, Set.intersection selected (constraintLevelMetas constraint))
      | constraint <- constraints
      ]
    adjacency = levelMetaAdjacency (map snd entries)
    components = go selected
    componentOf =
      Map.fromList
        [ (meta, componentId)
        | (componentId, component) <- zip [0 :: Int ..] components
        , meta <- Set.toList component
        ]
    groupedReversed =
      List.foldl'
        (\grouped (constraint, metas) ->
           case Set.lookupMin metas >>= (`Map.lookup` componentOf) of
             Nothing -> grouped
             Just componentId ->
               Map.insertWith (++) componentId [constraint] grouped)
        Map.empty
        entries
    go remaining
      | Set.null remaining = []
      | otherwise =
          let component =
                reachableLevelMetas adjacency (Set.singleton (Set.findMin remaining))
           in component : go (Set.difference remaining component)

-- | Project source-generalizable identities through the current level
-- substitution without transferring their inference role to elaboration-only
-- metas occurring inside the resulting expression. Generalizability is
-- provenance, not a property inherited by the arms of a solved @max@. A
-- substitution may eliminate a source meta or identify it with another source
-- meta in the same declaration SCC; it must never turn a dependency occurrence
-- into a declaration parameter.
projectGeneralizableLevelMetas
  :: Map LevelMeta Level
  -> Set LevelMeta
  -> Set LevelMeta
projectGeneralizableLevelMetas assignments origins =
  Set.intersection origins . Set.fromList $
    [ projected
    | origin <- Set.toList origins
    , projected <-
        levelMetas
          (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
    ]

-- | Instantiate every constraint of a still-provisional declaration at each
-- recorded reference. This is the constraint half of fresh telescope
-- specialization: substituting only the callee type loses relationships such
-- as the payload lower bound in @List A : Type u@ and lets a caller invent an
-- unrelated schema parameter for the result classifier.
materializeProvisionalUniverseConstraintsFor :: Set GName -> CheckM ()
materializeProvisionalUniverseConstraintsFor owners =
  materializeProvisionalUniverseConstraintsWhere
    (\occurrence -> puiOwner occurrence `Set.member` owners)

-- | Materialize only occurrences retained by the selected declaration bodies.
-- This is the body-completion counterpart of the callee-oriented SCC helper
-- above: it closes a completed consumer without touching uses retained by
-- still-open declarations.
materializeProvisionalUniverseConstraintsConsumedBy :: Set GName -> CheckM ()
materializeProvisionalUniverseConstraintsConsumedBy consumers =
  materializeProvisionalUniverseConstraintsWhere
    (\occurrence ->
       maybe False (`Set.member` consumers) (puiConsumer occurrence))

materializeProvisionalUniverseConstraintsWhere
  :: (ProvisionalUniverseInstantiation -> Bool)
  -> CheckM ()
materializeProvisionalUniverseConstraintsWhere selected = do
  st <- get
  let isSelected occurrence =
        not (puiConstraintsMaterialized occurrence)
          && selected occurrence
      occurrences = reverse (filter isSelected (csProvisionalUniverseInstantiations st))
      constructorIndex = constructorsByData (csCtors st)
  forM_ occurrences $ \occurrence -> do
    current <- get
    let assignments = csLevelAssignments current
    let sourceSet = Set.fromList (puiSourceMetas occurrence)
        owner = puiOwner occurrence
        ownerSet =
          Set.insert owner
            (Map.keysSet (Map.findWithDefault Map.empty owner constructorIndex))
        -- The dependency SCC has already selected its principal assignment.
        -- Instantiate that solved judgment, not the stale pre-solve metas
        -- retained in the module-wide constraint log. Otherwise a minimized
        -- callee position is freshened as a new caller choice and can survive
        -- projection as an unrelated residual.
        ownedConstraints =
          map
            (substituteLevelConstraintMetas assignments)
            (levelConstraintsOwnedBy current ownerSet)
        internalMetas =
          Set.toAscList . Set.difference
            ( Set.fromList
                [ meta
                | constraint <- ownedConstraints
                , meta <- levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint)
                ]
            ) $
            sourceSet
    freshInternal <- replicateM (length internalMetas) freshLevelInstantiationMeta
    let substitution =
          Map.fromList
            ( zip (puiSourceMetas occurrence) (puiFreshLevels occurrence)
                ++ zip internalMetas freshInternal
            )
        substitute = substituteLevelMetas substitution
        substituteAssumptions =
          foldr
            (\(lower, upper) -> insertAssumption (substitute lower) (substitute upper))
            emptyAssumptions
            . assumptionsList
        instantiatedSourceImage sourceMeta =
          substitute
            (normalizeLevel (substituteLevelMetas assignments (LMeta sourceMeta)))
    specializationIds <-
      fmap concat . forM (zip (puiSourceMetas occurrence) (puiFreshLevels occurrence)) $
      \(sourceMeta, freshLevel) -> do
        let image = instantiatedSourceImage sourceMeta
        if normalizeLevel freshLevel == normalizeLevel image
          then pure []
          else do
            -- The source image belongs to a still-provisional declaration
            -- SCC. Record specialization as an equality judgment; assigning
            -- the fresh occurrence meta here would install a choice before
            -- the callee's principal telescope is known and could later
            -- require revision.
            let origin =
                  ConstraintOrigin
                    ("principal universe specialization of " <> gnameText owner)
                    "global reference"
                insert =
                  insertProvisionalLevelConstraintOwned
                    (puiIdentity occurrence)
                    (puiConsumer occurrence)
                    emptyAssumptions
                    origin
            sequence [insert freshLevel image, insert image freshLevel]
    copiedIds <-
      forM ownedConstraints $ \constraint ->
        insertProvisionalLevelConstraintOwned
          (puiIdentity occurrence)
          (puiConsumer occurrence)
          (substituteAssumptions (lcAssumptions constraint))
          (lcOrigin constraint)
          (substitute (lcLhs constraint))
          (substitute (lcRhs constraint))
    let materializedIds = Set.fromList (specializationIds ++ copiedIds)
    modify' $ \state ->
      state
        { csProvisionalUniverseInstantiations =
            [ if puiIdentity candidate == puiIdentity occurrence
                then
                  candidate
                    { puiConstraintsMaterialized = True
                    , puiMaterializedConstraintIds =
                        Set.union
                          materializedIds
                          (puiMaterializedConstraintIds candidate)
                    }
                else candidate
            | candidate <- csProvisionalUniverseInstantiations state
            ]
        }

-- | Minimize each declaration SCC's own result-classifier metas before
-- provisional dependency occurrences are materialized. A callee such as
-- @List : (A : Type u) -> Type r@ owns the principal choice @r = 0@;
-- allowing caller constraints to participate first can incorrectly identify
-- @r@ with the caller's reusable @u@ and make a Type0 carrier monomorphic.
-- Parameter-position metas and fresh dependency instantiations are left for
-- the complete SCC generalizer below.
minimizeOwnedDeclarationClassifiers
  :: Set GName
  -> Set GName
  -> Set GName
  -> Set GName
  -> Set GName
  -> CheckM ()
minimizeOwnedDeclarationClassifiers preexisting preexistingCtors sourceGlobals sourceCtors deferredGlobals =
  do
  st0 <- get
  let currentModule = csModule st0
      globals =
        Map.filterWithKey
          (\g@(GName owner _) definition ->
             owner == currentModule
               && g `Set.notMember` csFinalizedUniverseInterfaces st0
               -- A signed body may remain deferred, but a source-written
               -- universe schema is already a complete public interface.
               -- Close its checker-created occurrence levels before another
               -- declaration can observe the signature.
               && ( g `Set.notMember` deferredGlobals
                      || dutExplicit (gdUniverses definition)
                  )
               && (g `Set.notMember` preexisting || g `Set.member` sourceGlobals))
          (csGlobals st0)
      candidateNames = Map.keysSet globals
      ec0 = ecOf st0
      constructorTerms =
        constructorInterfaceTermsByOwner
          ( Map.filter
              (\info -> ciData info `Set.member` candidateNames)
              (csCtors st0)
          )
      termsOf g gd =
        globalUniverseInterfaceTerms st0 g gd
          ++ Map.findWithDefault [] g constructorTerms
          ++ maybe [] pure (Map.lookup g (csCoreBodies st0))
      dependencies terms =
        Set.toList
          (Set.intersection candidateNames (Set.unions (map globalsOfTerm terms)))
      graph =
        [ (g, g, dependencies (termsOf g gd))
        | (g, gd) <- Map.toList globals
        ]
      components =
        [ case component of
            AcyclicSCC g -> [g]
            CyclicSCC gs -> sort gs
        | component <- stronglyConnComp graph
        ]
      eligibleConstructors =
        Map.filterWithKey
          (\ctor info ->
             let ownerExplicit =
                   maybe False (dutExplicit . gdUniverses)
                     (Map.lookup (ciData info) (csGlobals st0))
              in ciData info `Set.member` candidateNames
                   && ctor `Set.notMember` csFinalizedUniverseInterfaces st0
                   && ciData info `Set.notMember` csFinalizedUniverseInterfaces st0
                   && (ctor `Set.notMember` deferredGlobals || ownerExplicit)
                   && (ciData info `Set.notMember` deferredGlobals || ownerExplicit)
                   && (ctor `Set.notMember` preexistingCtors || ctor `Set.member` sourceCtors))
          (csCtors st0)
      eligibleConstructorsByData = constructorsByData eligibleConstructors
      generalizableByOwner =
        levelMetasByOwner (csLevelGeneralizableOwners st0)
  forM_ components $ \component -> do
    st <- get
    let ec = ecOf st
        assignments = csLevelAssignments st
        zonk = zonkLevels assignments
        terms =
          [ zonk term
          | g <- component
          , Just gd <- [Map.lookup g (csGlobals st)]
          , term <- globalUniverseInterfaceTerms st g gd
          ]
        componentSet = Set.fromList component
        ownedSymbols =
          Set.union componentSet . Set.unions $
            [ Map.keysSet
                (Map.findWithDefault Map.empty owner eligibleConstructorsByData)
            | owner <- component
            ]
        roles = mconcat (map declarationUniverseRoles terms)
        explicitInterfaceMetas =
          Set.fromList
            [ meta
            | g <- component
            , Just gd <- [Map.lookup g (csGlobals st)]
            , dutExplicit (gdUniverses gd)
            , term <- globalUniverseInterfaceTerms st g gd
            , meta <- levelMetasOfTerm (zonk term)
            ]
        ownedGeneralizableMetas =
          levelMetasOwnedBy generalizableByOwner ownedSymbols
        ordinaryClassifierTargets =
          Set.difference
            ( Set.difference
                (Set.difference (durMinimizable roles) (durGeneralizable roles))
                (csLevelGeneralizableMetas st)
            )
            (csLevelInstantiationMetas st)
        -- An explicit schema has no inferred public level parameters. Any
        -- residual interface meta not introduced by source syntax is a
        -- dependency-occurrence choice and must receive its principal value
        -- under this declaration's own constraints. In particular this
        -- closes @UIO A@ to the written rigid @u@ before callers instantiate
        -- the signature. Source-generalizable metas remain errors for the
        -- complete explicit-schema check; never minimize them as recovery.
        explicitOccurrenceTargets =
          Set.difference explicitInterfaceMetas ownedGeneralizableMetas
        targets = Set.union ordinaryClassifierTargets explicitOccurrenceTargets
        constraints =
          map
            (substituteLevelConstraintMetas assignments)
            (levelConstraintsOwnedBy st ownedSymbols)
    unless (Set.null targets) $
      do
        let diagnosticSpan = Span "<universe-inference>" (Pos 1 1) (Pos 1 1)
            explicitSchema =
              any
                (\g -> maybe False (dutExplicit . gdUniverses) (Map.lookup g (csGlobals st)))
                component
        inferred <-
          inferPrincipalAtDeclarationBoundary
            diagnosticSpan (map gKey component) explicitSchema targets constraints
        case inferred of
          PrincipalBoundarySolved candidate -> installLevelAssignments candidate
          PrincipalBoundaryDeferred -> pure ()
          PrincipalBoundaryRejected -> pure ()
    -- A dependency's principal source-meta image is now fixed. Materialize its
    -- recorded fresh specializations before the next (dependent) SCC is
    -- minimized, so caller result classifiers see the callee's equalities and
    -- lower bounds instead of defaulting independently.
    materializeProvisionalUniverseConstraintsFor ownedSymbols

instance Semigroup DeclarationUniverseRoles where
  DeclarationUniverseRoles g1 m1 <> DeclarationUniverseRoles g2 m2 =
    DeclarationUniverseRoles (Set.union g1 g2) (Set.union m1 m2)

instance Monoid DeclarationUniverseRoles where
  mempty = DeclarationUniverseRoles Set.empty Set.empty

-- | During header elaboration an inferred declaration is referenced through
-- a provisional telescope containing every level meta visible in its raw
-- interface. Principalization may later minimize some of those positions or
-- identify them with retained parameters. The finalized reference must apply
-- the resulting telescope morphism; merely preserving the provisional spine
-- gives one global two incompatible arities.
data UniverseReferenceProjection = UniverseReferenceProjection
  { urpSourceArity :: !Int
  , urpRetainedPositions :: ![Int]
  }
  deriving (Eq, Show)

-- | Global and constructor facets share the 'GName' namespace but may have
-- different universe schemas (notably @data T = T@).  Keep their provisional
-- spine projections separate so finalization cannot apply the constructor
-- telescope to the type facet or vice versa.
data UniverseReferenceProjections = UniverseReferenceProjections
  { urpGlobals :: !(Map (GName, Int) UniverseReferenceProjection)
  , urpConstructors :: !(Map (GName, Int) UniverseReferenceProjection)
  , urpExactGlobals :: !(Map (GName, [Level]) UniverseReferenceProjection)
  , urpExactConstructors :: !(Map (GName, [Level]) UniverseReferenceProjection)
  }
  deriving (Eq, Show)

deriveUniverseReferenceProjection
  :: Map LevelMeta Level
  -> [LevelMeta]
  -> [LevelMeta]
  -> Maybe UniverseReferenceProjection
deriveUniverseReferenceProjection assignments sourceMetas retainedMetas =
  deriveUniverseReferenceProjectionToLevels
    assignments sourceMetas (map LMeta retainedMetas)

deriveUniverseReferenceProjectionToLevels
  :: Map LevelMeta Level
  -> [LevelMeta]
  -> [Level]
  -> Maybe UniverseReferenceProjection
deriveUniverseReferenceProjectionToLevels assignments sourceMetas retainedLevels = do
  positions <- traverse positionOf retainedLevels
  guard (length positions == length (nub positions))
  pure (UniverseReferenceProjection (length sourceMetas) positions)
  where
    sourceImages =
      [ normalizeLevel (substituteLevelMetas assignments (LMeta sourceMeta))
      | sourceMeta <- sourceMetas
      ]
    positionOf retained =
      List.findIndex (== normalizeLevel retained) sourceImages

uniqueUniverseReferenceProjections
  :: Ord key
  => [(key, Maybe UniverseReferenceProjection)]
  -> Map key UniverseReferenceProjection
uniqueUniverseReferenceProjections alternatives =
  Map.mapMaybe selectProjection
    (Map.fromListWith (++) [(key, [projection]) | (key, projection) <- alternatives])
  where
    selectProjection possibilities =
      case sequence possibilities of
        Just projections -> case nub projections of
          [projection] -> Just projection
          _ -> Nothing
        Nothing -> Nothing

rewriteProvisionalUniverseReferences
  :: UniverseReferenceProjections
  -> Term
  -> Term
rewriteProvisionalUniverseReferences projections term =
  mapPatternConstructorUniverses projectConstructorSpine (walk 0 term)
  where
    walk depth = mapTermWithDepth rewrite depth

    projectConstructorSpine target universes =
      case
          Map.lookup (target, universes) (urpExactConstructors projections)
            <|> Map.lookup (target, length universes) (urpConstructors projections) of
        Just projection
          | length universes == urpSourceArity projection ->
              [universes !! position | position <- urpRetainedPositions projection]
        _ -> universes

    rewrite depth = \case
      CGlobal target universes
        | Just projection <-
            Map.lookup (target, universes) (urpExactGlobals projections)
              <|> Map.lookup (target, length universes) (urpGlobals projections)
        , length universes == urpSourceArity projection ->
            Just
              ( CGlobal target
                  [ universes !! position
                  | position <- urpRetainedPositions projection
                  ]
              )
      CCtorI target universes annotation arguments
        | Just projection <-
            Map.lookup (target, universes) (urpExactConstructors projections)
              <|> Map.lookup (target, length universes) (urpConstructors projections)
        , length universes == urpSourceArity projection ->
            -- 'mapTermWithDepth' is pre-order.  Recurse explicitly when this
            -- node is rewritten so nested references are projected too.
            Just
              ( CCtorI target
                  [ universes !! position
                  | position <- urpRetainedPositions projection
                  ]
                  (fmap (walk depth) annotation)
                  [argument {caTerm = walk depth (caTerm argument)} | argument <- arguments]
              )
      _ -> Nothing

-- | Unconditional atomic inequalities form a preorder on level metas. By
-- antisymmetry, every strongly connected component denotes one universe
-- identity. Quotienting these identities before minimization preserves a
-- single generalizable parameter; feeding the cycle to the least-lower-bound
-- solver would instead monomorphize the whole component to zero.
equivalentLevelMetaAssignments
  :: Set LevelMeta
  -> Set LevelMeta
  -> Set LevelMeta
  -> [LevelConstraint]
  -> Map LevelMeta Level
equivalentLevelMetaAssignments protectedGeneralizable generalizable minimizable constraints =
  Map.fromList
    [ (meta, LMeta representative)
    | component <- stronglyConnComp graph
    , let members = case component of
            AcyclicSCC meta -> [meta]
            CyclicSCC metas -> sort metas
    , let representative =
            List.minimumBy (\left right -> compare (priority left) (priority right)) members
    , meta <- members
    , meta /= representative
    -- A source parameter owned by another declaration is rigid at this
    -- boundary. Only fresh occurrence metas, or source identities owned by
    -- this declaration itself, may be redirected to the local representative.
    , meta `Set.notMember` protectedGeneralizable
        || meta `Set.member` generalizable
    ]
  where
    -- Preserve inference-role provenance across the quotient. A class that
    -- contains a source-generalizable meta denotes that source choice even if
    -- it also contains fresh dependency-instantiation metas. Otherwise prefer
    -- a minimizable representative so quotienting cannot accidentally turn an
    -- elaboration choice into a declaration schema parameter (§11.1.2.4A).
    priority meta
      | meta `Set.member` generalizable = (0 :: Int, meta)
      | meta `Set.member` minimizable = (1, meta)
      | otherwise = (2, meta)
    edges =
      [ (lower, upper)
      | constraint <- constraints
      , null (assumptionsList (lcAssumptions constraint))
      , LMeta lower <- [normalizeLevel (lcLhs constraint)]
      , LMeta upper <- [normalizeLevel (lcRhs constraint)]
      ]
    vertices = Set.toAscList (Set.fromList (concat [[lower, upper] | (lower, upper) <- edges]))
    graph =
      [ (meta, meta, [upper | (lower, upper) <- edges, lower == meta])
      | meta <- vertices
      ]

-- | A source-generalizable level remains a schema parameter unless the
-- completed declaration constraints determine it uniquely (§11.1.2.4A).
-- Compute the ordinary least candidate, then require the unconditional
-- constraint closure to prove equality in both directions. This discharges
-- pinned levels such as @0 <= u, u <= 0@ without turning a one-sided lower
-- bound into accidental monomorphism.
uniquelyDeterminedLevelMetaAssignments
  :: Set LevelMeta
  -> Set LevelMeta
  -> [LevelConstraint]
  -> Map LevelMeta Level
uniquelyDeterminedLevelMetaAssignments protectedGeneralizable generalizable constraints =
  Map.fromList
    [ (meta, candidate)
    | meta <- Set.toAscList generalizable
    , let target = Set.singleton meta
    , Right solution <- [solveLevelConstraintsFor target unconditional]
    , let candidate =
            normalizeLevel
              (Map.findWithDefault LZero meta (lsAssignments solution))
    , meta `notElem` levelMetas candidate
    -- A different source-generalizable identity is not a closed solution for
    -- this declaration. Collapsing the two here makes one declaration's
    -- schema depend on an unrelated owner's SCC order; any true same-SCC
    -- equality has already been quotient-ed by
    -- 'equivalentLevelMetaAssignments'.
    , Set.null
        ( Set.intersection protectedGeneralizable
            (Set.fromList (levelMetas candidate))
        )
    , constrainedLeq (LMeta meta) candidate
    , constrainedLeq candidate (LMeta meta)
    ]
  where
    unconditional =
      [ constraint
      | constraint <- constraints
      , null (assumptionsList (lcAssumptions constraint))
      ]
    -- 'proveLevelLeq' deliberately blocks on metas because its public use is
    -- rigid proof checking. At principalization time these exact constraints
    -- are the facts being solved, so use their directed reachability without
    -- treating a meta as a rigid proof identity. Expanding a maximum on the
    -- lower side is the ordinary join-semilattice elimination law.
    edges =
      nub
        [ (normalizeLevel lower, normalizeLevel (lcRhs constraint))
        | constraint <- unconditional
        , lower <- flattenLowerMax (lcLhs constraint)
        ]
    constrainedLeq lower upper =
      proveLevelLeq emptyAssumptions lower upper == Proved
        || reachable Set.empty [normalizeLevel lower]
      where
        target = normalizeLevel upper
        reachable _ [] = False
        reachable seen (current : rest)
          | current == target = True
          | current `Set.member` seen = reachable seen rest
          | otherwise =
              reachable
                (Set.insert current seen)
                ([next | (source, next) <- edges, source == current] ++ rest)
    flattenLowerMax = \case
      LMax left right -> flattenLowerMax left ++ flattenLowerMax right
      level -> [level]

-- | Classify the universe occurrences in one declaration interface as required
-- by §11.1.3. Parameter domains expose reusable universe choices and therefore
-- generalize. The terminal sort is the declaration/result classifier and is
-- minimized. A meta occurring in both sets remains generalizable unless the
-- constraint solver has already determined it uniquely.
declarationUniverseRoles :: Term -> DeclarationUniverseRoles
declarationUniverseRoles = go
  where
    go = \case
      CPiM _ _ _ _ _ domain codomain ->
        DeclarationUniverseRoles
          (Set.fromList (levelMetasOfTerm domain))
          Set.empty
          <> go codomain
      CUniverseLift _ _ _ term -> go term
      CSort level ->
        DeclarationUniverseRoles Set.empty (Set.fromList (levelMetas level))
      term ->
        DeclarationUniverseRoles
          (Set.fromList (levelMetasOfTerm term))
          Set.empty

-- | A constructor's terminal data-family application repeats the owning
-- declaration's universe spine; it is not a second source of generalized
-- parameters. Constructor telescope domains may introduce genuine local
-- universe choices, so only those domains contribute roles here.
constructorUniverseRoles :: Term -> DeclarationUniverseRoles
constructorUniverseRoles = go
  where
    go = \case
      CPiM _ _ _ _ _ domain codomain ->
        DeclarationUniverseRoles
          (Set.fromList (levelMetasOfTerm domain))
          Set.empty
          <> go codomain
      CUniverseLift _ _ _ term -> go term
      _ -> mempty

-- | Constructor telescopes are part of their owning data declaration's
-- observable interface.  In particular, references from one constructor
-- field to a sibling data family are semantic declaration dependencies even
-- though they do not occur in the family's result kind.  Every universe SCC
-- pass must therefore include these terms, or mutually recursive data schemas
-- become source-order dependent (§§11.1.2.3A and 15.16).
constructorInterfaceTermsByOwner :: Map GName CtorInfo -> Map GName [Term]
constructorInterfaceTermsByOwner =
  Map.fromListWith (++)
    . map (\info -> (ciData info, [ciType info]))
    . Map.elems

-- | Solve result-classifier metas before the SCC is generalized. The ordinary
-- solver cannot be run over every interface meta here: doing so would choose a
-- least monomorphic level for parameter-position metas which the spec requires
-- us to generalize. Explicit schemas are complete, so every residual interface
-- meta in an explicit declaration is instead a minimization obligation and is
-- never appended to the written telescope.
principalizeDeclarationUniverses
  :: Set GName
  -> Set GName
  -> Set GName
  -> Set GName
  -> Set GName
  -> CheckM ()
principalizeDeclarationUniverses preexisting preexistingCtors sourceGlobals sourceCtors deferredGlobals =
  do
  minimizeOwnedDeclarationClassifiers preexisting preexistingCtors sourceGlobals sourceCtors deferredGlobals
  st0 <- get
  let currentModule0 = csModule st0
      globals0 =
        Map.filterWithKey
          (\g@(GName owner _) _ ->
             owner == currentModule0
               && g `Set.notMember` csFinalizedUniverseInterfaces st0
               && g `Set.notMember` deferredGlobals
               && (g `Set.notMember` preexisting || g `Set.member` sourceGlobals))
          (csGlobals st0)
      ctors0 =
        Map.filterWithKey
          (\g@(GName owner _) info ->
             owner == currentModule0
               && g `Set.notMember` csFinalizedUniverseInterfaces st0
               && ciData info `Set.notMember` csFinalizedUniverseInterfaces st0
               && g `Set.notMember` deferredGlobals
               && ciData info `Set.notMember` deferredGlobals
               && (g `Set.notMember` preexistingCtors || g `Set.member` sourceCtors))
          (csCtors st0)
      ec0 = ecOf st0
      universeInterfaceValues0 = csUniverseInterfaceValues st0
      existingAssignments = csLevelAssignments st0
      zonk0 = zonkLevels existingAssignments
      traitInterfaceTerms0 =
        Map.fromListWith (++)
          [ (g, valueTerms ++ superTerms)
          | (g, info) <- Map.toList (Map.restrictKeys (csTraits st0) (Map.keysSet globals0))
          , let valueTerms =
                  maybe [] (maybe [] (pure . zonk0 . quote ec0 0) . gdValue) (Map.lookup g globals0)
                superTerms = map (zonk0 . snd) (tiSupers info)
          ]
      universeValueTerms0 =
        Map.mapMaybeWithKey
          (\global definition ->
             if globalValueIsUniverseInterface universeInterfaceValues0 global definition
               then zonk0 . quote ec0 0 <$> gdValue definition
               else Nothing)
          globals0
      globalInterfaceTerms0 =
        [ zonk0 term
        | (global, definition) <- Map.toList globals0
        , term <- globalUniverseInterfaceTerms st0 global definition
        ]
      roles0 =
        mconcat
          ( map declarationUniverseRoles globalInterfaceTerms0
              ++ map (constructorUniverseRoles . zonk0 . ciType) (Map.elems ctors0)
              ++ map declarationUniverseRoles (concat (Map.elems traitInterfaceTerms0))
              ++ map declarationUniverseRoles (Map.elems universeValueTerms0)
          )
      schemaGeneralizable0 =
        Set.unions
          ( map declarationSchemaGeneralizableMetas globalInterfaceTerms0
              ++ map (constructorSchemaGeneralizableMetas . zonk0 . ciType) (Map.elems ctors0)
              ++ map declarationSchemaGeneralizableMetas (concat (Map.elems traitInterfaceTerms0))
              ++ map declarationSchemaGeneralizableMetas (Map.elems universeValueTerms0)
          )
      generalizableOrigins0 =
        Set.intersection
          (csLevelGeneralizableMetas st0)
          schemaGeneralizable0
      instantiationOrigins0 =
        Set.difference
          (csLevelInstantiationMetas st0)
          generalizableOrigins0
      minimizableOrigins0 =
        Set.difference
          (Set.union (durMinimizable roles0) instantiationOrigins0)
          generalizableOrigins0
  componentState <- get
  let currentModule = csModule componentState
      globals =
        Map.filterWithKey
          (\g@(GName owner _) _ ->
             owner == currentModule
               && g `Set.notMember` csFinalizedUniverseInterfaces componentState
               && g `Set.notMember` deferredGlobals
               && (g `Set.notMember` preexisting || g `Set.member` sourceGlobals))
          (csGlobals componentState)
      candidateNames = Map.keysSet globals
      ec = ecOf componentState
      universeInterfaceValues = csUniverseInterfaceValues componentState
      rawGlobalTerms = Map.map (globalCoreType ec) globals
      rawBodyTerms = Map.restrictKeys (csCoreBodies componentState) candidateNames
      rawTraitInterfaceTerms =
        Map.fromListWith (++)
          [ (g, valueTerms ++ map snd (tiSupers info))
          | (g, info) <- Map.toList (Map.restrictKeys (csTraits componentState) candidateNames)
          , let valueTerms =
                  maybe [] (maybe [] (pure . quote ec 0) . gdValue) (Map.lookup g globals)
          ]
      rawInstanceInterfaceTerms =
        Map.fromList
          [ (g, instanceUniverseInterfaceTerms componentState g)
          | g <- Map.keys globals
          ]
      rawUniverseValueTerms =
        Map.mapMaybeWithKey
          (\global definition ->
             if globalValueIsUniverseInterface universeInterfaceValues global definition
               then quote ec 0 <$> gdValue definition
               else Nothing)
          globals
      rawConstructorTerms =
        constructorInterfaceTermsByOwner
          ( Map.filter
              (\info -> ciData info `Set.member` candidateNames)
              (csCtors componentState)
          )
      ctors0ByData = constructorsByData ctors0
      artifactTermsByOwner =
        Map.unionsWith
          (++)
          [ Map.map pure rawGlobalTerms
          , Map.map pure rawBodyTerms
          , rawTraitInterfaceTerms
          , rawInstanceInterfaceTerms
          , rawConstructorTerms
          , Map.map pure rawUniverseValueTerms
          ]
      artifactInstantiationOwners =
        Map.fromListWith
          Set.union
          [ (meta, Set.singleton owner)
          | (owner, terms) <- Map.toList artifactTermsByOwner
          , meta <- Set.toList (Set.fromList (concatMap levelMetasOfTerm terms))
          , meta `Set.member` csLevelInstantiationMetas componentState
          ]
      instantiationOwners =
        Map.unionWith
          Set.union
          (csLevelInstantiationOwners componentState)
          artifactInstantiationOwners
      generalizableByOwner =
        levelMetasByOwner
          (csLevelGeneralizableOwners componentState)
      instantiationByOwner =
        levelMetasByOwner
          instantiationOwners
      dependencies g =
        Set.toList . Set.intersection candidateNames . Set.unions . map globalsOfTerm $
          Map.findWithDefault [] g rawTraitInterfaceTerms
            ++ Map.findWithDefault [] g rawInstanceInterfaceTerms
            ++ Map.findWithDefault [] g rawConstructorTerms
            ++ maybe [] pure (Map.lookup g rawUniverseValueTerms)
            ++ maybe [] pure (Map.lookup g rawBodyTerms)
            ++ maybe [] pure (Map.lookup g rawGlobalTerms)
      graph = [(g, g, dependencies g) | g <- Map.keys globals]
      components =
        [ case component of
            AcyclicSCC g -> [g]
            CyclicSCC gs -> sort gs
        | component <- stronglyConnComp graph
        ]
      principalizationComponents =
        [ Set.union
            componentSet
            ( Set.unions
                [ Map.keysSet
                    (Map.findWithDefault Map.empty owner ctors0ByData)
                | owner <- component
                ]
            )
        | component <- components
        , let componentSet = Set.fromList component
        ]
  unless (Map.null artifactInstantiationOwners) $
    modify' $ \state ->
      state
        { csLevelInstantiationOwners =
            Map.unionWith
              Set.union
              (csLevelInstantiationOwners state)
              artifactInstantiationOwners
        }
  forM_ components $ \component -> do
      st <- get
      let
        componentSet = Set.fromList component
        componentCtors =
          Map.unions
            [ Map.findWithDefault Map.empty owner ctors0ByData
            | owner <- component
            ]
        ownedSymbols = Set.union componentSet (Map.keysSet componentCtors)
        assignments = csLevelAssignments st
        zonk = zonkLevels assignments
        currentGlobals = Map.restrictKeys (csGlobals st) componentSet
        globalTerms = Map.map (zonk . globalCoreType (ecOf st)) currentGlobals
        ctorTerms = Map.map (zonk . ciType) componentCtors
        traitInterfaceTerms =
          Map.fromListWith (++)
            [ (g, valueTerms ++ superTerms)
            | (g, info) <- Map.toList (Map.restrictKeys (csTraits st) componentSet)
            , let valueTerms =
                    maybe [] (maybe [] (pure . zonk . quote (ecOf st) 0) . gdValue)
                      (Map.lookup g currentGlobals)
                  superTerms = map (zonk . snd) (tiSupers info)
            ]
        instanceInterfaceTerms =
          Map.map (map zonk) (Map.restrictKeys rawInstanceInterfaceTerms componentSet)
        universeValueTerms = Map.map zonk (Map.restrictKeys rawUniverseValueTerms componentSet)
        interfaceTerms =
          Map.elems globalTerms
            ++ Map.elems ctorTerms
            ++ concat (Map.elems traitInterfaceTerms)
            ++ concat (Map.elems instanceInterfaceTerms)
            ++ Map.elems universeValueTerms
        inferredRoles =
          mconcat
            ( map declarationUniverseRoles (Map.elems globalTerms)
                ++ map constructorUniverseRoles (Map.elems ctorTerms)
                ++ map declarationUniverseRoles (concat (Map.elems traitInterfaceTerms))
                ++ map declarationUniverseRoles (concat (Map.elems instanceInterfaceTerms))
                ++ map declarationUniverseRoles (Map.elems universeValueTerms)
            )
        schemaGeneralizable =
          Set.unions
            ( map declarationSchemaGeneralizableMetas (Map.elems globalTerms)
                ++ map constructorSchemaGeneralizableMetas (Map.elems ctorTerms)
                ++ map declarationSchemaGeneralizableMetas (concat (Map.elems traitInterfaceTerms))
                ++ map declarationSchemaGeneralizableMetas (concat (Map.elems instanceInterfaceTerms))
                ++ map declarationSchemaGeneralizableMetas (Map.elems universeValueTerms)
            )
        explicitGlobals = Map.filter (dutExplicit . gdUniverses) currentGlobals
        -- A constructor spelling @C.{u}@ restates only the enclosing data
        -- family's explicit schema. Constructor-local binder classifiers may
        -- still contribute an inferred hidden suffix. The inherited
        -- 'dutExplicit' bit therefore cannot classify every meta in the
        -- constructor interface as covered by the source-written schema.
        explicitTerms =
          Map.elems (Map.restrictKeys globalTerms (Map.keysSet explicitGlobals))
            ++ concat
                 (Map.elems (Map.restrictKeys traitInterfaceTerms (Map.keysSet explicitGlobals)))
            ++ concat
                 (Map.elems (Map.restrictKeys instanceInterfaceTerms (Map.keysSet explicitGlobals)))
            ++ Map.elems (Map.restrictKeys universeValueTerms (Map.keysSet explicitGlobals))
        explicitMetas = Set.fromList (concatMap levelMetasOfTerm explicitTerms)
        interfaceMetas = Set.fromList (concatMap levelMetasOfTerm interfaceTerms)
        constraints =
          map
            (substituteLevelConstraintMetas assignments)
            (levelConstraintsOwnedBy st ownedSymbols)
        relevantMetas = constraintMetaClosure interfaceMetas constraints
        projectOrigins origins =
          Set.fromList
            [ projected
            | origin <- Set.toList origins
            , projected <-
                levelMetas
                  (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
            ]
        ownedGeneralizableOrigins =
          levelMetasOwnedBy generalizableByOwner ownedSymbols
        projectedGeneralizableOrigins =
          projectGeneralizableLevelMetas assignments ownedGeneralizableOrigins
        generalizableOrigins =
          Set.intersection projectedGeneralizableOrigins schemaGeneralizable
        ownedInstantiationOrigins =
          levelMetasOwnedBy instantiationByOwner ownedSymbols
        instantiationOrigins = projectOrigins ownedInstantiationOrigins
        instantiationMetas =
          Set.intersection relevantMetas
            (Set.difference instantiationOrigins generalizableOrigins)
        -- Explicit schema parameters are already rigid LParams. Any remaining
        -- source-generalizable meta retains that role: declaration explicitness
        -- cannot turn a polymorphic source position into a minimizable one.
        generalizable = generalizableOrigins
        explicitGeneralizable = Set.intersection explicitMetas generalizable
        -- Source provenance, not the incidental shape of elaborated Core, is
        -- the authority for generalization. Every other meta connected to the
        -- completed interface is an occurrence/result choice and must receive
        -- the SCC's principal least solution. In particular, constructor
        -- telescope domains contain freshly instantiated schemas whose Core
        -- shape is indistinguishable from a source binder after elaboration.
        minimizable =
          Set.unions
            [ durMinimizable inferredRoles
            , instantiationMetas
            , Set.difference relevantMetas generalizable
            ]
        -- A source-role identity is rigid outside the declaration component
        -- that owns it. Dependency terms can expose that identity while their
        -- fresh occurrence is still being principalized, but this component
        -- must solve the occurrence toward the source meta, never the source
        -- meta toward the occurrence. Otherwise one caller can erase another
        -- declaration's universe parameter and make schema inference depend on
        -- SCC traversal order.
        allProjectedGeneralizable =
          projectGeneralizableLevelMetas
            assignments
            (csLevelGeneralizableMetas st)
        foreignGeneralizable =
          Set.difference allProjectedGeneralizable projectedGeneralizableOrigins
        targets =
          Set.difference
            (Set.difference minimizable generalizable)
            foreignGeneralizable
      unless (Set.null explicitGeneralizable) $ do
        reportNoPrincipalUniverse component constraints True explicitGeneralizable
        -- Recovery is intentionally local and follows the diagnostic. It keeps
        -- later passes well scoped without making zero a successful schema
        -- specialization.
        installLevelAssignments (Map.fromSet (const LZero) explicitGeneralizable)
      unless (Set.null targets) $
        do
          let diagnosticSpan = Span "<universe-inference>" (Pos 1 1) (Pos 1 1)
          inferred <-
            inferPrincipalAtDeclarationBoundary
              diagnosticSpan
              (map gKey component)
              (not (Map.null explicitGlobals))
              targets
              constraints
          case inferred of
            PrincipalBoundarySolved candidate -> installLevelAssignments candidate
            PrincipalBoundaryDeferred -> pure ()
            PrincipalBoundaryRejected -> pure ()
  -- Source-generalizable identities are quotient-ed and uniquely solved only
  -- after every minimizable classifier/occurrence choice in the semantic SCC
  -- has reached its principal value. Reversing these phases can project a
  -- source role onto an unsolved dependency occurrence and freeze that
  -- internal choice into the public schema.
  principalizeOwnedGeneralizableMetas
    principalizationComponents
    minimizableOrigins0
  where
    reportNoPrincipalUniverse component constraints explicitSchema metas =
      reportNoPrincipalUniverseDiagnostic
        (Span "<universe-inference>" (Pos 1 1) (Pos 1 1))
        (map gKey component)
        explicitSchema
        metas
        constraints
        Nothing
        "declaration universe constraints have no unique principal solution (§11.1.3)"

-- | Complete steps 4 and 5 of §11.1.2.4A for one set of declaration owners,
-- after their minimizable metas have been solved. Constraint ownership is a
-- hard boundary: deferred declarations must not be influenced by an earlier
-- header pass that happens to share the same module state.
principalizeOwnedGeneralizableMetas
  :: [Set GName]
  -> Set LevelMeta
  -> CheckM ()
principalizeOwnedGeneralizableMetas semanticComponents minimizableOrigins =
  do
  initialState <- get
  let initialAssignments = csLevelAssignments initialState
      eligibleOwners = Set.unions semanticComponents
      componentOwners = Map.fromList (zip [0 :: Int ..] semanticComponents)
      ownerComponents =
        Map.fromList
          [ (owner, component)
          | (component, owners) <- Map.toList componentOwners
          , owner <- Set.toList owners
          ]
      generalizableByComponent =
        Map.map
          ( levelMetasOwnedBy
              ( levelMetasByOwner
                  (csLevelGeneralizableOwners initialState)
              )
          )
          componentOwners
      constraints =
        [ substituteLevelConstraintMetas initialAssignments constraint
        | constraint <- csLevelConstraints initialState
        , maybe False (`Set.member` eligibleOwners)
            (Map.lookup (lcIdentity constraint) (csLevelConstraintOwners initialState))
        ]
      constraintGroups =
        Map.fromListWith (++)
          [ ( owner >>= (`Map.lookup` ownerComponents)
            , [constraint]
            )
          | constraint <- constraints
          , let owner =
                  Map.lookup (lcIdentity constraint) (csLevelConstraintOwners initialState)
          ]
      generalizableFor = \case
        Nothing -> Set.empty
        Just component ->
          projectGeneralizableLevelMetas initialAssignments
            (Map.findWithDefault Set.empty component generalizableByComponent)
      equivalentCandidates =
        Map.fromListWith (++)
          [ (meta, [level])
          | (owner, ownerConstraints) <- Map.toList constraintGroups
          , (meta, level) <-
              Map.toList
                ( equivalentLevelMetaAssignments
                    (projectGeneralizableLevelMetas initialAssignments (csLevelGeneralizableMetas initialState))
                    (generalizableFor owner)
                    minimizableOrigins
                    ownerConstraints
                )
          ]
      equivalentAssignments =
        Map.map head
          (Map.filter ((== 1) . length . nub) equivalentCandidates)
  unless (Map.null equivalentAssignments) $
    installLevelAssignments equivalentAssignments

  determinedState <- get
  let determinedAssignments = csLevelAssignments determinedState
      zonkConstraint = substituteLevelConstraintMetas determinedAssignments
      determinedGeneralizableByComponent =
        Map.map
          ( levelMetasOwnedBy
              ( levelMetasByOwner
                  (csLevelGeneralizableOwners determinedState)
              )
          )
          componentOwners
      determinedConstraintGroups =
        Map.fromListWith (++)
          [ ( owner >>= (`Map.lookup` ownerComponents)
            , [zonkConstraint constraint]
            )
          | constraint <- csLevelConstraints determinedState
          , let owner =
                  Map.lookup (lcIdentity constraint) (csLevelConstraintOwners determinedState)
          , maybe False (`Set.member` eligibleOwners) owner
          ]
      projectedGeneralizableFor = \case
        Nothing -> Set.empty
        Just component ->
          projectGeneralizableLevelMetas determinedAssignments
            (Map.findWithDefault Set.empty component determinedGeneralizableByComponent)
      determinedCandidates =
        Map.fromListWith (++)
          [ (meta, [level])
          | (owner, ownerConstraints) <- Map.toList determinedConstraintGroups
          , (meta, level) <-
              Map.toList
                ( uniquelyDeterminedLevelMetaAssignments
                    (projectGeneralizableLevelMetas determinedAssignments (csLevelGeneralizableMetas determinedState))
                    (projectedGeneralizableFor owner)
                    ownerConstraints
                )
          ]
      uniquelyDeterminedAssignments =
        Map.map head
          (Map.filter ((== 1) . length . nub) determinedCandidates)
  unless (Map.null uniquelyDeterminedAssignments) $
    installLevelAssignments uniquelyDeterminedAssignments

-- | Principalize hidden-universe occurrences introduced after a declaration
-- interface has already been generalized. Bodies are checked after the
-- header boundary and may instantiate schemas in Core that never re-enters
-- interface generalization. Such metas are occurrence choices, never new
-- declaration parameters: solve their connected constraints and choose the
-- least level for an otherwise unconstrained occurrence.
principalizeFinalizedOccurrenceUniverses :: Set GName -> Set GName -> Set GName -> CheckM ()
principalizeFinalizedOccurrenceUniverses preexisting sourceGlobals deferredGlobals =
  do
  st <- get
  let currentModule = csModule st
      assignments = csLevelAssignments st
      zonk = zonkLevels assignments
      unresolved origin =
        not . null . levelMetas $
          normalizeLevel (substituteLevelMetas assignments (LMeta origin))
      unresolvedOwnedOwners =
        Set.unions
          [ owners
          | (origin, owners) <- Map.toList (csLevelInstantiationOwners st)
          , unresolved origin
          ]
      unresolvedUnownedInstantiationOrigins =
        Set.difference
          (Set.filter unresolved (csLevelInstantiationMetas st))
          (Map.keysSet (csLevelInstantiationOwners st))
      eligible g@(GName owner _) =
        owner == currentModule
          && g `Set.notMember` deferredGlobals
          && (g `Set.notMember` preexisting || g `Set.member` sourceGlobals)
      eligibleGlobals =
        Map.filterWithKey (\global _ -> eligible global) (csGlobals st)
      projectedUnownedInstantiationMetas =
        Set.fromList
          [ projected
          | origin <- Set.toList unresolvedUnownedInstantiationOrigins
          , projected <-
              levelMetas
                (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
          ]
      artifactTerms global definition =
        map zonk (globalUniverseInterfaceTerms st global definition)
          ++ maybe [] (pure . zonk) (Map.lookup global (csCoreBodies st))
      observableUnownedOwners
        | Set.null projectedUnownedInstantiationMetas = Set.empty
        | otherwise =
            Set.fromList
              [ global
              | (global, definition) <- Map.toList eligibleGlobals
              , let artifactMetas =
                      Set.fromList
                        (concatMap levelMetasOfTerm (artifactTerms global definition))
              , not
                  ( Set.null
                      (Set.intersection artifactMetas projectedUnownedInstantiationMetas)
                  )
              ]
      currentSymbols =
        Set.union
          observableUnownedOwners
          (Set.intersection (Map.keysSet eligibleGlobals) unresolvedOwnedOwners)
      belongsToCurrent global = global `Set.member` currentSymbols
      interfaceTerms =
        [ zonk term
        | (g, definition) <- Map.toList (csGlobals st)
        , belongsToCurrent g
        , term <- globalUniverseInterfaceTerms st g definition
        ]
      bodyTerms =
        [ zonk body
        | (g, body) <- Map.toList (csCoreBodies st)
        , belongsToCurrent g
        ]
      observableMetas =
        Set.fromList (concatMap levelMetasOfTerm (interfaceTerms ++ bodyTerms))
      relevantInstantiationOrigins =
        Set.filter
          (\origin ->
             let owners =
                   Map.findWithDefault Set.empty origin (csLevelInstantiationOwners st)
                 projected =
                   Set.fromList
                     ( levelMetas
                         (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
                     )
              in not (Set.null (Set.intersection currentSymbols owners))
                   || ( origin `Set.member` unresolvedUnownedInstantiationOrigins
                          && not (Set.null (Set.intersection observableMetas projected))
                      ))
          (csLevelInstantiationMetas st)
      instantiationMetas =
        Set.fromList
          [ projected
          | origin <- Set.toList relevantInstantiationOrigins
          , projected <-
              levelMetas
                (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
          ]
      generalizableMetas =
        Set.union
          (projectGeneralizableLevelMetas assignments (csLevelGeneralizableMetas st))
          ( durGeneralizable
              (mconcat (map declarationUniverseRoles interfaceTerms))
          )
      provisionalInstantiationMetas =
        Set.fromList
          [ meta
          | occurrence <- csProvisionalUniverseInstantiations st
          , not (puiConstraintsMaterialized occurrence)
          , let GName occurrenceModule _ = puiOwner occurrence
          , occurrenceModule == currentModule
          , puiOwner occurrence `Set.notMember` csFinalizedUniverseInterfaces st
          , level <- puiFreshLevels occurrence
          , meta <- levelMetas
              (normalizeLevel (substituteLevelMetas assignments level))
          ]
      currentConstraints =
        concat
          [ Map.findWithDefault [] owner (csLevelConstraintsByOwner st)
          | owner <- Set.toAscList currentSymbols
          ]
      ownedConstraintMetas =
        Set.fromList
          [ meta
          | constraint <- currentConstraints
          , meta <- levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint)
          ]
      -- A level can first enter through a polymorphic dependency occurrence
      -- and later become the inferred kind of a source declaration binder.
      -- The source role is authoritative: minimizing such a meta here would
      -- monomorphize the declaration before its SCC can generalize it.
      -- Likewise, occurrences of an unfinalized same-module declaration are
      -- not body-local choices yet. Their callee constraints are materialized
      -- by 'materializeProvisionalUniverseConstraints' in the complete SCC
      -- pass below; defaulting them here can select zero before a kind
      -- argument contributes its lower bound and desynchronize the rewritten
      -- Core spine from the retained constraint graph.
      seedInstantiationMetas =
        Set.difference
          (Set.difference instantiationMetas generalizableMetas)
          provisionalInstantiationMetas
      seedTargets =
        Set.intersection
          (Set.union observableMetas ownedConstraintMetas)
          seedInstantiationMetas
      constraints =
        [ substituteLevelConstraintMetas assignments constraint
        | constraint <- currentConstraints
        ]
      bodyMap = Map.restrictKeys (csCoreBodies st) currentSymbols
      bodyDependencies body =
        Set.toList (Set.intersection currentSymbols (globalsOfTerm body))
      bodyGraph =
        [ (owner, owner, bodyDependencies body)
        | (owner, body) <- Map.toList bodyMap
        ]
      recursiveComponentMembers =
        [ members
        | component <- stronglyConnComp bodyGraph
        , members <- case component of
            CyclicSCC owners -> [Set.fromList owners]
            AcyclicSCC owner
              | maybe False (Set.member owner . globalsOfTerm) (Map.lookup owner bodyMap) ->
                  [Set.singleton owner]
            _ -> []
        ]
      sameRecursiveComponent caller callee =
        any
          (\members -> caller `Set.member` members && callee `Set.member` members)
          recursiveComponentMembers
      declarationIdentityLevels global =
        case Map.lookup global (csGlobals st) of
          Nothing -> []
          Just definition
            | arity <- dutParameterCount (gdUniverses definition)
            , arity > 0 -> map LParam [0 .. arity - 1]
            | otherwise ->
                let terms =
                      map
                        (zonkLevels assignments)
                        (globalUniverseInterfaceTerms st global definition)
                    retained =
                      durGeneralizable
                        (mconcat (map declarationUniverseRoles terms))
                 in map LMeta . nub $
                      [ meta
                      | term <- terms
                      , meta <- levelMetasOfTerm term
                      , meta `Set.member` retained
                      ]
      identityCandidate occurrence = do
        guard (not (rsoExplicit occurrence))
        guard (sameRecursiveComponent (rsoCaller occurrence) (rsoCallee occurrence))
        let sourceLevels = declarationIdentityLevels (rsoCaller occurrence)
            calleeLevels = declarationIdentityLevels (rsoCallee occurrence)
            callerArity = length sourceLevels
            calleeArity = length calleeLevels
            targetLevels =
              map (normalizeLevel . substituteLevelMetas assignments) (rsoLevels occurrence)
        guard (callerArity > 0 && callerArity == calleeArity)
        guard (length targetLevels == callerArity)
        targetMetas <- traverse (\case LMeta meta -> Just meta; _ -> Nothing) targetLevels
        guard (all (`Set.member` csLevelInstantiationMetas st) targetMetas)
        let alternatives = zip targetMetas sourceLevels
            localChoices =
              Map.fromListWith (++) [(meta, [level]) | (meta, level) <- alternatives]
        guard
          ( all
              (\(meta, level) -> LMeta meta /= normalizeLevel level)
              alternatives
          )
        guard (all ((== 1) . length . nub) (Map.elems localChoices))
        let substitution = Map.map head localChoices
            affected constraint =
              any
                (`Map.member` substitution)
                (levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint))
            preserves constraint =
              let assumptions =
                    substituteLevelAssumptions substitution (lcAssumptions constraint)
                  lower = substituteLevelMetas substitution (lcLhs constraint)
                  upper = substituteLevelMetas substitution (lcRhs constraint)
               in proveLevelLeq assumptions lower upper == Proved
        guard (all preserves (filter affected constraints))
        pure alternatives
      identityAlternatives =
        Map.fromListWith (++)
          [ (meta, [level])
          | occurrence <- csRecursiveSchemaOccurrences st
          , alternatives <- maybeToList (identityCandidate occurrence)
          , (meta, level) <- alternatives
          ]
      identityDefaults =
        Map.map head
          (Map.filter ((== 1) . length . nub) identityAlternatives)
      connectedMetas = constraintMetaClosure seedTargets constraints
      -- §11.1.2.4B solves selected-meta SCCs together. The closure was
      -- previously used only to retain relevant constraints, leaving hidden
      -- occurrence metas unselected and turning ordinary occurrence chains
      -- into a spurious OutsidePortableInferenceFragment result. Select every
      -- connected occurrence-owned meta while continuing to exclude source
      -- schema identities and not-yet-materialized provisional occurrences.
      targets =
        Set.difference
          (Set.difference connectedMetas generalizableMetas)
          provisionalInstantiationMetas
      relevantConstraints =
        [ constraint
        | constraint <- constraints
        , let metas =
                Set.fromList
                  (levelMetas (lcLhs constraint) ++ levelMetas (lcRhs constraint))
        , not (Set.null (Set.intersection connectedMetas metas))
        ]
      targetGroups = selectedConstraintGroups targets relevantConstraints
  if Map.null identityDefaults
    then
      forM_ targetGroups $ \(componentTargets, componentConstraints) -> do
        let componentOwners =
              Set.fromList
                [ owner
                | constraint <- componentConstraints
                , Just owner <- [Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st)]
                , owner `Set.member` currentSymbols
                ]
            diagnosticSpan = Span "<universe-inference>" (Pos 1 1) (Pos 1 1)
        inferred <-
          inferPrincipalAtDeclarationBoundary
            diagnosticSpan
            (map gKey (Set.toAscList componentOwners))
            False
            componentTargets
            componentConstraints
        case inferred of
          PrincipalBoundarySolved candidate -> installLevelAssignments candidate
          PrincipalBoundaryDeferred -> pure ()
          PrincipalBoundaryRejected -> pure ()
    else do
      -- Re-enter with the identity defaults materialized so target components
      -- and constraints are recomputed from the new substitution. Each chosen
      -- meta disappears from 'identityCandidate', so recursion decreases.
      installLevelAssignments identityDefaults
      principalizeFinalizedOccurrenceUniverses preexisting sourceGlobals deferredGlobals

-- | Close solver-local universe occurrences in body-complete declarations
-- without publishing their declaration telescope early. Source metas remain
-- abstract; only fresh dependency/body occurrences are solved and reflected
-- into retained Core. This makes transparent delta reduction replayable for
-- following declarations while preserving one public generalization at the
-- complete semantic SCC boundary.
closeCompletedProvisionalBodyUniverses
  :: Set GName
  -> Set GName
  -> Set GName
  -> Set GName
  -> CheckM ()
closeCompletedProvisionalBodyUniverses preexisting sourceGlobals deferredGlobals owners
  | Set.null owners = pure ()
  | otherwise = do
      rewriteCompletedBodyUniverses owners
      beforeClose <- get
      let unresolvedOwners =
            Set.filter
              (\owner ->
                 maybe
                   False
                   (not . globalDefinitionBodyUniversesReplayable)
                   (Map.lookup owner (csGlobals beforeClose)))
              owners
      unless (Set.null unresolvedOwners) $ do
        materializeProvisionalUniverseConstraintsConsumedBy unresolvedOwners
        beforeSolve <- get
        let currentModule = csModule beforeSolve
            unrelatedCurrentGlobals =
              Set.fromList
                [ global
                | global@(GName ownerModule _) <- Map.keys (csGlobals beforeSolve)
                , ownerModule == currentModule
                , global `Set.notMember` unresolvedOwners
                ]
            scopedDeferredGlobals =
              Set.union deferredGlobals unrelatedCurrentGlobals
        principalizeFinalizedOccurrenceUniverses
          preexisting
          sourceGlobals
          scopedDeferredGlobals
        rewriteCompletedBodyUniverses unresolvedOwners

-- | Reflect already-solved body-local universe occurrences into retained Core
-- while preserving each declaration's source-generalizable metas. This fast
-- path is allocation and rewriting only; callers invoke the principal solver
-- afterwards only for bodies that remain unreplayable.
rewriteCompletedBodyUniverses :: Set GName -> CheckM ()
rewriteCompletedBodyUniverses owners = do
  st <- get
  let sourceMetas owner =
        Set.fromList . concat $
          Map.findWithDefault
            []
            owner
            (csProvisionalGlobalUniverseMetas st)
      rewriteBody owner body =
        evalState
          (zonkTermM 0 body)
          st
            { csLevelAssignments =
                Map.withoutKeys
                  (csLevelAssignments st)
                  (sourceMetas owner)
            }
      bodies' =
        Map.mapWithKey
          (\owner body ->
             if owner `Set.member` owners
               then rewriteBody owner body
               else body)
          (csCoreBodies st)
      stateWithBodies = st {csCoreBodies = bodies'}
      globals' =
        Map.mapWithKey
          (\owner definition ->
             case Map.lookup owner bodies' of
               Just body
                 | owner `Set.member` owners ->
                     globalDefWithCanonicalCoreBody
                       stateWithBodies
                       body
                       definition
               _ -> definition)
          (csGlobals st)
  put
    ( invalidateSemanticCaches
        stateWithBodies {csGlobals = globals'}
    )

-- | Recover the owning trait's universe occurrence from a generated member
-- accessor type. The accessor ABI is structural: after any generated
-- constraint binders and the owning trait's ordinary parameter telescope, the
-- next domain is the evidence dictionary. Its exact global identity, not a
-- source spelling, authenticates the prefix.
traitMemberOwnerUniverseMetas :: CheckState -> GName -> Term -> [LevelMeta]
traitMemberOwnerUniverseMetas state accessor accessorType =
  case Map.lookup accessor (csTraitMemberOwners state) of
    Nothing -> []
    Just owner ->
      case
          Map.lookup owner (csTraits state)
            >>= \info -> dictionaryDomain (tiParamCount info) accessorType
        of
        Nothing -> []
        Just domain ->
          case spineOfTerm domain of
            (CGlobal actualOwner universes, _)
              | actualOwner == owner -> nub (concatMap levelMetas universes)
            _ -> []
  where
    dictionaryDomain remaining = \case
      CPiEvidenceM _ _ _ _ _ _ assumption _ _ codomain
        | isJust assumption -> dictionaryDomain remaining codomain
      CPiEvidenceM _ _ _ _ _ _ _ _ domain codomain
        | remaining > 0 -> dictionaryDomain (remaining - 1) codomain
        | otherwise -> Just domain
      _ -> Nothing

-- | Generalize the still-observable universe metas of newly declared globals
-- into one hidden telescope per semantic declaration SCC (§11.1.2.3A).
-- Ordinary term metas are excluded by 'levelMetasOfTerm'.  References inside
-- the SCC are rewritten to pass the same hidden parameters; references to an
-- acyclic dependency forward precisely the metas that represented that
-- dependency during header elaboration.
generalizeDeclarationUniverses :: Set GName -> Set GName -> Set GName -> Set GName -> Set GName -> CheckM ()
generalizeDeclarationUniverses preexisting preexistingCtors sourceGlobals sourceCtors deferredGlobals =
  do
  captureState <- get
  let captureModule = csModule captureState
      finalizedAtCapture = csFinalizedUniverseInterfaces captureState
      capturableGlobals =
        Map.filterWithKey
          (\g@(GName owner _) _ ->
             owner == captureModule
               && g `Set.notMember` finalizedAtCapture
               && (g `Set.notMember` preexisting || g `Set.member` sourceGlobals))
          (csGlobals captureState)
      capturableConstructors =
        Map.filterWithKey
          (\g@(GName owner _) _ ->
             owner == captureModule
               && g `Set.notMember` finalizedAtCapture
               && (g `Set.notMember` preexistingCtors || g `Set.member` sourceCtors))
          (csCtors captureState)
      capturedGlobalMetas =
        Map.mapWithKey
          (\g gd ->
             [ nub
                 (concatMap levelMetasOfTerm
                   (globalUniverseInterfaceTerms captureState g gd))
             ])
          capturableGlobals
      capturedConstructorMetas =
        Map.map
          (\info -> [nub (levelMetasOfTerm (ciType info))])
          capturableConstructors
  modify' $ \state ->
    state
      { csProvisionalGlobalUniverseMetas =
          Map.unionWith
            (\existing new -> nub (existing ++ new))
            (csProvisionalGlobalUniverseMetas state)
            capturedGlobalMetas
      , csProvisionalConstructorUniverseMetas =
          Map.unionWith
            (\existing new -> nub (existing ++ new))
            (csProvisionalConstructorUniverseMetas state)
            capturedConstructorMetas
      }
  principalizeFinalizedOccurrenceUniverses preexisting sourceGlobals deferredGlobals
  provisionalState <- get
  let provisionalModule = csModule provisionalState
      finalizedInterfaces = csFinalizedUniverseInterfaces provisionalState
      provisionalGlobals =
        Map.filterWithKey
          (\g@(GName owner _) _ ->
             owner == provisionalModule
               && g `Set.notMember` deferredGlobals
               && (g `Set.notMember` preexisting || g `Set.member` sourceGlobals))
          (csGlobals provisionalState)
      provisionalCtors =
        Map.filterWithKey
          (\g@(GName owner _) info ->
             owner == provisionalModule
               && g `Set.notMember` deferredGlobals
               && ciData info `Set.notMember` deferredGlobals
               && (g `Set.notMember` preexistingCtors || g `Set.member` sourceCtors))
          (csCtors provisionalState)
      provisionalGlobalMetas =
        Map.restrictKeys
          (csProvisionalGlobalUniverseMetas provisionalState)
          (Map.keysSet provisionalGlobals)
      provisionalCtorMetas =
        Map.restrictKeys
          (csProvisionalConstructorUniverseMetas provisionalState)
          (Map.keysSet provisionalCtors)
      provisionalGeneralizableOwners =
        csLevelGeneralizableOwners provisionalState
      hasDeferredExplicitInterfaces =
        any
          (\(g, definition) ->
             g `Set.member` deferredGlobals
               && g `Set.notMember` finalizedInterfaces
               && dutExplicit (gdUniverses definition))
          (Map.toList (csGlobals provisionalState))
      hasUnfinalizedInterfaces =
        any (`Set.notMember` finalizedInterfaces) (Map.keys provisionalGlobals)
          || any (`Set.notMember` finalizedInterfaces) (Map.keys provisionalCtors)
  when (hasUnfinalizedInterfaces || hasDeferredExplicitInterfaces) $
    principalizeDeclarationUniverses
      preexisting preexistingCtors sourceGlobals sourceCtors deferredGlobals
  -- Principalizing declaration SCCs materializes every recorded use of their
  -- provisional telescope.  Those freshly materialized occurrence metas were
  -- intentionally excluded from the pass above while their callees were still
  -- provisional; close them now, before generalized parameters replace the
  -- declaration-local source metas and make the residual constraints escape
  -- their owning telescope.
  principalizeFinalizedOccurrenceUniverses preexisting sourceGlobals deferredGlobals
  st <- get
  let currentModule = csModule st
      candidates =
        Map.filterWithKey
          (\g@(GName owner _) gd ->
             owner == currentModule
               && g `Set.notMember` deferredGlobals
               && g `Set.notMember` csFinalizedUniverseInterfaces st
               && ( g `Set.notMember` preexisting
                      || g `Set.member` sourceGlobals
                  )
          )
          (csGlobals st)
      ctorCandidates =
        Map.filterWithKey
          (\g@(GName owner _) ci ->
             owner == currentModule
               && g `Set.notMember` deferredGlobals
               && ciData ci `Set.notMember` deferredGlobals
               && g `Set.notMember` csFinalizedUniverseInterfaces st
               && (g `Set.notMember` preexistingCtors || g `Set.member` sourceCtors)
          )
          (csCtors st)
  unless (Map.null candidates && Map.null ctorCandidates) $ do
    let ec = ecOf st
        assignments = csLevelAssignments st
        finalizedInterfaces = csFinalizedUniverseInterfaces st
        publicationTargets =
          Set.union (Map.keysSet candidates) (Map.keysSet ctorCandidates)
        ownerTerms =
          Map.unionsWith
            (++)
            [ Map.mapWithKey
                (\owner definition ->
                   globalCoreType ec definition
                     : maybe [] pure (Map.lookup owner (csCoreBodies st)))
                (csGlobals st)
            , Map.map (map snd . tiSupers) (csTraits st)
            , constructorInterfaceTermsByOwner (csCtors st)
            , Map.fromListWith
                (++)
                [ ( ieDict entry
                  , map CSort (ieTraitUniverses entry)
                      ++ iePremises entry
                      ++ ieHead entry
                  )
                | entry <- csInstances st
                ]
            , Map.fromListWith
                (++)
                [ ( piDictG entry
                  , map teDomain (piFvTele entry)
                      ++ piPremTms entry
                      ++ piArgTms entry
                  )
                | Just entry <- Map.elems (csPreInstances st)
                ]
            , Map.mapWithKey
                (\owner _ -> effectUniverseInterfaceTerms st owner)
                (csEffectInterfaces st)
            , Map.map
                (\case
                   PendingTraitNominalSummary _ _ clauses _ -> clauses
                   PendingDataNominalSummary {} -> [])
                (csNominalSummaryRequests st)
            ]
        publicationAffectedOwners =
          Map.keysSet
            ( Map.filter
                (\terms ->
                   not . Set.null . Set.intersection publicationTargets . Set.unions $
                     map globalsOfTerm terms)
                ownerTerms
            )
        ownerNeedsUniverseRewrite owner =
          gnameInModule owner currentModule
            && ( owner `Set.member` publicationTargets
                   || owner `Set.member` publicationAffectedOwners
               )
        constructorNeedsUniverseRewrite constructor info =
          ownerNeedsUniverseRewrite constructor
            || ownerNeedsUniverseRewrite (ciData info)
        zonkRawLevel = normalizeLevel . substituteLevelMetas assignments
        zonkRawLevels =
          zonkTermWith
            (\_ _ -> Nothing)
            (substituteLevelMetas assignments)
            0
        zonkRawTerm term = evalState (zonkTermM 0 term) st
        zonkRawTermPreserving preserved term =
          evalState
            (zonkTermM 0 term)
            st
              { csLevelAssignments =
                  Map.withoutKeys assignments preserved
              }
        originalRawTypes =
          Map.mapWithKey
            (\global definition ->
               Map.findWithDefault
                 (globalCoreType ec definition)
                 global
                 (csCoreSignatures st))
            candidates
        -- Bodies do not contribute hidden parameters: only the observable
        -- interface assigns inference roles. They do contribute semantic SCC
        -- edges, because the principal solve is performed once for the
        -- complete recursive declaration component (§11.1.2.4A).
        -- Ordinary definitions are represented authoritatively by
        -- 'csCoreBodies'. Quoting an NbE value here is both redundant and
        -- unsound for recursive SCCs: a mutually recursive closure can expand
        -- the cycle without bound. Only semantic values whose structure is
        -- itself part of the static interface need quoting.
        originalRawValues =
          Map.mapMaybeWithKey
            (\g definition -> do
               value <- gdValue definition
               guard
                 ( Map.member g (csTraits st)
                     || globalValueIsUniverseInterface
                          (csUniverseInterfaceValues st) g definition
                 )
               pure (quote ec 0 value))
            candidates
        originalRawBodies =
          Map.restrictKeys (csCoreBodies st) (Map.keysSet candidates)
        originalRawUniverseValues =
          Map.mapMaybeWithKey
            (\g value -> do
               definition <- Map.lookup g candidates
               guard
                 ( Map.notMember g (csTraits st)
                     && globalValueIsUniverseInterface
                          (csUniverseInterfaceValues st)
                          g
                          definition
                 )
               pure value)
            originalRawValues
        originalRawCtorTerms = Map.map ciType ctorCandidates
        originalRawTraitOnlyTerms =
          Map.map
            (map snd . tiSupers)
            (Map.restrictKeys (csTraits st) (Map.keysSet candidates))
        originalRawEffectTerms =
          Map.mapWithKey
            (\global _ -> effectUniverseInterfaceTerms st global)
            candidates
        originalRawInstanceTerms =
          Map.mapWithKey
            (\global _ -> instanceUniverseInterfaceTerms st global)
            candidates
        originalRawInterfaceTerms =
          Map.unionsWith
            (++)
            [ originalRawTraitOnlyTerms
            , originalRawEffectTerms
            , originalRawInstanceTerms
            ]
        originalRawTraitValues =
          Map.restrictKeys originalRawValues (Map.keysSet originalRawTraitOnlyTerms)
        projectOrigins origins =
          Set.fromList
            [ projected
            | origin <- Set.toList origins
            , projected <-
                levelMetas
                  (normalizeLevel (substituteLevelMetas assignments (LMeta origin)))
            ]
        sourceGeneralizableMetasFor owners =
          projectGeneralizableLevelMetas assignments . Set.fromList $
            [ meta
            | (meta, metaOwners) <- Map.toList provisionalGeneralizableOwners
            , not (Set.null (Set.intersection owners metaOwners))
            ]
        projectedInstantiationMetas =
          projectOrigins (csLevelInstantiationMetas st)
        candidateNames = Map.keysSet candidates
        originalRawCtorTermsByOwner =
          constructorInterfaceTermsByOwner ctorCandidates
        dependencyTerms g =
          [Map.findWithDefault (CGlob g) g originalRawTypes]
            ++ Map.findWithDefault [] g originalRawInterfaceTerms
            ++ Map.findWithDefault [] g originalRawCtorTermsByOwner
            ++ maybe [] pure (Map.lookup g originalRawUniverseValues)
            ++ maybe [] pure (Map.lookup g originalRawTraitValues)
            ++ maybe [] pure (Map.lookup g originalRawBodies)
        dependencies terms =
          Set.toList
            (Set.intersection candidateNames (Set.unions (map globalsOfTerm terms)))
        graph =
          [ (g, g, dependencies (dependencyTerms g))
          | g <- Map.keys originalRawTypes
          ]
        components =
          [ case component of
              AcyclicSCC g -> [g]
              CyclicSCC gs -> sort gs
          | component <- stronglyConnComp graph
          ]
        componentIdentities =
          Map.fromList
            [ (global, identity)
            | (identity, component) <- zip [(0 :: Int) ..] components
            , global <- component
            ]
        roleMetas sourceGeneralizableMetas classify term =
          let retained = classify term
              schemaBearing = schemaBearingLevelMetas term
              instantiationMetas =
                Set.difference projectedInstantiationMetas sourceGeneralizableMetas
           in filter
                (\meta ->
                   meta `Set.member` retained
                     && meta `Set.member` schemaBearing
                     && meta `Set.member` sourceGeneralizableMetas
                     && meta `Set.notMember` instantiationMetas)
                (levelMetasOfTerm term)
        componentMetas types traits universeValues ctorTerms component =
          let componentSet = Set.fromList component
              componentCtorNames =
                Set.fromList
                  [ ctor
                  | (ctor, info) <- Map.toList ctorCandidates
                  , ciData info `Set.member` componentSet
                  ]
              componentOwners = Set.union componentSet componentCtorNames
              sourceGeneralizableMetas =
                sourceGeneralizableMetasFor componentOwners
              instantiationMetas =
                Set.difference projectedInstantiationMetas sourceGeneralizableMetas
              retainSource =
                filter
                  (\meta ->
                     meta `Set.member` sourceGeneralizableMetas
                       && meta `Set.notMember` instantiationMetas)
              componentTypes =
                [Map.findWithDefault (CGlob g) g types | g <- component]
              componentTraits =
                concat [Map.findWithDefault [] g traits | g <- component]
              componentValues =
                mapMaybe (`Map.lookup` universeValues) component
              componentCtors =
                [ term
                | (ctor, term) <- Map.toList ctorTerms
                , ctor `Set.member` componentCtorNames
                ]
              roles =
                mconcat
                  ( map declarationUniverseRoles
                      (componentTypes ++ componentTraits ++ componentValues)
                      ++ map constructorUniverseRoles componentCtors
                  )
              schemaBearing =
                Set.unions
                  ( map schemaBearingLevelMetas
                      (componentTypes ++ componentTraits ++ componentValues)
                      ++ map schemaBearingLevelMetas componentCtors
                  )
              occurrences =
                concatMap levelMetasOfTerm
                  (componentTypes ++ componentTraits ++ componentValues)
           in nub
                [ meta
                | meta <- retainSource occurrences
                , meta `Set.member` durGeneralizable roles
                , meta `Set.member` schemaBearing
                ]
        globalMetasFor types traits universeValues ctorTerms =
          List.foldl'
            (\known component ->
               let metas = componentMetas types traits universeValues ctorTerms component
                in foldr
                     (\g ->
                        let explicit = maybe False (dutExplicit . gdUniverses) (Map.lookup g candidates)
                            finalized = g `Set.member` finalizedInterfaces
                            ownerPrefix =
                              case Map.lookup g originalRawTypes of
                                Nothing -> []
                                Just declarationType ->
                                  nub
                                    [ projected
                                    | raw <-
                                        traitMemberOwnerUniverseMetas
                                          st
                                          g
                                          declarationType
                                    , projected <-
                                        levelMetas
                                          ( normalizeLevel
                                              ( substituteLevelMetas
                                                  assignments
                                                  (LMeta raw)
                                              )
                                          )
                                    ]
                            memberGeneralizable =
                              sourceGeneralizableMetasFor (Set.singleton g)
                            retainedOwnerPrefix =
                              filter
                                (`Set.member` memberGeneralizable)
                                ownerPrefix
                            orderedMetas =
                              nub
                                ( retainedOwnerPrefix
                                    ++ metas
                                )
                         in Map.insert
                              g
                              (if explicit || finalized then [] else orderedMetas))
                     known
                     component)
            Map.empty
            components
        -- Constructor references expose the enclosing family schema as their
        -- source-written prefix. Levels introduced by constructor-local
        -- binders form an inferred suffix: they are fresh at each constructor
        -- use and never become arguments of the nominal family result.
        ctorMetasFor retainedGlobals terms =
          Map.mapWithKey
            (\constructor term ->
               let finalized = constructor `Set.member` finalizedInterfaces
                   family =
                     maybe constructor ciData
                       (Map.lookup constructor ctorCandidates)
                   ownerMetas =
                     Map.findWithDefault [] family retainedGlobals
                   sourceGeneralizableMetas =
                     sourceGeneralizableMetasFor . Set.fromList $
                       constructor
                         : maybe
                             []
                             (pure . ciData)
                             (Map.lookup constructor ctorCandidates)
                in if finalized
                     then []
                     else
                       nub
                         ( ownerMetas
                             ++ roleMetas
                                  sourceGeneralizableMetas
                                  (durGeneralizable . constructorUniverseRoles)
                                  term
                         ))
            terms
        initialGlobalProjections =
          uniqueUniverseReferenceProjections
            [ ( (g, length sourceMetas)
              , Just
                  (UniverseReferenceProjection
                    (length sourceMetas)
                    [0 .. length sourceMetas - 1])
              )
            | (g, sourceSpines) <- Map.toList provisionalGlobalMetas
            , Just gd <- [Map.lookup g candidates]
            , not (dutExplicit (gdUniverses gd))
            , g `Set.notMember` finalizedInterfaces
            , sourceMetas <- sourceSpines
            ]
        initialConstructorProjections =
          uniqueUniverseReferenceProjections
            [ ( (g, length sourceMetas)
              , Just
                  (UniverseReferenceProjection
                    (length sourceMetas)
                    [0 .. length sourceMetas - 1])
              )
            | (g, sourceSpines) <- Map.toList provisionalCtorMetas
            , Map.member g ctorCandidates
            , g `Set.notMember` finalizedInterfaces
            , sourceMetas <- sourceSpines
            ]
        initialProjections =
          UniverseReferenceProjections
            initialGlobalProjections
            initialConstructorProjections
            Map.empty
            Map.empty
        globalProjectionsFor retained =
          uniqueUniverseReferenceProjections
            [ ( (g, length sourceMetas)
              , deriveUniverseReferenceProjection
                  assignments
                  sourceMetas
                  (Map.findWithDefault [] g retained)
              )
            | (g, sourceSpines) <- Map.toList provisionalGlobalMetas
            , Just gd <- [Map.lookup g candidates]
            , not (dutExplicit (gdUniverses gd))
            , g `Set.notMember` finalizedInterfaces
            , sourceMetas <- sourceSpines
            ]
        constructorProjectionsFor retained =
          uniqueUniverseReferenceProjections
            [ ( (g, length sourceMetas)
              , deriveUniverseReferenceProjection
                  assignments
                  sourceMetas
                  (Map.findWithDefault [] g retained)
              )
            | (g, sourceSpines) <- Map.toList provisionalCtorMetas
            , Map.member g ctorCandidates
            , g `Set.notMember` finalizedInterfaces
            , sourceMetas <- sourceSpines
            ]
        exactGlobalProjectionsFor retained =
          uniqueUniverseReferenceProjections
            [ ( (puiOwner occurrence, occurrenceSpine)
              , deriveUniverseReferenceProjection
                  assignments
                  (puiSourceMetas occurrence)
                  (Map.findWithDefault [] (puiOwner occurrence) retained)
              )
            | occurrence <- csProvisionalUniverseInstantiations st
            , puiFacet occurrence == ProvisionalGlobalFacet
            , Just gd <- [Map.lookup (puiOwner occurrence) candidates]
            , not (dutExplicit (gdUniverses gd))
            , puiOwner occurrence `Set.notMember` finalizedInterfaces
            , occurrenceSpine <-
                nub
                  [ puiFreshLevels occurrence
                  , map zonkRawLevel (puiFreshLevels occurrence)
                  ]
            ]
        exactConstructorProjectionsFor retained =
          uniqueUniverseReferenceProjections
            [ ( (puiOwner occurrence, occurrenceSpine)
              , deriveUniverseReferenceProjection
                  assignments
                  (puiSourceMetas occurrence)
                  (Map.findWithDefault [] (puiOwner occurrence) retained)
              )
            | occurrence <- csProvisionalUniverseInstantiations st
            , puiFacet occurrence == ProvisionalConstructorFacet
            , Map.member (puiOwner occurrence) ctorCandidates
            , puiOwner occurrence `Set.notMember` finalizedInterfaces
            , occurrenceSpine <-
                nub
                  [ puiFreshLevels occurrence
                  , map zonkRawLevel (puiFreshLevels occurrence)
                  ]
            ]
        settleProjections fuel projections =
          let normalize =
                zonkRawLevels
                  . rewriteProvisionalUniverseReferences projections
                  . zonkRawTerm
              types = Map.map normalize originalRawTypes
              traits = Map.map (map normalize) originalRawInterfaceTerms
              universeValues = Map.map normalize originalRawUniverseValues
              ctorTerms = Map.map normalize originalRawCtorTerms
              retainedGlobals = globalMetasFor types traits universeValues ctorTerms
              retainedConstructors = ctorMetasFor retainedGlobals ctorTerms
              next =
                UniverseReferenceProjections
                  (globalProjectionsFor retainedGlobals)
                  (constructorProjectionsFor retainedConstructors)
                  (exactGlobalProjectionsFor retainedGlobals)
                  (exactConstructorProjectionsFor retainedConstructors)
           in if next == projections || fuel <= (0 :: Int)
                then
                  ( projections
                  , types
                  , traits
                  , universeValues
                  , ctorTerms
                  , retainedGlobals
                  , retainedConstructors
                  )
                else settleProjections (fuel - 1) next
        ( referenceProjections
          , _rawTypes
          , _rawTraitTerms
          , _rawUniverseValues
          , _rawCtorTerms
          , globalMetas
          , ctorMetas
          ) =
          settleProjections
            (Map.size candidates + Map.size ctorCandidates + 1)
            initialProjections
        rawValuesForRewrite =
          Map.map
            ( zonkRawLevels
                . rewriteProvisionalUniverseReferences referenceProjections
                . zonkRawTerm
            )
            originalRawValues
        -- A semantic SCC owns exactly the level metas occurring in its own
        -- completed interfaces. Dependency references already carry freshly
        -- instantiated universe spines; copying a dependency's declaration
        -- parameters into the client would change the client's schema and
        -- make telescope size grow transitively through the module.
        constraints =
          [ substituteLevelConstraintMetas assignments c
          | c <- csLevelConstraints st
          ]
        constraintMetas c =
          nub (levelMetas (lcLhs c) ++ levelMetas (lcRhs c))
        allOwnedMetas = Map.elems globalMetas ++ Map.elems ctorMetas
        generalizedMetas = Set.fromList (concat allOwnedMetas)
        generalizedConstraint c =
          let metas = constraintMetas c
           in not (null metas)
                && null (assumptionsList (lcAssumptions c))
                && all (`Set.member` generalizedMetas) metas
                && any (\owned -> all (`elem` owned) metas) allOwnedMetas

        transformFor owner existingParameterCount sourceMetas term =
          let paramSub =
                Map.fromList
                  (zip sourceMetas (map LParam [existingParameterCount ..]))
              substLevel = substituteLevelMetas paramSub
              -- A retained source meta is now a rigid declaration parameter.
              -- Zonk term metas while withholding solved level assignments
              -- for those identities, then abstract them before applying the
              -- remaining assignment map. Doing this in the opposite order
              -- can publish a nonempty schema whose type/body has already
              -- collapsed the corresponding occurrence to zero.
              zonkPreservingOwnerMetas =
                zonkRawTermPreserving (Set.fromList sourceMetas) term
              projected =
                rewriteProvisionalUniverseReferences
                  referenceProjections
                  zonkPreservingOwnerMetas
              parametersDone =
                zonkTermWith (\_ _ -> Nothing) substLevel 0 projected
              levelsDone = zonkRawLevels parametersDone
              ownerSchema =
                map LParam
                  [ 0
                  .. existingParameterCount + length sourceMetas - 1
                  ]
              completedArity target = do
                definition <- Map.lookup target candidates
                pure
                  ( dutParameterCount (gdUniverses definition)
                      + length (Map.findWithDefault [] target globalMetas)
                  )
              sameComponent target =
                case (Map.lookup owner componentIdentities, Map.lookup target componentIdentities) of
                  (Just ownerIdentity, Just targetIdentity) -> ownerIdentity == targetIdentity
                  _ -> False
              rewrite _ = \case
                CGlobal target universes
                  | sameComponent target
                  , Just targetArity <- completedArity target
                  , length universes /= targetArity
                  , length ownerSchema == targetArity ->
                      -- One inferred recursive declaration SCC owns one hidden
                      -- universe telescope (§11.1.2.3A). During body checking
                      -- an implicit self/mutual reference can still carry the
                      -- provisional all-interface-meta spine. That spine is
                      -- not an independent schema instance: replace it with
                      -- the SCC's rigid parameters. Equal-arity occurrences
                      -- stay intact so explicit same-or-lower calls retain
                      -- their selected instance (§11.1.2.3A.1).
                      Just (CGlobal target ownerSchema)
                  | otherwise ->
                      Just (CGlobal target (map substLevel universes))
                _ -> Nothing
           in mapTermWithDepth rewrite 0 levelsDone

        -- A trait's constructor schema is determined by the trait head and
        -- supertrait surface. Universes introduced inside member signatures
        -- belong to the generated member declarations, which generalize them
        -- independently. The checker-only dictionary record stored in the
        -- trait global is not itself a source declaration and cannot retain
        -- those member-local metas; levels erase at runtime, so close only
        -- that internal copy at their principal least level. The public
        -- member projection types are transformed separately with their own
        -- declaration telescopes below.
        closeTraitDictionaryLevels retainedParameterCount term =
          let residualMetas = nub (levelMetasOfTerm term)
              closeMetas =
                substituteLevelMetas
                  (Map.fromList [(meta, LZero) | meta <- residualMetas])
              parameters = levelParamsOfTerm term
              parameterArguments = case parameters of
                [] -> []
                _ ->
                  [ if index < retainedParameterCount then LParam index else LZero
                  | index <- [0 .. maximum parameters]
                  ]
              closeLevel = substituteLevelParams parameterArguments . closeMetas
           in zonkTermWith (\_ _ -> Nothing) closeLevel 0 term

        schemaFor existing metas =
          let existingParameterCount = dutParameterCount existing
              paramSub =
                Map.fromList
                  (zip metas (map LParam [existingParameterCount ..]))
              subst = substituteLevelMetas paramSub
              applies c =
                let used = constraintMetas c
                 in not (null used)
                      && null (assumptionsList (lcAssumptions c))
                      && all (`elem` metas) used
              generatedConstraints =
                dedupeUniverseConstraints
                  [ UniverseConstraint (subst (lcLhs c)) (subst (lcRhs c))
                  | c <- orderLevelConstraintsBySignatureOccurrence st constraints
                  , applies c
                  ]
           in ( DeclarationUniverseTelescope
                  (existingParameterCount + length metas)
                  (dutExplicit existing)
              , generatedConstraints
              )

        -- Constraints discovered only after the complete declaration body is
        -- available are prepended to an interface that may already contain
        -- earlier generated proof binders.  Record exactly that delta: uses
        -- in elaborated bodies already carry the earlier arguments and must
        -- receive only the newly prepended prefix.
        lateGeneratedConstraints =
          Map.mapMaybeWithKey
            (\g candidate -> do
               tyTerm <- Map.lookup g originalRawTypes
               let metas = Map.findWithDefault [] g globalMetas
                   existing = gdUniverses candidate
                   existingParameterCount = dutParameterCount existing
                   (telescope, requested) = schemaFor existing metas
                   transformedType = transformFor g existingParameterCount metas tyTerm
                   generated =
                     generatedConstraintsNotIn
                       (dutParameterCount telescope)
                       requested
                       transformedType
               if null generated then Nothing else Just generated)
            candidates

        rebuild g gd =
          case Map.lookup g originalRawTypes of
            Nothing -> gd
            Just tyTerm ->
              let metas = Map.findWithDefault [] g globalMetas
                  existing = gdUniverses gd
                  existingParameterCount = dutParameterCount existing
                  (telescope, generatedConstraints) = schemaFor existing metas
                  transformedType0 = transformFor g existingParameterCount metas tyTerm
                  -- A signed declaration can acquire body-derived rigid
                  -- constraints before this final SCC rebuild.  Its retained
                  -- source signature predates those generated proof Pis, so
                  -- rebuilding from that signature must explicitly preserve
                  -- the authenticated physical prefix already published on
                  -- the current global interface.
                  retainedConstraints =
                    declarationConstraintSummary
                      existingParameterCount
                      (globalCoreType ec gd)
                  requestedConstraints =
                    dedupeUniverseConstraints
                      (retainedConstraints ++ generatedConstraints)
                  transformedValue0 =
                    (\valueTerm ->
                       let transformed = transformFor g existingParameterCount metas valueTerm
                        in if Map.member g originalRawTraitValues
                             then
                               closeTraitDictionaryLevels
                                 (dutParameterCount telescope)
                                 transformed
                             else transformed)
                      <$> Map.lookup g rawValuesForRewrite
                  (transformedType, transformedValue) = case transformedValue0 of
                    Just value ->
                      let (ty, body) =
                            prependGeneratedConstraintBinders
                              (dutParameterCount telescope)
                              requestedConstraints
                              transformedType0
                              value
                       in (ty, Just body)
                    Nothing ->
                      let (ty, _) =
                            prependGeneratedConstraintBinders
                              (dutParameterCount telescope)
                              requestedConstraints
                              transformedType0
                              (CRecordV [])
                       in (ty, Nothing)
               in if termScopedAt 0 transformedType
                    then globalDefWithUniverses
                      telescope
                      gd
                        { gdProvisionalUniverseProjection =
                            nubBy
                              (\(left, _) (right, _) -> left == right)
                              ( [ (meta, parameter)
                                | (meta, parameter) <-
                                    gdProvisionalUniverseProjection gd
                                , parameter >= 0
                                , parameter < existingParameterCount
                                ]
                                  ++ zip metas [existingParameterCount ..]
                              )
                        , gdType = eval ec [] transformedType
                        , gdCoreType = Just transformedType
                        , gdValue = case transformedValue of
                            Just valueTerm | termScopedAt 0 valueTerm -> Just (eval ec [] valueTerm)
                            Just _ -> gdValue gd
                            Nothing -> gdValue gd
                        }
                    else gd
        -- A deferred declaration keeps its own provisional telescope until
        -- the post-body SCC boundary, but every reference in its already
        -- elaborated signature must immediately adopt the finalized spine of
        -- dependencies closed at this boundary. Leaving those occurrences
        -- untouched makes the type and constructor facets of a nominal family
        -- compare unequal even when they print identically.
        rewriteReferencedGlobal gd =
          let rewrite =
                zonkRawLevels
                  . rewriteProvisionalUniverseReferences referenceProjections
                  . zonkRawTerm
              rewrittenType = rewrite (globalCoreType ec gd)
           in if termScopedAt 0 rewrittenType
                then gd
                  { gdType = eval ec [] rewrittenType
                  , gdCoreType = Just rewrittenType
                  }
                else gd
        globalsRebuilt0 =
          Map.mapWithKey
            (\g gd ->
               case Map.lookup g candidates of
                 Just candidate -> rebuild g candidate
                 Nothing
                   | ownerNeedsUniverseRewrite g -> rewriteReferencedGlobal gd
                   | otherwise -> gd)
            (csGlobals st)
        -- Derive the public call-spine delta from the rebuilt interfaces, not
        -- from one solver bookkeeping route.  A constraint may have entered
        -- through an earlier materialization request and still become physical
        -- only in this SCC rebuild; the authenticated Pi telescope is the
        -- authority for what callers must now supply.
        finalizedConstraintDeltas =
          Map.mapMaybeWithKey
            (\g rebuilt -> do
               original <- Map.lookup g (csGlobals st)
               let before =
                     declarationConstraintSummary
                       (dutParameterCount (gdUniverses original))
                       (globalCoreType ec original)
                   after =
                     declarationConstraintSummary
                       (dutParameterCount (gdUniverses rebuilt))
                       (globalCoreType ec rebuilt)
                   added =
                     [ constraint
                     | constraint <- after
                     , not (any (equivalentUniverseConstraint constraint) before)
                     ]
               if null added then Nothing else Just added)
            globalsRebuilt0
        completionConstraintDeltas =
          Map.unionWith
            (\left right -> dedupeUniverseConstraints (left ++ right))
            lateGeneratedConstraints
            finalizedConstraintDeltas
        -- 'csCoreSignatures' deliberately retains a source interface from
        -- before declaration-universe publication. Rebuilding exactly such a
        -- declaration from that authority must replay every proof prefix
        -- already published by a current-module dependency, not merely the
        -- delta discovered by this final solve. Compiler-generated interfaces
        -- and unsigned declarations are rebuilt from their current Core type,
        -- which already contains every published prefix; replaying one there
        -- would duplicate a valid argument.
        publishedGlobalConstraintPrefixes =
          Map.mapMaybeWithKey
            (\target definition -> do
               guard (gnameInModule target currentModule)
               count <-
                 Map.lookup
                   (GeneratedGlobalInterface target)
                   (csPublishedGeneratedConstraintCounts st)
               let constraints =
                     map snd (generatedConstraintBinders (globalCoreType ec definition))
               guard (count > 0 && count <= length constraints)
               pure (take count constraints))
            (csGlobals st)
        publishedConstructorConstraintPrefixes =
          Map.mapMaybeWithKey
            (\constructor info -> do
               guard (gnameInModule constructor currentModule)
               count <-
                 Map.lookup
                   (GeneratedConstructorInterface constructor)
                   (csPublishedGeneratedConstraintCounts st)
               let constraints = map snd (generatedConstraintBinders (ciType info))
               guard (count > 0 && count <= length constraints)
               pure (take count constraints))
            (csCtors st)
        unpublishedCompletionConstraints published =
          Map.mapMaybeWithKey
            (\target constraints ->
               let publishedConstraints = Map.findWithDefault [] target published
                   remaining =
                     [ constraint
                     | constraint <- constraints
                     , not
                         ( any
                             (equivalentUniverseConstraint constraint)
                             publishedConstraints
                         )
                     ]
                in if null remaining then Nothing else Just remaining)
        newGlobalConstraintDeltas =
          unpublishedCompletionConstraints
            publishedGlobalConstraintPrefixes
            completionConstraintDeltas
        newGlobalConstraintTargets =
          Map.mapMaybeWithKey
            (\target constraints -> do
               definition <- Map.lookup target globalsRebuilt0
               pure
                 ( constraints
                 , corePiIcities (globalCoreType ec definition)
                 ))
            newGlobalConstraintDeltas
        publishedGlobalReplayTargets =
          Map.mapMaybeWithKey
            (\target constraints -> do
               definition <- Map.lookup target globalsRebuilt0
               pure
                 ( constraints
                 , corePiIcities (globalCoreType ec definition)
                 ))
            publishedGlobalConstraintPrefixes
        publishedConstructorReplayTargets =
          Map.mapMaybeWithKey
            (\constructor constraints -> do
               info <- Map.lookup constructor (csCtors st)
               pure (constraints, corePiIcities (ciType info)))
            publishedConstructorConstraintPrefixes
        -- The final SCC solve can discover a generated constraint only after a
        -- caller signature has already retained a reference to the target.
        -- Recursive self-references are target occurrences too: once the
        -- declaration prefix grows, every such occurrence needs the same
        -- authenticated arguments as a cross-declaration call. Bodies are
        -- repaired below; types are equally authoritative and must receive the
        -- same completed call spine before their semantic values are rebuilt.
        -- Only a physically present caller proof binder or a rigidly
        -- established closed witness may discharge the new argument.
        globalsWithRepairedCoreTypes =
          Map.mapWithKey
            (\g gd ->
               if not (ownerNeedsUniverseRewrite g)
                 then gd
                 else
                   let coreType = globalCoreType ec gd
                       completedType =
                         replayPublishedGeneratedConstraintCallSpines
                           GeneratedProofTelescope
                           newGlobalConstraintTargets
                           Map.empty
                           (generatedConstraintBinders coreType)
                           ( if Map.member prelRefl (csCtors st)
                               then Just solverEstablishedLevelWitness
                               else Nothing
                           )
                           coreType
                       repairedType =
                         replayPublishedGeneratedConstraintCallSpines
                           GeneratedProofTelescope
                           publishedGlobalReplayTargets
                           publishedConstructorReplayTargets
                           (generatedConstraintBinders coreType)
                           ( if Map.member prelRefl (csCtors st)
                               then Just solverEstablishedLevelWitness
                               else Nothing
                           )
                           completedType
                    in if termScopedAt 0 repairedType
                         then gd {gdCoreType = Just repairedType}
                         else gd)
            globalsRebuilt0
        repairedTypeContext =
          (ecOf st) {ecGlobals = Globals globalsWithRepairedCoreTypes}
        globalsRebuilt =
          Map.mapWithKey
            (\g gd ->
               if ownerNeedsUniverseRewrite g
                 then
                   let coreType = globalCoreType repairedTypeContext gd
                    in gd {gdType = eval repairedTypeContext [] coreType}
                 else gd)
            globalsWithRepairedCoreTypes
        -- The public generated member projections are the finalized checked
        -- authority for a trait dictionary's field telescope.  The opaque
        -- dictionary value was elaborated before declaration-universe
        -- principalization; retaining that provisional record can leave an
        -- owner carrier at @Type u@ while an operation in one of its fields is
        -- spuriously specialized to @Type 0@.  Recover each field after the
        -- projection declaration has been generalized, then substitute the
        -- projection's dictionary binder back to the canonical @this@
        -- neutral used by record interfaces.
        finalizedTraitMemberFieldType globals trait member = do
          info <- Map.lookup trait (csTraits st)
          definition <- Map.lookup (memberGlobal trait member) globals
          let context = (ecOf st) {ecGlobals = Globals globals}
              projectionType = globalCoreType context definition
          -- A declaration-level universe-evidence prefix is not part of the
          -- dictionary field itself.  Traits with such a prefix need their
          -- evidence promoted to the owning trait telescope before a field
          -- can be recovered; do not guess that transformation here.
          guard (null (generatedConstraintBinders projectionType))
          dictionaryPi <- dropTraitParameters (tiParamCount info) projectionType
          case dictionaryPi of
            CPiEvidenceM _ _ Impl _ _ "__d" _ _ _ codomain ->
              pure
                ( substTopTermAt
                    (tiParamCount info)
                    (CGlobal thisG [])
                    codomain
                )
            _ -> Nothing
          where
            dropTraitParameters 0 term = Just term
            dropTraitParameters count (CPiEvidenceM _ _ _ _ _ _ _ _ _ codomain) =
              dropTraitParameters (count - 1) codomain
            dropTraitParameters _ _ = Nothing
        finalizedTraitMemberFields globals trait info =
          Map.fromList
            <$> traverse
              (\member ->
                 (member,) <$> finalizedTraitMemberFieldType globals trait member)
              (tiMembers info)
        finalizedTraitSuperFields info =
          traverse
            (dropTraitParameters (tiParamCount info) . snd)
            (tiSupers info)
          where
            dropTraitParameters 0 term = Just term
            dropTraitParameters count (CLamM _ _ _ _ body) =
              dropTraitParameters (count - 1) body
            dropTraitParameters _ _ = Nothing
        rebuildTraitDictionaryInterface globals trait info definition = do
          value <- gdValue definition
          memberFields <- finalizedTraitMemberFields globals trait info
          let context = (ecOf st) {ecGlobals = Globals globals}
              rebuild remaining = \case
                CLamM mode icit quantity name body
                  | remaining > 0 ->
                      CLamM mode icit quantity name
                        (rebuild (remaining - 1) body)
                CRecordTQ fields
                  | remaining == 0 ->
                      CRecordTQ
                        [ field
                            { rfType =
                                Map.findWithDefault
                                  (rfType field)
                                  (rfName field)
                                  memberFields
                            }
                        | field <- fields
                        ]
                term -> term
              rebuilt = rebuild (tiParamCount info) (quote context 0 value)
          guard (termScopedAt 0 rebuilt)
          pure definition {gdValue = Just (eval context [] rebuilt)}
        globalsWithTraitInterfaces =
          Map.mapWithKey
            (\global definition ->
               if not (ownerNeedsUniverseRewrite global)
                 then definition
                 else
                   fromMaybe definition $ do
                     info <- Map.lookup global (csTraits st)
                     rebuildTraitDictionaryInterface
                       globalsRebuilt
                       global
                       info
                       definition)
            globalsRebuilt
        traits' =
          Map.mapWithKey
            (\g info ->
               case Map.lookup g globalMetas of
                 Nothing
                   | ownerNeedsUniverseRewrite g ->
                   info
                     { tiSupers =
                         [ ( field
                           , zonkRawLevels
                               ( rewriteProvisionalUniverseReferences
                                   referenceProjections
                                   (zonkRawTerm term)
                               )
                           )
                         | (field, term) <- tiSupers info
                         ]
                     }
                   | otherwise -> info
                 Just metas ->
                   let existingParameterCount =
                         maybe 0 (dutParameterCount . gdUniverses) (Map.lookup g candidates)
                       transform = transformFor g existingParameterCount metas
                    in info
                         { tiSupers =
                             [ (field, transform term)
                             | (field, term) <- tiSupers info
                             ]
                         }
            )
            (csTraits st)
        nominalSummaryRequests' =
          Map.mapWithKey
            (\family request ->
               if not (ownerNeedsUniverseRewrite family)
                 then request
                 else case request of
                 PendingTraitNominalSummary sourceSchema saturationArity clauses site ->
                   let existingParameterCount =
                         maybe
                           0
                           (dutParameterCount . gdUniverses)
                           (Map.lookup family candidates)
                       retainedParameterCount =
                         existingParameterCount
                           + length (Map.findWithDefault [] family globalMetas)
                       transform =
                         case Map.lookup family candidates of
                           Just _ ->
                             transformFor
                               family
                               existingParameterCount
                               (Map.findWithDefault [] family globalMetas)
                           Nothing ->
                             zonkRawLevels
                               . rewriteProvisionalUniverseReferences referenceProjections
                               . zonkRawTerm
                       finalizedClauses = do
                         info <- Map.lookup family traits'
                         supers <- finalizedTraitSuperFields info
                         fields <-
                           finalizedTraitMemberFields
                             globalsWithTraitInterfaces
                             family
                             info
                         members <- traverse (`Map.lookup` fields) (tiMembers info)
                         pure (supers ++ members)
                       transformedClauses =
                         case finalizedClauses of
                           Just typedClauses ->
                             typedClauses
                           Nothing ->
                             map
                               ( closeTraitDictionaryLevels retainedParameterCount
                                   . transform
                               )
                               clauses
                    in PendingTraitNominalSummary
                         sourceSchema
                         saturationArity
                         transformedClauses
                         site
                 PendingDataNominalSummary {} -> request)
            (csNominalSummaryRequests st)
        ctors' =
          Map.mapWithKey
            (\g ci ->
               case Map.lookup g ctorCandidates of
                 Nothing
                   | constructorNeedsUniverseRewrite g ci ->
                   ci
                     { ciType =
                         zonkRawLevels
                           ( rewriteProvisionalUniverseReferences
                               referenceProjections
                               (zonkRawTerm (ciType ci))
                           )
                     }
                   | otherwise -> ci
                 Just candidate ->
                   let family = ciData candidate
                       metas = Map.findWithDefault [] g ctorMetas
                       existing = ciUniverses candidate
                       existingParameterCount = dutParameterCount existing
                       (telescope, generatedConstraints) =
                         schemaFor existing metas
                       familyExisting =
                         maybe
                           existing
                           gdUniverses
                           (Map.lookup family candidates)
                       familyMetas = Map.findWithDefault [] family globalMetas
                       (familyTelescope, _) =
                         schemaFor familyExisting familyMetas
                       transformedType0 =
                         rewriteConstructorTypeResultHead
                           family
                           (map LParam [0 .. dutParameterCount familyTelescope - 1])
                           ( transformFor g existingParameterCount metas
                               (Map.findWithDefault (ciType candidate) g originalRawCtorTerms)
                           )
                       (transformedType, _) =
                         prependGeneratedConstraintBinders
                           (dutParameterCount telescope)
                           generatedConstraints
                           transformedType0
                           (CRecordV [])
                    in candidate
                         { ciUniverses = telescope
                         , ciType = transformedType
                         }
            )
            (csCtors st)
        coreBodies' =
          Map.mapWithKey
            (\g body ->
               if not (ownerNeedsUniverseRewrite g)
                 then body
                 else
                   let body' =
                         zonkRawLevels
                           ( rewriteProvisionalUniverseReferences
                               referenceProjections
                               (zonkRawTerm body)
                           )
                       candidate = Map.lookup g candidates
                       existingParameterCount =
                         maybe 0 (dutParameterCount . gdUniverses) candidate
                       transformed0 =
                         case candidate of
                           Just _ ->
                             transformFor
                               g
                               existingParameterCount
                               (Map.findWithDefault [] g globalMetas)
                               body
                           Nothing -> body'
                       newlyOwnedConstraints =
                         Map.findWithDefault [] g lateGeneratedConstraints
                       pendingForOwner =
                         Map.map pleConstraint
                           ( Map.filter
                               (\entry ->
                                  pleOwner entry == g
                                    && any
                                      (equivalentUniverseConstraint (pleConstraint entry))
                                      newlyOwnedConstraints
                               )
                               (csPendingLevelEvidence st)
                           )
                       -- Pending metas refer to the newly prepended owner delta.
                       -- Target call spines are completed only after every proof
                       -- lambda is present, using the finalized caller telescope.
                       (evidenceRepaired, _) =
                         rewriteGeneratedConstraintEvidence
                           Map.empty
                           newlyOwnedConstraints
                           pendingForOwner
                           transformed0
                       callerType = globalCoreType ec <$> Map.lookup g globalsRebuilt
                       proofNames = maybe [] generatedConstraintBinderNames callerType
                       withProofLambdas =
                         if isJust candidate
                           then ensureGeneratedConstraintLambdas proofNames evidenceRepaired
                           else evidenceRepaired
                       callerConstraints = maybe [] generatedConstraintBinders callerType
                    in replayPublishedGeneratedConstraintCallSpines
                         GeneratedProofLambdas
                         newGlobalConstraintTargets
                         Map.empty
                         callerConstraints
                         ( if Map.member prelRefl (csCtors st)
                             then Just solverEstablishedLevelWitness
                             else Nothing
                         )
                         withProofLambdas
            )
            (csCoreBodies st)
        stateWithRebuiltGlobals =
          st {csGlobals = globalsWithTraitInterfaces}
        globals' =
          Map.mapWithKey
            (\global definition ->
               if ownerNeedsUniverseRewrite global
                 then
                   maybe definition (\body -> globalDefWithCanonicalCoreBody stateWithRebuiltGlobals body definition)
                     (Map.lookup global coreBodies')
                 else definition)
            globalsWithTraitInterfaces
        transformGlobalUniverseSpine transform global universes =
          case transform (CGlobal global universes) of
            CGlobal actual transformed
              | actual == global -> transformed
            _ -> universes
        instances' =
          map
            (\entry ->
               case Map.lookup (ieDict entry) globalMetas of
                 Nothing
                   | ownerNeedsUniverseRewrite (ieDict entry) ->
                   let rewrite =
                         zonkRawLevels
                           . rewriteProvisionalUniverseReferences referenceProjections
                           . zonkRawTerm
                    in entry
                         { ieTraitUniverses =
                             transformGlobalUniverseSpine
                               rewrite
                               (ieTrait entry)
                               (ieTraitUniverses entry)
                         , iePremises = map rewrite (iePremises entry)
                         , ieHead = map rewrite (ieHead entry)
                         }
                   | otherwise -> entry
                 Just metas ->
                   let existing = ieUniverses entry
                       existingParameterCount = dutParameterCount existing
                       (telescope, _) = schemaFor existing metas
                       transform =
                         transformFor (ieDict entry) existingParameterCount metas
                    in entry
                         { ieTraitUniverses =
                             transformGlobalUniverseSpine
                               transform
                               (ieTrait entry)
                               (ieTraitUniverses entry)
                         , ieUniverses = telescope
                         , iePremises = map transform (iePremises entry)
                         , ieHead = map transform (ieHead entry)
                         }
            )
            (csInstances st)
        preInstances' =
          Map.map
            (fmap (\entry ->
               case Map.lookup (piDictG entry) globalMetas of
                 Nothing
                   | ownerNeedsUniverseRewrite (piDictG entry) ->
                   let rewrite =
                         zonkRawLevels
                             . rewriteProvisionalUniverseReferences referenceProjections
                             . zonkRawTerm
                    in entry
                         { piFvTele =
                             [ teleEntry {teDomain = rewrite (teDomain teleEntry)}
                             | teleEntry <- piFvTele entry
                             ]
                         , piPremTms = map rewrite (piPremTms entry)
                         , piArgTms = map rewrite (piArgTms entry)
                         }
                   | otherwise -> entry
                 Just metas ->
                   let existingParameterCount =
                         maybe 0 (dutParameterCount . gdUniverses) (Map.lookup (piDictG entry) candidates)
                       transform =
                         transformFor (piDictG entry) existingParameterCount metas
                    in entry
                         { piFvTele =
                             [ teleEntry {teDomain = transform (teDomain teleEntry)}
                             | teleEntry <- piFvTele entry
                             ]
                         , piPremTms = map transform (piPremTms entry)
                         , piArgTms = map transform (piArgTms entry)
                         }
            ))
            (csPreInstances st)
        transformEffectLabel effectInfo =
          let owner = eliIface effectInfo
           in if not (ownerNeedsUniverseRewrite owner)
                then effectInfo
                else case Map.lookup owner candidates of
                Nothing ->
                  let transform =
                        zonkRawLevels
                          . rewriteProvisionalUniverseReferences referenceProjections
                          . zonkRawTerm
                      transformEntry entry =
                        entry
                          { teDomain = transform (teDomain entry) }
                      transformOperation operation =
                        operation
                          { eoiImplicits = map transformEntry (eoiImplicits operation)
                          , eoiArgs = map transformEntry (eoiArgs operation)
                          , eoiResT = transform (eoiResT operation)
                          }
                   in effectInfo
                        { eliParams = map transformEntry (eliParams effectInfo)
                        , eliOps = map transformOperation (eliOps effectInfo)
                        }
                Just definition ->
                  let existingParameterCount =
                        dutParameterCount (gdUniverses definition)
                      metas = Map.findWithDefault [] owner globalMetas
                      transform =
                        transformFor owner existingParameterCount metas
                      transformLevel level =
                        case transform (CSort level) of
                          CSort transformed -> transformed
                          _ -> level
                      transformAssumption =
                        fmap (\(lower, upper) -> (transformLevel lower, transformLevel upper))
                      transformEntry entry =
                        entry
                          { teDomain = transform (teDomain entry)
                          , teLevelAssumption =
                              transformAssumption (teLevelAssumption entry)
                          }
                      transformOperation operation =
                        operation
                          { eoiImplicits = map transformEntry (eoiImplicits operation)
                          , eoiArgs = map transformEntry (eoiArgs operation)
                          , eoiResT = transform (eoiResT operation)
                          }
                   in effectInfo
                        { eliParams = map transformEntry (eliParams effectInfo)
                        , eliFixedUniverses = fmap (map transformLevel) (eliFixedUniverses effectInfo)
                        , eliOps = map transformOperation (eliOps effectInfo)
                        }
        effectLabels' = Map.map transformEffectLabel (csModEffLabels st)
        effectInterfaces' = Map.map transformEffectLabel (csEffectInterfaces st)
        finalizedGlobalMetaMaps =
          Map.mapWithKey
            (\global metas ->
               let offset =
                     maybe 0 (dutParameterCount . gdUniverses)
                       (Map.lookup global candidates)
                in Map.fromList
                     (zip metas (map LParam [offset ..])))
            globalMetas
        finalizedConstructorMetaMaps =
          Map.mapWithKey
            (\constructor metas ->
               let offset =
                     maybe 0 (dutParameterCount . ciUniverses)
                       (Map.lookup constructor ctorCandidates)
                in Map.fromList
                     (zip metas (map LParam [offset ..])))
            ctorMetas
        finalizedMetaMaps =
          Map.union finalizedGlobalMetaMaps finalizedConstructorMetaMaps
        pendingCoreSignatures =
          Map.withoutKeys
            ( Map.mapWithKey
                (\global signature ->
                   if not (ownerNeedsUniverseRewrite global)
                     then signature
                     else
                       let preserved =
                             Set.fromList
                               ( concat
                                   ( Map.findWithDefault
                                       []
                                       global
                                       (csProvisionalGlobalUniverseMetas st)
                                   )
                               )
                           remainingAssignments =
                             Map.withoutKeys assignments preserved
                        in zonkTermWith
                             (\_ _ -> Nothing)
                             (substituteLevelMetas remainingAssignments)
                             0
                             ( rewriteProvisionalUniverseReferences
                                 referenceProjections
                                 (zonkRawTermPreserving preserved signature)
                             )
                )
                (csCoreSignatures st)
            )
            (Map.keysSet candidates)
        recursiveSchemaOccurrences' =
          map
            (\occurrence ->
               let owner = rsoCaller occurrence
                in if not (ownerNeedsUniverseRewrite owner)
                     then occurrence
                     else
                       let transform =
                             case Map.lookup owner candidates of
                               Just definition ->
                                 transformFor
                                   owner
                                   (dutParameterCount (gdUniverses definition))
                                   (Map.findWithDefault [] owner globalMetas)
                               Nothing -> zonkRawLevels
                           transformedLevels =
                             case transform (CGlobal (rsoCallee occurrence) (rsoLevels occurrence)) of
                               CGlobal _ levels -> levels
                               _ -> map zonkRawLevel (rsoLevels occurrence)
                           transformLevel level =
                             case transform (CSort level) of
                               CSort transformed -> transformed
                               _ -> zonkRawLevel level
                           transformedAssumptions =
                             foldr
                               (\(lower, upper) ->
                                  insertAssumption
                                    (transformLevel lower)
                                    (transformLevel upper))
                               emptyAssumptions
                               (assumptionsList (rsoAssumptions occurrence))
                        in occurrence
                             { rsoLevels = transformedLevels
                             , rsoAssumptions = transformedAssumptions
                             })
            (csRecursiveSchemaOccurrences st)
        transformRetainedConstraint constraint =
          case Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st)
                 >>= (`Map.lookup` finalizedMetaMaps) of
            Nothing -> constraint
            Just metaMap ->
              let transformLevel = substituteLevelMetas metaMap
                  transformAssumptions =
                    foldr
                      (\(lower, upper) ->
                         insertAssumption
                           (transformLevel lower)
                           (transformLevel upper))
                      emptyAssumptions
                      . assumptionsList
               in constraint
                    { lcLhs = transformLevel (lcLhs constraint)
                    , lcRhs = transformLevel (lcRhs constraint)
                    , lcAssumptions =
                        transformAssumptions (lcAssumptions constraint)
                    }
    let finalizedSymbols = Set.union (Map.keysSet candidates) (Map.keysSet ctorCandidates)
        retiredOccurrenceIds =
          Set.fromList
            [ puiIdentity occurrence
            | occurrence <- csProvisionalUniverseInstantiations st
            , puiOwner occurrence `Set.member` finalizedSymbols
            , let retainedMetas =
                    case puiFacet occurrence of
                      ProvisionalGlobalFacet ->
                        Map.findWithDefault [] (puiOwner occurrence) globalMetas
                      ProvisionalConstructorFacet ->
                        Map.findWithDefault [] (puiOwner occurrence) ctorMetas
            , Just projection <-
                [ deriveUniverseReferenceProjection
                    assignments
                    (puiSourceMetas occurrence)
                    retainedMetas
                ]
            , null (urpRetainedPositions projection)
            ]
        retainedConstraints =
          map transformRetainedConstraint
            ( filter
                (\constraint ->
                   not (generalizedConstraint constraint)
                     && constraintOwnedAfterRetiringOccurrences
                          st
                          retiredOccurrenceIds
                          constraint)
                constraints
            )
    put . reindexLevelConstraints $
      invalidateSemanticCaches $
      setCheckInstances instances' $
        st
          { csGlobals = globals'
          , csTraits = traits'
          , csNominalSummaryRequests = nominalSummaryRequests'
          , csCtors = ctors'
          , csPreInstances = preInstances'
          , csModEffLabels = effectLabels'
          , csEffectInterfaces = effectInterfaces'
          , csCoreBodies = coreBodies'
          , csCoreSignatures = pendingCoreSignatures
          , csFinalizedGlobalUniverseMetaMaps =
              Map.union
                finalizedGlobalMetaMaps
                (csFinalizedGlobalUniverseMetaMaps st)
          , csRecursiveSchemaOccurrences = recursiveSchemaOccurrences'
          , csProvisionalUniverseInstantiations =
              filter
                (\occurrence -> puiOwner occurrence `Set.notMember` finalizedSymbols)
                (csProvisionalUniverseInstantiations st)
          , csLevelConstraints = retainedConstraints
          , csLevelConstraintOwners =
              Map.restrictKeys
                (csLevelConstraintOwners st)
                (Set.fromList (map lcIdentity retainedConstraints))
          , csLevelConstraintSpans =
              Map.restrictKeys
                (csLevelConstraintSpans st)
                (Set.fromList (map lcIdentity retainedConstraints))
          , csFinalizedUniverseInterfaces =
              Set.unions
                [ csFinalizedUniverseInterfaces st
                , Map.keysSet candidates
                , Map.keysSet ctorCandidates
                ]
          }
    finalizePendingNominalSummaries
-- | Check a resolved module: two passes (headers then bodies), per the
-- preceding-signature recursion rule (§15.16, §9.2).
checkModule :: CheckState -> Module -> (CheckState, Diagnostics)
checkModule st0 m =
  -- Sets, not lists: every let consults sigNames and every signature
  -- consults siglessLets, so list membership made large modules
  -- quadratic (measured ~4x time per size doubling at 16k+ decls)
  let sigNames = Set.fromList [nameText n | DSig _ n _ _ <- modDecls m]
      siglessLets =
        Set.fromList
          [ nameText n
          | DLet _ (LetDef (Just n) _ _ _ _ _ _ _ _) _ <- modDecls m
          , not (nameText n `Set.member` sigNames)
          ]
      termNames = Set.fromList [GName (csModule st0) nm | nm <- signedLetNames sigNames (modDecls m)]
      preexisting = Map.keysSet (csGlobals st0)
      preexistingCtors = Map.keysSet (csCtors st0)
      (sourceGlobals, sourceCtors) = sourceDeclarationSymbols (csModule st0) (modDecls m)
      expectDecls = [declaration | declaration@DExpect {} <- modDecls m]
      ordinaryDecls = [declaration | declaration <- modDecls m, not (isExpectDecl declaration)]
      expectNames =
        Set.fromList
          [ nameText name
          | DExpect _ form _ <- expectDecls
          , name <- case form of
              ExpectTerm n _ -> [n]
              ExpectType n _ _ -> [n]
              ExpectData n _ _ -> [n]
              ExpectTrait n _ _ -> [n]
          ]
      declarationInfos =
        [ (declaration, provided, declarationDependencies declaration)
        | declaration <- ordinaryDecls
        , let (providedGlobals, providedConstructors) =
                sourceDeclarationSymbols (csModule st0) [declaration]
              provided =
                Set.map gnameText
                  (Set.union providedGlobals providedConstructors)
        ]
      expectDependentNames =
        closeDeclarationDependencies declarationInfos $
          Set.unions
            [ Set.union
                (Set.intersection provided expectNames)
                ( if Set.null (Set.intersection expectNames dependencies)
                    then Set.empty
                    else provided
                )
            | (_, provided, dependencies) <- declarationInfos
            , not (Set.null (Set.intersection expectNames dependencies))
                || not (Set.null (Set.intersection provided expectNames))
            ]
      expectationProvider declaration =
        maybe False ((`Set.member` expectNames) . nameText)
          (declarationUniverseName declaration)
      preExpectOrdinary declaration =
        not (expectationProvider declaration)
          && let (providedGlobals, providedConstructors) =
                   sourceDeclarationSymbols (csModule st0) [declaration]
                 provided =
                   Set.map gnameText
                     (Set.union providedGlobals providedConstructors)
              in Set.null (Set.intersection provided expectDependentNames)
      preExpectOrdinaryDecls = filter preExpectOrdinary ordinaryDecls
      remainingOrdinaryDecls =
        [ declaration
        | declaration <- ordinaryDecls
        , not (preExpectOrdinary declaration)
        ]
      passes = do
        validateModuleConstructorBindings (modDecls m)
        mapM_ predeclarePass (modDecls m)
        -- An expectation may mention ordinary same-module declarations from
        -- another selected fragment. Elaborate every header whose identity is
        -- independent of the expectation first, preserving the established
        -- source order between data constructors, traits, signatures, and
        -- transparent aliases. Matching implementations and aliases that
        -- transitively depend on an expectation-provided identity remain in
        -- the post-expect phase, so they cannot overwrite their own contract.
        mapM_ (headerPassIn siglessLets) preExpectOrdinaryDecls
        -- §9.4 module fragments have no semantic declaration order. Register
        -- their contracts before elaborating any selected implementation
        -- header, even when a fragment suffix sorts before the common source
        -- file. The preceding shape pass still makes mutually referenced data
        -- family names available while these signatures are elaborated.
        mapM_
          (\declaration ->
             withDeclarationUniverseSchema declaration $
               case declaration of
                 DExpect _ form site -> headerExpect preexisting form site
                 _ -> pure ())
          expectDecls
        mapM_ (headerPassIn siglessLets) remainingOrdinaryDecls
        -- §10.4: once every data type's constructor types are
        -- elaborated, check strict positivity over the whole module's
        -- data group by fixed-point iteration and record each accepted
        -- type's parameter-positivity signature
        positivityPass (modDecls m)
        -- §14.3: register every top-level instance head before any
        -- body is checked, so instance visibility within the module
        -- does not depend on declaration order
        mapM_ instanceHeadPass (modDecls m)
        planDerivedDeclarations (modDecls m)
        -- Header/signature evidence now sees the complete instance set. Keep
        -- declaration universe interfaces provisional while bodies are
        -- elaborated: body edges are part of the semantic declaration SCC,
        -- and §11.1.2.4A permits exactly one principal solve after the
        -- complete SCC has been checked.
        beforeHeaderEvidencePublication <- get
        do
          flushPendingBeforeUniverseFinalization
          synchronizeGeneratedConstraintInterfaces beforeHeaderEvidencePublication
        headerState <- get
        let deferredInstanceDictionaries =
              Set.fromList
                [ piDictG preInstance
                | Just preInstance <- Map.elems (csPreInstances headerState)
                , let GName owner _ = piDictG preInstance
                , owner == csModule headerState
                ]
            -- An instance dictionary's semantic declaration includes every
            -- member body. Generalizing its normalized head after the
            -- instance-head pass alone would freeze occurrence ceilings before
            -- those bodies contribute their constraints, exactly like
            -- finalizing a signed let before checking its definition.
            deferredInterfaces =
              declarationUniverseDeferralClosure
                headerState
                (Set.union termNames deferredInstanceDictionaries)
        do
          generalizeDeclarationUniverses
            preexisting preexistingCtors sourceGlobals sourceCtors deferredInterfaces
          synchronizeGeneratedConstraintInterfaces headerState
        -- Static declarations such as type aliases have no body-pass event.
        -- If initial SCC generalization made one of their pending universe
        -- obligations physical, publish that call-spine delta now so every
        -- signature retained during the header pass is repaired before its
        -- definition is checked. Deferred semantic interfaces remain open and
        -- are published by the completed-component sweep below.
        initialUniverseState <- get
        let finalizedPendingOwners =
              Set.difference
                (Map.keysSet (csPendingUniverseProofs initialUniverseState))
                deferredInterfaces
        mapM_ materializePendingUniverseProofs
          (Set.toAscList finalizedPendingOwners)
        -- Runtime dictionary layout is representation metadata, not a source
        -- ordering effect. Header checking can already prove fields erased
        -- from local/supertrait evidence, while the remaining fields may need
        -- module-global instance heads and the principalized header-universe
        -- interfaces above. Finalize exactly here: both authorities are now
        -- complete, but no instance dictionary body or backend IR has yet been
        -- built from the member quantities.
        finalizeTraitMemberRepresentations
        finalizeDerivedRefinementDeclarations (modDecls m)
        let elaborateBodies _ [] = pure ()
            elaborateBodies remaining (declaration : rest) = do
              bodyPassIn siglessLets declaration
              current <- get
              let completedBodies =
                    Set.intersection remaining
                      (declarationBodyUniverseOwners current declaration)
                  remaining' = Set.difference remaining completedBodies
                  componentClosed owner =
                    case Map.lookup owner (csCoreBodies current) of
                      Nothing -> False
                      Just body ->
                        Set.null
                          ( Set.intersection remaining'
                              (expandedGlobalsOfTerm current body)
                          )
                  completedComponents =
                    Set.filter componentClosed completedBodies
                  completedOwners = Set.difference termNames remaining'
                  closedOwners = Set.filter componentClosed completedOwners
                  needsUniverseClose owner =
                    owner `Set.notMember` csFinalizedUniverseInterfaces current
                      && maybe
                           False
                           (not . globalDefinitionBodyUniversesReplayable)
                           (Map.lookup owner (csGlobals current))
                  newlyClosedUniverseOwners =
                    Set.filter needsUniverseClose closedOwners
              -- Body checking can add further interface-closed obligations.
              -- Publish those proof binders only for a completed dependency
              -- component, so following declarations elaborate the complete
              -- call spine.  A body that still references an open declaration
              -- remains part of that declaration SCC and is left untouched.
              -- Do not run the global universe solver here: declarations still
              -- in 'remaining'' must see one order-independent solve.
              mapM_ materializeOwnedInterfaceUniverseProofs
                (Set.toAscList completedComponents)
              unless (Set.null newlyClosedUniverseOwners) $ do
                closeCompletedProvisionalBodyUniverses
                  preexisting
                  sourceGlobals
                  (Set.difference deferredInterfaces closedOwners)
                  newlyClosedUniverseOwners
                afterClose <- get
                let unresolvedOwners =
                      Set.filter
                        (\owner ->
                           maybe
                             False
                             (not . globalDefinitionBodyUniversesReplayable)
                             (Map.lookup owner (csGlobals afterClose)))
                        newlyClosedUniverseOwners
                unless (Set.null unresolvedOwners) $ do
                  beforeIncrementalGeneralization <- get
                  generalizeDeclarationUniverses
                    preexisting
                    preexistingCtors
                    sourceGlobals
                    sourceCtors
                    (Set.difference deferredInterfaces closedOwners)
                  synchronizeGeneratedConstraintInterfaces
                    beforeIncrementalGeneralization
              elaborateBodies remaining' rest
        elaborateBodies (Set.union termNames deferredInstanceDictionaries) (modDecls m)
        -- Finalize body-owned occurrence choices before committing deferred
        -- evidence. Generated level propositions may mention those occurrence
        -- metas, so final evidence search must observe the principal SCC
        -- solution rather than diagnosing the provisional variables. The
        -- resulting proof terms are still available before termination.
        beforeFinalUniverseGeneralization <- get
        do
          generalizeDeclarationUniverses
            preexisting preexistingCtors sourceGlobals sourceCtors Set.empty
          synchronizeGeneratedConstraintInterfaces beforeFinalUniverseGeneralization
        -- The final generalization pass can turn occurrence-meta relations
        -- into rigid owner-parameter obligations. They did not exist during
        -- the per-body sweep above, so give every remaining current-module
        -- owner the same interface-closed proof-binder materialization before
        -- the final solver judges residual constraints.
        finalUniverseState <- get
        let finalConstraintOwners =
              Set.fromList
                [ owner
                | constraint <- csLevelConstraints finalUniverseState
                , Just owner@(GName ownerModule _) <-
                    [Map.lookup (lcIdentity constraint) (csLevelConstraintOwners finalUniverseState)]
                , ownerModule == csModule finalUniverseState
                ]
        mapM_ materializeOwnedInterfaceUniverseProofs
          (Set.toAscList finalConstraintOwners)
        levelDiagCount <- gets (length . csDiags)
        levelOk <- solveDeferredLevelConstraints True
        levelDiagCount' <- gets (length . csDiags)
        levelFailureExplained <- gets $ \state ->
          any (levelConstraintFailureAlreadyReported state)
            (csLevelConstraints state)
        unless (levelOk || levelDiagCount' > levelDiagCount || levelFailureExplained) $ do
          residualState <- get
          let pending = csLevelConstraints residualState
              assignments = csLevelAssignments residualState
          let renderConstraint constraint =
                renderLevel (substituteLevelMetas assignments (lcLhs constraint))
                  <> " <= "
                  <> renderLevel (substituteLevelMetas assignments (lcRhs constraint))
              summary = T.intercalate ", " (map renderConstraint (take 6 pending))
              renderOwner constraint =
                case Map.lookup (lcIdentity constraint) (csLevelConstraintOwners residualState) of
                  Nothing -> "<unowned>#" <> T.pack (show (lcIdentity constraint))
                  Just owner ->
                    let arity =
                          (dutParameterCount . gdUniverses <$> Map.lookup owner (csGlobals residualState))
                            <|> (dutParameterCount . ciUniverses <$> Map.lookup owner (csCtors residualState))
                        relation =
                          UniverseConstraint
                            (normalizeLevel (substituteLevelMetas assignments (lcLhs constraint)))
                            (normalizeLevel (substituteLevelMetas assignments (lcRhs constraint)))
                        binderPresent =
                          case (arity, Map.lookup owner (csGlobals residualState)) of
                            (Just parameterCount, Just definition) ->
                              any (equivalentUniverseConstraint relation)
                                (declarationConstraintSummary parameterCount (globalCoreType (ecOf residualState) definition))
                            _ -> False
                     in gKey owner
                          <> "#"
                          <> T.pack (show (lcIdentity constraint))
                          <> "[arity="
                          <> maybe "missing" (T.pack . show) arity
                          <> ",binder="
                          <> (if binderPresent then "yes" else "no")
                          <> ",assumptions="
                          <> renderLevelAssumptions (lcAssumptions constraint)
                          <> "]"
              ownerSummary = T.intercalate ", " (map renderOwner (take 6 pending))
          unless (null pending) $
            report $
              withPayload
                ( withPayloadField "residualConstraintOwners" ownerSummary
                    $ withPayloadField "residualConstraints" summary
                    $ payloadKind "universe-constraint-residual"
                ) $
                diag SevError StageElaborate "E_UNSOLVED_METAVARIABLE"
                  (Just "kappa.type.unsolved-metavariable")
                  (Span "<universe-inference>" (Pos 1 1) (Pos 1 1))
                  ( "universe constraints have no principal order-independent solution: "
                      <> summary
                      <> " (§11.1.3)"
                  )
        flushPendingFinal
        when levelOk $ do
          evidenceClosed <- closeFinalEvidenceUniverses
          when evidenceClosed $ do
            finalizeDiscardedResults
            repairFinalizedGeneratedConstraintEvidence
        -- Termination consumes both the finalized level assignments and the
        -- erased relation evidence they determine. Running SCT earlier would
        -- observe provisional occurrence metas or unresolved proof terms.
        terminationSccPass
        finalizeDeferredSignatureHoles
        sigSatisfactionPass
        -- §8.5.2: now that this module's bodies (and any in-module proofs
        -- that rely on an opaque definition unfolding) are checked, seal
        -- the module's 'opaque' definitions against δ-unfolding downstream.
        opaqueSealPass
      (_, st1) =
        runState
          passes
          ( st0
              { csSigPending = Map.empty
              , csPreInstances = Map.empty
              , csDerivedDecls = Map.empty
              , csTerminationNames = termNames
              , csTerminationDecls = Map.empty
              , csAssertTerminates = Set.empty
              , csAssertReducible = Set.empty
              }
          )
      st2 = compactCompletedModuleUniverseState st1
   in -- 'report' prepends; restore emission (source) order here
      (st2 {csDiags = []}, reverse (csDiags st1))
  where
    isExpectDecl DExpect {} = True
    isExpectDecl _ = False

    declarationDependencies :: Data a => a -> Set Text
    declarationDependencies value =
      case cast value of
        Just expression ->
          Set.fromList (map (nameText) (freeVarOccurrences expression))
        Nothing -> Set.unions (gmapQ declarationDependencies value)

    closeDeclarationDependencies infos = go
      where
        go dependent =
          let newlyDependent =
                Set.unions
                  [ provided
                  | (_, provided, dependencies) <- infos
                  , not (Set.null (Set.intersection dependent dependencies))
                  ]
              dependent' = Set.union dependent newlyDependent
           in if dependent' == dependent then dependent else go dependent'

-- | §7.1 binding groups admit at most one ordinary constructor declaration
-- with a given spelling in one lexical scope. The per-data check in
-- 'finishDataHeaderIn' catches repetition inside a declaration; this check
-- covers collisions between distinct data declarations before either header
-- can overwrite the other's semantic entry.
validateModuleConstructorBindings :: [Decl] -> CheckM ()
validateModuleConstructorBindings declarations =
  forM_ (Map.toList constructorsBySpelling) $ \(constructor, declarations') ->
    case declarations' of
      (_ : (_, duplicateSite) : _)
        | Set.size (Set.fromList (map fst declarations')) > 1 ->
            errAt duplicateSite
              "E_DUPLICATE_DECLARATION"
              (Just "kappa-hs.name.duplicate")
              ("duplicate constructor declaration '" <> constructor <> "' in the same lexical scope (§7.1)")
      _ -> pure ()
  where
    constructorsBySpelling =
      foldl'
        (\table (constructor, owner, site) ->
           Map.insertWith (flip (++)) constructor [(owner, site)] table)
        Map.empty
        [ (nameText constructor, nameText owner, site)
        | DData _ (DataDecl owner _ _ constructors) site <- declarations
        , CtorDecl constructor _ _ _ _ <- constructors
        ]

-- | Drop declaration-local universe inference history only after the complete
-- module boundary has consumed it. 'finalizeLevelArtifacts' has already
-- materialized the solved substitution in every exported Core/interface
-- artifact, but evidence selection, discarded-result checking, and
-- termination still need that substitution before 'checkModule' returns.
--
-- A failed or incomplete universe closeout retains its full diagnostic state:
-- clearing assignments in the presence of a residual constraint, pending
-- generated proof, or provisional occurrence would turn a later failure into
-- an accidental fresh inference problem. Stable declaration telescopes,
-- finalized owner projections, nominal summaries, selected evidence, and
-- inference records are semantic interface state and deliberately survive.
compactCompletedModuleUniverseState :: CheckState -> CheckState
compactCompletedModuleUniverseState st
  | not (null (csLevelConstraints st)) = st
  | not (Map.null (csLevelConstraintIndex st)) = st
  | not (Map.null (csPendingLevelEvidence st)) = st
  | not (Map.null (csPendingUniverseProofs st)) = st
  | not (null (csProvisionalUniverseInstantiations st)) = st
  | isJust (csActiveUniverseDefinition st) = st
  | otherwise =
      invalidateSemanticCaches
        st
          { csFirstClassLevelMetas = Set.empty
          , csLevelAssignments = Map.empty
          , csLevelAssignmentDependents = Map.empty
          , csLevelAssignmentBudget = emptyLevelAssignmentGraphBudget
          , csLevelGeneralizableMetas = Set.empty
          , csLevelGeneralizableOwners = Map.empty
          , csLevelInstantiationMetas = Set.empty
          , csLevelInstantiationOwners = Map.empty
          , csProvisionalGlobalUniverseMetas = Map.empty
          , csProvisionalConstructorUniverseMetas = Map.empty
          , csRecursiveSchemaOccurrences = []
          , csBareTypeLevels = Map.empty
          }

-- | Names of signature-governed term definitions in this module.  The SCC
-- termination pass is concerned with definitions, not standalone signatures,
-- so an unsatisfied signature is still reported by 'sigSatisfactionPass'.
signedLetNames :: Set Text -> [Decl] -> [Text]
signedLetNames sigNames = concatMap go
  where
    go = \case
      DLet _ (LetDef (Just n) _ Nothing _ _ _ _ _ _) _
        | nameText n `Set.member` sigNames -> [nameText n]
      DPattern _ (LetDef (Just n) _ Nothing _ _ _ _ _ _) _
        | nameText n `Set.member` sigNames -> [nameText n]
      DUnsafeAssert _ inner _ -> go inner
      _ -> []

-- | Resolved identities completed by one body-pass declaration.  The caller
-- intersects this with the signed-definition set: only those declarations
-- already have a complete provisional interface that can soundly be closed
-- before the module body boundary.  Inferred lets and instance dictionaries
-- retain their existing shared completion boundary.
declarationBodyUniverseOwners :: CheckState -> Decl -> Set GName
declarationBodyUniverseOwners state = \case
  DLet _ definition _ -> maybe Set.empty (Set.singleton . own) (ldName definition)
  DPattern _ definition _ -> maybe Set.empty (Set.singleton . own) (ldName definition)
  DProjection _ name _ _ _ _ -> Set.singleton (own name)
  DInstance _ span' ->
    maybe Set.empty (maybe Set.empty (Set.singleton . piDictG))
      (Map.lookup span' (csPreInstances state))
  DUnsafeAssert _ inner _ -> declarationBodyUniverseOwners state inner
  _ -> Set.empty
  where
    own name = GName (csModule state) (nameText name)

-- | Publish residual universe obligations that are already closed over one
-- signed declaration's interface.  The relation is retained as an erased
-- proof Pi while its levels are still metas; this is deliberately not
-- universe generalization.  A candidate is admissible only when every level
-- meta occurs in the public Core type and the relation is a consistent
-- unconditional assumption.  Body-local occurrence metas, lexical
-- assumptions, and rigid contradictions therefore remain fail-closed in the
-- ordinary solver/diagnostic path.
materializeOwnedInterfaceUniverseProofs :: GName -> CheckM ()
materializeOwnedInterfaceUniverseProofs owner = do
  st <- get
  case Map.lookup owner (csGlobals st) of
    Nothing -> pure ()
    Just definition -> do
      let (previewValid, assignments) =
            previewOwnedInterfaceUniverseAssignments owner definition st
          resolve = normalizeLevel . substituteLevelMetas assignments
          coreType = zonkTermWith (\_ _ -> Nothing) resolve 0
            (globalCoreType (ecOf st) definition)
          interfaceMetas = Set.fromList (levelMetasOfTerm coreType)
          parameterCount = dutParameterCount (gdUniverses definition)
          authenticatedConstraints =
            declarationConstraintSummary parameterCount coreType
              ++ Map.findWithDefault [] owner (csPendingUniverseProofs st)
          resolvedAuthenticatedConstraints =
            [ UniverseConstraint (resolve lower) (resolve upper)
            | UniverseConstraint lower upper <- authenticatedConstraints
            ]
          ownerAssumptionAuthorized lower upper =
            let resolved =
                  UniverseConstraint (resolve lower) (resolve upper)
             in proveLevelLeq
                  emptyAssumptions
                  (ucLower resolved)
                  (ucUpper resolved)
                  == Proved
                  || any
                    (equivalentUniverseConstraint resolved)
                    resolvedAuthenticatedConstraints
          closedLevel level =
            all (`Set.member` interfaceMetas) (levelMetas level)
              && null (levelVars level)
              && null (levelFields level)
              && all (\parameter -> parameter >= 0 && parameter < parameterCount)
                   (levelParams level)
          admissible constraint =
            Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st)
              == Just owner
              -- A constraint may be discovered after an earlier declaration
              -- proof was materialized. Those owner-local proof assumptions
              -- are authenticated context, not a reason to hide the new
              -- obligation. Lexical/branch assumptions still fail closed.
              && all (uncurry ownerAssumptionAuthorized)
                   (assumptionsList (lcAssumptions constraint))
              && closedLevel (lcLhs constraint)
              && closedLevel (lcRhs constraint)
              && let lower = resolve (lcLhs constraint)
                     upper = resolve (lcRhs constraint)
                  in case proveLevelLeq emptyAssumptions lower upper of
                       Proved -> False
                       -- A blocked meta relation is exactly what the final
                       -- declaration-SCC solve may retain as a proof binder.
                       -- It is not a rigid contradiction; self cycles are
                       -- classified 'Disproved' by the normalizer below.
                       Blocked _ -> True
                       Disproved ->
                         assumptionsConsistent
                           (insertAssumption lower upper emptyAssumptions)
                       ContradictoryAssumptions -> False
                       IndeterminateResourceLimit -> False
          candidates =
            dedupeUniverseConstraints
              [ UniverseConstraint
                  (resolve (lcLhs constraint))
                  (resolve (lcRhs constraint))
              | constraint <- orderLevelConstraintsBySignatureOccurrence st (csLevelConstraints st)
              , previewValid
              , admissible constraint
              ]
      unless (null candidates) $ do
        -- Use the same authority as body-time inferred requirements. Besides
        -- materializing the erased proof binders, it authenticates the
        -- corresponding owner constraints with those lexical assumptions.
        -- Directly editing 'csPendingUniverseProofs' produced a binder-shaped
        -- artifact while leaving the final solver to reject the undischarged
        -- duplicate judgment.
        void (recordUniverseRequirementsForOwner owner emptyAssumptions candidates)

-- | Preview the principal declaration-SCC classification for one completed
-- signed interface without mutating checker state.  This is the arity
-- authority for 'materializeOwnedInterfaceUniverseProofs': minimizable
-- occurrence/result metas and equivalent or uniquely determined source metas
-- are first eliminated exactly as the final solver will eliminate them.  Only
-- a relation that remains after that preview is eligible to become an early
-- proof Pi.  Any solver failure returns an invalid preview and leaves the
-- ordinary final diagnostic path authoritative.
previewOwnedInterfaceUniverseAssignments
  :: GName
  -> GlobalDef
  -> CheckState
  -> (Bool, Map LevelMeta Level)
previewOwnedInterfaceUniverseAssignments owner definition st =
  let initialAssignments = csLevelAssignments st
      initialResolve = substituteLevelMetas initialAssignments
      rawType = globalCoreType (ecOf st) definition
      interfaceType = zonkTermWith (\_ _ -> Nothing) initialResolve 0 rawType
      interfaceMetas = Set.fromList (levelMetasOfTerm interfaceType)
      ownedConstraints =
        [ constraint
            { lcLhs = initialResolve (lcLhs constraint)
            , lcRhs = initialResolve (lcRhs constraint)
            }
        | constraint <- csLevelConstraints st
        , Map.lookup (lcIdentity constraint) (csLevelConstraintOwners st)
            == Just owner
        ]
      relevantMetas = constraintMetaClosure interfaceMetas ownedConstraints
      ownedGeneralizableOrigins =
        Set.fromList
          [ meta
          | (meta, owners) <- Map.toList (csLevelGeneralizableOwners st)
          , owner `Set.member` owners
          ]
      generalizable =
        projectGeneralizableLevelMetas
          initialAssignments
          ownedGeneralizableOrigins
      projectedOrigins origins =
        Set.fromList
          [ projected
          | origin <- Set.toList origins
          , projected <-
              levelMetas
                (normalizeLevel (initialResolve (LMeta origin)))
          ]
      instantiationMetas =
        Set.intersection relevantMetas . Set.difference
          (projectedOrigins (csLevelInstantiationMetas st)) $
          generalizable
      roles = declarationUniverseRoles interfaceType
      minimizable =
        Set.unions
          [ durMinimizable roles
          , instantiationMetas
          , Set.difference relevantMetas generalizable
          ]
      targets =
        Set.difference
          (Set.difference minimizable generalizable)
          (csLevelGeneralizableMetas st)
      solveMinimizable
        | Set.null targets = Just (Map.empty, ownedConstraints)
        | otherwise = case solveLevelConstraintsFor targets ownedConstraints of
            Left _ -> Nothing
            Right solution ->
              let solved = lsAssignments solution
                  unresolved = Set.filter (`Map.notMember` solved) targets
                  candidate = Map.union solved (Map.fromSet (const LZero) unresolved)
                  residual =
                    map (substituteLevelConstraintMetas candidate) (lsResidual solution)
                  residualTargets =
                    Set.intersection targets . Set.fromList $
                      concat
                        [ levelMetas (lcLhs constraint)
                            ++ levelMetas (lcRhs constraint)
                        | constraint <- residual
                        ]
               in if Set.null residualTargets
                    then Just (candidate, residual)
                    else Nothing
   in case solveMinimizable of
        Nothing -> (False, initialAssignments)
        Just (minimizableAssignments, residual0) ->
          let afterMinimizable = Map.union minimizableAssignments initialAssignments
              zonkMinimizable = substituteLevelConstraintMetas afterMinimizable
              residual1 = map zonkMinimizable residual0
              generalized1 =
                projectGeneralizableLevelMetas
                  afterMinimizable
                  ownedGeneralizableOrigins
              equivalent =
                equivalentLevelMetaAssignments
                  (projectGeneralizableLevelMetas afterMinimizable (csLevelGeneralizableMetas st))
                  generalized1
                  minimizable
                  residual1
              afterEquivalent = Map.unions [equivalent, afterMinimizable]
              zonkEquivalent = substituteLevelConstraintMetas afterEquivalent
              residual2 = map zonkEquivalent residual1
              generalized2 =
                projectGeneralizableLevelMetas
                  afterEquivalent
                  ownedGeneralizableOrigins
              determined =
                uniquelyDeterminedLevelMetaAssignments
                  (projectGeneralizableLevelMetas afterEquivalent (csLevelGeneralizableMetas st))
                  generalized2
                  residual2
           in (True, Map.unions [determined, equivalent, afterMinimizable])

-- | Source-owned declaration identities. Compiler seeding may install a
-- placeholder global or constructor before its prelude source declaration is
-- checked, so map membership cannot distinguish a current declaration from an
-- untouched import. The surface declaration tree is the authoritative
-- ownership boundary; declarations introduced by top-level splices remain
-- covered by the ordinary "not preexisting" case above.
sourceDeclarationSymbols :: ModuleName -> [Decl] -> (Set GName, Set GName)
sourceDeclarationSymbols owner decls =
  ( Set.fromList [GName owner name | name <- concatMap globalNames decls]
  , Set.fromList [GName owner name | name <- concatMap ctorNames decls]
  )
  where
    namedLet def = maybe [] (pure . nameText) (ldName def)
    globalNames = \case
      DSig _ name _ _ -> [nameText name]
      DLet _ def _ -> namedLet def
      DData _ dd _ -> [nameText (ddName dd)]
      DTypeAlias _ name _ _ _ _ -> [nameText name]
      DTrait _ td _ ->
        let traitName = nameText (trName td)
            members = concatMap traitMemberName (trMembers td)
         in traitName
              : members
              ++ [traitName <> "." <> member | member <- members]
      DEffect _ eff _ -> nameText (effName eff) : map (nameText . eoName) (effOps eff)
      DExpect _ form _ -> [expectName form]
      DPattern _ def _ -> namedLet def
      DProjection _ name _ _ _ _ -> [nameText name]
      DUnsafeAssert _ inner _ -> globalNames inner
      _ -> []
    ctorNames = \case
      DData _ dd _ -> map (nameText . cdName) (ddCtors dd)
      DUnsafeAssert _ inner _ -> ctorNames inner
      _ -> []
    traitMemberName = \case
      TraitSig name _ _ -> [nameText name]
      TraitDefault def _ -> namedLet def
      TraitDerived name _ _ -> [nameText name]
      TraitEvidenceUniqueness {} -> []
    expectName = \case
      ExpectTerm name _ -> nameText name
      ExpectType name _ _ -> nameText name
      ExpectData name _ _ -> nameText name
      ExpectTrait name _ _ -> nameText name

-- §8.5.2: seal this module's 'opaque' term/type-alias definitions. Their
-- defining equations were available for definitional equality while this
-- module was checked (transparent within the defining module); now clear
-- 'gdReducible' so no downstream module can δ-unfold them during
-- conversion. Runtime evaluation is unaffected — 'ecRuntime' unfolds every
-- valued global regardless of 'gdReducible'.
opaqueSealPass :: CheckM ()
opaqueSealPass = modify' $ \st ->
  let mn = csModule st
      ours = [g | g@(GName m _) <- Map.keys (csOpaqueDefs st), m == mn]
   in st {csGlobals = foldr (Map.adjust (\gd -> gd {gdReducible = False})) (csGlobals st) ours}

-- §9.1: a non-expect top-level term signature must be satisfied by
-- exactly one matching definition in the same source file.
sigSatisfactionPass :: CheckM ()
sigSatisfactionPass = do
  st <- get
  unless (csModule st == preludeModule) $
    forM_ (Map.toList (csSigPending st)) $ \(g, sp) ->
      errAt sp "E_SIGNATURE_UNSATISFIED" (Just "kappa-hs.signature.unsatisfied")
        ("top-level signature '" <> gnameText g
           <> "' has no definition in this source file (Spec §9.1); use 'expect term' for external requirements (§9.4)")

-- Pre-register only the shape of data type-constructor names so declarations
-- in one file may refer to data types declared later (§10.1: declaration
-- order within a module is immaterial for type references).  This pass must
-- not elaborate source annotations: those may mention term interfaces (for
-- example a TypeLevel operator declared by an earlier @expect term@), and the
-- real header pass is the authority that checks them.
predeclarePass :: Decl -> CheckM ()
predeclarePass declaration =
  withDeclarationUniverseSchema declaration (predeclarePassRaw declaration)

predeclarePassRaw :: Decl -> CheckM ()
predeclarePassRaw = \case
  DLet mods (LetDef (Just n) _ Nothing _ _ [] _ Nothing rhs) _
    | not (dmOpaque mods) -> do
        g <- ownName n
        modify' $ \st ->
          st {csTransparentValueAliases = Map.insert g rhs (csTransparentValueAliases st)}
  DData _ declaration@(DataDecl n params _ _) sp -> do
    g <- ownName n
    exists <- gets (Map.member g . csGlobals)
    unless exists $ do
      paramTele <- forM params $ \binder -> do
        domain <- freshMeta
        let mode = fromMaybe Parametric (bpObservation (bPrefix binder))
            quantity = maybe (if mode == Parametric then Q0 else headerBinderQ binder)
              (qOf . Just) (bpQuantity (bPrefix binder))
        pure TelescopeEntry
          { teIcit = if bImplicit binder then Impl else Expl
          , teMode = mode
          , teFormation = if mode == Parametric then FormationParametric else FormationOrdinary
          , teQ = quantity
          , teBorrow = isJust (bpBorrow (bPrefix binder))
          , teName = maybe "_" nameText (bName binder)
          , teDomain = domain
          , teLevelAssumption = Nothing
          }
      resultLevel <- freshLevelMeta
      let tyTm = foldr telePi (CSort resultLevel) paramTele
      tyV <- evalIn emptyCtx tyTm
      addGlobal g
        ( globalDefWithObservationMode
            Ordinary
            (GlobalDef tyV Nothing False)
        )
    modify' $ \st ->
      st
        { csTopLevelDataHeaders =
            Map.insertWith
              (\_ existing -> existing)
              g
              (PendingTopLevelDataHeader declaration sp)
              (csTopLevelDataHeaders st)
        }
  _ -> pure ()

-- | Header pass, knowing which module-level lets have no signature: a
-- signature whose type mentions such a name (a reified static object,
-- §2.8.3) is deferred to the body pass, where the binding's value is
-- available in declaration order.
headerPassIn :: Set Text -> Decl -> CheckM ()
headerPassIn siglessLets declaration =
  case signatureDeclarationName declaration of
    Just signatureName ->
      withNamedHoleScope Map.empty (deferSignatureHoles signatureName) action
    Nothing ->
      withNamedHoleScope Map.empty finalizeNamedHoles action
  where
    action =
      withDeclarationUniverseSchema declaration
        (headerPassInRaw siglessLets declaration)

signatureDeclarationName :: Decl -> Maybe Name
signatureDeclarationName = \case
  DSig _ name _ _ -> Just name
  DUnsafeAssert _ inner _ -> signatureDeclarationName inner
  _ -> Nothing

-- | Run one header/body phase with an isolated named-hole map. The close
-- action runs before restoring the caller's map, so it can either diagnose a
-- completed declaration or retain a signature's obligations for its matching
-- body.
withNamedHoleScope
  :: Map Text NamedHole
  -> CheckM ()
  -> CheckM a
  -> CheckM a
withNamedHoleScope initial close action = do
  saved <- gets csHoles
  modify' $ \st -> st {csHoles = initial}
  result <- action
  close
  modify' $ \st -> st {csHoles = saved}
  pure result

deferSignatureHoles :: Name -> CheckM ()
deferSignatureHoles name = do
  owner <- ownName name
  holes <- gets csHoles
  modify' $ \st ->
    st
      { csSignatureHoles =
          Map.insert owner holes (csSignatureHoles st)
      }

headerPassInRaw :: Set Text -> Decl -> CheckM ()
headerPassInRaw siglessLets = \case
  DSig _ _ tyE _
    | any (`Set.member` siglessLets) (sigHeadNames tyE) ->
        -- deferred to 'bodyPassIn' (the let's value is needed first)
        pure ()
  DSig _ n tyE sp -> do
    -- §11.3.3 (approximation): free ASCII-lowercase heads in the
    -- signature that resolve to no global are implicitly universalized
    -- as erased implicit binders; the kind is inferred from use (a
    -- fresh meta, defaulted to Type when unconstrained).
    fvs <-
      filterM
        (\name -> do
          global <- lookupGlobalName name
          schemaLevel <- gets (Map.lookup name . csActiveUniverseSchema)
          pure (isNothing global && isNothing schemaLevel)
        )
        (nub (freeLower tyE))
    kvs <- mapM (const (freshMetaV emptyCtx)) fvs
    let ctx0 = foldl (\c (v, k) -> bindCtxMQProvisional Parametric Q0 v False k c) emptyCtx (zip fvs kvs)
    diagCount0 <- gets (length . csDiags)
    (tyTm0, _) <- withNamedCallableInoutSignature tyE (inferType ctx0 tyE)
    universalBinders <- forM (zip fvs kvs) $ \(v, kv) -> do
      kv' <- forceM kv
      kind <- case kv' of
        VFlex m [] -> do
          level <- freshLevelMeta
          solveMeta m (VSort level)
          pure (VSort level)
        _ -> pure kv'
      kindTm <- quoteIn emptyCtx kind
      markGeneralizableLevelTerm kindTm
      paramKind <- isParametricKind 0 kind
      pure (v, if paramKind then Parametric else Ordinary, if paramKind then FormationParametric else FormationOrdinary, if paramKind then Q0 else QW, kindTm)
    let tyTm = foldr (\(v, mode, formation, q, kT) acc -> CPiFormedM mode formation Impl q False v kT acc) tyTm0 universalBinders
    tyV <- evalIn emptyCtx tyTm
    g <- ownName n
    exists <- gets (Map.member g . csGlobals)
    isExpected <- gets (Map.member g . csExpects)
    when (exists && not isExpected) $ do
      enrich <- duplicateRelated (nameText n) g sp
      report $ enrich $
        diag SevError StageElaborate "E_DUPLICATE_DECLARATION" (Just "kappa-hs.name.duplicate") sp
          ("duplicate declaration of '" <> nameText n <> "'")
    recordDeclSite g sp
    addGlobal g (GlobalDef tyV Nothing False)
    -- The semantic value intentionally makes cumulative lifts transparent.
    -- Retain the checked signature until its complete declaration SCC is
    -- generalized; installing it in 'gdCoreType' here would change the
    -- semantic interface used to check the body.
    modify' $ \state ->
      state
        { csCoreSignatures =
            Map.insert g tyTm (csCoreSignatures state)
        }
    precertifyLevelOperatorAlias g
    recordSignatureInoutParams g tyE
    -- §9.1: the signature awaits its same-file definition (an expected
    -- name is governed by §9.4 satisfaction instead)
    diagCount1 <- gets (length . csDiags)
    unless (isExpected || diagCount1 > diagCount0) $
      modify' $ \st -> st {csSigPending = Map.insert g sp (csSigPending st)}
  DData mods dd sp -> do
    -- §22.1: an 'opaque data' representation is inspectable only in
    -- its defining module
    when (dmOpaque mods) $ do
      g <- ownName (ddName dd)
      modify' $ \st -> st {csOpaqueDatas = Map.insert g () (csOpaqueDatas st)}
    headerData dd sp
  DTypeAlias _ n params _ (Just rhs) sp
    | nameText n `elem` allNamesIn rhs -> do
        -- §15.16 admits recursive type-alias groups only "when
        -- admitted"; this implementation does not admit them (aliases
        -- are transparent definitions, §11.3) — recursion needs a data
        -- declaration. The alias is salvaged as a fresh metavariable
        -- so downstream uses do not cascade.
        errAt sp "E_RECURSIVE_TYPE_ALIAS" (Just "kappa-hs.type.recursive-alias")
          ("type alias '" <> nameText n
             <> "' refers to itself; recursive type aliases are not admitted (§15.16) — use a data declaration")
        g <- ownName n
        noteDefinition g sp
        modify' $ \st ->
          st {csUniverseInterfaceValues = Set.insert g (csUniverseInterfaceValues st)}
        tyV <- aliasKind params
        mv <- freshMetaV emptyCtx
        addGlobal g (GlobalDef tyV (Just mv) True)
  DTypeAlias mods n params mkind (Just rhs) sp -> do
    -- alias: a definition at a universe type
    (tm, ty) <- elabAliasBody params mkind rhs
    g <- ownName n
    noteDefinition g sp
    modify' $ \st ->
      st {csUniverseInterfaceValues = Set.insert g (csUniverseInterfaceValues st)}
    -- §8.5.2: an 'opaque' type alias is transparent only within its
    -- defining module; sealed at module end ('opaqueSealPass').
    when (dmOpaque mods) $
      modify' $ \st -> st {csOpaqueDefs = Map.insert g () (csOpaqueDefs st)}
    -- §22.2: remember the written field order of a record alias for
    -- derivation-shape reflection (core records are canonicalized)
    case rhs of
      ERecordType rfs Nothing _ ->
        modify' $ \st ->
          st {csRecordOrders = Map.insert g [nameText (rtfName f) | f <- rfs] (csRecordOrders st)}
      _ -> pure ()
    -- Evaluation is transparent through CUniverseLift, so re-quoting the
    -- alias value later cannot recover cumulative-lift evidence. Retain the
    -- elaborated alias body exactly as for term definitions; KCoreText and
    -- interface artifacts serialize this proof-carrying form.
    recordCoreBody g tm
    tmV <- evalIn emptyCtx tm
    observation <- aliasRhsObservation emptyCtx (gnameText g) tm ty
    addGlobal g (globalDefWithObservationMode (ojMode observation) (GlobalDef ty (Just tmV) True))
  DTypeAlias _ n params _ Nothing _ -> do
    g <- ownName n
    tyV <- aliasKind params
    addGlobal g (GlobalDef tyV Nothing False)
  DTrait _ td sp -> headerTrait td sp
  -- §18.1: a top-level (non-scoped) effect declaration registers a
  -- module-wide effect interface; a `scoped effect` is handled lexically by
  -- hoistScopedEffects in the block where it appears (so it is skipped here).
  DEffect mods eff sp
    | dmScoped mods -> pure ()
    | effIsLabelDecl eff -> elabTopEffectLabel eff sp
    | otherwise -> elabTopEffect eff sp
  -- Expectations are one dedicated module-header phase in 'checkModule'.
  -- Re-entering them here after an implementation header would make hidden
  -- universe generalization depend on fragment filename order.
  DExpect {} -> pure ()
  DInstance inst sp -> do
    bootstrap <- compilerOwnedTypeLevelInstance inst
    when bootstrap (instanceHeadPass (DInstance inst sp))
  -- §4.4: register the wrapped definition's header like any other; the
  -- assertion prefix only affects termination checking and gating, which
  -- happen in the body pass.
  DUnsafeAssert _ inner _ -> headerPassInRaw siglessLets inner
  _ -> pure ()

ownName :: Name -> CheckM GName
ownName n = do
  st <- get
  pure (GName (csModule st) (nameText n))

-- | Every identifier spelled anywhere inside a piece of surface syntax
-- (generic over-approximation; binder shadowing is ignored). Used for
-- the recursive-type-alias check.
allNamesIn :: Expr -> [Text]
allNamesIn = go
  where
    go :: Data a => a -> [Text]
    go x = case cast x :: Maybe Name of
      Just n -> [nameText n]
      Nothing -> concat (gmapQ go x)

aliasKind :: [Binder] -> CheckM Value
aliasKind params = do
  tele <- elabTele emptyCtx params
  evalIn emptyCtx (foldr telePi (CSort LZero) tele)

elabAliasBody :: [Binder] -> Maybe Expr -> Expr -> CheckM (Term, Value)
elabAliasBody params mkind rhs = do
  (tm0, kindTm0) <- go emptyCtx params
  tm <- zonkTermM 0 tm0
  kindTm <- zonkTermM 0 kindTm0
  tyV <- evalIn emptyCtx kindTm
  pure (tm, tyV)
  where
    go ctx [] = do
      -- an eta-reduced alias body may itself be a (partially applied)
      -- type former of higher kind ('type Equal (@0 a) = (=) a', §3.5.1)
      case mkind of
        Just kindE -> do
          (kindTm, _) <- inferType ctx kindE
          kindV <- evalIn ctx kindTm
          tm <- check ctx rhs kindV
          pure (tm, kindTm)
        -- A type alias declaration is a static, capability-preserving
        -- definition site. Parametric inputs may shape its RHS; ordinary
        -- observation is checked when the alias value reaches an ordinary
        -- sink, not while constructing the alias itself.
        Nothing -> do
          (tm, kindTm) <- inferAliasRhsKind ctx
          pure (tm, kindTm)
    go ctx (b : rest) = do
      (domTm, ownKindMeta, coerced, mSource) <- case bType b of
        Just t -> do
          domE <- normalizeBinderDomain ctx b t
          (term, _, wasCoerced) <-
            withGeneralizableBareTypeLevels $
              if bImplicit b
                then inferTypeBoolProp' ctx domE
                else (\(term', level) -> (term', level, False)) <$> inferType ctx domE
          pure (term, Nothing, wasCoerced, Just domE)
        Nothing -> do
          meta <- freshMetaId
          pure (CMeta meta, Just meta, False, Nothing)
      domV <- evalIn ctx domTm
      let nm = maybe "_" nameText (bName b)
          ic = if bImplicit b then Impl else Expl
          prefix = bPrefix b
          ordinaryDefault = if coerced then Q0 else headerBinderQ b
          provisionalMode = fromMaybe Parametric (bpObservation prefix)
          provisionalQ =
            maybe
              (if provisionalMode == Parametric then Q0 else ordinaryDefault)
              (qOf . Just)
              (bpQuantity prefix)
      (initialMode, initialQ) <- case ownKindMeta of
        Nothing -> resolveBinderModeQ ctx b domV ordinaryDefault
        Just _ -> pure (provisionalMode, provisionalQ)
      mBound <- case mSource of
        Just source -> levelAssumptionFromExpr ctx (Just domTm) source
        Nothing -> pure Nothing
      ctxWithBound <- extendLevelAssumption (bSpan b) ctx mBound
      let ctx' = bindCtxMQ initialMode initialQ nm False domV ctxWithBound
      (tm, innerK) <- go ctx' rest
      -- §11.3.3: only the kind metavariable introduced for this genuinely
      -- unannotated declaration parameter may take the floating-Type default.
      -- Commit that default after the RHS has had a chance to infer a more
      -- specific domain, then resolve observation mode from the final domain.
      forM_ ownKindMeta $ \meta -> do
        solution <- gets (Map.lookup meta . csMetas)
        case solution of
          Just Nothing -> do
            level <- freshLevelMeta
            solveMeta meta (VSort level)
            markGeneralizableLevelTerm (CSort level)
          _ -> pure ()
      (mode, q) <- case ownKindMeta of
        Nothing -> pure (initialMode, initialQ)
        Just _ -> do
          finalDomain <- forceM domV
          resolveBinderModeQ ctx b finalDomain ordinaryDefault
      finalDomain <- forceM domV
      formation <- selectFormationMode ctx mode finalDomain
      pure
        ( CLamM mode ic q nm tm
        , CPiBoundFormedM mode formation ic q False nm mBound domTm innerK
        )
    inferAliasRhsKind ctx = do
      (tm0, ty0) <- inferT ctx rhs
      tyF <- forceM ty0
      former <- finalIsSort ctx tyF
      case tyF of
        VSort lvl -> pure (tm0, CSort lvl)
        VFlex m [] -> do
          level <- freshLevelMeta
          solveMeta m (VSort level)
          pure (tm0, CSort level)
        VPi {} | former -> do
          kTm <- quoteIn ctx tyF
          pure (tm0, kTm)
        other -> do
          oT <- quoteIn ctx other
          errAt (exprSpan rhs) "E_NOT_A_TYPE" (Just "kappa.type.mismatch")
            ("expected a type; this expression has type " <> renderTerm oT)
          pure (tm0, CSort LZero)

headerData :: DataDecl -> Span -> CheckM ()
headerData declaration sp = do
  g <- ownName (ddName declaration)
  ensureTopLevelDataFamilyHeader g
  prepared <- gets (Map.lookup g . csTopLevelDataHeaders)
  case prepared of
    Just (PreparedTopLevelDataHeader paramTele sortT dataLevel) -> do
      finishDataHeaderIn emptyCtx [] declaration sp paramTele sortT dataLevel
      modify' $ \st ->
        st
          { csTopLevelDataHeaders =
              Map.delete g (csTopLevelDataHeaders st)
          }
    _ ->
      -- A declaration may reach this path without the module shape pass only
      -- in checker-internal/local construction. Preserve the same semantic
      -- split rather than reconstructing a source-shaped approximation.
      headerDataIn emptyCtx [] declaration sp

-- | Publish the real classifier of a predeclared top-level data family before
-- any forward reference is elaborated through it. The map is keyed by the
-- resolved family identity; deleting the pending entry before elaboration
-- also makes recursive classifier references terminate at the conservative
-- shape placeholder.
ensureTopLevelDataFamilyHeader :: GName -> CheckM ()
ensureTopLevelDataFamilyHeader global = do
  pending <- gets (Map.lookup global . csTopLevelDataHeaders)
  case pending of
    Just (PendingTopLevelDataHeader declaration sp) -> do
      modify' $ \st ->
        st
          { csTopLevelDataHeaders =
              Map.delete global (csTopLevelDataHeaders st)
          }
      let sourceDeclaration = DData noMods declaration sp
      prepared <-
        withDeclarationUniverseSchema sourceDeclaration $
          withoutGeneralizableBareTypeLevels $
            prepareDataFamilyHeaderIn emptyCtx [] declaration sp
      let (paramTele, sortT, dataLevel) = prepared
      modify' $ \st ->
        st
          { csTopLevelDataHeaders =
              Map.insert
                global
                (PreparedTopLevelDataHeader paramTele sortT dataLevel)
                (csTopLevelDataHeaders st)
          }
    _ -> pure ()

-- | Shared data-header elaborator. Top-level declarations have an empty base
-- context. A closure-converted local family supplies a closed capture
-- telescope and the matching rigid context; the resulting global data and
-- constructor interfaces prefix those captures as implicit Pis.
headerDataIn :: Ctx -> Telescope -> DataDecl -> Span -> CheckM ()
headerDataIn baseCtx captureTele declaration sp = do
  (paramTele, sortT, dataLevel) <-
    prepareDataFamilyHeaderIn baseCtx captureTele declaration sp
  finishDataHeaderIn
    baseCtx
    captureTele
    declaration
    sp
    paramTele
    sortT
    dataLevel

-- | Elaborate and publish only a data family's real parameter/result
-- classifier. Constructor interfaces are deliberately absent at this point:
-- sibling families may force this phase through a forward reference, and the
-- completed family classifiers are the environment required to elaborate
-- those constructors order-independently (§15.16).
prepareDataFamilyHeaderIn
  :: Ctx
  -> Telescope
  -> DataDecl
  -> Span
  -> CheckM (Telescope, Term, Level)
prepareDataFamilyHeaderIn baseCtx captureTele (DataDecl n params mkind _) sp = do
  g <- ownName n
  provisionalParamTele <- elabTele baseCtx params
  paramCtx <- extendTeleCtx baseCtx provisionalParamTele
  (sortT, dataLevel) <- dataResultSort paramCtx mkind sp
  let provisionalTyTm = foldr telePi sortT (captureTele ++ provisionalParamTele)
  tyV <- evalIn emptyCtx provisionalTyTm
  addGlobal g
    ( globalDefWithObservationMode
        Ordinary
        (GlobalDef tyV Nothing False)
    )
  pure (provisionalParamTele, sortT, dataLevel)

-- | Replace the nominal head of a constructor result while preserving its
-- checked family arguments and any explicit classifier lift. Constructor
-- declarations share the enclosing data schema, so this is the one place
-- where the result occurrence must use the constructor's complete schema
-- identity rather than a separately minimized occurrence spine.
rewriteConstructorResultHead :: GName -> [Level] -> Term -> Term
rewriteConstructorResultHead owner universes = go
  where
    go (CUniverseLift lower upper evidence term) =
      CUniverseLift lower upper evidence (go term)
    go term =
      let (headTerm, arguments) = spineOfTerm term
       in case headTerm of
            CGlobal target _ | target == owner ->
              foldl'
                (\function (icit, argument) -> CApp icit function argument)
                (CGlobI owner universes)
                arguments
            _ -> term

-- | Apply 'rewriteConstructorResultHead' to the terminal result of a complete
-- constructor telescope. Domains are left untouched: nested family uses in
-- fields are ordinary independently selected schema instances.
rewriteConstructorTypeResultHead :: GName -> [Level] -> Term -> Term
rewriteConstructorTypeResultHead owner universes = \case
  CPiEvidenceM mode formation icit quantity borrowed name assumption origin domain codomain ->
    CPiEvidenceM
      mode
      formation
      icit
      quantity
      borrowed
      name
      assumption
      origin
      domain
      (rewriteConstructorTypeResultHead owner universes codomain)
  result -> rewriteConstructorResultHead owner universes result

finishDataHeaderIn
  :: Ctx
  -> Telescope
  -> DataDecl
  -> Span
  -> Telescope
  -> Term
  -> Level
  -> CheckM ()
finishDataHeaderIn
  baseCtx
  captureTele
  (DataDecl n params _ ctors)
  sp
  provisionalParamTele
  sortT
  dataLevel = do
  g <- ownName n
  noteDefinition g sp
  forM_ (duplicatesOf [nameText cn | CtorDecl cn _ _ _ _ <- ctors]) $ \dn ->
    errAt sp "E_DUPLICATE_DECLARATION" (Just "kappa-hs.name.duplicate")
      ("duplicate constructor '" <> dn <> "' in data declaration")
  paramCtx <- extendTeleCtx baseCtx provisionalParamTele
  familyUniverseCount <-
    gets (maybe 0 (dutParameterCount . gdUniverses) . Map.lookup g . csGlobals)
  preparedCtors <- forM ctors $ \(CtorDecl cn constructorUniverses binders mgadt _) -> do
    forM_ binders (rejectInoutBinderContext "data constructor")
    forM_ mgadt (rejectAllInoutBinders "data constructor type")
    validateConstructorUniverseInstantiation paramCtx n cn constructorUniverses
    cg <- ownName cn
    prepared <-
      withUniverseConstraintOwner g $
        case mgadt of
          Just sig -> do
            -- GADT signature: free signature variables are constructor-local
            -- implicit universals (§10.4.1/§11.3.3), not unresolved globals.
            Right <$> elabGadtUnderParams g (nameText n) (nameText cn) dataLevel provisionalParamTele paramCtx sig
          Nothing -> do
            -- First infer every field against the shared provisional parameter
            -- context. A later constructor may still constrain an earlier
            -- parameter's kind, so no constructor result is frozen yet.
            fieldsTele <- elabConstructorTele (nameText n) (nameText cn) dataLevel paramCtx binders
            -- §10.1.1: a field default is checked at declaration against
            -- the field's type, with only the EARLIER fields in scope
            checkFieldDefaults paramCtx fieldsTele binders
            pure (Left fieldsTele)
    pure (cg, ctorFieldsOf binders mgadt, ctorSourceFieldsOf binders mgadt, prepared)

  -- Constructor fields and GADT result applications have now contributed all
  -- constraints on the data parameters. Finalize the shared telescope once,
  -- rebuild the data interface, and use its one provisional universe spine in
  -- every constructor result. Doing this per constructor makes the result
  -- depend on declaration order and leaves early constructors with stale
  -- empty/short global instances.
  paramTele <- finalizeSourceDeclarationTelescope baseCtx (zip params provisionalParamTele)
  pendingFamilyConstraints <-
    gets (Map.findWithDefault [] g . csPendingUniverseProofs)
  let baseTyTm = foldr telePi sortT (captureTele ++ paramTele)
      familyConstraints =
        generatedConstraintsNotIn
          familyUniverseCount
          pendingFamilyConstraints
          baseTyTm
      (tyTm, _) =
        prependGeneratedConstraintBinders
          familyUniverseCount
          familyConstraints
          baseTyTm
          (CRecordV [])
  modify' $ \st ->
    st {csPendingUniverseProofs = Map.delete g (csPendingUniverseProofs st)}
  tyV' <- evalIn emptyCtx tyTm
  addGlobal g
    ( globalDefWithObservationMode
        Ordinary
        (GlobalDef tyV' Nothing False)
    )
  declarationUniverses <- provisionalDeclarationUniverses [tyTm]
  let captureCount = length captureTele
      dataHeadAt depth =
        foldl'
          (CApp Impl)
          (CGlobI g declarationUniverses)
          [CVar (depth - captureLevel - 1) | captureLevel <- [0 .. captureCount - 1]]
  dataUniverses <- gets (maybe emptyDeclarationUniverseTelescope gdUniverses . Map.lookup g . csGlobals)
  ctorGs <- forM preparedCtors $ \(cg, fields, sourceFields, prepared) ->
    withActiveUniverseDefinition cg $
      do
        ctyBase <- case prepared of
          Left fieldsTele -> do
            let resultHead = dataHeadAt (captureCount + length paramTele + length fieldsTele)
                resultT =
                  foldl
                    (\f (entry, index) -> CApp (teIcit entry) f (CVar index))
                    resultHead
                    (zip paramTele (reverse [length fieldsTele .. length fieldsTele + length paramTele - 1]))
            pure $
              foldr telePi resultT
                (captureTele ++ [entry {teIcit = Impl, teQ = Q0} | entry <- paramTele] ++ fieldsTele)
          Right gadtType ->
            pure $
              foldr telePi
                (rewriteConstructorResultHead g declarationUniverses (dropLeadingPis (length paramTele) gadtType))
                (captureTele ++ [entry {teIcit = Impl, teQ = Q0} | entry <- paramTele])
        let proofCount = length familyConstraints
            ctyWithProofArguments =
              applyGeneratedConstraintArguments g proofCount ctyBase
            (cty0, _) =
              prependGeneratedConstraintBinders
                (dutParameterCount dataUniverses)
                familyConstraints
                ctyWithProofArguments
                (CRecordV [])
        cty <- zonkTermM 0 cty0
        modify' $ \st ->
          st
            { csCtors =
                Map.insert cg (CtorInfo g dataUniverses cty fields sourceFields) (csCtors st)
            }
        pure cg
  modify' $ \st ->
    st
      { csDatas =
          Map.insert g (DataInfo ctorGs (captureCount + length params) dataLevel) (csDatas st)
      }
  modify' $ \st ->
    st
      { csNominalSummaryRequests =
          Map.insert g
            (PendingDataNominalSummary (nameUniverseSchema n) (captureCount + length params) ctorGs sp)
            (csNominalSummaryRequests st)
      , csDirtyNominalSummaries = Set.insert g (csDirtyNominalSummaries st)
      }
  where
    -- A constructor instantiation in a declaration restates the enclosing
    -- data schema; it never introduces a second declaration telescope. The
    -- parser stores the spelling in the common schema node, so resolve every
    -- argument through the active owner-schema environment and compare the
    -- resulting rigid identities rather than comparing source names.
    validateConstructorUniverseInstantiation context ownerName constructorName = \case
        Nothing -> pure ()
        Just constructorInstantiation -> do
          let ownerArity = maybe 0 (length . usParameters) (nameUniverseSchema ownerName)
              supplied = uiLevels constructorInstantiation
              suppliedArity = length supplied
          when (ownerArity /= suppliedArity) $
            errAt (uiSpan constructorInstantiation)
              "E_UNIVERSE_SCHEMA_ARITY_MISMATCH"
              (Just "kappa.universe.schema-arity")
              ( "constructor '" <> nameText constructorName
                  <> "' restates the enclosing data schema, which expects "
                  <> T.pack (show ownerArity) <> " universe arguments, but "
                  <> T.pack (show suppliedArity) <> " were supplied"
              )
          errorsBefore <- gets (length . filter ((== SevError) . dSeverity) . csDiags)
          resolved <- mapM (fmap snd . elabLevelExpr context) supplied
          errorsAfter <- gets (length . filter ((== SevError) . dSeverity) . csDiags)
          let
              expected = map (Just . LParam) [0 .. ownerArity - 1]
          when (errorsAfter == errorsBefore && ownerArity == suppliedArity && map Just resolved /= expected) $
            errAt (uiSpan constructorInstantiation)
              "E_UNIVERSE_SCHEMA_SCOPE"
              (Just "kappa.universe.schema-scope")
              ( "constructor '" <> nameText constructorName
                  <> "' must restate the enclosing data declaration's universe arguments in declaration order"
              )

    dropLeadingPis 0 term = term
    dropLeadingPis count (CPiM _ _ _ _ _ _ codomain) = dropLeadingPis (count - 1) codomain
    dropLeadingPis _ term = term

    ctorFieldsOf binders mgadt = case mgadt of
      Just sig -> gadtFields sig
      Nothing -> [(nameText <$> bName b, bDefault b) | b <- binders, not (bImplicit b)]
    ctorSourceFieldsOf binders mgadt = case mgadt of
      Just sig -> gadtSourceFields sig
      Nothing ->
        [ (if bImplicit binder then Impl else Expl, nameText <$> bName binder)
        | binder <- binders
        ]
    gadtFields = \case
      EArrow b rest | not (bImplicit b) -> (nameText <$> bName b, bDefault b) : gadtFields rest
      EArrow _ rest -> gadtFields rest
      EForall _ rest _ -> gadtFields rest
      ETraitArrow _ rest -> gadtFields rest
      _ -> []
    gadtSourceFields = \case
      EArrow binder rest ->
        (if bImplicit binder then Impl else Expl, nameText <$> bName binder)
          : gadtSourceFields rest
      EForall _ rest _ -> gadtSourceFields rest
      ETraitArrow _ rest -> gadtSourceFields rest
      _ -> []

-- | Build and independently replay the nominal role summary from finalized
-- typed constructor telescopes.  Source annotations can only tighten this
-- inferred vector; they are never used as evidence for inference.
finalizePendingNominalSummaries :: CheckM ()
finalizePendingNominalSummaries = do
  state <- get
  let ready =
        Map.restrictKeys
          (csNominalSummaryRequests state)
          ( Set.intersection
              (csDirtyNominalSummaries state)
              (csFinalizedUniverseInterfaces state)
          )
  (roleFixedPoint, frozenMonotone, evidencePending) <- inferPendingNominalRoles ready
  let finalizable = Map.withoutKeys ready evidencePending
  forM_ (Map.toAscList finalizable) $ \(family, request) ->
    case request of
      PendingDataNominalSummary sourceSchema parameterCount constructors site -> do
        closure <- dataNominalSignatureClosure frozenMonotone roleFixedPoint family parameterCount constructors site
        installDataNominalSummary family sourceSchema closure site
      PendingTraitNominalSummary sourceSchema saturationArity clauses site -> do
        closure <- traitNominalSignatureClosure roleFixedPoint family saturationArity clauses site
        installTraitNominalSummary family sourceSchema closure site
  unless (Map.null finalizable) $
    modify' $ \st ->
      st
        { csDirtyNominalSummaries =
            Set.difference (csDirtyNominalSummaries st) (Map.keysSet finalizable)
        }

-- | §10.4.3.2 greatest fixed point for one finalized nominal block.  Every
-- family starts maximally permissive; recursive references consult the
-- tentative vector for this same block, while references outside the block
-- consume only independently verified summaries.  The transfer function can
-- therefore only retain or tighten roles and terminates over the finite
-- three-point lattice.
inferPendingNominalRoles
  :: Map GName PendingNominalSummary
  -> CheckM (Map GName [UniverseVariance], FrozenMonotoneEvidence, Set GName)
inferPendingNominalRoles pending = do
  definitions <- gets csGlobals
  (frozenMonotone, evidencePending) <- freezePendingMonotoneEvidence pending
  let arity family = maybe 0 (dutParameterCount . gdUniverses) (Map.lookup family definitions)
      initial = Map.mapWithKey (\family _ -> replicate (arity family) Irrelevant) pending
      iterateRoles roles = do
        requirements <- Map.traverseWithKey (requirementsFor frozenMonotone roles) pending
        let inferred = Map.mapWithKey (\family rs -> inferUniverseRoles (arity family) rs) requirements
            tightened = Map.intersectionWith (zipWith min) roles inferred
        if tightened == roles then pure roles else iterateRoles tightened
  roles <- iterateRoles initial
  pure (roles, frozenMonotone, evidencePending)
  where
    requirementsFor frozen roles family = \case
      PendingDataNominalSummary _ parameterCount constructors _ ->
        dataNominalRequirements frozen family roles parameterCount constructors
      PendingTraitNominalSummary _ _ clauses _ ->
        traitNominalRequirements roles clauses

-- | Evidence authority consumed by the role fixed point.  The key includes
-- the nominal block, declaration-universe parameter, and normalized one-hole
-- operator.  It is populated exactly once before iteration; replay never
-- launches open-ended trait search (§10.4.3.4).
type FrozenMonotoneKey = (GName, Int, NeutralLevelTerm)

type FrozenMonotoneEvidence = Map FrozenMonotoneKey NominalMonotoneWitness

freezePendingMonotoneEvidence
  :: Map GName PendingNominalSummary
  -> CheckM (FrozenMonotoneEvidence, Set GName)
freezePendingMonotoneEvidence pending = do
  results <- mapM freezeFamily (Map.toAscList pending)
  pure
    ( Map.fromList (concatMap fst results)
    , Set.fromList [family | (entries, family) <- zip results (Map.keys pending), snd entries]
    )
  where
    freezeFamily (family, PendingDataNominalSummary _ sourceParameterCount constructors _) = do
      constructorTable <- gets csCtors
      parameterCount <- nominalPhysicalSaturationArity family sourceParameterCount
      results <- forM constructors $ \constructor ->
        case Map.lookup constructor constructorTable of
          Nothing -> pure ([], False)
          Just info -> freezeConstructor family parameterCount (ciType info)
      pure (concatMap fst results, or (map snd results))
    freezeFamily (_, PendingTraitNominalSummary _ _ _ _) = pure ([], False)

    freezeConstructor family parameterCount constructorType = do
      (parameterCtx, fields) <- enterParameters emptyCtx parameterCount constructorType
      results <- goFields family parameterCtx fields
      pure (concatMap fst results, or (map snd results))

    enterParameters ctx 0 term = pure (ctx, term)
    enterParameters ctx count (CPiEvidenceM mode _ ic quantity borrowed name assumption _ domain codomain) = do
      domainValue <- evalIn ctx domain
      withAssumption <- extendLevelAssumption noSpan ctx assumption
      let next = bindCtxMQB mode quantity name (ic == Impl) borrowed domainValue withAssumption
      enterParameters next (count - 1) codomain
    enterParameters ctx _ term = pure (ctx, term)

    goFields family ctx (CPiEvidenceM mode _ ic quantity borrowed name assumption _ domain codomain) = do
      current <- mapM (freezeCandidate family ctx) (monotoneCandidatesOfTerm domain)
      domainValue <- evalIn ctx domain
      withAssumption <- extendLevelAssumption noSpan ctx assumption
      let next = bindCtxMQB mode quantity name (ic == Impl) borrowed domainValue withAssumption
      rest <- goFields family next codomain
      pure (current ++ rest)
    goFields _ _ _ = pure []

    freezeCandidate family ctx (parameter, operator) =
      case neutralLevelTermToCore (ctxLen ctx) operator of
        Nothing -> pure ([], False)
        Just operatorTerm -> do
          selected <- selectMonotoneEvidence ctx operatorTerm
          pending <- case selected >>= globalHeadOfTerm of
            Nothing -> pure False
            Just dictionary -> gets (maybe True (isNothing . gdValue) . Map.lookup dictionary . csGlobals)
          monotone <- globalHeadM prelMonotone
          let goalTerm = CApp Expl monotone operatorTerm
              serialized = do
                evidenceTerm <- selected
                goal <- coreToNeutralLevelTerm (ctxLen ctx) goalTerm
                evidence <- coreToNeutralLevelTerm (ctxLen ctx) evidenceTerm
                pure
                  ( (family, parameter, operator)
                  , NominalMonotoneWitness
                      { nmwParameter = parameter
                      , nmwOperator = operator
                      , nmwGoal = goal
                      , nmwEvidence = evidence
                      , nmwDependencies = nominalEvidenceDependencies [goal, evidence]
                      }
                  )
          pure (maybeToList serialized, pending)

    globalHeadOfTerm term = case fst (spineOfTerm term) of
      CGlobal identity _ -> Just identity
      _ -> Nothing

-- | Extract the opaque one-hole applications whose variance needs ordinary
-- evidence. Constructor algebra (succ/add/max) is handled structurally; an
-- arbitrary neutral application is never assumed monotone from its spelling.
monotoneCandidatesOfTerm :: Term -> [(Int, NeutralLevelTerm)]
monotoneCandidatesOfTerm = concatMap monotoneCandidatesOfLevel . levelsOfTerm
  where
    levelsOfTerm = \case
      CSort level -> [level]
      CLevel level -> [level]
      term ->
        concatMap levelsOfTerm (childrenOfTerm term)

    childrenOfTerm = \case
      CPiEvidenceM _ _ _ _ _ _ _ _ domain codomain -> [domain, codomain]
      CApp _ function argument -> [function, argument]
      CUniverseLift _ _ _ inner -> [inner]
      CSchemaLift _ _ _ _ _ _ sourceArguments targetArguments inner ->
        sourceArguments ++ targetArguments ++ [inner]
      CRecordTQ fields -> map rfType fields
      CRecordV fields -> map snd fields
      CProjM _ receiver _ -> [receiver]
      CProjAtM _ receiver _ _ -> [receiver]
      CVariantT members -> members
      CInject _ value -> [value]
      CSealE _ value -> [value]
      CSigT _ value -> [value]
      CThunkE value suspensionType -> value : maybeToList suspensionType
      CLazyE value suspensionType -> value : maybeToList suspensionType
      CForceE value resultType -> value : maybeToList resultType
      CIf condition yes no -> [condition, yes, no]
      _ -> []

monotoneCandidatesOfLevel :: Level -> [(Int, NeutralLevelTerm)]
monotoneCandidatesOfLevel = \case
  LSucc level -> monotoneCandidatesOfLevel level
  LAdd left right -> monotoneCandidatesOfLevel left ++ monotoneCandidatesOfLevel right
  LMax left right -> monotoneCandidatesOfLevel left ++ monotoneCandidatesOfLevel right
  LNeutral (NeutralLevelTermAtom _ term) -> case term of
    NLTApply True operator (NLTLevel (LParam parameter))
      | parameter `notElem` concatMap levelParams (neutralLevelTermLevels operator) ->
          [(parameter, operator)]
    _ -> []
  _ -> []

neutralLevelTermToCore :: Int -> NeutralLevelTerm -> Maybe Term
neutralLevelTermToCore depth = \case
  NLTLocal level
    | level >= 0 && level < depth -> Just (CVar (depth - level - 1))
    | otherwise -> Nothing
  NLTLocalDeclaration level universes
    | level >= 0 && level < depth -> Just (CLocal (depth - level - 1) universes)
    | otherwise -> Nothing
  NLTGlobal owner name universes -> Just (CGlobI (GName (ModuleName owner) name) universes)
  NLTConstruct owner name universes arguments ->
    CCtorI (GName (ModuleName owner) name) universes Nothing
      <$> mapM (\(explicit, argument) -> ConstructorArg (if explicit then Expl else Impl) True Nothing <$> neutralLevelTermToCore depth argument) arguments
  NLTApply explicit function argument ->
    CApp (if explicit then Expl else Impl)
      <$> neutralLevelTermToCore depth function
      <*> neutralLevelTermToCore depth argument
  NLTProject field receiver -> CProjM Ordinary <$> neutralLevelTermToCore depth receiver <*> pure field
  NLTLevel level -> Just (CLevel level)
  NLTLiteral literal -> CLit <$> case literal of
    NLLInt value -> Just (LitInt value)
    NLLDouble value -> Just (LitDouble value)
    NLLString value -> Just (LitStr value)
    NLLScalar value -> Just (LitScalar value)
    NLLByte value -> Just (LitByte value)
    -- Byte arrays are represented by a packed host ByteString in Core; this
    -- role-evidence path has no need to reconstruct literal byte payloads.
    NLLBytes _ -> Nothing
    NLLGrapheme value -> Just (LitGrapheme value)
  NLTRecord fields -> CRecordV <$> mapM (\(field, value) -> (field,) <$> neutralLevelTermToCore depth value) fields
  NLTIf condition yes no -> CIf
    <$> neutralLevelTermToCore depth condition
    <*> neutralLevelTermToCore depth yes
    <*> neutralLevelTermToCore depth no
  NLTUnsupported _ -> Nothing

selectMonotoneEvidence :: Ctx -> Term -> CheckM (Maybe Term)
selectMonotoneEvidence ctx operator = do
  monotone <- globalHeadM prelMonotone
  let goalTerm = CApp Expl monotone operator
  goal <- evalIn ctx goalTerm
  before <- get
  local <- localCandidate ctx noSpan Q0 goal
  selected <- case local of
    Just evidence -> pure (Just evidence)
    Nothing -> instanceSearch ctx noSpan goal
  case selected of
    Nothing -> put before >> pure Nothing
    Just evidence -> do
      recordSelectedMonotoneEvidence
        ctx
        operator
        ("(" <> renderTerm goalTerm <> ")")
        evidence
      pure (Just evidence)

-- | Freeze the selected artifact whenever ordinary implicit resolution
-- settles the canonical @Monotone@ goal.  Role inference and test reflection
-- observe this record; neither performs a second search.  Recognition is by
-- the resolved trait identity and the selected dictionary's exact checked
-- member, never by source spelling.
recordSelectedUniverseEvidence :: Ctx -> Value -> Term -> CheckM ()
recordSelectedUniverseEvidence ctx goal dictionary = do
  forced <- forceM goal
  case forced of
    VGlobI trait _ spine
      | trait == prelMonotone -> do
          st <- get
          case traitSemanticSpineIn st trait spine of
            Just [(_, operator)] -> do
              operatorTerm <- quoteIn ctx operator
              renderedGoal <- renderSelectedMonotoneGoal ctx operator operatorTerm
              recordSelectedMonotoneEvidence ctx operatorTerm renderedGoal dictionary
            _ -> pure ()
    _ -> pure ()

recordSelectedMonotoneEvidence :: Ctx -> Term -> Text -> Term -> CheckM ()
recordSelectedMonotoneEvidence ctx _operator renderedGoal dictionary = do
  evidenceIdentity <- selectedMonotoneMemberIdentity ctx dictionary
  forM_ evidenceIdentity $ \identity ->
    modify' $ \state ->
      state
        { csSelectedUniverseEvidence =
            Set.insert
              (SelectedUniverseEvidence renderedGoal identity)
              (csSelectedUniverseEvidence state)
        }

-- | Render the semantic one-hole level function in the compact source form
-- used by the Appendix-T reflection directive.  This is presentation only:
-- authentication and equality were already established from typed Core.  A
-- direct global keeps its identity; lambdas over the canonical level algebra
-- are rendered from their normalized 'Level', so elaborator-generated trait
-- dictionaries and aliases cannot perturb the reflected goal.
renderSelectedMonotoneGoal :: Ctx -> Value -> Term -> CheckM Text
renderSelectedMonotoneGoal ctx operator operatorTerm =
  case fst (spineOfTerm operatorTerm) of
    CGlobal _ _ | null (snd (spineOfTerm operatorTerm)) ->
      pure ("(Monotone " <> renderTerm operatorTerm <> ")")
    _ ->
      renderSelectedLevelLambda operatorTerm >>= \case
        Just rendered -> pure ("(Monotone " <> rendered <> ")")
        Nothing -> do
          typeLevel <- globalValueM prelTypeLevel []
          ec <- ec_
          let binderLevel = ctxLen ctx
              variable = VRigid binderLevel []
              extended = bindCtxMQ Parametric Q0 "x" False typeLevel ctx
          bodyTerm <- quoteIn extended (vapp ec operator Expl variable)
          (_, identity) <- levelIdentityOfCheckedTerm extended bodyTerm
          pure $ case identity of
            Right level ->
              "(Monotone (\\x -> "
                <> renderSelectedLevel binderLevel level
                <> "))"
            Left _ -> "(Monotone " <> renderTerm operatorTerm <> ")"

-- | Compact a checked source lambda over a standard level operator while
-- retaining its explicit operands.  Operator authority comes from the exact
-- selected global/dictionary identity; the textual spelling is never used to
-- recognize arithmetic.  This keeps reflection stable without reducing an
-- opaque operand such as @k@ to its implementation.
renderSelectedLevelLambda :: Term -> CheckM (Maybe Text)
renderSelectedLevelLambda = \case
  CLamM _ Expl _ _ body -> do
    let (headTerm, arguments) = spineWithIcit body
        implicitHead =
          List.foldl'
            (\function (icity, argument) -> CApp icity function argument)
            headTerm
            [argument | argument@(Impl, _) <- arguments]
        explicitArguments = [argument | (Expl, argument) <- arguments]
    classifyLevelOperatorTerm Set.empty implicitHead >>= \case
      Just LevelOperatorAdd
        | [left, right] <- explicitArguments ->
            pure (Just (lambdaBody (renderOperand left <> " + " <> renderOperand right)))
      Just LevelOperatorMax
        | [left, right] <- explicitArguments ->
            pure (Just (lambdaBody ("max " <> renderOperand left <> " " <> renderOperand right)))
      Just LevelOperatorSucc
        | [argument] <- explicitArguments ->
            pure (Just (lambdaBody ("succ " <> renderOperand argument)))
      _ -> pure Nothing
  _ -> pure Nothing
  where
    lambdaBody body = "(\\x -> " <> body <> ")"
    renderOperand term = case stripIdentityWrappers term of
      CVar 0 -> "x"
      other -> renderTerm other
    spineWithIcit = go []
      where
        go arguments (CApp icity function argument) =
          go ((icity, argument) : arguments) function
        go arguments function = (function, arguments)

renderSelectedLevel :: Int -> Level -> Text
renderSelectedLevel binderLevel = go . normalizeLevel
  where
    go = \case
      LZero -> "typeLevelZero"
      LFinite 1 -> "typeLevelOne"
      LFinite n -> "typeLevelFinite " <> T.pack (show n)
      LOmega -> "typeLevelOmega"
      LSucc level -> "succ " <> atom level
      LAdd left right -> atom left <> " + " <> atom right
      LMax left right -> "max " <> atom left <> " " <> atom right
      LVar level | level == binderLevel -> "x"
      LVar level -> "u" <> T.pack (show level)
      LField _ field -> "this." <> field
      LProjection root path ->
        "u" <> T.pack (show root) <> "." <> T.intercalate "." path
      LNeutral (NeutralLevelTermAtom _ term) ->
        maybe "<opaque-level>" renderTerm (neutralLevelTermToCore (binderLevel + 1) term)
      LNeutral (NeutralLevelSymbol identity arguments) ->
        identity
          <> if null arguments
               then ""
               else "[" <> T.intercalate ", " (map go arguments) <> "]"
      LMeta meta -> "?u" <> T.pack (show meta)
      LParam parameter -> "^u#" <> T.pack (show parameter)
    atom level@LAdd {} = "(" <> go level <> ")"
    atom level@LMax {} = "(" <> go level <> ")"
    atom level = go level

selectedMonotoneMemberIdentity :: Ctx -> Term -> CheckM (Maybe GName)
selectedMonotoneMemberIdentity ctx dictionary = do
  mode <- gets $ \state ->
    fromMaybe Parametric $ do
      trait <- Map.lookup prelMonotone (csTraits state)
      Map.lookup "monotone" (tiMemberModes trait)
  member <- forceM =<< evalIn ctx (CProjM mode dictionary "monotone")
  let projected = do
        term <- neutralValueTerm (ctxLen ctx) member
        globalHead term
  case projected of
    Just identity -> pure (Just identity)
    Nothing -> do
      -- Generated instance dictionaries may be deliberately non-reducible at
      -- this phase.  Their checked Core body is still the authoritative
      -- selected artifact, so inspect the exact selected dictionary global
      -- rather than scanning declarations for a theorem-shaped type.
      state <- get
      pure $ do
        dictionaryIdentity <- globalHead dictionary
        body <- Map.lookup dictionaryIdentity (csCoreBodies state)
          <|> (Map.lookup dictionaryIdentity (csGlobals state) >>= gdCoreBody)
        memberTerm <- case peelDictionaryTelescope body of
          CRecordV fields -> lookup "monotone" fields
          _ -> Nothing
        globalHead memberTerm
  where
    peelDictionaryTelescope = \case
      CLamM _ _ _ _ body -> peelDictionaryTelescope body
      body -> body
    globalHead term = case fst (spineOfTerm term) of
      CGlobal identity _ -> Just identity
      _ -> Nothing

-- | The saturation authority is the finalized physical family telescope.
-- Source parameter counts deliberately exclude compiler-generated proof
-- binders, while §11.1.2.3A.2 includes every implicit/erased binder in full
-- saturation. Falling back to the source count is only for the diagnostic
-- recovery path where the family global is unavailable.
nominalPhysicalSaturationArity :: GName -> Int -> CheckM Int
nominalPhysicalSaturationArity family fallback = do
  state <- get
  pure $
    maybe fallback (piArity . globalCoreType (ecOf state))
      (Map.lookup family (csGlobals state))
  where
    piArity (CPiM _ _ _ _ _ _ codomain) = 1 + piArity codomain
    piArity _ = 0

dataNominalRequirements
  :: FrozenMonotoneEvidence
  -> GName
  -> Map GName [UniverseVariance]
  -> Int
  -> [GName]
  -> CheckM [RoleRequirement]
dataNominalRequirements frozenMonotone family tentativeRoles dataParameterCount constructors = do
  constructorTable <- gets csCtors
  fmap (nub . sort . concat) $
    forM constructors $ \constructor ->
      case Map.lookup constructor constructorTable of
        Nothing -> pure []
        Just info ->
          nominalRequirementsFromConstructor
            frozenMonotone family tentativeRoles dataParameterCount (ciType info)

-- | Materialize the current ordinary-data signature closure once. Role
-- inference, certificate replay, semantic hashing, and interface export all
-- consume this same typed record; none rebuild a source-shaped clause list.
dataNominalSignatureClosure
  :: FrozenMonotoneEvidence
  -> Map GName [UniverseVariance]
  -> GName
  -> Int
  -> [GName]
  -> Span
  -> CheckM NominalSignatureClosure
dataNominalSignatureClosure frozenMonotone tentativeRoles family dataParameterCount constructors site = do
  definitions <- gets csGlobals
  constructorTable <- gets csCtors
  ec <- ec_
  case Map.lookup family definitions of
    Nothing -> do
      errAt site "E_KCORE_SCHEMA_CERTIFICATE_INVALID"
        (Just "kappa.kcore.schema-certificate-invalid")
        "nominal signature closure has no finalized family interface"
      pure $
        makeNominalSignatureClosure 0 [] dataParameterCount
          [ NominalClosureClause ClauseExtension ("invalid-family:" <> gKey family) [] "missing"
              [] NominalTransformRepresentation
          ]
    Just definition -> do
      pointClauses <- fmap concat . forM constructors $ \constructor ->
        case Map.lookup constructor constructorTable of
          Nothing -> do
            errAt site "E_KCORE_SCHEMA_CERTIFICATE_INVALID"
              (Just "kappa.kcore.schema-certificate-invalid")
              ("nominal signature closure is missing constructor " <> gKey constructor)
            pure []
          Just info -> do
            requirements <-
              nominalRequirementsFromConstructor
                frozenMonotone family tentativeRoles dataParameterCount (ciType info)
            pure [nominalClosureClause ClausePointConstructor ("constructor:" <> gKey constructor) requirements (ciType info)]
      let familyType = globalCoreType ec definition
          sortClause = nominalClosureClause ClauseSortDeclaration ("family:" <> gKey family) [] familyType
          generated kind label point =
            point
              { nccKind = kind
              , nccIdentity = label <> ":" <> nccIdentity point
              }
          clauses =
            sortClause : pointClauses
              ++ concat
                   [ [ generated ClauseEliminator "eliminator" point
                     , generated ClauseComputationRule "computation" point
                     ]
                   | point <- pointClauses
                   ]
      physicalSaturationArity <- nominalPhysicalSaturationArity family dataParameterCount
      pure $
        withNominalMonotoneWitnesses
          [ witness
          | ((owner, _, _), witness) <- Map.toAscList frozenMonotone
          , owner == family
          ]
          ( makeNominalSignatureClosure
              (dutParameterCount (gdUniverses definition))
              (declarationConstraintSummary (dutParameterCount (gdUniverses definition)) familyType)
              physicalSaturationArity
              clauses
          )

traitNominalSignatureClosure
  :: Map GName [UniverseVariance]
  -> GName
  -> Int
  -> [Term]
  -> Span
  -> CheckM NominalSignatureClosure
traitNominalSignatureClosure tentativeRoles family saturationArity clauses site = do
  definitions <- gets csGlobals
  ec <- ec_
  case Map.lookup family definitions of
    Nothing -> do
      errAt site "E_KCORE_SCHEMA_CERTIFICATE_INVALID"
        (Just "kappa.kcore.schema-certificate-invalid")
        "trait nominal signature closure has no finalized family interface"
      pure $
        makeNominalSignatureClosure 0 [] saturationArity
          [ NominalClosureClause ClauseExtension ("invalid-trait:" <> gKey family) [] "missing"
              [] NominalTransformRepresentation
          ]
    Just definition -> do
      memberClauses <- forM (zip [0 :: Int ..] clauses) $ \(index, term) -> do
        requirements <- traitNominalRequirements tentativeRoles [term]
        pure (nominalClosureClause ClauseGeneratedProjection ("projection:" <> gKey family <> ":" <> T.pack (show index)) requirements term)
      let familyType = globalCoreType ec definition
          sortClause = nominalClosureClause ClauseSortDeclaration ("family:" <> gKey family) [] familyType
          dictionaryClause =
            NominalClosureClause ClausePointConstructor ("dictionary:" <> gKey family)
              (concatMap nccBinders memberClauses)
              (nominalTypeFingerprint familyType)
              (concatMap nccRoleActions memberClauses)
              NominalPreserveRepresentation
          derivedDictionaryClause kind label =
            dictionaryClause
              { nccKind = kind
              , nccIdentity = label <> ":" <> nccIdentity dictionaryClause
              }
      physicalSaturationArity <- nominalPhysicalSaturationArity family saturationArity
      pure $
        makeNominalSignatureClosure
          (dutParameterCount (gdUniverses definition))
          (declarationConstraintSummary (dutParameterCount (gdUniverses definition)) familyType)
          physicalSaturationArity
          ( sortClause
              : dictionaryClause
              : derivedDictionaryClause ClauseEliminator "eliminator"
              : derivedDictionaryClause ClauseComputationRule "computation"
              : memberClauses
          )

nominalClosureClause :: NominalClauseKind -> Text -> [RoleRequirement] -> Term -> NominalClosureClause
nominalClosureClause kind identity requirements = go []
  where
    go binders (CPiEvidenceM mode formation ic quantity borrowed _ assumption _ domain codomain) =
      go
        ( binders
            ++ [ NominalBinderContract
                   mode
                   formation
                   (case ic of Expl -> NominalExplicit; Impl -> NominalImplicit)
                   (case quantity of
                      Q0 -> NominalZero
                      Q1 -> NominalOne
                      QW -> NominalOmega
                      QLe1 -> NominalAtMostOne
                      QGe1 -> NominalAtLeastOne)
                   borrowed
                   (fmap (\(lower, upper) -> (renderLevel (normalizeLevel lower), renderLevel (normalizeLevel upper))) assumption)
                   (nominalTypeFingerprint domain)
               ]
        )
        codomain
    go binders result =
      NominalClosureClause kind identity binders (nominalTypeFingerprint result)
        (map requirementAction requirements)
        NominalPreserveRepresentation

    requirementAction = \case
      RequireCovariant index _ -> NominalCovariantUse index
      RequireInvariant index _ -> NominalInvariantUse index

-- | Certify a compiler-seeded, universe-closed data family through the same
-- normalized nominal closure consumed by source declarations. Seeded logical
-- families such as Nat exist before the ordinary declaration pipeline runs,
-- so they cannot use 'PendingDataNominalSummary'; accepting them without a
-- summary would make independently verified KCore depend on an in-process
-- checker exception. Keep this entry point deliberately narrow: a seeded
-- family with universe parameters or constraints must go through the full
-- declaration fixed point instead of guessing roles here.
certifyClosedBuiltinData :: GName -> CheckState -> Either Text CheckState
certifyClosedBuiltinData family state = do
  definition <-
    maybe
      (Left ("seeded nominal family is missing its global interface: " <> gKey family))
      Right
      (Map.lookup family (csGlobals state))
  dataInfo <-
    maybe
      (Left ("seeded nominal family is missing its data interface: " <> gKey family))
      Right
      (Map.lookup family (csDatas state))
  unless (dutParameterCount (gdUniverses definition) == 0) $
    Left ("seeded closed nominal family unexpectedly has declaration universes: " <> gKey family)
  constructorInfos <-
    forM (diCtors dataInfo) $ \constructor ->
      maybe
        (Left ("seeded nominal family is missing constructor " <> gKey constructor))
        Right
        (Map.lookup constructor (csCtors state))
  unless (all ((== family) . ciData) constructorInfos) $
    Left ("seeded nominal family includes a constructor owned by another family: " <> gKey family)
  let ec = EvalCtx (Globals (csGlobals state)) (csMetas state) False mempty
      familyType = globalCoreType ec definition
      constructorTypes = map ciType constructorInfos
      constraints = declarationConstraintSummary 0 familyType
  unless
    ( null constraints
        && null (levelParamsOfTerm familyType)
        && all (null . levelParamsOfTerm) constructorTypes
    ) $
      Left ("seeded closed nominal family contains an open universe obligation: " <> gKey family)
  let sortClause =
        nominalClosureClause
          ClauseSortDeclaration
          ("family:" <> gKey family)
          []
          familyType
      pointClauses =
        zipWith
          (\constructor info ->
             nominalClosureClause
               ClausePointConstructor
               ("constructor:" <> gKey constructor)
               []
               (ciType info))
          (diCtors dataInfo)
          constructorInfos
      generated kind label point =
        point
          { nccKind = kind
          , nccIdentity = label <> ":" <> nccIdentity point
          }
      closure =
        makeNominalSignatureClosure
          0
          []
          (diParamCount dataInfo)
          ( sortClause
              : pointClauses
              ++ concat
                   [ [ generated ClauseEliminator "eliminator" point
                     , generated ClauseComputationRule "computation" point
                     ]
                   | point <- pointClauses
                   ]
          )
      summary =
        makeNominalCumulativitySummary
          (gKey family)
          []
          []
          closure
          Nothing
  unless (verifyNominalCumulativitySummary summary) $
    Left ("seeded nominal family certificate failed independent replay: " <> gKey family)
  pure
    state
      { csGlobals =
          Map.adjust
            (globalDefWithNominalSummary summary)
            family
            (csGlobals state)
      }

-- Resolved globals, de Bruijn indices, levels, and field identities are
-- semantic. Binder names are presentation only, so erase them recursively
-- from the type grammar before hashing the closure.
nominalTypeFingerprint :: Term -> Text
nominalTypeFingerprint = stableNominalHash . renderStructuralTermKey . alphaType
  where
    alphaType = \case
      CLamM mode ic quantity _ body -> CLamM mode ic quantity "_" (alphaType body)
      CPiEvidenceM mode formation ic quantity borrowed _ assumption origin domain codomain ->
        CPiEvidenceM mode formation ic quantity borrowed "_" assumption origin (alphaType domain) (alphaType codomain)
      CApp ic function argument -> CApp ic (alphaType function) (alphaType argument)
      CUniverseLift from to evidence term -> CUniverseLift from to evidence (alphaType term)
      CSchemaLift owner source target roles evidence certificate sourceArguments targetArguments term ->
        CSchemaLift owner source target roles evidence certificate
          (map alphaType sourceArguments) (map alphaType targetArguments) (alphaType term)
      CRecordTQ fields -> CRecordTQ (map (fmap alphaType) fields)
      CVariantT members -> CVariantT (map alphaType members)
      CSigT labels term -> CSigT labels (alphaType term)
      CSealE labels term -> CSealE labels (alphaType term)
      CProjM mode term field -> CProjM mode (alphaType term) field
      CProjAtM mode term field index -> CProjAtM mode (alphaType term) field index
      CThunkE term suspensionType ->
        CThunkE (alphaType term) (alphaType <$> suspensionType)
      CLazyE term suspensionType ->
        CLazyE (alphaType term) (alphaType <$> suspensionType)
      CForceE term resultType ->
        CForceE (alphaType term) (alphaType <$> resultType)
      term -> term

-- Trait dictionaries are nominal records. Their supplied trait parameters do
-- not constrain declaration-universe roles, but member and supertrait field
-- types do. Analyse those elaborated Core types in the same SCC fixed point as
-- data constructors; an unrecognized type operation is invariant.
traitNominalRequirements
  :: Map GName [UniverseVariance]
  -> [Term]
  -> CheckM [RoleRequirement]
traitNominalRequirements tentativeRoles terms =
  fmap (nub . sort . concat) (mapM requirements terms)
  where
    requirements term =
      go (stripNominalWrappers term)

    go = \case
      CSort level ->
        pure [RequireCovariant parameter "trait dictionary field stores a type code or witness" | parameter <- levelParams level]
      CPiEvidenceM _ _ _ _ _ _ _ _ domain codomain -> do
        let domainRequirements =
              [ RequireInvariant parameter "trait dictionary function domain uses a declaration universe"
              | parameter <- levelParamsOfTerm domain
              ]
        codomainRequirements <- go (stripNominalWrappers codomain)
        pure (domainRequirements ++ codomainRequirements)
      nominal -> do
        certified <- requirementsFromCertifiedNominal nominal
        pure $ fromMaybe
          [ RequireInvariant parameter "trait dictionary field uses a universe under an unverified operation"
          | parameter <- levelParamsOfTerm nominal
          ]
          certified

    requirementsFromCertifiedNominal term = do
      let (headTerm, arguments) = spineOfTerm term
      case headTerm of
        CGlobal nested levels -> do
          externalSummary <- gets (Map.lookup nested . csGlobals) >>= pure . (>>= gdNominalSummary)
          let certifiedRoles =
                Map.lookup nested tentativeRoles
                  <|> (ncsRoles <$> (externalSummary >>= \summary ->
                        guard (verifyNominalCumulativitySummary summary && ncsFamilyIdentity summary == gKey nested)
                          >> pure summary))
          pure $ do
            roles <- certifiedRoles
            guard (length levels == length roles)
            pure
              ( concat
                  [ case role of
                      Invariant -> [RequireInvariant parameter "trait dictionary field uses an invariant certified family" | parameter <- levelParams level]
                      Covariant -> [RequireCovariant parameter "trait dictionary field uses a covariant certified family" | parameter <- levelParams level]
                      Irrelevant -> []
                  | (role, level) <- zip roles levels
                  ]
              )
        _ -> pure Nothing

    stripNominalWrappers = \case
      CUniverseLift _ _ _ inner -> stripNominalWrappers inner
      CSchemaLift _ _ _ _ _ _ _ _ inner -> stripNominalWrappers inner
      term -> term

installDataNominalSummary
  :: GName -> Maybe UniverseSchema -> NominalSignatureClosure -> Span -> CheckM ()
installDataNominalSummary family sourceSchema closure site = do
  globals <- gets csGlobals
  case Map.lookup family globals of
    Nothing -> pure ()
    Just definition -> do
      let parameterCount = dutParameterCount (gdUniverses definition)
      let requirements = nominalClosureRequirements closure
      let inferred = inferUniverseRoles parameterCount requirements
          written = maybe [] usRoles sourceSchema ++ repeat Nothing
          -- A rejected annotation is a diagnostic, never input to the
          -- certificate.  Retain the independently inferred role so one bad
          -- source annotation cannot manufacture a second, misleading
          -- certificate-replay failure.
          effective =
            zipWith
              (\annotation inferredRole ->
                case annotation of
                  Just writtenRole | rolePermitsAnnotation writtenRole inferredRole -> writtenRole
                  _ -> inferredRole
              )
              written
              inferred
          explicitFlags = map isJust (take parameterCount written)
      forM_ (zip4 [0 :: Int ..] (take parameterCount written) inferred effective) $
        \(index, annotation, inferredRole, effectiveRole) ->
          case annotation of
            Just writtenRole | not (rolePermitsAnnotation writtenRole inferredRole) ->
              report $
                withPayload
                  ( withPayloadField "nominalDeclaration" (gKey family) $
                      withPayloadField "nominalDeclarationIdentity" (gKey family) $
                      withPayloadField "signatureBlock" (gKey family) $
                        withPayloadField "parameterIndex" (T.pack (show index)) $
                          withPayloadField "universeParameterIndex" (T.pack (show index)) $
                          withPayloadField "sourceName" (schemaParameterName index) $
                            withPayloadField "explicitRole" (varianceText writtenRole) $
                              withPayloadField "inferredRole" (varianceText inferredRole) $
                                withPayloadField "effectiveRole" (varianceText effectiveRole) $
                                  withPayloadField "roleCheckerVersion" "1" $
                                    withPayloadField "forcingObligation" (forcingRequirement index requirements) $
                                      withPayloadField "declarationKind" "ordinary-data" $
                                        withPayloadField "nearestAcceptedRole" (varianceText inferredRole) $
                                          payloadKind "universe-variance"
                  ) $
                    diag SevError StageElaborate "E_UNIVERSE_VARIANCE_TOO_PERMISSIVE"
                      (Just "kappa.universe.variance") site
                      ( "universe role " <> varianceText writtenRole <> " for parameter "
                          <> schemaParameterName index <> " is more permissive than inferred role "
                          <> varianceText inferredRole <> " (§11.1.2.3A.2)"
                      )
            _ -> pure ()
      let summary =
            makeNominalCumulativitySummary (gKey family) effective explicitFlags closure Nothing
      if verifyNominalCumulativitySummary summary
        then modify' $ \st -> st {csGlobals = Map.adjust (globalDefWithNominalSummary summary) family (csGlobals st)}
        else
          errAt site "E_KCORE_SCHEMA_CERTIFICATE_INVALID"
            (Just "kappa.kcore.schema-certificate-invalid")
            "the generated nominal action certificate failed independent replay"
  where
    schemaParameterName index =
      fromMaybe ("^u#" <> T.pack (show index)) $ do
        schema <- sourceSchema
        parameter <- usParameters schema List.!? index
        pure (nameText parameter)

    forcingRequirement index requirements =
      fromMaybe "no clause requires a tighter role" $
        listToMaybe
          [ reason
          | requirement <- requirements
          , let (parameter, reason) = case requirement of
                  RequireCovariant i why -> (i, why)
                  RequireInvariant i why -> (i, why)
          , parameter == index
          ]

    varianceText = \case
      Invariant -> "invariant"
      Covariant -> "covariant"
      Irrelevant -> "irrelevant"

-- | Requirements contributed by constructor-local fields. Leading family
-- parameters are fixed aligned arguments, so their classifiers do not impose
-- schema variance. A direct type-code/witness field is covariant; occurrence
-- below a function or an unverified nominal operation is invariant.
nominalRequirementsFromConstructor
  :: FrozenMonotoneEvidence
  -> GName
  -> Map GName [UniverseVariance]
  -> Int
  -> Term
  -> CheckM [RoleRequirement]
nominalRequirementsFromConstructor frozenMonotone family tentativeRoles dataParameterCount term = do
  schemaArity <- gets $ \state ->
    maybe 0 (dutParameterCount . gdUniverses) (Map.lookup family (csGlobals state))
  goFields (dropPis dataParameterCount (dropDeclarationConstraints schemaArity term))
  where
    dropDeclarationConstraints arity candidate =
      case declarationUniverseConstraintBinder arity candidate of
        Just _ -> case candidate of
          CPiEvidenceM _ _ _ _ _ _ _ _ _ codomain ->
            dropDeclarationConstraints arity codomain
          _ -> candidate
        Nothing -> candidate

    dropPis 0 term = term
    dropPis count (CPiEvidenceM _ _ _ _ _ _ _ _ _ codomain) = dropPis (count - 1) codomain
    dropPis _ term = term

    goFields (CPiEvidenceM _ _ _ _ _ name assumption _ domain codomain) = do
      domainRequirements <- case assumption of
        -- Declaration constraints have already been removed by exact
        -- declaration-telescope identity above. A remaining checked
        -- assumption belongs to this constructor telescope. Reconstructing
        -- @lower <= upper@ at a larger schema instance is covariant in a
        -- monotone upper endpoint and invariant in a lower endpoint: raising
        -- the lower bound can invalidate the source proof.
        Just (lower, upper) ->
          pure
            ( [ RequireInvariant parameter
                  ("constructor proof field " <> name <> " uses a declaration universe in its lower bound")
              | parameter <- levelParams lower
              ]
                ++ requirementsForLevel name upper
            )
        Nothing -> requirementsForDomain name domain
      rest <- goFields codomain
      pure (domainRequirements ++ rest)
    goFields _ = pure []

    requirementsForDomain field term =
      case stripNominalWrappers term of
        CSort level ->
          pure (requirementsForLevel field level)
        nominal -> do
          certified <- requirementsFromCertifiedNominal field nominal
          pure $ fromMaybe
            [RequireInvariant parameter ("constructor field " <> field <> " uses the universe under a runtime type operation") | parameter <- levelParamsOfTerm nominal]
            certified

    requirementsForLevel field = go
      where
        covariant parameter =
          RequireCovariant parameter ("constructor field " <> field <> " stores a type code/witness")
        invariant parameter =
          RequireInvariant parameter ("constructor field " <> field <> " uses an opaque TypeLevel operation without selected Monotone evidence")
        go = \case
          LZero -> []
          LFinite _ -> []
          LOmega -> []
          LSucc level -> go level
          LAdd left right -> go left ++ go right
          LMax left right -> go left ++ go right
          LVar _ -> []
          LParam parameter -> [covariant parameter]
          LField _ _ -> []
          LProjection _ _ -> []
          LMeta _ -> []
          neutral@(LNeutral _) ->
            let candidates = monotoneCandidatesOfLevel neutral
                selected parameter operator = Map.member (family, parameter, operator) frozenMonotone
                candidateFor parameter = [operator | (candidate, operator) <- candidates, candidate == parameter]
             in [ if any (selected parameter) (candidateFor parameter)
                    then covariant parameter
                    else invariant parameter
                | parameter <- levelParams neutral
                ]

    requirementsFromCertifiedNominal field term = do
      let (headTerm, _) = spineOfTerm term
      case headTerm of
        CGlobal nested levels -> do
          externalSummary <- gets (Map.lookup nested . csGlobals) >>= pure . (>>= gdNominalSummary)
          let certifiedRoles =
                Map.lookup nested tentativeRoles
                  <|> (ncsRoles <$> (externalSummary >>= \summary ->
                        guard (verifyNominalCumulativitySummary summary && ncsFamilyIdentity summary == gKey nested)
                          >> pure summary))
          pure $ do
            roles <- certifiedRoles
            guard (length levels == length roles)
            pure . concat $
              [ case role of
                  Invariant -> [RequireInvariant parameter ("constructor field " <> field <> " uses invariant nominal family " <> gKey nested) | parameter <- levelParams level]
                  Covariant -> [RequireCovariant parameter ("constructor field " <> field <> " uses covariant nominal family " <> gKey nested) | parameter <- levelParams level]
                  Irrelevant -> []
              | (role, level) <- zip roles levels
              ]
        _ -> pure Nothing

    stripNominalWrappers = \case
      CUniverseLift _ _ _ inner -> stripNominalWrappers inner
      CSchemaLift _ _ _ _ _ _ _ _ inner -> stripNominalWrappers inner
      term -> term

-- | Elaborate a data family's declared result universe. The annotation is a
-- universe term such as @Type3@, not a type that must itself inhabit Type0.
-- Keeping the actual sort term is essential for level-indexed families.
dataResultSort :: Ctx -> Maybe Expr -> Span -> CheckM (Term, Level)
dataResultSort _ Nothing _ = pure (CSort LZero, LZero)
dataResultSort ctx (Just kindExpr) sp = do
  (kindTm, _) <- inferType ctx kindExpr
  kindV <- evalIn ctx kindTm
  forceM kindV >>= \case
    VSort rho -> pure (CSort rho, rho)
    other -> do
      actual <- quoteIn ctx other
      errAt sp "E_NOT_A_TYPE" (Just "kappa.type.mismatch")
        ("a data result classifier must be a universe Type ρ; found " <> renderTerm actual)
      pure (CSort LZero, LZero)

-- | Constructor-local binders must fit in the declared family universe.
-- Parametric Q0 universe binders are the sole no-size-obligation case; later
-- fields mentioning their witness are checked normally (§10.4.1).
elabConstructorTele :: Text -> Text -> Level -> Ctx -> [Binder] -> CheckM Telescope
elabConstructorTele _ _ _ _ [] = pure []
elabConstructorTele dataName ctorName rho ctx (b : rest) = do
  domE <- normalizeBinderDomain ctx b (fromMaybe (EUnit (bSpan b)) (binderTypeExpr b))
  (domTm, alpha, coerced) <-
    withGeneralizableBareTypeLevels $
      if bImplicit b
        then inferTypeBoolProp' ctx domE
        else (\(tm, lvl) -> (tm, lvl, False)) <$> inferType ctx domE
  domV <- evalIn ctx domTm
  let nm = maybe "_" nameText (bName b)
      ic = if bImplicit b then Impl else Expl
      ordinaryDefault = if coerced then Q0 else binderQ b
  (mode, q) <- resolveBinderModeQ ctx b domV ordinaryDefault
  formation <- selectFormationMode ctx mode domV
  let contribution = formationContribution formation alpha
  fits <-
    if contribution == LZero
      then pure True
      else solveConstructorLevelInequality ctx contribution rho
  unless fits $
    reportConstructorSize dataName ctorName rho ctx b nm ic q domE contribution
  mBound <- levelAssumptionFromExpr ctx (Just domTm) domE
  withBound <- extendLevelAssumption (bSpan b) ctx mBound
  let next = bindCtxMQ mode q nm False domV withBound
  later <- elabConstructorTele dataName ctorName rho next rest
  pure (TelescopeEntry ic mode formation q (isJust (bpBorrow (bPrefix b))) nm domTm mBound : later)

reportConstructorSize :: Text -> Text -> Level -> Ctx -> Binder -> Text -> Icit -> Q -> Expr -> Level -> CheckM ()
reportConstructorSize dataName ctorName rho ctx binder binderName ic q annotation alpha = do
  let constraint = renderLevel alpha <> " <= " <> renderLevel rho
  report $
    withPayload
      ( withPayloadField "dataDeclaration" dataName $
          withPayloadField "dataResultUniverse" (renderLevel rho) $
            withPayloadField "constructor" ctorName $
              withPayloadField "constructorLocalBinder" binderName $
                withPayloadField "binderExplicitness" (if ic == Impl then "implicit" else "explicit") $
                  withPayloadField "binderQuantity" (renderCoreQ q) $
                    withPayloadField "binderOriginKind" "source-written" $
                      withPayloadField "binderAnnotation" (renderExprSrc annotation) $
                        withPayloadField "binderAnnotationUniverse" (renderLevel alpha) $
                          withPayloadField "requiredUniverseConstraint" constraint $
                            withPayloadField "normalizedFailedConstraint" constraint $
                              withPayloadField "levelAssumptions" (renderLevelAssumptions (ctxLevelAssumptions ctx)) $
                                withPayloadField "localRepairAvailable" "raise-data-result-universe" $
                                  payloadKind "universe-constructor-size"
      ) $
      diag SevError StageElaborate "E_DATA_CONSTRUCTOR_FIELD_UNIVERSE"
        (Just "kappa.universe.constructor-size") (bSpan binder)
        ( "constructor binder '" <> binderName <> "' has classifier Type " <> renderLevel alpha
            <> ", which does not fit the declared data universe Type " <> renderLevel rho
            <> " (§10.4.1)"
        )

elabGadtConstructorType :: Text -> Text -> Level -> Ctx -> Expr -> CheckM (Term, Level)
elabGadtConstructorType dataName ctorName rho = go
  where
    go ctx = \case
      EArrow b rest -> do
        domE0 <- pure (fromMaybe (EUnit (bSpan b)) (binderTypeExpr b))
        (domE, recoveredBoundSyntax) <- normalizeBinderDomainWithRecovery ctx b domE0
        (domTm, domLvl, coerced) <-
          withGeneralizableBareTypeLevels $
            if bImplicit b
              then inferTypeBoolProp' ctx domE
              else (\(tm, lvl) -> (tm, lvl, False)) <$> inferType ctx domE
        domV <- evalIn ctx domTm
        let ic = if bImplicit b then Impl else Expl
            nm = maybe "_" nameText (bName b)
            ordinaryDefault = if coerced then Q0 else binderQ b
        (mode, q) <- resolveBinderModeQ ctx b domV ordinaryDefault
        formation <- selectFormationMode ctx mode domV
        let contribution = formationContribution formation domLvl
        fits <-
          if contribution == LZero
            then pure True
            else solveConstructorLevelInequality ctx contribution rho
        unless fits $
          reportConstructorSize dataName ctorName rho ctx b nm ic q domE contribution
        mBound <- levelAssumptionFromExpr ctx (Just domTm) domE
        withBound <- extendLevelAssumption (bSpan b) ctx mBound
        let ctx' = bindCtxMQ mode q nm (bImplicit b) domV withBound
        (restTm, restLvl) <- go ctx' rest
        let (restTm', restCeiling) = formationCeilingTerm ctx' restLvl restTm
            binderLevel = ctxLen ctx
        levelBinder <- isTypeLevelValue domV
        let escapes = levelBinder && binderLevel `elem` levelVars restCeiling
        when (escapes && not recoveredBoundSyntax) $
          reportUnboundedTelescope ctx' (bSpan b) "GADT constructor telescope" nm restCeiling
        let piTm = CPiBoundFormedM mode formation ic q (isJust (bpBorrow (bPrefix b))) nm mBound domTm restTm'
        annotatedPi <- annotateExplicitBorrowRegion ctx b piTm
        pure
          (annotatedPi, levelMax contribution (if escapes then LZero else restCeiling))
      EForall bs rest _ -> do
        goForall ctx bs rest
      ETraitArrow premise rest -> do
        (tm, alpha, coerced) <- inferTypeBoolProp' ctx premise
        v <- evalIn ctx tm
        let q = if coerced then Q0 else QW
        let formation = FormationOrdinary
            contribution = formationContribution formation alpha
        fits <-
          if contribution == LZero
            then pure True
            else solveConstructorLevelInequality ctx contribution rho
        unless fits $
          reportEvidenceSize ctx premise contribution
        mBound <- levelAssumptionFromExpr ctx (Just tm) premise
        withBound <- extendLevelAssumption (exprSpan premise) ctx mBound
        let ctx' = bindCtxMQ Ordinary q "_ev" True v withBound
        (restTm, restLvl) <- go ctx' rest
        let (restTm', restCeiling) = formationCeilingTerm ctx' restLvl restTm
        pure
          ( CPiBoundFormedM Ordinary formation Impl q False "_ev" mBound tm restTm'
          , levelMax contribution restCeiling
          )
      terminal -> inferType ctx terminal

    goForall ctx [] rest = go ctx rest
    goForall ctx (b : bs) rest = do
      (domTm, domLvl, coerced, mSource) <- case bType b of
        Just source -> do
          domE <- normalizeBinderDomain ctx b source
          (tm, lvl, wasCoerced) <-
            withGeneralizableBareTypeLevels $
              if bImplicit b
                then inferTypeBoolProp' ctx domE
                else (\(x, lvl) -> (x, lvl, False)) <$> inferType ctx domE
          pure (tm, lvl, wasCoerced, Just domE)
        Nothing -> do
          level <- freshGeneralizableLevelMeta
          pure (CSort level, levelSucc level, False, Nothing)
      domV <- evalIn ctx domTm
      let nm = maybe "_" nameText (bName b)
          -- GADT-local @forall@ obeys the same implicit quantity-0 contract.
          ic = Impl
          ordinaryDefault = Q0
      (mode, q) <- resolveBinderModeQ ctx b domV ordinaryDefault
      formation <- selectFormationMode ctx mode domV
      let contribution = formationContribution formation domLvl
      fits <-
        if contribution == LZero
          then pure True
          else solveConstructorLevelInequality ctx contribution rho
      unless fits $
        reportConstructorSize dataName ctorName rho ctx b nm ic q
          (fromMaybe (EUnit (bSpan b)) mSource) contribution
      mBound <- case mSource of
        Just source -> levelAssumptionFromExpr ctx (Just domTm) source
        _ -> pure Nothing
      withBound <- extendLevelAssumption (bSpan b) ctx mBound
      let ctx' = bindCtxMQ mode q nm True domV withBound
      (restTm, restLvl) <- goForall ctx' bs rest
      let (restTm', restCeiling) = formationCeilingTerm ctx' restLvl restTm
          binderLevel = ctxLen ctx
      levelBinder <- isTypeLevelValue domV
      let escapes = levelBinder && binderLevel `elem` levelVars restCeiling
      when escapes $
        reportUnboundedTelescope ctx' (bSpan b) "GADT forall telescope" nm restCeiling
      pure
        ( CPiBoundFormedM mode formation ic q False nm mBound domTm restTm'
        , levelMax contribution (if escapes then LZero else restCeiling)
        )

    reportEvidenceSize ctx premise alpha =
      report $
        withPayload
          ( withPayloadField "dataDeclaration" dataName $
              withPayloadField "dataResultUniverse" (renderLevel rho) $
                withPayloadField "constructor" ctorName $
                  withPayloadField "constructorLocalBinder" "__evidence" $
                    withPayloadField "binderExplicitness" "implicit" $
                      withPayloadField "binderQuantity" "ω" $
                        withPayloadField "binderOriginKind" "trait-evidence" $
                          withPayloadField "binderAnnotation" (renderExprSrc premise) $
                            withPayloadField "binderAnnotationUniverse" (renderLevel alpha) $
                              withPayloadField "requiredUniverseConstraint" (renderLevel alpha <> " <= " <> renderLevel rho) $
                                withPayloadField "normalizedFailedConstraint" (renderLevel alpha <> " <= " <> renderLevel rho) $
                                  withPayloadField "levelAssumptions" (renderLevelAssumptions (ctxLevelAssumptions ctx)) $
                                    withPayloadField "localRepairAvailable" "raise-data-result-universe" $
                                      payloadKind "universe-constructor-size"
          ) $
          diag SevError StageElaborate "E_DATA_CONSTRUCTOR_FIELD_UNIVERSE"
            (Just "kappa.universe.constructor-size") (exprSpan premise)
            "constructor evidence exceeds the declared data universe (§10.4.1)"

-- ── §10.4 strict positivity ──────────────────────────────────────────
--
-- "Every 'data' declaration MUST satisfy strict positivity." After the
-- header pass has elaborated every constructor type, this pass treats
-- all 'data' declarations of the module as one mutually recursive group
-- (declaration order within a module is immaterial, §10.1), computes a
-- parameter-positivity signature for every group member by fixed-point
-- iteration (§10.4), and then rejects the group if, under the converged
-- signatures, any group type still occurs non-strictly-positively in any
-- constructor argument type.

-- | The constructor argument (field) types of a data type, as core
-- terms, each closed over the data parameters as the OUTERMOST de Bruijn
-- binders. 'tdParamCount' leading 'CPi' binders of the elaborated
-- constructor type are the (implicit) parameters; every remaining 'CPi'
-- domain up to the result head is a field type. The returned 'pfDepth'
-- is the number of binders in scope at the field domain (parameters plus
-- the earlier fields of the same constructor), so that parameter @j@
-- (0-based, first parameter) sits at de Bruijn index @pfDepth - 1 - j@.
data PosField = PosField
  { pfDepth :: !Int
  , pfType :: !Term
  }

-- | Per-data-type positivity input gathered from the elaborated state.
data PosData = PosData
  { pdName :: !GName
  , pdParamCount :: !Int
  , pdFields :: ![PosField] -- ^ across all constructors of this type
  , pdSpan :: !Span
  }

positivityPass :: [Decl] -> CheckM ()
positivityPass decls = do
  st <- get
  let dataDecls = [(dd, sp) | DData _ dd sp <- decls]
  group <- catMaybes <$> mapM (gatherPosData st) dataDecls
  unless (null group) $ do
    let groupNames = Set.fromList (map pdName group)
        dependencySccs =
          stronglyConnComp
            [ (d, pdName d, Set.toList (Set.intersection groupNames (Set.unions (map (globalsOfTerm . pfType) (pdFields d)))))
            | d <- group
            ]
        recursiveGroupOf =
          Map.fromList
            [ (pdName d, names)
            | scc <- dependencySccs
            , let members = case scc of
                    AcyclicSCC d -> [d]
                    CyclicSCC ds -> ds
                  names = Set.fromList (map pdName members)
            , d <- members
            ]
        -- prior (non-group) signatures: accepted data types and the
        -- strictly-positive built-in/imported carriers
        priorSig = csPositivity st
        -- fixed-point over the group for the parameter-positivity
        -- signatures (§10.4). The recompute operator is monotone in the
        -- "more positive" direction (a parameter known positive lets a
        -- recursive index recurse strictly-positively instead of
        -- demanding the parameter be absent), so the signature we want is
        -- its GREATEST fixed point: start every parameter positive and
        -- iterate downward until stable. (A least fixed point from
        -- all-non-positive degenerates — e.g. it would mark 'a' in
        -- 'data Tree a = ... Branch (Tree a) a (Tree a)' as non-positive,
        -- wrongly. The rejection judgement below is computed afterwards
        -- against the converged signatures, per §10.4.)
        sig0 = Map.fromList [(pdName d, replicate (pdParamCount d) True) | d <- group]
        converged = fixpoint groupNames priorSig group sig0
        fullSig = Map.union converged priorSig
    -- record the converged group signatures for later declarations
    modify' $ \s -> s {csPositivity = Map.union converged (csPositivity s)}
    -- reject any group member with a non-strictly-positive occurrence
    forM_ group $ \d ->
      forM_ (pdFields d) $ \fld ->
        let recursiveNames = Map.findWithDefault (Set.singleton (pdName d)) (pdName d) recursiveGroupOf
         in unless (spPositive recursiveNames fullSig (pfType fld)) $
          errOncePerSpan (pdSpan d) "E_DATA_NOT_STRICTLY_POSITIVE" (Just "kappa.termination.failure")
            ( "data type '" <> gnameText (pdName d)
                <> "' is not strictly positive: it occurs in a negative or non-admissible position"
                <> " in a constructor argument type (Spec §10.4)"
            )

-- | Collect the field types of one data declaration from the elaborated
-- 'CtorInfo' types. Returns 'Nothing' for a type with no recorded data
-- info (should not happen for a 'DData' that elaborated).
gatherPosData :: CheckState -> (DataDecl, Span) -> CheckM (Maybe PosData)
gatherPosData st (DataDecl n _ _ _, sp) = do
  g <- ownName n
  case Map.lookup g (csDatas st) of
    Nothing -> pure Nothing
    Just di -> do
      let pc = diParamCount di
          ctorTys = [ciType ci | cg <- diCtors di, Just ci <- [Map.lookup cg (csCtors st)]]
          rawFlds = concatMap (posCtorFieldTypes pc) ctorTys
      flds <- forM rawFlds $ \fld ->
        PosField (pfDepth fld) <$> normalizeTermAt (pfDepth fld) (pfType fld)
      pure (Just (PosData g pc flds sp))

-- | Peel 'pc' leading parameter binders, then collect each remaining
-- 'CPi' domain (a constructor field type) together with the binder depth
-- in scope at that domain.
posCtorFieldTypes :: Int -> Term -> [PosField]
posCtorFieldTypes pc = peelParams pc
  where
    peelParams 0 t = peelFields pc t
    peelParams k (CPi _ _ _ _ _ b) = peelParams (k - 1) b
    peelParams _ _ = [] -- malformed; nothing to check
    peelFields depth = \case
      CPi _ _ _ _ a b -> PosField depth a : peelFields (depth + 1) b
      _ -> [] -- the result head 'T params' carries no fields

-- | Fixed-point iteration of the group's parameter-positivity signatures
-- (§10.4): recompute every member's signature from the current
-- signatures until nothing changes.
fixpoint :: Set GName -> Map GName [Bool] -> [PosData] -> Map GName [Bool] -> Map GName [Bool]
fixpoint groupNames priorSig group = go
  where
    go sig =
      let sig' = Map.fromList [(pdName d, recomputeSig groupNames (Map.union sig priorSig) d) | d <- group]
       in if sig' == sig then sig else go sig'

-- | Recompute one data type's parameter-positivity signature: parameter
-- @j@ is positive iff every occurrence of the corresponding de Bruijn
-- variable in every field type is in a strictly positive position
-- (§10.4).
recomputeSig :: Set GName -> Map GName [Bool] -> PosData -> [Bool]
recomputeSig groupNames sig d =
  [ all (\fld -> varPositive groupNames sig (pfDepth fld - 1 - j) (pfType fld)) (pdFields d)
  | j <- [0 .. pdParamCount d - 1]
  ]

-- | Is the parameter-positivity signature of an applied head 'F' known
-- and is 'F' admissible in a strictly positive position? Returns the
-- per-argument positivity flags when admissible (§10.4 admissibility).
admissibleSig :: Set GName -> Map GName [Bool] -> Term -> Maybe [Bool]
admissibleSig groupNames sig = \case
  CGlob g
    | g `Set.member` groupNames -> Map.lookup g sig -- a group member (its evolving signature)
    | otherwise -> Map.lookup g sig -- a prior data type / built-in carrier with a recorded signature
  _ -> Nothing

-- | Split a term into its head and argument spine.
posSpine :: Term -> (Term, [Term])
posSpine = go []
  where
    go acc (CApp _ f a) = go (a : acc) f
    go acc t = (t, acc)

-- | §10.4 strict positivity of a constructor field type with respect to
-- a /target/ supplied as the predicate @hits@ (does this exact subterm
-- mention the target as its head?) plus @occurs@ (does the target occur
-- anywhere in this subterm?). The walk implements: the argument type
-- itself; @X -> U@ / @(x : X) -> U@ with the target absent from @X@ and
-- strictly positive in @U@; and an admissible application @F A1 .. An@
-- in which the target occurs strictly positively only in the @Ai@ whose
-- parameter is marked positive (and not at all in the others).
posWalk
  :: Set GName
  -> Map GName [Bool]
  -> (Int -> Term -> Bool) -- ^ @occurs shift t@: does the target occur in @t@ (shift = extra binders since the top)?
  -> (Int -> Term -> Bool) -- ^ @isBareTarget shift t@: is @t@ exactly a bare occurrence of the target (the "argument type itself")?
  -> Int -- ^ binders entered since the top (de Bruijn shift)
  -> Term
  -> Bool
posWalk groupNames sig occurs isBareTarget = go
  where
    go shift (CUniverseLift _ _ _ inner) = go shift inner
    go shift (CSchemaLift _ _ _ _ _ _ _ _ inner) = go shift inner
    go shift t
      -- the argument type itself (possibly with family arguments):
      -- a bare occurrence of the target is a strictly positive position
      | isBareTarget shift t = True
      -- the target does not occur at all: trivially strictly positive
      | not (occurs shift t) = True
      | otherwise = case posSpine t of
          -- function/dependent-function type 'X -> U' / '(x : X) -> U':
          -- target absent from the domain and strictly positive in 'U'
          (CPi _ _ _ _ a b, []) ->
            not (occurs shift a) && go (shift + 1) b
          -- application 'F A1 .. An'
          (hd, args@(_ : _)) ->
            case admissibleSig groupNames sig hd of
              Just flags ->
                -- 'F' is admissible (a prior/built-in carrier, or the
                -- defined type applied to family arguments, which is
                -- itself a strictly positive position): the target may
                -- occur strictly positively only in those 'Ai' whose
                -- parameter is marked positive in F's signature, and not
                -- at all in the others
                and
                  [ if positiveFlag
                      then go shift arg
                      else not (occurs shift arg)
                  | (arg, positiveFlag) <- zip args (flags ++ repeat False)
                  ]
              Nothing ->
                -- 'F' is not admissible (a bare variable, an opaque type
                -- without a positivity signature, …): the target must
                -- not occur anywhere in the application
                False
          -- covariant suspension wrappers: the target stays strictly
          -- positive under Thunk/Memo/Force in type position
          (CThunkE e _, []) -> go shift e
          (CLazyE e _, []) -> go shift e
          (CForceE e _, []) -> go shift e
          -- record / variant type formers: every component is covariant
          (CRecordT fs, []) -> all (go shift . snd) fs
          (CVariantT ms, []) -> all (go shift) ms
          -- any other shape carrying an occurrence is not a strictly
          -- positive position
          _ -> False

-- | §10.4 strict positivity of a field type with respect to the group
-- types (the reject condition target). A group type may occur, but only
-- in strictly positive positions.
spPositive :: Set GName -> Map GName [Bool] -> Term -> Bool
spPositive groupNames sig =
  posWalk groupNames sig (\_shift t -> mentionsGroup groupNames t) bareGroup 0
  where
    bareGroup _shift = \case
      CGlob g -> g `Set.member` groupNames
      _ -> False

-- | §10.4 strict positivity of a field type with respect to one data
-- parameter (the de Bruijn variable @v@ at the field-domain depth). Used
-- to compute the parameter-positivity signature.
varPositive :: Set GName -> Map GName [Bool] -> Int -> Term -> Bool
varPositive groupNames sig v0 =
  posWalk groupNames sig (\shift t -> mentionsVar (v0 + shift) t) bareVar 0
  where
    bareVar shift = \case
      CVar i -> i == v0 + shift
      _ -> False

-- | Does any group type constructor occur anywhere in a term?
mentionsGroup :: Set GName -> Term -> Bool
mentionsGroup groupNames = go
  where
    go = \case
      CGlob g -> g `Set.member` groupNames
      CUniverseLift _ _ _ inner -> go inner
      CSchemaLift _ _ _ _ _ _ sourceArguments targetArguments inner ->
        any go sourceArguments || any go targetArguments || go inner
      CArithmeticProof certificate ->
        any go (foldMapArithmeticCertificate (: []) certificate)
      CVar _ -> False
      CLam _ _ _ b -> go b
      CPi _ _ _ _ a b -> go a || go b
      CApp _ f a -> go f || go a
      CSort _ -> False
      CLevel _ -> False
      CLit _ -> False
      CCtor _ _ as -> any go as
      CMatch s _ _ alts -> go s || any (\(CaseAlt _ gd b) -> maybe False go gd || go b) alts
      CRecordT fs -> any (go . snd) fs
      CRecordV fs -> any (go . snd) fs
      CProj e _ -> go e
      CProjAt e _ _ -> go e
      CVariantT ms -> any go ms
      CInject _ e -> go e
      CLet _ _ a b c -> go a || go b || go c
      CLetRec _ _ a b c -> go a || go b || go c
      CLetPolyM _ _ _ _ a b c -> go a || go b || go c
      CLetRecPolyM _ _ _ _ a b c -> go a || go b || go c
      CLetRecGroupM _ definitions body ->
        any (\definition -> go (clrdType definition) || go (clrdRhs definition)) definitions || go body
      CMeta _ -> False
      CDo _ _ -> False
      CSealE _ e -> go e
      CSigT _ e -> go e
      CThunkE e suspensionType -> go e || maybe False go suspensionType
      CLazyE e suspensionType -> go e || maybe False go suspensionType
      CForceE e resultType -> go e || maybe False go resultType
      CIf a b c -> go a || go b || go c
      CQuote _ slots -> any go slots
      CLocal _ _ -> False

-- | Does the de Bruijn variable @v@ occur anywhere in a term (accounting
-- for binders that shift it)?
mentionsVar :: Int -> Term -> Bool
mentionsVar = go
  where
    go v = \case
      CVar i -> i == v
      CUniverseLift _ _ _ inner -> go v inner
      CSchemaLift _ _ _ _ _ _ sourceArguments targetArguments inner ->
        any (go v) sourceArguments || any (go v) targetArguments || go v inner
      CArithmeticProof certificate ->
        any (go v) (foldMapArithmeticCertificate (: []) certificate)
      CGlob _ -> False
      CLam _ _ _ b -> go (v + 1) b
      CPi _ _ _ _ a b -> go v a || go (v + 1) b
      CApp _ f a -> go v f || go v a
      CSort _ -> False
      CLevel _ -> False
      CLit _ -> False
      CCtor _ _ as -> any (go v) as
      CMatch s _ _ alts -> go v s || any (\(CaseAlt p gd b) -> let n = patBindersC p in maybe False (go (v + n)) gd || go (v + n) b) alts
      CRecordT fs -> any (go v . snd) fs
      CRecordV fs -> any (go v . snd) fs
      CProj e _ -> go v e
      CProjAt e _ _ -> go v e
      CVariantT ms -> any (go v) ms
      CInject _ e -> go v e
      CLet _ _ a b c -> go v a || go v b || go (v + 1) c
      CLetRec _ _ a b c -> go v a || go (v + 1) b || go (v + 1) c
      CLetPolyM _ _ _ _ a b c -> go v a || go v b || go (v + 1) c
      CLetRecPolyM _ _ _ _ a b c -> go v a || go (v + 1) b || go (v + 1) c
      CLetRecGroupM _ definitions body ->
        let count = length definitions
         in any (\definition -> go v (clrdType definition) || go (v + count) (clrdRhs definition)) definitions
              || go (v + count) body
      CMeta _ -> False
      CDo _ _ -> False
      CSealE _ e -> go v e
      CSigT _ e -> go v e
      CThunkE e suspensionType -> go v e || maybe False (go v) suspensionType
      CLazyE e suspensionType -> go v e || maybe False (go v) suspensionType
      CForceE e resultType -> go v e || maybe False (go v) resultType
      CIf a b c -> go v a || go v b || go v c
      CQuote _ slots -> any (go v) slots
      CLocal i _ -> i == v

-- §10.1.1 declaration-time validation of constructor field defaults:
-- each default must elaborate, with the preceding fields in scope, at
-- the field's declared type (later fields and the field itself are not
-- in scope).
checkFieldDefaults :: Ctx -> Telescope -> [Binder] -> CheckM ()
checkFieldDefaults parameterCtx fieldsTele binders = do
  let explicitBs = [b | b <- binders, not (bImplicit b)]
  _ <-
    foldM
      ( \(ctx, tele) b -> case tele of
          (TelescopeEntry ic mode _formation q borrowed nm domTm mBound : rest) -> do
            domV <- evalIn ctx domTm
            forM_ (bDefault b) $ \d -> do
              (dTm, dTy) <- infer ctx d
              eq <- unify ctx dTy domV
              unless eq $ do
                domR <- quoteIn ctx domV
                dTyR <- quoteIn ctx dTy
                errAt (exprSpan d) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
                  ( "constructor field default for '" <> nm
                      <> "' has type " <> renderTerm dTyR
                      <> ", but the field's type is " <> renderTerm domR <> " (Spec §10.1.1)"
                  )
              _ <- pure dTm
              pure ()
            ctxWithBound <- extendLevelAssumption (bSpan b) ctx mBound
            pure (bindCtxMQB mode q nm (ic == Impl) borrowed domV ctxWithBound, rest)
          [] -> pure (ctx, tele)
      )
      (parameterCtx, fieldsTele)
      explicitBs
  pure ()

-- bind each telescope entry at its elaborated domain type (the domain
-- term is closed over the preceding entries)
telePi :: TelescopeEntry -> Term -> Term
telePi entry =
  CPiBoundFormedM
    (teMode entry)
    (teFormation entry)
    (teIcit entry)
    (teQ entry)
    (teBorrow entry)
    (teName entry)
    (teLevelAssumption entry)
    (teDomain entry)

teleCtx :: Telescope -> CheckM Ctx
teleCtx = extendTeleCtx emptyCtx

extendTeleCtx :: Ctx -> Telescope -> CheckM Ctx
extendTeleCtx = foldM step
  where
    step c (TelescopeEntry ic mode _formation q borrowed nm domTm mBound) = do
      domV <- evalIn c domTm
      c' <- extendLevelAssumption noSpan c mBound
      pure (bindCtxMQB mode q nm (ic == Impl) borrowed domV c')

elabTele' :: Telescope -> [Binder] -> CheckM Telescope
elabTele' tele bs = do
  ctx <- teleCtx tele
  elabTele ctx bs

-- elaborate binders to a telescope (left to right).
elabTele :: Ctx -> [Binder] -> CheckM Telescope
elabTele _ [] = pure []
elabTele ctx (b : rest) = do
  (domTm, coerced, mSource, inferredDomain) <- case binderTypeExpr b of
    Just t -> do
      domE <- normalizeBinderDomain ctx b t
      (tm, _, wasCoerced) <- withGeneralizableBareTypeLevels $
        if bImplicit b then inferTypeBoolProp' ctx domE else (\(x, l) -> (x, l, False)) <$> inferType ctx domE
      pure (tm, wasCoerced, Just domE, False)
    -- an unannotated param's kind is inferred from its uses (a fresh
    -- meta; unconstrained params still default to Type, §11.3.3)
    Nothing -> (,,,True) <$> freshMeta <*> pure False <*> pure Nothing
  domV <- evalIn ctx domTm
  let nm = maybe "_" nameText (bName b)
      ic = if bImplicit b then Impl else Expl
      ordinaryDefault = if coerced then Q0 else headerBinderQ b
      explicitMode = bpObservation (bPrefix b)
      explicitQuantity = bpQuantity (bPrefix b)
  -- §11.3.3: while an implicitly universalized declaration parameter's
  -- domain meta is still being constrained by the declaration body, use the
  -- least-permissive admissible provisional contract.  Treating an unsolved
  -- domain as non-kind here permanently stamped generated type parameters as
  -- ordinary, so every later use such as @Box A@ or @Clone A@ looked like an
  -- illegal parametric-to-ordinary application at the KCore checkpoint.
  -- Explicit source prefixes remain authoritative.  Finalized Core validates
  -- that a provisional parametric binder did in fact resolve to paramKind.
  (mode, q) <-
    if inferredDomain && isNothing explicitMode
      then pure (Parametric, maybe Q0 (qOf . Just) explicitQuantity)
      else resolveBinderModeQ ctx b domV ordinaryDefault
  mBound <- case mSource of
    Just source -> levelAssumptionFromExpr ctx (Just domTm) source
    _ -> pure Nothing
  ctxWithBound <- extendLevelAssumption (bSpan b) ctx mBound
  let ctx' = bindCtxMQB mode q nm (bImplicit b) (isJust (bpBorrow (bPrefix b))) domV ctxWithBound
  restT <- elabTele ctx' rest
  -- Later header components may solve an unannotated domain meta (notably a
  -- row parameter inferred as RecRow). Finalize the generated binder from
  -- that solved domain instead of persisting the provisional parametric
  -- contract. Source-written mode/quantity prefixes remain authoritative.
  (finalMode, finalQ) <-
    if inferredDomain
      then do
        domain <- forceM domV
        paramKind <- isParametricKind (ctxLen ctx) domain
        let inferredMode = if paramKind then Parametric else Ordinary
            inferredQ =
              case explicitQuantity of
                Just quantity -> qOf (Just quantity)
                Nothing -> if inferredMode == Parametric then Q0 else ordinaryDefault
        pure (fromMaybe inferredMode explicitMode, inferredQ)
      else pure (mode, q)
  formation <- selectFormationMode ctx finalMode domV
  pure (TelescopeEntry ic finalMode formation finalQ (isJust (bpBorrow (bPrefix b))) nm domTm mBound : restT)

-- | Finalize a generated telescope after its use sites have constrained the
-- provisional domain metas. This is shared by GADT locals and instance-head
-- variables so higher-kinded and row variables retain their inferred domains
-- and receive the least-permissive legal observation contract.
finalizeGeneratedTelescope :: Ctx -> Telescope -> CheckM Telescope
finalizeGeneratedTelescope _ [] = pure []
finalizeGeneratedTelescope ctx (entry : rest) = do
  domain0 <- evalIn ctx (teDomain entry) >>= forceM
  domain <- case domain0 of
    VFlex meta [] -> do
      level <- freshLevelMeta
      solveMeta meta (VSort level)
      markGeneralizableLevelTerm (CSort level)
      pure (VSort level)
    value -> pure value
  domainTm <- quoteIn ctx domain
  markGeneralizableLevelTerm domainTm
  paramKind <- isParametricKind (ctxLen ctx) domain
  let mode = if paramKind then Parametric else Ordinary
      q = if paramKind then Q0 else QW
      formation = if paramKind && mode == Parametric then FormationParametric else FormationOrdinary
      entry' = entry {teMode = mode, teFormation = formation, teQ = q, teDomain = domainTm}
      ctx' = bindCtxMQB mode q (teName entry) (teIcit entry == Impl) (teBorrow entry) domain ctx
  rest' <- finalizeGeneratedTelescope ctx' rest
  pure (entry' : rest')

-- | Finalize source declaration parameters after the whole declaration header
-- has constrained their provisional kinds. Unannotated parameters acquire the
-- least kind-compatible observation contract and own every level appearing in
-- that inferred kind. Source-written annotations, modes, and quantities remain
-- authoritative; this pass only zonks their domains.
finalizeSourceDeclarationTelescope :: Ctx -> [(Binder, TelescopeEntry)] -> CheckM Telescope
finalizeSourceDeclarationTelescope _ [] = pure []
finalizeSourceDeclarationTelescope ctx ((binder, entry) : rest) = do
  domain0 <- evalIn ctx (teDomain entry) >>= forceM
  domain <- case domain0 of
    VFlex meta [] -> do
      level <- freshLevelMeta
      solveMeta meta (VSort level)
      pure (VSort level)
    value -> pure value
  domainTm <- quoteIn ctx domain
  when (isNothing (bType binder)) $
    markGeneralizableLevelTerm domainTm
  (mode, quantity) <-
    if isNothing (bType binder)
      then do
        paramKind <- isParametricKind (ctxLen ctx) domain
        let prefix = bPrefix binder
            inferredMode = if paramKind then Parametric else Ordinary
            selectedMode = fromMaybe inferredMode (bpObservation prefix)
            selectedQuantity =
              maybe
                (if selectedMode == Parametric then Q0 else headerBinderQ binder)
                (qOf . Just)
                (bpQuantity prefix)
        pure (selectedMode, selectedQuantity)
      else pure (teMode entry, teQ entry)
  formation <- selectFormationMode ctx mode domain
  let entry' = entry {teMode = mode, teFormation = formation, teQ = quantity, teDomain = domainTm}
      ctx' =
        bindCtxMQB
          mode
          quantity
          (teName entry)
          (teIcit entry == Impl)
          (teBorrow entry)
          domain
          ctx
  later <- finalizeSourceDeclarationTelescope ctx' rest
  pure (entry' : later)

-- | §11.3.3 declaration-header default: a genuinely unannotated parameter is
-- an erased parametric type variable. An explicit annotation or quantity keeps
-- the ordinary binder rules and is never rewritten after elaboration.
headerBinderQ :: Binder -> Q
headerBinderQ b
  | isNothing (bType b)
  , isNothing (bpQuantity (bPrefix b)) = Q0
  | otherwise = binderQ b

elabUnderParams :: Telescope -> Expr -> CheckM (Term, Value)
elabUnderParams tele e = do
  ctx <- teleCtx tele
  (tm, _) <- inferType ctx e
  -- Data-family parameters are supplied implicitly to constructors even when
  -- the family header itself uses explicit application syntax. They are
  -- compile-time constructor indices, not constructor payload fields.
  let closed = foldr (\entry acc -> telePi (entry {teIcit = Impl, teQ = Q0}) acc) tm tele
  pure (closed, VSort LZero)

-- | Elaborate a GADT signature under its family parameters and any genuinely
-- free signature variables. The latter receive stable erased constructor-local
-- binders; their kinds are inferred from the whole signature and default to
-- @Type0@ only when still unconstrained at this declaration boundary.
elabGadtUnderParams :: GName -> Text -> Text -> Level -> Telescope -> Ctx -> Expr -> CheckM Term
elabGadtUnderParams dataG dataName ctorName dataLevel paramTele paramCtx sig = do
  let bound = boundNamesIn sig
      candidates =
        nub
          [ nameText n
          | n <- freeVarOccurrences sig
          , nameText n `notElem` bound
          ]
  fvs <-
    filterM
      ( \name -> do
          global <- lookupGlobalName name
          schemaLevel <- gets (Map.lookup name . csActiveUniverseSchema)
          pure
            ( isNothing global
                && isNothing schemaLevel
                && isNothing (lookupCtx name paramCtx)
                && isNothing (sortName name)
            )
      )
      candidates
  (fvTele0, sigCtx) <- foldM addFree ([], paramCtx) fvs
  (sigTm0, _) <- elabGadtConstructorType dataName ctorName dataLevel sigCtx sig
  fvTele <- defaultKinds paramCtx fvTele0
  sigTm <- zonkTermM (ctxLen sigCtx) sigTm0
  unless (gadtResultHead sigTm == Just dataG) $
    errAt (exprSpan sig) "E_TYPE_EQUALITY_MISMATCH" (Just "kappa.type.mismatch")
      ( "constructor '" <> ctorName <> "' must return the data family '"
          <> dataName <> "' (§10.1, §10.4.1)"
      )
  let familyTele = [entry {teIcit = Impl, teQ = Q0} | entry <- paramTele]
      allTele = familyTele ++ fvTele
  pure (foldr telePi sigTm allTele)
  where
    gadtResultHead = \case
      CPi _ _ _ _ _ cod -> gadtResultHead cod
      term -> case spineOfTerm term of
        (CGlob g, _) -> Just g
        _ -> Nothing

    addFree (tele, ctx) name = do
      kindTm <- freshMeta
      kindV <- evalIn ctx kindTm
      let entry = TelescopeEntry Impl Parametric FormationParametric Q0 False name kindTm Nothing
      pure (tele ++ [entry], bindCtxMQProvisional Parametric Q0 name False kindV ctx)

    defaultKinds _ [] = pure []
    defaultKinds ctx (TelescopeEntry ic _mode _formation _q borrowed name kindTm bound : rest) = do
      kindV <- evalIn ctx kindTm >>= forceM
      kindTm' <- case kindV of
        VFlex meta [] -> do
          level <- freshLevelMeta
          solveMeta meta (VSort level)
          markGeneralizableLevelTerm (CSort level)
          pure (CSort level)
        value -> quoteIn ctx value
      kindV' <- evalIn ctx kindTm'
      paramKind <- isParametricKind (ctxLen ctx) kindV'
      let mode = if paramKind then Parametric else Ordinary
          q = if paramKind then Q0 else QW
      later <-
        defaultKinds
          (bindCtxMQB mode q name (ic == Impl) borrowed kindV' ctx)
          rest
      let formation = if paramKind && mode == Parametric then FormationParametric else FormationOrdinary
      pure (TelescopeEntry ic mode formation q borrowed name kindTm' bound : later)

-- | Prove that a trait member's eventual result is runtime-erased in the
-- member's checked telescope. This is a representation query over semantic
-- evidence: descend through the complete Pi telescope, then ask the ordinary
-- h-level solver for @IsProp result@. In particular, while elaborating
-- @Eq a@, the current trait's authenticated @IsSet a@ supertrait proves that
-- the equality results of @eqSound@ and @eqComplete@ are erased. A failed
-- probe is transactional and conservatively leaves the member runtime
-- relevant.
traitMemberResultRuntimeErased :: Ctx -> Span -> Value -> CheckM Bool
traitMemberResultRuntimeErased ctx site memberType = do
  before <- get
  erased <- go ctx memberType
  put before
  pure erased
  where
    go activeCtx ty =
      forceM ty >>= \case
        VPiBoundM mode icit quantity borrowed name assumption domain closure -> do
          withAssumption <- extendLevelAssumption site activeCtx assumption
          let level = ctxLen activeCtx
              nextCtx =
                bindCtxMQB
                  mode
                  quantity
                  name
                  (icit == Impl)
                  borrowed
                  domain
                  withAssumption
          result <- clApp closure (VRigid level [])
          go nextCtx result
        result -> do
          resultF <- forceM result
          evaluation <- ec_
          case canonicalEqualityPayload evaluation resultF of
            Just (carrier, _, _) ->
              isJust <$> isSetEvidence activeCtx site carrier
            Nothing -> do
              goal <- globalValueM prelIsProp [(Expl, resultF)]
              isJust <$> isPropClosure activeCtx site goal

-- | Complete the runtime-erasure classification of current-module trait
-- members after all instance heads have been registered and header universe
-- interfaces have been principalized. This is a monotone refinement: fields
-- already classified quantity-zero by declaration syntax or header-local
-- evidence stay zero, and an ordinary field is promoted only when its fully
-- checked global projection type is now semantically proven RuntimeErased.
-- Imported trait layouts are never rewritten.
finalizeTraitMemberRepresentations :: CheckM ()
finalizeTraitMemberRepresentations = do
  state <- get
  let currentModule = csModule state
      localTraits =
        [ (traitName, traitInfo)
        | (traitName@(GName owner _), traitInfo) <- Map.toList (csTraits state)
        , owner == currentModule
        ]
  refinements <- forM localTraits $ \(traitName, traitInfo) -> do
    quantities <- foldM (refineMember state traitName) (tiMemberQs traitInfo) (tiMembers traitInfo)
    pure (traitName, traitInfo {tiMemberQs = quantities})
  modify' $ \current ->
    current
      { csTraits =
          foldl'
            (\traits (traitName, traitInfo) -> Map.insert traitName traitInfo traits)
            (csTraits current)
            refinements
      }
  where
    refineMember state traitName quantities memberName
      | Map.lookup memberName quantities == Just Q0 = pure quantities
      | otherwise =
          case Map.lookup (memberGlobal traitName memberName) (csGlobals state) of
            Nothing -> pure quantities
            Just definition -> do
              erased <- traitMemberResultRuntimeErased emptyCtx noSpan (gdType definition)
              pure
                ( if erased
                    then Map.insert memberName Q0 quantities
                    else quantities
                )

headerTrait :: TraitDecl -> Span -> CheckM ()
headerTrait (TraitDecl supers n params members) sp = do
  g <- ownName n
  noteDefinition g sp
  rawParamTele <- elabTele emptyCtx params
  let provisionalParamTele = zipWith provisionalTraitParam params rawParamTele
  pctx <- teleCtx provisionalParamTele
  -- supertrait premises (§14.1.4): their evidence is carried as
  -- dictionary fields, projected by the compiler as ordinary evidence
  -- projections (§14.2.1); a parenthesized premise list (C1 a, C2 a)
  -- is several premises
  let superList =
        concatMap
          ( \item ->
              case stiType item of
                ETuple expressions _ ->
                  [(stiDerived item, expression) | expression <- expressions]
                expression -> [(stiDerived item, expression)]
          )
          supers
  supEntries <- forM (zip [(0 :: Int) ..] superList) $ \(i, (derived, s)) -> do
    (sTm, _) <- inferType pctx s
    pure (superFieldName i, sTm, derived)
  let supPairs = [(field, term) | (field, term, _) <- supEntries]
      derivedSuperFields =
        Set.fromList [field | (field, _, True) <- supEntries]
  -- member declarations in source order; earlier members are in scope
  -- for later member signatures as §13.2.1 siblings of the evidence
  -- record ("Inside the trait body, Item refers to the associated
  -- static member of the current trait evidence", §14.2.1), and free
  -- lowercase identifiers are implicitly universalized (§14.2/§11.3.3)
  let paramNames = map teName provisionalParamTele
      memberNames =
        nub $
          [nameText mn | Just mn <- map Kappa.Syntax.traitMemberName members]
      derivedMemberNames =
        Set.fromList [nameText mn | TraitDerived mn _ _ <- members]
  provisionalMemberFields <- forM memberNames $ \member ->
    RecordField member Ordinary FormationOrdinary QW Nothing <$> freshMetaV pctx
  let derivedMemberDeclarations =
        [ (nameText member, memberType, memberSpan)
        | TraitDerived member memberType memberSpan <- members
        ]
      derivedMemberGraph =
        [ ( (member, memberSpan)
          , member
          , nub
              [ dependency
              | dependency <- freeLower memberType
              , dependency `Set.member` derivedMemberNames
              ]
          )
        | (member, memberType, memberSpan) <- derivedMemberDeclarations
        ]
      derivedMemberCycles =
        [ cycleMembers
        | CyclicSCC cycleMembers <- stronglyConnComp derivedMemberGraph
        ]
  forM_ derivedMemberCycles $ \cycleMembers ->
    case cycleMembers of
      [] -> pure ()
      ((_, cycleSpan) : _) ->
        report $
          withPayload
            ( withPayloadField "cycle"
                (T.intercalate " -> " (map fst cycleMembers)) $
                payloadKind "derive-cycle"
            ) $
            diag SevError StageElaborate "E_DERIVE_CYCLE" (Just "kappa.derive") cycleSpan
              "the synthesized-member dependency graph contains an unproductive cycle (§14.3.4A)"
  let
      -- §14.1.4: a member signature may name a SUPERTRAIT operation (e.g.
      -- a member of a 'C => D' subtrait mentions an operation from the
      -- supertrait 'C'). Such an operation's implicit dictionary argument is the
      -- current trait evidence's supertrait field. During member-type
      -- elaboration we stash the supertrait premises in 'csTraitSupers'; the
      -- implicit solver ('superThisCandidate') then resolves that dictionary
      -- to a 'this.__superN' projection — a closed term that, after the
      -- 'substThisTm' in the member-projection construction, reads correctly
      -- both as a sibling field of the dictionary record type and as a
      -- projection from the member projection's '__d' binder. Because the
      -- dictionary is a closed projection (not a context binder), the
      -- operation's OTHER implicits — notably its carrier — keep their
      -- ordinary inference, so the member type is sound. Inert when the
      -- member names no supertrait operation.
      elabMemberTy acc mtyE = do
        fvs <-
          filterM
            (\v ->
              if v `elem` (paramNames ++ memberNames)
                then pure False
                else do
                  global <- lookupGlobalName v
                  schemaLevel <- gets (Map.lookup v . csActiveUniverseSchema)
                  pure (isNothing global && isNothing schemaLevel)
            )
            (nub (freeLower mtyE))
        kvs <- mapM (const (freshMetaV pctx)) fvs
        let mctx = foldl (\c (v, k) -> bindCtxMQProvisional Parametric Q0 v False k c) pctx (zip fvs kvs)
        superVals <- forM supPairs $ \(fld, sTm) -> (,) fld <$> evalIn pctx sTm
        oldSupers <- gets csTraitSupers
        modify' $ \st -> st {csTraitSupers = superVals}
        let availableMembers =
              acc
                ++ [ field
                   | field <- provisionalMemberFields
                   , rfName field `notElem` map rfName acc
                   ]
        (mtyTm0raw, _) <-
          withNamedCallableInoutSignature mtyE $
            withThis (Just (ThisTraitSibs (sortOn rfName availableMembers))) (inferType mctx mtyE)
        -- Resolve any POSTPONED supertrait-operation dictionaries now, while
        -- 'csTraitSupers' is still in scope and the operations' explicit args
        -- have pinned their carriers, so each commits to its 'this.__superN'
        -- projection (see 'flushPendingWith'/'superThisCandidate').
        unless (null supPairs) flushPending
        -- Zonk from the member context's depth: a dictionary implicit solved
        -- to a trait-parameter rigid (the supertrait-operation case) must be
        -- requoted at 'ctxLen mctx', not 0, or its de Bruijn index lands one
        -- binder short for every enclosing forall — yielding a member type
        -- whose carrier points at a forall value binder instead of the trait
        -- parameter (§14.1.4).
        mtyTm0 <- zonkTermM (ctxLen mctx) mtyTm0raw
        mtyV0 <- evalIn mctx mtyTm0
        runtimeErased <- traitMemberResultRuntimeErased mctx sp mtyV0
        modify' $ \st -> st {csTraitSupers = oldSupers}
        universalBinders <- forM (zip fvs kvs) $ \(v, kv) -> do
          kv' <- forceM kv
          kind <- case kv' of
            VFlex m [] -> do
              level <- freshLevelMeta
              solveMeta m (VSort level)
              markGeneralizableLevelTerm (CSort level)
              pure (VSort level)
            _ -> pure kv'
          kindTm <- quoteIn pctx kind
          paramKind <- isParametricKind (ctxLen pctx) kind
          pure (v, if paramKind then Parametric else Ordinary, if paramKind then FormationParametric else FormationOrdinary, if paramKind then Q0 else QW, kindTm)
        let mtyTm = foldr (\(v, mode, formation, q, kT) b -> CPiFormedM mode formation Impl q False v kT b) mtyTm0 universalBinders
        mtyV <- evalIn pctx mtyTm
        pure (mtyTm, mtyV, runtimeErased)
      memberName (mn, _, _, _, _, _, _, _, _) = mn
      memberTerm (mn, tm, _, mode, formation, q, _, _, _) = RecordField mn mode formation q Nothing tm
      memberQ mn = case T.uncons mn of
        Just (c, _) | c >= 'A' && c <= 'Z' -> Q0
        _ -> QW
      goMembers _acc done [] = pure (reverse done)
      goMembers acc done (m : rest) = case m of
        TraitSig mn mtyE _ -> do
          let memberSchema = nameUniverseSchema mn
              memberOwner = memberGlobal g (nameText mn)
          (mtyTm, mtyV, runtimeErased) <- case memberSchema of
            Nothing -> elabMemberTy acc mtyE
            Just _ ->
              withActiveUniverseDefinition memberOwner $
                withNestedUniverseSchemaParameters memberSchema $
                  elabMemberTy acc mtyE
          let inouts = inoutParamsFromBinders (signatureBinders mtyE)
          associatedStatic <-
            isAssociatedStaticMemberType (ctxLen pctx) mtyV
          let
              q =
                if runtimeErased || associatedStatic
                  then Q0
                  else memberQ (nameText mn)
          mode <- (\isKind -> if isKind then Parametric else Ordinary) <$> isParametricKind (ctxLen pctx) mtyV
          formation <- selectFormationMode pctx mode mtyV
          let field = RecordField (nameText mn) mode formation q Nothing mtyV
          goMembers
            (acc ++ [field])
            ( ( nameText mn
              , mtyTm
              , inouts
              , mode
              , formation
              , q
              , memberSchema
              , runtimeErased
              , associatedStatic
              )
                : done
            )
            rest
        TraitDerived mn mtyE memberSpan ->
          goMembers acc done (TraitSig mn mtyE memberSpan : rest)
        TraitDefault (LetDef (Just mn) _ _ _ _ _ mty _ _) _
          -- a default for an already-declared member supplies its
          -- definition only; the declaration owns the dictionary
          -- field (§14.2: declaration vs definition forms)
          | nameText mn `elem` map memberName done -> goMembers acc done rest
          | otherwise -> do
              let memberSchema = nameUniverseSchema mn
                  memberOwner = memberGlobal g (nameText mn)
                  elaborateMember = case mty of
                    Just t -> elabMemberTy acc t
                    Nothing -> do
                      mTm <- freshMeta
                      mV <- evalIn pctx mTm
                      pure (mTm, mV, False)
              (mtyTm, mtyV, runtimeErased) <- case memberSchema of
                Nothing -> elaborateMember
                Just _ ->
                  withActiveUniverseDefinition memberOwner $
                    withNestedUniverseSchemaParameters memberSchema elaborateMember
              let inouts = maybe [] (inoutParamsFromBinders . signatureBinders) mty
              associatedStatic <-
                isAssociatedStaticMemberType (ctxLen pctx) mtyV
              let
                  q =
                    if runtimeErased || associatedStatic
                      then Q0
                      else memberQ (nameText mn)
              mode <- (\isKind -> if isKind then Parametric else Ordinary) <$> isParametricKind (ctxLen pctx) mtyV
              formation <- selectFormationMode pctx mode mtyV
              let field = RecordField (nameText mn) mode formation q Nothing mtyV
              goMembers
                (acc ++ [field])
                ( ( nameText mn
                  , mtyTm
                  , inouts
                  , mode
                  , formation
                  , q
                  , memberSchema
                  , runtimeErased
                  , associatedStatic
                  )
                    : done
                )
                rest
        TraitDefault {} -> goMembers acc done rest
        TraitEvidenceUniqueness {} -> goMembers acc done rest
  ms <- goMembers [] [] members
  paramTele <- finalizeSourceDeclarationTelescope emptyCtx (zip params provisionalParamTele)
  -- The member/supertrait uses above have now constrained every generated
  -- parameter domain. Build the public trait constructor from that finalized
  -- telescope so its mode and kind are one coherent interface contract.
  let tyTm = foldr telePi (CSort LZero) paramTele
  let memberTerms = map memberTerm ms
      dictBody =
        CRecordTQ . sortOn rfName $
          [RecordField fn Ordinary FormationOrdinary QW Nothing tm | (fn, tm) <- supPairs] ++ memberTerms
      dictTm = foldr (\entry acc -> CLamM (teMode entry) (teIcit entry) (teQ entry) (teName entry) acc) dictBody paramTele
  traitUniverses <- provisionalDeclarationUniverses [tyTm]
  tyV <- evalIn emptyCtx tyTm
  dictV <- evalIn emptyCtx dictTm
  -- the trait constructor is abstract (§14.1.1): not conversion-reducible
  addGlobal g
    ( globalDefWithObservationMode
        Ordinary
        (GlobalDef tyV (Just dictV) False)
    )
  modify' $ \st ->
    st
      { csNominalSummaryRequests =
          Map.insert g
            ( PendingTraitNominalSummary
                (nameUniverseSchema n)
                (length paramTele)
                (map snd supPairs ++ [memberType | (_, memberType, _, _, _, _, _, _, _) <- ms])
                sp
            )
            (csNominalSummaryRequests st)
      , csDirtyNominalSummaries = Set.insert g (csDirtyNominalSummaries st)
      }
  defaultOwner <- gets csModule
  defaultEmbedded <- gets csEmbeddedLoad
  let defaults =
        Map.fromList
          [ (nameText dn, (defaultOwner, defaultEmbedded, ld))
          | TraitDefault ld@(LetDef (Just dn) _ _ _ _ _ _ _ _) _ <- members
          ]
      supTms = [(fn, foldr (\entry acc -> CLamM (teMode entry) (teIcit entry) (teQ entry) (teName entry) acc) sTm paramTele) | (fn, sTm) <- supPairs]
  modify' $ \st ->
    invalidateSemanticCaches
      ( st
          { csTraits =
              Map.insert
                g
                ( TraitInfo
                    (length paramTele)
                    (map memberName ms)
                    (Map.fromList [(mn, mode) | (mn, _, _, mode, _, _, _, _, _) <- ms])
                    ( Set.fromList
                        [ mn
                        | (mn, _, _, _, _, _, _, _, associatedStatic) <- ms
                        , associatedStatic
                        ]
                    )
                    (Map.fromList [(mn, q) | (mn, _, _, _, _, q, _, _, _) <- ms])
                    defaults
                    supTms
                    derivedMemberNames
                    derivedSuperFields
                    SealedCoherent
                )
                (csTraits st)
          }
      )
  -- member projection globals: m : forall params. (@d : Tr params) -> τ
  -- (occurrences of sibling members in τ become projections from the
  -- dict binder)
  forM_ ms $ \(mn, mtyTm, inouts, modeMember, _formationMember, _qMember, memberSchema, _runtimeErased, _associatedStatic) ->
    withNestedUniverseSchemaParameters memberSchema $ do
      let dictTy =
            foldl
              (\f (entry, i) -> CApp (teIcit entry) f (CVar i))
              (CGlobI g traitUniverses)
              (zip paramTele (reverse [0 .. length paramTele - 1]))
          projTy =
            foldr
              (\entry acc -> telePi (entry {teIcit = Impl, teBorrow = False}) acc)
              ( CPiFormedM Ordinary FormationOrdinary Impl QW False "__d" dictTy
                  (substThisTm (CVar 0) (weakenTermUnderBinderAt (length paramTele) mtyTm))
              )
              paramTele
          projTm =
            foldr
              (\entry acc -> CLamM (teMode entry) Impl (teQ entry) (teName entry) acc)
              (CLamM Ordinary Impl QW "__d" (CProjM modeMember (CVar 0) mn))
              paramTele
      projTyV <- evalIn emptyCtx projTy
      projV <- evalIn emptyCtx projTm
      mg <- ownName (Name mn sp)
      let qualifiedMember = memberGlobal g mn
      -- Install the bare member name only when it does not already denote a
      -- wired-in declaration. Public MonadRef operations are trait-member
      -- projections; concrete IO ref primitives live under the internal
      -- __io* names so ref-facet recognition is evidence-backed.
      bareExists <- gets (Map.member mg . csGlobals)
      when bareExists $ do
        previous <- gets (Map.lookup mg . csBareTraitMembers)
        forM_ previous $ \(previousTrait, previousMember) ->
          modify' $ \state ->
            state
              { csScopeAmbig =
                  Map.insertWith
                    (\new old -> sort (nub (new ++ old)))
                    mn
                    [memberGlobal previousTrait previousMember, qualifiedMember]
                    (csScopeAmbig state)
              }
      unless bareExists $ do
        inheritGeneralizableLevelRoles g mg projTy
        addGlobal mg (globalDefWithObservationMode modeMember (GlobalDef projTyV (Just projV) True))
        recordCoreBody mg projTm
        recordInoutParams mg inouts
        modify' $ \state ->
          state
            { csBareTraitMembers =
                Map.insert mg (g, mn) (csBareTraitMembers state)
            , csTraitMemberOwners =
                Map.insert mg g (csTraitMemberOwners state)
            }
      -- Always install the qualified projection global. Capture the KCore body for
      -- the native backend (§14.2.1 member projection): a CLam chain projecting the
      -- member field from the dict.
      inheritGeneralizableLevelRoles g qualifiedMember projTy
      addGlobal qualifiedMember (globalDefWithObservationMode modeMember (GlobalDef projTyV (Just projV) True))
      recordCoreBody qualifiedMember projTm
      recordInoutParams qualifiedMember inouts
      modify' $ \state ->
        state
          { csTraitMemberOwners =
              Map.insert qualifiedMember g (csTraitMemberOwners state)
          }

  let uniquenessClauses =
        [ (proof, clauseSpan)
        | TraitEvidenceUniqueness proof clauseSpan <- members
        ]
      independentlySubsingletonFields =
        all
          (\(_, _, _, _, _, _, _, runtimeErased, associatedStatic) -> runtimeErased || associatedStatic)
          ms
  constructionMode <-
    validateTraitEvidenceUniqueness
      g
      traitUniverses
      pctx
      paramTele
      supPairs
      independentlySubsingletonFields
      uniquenessClauses
  modify' $ \state ->
    state
      { csTraits =
          Map.adjust
            (\info -> info {tiEvidenceConstructionMode = constructionMode})
            g
            (csTraits state)
      }

  where
    provisionalTraitParam binder entry
      | isNothing (bType binder) =
          let prefix = bPrefix binder
              mode = fromMaybe Parametric (bpObservation prefix)
              quantity =
                maybe
                  (if mode == Parametric then Q0 else headerBinderQ binder)
                  (qOf . Just)
                  (bpQuantity prefix)
           in entry {teMode = mode, teQ = quantity}
      | otherwise = entry

-- | Validate the declaration-owned authority for fresh trait-evidence
-- construction (§14.1.1A).  Conventional certificates use a compact checked
-- structural proof: each field must already be independently subsingleton and
-- each supertrait must itself carry an independent certificate.  The embedded
-- standard foundation has additional identity-authenticated providers for
-- law-constrained fields such as @Eq.(==)@ and @IsContr.center@.  An explicit
-- proof is checked against the generated extensional theorem while the exact
-- trait is on 'csEvidenceUniquenessStack', disabling the forbidden
-- @IsTrait G -> IsSubsingleton G@ cycle.
validateTraitEvidenceUniqueness
  :: GName
  -> [Level]
  -> Ctx
  -> [TelescopeEntry]
  -> [(Text, Term)]
  -> Bool
  -> [(Expr, Span)]
  -> CheckM EvidenceConstructionMode
validateTraitEvidenceUniqueness trait traitUniverses parameterCtx parameterTele supers fieldsIndependent clauses =
  case clauses of
    [] -> pure SealedCoherent
    [(EDerive Nothing _, clauseSpan)] -> do
      supersIndependent <- and <$> mapM superIsIndependent supers
      foundation <- authenticatedFoundationProvider
      if (fieldsIndependent && supersIndependent) || foundation
        then pure IndependentlyUnique
        else do
          errAt clauseSpan "E_EVIDENCE_UNIQUENESS_INVALID"
            (Just "kappa.evidence.uniqueness")
            "the conventional evidence-uniqueness proof cannot establish independent equality of every evidence field (§14.1.1A)"
          pure SealedCoherent
    [(proofExpression, clauseSpan)] -> do
      expected <- evidenceUniquenessTheorem
      before <- gets (length . csDiags)
      modify' $ \state ->
        state
          { csEvidenceUniquenessStack =
              trait : csEvidenceUniquenessStack state
          }
      checkedProof <- check parameterCtx proofExpression expected
      -- Implicit evidence in the certificate body is often postponed until
      -- its endpoints are fixed.  Resolve it while the self-coherence guard
      -- is still active; popping the guard first would let the forbidden
      -- @IsTrait G@ edge enter through declaration closeout.
      flushPending
      modify' $ \state ->
        state
          { csEvidenceUniquenessStack =
              dropOne trait (csEvidenceUniquenessStack state)
          }
      diagnostics <- gets csDiags
      let added = take (length diagnostics - before) diagnostics
          dependencies = globalsOfTerm checkedProof
          coherenceCycle = prelTraitSubsingletonWitness `Set.member` dependencies
          cycleReported =
            coherenceCycle
              || any ((== "E_EVIDENCE_UNIQUENESS_CYCLE") . dCode) added
      when (coherenceCycle && not (any ((== "E_EVIDENCE_UNIQUENESS_CYCLE") . dCode) added)) $
        errAt clauseSpan "E_EVIDENCE_UNIQUENESS_CYCLE"
          (Just "kappa.evidence.uniqueness")
          "an evidence-uniqueness certificate depends on compiler-generated coherence for the same trait (§14.1.1A)"
      if null added && not coherenceCycle
        then pure IndependentlyUnique
        else do
          unless cycleReported $
            errAt clauseSpan "E_EVIDENCE_UNIQUENESS_INVALID"
              (Just "kappa.evidence.uniqueness")
              "the evidence-uniqueness expression does not prove the generated independent extensionality theorem (§14.1.1A)"
          pure SealedCoherent
    (_ : (_, duplicateSpan) : _) -> do
      errAt duplicateSpan "E_EVIDENCE_UNIQUENESS_INVALID"
        (Just "kappa.evidence.uniqueness")
        "a trait may declare at most one evidence-uniqueness certificate (§14.1.1A)"
      pure SealedCoherent
  where
    dropOne _ [] = []
    dropOne target (candidate : rest)
      | target == candidate = rest
      | otherwise = candidate : dropOne target rest

    superIsIndependent (_, closedSuper) = do
      superFunction <- evalIn parameterCtx closedSuper
      forceM superFunction >>= \case
        VGlobI superTrait _ _ -> do
          state <- get
          pure $
            maybe
              False
              ((== IndependentlyUnique) . tiEvidenceConstructionMode)
              (Map.lookup superTrait (csTraits state))
        _ -> pure False

    authenticatedFoundationProvider = do
      embedded <- gets csEmbeddedLoad
      pure
        ( embedded
            && trait
              `Set.member` Set.fromList
                [ gPrel "IsEmpty"
                , gPrel "IsContr"
                , gPrel "IsSubsingleton"
                , gPrel "IsProp"
                , gPrel "IsSet"
                , gPrel "IsGroupoid"
                , gPrel "Eq"
                ]
        )

    evidenceUniquenessTheorem = do
      let parameterIndices = reverse [0 .. length parameterTele - 1]
          evidenceTypeTerm =
            foldl
              (\function (entry, index) ->
                CApp (teIcit entry) function (CVar index))
              (CGlobI trait traitUniverses)
              (zip parameterTele parameterIndices)
      evidenceType <- evalIn parameterCtx evidenceTypeTerm
      let leftLevel = ctxLen parameterCtx
          leftCtx =
            bindCtxMQ Ordinary QW "left" False evidenceType parameterCtx
          rightLevel = ctxLen leftCtx
          rightCtx =
            bindCtxMQ Ordinary QW "right" False evidenceType leftCtx
      equality <-
        globalValueM
          prelEqType
          [ (Impl, evidenceType)
          , (Expl, VRigid leftLevel [])
          , (Expl, VRigid rightLevel [])
          ]
      equalityTerm <- quoteIn rightCtx equality
      let theoremTerm =
            CPiFormedM
              Ordinary
              FormationOrdinary
              Expl
              QW
              False
              "left"
              evidenceTypeTerm
              ( CPiFormedM
                  Ordinary
                  FormationOrdinary
                  Expl
                  QW
                  False
                  "right"
                  (shiftTerm 1 0 evidenceTypeTerm)
                  equalityTerm
              )
      evalIn parameterCtx theoremTerm

installTraitNominalSummary :: GName -> Maybe UniverseSchema -> NominalSignatureClosure -> Span -> CheckM ()
installTraitNominalSummary family sourceSchema closure site = do
  definitions <- gets csGlobals
  case Map.lookup family definitions of
    Nothing -> pure ()
    Just definition -> do
      let parameterCount = dutParameterCount (gdUniverses definition)
          requirements = nominalClosureRequirements closure
          inferred = inferUniverseRoles parameterCount requirements
          written = maybe [] usRoles sourceSchema ++ repeat Nothing
          effective =
            zipWith
              (\annotation inferredRole ->
                case annotation of
                  Just writtenRole | rolePermitsAnnotation writtenRole inferredRole -> writtenRole
                  _ -> inferredRole
              )
              written
              inferred
          explicitFlags = map isJust (take parameterCount written)
          summary =
            makeNominalCumulativitySummary (gKey family) effective explicitFlags closure Nothing
      forM_ (zip4 [0 :: Int ..] (take parameterCount written) inferred effective) $
        \(index, annotation, inferredRole, effectiveRole) ->
          case annotation of
            Just writtenRole | not (rolePermitsAnnotation writtenRole inferredRole) ->
              report $
                withPayload
                  ( withPayloadField "nominalDeclaration" (gKey family) $
                      withPayloadField "nominalDeclarationIdentity" (gKey family) $
                      withPayloadField "signatureBlock" (gKey family) $
                        withPayloadField "parameterIndex" (T.pack (show index)) $
                          withPayloadField "universeParameterIndex" (T.pack (show index)) $
                          withPayloadField "explicitRole" (varianceText writtenRole) $
                            withPayloadField "inferredRole" (varianceText inferredRole) $
                              withPayloadField "effectiveRole" (varianceText effectiveRole) $
                                withPayloadField "roleCheckerVersion" "1" $
                                  withPayloadField "declarationKind" "trait" $
                                    withPayloadField "nearestAcceptedRole" (varianceText inferredRole) $
                                      payloadKind "universe-variance"
                  ) $
                    diag SevError StageElaborate "E_UNIVERSE_VARIANCE_TOO_PERMISSIVE"
                      (Just "kappa.universe.variance") site
                      ( "universe role " <> varianceText writtenRole <> " for trait parameter "
                          <> T.pack (show index) <> " is more permissive than inferred role "
                          <> varianceText inferredRole <> " (§11.1.2.3A.2)"
                      )
            _ -> pure ()
      if verifyNominalCumulativitySummary summary
        then modify' $ \st -> st {csGlobals = Map.adjust (globalDefWithNominalSummary summary) family (csGlobals st)}
        else
          errAt site "E_KCORE_SCHEMA_CERTIFICATE_INVALID"
            (Just "kappa.kcore.schema-certificate-invalid")
            "the generated trait-evidence nominal certificate failed independent replay"
  where
    varianceText = \case
      Invariant -> "invariant"
      Covariant -> "covariant"
      Irrelevant -> "irrelevant"

-- | The dictionary field carrying the i-th supertrait premise's
-- evidence (§14.1.4/§14.3.3).
superFieldName :: Int -> Text
superFieldName i = "__super" <> T.pack (show i)

-- | Does a Pi/Lam closure body reference its own bound variable
-- (de Bruijn index 0, relative to the body)? Used to detect
-- non-dependent function arrows: when the codomain does not mention the
-- argument, elaborating an application slot need not evaluate the
-- argument value and unify it into the result type (the fresh
-- placeholder meta never appears in the codomain), which collapses the
-- per-slot cost of a deep application/operator chain from O(size) to
-- O(1) — restoring linear scaling for the (overwhelmingly common)
-- non-dependent case while leaving dependent elaboration unchanged.
--
-- Conservative: returns 'True' for the few constructs whose binder
-- structure is not traversed here ('CDo', 'CQuote'), so a body that
-- might reference index 0 is never mis-reported as independent.
coreUsesVar0 :: Term -> Bool
coreUsesVar0 = go 0
  where
    -- @d@ counts binders crossed; the body's index 0 appears as @CVar d@.
    go d = \case
      CVar i -> i == d
      CUniverseLift _ _ _ inner -> go d inner
      CSchemaLift _ _ _ _ _ _ sourceArguments targetArguments inner ->
        any (go d) sourceArguments || any (go d) targetArguments || go d inner
      CArithmeticProof certificate ->
        any (go d) (foldMapArithmeticCertificate (: []) certificate)
      CGlob _ -> False
      CLam _ _ _ b -> go (d + 1) b
      CPi _ _ _ _ a b -> go d a || go (d + 1) b
      CApp _ f a -> go d f || go d a
      CSort _ -> False
      CLevel _ -> False
      CLit _ -> False
      CCtor _ _ as -> any (go d) as
      CMatch s _ _ alts ->
        go d s || any (\(CaseAlt p gd b) -> let d' = d + patBindersC p in maybe False (go d') gd || go d' b) alts
      CRecordT fs -> any (go d . snd) fs
      CRecordV fs -> any (go d . snd) fs
      CProj e _ -> go d e
      CProjAt e _ _ -> go d e
      CVariantT ms -> any (go d) ms
      CInject _ e -> go d e
      CLet _ _ a b c -> go d a || go d b || go (d + 1) c
      CLetRec _ _ a b c -> go d a || go (d + 1) b || go (d + 1) c
      CLetPolyM _ _ _ _ a b c -> go d a || go d b || go (d + 1) c
      CLetRecPolyM _ _ _ _ a b c -> go d a || go (d + 1) b || go (d + 1) c
      CLetRecGroupM _ definitions body ->
        let count = length definitions
         in any (\definition -> go d (clrdType definition) || go (d + count) (clrdRhs definition)) definitions
              || go (d + count) body
      CMeta _ -> False
      CDo _ _ -> True
      CSealE _ e -> go d e
      CSigT _ e -> go d e
      CThunkE e suspensionType -> go d e || maybe False (go d) suspensionType
      CLazyE e suspensionType -> go d e || maybe False (go d) suspensionType
      CForceE e resultType -> go d e || maybe False (go d) resultType
      CIf a b c -> go d a || go d b || go d c
      CQuote _ _ -> True
      CLocal i _ -> i == d

headerExpect :: Set GName -> ExpectForm -> Span -> CheckM ()
headerExpect preexisting form sp = case form of
  ExpectTerm n tyE -> do
    g <- ownName n
    st0 <- get
    let alreadyDef = case Map.lookup g (csGlobals st0) of
          Just gd -> Set.member g preexisting && isJust (gdValue gd)
          Nothing -> False
        definedInCompanion =
          alreadyDef
            && maybe False ((/= spanFile sp) . spanFile)
                 (Map.lookup g (csDeclSites st0))
    -- Elaborate the declared signature up front: it is needed both to
    -- register the abstract global (name resolution) and to check a
    -- backend-intrinsic satisfier against it up to definitional equality.
    (tyTm, _) <- withNamedCallableInoutSignature tyE (inferType emptyCtx tyE)
    tyV <- evalIn emptyCtx tyTm
    unless alreadyDef $ addGlobal g (GlobalDef tyV Nothing False)
    recordSignatureInoutParams g tyE
    -- Portable foundation constants are authenticated by resolved identity
    -- and an independently seeded Core schema.  They are neither ordinary
    -- source companions nor spelling-based backend intrinsics.
    byFoundation <- foundationProviderSatisfies g tyV sp
    -- §34.5/§9.4: a matching backend intrinsic of the selected profile
    -- satisfies this expectation when its signature matches.
    byIntrinsic <- backendIntrinsicSatisfies g tyV sp
    let count = if definedInCompanion || byFoundation || byIntrinsic then 1 else 0
    modify' $ \st -> st {csExpects = Map.insert g (sp, count) (csExpects st)}
  ExpectType n params _ -> abstractType n params
  ExpectData n params _ -> do
    abstractType n params
    g <- ownName n
    modify' $ \st -> st {csDatas = Map.insertWith (\_ old -> old) g (DataInfo [] (length params) LZero) (csDatas st)}
  ExpectTrait n params _ -> abstractType n params
  where
    abstractType n params = do
      g <- ownName n
      fresh <- registerExpect g
      when fresh $ do
        tyV <- aliasKind params
        addGlobal g (GlobalDef tyV Nothing False)
    -- Record the §9.4 expectation. An existing ordinary declaration is a
    -- satisfier only when it came from another selected source fragment;
    -- §9.4 explicitly excludes a definition in the expect's own source file.
    -- Returns True only when the expect must introduce the declaration into
    -- the global table itself.
    registerExpect g = do
      st <- get
      let exists =
            Set.member g preexisting
              && ( Map.member g (csGlobals st)
                     || Map.member g (csDatas st)
                     || Map.member g (csTraits st)
                 )
          satisfied =
            exists
              && maybe False ((/= spanFile sp) . spanFile)
                   (Map.lookup g (csDeclSites st))
          count = if satisfied then 1 else 0
      put st {csExpects = Map.insert g (sp, count) (csExpects st)}
      pure (not exists)

-- | Check one mandatory portable-foundation provider.  A provider claim with
-- the right identity but the wrong ABI is a precise signature error and does
-- not also degrade into an unsatisfied-expectation cascade.
foundationProviderSatisfies :: GName -> Value -> Span -> CheckM Bool
foundationProviderSatisfies g tyV sp = do
  providers <- gets csFoundationProviders
  case Map.lookup g providers of
    Nothing -> pure False
    Just expectedTm -> do
      expectedV <- evalIn emptyCtx expectedTm
      matches <- withUniverseDiagnosticSpan sp (unify emptyCtx tyV expectedV)
      if matches
        then pure True
        else do
          ec <- ec_
          let declared = renderTerm (quote ec 0 tyV)
              required = renderTerm (quote ec 0 expectedV)
          errAt sp "E_FOUNDATION_PROVIDER_SIGNATURE_MISMATCH"
            (Just "kappa.internal.compiler")
            ( "portable foundation provider '" <> gnameText g
                <> "' does not match its required Core signature; declared: "
                <> declared <> "; required: " <> required
            )
          pure True

-- | §34.5/§9.4: decide whether a backend intrinsic of the selected profile
-- satisfies the expectation @g@ with declared type @tyV@. An intrinsic is
-- keyed by its Kappa spelling ('csBackendIntrinsics', empty unless a native
-- profile is selected); its expected signature MUST match @tyV@ up to
-- definitional equality. A name match with a type mismatch is reported as
-- 'E_BACKEND_INTRINSIC_SIGNATURE_MISMATCH' and still counts as "claimed by
-- the backend" so the precise mismatch is the sole diagnostic (not also a
-- spurious unsatisfied-expectation error).
backendIntrinsicSatisfies :: GName -> Value -> Span -> CheckM Bool
backendIntrinsicSatisfies g tyV sp = do
  st <- get
  case Map.lookup (gnameText g) (csBackendIntrinsics st) of
    Nothing -> pure False
    Just expectedTm -> do
      expectedV <- evalIn emptyCtx expectedTm
      ec <- ec_
      if convertible ec 0 tyV expectedV
        then pure True
        else do
          errAt sp "E_BACKEND_INTRINSIC_SIGNATURE_MISMATCH" (Just "kappa-hs.backend.intrinsic")
            ( "the declared type of '" <> gnameText g
                <> "' does not match the signature of the backend intrinsic that satisfies it (Spec §9.4, §34.5)"
            )
          pure True

-- | Note a top-level definition of @g@: it satisfies a pending same-file
-- signature (§9.1) and, when it belongs to another selected fragment, counts
-- toward §9.4 expect satisfaction (a second satisfier is ambiguous).
noteDefinition :: GName -> Span -> CheckM ()
noteDefinition g sp = do
  recordDeclSite g sp
  st <- get
  put st {csSigPending = Map.delete g (csSigPending st)}
  case Map.lookup g (csExpects st) of
    Nothing -> pure ()
    Just (esp, cnt)
      -- An expect requires an implementation outside its own source file.
      -- Same-module companion fragments retain distinct 'spanFile' identities
      -- after composition, so this check is independent of fragment order.
      | spanFile esp == spanFile sp -> pure ()
      | otherwise -> do
          modify' $ \st' -> st' {csExpects = Map.insert g (esp, cnt + 1) (csExpects st')}
          when (cnt + 1 == 2) $
            errAt sp "E_EXPECT_AMBIGUOUS" (Just "kappa-hs.expect.ambiguous")
              ("more than one definition satisfies expected declaration '" <> gnameText g <> "' (Spec §9.4)")

-- | §9.4: expects with no satisfier at the end of the compilation unit.
expectUnsatisfiedDiags :: CheckState -> Diagnostics
expectUnsatisfiedDiags st =
  [ diag SevError StageElaborate "E_EXPECT_UNSATISFIED" (Just "kappa-hs.expect.unsatisfied") sp
      ("expected declaration '" <> gnameText g
         <> "' is not satisfied by any definition, backend intrinsic, or imported artifact in this compilation unit (Spec §9.4)")
  | (g, (sp, n)) <- Map.toList (csExpects st)
  , n == 0
  ]

-- | Body pass: elaborates definitions, plus any signatures the header
-- pass deferred because they mention signature-less module lets.
bodyPassIn :: Set Text -> Decl -> CheckM ()
bodyPassIn siglessLets d = case d of
  DSig _ _ tyE _
    | any (`Set.member` siglessLets) (sigHeadNames tyE) -> headerPassIn Set.empty d
  _ -> bodyPass d

-- names a signature's type may resolve through (heads of applications,
-- dotted bases, binder domains)
sigHeadNames :: Expr -> [Text]
sigHeadNames = go
  where
    go = \case
      EVar (Name t _) -> [t]
      EApp f args -> go f ++ concatMap goArg args
      EDot e _ -> go e
      EQDot e _ -> go e
      EArrow b e -> maybe [] go (bType b) ++ go e
      EForall bs e _ -> concatMap (maybe [] go . bType) bs ++ go e
      EExists bs e _ -> concatMap (maybe [] go . bType) bs ++ go e
      ETuple es _ -> concatMap go es
      EOptionSugar e _ -> go e
      ETraitArrow a b -> go a ++ go b
      EOpChain els -> concat [go x | ChainOperand x <- els]
      _ -> []
    goArg = \case
      ArgExplicit e -> go e
      ArgImplicit e -> go e
      _ -> []

bodyPass :: Decl -> CheckM ()
bodyPass d =
  case d of
    -- Signatures are retained until their matching definition completes.
    -- Re-entering an empty body-pass scope here would diagnose them before
    -- that definition can constrain their metas.
    DSig {} -> action
    -- The wrapped declaration owns the semantic hole scope; 'elabUnsafeAssert'
    -- delegates to 'bodyPass' for that declaration after auditing the wrapper.
    DUnsafeAssert {} -> action
    _ -> do
      owner <- traverse ownName (declarationUniverseName d)
      pending <- case owner of
        Nothing -> pure Map.empty
        Just global ->
          gets (Map.findWithDefault Map.empty global . csSignatureHoles)
      withNamedHoleScope pending (close owner) action
  where
    action = withDeclarationUniverseSchema d (bodyPass' d)
    close owner = do
      finalizeNamedHoles
      forM_ owner $ \global ->
        modify' $ \st ->
          st
            { csSignatureHoles =
                Map.delete global (csSignatureHoles st)
            }

    bodyPass' = \case
      DLet mods ld sp -> elabLetDecl mods ld sp
      DInstance inst sp -> elabInstance inst sp
      DPattern mods ld sp -> elabActivePatternDecl mods ld sp
      DProjection mods n bs ty body sp -> elabProjectionDecl mods n bs ty body sp
      DDerive _ sp -> do
        generated <- gets (Map.findWithDefault [] sp . csDerivedDecls)
        valid <- validateDerivedDeclarations sp generated
        when valid $
          forM_ generated $ \case
            DInstance inst generatedSpan -> elabInstance inst generatedSpan
            _ -> pure ()
      DTopSplice _ sp ->
        unsupportedAt sp "top-level splices are not supported by this implementation"
      DUnsafeAssert akind inner sp -> elabUnsafeAssert akind inner sp
      _ -> pure ()

-- | Commit declaration-scoped named-hole obligations after every inference
-- mechanism for that declaration has run. A solved shared meta is ordinary
-- inferred Core and produces no diagnostic; an unsolved one reports once at
-- its first source occurrence. This ordering is required by §15.8.6:
-- arithmetic proof search may uniquely determine a named Nat hole while
-- checking a later erased proof argument.
finalizeNamedHoles :: CheckM ()
finalizeNamedHoles = do
  holes <- gets csHoles
  state <- get
  forM_ (Map.toAscList holes) $ \(name, hole) ->
    unless (null (unsolvedMetasOf state (nhTerm hole))) $ do
      let (depth, expected) =
            case nhTerm hole of
              CMeta meta
                | Just classifier <- Map.lookup meta (csMetaClassifiers state) ->
                    (micDepth classifier, micType classifier)
              _ -> (nhDepth hole, nhTypeTerm hole)
          occurrence = fromMaybe noSpan (lastMaybe (nhOccs hole))
      reportUnsolvedHoleAt depth ("?" <> name) occurrence expected

-- | Diagnose signatures that never reached a matching body (the ordinary
-- signature-satisfaction diagnostic is emitted separately). This also keeps
-- malformed declarations from leaking named-hole scopes across a module
-- boundary.
finalizeDeferredSignatureHoles :: CheckM ()
finalizeDeferredSignatureHoles = do
  pending <- gets csSignatureHoles
  forM_ (Map.toAscList pending) $ \(_, holes) ->
    withNamedHoleScope holes finalizeNamedHoles (pure ())
  modify' $ \st -> st {csSignatureHoles = Map.empty}

-- | Canonical alpha-bound names used while checking one declaration or SCC.
-- '$' is not a source identifier spelling, so an ordinary source binder
-- cannot capture a schema occurrence renamed to one of these names.
internalizeUniverseSchema :: UniverseSchema -> UniverseSchema
internalizeUniverseSchema schema =
  schema
    { usParameters =
        [ Name ("$schema" <> T.pack (show index)) (nameSpan parameter)
        | (index, parameter) <- zip [0 :: Int ..] (usParameters schema)
        ]
    }

-- | Enter the rigid static schema attached to a declaration name. The
-- mapping is deliberately checker state rather than 'Ctx': schema parameters
-- are not term binders and must not affect de Bruijn depth, closure capture,
-- quantities, or runtime environments.
withDeclarationUniverseSchema :: Decl -> CheckM a -> CheckM a
withDeclarationUniverseSchema declaration action = do
  validateUniverseVarianceApplicability declaration
  case declarationUniverseName declaration of
    Just declarationName -> do
      owner <- ownName declarationName
      case nameUniverseSchema declarationName of
        Just schema ->
          modify' $ \st ->
            st
              { csDeclaredUniverseSchemaNames =
                  Map.insert owner (map nameText (usParameters schema))
                    (csDeclaredUniverseSchemaNames st)
              }
        Nothing -> pure ()
      inherited <- gets (Map.lookup owner . csDeclaredUniverseSchemaNames)
      let effectiveSchema =
            nameUniverseSchema declarationName
              <|> fmap (\names -> UniverseSchema [Name name (nameSpan declarationName) | name <- names] [] (nameSpan declarationName)) inherited
      withActiveUniverseDefinition owner $
        withUniverseSchemaParameters effectiveSchema action
    Nothing -> case declaration of
      DInstance instanceDeclaration _ ->
        withUniverseSchemaParameters (inUniverseSchema instanceDeclaration) action
      _ -> action

validateUniverseVarianceApplicability :: Decl -> CheckM ()
validateUniverseVarianceApplicability declaration =
  case declarationUniverseName declaration >>= nameUniverseSchema of
    Just schema
      | any isJust (usRoles schema)
      , not (nominalDeclaration declaration) ->
          errOnce (usSpan schema) "E_UNIVERSE_VARIANCE_NOT_APPLICABLE"
            (Just "kappa.universe.variance")
            "declaration-universe roles are valid only on nominal data or trait signature blocks (§11.1.2.3A.2)"
    _ -> pure ()
  where
    nominalDeclaration = \case
      DData {} -> True
      DTrait {} -> True
      _ -> False

-- | Enter only the rigid schema-parameter scope. Anonymous declarations such
-- as instances acquire their semantic owner after head elaboration begins;
-- 'registerInstanceHead' establishes that owner around the complete typed
-- head while reusing this static mapping.
withUniverseSchemaParameters :: Maybe UniverseSchema -> CheckM a -> CheckM a
withUniverseSchemaParameters Nothing action = action
withUniverseSchemaParameters (Just (UniverseSchema parameters _ schemaSpan)) action = do
  let names = map nameText parameters
  forM_ (duplicatesOf names) $ \duplicate ->
    errAt schemaSpan "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
      ("duplicate declaration-universe parameter '" <> duplicate <> "' in one schema")
  previous <- gets csActiveUniverseSchema
  let active = Map.fromList (zip names (map LParam [0 ..]))
  modify' $ \st -> st {csActiveUniverseSchema = active}
  result <- action
  modify' $ \st -> st {csActiveUniverseSchema = previous}
  pure result

-- | Enter a nested local semantic declaration's universe boundary. Inferred
-- local declarations receive a fresh boundary while retaining outer schema
-- names; explicit local schemas prepend their own parameters and shift outer
-- parameters out of the way. The restoration action lets a local declaration
-- finish its header under the schema and check the following lexical body
-- after that schema has gone out of scope.
withLocalDeclarationUniverseSchema
  :: Bool
  -- ^ Whether the local declaration elaborates to a nominal signature block.
  -> Maybe UniverseSchema
  -> (CheckM () -> CheckM a)
  -> CheckM a
withLocalDeclarationUniverseSchema rolesApplicable schema action = do
  case schema of
    Just localSchema
      | any isJust (usRoles localSchema)
      , not rolesApplicable ->
          errOnce (usSpan localSchema) "E_UNIVERSE_VARIANCE_NOT_APPLICABLE"
            (Just "kappa.universe.variance")
            "declaration-universe roles are valid only on nominal data or trait signature blocks (§11.1.2.3A.2)"
    _ -> pure ()
  previousNames <- gets csActiveUniverseSchema
  previousCount <- gets csActiveLocalUniverseSchemaCount
  activeNames <- case schema of
    Nothing -> pure previousNames
    Just (UniverseSchema parameters _ schemaSpan) -> do
      let names = map nameText parameters
          count = length names
      forM_ (duplicatesOf names) $ \duplicate ->
        errAt schemaSpan "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
          ("duplicate local declaration-universe parameter '" <> duplicate <> "' in one schema")
      let localNames = Map.fromList (zip names (map LParam [0 ..]))
          shiftedOuter = Map.map (abstractLocalLevelParams count) previousNames
      pure (Map.union localNames shiftedOuter)
  let localCount = length . maybe [] usParameters $ schema
      restore = modify' $ \st ->
        st
          { csActiveUniverseSchema = previousNames
          , csActiveLocalUniverseSchemaCount = previousCount
          }
  modify' $ \st ->
    st
      { csActiveUniverseSchema = activeNames
      , csActiveLocalUniverseSchemaCount =
          case schema of
            Nothing -> Nothing
            Just _ -> Just localCount
      }
  result <- action restore
  restore
  pure result

-- | Extend an enclosing declaration schema for a nested semantic declaration
-- such as a data constructor or associated member. Enclosing parameters keep
-- their indices; the nested declaration appends its own rigid parameters.
-- Consequently the nested declaration's complete telescope contains every
-- static identity that can occur in its interface, while no parameter becomes
-- a term binder or runtime field.
withNestedUniverseSchemaParameters :: Maybe UniverseSchema -> CheckM a -> CheckM a
withNestedUniverseSchemaParameters Nothing action = action
withNestedUniverseSchemaParameters (Just (UniverseSchema parameters _ schemaSpan)) action = do
  previous <- gets csActiveUniverseSchema
  let names = map nameText parameters
      duplicates = duplicatesOf names
      shadows = filter (`Map.member` previous) names
      offset = Map.size previous
  forM_ duplicates $ \duplicate ->
    errAt schemaSpan "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
      ("duplicate declaration-universe parameter '" <> duplicate <> "' in one schema")
  forM_ shadows $ \shadow ->
    errAt schemaSpan "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
      ( "nested declaration-universe parameter '" <> shadow
          <> "' would shadow an enclosing schema parameter"
      )
  let appended = Map.fromList (zip names (map LParam [offset ..]))
      active = Map.union previous appended
  modify' $ \st -> st {csActiveUniverseSchema = active}
  result <- action
  modify' $ \st -> st {csActiveUniverseSchema = previous}
  pure result

declarationUniverseName :: Decl -> Maybe Name
declarationUniverseName = \case
  DSig _ name _ _ -> Just name
  DLet _ def _ -> ldName def
  DData _ decl _ -> Just (ddName decl)
  DTypeAlias _ name _ _ _ _ -> Just name
  DTrait _ decl _ -> Just (trName decl)
  DEffect _ decl _ -> Just (effName decl)
  DPattern _ def _ -> ldName def
  DProjection _ name _ _ _ _ -> Just name
  DExpect _ form _ -> case form of
    ExpectTerm name _ -> Just name
    ExpectType name _ _ -> Just name
    ExpectData name _ _ -> Just name
    ExpectTrait name _ _ -> Just name
  DUnsafeAssert _ inner _ -> declarationUniverseName inner
  _ -> Nothing

-- | §4.4 termination-assertion escape. The assertion is gated by the
-- §4.2 build configuration: rejected by default (kappa.feature.gated)
-- with a diagnostic naming both the offending form and the build setting
-- that disallows it. When permitted, the use is recorded in the §4.7
-- audit ledger and the wrapped definition is elaborated normally. Only
-- `assertReducible` records a conversion-reducibility override for the SCC
-- termination pass; `assertTerminates` remains an audited acceptance escape.
elabUnsafeAssert :: UnsafeAssertKind -> Decl -> Span -> CheckM ()
elabUnsafeAssert akind inner sp = do
  cfg <- gets csUnsafe
  let (facility, setting, allowed) = case akind of
        AssertTerminates -> ("assertTerminates", "allow_assert_terminates", allowAssertTerminates cfg)
        AssertTotal -> ("assertTotal", "allow_assert_terminates", allowAssertTerminates cfg)
        AssertReducible -> ("assertReducible", "allow_assert_reducible", allowAssertReducible cfg)
      affected = case inner of
        DLet _ ld _ -> maybe "<anonymous>" nameText (ldName ld)
        _ -> "<definition>"
  if allowed
    then do
      recordAudit facility affected setting sp Nothing
      case (akind, inner) of
        (AssertTerminates, DLet _ ld _) | Just n <- ldName ld -> do
          g <- ownName n
          modify' $ \st ->
            st {csAssertTerminates = Set.insert g (csAssertTerminates st)}
        (AssertTotal, DLet _ ld _) | Just n <- ldName ld -> do
          g <- ownName n
          modify' $ \st ->
            st {csAssertTerminates = Set.insert g (csAssertTerminates st)}
        (AssertReducible, DLet _ ld _) | Just n <- ldName ld -> do
          g <- ownName n
          modify' $ \st -> st {csAssertReducible = Set.insert g (csAssertReducible st)}
        _ -> pure ()
    else do
      gateUnsafe facility setting sp affected
      -- Keep elaborating the wrapped body for name recovery, but exclude it
      -- from totality checking: the disabled acceptance assertion is the root
      -- error and an additional termination failure would be a cascade.
      case inner of
        DLet _ definition _ | Just name <- ldName definition -> do
          global <- ownName name
          modify' $ \state ->
            state
              { csTerminationNames =
                  Set.delete global (csTerminationNames state)
              }
        _ -> pure ()
  -- Elaborate the wrapped definition regardless of gating: these forms
  -- never change runtime semantics (§4.4) and registering the binding avoids
  -- a spurious §9.1 signature-unsatisfied cascade on top of the gate error.
  bodyPass inner

-- | §4.2: reject an unsafe/debug facility that the build configuration
-- disallows, citing both the offending form and the disabling setting.
gateUnsafe :: Text -> Text -> Span -> Text -> CheckM ()
gateUnsafe facility setting sp affected =
  report $
    withPayload (featureGatedPayload ("unsafe-debug-facility:" <> facility) setting) $
    withRelated (related RoleFeatureGateSite sp ("build setting '" <> setting <> "' is disabled")) $
      diag SevError StageElaborate "E_FEATURE_INACTIVE" (Just "kappa.feature.gated") sp
        ( "use of unsafe/debug facility '" <> facility <> "'"
            <> (if T.null affected || affected == "<definition>" then "" else " (on '" <> affected <> "')")
            <> " requires the build setting '" <> setting
            <> "', which is disabled (Spec §4.2)"
        )

-- | §4.7: append one audit-ledger entry for an accepted unsafe/debug use.
recordAudit :: Text -> Text -> Text -> Span -> Maybe Text -> CheckM ()
recordAudit facility affected setting sp reason = do
  mn <- gets csModule
  let rec' = AuditRecord facility mn sp affected setting reason
  modify' $ \st -> st {csAuditLedger = csAuditLedger st ++ [rec']}

-- | §4.5: gate a reference to the unchecked-proof escape
-- @unsafeAssertProof@ (and its primitive @__unsafeAssertProof@, whose type
-- @forall (@0 p : Type). p@ is a raw admit — it inhabits ANY proposition from
-- a @Type@ alone, so naming it from ordinary user code forges false proofs).
--
-- There are exactly two doors, neither of them name-based:
--
--   * the 'csAllowUnsafeIntrinsics' flag — set by the prelude loader for the
--     genuine embedded prelude/std-lib (so the prelude can define and use
--     these admits), and by the pipeline for any user module that carries the
--     @AllowUnsafeIntrinsics attribute; and
--   * the @allow_unsafe_assert_proof@ build setting — the explicit, audited
--     per-build opt-in used by the lawful-trait escape (§11.4/§14.4).
--
-- The exemption is deliberately NOT name-based on @cur == preludeModule@. The
-- previous gate skipped its whole body whenever @cur == preludeModule@, so a
-- user file literally named @module std.prelude@ — which never goes through
-- the embedded-prelude loader and so never gets the flag — could forge
-- @let bogus : (=) True False = __unsafeAssertProof@ and inhabit Void. The
-- flag, not the module name, now decides the embedded exemption, exactly as
-- 'gateUnsafeIntrinsic' does, so the spoof module is rejected like any other.
-- Each accepted use is recorded in the §4.7 ledger (except the genuine
-- embedded prelude's own internal admits, which would otherwise pollute every
-- downstream module's carried-forward ledger).
gateUnsafeAssertProof :: GName -> Span -> CheckM ()
gateUnsafeAssertProof (GName gm nm) sp
  | gm == preludeModule, nm `elem` ["unsafeAssertProof", "__unsafeAssertProof"] = do
      allowed <- gets csAllowUnsafeIntrinsics
      embedded <- gets csEmbeddedLoad
      cfg <- gets csUnsafe
      if allowed
        then when (not embedded) $
          recordAudit "unsafeAssertProof" nm "allow_unsafe_intrinsics" sp Nothing
        else
          if allowUnsafeAssertProof cfg
            then recordAudit "unsafeAssertProof" nm "allow_unsafe_assert_proof" sp Nothing
            else gateUnsafe "unsafeAssertProof" "allow_unsafe_assert_proof" sp ""
  | otherwise = pure ()

-- | §4.5 soundness gate: the raw-admit proof intrinsics. Each of these
-- prelude primitives inhabits an ARBITRARY proposition from nothing but a
-- @Type@ (or transmutes one value to any type), so naming one from ordinary
-- user code is a total-unsoundness hole — e.g.
-- @let bogus : (=) True False = __eqProof@ type-checks, and @subst@ over a
-- discriminator family then inhabits @Void@. They exist only so the prelude
-- can admit the proof helpers (cong/sym/trans/subst/pathInd/isPropEq/… and
-- the §11.4 List-monoid laws) and so the elaborator can build @__handleEff@
-- applications. The exemption is the 'csAllowUnsafeIntrinsics' flag ALONE:
-- it is set by the prelude loader when elaborating the genuine embedded
-- prelude/std-lib (so those admit the proof helpers), and by the pipeline
-- for any user module that carries the @AllowUnsafeIntrinsics attribute
-- (for tests/bootstrapping). The exemption is deliberately NOT name-based
-- on @cur == preludeModule@ — a user file literally named @module std.prelude@
-- never goes through the embedded-prelude load and so never gets the flag,
-- and is rejected like any other module. Every gated name is rejected when
-- the flag is off, before any term is built, on every resolution path
-- (unqualified, module-aliased, fully-qualified, and reified-module-member),
-- so there is no path by which ordinary user code reaches the raw admit.
-- Each accepted opt-in use is recorded in the §4.7 audit ledger.
-- The complete set of user-nameable prelude prims that inhabit an arbitrary
-- proposition or can liberate a free result variable:
--
--   (a) RESULT type a free, unpinned variable — bound by the prim's telescope
--       but appearing in no argument, so it unifies with any target type. A
--       full prelude scan (§4.5) found these six: the four proof intrinsics
--       plus the two @std.debug@ introspection prims @__debugInspect@/
--       @__debugCompare@, whose result @r@ is pinned only by the std.debug
--       wrappers one module up but is free at the bare-prim level —
--       @let bogus : (=) True False = __debugInspect 0@ type-checks.
--
--   (b) Pure eliminators whose result is pinned to a FREE argument variable
--       that a sound producer can supply unconstrained — a composition hole.
--       The remaining prelude case is @__arrayIndexUnsafe@ via an empty
--       @__arrayFromList []@ producer.
--
-- @__debugRender@ is deliberately NOT gated: its result is pinned to @String@
-- (no free variable, no producer can liberate it), so it is not exploitable,
-- and a §11.4 positive test names it from a plain module to exercise carrier
-- recovery through a primitive equand (isprop-eq-string-prim-carrier-positive.kp)
-- — gating it would break that legitimate use for no soundness gain. The
-- §28.5 STEP-3 composition survey checked every remaining pinned-result
-- eliminator for a free-variable producer: @__codeEscape : Code t -> t@ has no
-- way to build a @Code (free t)@ (the only code producer, @.<e>.@, requires a
-- well-typed @e : t@); @runPure : Eff __effRowNil a -> a@ has no @Eff (free a)@
-- producer (@throwIO@/@stmAbort@ produce @IO@, not @Eff@, and a fully-handled
-- @__effRowNil@ row cannot be reached with a free result); and @atomically :
-- STM a -> IO Void a@ / @runCode : ClosedCode t -> IO Void t@ wrap (not extract)
-- the result. The remaining eliminator that does have a sound free-variable
-- producer is @__arrayIndexUnsafe@ (via @__arrayFromList []@), gated below.
-- @__bytesIndexUnsafe@/@__rowExtend@ have concrete results (@Byte@ / a row),
-- no free variable to liberate.
-- @__unsafeAssertProof@ is gated separately by 'gateUnsafeAssertProof'.
--
-- @std.testing.failNow@ (type @forall (@0 a : Type). String -> a@) has the same
-- raw-admit shape — its result @a@ is free — and, unlike the six prelude prims,
-- it lives in @std.testing@ and is reachable from a plain user module via
-- @import std.testing as T; T.failNow@ or a bare @std.testing.failNow@. A guard
-- keyed on @gm == preludeModule@ would never fire for it, so the gate is keyed
-- on the full @(module, name)@ pair below. @std.testing@ itself is loaded with
-- the 'csAllowUnsafeIntrinsics' flag (it is part of the embedded std-lib), so
-- its own definitions are exempt; only a NON-exempt module naming @failNow@ is
-- gated.
gatedUnsafeIntrinsics :: Set.Set GName
gatedUnsafeIntrinsics =
  Set.fromList $
    prelRawProof
      : [ GName preludeModule n
    | n <-
        [ "__transport"
        , "__absurd"
        , "__handleEff"
        , "__debugInspect"
        , "__debugCompare"
        , -- §4.5 composition class: @__arrayIndexUnsafe :
          -- forall a. Array a -> Int -> a@ extracts an element PURELY, and its
          -- result @a@ is pinned to the @Array a@ argument, so the original
          -- free-RESULT survey passed it over. But @__arrayFromList : forall a.
          -- List a -> Array a@ applied to the empty list @[]@ builds an @Array
          -- (free a)@ with NO element (a genuinely empty array — the producer is
          -- sound), and indexing it liberates the free @a@:
          -- @let bad : (=) True False = __arrayIndexUnsafe (__arrayFromList []) 0@
          -- type-checks. Users have the safe @arrayIndex@/@Array.get@ wrappers
          -- (which return @Option@/trap), and the embedded prelude's own
          -- @arrayIndex@ definition uses this prim under the
          -- 'csAllowUnsafeIntrinsics' exemption, so gating the bare prim costs
          -- ordinary code nothing. (@__bytesIndexUnsafe : Bytes -> Nat -> Byte@
          -- is NOT gated: its result @Byte@ is concrete — no free variable to
          -- liberate.)
          "__arrayIndexUnsafe"
        ]
    ]
      ++ [GName modTesting "failNow"]

gateUnsafeIntrinsic :: GName -> Span -> CheckM ()
gateUnsafeIntrinsic g@(GName _ nm) sp
  | g `Set.member` gatedUnsafeIntrinsics = do
      -- §4.5: exemption is the 'csAllowUnsafeIntrinsics' flag ALONE (set
      -- for the embedded prelude/std-lib by the loader, and for a user
      -- module carrying @AllowUnsafeIntrinsics). A user file merely named
      -- 'module std.prelude' does NOT get the flag and is rejected.
      allowed <- gets csAllowUnsafeIntrinsics
      embedded <- gets csEmbeddedLoad
      if allowed
        then -- §4.7: record each accepted opt-in use in the audit ledger so the
             -- soundness escape shows in the audit trail (mirrors how
             -- 'gateUnsafeAssertProof' records 'unsafeAssertProof'). The genuine
             -- embedded prelude/std-lib admits the proof helpers and wraps the
             -- debug prims internally — implementation machinery, not a user
             -- opt-in — so those uses are NOT ledgered (they would otherwise
             -- pollute every downstream module's ledger, since the base ledger
             -- carries forward). Every NON-embedded module reaching here did so
             -- via the @AllowUnsafeIntrinsics flag, so the use is recorded.
          when (not embedded) $
            recordAudit "unsafeIntrinsic" nm "allow_unsafe_intrinsics" sp Nothing
        else
          report $
            withPayload
              ( withPayloadField "name" nm $
                  payloadKind "unsafe-intrinsic-gated"
              ) $
              withRelated (related RoleUseSite sp ("'" <> nm <> "' named here")) $
                diag SevError StageElaborate "E_UNSAFE_INTRINSIC_GATED" (Just "kappa.feature.gated") sp
                  ( "the raw-admit proof intrinsic '" <> nm
                      <> "' inhabits an arbitrary proposition and is not nameable from ordinary"
                      <> " user code; it would forge false proofs and break soundness."
                      <> " Use the checked proof helpers (refl/cong/subst/…) instead, or mark the"
                      <> " module '@AllowUnsafeIntrinsics' to opt in for testing (Spec §4.5)"
                  )
  | otherwise = pure ()

-- | §4.5 soundness gate at every name/member resolution path. The two
-- escapes ('gateUnsafeAssertProof' and 'gateUnsafeIntrinsic') were
-- originally invoked only from the unqualified 'resolveName' path, which
-- a QUALIFIED reference bypasses: @import std.prelude as P@ then
-- @P.__eqProof@ (the module-alias branch of 'elabDotUnqualified'), a bare
-- fully-qualified @std.prelude.__eqProof@ ('elabDotOrdinary'), or a reified
-- module-object member ('moduleMember') each resolve straight to the
-- prelude 'globalTerm' with no gate. This helper runs BOTH gates and is
-- threaded through every such path, so a qualified reference is gated
-- identically to a bare one and the @AllowUnsafeIntrinsics flag is the only
-- way user code can name a gated intrinsic.
gateUnsafeResolved :: GName -> Span -> CheckM ()
gateUnsafeResolved g sp = do
  gateUnsafeAssertProof g sp
  gateUnsafeIntrinsic g sp

-- | An active-pattern declaration (§17.3.1) elaborates as an ordinary
-- function definition (the pattern name is also a first-class value)
-- and registers pattern metadata: its result classification and the
-- number of pattern arguments before the scrutinee.
elabActivePatternDecl :: DeclMods -> LetDef -> Span -> CheckM ()
elabActivePatternDecl mods ld sp = do
  elabLetDecl mods ld sp
  case ldName ld of
    Nothing -> pure ()
    Just n -> do
      g <- ownName n
      mgd <- gets (Map.lookup g . csGlobals)
      forM_ mgd $ \gd -> do
        (_argc, res) <- unrollExplicit 0 (gdType gd)
        resF <- forceM res
        let kind = case resF of
              VGlobN g _ | g == prelOption -> Right APOption
              VGlobN g _ | g == prelMatch -> Right APMatch
              VGlobN g _ | g `elem` kernelMonadCarriers -> Left (gKey g)
              _ -> Right APTotal
        case kind of
          Left h ->
            errAt sp "E_ACTIVE_PATTERN_MONADIC_RESULT" (Just "kappa-hs.pattern.active")
              ("an active pattern's result type may not be the monadic type '" <> h
                 <> "'; return Option, Match, or a total view type (§17.3.1)")
          Right k -> do
            -- an Option/total-view pattern cannot return a residue, so
            -- a linear scrutinee would be lost on the miss path
            let explBinders = [b | b <- ldBinders ld, not (bImplicit b)]
                scrutLinear = case reverse explBinders of
                  (b : _) ->
                    surfaceQuantityPositive (bpQuantity (bPrefix b))
                      && isNothing (bpBorrow (bPrefix b))
                  [] -> False
            when (scrutLinear && k /= APMatch) $
              errAt sp "E_ACTIVE_PATTERN_LINEARITY_VIOLATION" (Just "kappa-hs.pattern.active")
                "this active pattern consumes a linear scrutinee but cannot thread a residue back on a miss; return 'Match item residue' instead (§17.3)"
            modify' $ \st -> st {csActive = Map.insert g (APInfo k) (csActive st)}
  where
    unrollExplicit :: Int -> Value -> CheckM (Int, Value)
    unrollExplicit = goU 0
      where
        goU expl lvl v = do
          vf <- forceM v
          case vf of
            VPi ic _ _ _ _ clo -> do
              inner <- clApp clo (VRigid lvl [])
              goU (if ic == Expl then expl + 1 else expl) (lvl + 1) inner
            _ -> pure (expl, vf)

-- | A projection definition (§9.1.1). Both forms register a term facet
-- global (a first-class descriptor) plus 'csProjections' metadata used
-- by the application-site elaborators of §16.1.5/§16.1.6.
--
--   * selector form: term facet @Δ -> Projector Roots T@; the runtime
--     value is @λΔ. λplaces. body@ with each @yield p@ reading @p@.
--   * expanded form: term facet @Δ -> Bundle@, a structural record of
--     @Getter/Opener/Setter/Sinker@ accessor closures with the §9.1.1
--     descriptor-field synthesis (get+set ⇒ open, inout ⇒ set).
--
-- Place lambdas/applications use the canonical (lexicographic) order of
-- the @Roots@ record so descriptor applications can be elaborated from
-- the roots record type alone.
elabProjectionDecl :: DeclMods -> Name -> [Binder] -> Expr -> ProjBody -> Span -> CheckM ()
elabProjectionDecl _mods n binders resTyE body sp = do
  flushPending
  g <- ownName n
  let groups = projBinderGroups binders
      placeBs = [b | (True, b) <- groups]
      ordBs = [b | (False, b) <- groups]
  when (null placeBs) $
    errAt sp "E_PROJECTION_MISSING_PLACE_BINDER" (Just "kappa-hs.projection.place-binder")
      "a projection definition must contain at least one 'place' binder (§9.1.1)"
  -- Δ context: ordinary binders, declaration order
  (ctxD, ordTele) <- elabOrdBinders emptyCtx ordBs
  -- place binder types and the focus, under the full Δ
  places0 <- forM placeBs $ \b -> do
    tyTm <- case binderTypeExpr b of
      Just tyE -> withGeneralizableBareTypeLevels $
        normalizeBinderDomain ctxD b tyE >>= fmap fst . inferType ctxD
      Nothing -> freshMeta
    tyV <- evalIn ctxD tyTm
    pure (maybe "_" nameText (bName b), tyTm, tyV)
  let placesLex = sortOn (\(nm, _, _) -> nm) places0
      ctxPl = foldl (\c (nm, _, tv) -> bindCtx nm False tv c) ctxD placesLex
      nPl = length placesLex
  -- the declared focus may depend on the place binders (e.g.
  -- 'Array this.len Byte'); in the descriptor type a unique root is
  -- represented by the §13.2.1 'this' neutral
  (focusTmP, _) <- inferType ctxPl resTyE
  focusV <- evalIn ctxPl focusTmP
  let focusTm = placesToThis nPl focusTmP
      rootsTm = CRecordT [(nm, t) | (nm, t, _) <- placesLex]
      placeNames = [nm | (nm, _, _) <- places0]
      lamsOrd t = foldr (\(q, nm, _) acc -> CLamM Ordinary Expl q nm acc) t ordTele
      pisOrd t = foldr (\(q, nm, ty) acc -> CPiFormedM Ordinary FormationOrdinary Expl q False nm ty acc) t ordTele
      app2 h a b = CApp Expl (CApp Expl h a) b
  case body of
    ProjSelector bodyE0 -> do
      projectorHead <- globalHeadM (gPrel "Projector")
      let yields0 = projYieldPlaces bodyE0
      yields <- fmap catMaybes . forM yields0 $ \case
        Right (root, path)
          -- with no place binders at all the declaration-level
          -- diagnostic already covers every yield
          | root `elem` placeNames || null placeNames -> pure (Just (root, path))
        Right (_, _) -> do
          errAt sp "E_PROJECTION_YIELD_INVALID" (Just "kappa-hs.projection.yield")
            "each 'yield' operand must be a stable place rooted in a 'place' binder of this projection (§9.1.1)"
          pure Nothing
        Left ysp -> do
          errAt ysp "E_PROJECTION_YIELD_INVALID" (Just "kappa-hs.projection.yield")
            "each 'yield' operand must be a stable place rooted in a 'place' binder of this projection (§9.1.1)"
          pure Nothing
      let bodyE = stripYields bodyE0
      bodyTm <- check ctxPl bodyE focusV
      let coreTy = pisOrd (app2 projectorHead rootsTm focusTm)
          defTm = lamsOrd (foldr (\(nm, _, _) acc -> CLamM Ordinary Expl QW nm acc) bodyTm placesLex)
      registerProjection g coreTy defTm $
        ProjInfo [isP | (isP, _) <- groups] placeNames True yields
    ProjAccessors clauses -> do
      forM_ (duplicatesOf [k | (k, _, _) <- clauses]) $ \k ->
        errAt sp "E_PROJECTION_ACCESSOR_CLAUSE_DUPLICATE" (Just "kappa-hs.projection.accessor")
          ("the accessor clause '" <> k <> "' appears more than once (§9.1.1)")
      when (length placeBs /= 1) $
        errAt sp "E_PROJECTION_EXPANDED_ACCESSOR_PLACE_BINDER_MISMATCH" (Just "kappa-hs.projection.accessor")
          "an expanded-form projection must have exactly one 'place' binder (§9.1.1)"
      case places0 of
        [] -> pure ()
        ((pName, pTyTm, pTyV) : _) -> do
          zipperHead <- globalHeadM prelZipper
          getterHead <- globalHeadM (gPrel "Getter")
          openerHead <- globalHeadM (gPrel "Opener")
          setterHead <- globalHeadM (gPrel "Setter")
          sinkerHead <- globalHeadM (gPrel "Sinker")
          let ctxP = bindCtx pName False pTyV ctxD
              zipperTm = CApp Expl (CApp Expl (CApp Expl zipperHead pTyTm) focusTm) focusTm
          zipperV <- evalIn ctxD zipperTm
          let clauseOf k = [(mb, e) | (k', mb, e) <- clauses, k' == k]
              getC = clauseOf "get"
              setC = clauseOf "set"
              inoutC = clauseOf "inout"
              sinkC = clauseOf "sink"
          -- direct clause bodies
          getTm <- forM (take 1 getC) $ \(_, e) -> check ctxP e focusV
          sinkTm <- forM (take 1 sinkC) $ \(_, e) -> check ctxP e focusV
          inoutTm <- forM (take 1 inoutC) $ \(_, e) -> check ctxP e zipperV
          setTm <- forM (take 1 setC) $ \(mb, e) -> do
            let nv = fromMaybe "new_value" (mb >>= fmap nameText . bName)
            nvV <- case mb >>= bType of
              Just tyE -> do
                (t, _) <- inferType ctxD tyE
                evalIn ctxD t
              Nothing -> pure focusV
            tm <- check (bindCtx nv False nvV ctxP) e pTyV
            pure (nv, tm)
          -- synthesized descriptors (§9.1.1)
          synthOpen <-
            case (inoutTm, getC, setC) of
              ([], ((_, getE) : _), ((mb, setE) : _)) -> do
                let nvB = fromMaybe (simpleBinder (Name "new_value" sp)) mb
                    openE =
                      EApp (EVar (Name "Zipper" sp))
                        [ ArgExplicit getE
                        , ArgExplicit (ELambda Nothing [nvB] setE sp)
                        ]
                tm <- check ctxP openE zipperV
                pure [tm]
              _ -> pure []
          synthSet <-
            case (setTm, inoutC) of
              ([], ((_, inoutE) : _)) -> do
                let newE = EVar (Name "__new" sp)
                    fillE = EApp (EDot inoutE (DotName (Name "fill" sp))) [ArgExplicit newE]
                tm <- check (bindCtx "__new" False focusV ctxP) fillE pTyV
                pure [("__new", tm)]
              _ -> pure []
          let lamP t = CLamM Ordinary Expl QW pName t
              caps =
                [ ("get", app2 getterHead rootsTm focusTm, lamP t) | t <- take 1 getTm ]
                  ++ [ ("open", app2 openerHead rootsTm focusTm, lamP t)
                     | t <- take 1 (inoutTm ++ synthOpen)
                     ]
                  ++ [ ("set", app2 setterHead rootsTm focusTm, lamP (CLamM Ordinary Expl Q1 nv t))
                     | (nv, t) <- take 1 (setTm ++ synthSet)
                     ]
                  ++ [ ("sink", app2 sinkerHead rootsTm focusTm, lamP t) | t <- take 1 sinkTm ]
              capsSorted = sortOn (\(nm, _, _) -> nm) caps
              coreTy = pisOrd (CRecordT [(nm, t) | (nm, t, _) <- capsSorted])
              defTm = lamsOrd (CRecordV [(nm, t) | (nm, _, t) <- capsSorted])
          registerProjection g coreTy defTm $
            ProjInfo [isP | (isP, _) <- groups] placeNames False []
  where
    stripYields e0 = case e0 of
      EApp (EVar y) [ArgExplicit e] | nameText y == "yield" -> e
      EIf alts mels isp ->
        EIf [(c, stripYields b) | (c, b) <- alts] (stripYields <$> mels) isp
      EMatch scrut cases msp ->
        EMatch scrut
          [ case c of
              MatchCase p mg b csp -> MatchCase p mg (stripYields b) csp
              other -> other
          | c <- cases
          ]
          msp
      EBlock ds (Just fin) bsp -> EBlock ds (Just (stripYields fin)) bsp
      EAscription e tyE asp -> EAscription (stripYields e) tyE asp
      e -> e

-- | Rewrite references to the innermost @n@ binders (a projection's
-- place binders) into the §13.2.1 @this@ neutral, dropping the binders.
-- Used to express a root-dependent focus type under Δ alone.
placesToThis :: Int -> Term -> Term
placesToThis n = go 0
  where
    go d t = case t of
      CVar i
        | i >= d ->
            if i - d < n then CGlob thisG else CVar (i - n)
        | otherwise -> t
      CGlobal _ _ -> t
      CLamM mode ic q nm b -> CLamM mode ic q nm (go (d + 1) b)
      CPiEvidenceM mode formation ic q brw nm assumption origin a b ->
        CPiEvidenceM mode formation ic q brw nm assumption origin (go d a) (go (d + 1) b)
      CApp ic f a -> CApp ic (go d f) (go d a)
      CUniverseLift from to evidence inner ->
        CUniverseLift from to evidence (go d inner)
      CSchemaLift family source target roles evidence certificate sourceArguments targetArguments inner ->
        CSchemaLift family source target roles evidence certificate
          (map (go d) sourceArguments) (map (go d) targetArguments) (go d inner)
      CArithmeticProof certificate ->
        CArithmeticProof (mapArithmeticCertificate (go d) certificate)
      CSort _ -> t
      CLevel _ -> t
      CLit _ -> t
      CCtorI g universes ann arguments ->
        CCtorI g universes (fmap (go d) ann)
          [argument {caTerm = go d (caTerm argument)} | argument <- arguments]
      CMatch s ann resultAnn alts ->
        CMatch (go d s) (fmap (go d) ann) (fmap (go d) resultAnn)
          [CaseAlt p (fmap (go (d + patBindersC p)) g) (go (d + patBindersC p) b) | CaseAlt p g b <- alts]
      CRecordTQ fs -> CRecordTQ (map (fmap (go d)) fs)
      CRecordV fs -> CRecordV [(nm, go d x) | (nm, x) <- fs]
      CProjM mode e f -> CProjM mode (go d e) f
      CProjAtM mode e f i -> CProjAtM mode (go d e) f i
      CVariantT ms -> CVariantT (map (go d) ms)
      CInject tag e -> CInject tag (go d e)
      CLetM mode q nm a b c -> CLetM mode q nm (go d a) (go d b) (go (d + 1) c)
      CLetRecM mode q nm a b c -> CLetRecM mode q nm (go d a) (go (d + 1) b) (go (d + 1) c)
      CLetPolyM mode q nm telescope a b c ->
        CLetPolyM mode q nm telescope (go d a) (go d b) (go (d + 1) c)
      CLetRecPolyM mode q nm telescope a b c ->
        CLetRecPolyM mode q nm telescope (go d a) (go (d + 1) b) (go (d + 1) c)
      CLetRecGroupM telescope definitions body ->
        let d' = d + length definitions
         in CLetRecGroupM telescope
              [ definition
                  { clrdType = go d (clrdType definition)
                  , clrdRhs = go d' (clrdRhs definition)
                  }
              | definition <- definitions
              ]
              (go d' body)
      CMeta _ -> t
      CDo _ _ -> t
      CSealE ls e -> CSealE ls (go d e)
      CSigT ls e -> CSigT ls (go d e)
      CThunkE e suspensionType -> CThunkE (go d e) (go d <$> suspensionType)
      CLazyE e suspensionType -> CLazyE (go d e) (go d <$> suspensionType)
      CForceE e resultType -> CForceE (go d e) (go d <$> resultType)
      CIf a b c -> CIf (go d a) (go d b) (go d c)
      CQuote qs slots -> CQuote qs (map (go d) slots)
      CLocal i universes
        | i >= d ->
            if i - d < n then CGlob thisG else CLocal (i - n) universes
        | otherwise -> t

-- | Elaborate the ordinary (non-place) binders of a projection in
-- declaration order, returning the extended context and the telescope.
elabOrdBinders :: Ctx -> [Binder] -> CheckM (Ctx, [(Q, Text, Term)])
elabOrdBinders ctx0 [] = pure (ctx0, [])
elabOrdBinders ctx0 (b : bs) = do
  tyTm <- case binderTypeExpr b of
    Just tyE -> withGeneralizableBareTypeLevels $
      normalizeBinderDomain ctx0 b tyE >>= fmap fst . inferType ctx0
    Nothing -> freshMeta
  tyV <- evalIn ctx0 tyTm
  let nm = maybe "_" nameText (bName b)
      ctx1 = bindCtx nm (bImplicit b) tyV ctx0
  (ctx2, rest) <- elabOrdBinders ctx1 bs
  pure (ctx2, (binderQ b, nm, tyTm) : rest)

-- | Register a projection's term facet and projection-facet metadata.
registerProjection :: GName -> Term -> Term -> ProjInfo -> CheckM ()
registerProjection g coreTy defTm pj = do
  flushPending
  coreTy' <- zonkTermM 0 coreTy
  defTm' <- zonkTermM 0 defTm
  tyV <- evalIn emptyCtx coreTy'
  tmV <- evalIn emptyCtx defTm'
  addGlobal g (GlobalDef tyV (Just tmV) False)
  -- Record the projection's core definition so the native backend lowers the
  -- real selector (a CLam chain); without it the global has no recorded body
  -- and would be erased to the unit placeholder — a silent miscompile.
  recordCoreBody g defTm'
  modify' $ \st -> st {csProjections = Map.insert g pj (csProjections st)}

rejectInoutBinderContext :: Text -> Binder -> CheckM ()
rejectInoutBinderContext context b =
  when (bInout b) $
    errAt (bSpan b) "E_QTT_INOUT_BINDER_CONTEXT" (Just "kappa-hs.qtt.inout-marker")
      ( "'inout' is permitted only on explicit parameters of named functions, "
          <> "methods, and trait-member signatures; it is not permitted in a "
          <> context
          <> " (§18.9.2)"
      )

rejectAllInoutBinders :: Data a => Text -> a -> CheckM ()
rejectAllInoutBinders context x =
  forM_ (collectInoutBinders x) (rejectInoutBinderContext context)

collectInoutBinders :: Data a => a -> [Binder]
collectInoutBinders x =
  maybeToList (cast x >>= \b -> if bInout b then Just b else Nothing)
    ++ concat (gmapQ collectInoutBinders x)

withNamedCallableInoutSignature :: Expr -> CheckM a -> CheckM a
withNamedCallableInoutSignature tyE action = do
  validateNamedCallableInoutSignature tyE
  old <- gets csAllowInoutBinderContext
  modify' $ \st -> st {csAllowInoutBinderContext = True}
  r <- action
  modify' $ \st -> st {csAllowInoutBinderContext = old}
  pure r

validateNamedCallableInoutSignature :: Expr -> CheckM ()
validateNamedCallableInoutSignature = goHead
  where
    goHead = \case
      EArrow b body -> do
        forM_ (bType b) (rejectAllInoutBinders "parameter type")
        forM_ (bDefault b) (rejectAllInoutBinders "parameter default")
        goHead body
      EForall bs body _ -> do
        forM_ bs $ \b -> do
          rejectInoutBinderContext "forall binder" b
          forM_ (bType b) (rejectAllInoutBinders "forall binder type")
          forM_ (bDefault b) (rejectAllInoutBinders "forall binder default")
        goHead body
      ETraitArrow premise body -> do
        rejectAllInoutBinders "trait premise" premise
        goHead body
      EAscription e ty _ -> do
        goHead e
        rejectAllInoutBinders "signature ascription type" ty
      ECaptures e _ _ -> goHead e
      other ->
        rejectAllInoutBinders "nested anonymous function type" other

recordInoutParams :: GName -> [Maybe InoutParamInfo] -> CheckM ()
recordInoutParams g infos =
  when (any isJust infos) $
    modify' $ \st -> st {csInoutParams = Map.insert g infos (csInoutParams st)}

inoutParamsFromBinders :: [Binder] -> [Maybe InoutParamInfo]
inoutParamsFromBinders =
  mapMaybe explicitInfo
  where
    explicitInfo b
      | bImplicit b = Nothing
      | otherwise =
          Just $
            if bInout b
              then do
                nm <- bName b
                let t = nameText nm
                Just (InoutParamInfo t t)
              else Nothing

signatureBinders :: Expr -> [Binder]
signatureBinders = \case
  EForall bs body _ -> bs ++ signatureBinders body
  ETraitArrow _ body -> signatureBinders body
  EArrow b body -> b : signatureBinders body
  ECaptures e _ _ -> signatureBinders e
  EAscription e _ _ -> signatureBinders e
  _ -> []

recordSignatureInoutParams :: GName -> Expr -> CheckM ()
recordSignatureInoutParams g tyE =
  recordInoutParams g (inoutParamsFromBinders (signatureBinders tyE))

recordDefinitionInoutParams :: GName -> [Binder] -> CheckM ()
recordDefinitionInoutParams g binders =
  recordInoutParams g (inoutParamsFromBinders binders)

elabLetDecl :: DeclMods -> LetDef -> Span -> CheckM ()
elabLetDecl mods definition sp
  | Just _ <- ldConstructorPatternCandidate definition = do
      governed <- case ldName definition of
        Nothing -> pure False
        Just name -> do
          global <- ownName name
          gets (Map.member global . csCoreSignatures)
      if governed
        then
          elabLetDecl
            mods
            definition {ldConstructorPatternCandidate = Nothing}
            sp
        else do
          selected <- selectConstructorPatternLet emptyCtx sp definition
          case selected of
            Just (ConstructorPatternCandidate pattern' rhs) ->
              elabLetDecl
                mods
                definition
                  { ldName = Nothing
                  , ldPattern = Just pattern'
                  , ldConstructorPatternCandidate = Nothing
                  , ldBinders = []
                  , ldDecreases = Nothing
                  , ldBody = rhs
                  }
                sp
            Nothing ->
              elabLetDecl
                mods
                definition {ldConstructorPatternCandidate = Nothing}
                sp
-- Signature-governed functions are recorded for the SCC termination pass;
-- non-recursive values still become reducible immediately.
elabLetDecl mods (LetDef (Just n) _ Nothing _ prefix binders mResTy mdec body) sp = do
  declarationErrorsBefore <- gets (length . filter isError . csDiags)
  g <- ownName n
  noteDefinition g sp
  recordDefinitionInoutParams g binders
  mOpAlias <- if null binders then operationValueInfoOfExpr emptyCtx body else pure Nothing
  -- §8.5.2: an 'opaque' term definition keeps its equation available for
  -- definitional equality inside this module, but it is sealed
  -- (gdReducible cleared) at module end so other modules treat it as an
  -- opaque constant at its declared type.
  when (dmOpaque mods) $
    modify' $ \stM -> stM {csOpaqueDefs = Map.insert g () (csOpaqueDefs stM)}
  -- §7.4: record receiver-marked explicit binder positions (method
  -- sugar inserts the receiver at the unique such binder)
  let recvIdxs =
        [ i
        | (i, rb) <- zip [(0 :: Int) ..] [rb | rb <- binders, not (bImplicit rb)]
        , bReceiver rb /= NoReceiver
        ]
  unless (null recvIdxs) $
    modify' $ \stM -> stM {csReceivers = Map.insert g recvIdxs (csReceivers stM)}
  st <- get
  let msig = Map.lookup g (csGlobals st)
      definitionSchemaArity = maybe 0 (length . usParameters) (nameUniverseSchema n)
  case msig of
    Just gd
      | Nothing <- gdValue gd
      , let signatureSchema = gdUniverses gd
      , Just _ <- nameUniverseSchema n
      , not (dutExplicit signatureSchema)
          || dutParameterCount signatureSchema /= definitionSchemaArity ->
          errAt sp "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
            ( "the signature and definition of top-level declaration '" <> nameText n
                <> "' must expose alpha-equivalent universe schemas; signature has "
                <> T.pack (show (dutParameterCount signatureSchema)) <> " parameters and definition has "
                <> T.pack (show definitionSchemaArity)
            )
    _ -> pure ()
  case msig of
    Just gd | Nothing <- gdValue gd -> pure ()
    _ ->
      -- no governing signature: the binding is manifest (§2.8.4)
      modify' $ \stM -> stM {csManifest = Map.insert g () (csManifest stM)}
  -- §13.2.10/§2.8: a signature-governed binding whose definiens is an
  -- identity-preserving form (record/seal/projection chain, not a
  -- function result) still preserves static-object identity
  let { manifestShaped = \case
          CGlob _ -> True
          CRecordV _ -> True
          CSealE _ x -> manifestShaped x
          CProj x _ -> manifestShaped x
          CProjAt x _ _ -> manifestShaped x
          _ -> False
      }
  let duplicateOrInfer = do
        -- a previous definition with a value: duplicate declaration (§9.2)
        case msig of
          Just gd' | isJust (gdValue gd') -> do
            enrich <- duplicateRelated (nameText n) g sp
            report $ enrich $
              diag SevError StageElaborate "E_DUPLICATE_DECLARATION" (Just "kappa-hs.name.duplicate") sp
                ("duplicate declaration of '" <> nameText n <> "'")
          _ -> pure ()
        -- no preceding signature: pre-register the name so self-references
        -- resolve and are reported as recursion-without-signature (§9.2)
        placeholderTy <- freshMetaV emptyCtx
        addGlobal g (GlobalDef placeholderTy Nothing False)
        firstMeta <- gets csNextMeta
        (tmRaw, tyRaw) <-
          elabFunction (Just (nameText n)) binders mResTy body sp
        flushPendingDeclaration
        let inferredBinders = binders ++ case body of
              ELambda _ lambdaBinders _ _ -> lambdaBinders
              _ -> []
        (tm0, ty) <-
          if null inferredBinders
            then pure (tmRaw, tyRaw)
            else do
              tyRawTerm <- quoteIn emptyCtx tyRaw
              (tmFinal, tyFinalTerm) <-
                finalizeLocalLambdaContracts True emptyCtx inferredBinders tmRaw tyRawTerm
              validateInferredLambdaGeneralization
                sp [nameText n] emptyCtx inferredBinders tmFinal tyFinalTerm
              (tyGeneralized, tmGeneralized) <-
                generalizeLocalDeclarationMetas
                  firstMeta emptyCtx sp [nameText n] tyFinalTerm tmFinal
              (tmGeneralized,) <$> evalIn emptyCtx tyGeneralized
        markInferredDeclarationLevelCandidates g ty
        tm1 <- principalizeBodyUniverseInstantiations g ty tm0
        tm <- zonkTermM 0 tm1
        when (occursGlobal g tm) $
          errAt sp "E_RECURSION_REQUIRES_SIGNATURE" (Just "kappa.type.missing-signature")
            "recursive definitions require a preceding signature declaration (§15, §9.2)"
        when (isJust mResTy) $
          checkDeclaredOrdinaryResultObservation sp tm ty
        tmV <- evalIn emptyCtx tm
        inferredObservation <- observationJudgmentForTerm emptyCtx tm ty
        observation <-
          resolveDeclaredResultObservation
            emptyCtx sp prefix (isJust mResTy) ty inferredObservation
        recordCoreBody g tm
        addGlobal g (globalDefWithObservationMode (ojMode observation) (GlobalDef ty (Just tmV) True))
        recordLevelOperatorAlias g tm
        forM_ mOpAlias (recordEffectOpValueGlobal g)
  case msig of
    Just gd | Nothing <- gdValue gd -> withActiveUniverseDefinition g $ do
      -- Pending goals raised inside the signature may have been solved
      -- to the signature's own binder rigids; re-quote the type so the
      -- solutions are baked in as proper de Bruijn variables.
      sigTy <- do
        ec <- ec_
        evalIn emptyCtx (globalCoreType ec gd)
      addGlobal g gd {gdType = sigTy}
      -- signature first: check the definition against it (recursion OK)
      -- §7.1/§7.2: a definition body is a term-expression position, so
      -- the same-spelling constructor facet wins there even under a
      -- sort-typed signature (reaching the reified type facet requires
      -- the explicit `type T` selector, §7.1.1)
      ctorFacetWins <- case body of
        EVar bn | null binders -> do
          sigF <- forceM sigTy
          case sigF of
            VSort _ -> do
              mg <- lookupGlobalName (nameText bn)
              case mg of
                Just bg -> gets (Map.member bg . csCtors)
                Nothing -> pure False
            _ -> pure False
        _ -> pure False
      tm0 <- withRecursiveSchemaOccurrenceRecording $
        if ctorFacetWins
          then case body of
            EVar bn -> do
              (tm', ty') <- infer emptyCtx (EVar bn)
              expectType emptyCtx (nameSpan bn) ty' sigTy
              pure tm'
            _ -> checkAgainstSig (Just (nameText n)) sigTy binders body sp
          else checkAgainstSig (Just (nameText n)) sigTy binders body sp
      flushPendingDeclaration
      settleActiveUniverseRequirements
      tm1 <- principalizeBodyUniverseInstantiations g sigTy tm0
      settleActiveUniverseRequirements
      tm <- zonkTermM 0 tm1
      checkDeclaredOrdinaryResultObservation sp tm sigTy
      tmV <- evalIn emptyCtx tm
      -- The observation summary is an equation over finalized Core bodies.
      -- Register this body's identity before solving that equation so direct
      -- and mutual recursive edges are recognized structurally instead of
      -- being approximated from an incomplete global table.
      recordCoreBody g tm
      inferredObservation <- observationJudgmentForTerm emptyCtx tm sigTy
      observation <-
        resolveDeclaredResultObservation
          emptyCtx sp prefix True sigTy inferredObservation
      deps <- expandedGlobalsOfTermM tm
      let recursive = Set.member g deps
          isFunction = case tm of
            CLam {} -> True
            _ -> not (null binders)
      declarationErrorsAfter <- gets (length . filter isError . csDiags)
      participates0 <- gets (Set.member g . csTerminationNames)
      let participates =
            participates0
              && declarationErrorsAfter == declarationErrorsBefore
      let termDecl = TerminationDecl g sigTy binders mdec tm sp
      when (participates && isFunction) $
        recordTerminationDecl termDecl
      earlyTerminationResult <-
        if participates && isFunction && recursive
          then do
            singletonReady <- singletonTerminationDependenciesReady g deps
            if singletonReady
              then withSccOpaque [g] (verifyTerminationScc [termDecl])
              else pure TerminationUnverified
          else pure TerminationUnverified
      reducible <-
        if recursive && not isFunction
          then do
            -- a self-referential value (no intervening function
            -- abstraction) is a definitional cycle (§15.3, §16.4)
            errAt sp "E_RECURSIVE_VALUE_CYCLE" (Just "kappa.termination.failure")
              ("recursive value cycle: '" <> nameText n
                 <> "' refers to itself without an intervening function abstraction, so its evaluation cannot terminate (§15)")
            pure False
          else if participates && isFunction
            then
              case earlyTerminationResult of
                TerminationConversionSafe -> pure True
                TerminationTotalOnly -> pure False
                TerminationUnverified -> not <$> shouldDeferTermination g deps
            else pure True
      when (manifestShaped tm) $
        modify' $ \stM -> stM {csManifest = Map.insert g () (csManifest stM)}
      currentUniverses <-
        gets
          ( maybe (gdUniverses gd) gdUniverses
              . Map.lookup g
              . csGlobals
          )
      addGlobal g gd
        { gdType = sigTy
        , gdObservationMode = ojMode observation
        , gdValue = Just tmV
        , gdReducible = reducible
        , gdUniverses = currentUniverses
        }
      recordLevelOperatorAlias g tm
      forM_ mOpAlias (recordEffectOpValueGlobal g)
      settleActiveUniverseRequirements
    _ -> duplicateOrInfer

elabLetDecl _ (LetDef Nothing _ (Just pat) _ prefix [] mty Nothing body) sp = do
  -- top-level pattern binding: bind each variable to a projection
  (bodyTm, bodyTy) <- case mty of
    Just tyE -> do
      (tyTm, _) <- inferType emptyCtx tyE
      tyV <- evalIn emptyCtx tyTm
      tm <- check emptyCtx body tyV
      pure (tm, tyV)
    Nothing -> infer emptyCtx body
  checkIrrefutable emptyCtx pat bodyTy sp
  case pat of
    PVar n -> do
      g <- ownName n
      when (isJust mty) $
        checkDeclaredOrdinaryResultObservation sp bodyTm bodyTy
      mOpAlias <- operationValueInfoOfExpr emptyCtx body
      tmV <- evalIn emptyCtx bodyTm
      inferredObservation <- observationJudgmentForTerm emptyCtx bodyTm bodyTy
      observation <-
        resolveDeclaredResultObservation
          emptyCtx sp prefix (isJust mty) bodyTy inferredObservation
      addGlobal g (globalDefWithObservationMode (ojMode observation) (GlobalDef bodyTy (Just tmV) True))
      recordLevelOperatorAlias g bodyTm
      forM_ mOpAlias (recordEffectOpValueGlobal g)
      -- Record the elaborated core body so the native backend lowers the
      -- real value (a top-level prefixed binding `let 1 x = e` / `let &x = e`
      -- reaches here as a PVar pattern); without this it has no recorded body
      -- and would be erased to the unit placeholder — a silent miscompile.
      recordCoreBody g bodyTm
    _ -> do
      (patC, ctxP, patternRefinements) <-
        elabPattern emptyCtx pat bodyTy
      bodyTyTm <- quoteIn emptyCtx bodyTy
      let names = ctxEntries ctxP
      withPatternRefinements patternRefinements $
        forM_ (zip [0 ..] names) $ \(i, entry) -> do
          let proj =
                CMatch
                  bodyTm
                  (Just bodyTyTm)
                  Nothing
                  [CaseAlt patC Nothing (CVar i)]
          g <- ownName (Name (ceName entry) sp)
          projV <- evalIn emptyCtx proj
          addGlobal
            g
            ( globalDefWithObservationMode
                (ceMode entry)
                (GlobalDef (ceType entry) (Just projV) True)
            )
          recordCoreBody g proj
elabLetDecl _ _ sp =
  unsupportedAt sp "this let-definition form is not supported at top level"

withActiveUniverseDefinition :: GName -> CheckM a -> CheckM a
withActiveUniverseDefinition g action = do
  before <- get
  result <- withActiveUniverseDefinitionRaw g action
  after <- get
  synchronizeGeneratedConstraintInterfacesFor
    (Just (generatedConstraintInterfacesAffectedBy g before after))
    before
  pure result

withRecursiveSchemaOccurrenceRecording :: CheckM a -> CheckM a
withRecursiveSchemaOccurrenceRecording action = do
  previous <- gets csRecordRecursiveSchemaOccurrences
  modify' $ \state -> state {csRecordRecursiveSchemaOccurrences = True}
  result <- action
  modify' $ \state -> state {csRecordRecursiveSchemaOccurrences = previous}
  pure result

-- | Run one owner-scoped solver action and make its pending proof telescope
-- physical, but leave publication to the enclosing transaction.  Keeping this
-- operation separate prevents a publication worklist from recursively
-- re-entering itself while the current delta wave is only half repaired.
withActiveUniverseDefinitionRaw :: GName -> CheckM a -> CheckM a
withActiveUniverseDefinitionRaw g action = do
  previous <- gets csActiveUniverseDefinition
  modify' $ \st -> st {csActiveUniverseDefinition = Just g}
  result <- action
  materializePendingUniverseProofsRaw g
  modify' $ \st -> st {csActiveUniverseDefinition = previous}
  pure result

occursGlobal :: GName -> Term -> Bool
occursGlobal g = Set.member g . globalsOfTerm

expandedGlobalsOfTermM :: Term -> CheckM (Set GName)
expandedGlobalsOfTermM tm = do
  st <- get
  pure (expandedGlobalsOfTerm st tm)

expandedGlobalsOfTerm :: CheckState -> Term -> Set GName
expandedGlobalsOfTerm st =
  Termination.expandedGlobalsOfTerm $ \global -> do
    definition <- Map.lookup global (csGlobals st)
    pure (gdReducible definition, Map.lookup global (csCoreBodies st))

-- Termination verification (§15.3/§15.11, SCC-level).
--
-- A recursive definition is conversion-reducible only after this pass proves
-- that its whole strongly-connected component terminates.  The checker uses
-- two independent certificates:
--
--   * explicit ranking functions from `decreases`, checked on every call edge
--     f -> g by comparing g's measure at the call with f's measure at entry;
--   * size-change graphs for structural recursion, including mutual SCCs.
--
-- Surface helper names are not trusted by spelling.  Terms are normalized
-- through already-reducible globals, beta/iota/projection reduction, and then
-- classified only when primitive arithmetic semantics remain inspectable.
-- External solver results are not used to make definitions
-- conversion-reducible until there is an explicit trusted-boundary artifact
-- that records the replay data required by §15.9.
terminationSccPass :: CheckM ()
terminationSccPass = do
  st <- get
  let decls = Map.filterWithKey (\g _ -> Set.member g (csTerminationNames st)) (csTerminationDecls st)
      declKeys = Map.keysSet decls
  dependencyPairs <-
    forM (Map.elems decls) $ \td -> do
      let dependencies =
            Set.intersection declKeys (expandedGlobalsOfTerm st (tdCoreBody td))
      pure (td, dependencies)
  let dependencyMap =
        Map.fromList [(tdName td, dependencies) | (td, dependencies) <- dependencyPairs]
      depsOf td = Set.toList (Map.findWithDefault Set.empty (tdName td) dependencyMap)
      nodes = [(td, tdName td, depsOf td) | (td, _) <- dependencyPairs]
      sccs = stronglyConnComp nodes
      selfCycle td =
        tdName td
          `Set.member` Map.findWithDefault Set.empty (tdName td) dependencyMap
      recursiveGroups =
        [ group
        | scc <- sccs
        , group <- case scc of
            AcyclicSCC td | selfCycle td -> [[td]]
            CyclicSCC tds -> [tds]
            _ -> []
        ]
  classifyRecursiveSchemaOccurrences recursiveGroups
  -- Acyclic definitions may be unfolded while checking recursive SCCs.  This
  -- is safe even when such a helper mentions an unverified recursive function:
  -- unfolding the helper exposes that opaque function but cannot create a new
  -- conversion cycle through the helper itself.
  forM_ sccs $ \case
    AcyclicSCC td | not (selfCycle td) -> setGlobalReducible (tdName td) True
    _ -> pure ()
  verifyRecursiveGroups recursiveGroups
  where
    verifyRecursiveGroups [] = pure ()
    verifyRecursiveGroups groups = go groups
      where
        go pending = do
          results <- forM pending $ \tds -> do
            overrides <- gets csAssertReducible
            admissions <- gets csAssertTerminates
            let forced = all (`Set.member` overrides) (map tdName tds)
                admitted = all (`Set.member` admissions) (map tdName tds)
            result <-
              if forced then pure TerminationConversionSafe else withSccOpaque (map tdName tds) (verifyTerminationScc tds)
            case result of
              TerminationConversionSafe -> forM_ tds (\td -> setGlobalReducible (tdName td) True)
              TerminationTotalOnly -> forM_ tds (\td -> setGlobalReducible (tdName td) False)
              TerminationUnverified
                | admitted ->
                    forM_ tds (\td -> setGlobalReducible (tdName td) False)
              TerminationUnverified -> pure ()
            pure
              ( tds
              , if result == TerminationUnverified && admitted
                  then TerminationTotalOnly
                  else result
              )
          let failed = [tds | (tds, TerminationUnverified) <- results]
              madeProgress = any ((/= TerminationUnverified) . snd) results
          if null failed
            then pure ()
            else if madeProgress
              then go failed
              else forM_ failed rejectUnverified

    rejectUnverified tds = do
      overrides <- gets csAssertReducible
      occurrences <- gets csRecursiveSchemaOccurrences
      let names = Set.fromList (map tdName tds)
          forced = all (`Set.member` overrides) (map tdName tds)
      if forced
        then forM_ tds $ \td -> setGlobalReducible (tdName td) True
        else do
          forM_ tds $ \td -> setGlobalReducible (tdName td) False
          forM_ tds $ \td -> do
            let sites =
                  nub
                    [ rsoSpan occurrence
                    | occurrence <- occurrences
                    , rsoCaller occurrence == tdName td
                    , rsoCallee occurrence `Set.member` names
                    , rsoSpan occurrence /= noSpan
                    ]
            reportUnverifiedTermination
              (tdSpan td)
              sites
              ("could not verify termination of '" <> gnameText (tdName td) <> "' (§15)")
              "the recursive SCC has no checked well-founded decrease and is rejected because Kappa is total by default (§15.1–§15.2)"

reportUnverifiedTermination :: Span -> [Span] -> Text -> Text -> CheckM ()
reportUnverifiedTermination declarationSite callSites message note =
  forM_ primarySites $ \primarySite ->
    report $
      withNote note $
        addOrigins primarySite $
          diag
            SevError
            StageElaborate
            "E_TERMINATION_UNVERIFIED"
            (Just "kappa.termination.failure")
            primarySite
            message
  where
    sites = nub (filter (/= noSpan) callSites)
    primarySites = if null sites then [declarationSite] else sites
    addOrigins primarySite diagnostic =
      let withDeclaration
            | declarationSite == noSpan || declarationSite == primarySite = diagnostic
            | otherwise =
                withRelated
                  (related RoleDeclarationSite declarationSite "recursive declaration")
                  diagnostic
       in foldl'
            (\current site ->
               if site == primarySite
                 then current
                 else
                   withRelated
                     (related RoleCallSite site "other recursive call considered in this unverified SCC")
                     current)
            withDeclaration
            sites

classifyRecursiveSchemaOccurrences :: [[TerminationDecl]] -> CheckM ()
classifyRecursiveSchemaOccurrences groups = do
  st <- get
  let assignments = csLevelAssignments st
      groupSets = map (Set.fromList . map tdName) groups
      recursive occurrence =
        any
          (\members -> rsoCaller occurrence `Set.member` members && rsoCallee occurrence `Set.member` members)
          groupSets
          && ( declarationUniverseArity (rsoCaller occurrence) > 0
                 || declarationUniverseArity (rsoCallee occurrence) > 0
             )
      declarationUniverseArity global =
        maybe 0 (dutParameterCount . gdUniverses) (Map.lookup global (csGlobals st))
      occurrences = filter recursive (reverse (csRecursiveSchemaOccurrences st))
  forM_ occurrences $ \occurrence -> do
    current <- get
    let recursiveMembers =
          fromMaybe Set.empty . listToMaybe $
            [ members
            | members <- groupSets
            , rsoCaller occurrence `Set.member` members
            , rsoCallee occurrence `Set.member` members
            ]
        completeExplicitScc =
          all
            (\member ->
              member `Set.member` csTerminationNames current
                && maybe False (dutExplicit . gdUniverses)
                     (Map.lookup member (csGlobals current)))
            (Set.toList recursiveMembers)
        callerArity =
          maybe 0 (dutParameterCount . gdUniverses)
            (Map.lookup (rsoCaller occurrence) (csGlobals current))
        sourceLevels = map LParam [0 .. callerArity - 1]
        ownerAssignments =
          Map.union
            (Map.findWithDefault Map.empty (rsoCaller occurrence)
              (csFinalizedGlobalUniverseMetaMaps current))
            assignments
        rawOccurrenceLevels = rsoLevels occurrence
        occurrenceLevels =
          case Map.lookup
                 (rsoCallee occurrence, length rawOccurrenceLevels)
                 (provisionalUniverseProjections current (rsoCallee occurrence)) of
            Just projection
              | urpSourceArity projection == length rawOccurrenceLevels ->
                  [rawOccurrenceLevels !! position | position <- urpRetainedPositions projection]
            _ -> rawOccurrenceLevels
        targetLevels = map (normalizeLevel . substituteLevelMetas ownerAssignments) occurrenceLevels
        occurrenceAssumptions = substituteLevelAssumptions ownerAssignments (rsoAssumptions occurrence)
        identity =
          length sourceLevels == length targetLevels
            && and (zipWith (==) (map normalizeLevel sourceLevels) targetLevels)
        pointwise =
          length sourceLevels == length targetLevels
            && and
              [ proveLevelLeq occurrenceAssumptions target source == Proved
              | (target, source) <- zip targetLevels sourceLevels
              ]
        strict =
          pointwise
            && or
              [ proveLevelLeq occurrenceAssumptions (levelSucc target) source == Proved
              | (target, source) <- zip targetLevels sourceLevels
              ]
        site
          | rsoSpan occurrence == noSpan =
              Map.findWithDefault noSpan (rsoCaller occurrence) (csDeclSites current)
          | otherwise = rsoSpan occurrence
        edge relation =
          modify' $ \state ->
            state
              { csRecursiveSchemaEdges =
                  Set.insert
                    (RecursiveSchemaEdge (rsoCaller occurrence) (rsoCallee occurrence) relation)
                    (csRecursiveSchemaEdges state)
              }
    if identity
      then edge RecursiveSchemaIdentity
      else if not (rsoExplicit occurrence) || not completeExplicitScc
        then
          report $
            withPayload
              ( withPayloadField "caller" (gKey (rsoCaller occurrence)) $
                  withPayloadField "callee" (gKey (rsoCallee occurrence)) $
                    withPayloadField "completeExplicitRecursiveScc" (if completeExplicitScc then "true" else "false") $
                      withPayloadField "sourceInstance" (T.intercalate ", " (map renderLevel sourceLevels)) $
                        withPayloadField "targetInstance" (T.intercalate ", " (map renderLevel targetLevels)) $
                          payloadKind "universe-recursive-schema-implicit"
              ) $
              diag SevError StageElaborate "E_UNIVERSE_RECURSIVE_SCHEMA_IMPLICIT"
                (Just "kappa.universe.recursive-schema") site
                "a non-identity recursive declaration-schema call requires an explicit .{...} instance and complete explicit signatures and schemas for the whole SCC (§11.1.2.3A)"
        else if pointwise
          then edge (if strict then RecursiveSchemaStrictLower else RecursiveSchemaLowerOrEqual)
          else
            report $
              withPayload
                ( withPayloadField "caller" (gKey (rsoCaller occurrence)) $
                    withPayloadField "callee" (gKey (rsoCallee occurrence)) $
                      withPayloadField "sourceInstance" (T.intercalate ", " (map renderLevel sourceLevels)) $
                        withPayloadField "targetInstance" (T.intercalate ", " (map renderLevel targetLevels)) $
                          payloadKind "universe-recursive-schema-increase"
                ) $
                diag SevError StageElaborate "E_UNIVERSE_RECURSIVE_SCHEMA_INCREASE"
                  (Just "kappa.universe.recursive-schema") site
                  "a recursive declaration-schema instance must be pointwise same-or-lower than the current SCC instance (§11.1.2.3A)"

withSccOpaque :: [GName] -> CheckM a -> CheckM a
withSccOpaque gs act = do
  saved <- gets csGlobals
  let restore acc g = case Map.lookup g saved of
        Just gd -> Map.insert g gd acc
        Nothing -> acc
  modify' $ \st ->
    invalidateSemanticCaches
      (st {csGlobals = foldr (Map.adjust (\gd -> gd {gdReducible = False})) (csGlobals st) gs})
  r <- act
  modify' $ \st ->
    invalidateSemanticCaches (st {csGlobals = List.foldl' restore (csGlobals st) gs})
  pure r

setGlobalReducible :: GName -> Bool -> CheckM ()
setGlobalReducible g ok =
  modify' $ \st ->
    invalidateSemanticCaches
      (st {csGlobals = Map.adjust (\gd -> gd {gdReducible = ok}) g (csGlobals st)})

verifyTerminationScc :: [TerminationDecl] -> CheckM TerminationResult
verifyTerminationScc = verifyTerminationSccIn emptyCtx

-- | Check a recursive SCC whose functions close over an already-checked
-- lexical context. Top-level declarations use 'emptyCtx'; instance members
-- use their instance-parameter and premise context. Keeping the ambient depth
-- explicit lets the same symbol- and Core-based solver reason about captured
-- values without re-encoding them as synthetic runtime arguments.
verifyTerminationSccIn :: Ctx -> [TerminationDecl] -> CheckM TerminationResult
verifyTerminationSccIn ambient tds = do
  funs <- mapM (prepareTermFunIn ambient) tds
  let funMap = Map.fromList [(tfName f, f) | f <- funs]
      explicit = [tdDecreases (tfDecl f) | f <- funs]
  case explicit of
    _ | all isNothing explicit -> do
          structural <- structuralSccOK funMap Nothing
          if structural
            then pure TerminationConversionSafe
            else boolCert TerminationTotalOnly <$> inferredMeasureSccOK funMap
      | any isNothing explicit -> pure TerminationUnverified
      | all isStructuralDec explicit -> do
          valid <- validateStructuralSelections funs
          if valid
            then boolCert TerminationConversionSafe <$> structuralSccOK funMap (Just (structuralSelections funs))
            else pure TerminationUnverified
      | all isMeasureDec explicit -> do
          -- A `decreases <measure>` annotation states intent, but if the
          -- recursion is in fact STRUCTURAL — the recursive call passes a
          -- constructor sub-term of an argument (e.g. `decreases listLength
          -- xs` recursing on the tail of `xs`) — accept it by structural
          -- descent. Structural descent is the stronger, conversion-safe
          -- guarantee and subsumes any size-like measure: the recursion
          -- demonstrably terminates regardless of the (possibly
          -- non-arithmetic) measure the author named. Fall back to the
          -- arithmetic measure proof for genuinely non-structural measures
          -- (e.g. `decreases fuel` / `decreases max 0 n` on an Int counter).
          --
          -- Certify TOTALITY only (TerminationTotalOnly), NOT conversion
          -- safety: an explicit `decreases` measure signals the author
          -- intends a *total* (not necessarily δ-reducible) definition, and
          -- granting conversion-reducibility here would change how the body
          -- unfolds during conversion — perturbing downstream analyses such
          -- as match exhaustiveness. Clearing the termination warning must
          -- not silently alter reduction behavior.
          struct <- structuralSccOK funMap Nothing
          if struct
            then pure TerminationTotalOnly
            else boolCert TerminationTotalOnly <$> measureSccOK funMap
      | otherwise -> pure TerminationUnverified
  where
    boolCert yes ok = if ok then yes else TerminationUnverified
    isStructuralDec = \case
      Just DecStructural {} -> True
      _ -> False
    isMeasureDec = \case
      Just DecMeasure {} -> True
      _ -> False
    structuralSelections funs =
      Map.fromList
        [ (tfName f, ns)
        | f <- funs
        , Just (DecStructural xs) <- [tdDecreases (tfDecl f)]
        , let ns = map nameText xs
        ]
    validateStructuralSelections funs = and <$> mapM validateOne funs
    validateOne f =
      case tdDecreases (tfDecl f) of
        Just (DecStructural xs) -> do
          oks <- forM xs $ \x -> do
            let nm = nameText x
            if nm `elem` tfParamNames f
              then pure True
              else do
                report $
                  diag SevError StageElaborate "E_TERMINATION_INVALID_STRUCTURAL_TARGET" (Just "kappa.termination.invalid_structural_target") (nameSpan x)
                    ( "decreases structural target '" <> nm <> "' is not an explicit parameter of '"
                        <> gnameText (tfName f)
                        <> "' (§15.3)"
                    )
                pure False
          pure (and oks)
        _ -> pure True

data InferredMeasureShape
  = InferredParameter !Int
  | InferredDifference !Int !Int
  | InferredDifferencePlusOne !Int !Int
  | InferredSuccessorDifference !Int !Int
  deriving stock (Eq, Show)

-- | Try the bounded, deterministic ranking-function fragment required by
-- §§15.5-15.8 when no explicit @decreases@ clause is present. Candidates are
-- formed from typed explicit parameters only: each arithmetic parameter, then
-- each ordered difference of two integer parameters. Every candidate is
-- handed to the same proof-producing call-edge checker used for explicit
-- measures; no source spelling or unchecked heuristic can certify an SCC.
inferredMeasureSccOK :: Map GName TermFun -> CheckM Bool
inferredMeasureSccOK funMap
  | Map.null funMap = pure False
  | otherwise = tryShapes candidateShapes
  where
    functions = Map.elems funMap
    sharedArity = minimum (map (length . tfExplParams) functions)
    candidateShapes =
      [InferredParameter index | index <- [0 .. sharedArity - 1]]
        ++ [ InferredDifference left right
           | left <- [0 .. sharedArity - 1]
           , right <- [0 .. sharedArity - 1]
           , left /= right
           ]
        ++ [ InferredDifferencePlusOne left right
           | left <- [0 .. sharedArity - 1]
           , right <- [0 .. sharedArity - 1]
           , left /= right
           ]
        ++ [ InferredSuccessorDifference left right
           | left <- [0 .. sharedArity - 1]
           , right <- [0 .. sharedArity - 1]
           , left /= right
           ]

    tryShapes [] = pure False
    tryShapes (shape : rest) = do
      measured <- traverse (withInferredMeasure shape) funMap
      case sequence measured of
        Nothing -> tryShapes rest
        Just candidateMap -> do
          accepted <- measureSccOK candidateMap
          if accepted then pure True else tryShapes rest

withInferredMeasure :: InferredMeasureShape -> TermFun -> CheckM (Maybe TermFun)
withInferredMeasure shape function = do
  candidate <- case shape of
    InferredParameter index -> do
      parameter <- arithmeticParameter function index
      pure $ do
        (term, _, domain) <- parameter
        typeKey <- arithmeticMeasureTypeKey domain
        pure (term, typeKey)
    InferredDifference leftIndex rightIndex ->
      integerPairCandidate leftIndex rightIndex intSub
    InferredDifferencePlusOne leftIndex rightIndex ->
      integerPairCandidate leftIndex rightIndex $ \left right ->
        intAdd (intSub left right) (CLit (LitInt 1))
    InferredSuccessorDifference leftIndex rightIndex ->
      integerPairCandidate leftIndex rightIndex $ \left right ->
        intSub (intAdd left (CLit (LitInt 1))) right
  pure $ do
    (measure, typeKey) <- candidate
    pure
      function
        { tfMeasure =
            Just
              MeasureSpec
                { msMeasureTerm = measure
                , msMeasureTypeKey = typeKey
                , msRelation = Nothing
                , msProof = Nothing
                , msDepth = tfDepth function
                }
        }
  where
    integerPairCandidate leftIndex rightIndex build = do
      left <- arithmeticParameter function leftIndex
      right <- arithmeticParameter function rightIndex
      pure $ do
        (leftTerm, _, leftDomain) <- left
        (rightTerm, _, rightDomain) <- right
        guard (leftDomain == ArithmeticInteger)
        guard (rightDomain == ArithmeticInteger)
        typeKey <- arithmeticMeasureTypeKey leftDomain
        pure (build leftTerm rightTerm, typeKey)

    intAdd = integerBinary "addInt"
    intSub = integerBinary "subInt"
    integerBinary operation left right =
      CApp Expl (CApp Expl (CGlob (gPrel operation)) left) right

arithmeticParameter
  :: TermFun
  -> Int
  -> CheckM (Maybe (Term, Term, ArithmeticDomain))
arithmeticParameter function parameterIndex =
  case nthMaybe parameterIndex (tfExplParams function) of
    Nothing -> pure Nothing
    Just level ->
      case nthMaybe (tfDepth function - level - 1) (ctxEntries (tfCtx function)) of
        Nothing -> pure Nothing
        Just entry -> do
          typeKey <-
            quoteIn (tfCtx function) (ceType entry)
              >>= normalizeTermAt (tfDepth function)
          pure $ do
            domain <- arithmeticDomainForCarrier typeKey
            pure
              ( CVar (tfDepth function - level - 1)
              , typeKey
              , domain
              )

arithmeticMeasureTypeKey :: ArithmeticDomain -> Maybe Term
arithmeticMeasureTypeKey = \case
  ArithmeticNatural -> Just (CGlob prelNat)
  ArithmeticInteger -> Just (CGlob prelInteger)
  ArithmeticTypeLevel -> Nothing
  ArithmeticProviderLaw -> Nothing

-- Compatibility wrapper used by a few older call sites and useful in ghci.
-- The real implementation above works over SCCs; a singleton self-SCC is the
-- direct-recursion special case, not a separate algorithm.
terminationOK :: GName -> Value -> [Binder] -> Maybe Decreases -> Term -> CheckM Bool
terminationOK g sigTy binders mdec tm =
  (/= TerminationUnverified) <$> verifyTerminationScc [TerminationDecl g sigTy binders mdec tm noSpan]

data TermFun = TermFun
  { tfDecl :: !TerminationDecl
  , tfName :: !GName
  , tfCtx :: !Ctx
  , tfNatLvls :: !(Set Int)
  , tfParams :: ![(Icit, Int)]
  , tfExplParams :: ![Int]
  , tfParamNames :: ![Text]
  , tfBody :: !Term
  , tfDepth :: !Int
  , tfMeasure :: !(Maybe MeasureSpec)
  }

data MeasureSpec = MeasureSpec
  { msMeasureTerm :: !Term
  , msMeasureTypeKey :: !Term
  , msRelation :: !(Maybe RelationSpec)
  , msProof :: !(Maybe Expr)
  , msDepth :: !Int
  }

data RelationSpec = RelationSpec
  { rsTerm :: !Term
  , rsTypeKey :: !Term
  , rsFlavor :: !RelationFlavor
  , rsKey :: !Term
  , rsDepth :: !Int
  , rsWellFounded :: !Bool
  }

data RelationFlavor = RelationReturnsType | RelationReturnsBool | RelationUnknown
  deriving stock (Eq, Show)

-- | Reconstruct the source telescope used when elaborating a decreases
-- expression.  This mirrors the signature-driven lambda elaborator: implicit
-- binders present in the signature but absent from the source are still placed
-- in the context, while explicit source binders keep their written names.
measureCtxFromSig :: Value -> [Binder] -> CheckM Ctx
measureCtxFromSig = measureCtxFromSigIn emptyCtx

measureCtxFromSigIn :: Ctx -> Value -> [Binder] -> CheckM Ctx
measureCtxFromSigIn initial sigTy binders = go initial sigTy binders
  where
    go ctx _ [] = pure ctx
    go ctx ty0 bs@(b : rest) = do
      ty <- forceM ty0
      case ty of
        VPiBoundM _ Impl q _ nm assumption dom clo
          | not (bImplicit b)
          , (nameText <$> bName b) /= Just nm -> do
              cod <- clApp clo (VRigid (ctxLen ctx) [])
              withBound <- extendLevelAssumption (bSpan b) ctx assumption
              go (bindCtxQ q nm True dom withBound) cod bs
        VPiBoundM _ _ q _ nm assumption dom clo -> do
          let bn = fromMaybe nm (nameText <$> bName b)
          cod <- clApp clo (VRigid (ctxLen ctx) [])
          withBound <- extendLevelAssumption (bSpan b) ctx assumption
          go (bindCtxQ q bn (bImplicit b) dom withBound) cod rest
        _ -> pure ctx

ctxNatLevels :: Ctx -> CheckM (Set Int)
ctxNatLevels ctx =
  Set.fromList . catMaybes <$>
    forM (zip [0 :: Int ..] (ctxEntries ctx)) (\(i, e) -> do
      ty <- forceM (ceType e)
      let lvl = ctxLen ctx - 1 - i
      pure $ case ty of
        VGlobN g [] | g == prelNat -> Just lvl
        _ -> Nothing)

prepareTermFun :: TerminationDecl -> CheckM TermFun
prepareTermFun = prepareTermFunIn emptyCtx

prepareTermFunIn :: Ctx -> TerminationDecl -> CheckM TermFun
prepareTermFunIn ambient td = do
  ctx <- measureCtxFromSigIn ambient (tdSigType td) (tdBinders td)
  natLvls <- ctxNatLevels ctx
  let (params, body, depth0) =
        peelTermParamsAt (ctxLen ambient) (tdCoreBody td)
      explParams = [lvl | (Expl, lvl) <- params]
      explNames = [nameText n | b <- tdBinders td, not (bImplicit b), Just n <- [bName b]]
  mSpec <- case tdDecreases td of
    Just (DecMeasure measure byRel usingProof) -> do
      (m0, mTy0) <- infer ctx measure
      (mTm0, mTy) <- insertAllImplicits ctx (exprSpan measure) m0 mTy0
      mTyKey <- quoteIn ctx mTy >>= normalizeTermAt (ctxLen ctx)
      relSpec <- traverse (prepareRelationSpec ctx (ctxLen ctx) mTy) byRel
      -- Store the elaborated measure itself.  Recursive-call checking
      -- normalizes it after the SCC pass has marked acyclic helpers
      -- reducible, so transparent helper arithmetic is exposed without
      -- trusting helper names during initial declaration checking.
      pure (Just (MeasureSpec mTm0 mTyKey relSpec usingProof (ctxLen ctx)))
    _ -> pure Nothing
  pure
    TermFun
      { tfDecl = td
      , tfName = tdName td
      , tfCtx = ctx
      , tfNatLvls = natLvls
      , tfParams = params
      , tfExplParams = explParams
      , tfParamNames = explNames
      , tfBody = body
      , tfDepth = depth0
      , tfMeasure = mSpec
      }

prepareRelationSpec :: Ctx -> Int -> Value -> Expr -> CheckM RelationSpec
prepareRelationSpec ctx d measureTy relE = do
  checkedType <- tryRelationCheck ctx measureTy relE RelationReturnsType
  checked <- case checkedType of
    Just ok -> pure (Just ok)
    Nothing -> tryRelationCheck ctx measureTy relE RelationReturnsBool
  case checked of
    Just (rTm0, rTy, flavor) -> do
      rTm <- normalizeTermAt d rTm0
      rTyKey <- quoteIn ctx rTy >>= normalizeTermAt d
      rKey <- relationCanonicalKey d flavor rTm
      wf <- relationWellFoundedEvidence ctx d measureTy rTm flavor
      pure (RelationSpec rTm rTyKey flavor rKey d wf)
    Nothing -> do
      -- Keep the relation syntactically available for diagnostics and keys,
      -- but classify it as unusable for termination.  This path is reached
      -- only after the expression failed to check as either
      -- m -> m -> Type or m -> m -> Bool.
      (r0, rTy0) <- infer ctx relE
      (rTm0, rTy) <- insertAllImplicits ctx (exprSpan relE) r0 rTy0
      rTm <- normalizeTermAt d rTm0
      rTyKey <- quoteIn ctx rTy >>= normalizeTermAt d
      rKey <- relationCanonicalKey d RelationUnknown rTm
      pure (RelationSpec rTm rTyKey RelationUnknown rKey d False)

relationCanonicalKey :: Int -> RelationFlavor -> Term -> CheckM Term
relationCanonicalKey d flavor relTm = do
  isLt <- case flavor of
    RelationReturnsBool -> relationIsPrimitiveLtInt d relTm
    _ -> pure False
  if isLt
    then pure (CGlob (gPrel "ltInt"))
    else normalizeTermAt d relTm

relationIsPrimitiveLtInt :: Int -> Term -> CheckM Bool
relationIsPrimitiveLtInt d relTm = do
  relNorm <- normalizeTermAt d relTm
  if directLt relNorm
    then pure True
    else do
      let x = CVar 1
          y = CVar 0
          relUnderBinders = shiftTerm 2 0 relNorm
          applied = CApp Expl (CApp Expl relUnderBinders x) y
      appliedNorm <- normalizeTermAt (d + 2) applied
      pure $ case spineOfTerm appliedNorm of
        (CGlob g, args)
          | intCmpPrim g == Just PrimLtInt ->
              case last2 [a | (Expl, a) <- args] of
                Just (a, b) -> a == x && b == y
                Nothing -> False
        _ -> False
  where
    directLt = \case
      CGlob g -> intCmpPrim g == Just PrimLtInt
      _ -> False

tryRelationCheck :: Ctx -> Value -> Expr -> RelationFlavor -> CheckM (Maybe (Term, Value, RelationFlavor))
tryRelationCheck ctx measureTy relE flavor = do
  expected <- relationExpectedType ctx measureTy flavor
  saved <- get
  let diagCount0 = length (csDiags saved)
  r0 <- withDemand DemandRead (check ctx relE expected)
  diagCount1 <- gets (length . csDiags)
  if diagCount1 == diagCount0
    then do
      rTm <- zonkTermM (ctxLen ctx) r0
      pure (Just (rTm, expected, flavor))
    else put saved >> pure Nothing

relationExpectedType :: Ctx -> Value -> RelationFlavor -> CheckM Value
relationExpectedType ctx measureTy flavor = do
  mTyTm <- quoteIn ctx measureTy
  let cod = case flavor of
        RelationReturnsType -> CSort LZero
        RelationReturnsBool -> CGlob prelBool
        RelationUnknown -> CSort LZero
      tyTm = CPiFormedM Ordinary FormationOrdinary Expl QW False "_x" mTyTm (CPiFormedM Ordinary FormationOrdinary Expl QW False "_y" (shiftTerm 1 0 mTyTm) cod)
  evalIn ctx tyTm

-- | Evidence that an explicit `by R` relation is well-founded.  The current
-- surface language exposes well-foundedness through `WellFoundedRelation A`:
-- if instance search can synthesize such a dictionary and its `rel` member is
-- definitionally equal to R, then R carries the same well-founded order.  This
-- keeps proof-directed decreases conservative: a per-call proof proves only
-- the local descent fact; the relation itself still needs a well-founded
-- source.
relationWellFoundedEvidence :: Ctx -> Int -> Value -> Term -> RelationFlavor -> CheckM Bool
relationWellFoundedEvidence _ctx _d _measureTy _relTm flavor = do
  case flavor of
    -- The current prelude exposes `WellFoundedRelation.rel`, but not a real
    -- inspectable accessibility proof.  Treating erased placeholders as
    -- well-foundedness would make arbitrary user relations acceptable, so
    -- Type-valued relations remain uncertified here.
    RelationReturnsType -> pure False
    -- Bool-valued relations are a compiler convenience for primitive orders.
    -- They are accepted without an explicit WF dictionary only when the
    -- arithmetic/normalization prover can decide the call-site fact itself.
    -- A user proof for an arbitrary Bool relation does not make the relation
    -- well-founded.
    _ -> pure False

peelTermParams :: Term -> ([(Icit, Int)], Term, Int)
peelTermParams = peelTermParamsAt 0

peelTermParamsAt :: Int -> Term -> ([(Icit, Int)], Term, Int)
peelTermParamsAt initialDepth = go [] initialDepth
  where
    go acc d = \case
      CLam ic _ _ b -> go (acc ++ [(ic, d)]) (d + 1) b
      t -> (acc, t, d)

-- ── SCC call-edge collection ─────────────────────────────────────────

data CallEdge = CallEdge
  { edgeFrom :: !GName
  , edgeTo :: !GName
  , edgeUniverses :: ![Level]
  , edgeDepth :: !Int
  , edgeFacts :: ![AFact]
  , edgeBoolFacts :: ![(Term, Bool)]
  , edgeArgs :: ![(Icit, Term)]
  , edgeStructuralOrigins :: !StructuralOrigins
  }
  deriving stock (Show)

data StructuralStep
  = StructuralPosition !Int
  | StructuralField !Text
  | StructuralVariant !Text
  deriving stock (Eq, Ord, Show)

data StructuralOrigin = StructuralOrigin
  { structuralRoot :: !Int
  , structuralPath :: ![StructuralStep]
  }
  deriving stock (Eq, Ord, Show)

data StructuralShape
  = StructuralCtor !GName ![Level]
  | StructuralLiteral !Literal
  deriving stock (Eq, Ord, Show)

data StructuralOrigins = StructuralOrigins
  { structuralLocals :: !(Map Int (Set StructuralOrigin))
  , structuralShapes :: !(Map StructuralShape (Set StructuralOrigin))
  }
  deriving stock (Eq, Show)

collectSccEdges :: Map GName TermFun -> CheckM (Maybe [CallEdge])
collectSccEdges funMap = do
  edges <- mapM (collectFunEdges funMap) (Map.elems funMap)
  pure (concat <$> sequence edges)

data PartialCall = PartialCall
  { pcTarget :: !GName
  , pcUniverses :: ![Level]
  , pcDepth :: !Int
  , pcArgs :: ![(Icit, Term)]
  }
  deriving stock (Show)

collectFunEdges :: Map GName TermFun -> TermFun -> CheckM (Maybe [CallEdge])
collectFunEdges funMap src =
  go (tfDepth src) parameterOrigins Map.empty Set.empty [] [] (tfBody src)
  where
    sccNames = Map.keysSet funMap
    parameterOrigins =
      StructuralOrigins
        { structuralLocals =
            Map.fromList
              [ (level, Set.singleton (StructuralOrigin level []))
              | level <- tfExplParams src
              ]
        , structuralShapes = Map.empty
        }

    go :: Int -> StructuralOrigins -> Map Int PartialCall -> Set Int -> [AFact] -> [(Term, Bool)] -> Term -> CheckM (Maybe [CallEdge])
    go d sub ho esc facts boolFacts t = case t of
      CApp {} -> do
        case partialCallOf d ho t of
          Just pc | Set.member (pcTarget pc) sccNames, partialCallComplete pc ->
            collectApplication d sub ho esc facts boolFacts t
          _ ->
            if containsSccReference d ho esc t
              then do
                tNorm <- normalizeTermAt d t
                if tNorm /= t
                  -- §15.11: transparent higher-order helpers are part of the
                  -- semantic call shape.  Do not reject the pre-normalized term
                  -- just because it appears to pass a partial recursive closure
                  -- through a helper; unfold the helper first, then classify the
                  -- actual application that remains.  However, transparent
                  -- normalization must not erase recursive calls that occur while
                  -- evaluating strict helper arguments, such as `ignore (f n)`.
                  -- Collect complete recursive calls from the original strict
                  -- subterms and combine them with the normalized semantic edge.
                  -- Incomplete partial calls are not charged here; they are either
                  -- exposed by transparent normalization or rejected as opaque
                  -- higher-order escape by 'goArg'.
                  then joinEdges <$> collectStrictSubtermEdges d sub ho facts boolFacts t <*> go d sub ho esc facts boolFacts tNorm
                  else collectApplication d sub ho esc facts boolFacts t
              else collectApplication d sub ho esc facts boolFacts t
      CGlob callee | Set.member callee sccNames -> pure Nothing
      CVar i
        | Set.member (d - 1 - i) esc -> pure Nothing
      CVar i
        | Just pc0 <- Map.lookup (d - 1 - i) ho -> do
            let pc = instantiatePartialCall d pc0
                edge = CallEdge (tfName src) (pcTarget pc) (pcUniverses pc) d facts boolFacts (pcArgs pc) sub
            pure (Just [edge])
      CLam _ _ _ b -> go (d + 1) sub ho esc facts boolFacts b
      CPi _ _ _ _ a b -> joinEdges <$> go d sub ho esc facts boolFacts a <*> go (d + 1) sub ho esc facts boolFacts b
      CLet _ _ a b c -> do
        ra <- go d sub ho esc facts boolFacts a
        bNorm <-
          if containsSccReference d ho esc b
            then normalizeTermAt d b
            else pure b
        let normalizedPartial =
              if bNorm /= b
                then partialCallOf d ho bNorm
                else Nothing
        case partialCallOf d ho b <|> normalizedPartial of
          Just pc | not (partialCallComplete pc) -> do
            -- A let-bound partial SCC application is a first-class closure;
            -- track the closure and charge the recursive edge at each use.
            -- Its captured arguments are still checked for nested recursive
            -- calls, and any later escape as an opaque higher-order argument is
            -- rejected by 'goArg'.
            rbArgs <- joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts . snd) (pcArgs pc)
            let sub' = insertStructuralAlias d sub b
            rc <- go (d + 1) sub' (Map.insert d pc ho) esc facts boolFacts c
            pure (joinManyEdges [ra, rbArgs, rc])
          _ -> do
            let closureAlias =
                  recursiveClosureEscapes d ho esc b
                    || (bNorm /= b && recursiveClosureEscapes d ho esc bNorm)
                esc' = if closureAlias then Set.insert d esc else esc
                sub' = insertStructuralAlias d sub b
            join3Edges
              <$> pure ra
              <*> go d sub ho esc facts boolFacts b
              <*> go (d + 1) sub' ho esc' facts boolFacts c
      CLetRec _ _ a b c ->
        join3Edges
          <$> go d sub ho esc facts boolFacts a
          <*> go (d + 1) sub ho esc facts boolFacts b
          <*> go (d + 1) sub ho esc facts boolFacts c
      CIf c th el -> do
        rc <- go d sub ho esc facts boolFacts c
        c' <- normalizeTermAt d c
        trueFacts <- assumeBoolM d True c'
        falseFacts <- assumeBoolM d False c'
        rt <- go d sub ho esc (trueFacts ++ facts) ((c', True) : boolFacts) th
        re <- go d sub ho esc (falseFacts ++ facts) ((c', False) : boolFacts) el
        pure (joinManyEdges [rc, rt, re])
      CMatch scrut _ _ alts -> do
        rs <- go d sub ho esc facts boolFacts scrut
        let scrutOrigins = termStructuralOrigins d sub scrut
        ralts <- forM alts $ \(CaseAlt pat gd b) -> do
          let nb = patBindersC pat
              d' = d + nb
              sub' =
                recordMatchedStructuralShape scrutOrigins pat
                  (bindPatternStructuralOrigins d sub scrut pat)
              ho' = ho
          rg <- maybe (pure (Just [])) (go d' sub' ho' esc facts boolFacts) gd
          gd' <- traverse (normalizeTermAt d') gd
          patFacts <- comparePatternFactsM d scrut pat
          guardFacts <- maybe (pure []) (assumeBoolM d' True) gd'
          let facts' = guardFacts ++ patFacts ++ facts
              boolFacts' = maybe boolFacts (\guardTm -> (guardTm, True) : boolFacts) gd'
          rb <- go d' sub' ho' esc facts' boolFacts' b
          pure (joinEdges rg rb)
        pure (joinManyEdges (rs : ralts))
      CCtor _ _ as -> joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts) as
      CRecordT fs -> joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts . snd) fs
      CRecordV fs -> joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts . snd) fs
      CProj e _ -> go d sub ho esc facts boolFacts e
      CProjAt e _ _ -> go d sub ho esc facts boolFacts e
      CVariantT ms -> joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts) ms
      CInject _ e -> goArg d sub ho esc facts boolFacts e
      CThunkE e _ -> goArg d sub ho esc facts boolFacts e
      CLazyE e _ -> goArg d sub ho esc facts boolFacts e
      CForceE e _ -> go d sub ho esc facts boolFacts e
      CSealE _ e -> goArg d sub ho esc facts boolFacts e
      CSigT _ e -> goArg d sub ho esc facts boolFacts e
      CUniverseLift _ _ _ e -> go d sub ho esc facts boolFacts e
      CSchemaLift _ _ _ _ _ _ _ _ e -> go d sub ho esc facts boolFacts e
      CLetPolyM _ _ _ _ a b c ->
        join3Edges
          <$> go d sub ho esc facts boolFacts a
          <*> go d sub ho esc facts boolFacts b
          <*> go (d + 1) (insertStructuralAlias d sub b) ho esc facts boolFacts c
      CLetRecPolyM _ _ _ _ a b c ->
        join3Edges
          <$> go d sub ho esc facts boolFacts a
          <*> go (d + 1) sub ho esc facts boolFacts b
          <*> go (d + 1) sub ho esc facts boolFacts c
      CLetRecGroupM _ definitions body -> do
        let count = length definitions
            depth' = d + count
        types <- joinManyEdges <$> mapM (go d sub ho esc facts boolFacts . clrdType) definitions
        rhss <- joinManyEdges <$> mapM (go depth' sub ho esc facts boolFacts . clrdRhs) definitions
        bodyEdges <- go depth' sub ho esc facts boolFacts body
        pure (joinManyEdges [types, rhss, bodyEdges])
      CQuote _ slots -> joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts) slots
      CDo _ items -> goKItems d sub ho esc facts boolFacts items
      _ -> pure (Just [])

    collectApplication d sub ho esc facts boolFacts t =
      case partialCallOf d ho t of
        Just pc | Set.member (pcTarget pc) sccNames -> do
          argEdges <- joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts . snd) (pcArgs pc)
          let edge = CallEdge (tfName src) (pcTarget pc) (pcUniverses pc) d facts boolFacts (pcArgs pc) sub
          pure ((edge :) <$> argEdges)
        _ -> case spineOfTerm t of
          (f, args) -> do
            rf <- go d sub ho esc facts boolFacts f
            rs <- joinManyEdges <$> mapM (goArg d sub ho esc facts boolFacts . snd) args
            pure (joinEdges rf rs)

    -- Strict source subterms are still evaluated even when a transparent helper
    -- later normalizes away their value.  This traversal records only complete
    -- recursive calls.  It deliberately ignores incomplete partial recursive
    -- closures: a partial closure is not a call edge until transparent code
    -- applies it, and if opaque code receives it 'goArg' rejects the escape.
    collectStrictSubtermEdges :: Int -> StructuralOrigins -> Map Int PartialCall -> [AFact] -> [(Term, Bool)] -> Term -> CheckM (Maybe [CallEdge])
    collectStrictSubtermEdges d sub ho facts boolFacts t = case t of
      CApp {} -> do
        let here = case partialCallOf d ho t of
              Just pc | Set.member (pcTarget pc) sccNames, partialCallComplete pc ->
                Just [CallEdge (tfName src) (pcTarget pc) (pcUniverses pc) d facts boolFacts (pcArgs pc) sub]
              _ -> Just []
            (f, args) = spineOfTerm t
        children <- joinManyEdges <$> mapM (collectStrictSubtermEdges d sub ho facts boolFacts) (f : [a | (_, a) <- args])
        pure (joinEdges here children)
      CVar i
        | Just pc0 <- Map.lookup (d - 1 - i) ho -> do
            let pc = instantiatePartialCall d pc0
            pure $ case () of
              _ | Set.member (pcTarget pc) sccNames, partialCallComplete pc ->
                    Just [CallEdge (tfName src) (pcTarget pc) (pcUniverses pc) d facts boolFacts (pcArgs pc) sub]
                | otherwise -> Just []
      CLam {} -> pure (Just [])
      CThunkE {} -> pure (Just [])
      CLazyE {} -> pure (Just [])
      CQuote {} -> pure (Just [])
      CPi _ _ _ _ a b -> joinEdges <$> collectStrictSubtermEdges d sub ho facts boolFacts a <*> collectStrictSubtermEdges (d + 1) sub ho facts boolFacts b
      CLet _ _ a b c ->
        join3Edges
          <$> collectStrictSubtermEdges d sub ho facts boolFacts a
          <*> collectStrictSubtermEdges d sub ho facts boolFacts b
          <*> collectStrictSubtermEdges (d + 1) (insertStructuralAlias d sub b) ho facts boolFacts c
      CLetRec _ _ a b c ->
        join3Edges
          <$> collectStrictSubtermEdges d sub ho facts boolFacts a
          <*> collectStrictSubtermEdges (d + 1) sub ho facts boolFacts b
          <*> collectStrictSubtermEdges (d + 1) sub ho facts boolFacts c
      CIf c th el -> do
        rc <- collectStrictSubtermEdges d sub ho facts boolFacts c
        c' <- normalizeTermAt d c
        trueFacts <- assumeBoolM d True c'
        falseFacts <- assumeBoolM d False c'
        rt <- collectStrictSubtermEdges d sub ho (trueFacts ++ facts) ((c', True) : boolFacts) th
        re <- collectStrictSubtermEdges d sub ho (falseFacts ++ facts) ((c', False) : boolFacts) el
        pure (joinManyEdges [rc, rt, re])
      CMatch scrut _ _ alts -> do
        rs <- collectStrictSubtermEdges d sub ho facts boolFacts scrut
        let scrutOrigins = termStructuralOrigins d sub scrut
        ralts <- forM alts $ \(CaseAlt pat gd b) -> do
          let nb = patBindersC pat
              d' = d + nb
              sub' =
                recordMatchedStructuralShape scrutOrigins pat
                  (bindPatternStructuralOrigins d sub scrut pat)
          rg <- maybe (pure (Just [])) (collectStrictSubtermEdges d' sub' ho facts boolFacts) gd
          gd' <- traverse (normalizeTermAt d') gd
          patFacts <- comparePatternFactsM d scrut pat
          guardFacts <- maybe (pure []) (assumeBoolM d' True) gd'
          let facts' = guardFacts ++ patFacts ++ facts
              boolFacts' = maybe boolFacts (\guardTm -> (guardTm, True) : boolFacts) gd'
          rb <- collectStrictSubtermEdges d' sub' ho facts' boolFacts' b
          pure (joinEdges rg rb)
        pure (joinManyEdges (rs : ralts))
      CCtor _ _ as -> joinManyEdges <$> mapM (collectStrictSubtermEdges d sub ho facts boolFacts) as
      CRecordT fs -> joinManyEdges <$> mapM (collectStrictSubtermEdges d sub ho facts boolFacts . snd) fs
      CRecordV fs -> joinManyEdges <$> mapM (collectStrictSubtermEdges d sub ho facts boolFacts . snd) fs
      CProj e _ -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CProjAt e _ _ -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CVariantT ms -> joinManyEdges <$> mapM (collectStrictSubtermEdges d sub ho facts boolFacts) ms
      CInject _ e -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CForceE e _ -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CSealE _ e -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CSigT _ e -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CUniverseLift _ _ _ e -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CSchemaLift _ _ _ _ _ _ _ _ e -> collectStrictSubtermEdges d sub ho facts boolFacts e
      CLetPolyM _ _ _ _ a b c ->
        join3Edges
          <$> collectStrictSubtermEdges d sub ho facts boolFacts a
          <*> collectStrictSubtermEdges d sub ho facts boolFacts b
          <*> collectStrictSubtermEdges (d + 1) (insertStructuralAlias d sub b) ho facts boolFacts c
      CLetRecPolyM _ _ _ _ a b c ->
        join3Edges
          <$> collectStrictSubtermEdges d sub ho facts boolFacts a
          <*> collectStrictSubtermEdges (d + 1) sub ho facts boolFacts b
          <*> collectStrictSubtermEdges (d + 1) sub ho facts boolFacts c
      CLetRecGroupM _ definitions body -> do
        let count = length definitions
            depth' = d + count
        types <- joinManyEdges <$> mapM (collectStrictSubtermEdges d sub ho facts boolFacts . clrdType) definitions
        rhss <- joinManyEdges <$> mapM (collectStrictSubtermEdges depth' sub ho facts boolFacts . clrdRhs) definitions
        bodyEdges <- collectStrictSubtermEdges depth' sub ho facts boolFacts body
        pure (joinManyEdges [types, rhss, bodyEdges])
      CDo _ items -> collectStrictSubtermEdgesItems d sub ho facts boolFacts items
      _ -> pure (Just [])

    collectStrictSubtermEdgesItems
      :: Int
      -> StructuralOrigins
      -> Map Int PartialCall
      -> [AFact]
      -> [(Term, Bool)]
      -> [KItem]
      -> CheckM (Maybe [CallEdge])
    collectStrictSubtermEdgesItems _ _ _ _ _ [] = pure (Just [])
    collectStrictSubtermEdgesItems d sub ho facts boolFacts (item : rest) = do
      current <- collectStrictSubtermEdgesK d sub ho facts boolFacts item
      let (d', sub') = advanceKItemStructuralContext d sub item
      following <- collectStrictSubtermEdgesItems d' sub' ho facts boolFacts rest
      pure (joinEdges current following)

    collectStrictSubtermEdgesK :: Int -> StructuralOrigins -> Map Int PartialCall -> [AFact] -> [(Term, Bool)] -> KItem -> CheckM (Maybe [CallEdge])
    collectStrictSubtermEdgesK d sub ho facts boolFacts = \case
      KBind _ _ t _ -> collectStrictSubtermEdges d sub ho facts boolFacts t
      KLet _ _ t -> collectStrictSubtermEdges d sub ho facts boolFacts t
      KLetQ _ t m -> do
        rt <- collectStrictSubtermEdges d sub ho facts boolFacts t
        rm <-
          maybe
            (pure (Just []))
            (\(rejectionPattern, rejection) ->
               collectStrictSubtermEdges
                 (d + patBindersC rejectionPattern)
                 sub
                 ho
                 facts
                 boolFacts
                 rejection)
            m
        pure (joinEdges rt rm)
      KExpr t -> collectStrictSubtermEdges d sub ho facts boolFacts t
      KVarItem _ initT actT _ ->
        joinEdges <$> collectStrictSubtermEdges d sub ho facts boolFacts initT <*> collectStrictSubtermEdges d sub ho facts boolFacts actT
      KAssign lhs _ rhs actT _ ->
        joinManyEdges
          <$> sequence
            [ collectStrictSubtermEdges d sub ho facts boolFacts lhs
            , collectStrictSubtermEdges d sub ho facts boolFacts rhs
            , collectStrictSubtermEdges d sub ho facts boolFacts actT
            ]
      KReturn t -> collectStrictSubtermEdges d sub ho facts boolFacts t
      KWhile _ c b e ->
        join3Edges
          <$> collectStrictSubtermEdges d sub ho facts boolFacts (kCondTerm c)
          <*> collectStrictSubtermEdgesItems d sub ho facts boolFacts b
          <*> maybe
            (pure (Just []))
            (collectStrictSubtermEdgesItems d sub ho facts boolFacts)
            e
      KFor _ pattern' s b e ->
        join3Edges
          <$> collectStrictSubtermEdges d sub ho facts boolFacts s
          <*> collectStrictSubtermEdgesItems
            (d + patBindersC pattern')
            sub
            ho
            facts
            boolFacts
            b
          <*> maybe
            (pure (Just []))
            (collectStrictSubtermEdgesItems d sub ho facts boolFacts)
            e
      KIf alts e -> do
        ralts <- forM alts $ \(c, b) -> do
          rc <- collectStrictSubtermEdges d sub ho facts boolFacts c
          c' <- normalizeTermAt d c
          trueFacts <- assumeBoolM d True c'
          rb <-
            collectStrictSubtermEdgesItems
              d
              sub
              ho
              (trueFacts ++ facts)
              ((c', True) : boolFacts)
              b
          pure (joinEdges rc rb)
        relse <-
          maybe
            (pure (Just []))
            (collectStrictSubtermEdgesItems d sub ho facts boolFacts)
            e
        pure (joinManyEdges (ralts ++ [relse]))
      KDefer _ t -> collectStrictSubtermEdges d sub ho facts boolFacts t
      KUsing _ a r -> joinEdges <$> collectStrictSubtermEdges d sub ho facts boolFacts a <*> collectStrictSubtermEdges d sub ho facts boolFacts r
      KSubDo _ b -> collectStrictSubtermEdgesItems d sub ho facts boolFacts b
      _ -> pure (Just [])

    -- Traversal for syntactic positions that pass a value to an unknown
    -- consumer.  A partial recursive function may be returned directly or
    -- applied through a transparent helper, but it may not be hidden inside an
    -- opaque higher-order argument, record, constructor, thunk, or quote slot:
    -- that would let unknown code call it at arbitrary measures.
    goArg :: Int -> StructuralOrigins -> Map Int PartialCall -> Set Int -> [AFact] -> [(Term, Bool)] -> Term -> CheckM (Maybe [CallEdge])
    goArg d sub ho esc facts boolFacts t = do
      if opaqueRecursiveEscape t
        then pure Nothing
        else
          if containsSccReference d ho esc t
            then do
              tNorm <- normalizeTermAt d t
              if tNorm /= t && opaqueRecursiveEscape tNorm
                then pure Nothing
                else joinEdges <$> go d sub ho esc facts boolFacts t <*> go d sub ho esc facts boolFacts tNorm
            else go d sub ho esc facts boolFacts t
      where
        opaqueRecursiveEscape x =
          case partialCallOf d ho x of
            Just pc | Set.member (pcTarget pc) sccNames, not (partialCallComplete pc) -> True
            _ -> case x of
              CVar i -> Set.member (d - 1 - i) esc
              _ -> recursiveClosureEscapes d ho esc x

    recursiveClosureEscapes :: Int -> Map Int PartialCall -> Set Int -> Term -> Bool
    recursiveClosureEscapes d ho esc = \case
      CLam _ _ _ b -> containsSccReference (d + 1) ho esc b
      CThunkE t _ -> containsSccReference d ho esc t
      CLazyE t _ -> containsSccReference d ho esc t
      _ -> False

    containsSccReference :: Int -> Map Int PartialCall -> Set Int -> Term -> Bool
    containsSccReference d ho esc = \case
      CGlob g -> Set.member g sccNames
      CVar i -> Map.member (d - 1 - i) ho || Set.member (d - 1 - i) esc
      CLam _ _ _ b -> containsSccReference (d + 1) ho esc b
      CPi _ _ _ _ a b -> containsSccReference d ho esc a || containsSccReference (d + 1) ho esc b
      CApp _ f a -> containsSccReference d ho esc f || containsSccReference d ho esc a
      CCtor _ _ as -> any (containsSccReference d ho esc) as
      CMatch s _ _ alts ->
        containsSccReference d ho esc s
          || any
            ( \(CaseAlt pat gd b) ->
                let d' = d + patBindersC pat
                 in maybe False (containsSccReference d' ho esc) gd || containsSccReference d' ho esc b
            )
            alts
      CRecordT fs -> any (containsSccReference d ho esc . snd) fs
      CRecordV fs -> any (containsSccReference d ho esc . snd) fs
      CProj e _ -> containsSccReference d ho esc e
      CProjAt e _ _ -> containsSccReference d ho esc e
      CVariantT ms -> any (containsSccReference d ho esc) ms
      CInject _ e -> containsSccReference d ho esc e
      CLet _ _ a b c ->
        containsSccReference d ho esc a || containsSccReference d ho esc b || containsSccReference (d + 1) ho esc c
      CLetRec _ _ a b c ->
        containsSccReference d ho esc a || containsSccReference (d + 1) ho esc b || containsSccReference (d + 1) ho esc c
      CLetPolyM _ _ _ _ a b c ->
        containsSccReference d ho esc a || containsSccReference d ho esc b || containsSccReference (d + 1) ho esc c
      CLetRecPolyM _ _ _ _ a b c ->
        containsSccReference d ho esc a || containsSccReference (d + 1) ho esc b || containsSccReference (d + 1) ho esc c
      CLetRecGroupM _ definitions body ->
        let depth' = d + length definitions
         in any (containsSccReference d ho esc . clrdType) definitions
              || any (containsSccReference depth' ho esc . clrdRhs) definitions
              || containsSccReference depth' ho esc body
      CDo _ items -> containsSccReferenceItems d ho esc items
      CSealE _ e -> containsSccReference d ho esc e
      CSigT _ e -> containsSccReference d ho esc e
      CUniverseLift _ _ _ e -> containsSccReference d ho esc e
      CSchemaLift _ _ _ _ _ _ _ _ e -> containsSccReference d ho esc e
      CThunkE e _ -> containsSccReference d ho esc e
      CLazyE e _ -> containsSccReference d ho esc e
      CForceE e _ -> containsSccReference d ho esc e
      CIf a b c -> any (containsSccReference d ho esc) [a, b, c]
      CQuote _ slots -> any (containsSccReference d ho esc) slots
      _ -> False

    containsSccReferenceItems :: Int -> Map Int PartialCall -> Set Int -> [KItem] -> Bool
    containsSccReferenceItems _ _ _ [] = False
    containsSccReferenceItems d ho esc (item : rest) =
      containsSccReferenceK d ho esc item
        || containsSccReferenceItems (advanceKItemDepth d item) ho esc rest

    containsSccReferenceK :: Int -> Map Int PartialCall -> Set Int -> KItem -> Bool
    containsSccReferenceK d ho esc = \case
      KBind _ _ t _ -> containsSccReference d ho esc t
      KLet _ _ t -> containsSccReference d ho esc t
      KLetQ _ t m ->
        containsSccReference d ho esc t
          || maybe
            False
            (\(rejectionPattern, rejection) ->
               containsSccReference
                 (d + patBindersC rejectionPattern)
                 ho
                 esc
                 rejection)
            m
      KExpr t -> containsSccReference d ho esc t
      KVarItem _ initT actT _ -> containsSccReference d ho esc initT || containsSccReference d ho esc actT
      KAssign lhs _ rhs actT _ ->
        containsSccReference d ho esc lhs
          || containsSccReference d ho esc rhs
          || containsSccReference d ho esc actT
      KReturn t -> containsSccReference d ho esc t
      KWhile _ c b e ->
        containsSccReference d ho esc (kCondTerm c)
          || containsSccReferenceItems d ho esc b
          || maybe False (containsSccReferenceItems d ho esc) e
      KFor _ pattern' s b e ->
        containsSccReference d ho esc s
          || containsSccReferenceItems (d + patBindersC pattern') ho esc b
          || maybe False (containsSccReferenceItems d ho esc) e
      KIf alts e ->
        any
          (\(c, b) ->
             containsSccReference d ho esc c
               || containsSccReferenceItems d ho esc b)
          alts
          || maybe False (containsSccReferenceItems d ho esc) e
      KDefer _ t -> containsSccReference d ho esc t
      KUsing _ a r -> containsSccReference d ho esc a || containsSccReference d ho esc r
      KSubDo _ b -> containsSccReferenceItems d ho esc b
      _ -> False

    partialCallOf :: Int -> Map Int PartialCall -> Term -> Maybe PartialCall
    partialCallOf d ho t = case spineOfTerm t of
      (CGlobI callee universes, args)
        | Set.member callee sccNames -> Just (PartialCall callee universes d args)
      (CVar i, args) -> do
        pc0 <- Map.lookup (d - 1 - i) ho
        let pc = instantiatePartialCall d pc0
        pure pc {pcArgs = pcArgs pc ++ args}
      _ -> Nothing

    instantiatePartialCall :: Int -> PartialCall -> PartialCall
    instantiatePartialCall d pc =
      pc
        { pcDepth = d
        , pcArgs = [(ic, shiftTerm (d - pcDepth pc) 0 a) | (ic, a) <- pcArgs pc]
        }

    partialCallComplete :: PartialCall -> Bool
    partialCallComplete pc =
      case Map.lookup (pcTarget pc) funMap of
        Nothing -> False
        Just target -> length (pcArgs pc) >= length (tfParams target)

    goKItems
      :: Int
      -> StructuralOrigins
      -> Map Int PartialCall
      -> Set Int
      -> [AFact]
      -> [(Term, Bool)]
      -> [KItem]
      -> CheckM (Maybe [CallEdge])
    goKItems _ _ _ _ _ _ [] = pure (Just [])
    goKItems d sub ho esc facts boolFacts (item : rest) = do
      current <- goK d sub ho esc facts boolFacts item
      let (d', sub') = advanceKItemStructuralContext d sub item
      following <- goKItems d' sub' ho esc facts boolFacts rest
      pure (joinEdges current following)

    goK :: Int -> StructuralOrigins -> Map Int PartialCall -> Set Int -> [AFact] -> [(Term, Bool)] -> KItem -> CheckM (Maybe [CallEdge])
    goK d sub ho esc facts boolFacts = \case
      KBind _ _ t _ -> goArg d sub ho esc facts boolFacts t
      KLet _ _ t -> goArg d sub ho esc facts boolFacts t
      KLetQ _ t m -> do
        rt <- goArg d sub ho esc facts boolFacts t
        rm <-
          maybe
            (pure (Just []))
            (\(rejectionPattern, rejection) ->
               goArg
                 (d + patBindersC rejectionPattern)
                 sub
                 ho
                 esc
                 facts
                 boolFacts
                 rejection)
            m
        pure (joinEdges rt rm)
      KExpr t -> goArg d sub ho esc facts boolFacts t
      KVarItem _ initT actT _ ->
        joinEdges <$> goArg d sub ho esc facts boolFacts initT <*> goArg d sub ho esc facts boolFacts actT
      KAssign lhs _ rhs actT _ ->
        joinManyEdges
          <$> sequence
            [ goArg d sub ho esc facts boolFacts lhs
            , goArg d sub ho esc facts boolFacts rhs
            , goArg d sub ho esc facts boolFacts actT
            ]
      KReturn t -> go d sub ho esc facts boolFacts t
      KWhile _ c b e ->
        join3Edges
          <$> go d sub ho esc facts boolFacts (kCondTerm c)
          <*> goKItems d sub ho esc facts boolFacts b
          <*> maybe
            (pure (Just []))
            (goKItems d sub ho esc facts boolFacts)
            e
      KFor _ pattern' s b e ->
        join3Edges
          <$> goArg d sub ho esc facts boolFacts s
          <*> goKItems
            (d + patBindersC pattern')
            sub
            ho
            esc
            facts
            boolFacts
            b
          <*> maybe
            (pure (Just []))
            (goKItems d sub ho esc facts boolFacts)
            e
      KIf alts e -> do
        ralts <- forM alts $ \(c, b) -> do
          rc <- go d sub ho esc facts boolFacts c
          c' <- normalizeTermAt d c
          trueFacts <- assumeBoolM d True c'
          rb <-
            goKItems
              d
              sub
              ho
              esc
              (trueFacts ++ facts)
              ((c', True) : boolFacts)
              b
          pure (joinEdges rc rb)
        relse <-
          maybe
            (pure (Just []))
            (goKItems d sub ho esc facts boolFacts)
            e
        pure (joinManyEdges (ralts ++ [relse]))
      KDefer _ t -> goArg d sub ho esc facts boolFacts t
      KUsing _ a r -> joinEdges <$> goArg d sub ho esc facts boolFacts a <*> goArg d sub ho esc facts boolFacts r
      KSubDo _ b -> goKItems d sub ho esc facts boolFacts b
      _ -> pure (Just [])

    advanceKItemDepth :: Int -> KItem -> Int
    advanceKItemDepth d = \case
      KBind _ pattern' _ _ -> d + patBindersC pattern'
      KLet _ pattern' _ -> d + patBindersC pattern'
      KLetQ pattern' _ _ -> d + patBindersC pattern'
      KVarItem {} -> d + 1
      KUsing pattern' _ _ -> d + patBindersC pattern'
      _ -> d

    advanceKItemStructuralContext
      :: Int -> StructuralOrigins -> KItem -> (Int, StructuralOrigins)
    advanceKItemStructuralContext d sub item =
      ( advanceKItemDepth d item
      , case item of
          KLet _ pattern' value ->
            bindPatternStructuralOrigins d sub value pattern'
          KLetQ pattern' value _ ->
            bindPatternStructuralOrigins d sub value pattern'
          _ -> sub
      )

    joinEdges :: Maybe [CallEdge] -> Maybe [CallEdge] -> Maybe [CallEdge]
    joinEdges (Just a) (Just b) = Just (a ++ b)
    joinEdges _ _ = Nothing

    join3Edges :: Maybe [CallEdge] -> Maybe [CallEdge] -> Maybe [CallEdge] -> Maybe [CallEdge]
    join3Edges a b c = joinManyEdges [a, b, c]

    joinManyEdges :: [Maybe [CallEdge]] -> Maybe [CallEdge]
    joinManyEdges xs = concat <$> sequence xs

-- | Bind structural provenance per pattern binder. A positional pattern over
-- an explicit tuple/record scrutinee must follow each source field separately:
-- collapsing @(xs, ys)@ to one reconstructed origin loses the fact that @xr@
-- descends from @xs@ and @yr@ from @ys@. Unknown scrutinee structure still
-- uses exact typed pattern paths, preserving the ordinary constructor case.
bindPatternStructuralOrigins
  :: Int -> StructuralOrigins -> Term -> CorePat -> StructuralOrigins
bindPatternStructuralOrigins depth context scrutinee pattern' =
  foldr insert context
    (zip [depth ..] (patternStructuralBinderOrigins depth context scrutinee pattern'))
  where
    insert (_, origins) current | Set.null origins = current
    insert (level, origins) current =
      current
        { structuralLocals =
            Map.insertWith Set.union level origins (structuralLocals current)
        }

patternStructuralBinderOrigins
  :: Int -> StructuralOrigins -> Term -> CorePat -> [Set StructuralOrigin]
patternStructuralBinderOrigins depth context scrutinee =
  go (Just scrutinee) (termStructuralOrigins depth context scrutinee)
  where
    go concrete origins = \case
      CPWild -> []
      CPVarM _ _ -> [origins]
      CPLit _ -> []
      CPCtorM existentialModes bridges hidden _ _ patterns ->
        replicate
          (length existentialModes + constructorBridgeBinderCount bridges)
          Set.empty
          ++ case
            interleaveConstructorSourceBinders
              hidden
              [ descendPosition concrete origins index pattern'
              | (index, pattern') <- zip [0 ..] patterns
              ]
          of
            Just source ->
              concatMap (either (const [Set.empty]) id) source
            Nothing ->
              -- Structural descent evidence is optional. On malformed layout
              -- preserve binder cardinality but refuse to attach any origin.
              replicate
                (length hidden + sum (map patBindersC patterns))
                Set.empty
      CPTuple patterns ->
        concat
          [ descendPosition concrete origins index pattern'
          | (index, pattern') <- zip [0 ..] patterns
          ]
      CPRecordM fields rest ->
        concat
          [ descendField concrete origins field pattern'
          | (field, pattern') <- fields
          ]
          ++ maybe [] (const [Set.empty]) rest
      CPInject member pattern' ->
        case concrete >>= injectedPayload member of
          Just payload ->
            go
              (Just payload)
              (termStructuralOrigins depth context payload)
              pattern'
          Nothing ->
            go Nothing (appendOriginStep (StructuralVariant member) origins) pattern'
      CPInjectRestM _ _ -> [Set.empty]
      CPOr patterns _ -> maybe [] (go concrete origins) (listToMaybe patterns)
      CPAsM _ _ pattern' -> origins : go concrete origins pattern'

    descendPosition concrete origins index pattern' =
      case concrete >>= positionalPayload index of
        Just payload ->
          go
            (Just payload)
            (termStructuralOrigins depth context payload)
            pattern'
        Nothing ->
          go Nothing (appendOriginStep (StructuralPosition index) origins) pattern'

    descendField concrete origins field pattern' =
      case concrete >>= recordPayload field of
        Just payload ->
          go
            (Just payload)
            (termStructuralOrigins depth context payload)
            pattern'
        Nothing ->
          go Nothing (appendOriginStep (StructuralField field) origins) pattern'

    appendOriginStep step =
      Set.map
        (\origin ->
           origin
             { structuralPath = structuralPath origin ++ [step]
             })

    positionalPayload index term =
      nthMaybe index $ case stripIdentityWrappers term of
        CCtorI _ _ _ arguments ->
          [caTerm argument | argument <- arguments, caPayload argument]
        CCtor _ _ arguments -> arguments
        CRecordV fields -> map snd fields
        _ -> []

    recordPayload field term =
      lookup field $ case stripIdentityWrappers term of
        CRecordV fields -> fields
        _ -> []

    injectedPayload member term = case stripIdentityWrappers term of
      CInject actual payload | actual == member -> Just payload
      _ -> Nothing

-- ── Structural size-change checking ──────────────────────────────────

structuralSccOK :: Map GName TermFun -> Maybe (Map GName [Text]) -> CheckM Bool
structuralSccOK funMap selectedNames = do
  mEdges <- collectSccEdges funMap
  case mEdges of
    Nothing -> pure False
    Just edges -> do
      st <- get
      let hasSchema function =
            maybe False ((> 0) . dutParameterCount . gdUniverses)
              (Map.lookup (tfName function) (csGlobals st))
          useSchemaDimension = any hasSchema (Map.elems funMap)
      candidates <- mapM (edgeStructuralGraph st funMap selectedNames useSchemaDimension) edges
      case sequence candidates of
        Nothing -> pure False
        Just graphs -> pure (not (null graphs) && sizeChangeTerminates graphs)

edgeStructuralGraph
  :: CheckState
  -> Map GName TermFun
  -> Maybe (Map GName [Text])
  -> Bool
  -> CallEdge
  -> CheckM (Maybe (SCGraph GName))
edgeStructuralGraph st funMap selectedNames useSchemaDimension edge =
  case (Map.lookup (edgeFrom edge) funMap, Map.lookup (edgeTo edge) funMap) of
    (Just src, Just tgt) -> do
      let srcRefs = selectedParamRefs src selectedNames
          tgtRefs = selectedParamRefs tgt selectedNames
          srcParams = map snd srcRefs
          tgtParams = map snd tgtRefs
          explArgs = [argument | (Expl, argument) <- edgeArgs edge]
          schemaChange =
            if useSchemaDimension
              then recursiveSchemaChangeForEdge st edge
              else Nothing
      case traverse (\(argumentIndex, _) -> nthMaybe argumentIndex explArgs) tgtRefs of
        Nothing -> pure Nothing
        Just targetArguments -> do
          -- Constructor values are commonly represented by eta-expanded Core
          -- applications. Classification uses definitional normal forms so the
          -- path proof below sees the same constructor reconstruction without
          -- baking an elaborator presentation into the termination checker.
          normalizedArguments <-
            mapM (normalizeTermAt (edgeDepth edge)) targetArguments
          if (null srcParams || null tgtParams) && not useSchemaDimension
            then pure Nothing
            else do
              let ordinaryEntries =
                    [ ((sourceIndex, targetIndex), change)
                    | (targetIndex, argument) <- zip [0 :: Int ..] normalizedArguments
                    , (sourceIndex, change) <-
                        structuralArgChanges
                          srcParams
                          (edgeDepth edge)
                          (edgeStructuralOrigins edge)
                          argument
                    ]
                  schemaEntries =
                    [ ((length srcParams, length tgtParams), change)
                    | useSchemaDimension
                    , change <- maybeToList schemaChange
                    ]
              pure
                ( Just
                    SCGraph
                      { scFrom = edgeFrom edge
                      , scTo = edgeTo edge
                      , scRows = length srcParams + if useSchemaDimension then 1 else 0
                      , scCols = length tgtParams + if useSchemaDimension then 1 else 0
                      , scMat = Map.fromListWith strongerChange (ordinaryEntries ++ schemaEntries)
                      }
                )
    _ -> pure Nothing

-- | Classify the static declaration-schema component of one SCT call edge.
-- Calls carry their exact finalized universe spine.  We match that spine
-- against elaboration-time occurrences and admit a strict edge only when
-- every matching occurrence proves pointwise non-increase and at least one
-- strict component.  Multiple same-shaped call sites with different lexical
-- assumptions therefore degrade to weak rather than borrowing another site's
-- proof.  Missing or incomparable evidence contributes no static edge.
recursiveSchemaChangeForEdge :: CheckState -> CallEdge -> Maybe Change
recursiveSchemaChangeForEdge st edge
  | sourceArity == 0 && targetArity == 0 = Just ChWeak
  | sourceArity == 0 || targetArity == 0 = Nothing
  | null matching = Nothing
  | any isNothing classified = Nothing
  | all (== Just ChStrict) classified = Just ChStrict
  | otherwise = Just ChWeak
  where
    assignments = csLevelAssignments st
    sourceArity = declarationArity (edgeFrom edge)
    targetArity = declarationArity (edgeTo edge)
    declarationArity name =
      maybe 0 (dutParameterCount . gdUniverses) (Map.lookup name (csGlobals st))
    normalize = normalizeLevel . substituteLevelMetas assignments
    edgeSpine = map normalize (edgeUniverses edge)
    matching =
      [ occurrence
      | occurrence <- csRecursiveSchemaOccurrences st
      , rsoCaller occurrence == edgeFrom edge
      , rsoCallee occurrence == edgeTo edge
      , map normalize (rsoLevels occurrence) == edgeSpine
      ]
    sourceLevels = map LParam [0 .. sourceArity - 1]
    classify occurrence =
      let targetLevels = map normalize (rsoLevels occurrence)
          occurrenceAssumptions = substituteLevelAssumptions assignments (rsoAssumptions occurrence)
          pointwise =
            length sourceLevels == length targetLevels
              && and
                [ proveLevelLeq occurrenceAssumptions target source == Proved
                | (target, source) <- zip targetLevels sourceLevels
                ]
          strict =
            pointwise
              && or
                [ proveLevelLeq occurrenceAssumptions (levelSucc target) source == Proved
                | (target, source) <- zip targetLevels sourceLevels
                ]
       in if not pointwise
            then Nothing
            else Just (if strict then ChStrict else ChWeak)
    classified = map classify matching

selectedParamRefs :: TermFun -> Maybe (Map GName [Text]) -> [(Int, Int)]
selectedParamRefs f Nothing = zip [0 :: Int ..] (tfExplParams f)
selectedParamRefs f (Just byName) =
  case Map.lookup (tfName f) byName of
    Nothing -> []
    Just names ->
      [ (ix, lvl)
      | wanted <- names
      , Just ix <- [elemIndex wanted (tfParamNames f)]
      , Just lvl <- [nthMaybe ix (tfExplParams f)]
      ]

structuralArgChanges :: [Int] -> Int -> StructuralOrigins -> Term -> [(Int, Change)]
structuralArgChanges selected depth origins term =
  [ (index, if null (structuralPath origin) then ChWeak else ChStrict)
  | origin <- Set.toList (termStructuralOrigins depth origins term)
  , Just index <- [Map.lookup (structuralRoot origin) selectedIndex]
  ]
  where
    selectedIndex = Map.fromList (zip selected [0 :: Int ..])

insertStructuralAlias :: Int -> StructuralOrigins -> Term -> StructuralOrigins
insertStructuralAlias level origins rhs =
  let aliases = termStructuralOrigins level origins rhs
   in if Set.null aliases
        then origins
        else
          origins
            { structuralLocals =
                Map.insertWith Set.union level aliases (structuralLocals origins)
            }

recordMatchedStructuralShape
  :: Set StructuralOrigin -> CorePat -> StructuralOrigins -> StructuralOrigins
recordMatchedStructuralShape origins pattern' context
  | Set.null origins = context
  | otherwise = case pattern' of
      CPCtorM _ _ _ constructor universes [] ->
        insertShape (StructuralCtor constructor universes)
      CPLit literal -> insertShape (StructuralLiteral literal)
      CPOr (first : _) _ -> recordMatchedStructuralShape origins first context
      CPAsM _ _ inner -> recordMatchedStructuralShape origins inner context
      _ -> context
  where
    insertShape shape =
      context
        { structuralShapes =
            Map.insertWith Set.union shape origins (structuralShapes context)
        }

-- | Recover a structural subterm identity only from typed Core facts. A
-- constructor/record reconstruction is accepted when every argument is the
-- correctly ordered immediate child of one common path. This proves rebuilt
-- tails such as @second :: tail@ while rejecting reordered, duplicated, or
-- unrelated payloads.
termStructuralOrigins :: Int -> StructuralOrigins -> Term -> Set StructuralOrigin
termStructuralOrigins depth origins = go
  where
    go = \case
      CVar index ->
        Map.findWithDefault Set.empty (depth - 1 - index) (structuralLocals origins)
      -- Strictly-positive function-valued constructor fields denote families
      -- of recursive children. Application selects one child without changing
      -- the field's structural provenance.
      CApp _ function _ -> go function
      CProj receiver field -> Set.map (appendStep (StructuralField field)) (go receiver)
      CProjAt receiver field _ -> Set.map (appendStep (StructuralField field)) (go receiver)
      CCtorI constructor universes _ arguments ->
        let payload = [caTerm argument | argument <- arguments, caPayload argument]
         in if null payload
              then Map.findWithDefault Set.empty
                (StructuralCtor constructor universes)
                (structuralShapes origins)
              else reconstructPositions payload
      CRecordV fields -> reconstructFields fields
      CInject member value -> reconstructVariant member value
      CUniverseLift _ _ _ value -> go value
      CSchemaLift _ _ _ _ _ _ _ _ value -> go value
      CSealE _ value -> go value
      CLit literal ->
        Map.findWithDefault Set.empty
          (StructuralLiteral literal)
          (structuralShapes origins)
      _ -> Set.empty

    appendStep step origin =
      origin {structuralPath = structuralPath origin ++ [step]}

    reconstructPositions arguments =
      reconstructFromSuffixes
        [ (StructuralPosition index, go argument)
        | (index, argument) <- zip [0 ..] arguments
        ]

    reconstructFields fields =
      reconstructFromSuffixes
        [ (StructuralField field, go value)
        | (field, value) <- fields
        ]

    reconstructVariant member value =
      reconstructFromSuffixes [(StructuralVariant member, go value)]

    reconstructFromSuffixes [] = Set.empty
    reconstructFromSuffixes expected =
      case [Set.fromList
              (mapMaybe (stripExpected expectedStep) (Set.toList childOrigins))
           | (expectedStep, childOrigins) <- expected] of
        [] -> Set.empty
        first : rest -> foldl' Set.intersection first rest

    stripExpected expectedStep origin = do
      (prefix, actualStep) <- unsnoc (structuralPath origin)
      guard (actualStep == expectedStep)
      pure origin {structuralPath = prefix}

    unsnoc [] = Nothing
    unsnoc values = Just (init values, last values)

-- ── Explicit measure checking ────────────────────────────────────────

data MeasureCall = MeasureCall
  { mcDepth :: !Int
  , mcFacts :: ![AFact]
  , mcOldMeasure :: !Term
  , mcNewMeasure :: !Term
  , mcRelation :: !(Maybe RelationSpec)
  , mcProof :: !(Maybe Expr)
  , mcSource :: !TermFun
  }

measureSccOK :: Map GName TermFun -> CheckM Bool
measureSccOK funMap = do
  let specs = map tfMeasure (Map.elems funMap)
  if any isNothing specs
    then pure False
    else do
      compatible <- measureSpecsCompatible (catMaybes specs)
      if not compatible
        then pure False
        else do
          mEdges <- collectSccEdges funMap
          case mEdges of
            Nothing -> pure False
            Just edges -> case traverse (measureCallOfEdge funMap) edges of
              Nothing -> pure False
              Just calls -> do
                oks <- mapM measureCallOK calls
                pure (not (null calls) && and oks)

measureSpecsCompatible :: [MeasureSpec] -> CheckM Bool
measureSpecsCompatible [] = pure False
measureSpecsCompatible specs@(s0 : _) =
  do
    normalizedMeasures <- traverse (\s -> normalizeTermAt (msDepth s) (msMeasureTerm s)) specs
    case normalizedMeasures of
      [] -> pure False
      firstMeasure : restMeasures -> do
        let arity t = length (rankComponents t)
            expectedArity = arity firstMeasure
            sameArity = all (\t -> arity t == expectedArity) restMeasures
        pure (sameArity && sameMeasureType && sameRelationShape)
  where
    sameMeasureType = all (\s -> msMeasureTypeKey s == msMeasureTypeKey s0) specs
    relKey = fmap rsKey . msRelation
    relType = fmap rsTypeKey . msRelation
    sameRelationShape =
      all (\s -> fmap rsFlavor (msRelation s) == fmap rsFlavor (msRelation s0)) specs
        && all (\s -> relKey s == relKey s0) specs
        && all (\s -> relType s == relType s0) specs

measureCallOfEdge :: Map GName TermFun -> CallEdge -> Maybe MeasureCall
measureCallOfEdge funMap edge = do
  src <- Map.lookup (edgeFrom edge) funMap
  tgt <- Map.lookup (edgeTo edge) funMap
  srcSpec <- tfMeasure src
  tgtSpec <- tfMeasure tgt
  let tgtFormalLvls = map snd (tfParams tgt)
      supplied = take (length tgtFormalLvls) (edgeArgs edge)
      subst = Map.fromList (zip tgtFormalLvls (map snd supplied))
  if edgeDepth edge < msDepth srcSpec
    then Nothing
    else do
      newHere <- instantiateByLevelMaybe (msDepth tgtSpec) (edgeDepth edge) subst (msMeasureTerm tgtSpec)
      let oldHere = shiftTerm (edgeDepth edge - msDepth srcSpec) 0 (msMeasureTerm srcSpec)
      Just
        MeasureCall
          { mcDepth = edgeDepth edge
          , mcFacts = edgeFacts edge
          , mcOldMeasure = oldHere
          , mcNewMeasure = newHere
          , mcRelation = msRelation srcSpec
          , mcProof = msProof srcSpec
          , mcSource = src
          }

measureCallOK :: MeasureCall -> CheckM Bool
measureCallOK call = do
  let d = mcDepth call
      facts = mcFacts call
      oldM0 = mcOldMeasure call
      newM0 = mcNewMeasure call
      mRel = mcRelation call
      mProof = mcProof call
      src = mcSource call
  oldM <- normalizeTermAt d oldM0
  newM <- normalizeTermAt d newM0
  case (mRel, mProof) of
    (Nothing, Nothing) -> defaultMeasureCallOK (tfNatLvls src) d facts oldM newM
    (Nothing, Just _proofE) ->
      -- `using` is parsed and retained, but erased proof terms are not a
      -- termination oracle. Until proof checking produces inspectable descent
      -- evidence, a proof annotation can only accompany an internally proved
      -- measure decrease.
      defaultMeasureCallOK (tfNatLvls src) d facts oldM newM
    (Just rel, Nothing) -> do
      wf <- relationWellFoundedAtCall (tfNatLvls src) d facts rel oldM newM
      holds <- relationCallHolds (tfNatLvls src) d facts rel oldM newM
      pure (wf && holds)
    (Just rel, Just _proofE) -> do
      wf <- relationWellFoundedAtCall (tfNatLvls src) d facts rel oldM newM
      holds <- relationCallHolds (tfNatLvls src) d facts rel oldM newM
      pure (wf && holds)

defaultMeasureCallOK :: Set Int -> Int -> [AFact] -> Term -> Term -> CheckM Bool
defaultMeasureCallOK natLvls d facts oldM newM = do
  let oldCs = rankComponents oldM
      newCs = rankComponents newM
  if length oldCs /= length newCs
    then pure False
    else do
      nonNegOld <- mapM (componentNonNegative oldCs) oldCs
      nonNegNew <- mapM (componentNonNegative newCs) newCs
      dec <- lexDecreases (zip oldCs newCs)
      pure (and nonNegOld && and nonNegNew && dec)
  where
    componentNonNegative _ t = proveNonNeg natLvls facts d t
    lexDecreases [] = pure False
    lexDecreases ((oldC, newC) : rest) = do
      lt <- proveLt natLvls facts d newC oldC
      if lt
        then pure True
        else do
          eq <- proveEq natLvls facts d newC oldC
          if eq then lexDecreases rest else pure False

relationWellFoundedAtCall :: Set Int -> Int -> [AFact] -> RelationSpec -> Term -> Term -> CheckM Bool
relationWellFoundedAtCall natLvls d facts rel oldM newM
  | rsWellFounded rel = pure True
  | otherwise = do
      relHere <- normalizeTermAt d (shiftTerm (d - rsDepth rel) 0 (rsTerm rel))
      isLt <- relationIsPrimitiveLtInt d relHere
      if isLt
        then do
          oldOK <- and <$> mapM (proveNonNeg natLvls facts d) (rankComponents oldM)
          newOK <- and <$> mapM (proveNonNeg natLvls facts d) (rankComponents newM)
          pure (oldOK && newOK)
        else pure False

relationCallHolds :: Set Int -> Int -> [AFact] -> RelationSpec -> Term -> Term -> CheckM Bool
relationCallHolds natLvls d facts rel oldM newM = do
  relHere <- normalizeTermAt d (shiftTerm (d - rsDepth rel) 0 (rsTerm rel))
  goal <- normalizeTermAt d (CApp Expl (CApp Expl relHere newM) oldM)
  case rsFlavor rel of
    RelationReturnsBool -> proveBoolTrue natLvls facts d goal
    RelationReturnsType -> proveTypeRelationTrue natLvls facts d goal
    RelationUnknown -> pure False

-- ── Normalization and arithmetic evidence ────────────────────────────

normalizeTermAt :: Int -> Term -> CheckM Term
normalizeTermAt d t = do
  st <- get
  -- 'csFacts' alters conversion-time reduction of rigids.  Rather than trying
  -- to serialize arbitrary 'Value' facts into a cache key, bypass the cache
  -- while such facts are active.  Boolean branch facts are handled at the
  -- proposition-cache layer, not here.
  let cacheable =
        Map.null (csFacts st)
          && null (unsolvedMetasOf st t)
          && termCacheUniverseScoped st t
      key =
        NormCacheKey
          (csNormEpoch st)
          (csActiveUniverseDefinition st)
          d
          (renderStructuralTermKey t)
  case if cacheable then Map.lookup key (csNormCache st) else Nothing of
    Just cached -> pure cached
    Nothing -> do
      ec <- ec_
      let normalized =
            if maxFreeIndexTerm t >= d
              then simplifyDecisionTerm t
              else
                let env = [VRigid lvl [] | lvl <- [d - 1, d - 2 .. 0]]
                    v = force ec (eval ec env t)
                 in simplifyDecisionTerm (quote ec d v)
      let storeable =
            cacheable
              && null (unsolvedMetasOf st normalized)
              && termCacheUniverseScoped st normalized
      when storeable $
        modify' $ \s ->
          s {csNormCache = boundedInsert maxNormCacheEntries key normalized (csNormCache s)}
      pure normalized

assumeBoolM :: Int -> Bool -> Term -> CheckM [AFact]
assumeBoolM d truth t = do
  mFact <- boolRelBranchM d t
  pure $ case mFact >>= if truth then Just else negateFact of
    Just assumed -> [assumed]
    Nothing -> []

-- | Classify a boolean known from control flow into arithmetic evidence
-- without normalizing arbitrary function calls.  Branch conditions may be
-- recursive, effectful after erasure, or simply large; they are proof sources
-- only when their surface Core shape is already an arithmetic comparison.
-- Losing a branch fact is conservative, while unfolding a recursive condition
-- during checked arithmetic can make elaboration non-terminating.
boolRelBranchM :: Int -> Term -> CheckM (Maybe AFact)
boolRelBranchM d t0 = case simplifyDecisionTerm t0 of
  CIf c th el
    | isTrueTm th, isFalseTm el -> boolRelBranchM d c
    | isFalseTm th, isTrueTm el -> (>>= negateFact) <$> boolRelBranchM d c
    | isTrueTm th -> do
        cFact <- boolRelBranchM d c
        elFact <- boolRelBranchM d el
        pure (cFact >>= \cf -> elFact >>= combineOr cf)
  t -> case boolRel d t of
    Just fact -> pure (Just fact)
    Nothing -> do
      selectedStandardOrderFact d t >>= \case
        Just (_, fact) -> pure (Just fact)
        Nothing ->
          primitiveEqBranchM d t >>= \case
            Just fact -> pure (Just fact)
            Nothing -> compareMatchRelBranchM d t
  where
    isTrueTm = \case CCtor g _ [] -> g == prelTrue; _ -> False
    isFalseTm = \case CCtor g _ [] -> g == prelFalse; _ -> False
    combineOr (AFact ACmpLt a b) (AFact ACmpEq a' b') | a == a' && b == b' = Just (AFact ACmpLe a b)
    combineOr (AFact ACmpEq a b) (AFact ACmpLt a' b') | a == a' && b == b' = Just (AFact ACmpLe a b)
    combineOr _ _ = Nothing

-- | Decode the standard Nat/Integer order combinators while their exact
-- selected dictionary is still present. The public operators are ordinary
-- prelude definitions rather than trait members, so unrestricted transparent
-- reduction would turn them into a compare/match tree and lose provider
-- identity. Return the authenticated carrier domain with the fact so
-- certificate construction cannot silently cross domains.
selectedStandardOrderFact
  :: Int
  -> Term
  -> CheckM (Maybe (ArithmeticDomain, AFact))
selectedStandardOrderFact depth term =
  case spineOfTerm (stripIdentityWrappers term) of
    (headTerm, arguments)
      | Just operation <- termHeadGlob (stripIdentityWrappers headTerm)
      , operation `elem` map gPrel ["<", "<=", ">", ">="] -> do
          let implicitArguments = [argument | (Impl, argument) <- arguments]
              explicitArguments = [argument | (Expl, argument) <- arguments]
          case (implicitArguments, last2 explicitArguments) of
            (carrier : dictionary : _, Just (left, right)) ->
              case arithmeticDomainForCarrier carrier of
                Nothing -> pure Nothing
                Just domain -> do
                  standard <-
                    standardPreludeDictionary
                      prelOrd
                      (\case
                        [headType] ->
                          arithmeticDomainForCarrier headType == Just domain
                        _ -> False)
                      dictionary
                  if not standard
                    then pure Nothing
                    else do
                      leftExpression <-
                        selectedArithmeticExpression domain depth left
                      rightExpression <-
                        selectedArithmeticExpression domain depth right
                      pure $ do
                        left' <- leftExpression
                        right' <- rightExpression
                        pure
                          ( domain
                          , if operation == gPrel "<"
                              then AFact ACmpLt left' right'
                              else if operation == gPrel "<="
                                then AFact ACmpLe left' right'
                                else if operation == gPrel ">"
                                  then AFact ACmpLt right' left'
                                  else AFact ACmpLe right' left'
                          )
            _ -> pure Nothing
    _ -> pure Nothing

-- | Recognize an unresolved standard equality operation before transparent
-- projection reduction has exposed its primitive implementation.  Deferred
-- checked-arithmetic goals can be revisited while the branch condition still
-- has this shape.  The operation head, carrier, and selected dictionary are
-- all authenticated by semantic identity; user-defined equality operations
-- and dictionaries remain outside the arithmetic proof source.
primitiveEqBranchM :: Int -> Term -> CheckM (Maybe AFact)
primitiveEqBranchM d term = case spineOfTerm term of
  (CGlob operation, arguments)
    | operation == gPrel "==" -> do
        let implicits = [argument | (Impl, argument) <- arguments]
            explicits = [argument | (Expl, argument) <- arguments]
        case (implicits, last2 explicits) of
          (carrier : dictionary : _, Just (lhs, rhs)) -> do
            authenticated <- standardPrimitiveEqDict carrier dictionary
            if not authenticated
              then pure Nothing
              else do
                lhsExpression <- selectedNatArithmeticExpression d lhs
                rhsExpression <- selectedNatArithmeticExpression d rhs
                pure (AFact ACmpEq <$> lhsExpression <*> rhsExpression)
          _ -> pure Nothing
  _ -> pure Nothing

standardPrimitiveEqDict :: Term -> Term -> CheckM Bool
standardPrimitiveEqDict carrier dictionary =
  if primitiveOrderedType (stripIdentityWrappers carrier)
    then
      standardPreludeDictionary
        (gPrel "Eq")
        (\headArguments ->
           map stripIdentityWrappers headArguments
             == [stripIdentityWrappers carrier])
        dictionary
    else pure False

comparePatternFactsM :: Int -> Term -> CorePat -> CheckM [AFact]
comparePatternFactsM d scrut pat = do
  mArgs <- primitiveOrderedCompareArgs d scrut
  pure $ case mArgs of
    Just (aa, bb) -> maybeToList $ do
      mkFact <- compareCtorFact pat
      pure (mkFact aa bb)
    Nothing -> []
  where
    compareCtorFact = \case
      CPCtor g _ [] | g == prelLT -> Just (\a b -> AFact ACmpLt a b)
      CPCtor g _ [] | g == prelEQ -> Just (\a b -> AFact ACmpEq a b)
      CPCtor g _ [] | g == prelGT -> Just (\a b -> AFact ACmpLt b a)
      _ -> Nothing

compareMatchRelBranchM :: Int -> Term -> CheckM (Maybe AFact)
compareMatchRelBranchM d = \case
  CMatch scrut _ _ alts -> do
    mArgs <- primitiveOrderedCompareArgsRaw d scrut
    pure $ do
      (aa, bb) <- mArgs
      cmp <- compareBoolMatch alts
      pure $ case cmp of
        CompareLt -> AFact ACmpLt aa bb
        CompareLe -> AFact ACmpLe aa bb
        CompareGt -> AFact ACmpLt bb aa
        CompareGe -> AFact ACmpLe bb aa
  _ -> pure Nothing

data CompareBoolMatch = CompareLt | CompareLe | CompareGt | CompareGe
  deriving stock (Eq, Show)

compareBoolMatch :: [CaseAlt] -> Maybe CompareBoolMatch
compareBoolMatch alts = do
  branches <- traverse compareBoolBranch alts
  let tags = sort [tag | (tag, _) <- branches]
      expectedTags = ["EQ", "GT", "LT"] :: [Text]
  unlessMaybe (tags == expectedTags)
  lt <- lookup "LT" branches
  eq <- lookup "EQ" branches
  gt <- lookup "GT" branches
  case (lt, eq, gt) of
    (True, False, False) -> Just CompareLt
    (True, True, False) -> Just CompareLe
    (False, False, True) -> Just CompareGt
    (False, True, True) -> Just CompareGe
    _ -> Nothing
  where
    unlessMaybe True = Just ()
    unlessMaybe False = Nothing

    compareBoolBranch :: CaseAlt -> Maybe (Text, Bool)
    compareBoolBranch (CaseAlt (CPCtor g _ []) Nothing body)
      | g == prelLT = (\b -> ("LT", b)) <$> boolBody body
      | g == prelEQ = (\b -> ("EQ", b)) <$> boolBody body
      | g == prelGT = (\b -> ("GT", b)) <$> boolBody body
    compareBoolBranch _ = Nothing

    boolBody = \case
      CCtor g _ [] | g == prelTrue -> Just True
      CCtor g _ [] | g == prelFalse -> Just False
      _ -> Nothing

primitiveOrderedCompareArgs :: Int -> Term -> CheckM (Maybe (AExpr, AExpr))
primitiveOrderedCompareArgs d t = do
  raw <- primitiveOrderedCompareArgsRaw d t
  case raw of
    Just args -> pure (Just args)
    Nothing -> do
      t' <- transparentProofReduce d (96 :: Int) t
      primitiveOrderedCompareArgsRaw d t' >>= \case
        Just args -> pure (Just args)
        Nothing -> pure (primitiveCompareShape d t')

primitiveOrderedCompareArgsRaw :: Int -> Term -> CheckM (Maybe (AExpr, AExpr))
primitiveOrderedCompareArgsRaw d t =
  case rawCompareArgs t of
    Just (tyArg, dictArg, aa, bb) -> do
      ok <- standardPrimitiveOrdDict tyArg dictArg
      pure (if ok then Just (aa, bb) else Nothing)
    Nothing -> pure Nothing
  where
    rawCompareArgs :: Term -> Maybe (Term, Term, AExpr, AExpr)
    rawCompareArgs x = case spineOfTerm x of
      (CGlob g, args)
        | g == prelCompare -> do
            let impls = [a | (Impl, a) <- args]
                ex = [a | (Expl, a) <- args]
            case (impls, last2 ex) of
              (tyArg : dictArg : _, Just (a, b))
                | primitiveOrderedType tyArg -> do
                    aa <- arithOf d a
                    bb <- arithOf d b
                    Just (tyArg, dictArg, aa, bb)
              _ -> Nothing
      _ -> Nothing

primitiveCompareShape :: Int -> Term -> Maybe (AExpr, AExpr)
primitiveCompareShape d t0 = case simplifyDecisionTerm t0 of
  CIf lt (CCtor ltG _ []) (CIf eq (CCtor eqG _ []) (CCtor gtG _ []))
    | ltG == prelLT
    , eqG == prelEQ
    , gtG == prelGT -> do
        AFact ACmpLt a b <- boolRel d lt
        AFact ACmpEq a' b' <- boolRel d eq
        if a == a' && b == b'
          then Just (a, b)
          else Nothing
  _ -> Nothing

primitiveOrderedType :: Term -> Bool
primitiveOrderedType ty =
  let carrier = stripIdentityWrappers ty
   in carrier == CGlob prelInteger
        || carrier == CGlob prelNat

standardPrimitiveOrdDict :: Term -> Term -> CheckM Bool
standardPrimitiveOrdDict ty dictionary =
  standardPreludeDictionary
    prelOrd
    (\headArguments ->
       map stripIdentityWrappers headArguments
         == [stripIdentityWrappers ty])
    dictionary

gnameInModule :: GName -> ModuleName -> Bool
gnameInModule (GName m _) target = m == target

proveLt :: Set Int -> [AFact] -> Int -> Term -> Term -> CheckM Bool
proveLt natLvls facts d lhs rhs = do
  lhs' <- normalizeTermAt d lhs
  rhs' <- normalizeTermAt d rhs
  case (arithOf d lhs', arithOf d rhs') of
    (Just l, Just r) -> proveFact natLvls facts (AFact ACmpLt l r)
    _ -> pure False

proveEq :: Set Int -> [AFact] -> Int -> Term -> Term -> CheckM Bool
proveEq natLvls facts d lhs rhs = do
  lhs' <- normalizeTermAt d lhs
  rhs' <- normalizeTermAt d rhs
  if lhs' == rhs'
    then pure True
    else case (arithOf d lhs', arithOf d rhs') of
      (Just l, Just r) -> proveFact natLvls facts (AFact ACmpEq l r)
      _ -> pure False

proveNonNeg :: Set Int -> [AFact] -> Int -> Term -> CheckM Bool
proveNonNeg natLvls facts d t = do
  t' <- normalizeTermAt d t
  case arithOf d t' of
    Just a -> proveFact natLvls facts (AFact ACmpLe (AConst 0) a)
    Nothing -> pure False

proveBoolTrue :: Set Int -> [AFact] -> Int -> Term -> CheckM Bool
proveBoolTrue natLvls facts d t = do
  t' <- normalizeTermAt d t
  case t' of
    CCtor g _ [] | g == prelTrue -> pure True
    _ -> case boolRel d t' of
      Just fact -> proveFact natLvls facts fact
      Nothing -> pure False

-- | A Type-valued relation often encodes a decidable order as
-- `(p = True)`.  When normalization exposes that shape, the same arithmetic
-- evidence used for Bool-valued primitive orders can discharge the Type
-- proposition.  This is still conservative: arbitrary inhabited propositions
-- are not guessed.
proveTypeRelationTrue :: Set Int -> [AFact] -> Int -> Term -> CheckM Bool
proveTypeRelationTrue natLvls facts d t = do
  t' <- normalizeTermAt d t
  case boolEqualityTruePayload t' of
    Just b -> proveBoolTrue natLvls facts d b
    Nothing -> pure False

boolEqualityTruePayload :: Term -> Maybe Term
boolEqualityTruePayload t = case spineOfTerm (stripIdentityWrappers t) of
  (headTerm, args)
    | Just eqG <- termHeadGlob (stripIdentityWrappers headTerm)
    , eqG == prelEqType -> do
        let ex = [a | (Expl, a) <- args]
        (lhs, rhs) <- last2 ex
        case (stripIdentityWrappers lhs, stripIdentityWrappers rhs) of
          (relation, truth) | isTrueCtor truth -> Just relation
          (truth, relation) | isTrueCtor truth -> Just relation
          _ -> Nothing
  _ -> Nothing
  where
    isTrueCtor = \case
      CCtor g _ [] -> g == prelTrue
      CCtorI g _ _ [] -> g == prelTrue
      _ -> False

proveFact :: Set Int -> [AFact] -> AFact -> CheckM Bool
proveFact natLvls facts goal =
  if proveFactByBounds ArithmeticNaturalSemantics natLvls facts goal
    then pure True
    else pure False

checkAgainstSig :: Maybe Text -> Value -> [Binder] -> Expr -> Span -> CheckM Term
checkAgainstSig retName sigTy binders body sp = do
  -- consume binders against the signature's Pi telescope. §18.5: the body
  -- is the named function's body, so a `return@<name>` inside it resolves.
  go (emptyCtx {ctxReturnTarget = retName}) sigTy binders
  where
    -- §9.1: `let name = \binders -> body` is a named function `name`; the
    -- RHS lambda inherits the name as its return target. Inject it as the
    -- lambda's label so `return@name` inside the body resolves (an explicit
    -- label on the lambda is kept).
    body' = case (binders, body, retName) of
      ([], ELambda Nothing lbs lbody lsp, Just nm) -> ELambda (Just (Name nm lsp)) lbs lbody lsp
      _ -> body
    -- The function body do IS the return target's completion boundary, so
    -- elaborate it directly with ctxReturnTarget preserved (the generic
    -- EDo path would reset it, treating it as a nested do). §18.5.
    go ctx ty0 [] = do
      callableType <- peelCapturesM ty0
      case callableType of
        VPiBoundM mode Impl q _ nm assumption dom clo
          | not bodyStartsWithLambda ->
              -- Preserve an already-polymorphic body before introducing an
              -- omitted signature binder, but only when synthesis confirms
              -- that the body itself starts with an implicit callable
              -- telescope.  A speculative direct check alone is not enough:
              -- it may postpone an incompatible carrier/evidence obligation
              -- and appear diagnostic-free until the declaration boundary.
              -- Monomorphic bodies (notably @do@ blocks) must instead see the
              -- signature binders while they are elaborated.
              bodySynthesizesImplicit ctx >>= \case
                True ->
                  tryExpectedReading (checkBody ctx ty0) >>= \case
                    Just direct -> pure direct
                    Nothing ->
                      tryExpectedReading (skipImplicit ctx mode q nm assumption dom clo []) >>= \case
                        Just etaExpanded -> pure etaExpanded
                        -- Both readings failed.  Re-run the original direct
                        -- comparison so diagnostics describe the two
                        -- higher-rank types, not incidental implicit search
                        -- performed by the discarded eta alternative.
                        Nothing -> checkBody ctx ty0
                False -> skipImplicit ctx mode q nm assumption dom clo []
        -- No definition binder remains: an outer capture annotation is now
        -- the demanded result environment, not a transparent callable
        -- wrapper. Preserve it for closure inference and containment.
        _ -> checkBody ctx ty0
    go ctx ty0 (b : rest) = do
      -- §12.3.1 capture environments refine function identity without adding
      -- a source parameter. Peel them only while consuming a definition
      -- binder; the result type (the zero-binder case above) remains wrapped.
      (ty, captureRegions) <- peelCapturesWithRegionsM ty0
      case ty of
        VPiBoundM mode Impl q borrowed nm assumption dom clo
          | not (bImplicit b)
          , (nameText <$> bName b) /= Just nm -> do
              -- An unnamed trait-arrow binder may be named explicitly by a
              -- definition when the source supplies one more explicit binder
              -- than the remaining explicit Pi telescope. This is ordinary
              -- explicit dictionary passing (`let f A ev x = ...`) and is
              -- unambiguous with the elided form (`let f A x = ...`).
              cod <- clApp clo (VRigid (ctxLen ctx) [])
              traitBinder <- isTraitGoal dom
              remaining <- explicitPiArity (ctxLen ctx + 1) cod
              let supplied = length [() | sb <- b : rest, not (bImplicit sb)]
              if traitBinder && supplied > remaining
                then claim ctx mode Impl q borrowed captureRegions nm assumption dom clo b rest
                else skipImplicit ctx mode q nm assumption dom clo (b : rest)
        VPiBoundM mode Impl q borrowed nm assumption dom clo
          | bImplicit b
          , nm /= "_"
          , Just suppliedName <- nameText <$> bName b
          , suppliedName /= nm -> do
              codomain <- clApp clo (VRigid (ctxLen ctx) [])
              namedLater <-
                implicitBinderNamed
                  (ctxLen ctx + 1)
                  suppliedName
                  codomain
              if namedLater
                then
                  -- All forall binders are omittable implicits. Stable source
                  -- binder identity disambiguates omission from alpha-renaming:
                  -- when this name belongs to a later implicit slot, introduce
                  -- the intervening signature binder and retry unchanged.
                  skipImplicit ctx mode q nm assumption dom clo (b : rest)
                else case binderTypeExpr b of
                  Just tyE -> do
                    -- A differently named annotated binder claims the current
                    -- Pi only when its annotation matches. Otherwise it may be
                    -- targeting a later anonymous/generated implicit.
                    st0 <- get
                    nBefore <- gets (length . csDiags)
                    ok <- do
                      (tyTm, _) <- inferBinderDomainType ctx b tyE
                      tyV <- evalIn ctx tyTm
                      unify ctx dom tyV
                    nAfter <- gets (length . csDiags)
                    put st0
                    if ok && nAfter == nBefore
                      then claim ctx mode Impl q borrowed captureRegions nm assumption dom clo b rest
                      else skipImplicit ctx mode q nm assumption dom clo (b : rest)
                  Nothing ->
                    -- No later slot owns the supplied name and no annotation
                    -- says otherwise, so this is ordinary alpha-renaming of
                    -- the current implicit binder.
                    claim ctx mode Impl q borrowed captureRegions nm assumption dom clo b rest
        VPiBoundM mode ic q borrowed nm assumption dom clo ->
          claim ctx mode ic q borrowed captureRegions nm assumption dom clo b rest
        _ -> do
          errAt sp "E_SIGNATURE_ARITY" (Just "kappa-hs.type.signature-arity")
            "definition has more parameters than its signature type"
          check ctx body ty
    skipImplicit ctx mode q nm assumption dom clo bs = do
      withBound <- extendLevelAssumption sp ctx assumption
      let ctx' = bindCtxMQ mode q nm True dom withBound
      cod <- clApp clo (VRigid (ctxLen ctx) [])
      CLamM mode Impl q nm <$> go ctx' cod bs

    bodyStartsWithLambda = case body' of
      ELambda {} -> True
      _ -> False

    -- This is a read-only classification probe.  Inference can allocate metas,
    -- enqueue evidence, and record usage even when it reports no diagnostic,
    -- so every state component is restored before returning the answer.
    bodySynthesizesImplicit _ | EDo {} <- body' = pure False
    bodySynthesizesImplicit ctx = do
      st0 <- get
      n0 <- gets (length . csDiags)
      (_, actual0) <- infer ctx body'
      actual <- peelCapturesM actual0
      n1 <- gets (length . csDiags)
      let hasImplicit = case actual of
            VPiBoundM _ Impl _ _ _ _ _ _ -> True
            _ -> False
      put st0
      pure (n0 == n1 && hasImplicit)

    -- Choosing between the direct higher-rank reading and eta-expanding an
    -- omitted signature forall is structural recovery, not a demand that the
    -- chosen body be error-free. A reading whose only failure is its selected
    -- evidence obligation is the right reading and must retain that single
    -- cause; discarding it would replace E_UNSOLVED_IMPLICIT with a misleading
    -- whole-function type mismatch. Every other speculative failure restores
    -- the complete checker state.
    tryExpectedReading action = do
      initial <- get
      diagnosticCount <- gets (length . csDiags)
      result <- action
      diagnostics <- gets csDiags
      let added = take (length diagnostics - diagnosticCount) diagnostics
          evidenceOnly =
            not (null added)
              && all ((== "E_UNSOLVED_IMPLICIT") . dCode) added
      if null added || evidenceOnly
        then pure (Just result)
        else put initial >> pure Nothing

    checkBody ctx ty = case body' of
      EDo mlbl items isp -> do
        (tm, ty') <- elabDo ctx mlbl items isp (Just ty)
        expectType ctx isp ty' ty
        pure tm
      _ -> check ctx body' ty
    claim ctx mode ic q borrowed captureRegions nm assumption dom clo b rest = do
      let bn = fromMaybe nm (nameText <$> bName b)
      forM_ (binderTypeExpr b) $ \tyE -> do
        (tyTm, _) <- inferBinderDomainType ctx b tyE
        tyV <- evalIn ctx tyTm
        expectTypeAfterPendingEvidence ctx (bSpan b) dom tyV
      unless (ic == (if bImplicit b then Impl else Expl) || ic == Impl) $
        errAt (bSpan b) "E_BINDER_MISMATCH" (Just "kappa-hs.type.binder")
          "binder implicitness does not match the signature"
      withBound <- extendLevelAssumption (bSpan b) ctx assumption
      -- A source binder may explicitly name an implicit signature slot (most
      -- notably a trait-arrow dictionary).  Candidate status follows the
      -- checked Pi binder, not the surface spelling used to claim it; the
      -- resulting Core lambda is implicit and the dictionary must remain
      -- available to ordinary implicit resolution in the body.
      let ctx'0 = bindCtxMQ mode q bn (ic == Impl) dom withBound
      ctx' <- recordBinderCaptureRegion ctx b borrowed captureRegions ctx'0
      cod <- clApp clo (VRigid (ctxLen ctx) [])
      CLamM mode ic q bn <$> go ctx' cod rest

    explicitPiArity lvl ty0 = do
      ty <- peelCapturesM ty0
      case ty of
        VPi ic _ _ _ _ clo -> do
          cod <- clApp clo (VRigid lvl [])
          rest <- explicitPiArity (lvl + 1) cod
          pure (if ic == Expl then rest + 1 else rest)
        _ -> pure (0 :: Int)

    implicitBinderNamed lvl target ty0 = do
      ty <- peelCapturesM ty0
      case ty of
        VPiBoundM _ Impl _ _ name _ _ closure
          | name == target -> pure True
          | otherwise -> do
              codomain <- clApp closure (VRigid lvl [])
              implicitBinderNamed (lvl + 1) target codomain
        _ -> pure False


elabFunction :: Maybe Text -> [Binder] -> Maybe Expr -> Expr -> Span -> CheckM (Term, Value)
elabFunction retName [] mResTy body _ =
  let ctx = emptyCtx {ctxReturnTarget = retName}
   in case mResTy of
        Just tyE -> do
          (tyTm, _) <- inferType ctx tyE
          tyV <- evalIn ctx tyTm
          tm <- check ctx body tyV
          pure (tm, tyV)
        Nothing -> do
          -- A declaration boundary preserves an already-polymorphic value.
          -- Implicit insertion belongs to a use/application site; performing
          -- it here silently specializes @let boo = foo@ and destroys foo's
          -- existing forall telescope (§11.3.3).
          infer ctx body
elabFunction retName binders mResTy body sp = do
  let ctx = emptyCtx {ctxReturnTarget = retName}
  case mResTy of
    -- A fully annotated named definition is definitionally the same
    -- declaration contract as a separate signature followed by a body.
    -- Elaborating only an ascription on the body loses the source-level
    -- identity of transparent type aliases when the inferred Pi is quoted.
    -- Build and check against the complete annotated telescope instead.
    Just resultType
      | all (isJust . binderTypeExpr) binders -> do
          let declarationType = foldr EArrow resultType binders
          (typeTerm, _) <-
            withNamedCallableInoutSignature declarationType
              (inferType ctx declarationType)
          typeValue <- evalIn ctx typeTerm
          elabNamedDeclLambda ctx binders body sp (Just typeValue)
    Just resultType ->
      elabNamedDeclLambda ctx binders (EAscription body resultType sp) sp Nothing
    Nothing ->
      elabNamedDeclLambda ctx binders body sp Nothing

-- | §14.3 instance pre-pass: elaborate and register the head of every
-- top-level instance declaration (instance-set entry plus the
-- dictionary global's type) before any declaration body is checked,
-- so instance visibility within the module does not depend on
-- declaration order. Instance heads depend only on header-pass
-- artifacts (traits, data types, aliases; lowercase head names are
-- implicitly universalized per §11.3.3), so this is sound ahead of
-- the body pass. Member bodies are still checked in source order by
-- 'elabInstance'.
planDerivedDeclarations :: [Decl] -> CheckM ()
planDerivedDeclarations declarations = do
  requests <- fmap catMaybes . forM declarations $ \case
    DDerive headExpression sourceSpan -> do
      (traitIdentity, _, arguments) <- instSplitHead headExpression
      case (traitIdentity, arguments) of
        (Just trait, [target]) -> do
          targetTerm <- fst <$> inferType emptyCtx target
          targetTerm' <- zonkTermM 0 targetTerm
          pure
            ( Just
                ( sourceSpan
                , trait
                , target
                , targetTerm'
                )
            )
        _ -> do
          errAt sourceSpan "E_DERIVE_HEAD" (Just "kappa.derive")
            "derive expects one supported trait applied to one target type (§14.5)"
          pure Nothing
    _ -> pure Nothing
  let isSetTrait = gPrel "IsSet"
      eqTrait = gPrel "Eq"
  forM_ requests $ \(sourceSpan, trait, target, targetTerm) -> do
    generated <-
      if trait == isSetTrait
        then pure [derivedEmptyInstance sourceSpan 1 "IsSet" target]
        else
          if trait == eqTrait
            then do
              eqDeclaration <- derivedEqDecl sourceSpan 2 target targetTerm
              explicitIsSet <-
                anyM
                  (\(_, requestTrait, _, requestTarget) ->
                     if requestTrait == isSetTrait
                       then termsMatchTransactionally targetTerm requestTarget
                       else pure False)
                  requests
              registeredIsSet <- matchingEvidenceExists isSetTrait targetTerm
              pure $
                ( if explicitIsSet || registeredIsSet
                    then []
                    else [derivedEmptyInstance sourceSpan 1 "IsSet" target]
                )
                  ++ [eqDeclaration]
            else
              if trait == gPrel "RefinementView"
                then pure [derivedEmptyInstance sourceSpan 1 "RefinementView" target]
                else
                  if trait == gPrel "ExactNaturalRepresentation"
                    then pure [derivedEmptyInstance sourceSpan 1 "ExactNaturalRepresentation" target]
                    else pure [derivedWholeInstance sourceSpan trait target]
    modify' $ \state ->
      state {csDerivedDecls = Map.insert sourceSpan generated (csDerivedDecls state)}
    mapM_ instanceHeadPass generated
  where
    -- Paired derive requests are compared by checked Core under an isolated
    -- solver state. Independently fresh universe occurrence metas therefore
    -- do not manufacture duplicate evidence, while failed comparison cannot
    -- constrain either declaration (§14.5.1, §33.2.1).
    termsMatchTransactionally left right = do
      saved <- get
      matches <- termMatchesTerm emptyCtx left right
      put saved
      pure matches

    -- Reuse ordinary, identity-backed instance selection to detect an IsSet
    -- artifact already declared outside the derive request list. This keeps
    -- target equivalence, universe specialization, and head normalization in
    -- the same authority as every later evidence lookup.
    matchingEvidenceExists trait target = do
      saved <- get
      targetValue <- evalIn emptyCtx target
      goal <- globalValueM trait [(Expl, targetValue)]
      found <- isJust <$> traitEvidence emptyCtx noSpan goal
      put saved
      pure found

    anyM predicate = go
      where
        go [] = pure False
        go (value : rest) = do
          found <- predicate value
          if found then pure True else go rest

-- | Dependent refinement fibers can contain ordinary type/evidence metas that
-- are finalized only after the complete module header and instance set has
-- been checked. The derive head is registered by 'planDerivedDeclarations';
-- after header evidence finalization this pass replaces its head-only
-- placeholder with the checked generated members. This mirrors the ordinary
-- instance header/body split and avoids order-dependent retries.
finalizeDerivedRefinementDeclarations :: [Decl] -> CheckM ()
finalizeDerivedRefinementDeclarations declarations =
  forM_ declarations $ \case
    DDerive headExpression sourceSpan -> do
      (traitIdentity, _, arguments) <- instSplitHead headExpression
      case (traitIdentity, arguments) of
        (Just trait, [target])
          | trait == gPrel "RefinementView" -> do
              targetTerm0 <- fst <$> inferType emptyCtx target
              targetTerm <- zonkTermM 0 targetTerm0
              shape <- deriveRefinementViewShape sourceSpan target targetTerm
              let generated =
                    [ maybe
                        (derivedEmptyInstance sourceSpan 1 "RefinementView" target)
                        (derivedRefinementViewDecl sourceSpan target)
                        shape
                    ]
              modify' $ \state ->
                state
                  { csDerivedDecls =
                      Map.insert sourceSpan generated (csDerivedDecls state)
                  }
        _ -> pure ()
    _ -> pure ()

derivedGeneratedSpan :: Span -> Int -> Span
derivedGeneratedSpan (Span file start (Pos endLine endColumn)) discriminator =
  Span file start (Pos endLine (endColumn + discriminator))

derivedTraitHead :: Span -> Text -> Expr -> Expr
derivedTraitHead span' trait target =
  EApp (EVar (Name trait span')) [ArgExplicit target]

derivedEmptyInstance :: Span -> Int -> Text -> Expr -> Decl
derivedEmptyInstance sourceSpan discriminator trait target =
  let span' = derivedGeneratedSpan sourceSpan discriminator
   in DInstance
        ( InstanceDecl
            Nothing
            []
            (derivedTraitHead span' trait target)
            (InstanceMembers [])
        )
        span'

-- | Declaration-level @derive (Tr T)@ uses the same facet-completion mode as
-- @instance Tr T = derive@ (§14.3.4A). Trait-specific structural generators
-- may still produce a more explicit checked instance before reaching this
-- fallback; this constructor is the uniform protocol for every other trait.
derivedWholeInstance :: Span -> GName -> Expr -> Decl
derivedWholeInstance sourceSpan trait target =
  let span' = derivedGeneratedSpan sourceSpan 1
   in DInstance
        ( InstanceDecl
            Nothing
            []
            (derivedTraitHead span' (gnameText trait) target)
            InstanceDerive
        )
        span'

-- | The exact checked shape used to generate a 'RefinementView' dictionary.
-- Field positions are source-constructor positions, but their semantic roles
-- were selected from instantiated checked types and resolved global identity.
-- Textual names are used only to emit ordinary syntax that is re-resolved by
-- the checker.
data DerivedRefinementViewShape = DerivedRefinementViewShape
  { drvsConstructor :: !GName
  , drvsFieldCount :: !Int
  , drvsFieldIcit :: ![Icit]
  , drvsBaseIndex :: !Int
  , drvsIsPropIndex :: !Int
  , drvsProofIndex :: !Int
  , drvsBaseFieldName :: !(Maybe Text)
  , drvsIsPropFieldName :: !Text
  , drvsProofFieldName :: !Text
  , drvsBaseType :: !Expr
  , drvsPredicateBody :: !Expr
  }

data InstantiatedRefinementField = InstantiatedRefinementField
  { irfSourceIndex :: !Int
  , irfArgumentIndex :: !Int
  , irfMode :: !ObservationMode
  , irfQuantity :: !Q
  , irfType :: !Value
  , irfArgument :: !ConstructorArg
  }

-- | §14.5.2 eligibility and predicate recovery. This deliberately works from
-- the checked constructor telescope:
--
-- * one ordinary runtime-kept field is the base;
-- * every other source field is erased quantity-0 evidence;
-- * one field has checked type @IsProp P@ and one has checked type @P@;
-- * the two fibers are definitionally equal; and
-- * the predicate contains no unresolved meta except the selected base-field
--   meta, which is abstracted into the generated associated predicate.
--
-- Requiring exactly the base/IsProp/proof triple is the v1 deterministic
-- filler fragment. Shapes with additional erased fields fail closed until
-- those fields have a checked synthesis rule.
deriveRefinementViewShape
  :: Span
  -> Expr
  -> Term
  -> CheckM (Maybe DerivedRefinementViewShape)
deriveRefinementViewShape sourceSpan target _requestTargetTerm = do
  -- Re-specialize the target under the checked derived-head occurrence.
  -- Eligibility itself performs no evidence search and cannot be justified by
  -- the instance being generated.
  settledTargetTerm0 <- fst <$> inferType emptyCtx target
  settledTargetTerm <- zonkTermM 0 settledTargetTerm0
  deriveRefinementViewShapeSettled sourceSpan settledTargetTerm

deriveRefinementViewShapeSettled
  :: Span
  -> Term
  -> CheckM (Maybe DerivedRefinementViewShape)
deriveRefinementViewShapeSettled sourceSpan targetTerm = do
  state <- get
  case nominalDataHead targetTerm >>= \dataName -> (dataName,) <$> Map.lookup dataName (csDatas state) of
    Just (_dataName, dataInfo)
      | [constructor] <- diCtors dataInfo
      , Just constructorInfo <- Map.lookup constructor (csCtors state) -> do
          targetValue <- evalIn emptyCtx targetTerm
          (_universes, _constructorType, arguments, namedBinders, _explicitFields) <-
            instantiateConstructorForFields
              emptyCtx
              constructor
              constructorInfo
              targetValue
              sourceSpan
          let sourceFieldCount = length (ciSourceFields constructorInfo)
              sourceBinders =
                drop (length namedBinders - sourceFieldCount) namedBinders
              instantiatedFields0 =
                [ InstantiatedRefinementField
                    sourceIndex
                    argumentIndex
                    mode
                    quantity
                    fieldType
                    argument
                | (sourceIndex, (argumentIndex, _fieldName, mode, quantity, fieldType)) <-
                    zip [0 :: Int ..] sourceBinders
                , Just argument <- [arguments `atMay` argumentIndex]
                ]
          connectedEvidence <-
            pendingEvidenceComponent emptyCtx (map irfType instantiatedFields0)
          flushPendingSelected connectedEvidence
          instantiatedFields <-
            forM instantiatedFields0 $ \field -> do
              fieldTypeTerm <-
                quoteIn emptyCtx (irfType field) >>= zonkTermM 0
              fieldType <- evalIn emptyCtx fieldTypeTerm
              pure field {irfType = fieldType}
          ec <- ec_
          let retainedFields =
                [ field
                | field <- instantiatedFields
                , Repr.runtimeConstructorField
                    ec
                    (irfArgumentIndex field)
                    (caIcit (irfArgument field))
                    (irfQuantity field)
                    (irfType field)
                ]
              erasedFields =
                [ field
                | field <- instantiatedFields
                , field `notElemByIndex` retainedFields
                ]
              exactSourceShape =
                length instantiatedFields == sourceFieldCount
                  && and
                    [ caIcit (irfArgument field) == sourceIcit
                    | (field, (sourceIcit, _sourceName)) <-
                        zip instantiatedFields (ciSourceFields constructorInfo)
                    ]
          case retainedFields of
            [baseField]
              | exactSourceShape
              , irfMode baseField == Ordinary
              , length instantiatedFields == 3
              , all ((== Q0) . irfQuantity) erasedFields -> do
                  baseArgument <- zonkTermM 0 (caTerm (irfArgument baseField))
                  case stripIdentityWrappers baseArgument of
                    CMeta baseMeta -> do
                      classified <-
                        forM erasedFields $ \field ->
                          (field,) <$> refinementIsPropFiber (irfType field)
                      let isPropFields =
                            [ (field, fiber)
                            | (field, Just fiber) <- classified
                            ]
                          proofFields =
                            [ field
                            | (field, Nothing) <- classified
                            ]
                          matchingPairs =
                            [ (isPropField, proofField, fiber)
                            | (isPropField, fiber) <- isPropFields
                            , proofField <- proofFields
                            , convertible ec 0 fiber (irfType proofField)
                            ]
                      case matchingPairs of
                        [(isPropField, proofField, fiber)] -> do
                          baseTypeTerm <-
                            quoteIn emptyCtx (irfType baseField) >>= zonkTermM 0
                          predicateTerm0 <-
                            quoteIn emptyCtx fiber >>= zonkTermM 0
                          let predicateTerm =
                                mapTermWithDepth
                                  ( \depth -> \case
                                      CMeta meta
                                        | meta == baseMeta -> Just (CVar depth)
                                      _ -> Nothing
                                  )
                                  0
                                  predicateTerm0
                              noResidualMetas =
                                null (metaIdsOf baseTypeTerm)
                                  && null (metaIdsOf predicateTerm)
                              baseName = "__derive_refinement_base"
                              sourceNames = map snd (ciSourceFields constructorInfo)
                              baseFieldName =
                                sourceNames `atMay` irfSourceIndex baseField >>= id
                              isPropFieldName =
                                sourceNames `atMay` irfSourceIndex isPropField >>= id
                              proofFieldName =
                                sourceNames `atMay` irfSourceIndex proofField >>= id
                              checkedSourceModes =
                                ( caIcit (irfArgument baseField)
                                , caIcit (irfArgument isPropField)
                                , caIcit (irfArgument proofField)
                                )
                          pure $ do
                            guard noResidualMetas
                            guard (checkedSourceModes == (Expl, Impl, Impl))
                            isPropName <- isPropFieldName
                            proofName <- proofFieldName
                            baseType <-
                              delaborateTypeWithEnv emptyCtx sourceSpan [] baseTypeTerm
                            predicateBody <-
                              delaborateTypeWithEnv
                                emptyCtx
                                sourceSpan
                                [baseName]
                                predicateTerm
                            pure
                              DerivedRefinementViewShape
                                { drvsConstructor = constructor
                                , drvsFieldCount = length instantiatedFields
                                , drvsFieldIcit = map (caIcit . irfArgument) instantiatedFields
                                , drvsBaseIndex = irfSourceIndex baseField
                                , drvsIsPropIndex = irfSourceIndex isPropField
                                , drvsProofIndex = irfSourceIndex proofField
                                , drvsBaseFieldName = baseFieldName
                                , drvsIsPropFieldName = isPropName
                                , drvsProofFieldName = proofName
                                , drvsBaseType = baseType
                                , drvsPredicateBody = predicateBody
                                }
                        _ -> pure Nothing
                    _ -> pure Nothing
            _ -> pure Nothing
    _ -> pure Nothing
  where
    atMay values index
      | index < 0 = Nothing
      | otherwise = listToMaybe (drop index values)
    field `notElemByIndex` others =
      all ((/= irfSourceIndex field) . irfSourceIndex) others

-- | Recover the semantic fiber from checked @IsProp fiber@ evidence. Hidden
-- declaration-universe proof arguments are removed through the trait's
-- registered semantic telescope, so this cannot be confused by source
-- spelling or a same-named non-prelude declaration.
refinementIsPropFiber :: Value -> CheckM (Maybe Value)
refinementIsPropFiber fieldType = do
  normalized <- forceM fieldType
  state <- get
  pure $ case normalized of
    VGlobN trait arguments
      | trait == gPrel "IsProp"
      , Just [(Expl, fiber)] <- traitSemanticSpineIn state trait arguments ->
          Just fiber
    _ -> Nothing

derivedRefinementViewDecl
  :: Span
  -> Expr
  -> DerivedRefinementViewShape
  -> Decl
derivedRefinementViewDecl sourceSpan target shape =
  DInstance
    ( InstanceDecl
        Nothing
        []
        (derivedTraitHead span' "RefinementView" target)
        (InstanceMembers members)
    )
    span'
  where
    span' = derivedGeneratedSpan sourceSpan 1
    baseName = Name "__derive_refinement_base" span'
    valueName = Name "__derive_refinement_value" span'
    isPropName = Name "__derive_refinement_is_prop" span'
    proofName = Name "__derive_refinement_proof" span'
    refinedName = Name "__derive_refinement_value_object" span'
    predicateIsPropName = Name "__derive_refinement_predicate_is_prop" span'
    predicateProofName = Name "__derive_refinement_predicate_proof" span'
    implicit name = (simpleBinder name) {bImplicit = True}
    member name binders body =
      DLet
        noMods
        ( LetDef
            (Just (Name name span'))
            False
            Nothing
            Nothing
            emptyPrefix
            binders
            Nothing
            Nothing
            body
        )
        span'
    members =
      [ member "Base" [] (drvsBaseType shape)
      , member "Predicate" [simpleBinder baseName] (drvsPredicateBody shape)
      , member
          "refinementValue"
          [simpleBinder refinedName]
          (projectRefinementField refinedName (drvsBaseFieldName shape) valueName)
      , member
          "refinementPredicateIsProp"
          [simpleBinder refinedName]
          ( projectRefinementField
              refinedName
              (Just (drvsIsPropFieldName shape))
              isPropName
          )
      , member
          "refinementProof"
          [simpleBinder refinedName]
          ( projectRefinementField
              refinedName
              (Just (drvsProofFieldName shape))
              proofName
          )
      , member
          "refine"
          [ simpleBinder baseName
          , implicit predicateIsPropName
          , implicit predicateProofName
          ]
          constructDerivedRefinement
      , member
          "valueAfterRefine"
          [ implicit baseName
          , implicit predicateIsPropName
          , implicit predicateProofName
          ]
          refl
      , member
          "refineAfterValue"
          [implicit refinedName]
          (matchRefinementBase refinedName refl)
      ]
    targetQualifier = case targetHead target of
      EVar name -> Just name
      _ -> Nothing
    targetHead = \case
      EApp function _ -> targetHead function
      other -> other
    constructorName = Name (gnameText (drvsConstructor shape)) span'
    constructorPattern =
      PCtor
        (CtorRef targetQualifier constructorName)
        [PVar valueName]
        span'
    matchRefinementBase scrutinee body =
      EMatch
        (EVar scrutinee)
        [ MatchCase
            constructorPattern
            Nothing
            body
            span'
        ]
        span'
    projectRefinementField scrutinee fieldName fallbackName =
      case fieldName of
        Just name ->
          EDot (EVar scrutinee) (DotName (Name name span'))
        Nothing ->
          matchRefinementBase scrutinee (EVar fallbackName)
    constructorExpression =
      case targetQualifier of
        Just qualifier -> EDot (EVar qualifier) (DotName constructorName)
        Nothing -> EVar constructorName
    constructDerivedRefinement =
      EApp
        constructorExpression
        [ argumentFor index icit
        | (index, icit) <- zip [0 :: Int ..] (drvsFieldIcit shape)
        ]
    argumentFor index icit =
      let expression
            | index == drvsBaseIndex shape = EVar baseName
            | index == drvsIsPropIndex shape = EVar predicateIsPropName
            | index == drvsProofIndex shape = EVar predicateProofName
            | otherwise = EHole Nothing span'
       in case icit of
            Expl -> ArgExplicit expression
            Impl -> ArgImplicit expression
    refl = EVar (Name "refl" span')

derivedEqDecl :: Span -> Int -> Expr -> Term -> CheckM Decl
derivedEqDecl sourceSpan discriminator target targetTerm = do
  (shape, premises) <- deriveNominalShape emptyCtx sourceSpan targetTerm
  let span' = derivedGeneratedSpan sourceSpan discriminator
      xName = Name "__derive_x" span'
      yName = Name "__derive_y" span'
      member name binders body =
        DLet noMods
          ( LetDef
              (Just (Name name span'))
              False
              Nothing
              Nothing
              emptyPrefix
              binders
              Nothing
              Nothing
              body
          )
          span'
      equalityBody =
        derivedEqualityBody span' target shape xName yName
  pure $
    DInstance
      ( InstanceDecl
          Nothing
          premises
          (derivedTraitHead span' "Eq" target)
          ( InstanceMembers
              [ member "==" [simpleBinder xName, simpleBinder yName] equalityBody
              ]
          )
      )
      span'

data DerivedNominalField = DerivedNominalField
  { dnfQuantity :: !Q
  , dnfTypeTerm :: !Term
  , dnfTypeExpression :: !Expr
  }

type DerivedNominalShape = [(GName, [DerivedNominalField])]

-- | Stable, identity-backed source shape used only to generate ordinary
-- pattern syntax. Constructor and target identities come from the checked
-- header tables; textual names are emitted and then resolved by the ordinary
-- pattern checker. The checked field term is retained so later law synthesis
-- can authenticate the exact evidence selected by the checked comparator.
deriveNominalShape
  :: Ctx
  -> Span
  -> Term
  -> CheckM (DerivedNominalShape, [Expr])
deriveNominalShape ctx sourceSpan target = do
  state <- get
  case nominalDataHead target >>= (`Map.lookup` csDatas state) of
    Nothing -> pure ([], [])
    Just info -> do
      targetValue <- evalIn ctx target
      constructors <-
        forM
        [ (constructor, constructorInfo)
        | constructor <- diCtors info
        , Just constructorInfo <- [Map.lookup constructor (csCtors state)]
        ] $ \(constructor, constructorInfo) -> do
          instantiated <-
            ctorFieldTypesWithQ
              ctx
              constructor
              constructorInfo
              targetValue
              sourceSpan
          let explicitSourceCount =
                length
                  [ ()
                  | (icit, _) <- ciSourceFields constructorInfo
                  , icit == Expl
                  ]
              sourceFields =
                drop (length instantiated - explicitSourceCount) instantiated
          fields <-
            forM sourceFields $ \(_, quantity, fieldValue) -> do
              fieldType <- quoteIn ctx fieldValue >>= zonkTermM (ctxLen ctx)
              case delaborateType ctx sourceSpan fieldType of
                Just fieldExpression ->
                  pure
                    ( DerivedNominalField
                        quantity
                        fieldType
                        fieldExpression
                    )
                Nothing -> do
                  errAt sourceSpan "E_DERIVE_UNSUPPORTED" (Just "kappa.derive")
                    "derive Eq could not reify one checked field type as ordinary source syntax (§14.5.1)"
                  pure
                    ( DerivedNominalField
                        quantity
                        fieldType
                        (EHole Nothing sourceSpan)
                    )
          pure (constructor, fields)
      let self = nominalDataHead target
          premiseCandidates =
            [ (trait, fieldType, fieldExpression)
            | (_, fields) <- constructors
            , DerivedNominalField quantity fieldType fieldExpression <- fields
            , let trait =
                    if quantity == Q0
                      then gPrel "IsProp"
                      else gPrel "Eq"
            , quantity == Q0 || nominalDataHead fieldType /= self
            ]
          uniquePremises =
            nubBy
              (\(leftTrait, leftType, _) (rightTrait, rightType, _) ->
                 leftTrait == rightTrait && leftType == rightType)
              premiseCandidates
          premises =
            [ derivedTraitHead sourceSpan (gnameText trait) fieldExpression
            | (trait, _, fieldExpression) <- uniquePremises
            ]
          shape =
            [ (constructor, fields)
            | (constructor, fields) <- constructors
            ]
      pure (shape, premises)

derivedEqualityBody
  :: Span
  -> Expr
  -> DerivedNominalShape
  -> Name
  -> Name
  -> Expr
derivedEqualityBody span' target shape xName yName =
  EMatch (ETuple [EVar xName, EVar yName] span')
    ( [ MatchCase
          (derivedEqualityPairPattern span' target constructor xFields constructor yFields)
          Nothing
          (compareFields fields xFields yFields)
          span'
      | (constructor, fields) <- shape
      , let xFields = derivedEqualityFieldNames span' "__derive_x" constructor fields
            yFields = derivedEqualityFieldNames span' "__derive_y" constructor fields
      ]
        ++ [MatchCase (PWild span') Nothing falseExpr span']
    )
    span'
  where
    compareFields [] [] [] = trueExpr
    compareFields (field : fields) (left : lefts) (right : rights)
      | dnfQuantity field == Q0 =
          compareFields fields lefts rights
      | not (hasRuntimeDerivedField fields) =
          fieldEquality
            span'
            (dnfTypeExpression field)
            left
            right
      | otherwise =
          EIf
            [ ( fieldEquality
                  span'
                  (dnfTypeExpression field)
                  left
                  right
              , compareFields fields lefts rights
              )
            ]
            (Just falseExpr)
            span'
    compareFields _ _ _ = falseExpr
    trueExpr = EVar (Name "True" span')
    falseExpr = EVar (Name "False" span')

type DerivedEqEvidenceNames = Map GName [Maybe Name]

data DerivedEqFieldMethod
  = DerivedEqFieldEvidence !(Maybe Name)
  | DerivedEqFieldRecursive
  deriving stock (Eq)

type DerivedEqFieldMethods = Map GName [DerivedEqFieldMethod]

data DerivedFunctionalEquality = DerivedFunctionalEquality
  { dfeIdentity :: !GName
  , dfeBindingName :: !Name
  , dfeTerm :: !Term
  , dfeType :: !Value
  , dfeDomain :: !Value
  , dfeDomainExpr :: !Expr
  , dfeShape :: !DerivedNominalShape
  , dfeMethods :: !DerivedEqFieldMethods
  }

data DerivedEqEvidenceBinding = DerivedEqEvidenceBinding
  { deebName :: !Name
  , deebDictionary :: !Term
  , deebDictionaryType :: !Value
  }

-- | Align each runtime-relevant nominal field with the exact @Eq@ dictionary
-- selected by the already checked comparator. The comparator Core, dictionary
-- classifier, trait identity, and carrier conversion all participate in the
-- check; source spellings do not. A comparator with a different control-flow
-- shape (including a call to a recursive helper) returns 'Nothing' for the
-- functional-induction provider rather than guessing an alignment.
derivedEqEvidenceForComparator
  :: Ctx
  -> Span
  -> DerivedNominalShape
  -> Term
  -> CheckM (Maybe ([DerivedEqEvidenceBinding], DerivedEqEvidenceNames))
derivedEqEvidenceForComparator ctx site shape comparator = do
  runtimeFields <-
    forM runtimeFieldTerms $ \(constructor, fieldIndex, fieldType) ->
      (constructor, fieldIndex,) <$> evalIn ctx fieldType
  evidenceComponent <-
    pendingEvidenceComponentTerms ctx (map snd rawCandidates)
  flushPendingSelected evidenceComponent
  checkedCandidates <-
    forM rawCandidates $ \(depth, dictionary) -> do
      checked <- zonkTermM (ctxLen ctx + depth) dictionary
      pure (shiftTerm (-depth) 0 checked)
  candidates <- mapM authenticate checkedCandidates
  case sequence candidates of
    Nothing -> pure Nothing
    Just exact
      | length exact /= length runtimeFields -> pure Nothing
      | otherwise -> do
          let aligned = zip runtimeFields exact
          beforeAlignment <- get
          carrierMatches <-
            forM aligned $ \((_, _, fieldType), (_, _, carrier)) ->
              unify ctx fieldType carrier
          let carriersMatch = and carrierMatches
          if not carriersMatch
            then put beforeAlignment >> pure Nothing
            else do
              let bindings =
                    [ DerivedEqEvidenceBinding
                        (evidenceName constructor fieldIndex ordinal)
                        dictionary
                        dictionaryType
                    | ( ordinal
                      , ( (constructor, fieldIndex, _)
                        , (dictionary, dictionaryType, _)
                        )
                      ) <- zip [0 :: Int ..] aligned
                    ]
                  namesByField =
                    Map.fromList
                      [ ( constructor
                        , [ if dnfQuantity field == Q0
                              then Nothing
                              else
                                Just
                                  ( evidenceName
                                      constructor
                                      fieldIndex
                                      (runtimeOrdinal constructor fieldIndex)
                                  )
                          | (fieldIndex, field) <- zip [0 :: Int ..] fields
                          ]
                        )
                      | (constructor, fields) <- shape
                      ]
              pure (Just (bindings, namesByField))
  where
    rawCandidates =
      foldTermWithDepth collect 0 comparator

    collect depth node =
      case selectedEqOperation node of
        Nothing -> []
        Just (_, _, dictionaries) ->
          [ (depth, dictionary)
          | (_, dictionary) <- dictionaries
          ]

    runtimeFieldTerms =
      [ (constructor, fieldIndex, dnfTypeTerm field)
      | (constructor, fields) <- shape
      , (fieldIndex, field) <- zip [0 :: Int ..] fields
      , dnfQuantity field /= Q0
      ]

    authenticate dictionary
      | not (termScopedAt (ctxLen ctx) dictionary) = pure Nothing
      | otherwise =
          coreTermClassifierInCtx ctx dictionary >>= \case
            Nothing -> pure Nothing
            Just dictionaryType -> do
              state <- get
              forceM dictionaryType >>= \case
                VGlobI trait _ arguments
                  | trait == gPrel "Eq"
                  , Just [(_, carrier)] <-
                      traitSemanticSpineIn state trait arguments ->
                      pure (Just (dictionary, dictionaryType, carrier))
                _ -> pure Nothing

    evidenceName constructor fieldIndex ordinal =
      Name
        ( "__derive_eq_evidence_"
            <> gnameText constructor
            <> "_"
            <> T.pack (show fieldIndex)
            <> "_"
            <> T.pack (show ordinal)
        )
        site

    runtimeOrdinal targetConstructor targetFieldIndex =
      fromMaybe 0
        ( List.findIndex
            (\(constructor, fieldIndex, _) ->
               constructor == targetConstructor
                 && fieldIndex == targetFieldIndex)
            runtimeFieldTerms
        )

bindDerivedEqEvidence
  :: Ctx
  -> [DerivedEqEvidenceBinding]
  -> CheckM Ctx
bindDerivedEqEvidence source = foldM bindOne source
  where
    bindOne active DerivedEqEvidenceBinding {..} = do
      dictionaryValue <- evalIn source deebDictionary
      pure
        ( bindCtxLet
            (nameText deebName)
            False
            deebDictionaryType
            dictionaryValue
            active
        )

closeDerivedEqEvidence
  :: [DerivedEqEvidenceBinding]
  -> Term
  -> Term
closeDerivedEqEvidence bindings body0 =
  foldl'
    (\body (index, binding) ->
       substTopTermAt
         0
         (shiftTerm index 0 (deebDictionary binding))
         body)
    body0
    (reverse (zip [0 :: Int ..] bindings))

-- | Find the checked equation providers reached directly or transitively by
-- a custom equality comparator, and independently certify their ordinary
-- termination before a derivation may inspect those equations.  The result
-- is keyed entirely by resolved globals and Core dependencies.  A missing
-- body, an incomplete SCC, or an unverified decrease rejects the provider.
checkedFunctionalEqualityHelpers :: Term -> CheckM [GName]
checkedFunctionalEqualityHelpers comparator = do
  baseline <- get
  let declarations = csTerminationDecls baseline
      declarationNames = Map.keysSet declarations
      roots = Set.intersection declarationNames (globalsOfTerm comparator)
      reachable = closeReachable declarations roots
      selected = Map.restrictKeys declarations reachable
      dependencies declaration =
        Set.toList
          ( Set.intersection
              reachable
              (globalsOfTerm (tdCoreBody declaration))
          )
      components =
        stronglyConnComp
          [ (declaration, identity, dependencies declaration)
          | (identity, declaration) <- Map.toAscList selected
          ]
      members = \case
        AcyclicSCC declaration -> [declaration]
        CyclicSCC group -> group
  result <- certify [] (map members components)
  put baseline
  pure result
  where
    closeReachable declarations = go Set.empty . Set.toAscList
      where
        go reached [] = reached
        go reached (identity : pending)
          | Set.member identity reached = go reached pending
          | otherwise =
              let discovered =
                    maybe
                      []
                      ( Set.toAscList
                          . Set.intersection (Map.keysSet declarations)
                          . globalsOfTerm
                          . tdCoreBody
                      )
                      (Map.lookup identity declarations)
               in go (Set.insert identity reached) (discovered ++ pending)

    certify accepted [] = pure (reverse accepted)
    certify accepted (group : groups)
      | null group = certify accepted groups
      | otherwise = do
          let identities = map tdName group
          outcome <-
            withTemporaryReducibleGlobals accepted $
              withSccOpaque identities $
                verifyTerminationSccIn emptyCtx group
          if outcome == TerminationConversionSafe
            then certify (reverse identities ++ accepted) groups
            else pure []

checkedFunctionalEqualityPlan
  :: Ctx
  -> Span
  -> Term
  -> [GName]
  -> CheckM (Maybe DerivedFunctionalEquality)
checkedFunctionalEqualityPlan ctx site comparator certified = do
  plans <- catMaybes <$> mapM planFor occurrences
  pure $ case plans of
    [plan] -> Just plan
    _ -> Nothing
  where
    certifiedSet = Set.fromList certified
    occurrences =
      nub
        [ (identity, universes)
        | (_, CGlobal identity universes) <- foldTermWithDepth (\depth term -> [(depth, term)]) 0 comparator
        , Set.member identity certifiedSet
        ]

    planFor (identity, universes) = do
      let helperTerm = CGlobal identity universes
      coreTermClassifierInCtx ctx helperTerm >>= \case
        Nothing -> pure Nothing
        Just helperType ->
          binaryBooleanDomain helperType >>= \case
            Nothing -> pure Nothing
            Just domain -> do
              domainTerm <- quoteIn ctx domain
              case delaborateType ctx site domainTerm of
                Nothing -> pure Nothing
                Just domainExpr -> do
                  (shape, _) <- deriveNominalShape ctx site domainTerm
                  methods <- derivedRecursiveFieldMethods ctx domain shape
                  let hasRecursive =
                        any
                          (any (== DerivedEqFieldRecursive))
                          (Map.elems methods)
                  if null shape || not hasRecursive
                    then pure Nothing
                    else
                      pure
                        ( Just
                            DerivedFunctionalEquality
                              { dfeIdentity = identity
                              , dfeBindingName = Name "__derive_functional_comparator" site
                              , dfeTerm = helperTerm
                              , dfeType = helperType
                              , dfeDomain = domain
                              , dfeDomainExpr = domainExpr
                              , dfeShape = shape
                              , dfeMethods = methods
                              }
                        )

    binaryBooleanDomain helperType =
      forceM helperType >>= \case
        VPiM _ Expl _ _ _ firstDomain firstClosure -> do
          secondType <- clApp firstClosure (VRigid (ctxLen ctx) [])
          forceM secondType >>= \case
            VPiM _ Expl _ _ _ _ secondClosure -> do
              resultType <- clApp secondClosure (VRigid (ctxLen ctx + 1) [])
              forceM resultType >>= \case
                VGlobI boolean _ arguments
                  | boolean == prelBool
                  , null arguments -> pure (Just firstDomain)
                _ -> pure Nothing
            _ -> pure Nothing
        _ -> pure Nothing

derivedRecursiveFieldMethods
  :: Ctx
  -> Value
  -> DerivedNominalShape
  -> CheckM DerivedEqFieldMethods
derivedRecursiveFieldMethods ctx recursiveDomain shape =
  Map.fromList <$> mapM constructorMethods shape
  where
    constructorMethods (constructor, fields) =
      (constructor,) <$> mapM fieldMethod fields

    fieldMethod field
      | dnfQuantity field == Q0 =
          pure (DerivedEqFieldEvidence Nothing)
      | otherwise = do
          fieldType <- evalIn ctx (dnfTypeTerm field)
          baseline <- get
          recursive <- unify ctx fieldType recursiveDomain
          put baseline
          pure
            ( if recursive
                then DerivedEqFieldRecursive
                else DerivedEqFieldEvidence Nothing
            )

-- | Temporarily expose already-certified equations while preserving every
-- other state change made by the enclosed checker action.  Restoring just the
-- reducibility bits is important for speculative derive candidates: metas and
-- selected evidence from a successful ordinary check must survive, while the
-- module-level termination pass remains the sole publisher of permanent
-- conversion transparency.
withTemporaryReducibleGlobals :: [GName] -> CheckM a -> CheckM a
withTemporaryReducibleGlobals identities action = do
  globals <- gets csGlobals
  let saved =
        Map.map gdReducible
          (Map.restrictKeys globals (Set.fromList identities))
  modify' $ \state ->
    invalidateSemanticCaches
      state
        { csGlobals =
            foldr
              (Map.adjust (\definition -> definition {gdReducible = True}))
              (csGlobals state)
              identities
        }
  result <- action
  modify' $ \state ->
    invalidateSemanticCaches
      state
        { csGlobals =
            Map.foldlWithKey'
              (\globals identity reducible ->
                 Map.adjust
                   (\definition -> definition {gdReducible = reducible})
                   identity
                   globals)
              (csGlobals state)
              saved
        }
  pure result

derivedEqualitySoundBody
  :: Span
  -> Expr
  -> DerivedNominalShape
  -> DerivedEqEvidenceNames
  -> Name
  -> Name
  -> Name
  -> Expr
derivedEqualitySoundBody span' target shape evidenceNames xName yName proofName =
  derivedEqualitySoundBodyWithMethods
    span'
    target
    shape
    (Map.map (map DerivedEqFieldEvidence) evidenceNames)
    Nothing
    xName
    yName
    proofName

derivedEqualitySoundBodyWithMethods
  :: Span
  -> Expr
  -> DerivedNominalShape
  -> DerivedEqFieldMethods
  -> Maybe (Name, Name)
  -> Name
  -> Name
  -> Name
  -> Expr
derivedEqualitySoundBodyWithMethods span' target shape methods recursion xName yName proofName =
  EMatch (EVar xName)
    [ MatchCase
        (derivedEqualityCtorPattern span' target constructor xFields)
        Nothing
        ( EMatch (EVar yName)
            [ MatchCase
                (derivedEqualityCtorPattern span' target other yFields)
                Nothing
                ( if constructor == other
                    then
                      proveFields
                        fields
                        (Map.findWithDefault defaultMethods constructor methods)
                        xFields
                        yFields
                        (EVar proofName)
                    else eliminateFalseProof (EVar proofName)
                )
                span'
            | (other, otherFields) <- shape
            , let yFields =
                    derivedEqualityFieldNames
                      span'
                      "__derive_sound_y"
                      other
                      otherFields
            ]
            span'
        )
        span'
    | (constructor, fields) <- shape
    , let xFields =
            derivedEqualityFieldNames span' "__derive_sound_x" constructor fields
    ]
    span'
  where
    proveFields [] _ [] [] _ = reflExpr span'
    proveFields
      (field : fields)
      (method : methods')
      (left : lefts)
      (right : rights)
      proof
        | dnfQuantity field == Q0 =
            matchRefl
              span'
              (subsingletonEquality span' fieldType left right)
              (proveFields fields methods' lefts rights proof)
        | not (hasRuntimeDerivedField fields) =
            let fieldProof =
                  fieldSoundProof fieldType method left right proof
             in matchRefl
                  span'
                  fieldProof
                  (proveFields fields methods' lefts rights (reflExpr span'))
        | otherwise =
            let condition =
                  fieldCondition fieldType method left right
                remainder =
                  fieldEqualityBodyWithMethods
                    span'
                    fields
                    methods'
                    recursion
                    lefts
                    rights
                headProof =
                  callNamed
                    span'
                    "boolGuardCondition"
                    [condition, remainder, proof]
                tailProof =
                  callNamed
                    span'
                    "boolGuardBody"
                    [condition, remainder, proof]
                fieldProof =
                  fieldSoundProof fieldType method left right headProof
             in matchRefl
                  span'
                  fieldProof
                  (proveFields fields methods' lefts rights tailProof)
      where
        fieldType = dnfTypeExpression field
    proveFields _ _ _ _ proof = eliminateFalseProof proof
    eliminateFalseProof proof =
      matchRefl span' proof (EImpossible span')
    defaultMethods = repeat (DerivedEqFieldEvidence Nothing)
    fieldCondition fieldType method left right =
      case method of
        DerivedEqFieldEvidence evidence ->
          fieldEqualityWithEvidence span' fieldType evidence left right
        DerivedEqFieldRecursive ->
          case recursion of
            Just (comparator, _) ->
              callNamed span' (nameText comparator) [EVar left, EVar right]
            Nothing ->
              fieldEqualityWithEvidence span' fieldType Nothing left right
    fieldSoundProof fieldType method left right proof =
      case (method, recursion) of
        (DerivedEqFieldRecursive, Just (_, helper)) ->
          callNamed span' (nameText helper) [EVar left, EVar right, proof]
        (DerivedEqFieldEvidence evidence, _) ->
          fieldEvidenceMemberCall
            span'
            fieldType
            evidence
            "eqSound"
            [EVar left, EVar right, proof]
        (DerivedEqFieldRecursive, Nothing) -> EImpossible span'

derivedEqualityCompleteBody
  :: Span
  -> Expr
  -> DerivedNominalShape
  -> DerivedEqEvidenceNames
  -> Name
  -> Name
  -> Name
  -> Expr
derivedEqualityCompleteBody span' target shape evidenceNames xName yName proofName =
  derivedEqualityCompleteBodyWithMethods
    span'
    target
    shape
    (Map.map (map DerivedEqFieldEvidence) evidenceNames)
    Nothing
    xName
    yName
    proofName

derivedEqualityCompleteBodyWithMethods
  :: Span
  -> Expr
  -> DerivedNominalShape
  -> DerivedEqFieldMethods
  -> Maybe (Name, Name)
  -> Name
  -> Name
  -> Name
  -> Expr
derivedEqualityCompleteBodyWithMethods span' target shape methods recursion xName _yName proofName =
  matchRefl
    span'
    (EVar proofName)
    ( EMatch (EVar xName)
        [ MatchCase
            (derivedEqualityCtorPattern span' target constructor fields)
            Nothing
            ( proveReflexive
                constructorFields
                (Map.findWithDefault defaultMethods constructor methods)
                fields
            )
            span'
        | (constructor, constructorFields) <- shape
        , let fields =
                derivedEqualityFieldNames
                  span'
                  "__derive_complete_x"
                  constructor
                  constructorFields
        ]
        span'
    )
  where
    proveReflexive [] _ [] = reflExpr span'
    proveReflexive (fieldInfo : fields) (method : methods') (field : rest)
      | dnfQuantity fieldInfo == Q0 =
          proveReflexive fields methods' rest
      | not (hasRuntimeDerivedField fields) =
          fieldCompleteProof fieldType method field
      | otherwise =
          let condition =
                fieldCondition fieldType method field field
              remainder =
                fieldEqualityBodyWithMethods
                  span'
                  fields
                  methods'
                  recursion
                  rest
                  rest
              headProof =
                fieldCompleteProof fieldType method field
              tailProof = proveReflexive fields methods' rest
           in callNamed
                span'
                "boolGuardComplete"
                [condition, remainder, headProof, tailProof]
      where
        fieldType = dnfTypeExpression fieldInfo
    proveReflexive _ _ _ = EImpossible span'
    defaultMethods = repeat (DerivedEqFieldEvidence Nothing)
    fieldCondition fieldType method left right =
      case method of
        DerivedEqFieldEvidence evidence ->
          fieldEqualityWithEvidence span' fieldType evidence left right
        DerivedEqFieldRecursive ->
          case recursion of
            Just (comparator, _) ->
              callNamed span' (nameText comparator) [EVar left, EVar right]
            Nothing ->
              fieldEqualityWithEvidence span' fieldType Nothing left right
    fieldCompleteProof fieldType method field =
      case (method, recursion) of
        (DerivedEqFieldRecursive, Just (_, helper)) ->
          callNamed
            span'
            (nameText helper)
            [EVar field, EVar field, reflExpr span']
        (DerivedEqFieldEvidence evidence, _) ->
          fieldEvidenceMemberCall
            span'
            fieldType
            evidence
            "eqComplete"
            [EVar field, EVar field, reflExpr span']
        (DerivedEqFieldRecursive, Nothing) -> EImpossible span'

derivedFunctionalEqualityMemberBody
  :: Bool
  -> Span
  -> Expr
  -> DerivedNominalShape
  -> DerivedEqFieldMethods
  -> DerivedFunctionalEquality
  -> Name
  -> Name
  -> Name
  -> Expr
derivedFunctionalEqualityMemberBody sound span' target shape rootMethods functional xName yName proofName =
  ELet
    [ LetBind
        False
        emptyPrefix
        (PVar helperProofName)
        (Just helperProofType)
        (ELambda Nothing (map simpleBinder [helperX, helperY, helperProof]) helperBody span')
        span'
    ]
    rootBody
    span'
  where
    comparatorName = dfeBindingName functional
    helperProofName =
      Name
        (if sound then "__derive_functional_sound" else "__derive_functional_complete")
        span'
    helperX = Name "__derive_functional_x" span'
    helperY = Name "__derive_functional_y" span'
    helperProof = Name "__derive_functional_proof" span'
    recursion = Just (comparatorName, helperProofName)
    helperProofType =
      derivedFunctionalEqualityProofType
        sound
        span'
        (dfeDomainExpr functional)
        comparatorName
        helperX
        helperY
        helperProof
    helperBody
      | sound =
          derivedEqualitySoundBodyWithMethods
            span'
            (dfeDomainExpr functional)
            (dfeShape functional)
            (dfeMethods functional)
            recursion
            helperX
            helperY
            helperProof
      | otherwise =
          derivedEqualityCompleteBodyWithMethods
            span'
            (dfeDomainExpr functional)
            (dfeShape functional)
            (dfeMethods functional)
            recursion
            helperX
            helperY
            helperProof
    rootBody
      | sound =
          derivedEqualitySoundBodyWithMethods
            span'
            target
            shape
            rootMethods
            recursion
            xName
            yName
            proofName
      | otherwise =
          derivedEqualityCompleteBodyWithMethods
            span'
            target
            shape
            rootMethods
            recursion
            xName
            yName
            proofName

derivedFunctionalEqualityProofType
  :: Bool
  -> Span
  -> Expr
  -> Name
  -> Name
  -> Name
  -> Name
  -> Expr
derivedFunctionalEqualityProofType sound span' domain comparator xName yName proofName =
  EArrow (typed xName domain) $
    EArrow (typed yName domain) $
      EArrow (typed proofName premise) conclusion
  where
    comparatorResult =
      callNamed span' (nameText comparator) [EVar xName, EVar yName]
    decisionTrue = equality comparatorResult (EVar (Name "True" span'))
    endpointsEqual = equality (EVar xName) (EVar yName)
    (premise, conclusion)
      | sound = (decisionTrue, endpointsEqual)
      | otherwise = (endpointsEqual, decisionTrue)
    typed name ty = (simpleBinder name) {bType = Just ty}
    equality left right =
      EApp
        (EOpRef Nothing (Name "=" span') span')
        [ArgExplicit left, ArgExplicit right]

derivedEqualityCtorPattern :: Span -> Expr -> GName -> [Name] -> Pattern
derivedEqualityCtorPattern span' target constructor fields =
  PCtor
    (CtorRef (targetHeadName target) (Name (gnameText constructor) span'))
    (map PVar fields)
    span'

derivedEqualityPairPattern
  :: Span
  -> Expr
  -> GName
  -> [Name]
  -> GName
  -> [Name]
  -> Pattern
derivedEqualityPairPattern span' target left leftFields right rightFields =
  PTuple
    [ derivedEqualityCtorPattern span' target left leftFields
    , derivedEqualityCtorPattern span' target right rightFields
    ]
    span'

derivedEqualityFieldNames
  :: Span
  -> Text
  -> GName
  -> [DerivedNominalField]
  -> [Name]
derivedEqualityFieldNames span' prefix constructor fields =
  [ Name
      (prefix <> "_" <> gnameText constructor <> "_" <> T.pack (show index))
      span'
  | (index, _) <- zip [0 :: Int ..] fields
  ]

fieldEqualityBody
  :: Span
  -> [DerivedNominalField]
  -> [Maybe Name]
  -> [Name]
  -> [Name]
  -> Expr
fieldEqualityBody span' fields evidences =
  fieldEqualityBodyWithMethods
    span'
    fields
    (map DerivedEqFieldEvidence evidences)
    Nothing

fieldEqualityBodyWithMethods
  :: Span
  -> [DerivedNominalField]
  -> [DerivedEqFieldMethod]
  -> Maybe (Name, Name)
  -> [Name]
  -> [Name]
  -> Expr
fieldEqualityBodyWithMethods span' fields methods recursion = go fields methods
  where
    go [] _ [] [] = EVar (Name "True" span')
    go (field : restFields) (method : restMethods) (left : lefts) (right : rights)
      | dnfQuantity field == Q0 = go restFields restMethods lefts rights
      | not (hasRuntimeDerivedField restFields) =
          condition field method left right
      | otherwise =
          EIf
            [ ( condition field method left right
              , go restFields restMethods lefts rights
              )
            ]
            (Just (EVar (Name "False" span')))
            span'
    go _ _ _ _ = EVar (Name "False" span')

    condition field method left right =
      case method of
        DerivedEqFieldEvidence evidence ->
          fieldEqualityWithEvidence
            span'
            (dnfTypeExpression field)
            evidence
            left
            right
        DerivedEqFieldRecursive ->
          case recursion of
            Just (comparator, _) ->
              callNamed span' (nameText comparator) [EVar left, EVar right]
            Nothing ->
              fieldEqualityWithEvidence
                span'
                (dnfTypeExpression field)
                Nothing
                left
                right

hasRuntimeDerivedField :: [DerivedNominalField] -> Bool
hasRuntimeDerivedField = any ((/= Q0) . dnfQuantity)

fieldEquality :: Span -> Expr -> Name -> Name -> Expr
fieldEquality span' fieldType left right =
  fieldEqualityWithEvidence span' fieldType Nothing left right

fieldEqualityWithEvidence
  :: Span
  -> Expr
  -> Maybe Name
  -> Name
  -> Name
  -> Expr
fieldEqualityWithEvidence span' fieldType evidence left right =
  fieldEvidenceMemberCall
    span'
    fieldType
    evidence
    "=="
    [EVar left, EVar right]

-- | Invoke one checked member of the exact selected @Eq@ dictionary. Keeping
-- the dictionary projection in the generated term preserves the comparator's
-- evidence identity and universe instantiation; routing through a freshly
-- specialized @eqBoolean*@ convenience wrapper would create a second
-- conversion obligation unrelated to the user's checked comparator.
fieldEvidenceMemberCall
  :: Span
  -> Expr
  -> Maybe Name
  -> Text
  -> [Expr]
  -> Expr
fieldEvidenceMemberCall span' fieldType evidence member arguments =
  EApp
    ( EDot
        (fieldEvidenceExpression span' fieldType evidence)
        (DotName (Name member span'))
    )
    (map ArgExplicit arguments)

fieldEvidenceExpression :: Span -> Expr -> Maybe Name -> Expr
fieldEvidenceExpression span' fieldType =
  maybe
    (traitEvidenceExpression span' "Eq" fieldType)
    EVar

subsingletonEquality :: Span -> Expr -> Name -> Name -> Expr
subsingletonEquality span' fieldType left right =
  EApp
    ( EDot
        (traitEvidenceExpression span' "IsSubsingleton" fieldType)
        (DotName (Name "allEqual" span'))
    )
    [ArgExplicit (EVar left), ArgExplicit (EVar right)]

traitEvidenceExpression :: Span -> Text -> Expr -> Expr
traitEvidenceExpression span' trait fieldType =
  callNamed
    span'
    "summon"
    [EApp (EVar (Name trait span')) [ArgExplicit fieldType]]

callNamed :: Span -> Text -> [Expr] -> Expr
callNamed span' name arguments =
  EApp
    (EVar (Name name span'))
    (map ArgExplicit arguments)

matchRefl :: Span -> Expr -> Expr -> Expr
matchRefl span' scrutinee body =
  EMatch
    scrutinee
    [ MatchCase
        (PCtor (CtorRef Nothing (Name "refl" span')) [] span')
        Nothing
        body
        span'
    ]
    span'

reflExpr :: Span -> Expr
reflExpr span' = EVar (Name "refl" span')

targetHeadName :: Expr -> Maybe Name
targetHeadName = \case
  EVar name -> Just name
  EApp function _ -> targetHeadName function
  _ -> Nothing

validateDerivedDeclarations :: Span -> [Decl] -> CheckM Bool
validateDerivedDeclarations _ [] = pure False
validateDerivedDeclarations sourceSpan generated = do
  results <- forM generated $ \case
    -- Generic declaration-level derive is validated by the same typed facet
    -- planner as source @instance G = derive@. The structural checks below
    -- apply only to specialized generators that emit an explicit body.
    DInstance (InstanceDecl _ _ _ InstanceDerive) _ -> pure True
    DInstance (InstanceDecl _ _ headExpression (InstanceMembers _)) _ ->
      validateHead headExpression
    _ -> pure False
  let valid = and results
  unless valid $
    errAt sourceSpan "E_DERIVE_UNSUPPORTED" (Just "kappa.derive")
      "the requested derivation is outside the checked conservative structural fragment (§14.5.1-§14.5.2)"
  pure valid
  where
    validateHead headExpression = do
      (traitIdentity, _, arguments) <- instSplitHead headExpression
      case (traitIdentity, arguments) of
        (Just trait, [target])
          | trait == gPrel "IsSet" -> validateStructuralDerive (gPrel "IsSet") target
          | trait == gPrel "Eq" -> validateStructuralDerive (gPrel "Eq") target
          | trait == gPrel "ExactNaturalRepresentation" -> validateExactNaturalDerive target
          | trait == gPrel "RefinementView" -> validateRefinementViewDerive target
        _ -> pure False

validateStructuralDerive :: GName -> Expr -> CheckM Bool
validateStructuralDerive fieldTrait target = do
  targetTerm <- fst <$> inferType emptyCtx target
  targetTerm' <- zonkTermM 0 targetTerm
  state <- get
  case nominalDataHead targetTerm' >>= \dataName -> (dataName,) <$> Map.lookup dataName (csDatas state) of
    Nothing -> pure False
    Just (dataName, info) ->
      and <$> mapM (constructorEligible dataName) (diCtors info)
  where
    constructorEligible dataName constructor = do
      state <- get
      case Map.lookup constructor (csCtors state) of
        Nothing -> pure False
        Just info ->
          and <$> mapM (fieldEligible dataName) (constructorFieldBinders info)
    fieldEligible dataName (quantity, fieldType)
      | nominalDataHead fieldType == Just dataName = pure True
      | maxFreeIndexTerm fieldType >= 0 = pure False
      | otherwise = do
          fieldValue <- evalIn emptyCtx fieldType
          let requiredTrait = if quantity == Q0 then gPrel "IsProp" else fieldTrait
          goal <- globalValueM requiredTrait [(Expl, fieldValue)]
          derivationProbe emptyCtx (exprSpan target) goal

-- | Ask the unified derivation engine whether a closed structural obligation
-- is solvable without committing speculative metas, caches, expansions, or
-- diagnostics.  Declaration eligibility and expression-level @derive@ must
-- share one proof authority; otherwise a field can be accepted by one path
-- and rejected by the other.  A failed or diagnostic-producing search is an
-- ordinary conservative rejection.
derivationProbe :: Ctx -> Span -> Value -> CheckM Bool
derivationProbe ctx site goal = do
  baseline <- get
  diagnosticCount <- gets (length . csDiags)
  _ <- synthesizeDerivationWithFuel 24 ctx site goal
  diagnostics <- gets csDiags
  let solved = length diagnostics == diagnosticCount
  put baseline
  pure solved

validateExactNaturalDerive :: Expr -> CheckM Bool
validateExactNaturalDerive target = do
  targetTerm <- fst <$> inferType emptyCtx target
  state <- get
  case nominalDataHead targetTerm >>= \dataName -> (dataName,) <$> Map.lookup dataName (csDatas state) of
    Nothing -> pure False
    Just (dataName, info) -> do
      let runtimeFields constructor =
            [ fieldType
            | (quantity, fieldType) <-
                maybe [] constructorFieldBinders (Map.lookup constructor (csCtors state))
            , quantity /= Q0
            ]
          fields = map runtimeFields (diCtors info)
          zeroCount = length [() | [] <- fields]
          successorCount =
            length
              [ ()
              | [fieldType] <- fields
              , nominalDataHead fieldType == Just dataName
              ]
      pure (length fields == 2 && zeroCount == 1 && successorCount == 1)

validateRefinementViewDerive :: Expr -> CheckM Bool
validateRefinementViewDerive target = do
  targetTerm0 <- fst <$> inferType emptyCtx target
  targetTerm <- zonkTermM 0 targetTerm0
  isJust <$> deriveRefinementViewShape (exprSpan target) target targetTerm

constructorFieldBinders :: CtorInfo -> [(Q, Term)]
constructorFieldBinders info =
  drop (length binders - fieldCount) binders
  where
    -- 'ciFields' contains only explicit source fields because it also stores
    -- explicit-field defaults. Semantic constructor shape must include erased
    -- implicit proof fields as well; 'ciSourceFields' is the exact source
    -- telescope with family/generated binders intentionally absent.
    fieldCount = length (ciSourceFields info)
    binders = piBinders (ciType info)
    piBinders = \case
      CPiBoundM _ _ quantity _ _ _ domain body ->
        (quantity, domain) : piBinders body
      _ -> []

nominalDataHead :: Term -> Maybe GName
nominalDataHead term =
  termHeadGlob (stripIdentityWrappers (fst (spineOfTerm (stripIdentityWrappers term))))

compilerOwnedTypeLevelInstance :: InstanceDecl -> CheckM Bool
compilerOwnedTypeLevelInstance (InstanceDecl _ premises hd _) = do
  currentModule <- gets csModule
  (traitG, _, args) <- instSplitHead hd
  if currentModule /= modTypeLevel
      || not (null premises)
      || traitG `notElem` map Just compilerOwnedTypeLevelTraits
    then pure False
    else case args of
      [arg] -> do
        (argTm, _) <- inferType emptyCtx arg
        pure (argTm == CGlob prelTypeLevel)
      _ -> pure False

compilerOwnedTypeLevelTraits :: [GName]
compilerOwnedTypeLevelTraits =
  [ gPrel "Eq"
  , prelOrd
  , gPrel "Zero"
  , gPrel "One"
  , gPrel "FromInteger"
  , prelSuccessor
  , gPrel "Add"
  , prelMax
  ]

intrinsicUniverseTraits :: Set GName
intrinsicUniverseTraits = Set.fromList [prelIsNType, prelRuntimeErased]

instanceHeadPass :: Decl -> CheckM ()
instanceHeadPass declaration =
  withDeclarationUniverseSchema declaration (instanceHeadPassRaw declaration)

instanceHeadPassRaw :: Decl -> CheckM ()
instanceHeadPassRaw = \case
  DInstance (InstanceDecl _ premises hd _) sp -> do
    already <- gets (Map.member sp . csPreInstances)
    unless already $ do
      mpi <- registerInstanceHead premises hd sp
      modify' $ \st -> st {csPreInstances = Map.insert sp mpi (csPreInstances st)}
  _ -> pure ()

-- | Elaborate an instance head and register the dictionary global
-- (type only — 'elabInstance' fills the value) and the instance-set
-- entry consulted by §14.3.1 search.
registerInstanceHead :: [Expr] -> Expr -> Span -> CheckM (Maybe PreInstance)
registerInstanceHead premises hd sp = do
  (traitIdentity, _, _) <- instSplitHead hd
  dictName <-
    stableGeneratedNameAt
      "instance-dictionary"
      (maybe "invalid" gnameText traitIdentity)
      sp
  dictG <- gets (\state -> GName (csModule state) dictName)
  withActiveUniverseDefinition dictG (registerInstanceHeadAs dictG premises hd sp)

registerInstanceHeadAs :: GName -> [Expr] -> Expr -> Span -> CheckM (Maybe PreInstance)
registerInstanceHeadAs dictG premises hd sp = do
  -- head must be Trait args...
  (traitG, explicitUniverseArguments, argEs) <- instSplitHead hd
  st <- get
  case traitG >>= \g -> g <$ Map.lookup g (csTraits st) of
    Nothing -> do
      errAt sp "E_INSTANCE_HEAD" (Just "kappa-hs.trait.bad-instance-head")
        "instance head must be a trait applied to type arguments"
      pure Nothing
    Just g
      | csModule st /= preludeModule
      , g `Set.member` intrinsicUniverseTraits -> do
          errAt sp "E_UNIVERSE_LEVEL_EXPRESSION"
            (Just "kappa.universe.level-expression")
            ( "instances for intrinsic trait '" <> gnameText g
                <> "' are compiler-owned and cannot be declared in source (§11.1.4)"
            )
          pure Nothing
    Just g -> do
      -- Instance-head variables are the unresolved identifier leaves of the
      -- normalized head/premises. This includes the spec's conventional
      -- uppercase parametric names (`instance BadReflect A`) while resolved
      -- constructors and trait heads remain globals, never binders.
      fvs <- instanceFreeVars (hd : premises)
      compilerGeneratedDerive <-
        gets
          ( any
              (any (generatedInstanceAt sp))
              . Map.elems
              . csDerivedDecls
          )
      -- §14.3.5 instance-search termination (Paterson-style): every premise
      -- must be structurally smaller than the head, so resolution cannot
      -- loop. A premise is rejected if its constructor-and-variable size is
      -- not strictly smaller than the head's, or if it uses some type
      -- variable more often than the head does. Rejecting at declaration
      -- time keeps a circular instance (e.g. `Container f => Container f`,
      -- or `(C f, C f, C f) => C f`) out of the search set entirely — the
      -- depth backstop alone does not stop the exponential breadth.
      let headOccs = constraintIdOccs hd
          headSize = length headOccs
          headName = constraintHead hd
          occCount xs v = length (filter (== v) xs)
          patersonViolation p =
            let pOccs = constraintIdOccs p
                -- the strict-size condition (§14.3.5) bites only for a
                -- premise on the SAME trait as the head — that is the
                -- self-recursive case that can loop. A cross-trait bridge
                -- (e.g. the prelude's `Eq a => Equiv a`) is well-founded
                -- even at equal size, so only the variable-occurrence
                -- condition applies there.
                sameTrait = constraintHead p == headName
             in ( sameTrait
                    && not compilerGeneratedDerive
                    && length pOccs >= headSize
                )
                  || any (\v -> occCount pOccs v > occCount headOccs v) fvs
      if any patersonViolation premises
        then do
          errAt sp "E_INSTANCE_SEARCH_NONTERMINATING" (Just "kappa.termination.failure")
            ( "instance for trait '" <> gnameText g
                <> "' has a premise that is not structurally smaller than the head, "
                <> "so instance search may not terminate; every premise must be strictly "
                <> "smaller than the head and use no type variable more often than the head (§14.3.5)"
            )
          pure Nothing
        else patersonOk explicitUniverseArguments g argEs
  where
    generatedInstanceAt wanted = \case
      DInstance _ generatedSpan -> generatedSpan == wanted
      _ -> False

    patersonOk explicitUniverseArguments g argEs = do
      fvs <- instanceFreeVars (hd : premises)
      -- Infer each implicitly-universalized head variable's domain from the
      -- whole premise/head use, rather than fixing it to Type0. The
      -- provisional parametric contract is finalized below once the trait
      -- head has constrained these metas.
      fvTele0 <- forM fvs $ \v -> do
        kind <- freshMeta
        -- The domain meta has not yet established whether this is a kind
        -- parameter or an ordinary first-class value (for example the fixed
        -- TypeLevel in a parameterized Monotone instance).  Header checking is
        -- type-position-only, so start with ordinary observation and let
        -- 'finalizeGeneratedTelescope' install the erased parametric contract
        -- exactly when the inferred domain is a parametric kind.  Starting at
        -- Parametric here rejects an ordinary value while its own head is
        -- constraining the domain, before finalization can correct the mode.
        pure (TelescopeEntry Impl Ordinary FormationOrdinary QW False v kind Nothing)
      -- Implicitly-universalized head variables are not evidence premises.
      -- Keeping them out of local candidate search while their domain metas
      -- are being constrained prevents a value variable from solving itself
      -- to a trait dictionary (for example @k@ in @Monotone (add k)@).
      -- The finalized telescope remains implicit; only explicit instance
      -- premises become candidates through 'instBindPremises'.
      ctx0 <- foldM bindHeadVariable emptyCtx fvTele0
      premTms <- forM premises $ \p -> fst <$> inferType ctx0 p
      ctxP' <- instBindPremises ctx0 premTms
      -- head arguments check against the trait constructor's parameter
      -- types (so type constructors are valid arguments of
      -- higher-kinded traits, §14.1.2)
      traitDefinition <- gets (Map.lookup g . csGlobals)
      (traitHead, traitUniverses, checkedArguments) <- case traitDefinition of
        Just definition -> do
          (headTerm, traitTy, universes) <- case explicitUniverseArguments of
            Nothing -> instantiateGlobal g definition
            Just levelExpressions -> do
              supplied <- mapM (fmap snd . elabLevelExpr emptyCtx) levelExpressions
              let expected = dutParameterCount (gdUniverses definition)
                  found = length supplied
              when (expected /= found) $
                errAt sp "E_UNIVERSE_SCHEMA_ARITY_MISMATCH" (Just "kappa.universe.schema-arity")
                  ( "declaration '" <> gnameText g <> "' expects " <> T.pack (show expected)
                      <> " universe arguments, but this instantiation supplies " <> T.pack (show found)
                  )
              let actual = take expected (supplied ++ repeat LZero)
              (term, ty) <- specializeGlobalAt emptyCtx g definition actual
              pure (term, ty, actual)
          checkedArguments <- instCheckHeadArgs ctxP' traitTy argEs
          pure (headTerm, universes, checkedArguments)
        Nothing -> do
          checkedArguments <-
            forM argEs $ \argument -> do
              (term, _level) <- inferType ctxP' argument
              pure (term, Set.empty)
          pure (CGlob g, [], checkedArguments)
      fvTele <- finalizeGeneratedTelescope emptyCtx fvTele0
      let higherKindClassifierLevels = Set.unions (map snd checkedArguments)
      let teleLen = length fvTele + length premises
          argTms = map fst checkedArguments
      register
        g
        traitHead
        traitUniverses
        fvTele
        premTms
        argTms
        higherKindClassifierLevels
        teleLen
      where
        bindHeadVariable context entry = do
          domain <- evalIn context (teDomain entry)
          withBound <- extendLevelAssumption noSpan context (teLevelAssumption entry)
          pure
            ( bindCtxMQB
                (teMode entry)
                (teQ entry)
                (teName entry)
                False
                (teBorrow entry)
                domain
                withBound
            )
    register g traitHead traitUniverses fvTele premTms argTms higherKindClassifierLevels teleLen = do
      -- register the instance before checking members so member bodies
      -- can use the instance being defined (recursive instances, §14.3)
      (dictTyTerm0, _) <- instDictTy fvTele premTms traitHead argTms
      instantiationLevels <- gets csLevelInstantiationMetas
      let sourceLevels =
            Set.fromList
                  [ meta
                  | entry <- fvTele
                  , meta <-
                      levelMetasOfTerm (teDomain entry)
                        ++ maybe [] (\(lower, upper) -> levelMetas lower ++ levelMetas upper)
                             (teLevelAssumption entry)
                  ]
                  `Set.union` Set.unions
                    (map schemaBearingLevelMetas (premTms ++ argTms))
          -- An ordinary declaration occurrence is minimized before the
          -- generated dictionary is published.  A higher-kinded trait
          -- parameter is different: its checked classifier is part of the
          -- instance head's public contract.  For example, the universe at
          -- which @Applicative (IO e)@ accepts its result argument must remain
          -- abstract even though the matching @IO@ occurrence introduced it.
          -- Preserve exactly those levels authenticated by a Pi classifier;
          -- a first-order head such as @Eq TypeLevel@ still has no protected
          -- occurrence level and therefore retains its principal Type0
          -- specialization.
          protectedSourceLevels =
            Set.union
              (Set.difference sourceLevels instantiationLevels)
              higherKindClassifierLevels
      dictTyTerm <-
        principalizeGeneratedInterfaceOccurrences
          dictG
          protectedSourceLevels
          dictTyTerm0
      dictTy <- evalIn emptyCtx dictTyTerm
      -- §11.1.2.3A/§14.3: principal occurrence choices have been removed
      -- above.  The remaining normalized head and premises are the generated
      -- declaration's user-observable schema boundary.
      markDeclarationSchemaLevelCandidates dictG dictTyTerm
      schemaCount <- gets (Map.size . csActiveUniverseSchema)
      let schema = DeclarationUniverseTelescope schemaCount (schemaCount > 0)
      addGlobal dictG
        ( globalDefWithCoreType dictTyTerm
            (globalDefWithUniverses schema (GlobalDef dictTy Nothing False))
        )
      modify' $ \s ->
        invalidateSemanticCaches
          ( setCheckInstances
              ( InstanceEntry
                  g
                  traitUniverses
                  schema
                  teleLen
                  (map (shiftTerm (length premises) 0) premTms)
                  argTms
                  dictG
                  : csInstances s
              )
              s
          )
      pure (Just (PreInstance g fvTele premTms argTms dictG))

instSplitHead :: Expr -> CheckM (Maybe GName, Maybe [Expr], [Expr])
instSplitHead e = case e of
  EApp f args -> do
    (g, universes, es) <- instSplitHead f
    pure (g, universes, es ++ [a | ArgExplicit a <- args])
  EUniverseInstantiation base levels _ -> do
    (g, inherited, es) <- instSplitHead base
    case inherited of
      Nothing -> pure (g, Just levels, es)
      Just _ -> do
        errAt (exprSpan e) "E_UNIVERSE_SCHEMA_SCOPE" (Just "kappa.universe.schema-scope")
          "an instance trait head may carry only one explicit universe instantiation"
        pure (g, inherited, es)
  EVar n -> do
    mg <- lookupGlobalName (nameText n)
    pure (mg, Nothing, [])
  _ -> pure (Nothing, Nothing, [])

-- | Bind the instance's premise dictionaries as implicit-local candidates.
-- Each premise term was elaborated under the fv binders only, so the k-th
-- premise sits under k earlier premise binders and must be shifted by k. Each
-- dictionary also gets a DISTINCT name: 'localCandidate' dedups candidates by
-- name, so premises sharing a name (e.g. two @Eq@ premises @Eq e@, @Eq a@)
-- would shadow each other and the second goal would never resolve locally.
instBindPremises :: Ctx -> [Term] -> CheckM Ctx
instBindPremises ctx0 = go (0 :: Int) ctx0
  where
    go _ c [] = pure c
    go i c (p : rest) = do
      pv <- evalIn c (shiftTerm i 0 p)
      go (i + 1) (bindCtx ("__prem" <> T.pack (show i)) True pv c) rest

-- | Check an instance head against its owning trait telescope and retain only
-- authenticated source-owned classifier levels. Generated dictionary
-- principalization may preserve those identities, but never fresh occurrence
-- metas allocated by the observational inference probe.
instCheckHeadArgs :: Ctx -> Value -> [Expr] -> CheckM [(Term, Set LevelMeta)]
instCheckHeadArgs _ _ [] = pure []
instCheckHeadArgs ctx ty (e : es) = do
  t <- forceM ty
  case t of
    VPiM mode Expl q _ _ dom clo -> do
      -- Trait heads are type-position syntax (§14.3.1A). A parametric type
      -- witness may therefore instantiate a universe-classified trait
      -- parameter even when the dictionary's parameter quantity is not Q0;
      -- this does not expose the witness as an ordinary term value.
      domF <- forceM dom
      (tm, classifierLevels) <- case domF of
        VPiEvidenceM {} -> inferExactExplicitArg ctx mode q e dom
        _ -> do
          checked <- checkExplicitArg ctx mode q e dom
          pure (checked, Set.empty)
      v <- evalIn ctx tm
      rest <- clApp clo v >>= \cod -> instCheckHeadArgs ctx cod es
      pure ((tm, classifierLevels) : rest)
    _ -> do
      (tm, _classifierLevel) <- inferType ctx e
      rest <- instCheckHeadArgs ctx t es
      pure ((tm, Set.empty) : rest)

instDictTy :: Telescope -> [Term] -> Term -> [Term] -> CheckM (Term, Value)
instDictTy fvTele premTms traitHead argTms = do
  -- premises were elaborated under the fv binders only; the k-th
  -- premise domain sits under k earlier premise binders, so shift by
  -- k. The head ('argTms') was elaborated under fvs + all premises
  -- and is already correctly indexed.
  let dictHead = foldl (\f a -> CApp Expl f a) traitHead argTms
      withPrems = go (0 :: Int) premTms
      go _ [] = dictHead
      go k (p : ps) = CPiFormedM Ordinary FormationOrdinary Impl QW False "__p" (shiftTerm k 0 p) (go (k + 1) ps)
  let coreType = foldr telePi withPrems fvTele
  coreValue <- evalIn emptyCtx coreType
  pure (coreType, coreValue)

-- | Recover the owning trait's exact universe occurrence from the registered
-- instance head.  The instance registry is transformed together with the
-- dictionary declaration at every universe-finalization boundary, whereas
-- reparsing the dictionary's semantic type can observe an earlier
-- provisional reference shape while its body is still deferred.
instanceDictionaryTraitUniverses
  :: Span
  -> GName
  -> GName
  -> CheckM [Level]
instanceDictionaryTraitUniverses site dictionary expectedTrait = do
  state <- get
  case
      [ entry
      | entry <- csInstances state
      , ieDict entry == dictionary
      , ieTrait entry == expectedTrait
      ]
    of
      [entry] ->
        pure
          ( map
              (resolveFinalizedOwnerLevel state dictionary)
              (ieTraitUniverses entry)
          )
      _ -> malformed
  where
    malformed = do
      errAt site "E_INTERNAL_PRELUDE_INTERFACE" (Just "kappa.internal.compiler")
        ( "the registered head of instance dictionary '"
            <> gnameText dictionary
            <> "' does not identify exactly one entry for trait '"
            <> gnameText expectedTrait
            <> "'"
        )
      pure []

elabInstance :: InstanceDecl -> Span -> CheckM ()
elabInstance (InstanceDecl _ premises hd completion) sp = do
  let (wholeDerived, members) = case completion of
        InstanceMembers explicitMembers -> (False, explicitMembers)
        InstanceDerive -> (True, [])
  flushPending
  stash <- gets (Map.lookup sp . csPreInstances)
  mpi <- case stash of
    -- head already elaborated (or already rejected) by the pre-pass
    Just mpi -> pure mpi
    Nothing -> registerInstanceHead premises hd sp
  mpti <- case mpi of
    Nothing -> pure Nothing
    Just pinst -> gets (fmap ((,) pinst) . Map.lookup (piTrait pinst) . csTraits)
  forM_ mpti $ \(pinst, ti) -> do
    let g = piTrait pinst
        fvTele = piFvTele pinst
        premTms = piPremTms pinst
        argTms = piArgTms pinst
        dictG = piDictG pinst
    traitUniverses <-
      instanceDictionaryTraitUniverses sp dictG g
    diagnosticsBeforeBody <- gets (length . csDiags)
    withActiveUniverseDefinition dictG $ do
      ctx0 <- teleCtx fvTele
      ctxP' <- instBindPremises ctx0 premTms
      -- §14.1.4/§14.3.3: every supertrait premise of the trait must be
      -- satisfiable at the instance head (from the instance's own
      -- premises — including their transitive supertrait conformance
      -- paths — or the global instance set); the evidence found is
      -- stored in the dictionary's supertrait field
      superFields <- forM (tiSupers ti) $ \(fn, supClosed) -> do
        ec <- ec_
        argVs <- mapM (evalIn ctxP') argTms
        specializedSuper <- specializeDeclarationComponent g traitUniverses supClosed
        supF <- evalIn ctxP' specializedSuper
        supGoal <- forceM (evalApp ec supF [(Expl, a) | a <- argVs])
        mEv <- traitEvidence ctxP' sp supGoal
        case mEv of
          Just tm -> pure (Just (fn, tm))
          Nothing
            | wholeDerived || fn `Set.member` tiDerivedSupers ti -> pure Nothing
            | otherwise -> do
                gT <- quoteIn ctxP' supGoal
                errAt sp "E_DERIVE_SUPERTRAIT_UNSOLVED" (Just "kappa.derive")
                  ("instance does not satisfy the supertrait premise '" <> renderTerm gT <> "' of trait '" <> gnameText g <> "' (§14.1.4)")
                pure Nothing
      -- member definitions checked against member types, in declaration
      -- order; already-checked members (associated static members in
      -- particular) instantiate the dict binder of later member types
      -- (§14.3.4)
      let goFields done terminations [] =
            pure (reverse done, reverse terminations)
          goFields done terminations (mn : rest) = do
            let memberMode = Map.findWithDefault Ordinary mn (tiMemberModes ti)
            mfield <- case findMember mn members of
              Just (LetDef _ _ _ _ _ mbinders mResTy mdec mbody, msp) -> do
                memberTyV <-
                  memberSigInstance
                    g
                    traitUniverses
                    mn
                    argTms
                    ctxP'
                    (catMaybes superFields ++ reverse done)
                checked <-
                  checkInstanceMember
                    g
                    traitUniverses
                    ti
                    argTms
                    ctxP'
                    (catMaybes superFields)
                    (reverse done)
                    memberMode
                    memberTyV
                    mbinders
                    mResTy
                    mbody
                    msp
                let (tm, terminationBody) = checked
                pure
                  ( Just
                      ( (mn, tm)
                      , InstanceMemberTermination
                          mn
                          memberTyV
                          mbinders
                          mdec
                          terminationBody
                          msp
                      )
                  )
              Nothing -> case Map.lookup mn (tiDefaults ti) of
                -- the trait's default definition fills the member (§14.2.3)
                -- the default's own annotation mentions trait parameters
                -- and is superseded by the instantiated member type
                Just (_defaultOwner, defaultEmbedded, LetDef _ _ _ _ _ dbinders _ ddec dbody) -> do
                  memberTyV <-
                    memberSigInstance
                      g
                      traitUniverses
                      mn
                      argTms
                      ctxP'
                      (catMaybes superFields ++ reverse done)
                  (tm, terminationBody) <-
                    withEmbeddedDefaultProvenance defaultEmbedded $
                      checkInstanceMember
                        g
                        traitUniverses
                        ti
                        argTms
                        ctxP'
                        (catMaybes superFields)
                        (reverse done)
                        memberMode
                        memberTyV
                        dbinders
                        Nothing
                        dbody
                        sp
                  pure
                    ( Just
                        ( (mn, tm)
                        , InstanceMemberTermination
                            mn
                            memberTyV
                            dbinders
                            ddec
                            terminationBody
                            sp
                        )
                    )
                Nothing -> do
                  memberTyV <-
                    memberSigInstance
                      g
                      traitUniverses
                      mn
                      argTms
                      ctxP'
                      (catMaybes superFields ++ reverse done)
                  let declaredDerived =
                        wholeDerived || mn `Set.member` tiDerivedMembers ti
                  structural <-
                    if declaredDerived
                      then
                        deriveStructuralInstanceMember
                          g
                          dictG
                          traitUniverses
                          ti
                          argTms
                          ctxP'
                          (catMaybes superFields)
                          (reverse done)
                          memberMode
                          mn
                          memberTyV
                          sp
                      else pure Nothing
                  completed <- case structural of
                    Just result -> pure (Just result)
                    Nothing ->
                      completeOmittedMember
                        declaredDerived
                        mn
                        g
                        traitUniverses
                        ti
                        argTms
                        ctxP'
                        (catMaybes superFields)
                        (reverse done)
                        memberTyV
                        sp
                        >>= \case
                          Just proof -> pure (Just (proof, proof))
                          Nothing -> pure Nothing
                  case completed of
                      Just (proof, terminationBody) ->
                        pure
                          ( Just
                              ( (mn, proof)
                              , InstanceMemberTermination
                                  mn
                                  memberTyV
                                  []
                                  Nothing
                                  terminationBody
                                  sp
                              )
                          )
                      Nothing -> do
                        unless declaredDerived $
                          errAt sp "E_DERIVE_MEMBER_MISSING" (Just "kappa.derive")
                            ("instance does not define member '" <> mn <> "'")
                        pure Nothing
            case mfield of
              Nothing -> goFields done terminations rest
              Just (field, termination) ->
                goFields (field : done) (termination : terminations) rest
      (dictFields, memberTerminations) <- goFields [] [] (tiMembers ti)
      -- Derived supertraits are facets of the completed dictionary, not
      -- prerequisites for checking unrelated explicit/derived members. Retry
      -- unresolved derived slots with the completed member dictionary exposed
      -- as an ordinary implicit candidate. The resulting proof is then
      -- substituted with the checked record value; no incomplete evidence
      -- escapes this local derivation scope (§14.3.4A).
      completedDerivedSupers <-
        fmap catMaybes . forM (tiSupers ti) $ \(fn, supClosed) ->
          if not wholeDerived && fn `Set.notMember` tiDerivedSupers ti
              || isJust (lookup fn (catMaybes superFields))
            then pure Nothing
            else do
              ec <- ec_
              argVs <- mapM (evalIn ctxP') argTms
              specializedSuper <- specializeDeclarationComponent g traitUniverses supClosed
              supFunction <- evalIn ctxP' specializedSuper
              supGoal <- forceM (evalApp ec supFunction [(Expl, argument) | argument <- argVs])
              let selfTerm = foldl (CApp Expl) (CGlobal g traitUniverses) argTms
              selfGoal <- evalIn ctxP' selfTerm
              let selfCtx = bindCtxMQ Ordinary QW "__derived_self" True selfGoal ctxP'
                  partialDictionary =
                    CRecordV
                      ( sortOn fst
                          (catMaybes superFields ++ dictFields)
                      )
              baseline <- get
              modify' $ \state ->
                state
                  { csBlockedSupertraitProjections =
                      Set.insert (g, fn) (csBlockedSupertraitProjections state)
                  }
              proof <- synthesizeDerivation selfCtx sp supGoal
              modify' $ \state ->
                state
                  { csBlockedSupertraitProjections =
                      Set.delete (g, fn) (csBlockedSupertraitProjections state)
                  }
              diagnostics <- gets csDiags
              if length diagnostics == length (csDiags baseline)
                then
                  pure
                    ( Just
                        ( fn
                        , substTopTermAt 0 partialDictionary proof
                        )
                    )
                else pure Nothing
      let allSuperFields = catMaybes superFields ++ completedDerivedSupers
      -- §14.3.4: an instance member the trait does not declare is
      -- undeclared — an associated static member must be declared in the
      -- trait body before an instance may define it.
      forM_ [(nameText dn, dsp) | DLet _ (LetDef (Just dn) _ _ _ _ _ _ _ _) dsp <- members] $ \(inm, dsp) ->
        unless (inm `elem` tiMembers ti) $
          errAt dsp "E_ASSOCIATED_MEMBER_UNDECLARED" (Just "kappa.associated.member-undeclared")
            ( "instance defines '" <> inm <> "', which trait '" <> gnameText g
                <> "' does not declare; an associated static member must first be declared in the trait body (§14.3.4)"
            )
      flushPending
      settleActiveUniverseRequirements
      checkInstanceMemberTerminationSccs ctxP' g dictG memberTerminations
      let fields = sortOn fst (allSuperFields ++ dictFields)
          dictBody = CRecordV fields
          -- order: fvs outermost, then premises
          wrapped =
            foldr
              (\entry acc -> CLamM (teMode entry) (teIcit entry) (teQ entry) (teName entry) acc)
              (foldr (\_ acc -> CLamM Ordinary Impl QW "__p" acc) dictBody premises)
              fvTele
      dictType <- gets (maybe (VSort LZero) gdType . Map.lookup dictG . csGlobals)
      wrapped0 <- principalizeBodyUniverseInstantiations dictG dictType wrapped
      settleActiveUniverseRequirements
      wrapped' <- zonkTermM 0 wrapped0
      dictV <- evalIn emptyCtx wrapped'
      dictDef <- gets (Map.lookup dictG . csGlobals)
      addGlobal dictG $
        case dictDef of
          Just definition -> definition {gdValue = Just dictV, gdReducible = True}
          Nothing -> GlobalDef (VSort LZero) (Just dictV) True
      -- §14.1.1: trait evidence lowers to a runtime record of the member
      -- implementations; capture its KCore body for the native backend.
      recordCoreBody dictG wrapped'
      -- §14.3/§33.2.1: program-level coherence is a declaration-level
      -- validity condition. Member checking must run first because structural
      -- coherence compares completed evidence artifacts. A body-invalid,
      -- non-overlapping artifact is unpublished so recovery cannot poison
      -- later instance bodies. An overlapping artifact is still judged:
      -- generated-law recovery errors are replaced by the coherence root, and
      -- a body-valid incoherent artifact remains visible to resolution so an
      -- attempted selection also reports the non-deferrable use-site error
      -- required by §3.1.15.
      stPost <- get
      let diagnosticsAfterBody = length (csDiags stPost)
          bodyDiagnosticCount =
            max 0 (diagnosticsAfterBody - diagnosticsBeforeBody)
          bodyHasErrors =
            any isError (take bodyDiagnosticCount (csDiags stPost))
          unpublishInvalid state =
            invalidateSemanticCaches
              ( setCheckInstances
                  (filter ((/= dictG) . ieDict) (csInstances state))
                  state
              )
      case dropWhile ((/= dictG) . ieDict) (csInstances stPost) of
        (newIe : priors) -> do
          let sameTraitPriors = [ie | ie <- priors, ieTrait ie == g]
          incoherentPriors <-
            filterM (instanceOverlapIsIncoherent newIe) sameTraitPriors
          case incoherentPriors of
            [] -> when bodyHasErrors (modify' unpublishInvalid)
            _ -> do
              priorSites <- mapM (instanceDeclSite . ieDict) incoherentPriors
              modify' $ \state ->
                let withoutRecoveryDiagnostics =
                      state {csDiags = drop bodyDiagnosticCount (csDiags state)}
                 in if bodyHasErrors
                      then unpublishInvalid withoutRecoveryDiagnostics
                      else withoutRecoveryDiagnostics
              let relateds =
                    related RoleInstanceDeclarationSite sp "this overlapping instance"
                      : [ related RoleInstanceDeclarationSite priorSite
                            "conflicts with this instance"
                        | Just priorSite <- priorSites
                        ]
              report $
                withRelateds relateds $
                  diag SevError StageElaborate "E_INSTANCE_INCOHERENT"
                    (Just "kappa-hs.trait.incoherent") sp
                    ( "overlapping instances of trait '" <> gnameText g
                        <> "' are not equivalent implementations (§14.3, §33.2.1 coherence)"
                    )
        [] -> pure ()
      settleActiveUniverseRequirements
  where
    findMember mn ms =
      case [ (ld, dsp) | DLet _ ld@(LetDef (Just dn) _ _ _ _ _ _ _ _) dsp <- ms, nameText dn == mn
           ] of
        (x : _) -> Just x
        [] -> Nothing

    withEmbeddedDefaultProvenance False action = action
    withEmbeddedDefaultProvenance True action = do
      oldAllow <- gets csAllowUnsafeIntrinsics
      oldEmbedded <- gets csEmbeddedLoad
      modify' $ \state ->
        state
          { csAllowUnsafeIntrinsics = True
          , csEmbeddedLoad = True
          }
      result <- action
      modify' $ \state ->
        state
          { csAllowUnsafeIntrinsics = oldAllow
          , csEmbeddedLoad = oldEmbedded
          }
      pure result

    checkInstanceMemberTerminationSccs ambient trait dictionary terminations = do
      state <- get
      let identities =
            Map.fromList
              [ (imtName termination, memberIdentity (imtName termination))
              | termination <- terminations
              ]
          shapeValidatedAccessors =
            Map.fromList
              [ (global, accessor)
              | (global, definition) <- Map.toList (csGlobals state)
              , Just body <- [gdCoreBody definition]
              , Just accessor@(member, _, _) <- [projectionAccessor body]
              , Map.member member identities
              ]
          authenticatedAccessors =
            Map.fromList
              ( [ (global, member)
                | (global, (owner, member)) <-
                    Map.toList (csBareTraitMembers state)
                , owner == trait
                , Map.member member identities
                ]
                  ++ [ (global, member)
                     | member <- Map.keys identities
                     , let global = memberGlobal trait member
                     , Map.lookup global (csTraitMemberOwners state) == Just trait
                     ]
              )
          memberIdentity member =
            case dictionary of
              GName owner dictionaryName ->
                GName owner (dictionaryName <> "#termination-member#" <> member)
          rewriteMemberReference _ term = case term of
            CProjM _ receiver member
              | Just identity <- Map.lookup member identities
              , receiverIsCurrentDictionary receiver ->
                  Just (CGlob identity)
            _ ->
              case spineOfTerm term of
                (CGlob accessor, arguments)
                  | Just member <- Map.lookup accessor authenticatedAccessors
                  , Just receiverPosition <-
                      List.findIndex
                        (receiverIsCurrentDictionary . snd)
                        arguments
                  , accessorReceiverPositionIsValid
                      accessor
                      receiverPosition
                      arguments
                  , Just identity <- Map.lookup member identities ->
                      Just
                        ( List.foldl'
                            (\function (icit, argument) ->
                               CApp icit function argument)
                            (CGlob identity)
                            (drop (receiverPosition + 1) arguments)
                        )
                _ -> Nothing
          accessorReceiverPositionIsValid accessor receiverPosition arguments =
            case Map.lookup accessor shapeValidatedAccessors of
              Just (_, binderCount, expectedReceiverPosition) ->
                length arguments >= binderCount
                  && receiverPosition == expectedReceiverPosition
              Nothing -> True
          projectionAccessor = go 0
            where
              go binderCount = \case
                CLamM _ _ _ _ body -> go (binderCount + 1) body
                CProjM _ (CVar index) member
                  | let receiverPosition = binderCount - index - 1
                  , receiverPosition >= 0
                  , receiverPosition < binderCount ->
                      Just (member, binderCount, receiverPosition)
                _ -> Nothing
          receiverIsCurrentDictionary receiver =
            receiver == CGlob thisG
              || case fst (spineOfTerm receiver) of
                   CGlob resolved -> resolved == dictionary
                   _ -> False
      prepared <-
        fmap catMaybes . forM terminations $ \termination ->
          case Map.lookup (imtName termination) identities of
            Nothing -> pure Nothing
            Just identity -> do
              zonked <-
                zonkTermM (ctxLen ambient) (imtBody termination)
              let exposed =
                    mapTermWithDepth
                      rewriteMemberReference
                      0
                      zonked
              normalized <-
                normalizeTermAt (ctxLen ambient) exposed
              pure
                ( Just
                    ( termination
                    , identity
                    , mapTermWithDepth rewriteMemberReference 0 normalized
                    )
                )
      let
          memberNames = Set.fromList [identity | (_, identity, _) <- prepared]
          dependencies body =
            Set.toList (Set.intersection memberNames (globalsOfTerm body))
          graphNodes =
            [ ((termination, identity, body), identity, dependencies body)
            | (termination, identity, body) <- prepared
            ]
          selfRecursive (_, identity, body) =
            identity `Set.member` globalsOfTerm body
          recursiveGroups =
            [ group
            | component <- stronglyConnComp graphNodes
            , group <- case component of
                AcyclicSCC entry
                  | selfRecursive entry -> [[entry]]
                CyclicSCC entries -> [entries]
                _ -> []
            ]
      forM_ recursiveGroups $ \group -> do
        let declarations =
              [ TerminationDecl
                  identity
                  (imtType termination)
                  (imtBinders termination)
                  (imtDecreases termination)
                  body
                  (imtSpan termination)
              | (termination, identity, body) <- group
              ]
        result <- verifyTerminationSccIn ambient declarations
        when (result == TerminationUnverified) $
          forM_ group $ \(termination, _, _) ->
            reportUnverifiedTermination
              (imtSpan termination)
              []
              ( "could not verify termination of instance member '"
                  <> imtName termination
                  <> "' (§15)"
              )
              "this instance-member SCC has no checked well-founded decrease and is rejected because Kappa is total by default (§15.1–§15.2)"

    memberSigInstance traitG traitUniverses mn argTms ctx doneFields = do
      arguments <- mapM (evalIn ctx) argTms
      instantiateTraitMemberType
        ctx
        sp
        traitG
        traitUniverses
        mn
        arguments
        doneFields

    checkMemberAgainst memberMode ctx memberTy mbinders mResTy mbody msp =
      case mbinders of
        [] ->
          checkObservedExpr
            ctx
            "ordinary trait member"
            memberMode
            (maybe mbody (\t -> EAscription mbody t msp) mResTy)
            memberTy
        _ -> checkLambdaAgainst ctx memberTy mbinders mbody msp

    checkInstanceMember trait traitUniverses info argTms ctx supers done memberMode memberTy mbinders mResTy mbody msp = do
      siblingTypes <-
        instanceMemberSiblingTypes
          trait
          traitUniverses
          info
          argTms
          ctx
          supers
          done
      let partialDictionary = CRecordV (sortOn fst (supers ++ done))
      checked <-
        withThis (Just (ThisTraitSibs siblingTypes)) $
          checkMemberAgainst memberMode ctx memberTy mbinders mResTy mbody msp
      pure (substThisTm partialDictionary checked, checked)

    deriveStructuralInstanceMember trait _dictionary traitUniverses info argTms ctx supers done memberMode member memberTy site
      | trait /= gPrel "Eq" = pure Nothing
      | memberIdentity /= memberGlobal (gPrel "Eq") "eqSound"
          && memberIdentity /= memberGlobal (gPrel "Eq") "eqComplete" = pure Nothing
      | [targetTerm] <- argTms
      , Just target <- delaborateType ctx site targetTerm = do
          (shape, _) <- deriveNominalShape ctx site targetTerm
          case (shape, lookup "==" done) of
            ([], _) -> pure Nothing
            (_, Nothing) -> pure Nothing
            (_, Just comparator) ->
              derivedEqEvidenceForComparator
                ctx
                site
                shape
                comparator >>= \case
                Just exact -> Just <$> checkGenerated target shape exact
                Nothing ->
                  checkedFunctionalEqualityHelpers comparator >>= \case
                    [] -> pure Nothing
                    helpers -> attemptFunctional comparator target shape helpers
      | otherwise = pure Nothing
      where
        memberIdentity = memberGlobal trait member

        checkGenerated target shape (evidenceBindings, evidenceNames) = do
          let generatedSpan = derivedGeneratedSpan site 43
              xName = Name "__derive_member_x" generatedSpan
              yName = Name "__derive_member_y" generatedSpan
              proofName = Name "__derive_member_proof" generatedSpan
              body
                | memberIdentity == memberGlobal (gPrel "Eq") "eqSound" =
                    derivedEqualitySoundBody
                      generatedSpan
                      target
                      shape
                      evidenceNames
                      xName
                      yName
                      proofName
                | otherwise =
                    derivedEqualityCompleteBody
                      generatedSpan
                      target
                      shape
                      evidenceNames
                      xName
                      yName
                      proofName
          evidenceCtx <- bindDerivedEqEvidence ctx evidenceBindings
          checked <- checkGeneratedBody evidenceCtx body
          pure
            ( closeDerivedEqEvidence evidenceBindings (fst checked)
            , closeDerivedEqEvidence evidenceBindings (snd checked)
            )

        checkGeneratedBody activeCtx body = do
          let generatedSpan = derivedGeneratedSpan site 43
              xName = Name "__derive_member_x" generatedSpan
              yName = Name "__derive_member_y" generatedSpan
              proofName = Name "__derive_member_proof" generatedSpan
          siblingTypes <-
            instanceMemberSiblingTypes
              trait
              traitUniverses
              info
              argTms
              ctx
              supers
              done
          let partialDictionary = CRecordV (sortOn fst (supers ++ done))
          checked <-
            withThis (Just (ThisTraitSibs siblingTypes)) $
              checkMemberAgainst
                memberMode
                activeCtx
                memberTy
                [simpleBinder xName, simpleBinder yName, simpleBinder proofName]
                Nothing
                body
                generatedSpan
          pure
            ( substThisTm partialDictionary checked
            , checked
            )

        -- A custom comparator may delegate to a transparent recursive helper
        -- instead of projecting the selected field dictionaries directly.
        -- In that case propose the ordinary structural proof under the
        -- helper's checked equations.  This is deliberately speculative: the
        -- normal checker must establish that the helper is definitionally the
        -- same decision procedure, and a failed proposal leaves no metas or
        -- diagnostics behind.
        attemptFunctional comparator target shape helpers = do
          baseline <- get
          let errors state =
                length
                  [ ()
                  | diagnostic <- csDiags state
                  , dSeverity diagnostic == SevError
                  ]
          checkedFunctionalEqualityPlan ctx site comparator helpers >>= \case
            Nothing -> put baseline >> pure Nothing
            Just functional -> do
              rootMethods <-
                derivedRecursiveFieldMethods ctx (dfeDomain functional) shape
              helperValue <- evalIn ctx (dfeTerm functional)
              let helperCtx =
                    bindCtxLet
                      (nameText (dfeBindingName functional))
                      False
                      (dfeType functional)
                      helperValue
                      ctx
                  generatedSpan = derivedGeneratedSpan site 43
                  xName = Name "__derive_member_x" generatedSpan
                  yName = Name "__derive_member_y" generatedSpan
                  proofName = Name "__derive_member_proof" generatedSpan
                  sound =
                    memberIdentity == memberGlobal (gPrel "Eq") "eqSound"
                  body =
                    derivedFunctionalEqualityMemberBody
                      sound
                      generatedSpan
                      target
                      shape
                      rootMethods
                      functional
                      xName
                      yName
                      proofName
                  close = substTopTermAt 0 (dfeTerm functional)
              generated <-
                withTemporaryReducibleGlobals helpers $
                  checkGeneratedBody helperCtx body
              current <- get
              if errors current == errors baseline
                then
                  pure
                    ( Just
                        (close (fst generated), close (snd generated))
                    )
                else put baseline >> pure Nothing

    completeOmittedMember declaredDerived member trait traitUniverses info argTms ctx supers done memberTy site = do
      admissible <-
        if declaredDerived
          then pure True
          else do
            propositionGoal <- globalValueM prelIsProp [(Expl, memberTy)]
            isJust <$> isPropClosure ctx site propositionGoal
      if not admissible
        then pure Nothing
        else do
          baseline <- get
          siblingTypes <-
            instanceMemberSiblingTypes
              trait
              traitUniverses
              info
              argTms
              ctx
              supers
              done
          let partialDictionary = CRecordV (sortOn fst (supers ++ done))
          proof <-
            withThis (Just (ThisTraitSibs siblingTypes)) $
              synthesizeDerivation ctx site memberTy
          diagnostics <- gets csDiags
          let added = length diagnostics - length (csDiags baseline)
          if added == 0
            then pure (Just (substThisTm partialDictionary proof))
            else do
              when declaredDerived $
                retagNew (length (csDiags baseline)) $ \diagnostic ->
                  if dCode diagnostic == "E_DERIVE_AMBIGUOUS"
                    then
                      diagnostic
                        { dMessage =
                            dMessage diagnostic
                              <> " while completing member '"
                              <> member
                              <> "'"
                        }
                    else diagnostic
              unless declaredDerived (put baseline)
              pure Nothing

    instanceMemberSiblingTypes trait traitUniverses info argTms ctx supers = go []
      where
        go _ [] = pure []
        go preceding ((member, memberTerm) : rest) = do
          memberType <-
            memberSigInstance
              trait
              traitUniverses
              member
              argTms
              ctx
              (supers ++ preceding)
          let field =
                RecordField
                  member
                  (Map.findWithDefault Ordinary member (tiMemberModes info))
                  FormationOrdinary
                  (Map.findWithDefault QW member (tiMemberQs info))
                  Nothing
                  memberType
          (field :) <$> go (preceding ++ [(member, memberTerm)]) rest

    checkLambdaAgainst ctx ty binders body msp = do
      t <- case binders of
        [] -> forceM ty
        _ -> peelCapturesM ty
      case (binders, t) of
        ([], _) -> check ctx body t
        (b : rest, VPiBoundM mode Impl q _ nm assumption dom clo)
          | not (bImplicit b)
          , mode == Parametric || (nameText <$> bName b) /= Just nm -> do
              withBound <- extendLevelAssumption msp ctx assumption
              let ctx' = bindCtxMQ mode q nm True dom withBound
              cod <- clApp clo (VRigid (ctxLen ctx) [])
              CLamM mode Impl q nm <$> checkLambdaAgainst ctx' cod (b : rest) body msp
        (b : rest, VPiBoundM mode ic q _ nm assumption dom clo) -> do
          withBound <- extendLevelAssumption msp ctx assumption
          let bn = fromMaybe nm (nameText <$> bName b)
              ctx' = bindCtxMQ mode q bn (ic == Impl) dom withBound
          cod <- clApp clo (VRigid (ctxLen ctx) [])
          CLamM mode ic q bn <$> checkLambdaAgainst ctx' cod rest body msp
        (_ : _, _) -> do
          errAt msp "E_SIGNATURE_ARITY" (Just "kappa-hs.type.signature-arity")
            "instance member has more parameters than the trait member type"
          check ctx body t

-- | Evidence for a trait goal: the local implicit context first
-- (§16.3.3), then the instance set (§14.3.1), then §14.3.3 supertrait
-- conformance paths projected from local evidence.
traitEvidence :: Ctx -> Span -> Value -> CheckM (Maybe Term)
traitEvidence ctx sp goal = do
  mLoc <- localCandidate ctx sp Q0 goal
  case mLoc of
    Just tm -> pure (Just tm)
    Nothing -> do
      mInst <- instanceSearch ctx sp goal
      case mInst of
        Just tm -> pure (Just tm)
        Nothing -> superCandidate ctx sp goal

-- | §14.3.3 conformance-path selection: project the goal's evidence
-- out of an in-scope implicit binder through declared-supertrait
-- dictionary fields.
superCandidate :: Ctx -> Span -> Value -> CheckM (Maybe Term)
superCandidate ctx site goal = do
  localEntries <- filterM (isLocalEvidenceCandidate . snd) indexedEntries
  matches <- fmap catMaybes . forM localEntries $ \(index, entry) -> do
    saved <- get
    projected <- supertraitProject ctx 4 (CVar index) (ceType entry) goal
    solvedGoal <- traverse (const (forceM goal >>= quoteIn ctx)) projected
    put saved
    pure ((index, entry,) <$> solvedGoal)
  case matches of
    [] -> pure Nothing
    ((index, entry, solvedGoal) : rest)
      | all (\(_, _, candidateGoal) -> candidateGoal == solvedGoal) rest -> do
          coherentTraitGoal <- isTraitGoal goal
          let competing =
                [ (otherIndex, otherEntry)
                | (otherIndex, otherEntry, _) <- rest
                , sameImplicitScope index otherIndex
                ]
          unless (null competing || coherentTraitGoal) $
            report $
              withPayload
                ( withPayloadField "candidates"
                    (T.intercalate ", " (ceName entry : map (ceName . snd) competing)) $
                    withPayloadField "candidateKind" "projected-supertrait" $
                      payloadKind "implicit-ambiguous"
                )
                $ withRelated (related RoleObligationRequiredHere site "supertrait evidence required here")
                $ diag SevError StageElaborate "E_IMPLICIT_AMBIGUOUS"
                    (Just "kappa.implicit.ambiguous") site
                    "distinct local evidence values project the same supertrait goal; their evidence is not definitionally coherent (§14.3.3)"
          supertraitProject ctx 4 (CVar index) (ceType entry) goal
      | otherwise -> pure Nothing
  where
    sameImplicitScope inner outer =
      let innerLevel = ctxLen ctx - 1 - inner
          outerLevel = ctxLen ctx - 1 - outer
       in not (any (\barrier -> outerLevel < barrier && barrier <= innerLevel) (ctxBarriers ctx))
    indexedEntries = zip [0 ..] (ctxEntries ctx)

-- §14.3.3 conformance paths (depth-bounded): evidence 'evTm' of type
-- 'evTy' (a trait application) yields the trait goal 'goal' through
-- the evidence trait's transitive supertrait premises, as a chain of
-- supertrait-field projections.
supertraitProject :: Ctx -> Int -> Term -> Value -> Value -> CheckM (Maybe Term)
supertraitProject _ 0 _ _ _ = pure Nothing
supertraitProject ctx depth evTm evTy goal = do
  ev <- forceM evTy
  case ev of
    VGlobI tg traitUniverses args -> do
      st <- get
      case (Map.lookup tg (csTraits st), traitSemanticSpineIn st tg args) of
        (Just ti, Just semanticArguments) -> anyPath semanticArguments (tiSupers ti)
          where
            anyPath _ [] = pure Nothing
            anyPath semanticArguments ((fn, supClosed) : rest) = do
              blocked <- gets (Set.member (tg, fn) . csBlockedSupertraitProjections)
              if blocked
                then anyPath semanticArguments rest
                else do
                  ec <- ec_
                  specializedSuper <- specializeDeclarationComponent tg traitUniverses supClosed
                  supF <- evalIn ctx specializedSuper
                  supV <- forceM (evalApp ec supF [(Expl, a) | (_, a) <- semanticArguments])
                  st0 <- get
                  ok <- unify ctx supV goal
                  if ok
                    then pure (Just (CProjM Ordinary evTm fn))
                    else do
                      put st0
                      found <- supertraitProject ctx (depth - 1) (CProjM Ordinary evTm fn) supV goal
                      case found of
                        Just tm -> pure (Just tm)
                        Nothing -> anyPath semanticArguments rest
        _ -> pure Nothing
    _ -> pure Nothing

-- free lowercase identifiers (implicit universalization, §11.3.3
-- approximation: ASCII lowercase heads not resolving to globals).
freeLower :: Expr -> [Text]
freeLower = go
  where
    go = \case
      EVar (Name n _)
        | isLowerHead n -> [n]
        | otherwise -> []
      -- the label argument of a row constraint is not a type variable
      -- (§11.3.1: 'LacksRec r age')
      EApp f@(EVar hd) [rowA, ArgExplicit (EVar _)]
        | nameText hd == "LacksRec" -> go f ++ goArg rowA
      EApp f args -> go f ++ concatMap goArg args
      EArrow b e -> maybe [] go (bType b) ++ withoutBinders [b] (go e)
      -- §11.3.3: a `forall` binder is in scope for every LATER binder's
      -- type and the body, so a name bound earlier in the telescope is not
      -- free where a subsequent binder's type mentions it (e.g. the `a` in
      -- `(x : Core G a)` after `(a : Type)`). Threading the binders left to
      -- right avoids spuriously universalizing such a name as an extra
      -- leading implicit, which otherwise duplicates the binder and
      -- cross-links shared dependent indices.
      EForall bs e _ -> goTele bs
        where
          goTele [] = go e
          goTele (b : rest) = maybe [] go (bType b) ++ withoutBinders [b] (goTele rest)
      EExists bs e _ -> goTele bs
        where
          goTele [] = go e
          goTele (b : rest) = maybe [] go (bType b) ++ withoutBinders [b] (goTele rest)
      ETraitArrow a b -> go a ++ go b
      EOptionSugar e _ -> go e
      ETuple es _ -> concatMap go es
      ERecordType fields mtail _ ->
        let fieldNames = map (nameText . rtfName) fields
            mentioned = concatMap (go . rtfType) fields ++ maybe [] go mtail
         in filter (`notElem` fieldNames) mentioned
      EEffRow entries mtail _ ->
        concatMap (go . snd) entries ++ maybe [] go mtail
      EVariant arms mtail _ ->
        concatMap (\arm -> go (vaExpr arm) ++ maybe [] go (vaType arm)) arms
          ++ maybe [] go mtail
      EAscription e ty _ -> go e ++ go ty
      -- a dotted head (module path / projection, e.g. `main.Big`) is
      -- never an implicitly-universalized type variable
      EDot {} -> []
      _ -> []
    withoutBinders bs fvs =
      let bound = [nameText n | b <- bs, Just n <- [bName b]]
       in filter (`notElem` bound) fvs
    goArg = \case
      ArgExplicit e -> go e
      ArgImplicit e -> go e
      _ -> []
    isLowerHead n = case T.uncons n of
      Just (c, _) -> c >= 'a' && c <= 'z'
      Nothing -> False

instanceFreeVars :: [Expr] -> CheckM [Text]
instanceFreeVars exprs =
  filterM
    (\name -> do
       global <- lookupGlobalName name
       schemaLevel <- gets (Map.lookup name . csActiveUniverseSchema)
       -- Primitive universe spellings are syntax, never implicitly
       -- universalized instance-head variables. Treating @Type@ as an
       -- ordinary free head installs a local binder that shadows the
       -- primitive family and turns @Type u@ into an invalid runtime use of
       -- the rigid schema parameter @u@.
       pure
         ( isNothing global
             && isNothing schemaLevel
             && isNothing (sortName name)
             && name /= "ω"
         ))
    . nub
    $ concatMap constraintIdOccs exprs

-- | §14.3.5 instance-search termination: the identifier-leaf occurrences
-- of a constraint (type constructors AND variables, counting repetitions),
-- used to measure each instance premise against the head. Mirrors the
-- 'freeLower' traversal but keeps every name (not just free lowercase ones)
-- and does not deduplicate.
-- | The head identifier (trait name) of a constraint's application spine,
-- if any. Tells a self-recursive premise (same trait as the head) from a
-- cross-trait bridge premise like @Eq a => Equiv a@ (§14.3.5).
constraintHead :: Expr -> Maybe Text
constraintHead = \case
  EApp f _ -> constraintHead f
  EUniverseInstantiation base _ _ -> constraintHead base
  EVar (Name n _) -> Just n
  _ -> Nothing

constraintIdOccs :: Expr -> [Text]
constraintIdOccs = go
  where
    go = \case
      EVar (Name n _) -> [n]
      EApp f args -> go f ++ concatMap goArg args
      EUniverseInstantiation base _ _ -> go base
      EArrow b e -> maybe [] go (bType b) ++ go e
      EForall bs e _ -> concatMap (maybe [] go . bType) bs ++ go e
      ETraitArrow a b -> go a ++ go b
      EOptionSugar e _ -> go e
      ETuple es _ -> concatMap go es
      EDot {} -> []
      _ -> []
    goArg = \case
      ArgExplicit e -> go e
      ArgImplicit e -> go e
      _ -> []
